INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'I begynnelsen skapade Gud Himmel och Jord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Och jorden war öde och tom, och mörker war på djupet, och Guds Ande swäfde öfwer watnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Och Gud sade: Warde Ljus, och det wardt Ljus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Och Gud såg ljuset, at det war godt. Då skilde Gud ljuset ifrå mörkret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Och kallade ljuset Dag och mörkret Natt. Och wardt af afton och morgon den första dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Och Gud sade: Warde et Fäste emellan watnen, och åtskilje watn ifrå watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Och Gud gjorde fästet, och åtskilde det watnet, som war under fästet, ifrå det watn, som war ofwan fästet. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Och Gud kallade fästet Himmel. Och wardt af afton och morgon den andra dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Och Gud sade: Församle sig watnet, som är under himmelen, uti besynnerliga rum, att det torra må synas. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Och Gud kallade det torra Jord, och watnens församlingar kallade han Haf. Och Gud såg, at det war godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Och Gud sade: Bäre jorden gräs och örter, som frö hafwa, och fruktsam trä, at hwart och et bär frukt efter sin art, och hafwer sitt eget frö i sig sjelfwo på jordene. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Och jorden bar gräs och örter, som frö hade, hwart efter sin art, och trä, som frukt båro, och hade sitt eget frö i sig sjelfwo, hwart efter sin art. Och Gud såg, att det war godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Och wardt af afton och morgon den tredje dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Och Gud sade: Warde Ljus uti himmelens fäste, och åtskilje dag och natt, och gifwe tekn, månader, dagar och år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Och ware för ljus uti himmelens fäste, och lyse på jordene. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Och Gud gjorde tu stor ljus; et stort ljus, som regerade dagen, och et litet ljus, som regerade nattena; och stjernor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Och Gud satte dem uti himmelens fäste, at de skina skulle på jordene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Och regera dagen och nattena, och åtskilja ljuset och mörkret. Och Gud såg, at det war godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Och wardt af afton och morgon den fjerde dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Och Gud sade: Göre watnet af sig kräkande och lefwande djur, och foglar, som på jordene flyga under himmelens fäste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Och Gud skapade stora hwalar, och allahanda lefwande och kräkande djur, som watnet af sig gör, hwart efter sin art, och allahanda fjäderfoglar, hwart efter sin art. Och Gud såg, at det war godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Och wälsignade dem, och sade: Warer fruktsame, och förökens, och upfyller hafsens watn, och foglarna föröke sig på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Och wardt af afton och morgon den femte dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Och Gud sade: Göre jorden af sig lefwande djur, hwart efter sin art, fänad, kräkande djur, och wilddjur på jordene, hwart efter sin art. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Och Gud gjorde wilddjur på jordene, hwart efter sin art, fänad efter sin art, allahanda kräkande djur på jordene efter sin art. Och Gud såg, at det war godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Och Gud sade: Låt oss göra Menniskona til et beläte, det oss likt är, den råda skall öfwer fiskarna i hafwet, och öfwer foglarna under himmelen, och öfwer fänaden, och öfwer hela jordena, och öfwer allt som kräker på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Och Gud skapade menniskona sig till et beläte, til Guds beläte skapade han honom, Man och Qwinno skapade han dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Och Gud wälsignade dem, och sade til dem: Warer fruktsame, och föröker eder, och upfyller jordena, och hafwer henne under eder, och råder öfwer fiskarna i hafwet, och öfwer foglarna under himmelen, och öfwer all djur, som kräla på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Och Gud sade: Si, jag hafwer gifwit eder allahanda örter, som frö hafwa på hela jordene, och allahanda fruktsam trä, och trä, som frö hafwa i sig sjelfwo, eder til mat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Och allom djurom på jordene, och allom foglom under himmelen, och allo thy, som kräker på jordene, och lif hafwer, at de skola hafwa allahanda gröna örter til at äta. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Och Gud såg på allt det han gjort hade, och si, det war allt ganska godt. Och wardt af afton och morgon den sjette dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Så wardt nu himmel och jord fullkomnad med all sin här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Och Gud fullkomnade på sjunde dagenom sin werk, som han gjort hade, och hwilade på sjunde dagenom af all sin werk, som han gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Och wälsignade sjunde dagen, och helgade honom, derföre, at han på honom hwilade af all sin werk, som Gud skapade och gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Alltså är himmel och jord tilkommen, då de skapade wordo på den tid, då HERren Gud gjorde himmel och jord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Förra än någor stjelk war på markene, och förra än någor ört wäxte på jordene; förty HERren Gud hade än då intet låtit regna på jordene, och ingen menniska war, som brukade jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Men en dimba gick up af jordene, och watnade alla markena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Och HERren Gud gjorde menniskona af jordenes stoft, och inblåste uti hans näso en lefwande anda, och så wardt menniskan en lefwande själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Och HERren Gud planterade en lustgård uti Eden öster ut, och satte der in menniskona, som han gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Och HERren Gud lät upwäxa af jordene allahanda trä, lustig til at se och god til at äta; och lifsens trä midt i lustgårdenom, och kundskapsens trä på godt och ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Och utaf Eden gick en ström til at watna lustgården, och han delade sig i fyra hufwudfloder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Den förste kallas Pison, den löper om hela Hawila land, och der finnes guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Och dess landes guld är kosteligit, och der finnes Bedellion, och den ädle stenen Onix.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Den andre floden heter Gihon, den löper kring om hela Ethiopien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Den tredje floden kallas Hiddekel, den löper fram för Assyrien. Den fjerde floden är Phrath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Och HERren Gud tog menniskona, och satte honom in uti lustgården Eden, at han honom bruka och bewara skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Och HERren Gud böd menniskona, och sade: Du skalt äta af allahanda trä i lustgårdenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Men af kundskapsens trä på godt och ondt skalt du icke äta: förty, på hwad dag du deraf äter, skalt du döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Och HERren Gud sade: Det är icke godt, at menniskan är allena: Jag will göra honom ena hjelp, den sig til honom hålla må.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Som nu HERren Gud gjort hade af jordene allahanda djur på markene, och allahanda foglar under himmelen, hade han dem fram för menniskona, at han skulle se, huru han skulle nämna dem: Ty, såsom menniskan allahanda lefwande djur nämnde, så skulle de heta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Och menniskan gaf hwart och et fänad, och foglomen under himmelen, och djuren på markene, sina namn. Men till menniskone wardt icke funnen någon hjelp, den sig til honom hålla måtte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Då lät HERren Gud falla en tung sömn på menniskona, och wid han sof, tog han et af hans sidoref, och upfylte kött i samma staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Och HERren Gud byggde ena Qwinno utaf refwet, som han uttagit hade af menniskone, och hade henne fram för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Då sade menniskan: Detta är dock ben af minom benom, och kött af mino kötte, hon skall heta Manna, derföre, at hon är tagen utaf mannenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Fördenskull skall en man öfwergifwa fader och moder, och blifwa wid sina hustru, och skola warda til et kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Och de woro både nakne, menniskan och hans hustru, och de blygdes intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Och ormen war listigare än all djur på jordene, som HERren Gud gjort hade, och sade til qwinnona: Ja, skulle Gud hafwa sagt, I skolen icke äta af allahanda trä i lustgårdenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Då sade qwinnan til ormen: Wi äte af de träs frukt, som är i lustgårdenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Men af frukten af det trät, som är midt i lustgårdenom, hafwer Gud sagt: Äter icke deraf, och kommer icke heller derwid, at I icke dön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Då sade ormen til qwinnona: Ingalunda skolen I döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Förty Gud wet, at på hwad dag I äten deraf, skola edor ögon öpnas, och I warden såsom Gud, wetandes hwad godt och ondt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Och qwinnan såg til, at trät war godt at äta af, och ljufligit uppå se, och at det et lustigt trä war, efter det gaf förstånd; Och tog utaf fruktene, och åt, och gaf desslikes sinom man deraf, och han åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Då öpnades bägges deras ögon, och de wordo warse, at de woro nakne; Och de bundo tilhopa fikonalöf, och gjorde sig skörte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Och de hörde HERrans Guds röst gångandes i lustgårdenom, då dagen swalkades; och Adam undstack sig, med sine hustru, för HERrans Guds ansikte, ibland trän i lustgårdenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Och HERren Gud kallade Adam, och sade till honom: Hwar äst du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Och han sade: Jag hörde dina röst i lustgårdenom, och fruktade mig, ty jag är naken, derföre undstack jag mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Han sade: Ho hafwer låtit dig förstå, at du äst naken? Hafwer du icke ätit af det trä, om hwilket jag dig budit hafwer, at du deraf icke äta skulle?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Då sade Adam: Qwinnan, som du til mig gifwit hafwer, gaf mig af trät, så at jag åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Då sade HERren Gud til qwinnona: Hwi hafwer du det gjort? Qwinnan sade: Ormen beswek mig, så at jag åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Och HERren Gud sade til ormen: Efter du detta gjort hafwer, förbannad ware du öfwer all djur på markene: Du skalt gå på din buk, och äta jord i alla dina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Och jag skall sätta fiendskap emellan dig och qwinnona, och emellan dina säd och hennes säd. Den samme skall söndertrampa ditt hufwud, och du skalt stinga honom i hans häl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Och till qwinnona sade han: Jag skall få dig mycken wedermödo, då du aflat hafwer. Du skalt föda din barn med sweda, och din wilje skall dinom manne undergifwen wara, och han skall wara din herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Och til Adam sade han: Efter du lydde dine hustrus röst, och åt af trät, om hwilket jag dig böd och sade: Du skalt icke äta deraf; förbannad ware marken för dina skull, med bekymmer skalt du nära dig på henne i alla dina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Törne och tistlar skall hon bära dig, och du skalt äta örter på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Du skalt äta ditt bröd i dins anletes swett, til dess du warder åter til jord igen, der du af tagen äst; ty du äst jord, och til jord skalt du warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Och Adam kallade sine hustrus namn Hewa, derföre, at hon en moder är åt allom lefwandom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Och HERren Gud gjorde Adam och hans hustru kjortlar af skinn, och klädde uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Och HERren Gud sade: Si, Adam är worden såsom en af oss, och wet hwad godt och ondt är. Men nu, på det han icke uträcka skall sina hand, och taga desslikes af lifsens trä, och äta, och lefwa ewinnerliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Då lät HERren Gud honom utu lustgårdenom Eden, på det han skulle bruka jordena, der han af tagen war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Och dref Adam ut: Och satte för lustgården Eden Cherubim, med et bart huggande swärd, til at förwara wägen til lifsens trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Och Adam kände sina hustru Hewa, och hon aflade och födde Cain, och sade: Jag hafwer fått HERrans man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Och hon födde framdeles Habel hans broder. Och wardt Habel en fåraherde, men Cain wardt en åkerman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Och det begaf sig efter några dagar, at Cain offrade HERranom gåfwor af jordenes frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Och Habel offrade desslikes af förstlingene af sin får, och af deras talg: Och HERren Gud såg täckeliga til Habel och hans offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Men til Cain och hans offer såg han icke täckeliga. Då wardt Cain swårliga wred, och hans hy förwandlades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Sade HERren til Cain: Hwi äst du wred? Eller hwi förwandlas din hy?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Är det icke så? Om du äst from, så äst du tacknämlig; men äst du icke from, så blifwer icke synden säker eller fördold: men städ henne icke hennes wilja, utan råd öfwer henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Då talade Cain med sin broder Habel. Och det begaf sig, då de woro på markene, gaf Cain sig up emot sin broder Habel, och slog honom ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Då sade HERren til Cain: Hwar är din broder Habel? Han swarade: Jag wet det icke, skall jag taga wara på min broder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Och han sade til honom: Hwad hafwer du gjort? Dins broders blods röst ropar til mig utaf jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Och nu, förbannad ware du på jordene, som sin mun öpnat hafwer, och tagit dins broders blod utu dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Då du brukar jordena, skall hon icke strax gifwa dig efter sin förmågo; ostadig och flyktig skalt du blifwa på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Och Cain sade til HERran: Min missgerning är större, än at hon må mig förlåten warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Si, du drifwer mig i dag utaf landet, och jag måste gömma mig undan ditt ansikte, och måste ostadig och flyktig blifwa på jordene. Så warder mig gående, at hwilken som hälst mig finner, han slår mig ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Men HERren sade til honom: Nej, utan den som slår Cain ihjäl, det skall sjufalt hämnadt warda. Och HERren satte et tekn på Cain, at hwilken som hälst honom funne, skulle icke slå honom ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Och så gick Cain ifrå HERrans ansikte, och bodde i det landet Nod öster ut, på hinsidan Eden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Och Cain kände sina hustru, och hon aflade och födde Hanoch, och han byggde en stad, hwilken han nämnde efter sin sons namn Hanoch.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Men Hanoch födde Yrad: Yrad födde Mahujael: Mahujael födde Methusael: Methusael födde Lamech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Men Lamech tog sig twå hustrur: Den ena het Ada, den andra Zilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Och Ada födde Jabal, af honom kommo de som bodde under tjäll, och hade boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Och hans broder het Jubal, af honom kommo de, som brukade harpor och pipor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Födde ock desslikes Zilla, nemliga Tubalkain, som war en mästare i allahanda koppars och jerns werk; och Tubalkains syster war Naema.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Och Lamech sade til sina hustrur Ada och Zilla: I Lamechs hustrur, hörer mina röst, och märker hwad jag säger: Jag hafwer dräpit en man mig til sår, och en yngling mig til blånad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Cain skall warda hämnad sjufalt, men Lamech sju och sjutiofalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam kände åter sina hustru, och hon födde en son, och kallade honom Seth, sägandes: Gud hafwer satt mig en annor säd för Habel, som Cain ihjäl slog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Wardt också Seth född en son, den han kallade Enos. Och på den samma tiden begynte man predika om HERrans namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Detta är boken af menniskones slägt, på den tiden, då Gud skapte menniskona, och gjorde henne efter Guds liknelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Til man och qwinno skapade han dem, och wälsignade dem, och kallade deras namn menniska, på den tiden de wordo skapade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Och Adam war hundrade och tretio år gammal, och han födde en son, som hans beläte lik war, och kallade honom Seth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Och wordo hans dagar, sedan han hade födt Seth, åttahundrade år, och han födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Och wardt tiden på allan hans ålder niohundrade och tretio år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth war hundrade och fem år gammal, och födde Enos.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Och lefde derefter åttahundrade och sju år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Och wardt tiden på allan hans ålder niohundrade och tolf år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos war niotio år gammal, och födde Kenan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Och lefde derefter åttahundrade och femton år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Så at hans hela ålder wardt niohundrade och fem år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan war sjutio år gammal, och födde Mahalaleel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Och lefde derefter åttahundrade och fyratio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Så at hans hela ålder wardt niohundrade och tio år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel war sextio och fem år gammal, och födde Jared.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Och lefde sedan åttahundrade och tretio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Så at hans hela ålder wardt åttahundrade fem och niotio år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared war hundrade tu och sextio år gammal, och födde Henoch.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Och lefde derefter åttahundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Så at hans hela ålder wardt niohundrade sextio och tu år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch war sextio fem år gammal, och födde Methusalah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Och förde et gudeligit lefwerne i trehundrade år derefter, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Så at hans hela ålder wardt trehundrade sextio och fem år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Och efter han förde et gudeligit lefwerne, tog Gud honom bort, och han wardt sedan intet sedder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Methusalah war hundrade åttatio och sju år gammal, och födde Lamech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Och lefde derefter i sjuhundrade åttatio och tu år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Så at hans hela ålder wardt niohundrade sextio och nio år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamech war hundrade åttatio och tu år gammal, och födde en son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Och kallade honom Noah, och sade: Denne här warder oss tröstandes i wåra mödo och arbete på jordene, den HERren förbannat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Derefter lefde han femhundrade niotio och fem år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Så at hans hela ålder wardt sjuhundrade sjutio och sju år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noah war femhundrade år gammal, och födde Sem, Ham och Japhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Då menniskorna begynte förökas på jordene, och födde sig döttrar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Då sågo Guds söner menniskornas döttrar, at de woro dägeliga, och togo til hustrur hwilka de hälst wille.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Då sade HERren: Menniskorna wilja icke mer låta min Anda straffa sig, ty de äro kött. Jag will ännu gifwa dem hundrade och tjugu års dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'På den tiden woro ock tyranner på jordene, förty, sedan Guds söner ingingo til menniskors döttrar, och de födde barn, wordo deraf wäldige och fast beryktade män i werldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Men då HERren såg, at menniskones ondska war stor på jordene, och all hennes hjertas upsåt och tanke war alltid benägen til det ondt war:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Då ångrade HERranom, at han hade gjort menniskona på jordene, och det bekymrade honom i hans hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Och HERren sade: Menniskona, som jag skapade, skall jag förgöra utaf jordene, ifrå mennisko allt intil fänaden, och intil matkar, och intil foglarna under himmelen: Förty det ångrar mig, at jag dem gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Men Noah fann nåde för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Detta är Noahs slägt: Noah war en from man och fullkomlig, och förde et gudeligit lefwerne i sin tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Och födde tre söner, Sem, Ham, Japhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Men jorden war förderfwad för Guds åsyn, och full med orätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Då såg Gud på jordena, och si, hon war förderfwad, ty allt kött hade förderfwat sin wäg på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Då sade Gud til Noah: Allt kötts ändalykt är kommen för mig, ty jorden är full med orätt af dem, och si, jag will förderfwa dem med jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Gör dig en ark utaf furuträ, och gör kamrar derinne, och beka honom utan och innan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Och gör honom alltså: Trehundrade alnar skall wara längden, femtio alnar bredden, och tretio alnar högden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Et fenster skalt du göra der ofwan uppå, en aln stort. Dörene skalt du sätta midt på sidone: och skall han hafwa tre botnar, en nederst, den andra midt uti, den tredje öfwerst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ty si, jag skall låta komma en wattuflod öfwer jordena, til at förderfwa allt kött, der en lefwande ande uti är, under himmelen, och allt det på jordene är skall förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Men med dig will jag göra et förbund, och du skalt gå in i arken med dina söner, med dine hustru, och med dina söners hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Och du skalt låta komma in i arken allahanda djur af allt kött, ju et par, mankön och qwinkön, at de måga blifwa lefwande när dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Af foglarna efter deras slag, af fänadenom efter sitt slag, och af allahanda kräkande djur på jordene efter deras slag. Af allo desso skall ju et par ingå til dig, på det at de skola blifwa lefwande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Och du skalt til dig taga allahanda mat, som man tärer, och skalt samka honom til dig, at han warder dig och dem til födo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Och Noah gjorde allt det Gud böd honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Och HERren sade til Noah: Gack in uti arken, du och ditt hela hus, ty dig hafwer jag sett rättfärdigan för mig i denna tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Af allahanda ren fänad tag til dig, ju sju och sju, mankön och qwinkön; men af orenom fänad, ju et par, mankön och qwinkön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Sammalunda af foglarna under himmelen, ju sju och sju, mankön och qwinkön, på det at säd må blifwa lefwandes på hela jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Ty ännu efter sju dagar skall jag låta regna på jordene fyratio dagar och fyratio nätter, och förgöra utaf jordene allt det som warelse hafwer, det jag gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Och Noah gjorde allt det HERren böd honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Och han war sexhundrade år gammal, då flodenes watn flödade på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Och han gick in i arken med sina söner, sine hustru, och sina söners hustrur, för flodenes watns skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Af den rena fänaden, och af den orena, af foglar, och af allt det som kräker på jordene,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Gingo til honom in i arken, parom, ju mankön och qwinkön, såsom Gud honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Och då de sju dagar framlidne woro, kom flodsens watn uppå jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Uti de sjettehundrade årena i Noahs ålder, på sjuttonde dagenom, i den andra månadenom, det är den dagen, då upbrusto alla stora djupsens källor, och himmelens fenster öpnade sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Och et regn kom på jordene i fyratio dagar och fyratio nätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Rätt på samma dagen gick Noah in i arken, med Sem, Ham och Japhet sina söner, och med sine hustru, och med tre sina söners hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Dertil allahanda djur efter sitt slag, allahanda fänad efter sitt slag, och allt det på jordene kräker efter sitt slag, och allahanda foglar efter sitt slag, allt det flyga kunde, och allt det wingar hade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Det gick allt til Noah in uti arken, parom af allt kött, der en lefwande ande uti war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Och det war mankön och qwinkön, utaf allahanda kött, och gingo derin, såsom Gud honom budit hade, och HERren lät igen efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Då kom floden fyratio dagar på jordene, och watnet wäxte, och lyfte arken up, och förde honom högt up öfwer jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Så fick då watnet öfwermagt, och wäxte swårliga på jordene, så at arken dref på watnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Och watnet fick öfwerhand, och wäxte så swåra på jordene, at all hög berg under hela himmelen wordo öfwertäckte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Femton alnar högt gick watnet öfwer bergen, som öfwertäckte wordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Då förgicks allt kött, som på jordene kräker, foglar, fänad, wilddjur, och allt det, som sig röre på jordene, och alla menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Allt det, som en lefwande anda hade på thy torra, det blef dödt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Så wardt då förgjordt allt det på jordene war, ifrå menniskone allt intil fänaden, intil kräkande djur, och intil foglarna under himmelen, allt wardt förgjordt utaf jordene. Allena Noah blef behållen, och hwad med honom war i arkenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Och watnet stod på jordene hundrade och femtio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Då tänkte Gud på Noah, och på all djur, och på all fänad, som med honom i arkenom war, och lät komma wäder på jordene, och watnet minskades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Och djupsens källor förstoppades, så ock himmelens fenster, och regnet af himmelen wardt stilladt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Och watnet förlopp utaf jordene mer och mer, och wardt mindre, efter hundrade och femtio dagar. På sjuttonde dagenom i den sjunde månadenom blef arken ståndandes på de berg Ararat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Men watnet förlopp framgent af, och wardt ju mindre, allt intil tionde månaden. På första dagenom i tionde månadenom syntes det öfwersta på bergen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Efter fyratio dagar lät Noah fenstret up på arkenom, som han gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Och lät flyga en korp ut, och han flög bort åter och fram, til dess at watnet aftorkades af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Sedan lät han ena dufwo utflyga ifrå sig, på det han skulle försöka, om watnet på jordene war förfallet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Då dufwan fann icke hwar hon kunde hwila sin fot uppå, kom hon igen til honom i arken, ty watnet war ännu på hela jordene. Så räckte han handena ut, och tog henne til sig in i arken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Och bidde ännu andra sju dagar, och lät än en tid flyga ut dufwona af arkenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Hon kom til honom emot aftonen, och si, hon förde i sin mun et afbrutit oliwelöf. Så förnam Noah, at watnet war förfallet på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Men han töfwade ännu andra sju dagar, och lät så ena dufwo flyga ut, hwilken intet igen kom til honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'På första och sjettehundrade årena af Noahs ålder, på första dagenom i första månadenom, förtorkades watnet på jordene. Då lät Noah taket up på arkenom, och såg, at jorden war torr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Så wardt då jorden alstinges torr på sjunde och tjugonde dagenom i den andra månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Då talade Gud til Noah och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gack utur arkenom, du och din hustru, dine söner och dina söners hustrur med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Allahanda djur, som när dig äro, utaf hwarjo och eno kötte, både i foglar och fänad, och det som på jordene kräker, det gånge ut med dig. Och förkofrer eder uppå jordene, och warer fruktsamme, och föröker eder på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Så gick Noah ut med sina söner, och med sine hustru, och sina söners hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Dertil allahanda djur, allahanda krypande, allahanda foglar, och allt det som på jordene kräker, det gick utur arkenom, och hwart och et til sitt slag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Och Noah byggde HERranom et altare, och tog utaf allahanda ren fänad, och utaf allahanda rena foglar, och offrade brännoffer på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Och HERren luktade en söt lukt, och sade i sitt hjerta: Ingalunda skall jag mer härefter förbanna jordena för menniskones skull, förty menniskones hjertas upsåt är ondt allt ifrå ungdomen. Och skall jag nu icke mer härefter slå allt det som lefwandes är, såsom jag gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Så länge jorden står, skall icke återwända sående och upskärande, köld och hete, sommar och winter, dag och natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Och Gud wälsignade Noah och hans söner, och sade: Warer fruktsamme, och förökens, och upfyller jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Edor fruktan och rädsla ware öfwer all djur på jordene, öfwer alla foglar under himmelen, och öfwer allt det som kräker på jordene, och alle fiskar i hafwet ware gifne i edra hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Allena äter icke kött, det ännu lefwer i sinom blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Förty, jag will ock hämnas öfwer edar kropps blod, och will hämnat uppå all djur, och will hämnas menniskones lif på hwarjo och ena mennisko, eho hon är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Den som utgjuter menniskoblod, hans blod skall ock af menniskom utgjutit warda. Förty Gud hafwer gjort menniskona efter sitt beläte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Warer fruktsamme, och förökens, och förkofrer eder på jordene, at I upfyllen henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Yttermera sade Gud till Noah, och hans söner med honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Si, jag gör med eder et förbund, och med edra säd efter eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Och med allom lefwandom djurom som med eder äro, i foglar, i fänad, och i allom djurom, som på jordene när eder äro: Af allt det som utur arkenom gångit är, ehwad djur det är på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Och will göra mitt förbund med eder i så måtto, at härefter skall nu icke mer allt kött förderfwadt warda med flodsens watn, och skall härefter ingen mer flod komma, den jordena förderfwa skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Och Gud sade: Detta är teknet til mitt förbund, som jag gjort hafwer emellan mig och eder, och all lefwande djur med eder härefter til ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Min båga hafwer jag satt i skynom, den skall wara teknet til mitt förbund emellan mig och eder, och all lefwande djur med eder härefter til ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Och när så sker, at jag förer skyn öfwer jordena, så skall man se min båga i skynom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Och så skall jag tänka på mitt förbund emellan mig och eder, och all lefwande djur i hwart och et kött, at icke mer skall komma flod härefter, den allt kött förderfwa skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Derföre skall min båge wara i skynom, at jag skall se uppå honom, och tänka uppå det ewiga förbund emellan Gud och all lefwande djur i hwarjo och eno kötte, som på jordene är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Det samma sade ock Gud til Noah: Detta skall wara teknet til det förbund, som jag gjort hafwer emellan mig och allt kött på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Noahs söner, som utur arkenom gingo, äro desse: Sem, Ham, Japhet. Men Ham är fadren til Canaan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Dessa tre äro Noahs söner, af hwilkom all land besatt wordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Och Noah begynte til och wardt en åkerman, och plantade wingård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Och då han drack af winet, wardt han drucken, och låg oskyld uti sine hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Då nu Ham, Canaans fader, såg sins faders blygd, sade han det bådom sinom brödrom, som ute woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Då togo Sem och Japhet et kläde, och lade på bägges deras skuldror, och gingo baklänges til, och öfwertäckte deras faders blygd, och deras ansikte war ifrå wändt, så at de deras faders blygd icke sågo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Som nu Noah upwaknade af sino wine, och fick weta hwad hans yngste son honom gjort hade, sade han:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Förbannad ware Canaan, och ware en träl under alla trälar ibland hans bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Och sade yttermera: Lofwad ware HERren Sems Gud, och Canaan ware hans träl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gud förwidge Japhet, och låte honom bo i Sems hyddor, och Canaan ware hans träl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Och Noah lefde efter flodena trehundrade och femtio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Så at hans hela ålder wardt niohundrade och femtio år, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Detta är Noahs söners slägt: Sem, Ham, Japhet, och de födde barn efter flodena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Japhets barn äro desse: Gomer, Magog, Madaj, Jawan, Thubal, Mesech och Thiras.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Men Gomers barn äro desse: Aseenas, Riphath och Thogarma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Jawans barn äro desse: Elisa, Tharsis, Chitthim och Dodanim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Utaf dessom äro utspridde Hedningarnas öar i deras landom, hwar efter sitt mål, slägte och folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Hams barn äro desse: Chus, Mizraim, Phut och Canaan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Chus barn äro desse: Seba, Hawila, Sabtha, Raema och Sabthecha. Raemas barn äro desse: Scheba och Dedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Men Ehus födde Nimrod, han begynte en wäldig herre wara på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Och war en wäldig jägare för HERranom. Deraf är det ordspråket: Det är en wäldig jägare för HERranom, såsom Nimrod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Och hans rikes begynnelse war Babel, Erech, Acad och Calne uti Sinear land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Utaf det landet är sedan kommen Assur, och han byggde Ninewe och Rehoboth, och Calah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Och dertil Resen emellan Ninewe och Calah: Detta är en stor stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim födde Ludim, Anamim, Lehabim, Naphtuhim,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrusim och Castuhim. Af hwilkom utkomne äro de Philistim och Caphthorim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Men Canaan födde Zidon sin första son, och Heth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebusi, Emori, Girgasi,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hiwi, Archi, Sini,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arwadi, Semari och Hamathi. Af dem äro utspridde de Cananeers slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Och deras gränsor woro ifrå Zidon genom Gerar, allt intil Gaza, til dess man kommer intil Sodoma, Gomorra, Adama, Zeboim, och intil Lasa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Desse äro nu Hams barn i deras slägter, tungomålom, landom och folkom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Men Sem, Japhets broder, den äldste, födde ock barn, hwilken en fader är til all Ebers barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Och desse äro hans barn: Elam, Assur, Arphachsad, Lud och Aram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Arams barn äro desse: Uz, Hul, Gether och Mas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arphachsad födde Salah, Salah födde Eber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eber födde twå söner, en het Peleg, derföre, at i hans tid wardt werlden delad; hans broder het Jaketan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Och Jaketan födde Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikela,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Seba,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hawila och Jobab. Alle desse äro Jaketans söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Och deras boning war ifrå Mesa, intil man kommer til Sephar på berget öster ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dessa äro Sems barn, uti deras slägter, tungomålom, landom och folkom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Detta är nu Noahs barns afföda, uti deras slägter och folkom. Af hwilkom utspridt är folket på jordene efter floden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Och all werlden hade enahanda tungo och mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Då de nu drogo öster ut, funno de en plan uti Sinear Land, och bodde der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Och sade til hwarannan: Kommer, låter oss slå tegel och bränna. Och togo tegel för sten, och ler för kalk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Och sade: Kommer, låter oss bygga en stad och et torn, hwilkets högd skall räcka up i himmelen, at wi måge göra oss et namn, förty wi warde til äfwentyrs spridde ut i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Då steg HERren neder, at han skulle se staden och tornet, som menniskones barn byggde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Och HERren sade: Si, det är enahanda folk, och enahanda mål ibland dem alla, och hafwa detta begynt at göra, de warda icke aflåtande af allt det de hafwa sig företagit at göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Kommer, låter oss stiga neder och förbistra der deras tungomål, så at ingen skall förstå den andras mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Och så skingrade HERren dem dädan i all land, så at de återwände bygga staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Derföre kallades hans namn Babel, ty at HERren der förbistrade all lands tungomål, och HERren spridde dem dädan ut i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Detta är Sems slägt: Sem war hundrade år gammal, och födde Arphachsad, tu år efter floden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Och lefde derefter i femhundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arphachsad war fem och tretio år gammal, och födde Salah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Och lefde derefter fyrahundrade och tre år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Salah war tretio år gammal, och födde Eber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Och lefde derefter fyrahundrade och tre år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber war tretio och fyra år gammal, och födde Peleg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Och lefde derefter fyrahundrade och tretio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg war tretio år gammal, och födde Regu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Och lefde derefter i tuhundrade och nio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu war tu och tretio år gammal, och födde Serug.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Och lefde derefter tuhundrade och sju år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug war tretio år gammal, och födde Nahor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Och lefde derefter tuhundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor war nio och tjugu år gammal, och födde Tharah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Och lefde derefter hundrade och nitton år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Och lefde derefter hundrade och nitton år, och födde Abram, Nahor och Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Desse äro Tharahs slägter: Tharah födde Abram, Nahor och Haran. Haran födde Lot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Och dödde Haran när sinom fader Tharah, uti hans faders land i Ur i Chaldeen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Då togo Abram och Nahor sig hustrur: Abrams hustru het Sarai, och Nahors hustru Milca Harans dotter, den fader war åt Milca och åt Jisca.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Men Sarai war ofruktsam, och hade inga barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Så tog Tharah sin son Abram, och Lot sins sons Harans son, och sina sonahustru Sarai sins sons Abrams hustru, och förde dem ifrån Ur utu Chaldeen, på det de skulle fara i Canaans land; och de kommo till Haran, och bodde der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Och Tharah wardt tuhundrade och fem år gammal, och blef död i Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Och HERren talade til Abram: Gack utu ditt fädernes land, och ifrå dine slägt, och ifrå dins faders huse, uti et land, som jag dig wisa will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Och jag skall göra dig til et stort folk, jag skall wälsigna dig, och göra dig et stort namn, och du skalt wara en wälsignelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Jag skall wälsigna dem som dig wälsigna, och förbanna dem som dig förbanna: Och i dig skola wälsignade warda alla slägter på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Då for Abram ut, såsom HERren honom sagt hade, och Lot for med honom. Men Abram war sjutio och fem år gammal, då han for utaf Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Så tog Abram sina hustru Sarai och Lot sin broderson, med alla deras håfwor, som de förwärfwat hade, och de själar, som de födt hade i Haran, och foro ut til at resa in i Canaans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Och som de komne woro in i landet, drog han derigenom allt intil det rummet Sichem, och intil den lunden More. På den tiden bodde de Cananeer der i landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Då syntes HERren Abram och sade: Dine säd skall jag gifwa detta land. Och han byggde dersammastädes et altare HERranom, som honom synts hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Sedan drog han bätter fram dädan til et berg, som låg öster ut ifrå BethEl, och slog der sitt tjäll up, så at han hade BethEl wäster ut, och Ay öster ut, och byggde der HERranom et altare, och predikade om HERrans namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Och for Abram dädan fram bätter, och drog söder ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Då wardt en hård tid der i landet, derföre drog Abram neder uti Egypten, at han der en främling blifwa måtte, förty tiden war ganska hård i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Och då han kom hardt in emot Egypten, talade han til sina hustru Sarai: Si, jag wet, at du äst en dägelig qwinna under ansiktet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Då nu de Egyptier få se dig, skola de säga: Det är hans hustru, och slå mig ihjäl, och behålla dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Kära, säg fördenskull, at du äst min syster, at mig måtte ske godt för dina skull, och at min själ må lefwa för dina skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Som han nu kom uti Egypten, sågo de Egyptier qwinnona, at hon war ganska dägelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Och Pharaos öfwerstar sågo henne, och prisade henne för honom. Då wardt hon tagen in uti Pharaos hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Och Abram wederfors godt för hennes skull. Och han hade får, fä, åsnar, tjenare och tjenarinnor, åsninnor och cameler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Men HERren plågade Pharao med stora plågor, och hans hus, för Sarai Abrams hustrus skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Då kallade Pharao Abram til sig, och sade til honom: Hwi hafwer du sådant gjort mig? Hwi sade du mig icke, at hon war din hustru?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Hwi sade du, at det war din syster? Fördenskull wille jag taga henne til hustru. Och si, nu hafwer du här dina hustru, tag henne och gack.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Och han befallte sina män om honom, at de skulle fordra honom och hans hustru, och allt det han hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Så for då Abram up utur Egypten med sine hustru, och med allt det han hade, och Lot ock med honom, söder ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Och Abram war ganska rik på boskap, silfwer och guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Och han for bätter fram ifrå sönnan allt intil BethEl, til det rummet, der han sitt tjäll tilförene haft hade, emellan BethEl och Ay.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Rätt på samma rum, der han tilförene hade byggt altaret. Och der predikade han HERrans namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Men Lot, som med Abram for, hade också får, och fä, och tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Och landet kunde icke fördragat, at de bodde tilhopa, förty deras håfwor woro stora, och kunde icke bo med hwarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Och war ju alltid träta emellan herdarna öfwer Abrams boskap och herdarna öfwer Lots boskap. Och bodde desslikes i den tiden de Cananeer och Phereseer der i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Då sade Abram til Lot: Käre, låtom icke wara träta emellan mig och dig, och emellan mina och dina herdar ty wi äre bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Står icke allt landet dig öpet? Käre, skilj dig ifrå mig. Wilt du til wänstra handena, så will jag til den högra; eller wilt du til den högra, så will jag til den wänstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Då hof Lot sin ögon up, och besåg den hela ängden wid Jordan. Förty, förra än HERren förderfwade Sodom och Gomorra, war hon watturik, allt intil man kommer till Zoar, såsom en HERrans lustgård, lika som Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Så utwalde sig Lot den hela ängden wid Jordan, och drog öster ut. Och så skildes den ene brodren ifrå den andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'At Abram bodde i Canaans land, och Lot i samma ängdens städer, och slog sitt tjäll up in mot Sodom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Men det folk i Sodom war ondt, och syndade swårliga emot HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Då nu Lot hade skilt sig ifrån Abram, sade HERren (til Abram): Häf up din ögon, och se ifrå det rummet, der du nu bor, norr ut, söder ut, öster ut och wester ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Förty allt detta landet, som du ser, will jag gifwa dig och dine säd til ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Och will göra dina säd såsom stoftet på jordene. Kan en menniska räkna stoftet på jordene, så må hon ock räkna dina säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Derföre up, och drag genom landet, och ändalängs: Förty dig will jag gifwa det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Så tog Abram sitt tjäll up, och kom och bodde wid den lunden Mamre, hwilken i Hebron är, och byggde dersammastädes HERranom et altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Och det begaf sig i Amraphels tid Konungens af Sinear, Ariochs Konungens i Ellasar, Kedor Laomers Konungens i Elam, och Thideals Hedningarnas Konungs,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'At de örligade med Bera Konungenom i Sodom, och med Birsa Konungenom i Gomorra, och med Sineab Konungenom i Adama, och med Semeber Konungenom i Zeboim, och med Konungenom i Bela, det är Zoar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Desse kommo alle tilsammans i den dalenom Siddim, der nu är salthafwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Förty de hade warit i tolf år under Konung Kedor Laomer, och uti de trettonde årena woro de honom affallne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Derföre kom Kedor Laomer och de Konungar, som med honom woro, uti de fjortonde årena, och slogo de Resar i Astaroth Karnaim, och de Susim i Ham, och de Emim på den planenom Kiriathaim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Och de Horeer på deras berg Seir, intil den planen Pharan, som skjuter in på öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Sedan wände de om, och kommo til den brunnen Mispat, det är Kades, och slogo hela de Amalekiters land, dertil de Amoreer, som i Hazezon Thamar bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Så drogo ut Konungen i Sodom, Konungen i Gomorra, Konungen i Adama, Konungen i Zeboim, och Konungen af Bela, det Zoar heter, och rustade sig til at strida i den dalenom Siddim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Med Kedor Laomer Konungen i Elam, och med Thideal Hedningarnas Konung, och med Amraphel Konungenom i Sinear, och med Arioch Konungenom i Ellasar: Fyra Konungar emot fem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Och den dalen Siddim hade många lergropar. Men Konungen i Sodom och Gomorra wordo der slagne på flyktena och nederlagde, och de som öfwerblefwo flydde up på berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Så togo de alla ägodelar i Sodom och Gomorra, och alla fetalia, och drogo sina färde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Och togo desslikes med sig Lot Abrams broders son och hans ägodelar, ty han bodde i Sodom, och drogo sin wäg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Då kom en, som undsluppen war, och sade det för Abram, den en utländing war, och bodde i den lundenom Mamre, dens Amoreens, hwilken Escols och Aners broder war: Desse woro i förbund med Abram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Som nu Abram hörde, at hans broder war fången, wäpnade han sina egna hemfödda tjenare, trehundrade och aderton, och drog efter dem allt intil Dan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Delade sig, och föll til dem med sina tjenare om nattena, och slog dem, och fullföljde dem allt intil Hoba, som ligger på wänstra handen wid den staden Damasco,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Och tog alla ägodelar igen, och dertil Lot sin broder och hans ägodelar, och qwinnorna, och folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Då han nu igen kom, och hade afslagit Kedor Laomer och de Konungar med honom, gick Konungen i Sodom emot honom på den planenom, som het Konungsdalen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Men Melchisedech, Konung i Salem, bar fram bröd och win: Och han war den högstes Guds Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Och wälsignade honom, och sade: Wälsignad ware du Abram dem högsta Gudi, den himmel och jord tilhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Och lofwad ware Gud den högste, som dina fiender beslutit hafwer i dina hand. Och honom gaf Abram tionde af allo byte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Då sade Konungen af Sodom til Abram: Gif mig folket, och ägodelarne behålt för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Men Abram sade til Konungen af Sodom: Jag upphäfwer mina händer til HERran den högsta Gud, som himmel och jord tilhörer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'At jag af allo det ditt är icke en tråd eller en skorem taga will, at du icke skalt säga: Jag hafwer riktat Abram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Undantagno det de unge karlar förtärt hafwa, och de män, som med mig drogo, Aner, Escol och Mamre, dem låt taga deras del.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Sedan detta så skedt war, begaf sig, at HERrans ord i en syn kom til Abram, sägandes: Frukta dig intet, Abram, jag är ditt beskärm och din ganska stora lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Men Abram sade ytterligare: Men mig hafwer du ingen säd gifwit. Och si, mins tjenares son skall wara min arfwinge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Och si, HERrans ord kom til honom, sägandes: Han skall icke wara din arfwinge, utan den, som utaf ditt lif komma skall, han skall wara din arfwinge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Och han hade honom ut, och sade: Se up til himmelen, och räkna stjernorna, om du kan räkna dem. Och sade til honom: Så skall din säd wara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram trodde HERranom, och han räknade honom det til rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Och han sade til honom: Jag är HERren, som dig utfört hafwer ifrån Ur utu Chaldeen, at jag dig detta land gifwa skall til besittning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram sade: HErre, HERre, hwaruppå skall jag märka, at jag skall besitta det?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Och han sade til honom: Tag mig ena treåra ko, och ena treåra get, och en treåra wädur, och ena turturdufwo, och ena unga dufwo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Och han tog allt detta, och delade det midt i tu ifrå hwart annat, och lade hwar delen twärt emot den andra: Men foglarne delade han intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Och foglarne kommo neder på kropparna, och Abram dref bort dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Då solen nedergången war, föll en swår sömn på Abram, och si, en förskräckelse och et stort mörker kom öfwer honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Då sade han til Abram: Detta skalt du weta, at din säd skall warda främmande uti et land, det dem icke tilhörer, och man skall der göra dem til trälar och fara illa med dem i fyrahundrade år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Men öfwer det folk, som de tjenande warda, skall jag domare wara: Sedan skola de draga ut med stora håfwor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Och du skalt fara til dina fäder med frid, och i en god ålder begrafwen warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Men de skola i fjerde mans ålder komma hit igen; förty de Amoreers ondska är icke ännu all fullkomnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Då nu solen war nedergången, och mörker wordet, si, då rök en ugn, och en eld for emellan stycken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'På den dagen gjorde HERren et förbund med Abram, och sade: Dine säd skall jag gifwa detta landet, ifrå den älfwene i Egypten, allt intil den stora älfwen Phrath:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'De Keneer, de Keniseer, de Kadmoneer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'De Hetheer, de Phereseer, de Reser,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'De Amoreer, de Cananeer, de Girgaseer, de Jebuseer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai Abrams hustru födde honom intet: Men hon hade ena Egyptiska tjensteqwinno, som het Hagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Och sade til Abram: Si, HERren hafwer igenlyckt mig, at jag icke kan få barn: Käre, lägg dig när mina tjensteqwinno, at jag dock tiläfwentyrs måtte upbyggd warda af henne. Abram hörde Sarai röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Och Sarai Abrams hustru tog sina Egyptiska tjensteqwinno Hagar, och gaf henne Abram sinom man til hustru, sedan de hade bott i tio år i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Och han lade sig när Hagar, och hon wardt hafwande: Då hon nu såg, at hon wardt hafwande, föraktade hon sina fru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Då sade Sarai til Abram: Du gör orätt emot mig: Jag hafwer laggt mina tjensteqwinno när dig; nu, efter hon ser at hon här hafwande worden, måste jag ringa aktad warda för henne: HERren dömme emellan mig och dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Men Abram sade til Sarai: Si, din tjensteqwinna är under ditt wåld, gör med henne, som dig täckes. Då nu Sarai wille späka henne, flydde hon ifrå henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Men HERrans Ängel fann henne wid en wattenbrunn i öknene, nemliga wid den brunnen, som är på den wägen til Sur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Och sade til henne: Hagar, Sarai tjensteqwinna, hwadan kommer du? Eller hwart wilt du? Hon sade: Jag hafwer flytt ifrå mine fru Sarai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Och HERrans Ängel sade til henne: Wänd om til dina fru igen, och ödmjuka dig under hennes hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Och HERrans Ängel sade til henne: Jag skall så föröka dina säd, at för stor myckenhet skall hon icke kunna räknas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Yttermera sade HERrans Ängel til henne: Si, du äst hafwande worden, och skalt föda en son, hans namn skalt du kalla Ismael, derföre, at HERren hafwer sett dina wedermödo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Han skall wara en grym man: Hans hand emot hwar man, och hwars mans hand emot honom: Och han skall bo emot alla sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Och hon kallade HERrans namn, som talade med henne: Du Gud ser mig; ty hon sade: Wisserliga hafwer jag här sett ryggen på honom, som mig ser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Derföre kallade hon brunnen en brunn dens lefwandes, som mig ser, hwilken är emellan Kades och Bared.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Och Hagar födde Abram en son, och Abram kallade den sonen, som Hagar födde honom, Ismael.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Och Abram war sex och åttatio år gammal, då Hagar födde honom Ismael.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Då nu Abram nio och niotio år gammal war, syntes honom HERren, och sade til honom: Jag är Gud allsmäktig: Wandra för mig och war fullkomlig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Och jag skall göra mitt förbund emellan mig och dig, och jag skall föröka dig swårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Och Abram föll på sitt ansikte: Och Gud talade yttermera med honom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Si, Jag äret, och hafwer mitt förbund med dig, och du skalt warda en fader för mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Derföre skall du icke mer heta Abram, utan Abraham skall wara ditt namn: Ty jag hafwer gjort dig til en fader för mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Och skall göra dig ganska mycket fruktsamman, och skall göra folk af dig: Skola ock Konungar komma af dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Och jag will göra mitt förbund emellan mig och dig, och dina säd efter dig, i deras afkommandom, at det skall wara et ewigt förbund, så at jag skall wara din Gud, och dine säds efter dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Och skall gifwa dig, och dine säd efter dig, det land, der du en främling uti äst, nemliga, det hela landet Canaan til ewig besittning; och skall wara deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Och Gud sade yttermera til Abraham: Så hålt nu mitt förbund, du, och din säd efter dig, i deras afkommandom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Och detta är förbundet, som I hålla skolen, emellan mig och dig, och dina säd efter dig: Allt det mankön ibland eder är skall omskäras.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Men I skolen omskära edars kötts förhud. Det samma skall wara et tekn til förbundet emellan mig och eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Hwart och et piltebarn, då det är åtta dagar gammalt, skolen I omskära i edra afkommander. Sammalunda hwar och en tjenare, hemma födder eller köpter, eller eljest främmande, och icke af edro säd är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Och så skall mitt förbund wara på edro kötte, til et ewigt förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Och hwar något piltebarn icke warder omskoret i hans kötts förhud, hans själ skall utrotas utu hans folk, derföre, at han mitt förbund icke hållit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Och Gud sade åter til Abraham: Dina hustru Sarai skalt du icke mer kalla Sarai, utan Sara skall wara hennes namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ty jag skall wälsigna henne, och af henne skall jag gifwa dig en son, hwilken jag skall wälsigna, och folk skola warda af honom, och Konungar öfwer mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Då föll Abraham på sitt ansikte, och log, och sade i sitt hjerta: Skulle mig, som hundrade år gammal är, födas en son? Och Sara, som niotio år gammal är, skulle föda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Och Abraham sade til Gud: Ack, at dock Ismael måtte få lefwa för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Då sade Gud: Ja, Sara din hustru skall föda dig en son, hwilken du skalt kalla Isaac: Ty med honom skall jag uprätta mitt ewiga förbund, och med hans säd efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Der til hafwer jag ock bönhört dig om Ismael: Si, jag hafwer wälsignat honom, och skall göra honom fruktsamman, och föröka honom ganska swårliga: Tolf Förstar skall han föda, och jag skall göra honom til mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Men mitt förbund skall jag upprätta med Isaac, den Sara dig föda skall, på denna tidenom åt året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Och som talet wardt ändadt, for Gud up ifrån Abraham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Och Abraham tog sin son Ismael och alla tjenare, hemma födda och köpta, och allt det mankön war i hans huse, och omskar förhudena på deras kött, strax på samma dagenom, som Gud honom sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Och Abraham war nio och niotio år gammal, då han omskar förhudena på sitt kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Men Ismael hans son war tretton år gammal, då hans kötts förhud omskoren wardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Allt på enom dag wordo de alle omskorne, Abraham och hans son Ismael;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Och allt det mankön war i hans huse, både hemfödde tjenare och köpte, och eljest främmande,: Alle wordo de omskorne med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Och HERren syntes honom i dem lundenom Mamre, der han satt wid sins tjälls dör, då hetast war på dagenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Och som han uplyfte sin ögon och såg, då stodo tre män för honom. Och då han såg dem, lopp han emot dem ifrå sins tjälls dör, och bugade sig ned på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Och sade: HERre, hafwer jag funnit nåd för din ögon, så gack icke fram om din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man will hemta eder litet af watn och twå edra fötter, och hwiler eder under trät.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Och jag will lägga för eder et stycke bröd, at I wederqwecken edor hjerta; sedan gån I då fram bätter, förty derföre ären I komne til edar tjenare. De sade: Gör, som du hafwer sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham skyndade sig in i tjället til Sara, och sade henne: Skynda dig, och blanda tre mått semlomjöl, och baka kakor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Men han lopp bort til boskapen, och tog en god späd kalf, och fick drängenom; han skyndade sig, och tilredde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Och han tog fram smör och mjölk, och af kalfwenom, som han tilredt hade, och satte för dem; och gick fram för dem under trät, och de åto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Då sade de til honom: Hwar är din hustru Sara? Han swarade: Derinne i tjället.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Han sade: När jag igenkommer til dig, om man lefwer, si, så skall Sara din hustru hafwa en son. Detta hörde Sara, der hon stod bak tjälldörena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Och de woro, både Abraham och Sara, gamle och wäl til ålders komne, så at Sara nu icke mer hade som qwinnor plägar hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Derföre log hon wid sig sjelf, och sade: Nu jag gammal är, och min herre desslikes ålderstigen, skall jag ännu gifwa mig til lusta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Då sade HERren til Abraham: Hwi log Sara, sägandes: Menar du, at det kan wara, at jag ännu föda skall, så gammal som jag är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Mån HERranom något wara omöjeligit? I sinom tid will jag komma til dig igen, om man lefwer, och då skall Sara hafwa en son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Då nekade Sara, och sade: Jag log intet, och wardt förfärad. Men han sade: Det är icke så, du logst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Då stodo männerne up dädan, och wände sig åt Sodom, och Abraham följde dem och ledsagade dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Och HERren sade: Huru kan jag dölja för Abraham det jag gör?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Efter han skall warda til et stort och mägtigt folk, och all folk på jordene skola warda wälsignade i honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Ty jag wet, at han befaller sinom barnom, och sino huse efter sig, at de skola hålla HERrans wägar, och göra hwad rätt och godt är, på det at HERren skall låta komma öfwer Abraham allt det han honom låfwat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Och HERren sade: I Sodom och Gomorra är et rop, det är stort, och deras synder äro ganska swåra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Derföre skall jag fara ned och se til, om de allt gjort hafwa efter ropet, som för mig kommit är; eller om det icke så är, at jag må wetat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Och männerne wände sitt ansikte och gingo åt Sodom. Men Abraham wardt ståndandes för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Och trädde fram til honom, och sade: Wilt du då förgöra den rättfärdiga med den ogudaktiga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Kunde hända, at i stadenom woro femtio rättfärdige, wille du dem förgöra, och icke skona de rummena för femtio rättfärdigas skull, som derinne woro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Bort det ifrå dig, at du det göra skulle, och döda den rättfärdiga med den ogudaktiga, och at dem rättfärdiga skulle gå lika som de ogudaktiga; bort det ifrå dig, som alla werldenes domare äst, sådana straff låter du icke gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'HERren sade: Finner jag femtio rättfärdiga i Sodoms stad, så will jag skona allestäds i all rum för deras skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham swarade och sade: Ack si, jag hafwer tagit mig före at tala med HERranom, ändock jag är stoft och aska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Om der woro fem mindre än femtio rättfärdige inne, wille du då förgöra hela staden för de fem skull? Han sade: Finner jag derinne fem och fyratio, så will jag icke förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Och han talade ändå ytterligare til honom, och sade: Måtte hända, at man finner der fyratio inne. Och han sade: Jag will intet göra dem för de fyratio skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Och Abraham sade: HERre, tag icke til misstycke, om jag ännu talar något: Måtte hända, at man finner der tretio inne. Han swarade: Finner jag der tretio inne, så will jag intet göra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Och han sade: Ack si, jag hafwer tagit mig före at tala med min HERra: Måtte hända, at man finner tjugu derinne. Han swarade: Jag will icke förgöra dem för de tjugu skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Och han sade: Tag icke til misstycke, HERre, om jag talar än en tid: Måtte hända, at man finner tio derinne. Han sade: Jag will icke förgöra dem för tio skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Och HERren gick bort, sedan han hade uttalat med Abraham: Och Abraham wände om och gick hem til sitt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Och de twå Änglarne kommo om aftonen til Sodom; och Lot satt i Sodom i portenom: Och då han såg dem, stod han up emot dem, och bugade sig med sitt ansikte neder på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Och sade: Si Herre, kommer uti Si Herre, kommer uti edar tjenares hus, och blifwer der öfwer nattena: Låter twå edra fötter, och i morgon stån I bittida up, och faren edar wäg. De sade: Nej, men wi wilje blifwa öfwer nattena på gatone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Då nödgade han dem fast, och de gingo in med honom, och de kommo uti hans hus: Och han gjorde dem en måltid, och bakade dem osyradt bröd, och de åto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Men förra än de lade sig, kommo de män af stadenom Sodom, och omhwärfde huset, unge och gamle, och allt folket tilhopa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Och kallade Lot ut, och sade til honom: Hwar äro männerne, som til dig ingångne äro i denna nattene? Låt dem gå här ut til oss, at wi måge känna dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot gick ut til dem för dörene, och smälde dörena igen efter sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Och sade: Ack käre bröder, görer icke så illa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Si, jag hafwer twå döttrar, de hafwa ännu ingen man känt, dem will jag få ut til eder, och farer med dem som eder täckes; at I ju intet ondt gören dessa männerna: Ty derföre äro de ingångne under mitt taks skugga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Men de sade: Kom hit. Då sade de: Äst du icke allena en främling härinne, och wilt nu regera? Nu wäl, wi wilje göra dig mera ondt än dem. Och de trängde sig hårdeliga med wåld in på mannen Lot, och de lupo til, och wille slå up dörena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Men männerne räckte handen ut, och togo Lot in til sig i huset, och smälde dörena til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Och männerna, som för dörene woro af huset, slogo de med blindhet, både små och stora, så at de icke kunde finna dörena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Och männerne sade til Lot: Hafwer du ock härinne några mågar, eller söner, eller döttrar? Alla de, som dig tillhöra i stadenom, dem haf här utu detta rummet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Ty wi skole förgöra detta rummet; derföre, at deras rop är stort för HERranom, och HERren hafwer utsändt oss til att förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Då gick Lot ut, och talade med sina mågar, som skulle hafwa hans döttrar, och sade: Görer redo, och går utu detta rum: förty HERren skall förgöra denna stad. Men dem syntes det wara gabberi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'När nu morgonroden upgick, skyndade Änglarne på Lot, at han skulle låta sig lida, och sade: Gör redo, tag dina hustru, och dina twå döttrar, som du hafwer, at du ock icke förgås uti denna stadsens missgerningom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Som han ännu fördröjde, togo männerne honom wid handena, och hans hustru, och hans twå döttrar, efter HERren wille skona dem, och ledde honom ut, och läto honom ut för staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Och som de hade haft honom ut, sade de: Förwara dina själ, och se icke tillbaka, och statt icke i alla denna ängd; men på berget undsätt dig, at du icke förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Då sade Lot til dem: Ack nej, min Herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Si, efter din tjenare hafwer funnit nåd för din ögon, så gör dock dina barmhertighet stora, som du på mig bewist hafwer, at du skulle behålla mina själ wid lif: Jag kan icke förwara mig på bergena, mig måtte något ondt wederkomma, at jag blefwe död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Si, der är en stad icke långt hädan, der jag infly må, och han är liten, der will jag förwara mig: Är han dock liten, at min själ må der blifwa wid lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Då sade han til honom: Si, i desse stycke hafwer jag ock sett til dig, at jag icke will omstörta den staden, der du om talade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Låt lida dig, och förwara dig der; ty jag kan intet göra, til dess du kommer der in. Der af är den staden nämnd Zoar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Och solen war upgången på jordene, då Lot kom in uti Zoar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Då lät HERren regna swafwel och eld ifrå HERranom af himmelen, öfwer Sodom och Gomorra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Och omstörte de städer i alla den ängden, och alla de, som i städerna bodde, och allt det på landena wäxt war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Och hans hustru såg tilbaka, och wardt en saltstod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Men Abraham stod up om morgonen bittida, på det rummet, der han förr hade ståndet för HERranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Och såg ut emot Sodom och Gomorra, och allt landet i den ängden, och fick se, at der upgick et damb af landena, lika som en rök af en ugn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Ty då Gud omstörte de städer i den ängdene, tänkte han på Abraham, och frälste Lot utu de städer, som han omstörte, der Lot uti bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Och Lot for utu Zoar, och blef på bergena med båda sina döttrar; ty han fruktade at blifwa i Zoar: Och låg uti ene bergskrefwo, han och båda hans döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Då sade den äldsta til den yngsta: Wår fader är gammal, och ingen man är mer på jordene, som til oss ingå kan, efter alla werldenes sedwänjo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Kom, låt oss gifwa wår fader dricka win, och läggom oss när honom, at wi mågom behålla säd af wår fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Och så gåfwo de deras fader dricka win i den nattene: Och den äldsta gick in, och lade sig när sinom fader: Och han wardt intet warse, när hon lade sig, ej heller när hon stod up.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Om morgonen sade den äldsta til den yngsta: Si, jag låg i går när min fader, låt oss ock i denna nattene gifwa honom dricka win, at du ock må gå in til honom, och lägga dig när honom, at wi behålle säd af wår fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Och så gåfwo de desslikes i den nattene sin fader dricka win: Och den yngsta gick ock in, och lade sig när honom: Och han wardt det intet warse, när hon lade sig ned, ej heller när hon stod up.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Och så wordo de båda Lots döttrar hafwande af sin fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Och den äldsta födde en son, den hon kallade Moab: Af honom kommo de Moabiter, allt intil denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Och den yngsta födde ock en son, och hon kallade hans namn Ammi barn: Af honom kommo Ammons barn, allt intil denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Så for Abraham dädan in i landet söder ut, och bodde emellan Kades och Zur, och wardt en främling i Gerar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Och sade om sine hustru Sara: Det är min syster. Då sände Abimelech, Konungen i Gerar, efter henne, och lät hemta henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Men Gud kom til Abimelech om nattena i dröm, och sade til honom: Si, du måste dö för den qwinnones skull, som du tagit hafwer; ty hon är ens mans ägta hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Men Abimelech hade ännu intet kommit wid henne. Och han sade: HERre, wilt du ock dräpa et rättfärdigt folk?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Sade han icke til mig: Hon är min syster? Och hon sade desslikes: han är min broder. Hafwer jag dock detta gjort med enfaldigt hjerta och oskyldiga händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Och Gud sade til honom i drömmen: Jag wet ock, at du det med enfaldigo hjerta gjort hafwer: Derföre hafwer jag ock bewarat dig, at du icke skulle synda emot mig, och hafwer icke tillstadt, at du skulle komma wid henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Så få nu mannenom sina hustru igen; ty han är en Prophet, och låt honom bedja för dig, så behåller du lifwet: Hwar du icke öfwergifwer henne, så wet, at du måste döden dö, och allt det dig tilhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Då stod Abimelech bittida up om morgonen, och kallade alla sina tjenare, och sade allt detta i deras åhöro. Och de män alle fruktade sig swårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Och Abimelech kallade också Abraham, och sade til honom: Hwi hafwer du oss detta gjort? Och hwad hafwer jag brutit dig emot, at du wille komma så stor synd uppå mig och mitt rike? Du hafwer icke så gjort emot oss, som man göra skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Och Abimelech sade ytterligare til Abraham: Hwad hafwer du ansett, at du så gjorde?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham sade: Jag tänkte til äfwentyrs i desso rumme är ingen Gudsfruktan, och de slå mig ihjäl för mine hustrus skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Och är hon sannerliga min syster; ty hon är min faders dotter, men icke mine moders dotter: Och jag tog mig henne til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Och då Gud böd mig, at jag skulle wandra utu mins faders huse, sade jag til henne: Gör denna barmhertighet med mig, hwart wi kommom, at du säger, at jag är din broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Då tog Abimelech får och fä, tjenare och tjenarinnor, och gaf Abraham, och fick honom igen hans hustru Sara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Och sade: Si, mitt land står dig öpet, bo war dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Och sade til Sara: Si, jag hafwer gifwit dinom broder tusende silfwerpenningar: Si, han skall wara dig til en ögnatäckelse för alla de, som när dig äro, ehwart du far, och en förswarare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Och Abraham bad til Gud, och Gud botade Abimelech, och hans hustru, och hans tjensteqwinnor, at de födde barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Ty HERren hade tilförene hårdeliga tillyckt alla qweder i Abimelechs huse, för Sara Abrahams hustrus skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Och HERren sökte Sara, såsom han sagt hade, och HERren gjorde med henne såsom han talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Och Sara wardt hafwande, och födde Abraham en son i sinom ålderdom, wid den tiden, som Gud honom föresagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Och Abraham nämnde sin son, som honom född war, Isaac, den honom Sara födt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Och omskar honom på åttonde dagen, som Gud honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Hundrade år gammal war Abraham, då honom hans son Isaac födder war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Och Sara sade: Gud hafwer gjort mig et löje; ty hwilken det får höra, han får le åt mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Och sade ytterligare: Ho torde ock säga Abraham sjelfwom, at Sara dägde barn, och hade födt honom en son i sinom ålderdom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Och barnet wäxte, och wardt afwandt: Och Abraham gjorde et stort gästabud den dagen, då Isaac afwandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Och Sara fick se den Egyptiska qwinnones Hagars son, den hon Abraham födt hade, at han war en bespottare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Och sade til Abraham: Drif denna tjensteqwinnona ut med hennes son; ty denne tjensteqwinnones son skall icke ärfwa med min son Isaac.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Detta ordet behagade Abraham ganska illa för sin sons skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Men Gud sade til honom: Låt dig icke tycka hårdt wara om pilten och tjensteqwinnone: Allt det Sara dig sagt hafwer, så lyd henne: Förty i Isaac skall säden dig nämnd warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Jag skall ock göra tjensteqwinnones son til folk, derföre, at han din säd är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Då stod Abraham bittida up om morgonen, och tog bröd och en flaska med watn, och lade på Hagars rygg, och pilten med, och lät gå henne. Hon gick sin wäg, och for will i öknene, wid BerSaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Då nu watnet i flaskone war förtärdt, kastade hon pilten under en buska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Och gick bort och satte sig twärs öfwer långt ifrå, wid et armborst skott; ty hon sade: Jag gitter icke se uppå at pilten dör. Och wid hon satt twärs öfwer, hof hon up sina röst, och gret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Då hörde Gud piltens röst, och Guds Ängel kallade Hagar af himmelen, sägandes: Hwad skadar dig, Hagar? Frukta dig intet; förty Gud hafwer hört piltens röst, der han ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Statt up, tag pilten, och hålt honom med dina händer: Ty jag skall göra honom til stort folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Och Gud öpnade hennes ögon, at hon fick se en wattubrunn. Då gick hon til och fylde sina flasko med watn, och gaf piltenom dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Och Gud war med piltenom; han wäxte, och bodde i öknene, och wardt en god skytte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Och bodde i den öknene Pharan: Och hans moder tog honom hustru utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'På samma tiden talade Abimelech och Phicol, hans härhöfwitsman, med Abraham, och sade: Gud är med dig uti allt det du gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Så swär mig nu wid Gud, at du är mig icke arg, eller minom barnom, eller minom barnabarnom: Utan den barmhertighet, som jag hafwer gjort med dig, den gör ock med mig, och landena, der du en främling uti äst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Då sade Abraham: Jag will swärja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Och Abraham straffade Abimelech för den wattubrunnens skull, som Abimelechs tjenare hade tagit med wåld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Då swarade Abimelech: Jag hafwer icke wist, ho det gjorde: Ej heller sade du mig det; dertil hafwer jag icke hört det förra än i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Då tog Abraham får och fä, och gaf Abimelech: Och gjorde båda et förbund med hwarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Och Abraham stälde sju lamb afsides.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Sade Abimelech til Abraham: Hwad skola de sju lamb, som du hafwer stält der afsides?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Han swarade: Sju lamb skall du taga af mine hand, at de skola wara mig til ert wittnesbörd, at jag denna brunn grafwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Och alltså gjorde de det förbund i BerSaba: Då stodo Abimelech och hans härhöfwitsman Phicol up, och drogo in i de Philisteers land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Och Abraham plantade trä i BerSaba; och predikade der om HERrans ewiga Guds namn:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Och war en främling uti de Philisteers land i långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Sedan det skedt war, försökte Gud Abraham, och sade til honom: Abraham. Och han swarade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Och han sade: Tag Isaac din enda son, den du kär hafwer, och gack bort uti Moria land, och offra honom der til et bränneoffer på et berg, det jag dig sägandes warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Då stod Abraham bittida up om morgonen, och sadlade sin åsna, och tog med sig twå drängar, och sin son Isaac, och högg sönder wed til bränneoffer, stod up och gick bort til det rum, som Gud honom sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'På tredje dagen hof Abraham sin ögon up, och såg rummet långt ifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Och sade til sina drängar: Blifwer I här med åsnanom, jag och pilten wiljom gå dit bort, och när wi tilbedit hafwom, wilje wi komma igen til eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Och Abraham tog weden til bränneoffret, och lade den på sin son Isaac: Men han tog elden och knifwen i sina hand, och gingo så både tilsamman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Då sade Isaac til sin fader Abraham: Min fader. Abraham swarade: Här är jag, min son. Och han sade: Si, här är elden och weden, hwar är nu fåret til bränneoffret?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham swarade: Gud förser wäl fåret, min son, til bränneoffret: Och de gingo både tilsamman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Och som de kommo til rummet, der Gud honom af sagt hade, byggde Abraham der et altare, och lade weden deruppå; bandt sin son Isaac, och lade honom på altaret, ofwan på weden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Och uträckte sina hand, och tog til knifwen, at han skulle slagta sin son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Då ropade honom HERrans Ängel af himmelen och sade: Abraham, Abraham. Han swarade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Han sade: Kom intet dina hand wid pilten, och gör honom intet; ty nu wet jag at du fruktar Gud, och hafwer icke skonat din enda son för mina skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Då hof Abraham sin ögon up, och såg en wädur bak sig, bekajad med hornen uti en törnebuska: Och gick dit, och tog den wäduren, och offrade honom til et bränneoffer i sins sons stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Och Abraham kallade det rummet, HERren ser: Af hwilko man ännu i dag säger: På berget, der HERren sedd warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Och HERrans Ängel ropade åter til Abraham af himmelen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Och sade: Jag hafwer sworit wid mig sjelf, säger HERren, efter du detta gjorde, och icke skonade din enda son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'At jag skall wälsigna, och föröka dina säd såsom stjernorna på himmelen, och såsom sanden på hafsens strand: Och dina säd skall besitta sina fiendars portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Och i dine säd skall allt folk på jordene wälsignadt warda; derföre, at du mine röst lydt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Sedan gick Abraham til drängarna igen, och gjorde sig redo, och drogo tilsammans til BerSaba, och bodde der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Då detta få skedt war, begaf sig, at Abraham wardt sagdt: Si, Milca hafwer ock födt barn dinom broder Nahor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Nemliga Uz den förstfödda, och Bus hans broder, och Kemuel, af hwilkom de Syrier komne äro:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Och Kesed, och Haso, och Pildas, och Jidlaph, och Bethuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Men Bethuel födde Rebecka. Dessa åtta födde Milca Nahor, Abrahams broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Och hans frilla benämbd Rehuma födde ock, nemliga Tebah, Saham, Thahas och Maacha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara lefde i hundrade sju och tjugu år:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Och blef död i den hufwudstaden, som kallas Hebron i Canaans lande: Då kom Abraham til at sörja och begråta henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Sedan stod han up ifrå hennes lik, och talade til Hets barn, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Jag är en främling och en gäst när eder, gifwer mig en arfrätt til begrafning när eder, at jag må begrafwa min döda, som för mig ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Då swarade Hets barn Abraham, och sade til honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Hör oss, käre herre, du äst en Guds förste när oss; begraf din döda uti wåra bästa grifter: Ingen menniska af oss skall förwägra dig, at du begrafwer din döda i hans graf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Då stod Abraham up, och bugade sig för landsens folke, nemliga för Hets barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Och han talade med dem, och sade: Är det eder i sinnet, at jag begrafwer min döda, som för mig ligger, så hörer mig, och beder för mig inför Ephron Zoars son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'At han gifwer mig sina dubbelkulo, den han hafwer i andanom på sinom åker, för reda penningar; låter mig henne få när eder til en arfgrift.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ty Ephron bodde ibland Hets barn. Då swarade Ephron, den Hetheen, Abraham i Hets barns åhöro, för allom dem, som ut och in gingo genom hans stadsport, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nej, min herre, utan hör til hwad jag säga will: Jag gifwer dig åkren, och den kulon med, som der inne är, och gifwer dig honom för mitt folks barns åsyn, til at begrafwa din döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Då bugade sig Abraham för landsens folke,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Och talade til Ephron i landsens folks åhöro, och sade: Will du höra mig, så tag penningar af mig för åkren, de jag dig gifwa will; och så will jag der begrafwa min döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron swarade Abraham, och talade til honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Min herre, hör dock mig: Marken är wärd fyrahundrade siklar silfwer; men hwad kan det draga emellan mig och dig? Begraf man din döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham hörde Ephron, och wog honom penningarna til, som han nämnt hade, hwilket Hets barn åhörde, nemliga fyrahundrade siklar silfwer, som då gåfwe och gängse woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Och så wardt Ephrons åker, der den dubbelkulan inne war, twärs öfwer Mamre, tilegnad Abraham til ewärdeliga ägo, med kulone derinne, och med all trä omkring åkren,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'I Hets barns och allas deras åsyn, som genom hans stadsport ut och in gingo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Sedan begrof då Abraham Sara sina hustru uti kulone i åkrenom, den dubbel war, twärs öfwer ifrå Mamre, det är Hebron i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Och alltså wardt Abraham stadfäst den åkren, och kulan, til begrafnings egendom af Hets barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Och Abraham war gammal och wäl ålderstigen: Och HERren hade wälsignat honom i all stycke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Då sade han til sin äldsta hustjenare, den all hans tingest förestod: Lägg dina hand under mina länd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Och swär mig wid HERran, himmelens och jordenes Gud, at du icke tager minom sone hustru af Canaans döttrar, ibland hwilka jag bor:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Utan far in uti mitt fädernesland, och til mina slägt, och tag minom sone Isaac hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Tjenaren sade: Om så hände, at qwinnan icke wille komma med mig in i detta land, skall jag då låta din son komma dit i landet igen, dädan du kommen äst?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sade til honom: Wakta dig derföre, at du icke förer min son dit igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'HERren himmelens Gud, som mig tog utu mins faders huse, och utu mitt födsloland, den med mig talat, och desslikes swurit och sagt hafwer: Detta landet will jag gifwa dine säd; han skall sända sin Ängel framför dig, at du skalt taga minom sone der hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Hwar nu qwinnan dig icke följa will; så äst du qwitt denna ed: Allenast låt icke min son komma dit igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Då lade tjenaren sina hand under Abrahams sins herras länd, och swor honom här uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Så tog tjenaren tio camelar, af sins herras camelar, och drog åstad, och hade med sig af allahanda sins herras håfwor, och war uppe, och for til Mesopotamien til Nahors stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Der lät han camelarna blifwa utanför stadenom, wid en wattubrunn, om aftonen då qwinfolken plägade der komma och taga watn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Och sade: Herre, mins herras Abrahams Gud, kom i dag emot mig, och gör barmhertighet med minom herra Abraham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Si, jag står här när wattubrunnenom, och deras döttrar, som bo i denna stad, warda här utkommande til at taga watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Hwar nu någon piga kommer, och jag säger til henne: Hålt hit dina kruko, och låt mig dricka, och hon säger: Drick, jag will ock gifwa dina camelar dricka, at hon är den samma, som du hafwer beskärt dinom tjenare Isaac, och at jag derpå må förstå, at du hafwer gjort barmhertighet med minom herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Och förra än han uttalat hade: Si, Rebecka Bethuels dotter kom ut, hwilken är Milcas son, den Nahors Abrahams broders hustru war, hon bar ena kruko på axlarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Och hon war en ganska dägelig piga under ansiktet, och war ännu jungfru, och ingen man hade känt henne: Hon kom ned til brunnen, och fylde krukona, och wille gå hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Då lopp tjenaren emot henne, och sade: Låt mig dricka något litet watn af dine kruko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Och hon sade: Drick, min herre: Och strax tog hon krukona ned på sina hand, och gaf honom dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Och då hon hade gifwit honom dricka, sade hon: Jag will ock ösa watn åt dina camelar, til dess at de få alle dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Och hon slog strax watnet utu krukone i hoen, och lopp åter til brunnen til at ösa, och watnade alla hans camelar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Men mannen undrade på henne, och war stilla, til dess han kunde få weta, om HERren hade gjort hans resa lyckosam, eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Då nu alle camelarne hade druckit, tog han fram et gyldene ännespann, wägandes en half sikel, och twå armringar til hennes händer, wägande tio siklar guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Och sade: Min dotter, hwem hörer du til? Säg mig dock det: Hafwe wi ock rum til at få herberge i dins faders huse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hon sade til honom: Jag är Bethuels dotter, Mikas sons, som hon hafwer födt Nahor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Och hon sade ytterligare til honom: Är ock så mycket halm och foder när oss, och rum nog til herberge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Då böjde mannen sig ned, och bad til HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Och sade: Lofwad ware HERren, mins herras Abrahams Gud, som icke hafwer tagit sina barmhertighet och sina sanning ifrå minom herra: Förty HERren hafwer fört mig den rätta wägen til mins herras broders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Och pigan lopp, och sade allt detta i sins moders huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Och Rebecka hade en broder, som het Laban: Och Laban lopp ut til mannen wid brunnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Och när han såg ännespannet och armringarna i sine systers händer, och hörde Rebeckas sine systers ord, at hon sade: Så hafwer mannen sagt mig; kom han til mannen: Och si, han stod när camelarna wid brunnen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Och sade: Kom här in, du HERrans wälsignade, hwi står du här ute? Jag hafwer rymt huset, och gjort rum för camelarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Så hade han mannen in i huset, och lade af camelarna, och gaf dem halm och foder, och watn til at twå hans fötter, och männernas, som med honom woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Och satte mat för honom. Då sade han: Jag will icke äta, förra än jag hafwer wärfwat mitt ärende. De swarade: Säg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Han sade: Jag är Abrahams tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Och HERren hafwer rikeliga wälsignat min herra, och han är stor worden, och han hafwer gifwit honom får och fä, silfwer och guld, tjenare och tjenarinnor, camelar och åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Der til hafwer Sara, mins herras hustru, födt minom herra en son i sinom ålderdom, honom hafwer han gifwit allt det han hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Och min herre hafwer tagit en ed af mig, och sagt: Du skalt icke taga minom sone någon hustru af de Cananeers döttrar, i hwilkas land jag bor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Utan far bort til mins faders hus, och til mina slägt, tag der minom sone hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Men jag sade til min herra: Huru? Om qwinnan icke will följa mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Då sade han til mig: HERren, för hwilkom jag wandrar, warder sändandes sin Ängel med dig, och skall göra din wäg lyckosam, så at du skalt taga minom sone hustru af mine slägt och mins faders huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Då skall du wara min ed qwitt, när du kommer til mina slägt; gifwa de dig icke, så äst du min ed qwitt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Så kom jag i dag til brunnen, och sade: HERre, mins herras Abrahams Gud, hafwer du gjort min wäg lyckosam, den jag nu reser:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Si, så står jag här wid wattubrunnen. När nu en jungfru kommer här ut til at taga watn, och jag säger til henne: Gif mig litet watn at dricka af dine kruko;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Och hon warder sägandes: Drick du; jag will ock watna dina camelar: det är den qwinna, som HERren hafwer beskärt mins herras sone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Förra än jag nu sådan ord utsagt hade i mino hjerta, si, då kom Rebecka ut med ene kruko på sine axel, och gick ned åt brunnen til at taga watn. Då sade jag til henne: Gif mig dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Och hon tog snarliga krukona af sin axel, och sade: Drick; dina camelar will jag ock watna. Så drack jag, och hon watnade också camelarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Och jag frågade henne, och sade: Hwars dotter äst du? Hon swarade: Jag är Bethuels dotter, Nahors sons, som Milca honom födt hafwer. Då hängde jag et ännespann på hennes anlete, och armringar öfwer hennes händer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Och böjde mig neder, och bad til HERran, och lofwade HERran, mins herras Abrahams Gud, som mig hade fört rätta wägen, at jag skulle taga til hans son mins herras broders dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Om I nu ären de, som bewisen minom herra barmhertighet och sanning, så säger mig det: Hwar ock icke, så säger mig ock det; at jag wänder mig antingen til den högra sidona, eller til den wänstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Då swarade Laban och Bethuel, och sade: Det är utgångit af HERranom, derföre kunne wi intet säga dig emot, hwarken ondt eller godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Der är Rebecka för dig, tag henne, och far din wäg, at hon blifwer dins herras sons hustru, som HERren sagt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Då Abrahams tjenare hörde dessa ord, bugade han sig til jordena för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Och tog fram silfwer och gyldene klenodier och kläder, och gaf dem Rebecka: Men hennes broder och moder gaf han örter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Då åt han och drack samt med männerne, som med honom woro, och blefwo der öfwer nattena. Om morgonen stod han up, och sade: Låter mig fara til min herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Men hennes broder och moder sade: Låt dock blifwa pigona wid tio dagar när oss; sedan skall du fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Då sade han til dem: Förhåller mig icke, förty HERren hafwer gjort min wäg lyckosam: Släpper mig, at jag far til min herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Då sade de: Låter oss kalla pigona, och fråga hwad hon säger dertil.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Och de kallade Rebecka, och sade til henne: Will du fara med denne mannenom? Hon swarade: Ja, jag will med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Så läto de Rebecka sina syster fara med hennes ammo, och Abrahams tjenare, och hans följare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Och de wälsignade Rebecka, och sade til henne: Du äst wår syster, förkofra dig til tusende tusend, och din säd besitte sina fienders portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Så redde Rebecka sig til med sina pigor, och satte sig på camelarna, och följde mannen efter. Och tjenaren tog Rebecka til sig, och for sin wäg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Men Isaac kom ifrå den brunnen, som kallades dens lefwandes och seendes; ty han bodde i det landet söder ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Och war utgången til at bedja i markene om aftonen: Och hof up sin ögon, och såg at camelarne kommo der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Och Rebecka hof up sin ögon, och såg Isaac: Då steg hon af camelen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Och sade til tjenaren: Hwad man är det, som kommer emot oss på markene? Tjenaren sade: Det är min herre. Då tog hon mantelen och höljde sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Och tjenaren förtälde Isaac allt, huru han sakena uträttat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Då förde Isaac henne in i sins moders Saras hyddo, och tog Rebecka, och hon wardt hans hustru, och han wardt kär åt henne: Och så wardt Isaac hugswalad öfwer sina moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham tog åter ena hustru, hon het Ketura.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Hon födde honom Simran och Jacksan, Medan och Midian, Jisbak och Suah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Men Jacksan födde Seba och Dedan. Dedans barn woro Assurim, Letusim och Leummim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Midians barn woro Epha, Epher, Hanoch, Abida och Eldaa: Desse äro alle Ketura barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Men Abraham gaf allt sitt gods Isaac.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Men de barnen, som han hade af frillorna, gaf han skänker, och lät dem fara ifrå sin son Isaac, medan han än lefde, öster ut i österlanden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Men Abrahams ålder, som han lefde, war hundrade fem och sjutio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Och blef sjuk, och dödde i en rolig ålder, då han af ålder och lefwande mätter war; och wardt samlad til sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Och honom begrofwo hans söner, Isaac och Ismael, i den dubbelkulone, på Ephrons åker, Zohars Hetheens sons, som ligger emot Mamre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'I den markene, som Abraham köpt hade af Hets barnom: Der är Abraham begrafwen med Sara sine hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Och efter Abrahams död wälsignade Gud hans son Isaac: Och han bodde wid den brunnen, som kallades dens lefwandes och seendes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Detta är Ismaels Abrahams sons slägt, som Hagar, Saras tjensteqwinna af Egypten, födde honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Och detta är Ismaels barns namn, der deras slägte hafwa namn af: Ismaels förste son Nebajoth, Kedar, Adbeel, Mibsam,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Thema, Jethur, Naphis och Kedma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Desse äro Ismaels barn med deras namn, i deras byar och städer, tolf förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Och detta är Ismaels ålder, hundrade och sju och tretio år; och han wardt sjuk och dödde, och wardt samkad intil sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Men han bodde ifrå Hewila in til Zur emot Egypten, när man går til Assyrien; och satte sig emot alla sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Detta är Isaacs Abrahams sons slägte: Abraham födde Isaac.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Men Isaac war fyratio år gammal, då han tog Rebecka til hustru, Bethuels Syrens af Mesopotamien dotter, Labans Syrens syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Men Isaac bad HERran för sine hustru, ty hon war ofruktsam; och HERren hörde honom, och Rebecka hans hustru wardt hafwande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Och barnen stötte sig med hwarannan i hennes lif. Då sade hon: Efter mig skulle så gå, hwi är jag då worden hafwandes? Och gick bort til att fråga HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Och HERran sade til henne: Tu folk äro i dino lifwe, och twäggehanda folk skola skiljas utaf dino lifwe: Och det ena folket skall öfwerwinna det andra, och den större skall tjena den mindre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Då nu tiden kom at hon föda skulle, si, då woro twillingar i hennes lifwe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Den förste, som utkom, war röd och ludin som et skin: Och de kallade honom Esau.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Strax derefter kom hans broder ut, han hölt med sine hand i Esaus fotablad, och de kallade honom Jacob: Sextio år gammal war Isaac, då de wordo födde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Och då drängarne wordo store, wardt Esau en jägare och en åkerman; men Jacob en from man, och bodde i tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Och Isaac hade Esau kär, ty han plägade äta af hans wede: Men Rebecka hade Jacob kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Och Jacob kokade en rätt: Då kom Esau af markene, och war trötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Och sade til Jacob: Gif mig äta af denna röda rättenom, ty jag är trötter: Deraf heter han Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Men Jacob sade: Sälj mig i dag din förstfödslorätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau swarade: Si, jag måste dock dö: Hwad warder mig den förstfödslorätten nyttig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jacob sade: Så swär mig i dag. Och han swor honom: Och sålde så Jacob sin förstfödslorätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Då gaf Jacob honom bröd och den grynwällingen, och han åt och drack, och stod up, och gick dädan. Och så föraktade Esau sin förstfödslorätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Så kom en dyr tid i landet, efter den förra, som war i Abrahams tid: Och Isaac for til Abimelech, de Philisteers Konung, til Gerar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Då uppenbarade sig honom HERren, och sade: Far icke ned i Egypten; utan blif i det land, som jag säger dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Blif en främling i desso landena, och jag skall wara med dig, och wälsigna dig: Förty dig dine säd skall jag gifwa all denna landen, och skall stadfästa min ed, som jag dinom fader Abraham swurit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Och skall föröka dina säd såsom stjernorna på himmelen, och skall gifwa dine säd all denna landen: och igenom dina säd skola all folk på jordene wälsignade warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Derföre, at Abraham hafwer warit mina röst hörig, och hafwer hållit mina seder, min bud, mina stadgar och min lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Så bodde Isaac i Gerar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Och när folket i den landsändanom frågade honom om hans hustru, sade han: Hon är min syster; ty han fruktade at säga: Hon är min hustru; at de tiläfwentyrs icke måtte slagit honom ihjäl för Rebeckas skull: Ty hon war dägelig under ansiktet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Då han nu hade warit der en tid lång, såg Abimelech de Philisteers Konung ut genom fenstret, och wardt warse at Isaac skämtade med sine hustru Rebecka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Då kallade Abimelech Isaac, och sade: Si, det är din hustru; hwi hafwer du sagt: Hon är min syster? Isaac swarade honom: Jag tänkte, at jag måtte tiläfwentyrs warda slagen ihjäl för hennes skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech sade: Hwi hafwer du då gjort oss det? Måtte sakta hafwa skett, at någon af folket hade lägrat sig med dine hustru, och så hade du kommit skuld uppå oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Då böd Abimelech allo folkena, och sade: Hwilken som kommer wid denna mannen, eller hans hustru, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Och Isaac sådde der i landet, och fick det året hundradefalt; ty HERren wälsignade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Och han wardt en mägtig man, gick och wäxte til, til dess han wardt ganska stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Och hade mycket gods i får och fä, och mycket tjenstefolk: Derföre afundades de Philisteer wid honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Och kastade igen alla de brunnar, som hans faders tjenare grafwit hade i hans faders Abrahams tid, och fylde dem up med jord:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Så at ock Abimelech sade til honom: Far ifrån oss; ty du äst worden oss för mägtig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Då for Isaac dädan, och slog up sin tjäll i Gerars dal, och bodde der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Och lät upgrafwa igen de wattnabrunnar, som de i hans faders Abrahams tid grafwit hade, hwilka de Philisteer efter Abrahams död igenfyllt hade: Och kallade dem wid samma namnet, som hans fader dem kallat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Grofwo ock Isaacs tjenare i dalenom, och funno der en brunn med lefwandes watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Men herdarne af Gerar trätte med Isaacs herdar, och sade: Detta watnet är wårt. Då kallade han den brunnen Esek; derföre, at de hade der gjort honom högmod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Då grofwo de en annan brunn, der trätte de ock öfwer: Derföre kallade han honom Sitna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Då skyndade han sig dädan, och grof en annan brunn; der trätte de intet om: Derföre kallade han honom Rehoboth, och sade: Nu hafwer HERren gifwit oss rum, och låtit oss wäxa til i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Derefter for han dädan til Ber-Saba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Och HERren syntes honom i den nattene, och sade: Jag är dins faders Abrahams Gud: Frukta dig intet, ty jag är med dig, och skall wälsigna dig, och föröka dina säd, för mins tjenares Abrahams skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Då byggde han dersammastädes et altare, och predikade om HERrans namn, och upslog der sitt tjäll: Och hans tjenare grofwo der en brunn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Och Abimelech gick til honom af Gerar, och Ahusath hans wän, och Phicol hans härhöfwitsman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Men Isaac sade til dem: Hwi kommen I til mig? Haten I mig dock, och hafwen drifwit mig ifrån eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'De sade: Wi se med seende ögon, at HERren är med dig, derföre sade wi: Det skall wara en ed emellan oss och dig, och wiljom göra et förbund med dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'At du icke gör oss någon skada, lika som wi icke heller hafwe något afhändt dig, och såsom wi ej heller hafwe gjort dig annat än godt, och låtit dig fara med frid; men nu äst du den som HERren wälsignat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Då gjorde han dem en måltid, och de åto och drucko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Och om morgonen bittida stodo de up, och sworo den ene dem andra: Och Isaac lät dem gå. Och de foro ifrå honom med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Samma dagen kommo Isaacs tjenare, och sade honom om brunnen, som de grafwit hade, och sade til honom: Wi hafwom funnit watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Och han kallade honom Saba: Deraf heter den staden BerSaba än i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Då Esau war fyratio år gammal, tog han hustrur, Judith Beeri dens Hetheens dotter, och Basmath Elons dens Hetheens dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'De woro båda emot Isaac och Rebecka ganska bittra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Och det begaf sig, då Isaac war worden gammal, at hans ögon wordo mörk til syn, kallade han Esau, sin större son, och sade til honom: Min son. Han swarade honom: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Och han sade: Si, jag är worden gammal, och wet ej när jag skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Så tag nu din tyg, koger och boga, och gack ut i markena, och hemta mig willebråd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Och gör mig en mat, så som jag gerna will hafwat, och bär mig honom här in, at jag må äta; på det min själ må wälsigna dig, förra än jag dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Men Rebecka hörde sådana ord, som Isaac sade til sin son Esau. Och Esau gick ut i markena, at han skulle taga willebråd, och hafwa henne hem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Då sade Rebecka til sin son Jacob: Si, jag hafwer hört din fader tala med dinom broder Esau, och säga:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hemta mig en willebråd, och gör mig mat, at jag må äta, och wälsigna dig för HERranom, förra än jag dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Så hör nu min son mina röst, hwad jag dig säger:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gack bort til hjorden, och hemta mig twå goda kedlingar, at jag gör dinom fader deraf mat, såsom han gerna will hafwat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Det skalt du bära dinom fader in, at han äter; på det han må wälsigna dig, förra än han dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jacob sade til sina moder Rebecka: Si, min broder Esau är ludin, och jag släter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Så kan tiläfwentyrs min fader taga uppå mig, och måtte tänka, at jag will bedraga honom: Och låter så öfwer mig gå en förbannelse, och icke en wälsignelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Då sade hans moder til honom: Den förbannelsen ware öfwer mig, min son; hör man du mina röst, gack och tag mig det hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Då gick han bort och tog, och bar til sina moder: Då gjorde hans moder en mat, såsom hans fader gerna hadet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Och tog Esaus, hennes större sons, kosteliga kläder, som hon när sig i huset hade, och klädde dem på Jacob sin mindre son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Men skinnen af kedlingarna swepte hon om hans händer, och der han war släter på halsenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Och fick så maten, med bröd, såsom hon redt hade, uti Jacobs sins sons hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Och han bar det in til sin fader, och sade: Min fader. Han swarade: Här är jag; ho äst du, min son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jacob sade: Jag är Esau, din förstfödde son; jag hafwer gjort som du hafwer sagt mig: statt up, sätt dig, och ät af mine willebråd, på det din själ må wälsigna mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Men Isaac sade til sin son: Min son, huru hafwer du så snart funnit? Han swarade: HERren din Gud hafwer mig det bestyrt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Då sade Isaac til Jacob: Gack hit, min son, at jag tager uppå dig, om du äst min son Esau, eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Så gick Jacob til sin fader Isaac, och då han hade tagit uppå honom, sade han: Rösten är Jacobs röst, men händerna äro Esaus händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Och kände honom intet, ty hans händer woro ludna, såsom Esaus hans broders händer; och så wälsignade han honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Och sade til honom: Äst du min son Esau? Han swarade: Ja, jag äret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Då sade han: Så tag mig hit, min son, til at äta af dine willebråd, at min själ må wälsigna dig. Då bar han det til honom, och han åt; och bar honom desslikes win in, och han drack.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Och Isaac hans fader sade til honom: Kom hit, och kyss mig, min son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Han gick til, och kyste honom. Då kände han lukten af hans kläder, och wälsignade honom och sade: Si, mins sons lukt är såsom ens åkers lukt, den HERren wälsignat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Gud gifwe dig af himmelens dagg, och af jordenes fetma, och rikeliga korn och win.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Folk tjene dig, och slägter falle dig til fota: War en herre öfwer dina bröder, och dins moders barn falle dig til fota: Förbannad ware den dig förbannar; wälsignad ware den dig wälsignar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'När nu Isaac lyktat hade wälsignelsen öfwer Jacob, och Jacob som nogast utgången war ifrå sinom fader Isaac, då kom Esau hans broder utaf sine jagt,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Och gjorde också en mat, och bar in til sin fader, och sade til honom: statt up, min fader, och ät af dins sons wildebråd, at din själ må wälsigna mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Då swarade honom Isaac hans fader: Ho äst du? Han sade: Jag är Esau din förstfödde son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Då wardt Isaac öfwermåttan häpen, och sade: Ho? Och hwar är då den jägaren, som mig det burit hafwer, och jag åt utaf allo, förra än du kom, och wälsignade honom? Han skall ock wälsignad blifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'När Esau detta sins faders tal hörde, ropade han högt, och wardt öfwermåttan förbittrad, och sade til sin fader: Wälsigna ock mig, min fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Men han sade: Din broder är kommen med list, och hafwer din wälsignelse borta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Då sade han: Rätteliga heter han Jacob, ty han hafwer nu twå resor undertrampat mig: Min förstfödslorätt hafwer han borta; och si, nu tager han ock min wälsignelse bort. Och sade: Hafwer du ingen wälsignelse behållit för mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac swarade, och sade til honom: Jag hafwer satt honom til en herre öfwer dig, och alla hans bröder hafwer jag gjort honom til tjenare; med korn och win hafwer jag försett honom: Hwad skall jag dock nu göra dig, min son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esau sade til sin fader: Hafwer du då icke utan en wälsignelse, min fader? Wälsigna mig ock, min fader; och hof up sina röst och gret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Då swarade Isaac hans fader och sade til honom: Si, en fet boning skalt du hafwa på jordene, och af himmelens dagg ofwan efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Med ditt swärd skalt du nära dig, och skalt tjena dinom broder: Och det skall ske, at du skalt ock warda en herre, och rifwa hans ok af dinom halse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Och Esau wardt wred uppå Jacob, för wälsignelsens skull, der hans fader honom med wälsignat hade, och sade i sitt hjerta: Den tiden warder snart kommandes, at min fader måste få sorg, ty jag will dräpa min broder Jacob.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Då wardt Rebecka sagdt om dessa hennes större sons Esaus ord: Och sände bort, och lät kalla sin mindre son Jacob, och sade til honom: Si, din broder Esau hotar dig, at han will dräpa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Och hör nu mina röst, min son, gör dig redo, och fly til min broder Laban i Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Och blif en tid lång när honom, til dess dins broders grymhet återwänder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Och til dess hans wrede wändes ifrå dig, och förgäter det du honom gjort hafwer; så will jag sedan sända, och låta hemta dig dädan: Hwi skulle jag mista eder båda på en dag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Och Rebecka sade til Isaac: Mig ledes wid at lefwa, för Hets döttrars skull: Om Jacob tager hustru af Hets döttrar, hwilka äro såsom dessa landsens döttrar, efter hwad skall jag lefwa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Då kallade Isaac sin son Jacob, och wälsignade honom, och böd honom, och sade til honom: Tag icke hustru af Canaans döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Utan gör dig redo, och far in i Mesopotamien til Bethuel, dins moderfaders hus, och tag dig der hustru af Labans dins moderbroders döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Men allsmägtig Gud wälsigne dig, och göre dig fruktsam, och föröke dig, så at du warder en skare med folk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Och gifwe dig Abrahams wälsignelse, dig och dine säd med dig; at du må besitta det land, der du en främling uti äst, det Gud Abraham gifwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Så skilde Isaac Jacob ifrå sig, at han for in i Mesopotamien til Laban Bethuels son af Syrien, Rebeckas broder, som hans och Esaus moder war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'När nu Esau såg, at Isaac hade wälsignat Jacob, och sändt honom in i Mesopotamien, at han skulle der taga sig hustru; och at sedan han honom wälsignat hade, böd han honom, och sade: Du skalt ingen hustru taga af Canaans döttrar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Och at Jacob war sinom fader och moder lydig, och for in i Mesopotamien:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Säg ock, at Isaac hans fader såg icke gerna Canaans döttrar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Gick han bort til Ismael, och tog, utöfwer de hustrur han tilförene hade, Mahalath, Ismaels Abrahams sons dotter, Rebajoths syster, til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Men Jacob for ut ifrå BerSaba, och reste til Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Och kom på et rum, der blef han öfwer nattena, förty solen war bärgad; och han tog en sten der på rummena, och lade honom under sitt hufwud, och lade sig i samma rum til at sofwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Och honom drömde, och si, en stege stod på jordene, och änden på honom tog up i himmelen: Och si, Guds Änglar stego derpå up och neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Och HERren stod der öfwerst uppå, och sade: Jag är HERren, Abrahams och dins faders Gud, och Isaacs Gud: Det landet, som du ligger uppå, skall jag gifwa dig och dine säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Och din säd skall warda såsom stoftet på jordene; och du skalt warda utspridder wäster ut, öster ut, norr ut, och söder ut, och genom dig och dina säd skola alla slägter på jordene warda wälsignade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Och si, jag är med dig, och skall förwara dig ehwart du far, och skall föra dig åter i detta landet igen. Och skall icke öfwergifwa dig, til des jag gör allt det jag dig sagt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Då nu Jacob waknade up af sin sömn, sade han: Wisserliga är HERren i detta rum, och jag wistet icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Och fruktade han sig, och sade: Detta måste wara et heligt rum; ty här bor wisserliga Gud, och här är himmelens port.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Och Jacob stod up om morgonen bittida, och tog stenen, som han hade lagt under sitt hufwud, och reste honom up til en wård, och gjöt oljo der ofwan på.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Och kallade det rummet BethEl; men tilförene hette den staden Lus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Och Jacob gjorde et löfte, och sade: Om så är, at Gud blifwer med mig, och förwarar mig på denna wägen, som jag reser, och gifwer mig bröd til at äta, och kläder til att klädas med;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Och förer mig med strid åter hem igen til min fader; så skall HERren wara min Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Och denne stenen, som jag uprest hafwer til en wård, skall warda et Guds hus: Och allt det du mig gifwer, der will jag gifwa dig tiond af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Då hof Jacob sin fot up, och gick in i det land, som öster ut ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Och såg sig om, och si, der war en brunn på markene; och si, tre hjordar med får der när; förty hjordarne måste dricka af brunnenom; och låg en stor sten för hålet på brunnenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Och de plägade der församla alla hjordarna, och wältra stenen ifrå brunnshålet, och watna fåren, och lade så åter stenen för hålet i sitt rum igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Och Jacob sade til dem: Mine bröder, hwadan ären I? De swarade: Wi äre af Haran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Han sade til dem: Kännen I ock Laban Nahors son? De swarade: Wi känne honom wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Han sade: Går honom ock wäl i hand? De swarade: Honom går wäl i hand: Och si, der kommer hans dotter Rachel med fåren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Han sade: Det är ännu bittida dags, och är icke ännu tid drifwa boskapen hem; watner fåren, och går bort med dem i bet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'De swarade: Wi kunne icke, förra än du alle hjordarne komma tilsamman, och wi wältre stenen ifrå brunnshålet, och watne så fåren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Medan han ännu talade med dem, kom Rachel med sins faders får; förty hon waktade fåren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Då Jacob såg Rachel, Labans sins moderbroders dotter, och Labans sins moderbroders får, gick han til, och wältrade stenen ifrå hålet på brunnenom, och watnade Labans sins moderbroders får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Och kyste Rachel; hof up sina röst, och gret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Och kungjorde henne, at han war hennes faderbroders och Rebeckas son. Då lopp hon, och kungjorde det sinom fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Då nu Laban hörde om Jacob sin systerson, lopp han emot honom, och tog honom i famn, och kysten, och hade honom in i sitt hus. Då förtälde han honom allt, huru tilgått war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Då sade Laban til honom: Nu wäl, du äst mitt ben och mitt kött: Och när han nu en månad långt hade warit när honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Sade Laban til Jacob: Ändock du äst min broder, skulle du fördenskull tjena mig för intet? Säg, hwad skall wara din lön?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Och Laban hade twå döttrar; den äldsta het Lea, och den yngsta het Rachel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Men Lea war klenögd; Rachel war wäl skapad, och hade ett dägeligit ansikte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Til henne fick Jacob kärlek, och sade: Jag will tjena dig i sju år för Rachel dina yngsta dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban swarade: Det är bättre jag gifwer dig henne, än enom androm: Blif när mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Så tjente Jacob i sju år för Rachel; och tyckte honom det wara få dagar, så kär hade han henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Och Jacob sade til Laban: Få mig mina hustru; ty nu är tid, at jag kommer i säng med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Då böd Laban allt folket der omkring, och gjorde bröllop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Men om aftonen tog han Lea sina dotter, och hade henne in til honom: Och han låg när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Och Laban fick sine dotter Lea Silpa til ena tjenstepigo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Om morgonen, si, då war det Lea: Och han sade til Laban: Hwi hafwer du det gjort mig? Hafwer jag icke tjent dig för Rachel? Hwi hafwer du bedragit mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban swarade: Man går icke så i wåro lande, at man gifwer ut den yngsta förr än den äldsta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Hålt dessa weckona ut, så will jag ock gifwa dig denna med, för den tjenst, som du ännu skalt tjena mig i androm sju år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob gjorde så, och höll de weckona ut: Då gaf han honom Rachel sina dotter til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Och Laban gaf Rachel sine dotter Bilha til ena tjenstepigo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Så låg han ock när Rachel, och hade Rachel kärare än Lea; och tjente honom framdeles i de andra sju åren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Men då HERren såg, at Lea wardt wanwörd, gjorde han henne fruktsama, och Rachel ofruktsama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Och Lea wardt hafwande, och födde en son, den kallade hon Ruben, och sade: HERren hafwer sett til min förtryckelse; nu warder min man hafwandes mig kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Och wardt åter hafwande, och födde en son, och sade: HERren hafwer hört, at jag är wanwörd, och hafwer desslikes denna gifwit mig; och kallade honom Simeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Åter wardt hon hafwande, och födde en son, och sade: Nu warder min man åter hållandes sig til mig, ty jag hafwer födt honom tre söner; derföre kallade hon honom Levi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Fjerde reso wardt hon hafwande, och födde en son, och sade: Nu will jag tacka HERranom; derföre kallade hon honom Juda, och wände så igen at föda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Då Rachel såg, at hon födde Jacob intet, afundades hon wid sina syster, och sade til Jacob: Skaffa mig ock barn, eljest dör jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jacob wardt ganska wred på Rachel, och sade: Icke är jag Gud, som dig förmenar dins lifs frukt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Men hon sade: Si, der är min tjenstepiga Bilha: lägg dig när henne, at hon må föda i mitt sköt, och jag warder dock upbyggd genom henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Och gaf honom så Bilha, sina tjenstepigo, til hustru, och Jacob lade sig när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Och så wardt Bilha hafwande, och födde Jacob en son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Då sade Rachel: Gud hafwer dömt mina sak, och hört mina röst, och gifwit mig en son: Derföre kallade hon honom Dan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Åter wardt Bilha, Rachels tjensteqwinna, hafwande, och födde Jacob den andra sonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Då sade Rachel: Gud hafwer omwändt det med mig och mine syster, och jag får öfwerhandena: Och hon kallade honom Naphthali.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Då nu Lea såg, at hon hade wändt igen at föda, tog hon sina tjenstepigo Silpa, och gaf henne Jacob til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Så födde Silpa, Leas tjensteqwinna, Jacob en son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Då sade Lea: Rustig; och kallade honom Gad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Derefter födde Silpa, Leas tjensteqwinna, Jacob den andra sonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Då sade Lea: Wäl mig; förty döttrarna skola säga mig saliga: Och hon kallade honom Asser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben gick ut om hwete-andena, och fann liljor på markene, och hade dem hem til sina moder Lea. Då sade Rachel til Lea: Gif mig en del af din sons liljor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Hon swarade: Hafwer du icke nog, at du hafwer tagit min man bort, och wilt desslikes taga min sons liljor? Rachel sade: Nu wäl, låt honom denna nattena sofwa när dig, för dins sons liljor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Då nu Jacob kom om aftonen af markene, gick Lea ut emot honom, och sade: När mig skall du ligga: Förty jag hafwer köpt dig för mins sons liljor: Och han låg när henne de nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Och Gud hörde Lea, och hon wardt hafwande, och födde Jacob den femte sonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Och sade: Gud hafwer lönt mig, för det jag gaf minom manne mina tjenstepigo: Och hon kallade honom Isaschar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Åter wardt Lea hafwande, och födde Jacob den sjette sonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Och sade: Gud hafwer wäl försett mig: Nu warder åter min man boendes när mig, ty jag hafwer födt honom sex söner: Och kallade honom Sebulon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Derefter födde hon ena dotter, och kallade henne Dina.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Men Gud tänkte på Rachel, och hörde henne, och gjorde henne fruktsama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Då wardt hon hafwande, och födde en son, och sade: Gud hafwer min smälek ifrå mig tagit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Och kallade honom Joseph, och sade: HERren gifwe mig ännu en son härtil.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Då nu Rachel hade födt Joseph, sade Jacob til Laban: Låt mig färdas, och resa hem til mitt, och i mitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gif mig mina hustrur och min barn, som jag hafwer tjent dig före, at jag må färdas: Förty du wetst, hwad jag hafwer gjort dig för en tjenst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban sade til honom: Kan jag icke finna nåd för din ögon? Jag förnimmer, at HERren hafwer wälsignat mig för dina skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Säg, hwad lön jag skall gifwa dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Men han sade til honom: Du wetst, huru jag hafwer tjent dig, och hwad boskap du hafwer under mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Du hade litet, förra än jag kom, men nu äst du riker worden: och HERren hafwer wälsignat dig för mina skull: Och nu, när skall jag ock något bestyra til mitt hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Laban sade: Hwad skall jag då gifwa dig? Jacob sade: Du skalt allsintet gifwa mig; utan om du wilt göra mig det jag säger, så skall jag ännu beta och wakta din får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Jag will i dag gå igenom alla dina hjordar, och skilj du derifrån all fläckot och brokot får, och all swart får ibland lamben och kiden: Hwad nu sedan brokot och fläckot blifwer, det skall wara min lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Så warder mig min rätt färdighet betygandes i dag eller morgon, när dertil kommer, at jag skall taga min lön af dig, alltså, at hwad som icke fläckot eller brokot, eller ock hwad swart är ibland lamben och kiden, det ware en tjufnad med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Då sade Laban: Jag är til frids, blifwe som sagt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Och han skilde i den dagen ut spreklota och brokota bockar, och all fläckot och brokot kid, der som ju något hwitt war uppå, och allt det swart war ibland lamben; och fick det sin barn i händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Och lät blifwa tre dagsleder långe emellan sig och Jacob. Så bette Jacob det öfwer war af Labans hjord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Men Jacob tog gröna aspekäppar, hasl och castaneen, och barkade hwita ränder deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Och lade käpparna, som han barkat hade, i dryckehonar för hjordarna, som der komma måste och watnas, at de skulle hafwande warda, när de kommo til at dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Alltså wordo hjordarne hafwande öfwer käpparna, och födde fläckot, spreklot och brokot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Då afskilde Jacob lamben, det icke brokot, och allt det swart war, och lät dem in til Labans hjord, och gjorde sig en egen hjord, den lät han icke til Labans hjord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Men när den tidfödde hjorden lopp, lade han käpparna i honar för hjordens ögon, så at de wordo hafwande öfwer käpparna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Men när de senfödda lupo, lade han dem intet deruti. Så wordo då de senfödlingar Labans och de tidfödlingar Jacobs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Deraf wardt mannen öfwermåttan riker, så at han hade mycken får, tjenarinnor och tjenare, camelar och åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Och kom för honom Labans barns tal, at de sade: Jacob hafwer kommit allt wår faders gods til sig; och af wår faders gods hafwer han sådana rikedomar samkat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Och Jacob såg på Labans ansikte, och si, det war icke sådana emot honom, som i går och förrgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Och HERren sade til honom: Far åter in i dina fäders land, och til dina fränder: Jag will wara med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Då sände Jacob, och lät kalla Rachel och Lea ut på markena til sin hjord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Och sade til dem: Jag ser edars faders ansikte, at det är icke sådana emot mig, såsom i går och i förrgår: Men mins faders Gud hafwer warit med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Och I weten, at jag hafwer tjent edar fader af alla mina krafter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Och han hafwer beswikit mig, och nu tio resor förwandlat min lön; men Gud hafwer honom det icke tilstadt, at han skulle göra mig skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'När han sade: De brokota skola wara din lön, så bar hela hjorden brokot; men när han sade: De spreklota skola wara din lön, så bar hela hjorden spreklot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Så hafwer Gud wändt edars faders gods ifrå honom, och gifwit det mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Ty när aflotiden kom, hof jag up min ögon, och såg i dröm, och si, gumrarne sprungo på de spreklota, fläckota och brokota hjordarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Och Guds Ängel sade til mig i drömmenom: Jacob; och jag swarade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Men han sade: Häf up din ögon, och si, gumrarne springa på de spreklota, fläckota och brokota fåren; förty jag hafwer allt sett, hwad Laban gör dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jag är Gud i BethEl, der du hafwer smort stenen, och gjort mig der et löfte: Nu gör dig redo, och far utaf detta landet, och far in i ditt födsloland igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Då swarade Rachel och Lea, och sade til honom: Wi hafwe hwarken del eller arf i wår faders huse mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Hafwer han dock hållit oss lika som främmande: Förty han hafwer sålt oss, och förtärt wårt wärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Derföre hafwer Gud frånwändt wårom fader hans rikedomar til oss och wår barn. Allt det Gud dig nu sagt hafwer, det gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Så gjorde Jacob sig redo, och satte sin barn och hustrur på camelar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Och förde bort all sin boskap, och alla sina håfwor, som han hade förwärfwat i Mesopotamien; på det han skulle komma til sin fader Isaac i Canaans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Men Laban war gången bort til at klippa sin hjord. Och Rachel stal sins faders beläter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Alltså stal Jacob Laban af Syrien hjertat, at han honom icke tilsade, då han flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Så flydde han, och allt det hans war gjorde sig redo, och for öfwer älfwena, och stämde åt Gileads berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'På tredje dagen wardt det Laban sagdt, at Jacob flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Och han tog til sig sina bröder, och jagade efter honom sju dagsleder; och hinte honom på det berget Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Men Gud kom til Laban af Syrien i dröm om nattena, och sade til honom: Förwara dig, at du intet talar til Jacob annat än godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Och Laban nalkades intil Jacob. Men Jacob hade upslagit sin tjäll på bergena: Och Laban med sina bröder slog desslikes sin tjäll up på bergena Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Då sade Laban til Jacob: Hwad hafwer du gjort, at du hafwer stulit mitt hjerta, och bortfört mina döttrar, lika som de der med swärd gripna wore?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Hwarföre hafwer du det fördolt, at du skulle fly, och hafwer stulit dig ifrå mig, och hafwer icke tilsagt, at jag måtte hafwa ledsagat dig med fröjd, med sjungande, med bungande och harpande?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Och hafwer icke låtit mig kyssa min barn och döttrar? Du hafwer dårliga gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Och jag hade wäl så mycken magt, at jag kunde göra eder ondt; men edars faders Gud sade til mig i går: Förwara dig, at du intet talar til Jacob, utan godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Och medan du ju wille fara, och åstundade så mycket efter dins faders hus, hwarföre hafwer du då stulit mig mina gudar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jacob swarade, och sade til Laban: Jag fruktade, at du skulle hafwa tagit dina döttrar ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Men när hwilkom du finner dina gudar, han må dö här för wåra bröder. Gör efter ditt när mig, och tag det. Men han wisste icke, at Rachel hade stulit dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Då gick Laban in i Jacobs tjäll och Leas, och båda tjensteqwinnornas, och fann intet; och gick ut af Leas tjäll i Rachels tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Då tog Rachel beläten, och lade dem under camelahalmen, och satte sig derpå. Men Laban ransakade öfwer hela tjället, och fann intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Då sade hon til sin fader: Min herre, war icke wred: Förty jag kan icke stå up emot dig; förty det går med mig efter qwinno sätt. Så sökte han, och fann intet beläten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Och Jacob wardt wred, och kifwade med Laban, och sade til honom: Hwad hafwer jag misshandlat eller syndat, at du äst så heter på mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hafwer ransakat all min boting, hwad hafwer du funnit af din boting? Lägg det der för mina och dina bröder, at de döma emellan oss båda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Tjugu år hafwer jag warit när dig; din får och getter hafwa icke warit ofruktsamma, wädrarna af din hjord hafwer jag icke ätit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Det af djuren rifwit war, hade jag icke til dig, jag måste det betala: Du äskade det af mine hand, ehwad det war dag eller natt mig ifrå stulit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Om dagen war jag wanmägtig för hetas skull, om nattena för köld; och min sömn wek ifrå min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Så hafwer jag i tjugu år tjent i ditt hus; fjorton för dina döttrar, och sex för din hjord: Och du hafwer tio resor förwandlat min lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Hwar mins faders Abrahams Gud och Isaacs fruktan icke hade warit på mina sido, du hade låtit mig gå blottan ifrå dig. Men Gud hafwer ansett min förtryckelse och arbete, och straffade dig i går.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban swarade, och sade til Jacob: Döttrarna äro mina döttrar, och barnen äro mina barn, och hjordarna äro mine hjordar, och allt det du ser är mitt: Hwad kan jag i dag göra minom döttrom, eller deras barnom, som de födt hafwa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Så kom nu och låt oss göra et förbund, jag och du; som skall wara et wittnesbörd emellan mig och dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Då tog Jacob en sten, och reste honom up til en wård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Och sade til sina bröder: Hemter up stenar; och de togo stenar, och gjorde ena rösjo, och åto uppå samma rösjo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Och Laban kallade henne Jegar Sahaduta; men Jacob kallade henne Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Då sade Laban: Denna stenrösjan ware i dag wittnesbörd emellan mig och dig; deraf kallar man henne Gilead:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Och ware en wård; ty han sade: HERren se härtil emellan mig och dig, då wi komme ifrå hwarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Hwar du beswärar mina döttrar, eller tager andra hustrur deröfwer: Här är ingen menniska med oss; men si, Gud är wittne emellan mig och dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Och Laban sade ytterligare til Jacob: Si, detta är stenrösjan, och detta är wården, som jag uprest hafwer emellan mig och dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Samma rösjan ware wittne, och wården ware desslikes wittne, om jag far här öfwer til dig, eller du far öfwer denna rösjan och wården til mig, til att göra skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Abrahams Gud och Nahors Gud, och deras fäders Gud, ware domare emellan oss. Och Jacob swor honom, wid Isaacs sins faders fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Och Jacob offrade offer på bergena, och böd sina bröder at de skulle äta bröd. Och då de hade ätit, blefwo de på bergena öfwer nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Men om morgonen stod Laban bittida up, kyste sin barn och döttrar; wälsignade dem, och for sina färde, och kom hem til sitt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Men Jacob for sin wäg, och Guds Änglar mötte honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Och då han såg dem, sade han: Detta äro Guds härar; och kallade det rummet Mahanaim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Men Jacob sände bod fram för sig til sin broder Esau in uti Scirs land, i Edoms ängd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Och befallte dem, och sade: Så säger minom herra Esau: Din tjenare Jacob låter säga dig, jag hafwer warit ute när Laban, och hafwer allt härtil warit ibland främmande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Och hafwer fä och åsnor, får, tjenare och tjenarinnor; och hafwer utsändt, och låtit dig minom herra det beboda, på det jag måtte finna nåd för din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Boden kommo igen til Jacob, och sade: Wi kommom til din broder Esau, och han reser emot dig med fyrahundrade män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Då fruktade Jacob storliga, och war förfärad: Och skifte folket, som war när honom, och får, och fä, och camelar, i twå skarar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Och sade: Om Esau kommer på den ena skaran, och står honom, så må den andre undkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Ytterligare sade Jacob: Gud, mins faders Abrahams Gud, mins faders Isaacs, HERre, du som til mig sagt hafwer: Far åter in i ditt land til dina fränder, jag will göra dig godt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Jag är för ringa til all den barmhertighet och all den trohet, som du med dinom tjenare gjort hafwer; förty jag hade icke mer än denna stafwen, då jag gick öfwer denna Jordanen, och nu är jag til twå skarar worden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Hjelp mig utu mins broders hand, utu Esaus hand; ty jag fruktar för honom: At han icke kommer, och står mig både mödrar och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du hafwer sagt: Jag will göra dig godt, och göra din säd som sanden i hafwet, den så mycken är, at han ej kan räknas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Och han blef der den nattena, och tog af thy han för handena hade, skänker til sin broder Esau.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Tuhundrade getter, tjugu bockar, tuhundrade får, tjugu wädrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Och tretio däggande camelar med deras föl, fyratio kor, och tio oxar; tjugu åsninnor, med tio föl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Och fick dem under sina tjenares händer, ju hwar hjorden för sig, och sade til dem: Går fram för mig, och låter wara rum emellan den ena hjorden efter den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Och böd den första, och sade: När min broder Esau möter dig, och frågar dig: Hwem hörer du til, och hwart wilt du, och hwem hörer det til, som du drifwer för dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Skalt du säga: Det hörer dinom tjenare Jacob til; han sände sinom herra Esau skänker, och kommer härefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Så böd han ock den andra, och den tredje, och allom dem som gingo efter hjorden, och sade: Som jag hafwer sagt eder, så säger til Esau, när I finnen honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Och säger ju det med: Si, Jacob din tjenare är efter oss. Förty han tänkte, jag will blidka honom med den skänken, som går för mig; sedan will jag se honom; kan hända at han undfår mig wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Så gingo skänkningarna fram före honom; men han blef den nattena i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Och stod up om nattena, och tog sina twå hustrur, och de twå tjensteqwinnorna, och sin ellofwa barn, och for til wadet Jabbok:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Tog dem och förde dem öfwer älfwena, så at det han hade, kom öfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Och han blef på den sidone allena. Då brottades en man med honom til dess morgonrodnen upgick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Och då han såg, at han icke kunde öfwerwinna honom, rörde han hans höftes sena, och strax förtwinade hans höftes sena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Och han sade: Låt mig gå, ty morgonrodnen går up; men han swarade: Jag släpper dig icke, med mindre du wälsignar mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Han sade: Huru heter du? Han swarade: Jacob.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Han sade: Du skalt icke mer heta Jacob, utan Israel. Förty du hafwer med Gud och menniskor kämpat, och hafwer fått öfwerhandena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Och Jacob frågade honom, och sade: Huru heter du? Men han sade: Hwi frågar du, huru jag heter? Och han wälsignade honom der sammastädes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Och Jacob kallade det rummet Pnuel; ty jag hafwer sett Gud under ansiktet, och min själ är frälst worden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Och som han kom fram om Pnuel, gick honom solen up, och han haltade i sine höft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Fördenskull äta Israels barn inga höftsena ännu i dag, derföre, at Jacobs höftsena rörd wardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jacob hof up sin ögon, och såg sin broder Esau komma med fyrahundrade män. Och skifte sin barn til Lea, och til Rachel, och til båda tjensteqwinnorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Och skickade tjensteqwinnorna med deras barn främst; och Lea med hennes barn dernäst; och Rachel med Joseph efterst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Och han gick fram för dem, och bugade sig sju resor ned på jordena, til dess han kom fram til sin broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Men Esau lopp emot honom, och tog honom i famn, och fick honom om halsen, och kysste honom; och de greto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Och hof up sin ögon, och såg qwinnorna med barnen, och sade: Ho äro desse med dig? Han swarade: Det äro barnen, som Gud dinom tjenare beskärt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Och tjensteqwinnorna gingo fram med deras barn, och bugade sig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Lea gick ock fram med sin barn, och bugade sig för honom. Sedan gick Joseph och Rachel fram, och bugade sig ock för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Och han sade: Hwad wilt du med allan den skaran, som jag hafwer mött? Han swarade: At jag måtte finna nåd för minom herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esau sade: Jag hafwer nog, min broder; behålt det du hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jacob swarade: Ack nej! hafwer jag funnit nåd för dig, så tag min skänk af mine hand: Förty jag såg ditt ansikte, lika som jag hade sett Guds ansikte; och tag det täckeliga af mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Tag den wälsignelsen, som jag hafwer fört til dig; ty Gud hafwer mig det beskärt, och jag hafwer all ting nog. Så nödgade han honom, til dess han anammade det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Och han sade: Låt oss fara fram åt, och resa, jag will fara med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Men han sade til honom: Min herre, du wetst at jag hafwer späd barn när mig, dertil får och fä, som än äro unge; när de en dag för hastigt drifne wordo, dödde mig hela hjorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Min herre fare fram före åt för sin tjenare: Jag will sakta följa, efter som boskapen och barnen gå kunna, til dess jag kommer til min herra i Seir.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Esau sade: Så will jag dock låta blifwa när dig något af folket, som med mig är. Han swarade: Hwad görs det behof? Låt mig man finna nåd för minom herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Så for Esau den dagen tilbaka sin wäg åt Seir.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Och Jacob for til Succoth, och byggde sig et hus, och gjorde hyddor til sin boskap. Deraf heter det rummet Succoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Derefter kom Jacob til Salem, til den staden Sichem, som ligger i Canaans lande, sedan han war kommen utaf Mesopotamien, och gjorde sitt lägre för stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Och köpte et stycke åker af Hemors Sichems faders barnom, för hundrade penningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Der slog han up sin tjäll, och upreste der et altare, och åkallade dens starka Israels Guds namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Men Dina Leas dotter, den hon Jacob födt hade, gick ut til at bese dess landsens döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Då Sichem, Hemors Heweens son, som war dess landsens herre, såg henne, tog han henne, och belägrade henne, och förkränkte henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Och hon låg honom hårdt på hjertat, och han hade pigona kära, och talade ljufliga med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Och Sichem sade til sin fader Hemor: Tag mig den pigona til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Och Jacob förnam, at hans dotter Dina war skämd, och hans söner woro med boskapenom ute på markene: Och Jacob tigde til dess de kommo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Då gick Hemor Sichems fader ut til Jacob, til at tala med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'I det kommo Jacobs söner af markene; och då de det hörde, förtröt det männerna, och wordo ganska wrede, at han hade gjort en dårskap i Israel, och belägrat Jacobs dotter; ty det war icke rätt gjordt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Då talade Hemor med dem, och sade: Mins sons Sichems hjerta trängtar efter edra dotter; käre, gifwer honom henne til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Befrynder eder med oss; gifwer oss edra döttrar, och tager I wåra döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Och bor när oss: Landet skall stå eder öppet; bygger och bruker, och bor derinne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Och Sichem sade til hennes fader och bröder: Låter mig finna nåd när eder, hwad I mig sägen, det will jag gifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Begärer man troliga af mig morgongåfwor och skänker, jag will gifwa, som i begären; gifwer mig allenast pigona til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Då swarade Jacobs söner Sichem, och hans fader Hemor, och talade bedrägeliga, derföre, at deras syster Dina war skämd:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Och sade til dem: Wi kunne det icke göra, at wi skole gifwa wåra syster enom oomskornom manne; ty det wore oss en skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Dock likwäl wilje wi wara eder til wiljes, om I warden oss like, och allt mankön ibland eder warder omskoret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Då wilje wi gifwa eder wåra döttrar, och taga oss edra döttrar, och bo när eder, och wara et folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Men hwar I icke wiljen lyda oss, och omskära eder, så wilje wi taga wåra dotter, och fara wår wäg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Det talet behagade Hemer och hans son wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Och den unge mannen fördröjde intet at göra så: Förty han hade lust til Jacobs dotter, och han war härlig hållen öfwer alla i hans faders huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Så gingo Hemor och hans son Sichem i stadsporten, och talade med borgarena i stadenom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Desse män äro fridsamme när oss, och wilja bygga och bo i landena: Så är nu landet widt begripit: Wi wilje taga oss deras döttrar, och gifwa dem wåra döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Men då wilja de wara oss til wiljes, så at de bo när oss, och warda et folk med oss, om wi omskäre allt det som mankön är ibland oss, såsom de omskorne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Deras boskap och ägodelar, och allt det de hafwa, blifwer wårt, om wi eljest blifwom dem til wiljes, så at de bo när oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Och de lydde Hemor och Sichem hans sone, alle de som genom hans stadsport ut och in gingo, och omskoro allt det som mankön war, det som i deras stad ut och in gick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Och på tredje dagenom, då det wärkte dem, togo de twå Jacobs söner, Simeon och Levi, Dinas bröder, hwardera sitt swärd, och gingo dristeliga in i staden, och slogo ihjäl allt det som war mankön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Och slogo också ihjäl Hemor och hans son Sichem med swärds ägg, och togo sina syster Dina utaf Sichems huse, och gingo sin wäg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Då kommo Jacobs söner öfwer de slagna, och skinnade staden, derföre, at de skämt hade deras syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Och togo deras får, fä, åsnar, och hwad i stadenom och på markene war:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Och alla deras håfwor; all barn och qwinnor togo de til fångar, och skinnade allt det i husen war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Och Jacob sade til Simeon och Levi: I hafwen åstadkommit, at jag blifwer illa känder för alla dessa lands inbyggare, de Cananeer och Phereseer: Och jag är en ringa hop; när de nu församla sig öfwer mig, så slå de mig ihjäl, så warder jag om intet gjord med mino huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Men de swarade: Skulle de då handla med wåra syster, såsom med ene sköko?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Och Gud sade til Jacob: Gör dig redo, och far til BethEl, och bo der, och bygg der et altare Gudi som dig syntes, då du flydde för dinom broder Esau.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Då sade Jacob til sitt hus, och til alla de som med honom woro: Lägger ifrån eder de främmande gudar, som äro ibland eder, och renser eder, och förwandler edor kläder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Och görom oss redo at fara til BethEl, at jag må göra der et altare Gudi, den mig hört hafwer i min bedröfwelses tid, och hafwer warit med mig på wägenom, som jag rest hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Då fingo de honom alla de främmande gudar, som woro under deras händer, och deras örnaringar; och han grof dem under ena ek, som stod wid Sichem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Och for ut: Och en Gudsfruktan kom öfwer de städer, som lågo der omkring, at de icke foro efter Jacobs söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Så kom Jacob til Lus i Canaans land, som kallas BethEl, med allt det folk, som med honom war:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Och byggde der et altare, och kallade det rummet ElBethEl, efter det Gud wardt honom der uppenbarad, då han flydde för sinom broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Då dödde Debora Rebeckas amma, och wardt begrafwen nedanför BethEl, under ena ek, hwilken wardt kallad gråtoek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Och Gud syntes åter Jacob, sedan han war kommen utaf Mesopotamien, och wälsignade honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Och sade til honom: Du heter Jacob; men du skalt icke mer heta Jacob, utan Israel skalt du heta: Och så kallade man honom Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Och Gud sade til honom: Jag är den allsmägtige Gud; war fruktsam, och föröka dig: Folk och folks skarar skola komma utaf dig, och Konungar skola komma utaf dina länder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Och det landet, som jag Abraham och Isaac gifwit hafwer, skall jag gifwa dig, och skall det gifwa dine säd efter dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Och så for Gud up ifrå honom, ifrå det rummet, der han med honom talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Men Jacob reste up en stenwård på det rummet, der han med honom talat hade: Och gjöt drickoffer deruppå, och begjöt honom med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Och Jacob kallade det rummet, der Gud hade talat med honom, BethEl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Och han for ifrå BethEl: Och som ännu et litet stycke wägs war til Ephrath, då födde Rachel, och födslan war henne swår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Men då det wardt henne så swårt i födslone, sade Jordgumman til henne: Frukta dig icke; förty denna sonen skalt du ock hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Men då själen utgick, at hon dö måste, kallade hon honom BenOni; men hans fader kallade honom BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Så dödde Rachel, och wardt begrafwen wid wägen til Ephrath, som nu heter BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Och Jacob reste up en wård öfwer hennes graf: Der sammastädes är Rachels grafwård än i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Och Israel for ut, och slog up et tjäll på hinsidon wid det tornet Eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Och det begaf sig, då Israel bodde der i landet, gick Ruben bort och lade sig när Bilha, sins faders frillo: Och det kom för Israel. Men Jacob hade tolf söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Leas söner woro desse: Ruben, Jacobs förstfödde son, Simeon, Levi, Juda, Isaschar och Sebulon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rachels söner woro: Joseph och BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhas Rachels tjensteqwinnos söner: Dan och Naphthali.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Silpas Leas tjensteqwinnos söner: Gad och Asser. Desse äro Jacobs söner, som honom födde woro i Mesopotamien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Och Jacob kom til sin fader Isaac til Mamre i hufwudstaden, som heter Hebron, der Abraham och Isaac hade warit främlingar uti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Och Isaac wardt hundrade och åttatio år gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Och wardt sjuk, och dödde, och wardt samlad til sitt folk, gammal och mätt af lefwande: Och hans söner Esau och Jacob begrofwo honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Detta är Esaus slägte, som kallas Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau tog hustrur af Canaans döttrar: Ada Elons Hetheens dotter, och Aholibama Anas dotter, Zibeons Heweens dotters.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Och Basmath Ismaels dotter, Nebajoths syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Och Ada födde Esan Eliphas: Men Basmath födde Reguel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Aholibama födde Jeus, Jaelam och Korah. Desse äro Esaus barn, som honom födde woro i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Och Esau tog sina hustrur, söner och döttrar, och alla sins huses själar; sina håfwor, och allan boskapen med alla ägodelar, som han förwärfwat hade i Canaans lande: Och for uti et land, ifrå sin broder Jacob.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Förty deras ägodelar woro så stora, at de kunde icke bo med hwarannan: Och landet, der de uti främlingar woro, kunde icke fördraga dem, för deras stora ägodelars skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Så bodde då Esau på Seirs berg: Och denne Esau är Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Detta är Esaus slägte, af hwilkom de Edomeer komne äro på Seirs berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Och så heta Esaus barn: Eliphas Ada son, Esaus hustrus; Reguel Basmaths son, Esaus hustrus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Men Eliphas söner woro desse: Theman, Omar, Zepho, Gatham och Kenas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Och Thimna war Eliphas Esau sons frilla; hon födde Amalek. Desse äro de barn af Ada, Esaus hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Men Reguels barn äro desse: Nahath, Serah, Samma, Missa. Desse äro de barn af Basmath, Esaus hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Men de barn af Aholibama, Esaus hustru, Anas dotter, Zibeons dotters, äro desse, dem hon födde Esau: Jeus, Jaelam och Korah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Desse äro de Förstar ibland Esaus barn: Eliphas barn, den första Esaus sons, woro desse: den Försten Theman, den Försten Omar, den Försten Zepho, den Försten Kenas,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Den Försten Korah, den Försten Gatham, den Försten Amalek. Desse äro de Förstar af Eliphas i Edoms lande; och äro barn af Ada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Och desse äro Reguels barn, Esau sons: Den Försten Nahath, den Försten Serah, den Försten Samma, den Försten Missa. Desse äro de Förstar af Reguel uti de Edomeers lande; och äro barn af Basmath, Esaus hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Desse äro barn af Aholibama, Esaus hustru: Den Försten Jeus, den Försten Jaelam, den Försten Korah. Desse äro de Förstar af Aholibama Anas dotter, Esaus hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Desse äro Esaus barn, och deras Förstar; han är Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Men de barn af Seir den Horeens, som i landena bodde, äro desse: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer och Disan. Desse äro de Förstar ibland de Horeer, alle Seirs barn i Edoms lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Men Lotans barn woro desse: Hori och Hemam; och Lotans syster het Thimna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Sobals barn woro desse: Alvan, Manahat, Ebal, Sepho och Onam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Zibeons barn woro: Aja och Ana: Denne är den Ana, som i öknene påfann mular, då han waktade sins faders Zibeons åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Men Anas barn woro: Dison och Aholibama, det är Anas dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Disons barn woro: Hemdan, Esban, Jithran och Cheran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ezers barn woro: Bilhan, Saawan och Akan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Disans barn woro: Uz och Aran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Desse äro de Förstar ibland de Horeer: Den Försten Lotan, den Försten Sobal, den Försten Zideon, den Försten Ana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Den Försten Dison, den Försten Ezer, den Försten Disan. Desse äro de Förstar ibland de Horeer, de som regerade i Seirs lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Men de Konungar, som i Edoms lande regerade, förra än Israels barn Konungar hade, äro desse:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela war Konung i Edom, Beors son: Och hans stad het Dinhaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Och då Bela blef död, wardt Jobab Konung i hans stad, Seras son af Bozra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Då Jobab blef död, wardt Husam utaf de Themaneers lande Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Då Husam blef död, wardt Konung i hans stad Hadad Bedads son, den som slog de Midianiter på de Moabiters mark; och hans stad het Avith.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Då Hadad blef död, wardt Samla af Masreka Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Då Samla blef död, wardt Konung i hans stad Saul af Rehoboth wid älfwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Då Saul blef död, wardt Baalhanan Achbors son Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Då Baalhanan Achbors son blef död, wardt Hadar Konung i hans stad: Och hans stad het Pagu; och hans hustru het Mehetabeel, Matreds dotter, och Mesahabs dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Alltså heta de Förstar af Esau i deras slägter, rummom och namnom: Den Försten Thimna, den Försten Alva, den Försten Jetheth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Den Försten Aholibama, den Försten Ela, den Försten Pinon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Den Försten Kenas, den Försten Theman, den Försten Mibzar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Den Försten Magdiel, den Försten Iram. Desse äro de Förstar i Edom, såsom de bott hafwa uti deras arfwelande. Och Esau är fadren til de Edomeer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Men Jacob bodde i de landena, der hans fader war en främling uti, nemliga i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Och detta är Jacobs slägt: Joseph war sjutton år gammal, då han wardt en herde öfwer hjorden med sina bröder; och pilten war när Bilhas och Silpas sins faders hustrurs barnom: Och han sade för deras fader, hwilket ondt rykte öfwer dem war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Men Israel hade Joseph kärare än alla de andra sin barn, efter han hade födt honom i ålderdomen: Och gjorde honom en brokot kjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Då nu hans bröder sågo, at deras fader hade honom kärare än alla hans bröder, wordo de honom hätske, och kunde icke tala honom et wänligit ord til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Derutöfwer hade Joseph ena reso en dröm, och sade sina bröder deraf. Då blefwo de honom ännu hätskare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Ty han sade til dem: Käre, hörer hwad mig hafwer drömt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Mig tyckte wi bundom kärfwar på markene, och min kärfwe reste sig up och stod; och edre kärfwar der omkring bugade sig för min kärfwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Då sade hans bröder til honom: Skulle du warda wår Konung, och råda öfwer oss? Och wordo honom ändå hätskare för hans dröm och hans tals skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Och han hade ännu en annan dröm, den förtälde han sina bröder, och sade: Si, jag hafwer ännu haft en dröm: Mig tyckte, at solen och månen och ellofwa stjernor bugade sig för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Och då det hans fader och hans bröder sagdt wardt, straffade honom hans fader, och sade til honom: Hwad är det för en dröm, som dig hafwer drömt? Skall jag och din moder och dine bröder komma, och falla ned på jordena för dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Och hans bröder afundades wid honom. Men hans fader behölt dessa ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Då nu hans bröder gingo bort til at beta deras faders boskap i Sichem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Sade Israel til Joseph: Wakta icke dine bröder boskapen i Sichem? Kom, jag will sända dig til dem. Han sade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Och han sade: Gack bort och se til, om det står wäl til med dina bröder och boskapenom; och säg mig igen, huru det hafwer sig. Och han sände honom utaf den dalenom Hebron, at han skulle gå til Sichem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Då fann honom en man, der han for will på markene. Han frågade honom, och sade: Hwem söker du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Han swarade: Jag söker mina bröder: Käre, säg mig, hwarest de wakta hjorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mannen sade: De äro hädan farne; ty jag hörde, at de sade: Låt oss gå til Dothan. Då drog Joseph efter sina bröder, och fann dem i Dothan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Som de nu långt ifrå fingo se honom, förra än han kom när intil dem, rådslogo de til at döda honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Och sade inbördes: Si, drömaren kommer här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Så kommer nu, och låter oss slå honom ihjäl och kasta honom i ena grop; och säga, at et ondt djur hafwer ätit up honom: Så får man se, hwad hans drömar äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'När Ruben hörde det, wille han frälsa honom af deras händer, och sade: Låter oss icke slå ena själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Och ytterligare sade Ruben til dem: Låter oss icke utgjuta blod: Utan låt oss kasta honom i den gropena, som är i öknene, och icke komma händer wid honom. Men han wille hafwa frälst honom utu deras hand, at han måtte hafwa haft honom til sin fader igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Då nu Joseph kom til sina bröder, afklädde de honom hans kjortel, med den brokota kjortelen, som han hade uppå sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Och togo honom, och kastaden i ena grop; men gropen war tom, och intet watn deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Och de satte sig ned til at äta. I det hofwo de sin ögon up, och sågo en hop Ismaeliter komma ifrå Gilead med deras camelar; de förde kryddor, balsam och mirrham, och foro ned uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Då sade Juda til sina bröder: Hwad hjelper det oss, at wi dräpe wår broder, och fördölje hans blod?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommer, och låter oss sälja honom de Ismaeliter, at wåra händer icke förtaga sig på honom; ty han är wår broder, wårt kött och blod. Och de lydde honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Och då de Midianitiske köpmännerne foro der fram, drogo de honom up af gropene, och sålde honom de Ismaeliter för tjugu silfwerpenningar: De förde honom in i Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Då nu Ruben kom åter til gropena, och fann icke Joseph derinne, ref han sin kläder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Och kom åter til sina bröder, och sade: Pilten är icke der; hwart skall jag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Då togo de Josephs kjortel, och slagtade en bock, och indoppade kjortelen i blodet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Och sände den brokota kjortelen bort, och läto bära honom til deras fader, och sade: Denna hafwom wi funnit: Se, om det är dins sons kjortel eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Men han kände honom, och sade: Det är mins sons kjortel. Et ondt djur hafwer ätit up honom; et wilddjur hafwer rifwit Joseph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Och Jacob ref sin kläder, och swepte en säck om sina länder, och sörjde sin son långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Och alle hans söner och döttrar gingo til, at de skulle hugswala honom; men han wille icke låta hugswala sig, och sade: Jag warder med sorg wederfarande i grafwena til min son. Och hans fader gret honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Men de Midianiter sålde honom in i Egypten Potiphar, Pharaos hofmästare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Det begaf sig på samma tiden, at Juda for neder ifrå sina bröder, och gaf sig til en man i Adullam, som het Hira.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Och Juda såg der en Canaanesk mans dotter, han het Sua; och tog henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Och då han belåg henne, wardt hon hafwande, och födde en son, den kallade hon Er.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Och hon wardt åter hafwande, och födde en son, den kallade hon Onan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Åter födde hon en son, honom kallade hon Sela. Och han war i Chesib, när hon den födde. Och han war i Chesib, när hon den födde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Och Juda gaf sinom första sone Er ena hustru, som het Thamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Men Er Juda förstfödde son war arg för HERranom; derföre dödade HERren honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Då sade Juda til sin son Onan: Lägg dig när dins broders hustru, och tag henne til ägta, at du upwäcker dinom broder säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Men då Onan wisste, at säden icke skulle wara hans egen, då han låg när sins broders hustru, lät han det falla uppå jordena, och förderfwade det, at han icke skulle gifwa sinom broder säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Då misshagade HERranom det onda han gjorde, och dödade honom och.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Då sade Juda til sina sonahustru Thamar: Blif en enka i dins faders huse, så länge Sela min son warder stor; förty han tänkte, at han til äfwentyrs måtte ock så dö såsom hans broder. Så gick Thamar bort, och blef i sins faders huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Då nu månge dagar förledne woro, dödde Suas dotter, Judas hustru. Och sedan Juda utsörjt hade, gick han up til at klippa sin får i Thimnath, med sin herda Hira af Adullam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Då wardt Thamar sagdt: Si, din swär går up til Thimnath til at klippa sin får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Då lade hon af sin enkokläder, som hon drog, dokade sig, och förhöljde sig, och satte sig ut för porten på wägen emot Thimnath: Förty hon såg, at Sela war stor worden, och hon war icke gifwen honom til hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Då nu Juda såg henne, mente han det hade warit en sköka; förty hon hade förhöljt sitt ansikte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Och han wek af wägenom til henne, och sade: Käre, låt mig ligga när dig; ty han wisste icke, at det war hans sonahustru. Hon swarade: Hwad will du gifwa mig, at du ligger när mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Han sade: Jag will sända dig en bock ifrå hjordenom. Hon swarade: Gif mig en pant, så länge du sänder mig honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Han sade: Hwad wilt du jag skall gifwa dig för en pant? Hon swarade: Din ring, och din hufwudbonad, och din staf, som du hafwer i händerna. Det gaf han henne, och låg när henne, och hon wardt hafwande af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Och hon stod up, och gick dädan, och lade doken af, och tog sin enkokläder uppå igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Men Juda sände bocken med sin herde af Adullam, at han skulle taga igen panten ifrå qwinnonen: Och han fann henne intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Då frågade han folket, som bodde wid det rummet, och sade: Hwarest är den skökan, som satt ute på wägenom? De swarade: Ingen sköka hafwer der warit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Och då han kom åter til Juda, och sade: Jag hafwer intet funnit henne; dertil säger folket, som der bor, at der hafwer ingen sköka warit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda sade: Hafwe sig det, at wi icke til äfwentyrs skulle komma på skam: Ty jag hafwer sändt bocken, men du hafwer icke funnit henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Tre månader derefter wardt det Juda sagdt: Din sonahustru Thamar hafwer bolat; och si, i boleri är hon worden hafwande: Juda sade: Hafwer henne här fram, at hon skall brännas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Och då hon hades fram, sände hon til sin swär och sade: Af denna mannen är jag hafwande, som detta tilhörer. Och sade: Känner du ock, hwem denne ringen och hufwudbonaden och stafwen tilhörer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda kände det, och sade: Hon är rättfärdigare än jag; ty jag hafwer icke gifwit henne min son Sela. Dock belåg han henne intet mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Och då hon skulle föda, funnos twillingar i hennes lifwe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Och som hon nu födde, gaf sig en hand ut; då tog Jordgumman och band der en rödan tråd om, och sade: Denne skall först utkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Men då han drog sina hand åter in, kom hans broder ut, och hon sade: Hwi är hinnan för dina skull sönderremnad? Och man kallade honom Perez.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Derefter kom hans broder ut, som hade den röda tråden om sina hand; och man kallade honom Serah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joseph wardt förd neder i Egypten: Och Potiphar, en Egyptisk man, Pharaos hofmästare, köpte honom af de Ismaeliter, som honom hade fört der ned.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Och HERren war med Joseph, så at han wardt en lyckosam man: Och war i sins herras dens Egyptiens huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Och hans herre såg, at HERren war med honom: Ty allt det han gjorde, lät HERren gå lyckosamlig til med honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Så at han fann nåd för sinom herra, och wardt hans tjenare: Han satte honom öfwer sitt hus, och allt det han hade lät han under hans händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Och ifrå den tiden, då han hade satt honom öfwer sitt hus och alla sina ägodelar, wälsignade HERren den Egyptiens hus för Josephs skull: Och war alltsammans HERrans wälsignelse i allo de han hade, hema och på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Derföre lät han det allt under Josephs händer, hwad han hade; och hade intet deraf, utan allena brödet, som han åt. Och Joseph war dägelig och fager under ansiktet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Och det begaf sig, då detta war skedt, at hans herras hustru kastade sin ögon på Joseph, och sade: Ligg när mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Men han wägrade det henne, och sade til henne: Si, min herre wet icke hwad i hans huse är, och allt det han hafwer, hafwer han gifwit under mina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Och hafwer intet så godt i sino huse, det han i mitt wåld icke gifwit hafwer, utan dig, ty du äst hans hustru. Hwi skulle jag nu så mycket ondt göra, och synda emot Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Men hon hade dageliga sådana ord til Joseph; men han lydde henne intet, at han skulle ligga när henne, eller wara något om henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Det begaf sig en dag, at Joseph gick in i huset til at göra sina syslo; och ingen af husfolket war der när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Och hon fick honom i hans mantel, och sade: Ligg när mig. Men han lät blifwa mantelen i hennes hand, och rymde ut af huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Då hon nu såg, at han lät blifwa mantelen i hennes hand, och rymde ut,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Kallade hon husfolket, och sade til dem: Si, han hafwer fört oss här in en Ebreisk man, at han skulle komma oss på skam. han kom här in til mig, på det han skulle ligga när mig; men jag ropade med höga röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Och då han hörde, at jag skriade och ropade, då lefde han sin mantel när mig, och flydde, och lopp ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Och hon lade hans mantel när sig, så länge hennes herre kom hem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Och talade til honom samma orden, och sade: Den Ebreiske tjenaren, som du hafwer haft här in, kom här in til mig, at han skulle komma mig på skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Men då jag skriade och ropade, lefde han sin mantel när mig, och flydde ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Då hans herre hörde sådana sine hustrus ord, som hon til honom talade, och sade: Så hafwer mig din Ebreiske tjenare gjort; wardt han ganska wred.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Då tog hans herre honom, och lade honom i fängelse, der Konungens fångar inne lågo: Och der låg han då i fängelset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Men HERren war med honom, och war honom gunstig, och lät honom finna nåd för befallningsmannen öfwer fångahuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Så at han befallte alla fångarna i fängelsena under hans hand, at allt det der skedde, måste ske genom honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Förty befallningsmannen öfwer fängelset såg, at HERren war med honom i allt det som under hans händer war, och at HERren lät, det han gjorde, lyckosammeliga tilgå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Och det begaf sig derefter, at Konungens i Egypten höfwitsman öfwer skänkerna, och höfwitsmannen öfwer bakarena, bruto deras herra Konungenom i Egypten emot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Och Pharao wardt wred uppå dem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Och lät sätta dem i hofmästarens hus i fängelse, der Joseph låg fången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Och hofmästaren satte Joseph öfwer dem, at han skulle tjena dem; och de såto några dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Och både skänken och bakaren drömde om ena natt hwar sin dröm, och hwars deras dröm hade sin uttydelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Då nu Joseph kom om morgonen in til dem, och såg dem ångse,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Frågade han dem, och sade: Hwi ären i så ångse i dag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'De swarade: Oss hafwer drömt, och wi hafwom ingen, som oss det utlägger. Joseph sade: Utläggningen hörer Gudi til; dock förtäljer mig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Då förtälde skänken sin dröm för Joseph, och sade til honom: Mig drömde, at et winträ war för mig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Det hade tre grenar; det grönskades, wäxte och blomstrades, och dess drufwor wordo mogna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Och jag hade Pharaos skänkekar i mine hand, och tog och kryste dem i skänkekaret, och fick Pharao skänkekaret i handena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joseph sade: Detta är uttydningen: Tre grenar äro tre dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Efter tre dagar skall Pharao uphäfwa ditt hufwud, och sätta dig åter til dit ämbete, at du får honom skänkekaret i hans hand, såsom tilförene, då du war hans skänk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Men tänk uppå mig, då dig går wäl, och gör barmhertighet med mig, at du Pharao ingifwer, at han tager mig utaf detta huset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Ty jag är hemliga bortstulen utaf de Ebreers lande: Så hafwer jag ock här intet gjort, at de mig insatt hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Då bakaren såg, at uttydningen war god, sade han til Joseph: Mig hafwer ock drömt, at jag bar tre flätade korgar på mitt hufwud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Och i öfwersta korgenom allahanda bakad mat til Pharaos behof; och foglarne åto af korgenom på mitt hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joseph swarade, och sade: Detta är uttydningen: Tre korgar äro tre dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Och efter tre dagar skall Pharao upphäfwa ditt hufwud, och hänga dig i en galga; och foglarne skola äta ditt kött på dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Och det hände tredje dagen, då begick Pharao sin årsdag, och han gjorde alla sina tjenare ena måltid: Och upphof den öfwersta skänkens hufwud, och den öfwersta bakarens, ibland sina tjenare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Och satte den öfwersta skänken åter til sitt skänkeämbete, at han skulle få Pharao skänkekaret i handena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Men den öfwersta bakaren lät han hänga; som Joseph hade uttydt honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Men den öfwerste skänken tänkte intet på Joseph, utan förgat honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Och tu år derefter hade Pharao en dröm, såsom han hade ståndit wid älfwena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Och sett af älfwene upstiga sju nöt skön och fet; och de gingo i goda bet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Sedan såg han annor sju nöt upstiga af älfwene, wanskapeliga och magra; och gingo jemte de andra på strandene wid älfwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Och de sju wanskapeliga och magra nöten åto up de sju sköna och feta nöten. Då waknade Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Och han somnade åter, och åter drömde honom, och såg, at sju ax full och tjock wäxte på enom stjelk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Derefter såg han sju tunn förwisen ax upgå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Och de sju magra axen upslukte de sju stora och fulla axen. Då waknade Pharao, och såg, at det war en dröm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Och då det wardt morgon, war hans ande bedröfwad; och skickade ut, och lät kalla alla spåmän i Egypten, och alla wisa, och förtälde dem sin dröm: Men der war ingen, som honom kunde uttyda för Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Då talade den öfwerste skänken med Pharao, och sade: Jag kommer ihog i dag mina synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Då Pharao war förtörnad på sina tjenare, och lade mig med den öfwersta bakaren i fängelse, i hofmästarens hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Då drömde oss bådom i ene natt, hwar sin dröm, hwars uttydning hwarjom för sig pågalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Då war när oss en Ebreisk ung man, hofmästarens tjenare; honom förtälde wi det, och han uttydde oss wåra drömmar, hwarjom efter sinom dröm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Och som han oss uttyddet, så är det gånget: Ty jag är åter satt til mitt ämbete, och han är hängder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Då sände Pharao bort, och lät kalla Joseph, och de hade honom utu fängslet. Och han lät raka sig, och förwandla sin kläder, och kom in til Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Då sade Pharao til honom: Mig hafwer drömt en dröm, och ingen är, som honom uttyder: Men jag hafwer hört af dig sägas, at när du hörer en dröm, då uttyder du honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph swarade Pharao, och sade: Det står icke mig til; men Gud skall dock förkunna Pharao det godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Pharao sade til Joseph: Mig drömde, jag stod på strandene wid älfwena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Och såg upstiga af älfwene sju nöt, fet och skön, och de gingo i goda bet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Och efter dem såg jag sju annor nöt upstiga, tunn och fast wanskapeliga och magra; jag hafwer icke i hela Egypten sett så wanskapeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Och de sju wanskapeliga och magra nöten åto up de sju första feta nöten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Och då de hade ätit dem up, syntes intet på dem, at de hade ätit dem, och woro wanskapeliga såsom tilförene. Då waknade jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Och såg åter i minom dröm sju ax woxen på enom stjelk full och tjock.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Derefter gingo up sju torr ax tunn och förwisen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Och de sju tunna axen upsluko de sju torra axen. Och jag hafwer sagt det mina spåmän; men de kunna icke tyda mig det ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Joseph swarade Pharao: Båda drömarne, Pharao, äro ens. Gud förkunnar Pharao, hwad han göra will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'De sju sköna nöten äro sju år, och de sju fulla axen äro ock de sju åren: Det är allt enahanda dröm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'De sju magra nöten och wanskapeliga, som efter de andra upstigna äro, äro sju år; och de sju magra och förwisnade axen skola wara sju hård år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Det är nu det jag sagt hafwer til Pharao, at Gud underwisar Pharao, hwad han göra will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Si, sju år warda kommande med stor ymnoghet i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Och efter dem warda sju hård år kommande, at man warder förgätandes all sådana ymnoghet i Egypti lande: Och den dyre tiden warder förtärandes landet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'At man intet skall weta af den ymnoghetene i landena, för den dyra tidens skull, som efter kommer: Förty han skall warda ganska swår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Men det Pharao hafwer andra resona drömt betyder, at Gud skall sådant wisserliga och snarliga göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nu må Pharao se efter en förståndig och wis man, den han sätta må öfwer Egypti land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Och skaffa, at han förskickar ämbetsmän i landena, och taga den femte delen i Egypti lande i de sju rika åren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Och församle alla spisning af de goda åren, som komma skola, at de låta inkomma säd uti Pharaos kornhus til förråd i städerna, och förwara det:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'På det man finner landena spisning i de sju hårda åren, som komma skola öfwer Egypti land; at landet icke förderfwas af hunger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Det talet behagade Pharao och alla hans tjenare wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Och Pharao sade til sina tjenare: Huru kunne wi finna en sådana man, som Guds Ande är uti?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Och sade til Joseph: Efter Gud hafwer allt sådant kundgjort dig, är ingen så klok och förståndig, som du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du skall wara öfwer mitt hus, och efter dino orde skall allt mitt folk lydigt wara: Allena i mitt konungsliga säte will jag wara mer än du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Och sade: Si, jag hafwer satt dig öfwer hela Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Och tog sin ring af sine hand, och klädde honom Joseph i hwitt silke, och hängde en guldkedjo på hans hals.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Och lät honom sitta på den andra wagnen, och lät utropa honom: Denne är landsens fader: Och satte honom öfwer hela Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Och Pharao sade til Joseph: Jag är Pharao; utan din wilja skall ingen, i hela Egypti lande, röra sin hand eller fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Och kallade honom det hemligaste rådet; och gaf honom til hustru Asnath Potiphera dotter Prestens i On. Så for Joseph ut til at bese Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Och han war tretio år gammal, då han stod för Pharao. Och for ut ifrå Pharao, och for omkring hela Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Och landet gjorde allt så i de sju rika åren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Och församlade i de sju åren alla spisning i Egypti land, och läto det i städerna: Ehwad spisning som wäxte på markene wid hwar och en stad allt omkring, det läto de komma der in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Så lade Joseph tilhopa sädena öfwer måtto mycket, som sandkornen i hafwet, så at han wände igen at räkna; ty man kunde det icke räkna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Och Joseph wordo födde twå söner, förra än den dyre tiden kom, hwilka honom födde Asnath Potiphera dotter Prestens i On.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Och kallade den första Manasse; förty, sade han, Gud hafwer låtit mig förgäta alla mina olycko, och mins faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den andra kallade han Ephraim; förty, sade han, Gud hafwer låtit mig wäxa til i mins eländes lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Då nu de sju rika åren woro framliden i Egypten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Så begynte de sju hårda åren gå uppå, som Joseph hade omtalat. Och wardt en dyr tid i all land; men i hela Egypti lande war bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Då nu Egypti land ock led hunger, ropade folket til Pharao om bröd. Men Pharao sade til alla Egyptier: Går bort til Joseph, hwad han säger eder, det görer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'När nu dyr tid war öfwer allt landet, slog Joseph kornhusen up allestäds, och sålde de Egyptier: Förty som dyre tiden wardt ju längre ju större i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Och all land kommo til Egypten, til att köpa när Joseph: Förty den dyre tiden fick öfwerhandena i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Men då Jacob såg, at säd war fal i Egypten, sade han til sina söner: Hwi sen I icke til?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Si, jag hörer, at uti Egypten är säd nog, farer der ned, och köper oss säd, at wi må lefwa och icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Så foro då tio Josephs bröder ned, at de skulle köpa säd i Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Ty BenJamin Josephs broder lät Jacob icke fara med sina bröder, ty han sade: Honom måtte något ondt wederkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Så foro Israels barn åstad til at köpa säd med androm, som kommo med dem; ty det war ock dyr tid i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Men Joseph war rådandes i landena, och sålde säd allo folkena i landena. Då nu hans bröder kommo til honom, föllo de ned på jordene för honom på sitt ansikte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Och han såg uppå dem, och kände dem, och låts wara främmande emot dem, och talade skarpt med dem, och sade til dem: Hwadan kommen I? De sade: Utaf Canaans land til at köpa spisning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Och ändå han kände dem, så kände de dock intet honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Och Joseph tänkte på drömen, som honom hade drömt om dem, och sade til dem: I ären spejare, och ären komne til at bese, hwarest landet är öpet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'De swarade honom: Nej, min herre, dine tjenare äro komne til at köpa spisning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wi äre alle ens mans söner; wi äre redelige, och dine tjenare hafwa aldrig warit spejare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Han sade til dem: Nej, utan I ären komne til at bese, hwarest landet är öpet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'De swarade honom: Wi dine tjenare äre tolf bröder, ens mans söner i Canaans land; och den yngste är när wår fader, men den ene är icke mer til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph sade til dem: Detta är det jag hafwer sagt eder, spejare ären I.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'De uppå will jag pröfwa eder: Wid Pharaos lif, I skolen icke komma hädan, med mindre edar yngste broder kommer hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sänder en af eder bort, som hemtar hit edar broder: Men I skolen wara fångne. Så will jag pröfwa edart tal, om i faren med sanningene eller icke. Ty hwar så icke, så ären I, wid Pharaos lif, spejare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Och han lät dem allesamman i förwaring i tre dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Om tredje dagen sade han til dem: Wiljen I lefwa, så görer alltså; ty jag fruktar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ären I redelige, så låter en edar broder ligga bunden i edart fängelse; men I farer bort, och förer hem hwad som I köpt hafwen emot hungeren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Och förer edar yngsta broder hit til mig, så will jag tro edor ord, på det I icke skolen dö. Och de gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Men de talade inbördes: Detta hafwe wi förskyllat på wår broder, at wi såge hans själs ångest, då han bad oss, och wi wille intet höra honom; derför kommer nu denna bedröfwelsen öfwer oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben swarade dem, och sade: Sade jag icke eder, då jag talade: Synder icke på pilten; och I willen icke hörat? Nu warder hans blod utkräfd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Men de wisste icke, at Joseph förstod det; ty han talade med dem med en tolk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Och han wände sig ifrå dem, och gret. Då han nu wände sig åter til dem, och talade med dem, tog han Simeon utaf dem, och bandt honom för deras ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Och gaf befallningen, at deras säckar skulle fyllas med mälning, och gifwas deras penningar igen, hwars i hans säck; dertil ock hwarjom sina täring på resone. Och man gjorde dem så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Och de lade sina waror på sina åsnar, och foro dädan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Men då endera lät up sin säck, at han skulle fodra sin åsna i herberget, wardt han warse sina penningar, som lågo ofwan i säckenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Och sade til sina bröder: Jag hafwer fått mina penningar igen; si, de äro i minom säck. Då förföll dem deras hjerta och förskräcktes inbördes, och sade: Hwi hafwer Gud gjort oss så?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Då de nu kommo hem til deras fader Jacob i Canaans lande, sade de honom allt det dem wederfarit war, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Den mannen, som är herre i landet, talade skarpt til oss, och hölt oss för landsens spejare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Och då wi swarade: Wi äre redelige, och hafwe aldrig warit spejare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Utan ärom tolf bröder, wårs faders söner; en är icke mer til, och den yngste är ännu i denna dag när wår fader i Canaans lande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Sade han til oss: Deruppå will jag märkat, at I ären redelige: En edar broder låter när mig qwar, och tager nödtorft til edor hus, och farer bort:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Och hemter edar yngsta broder hit til mig, så kan jag märka, at I icke ären spejare, utan redelige män; så will jag ock gifwa eder edar broder igen, och så må I bruka edart bästa i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Och då de slogo ut af säckarna, fann hwar och en sitt penningaknyte i sinom säck: Och då de sågo, at det war deras penningaknyte, wordo de, med deras fader, förskräckte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Då sade Jacob deras fader: I hafwen gjort mig barnlös; Joseph är icke mera til, Simeon är ock icke mera til, BenJamin wiljen I taga ifrå mig: Det går allt öfwer mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben swarade sinom fader, och sade: Om jag icke förer dig honom hem igen, så dräp båda mina söner: Allenast gif honom i mina hand, jag will föra dig honom hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Han sade: Min son skall icke fara ned med eder; ty hans broder är död, och han är allena igenblifwen: Om honom wederfores något ondt i wägen, der I resten, worden I drifwande min grå hår med sorg neder i grafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Men den dyre tiden twingade landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Och det wardt allt, som de hade fört utaf Egypten, sade deras fader Jacob til dem: Farer åter dit, och köper oss någon spisning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Då swarade honom Juda, och sade: Den mannen wederlade oss det högeliga, och sade: I skolen icke komma för min ögon, med mindre edar broder är med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Är det nu så, at du sänder wår broder med oss, så wilje wi fara ned, och köpa dig spisning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Men är det så, at du icke sänder honom, så fare wi icke neder; ty mannen hafwer sagt oss: I skolen icke komma för min ögon, utan edar broder är med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sade: Hwi hafwen I så illa gjort emot mig, at I hafwen det sagt mannenom, at I haden än en broder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'De swarade: Den mannen frågade så grant om oss och wåra slägt, och sade: Lefwer edar fader än? Hafwen I ännu en broder? Då sade wi honom, som han frågade: Huru kunde wi weta, at han skulle säga: Hafwer edar broder hit ned med eder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Då sade Juda til Israel sin fader: Låt pilten fara med mig, at wi må göra oss redo och färdas, och mågom lefwa, och icke dö, både wi och du, och wår barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Jag will wara god för honom; utaf mina händer skall du äska honom: Förer jag dig icke honom igen, och sätter honom fram för din ögon, så will jag hafwa skuld så länge jag lefwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Ty hwar wi icke hade fördröjt, hade wi wäl allaredo twå resor warit igenkomne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Då sade Israel deras fader til dem: Måste det ju så wara, så görer det, och tager af landsens bästa frukt i edra säckar, och förer mannenom skänker dit neder, något balsam och hannog, och örter, och mirrham, och dadel och mandel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Tager ock andra penningar med eder, och de penningar, som I hafwen fått igen ofwan i edra säckar, förer också med eder; tiläfwentyrs der är någon willa ibland kommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Dertil tager edar broder; görer eder redo, och farer til mannen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Men allsmägtig Gud gifwe eder barmhertighet för den mannenom, at han måtte eder fri låta den andra broderen och BenJamin. Men jag måste wara, som den der sin barn slätt mist hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Då togo de dessa skänker, och penningar dubbelt med sig, och BenJamin; gjorde sig redo, och foro in i Egypten, och gingo in för Joseph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Då såg Joseph dem med BenJamin, och sade til honom, som war öfwer hans hus: Haf dessa männerna in i huset, och slagta, och red til: Förty de skola äta med mig i middag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Och mannen gjorde såsom Joseph honom sagt hade, och hade männerna in i Josephs hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Men de fruktade sig, at de wordo hafde i Josephs hus, och sade: Wi äre här införde för penningarnas skull, som wi tilförene funnom i wåra säckar, at han will komma oss det uppå, och låta en dom gå öfwer oss, der han oss med tager til sina trälar, med wåra åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Derföre gingo de til mannen, som war öfwer Josephs hus, och talade med honom utanför dörena af husena:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Och sade: Min herre, wi worom tilförene här nedre til at köpa spisning:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Och då wi kommo i herberget, och löste up wåra säckar, si, då woro hwars och ens penningar ofwan i hans säck, med fulla wigt; derföre hafwe wi åter fört dem med oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Hafwom också fört andra penningar med oss, til at köpa spisning med. Men wi wete icke, ho som hafwer stungit oss wåra penningar i wåra säckar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Men han sade: Warer til frids, frukter eder icke, edar Gud, och edar faders Gud, hafwer gifwit eder en skatt i edra säckar; edra penningar hafwer jag fått. Och han hade Simeon ut til dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Och hade dem i Josephs hus: Gaf dem watn, at de skulle twå sina fötter, och gaf deras åsnar foder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Men de redde til skänkerna, til dess Joseph kom til middagen: Ty de hade hört, at de skulle der äta bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Då nu Joseph gick in i huset, båro de honom skänkerna i huset på sina händer, och föllo för honom neder på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Men han tackade dem kärliga, och sade: Går det wäl med edrom fader den gamla, der I mig af saden? Lefwer han ännu?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'De swarade: Wårom fader dinom tjenare går wäl, och han lefwer ännu: Och bugade sig, och föllo ned för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Och han lyfte up sin ögon, och såg sin broder BenJamin, sine moders son, och sade: Är det edar yngste broder, som I saden mig af? Och sade ytterligare: Gud ware dig nådelig, min son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Och Joseph hastade, ty hans hjerta war brinnande öfwer sin broder, och sökte rum til at gråta; och gick i sin kammar, och gret der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Och då han hade twagit sitt ansikte, gick han ut, och hölt sig fast, och sade: Lägger bröd fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Och der bars fram, besynnerliga för honom, och besynnerliga för dem, och för de Egyptier, som med honom åto, ock besynnerliga: Förty de Egyptier töras icke äta bröd med de Ebreer, det är en wederstyggelse för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Och de sattes för honom, den förstfödde efter sina förstfödslo, och den yngste efter sin ungdom. Der förundrade de sig uppå inbördes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Och man bar dem besynnerliga rätter af hans bord: Men BenJamin fem sinom mer än de andra; och de drucko, och wordo druckne med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Och Joseph befallte honom, som war öfwer hans hus, och sade: Fyll dessa männernas säckar med spisning, så mycket de kunna föra, och lägg hwarjom sina penningar ofwan i hans säck:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Och mina silfskål ofwan i dens yngstas säck med penningarna för sädena. Han gjorde, som Joseph honom sade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Om morgonen, då ljust wardt, läto de männerna fara med sina åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Då de nu woro ut af stadenom, och icke långt komne, sade Joseph til honom, som war öfwer hans hus: Up och far efter männerna, och när du får dem, så säg til dem: Hwi hafwen I lönt godt med ondo?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Är icke det der min herre dricker utaf, och der han spår med? I hafwen illa gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Och som han beslog dem, sade han sådan ord til dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'De swarade honom: Hwi talar min herre sådana ord? Bort det, at dine tjenare skulle så göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Si, penningarna, som wi funnom ofwan uti wåra säckar, hafwom wi fört til dig igen af Canaans lande: Och hwi skulle wi då hafwa stulit silfwer eller guld af dins herras huse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'När hwilken det warder funnit ibland dina tjenare, han må dö: Dertil wilje wi ock wara mins herras trälar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Han sade: Ja, ware som I hafwen sagt: När hwilkom det finnes, han ware min träl: men I skolen wara löse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Och då de hastade sig, och lade hwar sin säck af ned på jordena, och hwar lät up sin säck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Och han sökte, och begynte på den första, in til den yngsta; då fans skålen i BenJamins säck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Då refwo de sin kläder, och ladde hwar uppå sin åsna, och foro åter in i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Och Juda gick med sina bröder in i Josephs hus: Ty han war ändå der, och de föllo ned på jordena för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph sade til dem: Hwi torden I det göra? Weten I icke, at en sådana man, som jag är, kunde spå til?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda sade: Hwad skole wi säga minom herra, eller huru skole wi bära före? Gud hafwer funnit dina tjenares missgerningar: Si, wi och den, som skålen är funnen när, äre min herras trälar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Men han sade: Bort det, at jag skulle så göra. Den mannen, som skålen är funnen när, han skall wara min träl: Men I farer med frid up til edar fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Då gick Juda til honom, och sade: Min herre, låt din tjenare tala et ord i dina öron, min herre, och din wrede harmes icke öfwer din tjenare; ty du äst såsom Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Min herre frågade sina tjenare, och sade: Hafwen I ock någon fader, eller broder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Då swarade wi: Wi hafwe en fader, och han är gammal, och en ung dräng föddan i hans ålderdom, och hans broder är död, och han är allena blifwen igen af sine moder, och hans fader hafwer honom kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Då sade du til dina tjenare: Hafwer honom hit ned til mig, och jag will göra honom godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Men wi swarade minom herra: Pilten kan icke komma ifrå sinom fader: Hwar han komme honom ifrå, dödde han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Då sade du til dina tjenare: Hwar edar yngste broder icke kommer här med eder, skolen I icke mera komma för min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Då forom wi up til din tjenare, min fader, och sadom honom mins herras tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Då sade wår fader: Farer åter bort, och köper oss någon spisning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Men wi sade: Wi kunne icke fara der ned, med mindre wår yngste broder är med oss, så wilje wi fara der ned: Ty wi kunne icke komma för dens mansens ögon, hwar wår yngste broder icke är med oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Då sade din tjenare, min fader, til oss: I weten, at min hustru hafwer födt mig twå:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Den ene gick bort ifrån mig, och det sades, at han skulle wara ihjälrifwen; och jag hafwer ej sett honom allt härtil.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Skolen I ock taga denna ifrå mig, och honom wederfars något ondt, så warden I drifwande min grå hår med sorg ned i grafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Om jag nu komme hem til din tjenare, min fader, och pilten wore icke med oss, efter hans själ hänger in til desses själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Så sker det, då han ser, at pilten icke är tilstädes, at han dör: Så worde wi dine tjenare, dins tjenares, wårs faders grå hår förande med jämmer ned i grafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ty jag, din tjenare, hafwer warit minom fader god för pilten, och sagt: Hafwer jag icke honom til dig igen, så will jag hafwa skuld i alla mina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Derföre, låt din tjenare blifwa här qwar minom herra för en träl i piltens stad; och låt pilten fara up med sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Förty, huru skulle jag fara up til min fader, när pilten är icke med mig? Jag finge se den jämmer, som min fader uppå komme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Då kunde icke Joseph hålla sig för allom dem, som omkring stodo, och han ropade: Går alle ut ifrå mig. Och stod ingen när honom, då Joseph bekände sig för sina bröder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Och han gret öfwerljudt, så at de Egyptier och Pharaos tjenare det hörde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Och han sade sina bröder: Jag är Joseph; lefwer min fader ännu? Och hans bröder kunde intet swara honom: Så förskräckte woro de för hans ansikte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Men han sade: Går dock hit til mig. Och de gingo til honom, och han sade: Jag är Joseph edar broder, den I hafwen sålt in uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Och nu låter det icke bekymra eder, och tänker icke at jag derföre är wred, at I hafwen sålt mig hit: Ty för edra wälfärds skull hafwer Gud sändt mig hit för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Ty det är nu tu år, at dyr tid hafwer warit i landena; och äro ännu fem år, at ingen plöjning eller upskörd skall warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Men Gud hafwer sändt mig hit för eder, at han will låta eder blifwa qwara på jordene, och hålla eder wid lif genom stor under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Så hafwen icke nu I sändt mig hit, utan Gud: Han hafwer gjort mig såsom en fader til Pharao, och til en herra öfwer allt hans hus, och til en Första i hela Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Skynder eder nu, och farer up til min fader, och säger honom: Det låter din son Joseph säga dig: Gud hafwer satt mig til en herra i hela Egypti land; kom ned til mig, försumma dig icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du skalt bo i det landet Gosen, och wara hardt när mig, du och din barn, och din baranabarn, din får och fä, och allt det ditt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Jag will der försörja dig: Ty det är ännu fem åra dyr tid at du icke warder förderfwad med ditt hus, och allt det ditt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Si, edor ögon se, och mins broders BenJamins ögon, at jag talar munteliga med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Förkunner minom fader alla mina härligheter i Egypten, och allt det I sett hafwen. Skynder eder, och kommer hit ned med minom fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Och han fick sin broder BenJamin om halsen, och gret; och BenJamin gret ock wid hans hals.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Och han kyste alla sina bröder, och gret öfwer dem. Sedan talade hans bröder med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Och när det ryktet kom i Pharaos hus, at Josephs bröder woro komne, behagade det Pharao wäl, och alla hans tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Och Pharao sade til Joseph: Säg dina bröder: Detta görer: Lader edor djur; farer bort, och när I kommen i Canaans land,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Så tager edar fader och edart folk, och kommer til mig, jag will gifwa eder af allt det goda, som i Egypti land är, at I skolen äta märgen i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Och bjud dem: Görer alltså: Tager edor utaf Egypti lande wagnar til edor barn och hustrur, och förer edar fader, och kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Och skoner icke edor bohags ting: Förty allt det goda i hela Egypten skall höra eder til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Israels barn gjorde så, och Joseph fick dem wagnar, efter Pharaos befallning, och förtäring på wägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Och gaf dem allom, hwarjom för sig, högtidskläder; men BenJamin och han trehundrad silfwerpenningar, gaf fem högtidsklädningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Men fadrenom sände han tio åsnar, ladda med gods utaf Egypten, och tio åsninnor med mälning och bröd och spisning, sinom fader på wägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Och så lät han sina bröder fara, och sade til dem: Kifwer icke på wägenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Så foro de utaf Egypten, och kommo uti Canaans land til sin fader Jacob;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Och förkunnade honom det, och sade: Din son Joseph lefwer ännu, och är en herre i hela Egypti lande. Men honom föll det icke i sinnet, ty han trodde dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Då sade de honom all Josephs ord, som han til dem sagt hade. Och då han såg wagnarna, som Joseph utsändt hade til at föra honom med, wardt hans ande lefwandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Och sade: Jag hafwer nog, at min son Joseph lefwer ännu. Jag will fara bort och se honom, förra än jag dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel for dit med allt det honom tillhörde. Och då han kom til BerSaba, offrade han et offer sins faders Isaacs Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Och Gud sade til honom om nattena i ene syn: Jacob, Jacob. Han sade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Och han sade: Jag är Gud, dins faders Gud, frukta dig icke at fara in i Egypten: Förty, der will jag göra dig til et mägtigt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Jag will fara dit med dig, och will åter föra dig derut. Och Joseph skall lägga sina hand uppå din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Då for Jacob ifrå BerSaba. Och Israels barn förde Jacob sin fader, med sin barn och hustrur, på wagnomen, som Pharao hade sändt til at föra dem med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Och togo sin boskap och håfwor, som de förwärfwat hade i Canaans lande, och kommo så in uti Egypten, Jacob och all hans säd med honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Hans barn och hans barnabarn med honom, hans döttrar, och hans barns döttrar, och all hans säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Desse äro Israels barns namn, de som kommo i Egypten: Jacob och hans söner. Jacobs förstfödde son Ruben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Rubens barn: Hanoch, Pallu, Hetsron och Charmi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeons barn: Jemuel, Jamin, Ohad, Jachin, Zohar, och Saul den Cananeeska qwinnones son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Levi barn: Gerson, Kehat och Merari.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Juda barn: Er, Onan, Sela, Perez och Serah. Men Er och Onan dödde i Canaans lande. Men Perez barn: Hezron och Hamul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isaschars barn: Thola, Phuva, Job och Simron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Sebulons barn: Sered, Elon och Jahleel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Desse äro barnen af Lea, som hon födde Jacob i Mesopotamien, med sine dotter Dina: De göra tilhopa alle, med söner och döttrar, tre och tretio själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gads barn: Ziphion, Haggi, Suni, Ezbon, Eri, Arodi och Areli.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Assers barn: Jimna, Jisua, Jisui, Brya; och Serah, deras syster. Men Bryas barn: Heber och Malchiel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Desse äro Silpas barn, som Laban gaf Lea sine dotter, och födde Jacob dessa sexton själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Rachels Jacobs hustrus barn: Joseph och BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Och Joseph wordo födde i Egypten, Manasse och Ephraim, som honom födde Asnath Potiphera dotter Prestens i On.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'BenJamins barn: Bela, Becher, Assberl, Gera, Naaman, Ehi, Ros, Muppim, Huppim och Ard.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Desse äro barnen af Rachel, som Jacob födde äro; alle tilhopa fjorton själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Dans barn: Husim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naphtali barn: Jahzeel, Guni, Jezer och Sillem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Desse äro Bilhas barn, som Laban hade gifwit sine dotter Rachel, och födde Jacob dessa sju själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alla själar som kommo med Jacob in i Egypten, som utgångne woro af hans länd, undantagande hans barnahustrur, äro alle tilsamman sex och sextio själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Och Josephs barn, som honom wordo födde i Egypten, woro twå själar: Så at alla Jacobs hus själar, som kommo in i Egypten, woro sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Och han sände Juda för sig til Joseph, at han skulle wisa honom wägen til Gosen; och de kommo in i landet Gosen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Då spände Joseph före sin wagn, och for ut emot Israel sin fader til Gosen. Och då han fick se honom, föll han om hans hals, och gret swårliga på hans hals.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Då sade Israel til Joseph: Nu will jag gerna dö, efter det jag hafwer sett ditt ansikte, at du ännu lefwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph sade til sina bröder och sin faders hus: Jag will fara up, och underwisa der Pharao, och säga til honom: Mine broder och mins faders hus är kommit til mig utaf Canaans land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Och äro herdar, ty det är sådana folk, som med boskap umgå plägar: Deras får och fä, och allt det de hafwa, hafwa de fört med sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Då nu Pharao warder eder kallandes, och säger: Hwad är edar handel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Så skolen I säga: Dine tjenare äro folk, som med boskap umgå ifrå wår barndom allt här til, både wi och wåre fäder, på det I må få bo i det landet Gosen: Förty alle herdar äro såsom en styggelse för de Egyptier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Då kom Joseph och förkunnade det Pharao, och sade: Min fader och mine bröder, deras får och fä, och hwad de hafwa, är kommet utu Canaans lande; och si, de äro i det landet Gosen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Och han tog fem fina bröder och stälte dem för Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Då sade Pharao til hans bröder: Hwad är edar handel? De swarade: Dine tjenare äro herdar, wi och wåre fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Och sade ytterligare til Pharao: Wi äre komne til at bor med eder i landena; ty dine tjenare hafwa ingen bet til deras boskap, så hårdt twingar den hårde tiden Canaans land: Så gör wäl, och låt dina tjenare bo i det landet Gosen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Pharao sade til Joseph: Det är din fader, och det äro dine bröder, de äro komne til dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egypti land står dig öpet; låt dem bo på bästa platsen i landena, at de må bo i det landet Gosen: Och om du wetst några män ibland dem, som dogse äro, så sätt dem öfver min boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph hade ock sin fader Jacob in, och stälte honom för Pharao: Och Jacob wälsignade Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Men Pharao frågade Jacob: Huru gammal äst du:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jacob sade: Mins eländes tid är hundrade och tretio år: Liten och onder är min eländes tid, och räcker intet til mina fäders eländes tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Och Jacob wälsignade Pharao, och gick ut ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Men Joseph skaffade sinom fader och sina bröder boning, och gaf dem en besittning i Egypti lande, på bästa platsen i landena, nemliga i det landet Rameses, såsom Pharao budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Och han försörjde sin fader och sina bröder, och hela sins faders hus, hwarjom och enom sin del bröd, allt ifrå de gamla intil de unga barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Men i all land war intet bröd: Ty at den dyre tiden war ganska swår, så at Egypten och Canaans land swolto för den dyra tidens skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Och Joseph samkade alla de penningar tilhopa, som funnos i Egypten och Canaan, för mälning, som de köpte: Och han lät alla penningarna komma i Pharaos hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Då nu penningarne fattades i Egypti land och Canaan, kommo alle Egyptier til Joseph, och sade: Skaffa oss bröd; hwi låter du oss dö för dig, derföre at wi hafwe inga penningar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sade: Skaffer hit edar boskap, så will jag gifwa eder för boskapen, medan I ären utan penningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Då hade de deras boskap til Joseph, och han gaf dem bröd för deras hästar, får, fä och åsnar: Så födde han dem det året med bröd för all deras boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Då året war omlidit, kommo de til honom: Wi wilje icke döljat för wår herra, at icke allena penningarne, utan ock all wår boskap är borto när wår herra, utan allena wår kropp och åker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Hwi låter du både oss och wår åker dö? Tag oss til dig, och wårt land, för bröd, at wi och wårt land måge wara Pharaos egne: Gif oss säd, at wi må lefwa och icke åkren icke förlägges.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Så tog Joseph hela Egypti land in til Pharao: Ty de Egyptier sålde hwar sin åker; ty den hårde tiden war allt för stark öfwer dem. Och wardt så landet Pharaos eget,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Med folket, som i hans städer ut och ingick, ifrå den ena ändan i Egypten intil den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Undantagen Presternas åker, den tog han icke in: Ty det war förskickadt af Pharao til Presterna, at de äta skulle det dem benämndt war, det han dem gaf; derföre behöfde de icke sälja sina åkrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Då sade Joseph til folket: Si, jag hafwer i dag intagit eder och edar åker til Pharao: Si, der hafwen I säd, och sår åkren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Och af wäxtenom skolen I gifwa Pharao den femte delen; fyra delar skola wara edre til at så åkren med til edor spisning, och til edor hus och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'De sade: Allenast låt oss lefwa, och finna nåd för dig wårom herra, wi wilje gerna wara Pharaos egne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Så gjorde Joseph dem en lag allt intil denna dag, öfwer de Egyptiers åker, til at gifwa Pharao den femte delen, undantagnom Prestaåkrenom, den wardt icke Pharaos egen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Så bodde Israel i Egypten, i det landet Gosen, och hadet inne, och wäxte til, och förökades swårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Och Jacob lefde sjutton år i Egypti land, så att hans hela ålder wardt hundrade och sju och fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Då nu tiden kom, at Israel dö skulle, kallade han sin son Joseph, och sade til honom: Hafwer jag funnit nåd för dig, så lägg dina hand under mina länd, at du gör barmhertighet och trohet med mig, och begrafwer mig icke uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Utan jag will ligga när mina fäder, och du skalt föra mig ut af Egypten, och begraf mig i deras grifter. Han sade: Jag will göra som du hafwer sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Och han sade: Så swär mig. Och han swor honom. Då böjde Israel sig intil sängenes hufwudgärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Derefter wardt Joseph sagdt: Si, din fader är sjuk. Och han tog båda sina söner med sig, Manasse och Ephraim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Då wardt Jacob sagdt: Si, din son Joseph kommer til dig. Och Israel tog styrko til sig, och satte sig up i sängene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Och sade til Joseph: Den alsmägtige Gud syntes mig i Lus i Canaans land, och wälsignade mig,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Och sade til mig: Si, jag skall låta dig wäxa och förökas, och göra dig til mycket folk, och skall gifwa dine säd efter dig detta landet til egendom ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Så skola nu dine twå söner, Ephraim och Manasse, som dig i Egypten födde äro, förra än jag kom hit in til dig, wara mine, lika som Ruben och Simeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Men de, som du föder efter dem, skola wara dine: men desse skola wara nämnde med deras bröders namn i deras arfwedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Och då jag kom utaf Mesopotamien, dödde mig Rachel i Canaans lande på wägenom, då ännu et litet stycke wägs war til Ephrath; Och jag begrof henne på wägenom til Ephrath, det nu heter BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Och Israel såg Josephs söner, och sade: Ho äro desse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph swarade sinom fader: Det äro mine söner, som Gud hafwer mig här gifwit. Han sade: Haf dem hit til mig, att jag wälsignar dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Ty Israels ögon woro mörk worden för ålders skull, och kunde icke wäl se. Och han hade dem til honom: Och han kyste dem, och tog dem i famn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Och sade til Joseph: Si, jag hafwer sett ditt ansikte, det jag icke förmodat hade: Och si, Gud hafwer ock låtit mig se dina säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Och Joseph tog dem utaf hans sköte, och han böjde sig ned på jordena för hans ansikte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Då tog Joseph dem båda, Ephraim i sin högra hand, emot Israels wänstra hand, och Manasse i sina wänstra hand, emot Israels högra hand, och dem til honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Men Israel räckte ut sina högra hand, och lade henne på Ephraims dens yngstes hufwud, och sina wänstra hand på Manasses hufwud, och omskifte händerna med wilja; ty Manasse war den förstfödde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Och han wälsignade Joseph, och sade: Gud, för hwilkom mine fäder Abraham och Isaac wandrat hafwa; Gud, som mig födt hafwer utaf min ungdom allt intil denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Ängelen, som mig frälst hafwer af allo ondo, han wälsigne dessa piltarna, at de må efter mitt, och mina fäders, Abrahams och Isaacs, namn nämnde warda, så at de må wäxa och förökas på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Men då Joseph såg, at hans fader lade sina högra hand på Ephraims hufwud, behagade det honom illa, och fattade uti sins faders hand, at han skulle wända sina hand af Ephraims hufwud in på Manasses hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Och sade til honom: Icke så, min fader; denne är den förstfödde, lägg dina högra hand på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Men hans fader nekade det, och sade: Jag wet wäl, min son, jag wet det wäl; denne skall ock warda til folk, och skall warda stor, men hans yngre broder skall warda större än han, och hans säd skall warda til et stort folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Så wälsignade han dem i den dagen och sade: Warde Israel wälsignad efter ditt sätt, så at man må säga: Gud sätte dig såsom Ephraim och Manasse: Och så satte han Ephraim för Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Och Israel sade til Joseph: Si, jag dör, och Gud skall wara med eder, och skall föra eder åter i edra fäders land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Jag hafwer gifwit dig et stycke land utan dina bröder, som jag med mitt swärd och boga utaf de Amoreers hand tagit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Och Jacob kallade sina söner, och sade: Församler eder, at jag må förkunna eder, hwad eder skall hända i den yttersta tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommer tilhopa, och hörer til, I Jacobs barn; hörer edar fader Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben min förste son, du äst min kraft, och min första magt, den öfwerste i offret, och den öfwerste i riket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Han utlöper med hast som watn: Du skalt icke wara den öfwerste; ty du hafwer upstigit i dins faders lägre, och der hafwer du med det upstigandet besmittat mina säng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'De bröder Simeon och Levi, de hafwa handlat orättfärdiga med deras mordwapn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Min själ komme icke i deras råd, och min härlighet ware icke i deras förbund: Förty uti deras wrede hafwa de dödat mannen, och uti deras öfwerdådighet hafwa de förderfwat oxan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Förbannad ware deras wrede, at hon så styf är, och deras grymhet, at hon så hård är: Jag skall skingra dem i Jacob, och förströ dem i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, du äret, dig skola dine bröder lofwa, din hand skall wara dina fiender på halsen; för dig skola dins faders barn buga sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda är et ungt lejon, du äst högt kommen, min son, genom stor seger: Han hafwer nederböjt sig, och lägrat sig som et lejon, och som en lejinna. Ho törs sätta sig up emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Spiran skall icke warda tagen ifrån Juda, ej heller en mästare ifrå hans fötter, till dess Hjelten kommer; och honom skola folken tilfalla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Han warder bindandes sin fåla wid winträt, och sine åsninnos son wid den ädla winqwisten. Han skall twå sin kläder i win, och sin mantel i winbärs blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Hans ögon äro rödaktigare än win, och hans tänder äro hwitare än mjölk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon skall bo wid hafshamnena, och wid skepphamnena, och sträcka sig intil Sidon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaschar skall wara en benåsne, och lägra sig emellan gränsorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Och han såg rolighetena, at hon är god, och landet, at det är lustigt, och böjde sina härdar til at bära, och är worden en skattskyldig tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan skall warda en domare ibland sitt folk, såsom et annat slägte i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan skall warda en orm på wägenom, och en huggorm på stigenom, och bita hästen i foten, at den derpå rider, skall til rygga falla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'HERre, jag wäntar efter dina helso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gud, wäpnad, skall föra hären, och åter igen föran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Af Asser kommer hans feta bröd, och han skall gifwa Konungenom kräselig mat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali är en snar hjort, och gifwer kosteligit tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph skall tilwäx; han skall tilwäxa likawist som wid en källo: Döttrarna träda fram uti regementet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Och ändock skyttarne woro honom förbittrade, trätte med honom, och hatade honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Så är dock hans boge blifwen fast, och hans händers armar äro förmannade, genom dess mägtiges händer i Jacob: Af honom äro komne herdar, stenar i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Ifrå dins faders Gud är dig kommen hjelp, och af den Allsmägtiga äst du wälsignad med wälsignelse ofwan efter af himlenom; med wälsignelse af djupet, som under ligger; med wälsignelse på bröst och qwed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Den wälsignelse, som dinom fader och minom föräldrom lofwad är, går mägteliga efter deras önskan, som höge äro i werldene. Utaf Joseph skola hufwuden warda, och de öfwerste Nazareer ibland sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'BenJamin är en glupande ulf: Om morgonen skall han äta rof, men om aftonen skall han utskifta rofwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Desse alle äro de tolf Israels slägter, och det är det, som deras fader hafwer talat med dem, då han wälsignade dem, hwar med sin besynnerliga wälsignelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Och han böd dem, och sade til dem: Jag skall samkas til mitt folk; begrafwer mig när mina fäder, i den kulone på Ephrons Hetheens åker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'I den dubbelkulone, som ligger emot Mamre i Canaans lande, hwilka Abraham köpte til en arfgrift med åkrenom af Ephron den Hetheen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Der hafwa de begrafwit Abraham och Sara hans hustru: Der hafwa de ock begrafwit Isaac och Rebecka hans hustru: Der hafwer jag ock begrafwit Lea;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'I den åkrenom och de kulone, som af Heths barnom köpt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Och när Jacob hade lyktat buden til sin barn, lade han sina fötter samman på sängene, led af, och wardt samkad til sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Då föll Joseph in på sins faders ansikte, och gret, och kyste honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Och Joseph befallte sina tjenare läkarena, at de skulle smörja hans fader: Och läkarena smorde Israel');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Til dess fyratio dagar woro förgångne; ty så länge warade smörjedagarna. Och de Egyptier begreto honom i sjutio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Då nu sörjodagarne ute woro, talade Joseph med Pharaos gårdsfolk, och sade: Hafwer jag funnit nåd för eder, så taler med Pharao, och säger:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Min fader hafwer tagit en ed af mig, och sagt: Si, jag dör; begraf mig i mine graf, som jag hafwer grafwit mig i Canaans lande. Så will jag nu fara up och begrafwa min fader, och komma igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Pharao sade: Far dit up, och begraf din fader, som du honom sworit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Så for Joseph up til at begrafwa sin fader: Oh med honom foro alle Pharaos tjenare, de äldste af hans folk, och alle de äldste i Egypti lande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Dertil allt Josephs folk, och hans bröder, och hans faders folk; allena deras barn, får och fä lefde de i det landet Gosen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Och foro desslikes up med honom wagnar och resenärer, och war en ganska stor skare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Då de nu kommo in på den planen Atad, som ligger in emot Jordan, då höllo de en ganska stor och bitter dödklagan; och han sörjde öfwer sin fader i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Och då folket i landet, de Cananeer, sågo det sörjandet på den planen Atad, sade de: De Egyptier sörja der fast. Deraf kallar man det rummet de Egyptiers sorg; hwilket ligger in emot Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Och hans barn gjorde som han dem befallt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Och förde honom i Canaans land, och begrofwo honom i den dubbelkulone af åkren, som Abraham med åkrenom köpt hade til arfgrift af Ephron Hetheen, twärt emot Mamre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Så for Joseph åter in i Egypten med sina bröder, och med allom dem, som woro farne up med honom til at begrafwa hans fader; när de hade begrafwit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Men Josephs bröder fruktade sig, då deras fader war död, och sade: Kanske, at Joseph är oss gramse, och måtte wedergälla oss det onda wi honom gjort hafwe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Derföre läto de säga honom: Din fader gaf befallning för sin död, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Så skolen I säga til Joseph: Käre, förlåt dina bröder deras missgerning och synd, at de så illa hafwa gjort emot dig. Käre, förlåt oss nu, som ärom dins faders Guds tjenare, denna missgerning. Men Joseph gret, då de sådant talade med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Och hans bröder gingo til, och föllo ned för honom, och sade: Si, wi äre dine tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph sade til dem: Frukter eder icke, ty jag är under Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'I tänkten ondt öfwer mig, men Gud hafwer wändt det til godo, at han gjorde som för ögon är, til at frälsa mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Så frukter eder nu intet, jag will försörja eder och edro barn. Och han stärkte dem, och talade wänliga med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Så bodde Joseph i Egypten med sins faders huse, och lefde hundrade och tio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Och såg Ephraims barn til tredje led: Föddes också barn på Josephs sköte, utaf Machirs barnom, hwilken Manasses son war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Och Joseph sade til sina bröder: Jag dör, och Gud warder eder sökandes, och förandes utaf detta landet, in uti det landet, som han hafwer sworit Abraham, Isaac och Jacob.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Derföre tog han en ed af Israels barnom, och sade: När Gud warder eder sökandes, så förer min ben hädan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Så dödde Joseph, då han war hundrade och tio år gammal. Och de smorde honom, och lade honom uti ena kisto i Egypten. Ände på den Första Boken Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Desse äro namnen af Israels barn, som kommo in uti Egypten med Jacob; hwar och en kom derin med sitt hus:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi, Juda,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaschar, Zebulon, BenJamin,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naphtali, Gad, Asser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Och alla de själar, som utaf Jacobs länd utgångna wore, wore sjutio. Men Joseph war tillförene uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Då nu Joseph död war, och alle hans bröder, och alle de som på den tiden lefwat hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Wäxte Israels barn, och födde barn, och förökades, och worde ganska månge, så att de uppfyllde landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Då wardt en ny Konung öfwer Egypten, hwilken intet wisste af Joseph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Han sade till sitt folk: Si, Israels barnas folk är mycket, och mera än wi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nu wäl, wi wilje listeliga förlägga dem, att de icke warda så månge. Ty om något örlig påkomme mot oss, måtte de ock gifwa sig till wåra fiendar, och strida emot oss, och draga utu landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Och han satte öfwer dem arbetsfogdar, som dem betwinga skulle med träldom; ty man byggde Pharao de städer Pithom och Raamses till skatthus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Men ju mer betungade folket, ju mer det förökades och förwidgade sig; derföre woro de Israels barnom hätske.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Och de Egyptier twingade Israels barn med obarmhertighet till att träla;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Och gjorde deras lefwerne bittert, med swårt arbete på ler och tegel, och med allahanda släpande på markene, och med allahanda arbete, som de kunde dem pålägga med obarmhertighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Och Konungen i Egypten sade till jordgummorna för de Ebreiska qwinnor; den ena het Siphra, och den andra Pua:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'När I hjelpen de Ebreiska qwinnor, och de skola föda; är det mankön, så dräper det; är det qwinnkön, så låter det lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Men jordgummorna fruktade Gud, och gjorde ej som Konungen i Egypten sade dem; utan läto barnen lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Då kallade Konungen i Egypten jordgummorna, och sade till dem: Hwarföre gören I det, att I låten lefwa barnen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Jordgummorna swarade Pharao: De Ebreiska qwinnor äro ej som de Egyptiska; förty de äro hårda qwinnor; förr än jordgumman kommer till dem, hafwa de födt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Därföre gjorde Gud wäl emot jordgummorna; och folket förökades och wardt ganska mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Och efter jordgummorna fruktade Gud, byggde han dem hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Då böd Pharao allo sino folke, och sade: Allt det mankön, som födt warder, kaster i älfwena, och allt qwinnkön låter lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Och en man gick bort af Levi hus, och tog ena Levi dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Och qwinnan aflade, och födde en son. Och då hon såg att det war ett dägeligit barn, fördolde hon det i tre månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Och då hon icke länger kunde fördölja det, tog hon ena kisto af rör, och beströk henne med ler och beck, och lade barnet deruti, och hof henne ut i wassen wid strandena af älfwene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Och hans syster stod långt ifrå, på det hon skulle se huru honom skulle warda gångandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Och Pharaos dotter kom ned, och skulle twå sig i älfwene, och hennes jungfrur gingo utmed bräddene af älfwene; och då fick se kistonna i wassenom, sände hon sina pigo dit, och lät hämta henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Och då hon upplyckte henne, fick hon se barnet, och si, barnet gret: Då ömkade hon sig deröfwer, och sade: Detta är ett af de Ebreiska barnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Då sade hans syster till Pharaos dotter; Will du, att jag går och kallar till dig ena Ebreiska qwinno, som dia gifwer, att hon ammar dig barnet upp?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Pharaos dotter sade till henne: Gack. Pigan gick, och kallade barnsens moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Då sade Pharaos dotter till henne: Tag detta barnet, och amma mig det upp, jag will löna dig. Qwinnan tog barnet, och ammade det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Och då barnet war stort wordet, antwardade hon det Pharaos dotter, och hon anammade honom för sin son, och kallade honom Mose, ty hon sade: Utu wattnet hafwer jag tagit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'På den tiden, när Mose war stor worden, gick han ut till sina bröder, och såg deras tunga; och wardt warse, att en Egyptisk man slog hans broder, en af de Ebreiska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Och han wände sig hit och dit, och då han såg, att der ingen menniska war, slog han den Egyptiska, och begrof honom uti sandenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'I den andra dagen gick han ock ut, och såg två Ebreiska män träta sinsemellan, och sade till den, som orätt gjorde: Hwi slår du din nästa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Han swarade: Ho hafwer gjort dig till höfwitsman eller domare öfwer oss? Will du ock slå mig ihjäl, såsom du hafwer slagit den Egyptiska mannen? Då fruktade Mose, och sade: Huru är detta uppkommet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Och det kom för Pharao, och han sökte efter att dräpa Mose. Men Mose flydde för Pharao, och blef i Midians lande, och bodde wid en brunn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Men Presten i Midian hade sju döttrar, de kommo till att winda watten, och de uppfyllde hoar till att wattna sins faders får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Då kommo någre herdar, och drefwo dem ifrå; men Mose gaf sig upp, och halp dem, och wattnadederas får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Och då de kommo till sin fader Reguel, sade han: Hwi kommen I i dag senare än I plägen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'De sade: En Egyptisk man halp oss för herdarna, och wand med oss watten, och wattnade fåren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Han sade till sina döttrar: Hwar är han? Hwi läten I så blifwa mannen, och icke båden honom komma och äta med oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Och Mose belefwade att blifwa när den mannenom: Och han gaf Mose sina dotter Zipora.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Hon födde honom en son, och han kallade honom Gerson, ty han sade: Jag är en utländning worden i främmande lande. Och hon födde ännu en son, den kallade han Elieser, och sade: Mins faders Gud är min hjelpare, och hafwer frälst mig utu Pharaos händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Någon tid derefter blef konungen i Egypten död. Och Israels barn suckade öfwer deras arbete, ochropade, och deras rop kom till Gud öfwer deras släpan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Och Gud hörde deras klagan, och tänkte på sitt förbund med Abraham, Isaac och Jacob.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Och han såg dertill, och lät sig wårda om dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Men Mose waktade sins swärs Jethro får, Prestens i Midian; och han dref fåren bak in i öknena, och kom till Guds berg Horeb.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Och HERrans Ängel syntes honom uti en brinnande låga utu buskanom. Och han såg, att busken brann af elden, och wardt dock icke förtärd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Och sade: Jag will gå dit, och bese denna stora synena, hwi busken icke uppbrinner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Då HERren såg, att han gick åstad till att se, kallade Gud honom utu buskanom, och sade: Mose, Mose. Han swarade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Han sade: Träd icke hit, drag dina skor af dina fötter; ty rummet, der du står uppå, är ett heligt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Och han sade ytterligare: Jag är dins faders Gud, Abrahams Gud, Isaacs Gud och Jacobs Gud. Och Mose skylde sitt ansigte; ty han fruktade se uppå Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Och HERren sade: Jag hafwer sett mins folks jämmer uti Egypten, och jag hafwer hört deras rop öfwer dem som drifwa dem: Jag hafwer förnummit deras wedermödo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Och är nederstigen till att frälsa dem utu de Egyptiers wåld; och föra dem utu det landet, in uti ett godt och widt land, som flytandes är med mjölk och hannog, såsom är på den platsen, som de Cananeer, Hetheer, Amoreer, Phereseer, Heveer och Jebuseer bo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Så efter nu Israels barnas rop är kommet före mig, och jag dertill hafwer skådat deras twång, der de Egyptier dem med betwinga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Så gack nu, jag will sända dig till Pharao, att du skall föra mitt folk Israels barn utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose sade till Gud: Ho är jag, att jag gå skulle till Pharao, och föra Israels barn utur Egypten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Han sade: Jag will wara med dig, och detta skall wara dig för ett tecken, att jag hafwer sändt dig: Då du hafwer fört mitt folk utur Egypten, skolen I offra Gudi på desso bergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mose sade till Gud: Si, när jag kommer till Israels barn, och säger till dem: Edra fäders Gud hafwer sändt mig till eder; och de säga till mig: Hwad är hans Namn? hwad skall jag säga dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Sade Gud till Mose: Jag skall wara den jag wara skall; och sade: Så skall du säga till Israels barn: Jag skall warat, han hafwer sändt mig till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Och Gud sade ytterligare till Mose: Så ifall du säga till Israels barn: HERren, edra fäders Gud, Abrahams Gud, Isaacs Gud och Jacobs Gud, hafwer sändt mig till eder: Detta Namnet är mig ewinnerliga; det skall wara min åminnelse ifrå barn till barnabarn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Derföre gack åstad, och församla de äldsta af Israel, och säg till dem: HERren, edra fäders Gud, hafwer synts mig, Abrahams Gud, Isaacs Gud och Jacobs Gud, och sagt: Jag hafwer sökt eder, och sett hwad eder wederfaret är uti Egypten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Och hafwer sagt: Jag skall föra eder utu den Egyptiska jämmeren in uti de Cananeers, Hetheers, Amoreers, Phereseers, Heveers och Jebuseers land, uti det land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Och då de höra dina röst, skall du och de äldste af Israel gå in till Konungen i Egypten, och säga till honom: HERren, de Ebreers Gud, hafwer kallat oss. Så låt oss nu gå tre dagsresor in uti öknena, till att offra HERranom wårom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Men jag vet, att Konungen i Egypten icke skall låta eder fara, utan genom stark under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Ty jag skall uträcka mina hand, och slå Egypten med allahanda under, som jag derinne göra skall; sedan skall han låta fara eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Och jag will gifwa desse folkena nåde för de Egyptier, att när I utfaren, skolen I icke utgå med tomma händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Utan hwar och en qwinna skall bedas af hennes grannqwinno och wärdinno silfwer och gyldene tyg och kläder: Dem skolen I lägga på edra söner och döttrar, och blotta de Egyptier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mose swarade, och sade: Si, de tro mig intet, ej heller höra mina röst, utan skola säga: HERren hafwer intet synts dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'HERren sade till honom: Hwad är det som du hafwer i dine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Han sade: En staf. Han sade: Kasta honom ifrå dig på markena. Och han kastade honom ifrå sig, och han wardt wänd uti en orm: Och Mose flydde för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Men HERren sade till honom: Räck dina hand ut, och tag honom om stjerten. Då räckte han sina hand ut, och höll honom, och han wändes uti en staf i hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Därföre skola de tro, att HERren hafwer synts dig, deras fäders Gud, Abrahams Gud, Isaacs Gud, och Jacobs Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Och HERren sade ytterligare till honom: Stick dina hand in i din barm. Och han stack henne i sin barm, och då han drog henne ut, si, då war hon spitelsk som en snö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Och han sade: Stick henne åter in i din barm. Och han stack henne åter in i barmen, och drog henne ut igen, si, så wardt hon åter som det andra hans kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Om de icke wilja tro dig, eller lyda hwad du säger af det ena tecknet, så warda de dock troende, när du säger dem af det andra tecknet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Om de icke tro dessa tu tecknen, icke heller höra dina röst, så tag wattnet utur älfwene, och gjut det ut på torra landet, så skall det samma wattnet, som du utur älfwene tagit hafwer, warda blod på torra landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Då sade Mose till HERran: Ack HERre! Jag är en sådan man som icke talande är, allt från i går och förrgår, och ifrå den tid du med din tjenare talat hafwer, ty jag hafwer ett tungt mål och ena swåra tungo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'HERren sade till honom: Ho hafwer skapat menniskone munnen? Eller ho hafwe gjort dumban, eller den döfwa, eller den seende, eller den blinda? Hafwer icke jag HERren gjort dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Så gack nu åstad, jag will wara i dinom mun, och lära dig, hwad du säga skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mose sade: Min HERre, sänd hwem du sända will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Då wardt HERren mycket wred öfwer Mose, och sade: Wet jag icke, att din broder Aaron af Levi slägte är talande? Och si, han skall utgå emot dig, och då han får se dig, skall han glädja sig af hjertat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Du skall tala till honom, och sätta orden i munnen på honom; och jag skall wara i dinom, och i hans munna, och lära eder, hwad I göra skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Och han skall tala för dig till folket; Han skall wara din mun, och du skall wara hans gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Och denna staf tag i dina hand, dermed du tecken göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Så gick då Mose dädan, och kom igen till sin swär Jethro, och sade till honom: Käre, låt mig gå, att jag åter må komma till mina bröder, som äro uti Egypten, och se, om de ännu lefwa. Jethro sade till honom: Gack i frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Och sade HERren till honom i Midian: Gack, och far åter in uti Egypten; förty de äro alle döde, som gingo efter ditt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Och så tog Mose sina hustru, och sina söner, och satte dem på en åsna, och for åter in uti Egypti land; och tog Guds staf i sina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Och HERren sade till Mose: Se till, när du åter kommer in uti Egypten, att du gör all de under för Pharao, som jag under dina hand gifwit hafwer. Men jag skall förstocka hans hjerta, att han icke skall släppa folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Och du skall säga till honom: Så säger HERren: Israel är min förstfödde son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Jag bjuder dig, att du låter min son fara, att han må tjena mig: Förwägrar du mig det, så skall jag dräpa din förstfödda son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Och wid han war på resone uti ett herberge, mötte honom HERren, och wille dräpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Då tog Zipora en sten, och skar sinom son förhudena af, och tog på hans fötter, och sade: Du äst mig en blodbrudgumme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Och så wände han igen af honom. Men hon sade blodbrudgumme, för omskärelsens skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Och HERren sade till Aaron: Gack ut emot Mose i öknena. Och han gick åstad, och mötte honom på Guds berge, och kysste honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Och Mose sade Aaron all HERrans ord, den honom sändt hade, och alla de tecken, som han honom befallt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Och de gingo åstad, och församlade alla de äldsta af Israels barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Och Aaron talade all de ord, som HERren med Mose talat hade, och gjorde tecknen för folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Och folket trodde. Och då de hörde, att HERren hade sökt Israels barn, och sett uppå deras jämmer, föllo de neder, och tillbåde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Derefter gingo Mose och Aaron in, och sade till Pharao: Så säger HERren, Israels Gud: Släpp mitt folk, att de må hålla mig högtid uti öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Pharao swarade: Ho är HERren, hwilkens röst jag höra skall, och släppa Israel? Jag wet intet af HERranom, och will ej heller släppa Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'De sade: De Ebreers Gud hafwer kallat oss: Så låt nu gå oss tre dagsresor in uti öknena, och offra HERranom wårom Gud, att oss icke öfwergå skall pestilentie eller swärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Då sade Konungen i Egypten till dem: Hwi gören I så, du Mose och Aaron, att detta folket öfwergifwer sitt arbete? Går bort till edart arbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Ytterligare sade Pharao: Si, folket är allaredo för mycket i landena; och I wiljen ännu låta dem hålla upp af arbetena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Derefter böd Pharao på samma dag fogdomen öfwer folket, och deras ämbetsmän, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'I skolen icke härefter hemta strå tillhopa, och få folkena till att bränna teglet, såsom tillförene: Låter dem sjelfwa gå bort och hemta sig strå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Och samma talet på teglet skolen I likwäl lägga dem uppå, såsom tillförne, och intet mindre; förty de gå fåfänge. Derföre ropa de, och säga: Wi wilje gå och offra wårom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Man må wäl förtunga dem med arbete, att de något hafwa till skaffa, och icke akta lögnaktigt tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Då gingo fogdarna öfwer folket och deras ämbetsmän ut, och sade till folket: Så säger Pharao: Man skall intet strå få eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Går själfwe bort och hemter eder strå, hwar I det finna kunnen; men af edart arbete skall intet afslås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Då förströdde sig folket kringom hela Egypti land, till att hemta sig stybbe, att de ju strå hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Och fordarna drefwo dem, och sade: Fyller upp edart dagsarbete, lika såsom I haden strå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Och de ämbetsmän af Israels barn, hwilka Pharaos fogdar öfwer dem satt hade, wordo slagne, och wardt sagdt till dem: Hwi hafwen I icke hwarken i dag eller i går fullkomnat edart förelagda dagsarbete, såsom tillförene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Då gingo de ämbetsmän af Israels barn in, och ropade till Pharao: Hwi far du så med dina tjenare?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Dinom tjenarom gifwes intet strå, och skola dock göra det tegel, som oss förelagdt är: Och si, dine tjenare warda slagne, och syndas uppå ditt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Pharao sade: I ären fåfänge, fåfänge ären I; därföre sägen I: Wi wiljom gå och offra HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Så går nu bort, och görer edor dagsarbete: Strå skall eder intet gifwas; men talet på teglet måsten I leverera från eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Då såge ämbetsmännerna af Israels barn, att det wardt intet bättre, efter sagdt wardt: I skolen intet förminska af dagsarbetena på teglet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Och då Mose och Aaron gingo ifrå Pharao, stodo de i wägenom före dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Och sade till dem: HERren se uppå eder, och döme det, att I hafwen gjort wår lukt illa luktandes för Pharao och hans tjenarom, och fått dem swärdet i händerna till att dräpa oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mose kom igen till HERran, och sade: HERre, hwi gör du så illa emot detta folket? Hwi hafwer du sändt mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Ty ifrå den tiden jag ingick till att tala med Pharao i ditt Namn, hafwer han ännu hårdare plågat folket; och du hafwer icke frälst ditt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'HERren sade till Mose: Nu skall du se hwad jag skall göra med Pharao; ty genom en wäldig hand måste han släppa dem: Han måste ännu genom en starka hand drifwa dem ifrå sig utu sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Och Gud talade till Mose, och sade till honom: Jag är HERren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Och hafwer synts Abraham, Isaac och Jacob, att jag will wara deras allsmägtige Gud; men mitt Namn HERRE gjorde jag dem icke kunnigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Och gjorde jag mitt förbund med dem, att jag skulle gifwa dem Canaans land; det land, der de uti wandrat hafwa, der de främmande uti warit hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Och hafwer jag hört Israels barnas suckan, hwilka de Egyptier med arbete förtunga; och hafwer ihågkommit mitt förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Därföre säg Israels barnom: Jag är HERren, och will taga eder utur edar tunga i Egypten, och förlossa eder ifrån edar träldom; och will frälsa eder med uträcktom arme och storom dom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Och will anamma eder för mitt folk, och will wara edar Gud; att I förnimma skolen, att jag är HERren edar Gud, den eder utfört hafwer utu de Egyptiers tunga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Och fört eder in uti det land, öfwer hwilket jag hafwer upphäfwit mina band, att jag skulle det gifwa Abraham, Isaac och Jacob; det will jag gifwa eder till eget: Jag HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Sådant allt sade Mose Israels barnom; men de hörde honom intet, för andans ångests skull, och för hårdt arbetes skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Då talade HERren med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gack in, och tala med Pharao, Konungenom i Egypten, att han släpper Israels barn ut af sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Men Mose talade för HERranom och sade: Si, Israels barn höra mig intet, huru skall då Pharao höra mig? Dertill hafwer jag oomskorna läppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Och så talade då HERren till Mose och Aaron, och gaf dem befallning till Israels barn, och till Pharao, Konungen i Egypten, att de skulle utföra Israels barn utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Desse äro hufwuden till deras fäders hus. Rubens, dens första Israels sons, barn äro desse: Hanoch, Pallu, Hezron, Charmi; det är Rubens slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeons barn äro desse: Jemuel, Jamin, Ohad, Jachin, Zoar och Saul, den Cananeiska qwinnones son; det är Simeons slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Desse äro Levi barnas namn i deras slägter: Gerson, Kehat, Merari. Men Levi wardt hundrade tretio och sju år gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersons barn äro desse: Libni och Simei, i deras slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehats barn äro desse: Amrar, Jizear, Hebron, Usiel. Men Kehat wardt hundrade tretio och tre år gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merari barn äro desse: Maheli och Musi. Det är nu Levi slägte i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Och Amram tog sina faders syster Jochebed till hustru; Den födde honom Aaron och Mose. Och wardt Amram hundrade tretio och sju år gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jizears barn äro desse: Korah, Nepheg, Sichri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Usiels barn äro desse: Misael, Elzaphan, Sithri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron tog sig hustru, Elizeba, Amminadabs dotter, Nahessons syster: Den födde honom Nadab, Abihu, Eleazar, Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korahs barn äro desse: Assir, Elkana, Abiassaph. Det äro nu de Korhiters slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Men Eleazar, Aarons son, tog sig hustru af Putiels döttrar: Den födde honom Pinehas. Desse äro nu hufwuden ibland fäderna till de Levitiska slägterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Desse äro Aaron och Mose, till hwilka HERren sade: Förer Israels barn utur Egypti land med deras härar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'De samme äro de, som talade med Pharao, Konungenom i Egypten, att de måtte utföra Israels barn utur Egypten, nämliga Mose och Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Och på den dagen talade HERren med Mose uti Egypti land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Och HERren sade: Jag är HERren; tala till Pharao, Konungen i Egypten, allt det jag talar med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Och han swarade för HERranom: Si, jag hafwer oomskorna läppar, huru skall Pharao höra mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'HERren sade till Mose: Si, jag hafwer satt dig till en gud öfwer Pharao; och Aaron din broder skall wara din Prophet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du skall tala allt det jag bjuder dig; men Aaron din broder skall tala det för Pharao, att han släpper Israels barn utu sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Men jag will förhärda Pharaos hjerta, på det jag skall göra min tecken och under många uti Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Och Pharao skall intet höra eder, på det jag skall bewisa mina hand uti Egypten; och föra min här, mitt folk Israels barn, utur Egypti land genom stora domar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Och de Egyptier skola förnimma, att jag är HERren, när jag nu uträcker mina hand öfwer Egypten, och utförer Israels bern ifrå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mose och Aaron gjorde såsom HERren hade budit dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Och Mose war åttatio år gammal, då de talade med Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Och HERren talade till Mose och Aaron:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'När Pharao säger till eder: Bewiser edor under; så skall du säga till Aaron: Tag din staf och kasta honom för Pharao, att han warder en orm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Då gingo Mose och Aaron in till Pharao, och gjorde såsom HERren hade budit dem: Och Aaron kastade sin staf för Pharao, och för hans tjenare, och han wardt en orm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Då lät Pharao kalla wisa och swartkonstiga: Och de Egyptiske trollkarlar gjorde ock sammalunda med deras beswärjningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Och hwardera kastade sin staf ifrå sig, och wordo ormar deraf; men Aarons staf uppslukte deras stafrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Så wardt Pharaos hjerta förstockat, och hörde dem intet, såsom HERren sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Och HERren sade till Mose: Pharaos hjerta är hårdt, och will icke släppa folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gack till Pharao bittida om morgonen, si, han warder utgångandes till älfwena: Så gack emot honom på strandena af älfwene, och tag stafwen i dina hand, den som en orm wardt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Och säg till honom: HERren, de Ebreers Gud, hafwer sändt mig till dig, och låter säga dig: Släpp mitt folk, att de må tjena mig uti öknene; men du hafwer härtilldags intet welat höra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Derföre säger HERren alltså: Deruppå skall du förnimma att jag är HERren: Si, jag will med den stafwen, som jag hafwer i mine hand, slå wattnet, som i älfwene är, och det skall wändas i blod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Så att fiskarna i älfwene skola dö, och älfwen lukta; och de Egyptier skola wämja, när de dricka af wattnet i älfwene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Och HERren sade till Mose: Säg till Aaron: Tag din staf, och räck ut dina hand ofwer wattnen i Egypten, öfwer deras älfwer, och strömmar, och sjöar, och öfwer all wattukärr, att de warda blod; och ware blod i hela Egypti land, både i träkar och i stenkar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose och Aaron gjorde, såsom HERren dem budit hade, och hof upp stafwen, och slog i wattnet, som i älfwene war, för Pharao och hans tjenare: Och allt wattnet i älfwene wardt wändt i blod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Och fiskarna i flodene dogo, och älfwen wardt luktandes, så att de Egyptier icke kunde dricka wattnet utur älfwene; och wardt blod i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Och de Egyptiske trollkarlar gjorde ock sammalunda med deras beswärjningar; men Pharaos hjerta wardt förstockadt, och han hörde dem intet, såsom HERren sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Och Pharao wände om, och gick hem, och lade det ännu intet på hjertat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Men alle Egyptier grofwo efter watten utmed elfwene till att dricka; ty wattnet af älfwene kunde de icke dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Och det warade i sju dagar långt, sedan HERren slog älfwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'HERren sade till Mose: Gack in till Pharao, och säg till honom: Detta säger HERren: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Hwar du icke will, si, så will jag plåga alla dina landsändar med paddor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Så att älwen skall uppwälla paddor: De skola uppstiga och komma in i din hus, in i din kammar, in i din lägre, in i din säng, och in i dina tjenares hus, ibland ditt folk, in uti dina bakugnar, och uti din deg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Och paddor skola stiga uppå dig, och uppå ditt folk, och uppå alla dina tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Och HERren sade till Mose: Säg till Aaron: Räck ut dina hand med din staf öfwer älfwer, och strömmar, och sjöar, och låt paddor komma öfwer Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Och Aaron räckte ut sina hand öfwer wattnen i Egypten; och paddor kommo derut, så att Egypti land wardt öfwertäckt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Då gjorde ock trollkarlarna sammalunda med deras beswärjningar; och läto komma paddor öfwer Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Då kallade Pharao Mose och Aaron, och sade: Beder HERran för mig att han tager paddorna ifrå mig, och ifrå mitt folk; så will jag släppa folket, att de måga offra HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mose sade: Haf du den ärona, och lägg mig före, när jag skall bedja för dig, för dina tjenare, och för ditt folk; att paddorna skola fördrefne warda ifrå dig, och ifrå ditt hus, och allenast blifwa i älfwene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Han sade: I morgon. Han sade: Såsom du sagt hafwer, på det du skall förnimma, att ingen är såsom HERren wår Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Så skola paddorna warda tagna ifrå dig, ifrå ditt hus, ifrå dina tjenare, ifrå ditt folk, och allena blifwa i älfwene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Så gingo Mose och Aaron ifrå Pharao. Och Mose ropade till HERran för paddornas skull, såsom han Pharao tillsagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Och HERren gjorde, som Mose sagt hade. Och paddorna blefwe döda i husen, i gårdarna, och på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Och de kastade dem tillsamman, här en hop, och der en hop, och marken luktade derutaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Då Pharao såg, att han hade sått rolighet, wardt hans hjerta förhärdardt, och hörde dem intet, såsom HERren sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Och HERren sade till Mose: Säg till Aaron: Räck ut din staf, och slå i stoftet på jordene, att löss warda i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'De gjorde ock så. Och Aaron räckte ut sina hand med sin staf, och slog i stoftet uppå jordene, och der wordo löss på menniskom, och på boskapen. Allt stoft på markene wardt löss i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Trollkarlarna gjorde ock sammalunda med deras beswärjningar, att de skulle göra löss, men de kunde icke. Och lössena woro på menniskom, och på boskapen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Då sade trollkarlarna till Pharao: Detta är Guds finger. Men Pharaos hjerta wardt förstockadt, och han hörde dem intet, såsom HERren sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Och HERren sade till Mose: Statt upp bittida om morgonen, och gack för Pharao: Si, han warder utgångandes till wattnet, och säg till honom: Detta säger HERren: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Hwar icke, si, så will jag låta komma allahanda ohyro öfwer dig, dina tjenare, ditt folk, och ditt hus, så att all de Egyptiers hus, och marken, och hwad deruppå är, skola warda full af ohyre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Och will jag på den dagen göra ett besynnerligit med den landsändan Gosen, der mitt folk uti är, att der skall ingen ohyra komma, på det du skall förnimma, att jag är HERren öfwer hela jordena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Och will en förlösning sätta emellan mitt folk och ditt. I morgon skall det tecknet ske.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Och HERren gjorde så. Och der kom mycken ohyra uti Pharaos hus, i hans tjenares hus, och öfwer hela Egypti land, och landet wardt förderfwadt af den ohyrene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Då kallade Pharao Mose och Aaron, och sade: Går åstad, och offrer edrom Gud här i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mose sade: Det betämmer sig icke, att wi så göre; förty wi offre HERranom wårom Gud de Egyptiers styggelse: Si, när vi nu de Egyptiers styggelse offrade för deras ögon, månde de icke skola stena oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Tre dagsresor wilje wi gå in uti öknena, och offra HERranom wårom Gud, såsom han oss sagt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Pharao sade: Jag will släppa eder, att I mån offra HERranom edrom Gud i öknene, allenast att I icke fjerran faren; och bedjen för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mose sade: Si, när jag härut ifrå dig kommer, så will jag bedja HERran, att denna ohyran må blifwa borttagen ifrå Pharao, och hans tjenare, och hans folk, i morgon: Allenast förhala mig icke länger, att du icke släpper folket till att offra HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Och Mose gick ut ifrå Pharao, och bad HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Och HERren gjorde, såsom Mose sagt hade, och tog de ohyrona bort ifrå Pharao, ifrå hans tjenare, och ifrå hans folke, så att icke en blef qwar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Men Pharao förhärdade sitt hjerta ännu i denna resone, och wille icke släppa folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'HERren sade till Mose: Gack in till Pharao, och säg till honom: Detta säger HERren de Ebreers Gud: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Hwar du icke will, utan förhåller dem länger;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Si, så skall HERrans hand warda utöfwer din boskap på markene; öfwer hästar, öfwer åsnar, öfwer camelar, öfwer oxar, öfwer får, med en ganska stor pestilentie.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Och HERren skall göra ett besynnerligit emellan de Israeliters boskap, och de Egyptiers; så att intet skall dö utaf allt det, som Israels barn hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Och HERren lade en tid före, och sade: I morgon skall HERren göra detta på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Och HERren gjorde så om morgonen, och allehanda boskap blef död för de Egyptier; men af Israels barnas boskap blef icke ett dödt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Och Pharao sände derefter, och si, der war icke ett blifwet dödt utaf Israels boskap. Men Pharaos hjerta wardt förstockadt, och släppte icke folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Då sade HERren till Mose och Aaron: Tager edra händer fulla med sot utaf skorstenen, och Mose stänke det upp åt himmelen för Pharao;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Att stoft skall komma öfwer hela Egypti land, och bölder och ond sår warda på menniskor, och på boskap i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Och de togo sotet utaf skorstenen, och stodo för Pharao, och Mose stänktet upp åt himmelen. Då worde bölder och ond sår på menniskom, och på boskapen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Så att trollkarlarna icke kunde stå för Mose, för de bölders skull; ty på trollkarlarna woro ock så wäl bölder, som på alla Egyptier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Men HERren förstockade Pharaos hjerta, så att han intet hörde dem, såsom HERren Mose sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Då sade HERren till Mose: Statt bittida upp om morgonen, och gack fram för Pharao, och säg till honom: Detta säger HERren de Ebreers Gud: Släpp mitt folk, att de måga tjena mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Annars will jag i denna resone sända alla mina plågor öfwer dig, öfwer dina tjenare, och öfwer ditt folk; att du skall förnimma, att i all land är ingen min like.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Förty nu will jag uträcka mina hand, och slå dig och ditt folk med pestilentie, att du skall förgås af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Och fördenskull hafwer jag uppwäckt dig, att min kraft skall synas på dig, och mitt Namn kunnigt warda i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Du förhåller ännu mitt folk, och will icke släppat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Si, jag will i morgon på denna tiden låta komma ett mägtigt stort hagel, hwilkets like icke warit hafwer i Egypten, ifrå den tid det funderadt wardt, intill nu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Så sänd nu bort, och förwara din boskap, och allt det du på markene hafwer; ty alla menniskor och boskap, som på markene funnen warder, och icke inhemtad är i husen, och haglet faller på dem, de blifwa döde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Den som nu ibland Pharaos tjenare fruktade HERrans ord, han låt sina tjenare och boskap fly in i husen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Men hwilkas hjerta intet aktade HERrans ord, de läto deras tjenare och boskap blifwa på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Då sade HERren till Mose: Räck dina hand upp åt himmelen, att det haglar öfwer hela Egypti land; öfwer menniskor, öfwer boskap, och öfwer all gröda på markene, i Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Så räckte Mose sin staf upp emot himmelen, och HERren lät dundra och hagla, så att elden flög på jordene. Alltså lät HERren komma hagel öfwer Egypti land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Att hagel och eld foro ibland hwartannat så grufweliga, att dess like icke warit hade i hela Egypti lande, ifrå den tid att det med folke besatt warde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Och haglet slog i hela Egypti lande allt det på markene war, både menniskor och boskap, och slog allan grödan på markene, och sönderslog all trä på markene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Utan allena i det landet Gosen, der Israels barn woro, der haglade intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Då sände Pharao bort, och lät kalla Mose och Aaron, och sade till dem: Jag hafwer i denna resone syndat: HERren är rättfärdig, men jag och mitt folk är ogudaktige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Därföre beder HERran, att Guds dunder och hagel återwänder, så will jag släppa eder, och icke länger förhålla eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose sade till honom: När jag kommer utu stadenom, will jag uträcka mina händer till HERran, så skall dundret återwända, och intet hagel mera wara; på det du skall förnimma, att jorden är HERrans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Dock wet jag wäl, att du och dine tjänare icke ännu frukten för HERran Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Så wardt då slaget linet och bjugget; ty bjugget war i ax gånget, och linet hade knoppat sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Men hwetet och rågen wardt icke slaget; förty det war sensäd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Så gick då Mose ifrå Pharao ut af stadenom, och räckte sina händer ut till HERran; och dundret och haglet wände igen, och regnet dröp intet mer på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Då nu Pharao såg, att regnet, och dundret, och haglet, wände igen, syndade han ändå ytterligare, och förhärdade sitt hjerta, han och hans tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Alltså wardt Pharaos hjerta förstockadt, att han icke släppte Israels barn, såsom HERren sagt hade genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Och HERren sade till Mose: Gack in till Pharao; ty jag hafwer förhärdat hans och hans tjenares hjerta, på det jag skall göra dessa min tecken ibland dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Och att du skall förkunna i din barnas öron, och din barnabarnas, hwad jag bedrifwit hafwer i Egypten; och huru jag hafwer bewisat min tecken ibland dem, att I skolen weta, att jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Så gingo Mose och Aaron in till Pharao, och sade till honom: Detta säger HERren de Ebreers Gud: Huru länge will du icke ödmjuka dig för mig, att du släpper mitt folk till att tjena mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Will du icke släppa mitt folk, si, så will jag i morgon låta komma gräshoppor i alla dina landsändar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Så att de skola öfwertäcka landet, så att man icke skall se landet, och de skola uppäta hwad eder qwart blifwet och undsatt är för haglena, och skola uppäta all eder grödande trä på markene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Och skola uppfylla all din hus, och alla dina tjenares hus, och alla Egyptiers hus, hwilkas like dine fäder, och fäders fäder icke sett hafwa, ifrå den tid de på jordena kommo, intill denna dag. Och han wände sig, och gick ut ifrå Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Då sade Pharaos tjenare till honom: Huru länge skole wi lida dessa plågor? Låt folket gå, att de måga tjena HERranom sinom Gud: Wetst du icke ännu, att Egypten är förderfwad?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Så wordo Mose och Aaron igen kallade till Pharao, och han sade till dem: Går åstad, och tjener HERranom edrom Gud. Hwilke äro nu de som gå skola?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose sade: Wi wilje gå med unga och gamla, med söner och döttrar, med får och fä; ty wi hafwe en HERrans högtid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Han sade till dem: Rätt så, HERren ware med eder. Skulle jag släppa eder och edor barn dertill? Ser der, om I icke hafwen något ondt för händer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Icke så, utan I män går åstad, och tjener HErranom; ty det samma hafwen I ock begärat. Och de drefwo dem ut ifrå Pharao.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Då sade HERren till Mose: Räck ut dina hand öfwer Egypti land om de gräshoppor, att de komma öfwer Egypti land, och äta allan grödan upp i landena, med allt det som qwart blifwet är efter haglet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mose räckte sin staf öfwer Egypti land, och HERren dref ett östanwäder i landet i den hela dagenom, och i den hela nattene. Och om morgonen förde det östanwädret gräshopporna fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Och de kommo öfwer hela Egypti land, och gåfwo sig ned allestäds i Egypten, så ganska många, att tillförene deras like intet warit hade, ej heller härefter warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Förty de öfwertäckte landet, och gjorde det swart. Och de åto upp allan grödan i landena, och all frukt på trän, som qwar war blifwen efter haglet, och läto intet grönt blifwa qwart på trän, och uppå grödan på markene i hela Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Då kallade Pharao hasteliga Mose och Aaron, och sade: Jag hafwer syndat emot HERran edar Gud, och emot eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Förlåter mig mina synder ännu i denna resone, och beder HERran edar Gud, att han dock borttager denna döden ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Och han gick ut ifrå Pharao, och bad HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Då wände HERren ett ganska starkt westanwäder, och upptog gräshopporna, och förde dem i röda hafwet; så att der icke blef en qwar någorstäds i hela Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Men HERren förstockade Pharaos hjerta, att han icke släppte Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'HERren sade till Mose: Räck dina hand upp åt himmelen, att det warder så mörkt i Egypti land, att man må taga uppå det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Och Mose räckte sina hand upp åt himmelen; då wardt ett tjockt mörker i hela Egypti lande i tre dagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Så att ingen såg den andra, ej heller uppstod af det rummet, der han war, i de tre dagar. Men när alla Israels barn war ljust, der de bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Då kallade Pharao Mose, och sade: Går åstad och tjener HERranom, allenast låter edor får och fä blifwa här; låter ock edor barn gå med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose sade: Du måste ock låta oß hafwa offer och bränneoffer, det wi HERranom wårom Gud göra skolom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Wår boskap skall gå med oß, och icke en klöf tillbakablifwa; förty af wåro skole wi taga HERranom wårom Gudi till tjenst; ty wi wete icke, hwarmed wi skole tjena HERranom tilldeß wi komme dit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Men HERren förstockade Pharaos hjerta, att han icke wille släppa dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Och Pharao sade till honom: Gack ifrå mig, och tag dig wara, att du icke mer kommer för min ögon; ty hwilken dag du för min ögon kommer, skall du dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose swarade: Såsom du sagt hafwer; jag will ej mer komma för din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Och HERren sade till Mose: Jag will ännu låta kommo ena plågo öfwer Pharao och Egypten, sedan skall han släppa eder hädan; och skall ej allenast släppa eder, utan ock drifwa eder hädan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Så säg nu till folket, att hwar och en man bedes af sin nästa, och hwar och en qwinna af sine nästo, silfwer och gyldene tyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Ty HERren warder gifwandes folkena nåd för de Egyptier. Och Mose war en ganska myndig man i Egypti land, för Pharaos tjenare och för folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Och Mose sade: Detta säger HERren: Jag will på midnattstid utgå i Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Och allt det förstfödt är i Egypti land skall blifwa dödt, ifrå Pharaos förstfödda son, den på hans stol sitter, allt intil tjensteqwinnones förstfödda son, som är wid qwarnena; och allt det förstfödt är ibland boskapen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Och ett stort rop skall wara i hela Egypti lande, hwilkets like icke warit hafwer, ej heller warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Men när Israels barnom skall icke en hund krätta med sine tungo, ifrå menniskom, allt intill boskapen; på det I skolen förnimma, huru HERren åtskiljer Egypten och Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Då skola alle deße dine tjenare gå ned till mig, och falla mig till fota, och säga: Far ut, du och allt folket, som under dig är. Sedan will jag fara ut. Och han gick ifrå Pharao ganska wreder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Men HERren sade till Mose: Pharao hörer eder intet, på det mycken under skola ske i Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Och Mose och Aaron gjorde all deßa under inför Pharao; men HERren förstockade honom hans hjerta, att han icke wille släppa Israels barn utu sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'HERren sade till Mose och Aaron i Egypti lande:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Denne månaden skall wara när eder den förste månaden; och af honom skolen I begynna månaderna om året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Taler till hela Israels menighet, och säger: På tionde dagen i denna månadenom tage hwar och en ett får, den en husfader är, ju ett får till huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Men der ett hus är för klent till ett får, så tage din nästa granna wid sitt hus efter själarnas tal, som nog kunde wara till att förtära fåret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Och det skall wara ett får, som ingen wank hafwer, en gummar och årsgammal. Af lambom eller kidom skolen I tagat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Och I skolen behållat intill fjortonde dagen i denna månadenom. Och hwar hopen i hela Israel skall slagtat till aftonen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Och skolen taga af deß blod och stryka på båda sidoträn åt dörrene, och öfra dörrträt i husen, der de äta det uti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Och skolen så äta köttet i den samma nattene, stekt wid eld, och osyradt bröd, och skolen ätat med bitter salso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'I skolen icke ätat rått, eller med wattne sudet; utan allena stekt wid eld, deß hufwud med deß fötter och inelfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Och I skolen intet låta qwart blifwa till morgonen: Om något blifwer qwart till morgonen, skolen I det uppbränna med elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Men så skolen I ätat: I skolen wara gjordade kringom edra länder, och hafwa edra skor på edra fötter, och stafrar i edra händer; och I skolen ätat, såsom de der hasta till wägs; ty det är HERrans Passah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Förty jag will i den samma nattene gå genom Egypti land, och slå allt det förstfödt är i Egypti lande, både af menniskor och boskap, och bewisa mitt straff på alla de Egyptiers gudar: Jag HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Och blodet skall wara eder ett tecken på husen, der I uti ären, att när jag ser blodet, skall jag gå framom eder; och eder icke wederfaras skall den plåga, som eder förderfwa må, när jag slår Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Och I skolen hafwa denna dagen till åminnelse; och I skolen hålla honom högtideligan HERranom till en fest; I och alle edra efterkommande i en ewig brukning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'I sju dagar skolen I äta osyradt bröd, nämliga på första dagenom skolen I upphålla med syradt bröd uti edor hus. Den som syradt bröd äter, ifrå första dagen, allt intill den sjunde, hans själ skall förgöras af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Den första dagen skall wara helig, att I sammankommen, och den sjunde skall ock wara helig, att I sammankommen: Intet arbete skolen I göra på dem, utan det som till maten hörer för allahanda själar, det allena mågen I göra för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Och håller eder wid osyradt bröd; förty på den samma dagen hafwer jag utfört edra härar utur Egypti land: Derföre skolen I, och alle edre efterkommande, hålla denna dagen i en ewig brukning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'På fjortonde dagen i första månadenom, om aftonen, skolen I äta osyradt bröd, intill en och tjugonde dagen i samma månadenom om aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Så att man i sju dagar intet syradt bröd finner i edor hus; ty den som syradt bröd äter, hans själ skall förgöras utur Israels menighet, ehwad han är utländsk eller inländsk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Derföre äter intet syradt bröd; utan allenast osyradt bröd uti alla edra boningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Och Mose kallade alla de äldsta i Israel, och sade till dem: Leter ut och tager får, hwar och en för sitt husfolk, och slagter Passah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Och tager ett knippe isop, och dopper i blodet i bäckenet, och stryker dermed på öfra dörrträt, och båda sidoträn; och ingen menniska gånge ut genom sins hus dörr intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Förty HERren warder gångandes der framom, och skall plåga de Egyptier. Och när han får se blodet på öfra dörrträt och på de tu sidoträn, går HERren framom dörrena, och icke låter förderwaren komma uti edor hus till att plågas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Derföre håll denna seden för dig och din barn till ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Och när I kommen in uti landet, det HERren eder gifwandes warder, såsom han sagt hafwer, så håller denna tjenstena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Och när edor barn säga till eder: Hwad hafwen I der för en tjenst?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Skolen I säga: Det är HERrans Passahoffer, den der gick framom Israels barn i Egypten, då han plågade de Egyptier, och frälste wår hus. Då bugade sig folket, och tillbad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Och Israels barn gingo bort, och gjorde, såsom HERren Mose och Aaron budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Och om midnattstid slog HERren allt det förstfödt war i Egypti lande, ifrå Pharaos förstfödda son, den på hans stol satt, allt intill dens förstfödda son, som fången satt i fängelset, och allt förstfödt af boskapenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Då stod Pharao upp, och alle hans tjenare på den nattene, och alle Egyptier, och ett stort rop wardt uti Egypten; ty der war intet hus, der icke en döder inne låg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Och han kallade Mose och Aaron om nattena, och sade: Görer eder reda, och farer ut ifrå mitt folk, I och Israels barn; går åstad, och tjener HERranom, såsom I sagt hafwen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tager ock med eder edor får och fä, såsom I sagt hafwen; går åstad, och wälsigner mig med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Och de Egyptier trängde fast uppå folket, att de måste med hast drifwa dem ut af landet; ty de sade: Wi dö hwar och en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Och folket bar råan deg, förra än han försyrad wardt, till deras mat, bundnan i deras kläder, på deras axlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Och Israels barn hade gjort, såsom Mose sagt hade; och hade bedts af de Egyptier silfwer, och gyldene tyg, och kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Och HERren hade gifwit folkena nåd för de Egyptier, så att de lånte dem; och de blottade de Egyptier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Så drogo Israels barn ut ifrå Rameses till Succoth, sexhundradetusend män till fot, förutan barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Och mycket gement folk drog också med dem; och får och fä, och ganska mycken boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Och de bakade af den råa degen, som de utur Egypten förde, osyrade kakor; ty han war icke syrad, efter de wordo utdrefne utur Egypten, och kunde icke förtöfwa, och hade eljest ingen kost beredt sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Tiden, i hwilkom Israels barn bodde i Egypten, är fyrahundrade och tretio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Då de förlidne woro, gick hela HERrans här på en dag utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Derföre warder denna natten hållen HERranom, att han hafwer fört dem utur Egypti land. Och Israels barn skola hålla henne HERranom, de och deras efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Och HERren sade till Mose och Aaron: Detta är sättet till att hålla Passah: Ingen främling skall äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Den som en köpter träl är, den skall man omskära, och sedan äte han deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'En husman, och en dagakarl, skola intet äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Uti eno huse skall man ätat. I skolen intet af deß kött bära ut för huset, och I skolen intet ben sönderslå af thy.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Hela menigheten i Israel skall så göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Om någon främling bor när dig, och will hålla HERranom Passah, han omskäre allt det mankön är, sedan gånge härtill, att han detta gör, och ware såsom en inländsker; ty ingen oomskoren skall äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Samma lagen ware dem inländska, och utländska, som bor ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Och all Israels barn gjorde såsom HERren hade budit Mose och Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Och så förde HERren på en dag Israels barn utur Egypti land, med deras härar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Helga mig allt förstfödt; det som allahanda moderlif öppnar när Israels barnom, både ibland menniskor och boskap; ty de äro min.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Då sade Mose till folket: Tänker uppå denna dagen, på hwilken I utgångne ären af Egypten, utu träldomens huse; att HERren hafwer eder hädan utfört med wäldiga hand; Derföre skall du icke äta surdeg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'I dag ären I utgångne i den månadenom Abib.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'När nu HERren låter komma dig in uti de Cananeers, Hetheers, Amoreers, Heveers och Jebuseers land, hwilket han dina fäder sworit hafwer, att han wille gifwa dig ett land, der mjölk och hannog uti flyter; så skall du denna tjenstena hålla i denna månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'I sju dagar skall du äta osyradt bröd, och på sjunde dagenom är HERrans högtid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Derföre skall du i sju dagar äta osyradt bröd; så att när dig ingen surdeg, ej heller syradt bröd skall finnas i alla dina landsändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Och du skall säga dinom son på den tiden: Sådant hålle wi fördenskull, att HERren så hafwer gjort med oß, då wi drogom utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Derföre skall dig wara ett tecken i dine hand, och en åminnelse för din ögon; på det att HERrans lag skall wara i dinom mun, att HERren hafwer utfört dig af Egypten med wäldiga hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Derföre håll denna seden i sinom tid årliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'När nu HERren hafwer låtit dig komma in uti de Cananeers land, såsom han dig och dina fäder sworit hafwer, och hafwer dig det gifwit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Så skall du afskilja HERanom allt det som öppnar moderlifwet, och förstfödt är ibland boskapen; det som mankön är skall höra HERranom till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Det förstfödda af åsnanom skall du lösa med ett får; om du icke löser det, så bryt halsen sönder på thy; men allt förstfödt af mennisko ibland din barn skall du lösa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Och när ditt barn frågar dig i dag eller i morgon: Hwad är detta? skall du säga thy: HERren hafwer fört oß med wäldiga hand utur Egypten, ifrå träldomens huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Ty då Pharao war trög till att släppa oß, slog HERren allt det förstfödt war i Egypti lande, ifrå menniskones förstfödda, intill boskapens förstfödda: Derföre offrar jag HERranom allt det, som moderlifwet öppnar, det mankön är; och det som förstfödt är af min barn löser jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Och det skall wara dig för ett tecken i dine hand, och en åminnelse för din ögon, att HERren hafwer fört oß med wäldiga hand utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Då nu Pharao hade släppt folket, förde icke Gud dem på den wägen genom de Philisteers land, den genast war; ty han tänkte att folket måtte ångra sig, när de sågo örlig emot sig, och så omwända igen till Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Derföre förde han folket omkring på den wägen genom öknena åt röda hafwet; och Israels barn foro wäpnade utur Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Och Mose tog med sig Josephs ben; ty han hade tagit en ed af Israels barnom, och sagt: Gud warder eder sökandes, så förer min ben hädan med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Så drogo de ut ifrå Succoth, och slogo deras lägre i Etam, närmast wid öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Och HERren gick före dem om dagen uti en molnstod, på det han skulle föra dem den rätta wägen; och om nattena uti en eldstod, på det han skulle lysa dem; till att wandra både dag och natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Den molnstoden och eldstoden skiljdes intet ifrå folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Tala med Israels barn, och säg att de wända om, och slå deras lägre twärtemot den dalen Hyroth, emellan Migdol och hafwet, emot BaalZephon, och der twärtöfwer slå lägret wid hafwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Förty Pharao warder sägandes om Israels barn: De fara wille i landena; öknen hafwer beslutit dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Och jag will förstocka hans hjerta, att han skall jaga efter dem, och will winna pris på Pharao och alla hans magt; och de Egyptier skola förnimma, att jag är HERren. Och de gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Och då det wardt sagdt för Konungenom i Egypten, att folket flydde, wardt hans och hans tjenares hjerta förwandladt emot folket, och sade: Hwi hafwom wi så gjort, att wi hafwom släppt Israel, att de icke skola tjena oß?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Och han gjorde redo sin wagn, och tog sitt folk med sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Och tog sexhundrade utwalda wagnar, och hwad der eljest war för wagnar i Egypten, och höfwitsmän öfwer allan sin här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Ty HERren förstockade Pharaos hjerta, Konungens i Egypten, att han jagade efter Israels barn, hwilke dock woro genom höga hand utgångne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Och de Egyptier jagade efter dem, och hinde dem der de sig lägrat hade wid hafwet, med hästar och wagnar och resenärer, och med all Pharaos här, uti den dalenom Hyroth, twärtemot BaalZephon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Och då Pharao nalkades dem, hofwo Israels barn sin ögon upp, och si, de Egyptier kommo efter dem; och de fruktade sig storliga, och ropade till HERran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Och sade till Mose: Woro icke grafwer i Egypten, att du måste bortföra os, att wi skulle dö i öknene? Hwi hafwer du så gjort oß, att du hafwer fört oß utur Egypten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Är icke nu detta det, som wi sade dig i Egypten: Låt blifwa oß, att wi må tjena de Egyptier? Ty det woro oß ju bättre tjena de Egyptier, än dö i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose sade till folket: Frukter eder intet, står och ser till, hwilken en salighet HERren warder görandes i dag med eder; ty deßa Egyptier som I sen i dag, dem skolen I aldrig mera se i ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'HERren warder stridandes för eder, och I skolen stå stilla dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'HERren sade till Mose: Hwad ropar du till mig? Säg Israels barnom, att de draga fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Men du häf din staf upp, och räck dina hand öfwer hafwet, och skilj det åt, att Israels barn måga gå der midt igenom på det torra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Si, jag will förstocka de Egyptiers hjerta, att de skola följa efter eder: Så will jag winna pris på Pharao, och alla hans magt, uppå hans wagnar och resenärer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Och de Egyptier skola förnimma, att jag är HERren; när jag hafwer pris wunnit på Pharao och hans wagnar och resenärer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Då upphof sig Guds Ängel, den som för Israels lägre gick och gaf sig bakom dem: Och molnstoden gaf sig ock utu deras ansigte, och gick bakom dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Och kom emellan de Egyptiers och Israels lägre; och det war ett mörkt moln, och upplyste nattena, så att deße och hine i den hela nattene icke kunde komma tillsamman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Då nu Mose räckte sin hand öfwer hafwet, lät HERren drifwa det bort genom ett starkt östanwäder i den hela nattene, och gjorde hafwet torrt; och wattnet skiljdes åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Och Israels barn gingo derin, midt i hafwet på det torra; och wattnet war dem för en mur på den högra sidone, och den wenstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Och de Egyptier följde, och gingo in efter dem, alle Pharaos hästar och wagnar och resenärer, midt in i hafet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Som nu morgonwäkten kom, såg HERren uppå de Egyptiers lägre utur eldstodene och molnena; och gjorde en förskräckelse i deras lägre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Och stötte hjulen ifrå deras wagnar, och störte dem wäldeliga omkull. Då sade de Egyptier: Låt oß fly ifrån Israel; HERren strider för dem emot de Egyptier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Men HERren sade till Mose: Räck ut dina hand öfwer hafwet, att wattnet igenfaller öfwer de Egyptier; öfwer deras wagnar och resenärer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Då räckte Mose sina hand ut öfwer hafwet, och hafwet kom åter för morgonen i sin ström igen; och då de Egyptier flydde, mötte dem wattnet: Och HERren inhwärfde dem midt i hafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Så att wattnet kom igen, och gick utöfwer wagnar och resenärer, och alla Pharaos magt, som dem efterföljt hade in i hafwet; så att icke en af dem blef igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Men Israels barn gingo torre midt igenom hafwet; och wattnet war dem för en mur på högra sidone, och den wenstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Och så halp HERren Israel på den dagenom ifrå de Egyptiers hand: Och de sågo de Egyptier döda på hafstrandene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Och den stora hand, som HERren hade bewisat på de Egyptier. Och folket fruktade HERran, och trodde HERranom och hans tjenare Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Då sjöng Mose och Israels barn HERranom denna wisona, och sade: Jag will sjunga HERranom; ty han hafwer ena härliga gerning gjort, häst och man hafwer han stört i hafwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'HERren är min starkhet och lofsång, och är min salighet; han är min Gud, jag will ära honom; han är mins faders Gud, och jag will upphöja honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'HERren är den rätte krigsmannen: HERre är hans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Pharaos wagnar och hans magt kastade han i hafwet; hans utkorade höfwitsmän äro fördränkte i röda hafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Djupet hafwer öfwertäckt dem; och de föllo åt bottnen såsom stenar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'HERre, din högra hand gör stor under: HERre, din högra hand hafwer slagit fiendan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Och med dine stora härlighet hafwer du förstört dina motståndare; ty när du lät utgå dina grymhet, förtärde hon dem såsom strå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Genom ditt blåsande gåfwo sig wattnet upp, flytande wattnet stod ihop; djupen swallade ifrå hwartannat midt i hafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Fienden sade: Jag will jaga efter dem, och gripa dem, och byta rof, och fläcka mitt mod på dem; jag will draga ut mitt swärd, och min hand skall förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Då blåste ditt wäder, och hafwet öfwertäckte dem; och de sönko ned såsom bly uti mägtig watten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'HERre, ho är din like ibland gudarna? Ho är dig lik, som är så härlig och helig, förfärlig, prislig och undergörandes?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Då du utsträckte dina hand, upswalg dem jorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du hafwer i barmhertighet warit ledsagar åt dino folke, det du förloßat hafwer; och hafwer fört dem uti dine starkhet till dina helga boning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Då folken det hörde, bäfwade de; på de Philisteer som ångest;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Då förfärades de Förstar i Edom, bäfwan kom öfwer de mägtiga i Moab; alle Canaans inbyggarr gåfwo sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Låt kalla förskräckelse öfwer dem, och fruktan, genom din stora arm, att de blifwa orörlige såsom stenar; tilldeß, HERre, ditt folk kommer igenom; tilldeß ditt folk igenomkommer, det du förswärat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Led dem in, och plantera de på dins arwedels berge, hwilket du, HERre, till dina boning gjort hafwer; till din helgedom, HERre, det din hand beredt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'HERren warder rådandes i ewighet och utan ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Ty Pharao for in i hafwet med hästar och wagnar och resenärer, och HERren lät hafwet igenkalla öfwer dem; men Israels barn gingo torre midt igenom hafwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Och MirJam den Prophetißan, Aarons syster, tog ena trummo uti sina hand; och alla qwinnor följde henne efter i dans med trummor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Och MirJam söng före dem: Låt oß sjunga HERranom, han hafwer gjort ena härliga gerning; man och häst hafwer han stört i hafwet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Så lät Mose Israels barn draga ifrå röda hafwet, ut åt den öknen Sur: Och de wandrade tre dagar i öknene, och funno intet watten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Då kommo de till Mara; men de kunde icke dricka det wattnet i Mara; ty det war mycket bittert; af hwilko det rummet heter Mara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Der knorrade folket emot Mose, och sade: Hwad skole wi dricka?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Han ropade till HERran: och HERren wiste honom ett trä, det satte han i wattnet, och så wardt det sött. Der satte han dem före lag och rätt, och försökte dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Och han sade: Will du höra HERrans dins Guds röst, och göra hwad som rätt är för honom, och fatta hans bud i din öron, och hålla alla hans lag; så skall jag ingen den krankhet lägga uppå dig, som jag på de Egyptier lagt hafwer; ty jag är HERren din läkare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Och de kommo till Elim, der woro tolf wattubrunnar, och sjutio palmträ; der lägrade sig sig wid wattnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Från Elim drogo de, och som hela hopen Israels barn uti den öknena Sin, hwilken ligger emellan Elim och Sinai, på femtonde dagen i den andra månadenom, sedan de utur Egypti land gångne woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Och hela menigheten af Israels barn knorrade emot Mose och Aaron uti öknene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Och sade till dem: Gud gifwe, att wi hade dött uti Egypti lande genom HERrans hand, der wi såto wid köttgrytorna, och hade bröd nog till att äta; ty I hafwen fördenskull fört oß i denna öknena, att I skolen låta denna hela hopen dö af hunger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Då sade HERren till Mose: Si, jag will låta regna eder bröd neder af himmelen; och folket skall gå ut och församla hwar dag så mycket som behöfwes, på det att jag må försöka, om de wilja wandra uti min lag eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'På sjette dagenom skola de bereda sig till att församla dubbelt, öfwer det de dageliga pläga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mose och Aaron sade till Israels barn: Om aftonen skolen I förnimma, att HERren hafwer fört eder utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Och om morgonen skolen I få se HERrans härlighet; ty han hafwer hört edor knorran emot HERran. Hwad äre wi, att I knorren emot oß?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Ytterligare sade Mose: HERren warder eder gifwandes om aftonen sött till att äta, och om morgonen bröd tillfyllest; derföre att HERren hafwer hört edor knorran, der I emot honom knorrat hafwen. Ty hwad äre wi? Edart knorrande är icke emot oß, utan emot HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Och Mose sade till Aaron: Säg till hela menigheten af Israels barn: Går hitfram till HERran; ty han hafwer hört edor knorran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Och då Aaron så sagt hade till hela menigheten af Israels barn, wände de sig emot öknena: Och si, HERrans härlighet syntes uti en sky.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Och HERren sade till Mose:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Jag hafwer hört att Israels barnas knorran; säg dem: Om aftonen skolen I hafwa sött till att äta, och om morgonen warda mättade af bröd; och skolen förnimma, att jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Och om aftonen kommo åkerhöns upp, och öfwertäckte lägret: Och om morgonen låg dagg omkring lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Och som daggen fallen war, si, då låg der något i öknene rundt och smått, såsom rimfrost på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Och då Israels barn sågo det, sade de till hwarannan: Detta är Man; ty de wißte icke hwad det war. Men Mose sade till dem: Det är det brödet, som HERren eder gifwit hafwer till att äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Det är det samma, om hwilket HERren budit hafwer: Hwar och en församle deraf så mycket han äter för sig; och tage ett gomer till hwart och ett hufwud, efter själarnas tal i deras tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Och Israels barn gjorde så, och församlade, den ene mycket, den andre litet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Men då man mätte det ut med gomer, wardt dem, som mycket hade, intet öfwerlöpte, och dem som litet hade, fattades intet; utan hwar och en hade församlat så mycket, som han åt för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Och Mose sade till dem: Ingen låte något qwart blifwa deraf till morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Men de hörde Mosen intet, utan somlige läto något qwart blifwa deraf intill morgonen; då wäxte der maskar uti, och wardt luktande: Och Mose blef wred uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Så församlade de deraf hwar morgon så mycket, som hwar och en förmådde äta för sig; men när solen wardt het, så försmälte det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Och på sjette dagenom församlade de dubbelt af det brödet, ju tu gomer för en. Och alle de öfwerste för menighetene kommo in, och förkunnade det Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Och han sade till dem: Detta är det som HERren sagt hafwer: I morgon är Sabbath, den helga hwilan HERranom: Hwad I baka wiljen, det baker, och hwad I koka wiljen, det koker; men hwad öfwer är, det låter blifwa, att det warder förwaradt intill morgons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Och de läto blifwat till morgonen, såsom Mose budit hade; då wardt det intet luktande, och ingen mask wardt derutinnan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Då sade Mose: Äter det i dag; ty i dag är HERrans Sabbath; I warden i dag intet finnande på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'I sex dagar skolen I församlat; men sjunde dagen är Sabbath, på honom wardet det intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Men på sjunde dagenom gingo somlige ut af folket till att församla, och funno intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Då sade HERren till Mose: Huru länge wiljen I icke hålla min bud och lag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Si, HERren hafwer gifwit eder Sabbath, och derföre hafwer han gifwit eder på sjette dagenom tweggedaga bröd: Så blifwe nu hwar och en hemma, och ingen gånge ut ifrå sitt rum på sjunde dagenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Så skonade då folket den sjunde dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Och Israels hus kallade det Man: Och det war såsom corianderfrö och hwitt, och hade en smak såsom semla med hannog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Och Mose sade: Detta är det som HERren budit hafwer: Uppfyll ett gomer deraf, till att förwara för edra efterkommande; på det man må se det bröd, der jag eder med spisat hafwer i öknene, då jag förde eder utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Och Mose sade till Aaron: Tag ett käril och låt derin ett gomer fullt med Man; och förwara det inför HERranom till edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Såsom HERren hade budit Mose, så lät Aaron förwara det der inför wittnesbördet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Och Israels barn åto Man i fyratio år, intilldeß de kommo til det land, der de bo skulle: Allt intill gränsona på Canaans land åto de Man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Och är gomer tiondeparten af ett epha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Och hela menigheten af Israels barn drog ut af den öknene Sin deras dagsresor, såsom HERren befallde dem; och lägrade sig i Rephidim; der hade folket intet watten till att dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Och de kifwade med Mose, och sade: Gifwer oß watten, att wi må dricka. Mose sade till dem: Hwi kifwen I med mig? Hwi försöken I HERran?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Då nu folket dersammastäds törste efter watten, knorrade de emot Mose, och sade: Hwi hafwer du låtit oß fara utur Egypten, på det att du oß, wår barn och boskap, skulle låta dör i törst?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mose ropade till HERran, och sade: Huru skall jag göra med detta folket? Det fattas icke mycket, att de warda mig ännu stenande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'HERren sade till honom: Gack för folket, och tag några de äldsta af Israel med dig; och tag din staf i dina hand, med hwilkom du slog wattnet, och gack.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Si, jag will stå der före dig på ett hälleberg i Horeb; der skall du slå hälleberget, och der skall utlöpa watten, så att folket får dricka. Mose gjorde ock så för de äldsta af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Derföre kallar man det rummet Maßa och Meriba; för det Israels barnas kifs skull, och för det, att de försökte HERran, och sade: Är HERren med oß eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Då kom Amalek, och stridde emot Israel i Nephidim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Och Mose sade till Josua: Utwälj oß män; far ut, och strid emot Amalek: I morgon will jag stå öfwerst på högenom, och hafwa Guds staf i mine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Och Josua gjorde såsom Mose honom sade, att han stridde emot Amalek. Men Mose, och Aaron, och Hur stego upp öfwerst på högen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Och så länge Mose upphöll sina händer, hade Israel öfwerhandena; men när han lät händerna ned, hade Amalek öfwerhandena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Men Mose händer woro tunga, derföre togo de en sten, och lade under honom, att han satte sig deruppå. Aaron och Hur höllo under hans händer, hwar på sine sido; så wordo hans händer stadiga, intilldeß solen gick neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Och Josua nederlade Amalek, och hans folk, genom swärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Och HERren sade till Mose: Skrif detta till en åtminnelse uti en bok, och befall det i Josua öron; ty jag skall förgöra Amalek undan himmelen, att man icke mer skall tänka uppå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Och Mose byggde ett altare, och kallade det HERren Nißi,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ty han sade: HERrans strid skall wara emot Amalek genom ena hand, under Guds beskärm ifrå barn intill barnabarn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Och då Jethro, Presten i Midian, Mose swär, hörde allt det Gud hade gjort med Mose och hans folk Israel, att HERren hade fört Israel utur Egypten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Tog han Zipora, Mose hustru, den han hade tillbakasändt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Samt med hennes twå söner; af hwilkom en het Gersom, ty han sade: Jag är worden en utländninge i främmande lande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Och den andra Elieser, ty han sade: Mins faders Gud hafwer warit min hjelp, och hafwer frälst mig ifrå Pharaos swärde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Då nu Jethro, Mose swär, och hans söner, och hans hustru, kommo till honom i öknene in på Guds berg, der han lägret uppslagit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Lät han säga Mose: Jag Jethro, din swär, är kommen till dig; och din hustru, och både hennes söner med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Då gick Mose ut emot honom, och böjde sig för honom, och kyßte honom. Och då de hade helsat hwarannan, gingo de in i tjället.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Då förtäljde Mose sinom swär allt det HERren hade gjort Pharao och de Egyptier, för Israels skull; och all den mödo, som de på wägenom haft hade, och att HERren hade hulpit dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Och Jethro fröjdade sig öfwer allt det goda, som HERren hade gjort Israel; att han hade frälst dem ifrå de Egyptiers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Och Jethro sade: Lofwad ware HERren, den eder frälst hafwer ifrå de Egyptiers och Pharaos hand; den der kan frälsa sitt folk ifrå Egypti hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nu wet jag, att HERren är större än alle gudar; derföre att de högmodeliga emot dem handlat hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Och Jethro, Mose swär, tog bränneoffer, och offrade det Gudi. Då kom Aaron, och alle de äldste i Israel, till att äta bröd för Gudi med Mose swär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Den andra morgonen satte sig Mose till att döma folket; och folket stod omkring Mose ifrå morgonen intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Då hans swär såg allt det han gjorde med folkena, sade han: Hwad är det du gör med folkena? Hwi sitter du allena, och allt folket står omkring dig ifrå morgonen allt intill aftonen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose swarade honom: Folket kommer till mig, och frågar Gud om råd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Ty då de hafwa något att skaffa, komma de till mig, att jag skall döma emellan hwar och en, och hans nästa; och wisa dem Guds rätt, och hans lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Hans swär sade till honom: Det är icke godt som du gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du gör owisliga; så ock folket, som med dig är: Detta ärendet är dig för swårt, du kan icke uträtta det allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Men hör mina röst; jag will gifwa dig råd, och Gud skall wara med dig: Sköt du folket inför Gud, och framsätt ärenden för Gudi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Och förse dem med rätt och lag, att du wisar dem den wäg, der de uti wandra skola; och de gerningar, som de göra skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Men sök dig upp ibland allt folket redeliga män, de som frukta Gud; sannfärdiga, och de som hata girighetena: Dem sätt öfwer dem, somliga öfwer tusende, öfwer hundrade, öfwer femtio, och öfwer tio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'De som alltid måga döma folket; men när någon swår sak är, att de må hafwa henne inför dig, och de åtskilja alla de ringa saker; så warder det dig lättare, och de dragat med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Om du det gör, kan du bestå hwad Gud dig bjuder; och allt detta folket kan gå hem till sitt igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose hörde sins swärs röst, och gjorde allt, såsom han sade honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Och utwalde redeliga män utaf hela Israel, och gjorde dem till höfdingar öfwer folket; somliga öfwer tusende, öfwer hundrade, föwer femtio, och öfwer tio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Att de alltid skulle döma folket; men hwad swåra saker woro, dem sköto de till Mose; och de ringa saker dömde de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Och så lät Mose sin swär fara hem i sitt land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Uti tredje månadenom, sedan Israels barn utgångne woro utur Egypti land, kommo de på denna dagen in uti den öknen Sinai;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Förty de woro utdragne ifrå Nephidim, och wille in uti den öknen Sinai, och lägrade sig der i öknene, twärtemot berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Och Mose steg upp till Gud. Och HERren ropade till honom af bergena, och sade: Detta skall du säga till Jacobs hus, och förkunna Israels barnom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'I hafwen sett hwad jag hafwer gjort de Egyptier; och huru jag hafwer burit eder på örnawingar, och tagit eder till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Om I nu hören mina röst, och hållen mitt förbund, så skolen I wara min egendom för allt folk; ty hela jorden är min.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Och I skolen wara mig ett Presterligit Konungsrike, och ett heligt folk. Deße äro de ord, som du skall säga Israels barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mose kom, och sammankallade de äldsta i folket, och framsatte all deßa orden för dem, såsom HERren budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Och allt folket swarade tillsammans, och sade: Allt det HERren sagt hafwer, wilje wi göra. Och Mose sade folkens ord HERranom igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Och HERren sade till Mose: Si, jag will komma till dig uti en tjock molnsky, att folket skall höra min ord, som jag talar med dig, och tro dig ewärderliga. Och Mose förkunnade HERranom folkens ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'HERren sade till Mose: Gack bort till folket, och helga dem i dag och i morgon, att de twå sin kläder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Och äro redo på tredje dagen; ty på tredje dagen warder HERren nederstigandes uppå Sinai berg för allo folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Och uppsätt tecken omkring folket, och säg till dem: Wakter eder, att I icke gån upp på berget, eller kommen wid ändan på thy; ty den som kommer wid berget, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ingen hand skall komma wid honom, utan han skall warda stenad, eller med skott genomskjuten; ehwad det är djur eller menniska, skall det icke lefwa. När man hörer ett långsamt ljud, skola de gå intill berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mose steg ned af berget till folket, och helgade dem, och de twådde sin kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Och han sade till dem: Warer redo på tredje dagen; och ingen komme wid sina hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Som nu den tredje dagen kom, och morgonen wardt, då hof sig upp ett dunder och ljungeld, och en tjock molnstod på bergena, och ett ljud af en ganska skarp basun: Och folket, som i lägret war, wardt förfäradt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Och Mose förde folket utu lägret emot Gud; och de gingo in under berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Och hela Sinai berg dambade deraf, att HERren steg neder uppå det i eld: Och deß rök gick upp såsom röken af en ugn, så att hela berget bäfwade swårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Och basunens ljud gick, och wardt ju starkare. Mose talade, och Gud swarade honom öfwerljudt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Då nu HERren nederkommen war uppå Sinai berg ofwanuppå kullen, kallade HERren Mose upp på bergskullen: Och Mose steg ditupp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Då sade HERren till honom: Gack neder, och betyga folkena, att de icke träda fram till HERran, att de skola se honom, och månge falla af dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Deßlikes Presterna, som nalkas HERranom, de skola ock helga sig, att HERren icke förgör dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose sade till HERran: Folket kan icke stiga upp på berget Sinai; ty du hafwer betygat oß, och sagt: Sätt tecken upp omkring berget, och helga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'HERren sade till honom: Gack, stig ned; du och Aaron med dig skolen uppstiga. Men Presterna, och folket, skola icke träda intill, så att de uppstiga till HERran; på det han icke skulle förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Och Mose steg neder till folket, och sade dem detta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Och Gud talade all deßa orden:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Jag är HERren din Gud, den dig utfört hafwer af Egypti lande, utu träldomens huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du skall inga andra gudar hafwa jemte mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du skall icke göra dig något beläte; ej heller eljest någon liknelse, antingen efter det ofwantill är i himlenom, eller efter det nedre är på jordene; ej heller efter det, som i wattnena är under jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Bed icke till dem, och tjena dem icke; ty jag HERren din Gud, är en stark hämnare, den som söker fädernas mißgerning, inpå barnen, allt intill tredje och fjerde led, de som mig hata;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Och gör barmhertighet uppå mång tusende, som mig hafwa kär, och hålla min bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du skall icke mißbruka HERrans dins Guds Namn; ty HERren skall icke låta honom blifwa ostraffad, som hans Namn mißbrukar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Tänk uppå Sabbathsdagen, att du helgar honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sex dagar skall du arbeta, och göra alla dina gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Men på sjunde dagenom är HERrans dins Guds Sabbath: Då skall du intet arbete göra, ej heller din son, ej heller din dotter, ej heller din tjenare, ej heller din tjenarinna, ej heller din ök, ej heller din främling, som innan din stadsport är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Ty uti sex dagar hafwer HERren gjort himmel och jord, och hafwet, och hwad derinne är, och hwilade på sjunde dagenom. Derföre wälsignade HERren Sabbathsdagen, och helgade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Du skall ära din fader och dina moder; på det du skall länge lefwa i landena, som HERren din Gud dig gifwa skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du skall icke dräpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du skall icke göra hor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du skall icke stjäla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du skall icke bära falskt wittnesbröd emot din nästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du skall icke hafwa lust till dins nästas hus. Du skall icke begära dins nästas hustru, ej heller hans tjenare, eller hans tjenarinno, ej heller hans oxa, ej heller hans åsna, ej heller något, det din näste hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Och allt folket såg dundret och ljungelden, och basunens ljud, och berget rykandes; och fruktade sig och flydde, trädandes fjerran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Och sade till Mose: Tala du med oß, wi wilje höra dertill; och låt icke Gud tala med oß, att wi icke skole dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose talade till folket: Frukter eder intet; ty Gud är kommen till att försöka eder; och att hans fruktan skall wara för edor ögon, att I icke synden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Och folket trädde långt ifrå; men Mose gick in till mörkret, der Gud uti war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Och HERren sade till honom: Så skall du säga Israels barnom: I hafwen sett, att jag af himmelen hafwer talat med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Derföre skolen I ingen ting hålla lika wid mig: Silfwergudar och gyldene gudar skolen I icke göra eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Ett altare af jord gör mig, der du uppå ditt bränneoffer och tackoffer, din får och fä offra skall; ty på hwad rum jag stiftar mins Namns åminnelse, der will jag komma till dig, och wälsigna dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Och om du will göra mig ett stenaltare, skall du icke göra det af huggen sten; förty om du far deråt med din knif, så gör du det oskärdt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Du skall ock icke uppstiga på trappor till mitt altare, att din stam icke skall der blifwa upptäckt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Deße äro de rätter, som du skall ditt folk föregifwa:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Om du köper en Ebreisk träl, han skall tjena när dig i sex år: På sjunde årena skall han utgå fri och ledig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Är han allena kommen, så skall han ock allena utgå: Är han kommen gifter, så skall hans hustru utgå med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hafwer hans herre gifwit honom hustru, och hon hafwer födt söner eller döttrar, så skall hustrun och barnen höra herranom till, och han skall gå allena ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Om trälen säger: Jag hafwer min herra, och min hustru, och min barn kär; jag will icke warda fri;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Så hafwe hans herra honom bort för gudarna, och hålle honom intill dörrena eller dörraträn; och borre honom igenom örat med en syl; och han ware hans träl ewärdeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Om någor följer sina dotter till en trälinna, så skall hon icke utgå såsom trälar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Behagar hon icke sinom herra, och han hafwer ingom förlofwat henne, han skall låta henne fri; men till främmande folk hafwer han ingen magt att sälja henne, efter han hafwer försmått henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Gifwer han henne sinom son, då skall han låta henne njuta dotters rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Gifwer han honom ena andra så skall han icke förwägra deßo hennes kost, kläder och ägtenskapspligt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Gör han icke denna tre stycken, så skall hon fri utgå, och intet betala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Den som slår ena mennisko, så att hon dör, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hafwer han det icke gjort med wilja, utan Gud hafwer låtit henne oförwarandes falla honom i händer, så skall jag sätta dig ett rum före, dit han fly skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Om någor går sin nästa efter med arghet, och dräper honom med försåt; den skall du taga ifrå mitt altare, så att man skall dräpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Den som sin fader eller moder slår, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Den som stjäl ena mennisko, och säljer henne, så att man finner honom dermed, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Den som bannar fader eller moder, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Der som någre män kifwa tillhopa, och den ene slår den andra med en sten, eller med näfwan, så att han icke dör, utan ligger på sängene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Fås han wid, så att han utgår wid sin staf, så skall han, som slog honom, wara ursaker; undantagno, att han skall betala honom hwad han försummat hafwer, och gifwa honom hans läkarelön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Den sin träl eller trälinno slår med en staf, så att han dör under hans händer, han skall lida der straff före.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Lefwer han öfwer en eller twå dagar, så skall han icke lida der straff före; ty det är hans penningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Om män kifwa tillhopa, och någondera stöter någon qwinno, som hafwandes är, så att henne förgås barn, och henne dock eljest intet skadar; så skall man näpsa honom till penningar, så mycket som qwinnones man honom pålägger; och skall det utgifwa efter mäklares känning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Skadar henne något, då skall han gifwa själ för själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Öga för öga, tand för tand, hand för hand, fot för fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brännande för brännande, får för får, blånad för blånad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Den som slår sin träl eller trälinno i ögat, och förderfwar det, han skall låta dem fri lös för ögat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Sammalunda om han slår sin träl eller trälinno en tand ut, skall han dem fri lös låta för tandena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Om en oxe stångar en man eller qwinno, så att han dör, så skall man den oxan stena, och icke äta hans kött; och så är oxans herre ursaker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'War oxen tillförene wan att stångas, och hans herre är derom tillsagd, och han icke bewarade honom, och deröfwer dräper en man eller qwinno; så skall man stena den oxan, och hans herre skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Warda honom penningar pålagda, så skall han gifwa till att lösa sitt lif så mycket, som honom pålagdt warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Sammalunda skall man ock med honom handla, om han en son eller dotter stångar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stångar han en träl, eller trälinno; så skall han gifwa deras herra tretio silfwerskiklar, och oxan skall man stena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Om någor öppnar ena grop, eller gräfwer ena grop, och täcker hennne icke till, och en oxe eller åsne faller så deruti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Då skall gropenas herra lösa det med penningar, och gifwa dem deß herra igen; men kroppen skall wara hans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Om någors mans oxe stångar ens annars oxa, så att han dör; då skola de sälja den lefwande oxan, och byta penningarna, och deßlikes byta kroppen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'War det wetterligit, att oxen war tillförene wan att stångas, och hans herre icke bewarade honom; då skall han gifwa en oxa för den andra, och behålla kroppen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Om någor stjäl en oxa eller ett får, och slagtar det, eller säljer, han skall igengifwa fem oxar för en oxa, och fyra får för ett får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Om en tjuf beslagen warder, att han bryter sig in, och får hugg till döds; så skall ingen blodsrätt gå öfwer dråparen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Men är solen öfwer honom uppgången, då skall man blodsrätten gå låta. En tjuf skall igen betala. Hafwer han intet, så skall man sälja honom, för hans tjufnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Finner man tjufnaden när honom lefwande, det ware sig oxe, åsne eller får, så skall han gifwa dubbelt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Om någor gör skada på åker eller wingård, så att han låter sin boskap skada göra uti ens annars åker; han skall af det bästa i sin åker och wingård igen betala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Om en eld uppkommer, och fänger i törne, så att skylarna eller säden, som ännu står, eller åkren uppbränd warder; det skall han betala igen, som elden släppt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Om någor får sinom nästa penningar, eller tyg till att gömma och dem samma warder det stulet utu huset; finner man tjufwen, då skall han gifwa det twefaldt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Finner man icke tjufwen, så skall man hafwa huswärden fram för gudarna; om han icke hafwer kommit sina hand wid sins nästas ting.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Och om en den andra skyller för någon orätt, ware sig om oxa, eller åsna, eller får, eller kläder, eller hwad som helst bortkommet är, då skall begges deras sak komma inför gudarna: Hwilken gudarne fördöma, han skall betala sinom nästa dubbelt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Om någor sätter neder när sin nästa, åsna, eller oxa, eller får, eller hwad boskap det kan wara, och det dör, eller eljest får skada, eller warder honom bortdrifwet, så att ingen ser det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Så skall det komma till en ed dem emellan wid HERran, att han icke hafwer låtit komma sina hand wid hans nästas ting. Och äganden skall den anamma, att hin icke skall gifwat igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Om en tjuf stjäl honom det ifrå, skall han då betala det ägandenom igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Warder det rifwet, skall han hafwa fram wittne deruppå, och så intet igengifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Om någor lånar af sin nästa, och det warder förderfwadt, eller dör, så att deß herre der icke när är, då skall han gifwa det igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Är deß herre der när, då skall han icke gifwa det igen; medan han det för sina penningar lejt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Om någor lockar ena jungfru, den ännu icke förlofwad är, och lägrar henne; han skall gifwa henne hennes morgongåfwor, och hafwa henne till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Om hennes fader försön honom henne, skall han då utgifwa penningar, så mycket som jungfruers morgongåfwor tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'En trollkona skall du icke låta lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Den som hafwer wärdskap med någon boskap, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Den som offrar gudom, utan HERranom allena, han ware förbannad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Främlingar skall du icke beröfwa eller undertrycka; förty I hafwen ock warit främlingar i Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'I skolen ingen enko och faderlös barn bedröfwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Bedröfwar du dem, så warda de ropande till mig, och jag skall höra deras rop;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Och min wrede skall förgrymma sig, så att jag dräper eder med swärd, och edra hustrur skola warda enkor, och edor barn faderlös.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'När du lånar mino folke penningar, det fattigt är när dig, skall du icke hafwa dig så med honom som en ockrare, och intet ocker på honom bedrifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'När du tager en klädnad till pant af din nästa, skall du få honom det igen, förra än solen går ned.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Förty hans klädnad är hans huds endesta öfwertäckelse, der han uti sofwer. Ropar han till mig, så will jag höra honom; ty jag är barmhertig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Gudarna skall du icke banna, och den öfwersta i ditt folk skall du icke lasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Din fyllelse och tårar skall du icke fördröja. Din första son skall du gifwa mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Så skall du ock göra med dinom oxa och får: I sju dagar låt det blifwa när sine moder; på åttonde dagenom skall du gifwa mig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'I skolen wara ett heligt folk för mig; Derföre skolen I intet kött äta, det som på markene af djurom rifwet är; utan kasta det för hundarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du skall icke tro lögnaktigt tal, så att du gör enom ogudaktigom bistånd, och warder ett wrångt wittne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du skall icke följa hopen efter till det ondt är; och icke swara för rätten, så att du efter hopen wiker ifrå det rätt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Du skall icke bepryda den fattiga i hans sak.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'När du finner dins owäns oxa eler åsna, att han far will, så skall du ledan hem till honom igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'När du finner hans åsna, som dig hatar, ligga under bördone, skall du icke låta honom ligga; utan hjelpa honom upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du skall icke böja dins fattigas rätt i hans sak.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'War fjerran ifrå falska saker. Den oskylidga och rättfärdiga skall du icke dräpa; ty jag gifwer ingom ogudaktigom rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Du skall icke taga mutor; förty mutor förblinda de seende, och förwända de rättfärdigas saker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Du skall icke undertrycka främlingar ty I hweten huru de främlingar i hjertat likar, efter I hafwen ock främlingar warit i Egypti lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'I sex år skall du få ditt land, och insamla deß frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'På sjunde årena skall du låta det hwilas och ligga, att de fattige af ditt folk måga äta deraf: Och hwad öfwer blifwer, låt wilddjuren på markene äta det. Så skall du ock göra med dinom wingård och oljoberge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'I sex dagar skall du göra ditt arbete, men den sjunde dagen skall du skona; på det din oxe och åsne måga hwila sig, och dine tjenarinnos son, och främlingen wederqwicka sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Allt det jag eder sagt hafwer, det håller. Och andra gudars namn skolen I icke ihågkomma; och af edar mun skola de icke hörde warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'I tre resor om året skolen I hålla mig högtid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Nämliga de osyrade bröds högtid skall du hålla, att du i sju dagar osyradt bröd äter, såsom jag dig budit hafwer, i den tiden i Abibs månad; förty uti honom äst du utfaren utur Egyten; men kom icke med tomma händer fram för mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Och den högtiden, när du först begynner berga det du på markene fått hafwer; och insamlingens högtid i årsens utgång, när du ditt arbete utaf markene insamlat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tre resor om året skall allt det mankön är komma fram för HERran Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du skall icke offra mitt offers blod med surdeg; och mins högtides feta skall icke blifwa qwart intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Förstlingen af första frukten på dine mark skall du föra in uti HERrans dins Guds hus; och skall icke koka kidet, så länge det på sine moders mjölk är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Si, jag sänder en Ängel framföre dig, den dig skall bewara på wägen, och föra dig till det rum, som jag beredt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Derföre tag dig wara för hans ansigte, och hör hans röst, och förbittra honom icke; ty han skall icke skona eder, när I brottslige ären; och mitt Namn är i honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Hörer du hans röst, och gör allt det jag säger dig; så skall jag wara dina fiendars fiende, och dina moståndares motståndare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'När nu min Ängel går framföre dig, och förer dig till de Amoreer, Hetheer, Phereseer, Cananeer, Heveer, och Jebuseer, och jag förgör dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Då skall du icke tillbedja deras gudar, ej heller tjena dem, och icke göra såsom de göra; utan skall deras afgudar bortkasta, och sönderslå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Men HERranom edrom Gud skolen I tjena, så skall han wälsigna ditt bröd och ditt watten; och skall alla krankhet taga dig ifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ingen ensam eller ofruktsam skall wara i dino lande; och jag skall låta dig blifwa gamlan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Jag skall sända min förskräckelse framföre dig, och göre allt folk förtwifladt, dit du kommer; och skall låta alla dina fiendar komma på flyktena för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Jag skall sända getingar framföre dig, som skola för dig utjaga de Heveer, Cananeer och Hetheer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Jag skall icke utdrifwa dem på ett år för dig, att landet icke skall öde warda, och wilddjur föröka sig emot dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Tågliga skall jag drifwa dem ut för dig, intilldeß du må wäxa till, och besitta landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Och skall jag sätta ditt landmäre, det röda hafwet, till de Philisteers haf, och ifrån öknene allt intill älfwena; ty jag skall gifwa landsens inbyggare i dina hand, att du skall utdrifwa dem före dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du skall intet förbund göra med dem; eller med deras gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Utan låt icke bo dem i dino lande, att de icke komma dig till att synda emot mig; förty, om du tjenar deras gudar, kommer det dig till förargelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Och till Mose sade han: Stig upp till HERran, du och Aaron, Nadab och Abihu, och de sjutio äldste i Israel, och tillbedjer fjerran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Och Mose nalke sig allena intill HERran, och låt de andra intet nalkas; och folket komme ej heller med honom upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mose kom, och förtäljde folkena all HERrans ord, och alla rätter: Då swarade allt folket med ena röst, och sade: All de ord, som HERren sagt hafwer, wilje wi göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Då skref Mose all HERrans ord, och stod om morgonen bittida upp, och byggde ett altare nedan wid berget, med tolf stodar, efter de tolf Israels slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Och sände dit unga män af Israels barnom, att de skulle offra deruppå bränneoffer och tackoffer HERranom af stutar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Och Mose tog hälftena af blodet, och lät det uti ett bäcken; den andra hälftena stänkte han uppå altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Och tog förbundsens bok, och las henne för folksens öron. Och då de sade: Allt det HERren sagt hafwer, wilje wi göra och efterlyda:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Då tog Mose blodet, och stänkte folket dermed, och sade: Si, detta är förbundsens blod, hwilket HERren med eder gör öfwer all deßa orden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Då stego Mose, Aaron, Nadab och Abihu, och de sjutio äldste af Israel upp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Och sågo Israels Gud. Under hans fötter war såsom en skön saphir, och såsom en himmel, då han klar är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Och han lät icke sina hand komma öfwer de yppersta af Israel. Och då de hade skådat Gud, åto de och drucko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Och HERren sade till Mose: Kom upp till mig på berget, och blif der, att jag gifwer dig stentaflor, och lag, och budord, de jag skrifwit hafwer, hwilka du dem lära skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Då stod Mose upp, och hans tjenare Josua, och steg upppå Guds berg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Och sade till de äldsta: Blifwer här, tilldeß wi komme igen till eder: Si, Aaron och Hur äro när eder; kommer någon sak på färde, den mån I hafwa inför dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Då nu Mose kom på berget, öfwertäckte en molnsky berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Och HERrans härlighet bodde uppå bergena Sinai, och öfwertäckte det med molnskyn i sex dagar: Och han kallade Mose på sjunde dagenom utu skynom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Och HERrans härlighets anseende war såsom en förtärande eld öfwerst på bergena, för Israels barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Och Mose gick midt in i skyn, och steg på berget; och blef uppå bergena i fyratio dagar, och fyratio nätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Säg Israels barnom, att de gifwa mig ett häfoffer: Och tager det af hwar man, den som dertill ett friwilligt hjerta hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Och detta är häfoffret, som I skolen taga af dem: Guld, silfwer, koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Gult silke, skarlakan, rosenrödt, hwitt twinnadt silke, getahår;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Rödlett wädurskinn, tackskinn, furoträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Oljo till lampor, speceri till smörjelse, och godt rökwerk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onichsten, och infattade stenar till lifkjortelen, och till skölden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Och de skola göra mig en helgedom, att jag må bo ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Efter som jag will wisa dig en eftersyn till tabernaklet, och till allt det som dertill hörer, så skolen I göra det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Görer en ark af furoträ; halftredje aln skall wara längden, halfannor aln bredden, och halfannor aln höjden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Och du skall bedraga honom med godt guld, innan och utan: Och gör en gyldene krans ofwan omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Och gjut fyra ringar af guld, dem skall du sätta i alla fyra hörnen; så att twå ringar äro på den ena sidone, och twå på den andra sidone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Och gör stänger af furoträ, och bedrag dem med guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Och stick dem in i ringarna på sidone af arken, att man må bära honom dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Och skola de blifwa i ringomen, och icke warda utdragna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Och du skall lägga uti arken det wittnesbörd, som jag skall få dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Du skall ock göra en nådastol af klart guld; halftredje aln skall wara längden på honom, och halfannor aln bredden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Och du skall göra twå Cherubim af tätt guld, på båda ändarna af nådastolenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Så att en Cherub är på denna ändanom, den andra på den andra ändanom: Och alltså äro twå Cherubim på nådastolens ändom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Och de Cherubim skola utsträcka sina wingar ofwan öfwer, så att de öfwertäcka nådastolen med sina wingar, och hwarsannars anlete stå emot hwartannat; och deras anlete skola se uppå nådastolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Och du skall sätta nådastolen ofwanuppå arken; och lägga i arken det wittnesbörd, som jag skall få dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Och dädan will jag betyga dig, och tala med dig, nämliga utaf nådastolenom, emellan de twå Cherubim, som äro uppå wittnesbördsens ark, allt det som jag will befalla dig till Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Du skall ock göra ett bord af furoträ: Twå alnar skall deß längd wara, och en aln bredden, och halfannor aln höjden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Och du skall bedraga det med klart guld, och göra en gyldene krans omkring det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Och ena listo omkring, en hand bredt hög, och en gyldene krans omkring listona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Och du skall göra der fyra gyldene ringar till, uppå de fyra hörnen på deß fyra fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Hardt under listone skola ringarna wara, att man må stinga stänger derin, och bära bordet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Och du skall göra stängerna af furoträ, och bedraga dem med guld, att bordet må dermed warda buret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Du skall ock göra deß fat, skedar, kannor, skålar, af klart guld, att man dermed ut och in skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Och skall du alltid lägga skådobröd fram för mig på bordet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Du skall ock göra en ljusastaka af klart tätt guld; läggen deruppå skall wara med rör, skålar, knöpar och blommor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Hwar och en rör skall hafwa tre skålar, såsom mandelnötter, knöpar och blommor. Detta skola wara de sex rör, som utgå af ljusastakanom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Men läggen af ljusastakanom skall hafwa fyra skålar, och dertill knöpar och blommor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Och ju en knöp under twå rör af de sex, som gå utaf ljusastakanom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ty både knöpar och rör skola gå derutaf; och alltsamman klart tätt guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Och du skall göra sju lampor ofwanuppå, så att de lysa emot hwarandra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Och ljusanäpor, och släcketyg, allt af klart guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Utaf en centener klart guld skall du göra honom, med all deße tyg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Och se till, att du allt gör efter den eftersyn, som du på bergena sett hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Tabernaklet skall du göra af tio tapeter, af hwitt twinnadt silke, af gult silke, af skarlakan och rosenrödt: Cherubim skall du göra deruppå konsteliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Längden på hwart tapetet skall wara åtta och tjugu alnar, bredden fyra alnar; och skola alla tio wara eus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Och skola ju wara fem tillhopafogd, det ena wid det andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Och du skall göra lyckor af gult silke, allestädes på stadet på tapeten, att de måga tillhopafogas, att ju tu och tu på sitt stad kunna tillsammanfästas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Femtio lyckor på hwart tapetet, att det ena må fästas wid det andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Och du skall göra femtio gyldene häfte, der man de tapeter med tillsammanknäpper, det ena wid det andra, tilldeß det blifwer ett tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Du skall ock göra ellofwa tapeter af getahår, till öfwertäckelse öfwer tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Längden af hwart tapetet skall wara tretio alnar, bredden fyra alnar; och skola alla ellofwa wara lika stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fem skall du med hwartannat tillhopafoga, och sedan ser tillhopa med hwartannat, så att du gör det sjette tapetet dubbelt frammanför tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Och du skall göra femtio lyckor på stadet, af hwart tapetet, att de måga tillhopaknäppas med hwartannat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Och skall du göra femtio kopparhäkte, och knäppa häkten in uti lyckorna, att tapeten tillsammanfogas, och warda en täckelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Men det öfwer är i längdene af tapeten på tabernaklet, skall du hälftena låta hänga utöfwer tabernaklet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'På båda sidor en aln långt; så att det öfwer är, blifwer på sidomen af tabernaklet och betäcker det på båda sidor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Utöfwer denna täckelse skall du göra en annor öfwertäckelse af rödlett wädurskinn; och dertill en öfwertäckelse af tackskinn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Du skall ock göra bräder till tabernaklet, af furoträ, hwilka stå skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Tio alnar långt skall hwart brädet wara, och halfannor aln bredt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Twå nåckor skall hwart brädet hafwa, så att det ena må sättas wid det andra: Alltså skall du göra all bräden till tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Tjugu af dem skola stå söder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'De skola hafwa fyratio silfwerfötter nedan under, ju twå fötter under hwart brädet på sina twå nåckor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Sammalunda på den andra sidone, norrut, skola ock stå tjugu bräder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Och fyratio silfwerfötter, ju twå fötter under hwart brädet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Men bak i tabernaklet, westerut, skall du göra sex bräder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Dertill tu bräder bak i de tu hörnen af tabernaklet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Så att hwartdera af de tu bräden lagar sig med sitt hörnebräde ifrå nedan allt uppåt, och komma ofwan tillika tillhopa med en krampo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Så att det äro åtta bräder med deras silfwerfötter, hwilke skola wara sexton; ju twå under ett bräde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Och du skall göra skottstänger af furoträ, fem till de bräden, som äro på den ena sidone i tabernaklet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Och fem till de bräden, som äro på den andra sidone i tabernaklet och fem till de bräden bak i tabernaklet, westerut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Och du skall skjuta medelstången midt öfwer bräden utåt, och fatta dem alla tillhopa ifrå den ena ändan till den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Och skall du bedraga bräden med guld, och ringarna på dem göra af guld, att man skjuter stängerna derin: Och stängerna skall du bedraga med guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Och så skall du nu göra tabernaklet, efter det sättet, som du sett hafwer på bergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Och du skall göra en förlåt af gult silke, skarlakan, och rosenrödt, och twinnadt hwitt silke: Och du skall göra Cherubim deruppå konsteliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Och du skall hänga det på fyra stolpar af furoträ, de som bedragne äro med guld, och hafwa gyldene knappar, och fyra silfwerfötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Och skall du knäppa förlåten derintill med häkter, och sätta wittnesbördsens ark innanför förlåten, att han är eder en åtskilnad emellan det helga, och det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Och du skall sätta nådastolen på wittnesbrödsens ark, uti det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Men bordet sätt utanför förlåten, och ljusastakan twärtöfwer emot bordet, söderut i tabernaklet, så att bordet står norrut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Och skall du göra ett kläde i tabernaklets dörr, wirkadt med gult silke, rosenrödt, skarlakan, och hwitt twinnadt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Och skall du göra fem stolpar till det samma klädet af furoträ, öfwerdragna med guld; med gyldene knappar; och du skall gjuta dem fem kopparfötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Och du skall göra ett altare af furoträ, fem alnar långt och bredt, så att det warder rätt fyrakant, och tre alnar högt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Horn skall du göra på alla fyra hörnen, och du skall öfwerdraga det med koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Gör ock askokäril, skoflar, bäcken, gafflar, kolpannor: Allt det dertill hörer skall du göra af koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Du skall ock göra ett galler, såsom ett nät, af koppar, och fyra kopparringar på deß fyra hörn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Du skall ock görat ifrå nedan uppåt kringom altaret, så att gallret räcker midt uppå altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Och skall du göra stänger till altaret af furoträ, öfwerdragna med koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Och skall du stinga stängerna in i ringarna, så att stängerna äro på båda sidor af altaret, der man må bära det med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Och skall du så görat af bräder att det blifwer ihålt, såsom dig på berget wist är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Du skall ock göra en gård till tabernaklet; en bonad af hwitt twinnadt silke, på den ena sidon, hundrade alnar lång söderut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Och tjugu stolpar på tjugu kopparfötter; och deras knappar med deras gjordar af silfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Sammalunda ock norrupppå en bonad, hundrade alnar lång; tjugu stolpar på tjugu kopparfötter, och deras knappar med deras gjordar af silfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Men westerut öfwer gårdsens bredd skall wara en bonad, femtio alnar lång; tio stolpar på tio fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Österut öfwer gårdsens bredd skall wara femtio alnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Så att bonaden hafwer på ene sidone femton alnar; dertill tre stolpar på tre fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Och femton alnar på den andra sidone; dertill tre stolpar på tre fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Men i gårdsens ingång skall wara ett kläde, tjugu alnar bredt, stickadt med gult silke, skarlakan, rosenrödt och hwitt twinnadt silke; dertill fyra stolpar på deras fyra fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle stolparna kringom gården skola hafwa silfwergjordar, och silfwerknappar, och kopparfötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Och längden på gården skall wara hundrade alnar, bredden femtio, höjden fem alnar, af hwitt twinnadt silke, och deras fötter skola wara af koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Och allt det som tabernaklet tillhörer till allahanda ämbete, och alle deß pålar, och alle gårdsens pålar, skola wara af koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Bjud Israels barnom, att de bära till dig den aldraklaresta oljo stött af oljoträ, till lysning; att man alltid deraf låter i lamporna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Uti wittnesbördsens tabernakel utanför förlåten, som hänger för wittnesbördet. Och Aaron med hans söner skola detta sköta, ifrå morgonen allt intill aftonen för HERranom. Det skall wara eder en ewig sed intill edra efterkommande, ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Och du skall taga till dig din broder Aaron, och hans söner utaf Israels barnom, att han skall wara min Prest, nämliga Aaron och hans söner, Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Och du skall göra dinom broder Aaron helig kläder, som äro härlig och skön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Och du skall tala med allom dem, som ett wist hjerta hafwa, de jag med wishetens anda uppfyllt hafwer, att de göra kläder åt Aaron till hans wigelse, att han blifwer min Prest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Och deße äro kläden, som de göra skola: Sköld, lifkjortel, silkeskjortel, trång kjortel, hatt och bälte: Alltså skola de göra dinom broder Aaron, och hans söner, helig kläder, att han skall wara min Prest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Dertill skola de taga guld, gult silke, skarlakan, rosenrödt och hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Lifkjortelen skola de göra af guld, gult silke, skarlakan, rosenrödt och twinnadt hwitt silke, konsteliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Att han warder sammanfogd på båda axlar, och tillhopabunden på båda sidor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Och hans bälte deröfwer skall wara af samma konst och werk; af guld, gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Och du skall taga twå onichinerstenar, och grafwa deruppå Israels söners namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'På hwardera sex namn, efter som de äro gamle till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Det skall du beställa med de stensnidare, som grafwa insegler, så att de warda infattade i guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Och du skall fästa dem uppå axlarna på lifkjortelen, att de äro åminnelsestenar för Israels barn, att Aaron drager deras namn på båda sina axlar, till åminnelse för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Och du skall göra gyldene spänne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Och twå kedjor af klart guld, som uppåt gå skola, dem skall du fästa uti spännen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Ämbetsskölden skall du göra efter konst, såsom lifkjortelen, af guld, gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Fyrahörnad skall han wara, och twefald: En hand bredt skall wara hans längd, och en hand bredt hans bredd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Och du skall uppfyllat med fyra rader af stenar. Den första raden skall wara en sardius, topaz, smaragd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Den andra, en rubin, saphir, diamant;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Den tredje, en lyncurer, achat, amethist;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Den fjerde, en turkos, onich, jaspis. Uti guld skola de satte warda på alla rader;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Och skola stå efter de tolf Israels söners namn, utgrafne af stensnidare, hwardera med sitt namn, efter de tolf slägten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Och du skall göra kedjor till skölden, som nederåt gå, af klart guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Och twå gyldene ringar, så att du fäster de twå ringar wid de tu hörnen af skölden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Och låt komma de twå gyldene kedjorna in uti de twå ringarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Men de twå ändarna af de twå kedjor skall du låta komma in uti de tu spännen, och fästa dem på axlarna af lifkjortelen emot hwarannat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Och du skall göra twå andra gyldene ringar, och fästa dem wid de andra tu hörnen af skölden, nämliga till sina bredd, der de utanpå lifkjortelen med hänga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Och skall åter göra twå gyldene ringar, och fästa dem emot hwarannan utantill, nedre på de tu hörnen af lifkjortelen, der som lifkjortelen kommer tillhopa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Och man skall tillhopaknäppa skölden med sina ringar med ett gult snöre intill lifkjortelens ringar, så att han ligger hardt inpå lifkjortelen, och skölden icke loßnar ifrå lifkjortelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Så skall Aaron bära Israels barnas namn uti ämbetssköldenom på sitt hjerta, när han går in uti det helga; till en åminnelse för HERranom alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Och du skall låta Ljus och Fullkomlighet i ämbetsskölden, att de blifwa på Aarons hjerta, när han ingår för HERranom; och bär Israels barnas ämbete på sino hjerta för HERranom alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Du skall ock göra under lifkjortelen en silkeskjortel, allsamman af gult silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Och öfwerst midt på honom skall wara ett halssmog; och en borda omkring halssmoget tillhopafållad, att det icke söndergår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Och nedanpå hans fåll skall du göra såsom granataäple af gult silke, skarlakan, rosenrödt, allt omkring, och emellan dem gyldene bjellror, och allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Så att der är en gyldene bjellra, och dernäst ett granataäple, och åter en gyldene bjellra med ett granataäple, allt omkring på fållen af samma silkeskjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Och Aaron skall hafwa honom uppå, när han tjenar, så att man hörer klanget af honom, när han ut och in går uti det helga för HERranom, på det att han icke skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Du skall ock göra ett ännespann af klart guld, och grafwa deruti, efter stensnidarekonst: HERRANS HELIGHET.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Och du skall fästa det på hatten, framman i ännet på Aaron, med ett gult snöre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Och det skall wara i Aarons änne, så att Aaron bär deß helgas brist, som Israels barn helga i allom sinom gåfwom och helgedom. Och det skall alltid wara på hans änne, att han skall försona dem för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Du skall ock göra en trång kjortel af hwitt silke, och en hatt af hwitt silke, och ett stickadt bälte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Och till Aarons söner skall du göra kjortlar, bälte och hufwor, som äro härlig och skön; och skall kläda dem uppå din broder Aaron med hans söner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Och skall smörja dem, och fylla deras händer, och wiga dem, att de blifwa mine Prester;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Och skall göra dem linnen nederkläder, till att skyla blygdenes kött, ifrå ländene allt ned på låren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Och Aaron med hans söner skola hafwa dem uppå, när de gå in uti wittnesbördsens tabernakel, eller fram till altaret, till att tjena uti thy helga, på det att de icke umgälla deras mißgerning, och måste dö. Det skall wara honom, och hans säd efter honom, ett ewigt sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Detta måste du ock göra dem, att de skola warda mig wigde till Prester. Tag en ungan stut, och twå wädrar utan wank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Osyradt bröd och osyrade kakor, blandade med oljo, och osyrade tunnkakor, smorda med oljo; af hwetemjöl skall du allt görat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Och skall läggat uti en korg, och uti korgenom bära det fram, samt med stutenom, och de twå wädrarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Och du skall hafwa Aaron och hans söner fram för dörrena af wittnesbördsens tabernakel, och twå dem med watten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Och taga kläden, och kläda uppå Aaron den trånga kjortelen, och den silkeskjortelen, och lifkjortelen, och skölden till lifkjortelen, och skall begjorda honom utanuppå lifkjortelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Och sätta hatten uppå hans hufwud, och den helga kronona uppå hatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Och skall taga smörjooljo, och gjuta uppå hans hufwud och smörja honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Och hans söner skall du ock hafwa fram, och kläda uppå dem den trånga kjortelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Och begjorda både Aaron och dem med bälter, och binda hufworna på dem, att de skola hafwa Presterskapet till ett ewigt sätt. Och du skall fylla händerna uppå Aaron och hans söner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Och skall hafwa stuten fram för dörrena af wittnesbördsens tabernakel. Och Aaron med hans söner skola lägga sina händer på hufwudet af stutenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Och du skall slagta stuten för HERranom, inför dörrena af wittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Och skall taga af hans blod, och stryka uppå altarens horn med ditt finger, och allt det andra blodet kasta neder på bottnen till altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Och skall taga allt det feta, som är på tarmarna, och det nätet öfwer lefrena, och båda njurarna, med det feta, som derpå är, och skall bränna det upp på altarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Men stutens kött, hudena och gåret, skall du uppbränna med eld utanför lägret; ty det är ett syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Men den ena wäduren skall du taga; och Aaron med hans söner skola lägga deras händer på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Sedan skall du slagta honom, och taga hans blod, och stänka uppå altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Men wäduren skall du hugga i stycker, och twå hans inelfwer och fötter, och skall lägga det på hans stycker och hufwud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Och bränna upp allan wäduren på altaret; ty det är ett bränneoffer HERranom, en söt lukt HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Den andra wäduren skall du taga; och Aaron med hans söner skola lägga sina händer på hans hufwud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Och skall slagtan, och taga af hans blod, och stryka på högra örnatimpen af Aaron och hans söner, och uppå tumman af deras högra hand, och på största tån af deras högra fot, och skall stänka blodet på altaret allt omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Och skall taga blodet på altarena, och smörjoljo, och stänka på Aaron och hans kläder; så warder han och hans kläder, hans söner och deras kläder wigd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Sedan skall du taga det feta af wäduren, stjerten, och det feta, som är på inelfwen, nätet, som är öfwer lefrena, och båda njurarna med det feta, som deröfwer är, och den högra bogen; ty det är fyllelsens wädur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Och ett bröd, och en oljokako, och en tunnkako, utu korgenom, der det osyrade brödet i är, den för HERranom står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Och lägg allt detta på Aarons och hans söners händer; och wefta det HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Och så skall du taga det utaf deras händer, och bränn det upp på altarena för ett bränneoffer, till en söt lukt för HERRanom; ty det är HERrans offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Och du skall taga bröstet af fyllelsens wädur Aarons, och skall wefta det för HERraom; det skall wara din del;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Och skall alltså helga weftebrödet och häfwobogarna, som weftade och häfne äro af fyllelsens wädur, Aarons och hans söners.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Och det skall wara Aarons och hans söners, till ett ewigt sätt af Israels barnom; ty det är ett häfoffer; och häfoffren skola höra HERranom till af Israels barnom i deras tackoffer och häfoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Men Aarons helga kläder skola hans söner hafwa efter honom, att de derutinnan skola warda smorde, och deras händer fyllda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Hwilken af hans söner warder Prest i hans stad, han skall kläda dem uppå i sju dagar, att han skall gå in uti wittnesbördsens tabernakel, till att tjena uti de helga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du skall ock taga fyllelsens wädur, och koka hans kött på heligt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Och Aaron med hans söner skola äta af samma wädurs kötte, med brödet, som i korgenom är, inför dörrena af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ty en försoning är dermed skedd, till att fylla deras händer, att de skola wigde warda. Ingen annar skall ätat; ty det är heligt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Om något öfwerblifwer af fyllelsens kötte, och af brödena intill morgonen, det skall du uppbränna på elde, och icke låta ätat; ty det är heligt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Och alltså skall du göra med Aaron och hans söner, såsom jag hafwer budit dig. I sju dagar skall du fylla deras händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Och hwar dag slagta en stut, till ett syndoffer till försoning; och skall skära altaret, när du försonar det, och skall smörja det, att det skall blifwa wigdt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'I sju dagar skall du försona och wiga altaret, att det skall wara deß aldrahelgestas altare. Ho som will komma wid altaret, han skall wara wigd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Och detta skall du göra med altaret: Tu lamb årsgammal skall du hwar dag offra deruppå:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Ett lamb om morgonen, det andra om aftonen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Och till ett lamb en tiung semlomjöl, blandadt med en fjerding af ett hin stött oljo; och en fjerding af ett hin win till drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Med det andra lambet, om aftonen, skall du göra såsom med morgonens spisoffer och drickoffer, till en söt lukt HERranom af offrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Detta är det dageliga bränneoffret intill edra efterkommande, för dörrene af wittnesbördsens tabernakel för HERranom, der jag eder betyga, och med dig tala will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Der will jag Israels barnom betygad och helgad warda i mine härlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Och wil helga wittnesbördsens tabernakel med altarena, och wiga Aaron med hans söner mig till Prester;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Och will bo ibland Israels barn, och wara deras Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Att de weta skola, att jag är HERren deras Gud, som dem förde utur Egypti land, att jag skulle bo ibland dem; Jag HERren deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Du skall ock göra ett rökaltare till rökning, af furoträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'En aln långt och bredt, rätt fyrakant, och twå alnar högt, med sin horn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Och skall öfwerdraga det med klart guld, deß tak, och deß wäggar allt omkring, och deß horn; och skall göra en krans af guld deromkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Och twå gyldene ringar under kransen på båda sidor, att man må sätta der stänger uti, och bärat dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Stängerna skall du ock göra af furoträ, och med guld öfwerdraga dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Och skall sätta det inför förlåten, som hänger för wittnesbördsens ark, och för nådastolen, som är på wittnesbördet: Dädan will jag betyga dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Och Aaron skall derpå röka godt rökwerk hwar morgon, när han reder lamporna till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Sammalunda när han upptänder lamporna om aftonen, skall han ock röka sådana rök. Det skall wara den dageliga röken för HERranom när edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'I skolen ingen främmande rök göra deruppå, och intet bränneoffer, ej heller spisoffer, och intet drickoffer offra deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Och Aaron skall på deß horn försona en tid om året, med syndoffrens blod till försoning. Sådana försoning skall ske en gång årliga när edra efterkommande; ty det är HERranom det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'När du räknar hufwuden af Israels barn, då skall hwar och en gifwa HERranom försoning för sina själ, på det dem icke skall wederfaras en plåga, när de räknade warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Och skall hwar och en, som med är i talet, gifwa en half sikel, efter helgedomens sikel. En sikel gäller tjugu gera. Sådana half sikel skall wara HERrans häfoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Den som i talet är ifrå tjugu år och derutöfwer, han skall gifwa HERranom häfoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Den rike skall icke mer gifwa, och den fattige icke mindre, i dem halfwa siklenom, som man gifwer HERranom till ett häfoffer, för deras själars försoning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Och du skall sådana försoningspenningar taga af Israels barnom, och lägga dem till Guds tjenste i wittnesbördsens tabernakel, så att det är Israels barnom en åminnelse för HERranom, att han låter försona sig öfwer deras själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du skall ock gör ett twättekar af koppar med en kopparfot, till att twå utaf; och skall sätta det emellan wittnesbördsens tabernakel och altaret, och låta der watten uti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Att Aaron och hans söner twå deras händer och fötter derutur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'När de gå in uti wittnesbördsens tabernakel, skola de twätta sig med watten, att de icke måga dö; eller då de nalkas till altaret, till att tjena HERranom med rökoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'De skola twätta sina händer och fötter, på det att de icke skola dö. Det skall dem ett ewigt sätt wara, honom och hans säd i deras efterkommandom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Tag dig aldrabästa speceri, aldraädlesta myrrham, femhundrade siklar, och canel halft så mycket, femtio och tuhundrad, och calamus deßlikes femtio och tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Och casia femhundrad, efter helgedomens sikel; och oljo af oljoträ ett hin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Och gör en helig smörjoljo efter apothekarekonst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Och du skall dermed smörja wittnesbördsens tabernakel; wittnesbördsens ark;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Bordet med all sin tyg; ljusastakan med sin tyg; rökaltaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Bränneoffersaltaret med all sin tyg; och twättekaret med sin fot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Och skall alltså wiga dem, att de blifwa det aldrahelgasta; ty den som will komma derwid, han måste wara wigd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aaron och hans söner skall du ock smörja, och wiga dem mig till Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Och du skall tala med Israels barn, och säga: Denna oljan skall wara mig en helig smörjelse när edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'På menniskokropp skall hon icke gjuten warda, och skall ej heller någon sådana göras; ty hon är helig, derföre skall hon wara eder helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Den som gör en sådana, eller gifwer enom androm deraf, han skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Och HERren sade till Mose: Tag dig speceri, balsam, stacten, galban, och rent rökelse, så mycket af det ena som af det andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Och gör der rökwerk af efter apothekarekonst bemängdt, så att det är klart till helighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Och stöt det till pulver, och du skall lägga det inför wittnesbördet, in uti wittnesbördsens tabernakel; dädan jag dig betyga skall. Det skall wara eder det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Och ett sådant rökwerk skolen I icke göra eder; utan det skall wara dig heligt HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Den som ett sådant gör, till att röka dermed, den skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Si, jag hafwer wid namn kallat Bezaleel, Uri son, Hurs sons, af Juda slägte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Och hafwer fyllt honom med Guds Anda; med wishet och förstånd, och konst, och med allahanda werk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Konsteliga till att arbeta på guld, silfwer, koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Konsteliga utskära och insätta stenar, och konsteliga timbra på trä; till att göra allahanda werk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Och si, jag hafwer fått honom till hjelp Aholiab, Ahisamachs son, af Dans slägte; och hafwer hwarjom och enom wisom gifwit wisdom i hjertat, att de göra skola allt det jag dig budit hafwer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Wittnesbördsens tabernakel, wittnesbördsens ark, nådastolen deruppå, och all tabernaklens tyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Bordet och deß tyg; den sköna ljusastakan och all hans tyg; rökaltaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Bränneoffersaltaret med all sin tyg; twättekaret med sinom fot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Ämbeteskläden, och de helga kläden Prestens Aarons, och hans söners kläder, till att tjena i Presterskapena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Smörjooljona och rökwerk af speceri till helgedomen. Allt det jag hafwer budit dig, skola de göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Tala till Israels barn, och säg: Håller min Sabbath; ty han är ett tecken emellan mig och eder, intill edra efterkommande, at I skolen weta, att jag är HERren, den eder helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Derföre håller min Sabbath; ty han skall wara eder helig. Den som ohelgar honom, han skall döden dö: Den som gör något arbete på honom, hans själ skall utrotad warda utu hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sex dagar skall man arbeta; men på sjunde dagen är Sabbath, HERrans helga hwila. Den som något arbete gör på Sabbathsdagen, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Derföre skola Israels barn hålla Sabbath, att de med deras efterkommande hålla honom till ett ewigt förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Han är ett ewigt tecken emellan mig och Israels barn. Ty i sex dagar gjorde HERren himmel och jord, men på sjunde dagen höll han upp, och hwilte sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Och då han hade uttalat med Mose på Sinai berg, gaf han honom twå wittnesbördsens taflor: De woro af sten, och skrefna med Guds finger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Då folket såg, att Mose fördröjde komma neder af bergena, församlade de sig emot Aaron, och sade till honom: Upp, och gör oß gudar, de som gå före oß; ty wi wete icke hwad deßom manne Mose wederfaret är, den oß fört hafwer utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron sade till dem: Rifwer de gyldene örnaringar utur edra hustrurs öron, edra söners och edra döttrars, och bärer dem till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Då ref allt folket deras gyldene örnaringar utu deras öron, och båro dem till Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Och han tog dem af deras händer, och utkastade det med en grafstickel, och gjorde en gjuten kalf. Och de sade: Deße äro dine gudar, Israel, som dig utur Egypti land fört hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Då Aaron såg det, byggde han ett altare för honom, och lät utropa, och säga: I morgon är HERrans högtid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Och de stodo om morgonen bittida upp, och offrade bränneoffer, och båro fram tackoffer. Sedan satte sig folket till att äta och dricka, och stodo upp till att leka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Då sade HERren till Mose: Gack, stig ned; ty ditt folk, som du utur Egypti land fört hafwer, hafwer förderfwat det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'De äro snarliga trädde ifrå de wägar, som jag dem budit hafwer. De hafwa gjort sig en gjuten kalf; och hafwa tillbedit honom, och offrat honom, och sagt: Deße äro dina gudar, Israel, som dig hafwa fört utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Och HERren sade till Mose: Jag ser, att det är ett hårdnackadt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Och nu låt mig, att min wrede förgrymmar sig öfwer dem, och uppfräter dem, så will jag göra dig till ett stort folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Men Mose bad allwarliga inför HERran sin Gud, och sade: Ack! HERre, hwi will din wrede förgrymma sig öfwer ditt folk, det du med stora magt och wäldiga hand utur Egypti land fört hafwer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Hwi skulle de Egyptier tala, och säga: Han hafwer fört dem ut till deras ofärd, på det han skulle dräpa dem i bergomen, och utskrapa dem af jordene? Wänd dig ifrå dine wredes grymhet, och war nådelig öfwer dins folks ondsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Tänk uppå dina tjenare Abraham, Isaac och Israel, hwilkom du wid dig sjelf sworit hafwer, och sagt dem: Jag skall föröka edra säd, såsom stjernorna i himlenom; och allt det landet, der jag om talat hafwer, will jag gifwa edro säd, och de skola besitta det ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Så ångrade då HERren det onda, som han hotade att göra sino folke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose wände sig och steg ned af bergena, och hade twå wittnesbördsens taflor i sine hand; de woro skrefne på båda sidor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Och Gud hade sjelf gjort dem, och sjelf skrifwit skriftena deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Då nu Josua hörde folksens skri, att de jubilerade, sade han till Mose: Ett krigskriande är i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Swarade han: Det är icke ett skriande såsom af dem der winna eller tappa; utan jag hörer ett skriande af qwädedansar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Som han nu kom intill lägret, och fick se kalfwen, och dansen, förgrymmade han sig i wrede, och kastade taflorna utu sine hand, och slog dem sönder nedanför bergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Och tog kalfwen, som de gjort hade, och brände honom upp i eld, och gjorde honom till pulver, och strödde det i wattnen, och gaf det Israels barnom till att dricka;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Och sade till Aaron: Hwad hafwer folket gjort dig, att du hafwer kommit dem en så stor synd uppå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron sade: Min herre låte sina wrede icke förgrymma sig; du wetst att detta folket är ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'De sade till mig: Gör oß gudar, som oß föregå; ty wi wete icke huru denna mannenom Mose går, den oß fört hafwer utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Jag sade till dem: Den som guld hafwer, han rifwe det af, och få mig; och jag kastade det i eld, deraf är denne kalfwen worden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Då nu Mose såg, att folket war fritt (ty Aaron hade gjort dem fri, och dermed han dem förhöja wille, kom han dem på skam),');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Trädde han in i porten åt lägrena, och sade: Kommer hit till mig hwar och en, som HERranom tillhörer. Då församlade sig till honom alle Levi barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Och han sade till dem: Detta säger HERren Israels Gud: Binde hwar och en sitt swärd på sina länder; och går igenom lägret fram och åter, ifrå den ena porten till den andra, och dräpe hwar och en sin broder, frända och nästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Levi barn gjorde såsom Mose dem sade. och föll i den dagen af folkena wid tretusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Då sade Mose: Fyller i dag edra händer HERranom, hwar och en på sin son och broder, att i dag må öfwer eder wälsignelse gifwen warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Om morgonen derefter sade Mose till folket: I hafwen gjort en stor synd. Nu, jag will uppstiga till HERran, om jag tilläfwentyrs kan försona edra synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Som nu Mose åter kom till HERran, sade han: Ack! detta folket hafwer gjort en stor synd; och hafwa gjort sig gyldene gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nu förlåt dem deras synd; hwar icke, så skrapa mig ock utu dine bok, som du skrifwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'HERren sade till Mose: Huru? Den will jag utskrapa utu mine bok, som syndar emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Så gack nu, och för folket dit, som jag hafwer sagt dig; si, min Ängel skall gå före dig. Men på min sökningsdag skall jag söka deras synder öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Alltså plågade HERren folket, derföre att de hade gjort kalfwen, hwilken Aaron gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'HERren sade till Mose: Gack, drag hädan, du och folket,som du utur Egypti land fört hafwer, in uti det landet, som jag Abraham, Isaac och Jacob sworit hafwer, och sagt: Dine säd will jag gifwa det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Och will sända min Ängel före dig, och utdrifwa de Cananeer, Amoreer, Hetheer, Phereseer, Heveer, och Jebuseer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Inuti det land, der mjölk och hannog uti flyter; ty jag will icke draga upp med dig; förty du äst ett hårdnackadt folk; jag måtte tilläfwentyrs i wägenom uppfräta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Då folket detta onda talet hörde, wordo de ångse; och ingen drog sin prydning på sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Och HERren sade till Mose: Säg till Israels barn: I ären ett hårdnackadt folk: Jag warder en gång kommandes med hast öfwer dig, och förgör dig. Och nu lägg dina prydning af dig, att jag må weta hwad jag skall göra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Så lade Israels barn deras prydning af sig, inför Horebs berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Så tog Mose tabernaklet, och slog det upp ute, långt ifrå lägret, och kallade det wittnesbördsens tabernakel. Och hwilken der något wille fråga HERran, han måste gå till wittnesbördsens tabernakel ut för lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Och när Mose gick ut till tabernaklet, så stod allt folket upp, och hwar och en trädde i sins tjälls dörr, och sågo efter honom, tilldeß han kom in uti tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Och när Mose kom in uti tabernaklet, så kom molnstoden neder, och stod i tabernaklens dörr, och talade med Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Och allt folket såg molnstodena stå uti tabernaklens dörr; och stodo upp, och bugade sig hwar och en i sins tjälls dörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Och HERren talade med Mose, ansigte mot ansigte, såsom en man talar med sin wän. Och när han wände om igen till lägret, gick icke hans tjenare, den unge mannen Josua, Runs son, utu tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Och Mose sade till HERran: Si, du säger till mig. För mig detta folket upp; och du låter mig icke weta, hwem du will sända med mig, och besynnerliga efter du sagt hafwer: Jag känner dig wid namn, och du hafwer funnit nåde för min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Hafwer jag då funnit nåde för din ögon, så låt mig weta din wäg, der jag af förnimma må, att jag finner nåde för din ögon; och se dock dertil, att detta folket är ditt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Han sade: Mitt ansigte warder gåendes, dermed will jag leda dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Han sade till honom: Om ditt ansigte icke går, så låt oß intet komma hädan af detta rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Ty hwarpå skall det dock förnummet warda, att jag och ditt folk hafwa funnit nåde för din ögon, utan då du går med oß; på det att jag och ditt folk måga warda något besynnerligit för allt folk, som på jordene är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'HERren sade till Mose: Såsom du nu sade, så will jag ock göra; ty du hafwer funnit nåde för min ögon, och jag känner dig wid namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Men han sade: Låt mig då se dina härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Och han sade: Jag will låta allt mitt goda gå framföre ditt ansigte, och will låta predika HERrans Namn för dig. Men hwem jag är gunstig, honom är jag gunstig, och öfwer hwem jag mig förbarmar, den förbarmar jag mig öfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Och sade ytterligare: Du kan icke se mitt ansigte; förty ingen menniska, som mig ser, kan lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Och HERren sade ytterligare: Si, här är ett rum när mig; der skall du stiga upp på klippona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'När då min härlighet går framom, will jag sätta dig in i stenklyftona: Och min hand skall hålla öfwer dig, tilldeß jag kommer framom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Och när jag tager mina hand af dig, skall du få se mig på baken; men mitt ansigte kan man icke se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Och HERren sade till Mose: Uthugg dig twå stentaflor, sådana som de första woro, att jag skrifwer de ord deruti, som i första taflomen woro, som du sönderslog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Och war redo i morgon, att du bittida stiger upp på Sinai berg, och träder der upp till mig öfwerst på berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Och låt ingen stiga ditupp, med dig, att ingen warder sedder kringom hela berget: Och låt ingen får eller fä beta in mot detta berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Och Mose uthögg sig twå stentaflor, sådana som de första woro, och stod bittida upp om morgonen, och steg upp på Sinai berg, såsom HERren honom budit hade, och tog de twå stentaflor i sina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Då kom HERren neder uti ett moln. Och han trädde ditfram till honom, och åkallade HERrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Och då HERren gick framom för hans ansigte, ropade han: HERre, HERre Gud, barmhertig och nådelig, och långmodig, och af stor nåde, och trofast.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Du som bewarar nåde till tusende leder, och förlåter mißgerningar, öfwerträdelse och synder; och för hwilkom ingen är oskyldig, du som söker fädernas mißgerningar på barn och barnabarn, allt intill tredje och fjerde led.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Och Mose böjde sig hasteliga neder på jordena, och bad till honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Och sade: Hafwer jag, HERre, funnit nåd för din ögon, så gånge HERren med oß; förty det är ett hårdnackadt folk; att du warder wårom mißgerningom och syndom nådelig, och låter oß wara ditt arfgods.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Och han sade: Si, jag will göra ett förbund för allo dino folke, och will göra undertecken, hwilkas like icke skapade äro i all land, och ibland all folk: Och allt folk, der du ibland äst, skall se HERrans werk; ty förskräckeligit skall det wara, som jag göra skall med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Håll det som jag bjuder dig i dag: Si, jag will utdrifwa för dig de Amoreer, Cananeer, Hetheer, Phereseer, Heveer och Jebuseer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Tag dig wara, att du icke gör något förbund med landsens inbyggare, der du inkommer; att de icke warda dig till förargelse ibland dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Utan deras altare skall du omstörta, och slå sönder deras beläter, och deras lundar hugga ned;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Ty du skall icke tillbedja en annan gud; ty HERren heter en nitälskare, derföre att han är en nitälskande Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'På det att om du gör något förbund med landsens inbyggare; och när de i horeri löpa efter sina gudar, och offra sina gudar, att de icke bjuda dig, och du äter af deras offer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Och tager dinom sönom deras döttrar till hustrur; hwilka i horeri löpa efter deras gudar, och komma dina söner ock till att löpa i horeri efter sina gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du skall inga gjutna gudar göra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Osyradt bröds högtid skall du hålla: I sju dagar skall du äta osyradt bröd, såsom jag dig budit hafwer, I Abibs månads tid; ty uti Abibs månad äst du utdragen utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Allt det som först öppnar moderlifwet, är mitt; det mankön är, i dinom boskap, det sitt moderlif öppnar, ware sig oxe eller får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Men åsnans förstföding skall du lösa med ett får; om du icke löser det, så bryt thy halsen sönder. Allt förstfödt af din barn skall du lösa; och att ingen kommer fram för mig med tomma händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sex dagar skall du arbeta; på sjunde dagen skall du hålla upp, både med plöjande och skärande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Weckohögtid skall du hålla med förstlingen af hweteskördene; och insamlingshögtid, när året ute är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tre resor om året skall allt dit mankön komma fram för den allsmägtiga HERran och Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'När jag utdrifwer hedningarna för dig, och förwidgar dina landsändar, skall ingen åstunda efter ditt land, den stund du uppgår, tre resor om året till att hafwa dig fram för HERran din Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du skall icke offra bloden af mitt offer på syradt bröd; och Påskahögtidenes offer skall icke blifwa öfwer nattena intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Förstlingen af den första frukten af dinom åker skall du föra in uti HERrans dins Guds hus. Du skall icke koka kidet, den stund det ännu på sins moders mjölk är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Och HERren sade till Mose: Skrif deßa orden; ty efter deßa orden hafwer jag gjort ett förbund med dig, och med Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Och han war der när HERranom fyratio dagar och fyratio nätter, och åt intet bröd, och drack intet watten: Och han skref på taflorna detta förbund, de tio ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Då nu Mose gick ned af berget Sinai, hade han de twå wittnesbördsens taflor i sine hand, och wißte icke, att huden af hans ansigte sken, deraf att han hade talat med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Och då Aaron och all Israels barn sågo, att hans ansigtes hud sken, fruktade de nalkas honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Då kallade Mose dem; och till honom wände sig både Aaron, och alle de öfwerste för menighetene: Och han talade med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sedan nalkades all Israels barn intill honom: Och han böd dem allt det HERren hade talat med honom på Sinai berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Och då han talade med dem, lade han ett täckelse på sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Och när han ingick för HERran till att tala med honom, lade han täckelset af, tilldeß han gick åter ut igen: Och när han kom ut, och talade med Israels barn det honom budet war;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Så sågo då Israels barn på hans ansigte, huru hans ansigtes hud sken: Så drog han åter täckelset öfwer ansigtet, tilldeß han gick åter in igen till att tala med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Och Mose församlade hela menighetena af Israels barn, och sade till dem: Detta är det som HERren budit hafwer, att I göra skolen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'I sex dagar skolen I arbeta; men den sjunde dagen skolen I hålla heligan, HERrans hwilos Sabbath. Den som något arbete gör på honom, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'I skolen ingen eld upptända på Sabbathsdagenom i alla edra boningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Och Mose sade till alla menighetena af Israels barn: Detta är det HERren budit hafwer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Gifwer ibland eder häfoffer HERranom, alltså att hwar och en frambär häfoffer HERranom af ett fritt hjerta, guld, silfwer, koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Gult silke, skarlakan, rosenrödt, hwitt silke, och getahår;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Rödlett wädurskinn och tackskinn, furoträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Oljo till lamporna, och speceri till smörjoljo, och till godt rökwerk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Onich och infattade stenar till lifkjortelen och till skölden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Och den ibland eder förståndig är, han komme och göre hwad HERren budit hafwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Nämliga tabernaklet med deß täckelse och öfwertäckelse; ringar, bräder, skottstänger, stolpar och fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Arken med hans stänger; nådastolen och förlåten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Bordet med sina stänger, och all deß tyg och förlåten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Ljusastakan till att lysa, och hans redskap, och hans lampor, och oljo till lysning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Rökaltaret med sina stänger, smörjooljan, och speceri till rökwerk; klädet för tabernaklets dörr;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Bränneoffersaltaret med deß koppargallrar, stänger och all sin redskap; twättekaret med sin fot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Bonaden till gården, med sina stolpar och fötter; och klädet till dörrena åt gårdenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Pålarna till tabernaklet, och till gården med deras tåg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Ämbetskläden till tjensten i det helga; de helga kläder till Presten Aaron, med hans söners kläder till Presterskapet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Då gick hela menigheten af Israels barn ut ifrå Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Och alle de som gerna och wälwiljeliga gåfwo, kommo och båro det fram till ett häfoffer HERranom, till wittnesbördsens tabernakels werk, och till all deß tjenste, och tilll de helga kläden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Både man och qwinna båro fram, hwilken som helst dertill hade wilja, spänner, örnaringar, ringar och spann, och allahanda gyldene redskap: Bar ock hwar man fram guld, till westoffer HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Och den som när sig fann gult silke, skarlakan, rosenrödt, hwitt silke, getahår, rödlett wädurskinn och tackskinn, han bar det fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Och den som silfwer eller koppar hof, han bar det fram HERranom till häfoffer. Och den som fann furoträ när sig, han bar det fram till allahanda Gudstjenstens werk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Och de der förståndiga qwinnor woro, de wirkade med sina händer, och båro sitt werk fram af gult silke, skarlakan, rosenrödt, och hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Och de qwinnor, som stickeliga woro, de wirkade getahår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Men Förstarna båro fram onich, och infattade stenar till lifkjortelen och till skölden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Och speceri och oljo till lysning och till smörjo, och till godt rökwerk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Alltså båro Israels barn fram HERranom friwiljoge, både män och qwinnor, till allahanda werk, som HERren budit hade genom Mose, att göras skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Och Mose sade till Israels barn: Ser, HERren hafwer kallat Bezaleel wid namn, Uri son, Hurs sons, af Juda slägte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Och hafwer uppfyllt honom med Guds Anda, att han är wis, förståndig, och stickelig till allahanda werk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Till att konsteliga arbeta på guld, silfwer och koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Snida, och insätta ädla stenar; till att timbra af trä; till att göra allt konsteligit arbete;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Och hafwer gifwit honom underwisning i hans hjerta; samt med Aholiab, Ahisamachs son, af Dans slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Han hafwer uppfyllt deras hjerta med wishet, till at göra allahanda werk, till att snida, wirka och sticka, med gult silke, skarlakan, rosenrödt, och hwitt silke, och med wäfwande, så att de göra allahanda werk, och konsteligit arbeta påfinna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Då arbetade Bezaleel och Aholiab, och alle wise män, de som HERren hade gifwit wishet och förstånd till att weta, huru de allahanda werk göra skulle, till den tjenst, som helgedomen tillhörde, efter allt det som HERren budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Och Mose kallade Bezaleel och Aholiab, och alla wisa män, dem HERren hade gifwit wishet i deras hjerta; nämliga alla de som wälwiljeliga tillbädo sig, och gingo dertill, till att arbeta på werket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Och de togo till sig af Mose alla häfningar, som Israels barn frambåro, till den tjenst, som helgedomen tillkrafde, att det skulle blifwa gjordt; ty de båro hwar morgon deras wiljoga hjelp till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Då komme alle de wise, som arbetade på helgedomens werk, hwar och en af sitt werk, som de gjorde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Och sade till Mose: Folket bär allt för mycket till, mer än till denna tjenstenes werk behöfwes, som HERren budit hafwer att göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Då böd Mose, att utropas skulle i lägren: Ingen gifwe mer till helgedomens häfning. Så wände folket igen att frambära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Ty der war allaredo nog till allahanda werk, som görandes war, och ändå utöfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Och så gjorde alle wise män ibland arbetarena på werket, tabernaklet, tio tapeter, af hwitt twinnadt silke, gult silke, skarlakan, rosenrödt, Cherubim konsteliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Längden af hwart tapetet war åtta och tjugu alnar, och bredden fyra alnar, och de woro all wid ena måtto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Och han häftade tillhopa ju fem tapeter, det ena wid det andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Och gjorde gula lyckor på hwart tapetens stad, der de wordo tillhopafogde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Ju femtio lyckor på hwart tapetet, der det ena det andra med fattade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Och gjorde femtio gyldene häfte, och tillhopafogde det ena tapetet med det andra med häften; så att det wardt ett tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Och han gjorde ellofwa tapeter af getahår till öfwertäckelse öfwer tabernaklet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Tretio alnar lång, och fyra alnar bred; all wid ena måtto;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Och fogde fem af dem tillhopa på en del;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Och sex tillhopa på den andra delen; och gjorde ju femtio lyckor på hwart tapetet wid stadet, dermed de wordo tillsammanknäppte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Och gjorde ju femtio kopparhäfte, der samma tapeter med tillhopafogades;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Och gjorde ett täckelse öfwer detta täckelset af rödlett wädurskinn; och öfwer det ännu ett täckelse af tackskinn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Och gjorde bräder till tabernaklet af furoträ, som stå skulle;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Hwartdera tio alnar långt, och halfannor aln bredt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Och uppå hwartdera twå nåckor, der de med wordo tillhopasatte: Så gjorde han all bräden till tabernaklet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'At tjugu af dem stodo på södra sidone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Och gjorde fyratio silfwerfötter derunder; under hwart brädet twå fötter, till twå sina näckor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'På den andra sidone af tabernaklet, som war nordantill, gjorde han ock tjugu bräder,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Med fyratio silfwerfötter; under hwart brädet twå fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Men bak i tabernaklet på westra sidone gjorde han sex bräder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Och tu annor på de tu hörnen af tabernaklet baktill;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Så att hwartdera af de båda parade sig med sitt hörnebräde, ifrå nedan uppåt, och kommo tillhopa ofwantill med en krampo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Så att bräden wordo åtta, och silfwerfötterna sexton; under hwart twå fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Och gjorde han skottstänger af furoträ; fem till bräden på den ena sidone af tabernaklet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Och fem på den andra sidone; och fem bak westantill;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Och gjorde skottstångena, så att hon öfwer bräden allt bortåt skjuten wardt, ifrå den ena ändan till den andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Och öfwerdrog bräden med guld. Men deras ringar gjorde han af guld till skottstängerna, och öfwerdrog stängerna med guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Och gjorde Cherubim på förlåten konsteliga af gult silke, skarlakan, rosenrödt, och hwitt twinnadt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Och gjorde till den samma fyra stolpar af furoträ, och öfwerdrog dem med guld, och deras knappar af guld, och göt dertill fyra silfwerfötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Och gjorde ett kläde uti tabernaklets dörr, stickadt af gult silke, skarlakan, rosenrödt, och hwitt twinnadt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Och fem stolpar dertill med deras knappar, och öfwerdrog deras knappar och gjordar med guld; och fem kopparfötter dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Och Bezaleel gjorde arken af furoträ, halftredje aln lång, halfannor aln bred och hög;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Och öfwerdrog honom med klart guld innan och utan; och gjorde honom en gyldene krans omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Och göt fyra gyldene ringar till hans fyra hörner; på hwarje sidone twå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Och gjorde stänger af furoträ, och öfwerdrog dem med guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Och satte dem uti ringarna på sidone af arken, så att man kunde bära honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Och han gjorde nådastolen af klart guld, halftredje aln lång, och halfannor aln bred;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Och gjorde twå Cherubim af tätt guld, på båda ändarna af nådastolenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'En Cherub på denna ändan; en annan på den andra ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Och de Cherubim utsträckte sina wingar ofwan öfwer, och öfwerskylde dermed nådastolen, och deras anlete stodo twärtemot hwarsannars; och sågo på nådastolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Och han gjorde bordet af furoträ, twå alnar långt, en aln bred, och halfannor aln högt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Och öfwerdrog det med klart guld, och gjorde der en gyldene krans omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Och gjorde der ena listo omkring, ena hand bredt hög, och gjorde en gyldene krans omkring listona;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Och göt dertill fyra gyldene ringar; och satte dem på de fyra hörnen uppå der fyra fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Hardt under listone, så att stängerna woro derut, der man bordet med bar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Och gjorde stängerna af furoträ, och öfwerdrog dem med guld, att man skulle bära bordet dermed;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Och gjorde deßlikes, af klart guld, redskapen på bordet, fat, skedar, kannor och skålar, der man med ut och in skänkte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Och gjorde ljusastakan af klart tätt guld; derpå woro läggen, rör, skålar, knöpar och blommor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sex rör gingo ut af sidorna, på hwarjo sidone tre rör;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tre skålar, såsom mandelnötter, woro på hwar rör, med knöpar och blommor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Men på ljusastakanom woro fyra skålar med knöpar och blommor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Inunder twå rör en knöp, så att sex rör gingo ut af honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Och hans knöpar och rör deruppå; och war allt klart tätt guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Och gjorde de sju lampor, med deras ljusanäpor och släcketyg, af klart guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Af en centener guld gjorde han honom, och all hans tyg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Han gjorde ock rökaltaret af furoträ, en aln långt och bredt, rätt fyrakant, och twå alnar högt med sin horn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Och öfwerdrog det med klart guld, deß tak och wäggar allt omkring och deß horn, och gjorde der en krans omkring af klart guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Och twå gyldene ringar under kransen på båda sidor, så att man satte stängerna deruti, och bar det dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Men stängerna gjorde han af furoträ, och öfwerdrog dem med guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Och gjorde den helga smörjooljon, och rökwerk af rent speceri, efter apothekarekonst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Och han gjorde brännoffersaltaret af furuträ, fem alnar långt och bredt, rätt fyrakant, och tre alnar högt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Och gjorde fyra horn, som utgingo af fyra hörnen, och öfwerdrog dem med koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Och gjorde allahanda redskap till altaret, tråg, skoflar, bäcken, eldgafflar, kolpannor; allt af koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Och gjorde på altaret ett galler, såsom ett nät omkring, af koppar, ifrå nedan uppåt, intill halfwäges på altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Och göt fyra ringar på de fyra hörnen af koppargallret till stängerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Dem gjorde han af furoträ, och öfwerdrog dem med koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Och satte dem in uti ringarna på sidone af altaret, att man bar det dermed; och gjorde det ihålt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Och gjorde twättekaret af koppar, och dess fot ock af koppar, twärtemot härarna, som för dörrene af wittnesbördsens tabernakel lågo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Och gjorde han en gård, på södra sidone en bonad, hundrade alnar lång, af twinnadt hwitt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Med hans tjugu stolpar och tjugu fötter af koppar; men deras knappar och gjordar af silfwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Sammalunda ock på norra sidone hundrade alnar, med tjugu stolpar och tjugu fötter af koppar; men deras knappar och gjordar af silfwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'På westra sidone femtio alnar, med tio stolpar och tio fötter; men deras knappar och gjordar af silfwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'På östra sidone femtio alnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Femton alnar på hwarje sidone wid porten af gårdenom; ju med tre stolpar, och tre fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Så att aller bonaden till gården war af twinnadt hwitt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Och fötterna till stolparna af koppar, och deras knappar och gjordar af silfwer; så att deras knappar woro öfwerdragne med silfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Men deras gjordar woro af silfwer på alla stolparna i gården.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Och klädet till ingången på gårdenom gjorde han stickadt af gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke; tjugu alnar långt, och fem alnar högt, efter det mått, som bonaden war till gården;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Dertill fyra stolpar och fyra fötter af koppar; och deras knappar af silfwer, och deras knöpar öfwerdragne; och deras gjordar af silfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Och alla pålarna till tabernaklet, och till gården allt omkring, woro af koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Detta är nu summan af det, som wittnesbördsens tabernakel tillhöre, det förtäljdt är, sosom Mose sagt hade, till Leviternas Gudstjenst under Ithamars hand, som war Prestens Aarons son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Hwilket Bezaleel, Uri son, Hurs sons, af Juda slägte, gjorde, allt såsom HERren hade budit Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Och med honom Aholiab, Ahisamachs son, af Dans slägte, en mästare till till snida, till wirka och till sticka med gult silke, skarlakan, rosenrödt, och hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Allt det guld, som förarbetadt wardt i detta hela helgedomens werk, det till weftoffer gifwet wardt, war nio och tjugu centener, sjuhundrade och tretio siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Men silfret, som kom ifrå menighetene, war hundrade centener; tusende, sjuhundrade fem och sjutio siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Så mång hufwud, så många halfwa siklar, efter helgedomens sikel, af alla dem som räknade wordo, ifrå tjugu år och deröfwer, sexhundradetusend, tretusend, femhundrade och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Utaf de hundrade centener silfwer göt man fötterna till helgedomen, och fötterna till förlåten; hundrade fötter utaf hundrade centener, ju en centener till foten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Men utaf de tusend, sjuhundrade och fem och sjutio siklar, wordo gjorde knapparna till stolparna; och deras knöpar öfwerdragne, och deras gjordar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Weftoffret af koppar war sjutio centener; tutusend och fyrahundrade siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Deraf wordo gjorde fötterna uti dörrene till wittnesbördsens tabernakel, och kopparaltaret, och koppargallret dertill; och all redskapen till altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Dertill fötterna till gården allt omkring, och fötterna i ingången på gårdenom; alle pålarna till tabernaklet, och alle pålarna till gården allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Men af det gula silket, skarlakanet och rosenrödt, gjorde de Aaron ämbetskläder, till att tjena i helgedomenom; såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Och han gjorde lifkjortelen af guld, gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Och utslog guldet, och skar det i trådar, så att man kunde konsteliga wirka det in med det gula silket, skarlakan, rosenrödt, och hwita silket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Och gjorde så, att man sammanfogde honom på båda axlar, och band honom tillhopa på båda sidor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Och bältet war af samma konst och werk, af guld, gult silke, skarlan, rosenrödt, och twinnadt hwitt silke, såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Och de tillredde twå onichinerstenar, omfattade i guld; utgrafna af stensnidare med Israels barnas namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Och fäste dem på axlarna af lifkjortelen, att de skulle wara åminnelsestenar till Israels barn; såsom HERren Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Och de gjorde skölden efter den konst och werk, som lifkjortelen war, af guld, gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Så att han war fyrakant och twefald, en hand lång och bred;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Och fyllde honom med fyra radar stenar. Den första raden war en sarder, topaz och smaragd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Den andra, en rubin, saphir och diamant;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Den tredje, en lyncurer, achat och amethist;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Den fjerde, en turkos, onicher och jaspis; omfattade i guld i alla radarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Och stenarna stodo grafne af stensnidarena, efter de tolf Israels barnas namn; hwardera af sitt namn, efter de tolf slägten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Och de gjorde till skölden kedjor uppåt af klart guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'och tu gyldene spänner, och twå gyldene ringar; och fäste de twå ringar wid tu hörnen af skölden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Och de twå gyldene kedjorna satte de uti de twå ringar på hörnen af skölden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Men de twå ändar af de gyldene kedjor läto de komma intill de tu spännen; och hakade dem intill hörnen af lifkjortelen twärtemot hwartannat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Och gjorde twå andra gyldene ringar, och knäppte dem wid de andra tu hörnen af skölden nedantill, så att han låg hardt inpå lifkjortelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Och gjorde twå andra gyldene ringar; dem gjorde de på de tu hörnen nedantill på lifkjortelen, twärtemot hwarannan, der lifkjortelen nedantill sammangår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Och wardt skölden med sina ringar knäppt intill lifkjortelens ringar med ett gult snöre, så att det låg hardt intill lifkjortelen, och icke for löst ifrå lifkjortelen; såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Och han gjorde silkeskjortelen under lifkjortelen, den all wirkad war med gult silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Och hans hufwudsmog midt ofwanuppå, och en borda omkring hufwudsmoget fållad, att det icke skulle gå sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Och de gjorde på hans fåll granatäple af gult silke, skarlakan, rosenrödt, och twinnadt hwitt silke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Och gjorde bjellror af klart guld; dem satte de emellan de granatäplen allt omkring på fållen af den silkeskjortelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Ju ett granatäple, och en bjellra allt omkring, till att tjena deruti; såsom HERren hade budit Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Och gjorde deßlikes den trånga kjortelen, wirkad af hwitt silke, till Aaron och hans söner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Och hatten af hwitt silke, och sköna hufwor af hwitt silke, och nederklädet af twinnadt hwitt linne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Och det stickade bältet af twinnadt hwitt silke, gult silke, skarlakan, rosenrödt; såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'De gjorde ock ännespannet på den helga kronona af klart guld, och grofwo skrift deruppå; HERRANS HELIGHET;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Och bundo ett gult snöre derwid, att det måtte knäppas ofwanpå hatten; såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Alltså wardt fullbordadt hela werket till wittnesbördsens tabernakels boning. Och Israels barn gjorde allt det HERren hade budit Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Och hade honingen till Mose, tabernaklet och all deß redskap, spänner, bräder, skottstänger, stolpar, fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Täckelset af rödlett wädurskinn; täckelset af tackskinn, och förlåten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Wittnesbördsens ark med sina stänger; nådastolen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Bordet med all deß redskap, och skådobröden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Den sköna ljusastakan, tillreddan med lamporna, och all sin redskap, och oljo till lysning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Gyldene altaret och smörjelsen, och godt rökwerk; klädet i tabernaklets dörr;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Kopparaltaret och deß koppargallrar, med sina stänger, och all sin redskap, twättekaret med sin fot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Bonaden till gården med sina stolpar och fötter, klädet till ingången åt gårdenom med sin tåg och pålar, och all redskap, som behöfdes till boningenes tjenst, wittnesbördsens tabernakels;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Aarons Prestens ämbetskläder till att tjena i helgedomenom; och hans söners kläder, till att de skulle göra Prestaämbetet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'All ting, såsom HERren hade budit Mose, gjorde Israels barn till alla denna tjenstena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Och Mose såg på allt detta werket, att de gjorde såsom HERren budit hade, och wälsignade dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'På första dagen i den första månaden skall du uppsätta wittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Och skall deruti sätta wittnesbördsens ark, och hänga förlåten för arken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Och skall bära bordet dit, och reda det till, och ställa der ljusastakan, och lamporna sätta deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Och skall sätta det gyldene rökaltaret för wittnesbördsens ark, och upphänga klädet i dörrene af tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Och bränneoffersaltaret skall du sätta inför dörrene af wittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Och twättekaret emellan wittnesbördsens tabernakel och altaret, och låta der watten in;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Och göra gården omkring, och upphänga klädet i ingången på gårdenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Och skall taga smörjooljo, och smörja tabernaklet, och allt det derinne är; och skall wiga det med all deß redskap, att det skall wara heligt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Och skall smörja bränneoffersaltaret med all sin redskap, och wigat, att det skall wara aldrahelgast.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Skall du också smörja och wiga twättekaret med deß fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Och du skall hafwa Aaron och hans söner fram för dörrena af wittnesbördsens tabernakel, och twå dem med watten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Och kläda på Aaron de helga kläden, och smörja och wiga honom, att han skalll wara min Prest;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Och hafwa deßlikes hans söner fram, och kläda uppå dem de trånga kjortlarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Och smörja dem, såsom du hafwer smort deras fader, att de skola wara mine Prester. Och denna smörjelsen skola de hafwa till ett ewigt Presterskap när deras efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Och Mose gjorde allt det HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Så wardt tabernaklet uppsatt i de andra årena på första dagenom i den första månaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Och då Mose uppsatte det, satte han fötterna och bräden, och skottstängerna, och reste upp stolparna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Och sträckte ut öfwertäckelset till ett tabernakel och lade deß täckelse ofwanuppå, såsom HERren honom budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Och tog wittnesbördet, och lade det in i arken, och satte stängerna på arken, och satte nådastolen ofwanpå arken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Och bar arken in i tabernaklet, och hängde förlåten för wittnesbördsens ark, såsom HERren honom budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Och satte bordet in uti wittnesbördsens tabernakel, på den sidon i tabernaklet norut, utanför förlåten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Och gjorde bröd redo deruppå för HERranom, såsom HERren honom budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Och satte deßlikes ljusastakan derin twärtöfwer ifrå bordet, på den sidon i tabernaklet söderut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Och lät komma lamporna deruppå för HERranom, såsom HERren honom budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Och satte gyldene altaret derin för förlåten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Och rökte deruppå med godt rökwerk, såsom HERren honom budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Och hängde klädet in i dörrena af tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Men bränneoffersaltaret satte han för dörrena af wittnesbördsens tabernakel, och offrade deruppå bränneoffer och spisoffer, såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Och twättekaret satte han emellan wittnesbördsens tabernakel och altaret, och lät watten derin, till att twå sig med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Och Mose, Aaron och hans söner twådde deras händer och fötter derutur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Förty de måste twå sig, när de gingo in uti wittnesbördsens tabernakel, eller framträdde till altaret såsom HERren dem budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Och gjorde han gården redo, kringom tabernaklet, och omkring altaret, och hängde klädet i ingången på gårdenom. Och alltså fullkomnade Mose det hela werket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Och så öfwertäckte en molnsky wittnesbördsens tabernakel; och HERrans härlighet uppfyllde tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Och Mose kunde icke gå in uti wittnesbördsens tabernakel, så länge som molnskyn blef deröfwer, och HERrans härlighet uppfyllde tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Och när molnskyn gaf sig upp ifrå tabernaklet, så foro Israels barn, så ofta som de reste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'När molnskyn icke gaf sig upp, då foro de intet, allt intill den dagen han sig uppgaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Förty HERrans molnsky war om dagen öfwer tabernaklet, och om natten war eld derinne, för hela Israels hus ögon, så länge de reste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Och HERren kallade Mose, och talade med honom utu wittnesbördsens tabernakel, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Tala med Israels barn, och säg til dem: Hwilken ibland eder will göra HERranom et offer, han göre det af boskap; af fä och af får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Will han göra et bränneoffer af oxar, så offre en stutkalf, den ingen brist hafwer, inför dörene af wittnesbördsens tabernakel, at det skall warda HERranom tacknämligit af honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Och lägge sina hand på bränneoffrets hufwud, så warder det tacknämligit, och försonar honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Och skall slagta den stuten för HERranom: Och Presterne Aarons söner skola bära blodet fram, och stänka allt omkring på altaret, som är för dörene af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Och huden skall bränneoffrena aftagas, och det skall huggas i stycken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Och Prestens Aarons söner skola göra en eld på altaret, och lägga der wed uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Och skola lägga stycken, nemliga, hufwudet och kroppen uppå weden, som ligger på eldenom på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Men inelfwerna och fötterna skall man twå med watn, och Presten skall allt detta upbränna på altaret til et bränneoffer. Detta är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Will han göra bränneoffer af får eller getter, så offre det mankön är, det ingen brist hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Och skall slagta det utmed sidone af altaret, som norr ut är för HERranom. Och Presterne Aarons söner skola stänka dess blod på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Och man skall hugga det i stycken. Och Presten skall lägga hufwudet och kroppen på weden och elden, som på altaret är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Men inelfwerna och fötterna skall man twå med watn. Och Presten skall allt det offra och upbränna på altaret til bränneoffer. Detta är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Will han ock göra HERranom et bränneoffer af foglar, så göre det af turturdufwor, eller af unga dufwor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Och Presten skall hafwat fram til altaret, och först wrida thy halsen af, at det må upbrännas på altaret, och låta utblöda blodet på altarens wägg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Och dess kräfwo med fjädrarna skall man kasta wid altaret öster ut på askohopen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Och skall bryta dess wingar sönder, men icke rifwa dem ifrå. Och alltså skall Presten upbränna det på altaret, på wedenom och eldenom, til et bränneoffer. Detta är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Will en själ göra HERranom et spisoffer, så skall det wara af semlomjöl; och skall gjuta der oljo uppå, och lägga rökelse deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Och bära det så till Presterna Aarons söner. Då skall Presten taga sina hand fulla af det samma semlomjölet och oljone, samt med allt rökelset, och bränna det up på altaret til en åminnelse. Detta är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Det öfwer är af spisoffret skall höra Aaron och hans söner til. Det skall wara det aldrahelgasta af HERrans offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Men will han göra et spisoffer af det i ugn bakas, så tage kakor af semlomjöl, osyrade, beblandade med oljo, och osyrade tunkakor, smorda med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Men är ditt spisoffer af något det som bakadt är i panno, så skall det wara af osyradt semlomjöl, beblandadt med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Och du skalt delat i stycken, och gjuta der oljo uppå; så är det et spisoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Är ock ditt spisoffer något det på halster bakadt är, så skalt du göra det af semlomjöl med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Och det spisoffer, som du af sådana wilt göra HERranom, det skalt du bära till Presten, han skall hafwa det fram til altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Och häfoffra det samma spisoffret til en åminnelse, och bränna det up på altaret. Det är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Det öfwer är skall höra Aaron och hans söner til. Det skall wara det aldrahelgasta af HERrans offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Allt spisoffer, som I wiljen offra HERranom, skolen I göra utan surdeg; ty ingen surdeg eller hannog skall der ibland upbränd warda HERranom för offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Men til en förstling skolen I offra dem HERRanom; men på intet altare skola de komma til en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Allt ditt spisoffer skalt du salta. Och ditt spisoffer skall aldrig wara utan dins Guds förbunds salt; ty uti alt ditt offer skalt du offra salt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Wilt du göra et spisoffer HERranom af första frukterna, skalt du torka de grona axen wid eld, och stöta dem små, och så offra spisoffer af dina första frukter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Och skalt låta der oljo uppå, och lägga rökelse deruppå; så är det et spisoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Och Presten skall taga af det stötta, och af oljone med allt rökelset, och upbränna det til en åminnelse. Det är HERranom et offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Om hans offer är et tackoffer, af fä, antingen oxe eller ko, skall han offra för HERranom det utan wank är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Och skall lägga sina hand på dess hufwud, och slagta det för dörene af wittnes bördsens tabernakel. Och Presterne Aarons söner skola stänka blodet på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Och skall offra af det tackoffret HERranom, nemliga, allt det feta på inelfwerna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Och båda njurarna med det feta som der på är wid länderna, och det nätet öfwer lefrena med njurarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Och Aarons söner skola det upbränna på altaret för et bränneoffer på wedenom, som ligger på eldenom. Det är et offer, som wäl luktar för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Men will han göra HERranom et tackoffer af små boskap, antingen gummar eller gymmer, så skall det wara utan all wank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Är det et lamb, så skall han hafwa det fram för HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Och skall lägga sina hand på dess hufwud, och slagta det inför wittnesbördsens tabernakel. Och Aarons söner skola stänka dess blod på altaret allt omkring:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Och alltså offra HERranom af tackoffrena, nemliga, dess feta; hela stjerten med ryggenom, det feta som är öfwer inelfwen, samt med allt det feta som inwärtes är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Och båda njurarna med allt det feta som derpå är wid länderna, och det nätet om lefrena med njurarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Och Presten skall upbränna det på altaret, til offrens spis HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Är hans offer en get, och bär henne fram för HERran:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Skall han lägga sina hand på hennes hufwud, och slagta henne för wittnesbördsens tabernakel. Och Aarons söner skola stänka hennes blod på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Och skall deraf offra et offer HERranom, nemliga, det feta som är omkring inelfwerna, och allt det feta som inwärtes är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Båda njurarna och det feta som derpå är wid länderna, och nätet öfwer lefrena med njurarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Och Presten skall upbrännat på altaret til offrens spis, til en söt lukt. Allt det feta hörer HERranom til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Det ware en ewig sed med edra efterkommande uti alla edra boningar, at I intet fett eller blod äten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Tala med Israels barn, och säg: Om en själ syndar af owetenhet emot något HERrans bud, som hon icke göra skulle:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Nemliga, om en Prester, som smord är, syndar, så at han förargar folket, han skall för sina synd, som han gjort hafwer, bära fram en ung stut, den utan wank är, HERranom til et syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Och skall hafwa stuten fram för HERran inför dörene af wittnesbördsens tabernakel, och lägga sina hand på hans hufwud, och slagta honom för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Och Presten, som smord är, skall taga af hans blod, och bära in uti wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Och skall doppa sitt ttnger uti blodet, och stänka dermed sju resor för HERranom inför förlotten i det helga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Och skall af samma blod stryka på hornen af rökaltaret, som står för HERranom in uti wittnesbördsens tabernakel, och gjuta allt blodet på bottnen af bränneoffrens altare, som står för dörene til wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Och allt det feta af syndoffret skall han häfoffra: Nemliga, det feta som är öfwer inelfwerna, och allt det feta som inwärtes är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Båda njurarna med det feta som derpå är wid länderna, och det nätet öfwer lefrena med njurarna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Såsom man häfoffrar i tackoffret af oxanom; och skall upbrännat på bränneoffrens altare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Men hudena af stuten med allt köttet, samt med hufwudet, och fötterna, och inelfwerna, och goret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Det skall han allt utföra utu lägret, på et rent rum, dit man slår askona, och skall upbrännat på wed i elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Om en hel menighet i Israel försåge sig, och gerningen wore fördold för deras ögon, så at de gjort hade emot något HERrans bud, det de icke göra skulle, och wordo så brotslige:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Och förnummo så sedan sina synd, som de gjort hade; så skola de hafwa en ung stut fram til syndoffer, och ställa honom för dörene af wittnesbördsens tabernakel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Och de äldste af menighetene skola lägga deras händer på hans hufwud för HERranom, och slagta den stuten för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Och Presten, som smord är, skall bära blodet af stuten in uti wittnesbördsens tabernakel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Och doppa der in med sitt finger, och sju resor stänka för HERranom inför förlotten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Och skall stryka af blodet på hornen af altaret, som står för HERranom uti wittnesbördsens tabernakel, och allt det andra blodet gjuta på bottnen af bränneoffers altaret, som står för dörene af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Allt hans feta skall han häfoffra, och upbränna på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Och skall göra med denna stuten, såsom han gjorde med syndoffers stutenom. Och alltså skall Presten försona dem, och det warder dem förlåtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Och skall han föra stuten utu lägret och bränna honom up, såsom han upbrände den förra stuten. Det skall wara syndoffret för menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Om en Förste syndar, och något gör emot HERrans sins Guds bud, det han icke göra skulle, och warder brotslig owetandes:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Och förnimmer sina synd, som han gjort hafwer; han skall frambära til offers en getabock utan all wank:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Och lägga sina hand på bocksens hufwud, och slagta honom på det rum, der man slagtar bränneoffer för HERranom: Det ware hans syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Sedan skall då Presten taga af syndoffrens blod med sitt finger, och stryka det på hornen af bränneoffers altaret, och det andra blodet gjuta på botnen af bränneoffrens altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Men allt hans feta skall han upbränna på altaret, lika såsom det feta af tackoffrena: Och alltså skall Presten försona hans synd, och det warder honom förlåtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Om en själ af meniga folket syndar owetandes, så at hon owetandes gör emot något HERrans bud, det hon icke göra skulle, och blifwer så brotslig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Eller förnimmer sina synd, som hon gjort hafwer; hon skall bära fram för et offer ena get utan wank, för syndena som hon gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Och skall lägga sina hand på syndoffrens hufwud, och slagta det på bränneoffrens rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Och Presten skall taga af blodet med sitt finger, och stryka på hornen af bränneo ffrens altare, och allt blodet gjuta på botnen af altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Allt hennes feta skall han aftaga, såsom han aftager det feta af tackoffrena, och skall upbränna på altaret til en söt lukt HERranom: Och alltså skall Presten försona henne, och det warder henne förlåtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Men bär han fram et får til syndoffer, så bäre en gymmer utan wank:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Och lägge sina hand på syndoffrens hufwud, och slagte det til et syndoffer, på det rummet, der man slagtar bränneoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Och Presten skall taga af blodet med sitt finger, och stryka på hornen af bränneoffrets altare, och gjuta allt blodet på botnen af altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Men allt dess feta skall man aftaga, såsom han aftager det feta af tackoffrets fåre, och skall det upbränna på altaret til et HERrans offer. Och alltså skall Presten försona hans synd, den han gjort hafwer, och honom warder det förlåtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Om en själ syndar, så at hon hörer några bannor, och hon är dess wittne, eller det sett eller förfarit hafwer, och icke hafwer tilsagt, hon är brotslig til en missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Eller om en själ kommer wid något orent, antingen et as af et orent djur, eller af boskap, eller af matkar, och wisste det icke, hon är oren, och är brotslig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Eller om hon kommer wid ena orena mennisko, i hwad som hälst orenhet der menniskan kan med oren warda, och wisste det icke, och förnimmer det sedan, den är brots lig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Eller om en själ swär, så att henne går af munnen at göra illa eller wäl, såsom ene mennisko wäl händer at swärja, och wisste det icke, och förnimmer det sedan, den warder brotslig på et af detta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'När nu händer, at hon brotslig är på etdera, och bekänner at hon derpå syndat hafwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Så skall hon för detta hennes synds brott, som hon gjort hafwer, bära fram HERranom af hjordenom et får eller ena get, som foster haft hafwer, til syndoffer; så skall Presten försona henne hennes synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Förmår hon icke et får, så bäre HERranom för sitt brott, som hon brutit hafwer, twå turturdufwor, eller twå unga dufwor; ena til syndoffer, den andra till bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Och bäre dem til Presten, han skall den första göra til syndoffer, och wrida halsen sönder af henne, och dock icke rifwa hufwudet ifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Och stänka med syndoffrets blod på altarens wägg, och låta det blodet, som öfwer är, utblöda på altarens botn: Det är syndo ffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Den andra skall han göra till bränneoffer efter dess rätt: Och alltså skall Presten försona henne hennes synd, som hon gjort hafwer, och det warder henne förlåtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Förmår hon icke twå turturdufwor, eller twå unga dufwor, så bäre fram sitt offer för sina synd, en tiondedel af ett Epha semlomjöl til syndoffer; men ingen oljo skall han låta deruppå, eller rökelse låta komma deruppå; ty det är et syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Och han skall bärat til Presten, och Presten skall taga deraf en hand full til åminnelse, och bränna det up på altaret HERranom til et offer: Detta är et syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Och Presten skall så försona honom hans synd, som han gjort hafwer, och det warder honom förlåtet. Och det skall höra Prestenom til såsom et spisoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Om en själ förtager sig, så at hon med owetenhet syndar på något, som HERranom wigdt är; skall hon bära HERranom skuldoffer, en wädur af hjordenom utan wank, den twå siklar silfwer är wärd, efter helgedomens sikel, til skuldoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Dertil hwad han syndat hafwer på det wigda, skall han det igengifwa, och ändå gifwa femtedelen derutöfwer. Och skall gifwat Prestenom, han skall försona honom med skuldoffrets wädur, så warder det honom förlåtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Om en själ syndar, och gör emot något HERrans bud, det hon icke göra skulle, och wisste det icke, hon är brotslig, och är skyldig åt den missgerningene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Och skall bära en wädur af hjordenom utan wank, den et skuldoffer wärd är, til Presten. Han skall försona honom hans owetenhet, den han gjort hafwer, och wisste det icke, så warder det honom förlåtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Det är skuldoffret, til hwilket han HERranom brotslig är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Om en själ syndar, och förtager sig för HERranom, så at han nekar sinom nästa det han honom befallt hafwer, eller det han honom i godo tro handfått hafwer, eller det han med wåld tagit, eller med orätt under sig slagit hafwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Eller det tappadt war funnit hafwer, och säger der nej til med en falsk ed, och hwad det hälst kan wara, det en menniska emot sin nästa bryter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'När nu sker, at han så syndar, och sig förbryter, så skall han igengifwa, hwad han så med wåld tagit hafwer, eller med orätt under sig slagit, eller det honom befaldt war, eller det han funnit hafwer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Eller der han den falska eden öfwer gjort hafwer, det skall han alltsammans igengifwa, och ändå gifwa femtedelen deröfwer, honom som det tilhörde, på den dagen han sitt skuldoffer gifwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Men för sina skuld skall han bära HERranom til Presten en wädur af hjorden utan wank, den et skuldoffer wärd är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Så skall Presten försona honom för HERranom; så warder honom förlåtet allt det han gjorde, der han sig med förbröt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Bjud Aaron och hans söner, och säg: Detta är bränneoffrets lag. Bränneoffret skall brinna på altarens eldstad, alla nattena intil morgonen; och allena altarens eld skall derpå brinna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Och Presten skall kläda på sig sin linna kjortel, och det linna nederklädet på sin kropp; och skall uptaga askona, som af bränneoffrets eld kommer uppå altaret, och lägga den jemte wid altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Och skall kläda sig af, och kläda sig i annor kläde, och bära askona ut om lägret på et rent rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Elden på altaret skall brinna, och aldrig utsläckas. Presten skall hwar morgon uptända weden deruppå, och ställa bränneo ffret deruppå, och bränna deruppå det feta af tackoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Alltid skall elden brinna på altaret, och aldrig utsläckas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Och detta är spisoffrens lag, det Aarons söner offra skola för HERranom på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Man skall häfoffra sin hand full af semlomjöl, af spisoffret och dess oljo, och allt rökelset, som ligger på spisoffret, och skall uptändat på altarena, til en söt lukt, HERranom till åminnelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Det öfwer är skall Aaron och hans söner förtära, och skola ätat osyradt på heligt rum, i gårdenom til wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'De skola intet baka med surdeg; ty det är deras del, den jag dem af mitt offer gifwit hafwer: Det skall wara dem det aldrahelgasta, lika såsom syndoffret och skuldoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Det mankön är ibland Aarons barn skola det äta. Det ware edrom efterkommandom en ewig rätt om HERrans offer. Ingen skall komma derwid, utan han är wigd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Detta skall wara Aarons och hans söners offer, som de skola offra HERranom på deras wigelsedag. Tiondedelen af et Epha semlomjöl til ewigt spisoffer, hälftena om morgonen, och hälftena om aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Uti panno skalt du göra det med oljo, och bära det bakadt fram, och i stycken skalt du det offra HERranom til en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Och Presten, som af hans söner i hans stad smord warder, han skall göra det. Detta är en ewig rätt HERranom. Det skall allt upbrändt warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Ty allt spisoffer, som för en Prest sker, skall förtäras af eld, och icke ätas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Tala til Aaron och hans söner, och säg: Detta är syndoffrens lag: på den staden, der du slagtar bränneoffret, der skalt du ock slagta syndoffret för HERranom: Det är det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Presten, som syndoffret offrar, skall det äta på heligt rum, uti gårdenom til wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Ingen skall komma wid dess kött, utan han är wigd. Och den som en klädnad stänker af dess blod, han skall twå sig på heligt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Och krukan, der det uti kokadt är, skall sönderslås. Är det en koppargryta, så skall man skura henne, och skölja med watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Det mankön är ibland Presterna, de skola äta deraf; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Men allt det syndoffer, hwars blod burit warder in uti wittnesbördsens tabernakel til försoning i thy helga, det skall man icke äta, utan upbränna det med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Och detta är skuldoffrens lag, och det är det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'På det rummet, der man slagtar bränneoffret, skall man ock slagta skuldoffret, och stänka dess blod på på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Och allt dess feta skall man offra, stjerten och det feta som är på inelfwerna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Båda njurarna med det feta som der på är wid länderna, och nätet öfwer lefrena med njurarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Och Presten skall upbränna det på altaret HERranom til et offer. Det är et skuldoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Det mankön är ibland Presterna skola det äta på heligt rum; ty det är det aldra helgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Såsom syndoffret, så skall ock skuldoffer wara: Bägges deras skall en lag wara. Och skall höra Prestenom til, som derigenom försonar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Den Prester något bränneoffer offrar, honom skall tilhöra huden af bränneoffret, som han offrat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Och allt spisoffer, som i ugn, eller på halster, eller uti panno bakadt warder, skall höra Prestenom til, som det offrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Och allt spisoffer, som med oljo blandadt eller tort är, det skall allom Aarons barnom tilhöra, så thy eno som thy andro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Och detta är tackoffers lag, det man HERranom offrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wilja de göra et lofoffer, så skola de o ffra osyrade kakor, blandade med oljo, och osyrade tunkakor, bestrukna med oljo, och i panno bakade semlokakor, blandade med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Och sådana offer skola de göra på en kako af syradt bröd til sitt tackoffers lofoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Och et af thy allo skall offras HERranom til häfoffer, och skall höra Prestenom til, som stänker tackoffrens blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Och lofoffrens kött, i sitt tackoffer, skall ätas på samma dagen, som det offradt warder, och intet låtas qwart intil morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Och ehwad det är et löfte eller friwiljogt offer, så skall det på samma dagen ätit warda, som det offradt är: Om något qwart blifwer til den andra dagen, skall man ändå ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Men hwad qwart blifwer af offradt kött intil tredje dagen, det skall upbrännas i elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Och om någor äter på tredje dagen af det offrade köttet af hans tackoffer, så blifwer han icke tacknämlig, som det offrat hafwer, det skall icke heller warda honom tillräknadt, utan det blifwer en styggelse. Och hwad själ som deraf äter, hon är brotslig til en missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Och det kött som kommer wid något orent, det skall icke warda ätit, utan upbrändt i elde. Den der ren är til lekamen, han skall äta det köttet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Och den själ som äter af tackoffrens kött, det HERranom tilhörer, hennes orenhet ware öfwer henne, och hon skall warda utrotad utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Och om en själ kommer wid något det orent är, ware sig oren menniska, boskap, eller hwad eljest styggeligit är, eller ock äter af tackoffrens kött, det HERranom tilhörer, den skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Tala med Israels barn, och säg: I skolen intet fett äta af fä, lambom och getom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Men det feta af et as, och hwad af wilddjur rifwit är, bruker eder til allahanda nytto; men icke skolen I ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Ty den som äter det feta af den boskap, som HERranom til offer gifwen är, den samma själen skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'I skolen ock intet blod äta, antingen af boskap, eller af foglar, der I bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Hwilken själ som äter något blod, hon skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Tala med Israels barn, och säg: Den som HERranom sitt tackoffer göra will, han skall ock bära med hwad som HERranom til et tackoffer tilhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Han skall med sine hand bärat fram til HERrans offer, nemliga, det feta på bröstena skall han frambära, samt med bröstet, at de skola warda ett weftoffer för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Och Presten skall upbränna det feta på altaret. Och bröstet skall höra Aaron til, och hans söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Och den högra bogen skola de gifwa Prestenom til häfoffer af deras tackoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Och hwilken ibland Aarons söner offrar blodet af tackoffret, och det feta, han skall ock hafwa den högra bogen på sin del.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Ty weftebröstet och häfwebogen hafwer jag tagit af Israels barn, af deras tack offer, och hafwer gifwit det Prestenom Aaron, och hans söner, til en ewig rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Detta är Aarons och hans söners wigelse af HERrans offer, på den dagen då de öfwerantwardade wordo til at wara HERranom Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Då HERren böd, på den dagen då han dem wigde, hwad dem af Israels barnom gifwas skulle, til en ewig rätt, allom deras efterkommandom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Och detta är bränneoffrens lag, spiso ffrens, syndoffrens, skuldoffrens, fylleoffrens och tackoffrens:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Det HERren på Sinai berg Mose böd, den dagen då han böd honom til Israels barn, at de skulle offra deras offer HERranom uti den öknene Sinai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Tag Aaron och hans söner med honom, samt med deras kläder, och smörjooljon, och en stut til syndoffer; twå wädrar, och en korg med osyradt bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Och församla alla menighetena inför dörene af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose gjorde såsom HERren honom böd, och församlade menighetena inför dörene af wittnesbördsens tabernakel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Och sade til dem: Detta är det, som HERren budit hafwer at göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Och tog Aaron och hans söner, och twådde dem med watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Och drog honom den linna kjortelen uppå, och bandt bältet omkring honom, och klädde på honom den gula silkeskjortelen, och fick honom lifkjortelen uppå, och gjordade honom öfwer lifkjortelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Och satte på honom skölden, och i skölden Ljus och Fullkomlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Och satte honom hatten på hans hufwud, och satte på hatten ofwanför hans änne, et gyldene span på den helga kronona; såsom HERren Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Och Mose tog smörjooljon, och smorde tabernaklet med allt det deruti war, och wigde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Och stänkte dermed sju resor på altaret, och smorde altaret med all sin redskap, twättekaret med sinom fot, at det skulle warda wigdt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Och gjöt af smörjooljone på Aarons hufwud, och smorde honom, at han skulle warda wigd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Och hade Aarons söner fram, och drog dem linna kjortlar uppå, och gjordade dem med bälter, och bandt dem hufwor uppå; såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Och lät hafwa fram til sig en stut til syndoffer. Och Aaron och hans söner lade si na händer på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Sedan slagtades han. Och Mose tog af blodet, och strök med fingret på hornen af altaret allt omkring, och skärde altaret, och gjöt blodet på altarens botn, och wigde det, at han skulle försonat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Och tog allt det feta af inelfwerna; nätet öfwer lefrena, och båda njurarna med det feta derpå är, och upbrände det på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Men stuten med hans hud, kött och träck, brände han up i elde utanför lägret, såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Och hade en wädur fram till bränneo ffer: Och Aaron med hans söner lade sina händer på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Sedan slagtades han. Och Mose stänkte af blodet på altaret allt omkring:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Högg wäduren i stycken, och brände up hufwudet och stycken:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Och twådde inelfwerna och fötterna med watn, och brände så hela wäduren up på altarena. Det war et bränneoffer til en söt lukt, et offer HERranom; såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Han hade ock fram den andra wäduren, som är fylleoffrens. Och Aaron med hans söner lade sina händer på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Sedan slagtades han. Och Mose tog af hans blod, och strök på högra örnatimpen af Aaron, och uppå tuman af högra handene, och på den största tåna af hans högra fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Och hade fram Aarons söner, och strök af blodet på deras högra örnatimp, och på tuman af deras högra hand, och på största tåna af deras högra fot: Och stänkte blodet på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Och tog det feta och stjerten, och allt det feta på inelfwerna, och nätet på lefrena, båda njurarna med det feta deruppå är, och den högra bogen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Dertil tog han utaf korgenom, der det osyrade brödet uti war för HERranom, ena osyrada kako, och ena kako af det oljade brödet, och ena tunkako, och lade det på det feta, och på högra bogen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Och fick allt detta Aaron och hans söner på händerna, och weftade det för ett weftoffer för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Och tog det allt igen af deras händer, och brände det up på altaret ofwan uppå bränneoffret: Ty det är fyllooffer til en söt lukt, et offer HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Och Mose tog bröstet, och weftade det til et weftoffer för HERranom af fyllooffrens wädur, den kom Mose på hans del; såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Och Mose tog af smörjooljone, och af blodet på altaret, och stänkte på Aaron och hans kläder, på hans söner och deras kläder, och wägde så Aaron och hans kläder, hans söner och deras kläder med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Och sade til Aaron och hans söner: Koker köttet för dörene af wittnesbördsens tabernakel; och äter det der, dertil med brödet i fylleoffrens korg, såsom mig budit är och sagdt, at Aaron och hans söner skulle ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Hwad öfwer blifwer af köttet och brödet, det skolen I upbränna på elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Och I skolen icke utgå i sju dagar ifrå dörene af wittnesbördsens tabernakel, allt intil den dagen, då edra fylloffers dagar äro ute; ty i sju dagar äro edra händer fyll da:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Såsom det på denna dag skedt är: HERren hafwer så budit at göra, på det I skolen wara försonade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Och I skolen blifwa för dörene af wittnesbördsens tabernakel dag och natt i sju dagar långt. Och skolen taga wara på HERrans wakt, at I icke dön: Ty så är mig budit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Och Aaron med hans söner gjorde allt det HERren genom Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Och på åttonde dagen kallade Mose Aaron och hans söner, och de äldsta i Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Och sade til Aaron: Tag til dig en ung kalf til syndoffer, och en wädur til bränneoffer, båda utan wank, och haf dem fram för HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Och tala med Israels barn, och säg: Tager en getabock til syndoffer, och en kalf, och et får, båda årsgamla, och utan wank, til bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Och en oxa och en wädur til tackoffer, at wi offre för HERranom; och et spisoffer blandadt med oljo: Förty i dag skall HERren låta eder se sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Och de togo det Mose budit hade inför dörene af wittnesbördsens tabernakel; och hela menigheten gick fram, och stod för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Då sade Mose: Detta är det HERren budit hafwer, at I göra skolen; så warder HERrans härlighet sig se låtandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Och Mose sade til Aaron: Gack fram til altaret, och gör ditt syndoffer, och ditt bränneoffer, och försona dig och folket. Derefter gör folkens offer, och försona desslikes dem; såsom HERren budit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Och Aaron gick fram til altaret, och slagtade kalfwen til sitt syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Och hans söner båro blodet til honom, och han doppade med sitt finger i blodet, och strök på hornen af altaret, och gjöt blodet på botnen af altaret:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Men det feta och njurarna och det nätet på lefrene af syndoffrena brände han up på altaret; såsom HERren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Och köttet och skinnet brände han up på elde, utanför lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Sedan slagtade han bränneoffret, och Aarons söner båro blodet til honom, och han stänkte det på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Och de båro bränneoffret til honom styckadt, och hufwudet: Och han brände det up på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Och han twådde inelfwerna och fötterna, och brände det up ofwan på bränneoffret på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Derefter bar han fram folkens offer, och tog bocken, folkens syndoffer, och slagtade honom, och gjorde et syndoffer deraf, såsom det förra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Och bar bränneoffret fram, och gjorde såsom det sig borde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Och bar fram spisoffret dertil, och tog sina hand full, och brände det up på altaret, förutan morgonens bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Sedan slagtade han oxan och wäduren til folkens tackoffer: Och hans söner båro honom blodet, det stänkte han på altaret allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Men det feta af oxanom och wädurenom, stjerten, och det feta som war öfwer inelfwerna, och njurarna, och nätet öfwer lefrena:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Allt detta feta lade de på bröstet, och brände det feta up på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Men bröstet och den högra bogen weftade Aaron til et weftoffer för HERranom; såsom Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Och Aaron hof sina hand up til folket, och wälsignade dem; och gick neder, sedan han syndoffret, bränneoffret och tacko ffret gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Och Mose och Aaron gingo in uti wittnesbördsens tabernakel. Och då de gingo åter ut igen, wälsignade de folket. Då lät HERrans härlighet se sig allo folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Ty eld kom ut ifrå HERranom, och förstörde bränneoffret, och det feta på altaret. Då allt folket såg detta, fröjdade det sig, och föllo på deras anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Och Aarons söner, Nadab och Abihu, togo hwar sitt rökelsekar, och lade eld deruti, och lade rökwerk deruppå, och båro främmande eld fram för HERran, det han dem icke budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Då kom en eld ut ifrå HERranom, och förtärde dem, så at de blefwo döde för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Då sade Mose til Aaron: Detta är det HERren sagt hafwer: Jag skall warda helgader på dem som nalkas mig, och för allo folke skall jag härlig hållen warda. Och Aaron tigde stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Men Mose kallade til sig Misael och Elzaphan Usiels söner, Aarons faderbroders, och sade til dem: Går fram, och bärer edra bröder här ut af helgedomenom, ut för lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Och de gingo fram, och båro dem med deras linne kjortlar ut för lägret; såsom Mose sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Då sade Mose til Aaron, och hans söner, Eleazar och Ithamar: I skolen icke blotta edor hufwud, icke heller rifwa edor kläder, at I icke dön, och wrede kommer öfwer hela menighetena: Låter edra bröder af hela Israels hus gråta öfwer denna branden, som HERren gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Men I skolen intet gå ut igenom dörena af wittnesbördsens tabernakel; annars kunden I dö: Ty HERrans smörjoolja är på eder. Och de gjorde såsom Mose sade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Men HERren talade med Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Du och dine söner med dig skola icke dricka win eller starka drycker, när I gån in uti wittnesbördsens tabernakel, at i icke skolen dö. Det ware en ewig rätt allom edrom efterkommandom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'At I mågen åtskilja hwad heligt och oheligt, hwad rent och orent är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Och at I mågen lära Israels barn alla rätter, som HERren til eder genom Mose sagt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Och Mose talade med Aaron, och med hans återlefda söner, Eleazar och Ithamar: Tager det öfwerblifwit är af spisoffret af HERrans offer, och äter det osyradt wid altaret; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Och I skolen ätat på et heligt rum, ty det är din rätt, och dina söners rätt af HERrans offer; ty så är mig budit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Weftebröstet och häfwebogen skalt du och dine söner, och dina döttrar med dig, äta på rent rum; ty denne rätten är dig och dina söner gifwen til Israels barns tackoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Ty häfwebogen och weftebröstet, med dess fetas offer, skola inbäras, at de skola warda weftade til weftoffer för HERranom. Derföre är det ditt och dina barns til en ewig rätt; såsom HERren budit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Och Mose sökte efter syndoffrens bock; och fann honom wara upbrändan. Och han wardt wred öfwer Eleazar och Ithamar Aarons söner, de ännu igenlefde woro; och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Hwi hafwen I icke ätit syndoffret på heligt rum, efter det är det aldrahelgasta, och han hafwer gifwit eder det, på det I skolen bära menighetenes missgerningar, och försona dem för HERranom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Si, hans blod är icke kommen in uti det helga: I skullen hafwa ätit det in i det helga, såsom mig budit är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Men Aaron sade til Mose: Si, i dag hafwa de offrat deras syndoffer, och deras bränneoffer för HERranom, och mig är så gångit som du ser. Skulle jag i dag äta af syndoffer, och wara wid godt mod för HERranom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Då Mose det hörde, war han til frids.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Och HERren talade med Mose och Aaron, och sade til dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Taler med Israels barn, och säger: Dessa äro de djur, som I äta skolen, ibland all djur på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Allt det som ibland djuren twåklöfwadt är, och idislar, det skolen i äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Men det som idislar, och är klöfwadt, dock icke twåklöfwadt, såsom camelen, det är eder orent, och I skolen icke ätat:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Cuniler idisla wäl; men de äro icke twåklöfwade: Derföre äro de orene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Haren idislar ock; men han är icke twåklöfwad: Derföre är han eder oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Och swinet är wäl twåklöfwadt; men det idislar icke: Derföre är det eder orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Af dessas kött skolen I icke äta, och icke komma wid deras as; ty de äro eder oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Detta skolen I äta ibland det som i watnena är: Allt det som spol och fjäll hafwer i floder, i hafwena, och i bäckom; det skolen I äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Men allt det som icke hafwer spol och fjäll i hafwena, och i bäckom, ibland allt det som röres i watnen, och allt det som lefwer i watne, det skall wara eder en wederstyggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'At I icke äten af dess kött: Och skyr wid deras as;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Ty allt det som icke hafwer spol och fjäll i watnena, der skolen I sky weder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Och detta skolen I sky weder ibland foglarna, at I icke äten dem: Örnen, höken, falken:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Gamen, gladona, och det af deras art är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Och alle korpar med deras art:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Strussfoglen, uglona, göken, sparfhöken med sin art:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Stenuglona, swanen, ufwen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Flädermusena, rördrommen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Storken, hägren, skrikona med sin art: Widhöfden och swalona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Och allt det sig rörer ibland foglarna, och går på fyra fötter, det skall wara eder en wederstyggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Dock detta skolen I äta af foglom, der sig rörer och går på fyra fötter, hwilkas knä stå tilbaka, der det med hoppar på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Der af må I äta, såsom är Arbe med sin art, och Saleam med sin art, och Hargol med sin art, och Hagab med sin art.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Allt det eljest hafwer fyra fötter ibland foglarna, det skall wara eder en wederstyggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Och I skolen räkna dem oren. Den som kommer wid deras as, han skall wara oren allt intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Och den som någors deras as bär, han skall twå sin kläder, och skall blifwa oren allt intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Derföre, allt det djur som klöfwadt är, och icke twåklöfwadt, och idislar icke, det skall wara eder orent: Den som kommer derwid, han blifwer oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Och allt det som går på händer ibland djuren, som gå på fyra fötter, det skall wara eder orent: Den som kommer wid deras as, han skall wara oren allt intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Och den som deras as bär, han skall twå sin kläder, och wara oren allt intil aftonen; ty allt sådant är eder orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Desse skola ock wara eder oren ibland de djur som krypa på jordene: Lekatten, musen, paddan, hwart efter sitt slag:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Igelkotten, molken, ödlan, stellion, mullwaden:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'De äro eder oren ibland allt det som kryper; den som kommer wid deras as, han skall wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Och allt det som et sådant dödt as på faller, det warder orent; ware sig allahanda träkäril, eller kläder, eller skinn, eller säck, och all sådana redskap, der man något med gör, skall man låta i watn, och det blifwer orent intil aftonen; så warder det rent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Allahanda lerkäril, om et sådant as deruti faller, warder allt orent, som deruti är, och skall sönderslås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'All mat som man äter, om det watnet kommer deruti, den är oren: Och all dryck, som man dricker af allahanda sådana kärile, är oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Och allt det som et sådant as på faller, det blifwer orent, ware sig ugn eller ketslar, det skall man slå sönder; ty det är orent, och skall wara eder orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Dock brunnar, källor och dammar äro rene: Den som kommer wid deras as, han är oren:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Och om et sådant as fölle på säd, som man sått hafwer, så är hon dock ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Men gjuter man watn på sädena, och sedan fölle sådant as deruppå, så worde hon eder oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Om et djur dör, det I äta mågen: Den som kommer wid det aset, den är oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Den som äter af sådant as, han skall twå sin kläder, och skall blifwa oren intil aftonen: Så ock den som bär et sådant as, han skall twå sin kläder, och blifwa oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Det som kräker på jordene skall wara eder en wederstyggelse, och man skall icke ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Och allt det som går på bukenom, och allt det som går på fyra eller flera fötter, af allo thy som kräker på jordene, det skolen I icke äta; ty det skall wara eder en wederstyggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Görer edra själar icke till styggelse, och besmitter eder icke deruppå, så at I blifwen orene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Ty jag är HERren edar Gud: Derföre skolen I helga eder, at I blifwen helige; ty jag är helig: Och I skolen icke orena edra själar på något kräkande djur, som på jordene kräker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Ty jag är HERren, som hafwer fört eder utur Egypti land, at jag skall wara edar Gud: Derföre skolen I wara helige, ty jag är helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Detta är lagen öfwer djur och foglar, och allahanda kräkande djur i watnena, och allahanda djur som kräka på jordene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'At I skolen weta åtskilnad på, hwad orent och rent är, och hwad djur man äta, och hwad man icke äta skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Tala med Israels barn, och säg: När en qwinna undfår säd, och föder piltabarn, då skall hon wara oren i sju dagar, så länge hon lider sina krankhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Och på åttonde dagen skall man omskära hans förhuds kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Och hon skall hema blifwa tre och trettio dagar uti hennes renselseblod. Intet heligt skall hon komma wid, och til helgedomen skall hon icke komma, til dess hennes renselsedagar äro ute.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Föder hon pigobarn, så skall hon wara oren i twå weckor, så länge hon lider sina krankhet, och skall sex och sextio dagar hema blifwa i hennes renselseblod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Och när hennes renselsedagar äro ute, efter son eller dotter, skall hon bära fram et årsgammalt lamb til bränneoffer, och en ung dufwo, eller turturdufwo, til syndoffer Prestenom, för dörena af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Der skall han offrat för HERranom, och försona henne, så warder hon ren af si nom blodgång. Detta är lagen för den som föder piltabarn eller pigobarn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Om hennes hand icke förmå et får, så tage twå turturdufwor, eller twå unga dufwor, den ena til bränneoffer, den andra til syndoffer: Så skall Presten försona henne, at hon skall warda ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Och HERren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Om ene mennisko något kommer på hennes kötts hud, eller warder skabbot, eller etterhwitt, såsom der wille spitelska komma på hans kötts hud, skall man hafwa honom til Presten Aaron, eller til en af hans söner ibland Presterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Och när Presten ser sårnaden på köttsens hud, at håren äro förwandlade til hwitnad, och rummet är så påseende, som det djupare är, än den andra huden af hans kött, så är det förwisso spitelska: Ty skall Presten bese honom, och döma honom oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Om något etterhwitt är på hans kötts hud, och är dock icke rummet så påseende, at det djupare är än den andra huden på köttet, och håren äro icke förwandlade til hwitnad, så skall Presten lycka honom inne i sju dagar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Och på sjunde dagen bese honom, om sårnaden synes för hans ögon såsom tilförene, och hafwer intet widare ätit sig ut på hudene, så skall Presten åter sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Och när han beser honom annan gången, på sjunde dagen, och finner då, at sårnaden är förswunnen, och hafwer intet widare ätit sig på hudene, så skall han döma honom renan; ty det är en skabb: Och han skall twå sin kläder, och så är han ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Om nu skabben widare äter sig på hudene, sedan han af Prestenom besedd och ren sagd wardt; och warder nu annan tid besedd af Prestenom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Ser då Presten, at skabben hafwer widare ätit sig i hudena, skall han döma honom oren: Ty det är wisserliga spitelska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Om någon spitelsko sårnad warder på ene mennisko, den skall man hafwa til Presten:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'När han ser och finner, at en hwitnad är kommen på hudena, och håren äro hwit wordne, och rått kött är i sårena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Så är det wisserliga en gammal spitelska på hans kötts hud; derföre skall Presten döma honom oren, och icke sluta honom inne; ty han är allaredo oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Om spitelskan förwidgas på hudene, och går utöfwer hela hudena, ifrå hufwudet ned til fötterna, allt det Prestenom för ögonen wara kan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'När nu Presten beser det, och finner at spitelskan är gången öfwer hela köttet, då skall han döma honom ren, efter det allt på honom förwandladt är til hwitnad; ty han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Men är der rått kött den dagen då han besedd warder, så är han oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Och när Presten ser det rå köttet, skall han döma honom oren; ty han är oren, och är wisserliga spitelsk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Om det rå köttet förwänder sig igen, och förwandlas til hwitnad, så skall han komma til Presten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Och när Presten ser och ttnner, at den sårnaden är förwandlad til hwitnad, skall han döma honom renan; ty han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Om någrom kommer på hans kötts hud en böld, och läkes åter igen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Och derefter på samma rummet upkommer något hwitt, eller rödligit etterhwitt warder, skall han warda besedd af Prestenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'När Presten ser, at det rummet är lägre än den andra huden, och håret är förwandladt til hwitnad, så skall han döma honom oren; ty det är wisserliga wordet en spitelsko sårnad af den böldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Men ser Presten och ttnner, at håren icke äro hwit, och är icke lägre än den andra huden, och är förswunnet, så skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Äter det sig widare i hudena, så skall han döma honom oren; ty det är wisserliga en spitelsko sårnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Men blifwer den etterhwitnaden så ståndandes, och äter sig icke widare, så är det ärret efter böldene; och Presten skall döma honom ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Om någors mans kött warder sårt på hudene af eldsbränning, och brännesårnaden är rödlig eller hwit:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Och Presten beser honom, och finner håret förwandladt til hwitnad, der bränningen war, och är lägre til anseende än den andra huden; så är wisserliga spitelska worden af den bränningene: Derföre skall Presten döma honom oren; ty det är en spitelsko sårnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Men ser Presten och ttnner, at håret på bränningene icke är förwandladt til hwitnad, och icke lägre än den andra huden, och är dertil förswunnet; skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Och på sjunde dagen skall han bese honom: Hafwer det widare ätit sig ut på hudene, så skall han döma honom oren: Ty det är spitelska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Men är det blifwit ståndande på bränningene, och icke hafwer widare ätit sig ut på hudene, och är dertil förswunnet, så är det et sår efter bränningene, och Presten skall döma honom ren; ty det är et ärr efter bränningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Om en man eller qwinna warder skabbot på hufwudet eller på skägget:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Och Presten beser sårnaden, och finner at det är lägre til anseende än den andra huden, och håret der sammastäds warder gulaktigt och tunt, så skall han döma honom oren; ty det är en spitelsko skabb på hufwudet eller skäggena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Men ser Presten, at skabben icke är lägre til anseende än den andra huden, och håret icke är blackt; skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Och när han på sjunde dagen ser och finner, at skabben icke hafwer ätit sig widare, och intet gult hår på färde är, och skabben är icke lägre til anseende än den andra huden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Skall han raka sig, dock at han icke rakar skabben; och Presten skall åter sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Och när han på sjunde dagen beser honom, och finner at skabben hafwer icke widare ätit sig i hudene, och är icke lägre til anseende än den andra huden, så skall Presten säga honom ren, och han skall twå sin kläder; ty han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Om skabben äter sig widare i hudena, sedan han ren sagd war:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Och Presten ser och finner, at skabben hafwer ätit sig widare på hudene, så skall han icke mer fråga efter, om håren äro gulaktig; ty han är oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Är det ock för ögonen, at skabben hafwer ståndit stilla, och der äro black hår upgångne, så är skabben läkt, och han är ren: Ty skall Presten säga honom renan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Om enom manne eller qwinno något etterhwitt kommer på hans kötts hud:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Och Presten ser, at det etterhwita något förswinner, så är det en hwit skabb, upkommen på hudena; och han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Om enom manne hufwudhåret affaller, så at han warder skallot, han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Faller det honom framman af hufwudet, så är det en framskallot; och han är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Men warder der någor hwit eller rödlig sårnad uppå det skallota eller framskallota, så är det spitelska upgången på samma skallota eller framskallota.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Derföre skall Presten bese honom, och när han finner den hwita eller rödliga sårnaden uplupen på hans skallota eller framskallota, at det synes såsom eljest spitelska på hudene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Så är han spitelsk och oren: Och Presten skall säga honom oren för sådana sårnads skull på hans hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Den som spitelsk är, hans kläder skola wara rifwin, och hufwudet blott; munne skylter, och skall allstinges oren kallas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Och så länge den sårnaden på honom är, skall han wara oren; bo allena, och hans boning skall wara utan lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Om på et kläde kommer en spitelsko sårnad, ware sig ullet eller linnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'På warp eller wäft, ehwad det är, linnet eller ullet, eller på ett skinn, eller på allt det af skinn gjordt är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Och när den sårnaden warder blek eller rödlig, på kläde eller på skinne, eller på warpe eller wäfte, eller på något ting, som af skinn gjordt är, det är wisst en spitelsko sårnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Derföre skall Presten bese det, och när han ser sårnaden, skall han sluta det inne i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Och om han på sjunde dagen ser, at sårnaden hafwer widare ätit sig, på klädet, på warpenom eller wäftena, på skinne, eller hwad af skinne gjordt är; så är det en inbiten spitelsko sårnad, och det är orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Och klädet skall brännas up, eller warpen, eller wäftet, ehwad det är ullet eller linnet, eller allahanda skinnwerk, der sådana sårnad uppå är: Ty det är en spitelsko sårnad, och skall brännas up i elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Om Presten ser, at sårnaden icke hafwer widare ätit sig på klädet eller på warpenom, eller wäftena, eller allahanda skinnwerk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Så skall han bjuda, at man twår, der sårnaden är, och skall sluta det inne i andra sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Och när Presten ser, sedan sårnaden twagen är, at sårnaden intet förwandlad är för hans ögon, och ej heller hafwer widare ätit sig, så är det orent, och skall upbrännas på elde: Ty det är djupt inätit, och hafwer befrätit det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Om Presten ser, at sårnaden något förswunnen är, sedan han wardt twagen; så skall han rifwa det af klädena, af skinnena, af warpenom eller wäftena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Synes det ändå sedan på klädena, på warpenom, på wäftena, eller allahanda skinnwerk; så är det en fläck, och skall det upbrännas med elde, der den sårnaden uti är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Men klädet eller warpen, eller wäftet, eller allahanda skinnwerk, som twagit är, och sårnaden afgången är, skall man på nytt twå, och så är det rent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Detta är lagen om spitelsko sårnad på kläder, ehwad de äro ullen eller linnen; på warp eller wäft, och allahanda skinnwerk, til at säga dem ren eller oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Detta är lagen om den spitelska, när han skall rensad warda. Han skall komma til Presten:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Och Presten skall gå utu lägret, och bese huru spitelsko sårnaden är på dem spitelska hel worden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Och skall bjuda honom, som rensas skall, at han tager twå lefwande foglar, de som rene äro, och cedreträ, och rosenfärgo ull, och Isop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Och skall bjuda at slagta den ena foglen uti et lerkärile wid rinnande watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Och skall taga den lefwande foglen med cedreträt, rosenfärgo ullen, och Isopen, och doppa uti den slagtade foglens blod wid rinnande watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Och stänka på honom, som af spitelskone rensas skall, sju resor; och rensa honom alltså, och låta den lefwande foglen flyga i fria markena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Men den rensade skall twå sin kläder, och raka allt sitt hår af, och bada sig i watne, och så är han ren: Sedan gånge han in i lägret, dock skall han blifwa utan sitt tjäll i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Och på sjunde dagen skall han raka allt sitt hår af hufwudet, skägget och ögonbrynen, så at allt hår blifwer afrakadt; och skall twå sin kläder, och bada sitt kött i watne, och så är han ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Och på åttonde dagen skall han taga tu lamb, de utan wank äro, och et årsgammalt får utan wank, och tre tijungar semlomjöl til spisoffer, blandadt med oljo, och en Log oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Då skall Presten ställa den rensada och dessa ting fram för HERran, för dörena af wittnesbördsens tabernakel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Och skall taga det ena lambet, och offra det til et skuldoffer med den Log oljo, och skall sådant weftoffra för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Och sedan slagta lambet, der man slagtar syndoffret och bränneoffret, som är på heligt rum: Ty såsom syndoffret, så hörer ock skuldoffret Prestenom til; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Och Presten skall taga af skuldoffrens blod, och stryka på högra örnatimpen af den rensada, och på tuman af hans högra hand, och på största tåna af hans högra fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Sedan skall han taga af oljone utu Logen, och gjuta den i sin wänstra hand:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Och doppa med sitt högra finger i oljona, den i hans wänstra hand är, och stänka oljona med sitt ttnger sju resor för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Men det öfwer blifwer af oljone i hans hand skall han gjuta på den högra örnatimpen af honom som rensad är, och på den högra tuman, och på den stora tåna af hans högra fot, ofwan uppå skuldoffrens blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Det qwart är af oljone i hans hand skall han slå på hans hufwud som rensader är, och försona honom för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Och skall göra syndoffer, och försona den rensada för hans orenlighets skull. Och skall sedan slagta bränneoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Och skall offra det på altaret samt med spisoffret, och försona honom, så är han ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Är han fattig, och icke så mycket förwärfwar med sine hand, så tage et lamb för sitt skuldoffer, til at weftoffra, til att försona honom, och en tijung af semlomjöl, blandad med oljo til spisoffer, och en Log oljo:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Och twå turturdufwor, eller twå unga dufwor, de han med sine hand förwärfwa kan; den ena ware til et syndoffer, den andra til et bränneoffer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Och bäre dem til Presten, på åttonde dagen efter hans renselse, inför dörena af wittnesbördsens tabernakel för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Då skall Presten taga skuldoffrens lamb, och den Log oljo, och skall det allt weftoffra för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Och slagta skuldoffrens lamb, och taga af samma skuldoffers blod, och stryka den rensada på hans högra örnatimp, och på tuman af hans hand, och på den stora tåna af hans högra fot:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Och gjuta oljona i sina wänstra hand:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Och stänka med sitt högra ttnger oljona, som i hans wänstra hand är, sju resor för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Det qwart blifwer i hans hand skall han låta på högra örnatimpen af den rensada, och på tuman af hans högra hand, och på stora tåna af hans högra fot, ofwan uppå skuldoffrens blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Det qwart är i hans hand af oljone skall han låta på hufwudet af den rensada, til at försona honom för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Och sedan göra et syndoffer utaf den ena turturdufwone, eller unga dufwone, såsom hans hand hafwer kunnat förwärfwa:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Utaf den andra et bränneoffer, samt med spisoffret. Och alltså skall Presten försona den rensada för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Detta ware lagen för den spitelska, som icke kan med sine hand förwärfwa det til hans renselse hörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Och HERren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'När i kommen in uti Canaans land, det jag eder til besittning gifwa skall, och jag der i någro edor besittnings huse en spitelsko sårnad gifwer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Så skall han, som huset tilhörer, komma, underwisa det Prestenom, och säga: Det synes såsom en spitelsko sårnad är i mino huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Då skall Presten säga dem, at de skola ryma utu huset förra än Presten går derin, til at bese sårnaden: På det at allt det i huset är icke skall warda orent. Sedan skall Presten gå in til at bese huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'När han nu ser sårnaden, och finner at på husens wäggar gula eller rödletta gropar äro, och deras anseende djupare in är, än wäggen eljest är:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Så skall han gå utu huset genom dörena, och igenlycka huset i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Och när han på sjunde dagen igenkommer, och ser at sårnaden hafwer ätit sig widare på wäggene af huset:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Så skall han bjuda dem utbryta stenarna, der den sårnaden uti är, och kasta det ut för staden på et orent rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Och huset skall man skrapa innantil allt omkring, och kasta det afskrapade stoftet ut för staden på et orent rum:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Och taga andra stenar, och sätta dem i samma staden; och taga annan kalk, och bestryka huset med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Om då sårnaden igenkommer, och brister ut på huset, sedan man hafwer uttagit stenarna, skrapat huset, och bestrukit det på nytt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Så skall Presten gå derin: Och när han ser at sårnaden hafwer widare ätit sig på husena, så är det wisserliga en frätande spitelska på huset; och är orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Derföre skall man bryta huset ned, både sten och trä, och allt stoftet af husena föra ut för staden på et orent rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Och den som går in i huset, så länge det tilslutit är, han är oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Och den derinne ligger, eller äter derinne, han skall twå sin kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Hwar nu Presten ser, då han går derin, at sårnaden icke widare hafwer ätit sig på huset, sedan huset bestrukit är; så skall han säga det rent; ty sårnaden är hel worden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Och skall taga til syndoffer för huset, twå foglar, cederträ, och rosenfärgad ull, och Isop:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Och slagta den ena foglen uti et lerkäril med rinnande watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Och skall taga det cederträt, rosenfärgada ullen, Isopen och den lefwande foglen, och doppa honom uti den slagtada foglens blod wid rinnande watn, och stänka huset sju resor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Och skall alltså skära huset med foglens blod, och med det rinnande watnet, med den lefwande foglen, med cedreträt, med Isopen, och med rosenfärgada ullen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Och skall låta den lefwande foglen flyga ut för staden i fria markena, och försona huset; så är det rent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Detta är lagen om all spitelskos och skabbs sårnad:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Om kläders spitelsko, och huses;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Om blemor, skabb och etterhwitt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'På det man skall weta, när något orent eller rent är. Detta är lagen om spitelsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Och HERren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Taler med Israels barn, och säger til dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Om enom manne flyter hans kötts flöd, han är oren. Och då är han oren af denna flödene, när hans kött förrötes, eller bortfrätes af det flytandet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'All säng, der han på ligger, och allt det han sitter uppå, skall wara orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Och den som kommer wid hans säng, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Och den som sätter sig der han suttit hafwer, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Den som kommer wid hans kött, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Om han spottar på den som ren är, skall han twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Och sadelen, der han rider uppå, skall wara oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Och den som kommer wid något, som under honom warit hafwer, han skall wara oren intil aftonen. Och den sådant bär, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Och den som han wederkommer, och hafwer tilförene icke twagit sina händer, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Kommer han wid et lerkäril, skall man det sönderslå: Men träkäril skall man skölja med watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Och när han warder ren af hans flytande, skall han räkna sju dagar sedan han wardt ren, och twå sin kläder, och bada sitt kött med rinnande watn, så är han ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Och på åttonde dagen skall han taga twå turturdufwor, eller twå unga dufwor, och bära fram för HERran inför dörena af wittnesbördsens tabernakel, och få Prestenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Och Presten skall göra af den ena et syndoffer, och af den andra et bränneoffer; och försona honom för HERranom, för hans flytande skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'När enom manne hans säd utgår i sömnen, han skall bada sitt hela kött med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Och allt kläde, och allt skinn, som med sådana säd befläckadt är, skall twås med watn, och wara orent intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'En qwinna, när hwilko en sådana ligger, hon skall bada sig i watne, och wara oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'När en qwinna hafwer sins kötts blodflöd, hon skall wara afsides i sju dagar. Och den som kommer wid henne, han skall wara oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Och allt det hon ligger uppå, så länge hon afsides är, skall wara orent: Och det hon sitter uppå skall wara orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Och den som kommer wid hennes säng, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Och den som kommer wid något, der hon hafwer suttit uppå, den skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Hwad som kommer wid hennes säng, eller det hon sitter på, den det rörer, han skall wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Och om en man ligger när henne, den stund hon afsides är, han skall wara oren i sju dagar; och sängen, der han uppå legat hafwer, skall wara oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Om en qwinna hafwer sin blodflöd i långan tid, icke allenast i så lång tid som wandt är, utan ock utöfwer den tiden som wandt är, skall hon wara oren så länge hon flyter: Såsom hon är i hennes rätta flöds tid, så skall hon ock wara oren i denna tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'All den säng, der hon uppå ligger, så länge hon då flyter, skall wara såsom den säng i hennes rätta flöds tid. Och allt det hon sitter uppå skall wara orent, såsom i den orenheten i hennes rätta flöds tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Den som kommer wid något deraf, han skall wara oren, och skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Warder hon ren af hennes flöd, så skall hon räkna sju dagar, sedan skall hon wara ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Och på åttonde dagen skall hon taga twå turturdufwor, eller twå unga dufwor, och bära dem til Presten inför dörena af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Och Presten skall göra et syndoffer af den ena; af den andra et bränneoffer, och försona henne för HERranom, öfwer hennes orenlighets flöd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Så skolen I förwara Israels barn för deras orenlighet, at de icke dö uti deras orenlighet, om de göra mitt tabernakel orent, det ibland eder är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Detta är lagen om den som hafwer en flöd, och den som i sömnen hans säd flyter, så at han warder deraf oren:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Och öfwer henne som hafwer sina blodsflöd, och den som en flöd hafwer, ehwad det är man eller qwinna, och när en man ligger när ena oreno.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Och HERren talade med Mose, sedan de twå Aarons söner döde woro, då de offrade för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Och HERren sade: Säg dinom broder Aaron, at han icke i alla tider ingår uti den innersta helgedomen, inom förlotten inför nådastolen som på arkenom är, at han icke dör; ty jag will låta se mig uti et moln på nådastolenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Utan härmed skall han gå in: med en ung stut til syndoffer, och med en wädur til brännoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Och skall kläda den helga linna kjortelen uppå, och hafwa det linna nederklädet uppå sitt kött, och gjorda sig med et linnet bälte, och hafwa den linna hatten uppå; förty det äro de helga kläden; och skall bada sitt kött med watn, och lägga dem uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Och skall taga utaf menighetene af Israels barnom, twå getabockar til syndoffer, och en wädur til bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Och Aaron skall hafwa fram stuten, sitt syndoffer, och försona sig och sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Och sedan taga de twå bockarna, och ställa dem fram för HERran inför dörena af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Och skall kasta lott öfwer de twå bock arna; den ena lotten HERranom, den andra fribockenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Och skall offra den bocken til et syndoffer, på hwilken HERrans lott föll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Men den bocken, öfwer hwilken dess frias lott föll, skall han ställa lefwande fram för HERran, at han skall försona honom, och släppa den fribocken i öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Och så skall han då hafwa fram sins syndoffers stut, och försona sig och sitt hus, och skall slagta honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Och skall taga ena panno, full med glöd af altaret, som står för HERranom, och handena fulla med stött rökwerk, och bära det inom förlotten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Och lägga rökwerket på elden inför HERranom, så at dambet af rökwerket skyler nådastolen, som är på wittnesbördet, at han icke dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Och skall taga blodet af stutenom, och stänka med sitt finger up åt nådastolen, frammantil. Sju resor skall han så stänka af blodet för nådastolenom med hans finger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Sedan skall han slagta bocken, folkens syndoffer, och bära af hans blod der inom förlotten, och skall göra med hans blod såsom han gjorde med stutens blod, och stänka desslikes dermed frammantil, up åt nådastolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Och skall alltså försona helgedomen af Israels barns orenhet, och ifrå deras öfwerträdelse i alla deras synder. Sammalunda skall han göra wittnesbördsens tabernakel; ty de äro orene, som omkring ligga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Ingen menniska skall wara in uti wittnesbördsens tabernakel, när han går der in til at försona i helgedomenom, til dess han går ut igen; och skall alltså försona sig och sitt hus, och hela Israels menighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Och när han utgår til altaret, som står för HERranom, skall han försona det; och skall taga af stutens blod, och af bockens blod, och stryka på altarens horn allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Och skall stänka af blodet med sitt finger sju resor der uppå, och rensa, och helga det af Israels barns orenhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Och när han fullkomnat hafwer helgedomens och wittnesbördsens tabernakels och altarens försoning, skall han hafwa fram den lefwande bocken:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Och skall då Aaron lägga båda sina händer på hans hufwud, och bekänna öfwer honom alla Israels barns missgerningar, och all deras öfwerträdelse i alla deras synder, och skall lägga dem på bockens hufwud, och låta honom löpa genom någons mans hjelp, som förhanden är, i öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'At bocken skall bortbära alla deras missgerningar på sig uti wildmarkena; och låta honom i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Och Aaron skall gå in uti wittnes bördsens tabernakel, och afkläda sig de linna kläden, som han på sig klädt hade, då han gick in uti helgedomen, och skall der låta blifwa dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Och skall bada sitt kött med watn på heligt rum, och kläda sin egen kläder uppå, och gå der ut, och göra sitt bränneoffer och folkens bränneoffer, och försona både sig och folket:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Och bränna up det feta af syndoffret på altarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Men den, som förde fribocken ut, skall twå sin kläder, och bada sitt kött med watn, och sedan komma igen i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Syndoffrens stut och syndoffrens bock, hwilkas blod til försoning burit wardt in i helgedomen, skall man föra utom lägret, och upbränna i elde, både deras hud, kött och träck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Och den som bränner det up, han skall twå sin kläder, och bada sitt kött med watn, och sedan komma i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Och skall detta wara eder en ewig rätt: På tionde dagenom i sjunde månadenom skolen I späka edra kroppar, och ingen gerning göra, ware sig inländsk eller utländsk ibland eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Förty på den dagen sker edor försoning, så at I warden rengjorde; ifrån alla edra synder warden I rengjorde för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Derföre skall det wara eder den störste Sabbath, och I skolen späka edra kroppar: En ewig rätt ware det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Men den försoningen skall en Prester göra, den man wigt hafwer, och hwilkens hand man fyllt hafwer til en Prest i hans faders stad; och skall kläda på sig de linna kläder, som äro heliga kläden:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Och skall alltså försona den helga helgedomen, och wittnesbördsens tabernakel, och altaret, och Presterna, och allt folket af menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Det skall wara eder en ewig rätt, at I försonen Israels barn af alla deras synder, ena reso om året. Och Mose gjorde såsom HERren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Tala med Aaron och hans söner, och all Israels barn, och säg til dem: Detta är det HERren budit hafwer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Hwilken af Israels hus, som i lägret, eller utanför lägret, slagtar en oxa, eller lamb, eller get:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Och intet bär fram för dörena af wittnesbördsens tabernakel det som HERranom för et offer burit warder inför HERrans boning, han skall för blod brotslig wara, såsom den som blod utgjutit hafwer; och sådana menniska skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Derföre skola Israels barn deras offer, som de på fria markene offra wilja, bära fram för HERran, inför dörena af wittnesbördsens tabernakel til Presten, och der offra deras tackoffer HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Och Presten skall stänka blodet på HERrans altare inför dörena af wittnesbördsens tabernakel, och bränna up det feta, HERranom til en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Och ingalunda mer offra djeflomen deras offer, med hwilkom de hor bedrifwa. Det skall dem wara en ewig rätt i deras efterkommandom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Derföre skalt du säga dem: Hwilken menniska af Israels huse, eller ock en främling, den ibland eder är, som gör et offer eller bränneoffer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Och bär det icke in för dörena af wittnesbördsens tabernakel, at han gör det HERranom, den skall utrotad warda utu hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Och hwilken menniska, ware sig af Israels huse, eller en främling ibland eder, äter något blod; emot honom skall jag sätta mitt anlete, och skall utrota honom midt utu hans folk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Ty kroppsens lif är uti blodet, och jag hafwer gifwit eder det til altaret, at edra själar skola dermed försonade warda: Förty blodet är försoning för lifwet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Derföre hafwer jag sagt Israels barnom: Ingen själ ibland eder skall äta blod, och ingen främling, som ibland eder bor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Och hwilken menniska, ware sig af Israels huse, eller en främling ibland eder, som tager et djur eller fogel i jagt, det man äter, han skall utgjuta dess blod, och öfwertäcka honom med jord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Ty kroppsens lif är i sinom blod. Och jag hafwer sagt Israels barnom: I skolen ingen kropps blod äta; ty kroppsens lif är i sinom blod. Den det äter, han skall utrotad warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Och hwilken själ som äter et as, eller det af wilddjur rifwit är, ware sig en inländsk eller utländsk, han skall twå sin kläder, och bada sig med watn, och wara oren intil aftonen, så warder han ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Om han icke twår sin kläder, eller sig icke badar, skall han bära sina missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Tala med Israels barn, och säg til dem: Jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'I skolen icke göra efter som görs i Egypti land, der I bott hafwen; och icke eft er som görs i Canaans land, der jag dig införa skall; I skolen icke heller hålla eder wid deras sätt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Utan efter mina rätter skolen I göra, och mina stadgar skolen I hålla, at I wandren derutinnan: Ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Derföre skolen I hålla mina stadgar, och mina rätter; ty hwilken menniska dem göra, han skall derigenom lefwa: Ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ingen skall gå in til sina nästa blods fränko, til att blotta hennes blygd: Ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Du skalt dins faders och dine moders blygd icke blotta: Hon är din moder, derföre skalt du icke blotta hennes blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du skalt icke blotta dins faders hustrus blygd; ty det är dins faders blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du skalt icke blotta dine systers blygd, den dins faders, eller dine moders dotter är, hema eller ute född.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Du skalt icke blotta dine sonadotters, eller dine dotterdotters blygd; ty det är din blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Du skalt icke blotta dins faders hustrus dotters blygd, den dinom fader född är, och din syster är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Du skalt icke blotta dins fadersysters blygd; ty hon är dins faders nästa blodsfränka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du skalt icke blotta dine modersysters blygd; ty hon är dine moders nästa blodsfränka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du skalt icke blotta dins faderbroders blygd, så at du tager hans hustru; ty hon är din swägerska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du skalt icke blotta dine sonahustrus blygd; ty hon är dins sons hustru, derföre skalt du icke blotta hennes blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du skalt icke blotta dins broders hustrus blygd; ty hon är dins broders blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du skalt icke blotta dine hustrus, samt med hennes dotters blygd: ej heller taga hennes sons dotter, eller dotterdotter, til at blotta hennes blygd; ty hon är hennes nästa blodsfränka: och det är en last.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du skalt ock icke taga dins hustrus syster, til at blotta hennes blygd, henne emot, medan hon ännu lefwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du skalt icke gå in til qwinnona, så länge hon hafwer sina sjuko i sine orenhet, til at blotta hennes blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Du skalt ock icke ligga när dins nästas hustru, til at beblanda dig med henne, dermed du orenar dig på henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du skalt ock icke gifwa af dine säd, at det skall upbrännas för Molec, at du icke ohelgar dins Guds namn; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du skalt icke ligga när drängar, såsom när ena qwinno; ty det är en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du skalt ock icke ligga när något djur, at du dermed orenar dig: Och ingen qwinna skall skaffa hafwa med något djur; ty det är en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'I skolen uti intet af detta orena eder; förty uti allt detta hafwa Hedningarne orenat sig, hwilka jag skall här utdrifwa för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Och landet är derigenom orenadt: Och jag skall söka deras missgerningar på dem, så at landet skall utspy sina inbyggare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Derföre håller mina stadgar och rätter, och görer intet af denna styggelsen, antingen inländske eller utländske ibland eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Ty all sådana styggelse hafwa landsens folk gjort, som för eder woro, och hafwa orenat landet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'På det at landet ock icke utspyr eder, då I det orenen, lika som det hafwer utspytt Hedningarna, som för eder woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Förty, de som göra denna styggelsen, deras själar skola utrotade warda utu deras folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Derföre håller mina stadgar, at I icke gören efter de styggeliga seder, som för eder woro, at I icke dermed orenade warden; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Tala med hela menighetene af Israels barn, och säg til dem: I skolen wara helige; ty jag är helig, HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Hwar och en frukte sina moder, och sin fader: Håller mina helgedagar; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'I skolen icke wända eder til afgudar, och skolen icke göra eder gutna gudar; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Och när I wiljen göra HERranom tackoffer, så skolen I offra det, at det må wara honom täckt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Och skolen det äta på samma dagen, då I offren det, och på den andra dagen. Hwad qwart blifwer til tredje dagen, det skall man bränna up i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Äter der någor af på tredje dagen, så är han en styggelse, och warder icke tacknämlig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Och den samme ätaren skall bära sin missgerning, at han HERrans helgedom hafwer ohelgat; och den själen skall utrotad warda utu sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'När du upskär af ditt land, skalt du icke skära intil ändan allt omkring, och icke noga allt afhemta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Sammalunda skalt du ej heller noga berga din wingård, eller uphemta de affall na bären: Utan skall det blifwa låta för de fattiga och främlingar; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'I skolen icke stjäla eller ljuga, eller handla falskeliga den ene med den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'I skolen icke swärja falskt wid mitt namn, och ohelga dins Guds namn; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du skalt icke göra dinom nästa orätt, eller röfwa honom. Din dagakarls lön skall icke blifwa när dig intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du skalt icke banna dem döfwa. Du skalt icke sätta för den blinda något, der han kan stöta sig uppå; utan du skalt frukta din Gud; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'I skolen icke handla orätt i dome, och skalt icke skona dem ringa, och icke ära den mägtiga, utan skalt döma dinom nästa rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du skalt icke wara en bakdantare ibland ditt folk. Du skalt ock icke stå emot dins nästas blod; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du skalt icke hata din broder i dino hjerta; utan du skalt straffa din nästa, på det du icke skalt lida skuld för hans skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du skalt icke hämnas, och icke behålla någon owilja emot dins folks barn. Du skalt älska din nästa såsom dig sjelfwan; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Mina stadgar skolen I hålla, at du icke låter din boskap hafwa beblandning med annor djur; och icke sår din åker med blandad säd: Och at ingen klädnad kommer på dig, som af ull och lin tilhopa kommen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Om en man ligger när ena qwinno, och beblandar sig med henne, och hon är en trälinna, och är af enom androm kränkt, dock är icke löst, eller frihet fått hafwer, det skall straffadt warda; men icke skola de dö: Ty hon hafwer icke warit fri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Men han skall frambära HERranom för sina skuld en wädur til skuldoffer, inför dörena af wittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Och Presten skall försona honom med skuldoffret för HERranom, för den synd, som han gjort hafwer: Så warder honom Gud nådelig öfwer hans synd, som han gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'När I kommen i landet, och planteren allahanda trä, der man af äter, skolen I afskära deras förhud med deras frukt: I tre år skolen I hålla dem för oomskorna, så at I icke äten dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Men i fjerde årena skall all deras frukt wara helgad och prisad HERranom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'I femte årena skolen I äta fruktena, och samla henne in; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'I skolen intet äta med blod: I skolen icke akta på foglarop; eller wälja några dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'I skolen icke skära någon plätt på edart hufwud, och icke allstinges raka edart skägg af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'I skolen icke skära något märke på edar kropp öfwer en dödan; eller skrifwa bokstäfwer på eder; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du skalt icke hålla dina dotter til boleri, på det at landet icke skall bedrifwa boleri, och warda fullt med laster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Håller mina helgedagar, och frukter för min helgedom; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'I skolen icke wända eder til spåmän, och fråger intet af de teknatydare, at I icke warden orenade på dem; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'För et grått hufwud skalt du upstå, och ära de gamla; ty du skalt frukta din Gud; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Om en främling warder boendes när eder i edro lande, den skolen I icke öfwerfalla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Han skall bo när eder såsom en inländsk ibland eder; och du skalt älskan såsom dig sjelfwan: Förty I woren ock främlingar i Egypti lande. Jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'I skolen intet olika handla, i dom, med aln, med wigt, med mått.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Rätt wåg, rätt pund, rätt skeppa, rätt kanna skall wara när eder; ty jag är HERren edar Gud, som hafwer fört eder utur Egypti land:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'At I skolen hålla och göra alla mina stadgar, och alla mina rätter; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Säg Israels barnom: Hwilken af Israels barn, eller en främling, som bor i Israel, gifwer af sine säd Molec, han skall döden dö; folket i landena skall stena honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Och jag skall sätta mitt anlete emot sådana mennisko, och skall utrota honom utu hans folk; derföre, at han af sine säd gifwit hafwer Molec, och orenat min helgedom, och ohelgat mitt helga namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Och om folket i landet se genom ttnger med de menniskone, som af sine säd hafwer gifwit Molec, så at de icke dräpa honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Så will jag dock sätta mitt anlete emot den menniskan, och emot hans slägt, och skall utrota honom, och alla de som efter honom med Molec hor bedrifwit hafwa, utu deras folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Om en själ wänder sig til spåmän och teknatydare, så at hon hor bedrifwer efter dem; så will jag sätta mitt anlete emot den samma själen, och will utrota henne utu hennes folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Derföre helger eder, och warer helige; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Och håller mina stadgar, och görer dem; ty jag är HERren, den eder helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Den som bannar sin fader eller sina moder, han skall döden dö; hans blod ware öfwer honom, at han sin fader eller moder bannat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Den som hor bedrifwer med någors mans hustru, den skall döden dö, både horkarlen och horkonan; derföre, at han med sins nästas hustru hor bedrifwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Om någor ligger när sins faders hustru, så at han sins faders blygd blottat hafwer, de skola både döden dö; deras blod ware öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Om någor ligger när sina sonahust ru, så skola de både döden dö; förty de hafwa gjort ena skam; deras blod ware öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Om någor ligger nära en dräng, såsom när ena qwinno, de hafwa gjort en stygghet, och skola både döden dö; deras blod ware öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Om någor tager en hustru, och hennes moder dertil, han hafwer gjort en last; man skall bränna honom up i elde, och de båda med, at ingen last blifwer ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Om någor hafwer skaffa med oskälig djur, han skall döden dö, och djuret skall man dräpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Om en qwinna låter sig in til något oskäligt djur, så at hon dermed hafwer skaffa, den skalt du dräpa, och djuret desslikes: Döden skola de dö; deras blod ware öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Om någor tager sina syster, sins faders dotter, eller sine moders dotter, och skådar hennes blygd, och hon åter hans blygd, det är en skam; de skola förgöras inför deras slägtes folk: Ty han hafwer blottat sine systers blygd; han skall bära sina skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Om en man ligger när ena qwinno i hennes krankhets tid, och blottar hennes blygd, och uplåter hennes brunn, och hon blottar sins blods brunn; de skola både förgjorde warda utu deras folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Dine modersysters blygd, och dine fadersysters blygd skalt du icke blotta: Ty en sådana hafwer sina nästa blodsfränko blottat; och de skola bära deras skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Om någor ligger när sins faderbroders hustru, den hafwer sins faderbroders blygd blottat: De skola bära deras synd; utan barn skola de dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Om någor tager sins broders hustru, det är en skamlig gerning: De skola wara utan barn, derföre, at han hafwer sins broders blygd blottat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Så håller nu alla mina stadgar och mina rätter, och görer dem, på det landet icke utspyr eder, der jag eder införer, at I deruti bo skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Och wandrer icke uti Hedningarnas stadgar, hwilka jag skall utdrifwa för eder; ty allt sådant hafwa de gjort, och jag hafwer haft en styggelse wid dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Men eder säger jag: I skolen besitta deras land; ty jag skall gifwa eder et land i arf, der mjölk och hannog uti flyter: Jag är HERren edar Gud, den eder afskilt hafwer ifrån annat folk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'At I ock skilja skolen den rena boskapen ifrå den orena; och orena foglar ifrå de rena; och icke orena edra själar på boskap, på foglar, och på allt det på jordene kryper, det jag eder afskilt hafwer, at det skall wara orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Derföre skolen I wara mig helige; ty jag HERren är helig, den eder afskilt hafwer ifrån annat folk, at I skolen höra mig til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Om någor man eller qwinna warder en spåman, eller en teknatydare, de skola döden dö; Man skall stena dem; deras blod ware öfwer dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Och HERren sade til Mose: Tala til Presterna, Aarons söner, och säg til dem: En Prester skall icke orena sig på någon dödan af sitt folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Utan på sin skyldman, den honom näst tilkommer, såsom på sin moder, på sin fader, på sin son, på sin dotter, på sin broder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Och på sin syster, den ännu en jungfru och ingens mans hustru warit hafwer; den hans nästa skyldman är, på dem må han orena sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Eljest skall han icke orena sig på någon, som honom är wederkommande ibland hans folk, så at han sig ohelgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Han skall ock ingen plätt göra på sitt hufwud, eller afraka sitt skägg, och på hans kropp intet märke skära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'De skola sinom Gudi helige wara, och icke ohelga sins Guds namn: Förty de offra HERrans offer, deras Guds bröd; derföre skola de wara helige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Han skall icke taga någon sköko, eller ena förkränkta, eller den som af sin man bortdrifwen är; ty han är helig sinom Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Derföre skalt du räkna honom helig; ty han offrar dins Guds bröd. Han skall wara dig helig; ty jag är helig, HERren som eder helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Om ens Prests dotter begynner til at bola, den skall man upbränna i elde; ty hon hafwer skämt sin fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Hwilken öfwerste Prester är ibland hans bröder, på hwilkens hufwud smörjooljan gutin är, och hans hand fylld är, så at han med kläden iklädd warder, den skall icke blotta sitt hufwud, och icke skära sin kläder sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Och skall til ingen dödan komma, och skall icke orena sig, hwarken öfwer fader eller moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Utu helgedomenom skall han icke gå, at han icke ohelgar sins Guds helgedom. Ty wigelsen, hans Guds smörjoolja, är på honom: Jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Ena jungfru skall han taga sig til hustru:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Men inga enko, eller bortdrefna, eller förkränkta, eller sköko; utan ena jungfru, af sitt folk, skall han taga til hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'På det han icke skall ohelga sina säd ibland sitt folk; ty jag är HERren, som honom helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Tala med Aaron, och säg: Om någor wank är på någrom af dine säd uti edart slägte, den skall icke gå fram, at han offrar sins Guds bröd:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Förty hwar och en, den någon wank hafwer, skall icke gå fram, ware sig blind, halt, med ene stygga näso, med oskickeliga lemmar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Eller den som hafwer en sönderbruten fot eller hand:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Eller kroppog är, eller hinno på ögonen hafwer, eller windögd, eller maslog, eller skabbog, eller förbråken är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Den som nu af Prestens Aarons säd hafwer en wank uppå sig, han skall icke gå fram til at offra HERrans offer; ty han hafwer en wank, derföre skall han intet nalkas intil sins Guds bröd, at han dem offrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Dock skall han äta af sins Guds bröde, både af det helgo, så ock af de aldrahelgasto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Men dock skall han icke komma in til förlotten, ej heller nalkas altarena, så länge sådana wank på honom är, at han icke ohelgar min helgedom; ty jag är HERren, som helgar dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Och Mose sade detta til Aaron, och til hans söner, och til all Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Säg Aaron och hans söner, at de hålla sig ifrån Israels barns helgo, hwilket de mig helga, och icke ohelga mitt helga namn; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Säg dem nu til, och deras efterkommandom: Hwilken af edor säd går til det helga, som Israels barn helga HERranom, och orenar sig så på det, hans själ skall utrotad warda för mitt anlete; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Hwilken af Aarons säd är spitelsk, eller hafwer ena flöd, den skall icke äta af det helga, til dess han warder ren. Den som kommer wid någon oren kropp, eller den som hans säd afgår i sömnen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Eller den som kommer wid en matk, den honom oren är, eller en mennisko, som honom oren är, och allt det honom orenar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Hwilken själ kommer wid något deraf, den är oren intil aftonen, och skall icke äta af de helgo; utan skall först bada sin kropp med watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Och när solen är nedergången, och han ren worden är, då må han äta deraf; ty det är hans spis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Et as, och hwad af wilddjur rifwit är, skolen I icke äta, at I icke skolen warda orene deruppå; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Derföre skola de hålla mina stadgar, at de icke skola lägga synd uppå sig, och dö deröfwer, när de ohelga sig; ty jag är HERren, som dem helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ingen annar skall äta af det helgo, ej heller Prestens husman, ej heller någon dagakarl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'När Presten köper ena själ för sina penningar, den må äta deraf. Och det i hans huse födt är, det må ock äta af hans bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Om Prestens dotter warder ens främmandes hustru, skall hon icke äta af dess helgas häfoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Warder hon en enka, eller utdrifwen, och hafwer ingen säd, och kommer igen til sins faders hus, så skall hon äta af sins faders bröd, såsom då hon ännu piga war: Men ingen främmande skall äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Hwilken som eljest äter af de helgo owetandes, han skall lägga femtedelen dertil, och gifwa Prestenom med de helgo:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'På det at de icke skola ohelga Israels barns helga, som de häfoffra HERranom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'At de icke skola lägga missgerning och skuld på sig, när de äta af deras helgo; ty jag är HERren, som dem helgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Säg Aaron och hans söner, och all Israels barn: Hwilken Israelit eller främling i Israel will göra sitt offer, ware sig af löfte, eller af fri wilja, at de wilja göra HERranom et bränneoffer, det honom skall wara tacknämligit af eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Det skall wara et mankön, och utan wank, af fä, lambom eller getom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Allt det som något fel hafwer, skolen I icke offra; förty det warder icke tacknämligit för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Och hwilken et tackoffer HERranom göra will, et besynnerligit löfte, eller af fri wilja, af fä eller får, det skall wara utan wank, at det må warda tacknämligit. Det skall hafwa ingen wank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Är det blindt, eller brutit, eller sargadt, eller förtwinadt, eller maslogt, eller skabbogt; så skola de icke sådant offra HERranom, och intet offer deraf gifwa på HERrans altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'En oxe eller får, som oskickeliga eller lytta lemmar hafwer, må du offra af en fri wilja; men icke warder det tacknämligit för et löfte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Du skalt ock icke offra HERranom något det förkramadt, eller förstött, eller förslitit, eller utskurit är; och skolen sådant icke göra i edro lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Du skalt ock icke offra något sådant af ens främlings hand, med edars Guds bröd; ty det doger intet, och hafwer en wank: Derföre warder det icke tacknämligit för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'När en kalf, eller lamb, eller get födt är, så skall det wara när sine moder i sju dagar: På åttonde dagen och derefter må man offra det HERranom, så är det tacknämligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ware sig nöt eller får, så skall man icke slagta det med sin unga på enom dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'När I wiljen göra HERranom et lofoffer, det för eder tacknämligit skall wara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Så skolen I äta det på samma dagen, och skolen intet behålla qwart intil morgonen; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Derföre håller min bud, och görer dem; ty jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'At I icke ohelgen mitt helga namn, och at jag må helgad warda ibland Israels barn; ty jag är HERren den eder helgar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Den eder utur Egypti land fört hafwer, at jag skulle wara edar Gud: Jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Tala til Israels barn, och säg til dem: Desse äro HERrans högtider, som I skolen kalla heliga och mina högtider, då I samman kommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sex dagar skalt du göra ditt arbete; men den sjunde dagen är den store helge Sabbathen, då I tilhopa kommen: Intet arbete skolen I göra på honom; förty det är HERrans Sabbath, ehwar I bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Desse äro de HERrans högtider, dem I skolen kalla helga högtider, då I samman kommen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'På fjortonde dagen i första månadenom om aftonen är HERrans Paffah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Och på den femtonde i samma månadenom är HERrans osyrade bröds högtid; då skolen I äta osyradt bröd i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Den förste dagen skall kallas helig ibland eder, då I samman kommen; då skolen I intet tjenstearbete göra:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Och offra HERranom i sju dagar. Den sjunde dagen skall ock helig kallas, då I tilhopa kommen; på honom skolen I ock intet tjenstearbete göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Tala med Israels barn, och säg til dem: När I kommen i landet, som jag eder gifwa skall, och i skolen upskära, så skolen I föra til Presten en kärfwa förstlingen af edro säd:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Då skall den kärfwen warda weftad för HERranom, at det skall blifwa tack nämligit af eder. Och detta skall Presten göra på den andra dagen näst efter Sabbathen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Och skolen på den dagen, då edar kärfwe weftad warder, göra HERranom et bränneoffer af et lamb, det utan wank och årsgammalt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Samt med spisoffret, twå tijungar semlomjöl, blandadt med oljo, til en söt lukts offer HERranom; dertil dryckoffer, en fjerding af et Hin win.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Och skolen intet äta af det nya, hwarken bröd, torkad ax eller korn, intil den dagen, då I bären edrom Gud offer. Det skall wara en ewig rätt til edra efterkommande, ehwar I bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sedan skolen I räkna ifrå den andra Sabbathsdagen, då i båren weftekärfwan fram, sju hela Sabbather:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Intil den andra dagen efter den sjunde Sabbathen: Det är, femtio dagar skolen I räkna och offra HERranom nytt spiso ffer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Och skolen offra det af alla edra boningar, nemliga, tu weftebröd af twå tijungar semlomjöl, syradt och bakadt HERranom til en förstling.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Och skolen frambära med edor bröd sju årsgamla lamb utan wank, och en ung stut, och twå wädrar: Det skall wara HERrans bränneoffer, spisoffer och dryckoffer; det är en söt lukts offer HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Dertil skolen I göra en getabock til syndoffer, och tu årsgamla lamb til tacko ffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Och Presten skall wefta det med förstlings brödena för HERranom til de tu lamben: Och skall wara HERranom heligt, och höra Presten til.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Och I skolen utropa denna dagen: Ty han skall kallas helig ibland eder, då I samman kommen: Intet tjenstearbete skolen i göra. En ewig rätt skall det wara, til edra efterkommande, ehwar I bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'När I upskären sädena i edro lande, skolen I icke allt upskära på åkren, och icke allt för noga uphemta; utan skolen det låta dem fattigom, och främlingom. Jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Tala med Israels barnom, och säg: På första dagen i sjunde månadenom skolen I hålla Blåsandens helga Sabbath til åminnelse, då I samman kommen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Då skolen I intet tjenstearbete göra; och skolen göra HERranom offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'På tionde dagen i denna sjunde månadenom är Försonedagen, den skall ibland eder kallas helig, at I tilhopa kommen. Då skolen I späka edra kroppar, och offra HERranom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Och skolen intet arbete göra på denna dagen; ty det är en försonedag, at I skolen försonade warda för HERranom edrom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Ty hwilken icke späker sin kropp på denna dagen, den skall utrotad warda utu hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Och hwilken på denna dagen något arbete gör, den skall jag förgöra utu hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Derföre skolen I intet arbete göra. Det skall wara en ewig rätt til edra efterkommande, ehwar I bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Det är edrar store Sabbath, at I skolen späka edra kroppar. På nionde dagen i månadenom om aftonen skolen I hålla denna Sabbath, ifrån aftonen och åter intil aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Och HERren talade med Mose och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Tala med Israels barn, och säg: På femtonde dagen i denna sjunde månadenom är Löfhyddo högtid i sju dagar HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Den förste dagen skall kallas helig, at I samman kommen; intet tjenstearbete skolen I göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'I sju dagar skolen I offra HERranom. Den åttonde dagen skall ock kallas helig, at I samman kommen: Och I skolen göra edart offer HERranom; ty det är samlingesdag: Intet tjenstearbete skolen I göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Desse äro HERrans helgedagar, de I skolen heliga hålla, at I samman kommen, och gören HERranom offer, bränneoffer, spisoffer, dryckoffer, och annor offer, hwart efter sin dag:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Förutan det HERrans Sabbath, och edra gåfwor och löfte, och friwiljoga gåfwor äro, som I gifwen HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Så skolen I nu på femtonde dagen i sjunde månadenom, när I hafwen i hus samlat årswäxten af landena, hålla HERrans högtid i sju dagar. På första dagenom är Sabbath, och på åttonde dagenom är ock Sabbath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Och I skolen på första dagenom taga frukt af skön träd, palmtelningar, och qwistar af tjockqwistadt trä, och pilträ; och wara glade i sju dagar för HERranom edrom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Och skolen alltså hålla HERranom den högtiden om året i sju dagar; det skall wara en ewig rätt til edra efterkommande, at de så skola hålla helg uti den sjunde månaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sju dagar skolen I bo i löfhyddor. Den en inländning är i Israel, han skall bo i löfhyddor:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'At edre efterkommande skola weta, huru jag hafwer låtit Israels barn bo i hyddor, då jag förde dem utur Egypti land. Jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Och Mose sade Israels barnom om denna HERrans helg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Bjud Israels barnom, at de bära til dig klara stötta bomoljo til lysning, hwilken dageliga skall slås up i lamporna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Utanför wittnesbördsens förlott i wittnesbördsens tabernakel. Och Aaron skall sköta det både afton och morgon för HERranom dageliga. Det skall wara en ewig rätt med edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Och skall han pynta til lamporna på dem sköna ljusastakanom för HERranom dageliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Och du skalt taga semlomjöl, och bara deraf tolf kakor; en kaka skall hålla twå tijungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Och skalt lägga dem ju sex i hwar hop på det sköna bordet för HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Och skalt lägga på dem rent rökelse, at det skall wara åminnelse-bröd til et offer HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'På hwar Sabbathsdag skall han pynta dem til HERranom alltid, af Israels barn til et ewigt förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Och skola höra Aaron och hans söner til, de skola äta dem på heligt rum; ty det är hans aldrahelgasta af HERrans offer til en ewig rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Och en man utgick, enes Israelitiska qwinnos son, den ens Egyptisk mans son war ibland Israels barn, och trätte med en Israelitisk man i lägret:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Och nämnde namnet, och bannades. Då hade de honom fram för Mose. Och hans moder het Selomith, Dibri dotter af Dans slägte:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Och de lade honom i fängelse, til dess dem worde wiss swar gifwen genom HERrans mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'För honom ut för lägret, som bannats hafwer, och låt alla dem, som det hörde, lägga sina händer på hans hufwud, och låt hela menighetena stena honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Och säg Israels barnom: Hwilken som bannar sin GUD, han skall bära sina synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Hwilken som HERrans namn nämner, han skall döden dö; hela menigheten skall stena honom. Såsom utländningen, så skall ock inländningen wara: Om han nämner det namnet, så skall han dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Om någor slår ena mennisko, han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Men den som slår någon boskap, han skall betalat kropp för kropp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Och den som gör sinom nästa skada, honom skall man göra såsom han gjorde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Skada för skada, öga för öga, tand för tand; såsom han hafwer gjort ene mennisko skada, så skall man göra honom igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Så at den som slår någon boskap, den skall betalat; men den som slår ena mennisko, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Samma rätten skall wara ibland eder, så för utländningen, som för inländningen; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Och Mose sade detta för Israels barnom, och förde honom, som bannats hade, ut för lägret, och stenade honom. Och alltså gjorde Israels barn, såsom HERren Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Och HERren talade med Mose på Sinai berg, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Tala med Israels barn, och säg til dem: När I kommen in uti det land, som jag eder gifwandes warder, skolen I hålla landsens helg HERranom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Så at du i sex år sår din åker, och i sex år skär din wingård, och samlar in fruktena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Men på sjunde årena skall landet hålla HERranom sina stora helg, i hwilko du icke skalt så din åker, eller berga din wingård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Och hwad af sig sjelfwo wäxer, efter din afbergning, skalt du icke berga. Och de windrufwor, som utan ditt arbete wäxte äro, skalt du icke afhemta, efter det är landsens helgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Utan landsens helgår skalt du fördenskull hålla, at du skalt äta der af, din tjena re, din tjenarinna, din dagakarl, din hus man, din främling när dig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Din boskap, och djuren i ditt land, allt det der wäxer skall wara til mats.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Och du skalt räkna sju sådana helgår, så at sju år skola sju resor tald warda, och den sju helgårs tiden gör nio och fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Då skalt du låta blåsa i basunen öfwer allt edart land, på tionde dagen i sjunde månadenom, rätt på Försonedagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Och I skolen helga det femtionde året, och skolen kalla det et friår i landena, allom dem som bo derinne; ty det är edart klangår. Så skall hwar och en när eder komma til sina ägor igen, och til sina slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ty det femtionde året är edart klangår. I skolen intet få, ej heller upskära det af sig sjelfwo wäxt är, ej heller afhemta i wingårdenom det utan arbete wäxt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Förty klangåret skall wara heligt ibland eder. Men I skolen äta allt det som marken bär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Det är klangåret, i hwilko hwar man skall komma til sitt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Om du något säljer dinom nästa, eller något köper af honom, skall ingen besnika sin broder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Men efter klangårens tal skalt du köpa det af honom, och hwad åren sedan draga kunna, der efter skall han sälja dig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Efter som åren äro mång til, så skalt du låta risa köpet, och efter som de äro så til, skalt du låta köpet falla; ty han skall sälja dig det efter som det draga kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Så besnike nu ingen sin nästa, utan frukta din Gud; ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Derföre görer efter mina stadgar, och håller mina rätter, at I dem gören, på det I mågen tryggeliga bo i landena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ty landet skall gifwa eder sina frukt, at I skolen hafwa nog til at äta, och bo tryggeliga derinne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Och om du worde sägandes: Hwad skole wi äta på sjunde årena; ty wi så intet, och församle ingen årswäxt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Så will jag bjuda min wälsignelse i sjette årena öfwer eder, så at det skall göra eder tre åras wäxt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Det I fån på de åttonde årena, och af den gamla årswäxten, der äter af intil nionde året, så at I äten af det gamla, intil dess åter ny årswäxt kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Derföre skolen I icke sälja landet ewinnerliga: Ty landet är mitt, och I ären främmande och gäster för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Och I skolen i allt edart land låta landet til lösen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Om din broder warder fattig, och säljer dig sina ägor, och hans näste skyldman kommer til honom, och will lösat, så skall han lösa det hans broder sålt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Om någor wore, som ingen lösare hafwer, och kan med sine hand så mycket åstadkomma, at han löser en del;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Då skall man räkna åratalet sedan han såldet, och hwad igen står, gifwe honom som köpt hafwer, at han må komma til sina ägor igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Om hans hand icke kan finna så mycket, at han kan få någon del igen, så skall det, som han sålt hafwer, wara i köparens händer intil klangåret; då skall det wara ute, och han komme til sina ägor igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ho som säljer bort et boningahus innan stadsmuren, han hafwer et helt års frist til at lösa det igen; det skall wara tiden, innan hwilken han det lösa må.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Om han icke löser det förra än hela året ute är, så skall köparen behålla det ewinnerliga, och hans efterkommande; och skall icke löst utgå i klangårena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Men är det et hus i sådana by, der ingen mur om är, det skall man räkna lika med markene i landena; och skall warda löst, och i klangårena fritt utgå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'De Leviters städer, och husen i städerna, der deras ägor inne äro, måga alltid löste warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Den som något löser ifrå de Leviter, den skall gå derifrån i klangårena, ware sig hus eller stad, som han besuttit hafwer; förty husen uti de Leviters städer äro deras ägor ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Men markena för deras städer skall man icke sälja; förty det är deras egendom ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Om din broder warder fattig, och af sig kommer när dig, så skalt du taga honom til dig, såsom en främling eller husman, at han må lefwa när dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Och du skalt icke taga ocker af honom, eller winning; utan skalt frukta din Gud, at din broder må lefwa bredewid dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Ty du skalt icke få honom dina pen ningar på ocker, och icke utfå din spis på fördel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ty jag är HERren edar Gud, den eder utur Egypti land fört hafwer, at jag skulle gifwa eder det landet Canaan, och wara edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Om din broder warder fattig när dig, och säljer dig, så skalt du icke låta honom göra trälars arbete:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Utan han skall wara när dig, såsom en dagakarl och en husman, och tjena dig intil klangåret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Då skall han gå lös ut ifrå dig, och hans barn med honom; och skall komma til sitt slägte igen, och til sina fäders ägor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Förty de äro mine tjenare, de jag utur Egypti land fört hafwer; ty skall man icke sälja dem efter trälars sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Och skalt du icke med stränghet råda öfwer dem, utan frukta din Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Men wilt du hafwa trälar och trälinnor, så skalt du köpa dem af Hedningarna, som omkring eder äro:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Af husmän, som främlingar ibland eder äro, och af deras afkommandom, som de när eder uti lande föda, dem skolen I hafwa til egna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Och skolen äga dem, och edor barn efter eder til en ewig ägo; dem skolen i låta wara trälar. Men öfwer edra bröder, Israels barn, skall ingen öfwer den andra råda med stränghet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Om en främling eller en husman wäxer til när dig, och din broder warder fattig när honom, och säljer sig enom främling, eller husmanne när dig, eller någrom af sine slägt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Så skal han rätt hafwa, sedan han såld är, at warda löst igen; och någor af hans bröder må lösa honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Eller hans faderbroder, eller faderbroders son, eller eljest någor hans när skyldman i hans slägte; eller om hans egen hand kan så mycket åstadkomma, så skall han lösa sig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Och skall räkna med sin köpare ifrå det året, då han sålde sig, intil klangåret. Och penningarne skola räknade warda efter åratalet, sedan han såldes; och skall hans lön med inräknas för hela tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Om ännu mång år äro intil klangåret, så skall han der efter desto mer gifwa för lösnen, efter som han köpt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Äro få år qwar intil klangåret, så skall han ock der efter igengifwa til sin lösning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Och skall räkna sin lön med honom år ifrån år. Och skalt icke låta råda öfwer honom med stränghet för din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Om han icke löser sig i denna måtto, så skall han i klangåret lös utgå, och hans barn med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Förty Israels barn äro mine tjenare, de jag utur Egypti land fört hafwer. Jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'I skolen icke göra eder några afgudar, eller beläte, icke heller upresa eder några stodar, icke heller någon wårdsten sätta uti edro lande, til at tilbedja derföre: Ty jag är HERren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Håller mina Sabbather, och frukter eder för min helgedom. Jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Om I wandren i minom stadgom, och hållen min bud, och gören dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Så skall jag gifwa eder regn i sinom tid; landet skall gifwa sin wäxt, och trän på markene bära sina frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Och tröskotiden skall räcka intil winandena, och winanden skall räcka intil sädestiden. Och I skolen hafwa bröd nog, och skolen tryggeliga bo i edro lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Jag skall gifwa frid i edro lande, at I skolen sofwa, och ingen förfära eder. Jag skall låta komma de onda djur utur edro lande, och intet swärd skall gå genom edart land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'I skolen jaga edra fiendar, och de skola falla för eder genom swärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Fem af eder skola jaga hundrade, och hundrade af eder skola jaga tio tusende; ty edre fiender skola falla för eder genom swärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Och jag skall wända mig til eder; jag skall föröka eder, och låta eder wäxa til, och jag skall göra mitt förbund fast med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Och I skolen äta af det gamla, så at I skolen låta det gamla fara för det nya.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Jag skall hafwa min boning ibland eder, och min själ skall icke förkasta eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Och jag skall wandra ibland eder, och skall wara edar Gud, så skolen I wara mitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ty jag är HERren edar Gud, den eder utur Egypti land fört hafwer, at I icke skullen wara deras trälar. Och hafwer sönderbrutit edart ok, och hafwer låtit eder gå rätta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Men om I icke hören mig, och icke gören dessa buden all:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Utan förakten mina stadgar, och edra själar förkasta mina rätter, så at I icke gören all min bud, och låten mitt förbund tilbaka;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Så skall jag ock då göra eder detta: Jag skall hemsöka eder med förskräckelse, swulnad, och skälfwo, at edor ansikte förfalla, och edre kroppar försmäkta skola: I skolen fåfängt så edra säd, och edre fiender skola äta henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Och jag skall ställa mitt anlete emot eder, och I skolen warda slagne för edra fi endar. Och de som hata eder, skola råda öfwer eder, och I skolen fly, då ingen jagar eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Om I ändå icke hören mig, så skall jag ännu sju resor mer görat, til at näpsa eder för edra synder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'At jag edra högfärd och genstörtighet nederslå skall. Och jag skall göra edar himmel såsom jern, och edra jord såsom koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Och edro möda och arbete skall förtappadt wara, så at edart land icke skall gifwa sin wäxt, och trän i landet icke bära sina frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Och om I wandren mig emot, och icke wiljen höra mig; så skall jag ändå görat sju resor mer, til at slå eder för edra synders skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Och skall sända wilddjur ibland eder: De skola upäta edor barn, och förderfwa edar boskap, och förminska eder; och edre wägar skola warda öde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Om I ändå icke dermed låten rätta eder, och wandren mig emot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Så skall jag ock wandra emot eder, och skall ännu slå eder sju resor mer för edra synders skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Och skall låta komma öfwer eder et hämndeswärd, det mitt förbund hämna skall. Och om I församlen eder uti edra städer, skall jag dock sända pestilentie ibland eder, och skall gifwa eder uti edra fienders händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Så skall jag ock förderfwa edars bröds tilråd, så at tio qwinnor skola baka sitt bröd i enom ugn, och edart bröd skall man utwäga med wigt; och när I äten, skolen I icke warda mätte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Om I dermed än icke hören mig, utan wandren mig emot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Så skall jag ock i grymhet wandra emot eder, och skall sjufallt mer näpsa eder för edra synders skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Så at I skolen äta edra söners och döttrars kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Och jag skall borthäfwa edra högder, och edro beläte utrota, och skall kasta edra kroppar uppå edra afgudar, och min själ skall wämja wid eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Och skall göra edra städer öde, och edra kyrkor förlägga, och skall icke wilja lukta edra söta lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Alltså skall jag göra landet öde, at edre fiender, som bo deruti, skola grufwa sig derföre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Men eder skall jag förskingra ibland Hedningarna, och draga ut swärdet efter eder, at edart land skall blifwa öde, och edre städer omkull slagne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Så skall då landena behaga sin helg, så länge det öde ligger, och I ären i fienda lande. Ja, då skall landet hålla helg, och dess helg thy behaga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Så länge det öde ligger, skall det hålla helg: Derföre, at det icke kunde heligt hålla, då I skullen låtat heligt hålla, då I deruti bodden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Och de som återlefwas af eder, dem skall jag göra et bäfwande hjerta uti deras fiendars lande, så at et ruskande löf skall jaga dem; och skola fiy derföre, likasom et swärd jagade dem, och falla der som ingen jagar dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Och den ene skall falla på den andra, lika såsom för swärd, och dock ingen jagar dem. Och I skolen icke töra duka eder up för edra ttendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Och I skolen förfaras ibland Hedningarna, och edra fiendars land skall fräta eder up.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'De som återlefwas, skola försmäktas i deras missgerningar uti fienda lande; och uti deras fäders missgerningar skola de försmäktas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Så skola de då bekänna sina missgerning, och sina fäders missgerning, i hwilkom de sig förtagit, och emot mig wandrat hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Derföre will jag ock wandra emot dem, och skall drifwa dem bort i deras fienda land. Då warder ju deras oomskorna hjerta sig ödmjukandes. Och då skall dem behaga deras missgerningars straff.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Och jag skall ihogkomma mitt förbund med Jacob, och mitt förbund med Isaac, och mitt förbund med Abraham; och skall tänka uppå landet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Som af dem öfwergifwit är, och hafwer haft et behag til sina helg, medan det öde ligger ifrå dem, och dem behagar deras missgerningars straff, derföre, at de hafwa föraktat mina rätter, och deras själ hafwer haft en wämjelse til mina stadgar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Och om de än i ttenda land äro, hafwer jag likwäl icke förkastat dem, och icke så wämjat wid dem, och mitt förbund med dem skulle intet mer gälla; ty jag är HERren deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Och jag skall för dem ihogkomma mitt första förbund, då jag förde dem utur Egypti land för Hedningarnas ögon, at jag skulle wara deras Gud: Jag är HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Desse äro de stadgar och rätter, och lag, som HERren emellan sig och Israels barn satt hafwer, på Sinai berg, genom Mose hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Och HERren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Tala med Israels barn, och säg til dem: Om någor gör HERranom et besynnerligit löfte, så at han skattar sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Så skall detta wara skattningen: En mansperson tjugu åra gammal, allt intil sextio år, skalt du skatta på femtio silfwer siklar, efter helgedomens sikel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'En qwinsperson på tretio siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Men ifrå fem år intil tjugu år; om det är en mansperson, skalt du skatta honom på tjugu siklar; en qwinsperson på tio siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Är det en månad gammalt, intil fem år; om det är en mansperson, skalt du skatta det på fem silfwer siklar; en qwinno på tre silfwer siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Men är det sextio åra gammalt, och der utöfwer; och är en mansperson, skalt du skatta honom på femton silfwer siklar; en qwinno på tio siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Om han är för fattig til sådana skattning, så skall han gå för Presten, och Presten skall skatta honom: Och han skall skatta honom efter som hans hand, som löftet gjort hafwer, förwärfwa kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Om det är af boskap det man HERranom offra må; allt det man HERranom gifwer, det är heligt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man skall icke wässla det, eller förwandlat, et godt för et ondt, eller et ondt för et godt. Om någor wässlar det, et djur för det andra, så skola de båda wara helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Är det djuret orent, det man icke bör offra HERranom; så skall man hafwa det fram för Presten:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Och Presten skall skatta det, om det är godt eller ondt. Och det skall blifwa wid Prestens skattning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will någor lösa det, han skall gifwa femte delen utöfwer skattningena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Om någor helgar sitt hus, så at det skall wara HERranom heligt; så skall Presten skatta det, om det är godt eller ondt. Och efter som Presten skattar det, så skall det blifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Men om han, som det helgat hafwer, will det lösa, skall han gifwa den femte delen i silfwer, mer än som det skattadt är, och så skall det warda hans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Om någor helgar HERranom et stycke åker af sitt arfwegods, så skall den skattad warda efter som han bär. Bär han en Homer korn, så skall han gälla femtio silfwer siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Men helgar han sin åker strax ifrå klangåret, så skall han gälla efter hans wärde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Hafwer han helgat honom efter klangåret, så skall Presten räkna honom efter de åren, som tilbaka stå intil klangåret, och der efter skatta honom desto ringare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will han, som honom helgat hafwer, lösa åkren, så skall han gifwa femte delen i silfwer, mer än han skattad är, och så skall han warda hans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Will han icke lösan, utan säljer honom enom androm, så skall han icke mer lösa honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Utan den samme åkren, när han i klangåret lös utgår, skall wara helig HERranom, såsom en förspild åker, och skall wara Prestens arfwegods.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Om någor helgar HERranom en åker, den han köpt hafwer, och icke hans arfwegods är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Så skall Presten räkna honom hwad han gälla kan intil klangåret, och han skall på samma dagen gifwa den skattningen ut, at hon skall wara HERranom helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Men på klangåret skall han komma til honom igen, som honom sålt hade, at han blifwer hans arfwegods i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'All skattning skall ske efter helgedomens sikel; men en sikel gör tjugu Gera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Det förstfödda ibland boskapen, det HERranom eljest tilhörer, skall ingen helga, ware sig oxe eller får; ty det är HERrans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Är något orent på boskapen, så skall man lösa det efter sitt wärde, och der utöfwer gifwa den femte delen. Will han icke lösa det, så må det säljas efter sitt wärde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Man skall intet spilgifwit sälja eller lösa, det någor HERranom til spillo gifwer, at allt det hans ägodelar är, ware sig menniska, boskap, eller arfåker; ty allt spilgifwit är det aldrahelgasta HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Man skall ock icke lösa någon spilgifwen mennisko; utan hon skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'All tionde i landet, både af landsens säd, och af frukten af trän, höra HERranom til, och skola wara helig HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Will någor lösa sin tiond, han skall gifwa femtedelen utöfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Och all tiond af fä och får, och allt det under ris går, det är en helig tiond HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man skall icke fråga, om det är godt eller ondt; man skall icke heller wässlat. Om någor wässlar det, så skall både wara heligt, och icke löst warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Desse äro de bud, som HERren böd Mose til Israels barn på Sinai berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Och Herren talade med Mose, i Sinai öken, uti vittnesbördsens tabernakel, på första dagen, i den andra månadenom, i de andra årena, sedan de voro gångne utur Egypti land, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tager en summo af hela Israels barnas menighet, efter deras släkter, och deras faders hus och namn, allt det som mankön är, ifrå hufvud till hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Ifrå tjugu år och derutöfver, allt det som doger till att draga i här i Israel. Och I skolen tälja dem efter deras härar, du och Aaron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Och skolen taga till eder af hvarjo slägtene en höfvitsman öfver hans faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Desse äro namnen af de höfvitsman, som med eder stå skola. Af Ruben: Elizur, Sedeurs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Af Simeon: Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Af Juda: Nahesson, Amminadabs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Af Isaschar: Nethaneel, Zuars son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Af Sebulon: Eliab, Helons son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Af Josephs barn: Af Ephraim, Elisama, Ammihuds son: Af Manasse, Gamliel, Pedahzurs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Af BenJamin: Abidan, Gideoni son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Af Dan: Ahieser, Ammi Sadai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Af Asser: Pagiel, Ochrans son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Af Gad: Eliasaph, Deguels son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Af Naphthali: Ahira, Enans son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Desse äro de namnkunnigaste i menighetene, höfvitsmän i deras faders slägter, som voro hufvud och Förstar i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Och Mose och Aaron togo dem till sig, såsom de vid namn uppräknade voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Och församlade desslikes hela menighetena på första dagen i den andra månadenom, och räknade dem efter deras börd, efter deras slägter och fäders hus och namn, ifrå tjugu är och derutöfver, ifrå hufvud till hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Såsom Herren hade budit Mose; och talde dem uti Sinai öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Rubens barn, som var den förste Israels son, efter deras börd, slägter, deras fäders hus och namn, ifrå hufvud till hufvud, allt det mankön var, ifrå tjugu är och derutöfver, och de som dogde till att draga i här,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'De vordo räknade intill Rubens slägte, sex och fyratio tusend, och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeons barn, efter deras börd, slägter, deras faders hus och namn, ifrå hufvud till hufvud, allt det som mankön var, ifrå tjugu är och derutöfver, och i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Vordo talde intill Simeons slägte, nio och femtio tusend, och trehundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gads barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu är och derutöfver, allt det som i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Vordo talde intill Gads slägte, fem och fyratio tusend, sexhundrad och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Juda barn, efter deras börd, slägter, deras faders hus och namn, ifrå tjugu är och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Vordo talde intill Juda slägte, fyra och sjutio tusend, och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Isaschars barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu är och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Vordo talde intill Isaschars slägte, fyra och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Sebulons barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Vordo talde intill Sebulons slägte, sju och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Josephs barn, af Ephraim, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Vordo talde intill Ephraims slägte, fyratiotusend, och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Manasse barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Vordo talde intill Manasse slägte, tu och tretio tusend, och tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'BenJamins barn, efter deras bord, slägter, deras faders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Vordo talde intill BenJamins slägte, fem och tretio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Dans barn, efter deras börd, slägter, deras faders hus och namn, ifrå tjugu är och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Vordo talde intill Dans slägte, tu och sextio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Assers barn, efter deras börd, slägter, deras faders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Vordo talde intill Assers slägte, ett och fyratio tusend, och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naphthali barn, efter deras börd, slägter, deras faders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Vordo talde intill Naphthali slägte, tre och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Desse äro de som Mose och Aaron, samt med de tolf Israels Förstar, talde, af hvilkom ju en var öfver hvart af deras faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Och summan af Israels barn, efter deras fäders hus, ifrå tjugu är och derutöfver, det i här draga dogde i Israel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Var sex resor hundradetusend, och tretusen, femhundrade och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Men de Leviter, efter deras faders slägter, vordo intet räknade ibland med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Levi slägt skall du intet räkna, eller taga någon summo af dem, ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Men du skall skicka dem till vittnesbördsens tabernakel, och till all dess tyg, och allt det dertill hörer; och de skola bära tabernaklet, och all dess tyg, och skola det sköta, och lägra sig omkring tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Och när man resa skall, då skola de Leviter taga tabernaklet neder; och när hären skall lägra sig, skola de slå tabernaklet upp. Om någor främmande nalkas dertill, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Israels barn skola lägra sig hvar i sitt lägre, och vid sins härs baner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Men Leviterna skola lägra sig omkring vittnesbördsens tabernakel, på det icke skall komma en vrede öfver menighetena af Israels barn. Derföre skola de Leviter vakt hålla vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Och Israels barn gjorde allt det Herren Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Israels barn skola lägra sig allt omkring för vittnesbördsens tabernakel, hvar under sitt baner och tecken, efter deras faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Österut skall sig lägra Juda med sitt baner och här; deras höfvitsman Nahesson, Amminadabs son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Och hans här, de fyra och sjutio tusend, och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Bredovid honom skall sig lägra Isaschars slägte; deras höfvitsman Nethaneel, Zuars son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Och hans här, de fyra och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Dertill Sebulons slägte; deras höfvitsman Eliab, Helons son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Med sin här, de sju och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Så att alle de, som höra till Juda lägre, skola vara i allo hundrade sex och åttatio tusend, och fyrahundrad, de som deras här tillhöra; och de skola draga främst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Söderut skall ligga Rubens lägre och baner med deras har; deras höfvitsman Elizur, Sedeurs son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Och hans häri de sex och fyratio tusend, femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Bredovid honom skall sig lägra Simeons slägte; deras höfvitsman Selumiel, ZuriSadai son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Och hans har, de nio och femtio tusend, trehundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Dertill Gads slägte; deras höfvitsman Eliasaph, Reguels son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Och hans här, de fem och fyratio tusend, sexhundrad och femtio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Så att alle de, som höra till Rubens lägre, skola vara i allo hundrade ett och femtio tusend, fyrahundrad och femtio, de som deras här tillhöra; och skola vara de andre i utdragningene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sedan skall vittnesbördsens tabernakel draga fram med Leviternas lägre midt ibland lägren; och såsom de lägra sig, så skola de ock draga, hvar vid sitt rum under sitt baner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Vesterut skall ligga Ephraims lägre och baner, med deras här; deras höfvitsman skall vara Elisama, Ammihuds son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Och hans här, de fyratiotusend och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Bredovid honom skall sig lägra Manasse slägte; deras höfvitsman Gamliel, Pedahzurs son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Hans här, de tu och tretio tusend, och tuhundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Dertill BenJamins slägte; deras höfvitsman, Abidan, Gideoni son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Hans här de fem och tretio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Så att alle de som Ephraims lägre tillhöra, skola vara hundrade och åtta tusend, och etthundrad, de hans här tillhöra; och skola vara de tredje i utdragningene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Norrut skall ligga Dans lägre och baner; deras höfvitsman Ahieser, AmmiSadai son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Hans här, de tu och sextio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Bredovid honom skall lägra sig Assers slägte; deras höfvitsman Pagiel, Ockrans son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Hans här, de ett och fyratio tusend, och femhundrad:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Dertill Naphthali slägte; deras höfvitsman Ahira, Enans son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Hans här, de tre och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Så att alle de, som höra till Dans lägre, skola vara hundrade sju och femtio tusend, och sexhundrad; och skola vara de ytterste i utdragningene med deras baner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Detta är summan af Israels barn, efter deras fäders hus och lägre med deras härar: sexhundradtusend, och tretusend, femhundrad och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Men de Levi ter vordo intet talde i summan med Israels barnom; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Och Israels barn gjorde allt det Herren hade budit Mose; och lägrade sig under deras baner, och drogo ut hvar i sine slägt efter deras faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Detta är Aarons och Mose slägt, i den tiden, då Herren talade med Mose på Sinai berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Och detta är Aarons söners namn: Den förstfödde Nadab, dernäst Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Det äro namn till Aarons söner, som till Prester smorde voro, och deras händer fyllde till Presterskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Men Nadab och Abihu blefvo döde för Herranom, då de offrade främmande eld för Herranom, uti Sinai öken, och hade inga söner. Men Eleazar och Ithamar skötte Prestaämbetet under deras fader Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Haf fram Levi slägte, och ställ dem inför Presten Aaron, att de skola tjena honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Och hålla hans och hela menighetenes vakt inför vittnesbördsens tabernakel, och tjena i tabernaklets tjenste;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Och vakta all tyg, som vittnesbördsens tabernakel tillhörer, och Israels barnas vakt, till att tjena i tabernaklets tjenste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Och skall gifva Aaron och hans sönom Leviterna till gåfvo af Israels barnom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Men Aaron och hans söner skall du sätta, att de vakta på deras Presterskap. Om någor främmande bjuder sig dertill, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Si, jag hafver tagit de Leviter ibland Israels barn, för allt förstfödt, som moderlif öppnar ibland Israels barn, så att Leviterna skola vara mine.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Förty de förstfödingar äro mine, ifrå den tid jag slog all förstföding i Egypti land; då helgade jag mig all förstföding i Israel, ifrå mennisko allt intill boskapen, att de skola höra mig till: Jag Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Och Herren talade med Mose uti Sinai öken, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Räkna Levi söner efter deras fäders hus och slägter, allt det mankön är, månade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Och så talde Mose dem efter Herrans ord, såsom han budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Och voro desse Levi barn vid namn: Gerson, Kehat, Merari.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Men Gersons barnas namn i deras slägter voro: Libni och Simei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kehats barn i deras slägter voro: Amram, Jizear, Hebron och Usiel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Merari barn i deras slägter voro: Malieli och Musi. Det äro Levi slägter, efter deras fäders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Desse äro Gersons slägter: De Libniter och Simeiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Summan af talet vardt funnen sjutusend och femhundrad, allt det som mankön var, och manade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Och de samma Gersoniters slägter skola lägra sig bakföre tabernaklet, vesterut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Deras öfverste skall vara Eliasaph, Laels son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Och de skola vakta på vittnesbördsens tabernakel, på boningena och täckelset, och dess öfvertäckelse, och på klädet i dörrene af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'På bonaden åt gårdenom, och på klädet i gårdsens ingång, hvilken går omkring boningena och altaret, och på dess tåg, och allt det som till dess tjenste hörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Desse äro Kehats slägter: De Amramiter, de Jizeariter, de Hebroniter och Usieliter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Allt det som mankön var, och månade gammalt, och derutöfver, vid tal åttatusend och sexhundrad, de som akta skola på helgedomens vakt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Och skola lägra sig vid sidona af tabernaklet, söderut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Deras öfverste skall vara Elizaphan, Usiels son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Och de skola vakta arken, bordet, ljusastakan, altaren, och all helgedomens tyg, der de tjena med; och på förlåten, och hvad till dess tjenste tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Men den öfverste öfver alla Leviternas Öfverstar skall vara Eleazar, Prestens Aarons son, öfver dem som skickade äro till att taga vara på helgedomens vakt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Desse äro Merari slägte: De Maheliter och Musiter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Hvilke till talet voro sextusend och tuhundrad, allt det mankön var, månade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Deras öfverste skall vara Zuriel, Abihails son; och skola lägra sig vid sidona af tabernaklet, norrut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Och deras ämbete skall vara, att vakta uppå bräden, skottstängerna, och stolparna, och fötterna åt tabernaklet, och all tyg, som till den tjensten tillhöra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Så ock på stolparna kringom gården, med fötterna, och pålarna, och tågen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Men framför boningena och vittnesbördsens tabernakel österut skola sig lägra Mose och Aaron, och hans söner, att de skola vakta på helgedomen, och på Israels barn. Om någor främmande bjuder sig dertill, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle Leviterna uti en summo, som Mose och Aaron talde efter deras slägter, efter Herrans ord, alltsammans mankön, månade gammalt, och derutöfver, voro tu och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Och Herren talade till Mose: Räkna all förstföding, det mankön är ibland Israels barn, månade gammalt, och derutöfver ock tag talet på deras namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Och skall uttaga Leviterna mig Herranom för all Israels barnas förstföding: och Leviternas boskap, för all förstföding af Israels barnas boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Och Mose talde, såsom Herren honom budit hade, all förstföding ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Och vardt funnet namnens tal, af all förstföding, det mankön var, månade gammalt, och derutöfver, i deras summo, tu och tjugu tusend, tuhundrad, och tre och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Tag de Leviter för all förstföding ibland Israels barn, och Leviternas boskap för deras boskap, att Leviterna skola vara mine, Herrans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Men de lösepenningar för de tuhundrade tre och sjutio, som öfverlöpse i Israels barnas förstföding, utöfver Leviternas tal,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Skall du taga ju fem siklar ifrå hufvud till hufvud, efter helgedomens sikel; tjugu gera gäller en sikel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Och skall de samma penningar, som öfverrisa utöfver deras tal, gifva Aaron och hans sönom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Då tog Mose de lösepenningarna, som öfverriste utöfver Leviternas tal,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Af Israels barnas förstfödingar, tusende trehundrad, och fem och sextio siklar, efter helgedomens sikel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Och fick dem Aaron och hans söner, efter Herrans ord, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Tag summon af Kehats barn utaf Levi söner, efter deras slägter och faders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Ifrå tretio år och derutöfver, allt intill femtionde året, alla de som doga till ämbetet, att de göra de verk i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Och detta skall vara Kehats söners ämbete uti vittnesbördsens tabernakel, det aldrahelgast är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'När hären drager af stad, så skola Aaron och hans söner gå in, och taga ned förlåten, och svepa vittnesbördsens ark deruti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Och lägga täckelset deröfver af tackskinn, och oreda deruppå ett kläde alltsammans gult, och lägga hans stänger dervid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Och breda desslikes öfver skådobordet ett gult kläde, och sätta deruppå fat, skedar, skålar och kannor, der man med ut och in skänker; och det dagliga brödet skall ligga der när;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Och skola breda deröfver ett rosenrödt kläde, och betäcka det med ett täckelse af tackskinn, och lägga dess stänger der när;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Och skola taga ett gult kläde, och svepa ljusens ljusastaka deruti, och hans lampor med hans ljusanäpor och släcketyg, och all oljokar, som ämbetet tillhöra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Och skola lägga om allt detta ett täckelse af tackskinn, och skola lägga dem på stänger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Sammalunda skola de ock breda öfver gyldene altaret ett gult kläde, och betäcka det med täckelset af tackskinn, och lägga dess stänger dervid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'All tyg, som de skola med tjena i helgedomen, skola de taga och lägga ett gult kläde deröfver, och täcka det med ett täckelse af tackskinn, och lägga uppå stänger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'De skola ock sopa askona utaf altaret, och breda ett skarlakanskläde deröfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Och all dess tyg lägga dertill, der de med skaffa hafva deruppå, kolpannor, gafflar, skoflar, bäcken med all redskap till altaret; och skola breda deröfver ett täckelse af tackskinn, och lägga dess stänger dervid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'När nu Aaron och hans söner sådant gjort hafva, och betäckt helgedomen, och all dess redskap, när hären drager af stad, då skola Kehats barn gå in till att bära det, och skola icke komma vid helgedomen, att de icke dö. Detta är Kehats barnas tunge vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Och Eleazar, Prestens Aarons son, skall hafva detta ämbetet, att han skickar oljona till lysning, och speceri till rökverk, och det dagliga spisoffret, och smörjooljan, så att han beskickar hela tabernaklet och allt det deruti är, uti helgedomenom, och hans redskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Och Herren talade med Mose och med Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'I skolen icke låta de Kehatiters slägtes ätt förderfva sig ibland de Leviter:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Utan det skolen I göra med dem, att de måga lefva och icke dö, om de komma vid det aldrahelgasta: Aaron och hans söner skola gå in, och skicka hvar och en till sitt ämbete och tunga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Men icke skola de gå derin, och skåda helgedomen ohöljdan, att de icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Tag desslikes summon af Gersons barn, efter deras faders hus och slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Ifrå tretio år och derutöfver, intill femtionde året, och skicka dem alla, som till ämbete dogse äro, att de skola hafva ämbete i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Och detta skall vara de Gersoniters slägtes ämbete, det de skola sköta och bära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'De skola bära boningenes tapeter, och vittnesbördsens tabernakel, och dess täckelse, och det täckelset af tackskinn, som ofvan öfver är, och klädet i dörrene af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Och den bonaden i gårdenom, och klädet i ingången åt gårdenom, som går omkring tabernaklet och altaret, och deras tåg, och all redskap till deras ämbete, och allt det som deras ämbete tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Efter Aarons och hans söners ord skall allt Gersons barnas ämbete gå, allt det de bära och sköta skola; och I skolen se till, att de taga vara på allan deras tunga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Detta skall vara de Gersoniters barnas slägtes ämbete uti vittnesbördsens tabernakel. Och deras vakt skall vara under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Merari barn, efter deras slägte och fäders hus, skall du ock skicka,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Ifrå tretio är och derutöfver, intill det femtionde året, alla de som till ämbete doga, att de skola hafva ämbete uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'På denna tungan skola de vakta, efter allt deras ämbete uti vittnesbördsens tabernakel, att de bära bräden till tabernaklet, och skottstängerna, och stolparna, och fötterna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Och dertillmed stolparna till gården allt omkring, och fötterna och pålarna, och tågen med all deras redskap, efter allt deras ämbete. Hvar och en skolen I tillskicka sin del af tunganom, till att taga vara på redskapen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Detta vare Merari barnas slägtes ämbete, af allt det de sköta skola uti vittnesbördsens tabernakel, under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Och Mose och Aaron, samt med höfvitsmännerna öfver menighetena, talde de Kehatiters barn, efter deras slägte och faders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Ifrå tretio år och derutöfver, intill femtionde året, alla de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Och summan var tutusend, sjuhundrad och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Det är summan af de Kehatiters slägte, hvilka alle till skaffa hade uti vittnesbördsens tabernakel; de Mose och Aaron talde efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Gersons barn vordo ock talde i deras slägter och fäders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Ifrå tretio år och derutöfver, allt intill det femtionde, alle de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Och summan var tutusend, sexhundrad och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Det är summan af Gersons barnas slägte, de der alle hade till skaffa, uti vittnesbördsens tabernakel, hvilka Mose och Aaron talde efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Merari barn vordo ock talde, efter deras slägter och fäders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Ifrå tretio år och derutöfver, allt intill det femtionde, alle de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Och summan var tretusend och tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Detta är summan af Merari barnas slägte, de Mose och Aaron talde efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Summan af alla Leviterna, som Mose och Aaron, samt med Israels höfvitsmän, talde efter deras slägter och fäders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Ifrå tretio år och derutöfver, intill det femtionde, alle de som ingingo till att skaffa, hvar i sitt ämbete, till att draga tungan uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Var åttatusend, femhundrad och åttatio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'De der talde vordo efter Herrans ord genom Mose, hvar och en till sitt ämbete och tunga, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Bjud Israels barnom, att de låta alla spitelska komma utu lägret, och alla de som etterflöd hafva, och de som på något dödt orene vordne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Både man och qvinno skola de drifva ut för lägret, att de icke skola göra deras lägre orent, der jag uti bor ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Och Israels barn gjorde så, och drefvo dem ut för lägret, såsom Herren hade sagt till Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Tala till Israels barn, och säg till dem: Om en man eller qvinna gör en synd på en mennisko, och förbryter sig dermed emot Herranom, så hafver den själen en skuld uppå sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Och de skola bekänna deras synd, som de gjort hafva, och skola försona deras skuld med lika värd, och derutöfver lägga femtedelen till, och gifva honom, som de emot syndat hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Om ingen är, hvilkom man betala skulle, så skall man gifvat Herranom inför Prestenom, undantagen försoningenes vädur, der han med försonad varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Desslikes skall allt häfoffer af allo thy, som Israels barn helga och offra Prestenom, vara hans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Och hvilken något helgar, det skall ock vara hans; och hvad någor gifver Prestenom, det skall ock vara hans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Tala till Israels barn, och säg till dem: Om en mans hustru förlöper honom, och förbryter sig emot honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Och någor köttsliga belägrar henne, och varder dock mannenom fördoldt för hans ögon, och varder förskyldt att hon oren vorden är, och han kan icke öfvertygat henne; ty hon är icke beslagen dermed;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Och misstankoanden upptänder honom, att han sina hustru misstänker, ehvad hon är oren, eller ej oren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Så skall han hafva henne fram för Presten, och bära fram ett offer öfver henne, tiondeparten af ett epha bjuggmjöl, och skall ingen oljo gjuta deruppå, ej heller lägga der rökelse på; ty det är ett misstankaoffer, och ett röjelseoffer, som missgerning röjer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Då skall Presten hafva henne fram, och ställa henne för Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Och taga af det helga vattnet uti ett lerkar, och lägga stoft af tabernaklets golf i vattnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Och skall ställa qvinnona inför Herran, och blotta hennes hufvud, och lägga röjelseoffret, det ett misstankaoffer är, på hennes hand; och Presten skall hafva i sine hand bittert förbannadt vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Han skall besvärja qvinnan, och säga till henne: Hafver ingen man belägrat dig, och du icke hafver förlupit din man, så att du hafver orenat dig, så skall detta bittra förbannade vattnet intet skada dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Men hafver du förlupit din man, så att du äst oren, och någor hafver belägrat dig förutan din man;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Så skall Presten besvärja qvinnona med sådana förbannelse, och skall säga till henne: Herren sätte dig i förbannelse och till en ed ibland ditt folk; så att Herren låter förfalla dina länder, och din buk svälla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Så gånge nu det förbannade vattnet i ditt lif, så att din buk sväller, och dina länder förfalla. Och qvinnan skall säga: Amen, amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Och så skall Presten skrifva denna förbannelsen på en sedel, och två det af med vattnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Och skall gifva qvinnone dricka af det bittra förbannade vattnet; och när det bittra förbannade vattnet är gånget uti henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Då skall Presten taga det misstankaoffret af hennes hand, och veftoffra det för Herranom till ett spisoffer, och offrat uppå altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Han skall taga en hand full af spisoffret till hennes åminnelse, och bränna det upp på altaret, och derefter gifva qvinnone dricka vattnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Och när hon hafver druckit vattnet, om hon är oren, och hafver sig emot sin man förbrutit; så skall det förbannade vattnet gå in i henne, och vara henne bittert, så att buken sväller på henne, och länderna förfalla; och den qvinna skall vara till en förbannelse ibland hennes folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Är samma qvinna intet orenad, utan är ren; så skall det intet skada henne, så att hon ju må varda hafvandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Detta är misstankas lag, när en qvinna förlöper sin man och varder oren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Eller när en misstankoande upptänder en man, att han misstänker sina hustru, att han skall ställa henne inför Herran; och Presten göre med henne allt efter denna lagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Och mannen skall vara utan skuld för den missgerning, men qvinnan skall bära sin skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Tala till Israels barn, och säg till dem: Om en man eller qvinna gör Herranom ett besynnerligt löfte till återhåll;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Han skall hålla sig ifrå vin och starka drycker; vinättiko och starka dryckers ättiko skall han ock icke dricka, ej heller det af vinbär gjordt varder; han skall hvarken färsk eller torr vinbär äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Så länge som hans löfte varar, skall han icke äta det af vinträ gjordt är, hvarken vinbärskärnarna eller skalena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Så länge hans löftes tid varar, skall icke rakoknif komma på hans hufvud, tilldess tiden är ute, den han Herranom lofvat hafver; ty han är helig, och skall låta fri växa håret på sitt hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'I hela tidenom, den han Herranom lofvat hafver, skall han till ingen dödan gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Han skall ej heller orena sig på sins faders död, sine moders, sins broders, eller sine systers; förty hans Guds löfte är öfver hans hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Och i hela hans löftes tid skall han vara Herranom helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Och om någor oförvarandes bråddör när honom, då varder hans löftes hufvud orent. Derföre skall han raka sitt hufvud på hans renselsedag, det är, på sjunde dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Och på åttonde dagen skall han bära fram två turturdufvor, eller två unga dufvor, till Presten inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Och Presten skall göra den ena till ett syndoffer, den andra till ett bränneoffer, och försona honom, derföre att han syndade öfver en dödan; och alltså på samma dagenom helga hans hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Att han skall uthålla Herranom tiden till sitt löfte; och skall bära fram ett årsgammalt lamb till ett skuldoffer. Dock skola de förra dagarna vara förgäfves, derföre att hans löfte vardt orenadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Detta är hans lag, som sig förlofvat hafver: När hans löftes tid ute är, skall man hafva honom fram för dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Och han skall bära fram sitt offer Herranom, ett årsgammalt lamb utan vank till bränneoffer, och ett årsgammalt får utan vank till syndoffer; och en vädur utan vank till tackoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Och en korg med osyrade kakor af semlomjöl, blandadt med oljo, och osyrade tunnkakor, smorda med oljo, och deras spisoffer och drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Och Presten skall bära det in för Herran, och skall göra hans syndoffer, och hans bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Och väduren skall han göra till ett tackoffer Herranom till den osyrade brödkorgen; och skall desslikes göra hans spisoffer, och hans drickoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Och skall raka dens förlofvades löftes hufvud inför dörrene af vittnesbördsens tabernakel; och skall taga hans löftes hufvudhår, och kasta det på elden, som under tackoffrena är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Och skall taga bogen af väduren sudnan, och en osyrad kako utu korgenom, och en osyrad tunnkako; och skall läggat dem förlofvade på hans händer, sedan han hans löfte af rakat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Och skall veftoffra det för Herranom. Det är heligt Prestenom, samt med veftoffersbröstena, och häfoffersbogenom. Sedan må den förlofvade dricka vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Detta är dens förlofvades lag, som sitt offer lofvar Herranom för sitt löfte, förutan det han eljest förmår. Såsom han lofvat hafver, så skall han ock göra, efter hans löftes lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Tala till Aaron och hans söner, och säg: Så skolen I säga till Israels barn, när I välsignen dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herren välsigne dig, och bevare dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herren låte sitt ansigte lysa öfver dig, och vare dig nådelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herren upplyfte sitt ansigte öfver dig, och gifve dig frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Ty I skolen sätta mitt Namn uppå Israels barn, att jag skall välsigna dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Och då Mose hade upprest tabernaklet, smort det, och helgat det med all dess tyg; dertill ock smort och helgat altaret med all dess tyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Så offrade höfvitsmännerna i Israel, de som ypperst voro i deras faders hus; förty de voro höfvitsman i slägterna, och stodo öfverst ibland dem som talde voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Och de båro sitt offer fram för Herran, sex öfvertäckta vagnar, och tolf oxar, ju en vagn för två höfvitsman, och en oxa för hvardera; och hade dem fram för tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Och Herren sade till Mose:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Tag det af dem, att det må tjena i vittnesbördsens tabernakels tjenste, och få det Leviterna, hvarjom efter sitt ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Då tog Mose vagnarna och oxarna, och fick dem Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Två vagnar och fyra oxar fick han Gersons barnom, efter deras ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Och fyra vagnar och åtta oxar fick han Merari barnom, efter deras ämbete, under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Men Kehats barnom fick han intet; derföre att de ett heligt ämbete på sig hade och måste bära på sina axlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Och höfvitsmännerna offrade till altarets vigning, på den dagen, då det vigdt vardt, och offrade sina gåfvor inför altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Och Herren sade till Mose: Låt hvar höfvitsmannen bära sitt offer fram på sin dag till altarets vigning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'På första dagen offrade Nahesson sina gåfvo, Amminadabs son, af Juda slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Och hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Dertill en gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Och två oxar till tackoffer, fem vädrar, fem bockar, och fem årsgamla lamb. Detta är Nahessons, Amminadabs sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'På den andra dagen offrade Nethaneel, Zuars son, höfvitsmannen för Isaschar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Dertill en gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Nethaneels, Zuars sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'På tredje dagen, höfvitsmannen för Sebulons barn, Eliab, Helons son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Eliabs, Helons sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'På fjerde dagen, höfvitsmannen för Rubens barn, Elizur, Sedeurs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Elizurs, Sedeurs sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'På femte dagen, höfvitsmannen för Simeons barn, Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, nåde full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Selumiels, ZuriSadai sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'På sjette dagen, höfvitsmannen för Gads barn, Eliasaph, Deguels son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Eliasaphs, Deguels sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'På sjunde dagen, höfvitsmannen för Ephraims barn, Elisama, Ammihuds son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Elisama, Ammihuds sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'På åttonde dagen, höfvitsmannen för Manasse barn, Gamliel, Pedahzurs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Gamliels, Pedahzurs sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'På nionde dagen, höfvitsmannen för BenJamins barn, Abidan, Gideoni son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Abidans, Gideoni sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'På tionde dagen, höfvitsmannen för Dans barn, Ahieser, AmmiSadai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Ahiesers, AmmiSadai sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'På ellofte dagen, höfvitsmannen för Assers barn, Pagiel, Ochrans son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem; årsgamla lamb. Detta är Pagiels, Ochrans sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'På tolfte dagen, höfvitsmannen för Naphthali barn, Ahira, Enans son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Ahira, Enans sons, gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Detta är nu altarets vigning, på den tiden, då det vigdt vardt, till hvilket de Israels höfvitsmän offrade dessa tolf silffat, tolf silfskålar, tolf gyldene skedar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Så att ju ett fat höll hundrade och tretio siklar silfver, och ju en skål sjutio siklar; så att summan af allt silfret i faten riste till tutusendfyrahundrade siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Och af de tolf gyldene skedar, fulla med rökverk, höll ju en tio siklar, efter helgedomens sikel; så att summan af guldet i skedarne riste till hundrade och tjugu siklar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Summan af boskapen till bränneoffret var tolf stutar, tolf vädrar, tolf årsgamla lamb, med deras spisoffer; och tolf getabockar till syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Och summan af boskapen till tackoffret var fyra och tjugu oxar, sextio vädrar, sextio bockar, sextio årsgamla lamb. Detta är nu altarets vigning, då det vigdt vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Och när Mose gick in uti vittnesbördsens tabernakel, att med honom skulle taladt varda, så hörde han röstena med sig tala af nådastolenom, som var på vittnesbördsens ark, emellan de två Cherubim; dädan vardt med honom taladt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Tala med Aaron, och säg till honom: När du uppsätter lamporna, skall du så sätta dem, att de alla sju lysa framföre ljusastakan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Och Aaron gjorde så, och satte lamporna upp till att lysa framföre ljusastakan; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Men ljusastaken var af tätt guld, både hans lägg och hans blommor; efter den eftersyn, som Herren hade vist Mose, så gjorde han ljusastakan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Tag Leviterna utur Israels barn, och rena dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Och alltså skall du göra med dem, att du dem renar: Du skall stänka skärvatten på dem, och allt slätt afraka allt deras hår, och två deras kläder, så äro de rene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Sedan skola de taga en ung stut, och hans spisoffer, semlomjöl, blandadt med oljo; och en annan ung stut skall du taga till syndoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Och skall hafva Leviterna in för dörrena af vittnesbördsens tabernakel, och församla hela menighetena af Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Och hafva Leviterna fram för Herran; och Israels barn skola lägga sina händer på Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Och Aaron skall veftoffra Leviterna för Herranom utaf Israels barn, att de tjena skola i Herrans ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Och Leviterna skola lägga sina händer på stutarnas hufvud; och den ene skall Herranom till ett syndoffer, och den andre till ett bränneoffer gjord varda, till att försona Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Och du skall ställa Leviterna inför Aaron och hans söner, och veftoffra dem Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Och skall således afskilja dem ifrån Israels barn, att de skola vara mine.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Sedan skola de ingå till att tjena ut i vittnesbördsens tabernakel. Alltså skall du rena och veftoffra dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Ty de äro min gåfva utaf Israels barn; och jag hafver tagit dem till mig för allt det som öppnar moderlif, nämliga för förstfödingen i all Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Förty all förstföding i Israels barn är min, både af menniskor och af fänad; den tid jag slog all förstföding i Egypti land, helgade jag dem mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Och tog Leviterna mig till för all förstföding ibland Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Och gaf dem Aaron och hans söner för en gåfvo utur Israels barn, att de tjena skola i Israels barnas ämbete uti vittnesbördsens tabernakel, till att försona Israels barn; på det att ibland Israels barn icke skall komma en plåga, om de ville nalkas helgedomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Och Mose, med Aaron och hela menigheten af Israels barn, gjorde med Leviterna allt såsom Herren Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Och Leviterna renade sig, och tvådde sin kläder; och Aaron veftoffrade dem för Herranom, och försonade dem, att de vordo rene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Sedan gingo de in att göra sitt ämbete uti vittnesbördsens tabernakel, för Aaron och hans söner. Såsom Herren hade budit Mose om Leviterna, så gjorde de med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Detta är det Leviterna bör: Ifrå fem och tjugu år, och derutöfver, doga de till ämbete och tjenst i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Men ifrå femtionde året skola de vara löse ifrå tjenstenes ämbete, och skola icke mera tjena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Utan taga vara på deras bröders tjenst uti vittnesbördsens tabernakel; men ämbetet skola de icke sköta. Alltså skall du göra med Leviterna, att hvar och en tager vara på sina vakt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Och Herren talade med Mose uti Sinai öken, i andra årena, sedan de voro dragne utur Egypti land, i första månadenom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Låt Israels barn hålla Passah i sinom tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'På fjortonde dagen i denna månadenom om aftonen, i sinom tid, skola de hållat, efter alla dess stadgar och rätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Och Mose talade med Israels barn, att de skulle hålla Passah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Och de höllo Passah på fjortonde dagen i första månadenom om aftonen, uti Sinai öken. Allt såsom Herren hade budit Mose, så gjorde Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Då voro der någre män orene öfver ena döda mennisko, så att de icke kunde hålla Passah på den dagen; de gingo på samma dagen till Mose och Aaron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Och de sade till honom: Vi äre orene öfver ena döda mennisko; hvi skulle vi så föraktelige vara, att vi icke måge bära Herranom våra gåfvo i sin tid, ibland Israels barn?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mose sade till dem: Bider, jag vill höra hvad Herren bjuder eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Tala till Israels barn, och säg: Om någor orenas på någon dödan, eller fjerran är ifrån eder på markene, eller ibland edra slägt, han skall ändå hålla Herranom Passah;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Dock uti den andra månaden, på fjortonde dagenom om aftonen; och de skola ätat med osyradt bröd och salso;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Och skola intet låta deraf blifva qvart till morgonen, och intet ben sönderbryta deraf; och skola hållat efter allt Passah sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Men den som ren är, och icke är på markene, och försummar hålla Passah, hans själ skall utrotad varda utu hans folk; derföre, att han icke hafver burit Herranom sina gåfvo i sinom tid; han skall bära sin synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Och om en främling bor när eder, han skall ock hålla Herranom Passah, och skall hållat efter de stadgar och sätt, som Passah kräfver. Detta sättet skall vara eder allom ens, så dem utländska, som dem inländska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Och på den dagen, då tabernaklet uppsatt vardt, öfvertäckte det en molnsky på vittnesbördsens tabernakel. Om aftonen, och sedan intill morgonen, var öfver tabernaklet såsom en eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Så skedde det allestädes, att molnskyn öfvertäckte det om dagen, och om nattena såsom en eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Och efter som molnskyn hof sig upp ifrå tabernaklet, så foro Israels barn; och uppå hvad rum molnskyn blef, der lägrade sig Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Efter Herrans ord foro Israels barn, och efter Herrans ord lägrade de sig. Så länge molnskyn blef öfver tabernaklet, så länge lågo de stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Och när molnskyn i flera dagar dvaldes öfver tabernaklet, så togo Israels barn vara uppå Herrans vakt, och foro ingen vägs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Och när så skedde, att molnskyn var på tabernaklet till några dagars tal, så lägrade de sig efter Herrans ord, och foro efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'När molnskyn der var ifrån aftonen allt intill morgonen, och så hof sig upp, så foro de; eller när han sig om dagen eller nattena upphof, så foro de ock.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Men när han två dagar, eller en månad, eller eljest länge blef öfver tabernaklet, så lågo Israels barn, och foro intet. Och när han då gaf sig upp, så foro de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Ty efter Herrans mun lågo de, och efter Herrans mun foro de; så att de togo vara på Herrans vakt, efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Gör dig två trummeter af tätt silfver, att du brukar dem till att kalla tillhopa menighetena, och när hären af stad skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'När man slätt blås med enom, så skola höfvitsmännerna församla sig till dig; de öfverste öfver tusende i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Men när I trummeten, så skola de lägren draga af stad, som ligga österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Och när I trummeten annan gång, då skola de lägren draga af stad, som ligga söderut; förty, när de resa skola, så skolen I trummeta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Men när menigheten skall församlas, skolen I slätt blåsa, och icke trummeta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'När man blås slätt med dem båda, skall församla sig tal dig hela menigheten inför dörrena af vittnesbördsens tabernakel. Och det blåsandet med trummeterna skola Prestens Aarons söner göra. Och det skall vara eder ett evigt sätt till edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'När I dragen till någon strid uti edro lande emot edra fiendar, som strida på eder, så skolen I trummeta med trummeterna, att uppå eder skall tänkt varda för Herranom edrom Gud, och I mågen löste varda ifrån edra fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Sammalunda ock, när I ären glade, på edra högtider och edra nymånader, skolen I blåsa med trummeterna öfver edor bränneoffer och tackoffer; att det skall vara eder till åminnelse för edrom Gud. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'På tjugonde dagen i dem andra månadenom, i de andra årena, gaf molnskyn sig upp af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Och Israels barn drogo i deras skarar utu Sinai öken; och molnskyn blef uti den öknene Paran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Och de förste drogo af stad, efter Herrans ord genom Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Nämliga det baneret af Juda barnas lägre drog först åstad med deras här; och öfver deras här var Nahesson, Amminadabs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Och öfver den hären af Isaschars barnas slägte var Nathaneel, Zuars son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Och öfver den hären af Sebulons barnas slägte var Eliab, Helons son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Då lade man tillsamman tabernaklet; och Gersons och Merari barn drogo åstad, och båro tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Dernäst följde det baneret af Rubens lägre med deras här; och öfver deras här var Elizur, Sedeurs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Och öfver den hären af Simeons barnas slägte var Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Och Eliasaph, Deguels son, öfver Gads barnas slägtes här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Så drogo ock de Kehatiter åstad, och båro helgedomen; och hine uppsatte tabernaklet tilldess denne kommo efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Dernäst drog det baneret åstad af Ephraims barnas lägre med deras här; och öfver dem var Elisama, Ammihuds son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Och Gamliel, Pedahzurs son, öfver den hären af Manasse barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Och Abidan, Gideoni son, öfver den hären af BenJamins barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Dernäst följde det baneret af Dans barnas lägre med deras här; och så voro all lägren uppe; och Ahieser, AmmiSadai son, var öfver deras här;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Och Pagiel, Ochrans son, öfver den hären af Assers barnas slägte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Och Ahira, Enans son, öfver den hären af Naphthali barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Så foro Israels barn med deras härar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Och Mose sade till sin svåger Hobab, Reguels son, af Midian: Vi drage till de rum, om hvilka Herren sagt hafver: Jag skall gifva eder dem; så kom nu med oss, vi vilje göra det bästa med dig; ty Herren hafver Israel godt tillsagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Han svarade: Jag vill icke med eder, utan fara i mitt land till mina slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Han sade: Käre, öfvergif oss icke; förty du vetst hvar vi skole lägra oss i öknene, och skall vara vårt öga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Och om du far med oss, det goda, som Herren gör med oss, det vilje vi göra med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Så drogo de ifrå Herrans berg tre dagsresor; och Herrans förbunds ark drog för dem tre dagsresor, till att visa dem hvar de hvila skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Och Herrans molnsky var öfver dem om dagen, när de drogo utu lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Och när arken for, så sade Mose: Herre, statt upp, att dine fiender måga förströs; och de som dig hata, måga flyktige varda för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Och när han sattes ned, sade han: Kom igen, Herre, till de många Israels tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Och som folket gjordes otåligt, misshagade det för Herrans öron. Och då Herren hörde det, förgrymmade sig hans vrede, och Herrans eld fängde ibland dem, hvilken förtärde de yttersta lägren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Då ropade folket till Mose. Och Mose bad Herran; så försvann elden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Och det rummet kallade man Thabeera; derföre, att Herrans eld hade sig upptändt ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Ty det meniga folk ibland dem hade fått lusta, och såto och greto samt med Israels barn, och sade: Ho kan fly oss kött till att äta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Vi komme ihåg den fisk, som vi åto till gäfves uti Egypten, och de cucumerer, meloner, purlök, rödlök och hvitlök;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Men nu är vår själ borttorkad; vår ögon se intet annat än Man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Och var Man såsom coriandersfrö, och så till seendes som bedellion.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Och folket lopp hit och dit, och samkade tillhopa, molo det på qvarn, och stötte det sönder i mortare, och kokade det i grytor och gjorde sig der kakor af; och det hade en smak såsom en oljokaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Och när daggen föll om nattena öfver lägret, så föll ock Man dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Då nu Mose hörde folket gråta i deras slägter, hvar och en i sins tjälls dörr, då förgrymmade sig Herrans vrede svårliga. Och Mose vardt ock ångse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Och Mose sade till Herran: Hvi bekymrar du din tjenare; och hvi finner jag icke nåd för din ögon, att du så lägger på mig all folkens tunga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Hafver nu jag allt detta folket, aflat eller födt, att du må säga till mig: Bär dem på dinom armom, såsom en amma bär ett barn, in uti det landet, som du deras fader svorit hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Hvar skulle jag nu taga kött, det jag allo desso folkena gifva skulle? De gråta för mig, och säga: Gif oss kött till att äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Jag förmår icke allt detta folket uppehålla allena; ty det är mig för svårt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Och vill du så göra emot mig, så slå mig heldre ihjäl, om jag eljest hafver funnit nåd för din ögon, att jag icke så skall se min jämmer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Och Herren sade till Mose: Församla mig sjutio män utaf de äldsta i Israel, de som du vetst att de äro de äldste och förmän i folkena, och haf dem fram för vittnesbördsens tabernakel, och ställ dem der när dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Så vill jag komma neder, och der tala med dig, och taga af dinom Anda, som öfver dig är, och få dem, att de måga draga tungan öfver folket med dig, att du icke drager honom allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Och till folket skall du saga: Helger eder till morgons, att I mågen få äta kött; förty eder gråt är kommen inför Herrans öron; ty I sägen: Ho gifver oss kött till att äta; förty vi mådde väl uti Egypten? Derföre skall Herren gifva eder kött, att I äten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Icke i en dag, icke i två, icke i fem, icke i tio, icke i tjugu dagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Utan en månad långt, tilldess att det skall gå eder utaf näsorna, och varda eder en vämjelse; derföre, att I hafven bortkastat Herran, den ibland eder är, och gråtit för honom, och sagt: Hvi äre vi gångne utur Egypten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Och Mose sade: Sexhundradtusend män fotfolk är, der jag ibland är, och du säger: Jag vill gifva eder kött, att I äten en månad långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Skall man slagta får och fä, att man må mätta dem, eller alla fiskar i hafvet församla dertill, att de måga blifva mättade?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Men Herren sade till Mose: Är då Herrans hand förkortad? Men du skall nu se, om min ord dig något värd äro, eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Och Mose gick ut, och sade till folket Herrans ord, och församlade de sjutio män af de äldsta i folket, och ställde dem omkring tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Då kom Herren neder i molnskyn, och talade med honom, och tog af Andanom, som öfver honom var, och gaf de sjutio äldsta männerna. Och när Anden hvilades utöfver dem, propheterade de, och vände sedan intet igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Och så hade ännu två män blifvit qvare i lägrena, den ene het Eldad, den andre Medad. Och Anden hvilades öfver dem; ty de voro ock uppskrefne, ändock de icke utgångne voro till tabernaklet; och de propheterade i lägrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Då lopp en dräng af stad, och bådade det Mose, och sade: Eldad och Medad prophetera i lägrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Då svarade Josua, Nuns son, Mose tjenare, den han utvalt hade, och sade: Min herre Mose, förbjud dem det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Men Mose sade till honom: Hvi äst du så nitisk för mig? Gåfve Gud, att allt Herrans folk propheterade, och Herren låte sin Anda komma öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Och så gingo Mose och de äldste af Israel i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Då kom ett väder ut ifrå Herranom, och lät komma åkerhöns ifrå hafvet, och förströdde dem öfver lägret, den ena dagen såsom den andra, i två dagar långt kringom lägret, två alnar högt uppifrå jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Då stod folket upp på den samma hela dagen och den hela natten, och på allan den dagen derefter, och samkade åkerhöns, och den som minst samkade, han samkade tio homer; och de torkade dem kringom lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Som ännu köttet var under deras tänder, och förr än det åtgånget var, förgrymmade sig Herrans vrede öfver folket, och Herren slog dem med en ganska stor plågo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Deraf heter det samma rummet Lustgrifter; derföre, att man der begrof det lustna folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Ifrå Lustgrifterna drog folket ut till Hazeroth; och blefvo i Hazeroth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Och Mirjam och Aaron talade emot Mose för hans hustrus skull, den Ethiopissan, som han till hustru tagit hade; derföre att han en Ethiopisso hade till hustru tagit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Och sade: Talar nu Herren allena genom Mose? Talar han ock icke genom oss? Och Herren hörde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Men Mose var en ganska saktmodig man, öfver alla menniskor på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Och strax sade Herren till Mose, och till Aaron, och till MirJam: Går ut I tre intill vittnesbördsens tabernakel. Och de gingo alle tre ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Då kom Herren neder i molnstodene, och steg in i dörrena af tabernaklet, och kallade Aaron och MirJam; och de gingo både ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Och han sade: Hörer min ord; om någor är ibland eder en Herrans Prophet, honom vill jag uppenbara mig uti en syn; eller uti en dröm vill jag tala med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Men icke så min tjenare Mose, hvilken uti mitt hela hus trogen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Munteliga talar jag med honom, och han ser Herran såsom han är, icke genom mörk ord eller liknelse. Hvi hafven I då icke fruktat att tala emot min tjenare Mose?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Och Herrans vrede förgrymmade sig öfver dem, och han vände sig bort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Dertill gaf ock molnskyn sig ifrå tabernaklet. Och si, då var MirJam spitelsk såsom en snö; och Aaron vände sig till MirJam, och fick se att hon var spitelsk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Han sade till Mose: Ack min herre! lägg icke denna syndena på oss, i det vi hafve ovisliga gjort, och syndat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Att denna icke blifver såsom ett dödt ting, som kommer ut af moderlifvet; det hafver allaredo bortfrätit hälftena af hennes kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Då ropade Mose till Herran, och sade: Ack Gud! gör henne helbregda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Herren sade: Om hennes, fader hade spottat henne i ansigtet, skulle hon icke skämma sig i sju dagar? Låt innelycka henne i sju dagar utan lägret; sedan låt åter taga henne igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Så vardt då MirJam innelyckt i sju dagar utan lägret, och folket for ingen vägs fram bätter, intilldess MirJam vardt igen anammad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Sedan drog folket ifrå Hazeroth, och lägrade sig uti den öknene Paran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Sänd ut män, de som må bespeja landet Canaan, det jag Israels barn gifva vill; af hvarjo deras faders slägt en myndig man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Mose sände dem ut af den öknene Paran, efter Herrans ord, de som alle voro myndige män ibland Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Och heto alltså: Sammua, Zaccurs son, af Rubens slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Saphat, Hori son, af Simeons slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Caleb, Jephunne son, af Juda slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Jigeal, Josephs son, af Isaschars slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Hosea, Nuns son, af Ephraims slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Palti, Raphu son, af BenJamins slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Gaddiel, Sodi son, af Sebulons slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Gaddi, Susi son, af Josephs slägte af Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Ammiel, Gemalli son, af Dans slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Sethur, Michaels son, af Assers slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Nahebi, Vaphsi son, af Naphthali slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Geuel, Machi son, af Gads slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Desse äro namnen af männerna, som Mose utsände till att bespeja landet. Och Hosea, Nuns son, kallade Mose Josua.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Då nu Mose utsände dem till att bespeja landet Canaan, sade han till dem: Farer upp söderut, och går upp på bergen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Och beser landet, huru det är, och folket, som deruti bor, om det är starkt eller svagt, litet eller mycket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Och hurudana land det är, der de uti bo, om det är godt eller ondt; och hurudana städer äro, der de uti bo, om de äro förvarade med murar, eller ej;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Och hurudana landet är, fett eller magert, och om trä deruti äro, eller ej; varer vid en god tröst, och tager af landsens frukt. Och det var rätt på den tiden, då första vinbären voro mogne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'De gingo upp, och bespejade landet, ifrå den öknene Zin allt intill Rehob, der man går till Hamath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'De gingo också upp söderut, och kommo till Hebron; der var Ahiman, Sesai och Thalmai, Enaks barn. Och Hebron var uppbygdt i sju år förra än Zoan uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Och de kommo intill den bäcken Escol, och skoro der en vinqvist af med en vinklasa, och läto två bära den på en stång, och dertill granatäple och fikon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Det rummet kallas Escols bäck, för den vinklasans skull, som Israels barn der afskoro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Och de vände om, när de hade bespejat landet, efter fyratio dagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Gingo och kommo till Mose och Aaron till hela menigheten af Israels barn, uti den öknene Paran till Kades; och sade honom igen, och hela menighetene, huruledes det stod till, och läto dem se landsens frukt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Och förtäljde dem, och sade: Vi vore in uti det land, dit I oss sänden, der mjölk och hannog uti flyter; och detta är dess frukt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Förutan att der bor starkt folk uti, och der äro ganska faste och store städer; och vi såge der ock Enaks barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'De Amalekiter bo söderut i landena; de Hetheer, och Jebuseer, och Amoreer bo uppå bergen; de Cananeer bo vid hafvet och vid Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Men Caleb stillte folket för Mose, och sade till dem: Låt oss draga ditupp, och taga landet in; förty vi kunne väl vara dem öfvermägtige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Men de män, som hade varit med honom uppfarne, sade: Vi förmåge icke draga ditupp emot det folk; ty de äro oss för starke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Och de förtalade landet, som de skådat hade, för Israels barnom, och sade: Landet, som vi igenomgångit hafve till att bespeja det, uppfräter sina inbyggare; och allt det folk, som vi derinne sågo, är ganska långt folk. Vi såge der ock tyranner, Enaks barn af de tyranner; och vi vorom för vår ögon såsom gräshoppor, och så vorom vi ock för deras ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Då tog hela menigheten till att skria; och folket gret den nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Och all Israels barn knorrade emot Mose och Aaron, och hela menigheten sade till dem: Ack! att vi dock hade mått dött i Egypti land, eller ännu dö måtte i denna öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Hvi förer Herren oss i detta landet, att vi skole falla för svärd, och våra hustrur och barn varda till rofs? Är icke bättre, att vi drage in uti Egypten igen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Och den ene sade till den andra: Låt oss häfva oss upp en höfvitsman, och fara in uti Egypten igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Men Mose och Aaron föllo uppå sin ansigte för hela menighetenes församling af Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Och Josua, Nuns son, och Caleb, Jephunne son, de ock landet bespejat hade, refvo sin kläder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Och sade till alla menighetena af Israels barn: Landet, som vi igenomvandrat hafve till att bespeja det, är ganska godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Hafver Herren vilja till oss, så förer han oss väl uti det landet, och gifver oss det; hvilket ett land är, som mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Faller icke ifrå Herran, och frukter eder intet för detta landsens folk; ty vi vilje äta dem upp såsom bröd. Deras beskärm är gånget ifrå dem, och Herren är med oss; frukter eder intet för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Då sade hela folket, att man skulle stena dem. Så syntes Herrans härlighet på vittnesbördsens tabernakel för all Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Och Herren sade till Mose: Huru länge skall detta folket försmäda mig? Och huru länge vilja de icke tro på mig genom allahanda tecken, som jag ibland dem gjort hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Jag skall slå dem med pestilentie, och förgöra dem, och göra dig till ett större och mägtigare folk, än detta är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Men Mose sade till Herran: Så få de Egyptier det höra; ty du hafver fört detta folket med dine kraft midt ut ifrå dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Och man varder sägandes till detta lands inbyggare, som hört hafva, att du, Herre, äst ibland detta folket, att du ansigte mot ansigte sedd varder, och din molnsky står öfver dem, och du, Herre, går för dem i molnstodene om dagen, och i eldstodene om nattene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Och du dräpte detta folket, såsom en man; så skulle Hedningarna, som sådana rop på dig hörde, tala och säga:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Herren förmådde icke föra det folket in uti det land, som han dem svorit hade; derföre hafver han dräpit dem i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Så lät nu Herrans kraft stor varda, såsom du talat hafver och sagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Herren är långmodig, och af stora barmhertighet, och förlåter missgerning och öfverträdelse, och låter ingen vara ostraffad, utan söker fädernas missgerningar öfver barnen, intill tredje och fjerde led.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Så var nu nådelig öfver detta folks missgerning, efter dina stora barmhertighet, såsom du ock desso folke förlåtit hafver, allt ifrån Egypten, och härtill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Och Herren sade: Jag hafver förlåtit dem det, såsom du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Men så visst som jag lefver, så skall all verlden varda full af Herrans härlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Ty alle de män, som hafva sett mina härlighet, och min tecken, som jag gjort hafver uti Egypten, och uti öknene, och nu tio resor försökt mig, och icke hafva lydt mine röst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Ingen af dem skall få se det landet, som jag deras fader svorit hafver; och ingen skall se det, den mig försmädat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Men min tjenare Caleb, derföre, att en annar Anda med honom är, och hafver troliga följt mig efter, honom skall jag föra in i det landet, der han inkom; och hans säd skall intaga det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Dertill ock de Amalekiter och Cananeer, som i dalarna bo. I morgon vänder om, och drager in uti öknena, på den vägen åt röda hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Huru länge skall denna onda hopen knorra emot mig? Ty jag hafver hört Israels barnas knorran, som de emot mig knorrat hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Derföre säg till dem: Så visst som jag lefver, säger Herren, skall jag göra eder såsom I för min öron sagt hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Edra kroppar skola falla i denna öknene; och alle I, som räknade ären ifrå tjugu år och derutöfver, I som emot mig knorrat hafven,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Skolen intet komma in uti det land, der jag mina hand på upphäfvit hafver, att jag skulle låta eder deruti bo, förutan Caleb, Jephunne son, och Josua, Nuns son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Men edor barn, der I om saden, att de skulle varda till ett rof, dem vill jag föra derin, att de skola få se det land, som I förkasten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Men I, med edra kroppar, skolen falla i denna öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Och edor barn skola varda herdar i öknene, i fyratio år, och umgälla edart horeri, intilldess edra kroppar varda åtgångne i öknene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Efter talet af de fyratio dagarna, i hvilkom I landet bespejaden, ju ett år för hvar dagen, att de skola umgälla edor missgerning i fyratio år; på det I skolen förnimma, hvad det är, när jag tager mina hand ifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Jag Herren hafver det sagt, det vill jag ock så göra allom dessom onda hopenom, som sig emot mig upphäfvit hafver; uti denna öken skola de åtgå, och der dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Alltså dödde af Herrans plågo alle de män, som Mose sändt hade till att bespeja landet, och igenkomne voro, och hade kommit hela menighetena till att knorra deremot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Dermed att de gåfvo landena ett rykte, att det var ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Men Josua, Nuns son, och Caleb, Jephunne son, blefvo lefvande, af de man, som gångne voro till att bespeja landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Och Mose talade dessa orden till all Israels barn; då sörjde folket svårliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Och stodo om morgonen bittida upp, och drogo upp på bergshöjdena, och sade: Här äre vi, och vilje draga upp till de rum, der Herren oss af sagt hafver; ty vi hafve syndat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Men Mose sade: Hvi gån I så utöfver Herrans ord? Det skall icke väl bekomma eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Drager icke upp; förty Herren är icke med eder; att I icke blifven slagne för edra fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Ty de Amalekiter och Cananeer äro der för eder; och I varden fallande för svärd, derföre, att I hafven vändt eder ifrå Herranom; och Herren skall intet vara med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Men de voro förblindade till att draga upp på bergshöjdena; men Herrans förbunds ark och Mose kommo intet utu lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Så kommo de Amalekiter och Cananeer, som på bergen bodde, neder, och slogo dem, och förföljde dem allt intill Horma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Tala med Israels barn, och säg till dem: När I kommen in uti det land, der I uti bo skolen, det jag eder gifva skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Och viljen göra Herranom offer, vare sig bränneoffer, eller ett offer af ett besynnerligit löfte, eller ett friviljeoffer, eller edor högtidsoffer; på det I skolen göra Herranom en söt lukt, af fä eller får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Hvilken nu Herranom sina gåfvo offra vill, han skall göra till ett spisoffer en tiung semlomjöl, blandadt med oljo; en fjerding af ett hin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Och vin till drickoffer, sammalunda en fjerding af ett hin till bränneoffer eller eljest till ett offer, der ett lamb offradt varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Men der en vädur varder offrad, skall du göra spisoffret två tiungar semlomjöl, blandadt med oljo, en tridiung af ett hin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Och vin till drickoffer, ock en tridiung af ett hin; det skall du offra Herranom till en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Men vill du göra en stut till bränneoffer, eller till ett besynnerligit löfteoffer, eller till tackoffer Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Så skall du till stuten göra ett spisoffer, tre tiungar semlomjöl, blandadt med oljo, ett hälft hin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Och vin till drickoffer, sammalunda ett hälft hin. Detta är ett offer Herranom till en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Alltså skall du göra med en stut, med enom vädur, med ett får, af lambom och getom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Derefter som talet är af dessa offren, derefter skall ock talet vara till spisoffret och drickoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Den som en inländsker är, han skall detta göra, på det han må göra Herranom ett offer till en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Och om en främling bor när eder, eller ibland eder när edra fränder är, och vill göra Herranom ett offer till en söt lukt; han skall göra såsom de göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Hela menighetene skall vara en stadge, både eder och främlingomen. En evig stadge skall det vara edrom efterkommandom, att för Herranom skall en främling vara såsom I.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'En lag, en rätt skall vara eder och främlingenom, som bor när eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Hala med Israels barn, och säg till dem: När I kommen in uti landet, dit jag eder införa skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Att I äten af landsens bröd, skolen I gifva Herranom ett häfoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Nämliga af edars degs förstling skolen I gifva ena kako till häfoffer, såsom I gifven häfoffer af ladone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Så skolen I ock gifva Herranom förstling af edar deg till häfoffer, med edra efterkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Och om I af ovetenhet försummen något af dessa bud, som Herren till Mose sagt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Och allt det Herren eder genom Mose budit hafver, ifrå den dagen Herren begynte bjuda, intill edra efterkommande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Om nu menigheten gör något ovetandes, så skall hela menigheten göra en ungan stut af boskapen till ett bränneoffer, Herranom till en söt lukt; samt med sitt spisoffer och drickoffer, såsom det sig bör; och en getabock till syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Och Presten skall alltså försona hela menighetena af Israels barn, så varder det dem förlåtet; ty det är en ovetenhet. Och de skola frambära sådana sina gåfvor Herranom till ett offer; och sitt syndoffer för Herranom öfver sina ovetenhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Så varder det förlåtet hela menighetene af Israels barn; dertill ock främlingomen, som bo ibland eder, efter hela folket är i sådana ovetenhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Men när en själ genom ovetenhet syndar, hon skall frambära en årsgammal get till syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Och Presten skall försona sådana ovetande själ med syndoffret för ovetenhetena för Herranom, så att han henne försonar; så varder det henne förlåtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Och det skall vara allt en lag, som I för ovetenhet göra skolen, både dem som inländske äro ibland Israels barn, ock så främlingomen, som bo ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Men om en själ något gör af öfverdådighet, vare sig inländsk eller utländsk, den hafver Herran försmädat; den själen skall utrotad varda utu hennes folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Ty hon hafver föraktat Herrans ord, och gjort hans bud omintet; hon skall platt utrotad varda, och umgälla sin skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Som nu Israels barn voro i öknene, funno de en man hemtande ved om Sabbathsdagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Och de som hade funnit honom dermed, då han hemtade veden, hade honom fram för Mose och Aaron, och för hela menighetena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Och de satte honom i fängelse; ty det var icke klarliga uttryckt, hvad man skulle göra med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Men Herren sade till Mose: Den mannen skall döden dö; hela menigheten skall stena honom utanför lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Så förde hela menigheten honom ut för lägret, och stenade honom ihjäl, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Och Herren sade till Mose:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Tala med Israels barn, och säg till dem, att de skola göra sig klutar på fållarna af deras kläder, i alla deras efterkommandom, och gul snöre i klutomen vid fållarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Och skola de klutar tjena eder dertill, att I skolen se på dem, och ihågkomma all Herrans bud, och göra dem, att I icke efterföljen edars hjertas tycko, eller hor drifven efter edor ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Derföre skolen I ihågkomma och göra all min bud, och helige vara edrom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Jag Herren edar Gud, den eder utur Egypti land fört hafver, att jag skulle vara edar Gud: Jag Herren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Och Koran, Jizears son, Kehats sons, Levi sons, tog till sig Dathan och Abiram, Eliabs söner, och On, Peleths son, af Rubens söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Och de hofvo sig upp emot Mose, med några män af Israels barn, tuhundrade och femtio myndige i menighetene, rådherrar och ärlige män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Och de församlade sig emot Mose och Aaron, och sade till dem: I gören allt för mycket; ty hela menigheten är helig, och Herren är ibland dem; hvi upphäfven I eder öfver Herrans menighet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Då Mose det hörde, föll han uppå sitt ansigte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Och sade till Korah, och hans hela parti: I morgon varder Herren kungörandes, hvilka honom tillhöra, hvilken helig är, och honom offra skall; den han utväljer, han skall offra honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Detta görer: Tager för eder rökopannor, Korah och hans hela parti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Och lägger der eld in, och kaster rökverk deruppå för Herranom i morgon. Hvilken som Herren utväljer, han vare helig; I göret allt för mycket, I Levi barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Och Mose sade till Korah: Käre, hörer dock, I Levi barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Är det eder icke nog, att Israels Gud hafver afskiljt eder ifrå den meniga Israel, att I skolen offra honom, så att I skolen tjena honom i Herrans tabernakels ämbete, och träda fram för menighetena till att tjena henne?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Han hafver tagit dig, och alla dina bröder, Levi barn, samt med dig till sig, och I faren nu ock efter Presterskapet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Du och ditt hela parti gören uppror emot Herran: Hvad är Aaron, att I knorren emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Och Mose sände bort och lät kalla Dathan och Abiram, Eliabs söner; men de sade: Vi komme intet ditupp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Är det icke nog, att du hafver fört oss utu landet, der mjölk och hannog uti flyter, att du skulle dräpa oss i öknene; skall du ännu dertill vara herre öfver oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Skönliga hafver du fört oss in uti det land, der mjölk och hannog uti flyter, och hafver gifvit oss åkrar och vingårdar till arfvedel; vill du ock stinga folke ögonen ut? Vi komme intet ditupp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Då förgrymmade sig Mose ganska svårliga, och sade till Herran: Vänd dig icke till deras spisoffer; jag hafver icke tagit dem en åsna ifrå, och ingen af dem något gjort emot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Och han sade till Korah: Du och ditt hela parti skolen i morgon vara för Herranom, du, de ock, och Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Och hvar tage sina rökopanno, och lägge rökverk deruppå, och går fram för Herran, hvar med sine panno, det äro tuhundrade och femtio pannor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Och hvardera tog sina panno, och lade der eld in, och kastade rökverk deruppå, och gingo in för dörrena af vittnesbördsens tabernakel; och Mose och Aaron desslikes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Och Korah församlade emot dem hela menighetena, inför dörrena af vittnesbördsens tabernakel. Och Herrans härlighet syntes för hela menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Skiljer eder ifrå denna menighetene, att jag med hast må förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Men de föllo på sitt ansigte, och sade: Ack Gud, allt kötts andas Gud! Om en man syndat hafver, vill du då hämnas öfver hela menighetena?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Tala till menighetena, och säg: Kommer upp ifrå Korans, och Dathans, och Abirams tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Och Mose stod upp, och gick till Dathan och Abiram; och de äldste af Israel följde honom efter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Och talade till menighetena, och sade: Går ifrå dessa ogudaktiga menniskors tjäll, och kommer intet vid något det dem tillhörer, att I icke tilläfventyrs förgås uti någon deras synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Och de gingo upp ifrå Korans, Dathans och Abirams tjäll; men Dathan och Abiram gingo ut, och trädde i dörrena af deras tjäll med deras hustrur, söner och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Och Mose sade: Deruppå skolen I märka, att Herren mig sändt hafver, att jag alla dessa gerningar göra skulle; och icke af mino hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Om de dö såsom alla menniskor, eller hemsökta varda, såsom alla menniskor hemsökta varda; så hafver Herren icke sändt mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Men om Herren gör här något nytt, så att jorden öppnar sin mun, och uppslukar dem, med allt det de hafva, att de lefvande fara neder i helvetet; så skolen I förstå, att desse männerna hafva försmädat Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Och som han all dessa orden uttalat hade, remnade jorden under dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Och lät sin mun upp, och uppslukte dem med deras hus, med alla de menniskor, som när Korah voro, och med alla deras håfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Och de foro lefvande neder i helvetet, med allt det de hade; och jorden öfvertäckte dem; och de förgingos utu menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Och hela Israel, som omkring dem var, flydde för deras skris skull; ty de sade: Att jorden icke ock uppslukar oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Dertill for en eld ut ifrå Herranom, och upptärde de tuhundrade och femtio män, som det rökverket offrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Säg Eleazar, Prestens Aarons son, att han upptager rökopannorna utu brandenom, och förströr elden hit och dit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Förty de syndares pannor äro helgade genom deras själar, att man må slå dem i skifvor, och hänga dem på altaret; ty de äro offrade för Herranom, och helgade, och skola vara Israels barnom ett tecken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Och Eleazar Presten tog de kopparpannorna, som de uppbrände män uti offrat hade, och slog dem i skifvor, till att hänga vid altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Israels barnom till en åminnelse, att ingen främmande skulle gå fram, som icke är af Aarons säd, till att offra rökverk för Herranom; på det honom icke skall gå såsom Korah och hans parti, såsom Herren honom sagt hade genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Den andra morgonen knorrade hela menigheten af Israels barn emot Mose och Aaron, och sade: I hafven dräpit Herrans folk. Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Och då menigheten församlade sig emot Mose och Aaron, vände de sig till vittnesbördsens tabernakel; och si, molnskyn öfvertäckte det, och Herrans härlighet syntes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Och Mose och Aaron gingo in för vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Går ut ifrå denna menighetene; jag vill med hast förgöra dem. Och de föllo uppå sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Och Mose sade till Aaron: Tag rökopannona, och låt der eld in af altaret, och kasta rökverk deruppå, och gack snarliga till menighetena, och försona dem; förty vrede är utgången af Herranom, och plågan hafver begynt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Och Aaron tog, såsom Mose sade honom, och lopp midt igenom menighetena; och si, plågan var uppågången ibland folket och han rökte, och försonade folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Och stod emellan de döda och de lefvande; då vardt plågan förtagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Men de som af plågone döde voro, voro fjortontusend och sjuhundrad, undantagnom dem som förgingos uti Korans uppror.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Och Aaron kom igen till Mose för dörrena af vittnesbördsens tabernakel; och plågan var förtagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Säg Israels barnom, och tag af dem tolf stafrar, af hvar och en sins faders hus Första en, och skrif hvarsderas namn på hans staf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Men Aarons namn skall du skrifva på Levi staf; ty ju för hvar sins faders hus höfvitsman skall vara en staf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Och lägg dem in i vittnesbördsens tabernakel, för vittnesbördet, der jag betygar eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Och den som jag utväljandes varder, hans staf skall grönskas; på det att jag må stilla det knorrandet, som Israels barn knorra emot eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Mose talade med Israels barn; och alle deras Förstar fingo honom tolf stafrar, hvar försten en staf efter deras fäders hus; och Aarons stafvar desslikes ibland deras stafrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Och Mose lade stafrarne inför Herran uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Om morgonen, då Mose gick in uti vittnesbördsens tabernakel, fann han Aarons staf af Levi hus grönskas, och blomstren utgångna, och mandel bära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Och Mose bar ut alla strafrarna ifrå Herranom för all Israels barn, så att då sågo det, och hvar och en tog sin staf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Då sade Herren till Mose: Bär Aarons staf åter inför vittnesbördet, att han förvarad varder för ett tecken till de olydiga barnen; att deras knorrande uppå mig må återvända, att de icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mose gjorde såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Och Israels barn sade till Mose: Si, vi förgås, och blifve borto; vi förminskas, och vardom alle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Ho som kommer intill Herrans tabernakel, han dör: skole vi då platt förödas?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Och Herren sade till Aaron: Du och dine söner, och dins faders hus med dig, skolen bära helgedomens missgerning; och du och dine söner med dig skolen bära edars Presterskaps missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Men dine bröder af Levi dins faders slägte skall du taga till dig, att de äro när dig, och tjena dig; men du och dine söner med dig skolen tjena inför vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Och de skola taga vara på din tjenst, och hela tabernaklets tjenst; dock skola de intet nalkas intill helgedomens tyg, och till altaret, att både de och I icke skolen dö;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Utan de skola vara när dig, att de taga vara uppå vittnesbördsens tabernakels tjenst, uti all tabernaklets ämbete; och ingen främmande skall nalkas eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Så akter nu uppå helgedomens tjenste, och uppå altarens tjenste, att icke mer en vrede kommer öfver Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ty si, jag hafver tagit edra bröder Leviterna ut ifrån Israels barn, och gifvit eder Herranom till en skänk, att de skola taga vara på ämbetet vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Men du och dine söner med dig skolen akta på edart Presterskap, att I tjenen uti all altarens handel, och innanför förlåten; ty edart Presterskap gifver jag eder till ett ämbete för en gåfvo; om någor främmande går härtill, han skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Och Herren sade till Aaron: Si, jag hafver gifvit dig mitt häfoffer, af allt det som Israels barn helga, för ditt Prestaämbete, och dinom sönom till en evig rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Detta skall du hafva af det aldrahelgasta, som de offra: Alla deras gåfvor med allt deras spisoffer, och med allt deras syndoffer, och med allt deras skuldoffer, som de mig gifva, det skall vara dig och dinom sönom det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'På aldrahelgasta rum skall du äta det; hvad mankön är, skall deraf äta; ty det skall vara dig heligt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Jag hafver ock gifvit dig och dinom sönom, och dinom döttrom med dig, deras gåfvors häfoffer, i allo Israels barnas veftoffre till en evig rätt: Den som ren är i dino huse, han stall äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alla bästa oljo, och all bästa vinmust, och deras förstlingskorn, det som de gifva Herranom, hafver jag gifvit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Den första frukten af allt det i deras lande är, det som de bära Herranom, skall vara ditt; den som ren är i dino huse, han skall äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Allt det spillgifvet är i Israel, skall vara ditt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Allt det som moderlif öppnar ibland allt kött, det som de bära Herranom, vare sig menniska eller fänad, skall vara ditt; dock så, att du den första fruktena af mennisko låter lösa, och den första frukten af en oren fänad också lösa låter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Och skola de lösa det, när det är en månad gammalt; och skall gifvat till lösen för penningar, för fem siklar efter helgedomens sikel, hvilken tjugu gera gäller.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Men den första frukten af fä eller får, eller get, skall du icke till lösen gifva; ty de äro helig. Deras blod skall du stänka på altaret, och deras feta skall du uppbränna till en söt lukts offer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Deras kött skall vara ditt, såsom ock veftebröstet, och högre bogen din är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Allt häfoffer, som Israels barn helga Herranom, hafver jag gifvit dig och dinom sönom, och dinom döttrom med dig till en evig rätt; det skall vara ett oförgängeligit och evigt förbund för Herranom, dig och dine säd med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Och Herren sade till Aaron: Du skall ingen besittning hafva i deras land, och ingen lott hafva med dem; ty jag är din lott, och ditt arfvegods ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Men Levi barn hafver jag gifvit all tionde i Israel till ett arfvegods, för deras ämbete, som de göra mig vid vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Så att härefter Israels barn intet skola nalkas intill vittnesbördsens tabernakel, till att komma sig i synd och dö;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Utan Leviterna skola akta på ämbetet vid vittnesbördsens tabernakel, och de skola bära deras synder till en evig rätt till edra efterkommande; och de skola intet arfvegods besitta ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Ty Israels barnas tiond, som de häfoffra Herranom, hafver jag gifvit Leviterna till arfvegods; derföre hafver jag sagt till dem, att de ibland Israels barn intet arfvegods besitta skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tala till de Leviter, och säg till dem: När I tagen tionden af Israels barn, den jag eder af dem gifvit hafver till edart arfvegods, så skolen I göra Herranom deraf ett häfoffer, ju tiond af tiond;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Och skolen sådana edart häfoffer hålla såsom I gåfven korn af ladone, och fyllo af pressen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Alltså skolen I ock gifva Herranom häfoffer af allo edro tiond, som I tagen af Israels barnom; så att I sådant Herrans häfoffer gifven Prestenom Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Utaf allt, det eder gifvet varder, skolen I gifva Herranom allahanda häfoffer, af allt det bästa, som deraf helgadt varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Och säg till dem: När I alltså det bästa deraf häfoffren, så skall det Levitomen räknadt varda, lika som det af ladone, och såsom det af pressen gåfves.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Och I mågen det äta allestäds, I och edor barn; ty det är edor lön för edart ämbete uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Så synden I icke deröfver, när I häfoffren det feta deraf, och icke ohelgen det Israels barn helgat hafva, att I icke dön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Detta sättet skall vara en lag, den Herren budit hafver, och sagt: Säg Israels barnom, att de hafva till dig en rödlett ko utan vank, der ingen brist på är, der intet ok ännu påkommet är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Och få henne Prestenom Eleazar, han skall föra henne ut för lägret, och låta der slagta henne för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Och Presten Eleazar skall taga af hennes blod med sitt finger, och stänka rätt emot vittnesbördsens tabernakel sju resor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Och låta uppbränna kona för sig, både hennes hud och hennes kött, dertill hennes blod, samt med gåret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Och Presten skall taga cedreträ och isop, och rosenröd ull, och kasta på den brinnande kona:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Och skall två sin kläder, och bada sin kropp med vatten, och sedan gå i lägret, och vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Och den som uppbrände henne, skall ock två sin kläder med vatten, och bada sin kropp i vatten, och vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Och en ren man skall upptaga askona af kone, och slå henne ut på ett rena rum utan lägret, att hon varder der förvarad åt menighetene af Israels barnom till stänkevatten; ty det är ett syndoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Och den som askona af kone upptog, skall två sin kläder, och vara oren allt intill aftonen. Detta skall vara en evig rätt Israels barnom, och främlingomen, som bo ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Den som kommer vid ena döda mennisko, han skall vara oren i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Så skall han härmed rena sig på tredje dagen, och på sjunde dagen, och så varder han ren. Och om han icke på tredje och sjunde dagen renar sig, så skall han icke ren varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Men om någor kommer vid ena döda mennisko, och icke vill rena sig, den orenar Herrans tabernakel, och sådana själ skall utrotad varda utur Israel; derföre, att stänkevattnet icke är stänkt öfver honom, så är han oren, så länge han sig icke rena låter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Detta är lagen, om en menniska dör i tjället: Den som går in i tjället, och allt det som i tjället är, skall vara orent i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Och hvart och ett botyg, som öppet är, det intet öfvertäckelse eller band hafver, det är orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Desslikes den som på markene kommer vid någon, som slagen är med svärd, eller eljest en dödan, eller ene menniskos ben, eller graf, den är oren i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Så skola de nu för den orena taga af desso uppbrända syndoffers asko, och låta deruppå rinnande vatten uti ett käril.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Och en ren man skall taga isop, och doppa i vattnet, och stänka tjället, och alla botyg, och alla de själar, som derinne äro; sammalunda ock den som hafver kommit vid ens döds ben, eller en slagnan, eller en dödan, eller någon graf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Och den rene skall stänka den orena på tredje dagen, och på sjunde dagen, och rena honom på sjunde dagen; och skall två sin kläder, och bada sig i vatten, så varder han ren om aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Men hvilken som varder oren, och icke vill rena sig, hans själ skall utrotad varda utu menighetene; förty han hafver orenat Herrans helgedom, och icke är med stänkevattne stänkt; derföre är han oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Och detta skall varda dem en evig rätt. Skall också den som med stänkevattnena stänkte, två sin kläder; och den som kommer vid stänkevattnet, han skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Och allt det han kommer vid, det skall vara orent. Och hvilken själ, som han vederkommer, hon skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Och Israels barn kommo med hela menighetene in uti den öknena Zin, i första månaden; och folket blef i Kades. Och MirJam blef der död, och vardt der begrafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Och menigheten hade intet vatten; och de församlade sig emot Mose och Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Och folket trätte med Mose, och sade: Ack! det vi hade förgångits, der vare bröder förgingos för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Hvi hafven I fört denna Herrans menighet uti denna öknena, att vi här dö skole med vårom boskap?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Och hvi hafven I fort oss utur Egypten intill denna onda platsen, der man intet så kan; der hvarken äro fikon eller vinträ, ej heller granatäple; och är dertillmed intet vatten till att dricka?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Då gingo Mose och Aaron ifrå menighetene intill dörrena af vittnesbördsens tabernakel, och föllo på sitt ansigte; och Herrans härlighet syntes dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Tag stafven, och församla menighetena, du och din broder Aaron, och taler till hälleberget för deras ögon; det skall gifva sitt vatten. Alltså skall du skaffa dem vatten utu hälleberget, och gifva menighetene dricka, och deras boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Då tog Mose stafven för Herranom, såsom han honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Och Mose och Aaron församlade menighetena inför hälleberget, och sade till dem: Hörer, I olydige; månne vi ock skole skaffa eder vatten utu detta hälleberget?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Och Mose hof upp sina hand, och slog på hälleberget med sin staf två gånger; då gick der ut mycket vatten, så, att menigheten fick dricka, och deras boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Och Herren sade till Mose och Aaron: Derföre, att I icke trodden uppå mig, att I måtten helgat mig för Israels barnom, skolen I icke föra denna menighetena in i det land, som jag dem gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Detta är det trätovattnet, öfver hvilket Israels barn trätte med Herranom, och han vardt helgad i dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Och Mose sände bådskap ut ifrå Kades till de Edomeers Konung: Så låter din broder Israel säga dig: Du vetst all den mödo, som oss påkommen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Att våre fäder voro nederfarne in uti Egypten, och vi i långan tid bodde uti Egypten, och de Egyptier handlade illa med oss och våra fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Och vi ropade till Herran, och han hörde våra röst, och utsände en Ängel, och förde oss utur Egypten: och si, vi äre i Kades, i den staden, som vid dina gränsor är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Låt oss draga igenom ditt land; vi vilje icke fara öfver åker eller vingårdar, och icke dricka vattnet utu brunnarna; vi vilje draga rätta landsstråtena, hvarken vikande på den högra sidona eller på den venstra, tilldess vi komme igenom dina landsändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'De Edomeer sade till dem: Du skall icke draga härigenom, eller jag skall möta dig med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Israels barn sade till dem: Vi vilje draga den meniga stråtena; och om vi dricke af ditt vatten, vi och vår boskap, så vilje vi det betala; vi vilje icke utan allenast gå till fot derigenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Men han sade: Du skall icke draga härigenom. Och de Edomeer drogo ut emot dem med mägtigt folk, och starka hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Alltså förvägrade de Edomeer Israel draga igenom deras landsändar. Och Israel vek ifrå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Och Israels barn drogo ifrå Kades, och kommo med hela menighetene intill det berget Hor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Och Herren talade med Mose och Aaron på bergena Hor, vid gränsen åt de Edomeers land, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Låt Aaron samla sig till sitt folk; ty han skall icke komma i det landet, som jag Israels barnom gifvit hafver, derföre, att I voren minom mun ohörsamme vid trätovattnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Så tag nu Aaron och hans son Eleazar, och haf dem upp på berget Hor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Och afkläd Aaron hans kläder, och kläd dem på hans son Eleazar; och Aaron skall der samlas, och dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mose gjorde såsom Herren honom bod; och de stego upp på berget Hor, för hela menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Och Mose afklädde Aaron hans kläder, och klädde dem på hans son Eleazar. Och Aaron blef der död uppå berget; men Mose och Eleazar stego neder utaf bergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Och då hela menigheten såg att Aaron var död, begreto de honom i tretio dagar, hela Israels hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Och då den Cananeen, Konungen i Arad, som söderut bor, hörde att Israel inkom genom spejares väg, stridde han emot Israel, och förde några af dem fångna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Då lofvade Israel Herranom ett löfte, och sade: Om du gifver detta folket under mina hand, så skall jag gifva deras städer tillspillo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Och Herren hörde Israels bön, och gaf dem de Cananeer, och de gjorde dem tillspillo med deras städer; och kallade det rummet Horma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Sedan drogo de ifrå berget Hor, på den vägen åt röda hafvet, att de skulle draga omkring de Edomeers land. Och folket vardt ledse på vägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Och folket talade emot Gud, och emot Mose: Hvi hafver du fört oss utur Egypten, att vi skulle dö i öknene? Ty här är hvarken bröd eller vatten, och var själ vämjar öfver denna lösa maten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Då sände Herren ibland folket brännande ormar; de beto folket, så att mycket folk i Israel blef dödt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Så kommo de till Mose, och sade: Vi hafve syndat, att vi emot Herran och emot dig talat hafve; bed Herran, att han tager dessa ormarna ifrån oss. Mose bad för folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Då sade Herren till Mose: Gör dig en kopparorm, och res honom upp för ett tecken; hvilken som biten är, och ser uppå honom, han skall lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Så gjorde Mose en kopparorm, och reste honom upp för ett tecken, och om någor vardt biten af orme, så såg han på den kopparormen, och blef vid lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Och Israels barn drogo ut, och lägrade sig i Oboth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Och ifrån Oboth drogo de ut, och lägrade sig i Ijim vid berget Abarim, uti den öknene tvärtöfver Moab österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Dädan drogo de, och lägrade sig vid den bäcken Sared.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Dädan drogo de, och lägrade sig på denna sidone vid Arnon, hvilket i öknene är, och sträcker sig ut ifrå de Amoreers landsändar; ty Arnon är Moabs landamäre, emellan Moab och de Amoreer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Deraf säger man uti den bokene om Herrans strider: Den höga bergklippan allt intill skyn, och intill Arnons bäck;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Och intill bäcksens källo, hvilken räcker allt intill den staden Ar, och böjer sig, och är Moabs gränsa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Och dädan drogo de till brunnen; det är den brunnen, der Herren af sade till Mose: Församla folket, jag vill gifva dem vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Då söng Israel denna visona, och söngo emot hvarannan öfver brunnen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Denna är den brunnen, som de Förstar grafvit hafva; de ädle i folket hafva grafvit honom, genom läraren och deras stafrar. Ifrå denne öknene drogo de till Mattana;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Och ifrå Mattana till Nahaliel, och ifrå Nahaliel till Bamoth;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Och ifrå Bamoth till den dalen, som ligger i Moabs mark, vid det höga berget Pisga, som vet åt öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Och Israel sände båd till Sihon, de Amoreers Konung, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Låt mig draga igenom ditt land; vi vilje intet vika in på åkrar, eller in på vingårdar; vi vilje icke heller dricka brunnvattnet; landstråtena vilje vi fara, tilldess vi komme genom dina landsändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Men Sihon tillstadde icke Israels barn gå igenom sina landsändar; utan församlade allt sitt folk, och drog emot Israel i öknena. Och som han kom till Jahza, stridde han emot Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Men Israel slog honom med svärdsegg, och tog hans land in, ifrån Arnon allt intill Jabbok, och allt intill Ammons barn; förty Ammons landsändar voro faste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Alltså tog Israel alla dessa städerna, och bodde i alla de Amoreers städer, i Hesbon, och alla hans döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Ty staden Hesbon hörde Sihon Amoreers Konunge till, och han hade tillförene stridt med de Moabiters Konung, och vunnit honom af all hans land, allt intill Arnon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Deraf säger man i ordspråket: Kommer till Hesbon, att man bygger och upprättar den staden Sihon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Ty en eld är utgången af Hesbon, en låge af den staden Sihon; han hafver uppfrätit Ar de Moabiters; och de der bo i de höjder Arnon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ve dig, Moab; du Chemos folk äst förgånget. Man hafver hans söner slagit på flyktena, och fört hans döttrar fångna till Sihon, de Amoreers Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Deras härlighet är vorden omintet, ifrå Hesbon intill Dibon; hon är förstörd allt intill Nopha, hvilken räcker allt intill Medeba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Så bodde Israel uti de Amoreers lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Och Mose sände ut spejare till Jaeser, och de vunno dess döttrar, och togo de Amoreer in, som deruti voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Och vände om, och drogo uppåt den vägen till Basan. Då drog Og, Konungen i Basan, ut emot dem med allt sitt folk, till att strida i Edrei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Och Herren sade till Mose: Frukta dig intet för honom; ty jag hafver gifvit honom i dina hand med land och folk; och du skall göra med honom, såsom du med Sihon, de Amoreers Konung, gjort hafver, hvilken i Hesbon bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Och de slogo honom och hans söner, och allt hans folk, tilldess att ingen var igen; och togo det landet in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Sedan foro Israels barn ut, och lägrade sig i Moabs mark, vid Jordan, in mot Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Och då Balak, Zipors son, såg allt det Israel gjort hade de Amoreer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Och att de Moabiter mycket fruktade för det folket, som så mycket var; och att de Moabiter grufvade sig för Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Då sade de Moabiter till de äldsta af de Midianiter: Nu varder denne hopen uppgnagandes allt det omkring oss är, såsom en oxe uppfräter gräset på markene. Och var Balak, Zipors son, den tiden de Moabiters Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Och han sände ut båd till Bileam, Beors son, den en spåman var; han bodde vid älfvena i hans folks barnas lande; att de skulle kalla honom, och lät säga honom: Si, ett folk är draget utur Egypten, det öfvertäcker jordenes ansigte, och det ligger emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Så kom nu, och förbanna mig det folket; ty det är mig för mägtigt; om jag kunde slå dem, och fördrifva dem utu landet; förty jag vet, hvem du välsignar, han är välsignad, och den du förbannar, han är förbannad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Och de äldste af de Moabiter gingo bort med de äldsta af de Midianiter, och hade spådomslön i deras händer; och gingo in till Bileam, och sade honom Balaks ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Och han sade till dem: Blifver här öfver nattena, så vill jag säga eder igen, hvad Herren mig sägandes varder. Så blefvo de Moabiters Förstar när Bileam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Och Gud kom till Bileam, och sade: Ho äro de män, som när dig äro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam sade till Gud: Balak, Zipors son, de Moabiters Konung, hafver sändt till mig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Si, ett folk är utdraget utur Egypten, och öfvertäcker jordenes ansigte; så kom nu, och förbanna dem; om jag kunde strila med dem, och fördrifva dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Men Gud sade till Bileam: Gack intet med dem, förbanna icke heller folket; ty det är välsignadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Då stod Bileam bittida upp om morgonen, och sade till Balaks Förstar: Går i edart land; förty Herren vill icke tillstädja, att jag går med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Och de Moabiters Förstar stodo upp, kommo till Balak, och sade: Bileam nekar sig vilja komma med oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Då sände Balak ännu yppare och härligare Förstar än hine voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Då de kommo till Bileam, sade de till honom: Så låter Balak, Zipors son, säga dig: Låt dig icke förtryta att komma till mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Ty jag vill högeliga ära dig, och hvad du säger mig, det vill jag göra: Käre, kom, och förbanna mig detta folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileam svarade, och sade till Balaks tjenare: Om Balak gåfve mig sitt hus fullt med silfver och guld, så kunde jag dock icke gå öfver Herrans mins Guds ord, litet eller mycket till att göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Så blifver ock ännu I här i denna natten, att jag må förfara hvad Herren ytterligare med mig talandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Då kom Gud om nattena till Bileam, och sade till honom: Äro desse männerne komne till att kalla dig, så statt upp, och far med dem; dock hvad jag säger dig, det skall du göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Då stod Bileam om morgonen upp, och sadlade sina åsninno, och följde de Moabiters Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Men Guds vrede förgrymmade sig, att han for dit. Och Herrans Ängel trädde fram i vägen, att han skulle stå honom emot. Men han red på sine åsninno, och två dränger voro med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Och åsninnan såg Herrans Ängel stå i vägenom, och ett draget svärd i hans hand. Och åsninnan vek af vägenom in på markena; men Bileam slog henne, att hon skulle gå på vägenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Då trädde Herrans Ängel uti ett trångt tä emellan vingårdar, der på båda sidor gårdar voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Och då åsninnan såg Herrans Ängel, trängde hon sig intill gården, och klämde foten af Bileam in mot gården; och han slog henne ännu mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Då gick Herrans Ängel ytterligare in på ett trångt rum, der ingen väg var till att afvika, antingen på högra eller venstra sidona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Och då åsninnan såg Herrans Ängel, föll hon på knä under Bileam. Då förgrymmade sig Bileams vrede, och han slog åsninnona med stafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Då öppnade Herren åsninnones mun, och hon sade till Bileam: Hvad hafver jag gjort dig, att du hafver slagit mig nu tre gånger?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam sade till åsninnan: Förty du gjorde gäck af mig; ack! hade jag nu ett svärd i handene, jag skulle dräpa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Åsninnan sade till Bileam: Är jag icke din åsninna, der du på ridit hafver i dina dagar intill denna tid? Hafver jag någon tid så plägat göra med dig? Han sade: Nej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Då öppnade Herren Bileams ögon, att han såg Herrans Ängel stå i vägenom, och ett draget svärd uti hans hand, och han neg, och bugade sig med sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Och Herrans Ängel sade till honom: Hvi hafver du slagit dina åsninno nu tre gånger? Si, jag är utgången, att jag skall stå dig emot; ty denne vägen är mig emot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Och åsninnan såg mig, och vek undan för mig i tre gånger: eljest, hvar hon icke undan vikit hade, så hade jag nu slagit dig ihjäl, och åsninnan hade lefvande blifvit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Då sade Bileam till Herrans Ängel: Jag hafver syndat; ty jag visste icke, att du stod emot mig i vägenom. Och nu, om det är icke din vilje, vill jag vända om igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Herrans Ängel sade till honom: Far med dessa männerna; men intet annat skall du tala, utan det jag säger dig. Så följde Bileam Balaks Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Då Balak hörde, att Bileam kom, for han ut emot honom uti de Moabiters stad, som ligger i gränsone vid Arnon, hvilken är vid den yttersta gränson;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Och sade till honom: Hafver jag icke sändt efter dig, och låtit kalla dig? Hvi äst du då icke kommen till mig? Menar du jag kunde icke ära dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bileam svarade honom: Si, jag är kommen till dig; men huru kan jag något annat tala, utan det Gud gifver mig i munnen, det måste jag tala?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Så for Bileam med Balak, och kommo in i gatustaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Och Balak offrade fä och får, och sände efter Bileam, och efter de Förstar som när honom voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Om morgonen tog Balak Bileam, och hade honom upp på Baals höjder, att han dädan af måtte se intill ändan af folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Och Bileam sade till Balak: Bygg mig här sju altare, och låt mig få hit sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak gjorde som Bileam honom sade. Och både Balak och Bileam offrade, ju på hvart altare en stut och en vädur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Och Bileam sade till Balak: Gack till ditt bränneoffer; och jag vill gå bort; om tilläfventyrs Herren kan komma emot mig, och undervisa mig hvad jag skall säga dig. Och gick åstad hasteliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Och Gud kom emot Bileam. Men han sade till honom: Sju altare hafver jag tillredt, och ju på hvart altaret en stut och en vädur offrat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Och Herren gaf Bileam ordet i munnen, och sade: Gack till Balak igen, och säg alltså.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Och då han kom igen till honom, si då stod han när sitt bränneoffer, med alla de Moabiters Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Då hof han sitt tal upp, och sade: Utaf Syrien hafver Balak, de Moabiters Konung, låtit hemta mig, ifrå bergen österut: Kom och förbanna mig Jacob; kom, tala ondt emot Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Huru skall jag förbanna den Gud icke förbannar? Huru skall jag tala ondt emot den Herren intet ondt emot talar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Ty af bergshöjden ser jag honom väl, och af högarna skadar jag honom. Si, det folket varder allena boendes, och icke skall räknadt varda ibland Hedningar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Ho kan räkna Jacobs stoft, och talet på fjerdedelen af Israel? Min själ dö med de rättfärdigas död, och min ände varde såsom dessas ände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Då sade Balak till Bileam: Hvad gör du mig? Jag hafver låtit hem ta dig till att förbanna mina fiendar, och si, du välsignar dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Han svarade, och sade: Skulle jag icke det hålla och tala, som Herren gifver mig i munnen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balak sade till honom: Kom då med mig på en annan plats, dädan du hans ända ser, och dock icke allansamman ser; och förbanna mig honom der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Och tog han honom på en fri plan, uppå kullen af berget Pisga, och byggde sju altare, och offrade ju på hvart altaret en stut och en vädur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Och sade till Balak: Gack till ditt bränneoffer; jag vill vänta derborta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Och Herren kom emot Bileam, och gaf honom ordet i hans mun, och sade: Gack till Balak igen, och säg alltså.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Och då han kom igen till honom, si, då stod han när sitt bränneoffer, med de Moabiters Förstar. Och Balak sade till honom: Hvad hafver Herren sagt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Och han hof upp sitt tal, och sade: Statt upp, Balak, och hör; fatta i öronen hvad jag säger, du Zipors son:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Gud är icke en menniska, att han kan ljuga; eller menniskobarn, att honom något kan ångra. Skulle han säga något, och icke görat? Skulle han något tala, och icke hållat?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Si, till att välsigna är jag hit hafd; jag välsignar, och kan icke omvändat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Man ser ingen mödo i Jacob, och intet arbete i Israel; Herren hans Gud är när honom, och Konungens trummetning ibland honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gud hafver fört honom utur Egypten; hans frimodighet är såsom ens enhörnings.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Ty ingen trollkarl är i Jacob, och ingen spåman i Israel. I sin tid varder man sägandes om Jacob och om Israel, hvilka under Gud gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Si, det folket varder uppståndandes såsom ett ungt lejon, och varder sig uppresandes såsom ett lejon; det skall icke lägga sig, tilldess det äter rof, och dricker deras blod, som slagne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Då sade Balak till Bileam: Du skall hvarken förbanna dem, eller välsigna dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam svarade, och sade till Balak: Hafver jag icke sagt dig, att allt det Herren talandes vorde, det måste jag göra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balak sade till honom: Kom, jag vill hafva dig på en annan plats; om tilläfventyrs Gudi må täckas, att du förbannar dem der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Och han tog honom upp på kullen af det berget Peor, hvilket vet åt öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Och Bileam sade till Balak: Bygg mig här sju altare, och låt mig få sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak gjorde såsom Bileam sade, och offrade ju uppå hvart altaret en stut och en vädur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Då nu Bileam såg, att Herranom täcktes, att han skulle välsigna Israel, gick han intet, såsom tillförene, bort till att söka trolldom, utan vände sitt ansigte rätt emot öknena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Hof sin ögon upp, och såg Israel såsom de lågo efter deras slägter; och Guds Ande kom öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Och han hof upp sitt tal, och sade: Detta säger Bileam, Beors son: Detta säger den man, hvilkom ögonen öppnade äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Detta säger den som hörer Guds tal; den som dens Allsmägtigas uppenbarelse ser, hvilkom ögonen öppnade varda, när han på knä faller:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Huru skön äro din tjäll, Jacob, och din boning, Israel!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Såsom bäcker utvidga sig, såsom örtagårdar vid vatten, såsom tjäll de Herren uppsätter, såsom cedreträ vid vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Vatten skola flyta utu hans ämbar, och hans säd skall varda till ett stort vatten. Hans Konung skall varda högre än Agag, och hans rike skall upphäfva sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gud hafver honom fört utur Egypten; hans frimodighet är såsom ens enhörnings; han skall uppfräta sina motståndare Hedningarna, och deras ben sönderkrossa, och med sina pilar sönderbråka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Han hafver sig nederlagt såsom ett lejon, och såsom ett ungt lejon. Ho vill sätta sig emot honom? Välsignad vare den som dig välsignar, och förbannad den dig förbannar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Då förgrymmade sig Balak i vrede emot Bileam, och slog händerna tillsamman, och sade till honom: Jag hafver kallat dig, att du skulle förbanna mina fiendar; och si, du hafver nu tre gånger välsignat dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Far nu hem till ditt. Jag tänkte, att jag skulle ärat dig; men Herren hafver den ärona förtagit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam svarade honom: Hafver jag ock icke talat med din sändningabåd, som du sände till mig, och sagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Om Balak gåfve mig sitt hus fullt med silfver och guld, så kunde jag dock icke gå utöfver Herrans ord, antingen till att göra ondt eller godt efter mitt sinne; utan hvad som Herren sägandes vorde, det skulle jag ock säga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Och nu, si, när jag far till mitt folk, så kom, jag skall råda dig, hvad detta folk med dino folke göra skall, på yttersta tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Och han hof sitt tal upp, och sade: Detta säger Bileam, Beors son: Det säger den man, hvilkom ögonen öppnade äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Det säger den som hörer Guds tal, och den som, dens Högstas kunskap hafver; den som ser dens Allsmägtigas uppenbarelse, hvilkom ögonen öppnade varda, när han på knä faller:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Jag skall få se honom, men icke nu; jag skall skåda honom, men icke när: En stjerna skall uppgå utaf Jacob, och en spira uppkomma af Israel, och skall sönderkrossa de Moabiters Förstar, och ödelägga all Seths barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Han skall intaga Edom, och Seir skall komma under sina fiendars våld, men Israel skall vinna seger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Utur Jacob varder kommandes den som råda skall, och omkullslå hvad igen är af städerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Och då han såg de Amalekiter, hof han upp sitt tal, och sade: Ainalek de förste ibland Hedningarna; men på sistone blifver du platt borta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Och då han såg de Keniter, hof han upp sitt tal, och sade: Fast är din boning, och du hafver lagt ditt näste, i hällebergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Men du, Kain, skall varda förbränd, när Assur dig fångnan bortförer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Och han hof åter upp sitt tal, och sade: Ack! ho må lefva, när Gud detta göra skall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Och skepp utu Chittim skola förderfva Assur och Eber; men han skall ock förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Och Bileam stod upp, och drog sina färde, och kom igen till sitt rum; och Balak for sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Och Israel bodde i Sittim, och folket begynte bola med de Moabiters döttrar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Hvilka bödo folket till deras gudars offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Och folket åt, och tillbad deras gudar, och Israel höll sig intill BaalPeor; då förgrymmade sig Herrans vrede öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Och Herren sade till Mose: Tag alla öfverstarna för folket, och häng dem upp Herranom i solene, på det den grymme Herrans vrede måtte varda vänd ifrån Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Och Mose sade till de domare i Israel: Hvar och en dräpe sina män, som sig till BaalPeor hållit, hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Och si, en man utaf Israels barn kom, och hade in ibland sina bröder ena Midianitiska qvinno; och lät Mose se det, och hela menighetena af Israels barn, som greto inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Då Pinehas det såg, Eleazars son, Prestens Aarons sons, stod han upp utu menighetene, och tog en knif i sina hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Och gick efter den Israelitiska mannen in uti horohuset, och stack dem, både den Israelitiska mannen och qvinnona, igenom deras buk. Så vände plågan igen af Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Och i de plågone vordo dräpne fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, Eleazars son, Prestens Aarons sons, hafver afvändt mina grymhet ifrån Israels barn, idet han nitisk var om mig, att jag i mitt nit icke skulle förgöra Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Derföre säger jag: Si, jag gifver honom mins frids förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Och han och hans säd efter honom skall hafva ett evigt Presterskaps förbund; derföre, att han för sin Gud hafver nitisk varit, och Israels barn försonat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Men den Israelitiska mannen, som slagen vardt med den Midianitiska qvinnone, het Simri, Salu son, en Förste öfver de Simeoniters fäders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Den Midianitiska qvinnan, som ock slagen vardt, het Cosbi, Zurs dotter, den en Förste var för en slägt ibland de Midianiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Och Herren talade med. Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Gör de Midianiter ondt, och slå dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Förty de hafva gjort eder ondt med deras list, den de eder beställt hafva med Peor, och med deras syster Cosbi, den Midianitiska Förstans dotter, hvilken slagen vardt, på plågones dag, för Peors skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Och skedde efter denna plågona, att Herren talade med Mose och Eleazar, Prestens Aarons son, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Tag summona af hela menighetene af Israels barn, ifrå tjugu år och derutöfver, efter deras fäders hus, alla de som förmå draga i här i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Och Mose, samt med Eleazar Prestenom, talade på de Moabiters mark, vid Jordan in mot Jericho,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Med dem, som tjugu åra gamle voro, och derutöfver, såsom Herren hade budit Mose och Israels barnom, som utur Egypti land dragne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, den förstfödde Israels son. Rubens barn voro: Hanoch, af hvilkom de Hanochiters slägt kommer: Pallu, af hvilkom de Palliters slägt kommer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hezron, af hvilkom de Hezroniters slägt kommer: Charmi, af hvilkom de Charmiters slägt kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Dessa äro Rubens slägter; och deras tal var tre och fyratio tusend, sjuhundrad och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Men Pallu barn voro: Eliab.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Och Eliabs barn voro: Remuel; och Dathan, och Abiram. Desse äro Dathan och Abiram, myndige män i den menighetene, som satte sig upp emot Mose och Aaron uti Korahs parti, då de satte sig upp emot Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Och jorden öppnade sin mun, och upp svalg dem med Korah, då det partiet blefvo döde, och elden förtärde tuhundrad och femtio män; och voro till ett tecken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Men Korahs barn blefvo icke döde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeons barn uti deras slägter voro: Nemuel, af honom kommer de Nemueliters slägt: Jamin, af honom kommer de Jaminiters slägt: Jachin, af honom kommer de Jachiniters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Serah, af honom kommer de Serahiters slägt: Saul, af honom kommer de Sauliters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dessa äro Simeons slägter, tu och tjugu tusend, och tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gads barn uti deras släkter voro: Zephon, af honom kommer de Zephoniters slägt: Haggi, af honom kommer de Haggiters slägt: Suni, af honom kommer de Suniters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osni, af honom kommer de Osniters slägt: Eri, af honom kommer de Eriters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, af honom kommer de Aroditers slägt: Areli, af honom kommer de Areliters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Dessa äro Gads barnas slägter: deras tal fyratiotusend och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Juda barn: Er och Onan, hvilke både blefvo döde i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Och voro Juda barn i deras slägter: Sela, af honom kommer de Selaniters slägt: Perez, af honom kommer de Pereziters slägt: Serah, af honom kommer de Serahiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Men Perez barn voro: Hezron, af honom kommer de Hezroniters slägt: Hamul, af honom kommer de Hamuliters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dessa äro Juda slägter; deras tal sex och sjutio tusend, och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Isaschar barn i deras slägter voro: Thola, af honom kommer de Tholaiters slägt: Phuva, af honom kommer de Phuvaiters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, af honom kommer de Jasubiters slägt: Simron, af honom kommer de Simroniters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Dessa äro Isaschars slägter; deras tal fyra och sextio tusend, trehundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulons barn i deras slägter voro: Sered, af honom kommer de Sarditers slägt: Elon, af honom kommer de Eloniters slägt: Jahleel, af honom kommer de Jahleeliters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dessa äro Sebulons slägter; deras tal sextiotusend, och femhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Josephs barn i deras slägter voro: Manasse och Ephraim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasse barn voro: Machir, af honom kommer de Machiriters slägt: Machir födde Gilead, af honom kommer de Gileaditers slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Gileads barn äro: Jeser, af honom kommer de Jeseriters slägt: Helek, af honom kommer de Helekiters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, af honom kommer de Asrieliters slägt: Sichem, af honom kommer de Sichemiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semida, af honom kommer de Semiditers slägt: Hepher, af honom kommer de Hepheriters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Men Zelaphehad var Hephers son, och hade inga söner, utan döttrar; de heto: Mahela, Noa, Hogla, Milca och Thirza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Dessa äro Manasse slägter; deras tal tu och femtio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ephraims barn i deras slägter voro: Suthelah, af honom kommer de Suthelahiters slägt: Becher, af honom kommer de Becheriters slägt: Thahan, af honom kommer de Thahaniters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Men Suthelahs barn voro: Eran, af honom kommer de Eraniters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dessa äro Ephraims bara as slägter, deras tal tu och tretio tusend, och femhundrad. Dessa äro Josephs barn i deras slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'BenJamins barn i deras slägter voro: Bela, af honom kommer de Belaiters slägt: Asbel, af honom kommer de Asbeliters slägt: Ahiram, af honom kommer de Ahiramiters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Supham, af honom kommer de Supliamiters slägt: Hupham, af honom kommer de Huphamiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Men Bela barn voro: Ard och Naaman, af dem kommer de Arditers och Naamiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dessa äro BenJamins barn i deras slägter; deras tal fem och fyratio tusend, och sexhundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dans barn i deras slägter voro: Suham, af honom kommer de Suhamiters slägt. Dessa äro Dans slägter i deras slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Och alle de Suhamiters slägte i deras tal voro fyra och sextio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Assers barn i deras slägter voro: Jimna, af honom kommer de Jimniters slägt: Jisvi, af honom kommer de Jisviters slägt: Beria, af honom kommer de Beriiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Men Beria barn voro: Heber, af honom kommer de Heberiters slägt: Malchiel, af honom kommer de Malchieliters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Och Assers dotter het Sarah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dessa äro Assers barnas slägter; deras tal tre och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naphthali barn i deras slägter voro: Jahzeel, af honom kommer de Jahzeeliters slägt: Guni, af honom kommer de Guniters slägt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jezer, af honom kommer de Jezeriters slägt: Sillem, af honom kommer de Sillemiters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Dessa, äro Naphthali slägter i deras slägter: deras tal fem och fyratio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Detta är summan af Israels barn, sex gånger hundradetusend, ett tusend, sjuhundrad och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Dessom skall du utskifta landet till arfs, efter namnens tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Mågom skall du gifva mycket till arfs, och fåm litet; hvarjom och enom skall man gifva efter deras tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Dock skall man skifta landet med lott; efter deras faders slägters namn skola de arf taga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Ty efter lotten skall du utskifta dem arfvet, emellan de många och de få.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Och detta är summan af de Leviter uti deras slägter: Gerson, af hvilkom de Gersoniters slägt: Kehat, af hvilkom de Kehatiters slägt: Merari, af hvilkom de Merariters slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dessa äro Levi slägter: De Libniters slägt, de Hebroniters slägt, de Maheliters slägt, de Musiters slägt, de Koralliters slägt; men Kehat födde Amram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Och Amrams hustru het Jochebed, Levi dotter, den honom född var uti Egypten; och hon födde Amram, Aaron och Mose, och deras syster MirJam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Men af Aaron vardt född Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Men Nadab och Abihu blefvo döde, då de offrade främmande eld för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Och deras tal var tre och tjugu tusend, allt mankön ifrå en månad och derutöfver; ty de vordo icke räknade ibland Israels barn: förty man gaf dem icke arf ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Detta är summan af Israels barn, som Mose och Presten Eleazar talde på de Moabiters mark vid Jordan, in mot Jericho;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Ibland hvilka var ingen utaf den summo, då Mose och Presten Aaron talde Israels barn uti Sinai öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Förty Herren hade sagt dem, att de skulle döden dö i öknene. Och ingen blef qvar, utan Caleb, Jephunne son, och Josua, Nuns son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Och Zelaphehads döttrar, Hephers sons, Gileads sons, Machirs sons, Manasse sons, utaf Manasse slägt, Josephs sons, benämnda Mahela, Noa, Hogla, Milca och Thirza, kommo fram;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Och de trädde för Mose, och för Presten Eleazar, och för Förstarna, och hela menighetena, inför dörrena af vittnesbördsens tabernakel, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Vår fader är döder i öknene, och han var icke med i den menighetene, som uppsatte sig emot Herran i Korahs upplopp; utan är i sine synd död blefven, och hade inga söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Hvi skall då vår faders namn borto blifva utu hans slägt, ändock att han ingen son hade? Gifver oss ock arfvegods ibland vår faders bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mose förde deras sak inför Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Och Herren sade till honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Zelaphehads döttrar hafva rätt sagt; du skall ock gifva dem arfvegods med deras faders bröder, och skall deras faders arf vända dem till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Och säg Israels barnom: Om någor dör och hafver inga söner, så skolen I hans arf gifva hans döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Hafver han inga döttrar, skolen I gifva det hans bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Hafver han inga bröder, så skolen I gifva det hans faderbroder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Hafver han icke faderbroder, skolen I gifva det hans nästa fränder, som honom skylde äro i hans slägt, att de taga det in. Det skall vara Israels barnom för en lag och rätt, såsom Herren budit hafver Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Och Herren sade till Mose: Stig upp på berget Abarim, och bese landet, som jag Israels barn gifva skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Och när du det sett hafver, skall du samka dig till ditt folk, såsom din broder Aaron samkad är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Efter det I min ord olydige voren uti den öknene Zin, öfver menighetenes träto, då I mig helga skullen genom vattnet för dem. Det är det trätovattnet i Kades uti den öknene Zin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Och Mose talade med Herranom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Herren Gud öfver allt lefvande kött sätte en man öfver menighetena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Som för dem ut och in går, och förer dem ut och in, att Herrans menighet icke skall vara såsom får utan herda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Och Herren sade till Mose: Tag Josua till dig, Nuns son, hvilken en man är, der Anden uti är, och lägg dina händer på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Och haf honom fram för Presten Eleazar, och för hela menighetena; och bjud honom för deras ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Och lägg dina härlighet uppå honom, att hela menigheten af Israels barn är honom lydig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Och han skall gå fram för Presten Eleazar; han skall rådfråga för honom genom Ljusens sätt inför Herranom. Efter hans mun skola ut och in gå, både han och all Israels barn med honom, och hela menigheten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mose gjorde såsom Herren honom böd; och tog Josua, och ställde honom fram för Presten Eleazar, och för hela menighetena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Och lade sina hand uppå honom, och böd honom, såsom Herren med Mose talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Bjud Israels barnom, och säg till dem: Mitt bröds offer, hvilket mitt offer är till en söt lukt, skolen I hålla i sinom tid, så att I mig det offren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Och säg till dem: Dessa äro de offer, som I offra skolen Herranom: årsgamla lamb, de som utan vank äro, dagliga tu till dagligit bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Ett lamb om morgonen, det andra om aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Dertill tiondeparten af ett epha semlomjöl till spisoffer, blandadt med oljo, den stött är, en fjerdepart af ett hin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Det är ett dagligit bränneoffer, det I uppå Sinai berg offraden, till en söt lukt af ett offer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Dertill dess drickoffer, ju till hvart lambet en fjerdedel af ett hin; och det skall offradt varda i helgedomenom, obemängdt Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Det andra lambet skall du göra om aftonen, såsom spisoffret om morgonen, och dess drickoffer till en söt lukts offer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Men om Sabbathsdagen tu årsgamla lamb utan vank, och två tiungar af semlomjöl till spisoffer, blandadt med oljo, och dess drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Det är hvars Sabbathens bränneoffer, utöfver det dagliga bränneoffret, med sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Men på första dagen i edra månader skolen I offra Herranom ett bränneoffer, två unga stutar, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Och ju tre tiungar semlomjöl till spisoffer, blandadt med oljo, till en stut, och två tiungar semlomjöl till spisoffer, blandadt med oljo, till en vädur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Och ju en tiung semlomjöl till spisoffer, med oljo blandadt, till ett lamb; det är bränneoffret till en söt lukt, ett offer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Och deras drickoffer skall vara, ett hälft hin vin till stuten, en tredjedel af ett hin till väduren, en fjerdedel af ett hin till lambet; det är bränneoffret till hvar månad om året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Dertill skall man göra en getabock till ett syndoffer Herranom, öfver det dagliga bränneoffret, och dess drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Men på fjortonde dagenom i första månaden är Passah Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Och uppå femtonde dagenom i samma månaden är högtid; i sju dagar skall man äta osyradt bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Den förste dagen skall kallas helig, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Och skolen I göra Herranom bränneoffer, två unga stutar, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar stuten, och två tiungar till väduren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Och ja en tiung till hvart af de sju lamben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Dertill en bock till syndoffer, på det I skolen försonade varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Och det skolen I göra om morgonen, förutan det bränneoffret, som ett dagligit bränneoffer är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Efter detta sättet skolen I hvar dag i de sju dagar offra bröd till en söt lukts offer Herranom, till det dagliga bränneoffret, dertill dess drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Och den sjunde dagen skall kallas helig ibland eder, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Och förstlingens dag, då I offren det nya spisoffret Herranom, när edra veckor äro framledna, skall helig kallas, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Och Skolen I göra Herranom bränneoffer till en söt lukt, två unga stutar, en vädur, sju årsgamla lamb;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Och ju en tiung till hvart och ett af de sju lamben;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Och en getabock till att försona eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Detta skolen I göra, förutan det dagliga bränneoffret med sitt spisoffer; utan vank skall det vara; dertill deras drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Och den förste dagen i sjunde månadenom skall ibland eder kallas helig, att I sammankommen; intet tjenstearbete skolen I göra deruppå; det är eder trummetandes dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Och I skolen göra bränneoffer till en söt lukt Herranom, en ungan stut, en vädur, sju årsgamla lamb utan vank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Dertill deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'En tiung på hvart och ett af de sju lamben;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Och en getabock till syndoffer, till att försona eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Förutan månadens bränneoffer, och dess spisoffer, och förutan det dagliga bränneoffret med dess spisoffer, och med deras drickoffer, efter deras sätt, till en söt lukt; det är ett offer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Den tionde dagen i denna sjunde månadenom skall ock när eder kallas helig, att I sammankommen; och I skolen späka edra kroppar, och intet arbete deruppå göra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Utan offra bränneoffer Herranom till en söt lukt, en ungan stut, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Med deras spisoffer, tre tiungar semlomjöl, blandade med oljo, till stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Och en tiung på hvart och ett af de sju lamben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Dertill en getabock till syndoffer, förutan försoningens syndoffer, och det dagliga bränneoffret med sitt spisoffer, och med deras drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Den femtonde dagen i den sjunde månaden skall kallas helig när eder, att I sammankommen; intet tjenstearbete skolen I göra deruppå, och I skolen hålla Herranom helg i sju dagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Och skolen göra bränneoffer till en söt lukts offer Herranom, tretton unga stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar och en af de tretton stutar, två tiungar uppå hvar väduren af de två;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Och en tiung uppå hvart och ett af de fjorton lamben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'På den andra dagen, tolf unga stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer, och med deras drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'På tredje dagen, ellofva stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'På fjerde dagen, tio stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'På femte dagen, nio stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Dertill en getabock till syndoffer, förutan det dagliga brännoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'På sjette dagen, åtta stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'På sjunde dagen sju stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'På den åttonde skall vara församlingenes dag; intet tjenstearbete skolen I göra deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Och skolen offra bränneoffer till en söt lukts offer Herranom; en stut, en vädur, sju årsgamla lamb, utan vank;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Med deras spisoffer och drickoffer, till stuten, till väduren, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Dertill en bock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Detta skolen I göra Herranom i edra högtider, undantagno det I lofven och friviljoge gifven till bränneoffer, spisoffer, drickoffer och tackoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Och Mose sade Israels barnom allt det Herren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Och Mose talade med de Förstar i slägterna af Israels barn, och sade: Detta är det som Herren budit hafver:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Om någor gör Herranom ett löfte, eller svär honom en ed, så att han förpligtar sina själ; han skall icke göra sin ord omyndig, utan göra allt det af hans mun utgånget är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Om en qvinna gör Herranom ett löfte, och förpligtar sig, medan hon är i sins faders huse och i sin pigodom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Och hennes löfte om förpligtelse, som hon gör öfver sina själ, kommer för hennes fader, och han tiger dertill; så gäller allt hennes löfte, och all hennes bepligtelse, som hon sig med öfver sina själ förpligtat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Men om hennes fader säger der nej till, på den dagen han det hörer; så gäller intet löfte eller bepligtelse, der hon sig med öfver sina själ förpligtat hafver; och Herren skall vara henne nådelig, efter fadren hafver det nekat henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Hafver hon man, och hafver ett löfte uppå sig, eller af hennes mun utgår en bepligtelse öfver hennes själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Och mannen hörer det, och tiger den dagen stilla; så gäller hennes löfte och bepligtelse, med hvilko hon sig öfver sina själ förpligtat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Men om hennes man säger der nej till, på den dagen han det hörer; så är hennes löfte löst, som hon hafver på sig, och den bepligtelsen, som af hennes mun öfver hennes själ utgången är; och Herren skall vara henne nådelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Enes enkos löfte, och enes, som bortdrifven är, allt det hon förpligtar sig öfver sina själ, det gäller öfver henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Om någons mans tjenstehjon lofvar, eller sig med en ed förpligtar öfver sina själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Och husbonden hörer det, och tiger dertill, och säger der intet nej till; så gäller allt det löftet, och allt det han sig förpligtat hafver öfver sina själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Om husbonden gör det löst, den dagen, då han det hörer; så gäller det intet, hvad utaf hans mun gånget är, och han lofvat, eller sig förpligtat hafver öfver sina själ; förty husbonden hafver gjort det löst; och Herren skall vara honom nådelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Och allt löfte, och eder, som bepligta till att späka kroppen, må husbonden vidmagthålla, eller omintetgöra alltså.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Om han tiger dertill ifrå den ena dagen till den andra; så gifver han allo hans löfte och förpligtelse magt, som han hafver på sig; derföre, att han hafver tegat, på den dagen, då han hörde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Om han efteråt ryggar det, sedan han det hört hafver, så skall han bära missgerningena. Desse äro de stadgar, som Herren hafver budit Mose emellan man och hustru, emellan fader och dotter, medan hon en piga är i sins faders huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Hämna Israels barn öfver de Midianiter, att du sedan församkar dig till ditt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Så talade Mose med folket, och sade: Väpner män af eder till härs emot de Midianiter, att de hämnas Herran öfver de Midianiter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Utu hvart slägte ett tusend, så att I skicken i hären af alla Israels slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Och de togo af Israels tusender, ju tusende af hvart slägtet, tolftusende väpnade till härs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Och Mose skickade dem med Pinehas, Prestens Eleazars son, i här, och de helga tygen, och de klangtrummeter i hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Och de förde hären emot de Midianiter, såsom Herren hade budit Mose; och slogo ihjäl allt det som mankön var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Dertill slogo de de Midianiters Konungar, med deras slagna, nämliga Evi, Rekem, Zur, Hur och Reba, de fem Midianiters Konungar; Bileam, Beors son, slogo de ock med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Och Israels barn togo till fångar de Midianiters qvinnor med deras barn; all deras boskap, alla deras håfvor, och allt deras gods skinnade de;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Och uppbrände med eld alla deras städer, deras boningar och alla borger;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Och togo allt rof, och allt det till tagandes var, både menniskor och boskap;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Och hade det till Mose, och till Presten Eleazar, och till menighetena af Israels barn, nämliga de fångar och den tagna boskapen, och det skinnade godset, uti lägret på de Moabiters mark, som ligger vid Jordan emot Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Och Mose och Eleazar Presten, och alle Förstarna för menighetene, gingo emot dem ut för lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Och Mose vardt vred på härens höfvitsmän, som höfvitsmän voro öfver tusende, och öfver hundrade, och kommo utu hären och stridene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Och sade till dem: Hafven I låtit alla qvinnor lefva?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Si, hafva icke de förvändt Israels barn, genom Bileams råd, till att synda emot Herran på Peor; och en plåga öfvergick Herrans menighet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Så slår nu ihjäl allt det som mankön är ibland barnen, och alla de qvinnor, som man känt och när legat hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Men all pigobarn, som icke ännu man känt, eller när legat hafva, dem låter för eder lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Och ligger utanför lägret i sju dagar, alle som någon slagit, eller den slagen var vederkommit hafven, på det I skolen rena eder på tredje och sjunde dagen; samt med dem som I till fångar gripit hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Och all kläder, och all tyg af skinn, och allt skinnverk, och all träkäril skolen I skär göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Och Presten Eleazar sade till krigsfolket, som i stridene varit hade: Detta är lagen, som Herren hafver budit Mose:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Guld, silfver, koppar, jern, tenn och bly:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Och allt det som eld lider, skolen I gå låta genom eld, och rena det, att det med stänkevattnena skärt varder; men allt det som icke lider eld, skolen I låta gå genom vatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Och skolen två eder kläder på sjunde dagen, så varden I rene; sedan skolen I komma i lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Tag summona af fångarnas rof, både af menniskor och af boskap, du och Eleazar Presten, och de öfverste fäderna i menighetene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Och gif dem hälftena, som utgingo i hären, och stridt hafva, och andra hälftena menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Och du skall häfoffra Herranom af stridsmännernas del, som i hären voro, ju af femhundrade ena själ, både i menniskor, fä, åsnar och får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Af deras hälfte skall du taga det, och få det Prestenom Eleazar, till att häfoffra det Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Men af den hälften, som Israels barn tillkommer, skall du ju af femtio taga ett stycke, både af menniskor, fä, åsnar och får, och af allom fänad, och skall gifva det Leviterna, som taga vara på Herrans tabernakels vakt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Och Mose, och Eleazar Presten, gjorde såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Och det öfriga bytet, som krigsfolket röfvat hade, var sexhundradetusend, fem och sjutio tusend får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Tu och sjutio tusend nöt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Ett och sextio tusend åsnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Och qvinnfolk, som icke hade känt man eller när legat, tu och tretio tusend själar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Och den hälften, som dem tillkom, som i stridene varit hade, var i talet trehundradetusend, sju och tretio tusend, och femhundrade får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Deraf vordo Herranom sexhundrade fem och sjutio får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Item sex och tretio tusend nöt; deraf vordo Herranom tu och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Item tretiotusend och femhundrade åsnar; deraf vordo Herranom en och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Item menniskors själar, sextontusend själar; deraf vordo Herranom två och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Och Mose fick det Herrans häfoffret Prestenom Eleazar, såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Men den andra hälften, som Mose Israels barnom tillbytt hade ifrå krigsmännerna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Nämliga den hälften, som menighetene tillkom, var ock trehundradetusend, sju och tretio tusend, femhundrade får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Sex och tretio tusend nöt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Tretiotusend och femhundrade åsnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Och sextontusend menniskors själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Och Mose tog af denna hälftene, som Israels barnas var, ju ett stycke af femtio, både af fänaden och af menniskor, och fick det Leviterna, som togo vara på Herrans tabernakels vakt; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Och de som höfvitsmännerna voro öfver de tusend i krigsfolket, nämliga öfver tusend, och öfver hundrade, gingo fram till Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Och de sade till honom: Dine tjenare hafva tagit summona af krigsfolket, som under våra händer varit hafva, och der fattas icke en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Derföre bäre vi Herranom gåfvor, hvad som hvar och en funnit hafver af gyldene tyg, kedjor, armsmide, ringar, örnaringar och spann, att våra själar måga varda försonada för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Och Mose med Prestenom Eleazar tog af dem guldet i allahanda tyg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Och allt gulds häfoffer, som de Herranom häfoffrade, var sextontusend, sjuhundrade och femtio siklar, af höfvitsmännerna öfver tusend, och öfver hundrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Förty krigsfolket hade röfvat hvar och en för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Och Mose med Prestenom Eleazar tog guldet af höfvitsmännerna öfver tusend, och öfver hundrade, och båro det in uti vittnesbördsens tabernakel, Israels barnom till en åminnelse för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubens barn och Gads barn hade ganska mycken boskap; och de sågo det landet Jaeser och Gilead, att det var beqvämt rum till att föda boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Så kommo de, och talade till Mose, och till Presten Eleazar, och till Förstarna i menighetene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Det landet Ataroth, Dibon, Jaeser, Nimra, Hesbon, Eleale, Sebam, Nebo och Beon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Som Herren slagit hade för Israels menighet, är beqvämt till boskap, och vi dine tjenare hafve boskap;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Och sade ytterligare: Hafve vi funnit nåde för dig, så gif dinom tjenarom detta landet till eget; och så fare vi intet öfver Jordanen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mose sade till dem: Skulle edra bröder draga i strid, och I skullen blifva här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Hvi omvänden I Israels barnas hjerta, att de icke skola draga utöfver, uti det land, som Herren dem gifva skall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Alltså gjorde ock edra fäder, då jag sände dem ifrå KadesBarnea, till att skåda landet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Och då de voro komne ditupp, allt intill den bäcken Escol, och sågo landet, omvände de Israels barnas hjerta, så att de icke ville in uti landet, som Herren dem gifva ville,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Och Herrans vrede förgrymmade sig på den tiden, och han svor, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Detta folket, som utur Egypten draget är, ifrå tjugu år och deröfver, skola ju icke se det landet, som jag Abraham, Isaac och Jacob svorit hafver; derföre, att de mig icke troliga efterföljt hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Undantagnom Caleb, Jephunne son, den Kenisiten, och Josua, Nuns son; ty de hafva Herranom troliga efterföljt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Så förgrymmade sig Herrans vrede öfver Israel, och lät fara dem hit och dit i öknene i fyratio år, intilldess en ände vardt på allt det slägtet, som syndat hade emot Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Och si, I ären inträdde uti edra fäders stad, att syndarena skola vara desto flere, och att I också Herrans vrede och grymhet ännu föröka skullen emot Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Förty om I vänden eder ifrå honom, så varder han ock ännu länger låtandes eder blifva i öknene, och så förderfven I allt detta folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Då gingo de fram, och sade: Vi vilje allenast bygga här fägårdar för vår boskap, och städer för vår barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Men vi vilje väpna oss, och gå framför Israels barn, intilldess vi före dem till deras rum; vår barn skola blifva uti de fasta städer för landsens inbyggares skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Vi vilje icke vända hemåt, intilldess Israels barn intaga hvar sitt arf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Ty vi vilje intet ärfva med dem på hinsidan Jordan; utan vårt arfvegods må vara på denna sidone Jordan österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mose sade till dem: När I det göra viljen, att I rusten eder till strid för Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Så drager öfver Jordan för Herranom, hvilken som helst ibland eder väpnader är, tilldess I utdrifven hans fiendar ifrå hans ansigte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Och landet blifver undergifvet för Herranom; sedan skolen I vända om, och oskyldige vara för Herranom, och för Israel; och skolen så hafva detta landet till eget för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Men om I det icke göra viljen, si, så varden I syndande emot Herran, och varden edra synder förnimmande, då de begripa eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Så bygger nu städer för edor barn, och fägårdar för edor boskap; och görer som I sagt hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Gads barn och Rubens barn sade till Mose: Dine tjenare skola göra såsom min herre budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Vår barn, hustrur, håfvor, och all vår boskap skola blifva uti Gileads städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Men vi dine tjenare vilje alle väpnade draga i stridena för Herranom, såsom min herre sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Då böd Mose för deras skull Prestenom Eleazar, och Josua, Nuns son, och de öfversta fäderna i Israels barnas slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Och sade till dem: Om Gads barn och Rubens barn draga öfver Jordan med eder, alle väpnade till strid för Herranom, och landet blifver eder allt undergifvet; så gifver dem det landet Gilead till eget;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Men draga de icke med eder väpnade, så skola de ärfva med eder i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Gads barn och Rubens barn svarade, och sade: Såsom Herren talat hafver till dina tjenare, så vilje vi göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Vi vilje draga väpnade för Herranom in uti Canaans land, och besitta vårt arfvegods på desso sidone Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Så gaf Mose Gads barnom, och Rubens barnom, och den halfva slägtene Manasse, Josephs sons, Sihons rike, de Amoreers Konungs, och Ogs rike, Konungens i Basan, landet och städerna i alla gränsor, deromkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Då byggde Gads barn Dibon, Ataroth, Aroer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atroth, Sophan, Jaeser, Jogbeha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bethnimra och Betharan, bevarada städer och fägårdar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubens barn byggde Hesbon, Eleale, Kiriathaim,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, BaalMeon; och förvände namnen; och Sibma; och gåfvo de städer namn, som de byggde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Och Maohirs barn, Manasse sons, drogo till Gilead, och vunno den, och fördrefvo de Amoreer, som derinne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Då gaf Mose Machir, Manasse sone, Gilead; och han bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Men Jair, Manasse son, drog bort, och vann deras byar, och kallade dem HavothJair.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobah drog åstad, och vann Kenath med dess döttrar, och kallade dem Nobah efter sitt namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Detta är Israels barnas resande, hvilke utur Egypti land dragne voro i deras härar, genom Mose och Aaron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Och Mose beskref deras utresande, såsom de drogo efter Herrans befallning; och äro desse de resande som de reste:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'De drogo ut ifrå Rameses på femtonde dagen i den första, månadenom, på annandag Påska, genom höga hand, i alla de Egyptiers åsyn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Då de Egyptier begrofvo sina förstfödingar, som Herren ibland dem slagit hade; ty Herren hade ock gjort dom öfver deras gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'När de dragne voro ifrå Rameses, lägrade de sig i Succoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Och de drogo ut ifrå Succoth, och lägrade sig i Etham, hvilket ligger vid ändan på öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Ifrån Etham drogo de ut, och blefvo i den dalen Hyroth, hvilken ligger emot BaalZephon; och lägrade sig inför Migdol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Ifrå Hyroth drogo de ut, och gingo midt igenom hafvet in uti öknena, och reste tre dagsresor inuti Ethams öken, och lägrade sig i Marah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Ifrå Maran drogo de ut, och kommo till Elim; der voro tolf vattubrunnar och sjutio palmträd; och lägrade sig der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Ifrån Elim drogo de ut, och lägrade sig invid röda hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Ifrå röda hafvet drogo de ut, och lägrade sig i den öknene Sin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Ifrå den öknene Sin drogo de ut, och lägrade sig i Daphka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Ifrå Daphka drogo de ut, och lägrade sig i Alus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Ifrån Alus drogo de ut, och lägrade sig i Rephidim; der hade folket intet vatten att dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Ifrå Rephidim drogo de ut, och lägrade sig uti den öknene Sinai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Ifrå Sinai drogo de ut, och lägrade sig i de Lustgrifter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Ifrå de Lustgrifter drogo de ut, och lägrade sig i Hazeroth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Ifrå Hazeroth drogo de ut, och lägrade sig i Rithma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Ifrå Rithma drogo de ut, och lägrade sig i RimmonParez.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Ifrå RimmonParez drogo de ut, och lägrade sig i Libna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Ifrå Libna drogo de ut, och lägrade sig i Rissa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Ifrå Rissa drogo de ut, och lägrade sig i Kehelatha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Ifrå Kehelatha drogo de ut, och lägrade sig på berget Sapher.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Ifrå berget Sapher drogo de ut, och lägrade sig i Harada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Ifrå Harada drogo de ut, och lägrade sig i Makheloth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Ifrå Makheloth drogo de ut, och lägrade sig i Thahath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Ifrå Thahath drogo de ut, och lägrade sig i Tharah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Ifrå Tharah drogo de ut, och lägrade sig i Mitka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Ifrå Mitka drogo de ut, och lägrade sig i Hasmona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Ifrå Hasmona drogo de ut, och lägrade sig i Moseroth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Ifrå Moseroth drogo de ut, och lägrade sig i BeneJaakan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Ifrå BeneJaakan drogo de ut, och lägrade sig i HorGidgad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Ifrå HorGidgad drogo de ut, och lägrade sig i Jotbatha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Ifrå Jotbatha drogo de ut, och lägrade sig i Abrona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Ifrån Abrona drogo de ut, och lägrade sig i EzionGaber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Ifrån EzionGaber drogo de ut, och lägrade sig i den öknene Zin, det är Kades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Ifrå Kades drogo de ut, och lägrade sig på det berget Hor, som är på gränsone vid Edoms land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Der gick Presten Aaron upp på berget Hor, efter Herrans befallning, och blef der död på fyrationde årena, sedan Israels barn voro utdragne utur Egypti land, på första dagen i femte månadenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Då han var hundrade tre och tjugu åra gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Och Arad, de Cananeers Konung, som bodde söderut i Canaans lande, hörde att Israels barn kommo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Ifrå berget Hor drogo de ut, och lägrade sig i Zalmona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Ifrå Zalmona drogo de ut, och lägrade sig i Punon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Ifrå Punon drogo de ut, och lägrade sig i Oboth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Ifrån Oboth drogo de ut, och lägrade sig i Ijim vid Abarim, i de Moabiters gränso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Ifrån Ijim drogo de ut, och lägrade sig i DibonGad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Ifrå DibonGad drogo de ut, och lägrade sig i AlmonDiblathaim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Ifrån AlmonDiblathaim drogo de ut, och lägrade sig på berget Abarim emot Nebo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Ifrå berget Abarim drogo de ut, och lägrade sig på de Moabiters mark, vid Jordan in mot Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Och de lägrade sig ifrå BethJesimoth allt intill den slättena Sittim, på de Moabiters mark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Och Herren talade med Mose på de Moabiters mark, vid Jordan, in mot Jericho, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Tala med Israels barn, och säg till dem: När I öfver Jordan komne ären, in uti Canaans land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Så skolen I fördrifva alla dess inbyggare för edart ansigte, och alla deras stodar, och alla deras gjutna beläten förgöra, och alla deras höjder förderfva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Så att I tagen landet in, och bon der uti; förty eder hafver jag gifvit landet, att I skolen det intaga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Och skolen utskifta landet genom lott ibland edra slägter; dem som månge äro; skolen I mer gifva, och dem som få äro, mindre; efter som lotten faller till hvar och en, så skall han hafva det, efter edra fäders slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Om I landsens inbyggare icke fördrifven för edart ansigte, så skola de, som återlefde äro, vara eder som törne i edor ögon, och såsom spjut i edra sidor; och skola tränga eder på landena, der I uti bon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Så skall då ske, att jag så varder görandes eder, som jag emot dem göra aktade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Bjud Israels barnom, och säg till dem: När I uti Canaans land kommen, så skall det landet, som eder till arfvedel faller i Canaans lande, häfva sin landamär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Den sidan söderut skall begynna af den öknene Zin vid Edom, så att edart landamäre söderut skall vara ifrån andanom af salthafvet, det österut ligger;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Och att det landamäret skall sträcka sig ifrå sunnan uppåt intill Akrabbim, och gå igenom Zinna; och dess ända ifrå sunnan intill KadesBarnea, och räcka intill den byn Addar, och gå igenom Azmon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Och skall sträcka sig ifrån Azmon allt intill Egypti bäck; och dess ände vare i hafvena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Men det landamäret vesterut skall vara detta, nämliga det stora hafvet; det skall vara edart landamäre vesterut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Det landamäret norrut skall vara detta: I skolen mäta ifrå stora hafvet allt intill berget Hor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Och ifrå berget Hor mäta intilldess man kommer till Hamath; så, att dess utgång skall vara det landamäret Zedada;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Och samma landämärens ände inåt Ziphron, och dess ände vare vid den byn Enan, det skall vara edart landamäre norrut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Och skolen mäta eder landamäret österut, ifrå den byn Enan intill Sepham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Och det landamäret gånge nederåt ifrå Sepham intill Ribla, till Ain östanefter; sedan gånge nederåt, och drage sig uppmed sidone af hafvet Cinnereth österut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Och komme neder åt Jordan, så att dess ände blifver salthafvet; det skall vara edart land med sin landamäre allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Och Mose böd Israels barnom, och sade: Detta är landet, som I skolen skifta emellan eder med lott, hvilket Herren budit hafver att gifva de nio slägter, och den halfva slägtene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Ty Rubens barnas slägte efter deras fäders hus, och Gads barnas slägte efter deras faders hus, och den halfva slägten Manasse, hafva allaredo tagit sin del.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Så hafva de två slägterna, och den halfva slägten, sin arfvedel på desso sidone Jordan in mot Jericho österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Desse äro namnen af männerna, som landet skola skifta emellan eder: Presten Eleazar, och Josua, Nuns son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Dertill skolen I taga Förstan af hvarjo slägtene, till att utskifta landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Och desse äro männernas namn: Caleb, Jephunne son, af Juda slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Semuel, Ammihuds son, af Simeons slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Elidad, Chislons son, af BenJamins slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Bucki, Jogli son, Försten för Dans barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Hanniel, Ephods son, Föräten för Manasse barnas slägte, af Josephs barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Kemuel, Siphtans son, Försten för Ephraims barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Elizaphan, Parnachs son, Försten för Sebulons barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Palthiel, Assans son, Försten för Isaschars barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Ahihud, Selomi son, Försten för Assers barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Pedahel, Ammihuds son, Försten för Naphthali barnas slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Desse äro de som Herren budit hafver, att de skulle utskifta Israels barnom arfvet i Canaans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Och Herren talade med Mose på de Moabiters mark, vid Jordan, in mot Jericho, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Bjud Israels barnom, att de gifva Leviterna städer utaf sitt arfvegods, der de måga uti bo; dertill förstäder omkring städerna skolen I ock gifva Leviterna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Att de skola bo i städerna, och hafva sin boskap, gods och allahanda djur i förstäderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Vidden till förstäderna, som de skola gifva Leviterna, skall vara tusende alnar utifrå stadsmuren allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Så skolen I då mäta utanför staden, på den sidone österut, tutusend alnar; och på den sidone söderut, tutusend alnar; och på den sidone vesterut, tutusend alnar; och på den sidone norrut, tutusend alnar; att staden skall vara midt uti. Det skall vara deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Och ibland de städer, som I gifven Leviterna, skolen I gifva sex fristäder, att den som någon ihjälslår må fly derin; derutöfver skolen I ännu gifva dem två och fyratio städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Så att alle städer, som I gifven Leviterna, blifva åtta och fyratio med deras förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Och skolen gifva dem mer af dem som mycket äga ibland Israels barn, och mindre af dem som mindre äga; hvar och en, efter hans arfvedel, den honom tillskift varder, skall gifva Leviterna städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Tala med Israels barn, och säg till dem: När I kommen öfver Jordan in uti Canaans land,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Skolen I utvälja städer, som fristäder skola vara, deruti fly må den som någon med våda ihjälslår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Och skola sådane fristäder vara ibland eder, för blodhämnarens skull, att han icke skall dö, som dråpet gjorde, intilldess han hafver ståndit till rätta inför menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Och de städer, som I gifva skolen, skola vara sex fristäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tre skolen I gifva på desso sidone Jordan; och tre i Canaans lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Det äro de sex fristäder, både för Israels barn, och främlingom, och husmän ibland eder; att dit må fly ho som helst ena själ slår med våda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Hvilken som slår en med något jern, så att han dör, han är en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Kastar han honom med en sten, der någor kan död af varda, så att han blifver död deraf, så är han en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Slår han honom med något trä, der någor kan med dödsslagen varda, så att han dör, så är han en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Blodhämnaren skall slå mandråparen ihjäl; såsom han slagit hafver, så skall man döda honom igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Stöter han honom af hat, eller kastar något på honom med försåt, så att han dör;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Eller slår honom af ovänskap med sine hand, så att han dör, så skall han döden dö, som honom slog; ty han är en mandråpare; blodhämnaren skall dräpa honom, när han råkar honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Men stöter han honom oförvarandes utan ovänskap, eller kastar något på honom, icke med försåt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Eller kastar en sten på honom oförvarandes, der man af dö kan, så att han dör, och han är icke hans ovän, och ville honom heller intet ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Så skall menigheten döma, emellan honom som slog och blodhämnaren, i denna sakene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Och menigheten skall fria mandråparen ifrå blodhämnarens hand, och låta honom komma i fristaden igen, dit han flydder var; och der skall han blifva, tilldess öfverste Presten dör, den man med den helga oljone smort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Om mandråparen går utaf sin fristads råmärke, dit han flydd är,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Och blodhämnaren finner honom utanför hans fristads råmärke, och slår honom ihjäl; han skall för det blod intet saker vara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Ty han skulle blifva i sinom fristad intill den öfversta Prestens död; och efter öfversta Prestens död åter komma till sins arfvegods land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Detta skall vara eder en rätt med edra efterkommande, i alla edra boningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Mandråparen skall man dräpa efter tvegga vittnes mun; ett vittne skall icke svara öfver en själ till döds.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Och I skolen ingen försoning taga för en mandråpares själ, ty han är saker till döden; utan han skall döden dö;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Och skolen ingen försoning taga öfver den, som till fristaden flydder var, så att han igenkommer till att bo i landena, intill att Presten dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Och skämmer icke landet, der I uti bon; ty den som blodssaker är, han skämmer landet; och landet kan icke försonadt varda för det blod, som der utgjutet varder, annars utan genom hans blod, som det utgjutit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Orener icke landet, som I bon uti, der jag ock uti bor; ty jag är Herren, som bor ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Och de öfverste fäderna till Gileads barnas slägte, Machirs sons, hvilken Manasse son var, af Josephs barnas slägte, gingo fram, och talade för Mose, och för Förstarna, öfversta fäderna till Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Och sade: Käre Herre, Herren hafver budit, att man skall utskifta landet Israels barnom till arfvedel genom lott; och du, min Herre, hafver budit genom Herran, att man vår broders Zelaphehads arfvedel hans döttrar gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Om någor af Israels slägte tager dem till hustru, så varder vår faders arfvedel mindre, och så mycket som de hafva, kommer den slägtenes arfvedel till, dit som de komma; och så varder vår arfvedels lott förminskad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'När nu Israels barnas klangår kommer, så kommer deras arfvedel till den slägtenes arfvedel, der de äro; så varder vår faders arfvedel förminskad, så mycket som de hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Så böd Mose Israels barnom, efter Herrans befallning, och sade: Josephs barnas slägt hafver talat rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Detta är det som Herren bjuder Zelaphehads döttrar, och säger: Gifte sig hvem de vilja; allenast att de gifta sig in i sina ätt och faders slägte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'På det att Israels barnas arfvedel icke skall falla ifrå den ena slägten till den andra; ty hvar och en ibland Israels barn skall hänga intill sitt fädernes slägtes arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Och alla döttrar, som äga arfvedel i Israels barnas slägter, skola gifta sig enom af sins faders slägts ätt; på det hvar och en ibland Israels barn må behålla sins faders arf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Och en arfvedel icke skall falla ifrå den ena slägtene till den andra; utan hvar och en hänge intill sitt arf ibland Israels barnas slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Såsom Herren böd Mose, så gjorde Zelaphehads döttrar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahela, Thirza, Hogla, Milca och Noa, och gifte sig vid deras faderbroders barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Af Manasse barnas slägte, Josephs sons; alltså blef deras arfvedel vid ättena och deras faders slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Desse äro de bud och rätter, som Herren genom Mose böd Israels barnom, på de Moabiters mark, vid Jordan, in mot Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Desse äro de ord, som Mose talade till hela Israel på hinsidon Jordan i öknene, på den markene emot röda hafvet, emellan Paran och Tophel, Laban, Hazeroth och Disahab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Ellofva dagsresor ifrå Horeb, den vägen om Seirs berg intill KadesBarnea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Och det skedde i fyrationde årena, på första dagen i den ellofte månadenom; då talade Mose med Israels barn, allt det Herren honom till dem budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Sedan att han hade slagit Sihon, de Amoreers Konung, som i Hesbon bodde; dertill Og, Konungen i Basan, som i Astaroth och i Edrei bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'På hinsidon Jordan, i de Moabiters lande, begynte Mose utlägga denna lagen, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Herren vår Gud talade med oss på Horebs berg, och sade: I hafven länge nog varit vid detta berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Vänder eder, och drager åstad, att I mån komma till de Amoreers berg, och till alla deras grannar, till mark, på berg och i dalar, söderut, och emot hafsens hamn, i Canaans lande, och till berget Libanon, allt intill den stora älfvena Phrath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Si, jag hafver gifvit eder landet, som för eder ligger; går derin, och intager det, såsom Herren edra fäder, Abraham, Isaac och Jacob, svorit hafver, att han dem, och deras säd efter dem, det gifva ville.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Då sade jag till eder på samma tiden: Jag förmår icke allena utstå med eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Förty Herren edar Gud hafver förökat eder, så att I på denna dag ären såsom stjernornas tal på himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Herren edra fäders Gud göre eder ännu mång tusend mer, och välsigne eder, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Huru kan jag allena sådana mödo, och tunga, och trätor, draga af eder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Tager utaf eder visa och förståndiga män, de som ibland edra slägter bekände äro, dem vill jag uppsätta eder för höfvitsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Då svaraden I mig, och säden: Det är en god ting, der du om talar, att du göra vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Så tog jag de yppersta af edra slägter, visa och bekända män, och satte dem öfver eder till höfvitsmän, öfver tusende, öfver hundrade, öfver femtio, öfver tio, och ämbetsmän i edra slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Och böd edra domare på samma tid, och sade: Förhörer edra bröder, och dömer rätt emellan hvar man och hans broder, och främlingen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'I skolen ingen person anse i domen; utan skolen höra den litsla såsom den stora, och icke hafva försyn för någons mans person; ty domsämbetet hörer Gudi till. Om någor sak varder eder för svår, den låter komma till mig, att jag må den höra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Alltså böd jag eder på den tiden allt det I göra skullen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Så drogo vi ut ifrå Horeb, och vandrade genom den hela öknena, den stor och grufvelig är, såsom I sett hafven, uppå den vägen till de Amoreers berg, såsom Herren vår Gud oss budit hade; och kommo intill KadesBarnea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Då sade jag till eder: I ären komne intill de Amoreers berg, det Herren vår Gud oss gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Si, landet före dig, hvilket Herren din Gud dig gifvit hafver! Drag ditupp, och tag det in, såsom Herren dina fäders Gud dig sagt hafver; frukta dig intet, och grufva dig intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Så kommen I till mig alle, och säden: Låt oss sända några män framför oss, som bespeja oss landet, och säga oss igen, hvilken vägen vi skole draga derin, och de städer, der vi inkomma skole.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Det nöjde mig väl; och tog utaf eder tolf män, utaf hvart slägtet en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Då de samme gingo åstad, och drogo upp på berget, och kommo till den bäcken Escol, så skådade de det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Och togo landsens frukt med sig, och båro neder till oss, och bådade oss igen, och sade: Landet är godt, som Herren vår Gud oss gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Men I villen icke draga ditupp, och blefven Herrans edor Guds orde ohörsamme;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Och knorraden i edor tjäll, och saden: Herren är oss hätsk, derföre hafver han fört oss utur Egypti land, på det han skall gifva oss i de Amoreers händer, till att förgöra oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Hvad skulle vi deruppe? Våra bröder hafva förfärat vårt hjerta, och sagt: Det folket är större och högre än vi; städerna äro store och bemurade upp till himmelen; dertill hafve vi sett der Enakims barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Och jag sade till eder: Grufver eder icke, och frukter eder intet för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Herren edar Gud drager för eder, och han skall strida för eder, såsom han hafver gjort med eder i Egypten för edor ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Och i öknene, der du sett hafver, huru Herren din Gud dig burit hafver, såsom en man bär sin son, i allom dem väg, der I vandrat hafven, intilldess I till detta rummet komne ären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Men I skötten der intet om, att I måtten trott Herranom edrom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Den för eder gick, till att visa eder de rum, der I eder lägra skullen, om nattena i eld, att han skulle visa eder vägen, den I gå skullen, och om dagen i molnskyn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Då nu Herren hörde edart rop, vardt han vred, och svor, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Ingen af detta onda slägtet skall få se det goda landet, som jag svorit hafver att gifva deras fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Förutan Caleb, Jephunne son, han skall se det; honom vill jag gifva det landet, der han på stigit hafver, och hans barnom; derföre att han hafver troliga efterföljt Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Och vardt Herren vred på mig för edra skull, och sade: Du skall icke heller komma derin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Men Josua, Nuns son, som din tjenare är, han skall komma derin; styrk honom; ty han skall utskifta Israel arfvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Och edor barn, om hvilka I säden: De skola blifva till ett rof; och edra söner, som på denna dag hvarken veta godt eller ondt; de skola komma derin, dem skall jag gifva det, och de skola taga det in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Men vänder I om, och drager åt öknena, den vägen åt röda hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Då svaraden I, och saden till mig: Vi hafve syndat emot Herran; vi vilje ditupp och strida, såsom Herren vår Gud oss budit hafver. Som I nu redo voren, hvar i sitt harnesk, och skullen draga upp på berget,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Sade Herren till mig: Säg dem, att de icke draga ditupp, ej heller strida; ty jag är icke med eder; att I icke varden slagne för edra fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Då jag detta sade eder, lydden I intet, och vorden Herrans ord ohörsamme, och vorden öfverdådige, och drogen upp på berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Så drogo de Amoreer ut, som på berget bodde, emot eder, och jagade eder, såsom bin göra, och slogo eder i Seir allt intill Horma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Då I nu igenkommen, och greten för Herranom, ville Herren icke höra edra röst, och böjde sin öron intet till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Så blefven I uti Kades en långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Då vände vi om, och drogo ut i öknena, på den vägen till röda hafvet, såsom Herren sade till mig; och drogom omkring Seirs berg, en långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Och Herren sade till mig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'I hafven nu nog dragit kringom detta berget; vänder eder norrut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Och bjud folkena, och säg: I skolen draga genom edra bröders Esau barnas gränsor, som bo i Seir, och de skola frukta för eder; men förvarer eder granneliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Slår icke uppå dem; ty jag skall icke gifva eder en fot bredt uti deras land; förty Esau barn hafver jag gifvit Seirs berg till att besitta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Maten skolen I köpa af dem för edra penningar, den I äten; och vattnet skolen I köpa af dem för penningar, som I dricken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Ty Herren din Gud hafver välsignat dig i alla dina händers gerningar; han hafver lagt på hjertat ditt resande genom denna stora öknena; och Herren din Gud hafver i fyratio år varit när dig, så att dig intet hafver fattats.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Då vi nu ifrå våra bröder Esau barn dragne voro, som på Seirs berg bodde, på den vägen den markenes ifrån Elath och EzionGaber, vände vi om, och gingom den vägen genom de Moabiters öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Då sade Herren till mig: Du skall ingen skada göra de Moabiter, eller slå uppå dem; ty jag vill intet gifva dig af deras land till att besitta; förty Lots barn hafver jag gifvit Ar till att besitta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'De Emim hafva i förtiden bott deruti, hvilke voro ett stort, starkt och högt folk, såsom Enakim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Man höll dem ock för Resar, såsom Enakim; och de Moabiter kalla dem ock Emim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Bodde ock i förtiden de Horeer i Seir, och Esau barn fördrefvo och förlade dem för sig, och bodde i deras stad, såsom Israel sins besittninges lande gjorde, det Herren dem gaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Så varer nu redo, och drager öfver den bäcken Sared. Och vi droge deröfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Men tiden medan vi droge ifrå KadesBarnea, intilldess vi komme öfver den bäcken Sared, var åtta och tretio år, tilldess alle stridsmän döde voro i lägrena, såsom Herren dem svorit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Dertill var ock Herrans hand emot dem, att de förgingos utu lägret, tilldess de voro åtgångne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Då alle stridsmännerna åtgångne voro, att de döde voro ibland folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Talade Herren med mig, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'I dag skall du draga genom de Moabiters landsändar vid Ar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Och skall komma in mot Ammons barn, dem skall du ingen skada göra, eller slå på dem; ty jag vill icke gifva dig Ammons barnas land till att besitta; förty jag hafver gifvit det Lots barnom till att besitta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Det hafver ock räknadt varit för Resars land; och hafva desslikes i förtiden Resar bott derinne. Och de Ammoniter kalla dem Samsummim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'De voro ett stort, starkt och högt folk, såsom Enakim; och Herren förgjorde dem för dem, och lät dem besitta dem, så att de skulle bo i deras stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Såsom han gjort hade med Esau barn, som på Seirs berg bo, då han förgjorde för dem de Horiter, och lät dem besitta dem, så att de hafva bott i deras stad, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Och de Caphthorim drogo utu Caphthor, och förgjorde de Avim, som bodde i Hazerim, allt intill Gaza, och bodde i deras stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Varer redo, och drager ut, och går öfver den bäcken vid Arnon. Si, jag hafver gifvit i dina händer Sihon, de Amoreers Konung i Hesbon, med hans land; begynn att intaga det, och strid emot dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'I dag vill jag begynna, att all folk under himmelen skola frukta och förskräckas för dig, så att, när de höra om dig, skola de bäfva och sorg hafva för din tillkommelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Då sände jag båd utaf öknene östanefter, till Sihon, Konungen i Hesbon, med fridsam ord, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Jag vill draga genom ditt land, och såsom vägen löper, så vill jag draga; jag vill icke vika antingen på den högra eller den venstra sidona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Mat skall du sälja mig för penningar, att jag äter; och vatten skall du sälja mig? för penningar, att jag dricker; jag vill allenast till fot gå derigenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Såsom Esau barn mig gjort hafva, som bo i Seir, och de Moabiter, som bo i Ar; tilldess jag må komma öfver Jordan, uti det landet, som Herren vår Gud oss gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Men Sihon, Konungen i Hesbon, ville icke att vi skulle draga derigenom; ty Herren din Gud förhärde hans sinne, och förstockade hans hjerta, på det han skulle gifva honom i dina händer, såsom du nu ser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Och Herren sade till mig: Si, jag hafver begynt att gifva för dig Sihon och hans land; begynn till att intaga och besitta hans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Och Sihon drog ut emot oss med allt sitt folk till strid, till Jahza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Men Herren vår Gud gaf honom för oss, att vi slogo honom med hans barn, och allt hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Så vunne vi på samma tiden alla hans städer, och tillspillogåfvom alla städer, både män, qvinnor och barn, och lätom ingen igenblifva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Utan boskapen toge vi för oss, och det byte af städerna, som vi vunne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Ifrån Aroer, som ligger på strandene utmed den bäcken vid Arnon, och ifrå den staden i dalenom allt intill Gilead, ingen stad var, som sig kunde beskydda för oss; Herren vår Gud gaf alltsamman för oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Utan till Ammons barnas land kom du icke, eller till något det som var vid den bäcken Jabbok, eller till de städer på bergena, eller till något det Herren var Gud oss förbudit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Och vi vände om, och drogo upp, den vägen till Basan. Och Og, Konungen i Basan, drog ut emot oss med allt sitt folk, till att strida vid Edrei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Men Herren sade till mig: Frukta dig intet för honom; ty jag hafver gifvit honom i dina händer, och allt hans folk med hans land, och du skall göra med honom, såsom du gjorde med Sihon, de Amoreers Konung, den i Hesbon satt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Alltså gaf Herren vår Gud ock Konung Og i Basan i våra händer, med allt hans folk, så att vi sloge honom, tilldess honom intet, igenblef.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'På samma tid vunne vi alla hans städer, och var ingen stad den vi honom icke aftogom; sextio städer, hela den ängden Argob i Ogs rike, som var i Basan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Alle desse städer voro faste med höga murar, portar och bommar, förutan andra ganska många små städer, som ingen mur hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Och gåfvom dem tillspillo, såsom vi, med Sihon, Konungenom i Hesbon, gjort hade; alla städer gåfve vi tillspillo, både med män, qvinnor och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Men allan boskapen, och rofvet af städerna toge vi för oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Alltså toge vi i den tiden landet utu de två Amoreers Konungars händer på hinsidon Jordan, ifrå den bäcken vid Arnon, allt intill det berget Hermon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Hvilket de Sidonier Sirion kalla; men de Amoreer kalla det Senir;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Alla de städer på slättene, och hela Gilead, och hela Basan, allt intill Salcha och Edrei, som äro städer i Ogs rike i Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Ty allena Konung Og i Basan var ännu igen utaf de Resar. Si, hans säng af jern är här i Rabbath, som hörer Ammons barnom till, nio alnar lång, och fyra alnar bred, efter ens mans armbåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Så toge vi då landet in på den tiden, ifrån Aroer, som ligger när bäcken vid Arnon; och halfva landet af Gileads berg, med dess städer, gaf jag de Rubeniter och Gaditer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Men det öfver var i Gilead, och hela Basan af Ogs rike, gaf jag den halfva slägtene Manasse; den hela ängden Argob med hela Basan, som kallas de Resars land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, Manasse son, fick den hela ängden Argob, allt intill Gessuri och Maachathi landsändar; och kallade Basan efter sitt namn, HavothJair, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Men Machir gaf jag Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Och de Rubeniter och Gaditer gaf jag en del af Gilead, allt intill bäcken vid Arnon, midt i bäcken, der landamäret är, och allt intill den bäcken Jabbok, der landamäret är för Ammons barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Dertill den slättmarkena, och Jordan, den landamäret är, ifrå Cinnereth intill hafvet vid slättmarkena; nämliga salthafvet nedan vid berget Pisga österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Och jag böd eder på samma tiden, och sade: Herren edar Gud hafver gifvit eder detta landet att intaga det; så drager nu väpnade för edra bröder Israels barn, alle I som stridsamme ären;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Förutan edra hustrur, barn och boskap; ty jag vet, att I hafven mycken boskap; låter dem blifva uti edra städer, som jag eder gifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Tilldess Herren låter ock edra bröder komma till rolighet såsom eder, att de ock intaga det land, som Herren deras Gud dem gifva skall på hinsidon Jordan; sedan skolen I omvända till edor besittning, den jag eder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Och jag böd Josua på samma tiden, och sade: Din ögon hafva sett allt det som Herren edar Gud dessa två. Konungar gjort hafver; så varder Herren ock görandes all Konungarike, dit du drager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Frukter eder intet för dem; ty Herren edar Gud strider för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Och jag bad Herran på den tiden, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Herre, Herre, du hafver begynt visa dinom tjenare dina härlighet och dina starka hand; ty hvilken är den Gud i himmelen eller på jordene, som förmår efter din verk och din magt göra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Låt mig gå och se det goda landet, på hinsidon Jordan; de goda berg, och Libanon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Men Herren vardt vred på mig för edra skull, och bönhörde mig intet; utan Herren sade till mig: Låt blifvat: tala intet mer derom för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Stig upp på höjden af berget Pisga, och häf din ögon upp vesterut, och norrut, och söderut, och österut, och se det med ögonen; ty du skall intet gå utöfver denna Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Utan bjud Josua, att han är tröst och frimodig; förty han skall gå öfver Jordan för folket, och skall utskifta dem landet, som du seendes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Så blefvo vi då i den dalen in mot Peors hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Och nu hör, Israel, de bud och rätter, som jag eder lärer, att I dem göra skolen, på det I män lefva, och inkomma, och intaga landet, som Herren edra fäders Gud eder gifver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'I skolen intet lägga dertill, som jag eder bjuder; och skolen ej heller taga der något ifrå; på det I mågen bevara Herrans edars Guds bud, som jag bjuder eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Edor ögon hafva sett hvad Herren gjort hafver med BaalPeor; ty alla de som efterföljde BaalPeor, dem hafver Herren din Gud förgjort ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Men I som höllen eder intill Herran edar Gud, I lefven alle på denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Si, jag hafver lärt eder bud och rätter, såsom Herren min Gud mig budit hafver, att I så göra skolen i landet, der I inkommande varden till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Så behåller det nu, och görer det; ty så varder edor vishet och förstånd berömd för all folk, när de hörande varda all denna bud, så att de skola säga: Si, hvilket vist och förståndigt folk detta är, och ett härligit folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Ty hvad folk är så härligit, hvilko gudarna så nalkas, såsom Herren vår Gud, så ofta som vi åkalle honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Och hvar är något så härligit folk, som så rättfärdiga seder och bud hafver, såsom all denna lagen, som jag eder på denna dagen föregifver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Så förvara dig nu och dina själ granneliga, att du icke förgäter hvad för din ögon skedt är, och att det icke gånger utu dino hjerta i alla dina lifsdagar; och skall förkunna dinom barnom, och dinom barnabarnom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Den dagen, då du stod för Herranom dinom Gud vid berget Horeb, och Herren till mig sade: Församla mig folket, att jag skall låta dem höra min ord, och lära frukta mig i alla deras lifsdagar på jordene, och lära sin barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Och I gingen fram, och stoden neder under berget, och berget brann halfväges upp till himmelen; och der var mörker, moln och töckna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Och Herren talade med eder midt utur elden; hans ords röst hörden I, men ingen liknelse sågen I, utan röstena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Och han förkunnade eder sitt förbund, det han eder böd att göra; nämliga de tio ord, och skref dem på två stentaflor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Och Herren böd mig på samma tiden, att jag skulle lära eder bud och rätter, att I derefter göra skullen uti de lande, der I indragen till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Så förvarer nu edra själar väl; ty I hafven ingen liknelse sett på den dagen, då Herren talade med eder utur elden på bergena Horeb;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'På det I icke skolen förderfva eder och göra eder något beläte, det en man likt är eller qvinno;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Eller djure på jordene, eller fogle under himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Eller matke, som kräker på jordene, eller fiske i vattnena under jordene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Och att du icke heller upphäfver din ögon till himmelen, och ser solen, och månan, och stjernorna, hela himmelens här, och faller af, och tillbeder dem, och tjenar dem, hvilka Herren din Gud förskickat hafver allom folkom under hela himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Men eder hafver Herren upptagit, och fört eder utu jernugnen, nämliga utur Egypten, att I skullen vara hans arffolk, som det ock är i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Och Herren vardt vred på mig för edra gerningars skull, så att han svor, att jag icke skulle komma öfver Jordanen, eller i det goda landet, som Herren din Gud dig till arfvedel gifva skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Utan jag måste dö i detta land, och skall icke gå öfver Jordanen; men I skolen gå deröfver, och intaga det goda landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Så tager eder nu vara, att I Herrans edars Guds förbund icke förgäten, det han med eder gjort hafver; och icke görer beläte till någrahanda liknelse, såsom Herren din Gud dig budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Förty Herren din Gud är en frätande eld, och en nitälskande Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'När I nu föden barn, och barnabarn, och bon på landena, och förderfven eder, och gören eder beläte till någrahanda liknelse, så att I gören illa för Herranom edrom Gud, och förtörnen honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Så kallar jag i denna dag himmel och jord till vittne öfver eder, att I skolen snart förgås utaf landena, uti hvilket I ingån öfver Jordanen, till att intaga det. I skolen icke länge blifva deruti; utan skolen förgjorde varda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Och Herren skall förströ eder ibland folk, och I varden ett fögo folk qvart blifvande ibland Hedningarna, dit Herren eder drifvandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Der skall du tjena afgudom, som menniskohandaverk äro, stock och sten, hvilke hvarken se eller höra, eller äta, eller lukta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Om du då der söker Herran din Gud, så skall du finna honom; om du söker honom af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'När du bedröfvad varder, och dig all denna tingen uppåkomma i de yttersta dagar, så skall du vända dig till Herran din Gud, och skall höra hans röst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Förty Herren din Gud är en barmhertig Gud; han varder dig icke öfvergifvandes, eller förderfvandes; och skall han icke förgäta det förbund med dina fäder, som han dem svorit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Befråga efter förtiden, som för dig varit hafver, ifrå den dagen då Gud skop menniskona på jordene, ifrå den ena himmelens ända till den andra, om någon tid en sådana stor ting skedd, eller dess like någon tid hörd är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Att något folk hade hört Guds röst talandes utur elden, såsom du hört hafver, och likväl lefver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Eller om Gud försökt hafver att ingå, och taga sig ett folk midt utur eno folke, genom frestelse, genom tecken, genom under, genom strid, och genom mägtiga hand, och genom uträcktan arm, och genom stora syner, såsom Herren edar Gud allt detta med eder gjort hafver, för din ögon uti Egypten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Du hafver sett det, på det du skall veta, att Herren är allena Gud, och ingen annan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Af himmelen hafver han låtit dig höra sina röst, att han skulle lära dig; och på jordene hafver han låtit dig se sin stora eld, och utur elden hafver du hört hans ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Derföre, att han dina fader älskat, och deras säd efter dem utvalt hafver; och fört dig utur Egypten med sitt ansigte, genom sina stora magt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'På det han skulle för dig fördrifva stor folk, och starkare än du äst, och föra dig derin, och gifva dig deras land till arfvedel, såsom det tillstår i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Så skall du nu veta i dag, och lägga det på hjertat, att Herren är en Gud, ofvan i himmelen, och nedre uppå jordene, och ingen annan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Att du håller hans rätter och bud, som jag i dag bjuder dig, så varder dig och dinom barnom efter dig väl gåendes, att ditt lif skall länge vara i landena, som Herren din Gud dig gifver evärdeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Då afskiljde Mose tre städer hinsidon Jordan, österut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Att dit fly skulle ho som sin nästa ihjälsloge med våda, och tillförene icke hade varit hans ovän; den skulle fly in uti en af de Städer, på det han måtte blifva vid lif;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer i öknene på den slättmarkene ibland de Rubeniter, och Ramoth i Gilead ibland de Gaditer, och Golan i Basan ibland de Manassiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Detta är den lag, som Mose Israels barnom föregaf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Och detta är vittnesbördet, och bud, och rätter, som Mose sade Israels barnom, då de utur Egypten dragne voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Hinsidon Jordan uti den dalenom in mot Peors hus, uti Sihons lande, de Amoreers Konungs, som i Hesbon bodde, hvilken Mose och Israels barn slogo, då de utur Egypten komne voro,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Och togo hans land in; dertill Ogs land, Konungens i Basan, de två Amoreers Konungars, som på hinsidon Jordan voro, österut:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Ifrån Aroer, hvilken på den bäckens strand vid Arnon ligger, intill berget Sion, det är Hermon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Och allt släta landet hinsidon Jordan, österut, allt intill hafvet, på slättene, nedanför berget Pisga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Och Mose kallade hela Israel, och sade till dem: Hör, Israel, de bud och rätter, som jag i dag talar för edor öron, och tärer dem, och behåller dem, att I gören derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herren vår Gud hafver gjort ett förbund med oss i Horeb;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Och Herren hafver icke gjort detta förbundet med våra fäder, utan med oss, som nu här äre på denna dag, och alle lefve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Ansigte mot ansigte hafver Herren talat med oss utur eldenom på berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Jag stod på den tiden emellan Herran och eder, att jag skulle föra Herrans ord till eder; förty I fruktaden eder för eldenom, och gingen icke upp på berget; och han sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Jag är Herren din Gud, som dig utur Egypti land fört hafver, utu träldomens hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du skall inga andra gudar hafva för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du skall intet beläte göra dig, efter någrahanda liknelse, antingen det ofvan i himmelen är, eller nedre på jordene, eller i vattnena under jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du skall icke tillbedja dem, eller tjena dem; ty jag är Herren din Gud, en nitälskande Gud, som hemsöker fädernas missgerningar öfver barnen, intill tredje och fjerde led, deras som mig hata;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Och beviser barmhertighet på mång tusend, som mig älska och min bud hålla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du skall icke missbruka Herrans dins Guds Namn; ty Herren skall icke låta blifva honom ostraffad, som hans Namn missbrukar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Sabbathsdagen skall du hålla, att du honom helgar; såsom Herren din Gud dig budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sex dagar skall du arbeta, och göra all din verk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Men på sjunde dagen är Herrans dins Guds Sabbath; då skall du intet arbete göra, icke heller din son, eller din dotter, eller din tjenare, eller din tjenarinna, eller din oxe, eller din åsne, eller all din boskap, eller främlingen som innan dina portar är; på det att din tjenare och tjenarinna måga hafva ro så väl som du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Förty du skall ihågkomma, att du vast ock en träl uti Egypti land, och Herren din Gud förde dig derut med mägtiga hand och uträcktom arme; derföre hafver Herren din Gud budit dig, att du skall hålla Sabbathsdagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Du skall hedra din fader och dina moder, såsom Herren din Gud dig budit hafver; på det att du må länge lefva, och att dig må väl gå uti de lande, som Herren din Gud dig gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du skall icke dräpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Du skall icke göra hor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Du skall icke stjäla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Du skall icke bära falskt vittnesbörd emot din nästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Du skall icke hafva lust till dins nästas hustru; du skall icke begära dins nästas hus, åker, tjenare, tjenarinno, oxa, åsna, eller hvad som helst honom tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Desse äro de ord, som Herren talade till alla edra menighet uppå berget, utur eldenom, och molnena, och töcknene, med stora röst; och lade der intet till; och skref dem på två stentaflor, och fick mig dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'När I hörden röstena utu mörkret, och berget brinna i elde, gingen I fram till mig, alle öfverstar i edra slägter, och edre äldste;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Och saden: Si, Herren vår Gud hafver låtit oss se sina härlighet, och sitt majestät, och vi hafve hört hans röst utur eldenom; i dag hafve vi sett, att Gud talade med menniskom, och de blefvo i lifve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Och nu, hvi skole vi dö, så att den store elden förtärer oss? Om vi oftare höre Herrans vår Guds röst, så måste vi dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Förty hvad är allt kött, att det höra må lefvandes Guds röst tala utur eldenom, såsom vi, och kan lefva?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Gack du fram, och hör allt det Herren, vår Gud säger; och säg oss det. Allt det Herren vår Gud med dig talar, det vilje vi höra och göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Då Herren hörde rösten af edor ord, som I taladen med mig, sade Herren till mig: Jag hafver hört detta folks ord, som de med dig talat hafva; det är allt godt, som de sagt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ack! det de ett sådant hjerta hade till att frukta mig, och till att hålla all min bud i deras lifsdagar; på det att dem måtte gå väl, och deras barn evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gack, och säg dem: Går hem i edor tjäll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Men du skall stå här för mig, att jag talar med dig all lag, och bud, och rätter, som du dem lära skall, att de göra derefter uti landena, som jag dem gifva skall till att intaga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Så behåller det nu, att I mån göra såsom Herren edar Gud eder budit hafver; och viker icke hvarken på högra sidon eller venstra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Utan vandrer i alla de vägar, som Herren edar Gud eder budit hafver; på det I mågen lefva, och eder skall väl gå, och I länge lefven i landena, som I intaga skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Desse äro nu de lag, och bud, och rätter, som Herren edar Gud budit hafver, att I dem lära och göra skolen i landena, dit I indragen till att intaga det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Att du fruktar Herran din Gud, och håller alla hans rätter och bud, som jag bjuder dig; du och din barn, och din barnabarn, i alla edra lifsdagar, på det I skolen länge lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Israel, du skall höra, och behållat, så att du gör ock så, att dig väl går, och varder mycket förökad, såsom Herren dina fäders Gud dig tillsagt hafver ett land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Hör, Israel: Herren vår Gud är en enig Herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Och du skall älska Herran din Gud af allo hjerta, af allo själ, af allo förmågo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Och dessa ord, som jag bjuder dig i dag, skall du lägga på hjertat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Och skall skärpa dem dinom barnom, och derom tala, när du sitter i ditt hus, eller går uppå vägen; när du nederlägger dig, eller uppstår;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Och skall binda dem för ett tecken på dine hand, och skola vara dig till en åminnelse för din ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Och skall skrifva dem på dins hus dörrträ, och uppå dörrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'När nu Herren din Gud låter dig komma uti landet, som han dina fader, Abraham, Isaac och Jacob, svorit hafver, dig att gifva stora och sköna städer, som du intet byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Och hus full med allt godt, de du intet uppfyllt hafver; och uthuggna brunnar, som du intet uthuggit hafver; och vingårdar och oljoberg, som du intet planterat hafver, att du må äta och mätt varda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Så tag dig vara, att du icke förgäter Herran, som dig utur Egypti land, utu träldomens hus, fört hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Utan skall frukta Herran din Gud, och tjena honom, och svärja vid hans Namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Och skall icke följa andra gudar efter, dess folks, som omkring eder bo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Ty Herren din Gud är en nitälskande Gud ibland dig; att Herrans dins Guds vrede icke skall förgrymma sig öfver dig, och förgöra dig af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'I skolen icke försöka Herran edar Gud, såsom I försökten honom i Massa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Utan skolen hålla Herrans edars Guds bud, och hans vittnesbörder, och hans rätter, som han budit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Att du gör det rätt och godt är för Herrans ögon, på det dig må gå väl, och du inkommer, och intager det goda landet, som Herren svorit hafver dina fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Att han skall fördrifva alla dina fiendar för dig, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'När nu din son i dag eller i morgon frågar dig, och säger: Hvad är detta för vittnesbörder, bud och rätter, som Herren vår Gud eder budit hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Så skall du säga dinom son: Vi vorom Pharaos trälar i Egypten; och Herren förde oss utur Egypten med mägtiga hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Och Herren gjorde stor och ond tecken och under öfver Egypten och Pharao, och allt hans hus, för vår ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Och förde oss dädan, på det han skulle införa oss, och gifva oss det land, som han våra fäder svorit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Och böd Herren oss att göra efter alla dessa rätter, att vi skole frukta Herran vår Gud, att oss väl går i alla våra lifsdagar, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Och det skall vara oss till rättfärdighet för Herranom vårom Gud, om vi hålle och göre all dessa buden, såsom han oss budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'När Herren din Gud förer dig in uti det land, der du inkomma skall, till att intaga det, och nederlägger mycket folk för dig; de Hetheer, Girgaseer, Amoreer, Cananeer, Pheriseer, Heveer och Jebuseer, sjuhanda folk, de som större äro och mägtigare än du;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Och när Herren din Gud gifver dem för dig, att du slår dem, så skall du gifva dem tillspillo, och intet förbund med dem göra, eller någon gunst bevisa dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Och skall intet befrynda dig med dem; edra döttrar skall du icke gifva deras söner, och deras döttrar skolen I icke taga edrom sönom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Förty de varda dragande edra söner ifrå mig, så att de tjena andra gudar; så varder då Herrans vrede förgrymmandes sig öfver eder, och snarliga förgör eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Utan alltså skolen I göra med dem: Deras altare skolen I nederrifva, deras stodar nederbryta, deras lundar afhugga, och deras lundar uppbränna med elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Ty du äst ett heligt folk Herranom dinom Gud; dig hafver Herren din Gud utvalt till att du skall vara hans eget folk, utaf all de folk som på jordene äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Icke hafver Herren upptagit och utvalt eder derföre, att I större på talet ären än annat folk; ty du äst minst i all folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Utan derföre, att Herren älskade eder, och att han skulle hålla sin ed, som han edra fäder svorit hade, hafver Herren utfört eder med mägtiga hand; och hafver frälst dig utu träldomens hus, utu Pharaos hand, Konungens i Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Så skall du nu veta, att Herren din Gud är en Gud, en trofast Gud, hållandes förbund och barmhertighet dem som älska honom, och hålla hans bud, i tusende leder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Och vedergäller dem som hata honom, för sitt ansigte, så att han förgör dem; och skall icke fördröjat, att han dem vedergäller för sitt ansigte, som hata honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Så behåll nu de bud, och lag, och rätter, som jag dig bjuder i denna dag, att du gör derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Och när I dessa rätter hören, och hållen dem, och gören derefter, så varder Herren din Gud ock hållandes det förbund och barmhertighet, som han dina fäder svorit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Han skall älska dig, välsigna och föröka; och skall välsigna dins lifs frukt, och dins lands frukt, dina säd, vin och oljo, fruktena af dina kor, och fruktena af din får, på landet, som han dina fäder svorit hafver att gifva dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Välsignad varder du utöfver all folk; ingen ibland dig skall vara ofruktsam, ej heller ibland din boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Herren skall taga ifrå dig all krankhet, och skall icke kasta dig någon de Egyptiers onda sjukdom uppå, hvilka du förnummit hafver; men han skall kasta dem på alla dem som dig hata.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Du skall uppfräta allt det folk, som Herren din Gud dig gifvandes varder; du skall icke skona dem, och icke tjena deras gudar; ty det vorde dig till en snaro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Om du säger i ditt hjerta: Detta folk är mer än jag; huru kan jag fördrifva dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Så frukta dig intet för dem; tänk uppå hvad Herren din Gud gjorde Pharao, och alla Egyptier;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Med stor försökelse, som du med ögonen sett hafver, och med tecken och under, och genom mägtiga hand och uträcktom arm, med hvilko Herren din Gud dig utförde. Alltså skall Herren din Gud göra allom folkom, som du fruktar före.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Dertill skall Herren din Gud sända ibland dem getingar, in tilldess förgjordt varder hvad som qvart är, och sig för dig förgömmer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Grufva dig intet för dem; ty Herren din Gud är ibland dig, den store och förfärlige Guden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Han, Herren din Gud, skall utrota dessa folken för dig, med tiden, det ena efter det andra; du kan icke hastigt förgöra dem, på det att djuren icke skola förökas emot dig på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Herren din Gud skall gifva dem för dig, och skall slå dem med stort slag, intilldess han förgör dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Och skall gifva deras Konungar i dina händer, och du skall förgöra deras namn under himmelen; ingen skall kunna dig emotstå, tilldess du förgör dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Deras afgudars beläte skall du bränna upp i elde; och skall intet begära utaf silfret eller, guldet, som deruppå är, eller taga det till dig, på det att du icke skall förtaga dig derutinnan: ty sådant är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Derföre skall du icke föra den styggelsen in uti ditt hus, att du icke varder tillspillogifven, såsom ock det är; utan du skall hafva en vämjelse och styggelse dervid; ty det är tillspillogifvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'All de bud, som jag bjuder dig i dag, skolen I hålla, att I gören derefter; på det I mågen lefva och förökas, och komma in, och intaga det land, som Herren edra fäder svorit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Och skall tänka på allan den väg, genom hvilken Herren din Gud dig ledt hafver, i dessa fyratio åren i öknene; på det han skulle späka och försöka dig, att kunnigt skulle varda hvad i dino hjerta var; om du hölle hans bud eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Han späkte dig och lät dig hungra, och spisade dig med Man, det du och dine fäder intet känt hade; på det han skulle låta dig veta, att menniskan lefver icke allenast af bröd, utan af allt det af Herrans mun går.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Din kläder äro intet förslitne på dig, och dine fötter äro intet svullnade i dessa fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Så finner du ju i dino hjerta, att Herren din Gud dig lärt hafver, såsom en man lärer sin son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Så håll nu Herrans dins Guds bud, att du vandrar i hans vägar, och fruktar honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Ty Herren din Gud förer dig uti ett godt land; i ett land, der bäcker, och brunnar, och djup uti äro, hvilke utmed bergen och inpå slättena flyta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Ett land, der hvete, korn, vinträ, fikonträ och granatäple uti äro; ett land, der oljoträ och hannog uti växer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Ett land, der du skall hafva bröd nog till att äta, der ock intet fattas; ett land, hvilkets stenar äro jern; der du ock koppar utu bergen hugger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Och när du ätit hafver och äst mätt, att du då lofvar Herran din Gud, för det goda land, som han dig gifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Så tag dig nu vara, att du icke förgäter Herran din Gud, dermed, att du icke håller hans bud, och hans lag och rätter, som jag bjuder dig i dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Att när du ätit hafver, och äst mätt, och bygger skön hus, der du uti bor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Och ditt fä och får, och silfver och guld, och allt det du hafver, förökas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Att ditt hjerta då icke upphäfves, och du förgäter Herran din Gud, som dig utur Egypti land fört hafver, utu träldomens hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Och hafver ledt dig igenom denna stora och förskräckeliga öknen, der brännande ormar, och scorpion, och torrhet, och platt intet vatten var, och lät dig utgå vatten ur hårda hälleberget;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Och spisade dig med Man i öknene, der dine fäder intet af vetat hade; på det han skulle späka och försöka dig, och framdeles göra väl emot dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Annars måtte du säga i dino hjerta: Min kraft och mina händers starkhet hafver mig denna förmågona gjort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Utan tänk på Herran din Gud; ty han är den som kraft gifver till att komma detta åstad; på det han skulle fullkomna sitt förbund, som han dina fäder svorit hade, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Men om du förgäter Herran din Gud, och följer andra gudar efter, och tjenar dem, och tillbeder dem; så betygar jag i dag öfver eder, att I skolen slätt förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Lika som Hedningarna, hvilka Herren förgör för edart ansigte, så skolen ock I förgås; derföre, att I icke ären Herrans edars Guds röst hörige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Hör, Israel: I dag skall du gå öfver Jordan, att du inkommer till att intaga de folk, som större och starkare äro än du; stora städer, murade upp till himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Ett stort högt folk, Enakims barn, som du känt hafver, af hvilkom du ock hört hafver: Ho kan stå emot Enaks barn?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Så skall du veta i dag, att Herren din Gud går framför dig, en förtärande eld; han varder dem förgörandes och nederläggandes för dig, och skall fördrifva dem, och omintetgöra dem snarliga, såsom Herren dig sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Då nu Herren din Gud dem utdrifvit hafver för dig, så säg icke i dino hjerta: Herren hafver mig här infört, till att intaga detta landet för mina rättfärdighets skull; ändock Herren fördrifver Hedningarna för dig, för deras ogudaktighets skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ty du kommer icke in i landet till att besitta det, för dina rättfärdighet, eller för dins hjertas fromhets skull; utan Herren din Gud fördrifver dessa Hedningarna för deras ogudaktighets skull, på det han skall fullkomna det ord, som Herren dina fäder, Abraham, Isaac och Jacob, svorit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Så vet nu, att Herren din Gud icke gifver dig detta goda landet till att intaga för dina rättfärdighets skull; efter du äst ett halsstyft folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Kom ihåg, och förgät icke, huru du Herran din Gud förtörnade i öknene; ifrå den dag att du drog utur Egypti land, tilldess I komne ären till detta rum, hafven I varit Herranom ohörsamme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Förty i Horeb förtörnaden I Herran, så att Herren för vredes skull ville förgöra eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Då jag gången var på berget, till att anamma de stentaflor, förbundsens taflor, som Herren gjorde med eder, och jag blef på bergena fyratio dagar, och fyratio nätter, och åt intet bröd och drack intet vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Och Herren fick mig de två stentaflorna, beskrefna med Guds finger, och derutinnan all ord, som Herren med eder utur elden på berget talat hade, på församlingenes dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Och efter de fyratio dagar och fyratio nätter fick mig Herren de två förbundsens stentaflor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Och Herren sade till mig: Statt upp, gack snart ned hädan; ty ditt folk, som du utfört hafver af Egypten, hafver förderfvat det; de äro snarliga trädde ifrå den vägen, som jag hafver budit dem; de hafva gjort sig ett gjutet beläte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Och Herren sade till mig: Jag ser, att detta folket är ett halsstyft folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Låt mig betämma, att jag förgör dem, och utskrapar deras namn under himmelen. Jag vill göra ett starkare och mägtigare folk af dig, än detta är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Och som jag omvände mig, och gick ned af berget, som brann i eld, och hade de två förbundsens taflor i båda mina händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Då såg jag, och si, då haden I syndat emot Herran edar Gud, så att I haden gjort en gjuten kalf, och voren snarliga trädde ifrå den vägen, den Herren eder budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Så tog jag båda taflorna, och kastade dem bort utu båda händerna, och slog dem sönder för edor ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Och föll ned för Herran, såsom tillforene, i fyratio dagar, och fyratio nätter; och åt intet bröd, och drack intet vatten, för alla edra synders skull, som I gjort haden; i det I sådant ondt gjorden för Herranom, till att förtörna honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Ty jag fruktade för den vrede och grymhet, der Herren på eder med förtörnad var, så att han ville förgöra eder. Och Herren hörde mig än i den gången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Var ock Herren storliga vred på Aaron, så att han ville förgöra honom; men jag bad ock för Aaron på samma tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Men edor synd, kalfven som I gjort haden, tog jag och brände upp i elde, och slog sönder honom, och sönderstötte, tilldess han vardt stoft; och kastade stoftet i bäcken, som flyter utaf bergena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Sammalunda förtörnaden I ock Herran i Thabeera, och i Massa, och vid de Lustgrifter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Och då Herren sände eder ifrå KadesBarnea, och sade: Går ditupp, och tager landet in, som jag eder gifvit hafver; voren I Herrans edars Guds mun ohörsamme, och trodden icke på honom, och lydden icke hans röst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Ty I hafven varit Herranom ohörsamme, så länge som jag eder känt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Då föll jag neder för Herran fyratio dagar, och fyratio nätter, som jag der låg; ty Herren sade, att han ville förgöra eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Men jag bad Herran, och sade: Herre, Herre, förderfva icke ditt folk och din arfvedel, hvilket du genom dina stora magt förlossat, och med mägtiga hand utur Egypten fört hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Kom ihåg dina tjenare Abraham, Isaac och Jacob; se icke på detta folkets hårdhet, och detta folkets ogudaktighet och synd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Att det landet, der du oss utfört hafver, icke skall säga: Herren kunde icke föra dem uti det land, som han dem lofvat hade, och hafver fördenskull fört dem derut, att han var vred på dem, att han skulle dräpa dem i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Förty de äro ditt folk, och din arfvedel, som du med dine stora magt, och med din uträckta arm, utfört hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'På samma tiden sade Herren till mig: Uthugg dig två stentaflor såsom de första, och kom till mig på berget, och gör dig en ark af trä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Så vill jag skrifva på taflorna de ord, som på de första voro, hvilka du sönderslagit hafver; och du skall lägga dem i arken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Så gjorde jag då en ark af furoträ, och uthögg två stentaflor, sådana som de första voro, och gick upp på berget, och hade de två taflorna i mina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Då skref han på taflorna, såsom den första skriften var, de tio ord, som Herren talade till eder utur eldenom på berget, på församlingenes dag; och Herren fick mig dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Och jag vände om, och gick af berget, och lade taflorna i arken, som jag gjort hade, att de skulle der blifva, såsom Herren mig budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Och Israels barn drogo ut ifrå Beeroth BeneJaakan till Moserah; der blef Aaron död, och vardt der begrafven; och hans son Eleazar vardt Prester för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Dädan drogo de ut till Gudgoda; ifrå Gudgoda till Jothbath, ett land der bäcker äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'På den tiden afskiljde Herren Levi slägte, till att bära Herrans förbunds ark, och till att stå för Herranom, till att tjena honom, och lofva hans Namn, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Derföre skulle de Leviter ingen del eller arf hafva med sina bröder; ty Herren är deras arf, såsom Herren din Gud dem sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Och jag stod på bergena, såsom tillförene, fyratio dagar och fyratio nätter, och Herren bönhörde mig än i den gången, och Herren ville icke förgöra dig,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Men Herren sade till mig: Statt upp, och gack åstad, att du går för folket, att de inkomma, och intaga landet, som jag deras fäder svorit hafver dem att gifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nu, Israel, hvad äskar Herren din Gud af dig, utan att du skall frukta Herran din Gud, att du vandrar i alla hans vägar, och älskar honom, och tjenar Herranom dinom Gud, af allo hjerta och af allo själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Att du håller Herrans bud och hans rätter, de jag dig bjuder i denna dag, på det att dig må väl gå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Si, himmelen och alla himlars himlar, och jorden, och allt det deruti är, är Herrans dins Guds?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Dock likväl hafver Herren allena haft vilja till dina fäder, så att han älskade dem, och hafver utvalt deras säd efter dem, nämliga eder, utöfver allt folk, såsom det ock tillgår på denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Så omskärer nu edars hjertas förhud, och varer icke mer halsstyfve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Förty Herren edar Gud är en Gud öfver alla gudar, och en Herre öfver alla herrar, en stor Gud, mägtig och förfärlig, den ingen person aktar, och tager inga mutor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Och skaffar dem faderlösom och enkom rätt, och älskar de främmande, så att han gifver dem födo och kläde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Derföre skolen I ock älska de främmande; ty I hafven ock varit främmande uti Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Herran din Gud skall du frukta; honom skall du tjena; till honom skall du hålla dig, och svärja vid hans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Han är ditt lof, och din Gud, den med dig så stor och förfärlig ting gjort hafver, såsom din ögon sett hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Dine fäder foro neder uti Egypten med sjutio själar; men nu hafver Herren din Gud förökat dig, såsom stjernorna på himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Så skall du nu älska Herran din Gud, och hålla hans lag, hans seder, hans rätter och hans bud, så länge du lefver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Och förnimmer i dag det edor barn icke veta, eller sett hafva; nämliga Herrans edars Guds tuktan, hans härlighet, och hans mägtiga hand, och uträckta arm;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Och hans tecken och verk, som han gjorde ibland de Egyptier, på Pharao, Konungen i Egypten, och på allt hans land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Och hvad han gjorde på de Egyptiers magt; på deras hästar och vagnar, då han lät komma vattnet af det röda hafvet öfver dem, när de foro efter eder, och Herren förgjorde dem, allt intill denna dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Och hvad han eder gjorde i öknene, intilldess I nu till detta rummet komne ären;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Hvad han gjorde Dathan och Abiram, Eliabs sönom, Rubens sons; huru jorden öppnade sin mun, och uppsvalg dem med deras folk och tjäll, och alla deras ägodelar, som under dem voro, midt i hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Ty edor ögon hafva sett de stora Herrans gerningar, som han gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Derföre skolen I hålla all de bud, som jag bjuder eder i dag, på det I skolen styrkte varda till att komma in, och intaga landet, dit I faren till att intaga det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Och att du skall länge lefva i landena, som Herren edra fäder svorit hafver att gifva dem och deras säd, ett land der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Ty det landet, som du kommer till att intaga, är icke såsom Egypti land, der I utdragne ären, der man sår säd, och bär dit vatten till fots, såsom till en kålgård;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Utan det hafver berg, och slättmarker, hvilka regn af himmelen vattna måste:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Om hvilket land Herren din Gud låter sig vårda, och Herrans dins Guds ögon se alltid deruppå, ifrå begynnelsen på året, intill ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Om I nu hören min bud, som jag bjuder eder i dag, att I älsken Herran edar Gud, och tjenen honom af allt hjerta, och af allo själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Så skall jag gifva edro lande regn i sinom tid, arla och serla, att du skall inberga din säd, ditt vin, och dina oljo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Och skall gifva dinom boskap gräs på dine mark, att I mågen äta och varda mätte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Men tager eder vara, att edart hjerta icke låter draga sig dertill, att I afträden, och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Och Herrans vrede förgrymmar sig då öfver eder, och lycker himmelen till, att intet regn kommer, och jorden icke gifver sin växt, och I snarliga förgås utaf det goda landet, som Herren eder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Så fatter nu dessa orden i hjertat, och i edra själar, och binder dem för ett tecken på edra hand, att de äro till en åminnelse för edor ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Och lärer dem edor barn, så att du talar derom, när du sitter i dino huse, eller går på vägen; när du lägger dig neder, och när du uppstår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Och skrif dem på dörrträn i dino huse, och på dine dörr;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Att du och din barn mågen länge lefva i landena, som Herren dine fäder svorit hafver att gifva dem, så länge dagarna af himmelen på jordene vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Ty om I alla dessa buden hållen, som jag bjuder eder, och derefter gören, så att I älsken Herran edar Gud, och vandren i alla hans vägar, och håller eder intill honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Så skall Herren fördrifva allt detta folket för eder, så att I skolen intaga större och starkare folk än I ären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'All rum, som edar fot på träder, skola vara edor; ifrån öknene och ifrå berget Libanon, och ifrån älfvene Phrath, allt intill det yttersta hafvet, skall edart landamäre vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ingen skall kunna stå eder emot; edar räddhåga och förfärelse skall Herren låta komma öfver all de land, der I inresen, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Si, jag lägger eder före i dag välsignelse och förbannelse:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Välsignelse, om I lyden Herrans edars Guds bud, som jag bjuder eder i dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Förbannelse, om I icke lyden Herrans edars Guds bud, och afträden ifrå den vägen, som jag bjuder eder i dag, så att I vandren efter andra gudar, de I icke kännen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'När Herren din Gud förer dig in i det land, der du inkommer till att intågat, så skall du låta tala välsignelsen på det berget Grisim, och förbannelsen på det berget Ebal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Hvilke äro på hinsidon Jordan, på den vägen vesterut, i de Cananeers lande, som bo på den slättmarkene in emot Gilgal, vid den lunden More.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Ty du måste gå öfver Jordan, att du inkommer, och tager landet in, som Herren edar Gud eder gifvit hafver, att I det intaga och deruti bo skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Så ser nu till, att I gören efter all de bud och rätter, som jag eder i dag förelägger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Desse äro de bud och rätter, som I hålla skolen, så att I gören derefter uti i landena, som Herren dina fäders Gud dig gifvit hafver till att intaga, så länge I på jordene lefven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Förgörer all de rum, der Hedningarna, som I intagen, sina gudar tjent hafva, vare sig på hög berg, på backar, eller under grön trä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Och bryter neder deras altare, och slår sönder deras stodar; och deras lundar uppbränner med eld, och deras afgudabeläte kaster bort, och tager bort deras namn utu det rummet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'I skolen icke så göra Herranom edrom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Utan på det rum, som Herren edar Gud utväljer af allom edrom slägtom, att han vill låta sitt Namn der bo, der skolen I fråga, och dit komma;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Och göra edart bränneoffer, och edor annor offer, och edor tiond, och edra händers häfoffer, och edor löfte, och edor friviljoga offer, och förstfödningena af edart fä och får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Och der skolen I äta för Herranom edrom Gud, och vara glade öfver allt det I och edor hus förvärfven, der Herren din Gud dig uti välsignat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'I skolen intet göra af det vi i dag här görom, hvar och en som honom tycker rätt vara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Ty I ären ännu härtilldags icke komne till ro, eller till arfvedelen, som Herren din Gud dig gifva skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Men I måsten gå öfver Jordan, och bo i de landena, som Herren edar Gud eder till arfs utskiftandes varder; och han skall låta eder få ro för alla edra fiendar omkring eder, och I skolen bo trygge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'När nu Herren din Gud utväljer ett rum, att hans Namn der bo skall, dit skolen I bära allt det jag bjuder eder: edart bränneoffer, edor annor offer, edor tiond, edra händers häfoffer, och all edor fri löfte, som I Herranom lofven;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Och skolen vara glade för Herranom edrom Gud, I och edre söner, och edra döttrar, och edre tjenare, och edra tjenarinnor, och Leviterna, som i edra portar äro; förty de hafva ingen lott eller arfvedel med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Tag dig vara, att du icke offrar ditt bränneoffer i all de rum som du ser;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Utan i det rum, som Herren utväljer, uti någro af dina slägter, der skall du offra ditt bränneoffer, och göra allt det jag bjuder dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Dock må du slagta, och äta kött i alla dina portar, efter all dine själs begärelse, efter Herrans dins Guds välsignelse, som han dig gifvit hafver; både rene och orene måga det äta, såsom en rå eller en hjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Men blodet skall du icke äta; utan gjuta det på jordena såsom vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Men icke må du äta i dina portar utaf tionden af din säd, dino vine, dine oljo, ej heller af den förstfödning af dino fä, af din får, eller af något ditt löfte, som du lofvat hafver, eller af ditt friviljoge offer, eller af dine hands häfoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Utan för Herranom dinom Gud skall du sådant äta på de rumme, som Herren din Gud utväljer, du och dine söner, dina döttrar, dine tjenare, dina tjenarinnor, och Leviten, som i dina portar är; och skall vara glad för Herranom dinom Gud, öfver allt det du dig företager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Och tag dig vara, att du icke öfvergifver Leviten, så länge du lefver på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'När nu Herren din Gud varder förvidgandes dina landsändar, såsom han dig sagt hafver, och du säger: Jag vill äta kött; efter din själ lyster äta kött, så ät kött efter alla dine själs begärelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Är rummet långt ifrå dig, som Herren din Gud utvalt hafver, att han der vill låta bo sitt Namn, så slagta af ditt fä eller får, som Herren dig gifvit hafver, såsom jag dig budit hafver, och att det i dinom portom, efter all dine själs begärelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Såsom man äter en rå eller en hjort, må du ätat; både rene och orene måga lika väl ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Allenast vakta, att du icke äter blodet; ty blodet är själen, derföre skall du icke äta själena med köttet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Utan skall gjuta det på jordena såsom vatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Och skall fördenskull icke ätat, att dig må väl gå, och dinom barnom efter dig, deraf att du gjort hafver det som rätt är för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Men när du helgar något det ditt är, eller lofvar, så skall du tagat, och bära till det rum, som Herren utvalt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Och göra ditt bränneoffer, med kött och blod, på Herrans dins Guds altare; blodet af ditt offer skall du gjuta på Herrans dins Guds altare, och äta köttet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Se till, och hör alla dessa orden, som jag bjuder dig; på det dig må väl gå, och dinom barnom efter dig till evig tid, deraf att du gjort hafver det rätt är, och Herranom dinom Gud behageligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'När Herren din Gud utrotar Hedningarna för dig, der du inkommer till att intaga dem, och du dem intagit hafver, och bor i deras land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Så tag dig vara, att du icke faller i snarona efter dem, sedan de fördrefne äro för dig; och att du intet söker efter deras gudar, och säger: Såsom detta folk hafver tjent deras gudar, så vill jag ock göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Du skall icke således göra Herranom dinom Gud; förty de hafva gjort sinom gudom allt det Herranom stygges vid, och det han hatar; ty de hafva ock uppbränt i elde sina söner och döttrar till sina gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Allt det jag bjuder eder, det skolen I hålla, så att I gören derefter. I skolen intet lägga dertill, och intet taga derifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Om en Prophet eller drömmare uppkommer ibland eder, och han gifver dig ett tecken eller under;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Och det tecken eller under sker, der han dig af sade, och säger: Låt oss vandra efter andra gudar, de som I icke kännen, och tjenom dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Så skall du icke höra den Prophetens eller drömmarens ord; ty Herren din Gud försöker eder, att han må förfara, om I af allo hjerta, och af allo själ, älsken Herran edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Ty Herran edar Gud skolen I följa, och frukta honom, och hålla hans bud, och höra hans röst, och honom tjena, och hålla eder intill honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Men den Propheten eller drömmaren skall dö, derföre att han lärde afträdelse ifrå Herranom edrom Gud, som eder utur Egypti land fört, och dig utu träldomens hus förlossat hafver: på det han skulle komma dig utaf den vägen, som Herren din Gud budit hafver, till att vandra deruppå; på det att du skall skilja den onda ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Om din broder, dins moders son, eller din son, eller din dotter, eller hustrun, som är i dinom famn, eller din vän, den dig är såsom ditt hjerta, råder dig hemliga, och säger: Låt oss gå, och tjena andra gudar, hvilka du intet känner, ej heller dine fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'De gudar, som ibland folken allt omkring eder äro, ehvad de äro när eller fjerran, ifrå den ena jordenes ända intill den andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Så samtyck det icke, ej heller lyd honom; och skall ditt öga intet skona honom, och skall intet förbarma dig öfver honom, eller fördölja honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Utan skall dräpa honom; din hand skall vara den första öfver honom, att han dräpes; och dernäst hela folkens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Man skall stena honom ihjäl; ty han for efter att han skulle komma dig ifrå Herranom dinom Gud, den dig utur Egypti land, ifrå träldomens hus, fört hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'På det att hela Israel skall det höra, och befrukta sig, och icke mer taga sig sådana ondt före ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Om du får höra i någon stad, som Herren din Gud dig gifvit hafver till att bo uti, att man säger:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Någre Belials barn äro utgångne ibland dig, och hafva förfört deras stads inbyggare, och sagt: Låt oss gå, och tjena andra guidar, som I intet kännen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Så skall du granneliga söka, ransaka och befråga, om sanningen finnes, att så visst är, att denna styggelsen ibland eder skedd är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Så skall du slå den stadsens inbyggare med svärdsegg, och dem tillspillogifva, med allt som derinne är, och deras boskap med svärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Och allt deras rof skall du tillhopabära midt uppå gatona, och bränna upp i elde, både staden och allt hans rof, det ena med det andra, Herranom dinom Gud; att han till en hög blifver i evig tid, och aldrig uppbyggd varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Och låt intet blifva i dine hand af det som tillspillogifvet är; på det att Herren skall vändas ifrå sine vredes grymhet, och gifva dig barmhertighet, och förbarma sig öfver dig, och föröka dig, såsom han dina fäder svorit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Derföre, att du Herrans dins Guds röst lydt hafver, till att hålla all hans bud, som jag dig bjuder på denna dag, att du skall göra det som rätt är för Herrans dins Guds ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'I ären Herrans edars Guds barn; skärer eder icke, och görer eder icke skallota öfver edart änne för någon dödan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Ty du äst ett heligt folk Herranom dinom Gud, och Herren hafver utvalt dig, att du skall vara hans eget, utaf all folk som på jordene äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du skall ingen styggelse äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Men desse äro de djur, som I äta skolen: Fä, får, get, hjort,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Rå, buffel, stenbock, enhörning, urnöt, och elgen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Och all djur, som tveklöfvad äro, och idisla, skolen I äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Men det skolen I icke äta, som idislar, och icke tveklöfvadt är: camelen, haran, cunilen. De som idisla, och icke tveklöfvad äro, de skola vara eder oren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Svinet, ändock det tveklöfvadt är, så idislar det dock icke, det skall vara eder orent; af dess kött skolen I icke äta, och vid dess as skolen I icke komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Detta är det I äta skolen, utaf allt det i vattnet är: allt det som spol och fjäll hafver, det skolen I äta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Men det som intet spol eller fjäll hafver, det skolen I icke äta; ty det är eder orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alla rena foglar äter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Desse af dem äro de som I icke äta skolen: örnen, höken, falken,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Fiskagjusen, gladan, gamen med sine art,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Och alla korpar med deras art,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Strutsfoglen, ugglan, göken, sparfhöken med sine art,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Stenugglan, ufven, flädermusen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Rördrommen, storken, svanen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Hägren, skrikan med sine art, vidhöfden, och svalan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Och alle foglar, som krypa, skola vara eder orene, och I skolen icke äta dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'De rena foglar skolen I äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'I skolen intet as äta. Främlingenom, som i dinom porte är, må du gifva det, att han det äter, eller sälj det enom främmande; ty du äst ett heligt folk Herranom dinom Gud. Du skall icke koka kidet, medan det ännu dir sina moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Du skall all år afskilja tionden af allo dine säds frukt, som utaf dinom åker kommer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Och skall äta den för Herranom dinom Gud, på det rum som han utväljer, att hans Namn der bo skall; nämliga af tionden utaf din säd, dino vine, dine oljo, och förstfödningen af ditt fä och din får; på det du skall lära frukta Herran din Gud i alla dina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Om vägen är dig för lång, att du icke kan komma det dit, derföre att det rummet är dig för långt ifrå, som Herren din Gud utvalt hafver, att han vill låta sitt Namn bo der; ty Herren din Gud hafver välsignat dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Så sälj det allt för penningar, och tag penningarna i dina hand, och gack till det rum, som Herren din Gud utvalt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Och köp för penningarna allt det din själ lyster, vare sig fä, får, vin, stark dryck, eller allt det din själ begärar; och ät det der för Herranom dinom Gud, och var glad, du och ditt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Och Leviten, som i dina portar är, honom skall du icke förlåta; förty han hafver ingen lott eller arf med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Efter tre år skall du afsöndra all tiond af dine säd i det året, och skall lägga henne i dina portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Så skall Leviten komma, som ingen lott eller arf hafver med dig; och främlingen, och den faderlöse, och enkan, som i dina portar äro, och äta, och mätta sig; på det Herren din Gud dig välsigna skall i alla dina händers gerningar, som du gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Efter sju år skall du hålla ett friår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Och så skall det tillgå med samma friår: Hvilken man något ifrå sine hand sinom nästa borgat hafver, han skall icke kräfva det in af sinom nästa, eller af sinom broder; förty det heter friår Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Utaf en främmande må du det inkräfva; men dinom broder skall du tillgifvat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Och skall allsingen fattig vara ibland eder; ty Herren varder dig välsignande uti landena, som Herren din Gud dig till arfs gifva skall, till att intaga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Allenast att du lyder Herrans dins Guds röst, och håller all dessa buden, som jag bjuder dig i denna dag, att du gör derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Ty Herren din Gud skall välsigna dig, såsom han dig sagt hafver: Så skall du låna myckno folke; men af ingom skall du till låns taga; du skall blifva rådandes öfver mycket folk; men öfver dig skall ingen rådandes blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Om din broder i någon stad är fattig i dino lande, som Herren din Gud dig gifvandes varder, så skall du icke förhärda ditt hjerta eller tillycka dina hand för dinom fattiga broder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Utan skall upplycka henne honom, och låna honom, efter som honom fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Vakta dig, att i ditt hjerta icke ligger ett Belials ord, så att du säger: Det kommer snart sjunde året, som är friåret, och ser så illa ut på din fattiga broder, och får honom intet; så varder han ropandes öfver dig till Herran, och det varder dig till synd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Utan du skall låtan fåt, och ditt hjerta skall icke förtrytat, att du får honom det; ty fördenskull skall Herren din Gud välsigna dig i alla dina gerningar, och i allt det du företager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Fattige skola väl alltid vara i landena; derföre bjuder jag dig, och säger, att du skall upplycka dina hand dinom broder, som trängder och fattiger är i dino lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Om din broder, en Ebreisk eller Ebreiska, säljer sig dig, så skall han tjena dig i sex år, i sjunde årena skall du gifva honom fri lös.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Och när du gifver honom fri lös, skall du icke låta honom gå med tomma händer ifrå dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Utan du skall få honom med sig af din får, af dine lado, af dinom press, så att du gifver honom af det som Herren din Gud dig med välsignat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Och tänk uppå, att du ock vast en träl i Egypti land, och Herren din Gud förlossade dig; derföre bjuder jag dig detta i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Säger han till dig: Jag vill icke fara ut ifrå dig; ty jag unner dig och dino huse godt, efter han mår väl när dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Så tag en syl, och borra honom genom hans öra, vid dins huses dörr, och låt honom blifva din träl i evig tid; med dine trälinno skall du ock så göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Och låt dig icke tycka tungt vara, att du gifver honom fri lös; förty han hafver tjent dig såsom en dubbel legodräng, i sex år; så skall Herren din Gud välsigna dig i allt det du gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Allt förstfödt, som ibland ditt fä och får födt varder, det mankön är, det skall du helga Herranom dinom Gud; du skall icke arbeta med förstfödningen af dino fä, och icke klippa förstfödningen af din får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'För Herranom dinom Gud skall du äta dem årliga, på det rum som Herren utvalt hafver, du och ditt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Om det hafver någon brist, så att det haltar, eller är blindt, eller eljest någon ond vank hafver, så skall du icke offra det Herranom dinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Utan i dinom port skall du ätat, ehvad du äst ren eller oren, såsom en rå eller hjort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Allenast att du icke äter af dess blod, utan gjuter det på jordena såsom vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Håll den månaden Abib, att du gör Herranom dinom Gud Passah; förty uti Abibs månad hafver Herren din Gud fört dig utur Egypten om natten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Och du skall slagta Herranom dinom Gud Passah, får och fä, på det rum, som Herren utväljandes varder, att hans Namn der bo skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du skall intet syradt bröd äta i de högtidene. I sju dagar skall du äta osyradt bedröfvelsens bröd; förty med hast gick du utur Egypti land; på det att du skall ihågkomma den dagen, som du drog utur Egypti land, i alla dina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'I sju dagar skall intet syradt bröd sedt varda i alla dina landsändar; och skall intet af köttet, som på första dagen om aftonen slagtadt vardt, blifva qvart öfver nattena intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du kan icke slagta Passah någorstädes i dinom portom, som Herren din Gud dig gifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Utan på det rum, som Herren din Gud utväljandes varder, att hans Namn der bo skall, der skall du slagta Passah, om aftonen när solen nedergången är, vid den tiden som du utur Egypten drogst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Och du skall kokat, och ätat på det rum, som Herren din Gud utväljandes varder; och sedan om morgonen vända dig, och gå hem i dina hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'I sex dagar skall du äta osyradt, och på sjunde dagen är Herrans dins Guds församling, då skall du intet arbete göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sju veckor skall du räkna dig, och begynna räkna ifrå den dagen, när man kastar lian i sädena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Och skall hålla veckohögtid Herranom dinom Gud, att du gifver dina hands friviljoga gåfvo, efter som Herren din Gud dig välsignat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Och du skall vara glad för Herranom dinom Gud, du och din son, din dotter, din tjenare, din tjenarinna, och Leviten som är i dina portar, främlingen, den faderlöse och enkan, som ibland dig äro, på det rum som Herren din Gud utväljandes varder, att hans Namn der bo skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Och tänk uppå, att du hafver varit en träl i Egypten, att du håller och gör efter dessa buden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Löfhyddohögtid skall du hålla i sju dagar, när du hafver insamlat af dinom loga, och af dinom press;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Och skall vara glad på dine högtid, du och din son, din dotter, din tjenare, din tjenarinna, Leviten, främlingen, den faderlöse och enkan, som i dina portar äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'I sju dagar skall du hålla den högtiden Herranom dinom Gud, på det rum som Herren din Gud dig utväljandes varder; ty Herren din Gud skall välsigna dig i allt det du inbergar, och i alla dina händers gerningar; derföre skall du vara glad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Tre resor om året skall allt det mankön är ibland dig, komma fram för Herran din Gud, på det rum som han utväljandes varder, på osyrade bröds högtidene, på veckohögtidene, och på löfhyddohögtidene; icke skall han tomhändter komma fram för Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Hvar och en efter sine hands gåfvo, efter den välsignelse, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Domare och ämbetsmän skall du sätta dig i allom dinom portom, som Herren din Gud dig gifvandes varder ibland dina slägter, att de måga döma folket med rättom dom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du skall icke böja rätten, och skall ock ingen person anse, eller mutor taga; förty mutor förblinda de visa, och förvända de rättfärdigas saker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Du skall fara efter det rätt är; på det du må lefva, och besitta det land, som Herren din Gud dig gifvandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du skall icke någon lund af någrahanda trä plantera vid Herrans dins Guds altare, som du dig gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Du skall ingen stod uppresa, hvilket Herren din Gud hatar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du skall icke offra Herranom dinom Gud något nöt eller får, det någon brist eller något ondt på sig hafver; förty det är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Om någor funnen varder i någon af dina portar, som Herren din Gud dig gifvandes varder, man eller qvinna, den som illa gör för Herrans dins Guds ögon, så att han öfverträder hans förbund;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Och går bort, och tjenar andra gudar, och tillbeder dem, vare sig sol eller måne, eller någor himmels här, det jag icke budit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Och det varder dig sagdt, och du hörer det, så skall du granneligen fråga derefter; och när du finner, att det visserliga sant är, att sådana styggelse skedd är i Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Så skall du utföra den samma mannen eller den samma qvinnona, som sådana ondt gjort hafva, till dina portar, och skall stena dem ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Efter tu eller tre vittnes mun skall den dö, som döden värd är; men efter ett vittnes mun skall han icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Vittnens hand skall den första vara till att dräpa honom, och sedan allt folksens hand; på det att du låter den onda ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Om någor sak i rätta varder dig för svår, emellan blod och blod, emellan handel och handel, emellan skada och skada, och hvad tvedrägtiga saker äro i dinom portom, så skall du stå upp, och gå upp till det rum, som Herren din Gud utväljandes varder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Och till Presterna, Leviterna, och till domaren, som den tiden är, och fråga af dem; de skola säga dig domen af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Och du skall göra efter som de säga dig före i de rumme, som Herren utväljandes varder; och skall hålla det så, att du gör efter allt det som de dig lära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Efter lagen, som de lära dig, och efter rätten, som de säga dig före, skall du hålla dig, så att du icke viker derifrå, antingen på den högra sidon, eller på den venstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Och om någor vore öfverdådig, så att han icke ville lyda Prestenom, som der i Herrans dins Guds ämbete står, eller domarenom, han skall dö; och du skall borttaga den onda af Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Att allt folket skall höra det, och rädas och icke mer öfverdådige vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'När du kommer uti landet, som Herren din Gud dig gifva skall, och tager det in, och bor der, och varder sägandes: Jag vill sätta en Konung öfver mig, såsom all folk omkring mig hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Så skall du den sätta för Konung öfver dig, som Herren din Gud utväljer. Du skall en af dina bröder sätta öfver dig för Konung; du kan icke sätta en främmande öfver dig, den icke din broder är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Allenast att han icke håller många hästar, och förer folket åter in i Egypten, för de många hästars skull; efter Herren eder sagt hafver, att I icke mer genom denna vägen komma skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Han skall ock icke taga sig många hustrur, att hans hjerta varder icke afvändt; och skall ej heller mycket silfver eller guld församla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Och när han nu sittandes varder på sins rikes stol, skall han taga denna andra lagen af Prestomen Levitomen, och låta den skrifva uti en bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Hon skall vara när honom, och han skall deruti läsa i alla sina lifsdagar; på det att han skall lära frukta Herran sin Gud, att han håller all denna lagsens ord, och dessa rätter, att han gör derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Han skall icke förhäfva sitt hjerta utöfver sina bröder; och skall icke vika ifrå budet, hvarken på den högra sidona, eller på den venstra; på det han skall förlänga sina dagar i sitt regemente, han och hans barn i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Presterna Leviterna, och hela Levi slägt, skola ingen lott eller arf hafva med Israel; Herrans offer och hans arfvedel skola de äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Derföre skola de intet arf hafva ibland deras bröder; ty Herren är deras arf, såsom han dem sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Och detta skall vara Presternas rättighet af folkena, och af dem som offra, ehvad det är fä eller får, att man skall gifva Prestenom bogen, och båda kindbenen, och våmbena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Och förstlingen af ditt korn, och dinom must, och dine oljo; och förstlingen af din fårs klippning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Förty Herren din Gud hafver utvalt honom utur alla dina slägter, att han stå skall i tjenstene i Herrans Namn, och hans söner evärdeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Om en Levit kommer utaf någon dina städer, eller eljest af hela Israel, der han en gäst är, och kommer af allo hans själs begärelse, till det rum som Herren utvalt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Att han vill tjena i Herrans sins Guds Namn, såsom alle hans bröder Leviterna, som der stå för Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'De skola få lika del till att äta, förutan det han hafver af sina faders sålda godse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'När du kommer uti landet, som Herren din Gud dig gifvandes varder, så skall du icke lära göra dens folksens styggelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Att ingen ibland dig varder funnen, som sin son eller dotter låter gå igenom eld, eller den som är en spåman, eller en dagväljare, eller den som på foglalåt aktar, eller trollkarl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Eller besvärjare, eller en svartkonstig, eller en tecknatydare, eller den der någon dödan frågar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Ty den som sådant gör, han är Herranom en styggelse; och för sådana styggelses skull fördrifver dem Herren din Gud för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Var utan vank inför Herranom dinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Ty detta folket, som du intaga skall, lyda de dagväljare och spåmän; men du skall icke så göra Herranom dinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'En Prophet, såsom mig, skall Herren din Gud uppväcka dig, utaf dig, och utaf dina bröder; honom skolen I lyda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Såsom du beddes af Herranom dinom Gud i Horeb, på församlingenes dag, och sade: Jag vill icke mer höra Herrans mins Guds röst, och icke mer se den stora elden, att jag icke skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Och Herren sade till mig: De hafva väl sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Jag skall uppväcka dem en Prophet, såsom du äst, utaf deras bröder, och gifva min ord i hans mun; han skall tala till dem allt det jag honom bjuda vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Och den som min ord icke hörer, som han i mitt Namn talandes varder, af honom vill jag utkräfva det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Dock om någor Prophete djerfves tala i mitt Namn, det jag honom icke befallt hafver att tala, och den som talar i andra gudars namn, den Propheten skall dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Om du nu säga ville i ditt hjerta: Huru kan jag märka, hvilket ord Herren icke talat hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'När den Propheten talar i Herrans Namn, och der varder intet af, och sker intet, så är det det ord, som Herren icke talat hafver. Den Propheten hafver det talat af öfverdådighet: derföre skall du icke frukta dig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'När Herren din Gud hafver utrotat folket, hvilkets land Herren din Gud dig gifva skall, att du dem intager, och bor i deras städer och husom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Så skall du afskilja dig tre städer i landena, som Herren din Gud dig gifva skall till att intaga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Och skall utvälja belägna rum, och skifta dins lands gränsor, som Herren din Gud dig utdelandes varder, i tre delar; att dit må fly den som ett mandråp gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Och det skall vara saken, att dit skall fly den som ett mandråp gjort hafver, att han må lefva. Om någor slår sina nästa icke med vilja, och hafver tillförene intet hat haft till honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Utan såsom någor ginge med sin nästa i skogen till att hugga ved, och hofve med handene yxena upp till att hugga veden och jernet fölle af skaftet, och råkade hans nästa, så att han blefve död; den skall uti en af dessa städerna fly, och få lefva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'På det blodhämnaren icke skall fara efter dråparen, medan hans hjerta förbittradt är, och få fatt på honom, om vägen är lång, och slå hans själ; ändock han till döds icke brutit hafver, efter han tillförene intet hat till honom haft hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Derföre bjuder jag dig, att du afskiljer tre städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Och om Herren din Gud dina landsändar utvidgandes varder, såsom han dina fäder svorit hafver, och gifver dig allt det landet, som han dina fäder lofvat hafver att gifva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Om du annars håller all dessa buden, att du gör derefter, som jag dig bjuder i denna dag, att du älskar Herran din Gud, och vandrar i hans vägar i dina lifsdagar, så skall du ännu tre städer lägga till dessa tre städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'På det oskyldigt blod icke skall utgjutet varda i dino lande, som Herren din Gud dig till arfs gifva skall, och blodskulder komma öfver dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Men om någor hafver hat emot sin nästa, och vaktar efter honom, och han går åstad, och slår honom hans själ ihjäl, och flyr uti en af dessa städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Så skola de äldste i hans stad sända dit, och låta hem ta honom dädan, och få honom i blodhämnarens händer, att han skall dräpas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Din ögon skola intet skona honom, och skall borttaga oskyldigt blod af Israel, på det att dig må väl gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du skall icke dins nästas råmärke flytta, hvilka förfäderna satt hafva i dinom arfvedel, den du ärfver i landena, som Herren din Gud dig gifvit hafver att intaga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Intet vittne skall ensamt framträda emot någon om någor missgerning eller synd, ehvad missgerning det är som man göra kan; utan i tvegge eller tregge vittnes mun skola alla saker stå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Om ett vrångt vittne går fram emot någon, till att vittna öfver honom någon öfverträdning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Så skola de både männerna, som saken på gäller, stå för Herranom framför Presterna och domarena, som på den tiden äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Och domarena skola väl ransakat. Och om det falska vittnet hafver burit falskt vittnesbörd emot sin broder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Så skolen I göra honom, såsom han hade aktat göra sinom broder; på det att du skall skilja den onda ifrå dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Och andre skola det höra och rädas, och icke mer taga sig före sådana ondt stycke göra ibland dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ditt öga skall icke skona honom: själ för själ, öga för öga, tand för tand, hand för hand, fot för fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'När du drager till örlig emot dina fiendar, och får se hästar och vagnar, dess folks som är större än du, så frukta dig intet för dem; ty Herren din Gud, som dig utur Egypti land fört hafver, han är med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'När I nu kommen till strids, så skall Presten träda fram, och tala med folkena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Och säga till dem: Israel, hör härtill; I gån i dag i stridena emot edra fiendar. Edart hjerta vare icke blödigt; frukter eder intet, bäfver intet, och grufver eder intet för dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Ty Herren edar Gud går med eder, att han skall strida för eder mot edra fiendar, och hjelpa eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Men ämbetsmännerna skola tala med folket, och säga: Hvilken som ett nytt hus byggt hafver, och hafver icke ännu vigt det, han gånge sina färde, och blifve hemma; på det han icke skall blifva död i stridene, och en annar viger det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Hvilken som hafver plantat en vingård, och hafver icke ännu gjort honom menligan, han gånge sina färde, och blifve hemma; på det han icke blifver död i stridene, och en annan gör honom menligan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Hvilken sig en hustru trolofvat hafver, och hafver icke ännu hemtat henne hem, den gånge sina färde, och blifve hemma; att han icke dör i stridene, och en annar hemtar henne hem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Och ämbetsmännerna skola ytterligare tala med folket, och säga: Hvilken som rädder är, och förskräckt hjerta hafver, han gånge sina färde, och blifve hemma; på det han ock icke skall göra sina bröders hjerta förskräckt, såsom hans hjerta är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Och när ämbetsmännerna uttalat hafva med folkena, så skola de skicka höfvitsmännerna för folket främst i spetsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'När du drager för en stad, till att bestrida honom, så skall du först bjuda dem frid till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Svara de dig fridliga, och låta upp för dig, så skall allt det folk, som derinne är, vara dig skattskyldigt och underdånigt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Men vilja de icke fridliga handla med dig, och vilja örliga med dig, så belägg dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Och när Herren din Gud gifver dem dig i händer, så skall du slå allt mankön, som derinne är, med svärdsegg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Utan qvinnfolk, barn och boskap, och allt det i staden är, och allt rofvet skall du byta emellan dig, och skall äta af dina fiendars byte, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Alltså skall du göra med alla städer, som fast långt ifrå dig ligga, och icke äro af desso folks städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Men i desso folks städer, som Herren din Gud dig till arf gifva skall, skall du intet låta lefva det som anda hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Utan skall gifva det tillspillo, nämliga de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer, såsom Herren din Gud dig budit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'På det att de icke skola lära eder göra all den styggelse, som de göra deras gudar, och I synden emot Herran edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Om du måste länge ligga för en stad, emot hvilken du strider, till att intagan, så skall du icke förderfva trän, så att du låter yxena komma på dem; förty du kan äta deraf, derföre skall du icke afhugga dem. Är det dock ett trä på markene, och icke menniska, och kan icke komma i bålverk emot dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Men de trä, som du vetst att man icke äter deraf, dem skall du förderfva och afhugga, och gör bålverk emot staden som med dig örligar, tilldess du honom öfvermägtig varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Om någon dräpen man finnes i landena, som Herren din Gud dig gifva skall till att intaga, och ligger på markene, och man icke vet ho honom dräpit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Så skola dine äldste och domare gå der ut, och mäla ifrå den dräpna, intill de städer, som deromkring ligga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Hvilken staden, som der näst är, hans äldste skola taga af boskapenom ena unga ko, der man intet med arbetat hafver, och den intet ok hafver dragit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Och de skola leda henne in på en stenogan dal, den intet hafver brukad varit, ej heller besådd, och der i dalen hugga henne halsen af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Så skola Presterna gå fram, Levi söner, ty Herren din Gud hafver utvalt dem, att de skola tjena honom, och lofva Herrans Namn, och efter deras mun skola alla saker och all slags mål handlad varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Och alle äldste af den staden skola gå fram till den dräpna, och två sina händer öfver den unga kon, som i dalenom halshuggen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Och skola svara och säga: Våra händer hafva detta blodet icke utgjutit; hafva ej heller vår ögon sett det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Var nådelig dino folke Israel, som du, Herre, förlossat hafver; lägg icke detta oskyldiga blodet på ditt folk Israel. Så skola de vara försonade för det blodet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Alltså skall du lägga ifrå dig oskyldigt blod, att du skall göra det rätt är för Herrans ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'När du drager i strid emot dina fiendar, och Herren din Gud gifver dem i dina händer, att du förer dem fångna bort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Och du ser ibland de fångar en dägelig qvinno, och dig faller lust till henne, att du måtte taga henne till hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Så för henne i ditt hus, och låt raka henne håret af, och omskära hennes naglar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Och lägga de kläder af, der hon uti fången var, och låt henne sitta i dino huse, och gråta i en månad sin fader och sina moder; sedan sof när henne, och tag henne till äkta, och låt henne vara din hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Om du sedan icke hafver lust till henne, så skall du låta henne fara hvart hon vill, och icke sälja henne för penningar, eller försätta henne; derföre, att du hafver förnedrat henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Om någor hafver två hustrur, ena som han kär hafver, och ena som han hatar, och de föda honom barn, både den kära och den okära, så att det förstfödda är de okäres;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Och tiden kommer, att han skall sinom barnom utskifta arfvet, så kan han icke göra dess käres son till förstfödda son, för den okäres förstfödda son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Utan han skall bekänna den okäres son för förstfödda sonen, så att han gifver honom dubbelt af allt det på färde är; förty den samme är hans första kraft, och honom hörer förstfödslorätten till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Om någor hafver en sjelfsvörding och ohörsamman son, som faders och moders röst icke lyder, och när de tukta honom, lyder han dem intet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Så skola hans fader och moder taga honom fatt, och hafva honom fram för de äldsta i staden, och till porten åt samma rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Och säga till de äldsta i staden: Denne vår son är en sjelfsvörding och ohörsam, och lyder intet vara röst, och är en fråssare och drinkare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Så skall allt folket i staden stena honom ihjäl; och alltså skall du skilja den onda ifrå dig, att hela Israel skall det höra och rädas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'När någor hafver bedrifvit en synd, den döden värd är, och varder så dödad, att man hängre honom upp i trä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Si skall hans lekamen icke blifva på trät öfver nattena; utan I skolen begrafva honom på den samma dagen; ty förbannad är den för Gud, som hängder är; på det att du icke skall orena ditt land, som Herren din Gud gifver dig till arfs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'När du dins broders oxa eller får ser vilsefara, så skall du icke draga dig derifrån; utan skall drifva dem till din broder igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Om din broder icke bor när, och du känner honom icke, så skall du taga dem in uti ditt hus, att de blifva när dig, tilldess din broder söker efter dem, och då får du honom dem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Sammalunda skall du göra med hans åsna, med hans kläde, och med allt det som tappadt är, det din broder mist hafver, och du finner det; drag dig icke derifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Om du ser dins broders åsna eller oxa falla på vägenom, så skall du icke draga dig derifrån; utan skall hjelpa honom upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'En qvinna skall icke bära mans tyg, och en man skall icke draga qvinnokläder uppå; ty den som det gör, är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Om du råkar på vägen ett foglabo, på eno trä eller på jordene, med ungar eller med ägg, och modren sitter på ungarna eller på äggen, så skall du icke taga modren med ungarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Utan skall låta modren flyga, och taga ungarna; att dig må gå väl, och du må länge lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'När du bygger ett nytt hus, så gör såsom en värn ofvanomkring på taket, att du icke indrager blod på ditt hus, om någon faller deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du skall icke så din vingård med mångahanda, att du icke helgar till fyllelse sådana säd, som du sått hafver ibland vingårdsens frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du skall icke plöja tillhopa med en oxa och med en åsna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du skall icke utikläda dig en klädning, som af ull och lin tillsammans kommen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Du skall göra dig klutar i fyra hörnen på din mantel, som du hafver på dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Om någor tager ena hustru, och, sedan han henne belägrat hafver, får ledo till henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Och kastar henne något slemt före, och förer henne ett rykte uppå, och säger: Denna qvinnona hafver jag tagit, och när jag ingick till henne, fann jag att hon icke var jungfru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Så skola fader och moder åt qvinnone taga henne, och bära, fram qvinnones jungfruskap inför de äldsta i stadenom, som i porten sitta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Och qvinnones fader skall säga till de äldsta: Jag hafver gifvit denna mannenom mina dotter till hustru; nu är han henne vorden hätsk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Och kastar henne skamlig ting före, och säger: Jag hafver icke funnit dina dotter jungfru; detta är mina dotters jungfruskap. Och de skola utbreda klädet för de äldsta i stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Så skola de äldste i stadenom taga mannen och näpsa honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Och sakfälla honom till hundrade siklar silfver, och gifva dem qvinnones fader, derföre att han hafver beryktat ena jungfru i Israel; och han skall hafva henne till hustru, så att han icke skall öfvergifva henne i alla sina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Är det ock sant, att qvinnan icke är funnen jungfru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Så skall man föra henne ut för hennes faders husdörr, och folket i staden skola stena henne till döds, derföre att hon hafver bedrifvit en galenskap i Israel, och hafver bolat i hennes faders hus; och skall bortkasta det onda ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Om någor varder befunnen, att han ligger när en hustru, som en äkta man hafver, så skola de både dräpas, mannen och qvinnan, som han när legat hafver; och skall taga bort det onda af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Om en piga är enom manne trolofvad, och någor kommer i färd med henne i stadenom, och ligger när henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Så skall du föra dem båda ut till stadsporten, och skall stena dem båda till döds; pigona fördenskull, att hon icke ropade, efter hon var i stadenom; mannen fördenskull, att han sins nästas hustru skämt hafver; och skall kasta det onda bort ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Om någor finner en förlofvad pigo på markene, och tager henne fatt, och ligger när henne; så skall mannen allena dräpas, som låg när henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Och pigone skall du intet göra; ty hon hafver ingen synd gjort, som döden värd är; utan lika som någor hofve sig upp emot sin nästa, och sloge hans själ ihjäl, så är detta ock;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Ty han fann henne på markene, och den förlofvade pigan ropade, och ingen var som henne halp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Om någor kommer till en jungfru som intet trolofvad är, och får henne fatt och ligger när henne, och det varder funnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Så skall han, som när henne låg, gifva hennes fader femtio siklar silfver, och skall hafva henne till hustru, derföre att han hafver förnedrat henne; han må icke öfvergifva henne i hans lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ingen skall taga sins faders hustru, och icke upptäcka sins faders täckelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Ingen förbråken eller snöpt skall komma in i Herrans församling.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Skall ock ingen skökoson komma i Herrans församling, ja ock efter tionde led; utan skall platt intet komma i Herrans församling.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'De Ammoniter och Moabiter skola icke komma in i Herrans församling; ja ock efter tionde led; aldrig skola de komma in i Herrans församling;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Derföre, att de icke ville möta dig med bröd och vatten på vägen, då I drogen utur Egypten; och dertill lejde emot eder Bileam, Beors son, den spåmannen utaf Mesopotamien, att han skulle förbanna dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Men Herren din Gud ville icke höra Bileam; och Herren din Gud förvände dig den förbannelsen uti välsignelse; derföre, att Herren din Gud hade dig kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Du skall dem hvarken godt eller äro bevisa i alla dina lifsdagar evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomeen skall du icke för styggelse hålla; ty han är din broder. Egyptien skall du ej heller hålla för styggelse; ty du hafver varit en främling i hans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'De barn, som af dem födde varda i tredje led, de måga komma in uti Herrans församling.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'När du utdrager utu lägret emot dina fiendar, så tag dig vara för allt ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Är någor ibland dig, som icke är ren, att honom om natten något vederfaret är, han skall gå ut för lägret, och icke igen inkomma;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Förra än han mot aftonen tvår sig i vatten; och när solen nedergången är, skall han åter komma i lägret igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Utanför lägret skall du hafva en plats, der du ut uppå går till dina tarfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Och skall hafva en staka vid bältet, och när du dig derute sätta vill, skall du grafva dermed; och när du sutit hafver, skall du med mullene öfverskyla det af dig gånget är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Ty Herren din Gud vandrar i dino lägre, att han skall frälsa dig, och gifva dina fiendar för dig; derföre skall ditt lägre vara heligt, att ingen skam skall sedd vara ibland dig, och han vänder sig ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Du skall icke igen antvarda husbondanom tjenaren, som ifrå honom flyr till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Han skall blifva när dig på det rum, som honom täckes i någon af dina portar, sig till godo, och skall icke bedröfva honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ingen sköka skall vara ibland Israels döttrar, och ingen bolare ibland Israels söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Du skall icke bära skökolön eller hundapenningar uti Herrans dins Guds hus, af någrahanda löfte; ty både äro Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du skall icke ockra på dinom broder, antingen med penningar eller fetalia, eller med någon ting, der man med ockra kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'På dem främmande må du ockra, men icke på dinom broder; på det Herren din Gud skall välsigna dig i allt det du företager i landena, dit du kommer till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'När du gör Herranom dinom Gud ett löfte, så skall du icke fördröja att hålla det; ty Herren din Gud varder det utkräfvandes af dig; och det blifver dig räknadt till synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Om du intet löfte lofvar, så är det dig ingen synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Hvad af dina läppar utgånget är, det skall du hålla, och göra derefter, såsom du Herranom dinom Gud med fri vilja lofvat hafver, det du med dinom mun talat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'När du går i dins nästas vingård, så må du äta af vinbären så mycket dig täckes, tilldess du blifver mätt; men du skall intet taga med dig i dino kärile.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'När du går i dins nästas säd, så må du afplocka ax; men med lian skall du icke gå dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Om någor tager sig hustru, och äktar henne, och hon icke finner ynnest för hans ögon, för någon olusts skull, så skall han skrifva ett skiljobref, och få henne i handena, och låta henne utu sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'När hon utu hans hus gången är, och går till och blifver ens annars mans hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Och den samme andre mannen varder henne ock ogunstig, och skrifver ett skiljobref och får henne i handena, och låter henne utu sitt hus; eller om den samme andre mannen dör, som henne till hustru tog;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Så kan hennes förste man, som henne utdref, icke taga henne igen, att hon blifver hans hustru, efter det att hon är oren; ty det är en styggelse för Herranom; på det att du icke skall komma landet i synd, som Herren din Gud dig till arfs gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Om någor hafver nyliga tagit sig hustru, han skall icke draga ut i härfärd, och man skall intet lägga honom uppå; han skall vara fri i sino huse ett år igenom, att han må vara glad med sine hustru, som han tagit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Du skall intet till pant taga understenen och öfverstenen i qvarnene; ty han hafver satt dig själena till pant.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Om någor varder funnen den som stjäl ena själ utaf sina bröder utaf Israels barnom, och försätter eller säljer henne, den tjufven skall dräpas; att du skiljer det onda ifrå dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Tag dig vara för den plågon spitelskona, att du med flit håller och gör allt det som Presterna Leviterna lära dig, och jag dem budit hafver; det skolen I hålla, och göra derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Kom ihåg hvad Herren din Gud gjorde med MirJam på vägen om, då I drogen utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Om du något borgar dinom nästa, så skall du icke gå i hans hus, och taga honom en pant af;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Utan du skall stå utanföre, och den som du borgat hafver, skall bära sin pant ut till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Är han nödställd, så skall du icke gå och lägga dig sofva med hans pant;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Utan skall gifva honom hans pant igen, när solen nedergår, att han må sofva i sin kläder, och välsigna dig; det varder dig räknadt för Herranom dinom Gud till rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du skall icke förhålla lönen för den som torftig och fattig är ibland dina bröder; eller för främlingenom, som i dino lande eller i dina portar är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Utan skall gifva honom samma dagen sin lön, att solen dermed icke nedergår, efter han nödställd är, och dermed uppehåller sina själ; på det han icke skall ropa till Herran öfver dig, och det varder dig till synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Fäderna skola icke dö för barnen, ej eller barnen för fäderna; utan hvar och en skall dö för sina synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du skall icke böja främlingens, eller dens faderlösas rätt; och skall icke taga enkone hennes kläder af till pant.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ty du skall ihågkomma, att du hafver varit en träl i Egypten, och Herren din Gud hafver dig dädan löst; derföre bjuder jag dig, att du detta gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'När du hafver bergat af dinom åker, och du en kärfva förgätit hafver på åkrenom, så skall du icke omvända och taga honom; utan han skall höra främlingenom, dem faderlösa och enkone till; på det att Herren din Gud skall välsigna dig i all din händers verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'När du afrist hafver af ditt oljoträ, så skall du icke sedan på nytt afrista; det skall höra främlingenom, dem faderlösa och enkone till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'När du din vingård afbergat hafver, så skall du icke sedan på nytt hemta; det skall höra främlingenom, dem faderlösa och enkone till;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Och skall ihågkomma, att du hafver varit en träl i Egypti land; derföre bjuder jag dig, att du detta gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Om en träta är emellan män, så skall man hafva dem fram för rätten, och döma emellan dem, och gifva dem rättfärdiga rätt, och den ogudaktiga fördöma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Och om den ogudaktige hafver förtjent hugg, skall domaren bjuda honom falla neder, och de skola inför honom slå honom, efter det mått och tal, som missgerningen kräfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'När man honom fyratio slag gifvit hafver, skall man icke mer slå; på det, om man mer slår, han icke skall förmycket slagen varda, och din broder styggelig varder för din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du skall icke binda munnen till på oxanom, som tröskar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'När bröder bo tillhopa, och en dör utan barn, så skall dens dödas hustru icke taga någon främmande man utantill; utan hennes svåger skall ingå till henne, och taga henne till hustru, och befrynda henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Och den förste sonen, som hon föder, skall nämnas efter hans döda broder; att hans namn icke nederlägges i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Om mannenom icke täckes, att han tager sina svägersko, så skall hans svägerska uppgå till porten för de äldsta, och säga: Min svåger nekar sig vilja uppväcka sinom broder namn i Israel, och vill icke hafva mig till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Så skola de äldste i stadenom låta kalla honom, och tala med honom. Om han då står, och säger: Mig faller icke i sinnet att taga henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Så skall hans svägerska träda till honom inför de äldsta, och draga honom en sko af hans fötter, och spotta uppå honom, och skall svara och säga: Så skall man göra hvarjom och enom, som sins broders hus icke uppbygga vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Och hans namn skall heta i Israel: Dens barföttes hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Om två män träta tillhopa, och ensderas hustru löper till, att hon vill undsätta sin man ifrå hans hand som honom slår, och räcker sina hand ut, och fatter honom om hans hemlig ting;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Så skall du hugga henne handena af, och ditt öga skall icke skona henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du skall icke hafva tveggehanda vigt i dinom säck, större och mindre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Och i dino huse skall icke vara tveggehanda skäppa, större och mindre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Du skall hafva ena fulla och rätta vigt, och ena fulla och rätta skäppo; på det att du skall länge lefva på landena, som Herren din Gud dig gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Ty den som detta gör, han är Herranom dinom Gud en styggelse; såsom ock alle de som illa göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Kom ihåg hvad de Amalekiter gjorde dig uppå vägenom, då I drogen utur Egypten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Huru de kommo emot dig på vägenom, och slogo dina eftersta, alla de svaga som efterst drogo, när du mödd och trött vast, och de fruktade icke Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'När nu Herren din Gud låter dig komma till ro ifrån alla dina fiendar omkring dig i landena, som Herren din Gud dig gifver till arfs till att intaga, så skall du utskrapa de Amalekiters åminnelse under himmelen; det förgät icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'När du kommer in i landet, som Herren din Gud dig till arfs gifva skall, och du tager det in, och bor der;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Så skall du taga allahanda landsens första frukter, som af jordene komma, som Herren din Gud dig gifver, och skall lägga dem uti en korg, och gå bort på det rum, som Herren din Gud utväljandes varder, att hans Namn der bo skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Och skall gå till Presten, som på den tiden är, och säga till honom: Jag förkunnar på denna dag Herranom dinom Gud, att jag är kommen in uti det land, som Herren vårom fädrom svorit hafver till att gifva oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Och Presten skall taga korgen utu dine hand, och sätta honom ned för Herrans dins Guds altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Då skall du svara, och säga för Herranom dinom Gud: De Syrer ville förgöra min fader, han drog neder i Egypten, och var der en främling med fögo folk; och vardt der ett stort, starkt och mycket folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Men de Egyptier handlade illa med oss, och tvingade oss, och lade en hård träldom på oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Då ropade vi till Herran våra fäders Gud, och Herren hörde vårt rop, och såg vårt elände, ångest och nöd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Och Herren förde oss utur Egypten med väldiga hand och uträcktom arm, och med stor förfärelse genom tecken och under;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Och förde oss på detta rummet, och gaf oss detta landet, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Och derföre bär jag nu här fram landsens första frukt, som du, Herre, mig gifvit hafver. Och så skall du låta det der för Herranom dinom Gud, och tillbedja för Herranom dinom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Och vara glad öfver allt det goda, som Herren din Gud hafver gifvit dig, och dino huse, du och Leviten, och främlingen som när dig är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'När du hafver tillhopasamlat allan tionden af din årsväxt i tredje årena, hvilket är ett tiondeår, så skall du gifva Levitenom, främlingenom, dem faderlösa och enkone, att de måga äta i dinom port, och varda mätte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Och skall säga för Herranom dinom Gud: Jag hafver här framburit det som helgadt är af mino huse, och hafver gifvit det Levitenom, främlingenom, dem faderlösa och enkone, efter allt ditt bud, som du mig budit hafver; jag hafver icke gått utöfver ditt bud, eller förgätit det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Jag hafver icke ätit deraf i mine sorg; jag hafver intet tagit deraf i orenlighet; jag hafver intet deraf gifvit till de döda; jag hafver varit Herrans mins Guds röst hörig, och hafver gjort allt det du mig budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Se här neder af dine helga boning af himmelen, och välsigna ditt folk Israel, och landet som du oss gifvit hafver, såsom du våra fäder svorit hafver, ett land der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'I dag hafver Herren din Gud budit dig, att du efter all dessa bud och rätter göra skall, så att du håller dem, och gör derefter af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Herranom hafver du det tillsagt i denna dag, att han skall vara din Gud, och du skall vandra i hans vägar, och hålla hans lag, bud och rätter, och lyda hans röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Herren hafver dig tillsagt i dag, att du skall vara hans eget folk, såsom han dig sagt hafver; att du skall hålla all hans bud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Och han skall göra dig det högsta, och du varder prisad, lofvad och ärad, öfver allt folk som han gjort hafver; på det du skall vara Herranom dinom Gud ett heligt folk, såsom han sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Och Mose, samt med de äldsta i Israel, böd folkena, och sade: Behåller all de bud, som jag bjuder eder i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Och på den tiden, när I öfver Jordan dragen in i landet, som Herren din Gud dig gifvandes varder, skall du uppresa stora stenar, och plåstra dem med kalk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Och derpå skrifva all dessa lagsens ord, när du deröfver kommer; på det du skall komma i landet, som Herren din Gud dig gifva skall, ett land der mjölk och hannog uti flyter; såsom Herren dina fäders Gud dig sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'När I nu gån öfver Jordan, så skolen I sådana stenar uppresa, om hvilka jag eder i dag bjuder, på det berget Ebal, och plåstra dem med kalk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Och skall dersammastäds uppbygga Herranom dinom Gud ett altare af sten, der intet jern kommer vid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Af helom stenom skall du bygga det altaret Herranom dinom Gud, och offra deruppå bränneoffer Herranom dinom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Och skall offra tackoffer, och dersammastäds äta, och vara glad för Herranom dinom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Och skall skrifva på stenarna all dessa lagsens ord, klarliga och ljusliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Och Mose, samt med Presterna Leviterna, talade med hela Israel, och sade: Märk och hör till, Israel; på denna dagen äst du vorden Herrans dins Guds folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Att du skall lydig vara Herrans dins Guds röst, och göra efter hans bud och rätter, som jag bjuder dig i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Och Mose böd folkena på samma dagen, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Desse skola stå på det berget Grisim, till att välsigna folket, när I öfver Jordan gångne ären: Simeon, Levi, Juda, Isaschar, Joseph och BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Och desse skola stå på det berget Ebal, till att förbanna: Ruben, Gad, Asser, Sebulon, Dan och Naphthali.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Och Leviterna skola begynna, och säga till hvar man af Israel med klara röst:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Förbannad vare den som gör en afgud eller gjutet beläte, Herrans styggelse; ett verk, som konstnärers händer gjort hafva, och sätter det hemliga; och allt folket skall svara och säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Förbannad vare den som bannar sin fader eller moder; och allt folket skall svara och säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Förbannad vare den som flyttar sins nästas råmärke; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Förbannad vare den som låter en blindan fara vill på vägenom; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Förbannad vare den som böjer främlingens, dens faderlösas och enkones rätt; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Förbannad vare den som ligger när sins faders hustru, att han upptäcker sins faders täckelse; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Förbannad vare den som beligger någon fänad; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Förbannad vare den som ligger när sina syster, den hans faders eller moders dotter är; och allt folket skall Säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Förbannad vare den som ligger när sina svära; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Förbannad vare den som slår sin nästa hemliga; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Förbannad vare den som tager mutor, att han ens oskyldigs blods själ slå skall; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Förbannad vare den som icke fullkomnar all denna lagsens ord, så att han gör derefter; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Och om du Herrans dins Guds röst lydig äst, att du behåller och gör all hans bud, som jag bjuder dig i dag; så skall Herren din Gud göra dig högst öfver allt folk på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Och all denna välsignelsen skola komma öfver dig, och drabba på dig, derföre att du hafver varit Herrans dins Guds röst hörig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Välsignad skall du vara uti stadenom, välsignad på åkrenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Välsignad skall vara dins lifs frukt, dins lands frukt, och frukten af dinom boskap, frukten af ditt fä, frukten af din får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Välsignad varder din korg, och dina öfverlefvor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Välsignad skall du vara, när du ingår; välsignad, när du utgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Och Herren skall dina fiendar, som sig emot dig resa, låta falla för dig; på en väg skola de komma ut emot dig, och på sju vägar fly för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Herren skall bjuda välsignelsen, att hon är med dig i ditt visthus, och i allt det du företager; och skall välsigna dig i landena, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Herren skall upprätta dig sig till ett heligt folk, såsom han dig svorit hafver; derföre, att du Herrans dins Guds bud håller, och vandrar i hans vägar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Att all folk på jordene skola se, att du nämnd är efter Herrans Namn; och skola frukta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Och Herren skall göra, att du skall öfverflöda i alla ägodelar; i dine lifs frukt, i dins boskaps frukt, i dins åkers frukt, på landena som Herren dina fäder svorit hafver dig till att gifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Och Herren skall öppna dig sina goda håfvor, himmelen, att han skall gifva dino lande regn i sinom tid, och att han skall välsigna all dina händers verk; och du skall låna mycket folk, och du skall taga till låns af ingom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Och Herren skall göra dig till hufvud, och icke till stjert, och skall alltid sväfva ofvanuppå, och icke underligga; derföre, att du äst lydig Herrans dins Guds bud, som jag dig bjuder i denna dag, till att hålla och göra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Och hafver icke vikit ifrå något det ord, som jag bjuder dig i dag, hvarken på den högra sidon, eller på den venstra, så att du efterföljde andra gudar, till att tjena dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Om du ock icke lyder Herrans dins Guds röst, så att du håller och gör all hans bud och rätter, som jag bjuder dig i dag, så skola all denna förbannelsen komma öfver dig, och drabba på dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Förbannad skall du vara i stadenom; förbannad på åkrenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Förbannad skall vara din korg, och dina öfverlefvor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Förbannad skall vara dins lifs frukt, dins lands frukt, frukten af ditt fä, frukten af din får;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Förbannad skall du vara, när du ingår: förbannad, när du utgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Herren skall sända ibland dig armod, ofrid och oråd, öfver allt det du tager dig före att göra, tilldess han förgör dig, och förderfvar dig snarliga, för dina onda gerningars skull, att du mig öfvergifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Herren skall låta pestilentie låda vid dig, tilldess han gör ända med dig på landena, dit du kom mer till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Herren skall slå dig med svullnad, skälfvo, hetta, bränno, torrhet och blekhet; och skall förfölja dig, tilldess han förgör dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Himmelen, som öfver ditt hufvud är, skall vara som koppar; och jorden under dig såsom jern.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Herren skall gifva dino lande stoft och asko för regn af himmelen öfver dig, tilldess han förgör dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Herren skall låta slå dig för dina fiendar; på en väg skall du draga ut till dem, och på sju vägar skall du fly ifrå dem; och skall varda förströdd kringom all rike på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Din lekamen skall till mat vara allom himmelens foglom, och allom vilddjurom på jordene, och ingen skall vara, som dem afdrifver,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Herren skall slå dig med Egyptes böld, med fikbölder, med skabb och klåda, så att du icke skall kunna varda hel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Herren skall slå dig med ursinnighet, blindhet, och hjertans rasande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Och du skall famla om middagen, såsom en blinder famlar i mörkret, och skall ingen lycko hafva på dina vägar; och skall lida våld och orätt så länge du lefver, och ingen skall hjelpa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Du skall trolofva dig hustru, men en annar skall sofva när henne; du skall bygga dig hus, men en annar skall bo deruti; du skall plantera vingård, men du skall icke bergan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Din oxe skall för din ögon slagtad varda, men du skall intet få äta af honom; din åsne skall för din ögon med våld tagen varda, och skall dig intet igengifven varda; din får skola varda gifne dinom fiendom, och ingen skall hjelpa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Dine söner och dina döttrar skola andro folke gifne varda, så att din ögon skola se deruppå, och uppgifvas öfver dem dagliga; och ingen starkhet skall vara i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Frukten af dino lande, och allt ditt arbete skall ett folk förtära, som du intet känner; och du skall orätt lida, och förtryckt varda i alla dina dagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Och skall ursinnig blifva för sådana syn, som din ögon se skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Herren skall slå dig med en ond böld på knän, och uppå benkalfvana, att du icke skall kunna helas ifrå fotbjellet intill hjessan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Herren skall drifva dig och din Konung, som du öfver dig satt hafver, till ett folk, som du intet känner eller dina fäder; och der skall du tjena andra gudar, stockar och stenar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Och skall varda till en grufvelse, och till ett ordspråk och gabberi ibland all folk, dit Herren dig drifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Du skall mycken säd föra ut på markena, och litet införa; ty gräshoppor skola det uppäta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Du skall plantera och bruka vingård, men intet vinet dricka eller hemta; ty matkar skola förtärat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Du skall hafva oljoträ i allom dinom landsändom, men du skall icke smörja dig med oljone; ty ditt oljoträ skall uppryckt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Söner och döttrar skall du föda, och dock intet hafva dem; ty de skola varda bortförde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'All din trä och dins lands frukt skall ohyra förtära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Främlingen, som när dig är, skall stiga öfver dig, och alltid blifva öfverst; men du skall stiga neder, och alltid ligga under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Han skall låna dig, men du skall intet låna honom: han skall vara hufvudet, och du skall vara stjerten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Och all denna förbannelsen skola komma öfver dig, och förfölja dig, och drabba uppå dig, tilldess du blifver omintet; derföre, att du Herrans dins Guds röst icke hört hafver, att du måtte hållit hans bud och rätter, som han dig budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Derföre skola tecken och under varda på dig och dine säd till evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Att du icke hafver tjent Herranom dinom Gud med gladt och lustigt hjerta, då du allahanda nog hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Och du skall tjena dinom fienda, som Herren dig tillskickandes varder, i hunger och törst, i nakenhet och allahanda nöd; och han skall lägga på din hals ett jernok, tilldess han förgör dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herren skall låta folk komma på dig fjerranefter ifrå verldenes ända, såsom en örn flyger, hvilkets mål du icke förstå kan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Ett skamlöst folk, det icke skall hafva försyn för dens gamlas person, ej heller mildt är för den unga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Och skall förtära fruktena af din boskap, och fruktena af ditt land, tilldess han förgör dig; och skall intet låta dig qvart blifva, i korn, vin, oljo, i frukt af fä eller får, tilldess han gör dig omintet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Och skall tränga dig i alla dina portar, tilldess han nederlägger dina höga och fasta murar, der du på förlåter dig i allo dino lande; och du skall trängd varda i alla dina portar, i hela dino lande, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Du skall äta fruktena af ditt eget lif; dins sons och dine dotters kött, som Herren din Gud dig gifvit hafver, i den ångest och nöd, som din fiende dig uti tvinga skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Så att en man, som tillförene kräsliga och i mycken vällust ibland eder lefvat hafver, skall missunna sinom broder, och hustrune som i hans famn är, och sonenom som ännu igenlefder är af hans söner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Att gifva någromdera af sins sons kött, der han af äter; efter han nu intet mer hafver af alla sina ägodelar, i den ångest och nöd, som din fiende dig med tvinga skall uti alla dina portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'En qvinna ibland eder, som tillförene kräseliga och i vällust lefvat hafver, så att hon icke hafver försökt sätta sin fot på jordena för kräselighets och vällusts skull, hon skall icke unna mannenom som i hennes famn är, och sinom son, och sine dotter,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Efterbördena, som emellan hennes ben utgången är; ja, ock sina söner, som hon födft hafver; förty de skola äta dem hemliga, för allahanda brists skull, i den ångest och nöd, med hvilko din fiende dig tvinga skall i dina portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Om du icke håller och gör all dessa lagsens ord, som i denna bokene skrifne äro, så att du fruktar detta härliga och förskräckeliga Namnet, Herran din Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Så skall Herren underliga hafva sig med dig, med plågo på dig och dina säd, med stora och långsamma plågor, med onda och långsamma krankheter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Och skall vända till dig alla de Egyptiska sjukdomar, der du rädes före; och de skola låda vid dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Dertill alla krankheter, och alla plågor, som icke skrifne äro i denna lagbok, skall Herren låta komma öfver dig, tilldess att han förgör dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Och fögo folk skall öfverblifva af eder, som tillförene voren såsom stjernorna på himmelen, för myckenhets skull; derföre, att du icke lydt hafver Herrans dins Guds röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Och såsom Herren tillförene fröjdade sig öfver eder, att han gjorde eder godt, och förökade eder; så skall Herren fröjda sig öfver eder, att han förderfvar eder, och omintetgör; och I varden förstörde ifrå landena, der du nu indrager till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Ty Herren skall förskingra eder ibland all folk, ifrå den ena verldenes ända till den andra; och der skall du tjena andra gudar, som du intet känner, eller dine fader, stock och sten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Och ibland de folk skall du intet visst hemman hafva, och din fotbjelle skola ingen hvilo få; ty Herren skall gifva dig der ett bäfvande hjerta, och vanmägtig ögon, och en förvissnada själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Så att ditt lif skall vara hängandes för dig; dag och natt skall du rädas, och skall icke vara viss på ditt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Om morgonen skall du säga: Ack! det jag måtte lefva till aftonen; och om aftonen skall du säga: Ack! det jag måtte lefva till morgonen, för dins hjertas stora räddhåga, som dig förskräcka skall, och för det som du med din ögon se skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Och Herren skall föra dig skeppom full åter in uti Egypten på den vägen, om hvilken jag sade: Du skall icke mer se honom; och skolen varda sålde edrom fiendom till trälar och trälinnor, och der skall ingen vara, som köpa vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Desse äro förbundsens ord, som Herren böd Mose att göra med Israels barnom, uti de Moabiters land, annan gång, sedan han det samma med dem gjort hade i Horeb.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Och Mose kallade hela Israel, och sade till dem: I hafven sett allt det Herren för edor ögon gjort hafver i Egypten, Pharao, med alla hans tjenare, och hela hans land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'De stora frestelser, som din ögon sett hafva; och det var stor tecken och under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Och Herren hafver ännu intill denna dag icke gifvit dig ett hjerta, som förståndigt vore; ögon, som se kunde, och öron, som höra kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Han hafver låtit eder vandra i öknene i fyratio år; edor kläder äro icke förslitne vordne på eder, och dina skor äro icke föråldrade på dina fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'I åten intet bröd, och intet vin drucken, eller starka drycker, på det att du skulle veta, att jag är Herren edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Och då I kommen på detta rummet, drog ut Sihon, Konungen i Hesbon, och Og, Konungen i Basan, till att strida med oss, och vi sloge dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Och toge deras land in, och gåfvom det de Rubeniter och Gaditer, och den halfve slägtene af de Manassiter till arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Så håller nu detta förbunds ord, och görer derefter, på det I skolen visliga handla i allt det I gören.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'I stån alle i dag för Herranom edrom Gud; de öfverste i edra slägter, edre äldste, edre ämbetsmän, hvar och en i Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Edra barn, edra qvinnor, främlingen som i ditt lägre är, både din vedahuggare, och din vattudragare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Att du skall ingå uti Herrans dins Guds förbund, och i den ed som Herren din Gud med dig gör i dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'På det han skall i denna dag upprätta dig sig till folk; och han skall vara din Gud, såsom han dig sagt hafver, och såsom han dina fäder, Abraham, Isaac och Jacob, svorit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Ty jag gör icke detta förbundet och denna eden med eder allena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Utan både med eder, som i dag här ären, och stån här med oss för Herranom vårom Gud, och med dem som i dag här icke med oss äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Förty I veten huru vi bodde i Egypti land, och droge midt igenom Hedningarna, genom hvilka I foren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Och sågen deras styggelse, och deras afgudar, stock och sten, silfver och guld, som när dem var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Att tilläfventyrs icke någor är ibland eder, man eller qvinna, eller en slägt, eller ätt, som sitt hjerta i dag vändt hafver ifrå Herranom vårom Gud, så att han vill bortgå, och tjena dessa folks gudar, och varder tilläfventyrs en rot ibland eder, som galla och malört bär;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Och ändock han än hörer denna förbannelsens ord, välsignar han sig likaväl i sino hjerta, och säger: Det varder icke än så ondt; jag vill vandra såsom mitt hjerta täckes; och varda alltså de druckne med de törstiga förtappade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Då skall Herren icke vara honom nådelig; utan då skall Herrans vrede och nit hämnas öfver den mannen, och på honom skola all denna förbannelsen lägga sig, som i denna bokene skrifne äro; och Herren skall utskrapa hans namn under himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Och Herren skall afskilja honom till det ondt är, utur all Israels slägter, efter all förbundsens förbannelse, som i desso lagbok skrifne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Och så skall då edor afföda säga edor barn, som efter eder uppkomma, och de främmande, som fjerran långvägs komma, när de se detta landsens plågo, och de krankheter, som Herren dem med besvärat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Att han allt deras land med svafvel och salt förbränt hafver, så att det icke kan sådt varda, ej heller växer, ej heller någon ört uppgår, lika som Sodom, Gomorra, Adama och Zeboim omstörte äro, hvilka Herren i sine vrede och grymhet omstörte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Så skola all folk säga: Hvi hafver Herren så gjort desso landena? Hvad är denna hans stora grymma vrede?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Då skall man säga: Derföre, att de hafva gått ifrå Herrans deras fäders Guds förbund, som han med dem gjort hade, då han förde dem utur Egypti land,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Och de äro bortgångne, och hafva tjent andra gudar, och tillbedit dem; sådana gudar, som de intet kände, och dem de intet tillhörde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Derföre hafver Herrans vrede förgrymmat sig öfver detta land, så att han hafver låtit komma öfver dem all de förbannelser, som i denna bok skrifne stå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Och Herren hafver drifvit dem utu deras land med stora vrede, grymhet och ogunst, och kastat dem uti ett annat land, såsom det i denna dag befinnes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Herrans vår Guds hemlighet är uppenbarad oss och vårom barnom till evig tid, att vi all dessa lagsens ord göra skole.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'När nu allt detta kommer öfver dig, antingen välsignelsen eller förbannelsen, som jag dig föresatt hafver, och du begynner lägga på hjertat, huru du äst ibland Hedningar, dit Herren din Gud dig fördrifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Och du omvänder dig till Herran din Gud, så att du lyder hans röst, du och din barn, af allo hjerta, och af allo själ, i allt det som jag bjuder dig i denna dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Så skall Herren din Gud vända ditt fängelse, och förbarma sig öfver dig, och skall åter församla dig utur all folk, dit Herren din Gud dig förskingrat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Om du vore bortdrifven allt intill himmelens ända, så skall dock Herren din Gud församla dig dädan, och hemta dig dädan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Och Herren din Gud skall låta dig komma i det land, som dine fäder besutit hafva; och du skall det intaga, och han skall göra dig godt, och föröka dig öfver dina fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Och Herren din Gud skall omskära ditt hjerta, och dine säds hjerta, att du Herran din Gud älska skall af allo hjerta, och af allo själ; på det att du må lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Men denna förbannelsen skall Herren din Gud alla låta komma uppå dina fiendar, och uppå dem som dig hata och förfölja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Men du skall omvända dig, och lyda Herrans röst, att du gör all hans bud, som jag bjuder dig i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Och Herren din Gud skall gifva dig lycko i alla dina händers gerningar; i dins lifs frukt, i dins boskaps frukt, i dins lands frukt, att det kommer dig till godo; ty Herren skall vända sig, så att han skall fröjda sig öfver dig, dig till godo, såsom han sig öfver dina fäder fröjdat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Derföre, att du Herrans dins Guds röst lyder, till att hålla hans bud och rätter, som skrifne äro i desso lagbok; såframt du vänder dig till Herran din Gud af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Ty det budet, som jag bjuder dig i dag, är dig icke fördoldt, ej heller för fjerran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Ej heller i himmelen, så att du måtte säga: Ho vill fara oss upp i himmelen, och hemta oss det, att vi måge hörat och görat?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Det är icke heller på hinsidon hafvet, så att du måtte säga: Ho vill fara oss öfver hafvet, och hemta oss det, att vi måge hörat och görat?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Ty ordet är ganska hardt när dig, i dinom mun, och i dino hjerta, att du det göra må.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Si, jag hafver i dag satt dig före lifvet, och det goda; döden, och det onda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Det jag bjuder dig i dag, att du skall älska Herran din Gud, och vandra i hans vägar, och hålla hans bud, lag och rätter, och få lefva, och varda förökad; och Herren din Gud skall välsigna dig i landena, der du indrager till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Men vänder du ditt hjerta, och lyder icke, utan låter förföra dig, så att du tillbeder andra gudar, och tjenar dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Så förkunnar jag eder i dag, att I skolen förgås, och icke länge blifva i landena, der du indrager öfver Jordan, det att intaga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Jag tager i dag himmel och jord till vittne öfver eder, jag hafver satt eder före lifvet och döden, välsignelse och förbannelse, att du skall utvälja lifvet, och du och din säd mågen lefva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Att I skolen älska Herran edar Gud, och lyda hans röst, och hålla eder intill honom; ty det är ditt lif, och din långa ålder, att du må bo i landena, som Herren dina fäder, Abraham, Isaac och Jacob, svorit hafver dem att gifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Och Mose gick bort, och talade dessa orden med hela Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Och sade till dem: Jag är i dag hundrade och tjugu åra gammal; jag kan icke mer ut och in gå; dertill hafver Herren sagt till mig: Du skall icke gå öfver denna Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Herren din Gud skall sjelfver gå för dig; han skall sjelf förgöra dessa folk för dig, så att du skall taga dem in; Josua skall gå för dig deröfver, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Och Herren skall göra dem, såsom han gjort hafver Sihon och Og, de Amoreers konungar, och deras lande, hvilka han förgjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'När nu Herren gifver dem för eder, så skolen I göra dem efter all de bud, som jag eder budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Varer tröste, och vid godt mod; frukter eder intet, och grufver eder intet för dem; ty Herren din Gud skall sjelfver vandra med dig, och skall icke draga handena ifrå, ej heller förlåta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Och Mose kallade Josua, och sade till honom för hela Israels ögon: Var tröst, och vid godt mod; ty du skall föra detta folket i landet, som Herren deras fäder svorit hafver dem att gifva; och skall utskifta det emellan dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Men Herren, som sjelfver går för eder, han skall vara med dig, och icke draga handena ifrå, icke heller förlåta dig; frukta dig intet, och förskräck dig intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Och Mose skref denna lagen, och fick Presterna, Levi söner, som båro Herrans förbundsark, och allom Israels äldstom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Och böd dem, och sade: Ju efter sju år, då friåret är, på löfhyddohögtiden,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Då hela Israel kommer till att bete sig för Herranom dinom Gud, på det rum, som han utväljandes varder, skall du denna lagen låta utropa för hela Israel, för deras öron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Nämliga för folkens församling, både för män och qvinnor, barn, och dinom främling som i dina portar är; på det att de skola höra och lära, huru de skola frukta Herran sin Gud, och akta uppå, att de göra all denna lagsens ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Och att deras barn, som icke vetat, måga ock höra och lära, huru de skola frukta Herran edar Gud i alla edra lifsdagar, som I på landena lefven, dit I öfver Jordan ingån, till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Och Herren sade till Mose: Si, din dödstid är kommen; kalla Josua, och går in i vittnesbördsens tabernakel, att jag må gifva honom befallning. Mose gick åstad med Josua, och trädde in i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Och Herren syntes i tabernaklet uti en molnstod, och samma molnstod stod i dörrene på tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Och Herren sade till Mose: Si, du skall afsomna med dina fäder, och detta folket skall uppkomma, och skall löpa i horeri efter landsens främmande gudar, der de inkomma, och skola öfvergifva mig, och omintetgöra det förbund, som jag med dem gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Så skall min vrede förgrymma sig öfver dem på samma tiden, och jag skall öfvergifva dem, och fördölja mitt ansigte för dem, att de skola upptärde varda. Och när dem då mycken olycka och ångest öfverkommer, skola de säga: Hafver icke allt detta onda råkat på mig, efter Gud icke är med mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Men jag skall på den tiden förskyla mitt ansigte, för allt det ondas skull, som de gjort hafva, att de hafva vändt sig till andra gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Så skrifver eder nu denna visona, och lärer henne Israels barn; och sätter henne i deras mun, att den visan blifver mig ett vittne ibland Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Ty jag vill föra dem i landet, som jag deras fader svorit hafver, der mjölk och hannog uti flyter; och när de äta och varda mätte och fete, så varda de sig vändande till andra gudar, och tjena dem och förhäda mig, och låta mitt förbund fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Och när dem då mycken olycka och ångest påkommer, så skall denna visan vara dem för ett vittnesbörd, den de icke skola förgäta utu deras säds mun; ty jag vet deras tankar, som de nu allaredo med omgå, förra än jag förer dem i landet, som jag svorit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Så skref Mose denna visona på samma tiden, och lärde henne Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Och befallde Josua, Nuns sone, och sade: Var tröst och frimodig; förty du skall föra Israels barn i landet, som jag dem svorit hafver, och jag skall vara med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Då Mose hade all denna lagsens ord utskrifvit i en bok,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Böd han Leviterna, som Herrans vittnesbörds ark båro, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Tager denna lagsens bok, och lägger henne vid sidon på förbundsens ark, Herrans edars Guds; på det att han skall vara der till ett vittne emot dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Förty jag känner dina olydighet och halsstyfhet; si, medan jag ännu i dag lefver med eder, hafven I olydige varit emot Herranom; huru mycket mer efter min död?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Så låter nu tillhopakomma för mig alla de äldsta i edra slägter, och edra ämbetsmän, att jag må tala dessa orden för deras öron, och taga himmel och jord till vittne öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Ty jag vet, att I efter min död skolen förderfvat, och gå utaf vägenom, den jag eder budit hafver; så skall eder vederfaras olycka derefter, derföre, att I hafven illa gjort för Herrans ögon, och förtörnat honom genom edra händers gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Alltså talade Mose denna visones ord all ut, för hela Israels församlings öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Akter uppå, I himlar, jag vill tala; och i orden höre mins muns ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Min lära drype såsom regn, och mitt tal flyte såsom dagg; såsom regn uppå gräs, och såsom droppar uppå örter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Ty jag vill prisa Herrans Namn; gifvom vårom Gudi allena ärona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Han är en klippa; hans verk äro ostraffelig; ty allt det han gör, det är rätt. Trofast är Gud, och utan allt argt; rättvis och from är han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Den afvoga och onda slägten är honom ifråfallen; skamfläcker äro de, och icke hans barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Tackar du så Herranom dinom Gud, du galna och ovisa folk? Är han icke din Fader, och din Herre? Hafver han icke allena gjort och beredt dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Tänk uppå den förra tiden allt härtill, och betrakta hvad han gjort hafver med de gamla fäder; fråga din fader, han skall förkunnat dig; dina äldsta, och de skola sägat dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'När den Högste utskifte folken, och utströdde menniskors barn, då satte han landamäre till folken, efter Israels barnas tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Ty Herrans lott är hans folk; Jacob är snöret till hans arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Han fann honom i vildmarkene; uti torro öknene, der styggeligit är; han förde honom omkring, och gaf honom lag, och bevarade honom såsom sin ögnasten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Såsom en örn utförer sina ungar, och flyger öfver dem; så räckte han sina vingar ut, tog dem, och bar dem uppå sina vingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Herren allena ledde honom, och ingen främmande gud var med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Han lät honom fara högt uppe på jordene, och födde honom med åkrens frukt; och lät honom suga hannog utu hälleberget, och oljo utu hårda stenen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Smör af korna, och mjölk af fåren, samt med det feta af lamben, och fetesta vädrar, och bockar med feta njurar, och hvete; och lät honom dricka goda vindrufvos blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Och då han vardt fet och mätt, vardt han kåter; han är fet, tjock och stark vorden; och hafver öfvergifvit Gud, den honom gjort hade; sine helsos klippo aktade han ringa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Och rette honom genom främmande gudar till nit; genom styggelse förtörnade han honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'De offrade djeflom, och icke sinom Gud; dem gudom, som de intet kände; dem nyom, som icke tillförene varit hade, hvilka deras fäder intet dyrkat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Dina klippo, den dig födt hafver, den öfvergaf du, och förgät den Gud, som dig skapat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Och då Herren det såg, vardt han vreder öfver sina söner och döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Och han sade: Jag skall förskyla mitt ansigte för dem, och vill se hvad dem på sistone vederfaras kan; ty det är ett afvogt slägte, och sådana barn, der ingen tro uti är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'De hafva rett mig på det som icke är Gud; med deras afguderi hafva de förtörnat mig; och jag skall reta dem igen, på det som icke är folk; med ett galet folk skall jag förtörna dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Elden är upptänd i mine vrede, och skall brinna intill det nedersta helvetet; och skall förtära landet med sin växt, och skall uppbränna bergsgrunden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Jag skall samka olycko öfver dem; jag skall förskjuta alla mina pilar på dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'För hunger skola de försmäkta, och förtärde varda af skälfvo och ond sår; jag skall låta komma till dem vilddjurständer och grymma ormar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Utvärtes skall svärdet föröda dem, och invärtes förskräckelse; både dränger och pigor, den som dir med dem gråhårota.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Jag skall säga: Hvar äro de? Jag skall borttaga deras åminnelse ifrå menniskomen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Om jag icke skydde för fiendernas vrede, att deras fiender icke skola varda stolte, och måtte säga: Vår höga hand hafver allt detta gjort, och icke Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Ty det är ett folk, der intet råd uti är, och intet förstånd är i dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'O! att de vise vore, och de måtte besinna, hvad dem framdeles öfvergå skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Huru kommer det till, att en skall jaga tusende af dem, och två skola komma tiotusend på flyktena? Månn icke deras klippa hafva sålt dem, och Herren hafver öfvergifvit dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Förty vår klippa är icke såsom deras klippa; vare fiender äro der sjelfve domare om.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Deras vinträ är Sodoms vinträ, och af Gomorres åker; deras drufvor äro galle, de hafva bitter bär;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Deras vin är drakaetter, och grymma huggormars galle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Är icke sådant fördoldt när mig, och försegladt i minom håfvom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Hämnden är min; jag skall vedergällat. På sin tid skall deras fot slinta; deras ofärds tid är när, och det dem tillstundar skyndar sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Ty Herren varder dömandes sitt folk, och öfver sina tjenare skall han förbarma sig; ty han varder anseendes, att de äro slätt förgångne, och hvarken de beslutne, eller någon man är öfverblifven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Och man varder sägandes: Hvar äro deras gudar; deras klippa, der de förtröste sig uppå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Af hvilkas offer de åto det feta, och drucko vin af deras drickoffer; lät dem uppstå och hjelpa eder, och beskärma eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Sen I nu, att jag allena äret, och ingen Gud är förutan mig; jag kan döda, och lefvande göra; jag kan slå, och kan hela, och ingen är, som utu mine hand kan fria.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Ty jag vill lyfta mina hand upp i himmelen, och vill säga: Jag lefver evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'När jag mins svärds ljungande hvetter, och min hand tager till straffa; så skall jag hämnas igen på mina fiendar, och vedergälla dem som mig hata.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Jag skall göra mina pilar druckna af blod, och mitt svärd skall äta kött, öfver de slagnas blod, och öfver fängelset, och öfver fiendens blottade hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Fröjdens alle I som ären hans folk; ty han varder hämnandes sina tjenares blod; och varder nämnandes öfver sina fiendar; och skall nådelig vara sins folks lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Och Mose kom, och talade all denna visones ord för folkens öron, han och Josua, Nuns son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Då nu Mose allt detta uttalat hade till hela Israel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Sade han till dem: Lägger på hjertat all de ord, som jag betygar eder i dag, att I befallen edor barn, att de hålla och göra all dessa lagsens ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Förty det är intet fåfängt ord till eder, utan det är edart lif; och det ord skall förlänga edart lif på landena, dit I gån öfver Jordan till att intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Och Herren talade till Mose på samma dagen, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Gack upp på berget Abarim, uppå Nebo berg som ligger i de Moabiters land, tvärtöfver Jericho, och bese landet Canaan, som jag Israels barnom till eget gifva skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Och blif död på bergena, då du dit uppkommen äst, och församla dig till ditt folk; lika som din broder Aaron blef död på de bergena Hor, och församlade sig till sitt folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Derföre, att I hafven brutit emot mig ibland Israels barn, vid trätovattnet i Kades, i den öknene Zin, att I icke helgaden mig ibland Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Ty du skall få se landet tvärtifrå dig, det jag Israels barn gifver; men du skall icke komma derin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Detta är välsignelsen, der Mose, Guds man, med välsignade Israels barn för hans död,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Och sade: Herren är kommen af Sinai, och är dem uppgången af Seir; han är framkommen ifrå det berget Paran, och är kommen med mång tusend heliga; på hans högra hand är en brinnande lag för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'O! huru kär hafver han folken; alle hans helige äro i dine hand, de skola sätta sig till dina fötter, och skola lära af dinom ordom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mose hafver budit oss lagen, Jacobs menighets arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Och han var i Konungavälde, och Förstarna för folket höll han tillhopa, samt med Israels slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben lefve, och dö icke, och hans folk vare fögo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Detta är Juda välsignelse; och han sade: Herre, hör Juda röst, och gör honom till en regent i sitt folk, och låt hans magt varda stora, och honom varde hulpet ifrå hans fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Och till Levi sade han: Din rätt och ditt ljus vare när dinom helga Man, den du försökte i Massa, der I trätten vid trätovattnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Den som till sin fader, och till sina moder säger: Jag ser dem intet; och till sina bröder: Jag känner dem intet; och till sin son: Jag vet intet af honom; då samma hålla din ord, och bevara ditt förbund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'De skola lära Jacob dina rätter, och Israel din lag; de skola bära rökverk fram för dina näso, och heloffer på ditt altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Herre, välsigna hans förmågo, och låt hans händers gerningar behaga dig; slå deras rygg sönder, som sätta sig upp emot honom, och deras som hata honom, att de icke skola kunna rätta sig upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Och till BenJamin sade han: Herrans kärkomne skola bo säkert: alltid skall han akta uppå honom, och skall bo emellan hans axlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Och till Joseph sade han: Hans land ligger i Herrans välsignelse; der äro ädla frukter af himmelen, af daggene, och af djupet, som under ligger;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Der äro ädla frukter af solene, och ädla mogna frukter af månanom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Och af de höga bergen af begynnelsen, och af högomen i evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Och ädla frukter af jordene, och hvad derpå är; hans nåd, som bodde i buskanom, komme öfver Josephs hufvud, och uppå Nazirs hjessa ibland hans bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Hans härlighet är såsom en förstfödd oxe, och hans horn äro såsom enhörningshorn; med dem skall han stånga folken ihop intill landsens ända. Detta är Ephraims tiotusende, och Manasses tusende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Och till Sebulon sade han: Sebulon, fröjda dig af din utgång. Men Isaschar, fröjda dig af dina hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'De skola kalla folk uppå berget, och offra der rättfärdighetenes offer; ty de skola suga hafsens ymnighet, och de fördolda håfvor i sandenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Och till Gad sade han: Välsignad vare den utrymmaren Gad; han bor som ett lejon, och röfvar arm och hjessa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Och han såg, att honom ett hufvud gifvet var; en lärare, som är fördold, och kom med folkens öfverstar, och skaffade Herrans rättviso, och hans rätter med Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Och till Dan sade han: Dan, ett ungt lejon; han skall flyta af Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Och till Naphthali sade han: Naphthali skall hafva nog, ehvad honom lyster, och skall vara full med Herrans välsignelse; vesterut, och söderut skall hans besittning vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Och till Asser sade han: Asser vare välsignad med söner; han vare sina bröder täck, och doppe sin fot i oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Jern och koppar vare på hans skor; din ålder vare såsom din ungdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ingen Gud är såsom dens starkas Gud; den som sitter i himmelen, han vare din hjelp; hans härlighet är i skyn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Det är Guds boning af begynnelsen, och hans armar äro härnedre evinnerlig; och han skall utdrifva din fienda för dig, och säga: Var förderfvad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israel skall allena trygger bo; Jacobs brunn skall vara uppå det land, som korn och vin uti är, och dess himmel skall drypa dagg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Väl är dig, Israel; ho är din like? O du folk, som igenom Herran salig varder, hvilken dins hjelps sköld är, och dins segers svärd! Dine fiender skola fela, och du skall träda in på deras höjder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Och Mose gick utaf de Moabiters mark, upp på berget Nebo, uppå klinten af berget Pisga, tvärtemot Jericho; och Herren viste honom det hela landet Gilead, allt intill Dan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Och hela Naphthali, och Ephraims land, och Manasse, och hela Judaland, allt intill det yttersta hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Och söderut, och den breda ängden vid Jericho Palma stadsens, allt intill Zoar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Och Herren sade till honom: Detta är det landet, som jag Abraham, Isaac och Jacob, svorit hafver, och sagt: Jag skall gifva det dine säd. Du hafver nu sett det med din ögon; men du skall icke komma ditöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Och så blef Mose Herrans tjenare der död i de Moabiters lande, efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Och han begrof honom uti dalenom uti de Moabiters lande, emot Peors hus; och ingen hafver fått veta hans graf allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Och Mose var hundrade och tjugu år gammal, då han blef död; hans ögon voro intet mörk vorden, och hans kinder voro intet förfallna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Och Israels barn begreto Mose på de Moabiters mark i tretio dagar; och de gråto- och klagodagar öfver Mose vordo fullkomnade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Men Josua, Nuns son, vardt uppfylld med vishetsanda; ty Mose hade lagt sina händer på honom; och Israels barn lydde honom, och gjorde såsom Herren budit hade Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Och sedan stod ingen Prophete upp i Israel, såsom Mose, den Herren kände ansigte mot ansigte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Till allahanda tecken och under, till hvilken Herren honom sände, att han dem göra skulle i Egypti land, på Pharao och alla hans tjenare, och på allt hans land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Och till all den mägtiga hand, och stora syner, som Mose gjorde för hela Israels ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Efter Mose, Herrans tjenares död, sade Herren till Josua, Nuns son, Mose tjenare:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Min tjenare Mose är död; så gör dig nu redo och drag öfver denna Jordan, du och allt detta folket, in uti det land, som jag dem, nämliga Israels barnom, gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Allt rum, der edart fotbjelle på trädandes varder, hafver jag gifvit eder, såsom jag Mose sagt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Ifrån, öknene och denna Libanon, intill den stora älfvena Phrath, hela Hetheers land, intill det stora hafvet vesterut, skola edor landamäre vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ingen skall stå emot dig i dina lifsdagar; såsom jag hafver varit med Mose, så skall jag ock vara med dig; jag skall icke öfvergifva eller förgäta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Var tröst och frimodig; ty du skall utskifta desso folkena landet, som jag deras fäder svorit hafver, att jag dem det gifva skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Var nu tröst och ganska frimodig, att du håller och gör all ting efter lagen, som Mose min tjenare dig budit hafver; vik icke derifrån, antingen, på högra sidon eller den venstra, på det att du må handla visliga i allt det du göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Och låt denna lagbokena icke komma utu dinom mun; utan haf dina tankar deruti dag och natt, på det att du skall hålla och göra all ting derefter, som deruti skrifvet står; så skall dig lyckas i allt det du gör, och du skall kunna handla visliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Si, jag hafver budit dig, att du skall vara tröst, och vid godt mod; grufva dig för ingen ting, och frukta intet; ty Herren din Gud är med dig i allt det du företager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Då böd Josua höfvitsmännerna öfver folket, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Går igenom lägret, och bjuder folkena, och säger: Bereder eder spisning; ty efter tre dagar skolen I gå öfver denna Jordanen, att I mågen inkomma till att intaga landet, som Herren edar Gud eder gifva skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Och sade Josua till de Rubeniter, Gaditer, och till de halfva slägtena Manasse:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Tänker uppå det ord, som Mose Herrans tjenare eder böd, och sade: Herren edar Gud hafver låtit eder komma till ro, och gifvit eder detta landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Edra hustrur, barn och boskap låter blifva i landena, som Mose eder gifvit hafver, på denna sidone Jordan; men I skolen gå för edra bröder väpnade, alle de som väraktige män äro, och hjelpa dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Intilldess Herren låter ock edra bröder komma till ro, så väl som eder, att de ock måga intaga det land, som Herren edar Gud dem gifva skall. Sedan skolen I vända om igen till edart land, att I det besitten, som Mose Herrans tjenare eder gifvit hafver, på denna sidone Jordan österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Och de svarade Josua, och sade: Allt det du oss budit hafver, det vilje vi göra, och hvart du sänder oss, dit vilje vi gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Såsom vi hafve varit Mose lydige, så vilje vi ock vara dig lydige; allenast vare Herren din Gud med dig, såsom han var med Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Hvilken som din mun emotstår, och icke lyder din ord i allt det du bjuder oss, han skall dö; allenast var du tröst, och vid godt mod,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Josua, Nuns son, sände hemliga ut två spejare ifrå Sittim, och sade dem: Går och beser landet, och Jericho. De gingo åstad, och kommo in uti ene skökos hus, som het Rahab, och der lågo de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Då vardt Konungenom i Jericho sagdt Si, i denna nattene äro någre män inkomne ifrån Israels barn, till att bespeja, landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Då sände Konungen i Jericho till Rahab, och lät säga henne: Få oss ut de män, som till dig i ditt hus komne äro; ty de äro komne till att bespeja allt landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Men qvinnan fördolde de två männerna, och sade: Här äro väl två män inkomne till mig; men jag visste icke hvadan de voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Och då jag ville låta dörrena igen, då mörkt vardt, gingo de ut, så att jag icke vet hvart de gingo; söker med hast efter dem, I fån dem väl fatt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Men hon lät dem stiga upp på taket, och öfvertäckte dem med linstjelkar, som hon der på taket utbredt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Men männerna sökte efter dem på den vägen till Jordan, allt intill färjostaden; och porten vardt tilläster straxt de utkomne voro, som efter dem jagade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Och förra än männerna lade sig till sofva, steg hon upp på taket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Och sade till dem: Jag vet, att Herren hafver gifvit eder detta landet; ty en förskräckelse för eder är fallen öfver oss, och alle landsens inbyggare äro bäfvande vordne för edor tillkommelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Ty vi hafve hört, huru Herren uttorkade vattnet i röda hafvet för eder, då I drogen utur Egypten; och hvad I gjort hafven de två Amoreers Konungar, Sihon och Og, på hinsidon Jordan, huru I gåfven dem tillspillo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Och sedan vi det hörde, vardt vårt hjerta förtvifladt, och intet mod är mer i någon man för edor tillkommelse; ty Herren edar Gud han är Gud, både uppe i himmelen, och nedre på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Så svärjer mig nu vid Herran, efter jag hafver gjort barmhertighet med eder, att I ock gören barmhertighet med mins faders hus, och gifver mig ett vårdtecken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Att I låten lefva min fader, mina moder, mina breder, och mina systrar, och allt det de hafva; och frälser våra själar ifrå döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Männerna sade till henne: Om vi icke göre barmhertighet och trohet med dig, då Herren gifver oss landet, så skall var själ vara döden skyldig för eder, såframt du icke förråder vårt ärende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Så släppte hon dem neder med ett tåg genom ett fenster; ty hennes hus var i stadsmurenom; och hon bodde desslikes på murenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Och hon sade till dem: Går uppåt berget, att de, som söka efter eder, icke möta eder, och gömmer eder der i tre dagar, så länge de komma igen, som efter eder fara; sedan går edar väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Männerna sade till henne: Vi vilje vara denna eden qvitte, som du af oss tagit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'När vi komme i landet, och du icke binder detta rosenröda tåget i fenstret, med hvilko du oss nedersläppt hafver: och hafver församlat till dig i huset din fader, dina moder, dina bröder, och hela dins fadershus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Och hvilken som går utom dörrena af ditt hus, hans blod vare öfver hans hufvud, och vi oskyldige; men alle de som i dino huse äro, om en hand kommer vid dem, så skall deras blod vara öfver vårt hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Och om du något af denna vår ärende utröjer, så vilje vi vara den eden qvitte, som du af oss tagit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Hon sade: Vare som I sägen: och låt gå dem; och de gingo sin väg, och hon band det rosenröda tåget i fenstret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Och de gingo sin väg, och kommo upp på berget, och blefvo den tre dagar, tilldess de kommo igen, som efter dem foro: ty de hade sökt dem på alla vägar, och dock intet funnit dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Så vände de två männerna tillbaka, gingo ned af berget, och foro utöfver, och kommo till Josua, Nuns son, och förtäljde honom allt, såsom de det funnit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Och sade till Josua: Herren hafver gifvit oss allt landet i våra händer, alle landsens inbyggare äro förskräckte för oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Och Josua stod bittida upp, och de drogo ut ifrå Sittim, och kommo till Jordan, han och all Israels barn, och blefvo der öfver nattena, förra än de drogo utöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Efter tre dagar gingo befallningsmännerna genom lägret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Och bödo folkena, och sade: När I sen Herrans edars Guds förbunds ark, och Presterna Leviterna bära honom, så drager ut ifrån edor rum, och följer honom efter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Dock så, att emellan eder och honom är rum vid tutusende alnar långt. I skolen ock icke komma hardt intill honom, på det I mågen veta, på hvilken vägen I gå skolen; förty I hafven den vägen tillförene icke gångit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Och Josua sade till folket: Helger eder; ty i morgon varder Herren görandes ett underligit ting ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Och till Presterna sade han: Tager förbundsens ark, och går framför folket. Och de togo förbundsens ark, och gingo för folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Och Herren sade till Josua: I dag skall jag begynna göra dig stor för hela Israel, att de skola veta att, såsom jag hafver varit med Mose, så är jag ock med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Och du bjud Presterna, som förbundsens ark bära, och säg: Som I kommen först i vattnet af Jordan, så står stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Och Josua sade till Israels barn: Går fram, och hörer Herrans edars Guds ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Och sade: Deruppå skolen I märka, att en lefvandes Gud är ibland eder, och han för eder utdrifva skall de Cananeer, Hetheer, Heveer, Phereseer, Girgaseer, Amoreer och Jebuseer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Si, hans förbunds ark, som en Herre är öfver alla verldena, skall gå för eder in uti Jordanen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Så tager nu tolf män utaf Israels slägter, utaf hvart slägte en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'När då Presternas fotbjelle, som bära Herrans ark, den en Herre är öfver alla verldena, komma in uti Jordans vatten, så skall vattnet, som ofvanefter flyter, i Jordan afskilja sig, så att det skall stå i enom hop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Då nu folket drog ut af sin tjäll, att de skulle gå utöfver Jordan, och Presterna båro förbundsens ark fram för folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Och kommo intill Jordanen, och deras fötter först trädde i vattnet, och Jordan var full till alla sina brädder af allahanda andenes vatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Då stod det vattnet, som ofvanefter flöt, upprest i en hop, ganska långt ifrå dens stadsens folk, som ligger utmed Zarthan; men det vattnet, som nederlopp åt hafvet, som är salthafvet, det förminskades, och förlopp. Så gick då folket deröfver inåt Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Och Presterna, som båro Herrans förbunds ark, stodo stilla, torre midt i Jordan, och hela Israel gick torr igenom, tilldess allt folket kom öfver Jordan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Och Herren sade till Josua:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Tager eder tolf män, utaf hvart slägtet en;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Och bjuder dem, och säger: Lyfter upp utur Jordan tolf stenar, af det rummet der Presternas fötter stilla stå, och hafver dem öfver med eder, att I lefven dem i lägrena, der I eder i denna nattene lägren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Då kallade Josua tolf män, som tillskickade voro af Israels barn, utaf hvart slägte en;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Och sade till dem: Går fram för Herrans edars Guds ark midt i Jordan, och hvar lyfte en sten på sina axlar, efter talet af Israels barnas slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Att de skola vara ett tecken ibland eder, när edor barn i framtiden fråga sina fäder, och säga: Hvad göra desse stenarna här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Att I då mågen säga dem, huru Jordans vatten sig åtskiljde för Herrans förbunds ark, då han gick genom Jordan; så att desse stenarna skola vara Israels barnom till en evig åminnelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Då gjorde Israels barn såsom Josua böd dem; och båro tolf stenar midt utur Jordan, såsom Herren hade sagt Josua, efter talet af Israels barnas slägte; och båro dem med sig till det rummet, der de lägrade sig, och der lade de dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Och Josua reste upp tolf stenar midt i Jordan, der Presternas fötter ståndit hade, som förbundsens ark båro, och de äro der ännu intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Ty Presterna, som arken båro, stodo midt i Jordan, tilldess allt bestäldt vardt, som Herren böd Josua säga folkena, och Mose Josua budit hade; och folket skyndade sig, och gick öfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Då nu folket allt öfvergånget var, så gick ock Herrans ark öfver, och Presterna för folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Och de Rubeniter, och de Gaditer, och den halfva Manasse slägt, gingo väpnade för Israels barnom, såsom Mose dem sagt hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Vid fyratiotusend väpnade till härs gingo för Herranom till strids på Jericho mark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'På den dagen gjorde Herren Josua stor för hela Israel; och de fruktade honom, såsom de fruktade Mose, medan han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Och Herren sade till Josua:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Bjud Presterna, som bära vittnesbördsens ark, att de träda upp utur Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Alltså böd Josua Prestomen, och sade: Stiger upp utur Jordan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Och då Presterna, som Herrans förbunds ark båro, stego upp utur Jordan, och trädde med deras fotbjelle på torra landet, kom Jordans vatten återigen i sin stad, och flöt såsom tillförene till alla sina brädder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Och det var den tionde dagen i den första månadenom, då folket uppsteg utur Jordan, och lägrade sig i Gilgal, östan för Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Och de tolf stenar, som de utur Jordan tagit hade, reste Josua upp i Gilgal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Och sade till Israels barn: När nu i framtiden edor barn fråga sina fäder, och säga: Hvad skola desse stenarna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Så skolen I undervisa dem, och säga: Israel gick torr igenom Jordan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Då Herren edar Gud förtorkade Jordans vatten för eder, så länge I gingen deröfver, lika som Herren edar Gud gjorde i röda hafvet, hvilket han torrt gjorde för oss, så att vi ginge derigenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'På det all folk på jordene skola känna Herrans hand, huru mägtig hon är; och att I skolen frukta Herran edar Gud alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Då nu alla de Amoreers Konungar, som på den sidan Jordan vesterut bodde, och alla de Cananeers Konungar vid hafvet, hörde huru Herren hade förtorkat Jordans vatten för Israels barn, så länge de gingo deröfver, vardt deras hjerta bäfvande, och intet mod var mer i dem, för Israels barns skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'På den tiden sade Herren till Josua: Gör dig stenknifvar, och omskär Israels bara annan gång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Då gjorde Josua sig stenknifvar, och omskar Israels barn på den högen Araloth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Och detta är saken, hvarföre Josua omskar allt folket, som utur Egypten draget var, mankön; ty allt krigsfolket var dödt blifvet i öknene på vägenom, då de drogo utur Egypten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Ty allt det folk, som utdrog, var omskoret; men allt det folk, som i öknene föddes på vägenom, då de drogo utur Egypten, det var icke omskoret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Förty Israels barn vandrade i fyratio år i öknene, tilldess allt folket af krigsmännerna, som utur Egypten dragne voro, förgingos; derföre, att de icke lydde Herrans röst, såsom Herren dem svorit hade, att de icke skulle få se det landet, som Herren deras fader svorit hade, att gifva oss ett land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Deras barn, som i deras stad uppkomne voro, dem omskar Josua; förty de hade förhud, och voro intet omskorne på vägenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Och då hela folket omskoret var, blefvo de på sitt rum i lägrena, tilldess de voro läkte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Och Herren sade till Josua: I denna dag hafver jag vändt ifrån eder Egypti skam; och det rummet vardt kalladt Gilgal, intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Och som Israels barn så hade deras lägre i Gilgal, höllo de Passah, på fjortonde dagen i den månadenom, om aftonen, uppå Jericho mark;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Och åto af landsens säd på annan dagen i Passah, nämliga osyradt bröd, och torkad ax, rätt uppå samma dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Och Man vände åter på den andra dagen, sedan de hade ätit af landsens säd, så att Israels barn intet Man mera hade, utan åto af landsens Canaans säd, utaf det samma året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Och det begaf sig, då Josua var vid Jericho, att han upplyfte sin ögon, och vardt varse att en man stod der för honom, och hade ett draget svärd i sine hand; och Josua gick till honom, och sade till honom: Hörer du oss, eller våra fiendar till?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Han sade: Nej; utan jag är Förste öfver Herrans här, och är rätt nu kommen. Då föll Josua neder på jordena på sitt ansigte, och tillbad, och sade till honom: Hvad säger min Herre till sin tjenare?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Och Försten öfver Herrans här sade till Josua: Drag dina skor af dina fötter; ty rummet, som du står uppå, är heligt. Och Josua gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Och Jericho var tillstängdt och förvaradt för Israels barns skull, så att ingen kunde komma ut eller in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Men Herren sade till Josua: Si, jag hafver gifvit Jericho, med dess Konung och krigsfolk, i dina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Låt alla krigsmännerna gå en gång kringom staden; och gör så i sex dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'På sjunde dagen låt Presterna taga sju klangårens basuner, och gå dermed för arken; och går på den samma sjunde dagenom sju resor kringom staden, och låt Presterna blåsa i basunerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Och då man blås i klangårshornet långsamt, så att I hören basunerna, då skall folket göra ett stort skri, och så skola stadsmurarna falla, och folket skall falla derin, hvar och en rätt framför sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Då kallade Josua, Nuns son, Presterna, och sade till dem: Bärer förbundsens ark, och låter sju Prester bära sju klangårens basuner för Herrans ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Men till folket sade han: Drager åstad, och går omkring staden, och hvilken som väpnader är, han gånge fram för Herrans ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Då Josua detta folkena sagt hade, togo de sju Prester sju klangårens basuner, och gingo för Herrans ark, och blåste i basunerna; och Herrans förbunds ark följde efter dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Och hvilken som väpnader var, han gick för Presterna, som i basunerna blåste, och hopen följde efter arken, och blåste i basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Men Josua böd folkena, och sade: I skolen intet härskri göra, eller låta höra edra röst, eller något ord låta gå utaf edar mun, intill den dagen jag säger till eder: Gifver upp ett härskri; då gifver ett härskri upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Så gick Herrans ark kringom staden en gång; och kommo i lägret, och blefvo der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Förty Josua plägade vara bittida uppe om morgonen; och Presterna båro Herrans ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Så båro de sju Presterna de sju klangårens basuner för Herrans ark, och gingo och blåste i basunerna; och hvilken som väpnad var, han gick för dem, och hopen följde Herrans ark, och blåste i basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'På den andra dagen gingo de ock en gång om staden, och kommo i lägret igen; så gjorde de i sex dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Men på sjunde dagen, då morgonrodnen uppgick, voro de bittida uppe, och gingo vid samma sättet sju resor kringom staden; så att de på den samma ena dagen kommo sju resor kringom staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Och på sjunde resone, då Presterna blåste i basunerna, sade Josua till folket: Gifver upp ett härskri; ty Herren hafver gifvit eder staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Men staden, och allt det deruti är, skall tillspillogifvas Herranom; allenast den skökan Rahab skall blifva lefvandes, och alla de som med henne äro i huse; ty hon fördolde de bådskap, som vi utsände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Allenast tager eder vara för det som tillspillogifvet är, att I icke gifven eder sjelf tillspillo, om I något tagen af det som tillspillogifvet är, och gören så Israels lägre tillspillo, och låten det komma i olycko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Men allt silfver och guld, och koppars och jerns tyg, skall vara helgadt Herranom, och bevaras till Herrans skatt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Då gaf folket upp ett härskri, och blåste i basunerna; ty allt folket, som hörde basunernas ljud, gaf upp ett stort härskri, och murarna föllo omkull, och folket besteg staden, hvar och en rätt för sig. Så vunno de staden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Och tillspillogjorde allt det i stadenom var, med svärdsegg, både man och qvinno, ung och gammal, fä, får och åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Och Josua sade till de två män, som hade bespejat landet: Går uti den skökones hus, och hafver qvinnona dädan hitut, med allt det hon hafver, såsom I hafven svorit henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Då gingo de unge män spejarena ditin, och hade Rahab ut med hennes fader och moder, och bröder, och allt det hon hade, och alla hennes slägt, och läto dem blifva utanför Israels lägre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Men staden brände de upp med eld, och allt det deruti var; allenast silfver och guld, och koppars och jerns tyg, lade de för en skatt in uti Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Men den skökan Rahab, med hennes faders hus, och allo thy hon hade, lät Josua lefva; och hon bodde i Israel intill denna dag; derföre att hon hade fördolt de bådskap, som Josua till att bespeja utsändt hade till Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'På den tiden svor Josua, och sade: Förbannad vare den man för Herranom, som upprättar och bygger denna staden Jericho. När han lägger hans grund, det koste honom hans första son; och när han uppsätter hans port, det koste honom hans yngsta son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Och var Herren med Josua, så att han vardt namnkunnig i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Men Israels barn förtogo sig på det som tillspillogifvet var; ty Achan, Charmi son, Sabdi sons, Serahs sons, af Juda slägte, tog något af det som tillspillogifvet var; då förgrymmade sig Herrans vrede öfver Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Och Josua utsände af Jericho några män in mot Aj, som ligger vid BethAven österut ifrå BethEl, och sade till dem: Går upp, och bespejer landet. Och då de hade uppgångit, och bespejat Aj,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kommo de igen till Josua, och sade till honom: Låt icke allt folket draga ditupp; utan vid tu eller tre tusend män, att de draga ditupp, och slå Aj, att icke allt folket gör sig der mödo om; förty de äro få.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Så drogo ditupp af folkena vid tretusend män, och de flydde för de män af Aj.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Och de af Aj slogo af dem vid sex och tretio män, och jagade dem allt ifrå porten intill Sebarim, och slogo dem den vägen nederåt. Då vardt folkens hjerta förtvifladt, och vardt såsom vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Och Josua ref sina kläder sönder, och föll uppå sitt ansigte till jordena för Herrans ark, allt intill aftonen, samt med de äldsta af Israel, och de strödde stoft på sin hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Och Josua sade: Ack! Herre, Herre, hvi hafver du fört detta folket öfver Jordan, att du skulle gifva oss uti de Amoreers händer, till att förgöra oss? Ack! det vi dock hade blifvit på hinsidon Jordan, såsom vi begynt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ack! min Herre, hvad skall jag säga, medan Israel vänder ryggen till sina fiendar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'När de Cananeer och alle landsens inbyggare det höra, så varda de oss omkringhvärfvande, och utrota vårt namn af jordene; hvad vill du då göra dino stora Namne?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Då sade Herren till Josua: Statt upp, hvi ligger du så på ditt ansigte?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hafver syndat, och de hafva gångit öfver mitt förbund, som jag dem budit hafver; och hafva tagit af det som tillspillogifvet var, och stulit, och ljugit, och lagt ibland sin tyg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Israels barn kunna icke blifva ståndande för sina fiendar; utan måste vända ryggen till sina fiendar; förty de äro tillspillo vordne. Jag skall icke vara mera med eder, om I icke låten komma den spillning ifrån eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Statt upp, och helga folket, och säg: Helger eder till morgons; ty så säger Herren Israels Gud: En spillning är ibland dig, Israel; derföre kan du icke blifva ståndandes för dina fiendar, tilldess I låten den spillningen komma ifrån eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Och I skolen bittida gå fram, den ena slägten efter den andra; och på hvilken slägten Herren drabbar, der skall gå fram den ena ätten efter den andra; och på hvilken ätten Herren drabbar, der skall gå fram det ena huset efter det andra; och på hvilket hus Herren drabbar, der skall gå fram den ene husbonden efter den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Och hvilken som befunnen varder med någon spillgifven ting, honom skall man uppbränna i eld, med allt det han hafver; derföre, att han hafver gångit emot Herrans förbund, och bedrifvit en galenskap i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Så stod Josua bittida upp om morgonen, och hade fram Israel, den ena slägten efter den andra; och det drabbade inpå Juda slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Och då han hade Juda slägte fram, drabbade det inpå de Serahiters ätt; och då han hade de Serahiters ätt fram, den ena husbonden efter den andra, drabbade det på Sabdi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Och då han hade hans hus fram, den ena husbonden efter den andra, drabbade det på Achan, Charmi son, Sabdi sons, Serahs sons, utaf Juda slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Och Josua sade till Achan: Min son, gif Herranom Israels Gudi ärona, och gif honom prisen; och säg mig hvad du gjort hafver, och ljug intet för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Då svarade Achan Josua, och sade: Sannerliga, jag hafver syndat emot Herran Israels Gud; så och så hafver jag gjort:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Jag såg ibland rofvet en kostelig Babylonisk mantel, och tuhundrade siklar silfver, och en gyldene tungo, femtio siklar värd till vigt; der fick jag lust till, och tog det; och si, det är nedergrafvet i jordene i mitt tjäll, och silfret derunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Då sände Josua dit båd; de lupo till tjället, och si, der var det nedergrafvet i hans tjäll, och silfret derunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Och de togo det utu tjället, och båro till Josua, och till all Israels barn, och kastade det der ned för Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Då tog Josua och hela Israel med honom Achan, Serahs son, med silfret, mantelen och gyldene tungone, hans söner och döttrar, hans oxar och åsnar, och får, hans tjäll, och allt det han hade; och förde ut i Achors dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Och Josua sade: Efter du hafver plågat oss, så plåge dig Herren på denna dag! Och hela Israel stenade dem, och brände dem upp i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Och då de hade stenat dem, gjorde de ena stora stenrösjo öfver dem, hvilken ännu varar allt intill denna dag. Så vände då Herren sig ifrå sine vredes grymhet; deraf heter det rummet Achors dal intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Och Herren sade till Josua: Frukta dig intet, och var intet förfärad. Tag med dig allt krigsfolket, och gör redo, och drag upp till Aj. Si, jag hafver gifvit Konungen i Aj, med hans folk, hans stad och land, i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Och du skall göra med Aj och dess Konung, såsom du med Jericho och dess Konung gjort hafver; undantagno, att dess rof och dess boskap skolen I byta eder emellan. Beställ ett bakhåll afsides vid staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Då gjorde Josua redo, och allt krigsfolket, till att draga upp till Aj; och Josua utvalde tretiotusend stridsmän, och sände ut om nattena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Och böd dem, och sade: Ser till, I skolen vara i bakhåll, afsides vid staden; och varer icke för långt ifrå staden, och varer alle redo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Men jag, och allt folket, som med mig är, viljom draga till staden; och när de draga ut emot oss, såsom tillförene, så vilje vi fly för dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Att de draga ut efter oss, så länge vi komme dem ut ifrå staden; ty de skola tänka, att vi fly för dem, såsom tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Och medan vi fly för dem, skolen I redo vara i bakhållena, och taga staden in; förty Herren edar Gud skall gifva eder honom i händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'När I hafven intagit staden, så tänder elden på honom; efter Herrans ord görer: si, jag hafver det budit eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Så sände Josua dem åstad, och de gingo ditupp i bakhåll, och höllo emellan BethEl och Aj, vesterut ifrån Aj; men Josua blef i den nattene när folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Och om morgonen var han bittida uppe, och skickade folket, och drog upp med de äldsta af Israel för folkena till Aj.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Och allt krigsfolket, som när honom var, drogo upp, och trädde fram, och kommo in mot staden, och lägrade sig norrut ifrån Aj; så att en dal var emellan dem och Aj.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Men han hade tagit vid femtusend män, och ställt dem till bakhåll emellan BethEl och Aj, vesterut ifrå staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Och folket af hela lägret, som norrut ifrå stadenom var, ställdes så, att dess yttersta räckte vester om staden; så drog då Josua i den nattene midt in uppå dalen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Som nu Konungen i Aj såg det, skyndade de sig, och gjorde bittida redo; och männerna af stadenom drogo ut, till att möta Israel i strid med allt sitt folk, på ett förelagdt rum emot slättmarkene; ty han visste icke, att ett bakhåll var på honom bakom staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Men Josua och hela Israel ställde sig, såsom de hade varit slagne för dem, och flydde på den vägen åt öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Då skriade allt folket af stadenom, att man skulle förfölja dem; och de jagade desslikes efter Josua, och föllo utu stadenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Så att icke en man blef qvar i Aj och BethEl, den icke utdrog, och förföljde Israel; och läto staden stå öppen, på det de skulle jaga efter Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Då sade Herren till Josua: Räck ut spetsen, som du hafver i dine hand, emot Aj; ty jag vill gifva det i dina hand. Och Josua räckte ut spetsen, som i hans hand var, emot staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Då gaf sig bakhållet upp med hast utaf sitt rum, och lupo, sedan han räckte ut sina hand, och kommo i staden, och vunno honom, och hastade sig, och tände elden på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Och de män af Aj vände sig, och sågo tillbaka, och fingo se röken af staden gå upp i himmelen, och hade intet rum till att fly, hvarken hit eller dit: och det folket, som flydde åt öknena, vände sig om till att jaga efter dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Då nu Josua och hela Israel sågo, att bakhållet hade vunnit staden, efter röken gick upp af stadenom, vände de om, och slogo de män af Aj.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Och de i staden drogo också ut emot dem, så att de kommo midt ibland Israel på båda sidor; och de slogo dem, tilldess ingen af dem öfverblef lefvandes, eller undslapp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Och grepo Konungen af Aj lefvandes, och förde honom till Josua.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Och då Israel hade ihjälslagit alla Ajs inbyggare på markene, och i öknene, som hade jagat efter dem, och de föllo alle genom svärdsegg, tilldess de voro ändade; då vände sig hela Israel åt Aj, och slogo det med svärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Och alle de som föllo på den dagen, både män och qvinnor, de voro tolftusend, allt folk i Aj.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Och Josua drog icke handena igen, med hvilko han uträckte spetsen, tilldess han tillspillogjorde alla Ajs inbyggare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Utan boskapen, och rofvet af stadenom, utbytte Israel emellan sig, efter Herrans ord, såsom han Josua budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Och Josua brände upp Aj, och gjorde en hög deraf till evig tid, den ännu der är på denna dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Och lät upphänga Konungen af Aj i ett trä intill aftonen. Då solen var nedergången, befallde han, att man skulle taga hans kropp utu trät; och de kastaden i stadsporten, och hofvo en stor stenhop deruppå, hvilken ännu der är intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Då byggde Josua Herranom Israels Gud ett altare, på det berget Ebal,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Såsom Mose Herrans tjenare Israels barnom budit hade, såsom skrifvet står i Mose lagbok, ett altare af hela stenar, der intet jern på kommet var; och offrade deruppå Herranom bränneoffer och tackoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Och skref der på stenarna den andra lagen, som Mose Israels barnom föreskrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Och hela Israel med deras äldsta, och ämbetsmän och domare, stodo på båda sidor vid arken inför Presterna af Levi, som båro Herrans förbunds ark; de främlingar, så väl som de infödde; hälften af dem invid det berget Grisim, och den andra hälften invid det berget Ebal; såsom Mose Herrans tjenare tillförene budit hade till att välsigna Israels folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Sedan lät han utropa all lagsens ord, om välsignelsen och förbannelsen, som skrifne stå i lagbokene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Det var icke ett ord, som Mose budit hade, det Josua icke lät utropa för hela Israels menighet; för qvinnor och barn, och främlingom, som ibland dem voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Då nu detta hördes intill alla de Konungar, som voro på den sidon Jordan, på bergom och i dalom, och i alla stora hafsens nämner, och när dem som voro invid Libanons berg, nämliga de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Samkade de sig tillhopa endrägteliga, att de skulle strida emot Josua, och emot Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Men Gibeons inbyggare, då de hörde hvad Josua gjort hade med Jericho och Aj,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Upptänkte de en list, gingo till och sände bådskap åstad, och togo gamla säcker på sina åsnar, och gamla slitna vinläglar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Och gamla lappade skor på sina fötter, och drogo gamla och rifna kläder uppå; och allt det bröd, som de togo med sig, var hårdt och mögladt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Och gingo till Josua i lägret vid Gilgal, och sade till honom, och till hela Israel: Vi äre komne fjerran af annor land; så görer nu ett förbund med oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Då sade hela Israel till de Heveer: Kan hända, att du bor här ibland oss, huru kunne vi då göra förbund med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'De sade till Josua: Vi äre dine tjenare. Josua sade till dem: Ho ären I; eller hvadan kommen I?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'De sade: Dine tjenare äro ganska fjerran komne af annor land, för Herrans dins Guds Namns skull; ty vi hafve hört hans rykte, och allt det han i Egypten gjort hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Och allt det han de två Amoreers Konungar på hinsidon Jordan gjort hafver, Sihon, Konungenom i Hesbon, och Og, Konungenom i Basan, som bodde i Astaroth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Derföre sade våre äldste; och alle vårt lands inbyggare: Tager spisning med eder på resona, och går åstad emot dem, och säger till dem: Vi äre edre tjenare; så görer nu ett förbund med oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Detta vårt bröd, som vi togo med oss till spisning utu vår hus, var ännu färskt, då vi åstad forom till eder; men nu, si, det är hårdt och mögladt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Och dessa vinläglarna fyllde vi nya; och si, de äro slitne; och denna vår kläder och skor äro gamla vordna för denna ganska långa resonas skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Då togo höfvitsmännerna af deras spisning, och frågade intet Herrans mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Och Josua gjorde frid med dem, och ingick ett förbund med dem, att de skulle blifva lefvande; och de öfverste för menighetene svoro dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Men efter tre dagar, sedan de hade gjort förbundet med dem, kom för dem, att de voro hardt när dem, och skulle bo ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Ty då Israels barn drogo framåt, kommo de tredje dagen till deras städer, hvilke så voro nämnde: Gibeon, Cephira, Beeroth och KiriathJearim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Och de slogo dem intet, ty de öfverste för menighetene hade svorit vid Herran Israels Gud; och hela menigheten knorrade emot de öfversta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Då sade alle de öfverste för hela menighetene: Vi hafve svorit dem vid Herran Israels Gud; derföre kunne vi intet komma vid dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Men det vilje vi göra dem; låtom dem lefva, att en vrede icke kommer öfver oss för edens skull, den vi dem gjort hafvom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Och de öfverste sade till dem: Låtom dem lefva, att de måga vara vedahuggare och vattudragare för hela menighetene, såsom öfverstarna dem sagt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Då kallade dem Josua, och talade med dem, och sade: Hvi hafven I bedragit oss, och sagt: I ären ganska långt ifrån oss; ändock I bon ibland oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Derföre skolen I vara förbannade, så att af eder icke skall återvända trälar, som ved hugga, och vatten draga, till mins Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'De svarade Josua, och sade: Det hafver varit sagdt dina tjenare, att Herren din Gud hafver budit sinom tjenare Mose, att han skall gifva eder detta hela landet, och förgöra för eder alla landsens inbyggare; då fruktade vi om våra själar för eder storliga, och gjorde detta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Men nu, si, vi äre i dina händer; hvad dig tycker godt och rätt vara att göra med oss, det gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Och han gjorde dem så, och friade dem ifrån Israels barnas hand, att de icke slogo dem ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Så gjorde Josua dem på samma dagen till vedahuggare och vattudragare för menighetene, och till Herrans altare, allt intill denna dag, på det rum som han utväljandes vorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Då nu AdoniZedech, Konungen i Jerusalem, hörde att Josua hade vunnit Aj, och gifvit det tillspillo, och hade gjort Aj och dess Konung lika såsom han hade gjort Jericho och dess Konung, och att de Gibeoniter hade gjort frid med Israel, och voro komne ibland dem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Fruktade de svårliga; förty Gibeon var en stor stad, såsom en af Konungastäderna, och större än Aj, och alle hans borgare gode stridsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Och han sände till Hoham, Konungen i Hebron, och till Piram, Konungen i Jarmuth, och till Japhia, Konungen i Lachis, och till Debir, Konungen i Eglon, och lät säga dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Kommer hitupp till mig, och hjelper mig, att vi må slå Gibeon; förty de hafva gjort frid med Josua och Israels barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Då kommo tillhopa, och drogo uppåt, de fem Amoreers Konungar: Konungen i Jerusalem, Konungen i Hebron, Konungen i Jarmuth, Konungen i Lachis, Konungen i Eglon, med all deras härlägre, och belade Gibeon, och stridde deremot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Men de af Gibeon sände till Josua i lägret i Gilgal, och läto säga honom: Drag icke dina hand ifrå dina tjenare; kom hitupp till oss snarliga, undsätt och hjelp oss; ty alla de Amoreers Konungar, som bo uppå bergen, hafva samkat sig tillhopa emot oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Josua drog ditupp ifrå Gilgal, och allt krigsfolket med honom, och alle gode stridsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Och Herren sade till Josua: Frukta dig intet för dem; ty jag hafver gifvit dem i dina händer; ingen af dem skall kunna blifva ståndandes för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Alltså kom Josua hasteliga på dem; ty han drog i hela nattene upp ifrå Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Men Herren förskräckte dem för Israel, så att de slogo dem en stor slagtning af i Gibeon; och jagade efter dem på den vägen till BethHoron, och slogo dem intill Aseka och Makkeda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Och då de flydde för Israel den vägen nederåt till BethHoron, lät Herren falla af himmelen stora hagelstenar på dem intill Aseka, så att de blefvo döde; och mycket flere af dem blefvo döde af hagelstenarna, än Israels barn slogo med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Då talade Josua med Herranom, på den dagen, när Herren gaf de Amoreer för Israels barn, och sade i Israels närvaro: Sol, statt stilla i Gibeon, och måne, i Ajalons dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Då stod solen stilla, och månen desslikes, tilldess att folket hämnade sig på sina fiendar. Är icke detta skrifvet i dens frommas bok? Så stod solen midt på himmelen, och fördröjde gå neder, sånär en helan dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Och hafver ingen dag varit lik vid denna, hvarken förr eller sedan, då Herren lydde ens mans röst; ty Herren stridde för Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Och Josua drog åter i lägret igen till Gilgal; och hela Israel med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Men de fem Konungar voro flydde, och undstungo sig uti en kulo i Makkeda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Då vardt Josua sagdt: Vi hafve funnit de fem Konungar fördolda i ene kulo i Makkeda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Josua sade: Så välter stora stenar för gapet af kulone; och befaller några män, som taga der vara på dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Men I står icke stilla, utan jager efter edra fiendar, och slår deras eftersta, och låter icke komma dem i deras städer; ty Herren edar Gud hafver gifvit dem i edra händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Och då Josua och Israels barn hade lyktat den mägtiga stora slagtningen på dem, och platt slagit dem, hvad sedan qvart blef af dem, det kom in i de fasta städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Så kom allt folket åter i lägret igen till Josua i Makkeda med frid; och ingen torde röra sina tungo för Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Men Josua sade: Låter upp gapet för kulone, och drager fram de fem Konungar till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'De gjorde ock så, och hade de fem Konungar till honom utu kulone: Konungen i Jerusalem, Konungen i Hebron, Konungen i Jarmuth, Konungen i Lachis, Konungen i Eglon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Då nu desse Konungar voro framledde till honom, kallade Josua hela Israel, och sade till de öfversta af krigsfolket, som med honom drogo: Kommer hit, och träder dessa Konungarna på halsen med fötterna; och de kommo fram, och trädde på deras halsar med fötterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Och Josua sade till dem: Frukter eder intet, och grufver eder intet; varer tröste och vid ett fritt mod; ty alltså skall Herren göra alla edra fiendar, som I emot striden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Och Josua slog dem sedan, och drap dem, och hängde dem i fem trä; och de hängde i trän allt intill aftonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Då solen var nedergången, böd han, att man skulle taga dem ned af trän, och kasta dem in i kulona, der de sig uti fördolt hade; och lade stora stenar för gapet af kulone, hvilke der ännu äro på denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'På den samma dagen vann ock Josua Makkeda, och slog det med svärdsegg, med dess Konung, och gaf det tillspillo, och alla de själar, som derinne voro, och lät ingen blifva igen; och gjorde dem Konungenom i Makkeda, såsom han hade gjort Konungenom i Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Så drog Josua, och hela Israel med honom, ifrå Makkeda till Libna, och stridde deremot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Och Herren gaf det också i Israels hand, med dess Konung; och han slog det med svärdsegg, och alla de själar, som derinne voro, och lät ingen blifva igen derinne; och gjorde dess Konung, såsom han hade gjort Konungenom i Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Sedan drog Josua, och hela Israel med honom, ifrå Libna till Lachis; belade och bestridde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Och Herren gaf desslikes Lachis i Israels händer, så att de vunno det på annan dagen, och slogo det med svärdsegg, och alla de själar som derinne voro, alldeles som han hade gjort i Libna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'På samma tiden drog Horam, Konungen i Geser, upp till att hjelpa Lachis; men Josua slog honom med allt hans folk, tilldess ingen igenblef.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Och Josua drog ifrå Lachis med hela Israel, intill Eglon, och belade och bestridde det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Och vann det på samma dag, och slog det med svärdsegg, och gaf tillspillo alla de själar, som derinne voro på samma dagen, alldeles såsom han hade gjort Lachis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Sedan drog Josua med hela Israel ifrån Eglon upp till Hebron, och bestridde det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Och vann det, och slog det med svärdsegg, och dess Konung med alla dess städer, och alla de själar, som derinne voro; och lät icke en igenblifva, alldeles såsom han hade gjort Eglon; och gaf det tillspillo, och alla de själar som derinne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Då vände Josua igen med hela Israel inåt Debir, och bestridde det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Och vann det med dess Konung, och alla dess städer, och slogo dem med svärdsegg, och gåfvo tillspillo alla de själar som derinne voro; och lät icke en igenblifva. Såsom han hade gjort Hebron, så gjorde han ock Debir och dess Konung, och såsom han hade gjort Libna och dess Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Alltså slog Josua allt landet på bergen, och söderut, och i dalarna, och vid bäckerna, med alla deras Konungar; och lät icke en igenblifva; och gaf tillspillo allt det som anda hade, såsom Herren Israels Gud budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Och slog dem allt ifrå KadesBarnea intill Gasa; och hela landet Gosen intill Gibeon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Och vann alla dessa Konungarna med deras land, allt med en ryck; ty Herren Israels Gud stridde för Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Och Josua drog åter i lägret till Gilgal med hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Då Jabin, Konungen i Hazor, detta hörde, sände han till Jobab, Konungen i Madon, och till Konungen i Achsaph,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Och till de Konungar, som bodde norrut uppå bergen, och uppå slättmarkene, söderut Cinneroth; och i dalarna, och i NaphotDor, utmed hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Till de Cananeer österut och vesterut, till de Amoreer, Hetheer, Phereseer, och Jebuseer uppå bergen; så ock till de Heveer nedanför Hermons berg i Mizpa land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Desse drogo ut med alla deras härar, dråpeliga mycket folk, såsom sanden i hafsstrandene; och ganska många hästar och vagnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Alle desse Konungar församlade sig, och kommo, och lägrade sig ihop vid det vattnet Merom, till att strida med Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Och Herren sade till Josua: Frukta dig intet för dem; ty i morgon på denna tiden skall jag gifva dem alla slagna för Israels barn; deras hästar skall du hasa, och bränna deras vagnar i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Och Josua kom hasteliga på dem, och allt krigsfolket med honom, vid vattnet Merom, och öfverföll dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Och Herren gaf dem i Israels händer; och de slogo dem, och jagade dem allt intill det stora Zidon, och intill det varma vattnet; och intill slätten i Mizpe österut, och slogo dem tilldess icke en igenblef.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Då gjorde Josua dem såsom Herren honom budit hade, och hasade deras hästar, och brände upp deras vagnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Och vände om på samma tiden, och vann Hazor, och slog dess Konung med svärd; ty Hazor var tillförene hufvudstaden för alla dessa Konungariken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Och slog alla de själar, som derinne voro, med svärdsegg, och gaf dem tillspillo; och lät intet igenblifva, som anda hade; och brände upp Hazor med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Dertill alla dessa Konungarnas städer vann Josua, med deras Konungar; och slog dem med svärdsegg, och gaf dem tillspillo, såsom Mose Herrans tjenare budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Dock uppbrände Israels barn inga städer med eld, som högt uppe lågo, förutan Hazor allena; det uppbrände Josua.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Och allt rofvet af dessa städerna, och boskapen, bytte Israels barn emellan sig; men alla menniskor slogo de med svärdsegg, tilldess de förgjorde dem, och läto intet igenblifva, som anda hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Såsom Herren sinom tjenare Mose, och Mose Josua budit hade, så gjorde Josua, att intet blef tillbaka af allt det Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Alltså intog Josua all denna landen på bergen, och allt det söderut ligger, och allt landet Gosen, och dalarna, och slättmarkena, och Israels berg med dess dalar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Allt ifrå berget, som åtskiljer landet uppåt emot Seir intill BaalGad, på bergsens Libanons slätt nedan vid Hermons berg; alla deras Konungar vann han, och slog dem, och drap dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Men han förde örlig med dessa Konungarna i långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Och var ingen stad, som sig gaf med frid under Israels barn, undantagna de Heveer, som bodde i Gibeon; utan de vunno dem alla med strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Och det skedde så af Herranom, att deras hjerta vardt förstockadt, till att möta Israels barn med strid; på det de skulle tillspillo komma, och dem ingen nåd vederfaras, utan förgöras, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'På den tiden kom Josua, och utrotade de Enakim utaf bergen af Hebron, af Debir, af Anab, af all Juda berg, och af all Israels berg, och gaf dem tillspillo med deras städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Och lät ingen Enakim igenblifva i Israels barnas land, förutan i Gasa, i Gath, och i Asdod; der blefvo de igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Alltså tog Josua allt landet in, alldeles såsom Herren hade sagt till Mose; och gaf det Israels barnom till arfs, hvarjo slägtene sin del. Och landet vände åter att strida.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Desse äro de Konungar i landena, som Israels barn slogo, och togo deras land in på hinsidon Jordan, österut: ifrån Arnons bäck intill Hermons berg, och hela marken österut:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, de Amoreers Konung, som bodde i Hesbon, och var rådandes ifrån Aroer, som på strandene ligger vid den bäcken vid Arnon, och midt i bäcken, och öfver hälft Gilead, intill den bäcken Jabbok, der Ammons barnas landamäre är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Och öfver den slättmarkena allt intill hafvet Cinneroth österut, och intill hafvet i slättmarkene, som är salthafvet österut, den vägen åt BethJesimoth; och ifrå sunnan neder utmed bäcken vid berget Pisga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Dertill Ogs gränso, Konungens i Basan, den ännu af de Resar qvar blifven var, och bodde i Astaroth och Edrei,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Och var rådandes öfver berget Hermon, öfver Salcha, och öfver hela Basan, allt intill Gessuri och Maachathi gränsor, och i halfva Gilead, hvilket var Sihons gränsa, Konungens i Hesbon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose Herrans tjenare, och Israels barn slogo dem, och Mose Herrans tjenare gaf dem de Rubeniter, Gaditer, och den halfva slägtene Manasse till att intaga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Men desse äro de Konungar i landena, som Josua slog, och Israels barn, på denna sidone Jordan, vesterut, ifrå BaalGad på Libanons bergs slätt, intill det berget som åtskiljer landet uppåt emot Seir, och det Josua Israels slägter gaf till att intaga, hvarjom och enom sin del;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Det som uppå bergen, dalomen, slättmarkene, vid bäcker, i öknene, och söderut var, de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Konungen i Jericho, Konungen i Aj, som vid sidona ligger af BethEl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Konungen i Jerusalem, Konungen i Hebron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Konungen i Jarmuth, Konungen i Lachis;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Konungen i Eglon, Konungen i Geser;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Konungen i Debir, Konungen i Geder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Konungen i Horma, Konungen i Arad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Konungen i Libna, Konungen i Adullam;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Konungen i Makkeda, Konungen i BethEl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Konungen i Tappnah, Konungen i Hepher;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Konungen i Aphek, Konungen i Lasaron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Konungen i Madon, Konungen i Hazor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Konungen i SimronMeron, Konungen i Achsaph;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Konungen i Thaanach, Konungen i Megiddo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Konungen i Kedes, Konungen i Jokneam på Charmel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Konungen i DorNaphotDor, Konungen för de Hedningar i Gilgal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Konungen i Tirza. Det äro en och tretio Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Då nu Josua vardt gammal, och väl till ålders, sade Herren till honom: Du äst gammal vorden, och väl till ålders, och landet är ännu mycket qvart, som intagas skall:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Nämliga hela landet de Philisteers och hela Gessuri,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Ifrå Sichor, som löper framom Egypten, allt intill Ekrons landsändar norrut, hvilka de Cananeer tillräknas; fem de Philisteers herrar, nämliga de Gasiter, de Asdod i ter, de Askaloniter, de Gittiter, de Ekroniter, och de Aviter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Men ifrå söder är hela de Cananeers land, och Mearah de Zidoniers, allt intill Aphek, och till de Amoreers landsändar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Dertill de Gibliters land, och hela Libanon österut, ifrå BaalGad nedanför berget Hermon, tilldess man kommer till Hamath;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Alle de som på bergen bo, ifrå Libanon intill det varma vattnet, och alle Zidonier; jag skall fördrifva dem för Israels barn; kasta lott derom, till att utskifta dem emellan Israel, såsom jag hafver budit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Så skift nu denna landen emellan de nio slägter till arfs, och emellan den halfva slägten Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Ty de Rubeniter och Gaditer hafva med den andra halfva Manasse undfått deras arfvedel, som Mose dem gaf på hinsidon Jordan österut, såsom Herrans tjenare Mose dem det gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Ifrån Aroer, som ligger på bäcksens strand vid Arnon, och ifrå den staden midt i bäcken, och all den ängden Medeba allt intill Dibon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Och alla Sihons, de Amoreers Konungs, städer, som satt i Hesbon, allt intill Ammons barnas landsändar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Dertill Gilead, och de landsändar vid Gessuri och Maachati, och hela berget Hermon, och hela Basan, allt intill Salcha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Hela Ogs rike i Basan, den i Astaroth och Edrei satt, hvilken ännu igen var af de Resar; men Mose slog dem, och fördref dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Men Israels barn fördrefvo icke dem i Gessur, och i Maachath: utan de bodde, både Gessur och Maachath, ibland Israels barn allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Men de Leviters slägte gaf han ingen arfvedel; ty Herrans Israels Guds offer är deras arfvedel, såsom han dem sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Så gaf Mose Rubens barnas slägte, efter deras ätter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Så att deras landsändar voro ifrån Aroer, som ligger på bäcksens strand vid Arnon, och den staden midt i bäcken, med alla slättmarkene intill Medeba;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon och alla dess städer, som ligga på slättmarkene, Dibon, BamothBaal, och BethBaalMeon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahza, Kedemoth, Mephaath,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kiriathaim, Sibma, SerethSahar uppå berget Emek,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'BethPeor, de bäcker vid Pisga, och BethJesimoth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Och alla de städer på slättmarkene; och hela Sihons, de Amoreers Konungs, rike, som satt i Hesbon, den Mose slog med de Förstar i Midian, Evi, Rekem, Zur, Hur och Reba, hvilke Konung Sihons höfvitsmän voro, som i landena bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Dertill Bileam, Beors son, den spåmannen, slogo Israels barn med svärd, samt med de andra dräpna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Och landamäret till Rubens barn var Jordan. Detta är nu Rubens barnas arfvedel i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Gads barnas slägte, efter deras ätter, gaf Mose,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Så att deras landsändar voro Jaeser, och alla de städer i Gilead, och hälft Ammons barnas land, allt intill Aroer, som ligger för Rabbah;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Och ifrå Hesbon intill RamathMizpe och Betonim; och ifrå Mahanaim allt intill Debirs landsändar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Men i dalenom, BethHaram, BethNimra, Succoth och Zaphon, som qvart var af Sihons rike, Konungens i Hesbon, hvilkets gränsa var Jordan, allt intill ändan af hafvet Cinnereth, på denna sidone Jordan, österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Detta är nu Gads barnas arfvedel, i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Den halfva Manasse barnas slägt, efter deras ätter, gaf Mose,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Så att deras landsändar voro ifrå Mahanaim, hela Basan; hela Ogs rike, Konungens i Basan, och alla Jairs byar, som i Basan ligga, nämliga sextio städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Och halfva Gilead, Astaroth, Edrei, Ogs rikes städer i Basan, gaf han Machirs Manasse sons barnom, det är, hälftena af Machirs barnom, efter deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Detta är det som Mose utskifte uppå Moabs mark, hinsidon Jordan in mot Jericho, österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Men Levi slägte gaf Mose ingen arfvedel; ty Herren Israels Gud är deras arfvedel, såsom han dem sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Detta är nu det som Israels barn intogo i Canaans lande, hvilket dem emellan utskifte Presten Eleazar, och Josua, Nuns son, och de öfverste fader i Israels barnas slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Och de skifte det emellan sig med lott, såsom Herren budit hade genom Mose, att gifva de halftionde slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Ty de två slägterna, och den halfva; hade Mose gifvit arfvedel hinsidon Jordan; men Leviterna hade han ingen arfvedel gifvit ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Ty Josephs barn vordo två slägter, Manasse och Ephraim; derföre gåfvo de Leviterna ingen del i landena, utan städer, der de skulle bo uti, och förstäder för deras boskap, och håfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Såsom Herren hade budit Mose, så gjorde Israels barn, och skifte landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Då gingo Juda barn fram till Josua i Gilgal; och Caleb, Jephunne son, den Kenisiten, sade till honom: Du vetst hvad Herren sade till den Guds männen Mose, på mina och dina vägnar, i KadesBarnea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Jag var fyratio åra gammal, när Mose Herrans tjenare mig utsände ifrå KadesBarnea, till att bespeja landet; och jag sade honom igen efter mitt samvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Men mine bröder, som med mig uppgångne voro, gjorde folkena ett förskräckt hjerta; men jag följde Herran min Gud troliga efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Då svor Mose på den samma dagen, och sade: Det landet, som du på trädt hafver med din fot, skall vara din och dina barnas arfvedel till evig tid; derföre, att du Herran min Gud troliga efterföljt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Och nu, si, Herren hafver låtit mig lefva, såsom han sagt hade; det är nu fem och fyratio år, sedan Herren detta sade till Mose, då Israel vandrade i öknene; och si, jag är nu på denna dag fem och åttatio åra gammal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Och är ännu i dag så stark, som jag var på den dagen, då Mose sände mig ut; såsom min magt var på den tiden, så är hon ännu, till att strida och till att gå ut och in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Så gif mig nu detta berget, om hvilket Herren sade på den dagen; ty du hörde det på den tiden, att de Enakim bo deruppå, och äro store och faste städer, om Herren ville vara med mig, att jag kunde fördrifva dem, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Då välsignade Josua honom, och gaf så Caleb, Jephunne son, Hebron till arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Deraf vardt Hebron Calebs, Jephunne sons, den Kenisitens arfvedel, allt intill denna dag; derföre, att han hade troliga efterföljt Herran Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Men Hebron kallades i förtiden KiriathArba, den en stor man var ibland de Enakim. Och landet hade återvändt örliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juda barnas slägtes lott, efter deras ätter, var in emot Edoms landsändar, vid den öknen, Zin, som söderut stöter inpå söderlanden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Så att deras södergränsor voro ifrån andanom af salthafvet, det är, ifrå den tungone som drager söderåt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Och går dädan uppåt Akrabbim, och går igenom Zin, och går uppåt ifrå sunnan intill KadesBarnea; och går igenom Hezron, och går uppåt Adar, och böjer sig omkring Karkaa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Och går igenom Azmon, och kommer ut vid Egypti bäck, så att änden af den gränson varder hafvet. Detta äro nu edra gränsor söderut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Men östergränsen är salthafvet intill Jordans ända. Den norra gränsan är ifrå hafsens tungo, som är vid Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Och går uppåt intill BethHogla, och drager sig ifrå nordan intill BethAraba, och går uppåt till Bohans sten, Rubens sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Och går uppåt till Debir ifrån Achors dal, och ifrå norra sidone, som vet åt Gilgal, det tvärtöfver ligger vid Adummim uppåt, hvilket sunnantill ligger vid bäcken; sedan går hon uppåt till det vattnet EnSemes, och går ut vid den brunnen Rogel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Sedan går hon uppåt till Hinnoms sons dal, vid den Jebuseens sido, som bor söderut, det är Jerusalem; och går uppåt öfver bergsklinten, som ligger för den dalen Hinnom vesterut, hvilken stöter inpå sidona af Rephaims dal norrut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Sedan går hon ifrå den samma bergsklinten, intill den vattubrunnen Nephtoah, och går ut till de städer vid Ephrons berg, och böjer sig åt Baala, det är KiriathJearim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Och går omkring ifrå Baala vesterut intill berget Seir, och går utmed sidone af det berget Jearim ifrå nordan, det är Chesalon, och kommer neder till BethSemes, och går igenom Thimna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Och kommer ut vid sidona af Ekron norrut, och drager sig inåt Sichron, och går öfver det berget Baala, och kommer ut vid Jabneel; så att hennes yttersta är hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Den gränsan vesterut är det stora hafvet. Detta är nu Juda barnas gränsor allt omkring i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Men Caleb, Jephunne son, vardt gifvet hans del ibland Juda barn, efter som Herren hade befallt Josua; nämliga KiriathArba, Enaks faders, det är Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Och Caleb fördref dädan de tre Enaks söner, Sesai, Ahiman och Thalmai, Enaks afföda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Och drog dädan uppåt till Debirs inbyggare; och Debir het tillförene KiriathSepher.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Och Caleb sade: Den som slår KiriathSepher, och vinner det, honom vill jag gifva mina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Då vann det Athniel, Kenas son, Calebs broders; och han gaf honom sina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Och det begaf sig, då hon indrog, vardt henne rådet, att bedas en åker af sinom fader; och hon gaf sig ifrån åsnan. Då sade Caleb till henne: Hvad är dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Hon sade: Gif mig en välsignelse; ty du hafver gifvit mig ett söderland, gif mig ock vattukällor; så gaf han henne källor ofvan och nedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Detta är nu Juda slägtes arfvedel i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Och Juda barnas slägtes städer ifrå den ena sidone till den andra, utmed de Edomeers gränsor söderut, voro desse: Kabzeel, Eder, Jagur,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, AdAda,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hazor, Jithnan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealoth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'HazorHadatta, Kerioth, Hezron, det är Hazor,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Aman, Serna, Molada,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'HazarGadda, Hesmon, BethPalet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'HazarSual, BerSeba, Bisjothja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Jjim, Azem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltholad, Chesil, Horma,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziklag, Madmanna, Sansanna,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth, Silhim, Ain, Rimmon. Det äro nio och tjugu städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Men i dalarna voro Esthaol, Zorga, Asna,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Sanoah, EnGannim, Tappuah, Enam,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth, Adullam, Socho, Aseka,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Adithaim, Gedera, Gederothaim. Det äro fjorton städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, MigdalGad,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Mizpe. Joktheel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis, Bozkath, Eglon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chabbon, Lahmas, Cithlis,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederoth, BethDagon, Naama, Makkeda. Det äro sexton städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Ether, Asan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiphthah, Asna, Nesib,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Achsib, Maresa. Det äro nio städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron med dess döttrar och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Ifrån Ekron och intill hafvet, allt det som räcker intill Asdod, och dess byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod med dess döttrar och byar, Gaza med dess döttrar och byar intill Egypti bäck, och det stora hafvet är gränsan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Men uppå berget var Samir, Jathir, Socho,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, KiriathSanna, det är Debir,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Anim,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon, Gilo. Det äro ellofva städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esean,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, BethTappuah, Apheka,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, KiriathArba, det är Hebron, Zior. Det äro nio städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Carmel, Siph, Jutta,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jesreel, Jokedam, Sanoah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea, Thimna. Det äro tio städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Bethzur, Gedor,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarath, BethAnoth, Elthekon. Det äro sex städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'KiriathBaal, det är KiriathJearim, Rabba; två städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Men i öknene voro, BethAraba, Middin, Sechacha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, och den saltstaden, och EnGedi. Det äro sex städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Men de Jebuseer bodde i Jerusalem, och Juda barn kunde icke fördrifva dem; alltså blefvo de Jebuseer med Juda barnom i Jerusalem allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Och Josephs barnom föll lotten till ifrå Jordan, in mot Jericho, allt intill vattnet vid Jericho ifrån östan, och öknen, som går uppifrå Jericho genom det berget BethEl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Och går ut ifrå BethEl till Lus, och går igenom den gränson ArchiAtaroth;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Och drager sig nederåt vesterut, till den gränson Japhleti, allt intill den nedra Bethorons gränso, och allt intill Gaser; och dess ände är vid hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Detta fingo nu Josephs barn till arfvedel, Manasse och Ephraim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Ephraims barnas gränsa i deras ätter till deras arfvedel ifrån östan var AtarothAddar, allt intill det öfra BethHoron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Och går ut vesteråt vid Michmethath, som norrut ligger, der böjer det sig omkring öster om den staden ThaanathSilo; och går ifrån östan inåt Janoha;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Och kommer neder ifrå Janoha till Ataroth, och Naaratha, och stöter inpå Jericho, och går ut vid Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Ifrå Tappuah går hon vesterut till NahalKana, och hennes utgång är i hafvet. Detta är nu Ephraims barnas slägtes arfvedel, till deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Och alle Ephraims barnas gränsostäder med deras byar, lågo förströdde ibland Manasse barnas arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Och de fördrefvo icke de Cananeer, som bodde i Gaser; så blefvo då de Cananeer ibland Ephraim allt intill denna dag, och vordo skattskyldige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Och lotten föll till Manasse slägte, den Josephs förste son var, och föll till Machir, Manasse första son, Gileads fader; ty han var en god stridsman, derföre fick han Gilead och Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dem androm Manasse barnom uti deras ätter föll också till, nämliga: Abiesers barnom, Heleks barnom, Asriels barnom, Sechems barnom, Hephers barnom, och Semida barnom. Desse äro Manasse barn, Josephs sons, som mankön voro i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Men Zelaphehad, Hephers son, Gileads sons, Machirs sons, Manasse sons, hade inga söner, utan döttrar; och deras namn äro desse: Mahela, Noa, Hogla, Milca, Thirza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Och de gingo fram för Presten Eleazar, och för Josua, Nuns son, och för de örversta, och sade: Herren böd Mose, att han skulle gifva oss arfvedel ibland våra bröder; så gaf han dem ock arfvedel ibland deras faders bröder, efter Herrans befallning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Men Manasse föllo tio snöre till, förutan det landet Gilead och Basan, som på hinsidon Jordan ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Ty Manasse döttrar togo arfvedel med hans söner; och det landet Gilead kom de andra Manasse barn till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Och Manasse gränsa var ifrån Asser till Michmethath, som ligger för Sechem, och går ut på högra handena intill dem af EnTappuah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Ty det landet Tappuah kom Manasse till, och är Manasse gränsa invid Ephraims barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Sedan går hon neder till NahalKana söderut till bäckstäderna, hvilka Ephraim tillhöra ibland Manasse städer; men ifrå nordan är Manasse gränsa inpå bäcken, och går ut i hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Ephraims söderut, och Manasse norrut, och hafvet är hans landamäre, och stöter inpå Asser ifrå nordan, och inpå Isaschar ifrån östan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Så hade nu Manasse ibland Isaschar och Asser, BethSean och dess döttrar, Jibleam och dess döttrar, och dem i Dor och dess döttrar, och dem i Endor och dess döttrar, och dem i Thaanach och dess döttrar, och dem i Megiddo och dess döttrar, och tredje delen Naphet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Och Manasse barn kunde icke intaga de städer; utan de Cananeer begynte till att bo i dessa landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Men då Israels barn vordo mägtige, gjorde de de Cananeer skattskyldiga, och fördrefvo dem icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Då talade Josephs barn till Josua, och sade: Hvi hafver du icke gifvit mig mer än en lott, och ett snöre af arfvedelenom, och jag är dock ett mycket folk, såsom Herren hafver välsignat mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Då sade Josua till dem: Efter du äst ett mycket folk, så gack upp i skogen, och rödj dig der rum uti de Phereseers och Resars land, efter Ephraims berg är dig för trångt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Då sade Josephs barn: Berget kunne vi icke få; ty de Cananeer bruka alle jernvagnar, som i de landena Emek bo, när hvilko ligger BethSean och dess döttrar, och Jisreel i Emek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Josua sade till Josephs hus, Ephraim och Manasse: Du äst ett mycket folk; och efter du så mycket äst, måste du icke hafva en lott;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Utan berget skall höra dig till, der skogen är; der rödj om dig, så blifver det dins lotts ände, när du fördrifver de Cananeer, som jernvagnar hafva och mägtige äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Och hela menigheten af Israels barn församlade sig i Silo, och der uppsatte de vittnesbördsens tabernakel; och landet var dem undergifvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Och voro ännu sju slägter af Israels barn, hvilkom deras del icke utskift var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Och Josua sade till Israels barn: Huru länge viljen I vara så late, att I icke gån åstad, och tagen landet in, som Herren edra fäders Gud eder gifvit hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Tager eder af hvarjo slägtene tre män, att jag må sända dem, och de stå upp, och gå igenom landet, och beskrifva det efter deras arfvedelar, och komma till mig igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Skifter landet i sju delar: Juda skall blifva vid sina gränsor sunnanefter; och Josephs hus skall blifva vid sina gränsor nordanefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Men I, beskrifver de sju delars land, och bärer det hit till mig, så vill jag kasta eder lott för Herranom vårom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Ty Leviterna hafva ingen del ibland eder, utan Herrans Presterskap är deras arfvedel; men Gad och Ruben, och den halfva slägten Manasse, hafva tagit sin del på hinsidon Jordan österut, den Mose Herrans tjenare dem gaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Då stodo de män upp, och foro åstad; och Josua böd dem, då de gå ville till att beskrifva landet, och sade: Vandrer igenom landet, och beskrifver det, och kommer igen till mig, att jag må kasta eder lott för Herranom i Silo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Så gingo männerna åstad, och drogo landet igenom, och beskrefvo det på en skrift efter städerna i sju delar; och kommo till Josua i lägret igen i Silo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Då kastade Josua lotten öfver dem i Silo för Herranom, och skifte der landet ut ibland Israels barn, hvarjom och enom sin del.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Och föll BenJamins barnas slägtes lott efter deras ätter, och vardt deras lotts gränsa emellan Juda barn och Josephs barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Och deras gränsa var på sidone norrut ifrå Jordan, och går uppåt utmed Jericho på norra sidone, och kommer upp på berget vesterut; och utgången är vid den öknen BethAven;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Och går dädan intill Lus, utmed sidone på Lus söderut, det är BethEl; och går nederåt intill AtharothAdar vid berget, som ligger sunnan vid det nedra BethHoron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Och går neder, och böjer sig omkring till vestra sidona söderut ifrå berget, som ligger för BethHoron söderut; och går ut vid KiriathBaal, det är KiriathJearim, Juda barnas stad. Detta är nu den sidan vesterut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Men den sidan söderut är ifrå KiriathJearim, och går ut emot vester, och kommer ut till vattubrunnen Nephtoah:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Och går neder vid ändan på berget, som ligger för Hinnoms sons dal, den der ligger i Naphaims dal norrut, och går neder genom Hinnoms dal på de Jebuseers sido, sunnantill, och kommer neder vid den brunnen Rogel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Och drager sig ifrå nordan, och kommer ut till EnSemes, och kommer ut till de högar, som ligga uppe emot Adummim, och kommer ned till Bohens sten, Rubens sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Och går utmed sidone vid slättmarkena, som ligger norrut, och kommer neder på slättmarkena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Och drager utmed den sidone vid BethHogla, som ligger norrut, och änden deraf vid salthafsens tungo norrut, inpå Jordans södra ända. Detta är nu den södra gränsan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Men till den östra sidan skall Jordan vara änden. Detta är nu BenJamins arfvedel i deras gränsor allt omkring, i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Men städerna BenJamins barnas slägters, ibland deras ätter, äro desse: Jericho, BethHogla, EmekKeziz,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'BethAraba, Zemaraim, BethEl,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Para, Ophra,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'CepharAmmonai, Ophni, Gaba. Det äro tolf städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beeroth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mizpe, Cephira, Moza,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Thareala,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Eleph, och de Jebuseer, det är Jerusalem, Gibeath, Kiriath; fjorton städer, och deras byar. Detta är nu BenJamins barnas arfvedel i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Sedan föll den andre lotten Simeons barnas slägtes, efter deras ätter; och deras arfvedel var ibland Juda barnas arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Och kom på deras arfvedel BerSeba, Seba, Molada,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'HazarSual, Bala, Azem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Bethul, Horma,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziklag, BethMarkaboth, HazarSusa,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'BethLebaoth, Saruhen. Det äro tretton städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Ether, Asan. Det äro fyra städer och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Dertill alla byar, som ligga omkring dessa städerna, allt intill BaalathBer, Ramath söderut. Detta är Simeons barnas arfvedel i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Ty Simeons barnas arfvedel är ibland Juda barnas snöre; efter Juda barnom var deras arfvedel för stor; derföre fingo Simeons barn del ibland deras arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Tredje lotten föll på Sebulons barn efter deras ätter; och deras arfvedels gränsa var allt intill Sarid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Och går uppåt vesterut till Marala, och stöter inpå Dabbaseth, och stöter inpå bäcken, som löper framom Jokneam;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Och vänder sig ifrå Sarid österut, allt intill den gränsan CislothThabor; och går ut till Dabberath, och räcker upp till Japhia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Och löper dädan österåt igenom GittaHepher, IttaKazin, och kommer ut till Rimmon, Hammethoar, Hannea;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Och böjer sig omkring ifrå nordan inåt Nathon; och utgången är i den dalen JiphtaEl;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattath, Nahalal, Simron, Jideala och BethLehem. Det äro tolf städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Detta är nu Sebulons barnas arfvedel till deras ätter; och detta är deras städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Fjerde lotten föll på Isaschars barn efter deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Och deras gränsa var Jisreel, Chesulloth, Sunem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharaim, Sion, Anaharath,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbith, Kisjon, Abez.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, EnGannim, EnHadda, BethPazzez;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Och stöter inpå Thabor, Sahazima, BethSemes, och utgången deraf var inuppå Jordan; sexton städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Detta är nu Isaschars barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Femte lotten föll på Assers barnas slägte i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Och deras gränsa var Helkath, Hali, BetenAchsaph,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelech, Amead, Miseal; och stöter inpå Carmel vid hafvet, och till SihorLibnath;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Och vänder sig österut till BethDagon, och stöter inpå Sebulon, och till den dalen JiphthahEl norrut, BethEmek, Negiel, och kommer ut vid Cabul på venstra sidone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebron, Rehob, Hammon, Kana, allt intill det stora Zidon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Och vänder sig inåt Rama, allt intill den fasta staden Zor; och vänder sig åt Hosa, och går ut vid hafvet efter snöret åt Achsib;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Aphek, Rehob; två och tjugu städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Detta är nu Assers barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Sjette lotten föll på Naphthali barn i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Och deras gränsa var ifrå Heleph, Allon, igenom Zaanannim, Adami, Nekeb, JabneEl, allt intill Lakum, och går ut inpå Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Och vänder sig vesterut åt Asnoth Thabor; och kommer dädan ut och till Hukkob, och stöter inpå Sebulon söderut, och till Assur vesterut, och till Juda invid Jordan österut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Och hafver fasta städer, Ziddim, Zer, Hammath, Rakkath, Chinnareth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hazor,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, EnHazor,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, MigdalEl, Horem, BethAnath, BethSames; nitton städer, och deras byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Detta är nu Naphthali barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Sjunde lotten föll på Dans barnas slägte i deras ätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Och gränsan af deras arfvedel var: Zorga, Esthaol, IrSames,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Ajalon, Jithla,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnatha, Ekron,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Eltheke, Gibbethon, Baalath,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Benebarak, GrathRimmon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'MeJarkon, Rakkon med den gränsona vid Japho;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Och der går Dans barnas gränsa ut. Och Dans barn drogo upp, och stridde emot Lesem och vunno det, och slogo det med svärdsegg; och togo det in, och bodde deruti, och kallade det Dan, efter deras faders namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Detta är nu Dans barnas slägtes arfvedel i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Och då de hade lyktat utskifta landet med dess gränsor, gåfvo Israels barn Josua, Nuns son, en arfvedel ibland sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Och gåfvo honom efter Herrans befallning den stad, som han begärade, som var ThimnathSerah uppå Ephraims berg; den staden byggde han, och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Desse äro nu de arfvedelar, som Eleazar Presten, och Josua, Nuns son, och de öfverste af fäderna ibland släkterna, genom lott utskifte Israels barnom i Silo för Herranom, inför dörrene af vittnesbördsens tabernakel; och lyktade så landsens utskiftning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Och Herren talade med Josua, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Säg Israels barnom: Skicker ibland eder några fristäder, om hvilka jag eder genom Mosen sagt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Att dit må fly en mandråpare, som slår en själ oförvarandes och ovetandes; att de må ibland eder fri vara för blodhämnaren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Och den som flyr till någon af de städer, han skall stå utanför stadsporten, och för de äldsta i staden förtälja sin sak; så skola de taga honom in i staden till sig, och få honom rum, att han må bo när dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Och om blodhämnaren kommer efter honom, skola de icke öfverantvarda dråparen i hans händer, efter han oförvarandes slog sin nästa, och var icke tillförene hans ovän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Så skall han bo i stadenom, tilldess han står för menighetene till rätta, allt intilldess öfverste Presten dör, som på den tiden är; då skall dråparen komma till sin stad igen, och i sitt hus i stadenom, der han utflydder var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Då helgade de Kedes i Galilea på Naphthali berg, och Sechem på Ephraims berg, och KariathArba, det är Hebron, på Juda berg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Och på hinsidon Jordan vid Jericho Österut skickade de Bezer i öknene på slättmarkene, af Rubens slägte; och Ramoth i Gilead, af Gads slägte, och Golan i Basan, af Manasse slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Det voro då de städer, som Israels barnom förelagde voro, och främlingomen som ibland dem bodde, att dit skulle fly den som en själ oförvarandes sloge; att han icke skulle ihjälslås af blodhämnaren, intilldess han hade ståndit för menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Då trädde de öfverste fäder ibland Leviterna fram för Presten Eleazar, och för Josua, Nuns son, och för de öfversta fäder ibland Israels barnas slägte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Och talade med dem i Silo i Canaans land, och sade: Herren hafver budit genom Mose, att man skulle gifva oss städer till att bo uti, och deras förstäder till vår boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Så gåfvo då Israels barn Leviterna utaf deras arfvedelar, efter Herrans befallning, dessa städer och deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Och lotten föll uppå de Kehathiters ätt; och kommo Aarons barnom Prestens af Leviterna tretton städer till, igenom lotten; af Juda slägte, af Simeons slägte, och af BenJamins slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Men de andra Kehats barnom af samma ätt kommo tio städer till, igenom lotten; af Ephraims slägte, af Dans slägte, och af den halfva slägtene Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Men Gersons barnom af samma ätt kommo tretton städer till, igenom lotten; af Isaschars slägte, af Assers slägte, och af Naphthali slägte, och af den halfva slägtene Manasse i Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merari barnom till deras ätter kommo tolf städer till; af Rubens slägte, af Gads slägte, och af Sebulons slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Alltså gåfvo Israels barn Leviterna igenom lotten dessa städer, och deras förstäder, såsom Herren genom Mose budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Af Juda barnas slägte, och af Simeons barnas slägte, gåfvo de dessa städerna, hvilka de nämnde efter deras namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Aarons barnom af de Kehathiters ätt, af Levi barnom; ty förste lotten var deras;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Så gåfvo de dem nu KiriathArba, den Enaks fader var, det är Hebron, på Juda berg, och dess förstäder allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Men stadsens åker, och hans byar gåfvo de Caleb, Jephunne son, till hans arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Så gåfvo de Prestens Aarons barnom den mandråpares fristad Hebron, och hans förstäder; Libna, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jathir, och dess förstäder; Estemoa, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon, och dess förstäder; Debir, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain, och dess förstäder; Jutta, och dess förstäder; BethSemes, och dess förstäder; nio städer af dessa två slägterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Af BenJamins slägte gåfvo de fyra städer: Gibeon, och dess förstäder; Geba och dess förstäder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth, och dess förstäder; Aimon, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Så att alle Aarons Prestens barnas städer voro tretton, med deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Men de andra Kehats Levitens barnas ätter kommo fyra städer till, igenom deras lott, af Ephraims slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Och de gåfvo dem den mandråpares fristaden Sechem, och hans förstäder på Ephraims berg; Geser, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibzaim, och dess förstäder; BethHoron, och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Af Dans slägte fyra städer: Eltheke, och dess förstäder; Gibbethon, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon, och dess förstäder; GathRimmon, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Af den halfva slägtene Manasse två städer: Thaenach, och dess förstäder; GathRimmon, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Så att alla de andra Kehats ätts barnas städer voro tio, med deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Men Gersons barnom af de Leviters ätter vordo gifne af den halfva slägtene Manasse, två städer, den mandråpares fristaden Golan i Basan, med dess förstäder; Beestera, och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Af Isaschars slägte fyra städer: Kision, och dess förstäder; Dabrath, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth, och dess förstäder; EnGannim, och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Af Assers slägte fyra städer: Miseal, och dess förstäder; Abdon, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath, och dess förstäder; Rehob, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Af Naphthali slägte tre städer: den mandråpares fristaden Kedes i Galilea, och dess förstäder: HamothDor, och dess förstäder; Karthan, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Så att alle Gersoniters ätts städer voro tretton, med deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Men Merari barnom, de andra Leviterna vardt gifvet, af den slägten Sebulon, fyra städer: Jokneam, och dess förstäder; Kartha, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna, och dess förstäder; Nahalal, och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Af Rubens slägte fyra städer: Bezer, och dess förstäder; Jahza, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth, och dess förstäder; Mephaath, och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Af Gads slägte fyra städer: den mandråpares fristaden Ramoth i Gilead, och dess förstäder; Mahanaim, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon, och dess förstäder; Jaeser, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Så att alle Merari barnas, de andra Leviternas städer, ibland deras ätter, efter deras lott, voro tolf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Alle Leviternas städer, ibland Israels barnas arf, voro åtta och fyratio, med deras förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Och hvar och en af dessa hade sin förstad om sig; den ene som den andre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Alltså gaf Herren Israels barnom allt landet, som han svorit hade deras fäder att gifva: och de togo det in, och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Och Herren lät dem hafva ro för allom omkring dem, såsom han deras fäder svorit hade. Och ingen af deras fiendar stod emot dem; utan alla deras fiendar gaf Herren i deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Och felade intet af det goda, som Herren Israels hus tillsagt hade; utan det skedde så allt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Då kallade Josua till sig de Rubeniter och Gaditer, och den halfva slägtena Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Och sade till dem: I hafven hållit allt det Mose Herrans tjenare eder budit hafver, och lydt mine röst i allt det jag hafver budit eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'I hafven icke öfvergifvit edra bröder nu i en lång tid, allt intill denna dag; och hafven blifvit vid Herrans edars Guds bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Efter nu Herren edar Gud hafver låtit edra bröder komma till ro, såsom han dem sagt hade; så vänder nu om igen, och drager till edra hyddor i edars arfs land, som Mose Herrans tjenare eder gifvit hafver på hinsidon Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Allenast tager der vara uppå granneliga, att I gören efter de bud och lag, som Mose Herrans tjenare eder budit hafver; att I älsken Herran edar Gud, och vandren uppå alla hans vägar, och hållen hans bud, och hållen eder intill honom, och tjenen honom af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Så välsignade Josua dem, och lät gå dem; och de gingo till deras hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Den halfva slägtene Manasse hade Mose gifvit i Basan; den andra hälftene gaf Josua ibland deras bröder på desso sidone Jordan, vestantill. Och då han lät dem gå till deras hyddor, och hade välsignat dem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Sade han till dem: I kommen hem igen med stora ägodelar till edra hyddor, med ganska mycken boskap, silfver, guld, koppar, jern och kläder; så skifter nu edra fiendars rof med edra bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Och så vände de Rubeniter och Gaditer, och den halfva slägten Manasse, om igen, och gingo ifrån Israels barn af Silo, som i Canaans land ligger, att de skulle draga in i Gileads land till deras arfs land, det de till arfs fått hade af Herrans befallning genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Och då de kommo till de högar vid Jordan, som i Canaans land ligga, byggde de samme Rubeniter, Gaditer, och halfva Manasse slägt, der vid Jordan ett stort skönt altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Då Israels barn hörde sägas: Si, Rubens barn, Gads barn, och den halfva slägten Manasse hafva byggt ett altare emot Canaans land, vid Jordans högar, på desso sidone vid Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Församlade de sig hela menigheten i Silo, att de skulle draga upp till dem, och strida med dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Och sände till dem in uti Gileads land, Pinehas, Eleazars Prestens son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Och med honom tio öfversta Förstar ibland deras fäders hus, af hvarjo Israels slägt en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Och när de kommo till dem i landet Gilead, talade de med dem, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Så låter hela Herrans menighet säga eder: Hvi synden I så emot Israels Gud; och vänden eder i dag ifrå Herranom, dermed att I byggen eder ett altare, och fallen ifrå Herranom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Är oss icke nog med Peors missgerning, af hvilko vi ännu på denna dag icke renade äre; och en plåga kom i Herrans menighet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Och I vänden eder i dag bort ifrå Herranom, och ären i dag affällige vordne ifrå Herranom; på det han i dag eller morgon skall vredgas öfver hela Israels menighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Tycker eder, att edart arfs land är orent, så kommer hitöfver i det land, som Herren hafver, der Herrans tabernakel är, och tager arf ibland oss; och träder icke ifrå Herranom, och ifrån oss, att I byggen eder ett altare, förutan Herrans vårs Guds altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Förbröt icke Achan, Serahs son, sig på det spillgifna; och vreden kom öfver hela Israels menighet, och han umgalt icke sina synd allena?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Då svarade Rubens barn, och Gads barn, och den halfva slägten Manasse, och sade till de höfvitsmän och Förstar af Israel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Herren den starke Gud, Herren den starke Gud vet det, och Israel desslikes; är detta afträdning eller synd emot Herran, så hjelpe han oss intet i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Och om vi altaret fördenskull byggt hafve, att vi vilje vända oss ifrå Herranom, offra deruppå bränneoffer och spisoffer, eller göra der tackoffer uppå, så hämnes det Herren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Och om vi icke det mycket heldre för denna sakens skull gjorde, och sade: I dag eller morgon måtte edor barn säga till vår barn: Hvad hafven I göra med Herranom Israels Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Herren hafver satt Jordan till ett landamäre emellan oss och eder; I Rubens och Gads barn, I hafven ingen del med Herranom; och så måtte edor barn komma vår barn ifrå Herrans fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Derföre sade vi: Låt oss bygga ett altare, icke till något offer eller bränneoffer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Utan på det att det må vara ett vittnesbörd emellan oss och eder, och våra efterkommande, att vi måge tjena Herranom för honom med vårt bränneoffer, tackoffer och annor offer; och edor barn icke behöfva i dag eller morgon säga till vår barn: I hafven ingen del med Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'När de nu vordo sägande till oss, eller våra efterkommande i dag eller morgon, så kunna de säga: Ser liknelsen till Herrans altare, hvilket våre fäder gjort hafva; icke till offer eller bränneoffer, utan till ett vittnesbörd emellan oss och eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Bort det ifrån oss, att vi skulle träda ifrå Herranom, så att vi i dag skulle vända oss ifrå Herranom, och bygga ett altare till bränneoffer, och till spisoffer, och annor offer, förutan Herrans vårs Guds altare, som står för hans tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Då nu Pinehas Presten, och de öfverste för menighetene, Israels Förstar, som med honom voro, detta hörde, täcktes dem väl Rubens barnas, Gads, och den halfva Manasse slägts ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Och Pinehas, Prestens Eleazars son, sade till Rubens, Gads, och Manasse barn: I dag förstå vi, att Herren är med oss, att I icke hafven syndat emot Herran med denna gerning; nu hafven I frälst Israels barn utu Herrans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Så drog Pinehas, Prestens Eleazars son, och de öfverste, utu Gileads land, ifrå Rubens och Gads barn, åter in uti Canaans land, till Israels barn, och sade dem det igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Då behagade det Israels barnom väl, och lofvade Israels barnas Gud; och sade intet mer, att de ville draga upp emot dem till slags, till att förderfva landet, som Rubens och Gads barn uti bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Och Rubens och Gads barn kallade det altaret, att det skall vara ett vittne emellan oss, och att Herren är Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Efter lång tid, sedan Herren hade låtit Israel komma till ro för alla deras fiendar omkring sig; och Josua nu gammal och väl till ålders kommen var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Kallade han till sig hela Israel, och deras äldsta, höfvitsmän, domare och ämbetsmän, och sade till dem: Jag är gammal och väl till ålders;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Och I hafven sett allt det Herren edar Gud gjort hafver på all dessa folken här för eder; ty Herren edar Gud hafver sjelf stridt för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Ser, jag hafver utskift eder de folk, som ännu qvare äro, genom lott, hvarjo slägtene sin arfvedel, allt ifrå Jordan, och all de folk, som jag utrotat hafver; och ifrå stora hafvet vesterut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Och Herren edar Gud skall utdrifva dem för eder, och utrota dem ifrån eder, så att I skolen intaga deras land, såsom Herren edar Gud eder sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Så varer nu fast frimodige, att I hållen och gören allt det som skrifvet står i Mose lagbok; att I icke viken derifrå, antingen på den högra sidon eller på den venstra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Att I icke kommen ibland dessa återlefda folken, som med eder ännu äro; och I icke ihågkommen, eller svärjen vid deras gudars namn, eller tjenen dem, eller tillbedjen dem:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Utan håller eder intill Herran edar Gud, såsom I intill denna dag gjort hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Så skall Herren fördrifva för eder stor och mägtig folk; och ingen hafver kunnat stå eder emot allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'En af eder skall jaga tusende; ty Herren edar Gud strider för eder, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Derföre bevarer edra själar granneliga, att I hafven Herran edar Gud kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Men om I vänden eder härifrå, och hållen eder intill dessa återlefda folken, och befrynden eder med dem i giftermål, så att I kommen ibland dem, och de ibland eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Så veter, att Herren edar Gud skall icke mer fördrifva all dessa folken för eder; utan de skola eder varda till snaro och nät, och till en staka i edra sido, och till en törnagadd i edor ögon, tilldess han förgör eder utu det goda landet, som Herren edar Gud eder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Si, jag går i dag alla verldenes väg, och I skolen veta af allt hjerta, och af allo själ, att icke ett ord felat hafver på allt det goda, som Herren edar Gud eder sagt hafver; allt är skedt, och intet tillbakablifvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Lika som nu allt det goda kommet är, som Herren edar Gud eder sagt hafver, så skall ock Herren låta komma öfver eder allt ondt, tilldess han förgör eder utu detta goda landet, som Herren edar Gud eder gifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Om I Herrans edars Guds förbund öfverträden, som han eder budit hafver, och gången bort, och tjenen andra gudar, och tillbedjen dem; så att Herrans vrede förgrymmar sig öfver eder, och snarliga förgör eder utu det goda landet, som han eder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Och Josua församlade alla Israels slägter till Sichem, och kallade fram de äldsta i Israel, höfvitsmän, domare och ämbetsmän. Då de voro framträdde för Gud,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Sade han till hela folket: Så säger Herren, Israels Gud: Edra fäder bodde i förtiden på hinsidon älfven, Tharah, Abrahams och Nahors fader, och tjente andra gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Då tog jag edar fader Abraham på hinsidon älfven, och lät honom vandra i hela Canaans land, och förökade honom hans säd, och gaf honom Isaac.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Och Isaac gaf jag Jacob och Esau; och gaf Esau det berget Seir till besitta; men Jacob och hans barn drogo neder uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Då sände jag Mose och Aaron, och plågade Egypten, såsom jag ibland dem gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Sedan förde jag eder och edra fäder utur Egypten, och när I kommen till hafvet, och de Egyptier jagade efter edra fäder med vagnar och resenärar intill röda hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Så ropade de till Herran, och han satte ett mörker emellan eder och de Egyptier, och förde hafvet öfver dem, och öfvertäckte dem; och edor ögon sågo hvad jag i Egypten gjorde; och I bodden i öknene i en lång tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Och jag förde eder uti de Amoreers land, som bodde på hinsidon Jordan; och då de stridde emot eder, gaf jag dem i edra händer, så att I besågen deras land, och förgjorden dem för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Då reste sig upp Balak, Zipors son, de Moabiters Konung, och stridde emot Israel, och han sände bort, och lät kalla Bileam, Beors son, att han skulle förbanna eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Men jag ville intet höra honom, och han välsignade eder; och jag frälste eder utu hans händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Och då I gingen öfver Jordan, och kommen till Jericho, stridde Jericho inbyggare emot eder, de Amoreer, Phereseer, Cananeer, Hetheer, Girgaseer, Heveer och Jebuseer; men jag gaf dem i edra händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Och sände getingar framför eder, de drefvo dem ut för eder, de två Amoreers Konungar; icke genom ditt svärd eller genom din båga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Och gaf eder ett land, der I intet på arbetat haden, och städer, som I intet uppbyggt haden; att I skullen bo deruti, och skullen äta af vingårdar, och oljoberg, som I intet planterat haden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Så frukter nu Herran, och tjener honom troliga och rättsinneliga; och låter fara de gudar, som edra fäder tjent hafva på hinsidon älfven, och i Egypten; och tjener Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Tycker eder icke godt vara, att I tjenen Herranom, så utväljer eder i dag hvem I tjena viljen; antingen den Gud, som edre fäder tjent hafva på hinsidon älfvena, eller de Amoreers gudar, i hvilkas land I bon; men jag och mitt hus vilje tjena Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Då svarade folket, och sade: Bort det, att vi skulle öfvergifva Herran, och tjena andra gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Ty Herren vår Gud hafver fört oss och våra fäder utur Egypti land, utu träldomens hus; och hafver för vår ögon gjort så stor tecken, och bevarat oss på hela vägenom, som vi dragit hafve; och ibland alla de folk, genom hvilka vi gångne äre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Och Herren hafver utdrifvit för oss all de Amoreers folk, som bodde i landena; derföre vilje vi ock tjena Herranom; ty han är vår Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Josua sade till folket: I kunnen icke tjena Herranom; ty han är en helig Gud, och en nitälskande Gud, den eder icke förlåter edor öfverträdelse och synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'När I nu öfvergifven Herran, och tjenen en främmande gud, så skall han vända sig, och göra eder ondt; och förgöra eder, sedan han eder godt gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Men folket sade till Josua: Icke så, utan vi vilje tjena Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Då sade Josua till folket: I ären vittne öfver eder, att I hafven eder utvalt Herran, att I skolen tjena honom. Och de sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Så lägger nu ifrån eder de främmande gudar, som ibland eder äro, och böjer edor hjerta till Herran Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Och folket sade till Josua: Vi vilje tjena Herranom vårom Gud, och lyda hans röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Så gjorde Josua på den samma dagen ett förbund med folket, och satte dem lag och rätt före i Sichem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Och Josua skref allt detta i Guds lagbok, och tog en stor sten, och reste honom der upp under ena ek, som var vid Herrans helgedom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Och sade till allt folket: Si, denne stenen skall vara vittne emellan oss; ty han hafver hört allt Herrans tal, som han med oss talat hafver; och skall vara ett vittne öfver eder, att I edar Gud icke försaka skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Alltså lät Josua folket gå, hvar och en i sin arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Och det begaf sig, när detta skedt var, att Josua, Nuns son, Herrans tjenare, blef död, då han hundrade och tio är gammal var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Och de begrofvo honom i hans arfvedels gränso i ThimnathSerah, som ligger på Ephraims berg, på norra sidone vid det berget Gaas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Och Israel tjente Herranom så länge Josua lefde, och de äldste, hvilke i långan tid lefde efter Josua, och visste alla Herrans gerningar, som han med Israel gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Och Josephs ben, som Israels barn hade fört utur Egypten, begrofvo de i Sichem, i det åkrastycket, som Jacob köpte af Hemors barnom, Sichems faders, för hundrade penningar; och vardt Josephs barnas arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Blef ock Eleazar, Aarons son, död, och de begrofvo honom i Gibeath Pinehas hans sons, det honom på Ephraims berg gifvet var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Efter Josua död frågade Israels barn Herran, och sade: Ho skall ibland oss föra örliget emot de Cananeer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Herren sade: Juda skall föra det; si, jag hafver gifvit landet i hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Då sade Juda till sin broder Simeon: Drag med mig upp i min lott, och låt oss strida emot de Cananeer, så vill jag åter draga med dig i din lott. Så drog Simeon med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Då nu Juda drog ditupp, gaf Herren honom de Cananeer och Phereseer i deras händer; och de slogo i Besek tiotusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Och de funno AdoniBesek i Besek; och stridde emot honom, och slogo de Cananeer och Phereseer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Men AdoniBesek flydde, och de jagade efter honom, fingo honom, och höggo af honom tummarna, både af hans händer och fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Då sade AdoniBesek: Sjutio Konungar, med afhuggna tummar af deras händer och fötter, hemtade upp under mitt bord; såsom jag nu gjort hafver, så hafver Gud vedergullit mig. Och de förde honom till Jerusalem, der blef han död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Men Juda barn stridde emot Jerusalem, och vunno det, och slogo det med svärdsegg, och brände staden upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sedan drogo Juda barn neder, till att strida emot de Cananeer, som bodde på bergen, och söderut, och i dalarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Och Juda drog emot de Cananeer, som bodde i Hebron; men Hebron het i förtiden KiriathArba; och slog Sesai, och Ahiman, och Thalmai;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Och drog dädan emot Debirs inbyggare; men Debir het i förtiden KiriathSepher.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Och Caleb sade: Den som KiriathSepher slår och vinner, honom vill jag gifva mina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Då vann det Athniel, Kenas son, Calebs yngsta broders; och han gaf honom sina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Och det begaf sig, då hon indrog, vardt henne rådet, att hon skulle bedas en åker af sin fader; och hon gaf sig ifrån åsnanom. Då sade Caleb till henne: Hvad är dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Hon sade: Gif mig en välsignelse; ty du hafver gifvit mig ett söderland; gif mig ock ett, som vatten hafver. Då gaf han henne ett, som vatten hade ofvan och nedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Och de Keniters barn, Mose svågers, drogo upp utu Palma staden med Juda barn uti Juda öken, som ligger sunnan för den staden Arad; och gingo till, och bodde ibland folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Och Juda drog åstad med hans broder Simeon, och slogo de Cananeer i Zephat, och gåfvo honom tillspillo, och kallade staden Horma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Dertill vann Juda Gaza med dess tillhöring, och Askelon med dess tillhöring, och Ekron med dess tillhöring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Och Herren var med Juda, så att han intog berget; förty han kunde icke intaga dem som i dalarna bodde, derföre, att de hade jernvagnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Och de gåfvo Caleb Hebron, såsom Mose sagt hade; och han fördref derut de tre Enaks söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Men BenJamins barn fördrefvo icke de Jebuseer, som bodde i Jerusalem; utan de Jebuseer bodde när BenJamins barn i Jerusalem, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Sammalunda drogo ock Josephs barn upp till BethEl; och Herren var med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Och Josephs hus bespejade BethEl, det tillförene het Lus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Och hållarena fingo se en man gå utu staden, och sade till honom: Visa oss huru vi skole komma in i staden, så vilje vi göra barmhertighet med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Och när han hade vist dem hvar de skulle komma in, slogo de staden med svärdsegg; men den mannen och all hans slägt läto de gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Då drog den samme mannen in uti de Hetheers land, och byggde en stad, och kallade honom Lus. Den heter ännu i dag så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Och Manasse fördref icke BethSean med dess döttrar; icke heller Thaanach med dess döttrar, och icke heller de inbyggare i Dor med dess döttrar, ej heller de inbyggare i Jibleam med dess döttrar, ej heller de inbyggare i Megiddo med dess döttrar; och de Cananeer begynte till att bo i de samma landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Men då Israel kom till magt, gjorde han de Cananeer skattpligtiga, och fördref dem icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Sammalunda fördref icke heller Ephraim de Cananeer, som bodde i Gaser; utan de Cananeer bodde ibland dem i Gaser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon fördref icke heller dem som bodde i Kitron och Nahalol; utan de Cananeer bodde ibland dem, och voro skattpligtige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser fördref icke dem som bodde i Acco; icke heller dem som bodde i Zidon, i Ahlab, i Achsib, i Helbah, i Aphik och i Rehob;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Utan de Asseriter bodde ibland de Cananeer, som i landena bodde; ty de fördrefvo dem icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Napthali fördref icke dem som bodde i BethSemes, ej heller i BethAnath; utan bodde ibland de Cananeer, som i landena bodde; men de i BethSemes och i BethAnath vordo skattpligtige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Men de Amoreer trängde Dans barn in på bergena, och stadde dem icke till, att de kommo neder i dalarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Och de Amoreer begynte bo på de bergena Heres i Ajalon och Saalbim; dock vardt Josephs hus hand dem för svår, så att de vordo skattpligtige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Och de Amoreers gränsa var der man uppgår till Akrabbim, och ifrå klippone, och ifrå höjdene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Och kom en Herrans Ängel upp ifrå Gilgal till Bochim, och sade: Jag förde eder utur Egypten, och lät eder komma in uti det land, som jag edra fäder svorit hade, och sade: Jag skall icke göra mitt förbund med eder ogildt i evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Att I icke skullen göra något förbund med detta lands inbyggare, utan skullen bryta deras altare omkull; men I hafven intet lydt mine röst. Hvi hafven I det gjort?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Sade jag ock med: Jag vill icke fördrifva dem för eder; att de skola vara eder till snaro, och deras gudar eder till nät.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Och då Herrans Ängel dessa orden sagt hade till all Israels barn, hof folket sina röst upp, och gret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Och kallade det rummet Bochim, och offrade der Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Ty då Josua hade släppt folket ifrå sig, och Israel var dragen hvar till sin arfvedel, till att intaga landet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Tjente folket Herranom, så länge Josua lefde, och de äldste, som länge lefde efter Josua, och sett hade alla Herrans stora gerningar, som han Israel gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Men då Josua, Nuns son, Herrans tjenare, död var, hundrade och tio är gammal,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Begrofvo de honom i hans arfvedels gränso i ThimnathHeres, på Ephraims berg, på norra sidone vid Gaas berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Då ock alle de, som på den tiden lefde, voro samkade till sina fäder, kom ett annat slägte upp efter dem, som intet kände Herran, eller de gerningar, som han med Israel gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Så gjorde Israels barn det ondt var för Herranom, och tjente Baalim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Och öfvergåfvo Herran deras fäders Gud, som dem utur Egypti land fört hade, och följde andra gudar efter, och de folks gudar, som omkring dem bodde, och tillbådo dem, och förtörnade Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Ty de öfvergåfvo ju mer och mer Herran, och tjente Baal och Astaroth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Så förgrymmade då Herrans vrede sig öfver Israel, och gaf dem i deras hand, som dem röfvade, att de dem beröfva skulle, och sålde dem i deras fiendars händer allt omkring; och de kunde icke mer stå deras fiendar emot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Utan, ehvart de vände sig, var Herrans hand emot dem till deras ofärd, såsom Herren dem sagt, och Herren dem svorit hade; och de vordo hårdeliga plågade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'När nu Herren uppväckte domare, som dem hulpo utu röfvarenas hand,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Så lydde de icke heller domarena, utan bedrefvo hor med andra gudar, och tillbådo dem, och veko snarliga af den vägen, der deras fäder på gångit hade, till att lyda Herrans bud och gjorde intet såsom de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Då nu Herren uppväckte dem domare, så var Herren med domarenom, och halp dem utu deras fiendars hand, så länge domaren lefde; ty Herren förbarmade sig öfver deras suckan, öfver dem som dem tvingade, och trängde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Men när domaren blef död, så vände de sig, och förderfvade det mer än deras fäder, så att de följde andra gudar, till att tjena dem, och tillbedja dem de gingo icke ifrå sina påfunder, eller ifrå sina halsstyfva väsende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Derföre förgrymmade sig så Herrans vrede öfver Israel, att han sade: Efter detta folket hafver gått ifrå mitt förbund, som jag deras fader budit hafver, och icke velat höra min röst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Så skall jag nu härefter ingen fördrifva af de Hedningar, som Josua återlefde, då han blef död:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Att jag på dem må försöka Israel, om de vilja blifva på Herrans vägar, och vandra på dem, såsom deras fäder vandrat hafva, eller ej.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Så lät då Herren blifva dessa Hedningar, att han icke med hast fördref dem, hvilka han i Josua hand icke gifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Desse äro de Hedningar, som Herren lät blifva, på det han skulle med dem försöka Israel, som intet visste utaf Canaans örlig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Och att Israels barnas afföda måtte veta och lära strida, de som tillförene intet visste deraf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Nämliga de fem Philisteers Förstar, och alla Cananeer och Zidonier, och de Heveer, som bodde på Libanons berg, allt ifrå det berget BaalHermon, tilldess man kommer till Hamath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'De samme blefvo till att försöka Israel med dem, att man måtte förfara, om de lydde Herrans bud, som han deras fäder budit hade genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Då nu Israels barn bodde ibland de Cananeer, Hetheer, Amoreer, Phereseer, Heveer och Jebuseer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Togo de deras döttrar till hustrur, och gåfvo sina döttrar deras söner, och tjente deras gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Och gjorde, illa för Herranom, och förgåto Herran deras Gud, och tjente Baalim och lundom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Då förgrymmade sig Herrans vrede öfver Israel, och sålde dem i CusanRisathaims hand, Konungens i Mesopotamien; och så tjente Israels barn CusanRisathaim i åtta år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Då ropade Israels barn till Herran, och Herren uppväckte dem en frälsare, som dem frälste, Athniel, Kenas son, Calebs yngste broders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Och Herrans Ande var i honom, och han vardt domare i Israel, och drog ut till strid; och Herren gaf CusanRisathaim, Konungen i Syrien, i hans hand, så att hans hand vardt honom öfvermägtig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Så blef landet stilla i fyratio år; och Athniel, Kenas son, blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Men Israels barn gjorde ännu mer ondt för Herranom. Då stärkte Herren Eglon, de Moabiters Konung, emot Israel, derföre att de gjorde det ondt var för Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Och församlade till sig Ammons barn och de Amalekiter; och han drog åstad, och slog Israel, och tog in Palma staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Och Israels barn tjente Eglon, de Moabiters Konung, i aderton år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Så ropade de till Herran, och Herren uppväckte dem en frälsare, Ehud, Gera son, Jemini sons; han var ofärdig i sin högra hand. Och Israels barn sände med honom skänker till Eglon, de Moabiters Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Och Ehud gjorde sig ett tveeggadt svärd, en aln långt, och band det under, sin kläder på högra låret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Och bar fram skänken till Eglon, de Moabiters Konung; och Eglon var en ganska fet man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Och när han hade fått ifrå sig skänken, öfvergaf han folket, som hade burit skänken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Och vände tillbaka igen ifrå de afgudar i Gilgal; och lät båda: Jag hafver, o Konung, något hemligit tala vid dig. Han bad gifva ljud; och de gingo alle ut, som stodo omkring honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Och Ehud kom till honom in, och han satt uti en sommarsal allena; och Ehud sade: Jag hafver Guds ord till dig; då stod han upp af sinom stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Men Ehud räckte ut sina venstra hand, och tog svärdet af sitt högra lår, och stötte det in uti hans buk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Så att ock skaftet följde in med bladet, och fetman innelyckte skaftet; ty han drog intet svärdet ut af hans buk, och träcken gick af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Men Ehud gick ut genom bakdörrena, och lät igen dörrena efter sig, och slog henne i lås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Då han nu utkommen var, gingo hans tjenare in; och som de sågo, att dörren på sommarsalen igenlyckt var, sade de: Han är tilläfventyrs gången på stol i kammaren till sommarsalen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'När de nu så länge bidt hade, att de skämdes, ty ingen lät dem dörrena upp af salen, togo de nyckelen, och läste upp; si, då låg deras herre der död på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Och Ehud undflydde, medan de fördröjde, och gick fram om af gudarna, och undkom allt intill Seirath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Och då han kom derin, blåste han i basuner på Ephraims berg, och Israels barn drogo med honom af bergena, och han framför dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Och sade till dem: Följer mig efter, ty Herren hafver gifvit edra fiendar, de Moabiter, i edra händer; och de följde honom efter, och vunno Jordans färjostad, den som drager åt Moab, och läto ingen komma deröfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Och slogo de Moabiter af på den tiden vid tiotusend män, alltsammans adla och stridsamma män, så att icke en undslapp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Alltså vordo de Moabiter på den tiden nederlagde, under Israels barnas hand; och landet var stilla i åttatio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Efter honom var Samlar, Anaths son; han slog sexhundrade Philisteer med en herdastaf, och frälste ock han Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Men Israels barn gjorde ytterligare illa för Herranom, då Ehud var död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Och Herren sålde dem uti Jabins, de Cananeers Konungs, händer, som satt i Hazor, och hans härhöfvitsman var Sisera, och han bodde i Haroseth Hedningarnas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Och Israels barn ropade till Herran; ty han hade niohundrade järnvägnar, och tvingade Israels barn med våld i tjugu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'På den samma tiden var domarinna i Israel, den Prophetissan Debora, Lappidoths hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Och hon bodde under Deboras palmträ, emellan Rama och BethEl, på Ephraims berg; och Israels barn kommo ditupp till henne för rätta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Hon sände åstad, och kallade Barak, AbiNoams son, af Kedes Naphthali, och lät säga honom: Hafver icke Herren Israels Gud budit dig: Gack åstad, och drag upp på berget Thabor, och tag tiotusend män med dig, utaf Naphthali och Sebulons barn?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ty jag vill föra till dig Sisera, Jabins härhöfvitsman, vid den bäcken Kison, med hans vagnar, och med all hans hop; och vill gifva honom i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak sade till henne: Om du far med mig, så drager jag åstad; men far du icke med, så drager icke heller jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Hon sade: Jag vill draga med dig; men segren blifver icke din i denna resone, som du gör; utan Herren skall gifva Sisera uti en qvinnos hand. Så gjorde Debora redo, och for med Barak till Kedes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Då kallade Balak Sebulon och Naphthali till Kedes, och drog till fot med tiotusend män; Debora följde ock med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Men Heber den Keniten var dragen ifrå de Keniter, ifrå Hobabs barn, Mose svågers, och hade uppslagit sin tjäll vid den eken Zaanaim invid Kedes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Då vardt Sisera bådadt, att Barak, AbiNoams son, var dragen upp på det berget Thabor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Så samkade han alla sina vagnar tillhopa, niohundrade jernvagnar; och allt det folk med honom var, ifrå Haroseth Hedningarnas, allt intill den bäcken Kison.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Men Debora sade till Barak: Upp, detta är den dagen, i hvilkom Herren hafver gifvit Sisera i dina hand; ty Herren skall draga ut för dig. Så drog Barak neder af berget Thabor, och de tiotusend män med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Och Herren förskräckte Sisera med alla hans vagnar, och all hans här, för Baraks svärdsegg, så att Sisera sprang ifrå sin vagn, och flydde till fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Men Barak jagade efter vagnarna och hären, allt intill Haroseth Hedningarnas, och all Sisera här föll för svärdsegg, så att icke en blef öfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Men Sisera flydde till fot in uti Jaels tjäll, Hebers den Kenitens hustrus; förty Konung Jabin i Hazor, och Hebers den Kenitens hus stodo i frid med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Och Jael gick ut emot Sisera, och sade till honom: Kom, min Herre, kom in till mig, och frukta dig intet; och han gaf sig in till henne uti hennes tjäll, och hon höljde öfver honom en mantel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Och han sade till henne: Kära, gif mig litet vatten till att dricka, ty mig törster. Då tog hon en bytto mjölk, och gaf honom dricka, och höljde på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Och han sade till henne: Gack fram i dörrena på tjället, och om någor kommer och frågar, om någor är här, så säg: Ingen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Så tog Jael, Hebers hustru, en nagla af tjället, och en hammar i sina hand, och gick sakta in till honom, och slog honom naglan genom tinningen, så att han sank neder till jordena; ty han var sömnig och vanmägtig, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Då Barak jagade efter Sisera, gick Jael ut emot honom, och sade till honom: Kom hit, jag vill visa dig den man, som du söker efter. Och då han kom in till henne, låg Sisera död, och naglen fast i hans tinning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Alltså nederlade Gud, på den tiden, Jabin, de Cananeers Konung för Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Och Israels barnas hand fullföljde, och vardt stark emot Jabin, de Cananeers Konung, tilldess de utrotade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Då söngo Deborah och Barak, AbiNoams son, på den samma tiden, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Lofver Herran, att Israel är åter fri vorden, och folket hafver varit der viljogt till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Hörer till, I Konungar, och akter uppå, I Förstar: jag vill, Herranom vill jag sjunga, Herranom Israels Gudi vill jag spela.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Herre, då du utdrogst ifrå Seir, och gick fram ifrån Edoms mark, då skalf jorden, himmelen dröp, och skyarna dröpo vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Bergen smulto för Herranom, Sinai för Herranom Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'I Samgars, Anaths sons, tid, i Jaels tid, voro vägarna förgångne; och de som på stigarna gå skulle, de vandrade krokota vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Det fattades, bönder fattades i Israel, tilldess jag Debora uppkom, tilldess jag uppkom en moder i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Ett nytt hafver Gud utvalt, portarna hafver han bestridt; ingen sköld eller spets vardt sedd ibland fyratiotusend i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mitt hjerta faller till Israels regenter, hvilke friviljoge äro ibland folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Lofver Herran, I som riden på sköna åsninnor, I som sitten för rätta; och sjunger, I som gån på vägomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Der skyttarna ropa ibland dem som vatten hemta, der säge man om Herrans rättfärdighet, om hans bönders rättfärdighet i Israel; då drog Herrans folk neder till portarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Upp, upp, Debora, upp, upp, och sjung ena viso; upp, Barak, och fånga dina fångare, du AbiNoams son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Då vordo de förlåtne rådande öfver de mägtiga; Herren vardt rådandes genom mig öfver de hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Utaf Ephraim var deras rot emot Amalek; och efter dig BenJamin i ditt folk. Af Machir äro komne regenter; och af Sebulon äro regerare vordne igenom skrifpennan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Isaschars Förstar voro med Debora, och Isaschar var såsom Barak i dalenom, utsänder med sitt fotfolk. Ruben höll mycket af sig, och skiljde sig ifrån oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Hvi blefst du i dinom fårahyddom, till att höra hjordarnas bräkande; och höll mycket af dig, och skiljde dig ifrån oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead blef hinsidon Jordan. Och hvi bor Dan ibland skeppen? Asser satt i hafsens hamn, och blef i sina förfallna byar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Men Sebulons folk vågade sina själ i döden; Naphthali desslikes på höjdene af markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Konungarna kommo och stridde. Då stridde de Cananeers Konungar i Thaanach, vid det vattnet Megiddo; men de hade ingen vinning deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Af himmelen var stridt emot dem; stjernorna i deras lopp stridde emot Sisera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Den bäcken Kison vältrade dem, den bäcken Kedumim, den bäcken Kison. Träd, min själ, på de starka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Då darrade hästarnas fötter, för deras starka åsittares förfärelses skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Förbanner den staden Meros, sade Herrans Ängel; förbanner hans borgare, att de icke kommo Herranom till hjelp; till hjelp Herranom, till de hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Välsignad vare ibland qvinnor Jael, Hebers den Kenitens hustru; välsignad vare hon i hyddomen ibland qvinnor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Mjölk gaf hon, då han vatten beddes, och bar smör in uti en härlig skål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Hon tog naglan med sin hand, och smedshammaren i sina högra hand, och slog Sisera genom hans hufvud; sönderkrossade, och genomstack hans tinningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Till hennes fötter krökte han sig, föll neder, och lade sig; han krökte sig, och föll neder till hennes fötter; såsom han krökte sig, så låg han förderfvad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Sisera moder såg genom fenstret ut, och gret igenom gallren: Hvi förtöfvar hans vagn så länge, att han icke kommer? Hvi fördröja hans vagns hjul?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'De visesta ibland hennes qvinnor svarade, då hon så jämmerliga qvidde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Skulle de icke finna och byta rof, hvarjom manne en ung pigo eller två till byte; och Sisera brokot stickad kläder till byte, stickad brokot kläder om halsen till byte?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Alltså, Herre, förgånge alle dine fiender; men de som honom kär hafva, de vare såsom uppgångande solen i sine magt. Och landet hade frid i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Och då Israels barn gjorde det ondt var för Herranom, gaf Herren dem under de Midianiters hand i sju år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Och då de Midianiters hand vardt för stark öfver Israel, gjorde Israels barn sig klyfter i bergen, och kulor, och fäste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Och när Israel något sådde, så kommo de Midianiter upp, och de Amalekiter, och de af österlanden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Och lägrade sig emot dem, och förderfvade växten på landet, allt intill Gasa, och läto ingen boskap blifva qvar i Israel, hvarken får, fä eller åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Förty de kommo ditupp med sinom boskap och tjäll, såsom ett stort tal gräshoppor, så att hvarken de eller deras cameler stodo till att räkna; och de föllo in i landet, på det de skulle förderfva det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Så vardt Israel mycket försvagad för de Midianiter. Då ropade Israels barn till Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Som de nu ropade till Herran, för de Midianiters skull,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Sände Herren till dem en Prophet; han sade till dem: Detta säger Herren Israels Gud: Jag hafver fört eder utur Egypten, och utu träldomens hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Och hafver frälst eder utu de Egyptiers hand, och utur alla deras hand, som eder tvingade, och hafver drifvit dem ut för eder, och gifvit eder deras land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Och sade till eder: Jag är Herren edar Gud; frukter intet de Amoreers gudar, i hvilkas land I bon. Och I lydden mine röst intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Och en Herrans Ängel kom, och satte sig under ena ek i Ophra, hvilken Joas tillhörde, de Esriters fader; och hans son Gideon tröskade hvete i pressen, på det han skulle fly för de Midianiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Då syntes honom Herrans Ängel, och sade till honom: Herren vare med dig, du stridsamme hjelte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon sade till honom: Min Herre, är Herren med oss, hvi vederfars oss då allt detta? Och hvar äro all hans under, som våre fäder hafva förtäljt oss, och sagt: Herren hafver fört oss utur Egypten? Herren hafver nu öfvergifvit oss, och gifvit oss i de Midianiters händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Då vände Herren sig till honom, och sade: Gack åstad i denna dine kraft; du skall fria Israel utu de Midianiters händer; si, jag hafver sändt dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Han sade till honom: Min Herre, hvarmed skall jag fria Israel? Si, min slägt är den minsta i Manasse, och jag är den svagaste i mins faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Herren sade till honom: Jag vill vara med dig, så att du skall slå de Midianiter, såsom en man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Men han sade till honom: Käre, hafver jag funnit nåd för dig, så gif mig ett tecken, att det är du, som talar med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Gack icke hädan, tilldess jag kommer till dig, och bär mitt spisoffer, och lägger det för dig. Han sade: Jag vill blifva, tilldess du kommer igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Och Gideon gick, och slagtade ett kid, och tog ett epha osyradt mjöl; och lade kött uti en korg, och lät sådet uti ena kruko, och bar ut till honom under ekena, och gick fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Men Guds Ängel sade till honom: Tag köttet, och det osyrada, och lägg det på hälleberget, som här är, och gjut sådet ut. Och han gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Då räckte Herrans Ängel käppen ut, som han hade i handene, och kom vid köttet och det osyrada mjölet med käppsändanom; och elden kom utu hällebergena, och förtärde köttet och det osyrada mjölet. Och Herrans Ängel försvann utu hans ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Då nu Gideon såg, att det var en Herrans Ängel, sade han: O! Herre, Herre, hafver jag nu sett en Herrans Ängel ansigte mot ansigte?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Men Herren sade till honom: Frid vare med dig; frukta dig intet, du skall icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Då byggde Gideon dersammastäds Herranom ett altare, och kallade det fridsens Herre. Det står der ännu på denna dag, i Ophra, de Esriters faders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Och i den samma nattene sade Herren till honom: Tag en stut ibland oxarna, som dinom fader tillhöra, och en annan stut som sju åra gammal är, och slå sönder Baals altare, som är dins faders, och hugg bort den lunden, som der när står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Och bygg Herranom dinom Gud ett altare öfverst på desso hällebergena, och red det till; och tag den andra stuten, och offra ett bränneoffer, med veden af lundenom, som du borthuggit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Då tog Gideon tio män ut af sina tjenare, och gjorde såsom Herren honom sagt hade; men han fruktade sig göra det om dagen, för sins faders hus skull, och för folkens skull i stadenom; utan om nattena gjorde han det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Då nu folket i staden stodo upp bittida om morgonen, si, då var Baals altare sönderslaget, och lunden der när afhuggen; och den andre stuten för ett bränneoffer lagd på det altaret, som uppbygdt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Och den ene sade till den andra: Ho hafver detta gjort? Och då de sökte, och frågade derefter, vardt sagdt: Gideon, Joas son, hafver det gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Då talade folket i staden till Joas: Få oss hitut din son; han måste dö, derföre, att han hafver omkullslagit Baals altare, och afhuggit lunden der när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Men Joas sade till alla dem som när honom stodo: Viljen I lägga eder ut för Baal? Viljen I fria honom? Den som lägger sig ut för honom, han skall dö i denna morgon. Är han gud, så hämne sig sjelf, att hans altare omkullslaget är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Ifrå den dagen kallade man honom JerubBaal, och sade: Baal hämne sig sjelf, att hans altare omkullslaget är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Då församlade sig tillhopa de Midianiter och Amalekiter, och de österländningar, och drogo öfver, och lägrade sig i den dalen Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Så iklädde Herrans Ande Gideon, och han lät blåsa i basuner, och kallade AbiEser, att de skulle följa honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Och sände bådskap i hela Manasse, och kallade dem, att de skulle ock följa honom; han sände ock bådskap till Asser, och Sebulon, och Naphthali; de kommo upp emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Och Gideon sade till Gud: Vill du frälsa Israel igenom mina hand, såsom du sagt hafver,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Så vill jag lägga ett skinn med ullone ut på logan; om daggen lägger sig allenast på skinnet, och all marken är torr, så kan jag märka, att du vill frälsa Israel igenom mina hand, såsom du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Och det skedde så. Och då han den andra morgonen bittida uppstod, tryckte han daggena utu skinnet, och uppfyllde ena skål med det vattnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Och Gideon sade till Gud: Din vrede förgrymme sig icke öfver mig, om jag än en tid talar; jag vill än en tid försökat med skinnet; vare nu allena torrt på skinnena, och daggen på allo markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Gud gjorde ock så i samma natt, att allena var torrt på skinnet, och dagg uppå allo markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Då stod JerubBaal, det är Gideon, bittida upp, och allt folket, som med honom var, och lägrade sig vid den brunnen Harod, så att han hade de Midianiters här norrut, bakföre det berget More i dalenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Och Herren sade till Gideon: Folket, som med dig är, är allt för mycket. Om jag gåfve Midian i deras händer, måtte Israels barn berömma sig emot mig, och säga: Min hand hafver frälst mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Så låt nu utropa för folkets öron, och säga: Den som rädder är och förfärad, han vände om, och skynde sig af berget Gilead. Då vände folket tillbaka, tu och tjugu tusend, så att icke utan tiotusend blefvo qvara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Och Herren sade till Gideon: Detta folket är ännu för mycket; haf dem neder till vattnet, der vill jag pröfva dig dem; och om hvilken jag säger dig, att han skall draga med dig, han skall draga med dig; och om hvilken jag säger, att han icke skall draga med dig, han skall icke draga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Och han hade folket neder till vattnet. Och Herren sade till Gideon: Hvilken som läppjar vattnet med sine tungo, såsom en hund läppjar, honom ställ afsides; desslikes dem som på sin knä nederfalla till att dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Då var deras tal, som med munnen läppjat hade utu handene, trehundrade män; allt det andra folket hade fallit på knä och druckit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Och Herren sade till Gideon: Med de trehundrade män, som läppjat hafva, vill jag frälsa eder, och gifva de Midianiter i dina händer; men det andra folket lät alltsammans gå hem till sitt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Och de togo spisning för folket med sig, och sina basuner; men de andra Israeliter lät han alla gå hvar och en i sina hyddo; men han stärkte sig med de trehundrade män; och de Midianiters här låg nedanför honom i dalenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Och Herren sade till honom i samma natt: Statt upp, och gack neder till lägret; ty jag hafver gifvit dem i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Om du fruktar dig att gå ditneder, så låt din dräng Pura gå ned med dig till lägret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Att du må få höra hvad de tala; sedan skall du med magt draga neder till lägret. Så gick Gideon med sin dräng Pura neder till det rummet på lägret, der vakten var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Men de Midianiter och de Amalekiter, och alle österländningarna, hade lägrat sig i dalenom, såsom en hop gräshoppor; och deras cameler stodo icke till att räkna, så månge voro de, såsom sanden på hafsens strand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Då nu Gideon kom, si, då förtäljde en för dem andra en dröm, och sade: Mig tyckte, att ett bjuggbröd, på glöd bakadt, välte sig intill de Midianiters lägre, och då det kom till tjället, slog det det, och kastade det neder, och vände upp ned uppå thy, så att tjället låg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Då svarade den andre: Det är icke annat än Gideons svärd, Joas sons, den Israelitens; Gud hafver gifvit de Midianiter i hans händer med hela hären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Då Gideon nu hörde förtäljas sådana dröm, och hans utläggning, tillbad han, och kom igen i Israels här, och sade: Upp, ty Herren hafver gifvit de Midianiters här uti edra händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Och han skifte de trehundrade män i tre delar, och fick hvarjom och enom en basun i sina hand, och tomma krukor, och lampor deruti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Och sade till dem: Ser på mig, och görer ock så; si, när jag kommer intill hären, såsom jag gör, så görer ock med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Såsom jag blås i basunen, och alle de som med mig äro, så skolen ock I blåsa i basunen omkring hela haren, och säga: Herren och Gideon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Så kom Gideon, och hundrade män med honom, till det yttersta på hären, till första väktarena, som der skickade voro och väckte dem upp, och blåste med basunerna, och slogo sönder krukorna i sina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Och så blåste då alle tre hoparna med basunerna, och slogo sönder krukorna; men lamporna höllo de i deras venstra hand, och basunen i deras högra hand, och blåste och ropade: Herrans och Gideons svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Och hvar och en stod på sitt rum, omkring hären. Då begynte hela hären att löpa, ropa och fly.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Och som de trehundrade män blåste i basunerna, gjorde Herren så, att hvars och ens svärd i hela härenom var emot den andra; och hären flydde allt intill BethSittaZereratha, allt intill gränsona åt den slättene Mehola vid Tabbath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Och de Israels män af Naphthali, af Asser, och af hela Manasse, skriade, och jagade efter de Midianiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Och Gideon sände bådskap på hela berget Ephraim, och lät säga dem: Kommer neder emot de Midianiter, och kommer förr än de till vattnet, intill BethBara och Jordan. Så ropade alle de som af Ephraim voro, och kommo förr än de till vattnet, intill BethBara och Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Och de fingo fatt på två de Midianiters Förstar, Oreb och Seeb; och dråpo Oreb på det hälleberget Oreb, och Seeb i Seebs press; och jagade de Midianiter; och båro Orebs och Seebs hufvud till Gideon öfver Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Och de män af Ephraim sade till honom: Hvi gjorde du oss detta, att du icke kallade oss, då du drog till strids emot de Midianiter? Och kifvade svårliga på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Men han sade till dem: Hvad hafver jag nu gjort, det edro gerning liknas kan? Är icke en vinqvist Ephraims bättre, än hela AbiEsers vinbergning?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Gud hafver gifvit i edra händer de Midianiters Förstar Oreb och Seeb. Huru skulle jag kunnat det gjort, som I gjort hafven? Då han detta sade, stillades deras vrede emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Då nu Gideon kom till Jordan, gick han deröfver med trehundrade män, som med honom voro; och de voro trötte, och jagade efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Och han sade till det folket i Succoth: Käre, gif detta folket, som under mig är, något bröd, förty de äro trötte; att jag måtte jaga efter de Midianiters Konungar, Sebah och Zalmunna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Men de öfverste i Succoth sade: Äro Sebahs och Zalmunna händer allaredo i dina händer, att vi ju skole gifva dinom här bröd?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon sade: Nu väl, när Herren gifver Sebah och Zalmunna i mina hand, skall jag söndertröska edart kött med törne utur öknene, och med tistlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Och han drog dädan upp till Pnuel, och talade sammalunda till dem. Och det folket i Pnuel svarade honom lika som de i Succoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Och han sade ock till det folket i Pnuel: Kommer jag igen i frid, så skall jag bryta detta tornet neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Men Sebah och Zalmunna voro i Karkor, och deras här när dem, vid femtontusend, hvilke alle voro undsluppne af hela de österländningars här; ty tjugu och hundrade tusend voro fallne, som svärd utdraga kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Och Gideon drog uppåt på den vägen, der man i tjäll bor, österut in mot Nobah och Jogbeha, och slog hären; ty hären var trygg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Och Sebah och Zalmunna flydde; men han jagade efter dem, och grep de två Midianiters Konungar, Sebah och Zalmunna, och förskräckte hela hären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Då nu Gideon, Joas son, kom igen af stridene, förr än solen uppgången var,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Fick han fatt på en dräng utaf det folket i Succoth, och frågade honom; han skref honom upp de öfversta i Succoth, och deras äldsta, sju och sjutio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Och han kom till det folket i Succoth, och sade: Si, här äro Sebah och Zalmunna, om hvilka I bespottaden mig, och säden: Är då allaredo Sebahs och Zalmunna hand uti dina händer, att vi ju skole gifva dino folke, som trött är, bröd?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Och han tog de äldsta af staden, och törne utaf öknene och tistlar, och lät dermed sönderslita det folket i Succoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Och tornet i Pnuel bröt han neder, och slog ihjäl folket i stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Och till Sebah och Zalmunna sade han: Hurudana voro de män, som I slogen ihjäl i Thabor? De sade: De voro sådana som du, och dägelige såsom ens Konungs barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Han sade: De voro mine bröder, mine moders söner; så sant som Herren lefver, om I haden låtit dem lefva, skulle jag icke aflifva eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Och sade till sin förstfödda son Jether: Statt upp, och dräp dem. Men drängen drog sitt svärd icke ut; ty han fruktade sig, efter han var ännu en ung dräng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Då sade Sebah och Zalmunna: Statt du upp, och slå oss; ty efter som mannen är, så är ock hans magt. Så stod Gideon upp, och slog ihjäl Sebah och Zalmunna, och tog de spänger, som voro på deras camelers halsar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Då sade till Gideon någre af Israel: Var herre öfver oss, du och din son, och dins sons son, efter du hafver frälst oss ifrå de Midianiters hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Men Gideon sade till dem: Jag vill ingen herre vara öfver eder, och min son skall icke heller vara herre öfver eder; utan Herren skall vara herre öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Och Gideon sade till dem: Ett begärar jag af eder, hvar och en gifve mig de örnaringar, som han röfvat hafver; förty, efter de voro Ismaeliter, hade de gyldene örnaringar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'De sade: Dem vilje vi gifva; och bredde ett kläde ut, och hvar och en kastade örnaringarna deruppå, som han röfvat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Och de gyldene örnaringarna, som han hade begärat, gjorde till vigt tusende sjuhundrade siklar guld; förutan de spänger, kedjor och skarlakanskläder, som de Midianiters Konungar plägade bära, och förutan deras camelers halsband.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Och Gideon gjorde der en lifkjortel af, och satte honom i sin stad Ophra; och hela Israel bedref der hor uppå; och det vardt Gideon och hans huse till förargelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Alltså vordo de Midianiter förnedrade för Israels barn, och hofvo sitt hufvud icke mer upp; och landet var stilla i fyratio år, så länge Gideon lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Och JerubBaal, Joas son, gick bort, och bodde i sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Och Gideon hade sjutio söner, som utaf hans länder komne voro; ty han hade många hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Och hans frilla, den han hade i Sichem, födde honom ock en son; hans namn kallade han AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Och Gideon, Joas son, blef död i godom ålder, och vardt begrafven i sins faders Joas graf, i Ophra, de Esriters faders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Då Gideon var död, vände Israels barn om, och bedrefvo hor efter Baalim, och gjorde BaalBerith sig till en gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Och Israels barn kommo intet Herran deras Gud ihåg, den dem frälsat hade ifrån allas deras fiendars hand allt omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Och de gjorde ingen barmhertighet med JerubBaals Gideons huse, efter allt det goda, som han emot Israel gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Men AbiMelech, JerubBaals son, gick bort till Sichem till sina moders bröder, och talade med dem, och med hela slägtene af hans moderfaders hus, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Käre, taler för alla mäns öron i Sichem: Hvilket är eder bättre, att sjutio män, alle JerubBaals barn, blifva herrar öfver eder, eller en man blifver herre öfver eder? Kommer ock dertillmed ihåg, att jag är edart ben och kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Då talade hans moders bröder all dessa orden om honom, för alla mäns öron i Sichem; och deras hjerta bevektes efter AbiMelech; ty de tänkte: Han är vår broder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Och gåfvo honom sjutio silfpenningar utur BaalBeriths huse; och AbiMelech lejde sig dermed lösaktiga och lättfärdiga män, som honom följde efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Och han kom i sins faders hus i Ophra, och slog sina bröder, JerubBaals söner, sjutio män, ihjäl på enom sten; men Jotham, den yngste sonen JerubBaals, blef igen; ty han vardt undstungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Och sig församlade alle män af Sichem, och hela Millo hus; och gingo till, och gjorde AbiMelech till Konung vid den höga ekena, som stod i Sichem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Då detta var sagdt Jotham, gick han bort, och stod öfverst på Grisims berg, och hof sin röst upp, ropade, och sade till dem: Hörer mig, I män af Sichem, att Gud ock hörer eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Trän gingo till och skulle smörja öfver sig en Konung, och sade till oljoträt: Var vår Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Men oljoträt svarade dem: Skulle jag öfvergifva min fetma, hvilken både Gud och menniskor prisa i mig, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Då sade trän till fikonträt: Kom du, och var Konung öfver oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Men fikonträt sade till dem: Skulle jag öfvergifva min sötma och mina goda frukt, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Då sade trän till vinträt: Kom du, och var vår Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Men vinträt sade till dem: Skulle jag öfvergifva min must, den Gud och menniskor glada gör, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Då sade all trän till törnebuskan: Kom du, och var Konung öfver oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Och törnebusken sade till trän: Är det sant, att I viljen smörja mig till Konung öfver eder, så kommer, och betror eder under min skugga; hvar I icke viljen, så gånge en eld utu törnebuskan, och förtäre cedreträn i Libanon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Hafven I nu gjort rätt och redeliga, att I hafven gjort AbiMelech till Konung; och hafven I gjort väl emot JerubBaal och hans hus; och hafven så gjort emot honom som han förtjent hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Att min fader för edra skull stridde, och vågade sin själ, derföre att han skulle frälsa eder ifrå de Midianiters hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Och hafven uppsatt eder i denna dag emot mins faders hus, och slagit hans söner ihjäl, sjutio män på en sten, och gjort eder till Konung AbiMelech, hans tjensteqvinnos son, öfver de män i Sichem, efter han edar broder är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Hafven I nu gjort rätt och redeliga emot JerubBaal och hans hus på denna dag, så varer glade öfver AbiMelech, och han vare glad öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Hvar ock icke, så gånge en eld utaf AbiMelech, och förtäre de män af Sichem, och af Millo hus; och gånge desslikes ut en eld af de män i Sichem, och af Millo hus, och förtäre AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Och Jotham flydde, och undvek, och gick till Ber, och bodde der, för hans broders AbiMelechs skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Då nu AbiMelech hade rådit öfver Israel i tre år,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Sände Gud en ondan vilja emellan AbiMelech och de män af Sichem; förty de män af Sichem förtalade AbiMelech,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Och kastade honom före den ogerning, som han bedref på de sjutio JerubBaals söner, och lade deras blod på AbiMelech deras broder, den dem ihjälslog; och på de män i Sichem, som honom hans hand dertill styrkt hade, att han sina bröder drap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Och de män i Sichem beställde ett bakhåll öfverst på bergen, och röfvade på vägenom alla de som foro der fram; och det vardt bådadt AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Så kom Gaal, Ebeds son, och hans bröder, och gingo in i Sichem; och de män i Sichem förläto sig uppå honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Och drogo ut på markena, och bergde sina vingårdar, och trampade der, och gjorde en dans, och gingo uti deras guds hus, och åto och drucko, och bannade AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Och Gaal, Ebeds son, sade: Hvad är AbiMelech? Och hvad är Sichem, att vi honom tjena skole? Är icke han JerubBaals son, och hafver satt sin tjenare Sebul hit öfver Hemors folk, Sichems faders? Hvi skulle vi tjena honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Gud gifve, att detta folket vore under mine hand, att jag måtte förjaga AbiMelech. Och det vardt sagdt AbiMelech: Föröka din här, och drag ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Förty Sebul, öfversten i stadenom, då han hörde Gaals, Ebeds sons ord, vardt han illa vred;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Och sände bådskap till AbiMelech hemliga, och lät säga honom: Si, Gaal, Ebeds son, och hans bröder, äro komne till Sichem, och göra dig staden genstörtigan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Så statt nu upp om natten, du och ditt folk, som när dig är, och var i bakhåll för dem i markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Och i morgonstundene, när solen uppgår, så var bittida uppe, och fall till staden; och när han och det folk, som med honom är, draga ut till dig, så gör med dem såsom din hand finna kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'AbiMelech stod upp om nattena, och allt folket, som med honom var, och satte bakhåll inför Sichem med fyra skarar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Och Gaal, Ebeds son, drog ut för stadsporten; men AbiMelech reste upp utaf bakhållet, med det folk som med honom var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Då nu Gaal såg folket, sade han till Sebul: Si, der kommer en hop folk neder af bergshöjdene. Sebul sade: Du ser skuggan af bergen, likasom det vore menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal talade än en tid, och sade: Si, der kommer en hop folk neder midt utaf landet; och en här kommer på den vägen till trollareekena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Då sade Sebul till honom: Hvar är nu din mun, som sade: Ho är AbiMelech, att vi honom tjena skole? Är icke nu detta det folk, som du föraktat hafver? Drag nu ut, och strid med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal drog ut med Sichems folk, och stridde med AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Men AbiMelech jagade honom, så att han flydde för honom; och månge föllo slagne allt intill stadsporten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Och AbiMelech blef i Aruma; men Sebul dref Gaal och hans bröder ut, så att de icke måtte blifva i Sichem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Om morgonen gick folket ut på markena; och det vardt sagdt AbiMelech.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Och han tog folket, och skifte det i tre delar, och beställde håll på dem i markene. Som han nu såg, att folket gick utu stadenom, föll han till dem, och slog dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Men AbiMelech med den hopen, som med honom var, föllo till, och trädde intill stadsporten; de andre två hoparna föllo till alla dem som på markene voro, och slogo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Då stridde AbiMelech emot staden den hela dagen, och vann honom; och drap det folk, som derinne var, och slog staden neder, och sådde salt deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'När de män, som i Sichems torn bodde, detta hörde, gingo de in uti ett fäste i den gudens Beriths hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Då AbiMelech det hörde, att alle de män af Sichems torn voro församlade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Gick han på det berget Zalmon med allt sitt folk, som med honom var; och tog ena yxa i sin hand, och högg en gren af ett trä, och lade på sin axel, och sade till allt folket, som med honom var: Hvad I sågen att jag gjorde, det görer ock I med hast såsom jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Då högg allt folket hvar i sin stad en gren af, och följde AbiMelech efter, och kastade dem intill fästet, och tände der eld uppå; så att alle de män af Sichems torn blefvo döde, vid tusend män och qvinnor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Och AbiMelech drog till Thebez, och belade det, och vann det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Men der var ett starkt torn midt i stadenom, på hvilket flydde alle, både män och qvinnor, och alle stadsens inbyggare, och läste igen efter sig, och stego upp på taket af tornet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Då kom AbiMelech intill tornet, och stridde deremot, och kom sig intill porten af tornet, på det han skulle tända der eld uppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Men en qvinna kastade ett stycke af en qvarnsten ned på AbiMelechs hufvud, och slog honom hufvudskålena sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Då kallade AbiMelech drängen, som hans värja drog, hasteliga, och sade till honom: Drag ut ditt svärd, och dräp mig, att man icke skall säga: En qvinna slog honom ihjäl. Så stack hans dräng honom igenom, och han blef död,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Då nu de Israeliter, som med honom voro, sågo att AbiMelech var död, gick hvar och en hem till sin ort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Alltså betalade Gud AbiMelech det onda, som han emot sin fader gjort hade, då han drap sina sjutio bröder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Desslikes allt det onda, som de män af Sichem gjorde, betalade dem Gud på deras hufvud; och öfver dem kom Jothams förbannelse, JerubBaals sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Efter AbiMelech kom upp en annan frälsare i Israel, Thola, en man af Isaschar, Puahs son, Dodo sons; och han bodde i Samir på Ephraims berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Och han dömde Israel i tre och tjugu år, och blef död, och vardt begrafven i Samir.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Efter honom kom upp Jair, en Gileadit, och han dömde Israel itu och tjugu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Och han hade tretio söner, ridande på tretio åsnafålar, och hade tretio städer, de kallades HavothJair allt intill denna dag, och ligga i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Och Jair blef död, och vardt begrafven i Kamon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Men Israels barn gjorde åter det ondt var för Herranom; och tjente Baalim och Astaroth, och de gudar i Syria, och de gudar i Zidon, och Moabs gudar, och Ammons barnas gudar, och de Philisteers gudar, och öfvergåfvo Herran, och tjente honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Då förgrymmade sig Herrans vrede öfver Israel, och sålde dem under de Philisteers och Ammons barnas hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Och de tvingade och förtryckte Israels barn, ifrå det året, i aderton år; alla Israels barn på hinsidon Jordan, uti de Amoreers lande, som i Gilead ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Dertill drogo Ammons barn öfver Jordan, och stridde emot Juda, BenJamin, och emot Ephraims hus, så att Israel vardt ganska svårliga förtryckt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Då ropade Israels barn till Herran, och sade: Vi hafve syndat emot dig; ty vi hafve öfvergifvit var Gud, och tjent Baalim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Men Herren sade till Israels barn: Betvingade ock icke eder de Egyptier, de Amoreer, Ammons barn, de Philisteer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'De Zidonier, de Amalekiter och Maoniter? Och jag halp eder utu deras händer, då I ropaden till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Så hafven I dock likaväl öfvergifvit mig, och tjent andra gudar; derföre vill jag intet mer hjelpa eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Går och åkaller de gudar, som I utvalt hafven; låter dem hjelpa eder uti edor bedröfvelses tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Men Israels barn sade till Herran: Vi hafve syndat; gör du med oss hvad dig täckes, allenast hjelp oss i denna tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Och de kastade ifrå sig de främmande gudar, och tjente Herranom; och honom ömkade deröfver, att Israel så tvingad vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Och Ammons barn slogo sig ihop, och lägrade sig i Gilead; men Israels barn församlade sig, och lägrade sig i Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Och folket, de öfverste i Gilead, sade emellan sig: Hvilken som först begynner till att strida emot Ammons barn, han skall vara höfvitsman öfver alla de som bo i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jephthah, en Gileadit, var en stridsam hjelte, dock likväl enes skökos son; och Gilead hade födt Jephthah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Men då Gileads hustru födde honom barn, och de samma barn vordo stor, drefvo de Jephthah ut och sade till honom: Du skall intet arf taga i vårs faders huse; ty du äst ens annors qvinnos son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Då flydde han för sina bröder, och bodde i det landet Tob; och till honom församlade sig lösaktige män, och drogo ut med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Och någon tid derefter stridde Ammons barn med Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Då nu Ammons barn så stridde med Israel, gingo de äldste af Gilead bort, till att hemta Jephthah utu Tobs lande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Och sade till honom: Kom, och var vår höfvitsman, att vi måge strida emot Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Men Jephthah sade till de äldsta af Gilead: Ären icke I de som mig haten, och hafven drifvit mig utu mins faders hus, och nu kommen I till mig, medan I ären i bedröfvelse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'De äldste i Gilead sade till Jephthah: Derföre komme vi nu igen till dig, att du skall gå med oss, och hjelpa oss strida emot Ammons barn; och vara vår höfvitsman öfver alla de som bo i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jephthah sade till de äldsta i Gilead: Om I hemten mig igen till att strida emot Ammons barn, och Herren gifver dem för mig, skall jag då vara edar höfvitsman?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'De äldste af Gilead sade till Jephthah: Herren vare tillhörare emellan oss, om vi icke göre som du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Alltså gick då Jephthah med de äldsta af Gilead, och folket satte honom för höfvitsman och öfversta öfver sig; och Jephthah talade allt detta inför Herranom i Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Då sände Jephthah bådskap till Konungen öfver Ammons barn, och lät säga honom: Hvad hafver du med mig att skaffa, att du kommer emot mig, till att strida emot mitt land?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Konungen öfver Ammons barn svarade Jephthas bådskap: Derföre, att Israel hafver tagit bort mitt land, då de drogo utur Egypten, allt ifrån Arnon intill Jabbok, och allt intill Jordan; så få mig nu det igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jephthah sände åter bådskap till Ammons barnas Konung;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Och lät säga honom: Så säger Jephthah: Israel hafver intet land borttagit, antingen ifrå de Moabiter, eller ifrån Ammons barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Förty när de drogo utur Egypten, vandrade Israel genom öknena allt intill röda hafvet, och kom till Kades;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Och sände bådskap till de Edomeers Konung, och sade: Låt mig draga igenom ditt land; men de Edomeers Konung tillstadde dem intet. Och sände han båd till Konungen öfver de Moabiter; han ville icke heller tillstädjat. Så, blef Israel i Kades;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Och vandrade i öknene, och drog omkring de Edomeers och Moabiters land, och kom östan på de Moabiters land, och lägrade sig på hinsidon Arnon; och kom intet in uti de Moabiters landsändar; ty Arnon är de Moabiters landamäre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Och Israel sände båd till Sihon, de Amoreers Konung, i Hesbon, och sade: Låt oss draga igenom ditt land in till mitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Men Sihon betrodde icke Israel, att han skulle draga igenom hans landsändar; utan församlade allt sitt folk, och lägrade sig i Jahza, och stridde med Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Men Herren Israels Gud gaf Sihon, med allt hans folk, i Israels händer, så att de slogo dem; alltså tog Israel in allt de Amoreers land, som då i samma land bodde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Och togo alla de Amoreers landsändar in, ifrån Arnon allt intill Jabbok, och ifrån öknene intill Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Så hafver nu Herren Israels Gud fördrifvit de Amoreer för sino folke Israel; och du vill nu taga dem in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Hafver din gud Chemos några fördrifvit, dem må du intaga, och låta oss intaga alla dem som Herren vår Gud för oss fördrifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Menar du, att du bättre rätt hafver, än Balak, Zipors son, de Moabiters Konung? Trätte icke han och stridde emot Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Så ändock Israel nu i trehundrad år bott hafver i Hesbon och dess döttrar, i Aroer och dess döttrar, och i alla städer, som ligga vid Arnon; hvi friaden I det icke på den tiden?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Jag hafver intet brutit emot dig, och du gör så illa emot mig, att du strider emot mig. Herren döme i dag emellan Israel och Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Men Ammons barnas Konung skötte intet efter de Jephthahs ord, som han böd honom till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Då kom Herrans Ande öfver Jephthah, och han drog igenom Gilead och Manasse, och igenom Mizpe, som i Gilead ligger, och ifrå Mizpe, som i Gilead ligger, inpå Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Och Jephthah lofvade Herranom ett löfte, och sade: Gifver du Ammons barn i mina hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Hvad som helst utu mins hus dörr kommer emot mig, när jag med frid igenkommer ifrån Ammons barn, det skall höra Herranom till; och jag skall offra det till bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Så drog Jephthah in på Ammons barn till att strida på dem; och Herren gaf dem i hans händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Och han slog dem, allt ifrån Aroer intilldess man kommer till Minnith, tjugu städer, och intill vingårdaplatsen, en mägtig stor slagtning. Och vordo så Ammons barn nedtryckte för Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Då nu Jephthah kom till Mizpa till sitt hus, si, då gick hans dotter ut emot honom, med pipande och dansande, och hon var enda barn, och han hade eljest ingen son eller dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Och som han fick se henne, ref han sin kläder, och sade: Aj! min dotter, du gör mig en hjertans sorg, och bedröfvar mig; ty jag hafver öppnat min mun inför Herranom, och kan icke kalla det tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Men hon sade: Min fader, hafver du öppnat din mun inför Herranom, så gör med mig såsom utaf din mun gånget är, efter Herren hafver hämnats på dina fiendar. Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Och hon sade till sin fader: Allenast beder jag dig om ett, att du unner mig två månader, att jag går neder på bergen, och begråter min jungfrudom med mina leksystrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Han sade: Gack; och låt henne gå i två månader. Så gick hon bort med sina leksystrar, och begret sin jungfrudom på bergen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Och efter två månader kom hon igen till sin fader, och han gjorde henne såsom han lofvat hade; och hon hade intet skaffa haft med någrom man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Och en sedvänja kom upp i Israel, att Israels döttrar gingo årliga till, och begreto Jephthahs den Gileaditens dotter, fyra dagar om året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Och de af Ephraim skriade, och gingo norrut, och sade till Jephthah: Hvi drogst du i strid emot Ammons barn, och kallade icke oss, att vi hade mått dragit med dig? Vi vilje uppbränna ditt hus med dig i elde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jephthah sade till dem: Jag och mitt folk hade en stor sak med Ammons barn; och jag kallade på eder, men I hulpen mig intet utu deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Då jag nu såg, att ingen frälsare på färde var, satte jag mina själ i mina hand, och drog åstad emot Ammons barn, och Herren gaf dem i mina hand. Hvi kommen I nu hitupp till mig, till att strida emot mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Och Jephthah församlade alla män i Gilead, och stridde emot Ephraim; och de män i Gilead slogo Ephraim, derföre, att de sade: Ären I dock, I Gileaditer, ibland Ephraim och Manasse, såsom de der af Ephraim beskyddas måste?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Och de Gileaditer togo in Jordans färjostad för Ephraim. När de nu sade: Vi äre ock de beskyddade af Ephraim, låt mig fara öfver; så sade de män af Gilead till honom: Äst du en Ephrait? När han nu svarade nej,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Så bådo de honom säga Schibboleth; så sade han Sibboleth, och kunde icke rätt säga det ut. Så togo de honom fatt, och dråpo honom vid färjostaden åt Jordan; så att på den tiden föllo af Ephraim tu och fyratio tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Och Jephthah dömde Israel i sex år. Och Jephthah den Gileaditen blef död, och vardt begrafven i de städer i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Efter dessom dömde Ibzan af BethLehem Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Han hade tretio söner, och tretio döttrar gifte han ut, och tretio döttrar tog han utanefter till sina söner; och dömde Israel i sju år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Och blef död, och blef begrafven i BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Efter dessom dömde Israel Elon, en Sebulonit, och dömde Israel i tio år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Och blef död, och vardt begrafven i Ajalon, uti Sebulons land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Efter dessom dömde Israel Abdon, Hillels son, en Pirgathonit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Han hade fyratio söner, och tretio sonasöner, som på sjutio åsnafålar redo. Han dömde Israel i åtta är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Och blef död, och vardt begrafven i Pirgathon uti Ephraims lande, på de Amalekiters berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Och Israels barn gjorde åter det ondt var för Herranom; och Herren gaf dem uti de Philisteers händer i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Men en man var i Zorga utaf Dans slägte, benämnd Manoah, och hans hustru var ofruktsam, och födde intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Och Herrans Ängel syntes hustrune, och sade till henne: Si, du äst ofruktsam, och föder intet; men du skall varda hafvandes, och föda en son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Så vakta dig nu, att du icke dricker vin, eller starka drycker, och att du intet orent äter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Ty du skall varda hafvandes, och föda en son, hvilkom ingen rakoknif skall komma på hufvudet; förty den pilten skall vara en Guds Nazir utaf moderlifvet; och han skall begynna till att frälsa Israel utu de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Då kom qvinnan, och talade med sin man och sade: En Guds man kom till mig, och han var till seendes såsom en Guds Ängel, ganska förskräcklig; så att jag intet frågade honom hvadan han var, eller hvart han ville; och han sade mig intet hur han het.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Men han sade till mig; Si, du skall varda hafvandes, och föda en son; så drick nu intet vin, eller starka drycker, och ät intet orent; förty pilten skall vara en Guds Nazir, ifrå moderlifvet allt intill hans död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Då bad Manoah Herran, och sade: Ack! Herre, låt den Guds mannen åter komma till oss, den du utsändt hafver, att han må lära oss, hvad vi skole göra med piltenom, som födas skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Och Gud hörde Manoahs röst; och Guds Ängel kom igen till qvinnona; och hon satt på markene, och hennes man Manoah var icke när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Då lopp hon hasteliga, och underviste det sinom man, och sade till honom: Si, den mannen hafver synts mig, som i dag kom till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoah stod upp, och följde qvinnona efter, och kom till mannen, och sade till honom: Äst du den mannen, som talade med qvinnone? Han sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Och Manoah sade: När nu sker såsom du sagt hafver, hurudana skola piltens seder och gerning vara?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Herrans Ängel sade till Manoah: Han skall vakta sig för allt det som jag qvinnone sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Han skall icke äta hvad utaf vinträ kommet är, och skall intet vin dricka, eller starka drycker, och äta intet orent; allt det jag henne budit hafver, skall han hålla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manoah sade till Herrans Ängel: Käre, låt oss behålla dig här, vi vilje tillreda dig ett kid af getterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Men Herrans Ängel svarade Manoah: Om du än behåller mig, så äter jag dock intet utaf ditt bröd; men vill du göra Herranom ett bränneoffer, så må du det offra; ty Manoah visste icke, att det var en Herrans Ängel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Och Manoah sade till Herrans Ängel: Huru heter du, att vi dig prisa måge, när du kommer såsom du sagt hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Herrans Ängel sade till honom: Hvi frågar du efter mitt Namn, det dock underligit är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Då tog Manoah ett kid af getterna och spisoffer, och lade det på en sten Herranom; och han gjorde det underliga; och Manoah med hans hustru sågo deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Och då lågen uppgick af altaret åt himmelen, för Herrans Ängel ock upp i altarens låga. Då Manoah och hans hustru det sågo, föllo de neder till jordena på sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Och Herrans Ängel syntes intet mer Manoah och hans hustru. Så förnam Manoah, att det var en Herrans Ängel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Och sade till sina hustru: Vi måste döden dö, att vi hafve sett Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Men hans hustru svarade honom: Om Herren hade velat dräpa oss, så hade han icke anammat bränneoffret och; spisoffret af våra händer, och hade icke tett oss allt detta, ej heller låtit oss detta höra, såsom nu skedt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Och qvinnan födde en son, och kallade honom Simson; och pilten växte, och Herren välsignade honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Och Herrans Ande begynte till att vara med honom, uti Dans lägre, emellan Zorga och Esthaol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Simson gick ned till Thimnath, och såg ena qvinno i Thimnath, utaf de Philisteers döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Och då han uppkom, underviste han det sinom fader och sine moder, och sade: Jag hafver sett ena qvinno i Thimnath, utaf de Philisteers döttrar; käre, gifver mig henne till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Hans fader och moder sade till honom: Är nu ingen qvinna ibland dina bröders döttrar, och i allt mitt folk, att du går bort, och tager dig hustru när de Philisteer, som oomskorne äro? Simson sade till sin fader: Gif mig denna; ty hon behagar min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Men hans fader och moder visste icke, att det var af Herranom; ty han sökte tillfälle emot de Philisteer; och de Philisteer rådde på den tiden öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Så gick Simson neder med sinom fader och sine moder till Thimnath; och som de kommo till vingårdarna vid Thimnath, si, då kom ett ungt lejon rytandes emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Och Herrans Ande föll öfver honom, och han ref det sönder i stycker, såsom man hade sönderrifvit ett kid, och hade dock platt intet i handene; och sade icke sinom fader eller sine moder, hvad han gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Då han nu kom ditneder, talade han med qvinnone, och hon behagade Simson i hans ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Och några dagar derefter kom han igen till att taga henne, och gick af vägenom till att bese aset af lejonet; si, då var en bisvärm i aset af lejonet, och hannog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Och han tog det i sina hand, och åt deraf i vägenom, och gick till sin fader och till sina moder, och gaf dem, så att de ock åto; men han sade dem intet deraf, att han hade tagit hannogen utaf lejonets as.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Och då hans fader kom ditneder till qvinnona, gjorde Simson der bröllop, såsom unga män pläga göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Och då de sågo honom, fingo de honom tretio stallbröder, som skulle vara när honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Men Simson sade till dem: Jag vill sätta eder ena gåto före; om I det utgäten, och råken rätt i dessa sju bröllopsdagar, så vill jag gifva eder tretio skjortor, och tretio högtidskläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Men kunnen I icke utråda henne, så skolen, I gifva mig tretio skjortor och tretio högtidskläder. Och de sade till honom: Sätt fram dina gåto, låt oss höra henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Han sade till dem: Af fråssarenom utgick mat, och, sötme utaf dem starka. Och de kunde i tre dagar icke råka uppå gåtona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'På sjunde dagen talade de till Simsons hustru: Locka för dinom man, att han utsäger oss gåtona, eller vi skole bränna dig och dins faders hus upp i eld; hafven I budit oss hit, till att; göra oss fattiga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Då gret Simsons hustru för honom, och sade: Du äst mig vred, och hafver mig icke kär; du hafver gifvit mins folks barnom ena gåto före, och hafver icke utsagt mig henne. Han sade till henne: Si, jag hafver icke utsagt henne minom fader, eller mine moder; skulle jag nu sägat för dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Och hon gret i de sju dagar för honom, medan bröllopet stod. På sjunde dagen sade han henne det, ty hon låg honom så hårdt uppå; och hon sade gåtona för sins folks barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Då sade de män af stadenom till honom på sjunde dagen, förra än solen gick neder: Hvad är sötare än hannogen; hvad är starkare än lejonet? Han sade till dem: Om I icke haden plöjt med minom kalf, I haden icke råkat på mina gåto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Och Herrans Ande föll på honom, och han gick neder till Askelon, och slog tretio män af dem, och tog deras kläder, och gaf högtidskläder dem som gåtona på råkat hade; och vardt ganska vred, och gick upp i sin faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Men Simsons hustru vardt gifven enom hans stallbroder, den honom tillydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Och det begaf sig efter några dagar, om hveteandene, att Simson sökte sina hustru med ett kid af getterna; och som han tänkte: Jag vill gå till mina hustru i kammaren, ville hennes fader icke låta honom in;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Och sade: Jag mente att du hade varit henne vred vorden, ty hafver jag gifvit henne dinom stallbroder; men hon hafver ena yngre syster, hon är dägeligare än hon, tag henne för desso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Då sade Simson till honom: Jag hafver en gång en rättfärdig sak emot de Philisteer; jag skall göra eder skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Och Simson gick bort, och fick trehundrade räfvar, och tog brandar, och vände ju en stjert emot den andra, och satte ju en brand emellan två stjertar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Och tände eld på dem, och släppte dem uti de Philisteers säd, och brände upp kärfvarna med den ståndande sädene, och vingårdarna, och oljoträn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Då sade de Philisteer: Ho hafver detta gjort? Då sades: Simson den Thimnitens måg, derföre att han hafver tagit honom hans hustru ifrå, och gifvit henne hans stallbroder. Då foro de Philisteer upp, och brände upp både henne och hennes fader i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Men Simson sade till dem: Jag låter eder det göra; jag vill ändå hämna mig på eder, och sedan vara tillfrids.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Och han slog dem hårdeliga, både på skuldror och på länder; och gick neder, och bodde uti en bergklyfto i Etham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Då drogo de Philisteer upp, och belade Juda; och gåfvo sig neder till Lehi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'De af Juda sade: Hvi hafven I dragit hitupp emot oss? De svarade: Vi äre komne hitupp till att binda Simson, att vi måge göra honom, såsom han oss gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Så drogo tretusend män af Juda neder i bergklyftena i Etham, och sade till Simson: Vetst du icke, att de Philisteer äro rådande öfver oss? Hvi hafver du så gjort emot oss? Han sade till dem: Såsom de hafva gjort emot mig, så hafver jag gjort emot dem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'De sade till honom: Vi äre komne hitneder till att binda dig, och få dig de Philisteer i händer. Simson sade till dem: Så svärjen, att I viljen intet hinder göra mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'De svarade honom: Vi vilje intet hinder göra dig; utan vi vilje allenast binda dig, och antvarda dig dem i händer, och vilje intet dräpa dig; och de bundo honom med tu ny tåg, och förde honom upp ifrå klippone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Och då han kom intill Lehi, skriade de Philisteer, och kommo emot honom; men Herrans Ande föll på honom, och tågen på hans armar vordo såsom blår, de af eld förbrände äro, så att banden på hans händer försmulto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Och han råkade en rutten åsnakindbåga; han räckte ut sina hand och tog honom, och slog dermed tusende man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Och Simson sade: Der ligga de ihop; med en åsnakindbåga hafver jag slagit tusende män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Och då han det utsagt hade, kastade han kindbågan utu sine hand, och kallade det rummet RamathLehi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Och som han begynte svårliga törsta, åkallade han Herran, och sade: Du hafver en så stor salighet gifvit igenom dins tjenares hand, och nu måste jag dö i törst, och falla uti de oomskornas händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Då öppnade Gud ena oxlatand i kindbåganom, och der gick ut vatten; och som han drack, kom hans ande igen, och vederkvicktes; derföre heter ock det rummet åkallarens kindbågabrunn, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Och han dömde Israel uti de Philisteers dagar i tjugu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Och Simson gick till Gasa, och fick der se ena sköko, och lade sig när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Då vardt sagdt de Gasiter: Simson är kommen härin; och de omhvärfde honom, och läto taga vara på honom i stadsportenom i hela nattene: och voro stilla i hela nattene, och sade: I morgon, då ljust varder, vilje vi slå honom ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Men Simson låg intill midnatt. Då stod han upp om midnatt, och fattade båda dörrarna i stadsporten med båda dörrträn, och skottbommen, och lade dem på sina axlar, och bar dem upp på bergshöjdena för Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Derefter fick han kärlek till ena qvinno vid den bäcken Sorek, hvilken het Delila.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Upp till henne kommo de Philisteers Förstar, och sade till henne: Tala så vid honom, att du kan få se, hvarutinnan han sådana stor kraft hafver, och hvarmed vi kunne varda honom öfverhändige, så att vi finge bindan och tvingan; så vilje vi gifva dig hvar våra tusende och hundrade silfpenningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Och Delila sade till Simson: Käre, säg mig, hvaruti står din stora starkhet; och hvarmed man kunde binda dig, och tvinga dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson sade till henne: Om man bunde mig med sju ny tåg, som ännu intet förtorkad voro, så vorde jag svag, och såsom en annor menniska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Då förde de Philisteers Förstar upp till henne sju ny tåg, som ännu intet förtorkad voro, och hon band honom dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Och de hade håll på honom när henne i kammaren; och hon sade till honom: De Philisteer öfver dig, Simson! Och han slet sönder tågen, såsom ett vridet snöre söndergår, när det af eld förbrändt är; och vardt icke kunnigt, hvarutinnan hans starkhet var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Då sade Delila till Simson: Si, du hafver gäckat mig, och ljugit för mig; säg mig dock nu, hvarmed man dig binda kan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Han svarade: Om jag vorde bunden med ny tåg, der ännu intet arbete med gjordt är, så vorde jag svag, och såsom en annor menniska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Så tog Delila ny tåg, och band honom dermed, och sade: De Philisteer öfver dig, Simson! Och de hade håll på honom i kammaren; och han slet sönder dem utaf sina armar, såsom ett snöre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Delila sade till honom: Du hafver ännu gäckat mig, och ljugit för mig. Käre, säg mig dock, hvarmed man kan dig binda? Han svarade henne: Om du flätade sju lockar af mitt hufvud uti ett fläteband.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Och hon fäste dem in med en nagla, och sade till honom: De Philisteer öfver dig, Simson! Och han vaknade upp af sinom sömn, och drog de flätade lockar med nagla och fläteband ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Då sade hon till honom: Huru kan du säga, att du hafver mig kär, efter ditt hjerta är dock icke när mig? I tre gånger hafver du gäckat mig, och icke sagt mig, hvarutinnan din stora starkhet är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Och som hon alla dagar låg honom uppå med sådana ordom, och lät honom ingen ro få, vardt hans själ uppgifven allt intill döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Och sade henne allt sitt hjerta, och sade till henne: På mitt hufvud hafver aldrig någon rakoknif kommit, ty jag är en Guds Nazir af moderlifvet; om man rakar håret af mig, så går min starkhet ifrå mig, så att jag varder svag, lika som andra menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Då nu Delila såg, att han hade uppenbarat henne allt sitt hjerta, sände hon bort, och lät kalla de Philisteers Förstar, och sade: Kommer än en gång hitupp; ty han hafver uppenbarat mig allt sitt hjerta. Då kommo de Philisteers Förstar upp till henne, och hade penningarna med sig i sine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Och hon lät honom sofva på sitt knä, och kallade en, som rakade honom bort de sju lockar af hans hufvud; och hon begynte till att tvinga honom, och hans magt var gången ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Och hon sade till honom: De Philisteer öfver dig, Simson! Som han nu vaknade af sinom sömn, tänkte han: Jag vill gå ut, såsom jag i flera resor gjort hafver, jag vill slita mig lös; och visste icke, att Herren var viken ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Men de Philisteer grepo honom, och stungo honom ögonen ut, och förde honom neder till Gasa, och bundo honom med två kopparfjettrar; och han måste mala i fängelset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Och hans hufvudhår begynte åter växa, der han rakad var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Då församlade sig de Philisteers Förstar, till att göra sinom gud Dagon ett stort offer, och göra sig glada, och sade: Vår gud hafver gifvit oss vår fienda Simson i våra händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Sammalunda när folket såg honom, prisade de deras gud: ty de sade: Vår gud hafver gifvit vår fienda i våra händer, den vårt land förderfvade, och slog många af oss ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Då nu deras hjerta väl gladt var, sade de: Låt hemta Simson, att han må spela för oss. Så hemtade de Simson utu fängelset, och han spelade för dem, och de ställde honom emellan två pelare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Men Simson sade till drängen, som ledde honom vid handena: Låt mig taga på pelarena, på hvilka huset hänger, att jag må stödja mig derintill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Och huset var fullt med män och qvinnor; och de Philisteers Förstar voro der ock alle, och på taket vid tretusend män och qvinnor, de som sågo till huru Simson spelade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Men Simson åkallade Herran, och sade: Herre, Herre, tänk uppå mig, och styrk mig, Gud! i denna gången, att jag för båda min ögon må ena reso hämnas på de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Och han fattade de två medelpelare, på hvilka huset hängde, och stödde sig på dem, och tog den ena i den högra, och den andra i den venstra handena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Och sade: Min själ dö med de Philisteer! och han böjde dem krafteliga. Så föll huset uppå Förstarna, och uppå allt folket, som derinne var, så att de döde, som han drap i sin död, voro flere, än de som han drap medan han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Då kommo hans bröder ditneder, och hela hans faders hus, och togo honom upp, och båro honom upp, och begrofvo honom i hans faders Manoahs graf, emellan Zorga och Esthaol. Men han dömde Israel i tjugu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'En man var på Ephraims berg, benämnd Micha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Han sade till sina moder: De tusende och hundrade silfpenningar, som äro tagne ifrå dig, och som du svorit öfver, och sagt för min öron, si, de samma penningar äro när mig: jag hafver tagit dem till mig. Då sade hans moder: Välsignad vare min son Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Så fick han sine moder de tusende och hundrade silfpenningar igen; och hans moder sade: Jag hafver helgat de penningarna Herranom ifrå mine hand, för min son, till att man må göra ett gjutet beläte; derföre så får jag dig dem nu igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Men han fick sine moder penningarna igen. Då tog hans moder tuhundrade silfpenningar, och fick dem till guldsmeden; han gjorde henne ett gjutet beläte; det var sedan i Micha huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Och den mannen Micha hade så ett guds hus; och han gjorde en lifkjortel, och afgudar, och fyllde enom sinom son handena, att han vardt hans Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'På den tiden var ingen Konung i Israel, och hvar och en gjorde såsom honom tyckte godt vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Men en ung man var på den tiden af Bethlehem Juda, ibland Juda slägte, och han var en Levit, och var dersammastäds främmande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Men han drog utu BethLehem, Juda stad, till att vandra hvart han kunde; och då han kom på Ephraims berg till Micha hus, på det han skulle hålla sin väg fram,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Frågade honom Micha: Hvadan kommer du? Han svarade honom: Jag är en Levit af BethLehem Juda, och vandrar hvart jag kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Micha sade till honom: Blif när mig, du skall vara min fader, och min Prest; jag vill gifva dig årliga tio silfpenningar, och någor förenämnd kläder, och din födo. Och Leviten gick med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Och Leviten tog till att blifva när mannen om; och han höll den unga mannen såsom en son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Och Micha fyllde Levitenom handena, så att han vardt hans Prester, och blef så i Micha huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Och Micha sade: Nu vet jag, att Herren varder mig godt görandes, efter jag hafver en Levit till Prest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'På den tiden var ingen Konung i Israel; och Dans slägte sökte sig en arfvedel, der de måtte bo; ty intill den dagen var ännu ingen arflott fallen för dem ibland Israels slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Och Dans barn sände utaf sitt slägte och sina landsändar fem höfvitsmän, stridsamma män, ifrå Zorga och Esthaol, till att bespeja landet, och ransaka om det, och sade till dem: Går åstad, och bespejer landet; och de kommo uppå Ephraims berg till Micha hus, och blefvo der öfver nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Och som de nu voro med Micha husfolk, kände de röstena af dem unga mannenom Levitenom, och gingo bort till honom, och sade till honom: Ho hafver kommit dig hit? Hvad gör du här? Och hvad hafver du här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Han svarade dem: Så och så hafver Micha gjort emot mig, och hafver lejt mig, att jag skall vara hans Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'De sade till honom: Käre, fråga Gud till, att vi måge få veta om vår väg, som vi vandrom, skall oss lyckosam varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Presten svarade dem: Går åstad med frid; edar väg är rätt för Herranom, den I vandren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Så gingo de fem män åstad, och kommo till Lais, och sågo att det folk, som derinne var, bodde säkert, efter de Zidoniers sed, stilla och säkre; och ingen var, som dem något bekymmer gjorde i landena, eller hade det under sig; och voro långt ifrå de Zidonier, och hade intet beställa med något folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Och de kommo till sina bröder i Zorga och Esthaol; och deras bröder sade till dem: Huru går det till med eder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'De sade: Upp, låt oss draga upp till dem; ty vi hafve besett landet, det är ganska godt; derföre skynder eder, och varer icke sene till att draga, att I mågen komma och taga landet in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'När I kommen, varden I finnande ett säkert folk, och landet är vidt och bredt; ty Gud hafver det gifvit i edra händer, en sådana plats, der intet fattas som på jordene är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Så drogo ut af Dans slägte, ifrå Zorga och Esthaol, sexhundrad män, väl väpnade till strids;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Och drogo ditupp, och lägrade sig i KiriathJearim, i Juda; deraf kallas det rummet Dans lägre, allt intill denna dag; och det är bakför KiriathJearim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Och dädan gingo de upp på Ephraims berg, och kommo till Micha hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Då svarade de fem män, som hade varit utgångne till att bespeja Lais land, och sade till sina bröder: Veten I ock, att i dessom husom är en lifkjortel, af gudar och gjutet beläte? I mågen tillse, hvad eder till görandes är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'De drogo dit, och kommo i den unga mansens Levitens hus, uti Micha hus, och helsade honom vänliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Men de sexhundrad väpnade, med deras harnesk, som voro utaf Dans barnom, stodo för dörrene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Och de fem män, som hade utdragne varit till att bespeja landet, gingo upp, och kommo dit, och togo belätet, lifkjortelen, och de gjutna afgudarna; emedan stod Presten för portenom när de sexhundrad väpnade i deras harnesk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Som nu hine voro komne in uti Micha hus, och togo belätet, lifkjortelen, och de gjutna afgudarna, sade Presten till dem: Hvad gören I?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'De svarade honom: Tig, och håll munnen på dig, och kom med oss, att du må blifva vår fader och Prester. Är det dig bättre, att du äst Prester uti ens mans huse, än uti en hel slägt och ätt i Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Det behagade Prestenom väl; och tog både lifkjortelen, afgudarna, och belätet, och gaf sig midt ibland folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Och då de vände om, och drogo sin väg, skickade de barnen, och boskapen, och allt det bästa som de hade, framför sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Som de nu voro fjerran komne ifrå Micha hus, ropade de män, som i husen voro vid Micha hus, och följde efter Dans barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Och ropade till Dans barn. Och de vände sitt ansigte om, och sade till Micha: Hvad skadar dig, att du så ropar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Han svarade: I hafven tagit bort mina gudar, som jag gjort hafver, och Presten, och dragen edra färde, och hvad hafver jag nu mer? Och I sägen ändå till mig: Hvad skadar dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Men Dans barn sade till honom: Låt dina röst intet höras när oss, att icke öfverfalla dig vrede män, och du låter dina själ till, och dins hus själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Så gingo Dans barn sin väg. Och Micha, då han såg att de voro honom för starke, vände om, och kom igen till sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Men de togo det Micha gjort; hade, och den Presten, som han hade, och kommo till Lais, till ett stilla och säkert folk, och slogo dem med svärdsegg, och uppbrände staden med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Och ingen var, som dem undsatte, ty han låg långt ifrå Zidon, och hade med ingom beställa; och han låg i den dalen, som ligger vid BethRehob. Så byggde de staden, och bodde deruti;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Och kallade honom Dan, efter sins faders Dans namn, hvilken af Israel född var; och staden het tillförene Lais.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Och Dans barn uppsatte sig belätet; och Jonathan, Gersons son, Manasse sons, och hans söner voro Prester uti de Daniters slägte, allt intill den tiden, som de vordo förde fångne utu landena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Och satte alltså ibland sig det Micha beläte, som han gjort hade, så länge som Guds hus var i Silo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Uti den tiden var ingen Konung i Israel. Och en Levitisk man var en främling vid sidone af Ephraims berg, och hade tagit sig ena frillo till hustru uti BethLehem Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Och som hon bedref hor när honom, lopp hon ifrå honom till sins faders hus till BethLehem Juda, och blef der i fyra månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Och hennes man stod upp, och for efter henne, på det han skulle tala vänliga med henne, och hemta henne igen till sig. Och han hade en dräng och ett par åsnar med sig. Och hon hade honom in uti sins faders hus; och då qvinnones fader såg honom, vardt han glad, och undfick honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Och hans svär, qvinnones fader, höll honom uppe, så att han blef der i tre dagar när honom; åto och drucko, och blefvo der om nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'På fjerde dagen voro de bittida uppe, och han stod upp, och ville färdas; då sade qvinnones fader till sin måg: Styrk ditt hjerta med en beta bröd, sedan mån I fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Och de satte sig, och åto hvar med annan, och drucko. Så sade qvinnones fader till mannen: Käre, blif öfver nattena, och ditt hjerta vare lustigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Men mannen stod upp, och ville färdas, men hans svär nödgade honom, så att han blef den nattena der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Om morgonen på femte dagen var han uppe, och ville färdas; då sade qvinnones fader: Käre, vederqvick ditt hjerta, och låt oss töfva, så länge något lider uppå dagen; och de åto med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Och mannen stod upp och ville fara med sine frillo, och med sinom dräng; men hans svär, qvinnones fader, sade till honom: Si, dagen är framliden, och aftonen är för handene, blif qvar i natt; si, här är herberge ännu i denna dagen; blif här öfver natten, att ditt hjerta må vara lustigt; i morgon stån I bittida upp, och dragen edra färde till dina hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Men mannen ville icke blifva öfver nattena, utan stod upp, och for sin väg, och kom inför Jebus, det är Jerusalem, och hans par åsnar klefjade, och hans frilla med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Som de nu kommo intill Jebus, förled fast dagen, och drängen sade till sin herra: Käre, Kom och låt oss draga in uti de Jebuseers stad, och blifva der öfver nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Men hans herre sade till honom: Vi vilje icke draga in uti de främmandes stad, som icke äro af Israels barn; utan vi vilje fram bätter till Gibea;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Och sade till sin dräng: Gack uppå, att vi måge komma någorstäds till nattena, antingen i Gibea eller i Ramah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Och de drogo framåt, och reste; och solen gick dem neder hardt invid Gibea, som ligger i BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Och der drogo de in, till att blifva der i Gibea öfver nattena. Då han kom derin, satte han sig på gatone i stadenom; ty der var ingen, som dem ville herberga i sino huse öfver nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Och si, der kom en gammal man utaf markene, ifrå sitt arbete om aftonen; och han var också utaf Ephraims berg, och en främling i Gibea; men folket i det rummet voro Jemini barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Och då han upplyfte sin ögon, såg han den främmande mannen på gatone, och sade till honom: Hvart vill du? Och hvadan kommer du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Han svarade honom: Vi äre komne ifrå BethLehem Juda, och farom intill sidona af Ephraims berg, dädan jag är; och var faren till BethLehem Juda, och nu far jag till Herrans hus, och ingen vill herberga mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Vi hafve halm och foder till våra åsnar, och bröd och vin för mig, och dine tjenarinno, och för drängen, som med dinom tjenare är; så att oss fattas intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Den gamle mannen sade: Var tillfrids; allt det dig fattas, finner du när mig; allenast blif icke öfver nattena på gatone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Och han hade honom i sitt hus, och gaf åsnomen foder; och de tvådde sina fötter, och åto och drucko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Och som deras hjerta begynte vara gladt, si, då kommo män af stadenom, Belials barn, och belade huset, och klappade på dörrena, och sade till den gamla mannen, värden i huset: Låt oss få den mannen hitut, som i ditt hus kommen är, att vi måge känna honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Men mannen husvärden gick ut till dem, och sade till dem: Icke så, mine bröder, görer icke detta onda; efter denne mannen är kommen i mitt hus; görer icke en sådana galenskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Si, jag hafver ena dotter, den ännu en jungfru är, och denne hafver ena frillo, dem vill jag låta komma ut till eder, att I förnedren dem, och gören med dem hvad eder täckes; men på denna mannen görer icke en sådana galenskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Men männerna ville intet lyda honom. Så tog mannen sina frillo, och hade henne ut till dem; den kände de, och hade sig skändeliga med henne i den hela nattene allt intill morgonen; och som morgonrodnen uppgick, läto de gå henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Då kom qvinnan, litet för dagningen, inför dörrena af mansens hus, der hennes herre inne var, och föll der omkull, och låg der intill ljust var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Då nu hennes herre uppstod om morgonen, och lät upp dörrena af huset, och gick ut till att fara sin väg; si, då låg hans frilla för dörrene af huset, och hennes händer på tröskelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Och han sade till henne: Statt upp, låt oss gå; men hon svarade honom intet. Så tog han henne på sin åsna, redde sig till, och for hem till sitt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Som han hemkom, tog han en knif, och tog sina frillo, och styckade henne, med ben och med allo, i tolf stycker, och sände till alla Israels landsändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Alle de, som det sågo, sade: Sådant är aldrig skedt eller sedt, sedan Israels barn kommo utur Egypti land, intill denna dag: Nu, betänker eder häröfver, och rådens vid, och säger till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Så drogo Israels barn ut, och församlade sig ihop, såsom en man, ifrå Dan allt intill BerSeba, och ifrå Gileads land, intill Herran i Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Och gingo tillhopa utaf alla vrår, all folk af all Israels slägte i Guds menighet, fyrahundradetusend män till fot, som svärd utdrogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Men BenJamins barn fingo höra, att Israels barn voro dragne upp till Mizpa, och Israels barn sade: Säger, huru det onda tillgånget är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Då svarade Leviten, qvinnones man, som dräpen var, och sade: Jag kom till Gibea i BenJamin med mine frillo, till att blifva der öfver nattena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Då hofvo sig upp borgarena i Gibea emot mig, och belade mig i huset, om nattena, och ville slå mig ihjäl, och skämde min frillo, så att hon blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Så tog jag min frillo, och styckade henne, och sände det i alla Israels arfs mark; förty de hade gjort en slem ting, och galenskap i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Si, nu ären I här alle Israels barn, rådens vid, hvad I skolen göra dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Då reste sig allt folket upp, såsom en man, och sade: Ingen gånge hem i sina hyddo eller i sitt hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Utan det vilje vi nu göra emot Gibea; låt oss kasta lott;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Och taga tio män af hundrade, och hundrade af tusend, och tusend af tiotusend, af alla Israels slägter, att de besörja spisning för folket, att de måga komma, och göra med Gibea BenJamins, efter all deras galenskap, som de i Israel bedrifvit hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Så församlade sig till staden alle Israels män, såsom en man, och förbundo sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Och Israels slägter sände några män till alla BenJamins slägt, och läto säga dem: Hvad är det för en ond ting, som när eder skedd är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Så får oss nu ut de män, Belials barn i Gibea, att vi måge dräpa dem, och låta det onda komma ifrån Israel. Men BenJamins barn ville icke lyda sina bröders Israels barnas röst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Utan församlade sig utu städerna intill Gibea, till att draga ut till strids emot Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Och vordo på den dagen talde BenJamins barn utu städerna, sex och tjugu tusend män, som svärd utdrogo; förutan de borgare i Gibea, de vordo talde sjuhundrade utvalde män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Och ibland allt detta folket voro sjuhundrade utvalde män, som vensterhändte voro, och kunde med slungor drabba på ett hår, så att de intet felade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Men de män af Israel, förutan de af BenJamin, vordo talde fyrahundradetusend män, som svärd förde, och stridsamme män voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Israels barn stodo upp, och drogo upp till Guds hus, och frågade Gud, och sade: Ho skall draga ditupp för oss till att begynna striden emot BenJamins barn? Herren sade: Juda skall begynna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Alltså stodo Israels barn om morgonen upp, och lägrade sig för Gibea;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Och hvar och en af Israel gick ut till att strida med BenJamin, och skickade sig till att strida emot Gibea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Då föllo BenJamins barn ut af Gibea, och slogo på den dagen af Israel tu och tjugu tusend män till markena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Men folket Israels män förmannade sig, och redde sig till att ytterligare strida på samma platsen, der de sig i den förra dagen redt hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Och Israels barn drogo upp, och greto för Herranom allt intill aftonen, och frågade Herran, och sade: Skole vi mer falla till och strida med BenJamins barn, våra bröder? Herren sade: Drager upp till dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Och då Israels barn trädde den andra dagen till att strida emot BenJamins barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Föllo de BenJamiter utu Gibea emot dem på samma dagen, och slogo ännu till markena adertontusend män af Israels barn, som alle svärd förde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Då drogo all Israels barn upp, och allt folket, och kommo till Guds hus, och greto, och blefvo der för Herranom, och fastade den dagen intill aftonen, och offrade bränneoffer och tackoffer för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Och Israels barn frågade Herran, och dersammastäds var Guds förbunds ark på den tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Och Pinehas, Eleazars son, Aarons sons, stod för honom på den tiden, och sade: Skole vi mer draga ut till att strida emot BenJamins barn, våra bröder, eller skall jag vända igen? Herren sade: Drager ditupp; i morgon skall jag gifva dem i edra händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Och Israels barn beställde ett bakhåll omkring staden Gibea;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Och drogo så Israels barn upp på tredje dagen till BenJamins barn; och skickade sig emot Gibea, såsom i de två gånger tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Då drogo BenJamins barn ut emot folket, och gåfvo sig ifrå staden, och begynte till att slå och sarga några af folket, såsom förr i de två gånger, i markene på två vägar, den ene går till BethEl, och den andre till Gibea, vid tretio män i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Då tänkte BenJamins barn: De äro slagne för oss såsom tillförene. Men Israels barn sade: Låt oss fly, att vi måge komma dem ifrå staden ut uppå vägarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Så reste upp alle män af Israel, hvar af sitt rum, och skickade sig i BaalThamar, och det bakhållet af Israel gaf sig upp utu sitt rum, ifrå Gaba kulo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Och kommo in mot Gibea tiotusend män, utvalde af hela Israel, så att striden vardt skarp; men de visste icke, att dem ondt tillstundade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Alltså slog Herren BenJamin för Israels barn, så att Israels barn på den dagen förderfvade fem och tjugu tusend och hundrade män i BenJamin, som alle svärd förde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Ty då BenJamins barn sågo, att de slagne voro, gåfvo Israels män dem rum; ty de förläto sig på bakhållet, som de hade beställt invid Gibea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Och bakhållet skyndade sig ock, och drogo fram till Gibea, och stormade till, och slogo den hela staden med svärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Och de hade en lösen sig emellan, de män af Israel och bakhållet, till att öfverfalla dem med svärd, när röken af stadenom uppslog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Då nu de män af Israel vände sig i stridene, och BenJamin begynte till att slå och försarga i Israel vid tretio män; och tänkte: De äro slagne för oss såsom i den förra stridene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Så begynte slå en rök af staden rättupp. Och BenJamin vände sig tillbaka; si, då gick röken af hela stadenom upp i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Och de män af Israel vände ock om; då förskräcktes de män af BenJamin; förty de sågo, att dem tillstundade ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Och de vände sig för de män af Israel på den vägen till öknena; men striden fullföljde dem; dertill de som af städerna inkomne voro, de förderfvade dem derinne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Och de kringhvärfde BenJamin, och fullföljde dem allt intill Menuah, och förtrampade dem inför Gibea österut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Och föllo af BenJamin adertontusend män, som alle stridsamme män voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Då vände de sig, och flydde åt öknena till den bergklippon Rimmon; men på den samma vägen slogo de femtusend män, och följde dem efter allt intill Gideom, och slogo dem af tutusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Och så föllo på den dagen af BenJamin fem och tjugu tusend män, som svärd förde, och alle stridsamme män voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Allenast sexhundrad män vände sig, och flydde åt öknena till den bergklippon Rimmon; och blefvo i Rimmons bergklippo i fyra månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Och de män af Israel kommo igen till BenJamins barn, och slogo med svärdsegg dem i stadenom, både folk och fä, och allt det man fann; och alla de städer, som de funno, uppbrände de i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Och de män af Israel hade svorit i Mizpa, och sagt: Ingen af oss skall gifva sina dotter de BenJamiter till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Och folket kom till Guds hus, och blef der för Gudi allt intill aftonen; och de upphofvo sina röst, och greto svårliga,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Och sade: O Herre Israels Gud, hvi är detta skedt i Israel, att en slägt är i dag nederlagd i Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Och andra dagen var folket bittida uppe och byggde der ett altare, och offrade bränneoffer och tackoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Och Israels barn sade: Hvilken är den af Israels slägter, som icke hit uppkommen är med menighetene inför Herran? Ty en stor ed var gången, att den som icke uppkomme till Herran i Mizpa, han skulle döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Och Israel ångrade sig öfver sin broder BenJamin, och sade: I dag är en slägt i Israel nederlagd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Huru vilje vi göra, att de som qvare äro måga få hustrur? Ty vi hafve svorit vid Herran, att vi icke skole gifva dem hustrur utaf våra döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Och sade: Hvilken är af Israels slägter, som icke är kommen hitupp till Herran i Mizpa? Och si, der hade ingen varit i menighetenes lägre utaf Jabes i Gilead;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Ty de talde folket, och si, der var ingen borgare af Jabes i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Då sände menigheten tolftusend män af stridsamma män, och bödo dem, och sade: Går bort, och slår med svärdsegg de borgare i Jabes i Gilead, med hustrur och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Dock skolen I så göra: allt det mankön är, och alla de qvinnor, som när manne legat hafva, skolen I tillspillogifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Och de funno när de borgare i Jabes i Gilead fyrahundrade pigor, som jungfrur voro, och när ingen man legat hade; dem förde de i lägret till Silo, som ligger i Canaans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Då sände hela menigheten bort, och lät tala med BenJamins barn, som lågo i bergklippone Rimmon, och kallade dem vänliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Alltså kommo BenJamins barn igen på den tiden; och de gåfvo dem till hustrur de som de vid lif behållit hade utaf Jabes qvinnfolk i Gilead; och funno så inga flera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Då ångrade sig folket öfver BenJamin, att Herren hade gjort ett splitter i Israels slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Och de äldste i menighetene sade: Hvad vilje vi göra, att de som öfver äro måga ock få hustrur? Ty de qvinnor i BenJamin äro förgjorda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Och sade: De måste ju behålla sitt arf, som igenblefne äro af BenJamin, att icke en slägt nederlägges i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Och vi kunne icke gifva dem våra döttrar till hustrur; ty Israels barn hafva svorit och sagt: Förbannad vare den, som de BenJamiter gifver hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Och de sade: Si, det är en årlig Herrans högtid i Silo, norrut ifrå Guds hus, österut på den vägen, som drager ifrå BethEl intill Sichem, och söder ifrå Lebona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Och de bödo BenJamins barnom, och sade: Går bort, och sitter i försåt i vingårdarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'När I då sen, att Silo döttrar gå ut i dans, så gifver eder hasteliga utu vingårdarna, och tager hvar och en sig en hustru af Silo döttrar, och går uti BenJamins land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'När nu deras fäder eller bröder komma till att beklaga sig för oss, vilje vi säga till dem: Varer dem barmhertige för våra skull; förty vi hafve icke tagit dem hustrur med strid, utan I vill en icke gifva dem dem; det är nu edor skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'BenJamins barn gjorde ock så, och togo qvinnor efter sitt tal, hvilka de röfvade utaf dansen; och foro bort, och bodde i sin arfvedel, och byggde städer, och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Israels barn foro ock dädan på den tiden, hvar och en till sina slägt, och till sina ätt; och drogo ut dädan, hvar och en till sin arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'På den tiden var ingen Konung i Israel; utan hvar och en gjorde hvad honom tycktes rätt vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'På den tiden, då domare regerade, vardt en hård tid i landena; och en man af BethLehem Juda for bort, och var främmande uti de Moabiters land, med sine hustru och två söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Han het EliMelech, och hans hustru Naemi, och hans två söner Mahlon och Chilion, de voro Ephrateer af BethLehem Juda; och då de kommo in i de Moabiters land, blefvo de der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Och EliMelech, Naemis man, blef död; och hon blef qvar med sina två söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'De togo Moabitiska hustrur; den ena het Arpa, den andra Ruth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Och som de hade bott der i tio år, blefvo de både döde, Mahlon och Chilion, så att qvinnan var qvar efter båda sina söner och sin man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Så gjorde hon redo med sina två sonahustrur, och for ut igen af de Moabiters land; ty hon hade förnummit i de Moabiters land, att Herren hade sökt sitt folk, och gifvit dem bröd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Och gick ut ifrå det rum, der hon varit hade, och båda hennes sonahustrur med henne. Och då hon i vägen var hem åt Juda land igen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Sade hon till båda sina sonahustrur: Går edra färde, och vänder om igen, hvar edra till sins moders hus. Herren göre barmhertighet med eder, såsom I med de döda och med mig gjort hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herren gifve eder, att I mågen finna ro, hvar i sins mans hus. Och hon kysste dem. Då hofvo de sina röst upp, och greto:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Och sade till henne: Vi vilje gå med dig till ditt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Men Naemi sade: Vänder om, mina döttrar; hvi viljen I gå med mig? Huru kan jag nu härefter hafva barn i mitt lif, som edra män blifva måtte?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Vänder om, mina döttrar, och går edra färde: ty jag är nu för gammal, till att gifva mig manne i våld. Och om jag än sade: Det är förhoppandes, att jag i denna nattene må taga mig en man, och föda barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Så kunnen I dock icke bida, intilldess de varda store; ty I föråldradens, så att I kunden inga män hafva. Ingalunda, mina döttrar; ty det gör mig ångest för edra skull; ty Herrans hand är utgången öfver mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Då hofvo de sina röst upp, och greto ännu mer; och Arpa kysste sina sväro; men Ruth blef när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Men hon sade: Si, din svägerska hafver vändt tillbaka till sitt folk, och till sin gud. Vänd ock du om efter dina svägersko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruth svarade: Tala mig icke i det sinnet, att jag skall öfvergifva dig, och vända tillbaka igen ifrå dig; dit du går, dit vill jag ock gå; der du blifver, der blifver jag ock. Ditt folk är mitt folk, och din Gud är min Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Der du dör, der dör jag ock, der vill jag ock begrafven varda. Herren göre mig det och det, om döden icke skall skilja oss åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Som hon nu såg, att hon stod fast i det sinnet, att hon ville följa henne, vände hon åter att tala mer derom med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Så gingo de båda med hvarandra, intilldess de kommo till BethLehem. Och då de kommo till BethLehem, rörde sig hela staden öfver dem, och sade: Är detta Naemi?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Men hon sade till dem: Kaller mig icke Naemi, utan Mara; ty den Allsmägtige hafver svårliga bedröfvat mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Full drog jag härut, och tomman hafver Herren låtit mig komma igen. Hvi kallen I mig då Naemi, efter Herren hafver så tryckt mig, och den Allsmägtige hafver bedröfvat mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Och det var på den tiden, då bjugganden var begynt, då Naemi och hennes sonahustru Ruth, den Moabitiskan, igenkommo af de Moabiters land till BethLehem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Och der var en man, Naemis mans frände af EliMelechs slägt, benämnd Boas; och var en ärlig man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Och Ruth, den Moabitiskan, sade till Naemi: Låt mig gå ut på åkren, och hemta ax efter den som jag nåde för finner. Hon sade till henne: Gack, min dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Hon gick åstad, kom och hemtade upp efter dem som skåro på åkrenom; och det hände, att den åkren var Boas arfvedel, som af EliMelechs slägt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Och si, Boas kom ifrå BethLehem och sade till skördemännerna: Herren vare med eder. De svarade: Herren välsigne dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Och Boas sade till sin tjenare, som satter var öfver skördemännerna: Hvem hörer den unga qvinnan till?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Drängen, som öfver skördemännerna sätter var, svarade och sade: Det är den Moabitiska qvinnan, som med Naemi igenkommen är ifrå de Moabiters land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ty hon sade: Käre, låt mig upphemta och församla emellan kärfvarna efter skördemännerna; och är så kommen, och hafver ståndit sedan i morgons intill nu, och hafver icke en tid gångit hem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Då sade Boas till Ruth: Hör, min dotter, du skall icke gå bort på någon annan åker till att hemta; och skall icke heller gå hädan, utan håll dig intill mina pigor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Och tag vara uppå, hvar de skära på åkren, och gack efter dem. Jag hafver sagt mina dränger, att ingen skall komma vid dig; och om dig törster, gack till karen, och drick der mina dränger hemta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Då föll hon på sitt ansigte, och tillbad ned på jordene, och sade till honom: Hvarmed hafver jag den nåden funnit för din ögon, att du känner mig, som dock främmande är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boas svarade och sade till henne: Mig är sagdt allt det du gjort hafver med dine sväro efter dins mans död, att du hafver öfvergifvit din fader och dina moder, och ditt fädernesland, och farit till det folk, som du tillförene intet kände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herren vedergälle dig det du gjort hafver; och din lön vare fullkommen när Herranom Israels Gud, till hvilken du kommen äst, till att hafva tröst under hans vingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Hon sade: Låt mig finna nåd för din ögon, min Herre; ty du hafver hugsvalat mig, och talat dine tjenarinno vänliga till, ändock jag icke är såsom någon af dina pigor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Boas sade till henne: När måltid är, så kom hit till med, och ät bröd, och doppa, din beta uti ättikona. Så satte hon sig när skördemännerna; och han lade henne torkad ax före, och hon åt, och vardt mätt, och lät blifva något qvart.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Och då hon stod upp till att hemta, böd Boas sina dränger, och sade: Låter henne ock hemta emellan kärfvarna, och snubber henne intet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Och låter desslikes falla utaf händerna henne till, och låter liggat, att hon må upphemta det, och ingen tale derföre illa till henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Så hemtade hon på åkrenom allt intill aftonen; och det hon upphemtat hade, tröskade hon, och det var vid ett epha bjugg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Och lade på sig, och kom i staden, och viste, sina sväro hvad hon hemtat hade; dertill bar hon fram, och gaf henne det henne qvart blifvit var, der hon af mättad vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Då sade hennes svära till henne: Hvar hafver du hemtat i dag, och hvar hafver du arbetat? Välsignad vare den som vid dig känts hafver. Och hon sade det sine sväro, när hvem hon arbetat hade, och sade: Den man, som jag i dag när arbetat hafver, heter Boas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Naemi sade till sina sonahustru: Välsignad vare han Herranom; ty han hafver icke tillbakalåtit sina barmhertighet, hvarken på de lefvande, eller på de döda. Och Naemi sade till henne: Den mannen är oss åkommen, och är vår arfvinge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Ruth, den Moabitiskan, sade: Han sade ock till mig: Håll dig intill mina dränger, tilldess de hafva allt inbergat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naemi sade till Ruth sina sonahustru: Det är bättre, min dotter, att du går ut med hans pigor, att på en annan åker icke någor afvisar dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Alltså höll hon sig intill Boas pigor, och hemtade der, så länge bjugganden och hveteanden öfverfaren var; och kom igen till sina sväro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Och Naemi hennes svära sade till henne: Min dotter, jag vill komma dig till ro, så att du skall må väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Den samme Boas, vår skyldman, när hvilkens pigor du varit hafver, kastar i denna nattene korn på sin loga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Så två dig, och smörj dig, och drag din kläder uppå, och gack neder till logan, så att ingen känner dig, tilldess han hafver ätit och druckit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'När han då lägger sig, så märk till, hvar han lägger sig, och kom och lyft upp kläden vid hans fötter, och lägg dig, så varder han dig väl sägandes, hvad du göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Hon sade till henne: Allt det du säger mig, vill jag göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Hon gick neder till logan, och gjorde allt såsom hennes svära henne budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Och då Boas hade ätit och druckit, vardt hans hjerta gladt, och kom och lade sig bakom en kornskyl; och hon kom sakta, och lyfte upp kläden vid hans fötter, och lade sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Vid midnattstid vardt mannen förfärad, och tog om sig, och si, en qvinna låg vid hans fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Och han sade: Ho äst du? Hon svarade: Jag är Ruth din tjenarinna, sträck ut din vinga öfver dina tjenarinno; ty du äst arfvingen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Han sade: Välsignad vare du Herranom, min dotter, du hafver sedermer gjort en bättre barmhertighet än tillförene, att du icke hafver gångit efter ynglingar, rika eller fattiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Nu, min dotter, frukta dig intet; allt det du säger, vill jag göra dig; förty hela staden af mitt folk vet, att du äst en dygdesam qvinna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Det är sant, att jag är arfvingen, men en annar är när mer än jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Blif i natt; i morgon om han tager dig, är så godt; lyster honom ock icke taga dig, så vill jag taga dig, så visst som Herren lefver. Sof intill morgonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Och hon sof intill morgonen vid hans fötter; och hon stod upp, förra än någor den andra känna kunde och han sade: Låt icke uppenbart varda, att någon qvinna är kommen till logan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Och sade: Räck hit din mantel, som du hafver uppå, och håll honom fram; och hon höll honom fram, och han mälte sex mätt korn, och lade på henne. Och han kom i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Men hon kom till sina sväro; den sade: Huru går det med dig, min dotter? Och hon sade henne allt det mannen hade gjort henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Och sade: Dessa sex mått korn gaf han mig; ty han sade: Du skall icke komma med tomma händer till dina sväro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Hon sade: Låt oss bida, min dotter, tilldess du får se hvartut det vill; ty mannen vänder icke igen, med mindre han gör der i dag en ända med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boas gick upp i porten, och satte sig der. Och si, när arfvingen gick derfram, talade Boas till honom, och sade: Kom, och sätt dig här, ehuru ditt namn är. Och han kom, och satte sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Och han tog tio män af de äldsta i staden, och sade: Sätter eder här. Och de satte sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Då sade han till arfvingan: Naemi, som ifrå de Moabiters land igenkommen är, bjuder ett stycke åker fält, som hörde vår broder EliMelech till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Derföre tänkte jag, att jag skulle det kungöra dig, och säga: Vill du komma det i ditt arf, så köp det inför borgarena, och inför de äldsta af mitt folk. Vill du ock icke kommat i ditt arf, så säg mig det, att jag må veta det; ty här är ingen arfvinge till, annar än du, och jag näst dig. Han sade: Jag vill komman i mitt arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Boas sade: När du köper åkren af Naemis hand, så måste du ock taga Ruth, den Moabitiskon, dens dödas hustru, att du må uppväcka dem döda namn till hans arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Då sade han: Jag kan icke blifva vid arfvet, att jag tilläfventyrs icke förderfvar min arfvedel. Lös du hvad jag lösa skulle, ty jag kan icke lösan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Och det var en gammal sedvänja i Israel, när en någon ting icke ärfva eller köpa ville, till att all ting skulle fast blifva, så drog han sin sko utaf, ock fick dem andra; det var då till ett vittnesbörd i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Och arfvingen sade till Boas: Köp du det; och drog sin sko af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Och Boas sade till de äldsta, och till allt folket: I ären i denna dag vittne, att jag hafver köpt allt det EliMelech, och allt det Chilion och Mahlon tillhörde, utaf Naemis hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Dertill tager jag ock Ruth, den Moabitiskon, Mahlons hustru, mig till hustru, att jag må uppväcka dem döda namn i hans arfvedel, och hans namn icke skall utrotadt varda ibland hans bröder, och utu hans rums portar; dess ären I vittne i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Och allt folket, som i portenom var, samt med de äldsta, sade: Vi äre vittne; Herren göre den qvinnona, som kommer i ditt hus, såsom Rachel och Lea, hvilka båda hafva uppbyggt Israels hus; och blif ärlig hållen i Ephrata, och var namnkunnig i BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Och ditt hus vare såsom Perez hus, hvilken Thamar födde Juda, utaf den säd, som Herren dig gifvandes varder af denna qvinnone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Så tog Boas Ruth, att hon vardt hans hustru; och när han låg när henne, gaf Herren henne, att hon vardt hafvandes, och födde en son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Då sade qvinnorna till Naemi: Lofvad vare Herren, som hafver låtit dig icke fattas arfvinga i denna tiden, att hans namn må blifva i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Han varder dig kommandes till lif igen, och försörjandes dig i dinom ålder; ty din sonahustru, som dig älskat hafver, hafver födt den dig bättre är än sju söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Och Naemi tog barnet, och lade det i sitt sköt, och vardt dess amma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Och hennes grannhustrur gåfvo honom ett namn, och sade: Naemi är födt ett barn; och de kallade honom Obed; han är Isai fader, som är Davids fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Detta är Perez börd: Perez födde Hezron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezron födde Ram; Barn födde Amminadab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab födde Nahesson; Nahesson födde Salmon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon födde Boas; Boas födde Obed;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed födde Isai; Isai födde David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Det var en man af Ramathaim Zophim, af Ephraims berg; han het ElKana, Jerohams son, Elihu sons, Thohu sons, Zuphs sons, hvilken en Ephrateer var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Och han hade två hustrur, den ena het Hanna, den andra Peninna; men Peninna hade barn, och Hanna hade inga barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Den samme mannen gick upp ifrå sin stad i sinom tid, att han skulle tillbedja och offra Herranom Zebaoth i Silo: och dersammastäds voro Herrans Prester Hophni och Pinehas, både Eli söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Då nu en dag kom, att ElKana offrade, gaf han sine hustru Peninna, och alla hennes söner och döttrar, stycker;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Men Hanna gaf han ett stycke sörjandes; ty han hade Hanna kär; men Herren hade igenlyckt hennes lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Och hennes haterska gjorde henne harmt, och kastade henne före hennes ofruktsamhet, att Herren hade igenlyckt hennes lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Så gjorde hon hvart år, när de gingo upp till Herrans hus, och gjorde henne alltså harmt; men hon gret, och åt intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Och ElKana hennes man sade till henne: Hanna, hvi gråter du? Och hvi äter du icke? Och för hvad sak är ditt hjerta så illa tillfrids? Är jag dig icke bättre än tio söner?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Då stod Hanna upp, sedan hon ätit och druckit hade i Silo; och Presten Eli satt på en stol utanför dörrene af Herrans tempel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Och hon var full med hjertans bedröfvelse; och hon bad till Herran, och gret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Och lofvade ett löfte, och sade: Herre Zebaoth, om du ville se till dina tjenarinnos jämmer, och tänka på mig, och icke förgäta dina tjenarinno, utan gifva dina tjenarinno en son, så vill jag gifva honom Herranom, så länge han lefver, och ingen rakoknif skall komma på hans hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Och som hon länge bad för Herranom, gaf Eli akt på hennes mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ty Hanna talade i sitt hjerta, allenast hennes läppar rörde sig, men hennes röst hördes intet. Då mente Eli, att hon var drucken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Och sade till henne: Huru länge vill du vara drucken? Låt vinet gå af dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Men Hanna svarade och sade: Nej, min Herre, jag är en bedröfvad qvinna; vin och starka drycker hafver jag icke druckit, utan hafver utgjutit mitt hjerta för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Räkna dock icke dina tjenarinno såsom en Belials dotter; ty jag hafver utaf mitt svåra bekymmer och sorg talat allt härtill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eli svarade, och sade: Gack i frid; Israels Gud gifve dig dina bön, den du af honom bedit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Hon sade: Låt dina tjenarinno finna nåd för din ögon. Så gick qvinnan sin väg och åt, och såg icke mer så sorgeliga ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Och om morgonen voro de bittida uppe; och då de tillbedit hade för Herranom, vände de om, och gingo hem igen till Ramath. Och ElKana kände sina hustru Hanna. Och Herren tänkte på henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Och då någre dagar voro framlidne, vardt hon hafvandes, och födde en son, och kallade honom Samuel, sägandes: Ty jag hafver bedit honom af Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Och då mannen ElKana for upp med hela sitt hus, till att offra Herranom offer efter sedvänjon och sitt löfte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'For Hanna intet med upp; utan sade till sin man: Jag vill icke fara upp, tilldess barnet är afvanat; då vill jag hafva honom med, att han må hafvas fram för Herran, och blifva der sedan evigliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'ElKana hennes man sade till henne: Gör såsom dig täckes; blif, tilldess du hafver afvant honom; Herren stadfäste det han sagt hafver. Så blef då qvinnan, och däggde sin son, intilldess hon vande honom af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Och så hade hon honom upp, sedan hon honom afvant hade, med tre stutar, med ett epha mjöl, och med en flasko vin, och hade honom in i Herrans hus i Silo; och pilten var ännu ung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Och de slagtade stuten, och hade pilten fram för Eli.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Och hon sade: Ack! min Herre, så visst som din själ lefver, min Herre, jag är den qvinnan, som här när dig stod, och bad Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Då jag bad om denna pilten. Nu hafver Herren gifvit mig den bönena, som jag bad af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Derföre gifver jag honom Herranom igen evigliga, efter han af Herranom beden är. Och de tillbådo der Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Och Hanna bad, och sade: Mitt hjerta fröjdar sig i Herranom; mitt horn är upphöjdt i Herranom; min mun hafver vidt öppnat sig öfver mina fiendar; ty jag fröjdar mig af dine salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Ingen är helig såsom Herren. Utan dig är ingen; och ingen tröst är såsom vår Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Låter af att berömma eder och tala stor ord. Låter det gamla utur edar mun: ty Herren är en Gud, som vet det, och låter icke sådana anslag hafva framgång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'De starkas båge är sönderbruten, och de svage äro omgjordade med starkhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'De som mätte voro, de vordo sålde för bröd; och de som hunger ledo, hungra intet mer; tilldess den ofruktsamma födde sju, och den som mång barn hade, vardt försvagad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herren dödar, och gifver lif; förer till helvete, och derut igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herren gör fattigan; han gör ock rikan han förnedrar och upphöjer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Han uppreser den torftiga utu stoftet, och upphäfver den fattiga utu träcken, att han skall sätta honom ibland Förstar, och låtan ärfva ärones stol; ty verldenes ändar äro Herrans, och jordenes krets hafver han satt deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Han varder bevarandes sina heligas fötter; men de ogudaktige skola vara tyste i mörkrena; ty ingen förmår något af sin egen kraft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'För Herranom skola förskräckas hans fiender; öfver dem skall han dundra i himmelen. Herren skall döma verldenes ändar, och skall gifva sinom Konung magt, och upphöja sins Smordas horn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Och ElKana gick hem igen till Hamath uti sitt hus, och pilten var Herrans tjenare inför Presten Eli.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Men Eli söner voro Belials barn, och visste intet af Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Ej heller hvad deras Prestaämbete var till folket. Då någor ville något offra, så kom Prostens dräng, medan köttet kokades, och hade en treuddad gaffel i sine hand:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Och stack i grytona eller kettilen, eller pannona, eller krukona, och hvad han drog ut med gaffelen, det tog Presten till sig. Så gjorde de allom Israel, som ditkommo till Silo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Sammalunda, förra än de uppbrände det feta, kom Prestens dräng, och sade till honom, som offret frambar: Få mig kött, att jag må steka det åt Prestenom; ty han vill icke taga kokadt kött af dig, utan rått.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'När då någor sade till honom: Låt upptända det feta såsom det bör sig i dag, och tag sedan hvad ditt hjerta begärar, så sade han till honom: Du skall nu gifva mig det, eljest skall jag taga det med våld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Derföre var piltarnas synd ganska stor för Herranom; förty folket förhädde Herrans spisoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Men Samuel var en tjenare för Herranom, en dräng i en linnen lifkjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Dertill gjorde hans moder honom en liten kjortel, och förde den upp till honom i sinom tid, då hon uppgick med sin man, till att offra offer i sinom tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Och Eli välsignade ElKana och hans hustru, och sade: Herren gifve dig säd utaf denna qvinnone för den bön, som du hafver bedit af Herranom. Och de gingo hem till sitt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Och Herren sökte Hanna, att hon blef hafvandes, och födde tre söner och två döttrar; men pilten Samuel växte till för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Men Eli var ganska gammal, och han förnam hvad hans söner gjorde allom Israel; och att de sofvo när de qvinnor, som tjente inför dörrene af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Och han sade till dem: Hvi gören I sådant? Ty jag hörer edart onda väsende af allt detta folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Icke så, mina barn, det är icke godt rykte, som jag hörer; I kommen Herrans folk till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Om någor syndar emot en mennisko, så kunna domarena förlika det; men om någor syndar emot Herran, ho kan förlikat? Och de hörde intet sins faders röst; ty Herren ville döda dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Men pilten Samuel växte till, och var både Herranom och menniskom täcker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Och en Guds man kom till Eli, och sade till honom: Så säger Herren: Jag hafver uppenbarat mig dins faders huse, då de ännu voro uti Egypten i Pharaos hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Och utvalde honom der mig, för all Israels slägter till Presterskap, att han skulle offra på mitt altare, och upptända rökverk, och bära lifkjortel för mig: och gaf dins faders huse all Israels barnas offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Hvi spjernar du då emot mitt offer och spisoffer, som jag budit hafver i tabernaklet, och du ärar dina söner mer än mig, så att I göden eder utaf allt mitt folks Israels spisoffers förstling?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Derföre säger Herren Israels Gud: Jag hafver sagt, att ditt hus och dins faders hus skulle vandra för mig evinnerliga. Men nu säger Herren: Det vare långt ifrå mig; utan den mig ärar, honom vill jag ock ära: men den mig föraktar, han skall komma på skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Si, den tid skall komma, att jag skall bryta din arm sönder, och dins faders hus arm, så att ingen gammal skall vara i dino huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Och du skall se din motståndare uti tabernaklet i allo Israels godo; och ingen gammal skall vara i dins faders hus evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Dock vill jag icke utrota af dig allan man ifrå mitt altare, på det din ögon skola försmäkta, och din själ gräma sig; och hela hopen i dino huse skola dö, då de till manna komne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Och detta skall vara dig ett tecken, som båda dina söner Hophni och Pinehas öfvergå skall: På en dag skola de både dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Och jag skall uppväcka mig en trogen Prest, och han skall göra såsom det i mino hjerta och mine själ är; honom skall jag bygga ett säkert hus, så att han skall vandra inför minom Smorda i alla dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Och den qvar blifver af ditt hus, han skall komma och falla neder för honom, om en silfpenning och ett stycke bröd, och skall säga: Käre, låt mig komma till en Prestadel, att jag må äta en beta bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Och då pilten Samuel tjente Herranom under Eli, var Herrans ord sällsynt på den tiden, och var fögo Prophetia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Och det begaf sig på samma tid, att Eli låg i sino rumme, och hans ögon begynte mörkas, så att han icke se kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Och Samuel hade lagt sig uti Herrans tempel, der Guds ark var, förra än Guds lampa utsläcktes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Och Herren kallade Samuel. Han svarade: Si, här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Och han lopp till Eli, och sade: Si, här är jag, du kallade mig. Han sade: Jag hafver intet kallat dig; gack bort igen, och lägg dig sofva. Och han gick bort, och lade sig sofva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Och Herren kallade åter Samuel, och Samuel stod upp, och gick till Eli, och sade: Si, här är jag, du hafver kallat mig. Han sade: Jag hafver icke kallat dig, min son; gack bort igen, och lägg dig sofva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Men Samuel kände icke ännu Herran, och Herrans ord var honom icke ännu uppenbaradt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Och Herren kallade Samuel ännu tredje gången, och han stod upp, och gick till Eli, och sade: Si, här är jag, du hafver kallat mig. Så förmärkte Eli, att Herren kallade pilten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Och sade till honom: Gack bort igen, och lägg dig sofva; och om han mer kallar dig, så säg: Tala, Herre, ty din tjenare hörer till. Samuel gick bort och lade sig i sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Så kom Herren, och gick fram, och kallade såsom tillförene: Samuel, Samuel. Och Samuel sade: Tala, ty din tjenare hörer till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Och Herren sade till Samuel: Si, jag skall göra en ting i Israel, så att den det får höra, honom skall gälla i båda hans öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'På den dagen skall jag uppväcka öfver Eli allt det jag öfver hans hus sagt hafver; jag skall begynnat och fullkomnat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ty jag hafver sagt honom till, att jag vill vara domare öfver hans hus till evig tid, för den missgernings skull, att han visste huru hans söner bedrefvo slem ting, och hafver icke en gång sett illa på dem derföre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Fördenskull hafver jag svorit Eli huse, att denna Eli hus missgerning skall icke försonad varda antingen med offer eller spisoffer, till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Och Samuel låg intill morgonen, och lät upp dörrena af Herrans hus. Och Samuel torde icke säga Eli synena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Då kallade Eli honom, och sade: Samuel, min son. Han svarade: Si, här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Han sade: Hvad är det för ord, som dig sagdt är? Dölj det icke för mig; Gud göre dig det och det, om du något döljer för mig, af det som dig sagdt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Då sade Samuel honom alltsamman, och döljde intet för honom; men han sade: Han är Herren; han göre såsom honom godt tyckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Och Samuel växte till, och Herren var med honom, och intet af all hans ord föll på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Och hela Israel, allt ifrå Dan intill BerSaba, visste att Samuel var en trogen Herrans Prophet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Och Herren syntes åter i Silo; ty Herren var Samuel uppenbarad vorden i Silo, genom Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Och Samuel begynte predika för hela Israel. Och israel drog ut emot de Philisteer i strid, och lägrade sig vid Hjelpostenen; men de Philisteer hade lägrat sig i Aphek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Och de gjorde redo emot Israel; och hären vardt förskingrad, så att Israel vardt slagen förde Philisteer; och de slogo i spetsen på markene vid fyratusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Och då folket kom i lägret, sade de äldsta i Israel: Hvi hafver Herren låtit slå oss i dag för de Philisteer? Låt oss taga till oss Herrans förbunds ark ifrå Silo, och låt honom komma ibland oss, att han må frälsa oss ifrå våra fiendars hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Och folket sände till Silo, ock läto hemta dädan Herrans Zebaoths förbunds ark, hvilken der sitter på Cherubim. Och voro de två Eli söner med Guds förbunds ark, Hophni och Pinehas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Och då Herrans förbunds ark kom i lägret, skriade hela Israel med stort skriande, så att det skall i markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Då de Philisteer hörde det skriandet, sade de: Hvad är det för ett skri och glädje uti de Ebreers lägre? Och då de förnummo, att Herrans ark var kommen i lägret,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Fruktade de sig, och sade: Gud är kommen i lägret; och sade ytterligare: Ve oss, ty det hafver icke så varit tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ve oss, ho kan hjelpa oss ifrå dessa mägtiga Gudars hand? Det äro de Gudar, som slogo Egypten med allahanda plågo i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Så varer nu tröste, och varer män, I Philisteer, att I icke skolen tjena de Ebreer, såsom de hafva tjent eder; varer män och strider.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Då stridde de Philisteer, och Israel vardt slagen, och hvar och en flydde uti sina hyddo; och det var en ganska stor slagtning, så att utaf Israel föllo tretiotusend män fotfolk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Och Guds ark vardt tagen, och de två Eli söner Hophni och Pinehas blefvo döde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Då lopp en af BenJamin utaf hären, och kom den samma dagen till Silo; och hade rifvit sin kläder, och hade strött jord uppå hufvudet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Och som han kom derin, satt Eli på en stol, till att se ut på vägen; ty hans hjerta var bekymradt om Guds ark; och då mannen kom i staden, sade han det; och hela staden gret och ropade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Och som Eli fick höra det ropet, sade han: Hvad är detta för ett rop och buller? Så kom mannen hasteliga, och sade det Eli.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Och Eli var åtta och niotio år gammal; och hans ögon voro mörk, så att han icke kunde se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Och mannen sade till Eli: Jag är kommen, och är flydd i dag utu hären; men han sade: Huru går det, min son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Då svarade bådet, och sade: Israel är flydd för de Philisteer, och en stor slagtning är skedd på folket, och dine två söner, Hophni och Pinehas, äro döde; dertill är Guds ark borttagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Och som han rörde om arken, föll han tillrygga af stolenom vid dörrena, och slog sig halsen sönder, och blef död; ty han var gammal och en tung man; men han hade dömt Israel i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Och hans sonahustru, Pinehas hustru, var hafvandes, och skulle snart läggas ned. Då hon hörde det ryktet, att Guds ark var tagen, och hennes svär och man voro döde, böjde hon sig, och födde; ty hennes nöd kom henne uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Och som hon nu dö skulle, sade qvinnorna, som när henne stodo: Var icke förfärad, du hafver födt en son; men hon svarade intet, och lade det heller intet på hjertat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Och hon kallade det barnet Icabod, och sade: Israels härlighet är borto; efter Guds ark tagen var, och hennes svär, och hennes man;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Och sade åter: Israels härlighet är borto; ty Guds ark är tagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Och de Philisteer togo Guds ark, och förde honom ifrå Hjelpostenen intill Asdod,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Uti Dagons hus, och satte honom bredovid Dagon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Och som de af Asdod den andra morgonen bittida uppstodo, funno de Dagon liggandes framstupa, på jordene inför Herrans ark; men de togo Dagon, och satte honom upp igen i sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Då de den andra morgonen igen uppstodo, funno de Dagon åter liggandes framstupa på jordene inför Herrans ark, och hans hufvud och båda hans händer afhuggna vid tröskelen, så att stumpen låg allena för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Derföre träda icke Dagons Prester, och alle de som i Dagons hus gå, på Dagons tröskel i Asdod, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Men Herrans hand vardt svår öfver dem i Asdod, och förderfvade dem; och slog Asdod och alla dess gränsor, i deras hemlig rum baktill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Då nu det folk i Asdod sågo, att så tillgick, sade de: Låt icke Israels Guds ark blifva när oss, förty hans hand är för svår öfver oss, och öfver vår gud Dagon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Och de sände bort, och församlade alla de Philisteers Förstar till sig, och sade: Hvad skole vi göra af Israels Guds ark? Då svarade de: Låter bära Israels Guds ark omkring till Gath. Och de båro Israels Guds ark omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Då de nu båro honom omkring, vardt ett stort buller i stadenom genom Herrans hand; och han slog folket i stadenom, både små och stora, och förderfvade dem i deras hemlig rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Så sände de Guds ark till Ekron. Då nu Guds ark kom till Ekron, ropade de af Ekron, och sade: De hafva omkringdragit Guds ark till mig, på det de skola dräpa mig och mitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Då sände de bort, och församlade alla de Philisteers Förstar, och sade: Sänder Israels Guds ark åter till sitt rum igen, att han icke dräper mig och mitt folk; förty Guds hand gjorde ett ganska stort rumor med dräpande i hela stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Och det folk, som icke blefvo döde, de vordo slagne i deras hemlig rum, så att skriet af stadenom gick upp i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Så var Herrans ark i sju månader uti de Philisteers land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Och de Philisteer kallade sina Prester och spåmän, och sade: Hvad skole vi göra med Herrans ark? Säger oss före, hvarmed vi skole sända honom till sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'De sade: Viljen I sända Israels Guds ark, så sänder honom icke allstinges blottan, utan betaler honom ett skuldoffer; så varden I helbregda, och eder skall varda kunnigt, hvarföre hans hand icke återvänder af eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Men de sade: Hvilket är det skuldoffret, det vi honom gifva skole? De svarade: Fem gyldene ardsar, och fem gyldene möss, efter de fem Philisteers Förstars tal; förty det hafver varit allt enahanda plåga öfver eder alla, och öfver edra Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Så må I nu göra liknelse efter edra ardsar, och efter edra möss, som edart land förderfvat hafva, så att I hedren Israels Gud; tilläfventyrs hans hand varder lättare öfver eder, och öfver edar gud, och öfver edart land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Hvi förhärden I edor hjerta, såsom de Egyptier och Pharao förhärde sin hjerta? Skedde det icke så, att då han beviste sig på dem, läto de fara dem, att de gingo sin väg?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Så tager nu till, och görer en ny vagn; och tager två unga däggande kor, på hvilka intet ok kommet är, och spänner dem för vagnen, och låter deras kalfvar blifva qvara hemma efter dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Och tager Herrans ark, och sätter honom på vagnen; och de gyldene klenodier, som I honom till skuldoffer gifven, lägger i ett skrin utmed hans sido, och sänder honom åstad, och låter gån.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Och ser I till, går han upp den vägen åt sina gränsor emot BethSemes, så hafver han gjort oss allt detta stora onda; hvar ock icke, så måge vi veta, att hans hand icke hafver rört oss, utan det är oss eljest af en olycko påkommet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Folket gjorde ock så, och togo två unga däggande kor, och spände dem för en vagn, och behöllo deras kalfvar hemma;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Och satte Herrans ark på vagnen, och det skrinet med de gyldene möss, och med deras ardsars liknelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Och korna gingo rättfram den vägen, som drog till BethSemes, på enom väg, och gingo och råmade, och veko hvarken på den högra sidona eller på den venstra; och de Philisteers Förstar gingo efter dem, allt intill BethSemes gränso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Men de BethSemiter gingo och skåro i hveteandene i dalenom, och de hofvo sin ögon upp, och fingo se arken, och vordo glade att de fingo se honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Men vagnen kom uppå Josua den BethSemitens åker, och stadnade der. Och der var en stor sten; och de höggo sönder trät af vagnenom, och offrade de kor Herranom till bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Och Leviterna lyfte Herrans ark neder, och det skrinet, som der bredovid låg, der de gyldene klenodier uti voro, och satte på den stora stenen. Och det folket i BethSemes offrade på den dagen Herranom bränneoffer och annor offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'När nu de fem Philisteers Förstar hade detta sett, foro de tillbaka igen på samma dagen till Ekron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Och detta äro de gyldene ardsar, som de Philisteer offrade Herranom till skuldoffer: Asdod en, Gasa en, Askelon en, Gath en, och Ekron en;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Och gyldene möss efter talet af alla de Philisteers städer, under de fem Förstar, både murade städer och byar; och intill det stora sorgerummet, der de läto Herrans ark uppå, intill denna dag, på Josua den BethSemitens åker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Och somlige af de BethSemiter vordo slagne, derföre att de hade sett Herrans ark; och han slog af folket femtiotusend och sjutio män. Då jämrade sig folket, att Herren hade med så stor plågo slagit folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Och det folket i BethSemes sade: Ho kan blifva ståndandes för Herranom, en sådana helig Gud? Och till hvem skall han fara ifrån oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Och de sände bådskap till de borgare af KiriathJearim, och läto säga dem: De Philisteer hafva fört igen Herrans ark; kommer hitneder, och hemter honom upp till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Så kommo det folket af KiriathJearim, och hemtade Herrans ark ditupp, och förde honom i AbiNadabs hus i Gibea; och hans son Eleazar vigde de, att han skulle taga vara på Herrans ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Och ifrå den dagen, då Herrans ark kom till KiriathJearim, fördröjde sig tiden, tilldess tjugu år voro förlupne; och allt Israels hus greto för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Men Samuel sade till hela Israels hus: Om I omvänden eder med allt hjerta till Herran, så låter ifrån eder de främmande gudar och Astaroth, och bereder edart hjerta till Herran, och tjener honom allena, så varder han eder frälsandes utu de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Så bortkastade Israels barn ifrå sig Baalim och Astaroth, och tjente Herranom allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Och Samuel sade: Församler hela Israel till Mizpa, att jag må der bedja Herran för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Och de kommo tillhopa i Mizpa, och öste vatten, och göto ut för Herranom, och fastade den dagen, och sade der: Vi hafve syndat för Herranom. Och så dömde Samuel Israels barn i Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Då nu de Philisteer hörde, att Israels barn voro tillhopakomne i Mizpa, drogo de Philisteers Förstar upp emot Israel. När Israels barn det hörde, fruktade de sig för de Philisteer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Och sade till Samuel: Vänd icke igen att ropa för oss till Herran vår Gud, att han hjelper oss utu de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel tog ett fett lamb, och offrade Herranom ett helt bränneoffer, och ropade till Herran för Israel; och Herren bönhörde honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Och som Samuel offrade bränneoffret, kommo de Philisteer fram till att strida emot Israel. Men Herren lät dundra en stor tordön öfver de Philisteer på den dagen; och förfärade dem, så att de vordo slagne för Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Så drogo Israels män ut ifrå Mizpa, och jagade de Philisteer, och slogo dem allt inunder BethCar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Då tog Samuel en sten, och satte honom emellan Mizpa och Sen, och kallade honom Hjelposten, och sade: Allt härintill hafver Herren hulpit oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Så vordo de Philisteer förtryckte, och kommo intet mer i Israels gränso. Och Herrans hand var emot de Philisteer, så länge Samuel lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Så vordo ock de städer Israel igengifne, som de Philisteer dem ifråtagit hade, ifrån Ekron intill Gath, med deras gränsor; dem friade Israel utu de Philisteers hand; ty Israel hade frid med de Amoreer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Och Samuel dömde Israel, så länge han lefde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Och for hvart år omkring till BethEl, och Gilgal, och Mizpa. Och när han hade på all denna rummen dömt Israel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Kom han igen till Ramath, ty der var hans hus; och dömde der Israel, och byggde der Herranom ett altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Då nu Samuel vardt gammal, satte han sina söner till domare öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Hans förstfödde son het Joel, och den andre Abia; och de voro domare i BerSaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Men hans söner vandrade icke uti hans vägar; utan böjde sig efter girighet, och togo gåfvor, och förvände rätten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Så församlade sig alle äldste i Israel, och kommo till Ramath till Samuel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Och sade till honom: Si, du äst vorden gammal, och dine söner gå icke uti dina vägar: så sätt nu en Konung öfver oss, den oss döma må, såsom alle Hedningar hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Det behagade Samuel illa, när de sade: Få oss en Konung, den oss döma må. Och Samuel bad inför Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Och Herren sade till Samuel: Hör folkens röst i allt det de hafva talat dig till; förty de hafva icke förkastat dig, utan mig, att jag icke skall vara Konung öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'De göra dig såsom de alltid gjort hafva, ifrå den dag, då jag förde dem utur Egypten, allt intill denna dag; och hafva öfvergifvit mig, och tjent andra gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Så hör nu deras röst; dock betyga dem, och undervisa dem Konungens rätt, den öfver dem råda skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Och Samuel sade all Herrans ord folkena, som af honom Konung begärat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Detta skall vara Konungs rätt, den öfver eder råda skall; edra söner skall han taga till sin vagn, och resenärar som rida för hans vagn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Och till höfvitsmän öfver tusende, och öfver femtio, och till åkermän, som hans åker bruka skola, och till uppskärare i hans säd, och de som göra hans harnesk, och det hans vagnar tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Edra döttrar skall han taga sig till apothekerskor, kokerskor och bakerskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Edra bästa åkrar och vingårdar, och oljogårdar skall han taga och gifva sina tjenare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Dertill skall han taga af edra säd och vingårdar tiond, och gifva sina kamererare och tjenare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Och edra tjenare och tjenarinnor, och edra dägeligaste ynglingar, och edra åsnar, skall han taga, och uträtta sin ärende med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Af edra hjordar skall han taga tiond; och I måsten vara hans trälar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'När I då ropen på den tiden öfver edar Konung, som I eder utvalt hafven, så skall Herren på den tiden intet höra eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Men folket ville intet höra Samuels röst, och sade: Ingalunda, utan en Konung måste vara öfver oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Att vi ock äre såsom alle andre Hedningar; att vår Konung må döma oss, och draga ut för oss, när vi före vårt örlig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Så hörde Samuel allt detta, som folket sade: och sade det för Herrans öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Och Herren sade till Samuel: Hör deras röst, och gör dem en Konung. Och Samuel sade till Israels män: Går edra färde, hvar och en i sin stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Och en man af BenJamin benämnd Kis, Abiels son, Zerors sons, Bechoraths sons, Aphiahs sons, en mans Jemini sons, en ärlig man;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Han hade en son benämnd Saul, han var en dägelig ung man, så att ingen dägeligare var ibland Israels barn; hufvudet högre än allt folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Så hade Sauls fader Kis borttappat sina åsninnor; och han talade till sin son Saul: Tag en af drängerna med dig, och statt upp, gack bort, och sök upp åsninnorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Och han gick öfver Ephraims berg, och genom det landet Salisa, och de funno dem intet. De gingo igenom det landet Saalim, och der voro de intet. De gingo genom Jemini land, och funno dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'När de kommo uti det landet Zuph, sade Saul till drängen, som med honom var: Kom, låt oss gå hem igen; min fader måtte öfvergifva åsninnorna, och hafva sorg om oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Men han sade: Si, här är en märkelig Guds man i denna staden; allt det han säger, det sker; låt oss nu gå dit; tilläfventyrs säger han oss vår väg, den vi gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul sade till sin dräng: Om vi än gå dit, hvad bäre vi mannenom? Förty brödet är allaredo upptärdt utu vår matsäck; vi hafve ingen gåfvo, som vi kunne bära dem Guds mannenom: Hvad hafve vi?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Drängen svarade igen, och sade: Si, jag hafver fjerdedelen af en sikel silfver när mig; den vilje vi gifva dem Guds mannenom, att han må säga oss vår väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Fordomtid i Israel, när man gick bort till att fråga Gud, sade man: Kom, låt oss gå till Siaren; ty de som man nu kallar Propheter, dem kallade man i förtiden Siare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul sade till sin dräng: Du hafver väl sagt; kom, låt oss gå. Och de gingo åstad till staden, der Guds mannen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Och när de komne voro upp till staden, funno de pigor, som utgångna voro till att hemta vatten; till dem sade de: Är Siaren här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'De svarade dem, och sade: Ja, si, här är han; skynda dig, ty i dag är han kommen i staden; efter folket i dag offrar uppå höjdene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'När I kommen i staden, så finnen I honom, förra än han uppgår på höjdena till att äta; förty folket äter icke, förra än han kommer, efter han skall välsigna offret; sedan äta de som budne äro. Derföre går ditupp, rätt nu finnen I honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Och då de kommo upp i staden, och voro midt i stadenom, si, då gick Samuel ut emot dem, och ville gå upp till höjdena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Men Herren hade uppenbarat för Samuels öron, en dag förra än Saul kom, och sagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'I morgon på denna tiden skall jag sända till dig en man utu BenJamins land; den skall du smörja till en Första öfver mitt folk Israel, att han skall frälsa mitt folk ifrå de Philisteers hand; ty jag hafver sett till mitt folk, och deras rop är kommet till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Då nu Samuel fick se Saul, svarade Herren honom, och sade: Si, der är mannen, som jag dig af sagt hafver, att han skall råda öfver mitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Då gick Saul fram till Samuel i porten, och sade: Säg mig, hvar är här Siarens hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel svarade Saul, och sade: Jag är Siaren, gack för mig upp på höjdena, ty I måsten i dag äta med mig; i morgon vill jag låta dig gå, och allt det i dino hjerta är, vill jag säga dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Och om åsninnorna, som du för tre dagar sedan borttappade, var nu intet bekymrad, ty de äro funna; och hvem hörer allt det goda till i Israel? Blifver det icke ditt, och hela dins faders hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul sade: Är jag icke en son af Jemini, och af det ringasta slägtet i Israel, och min ätt ringast ibland alla ätter i BenJamin? Hvi säger du då mig sådant?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Men Samuel tog Saul, och hans dräng, och hade dem upp i salen, och satte dem öfverst ibland dem som budne voro, hvilke voro vid tretio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Och Samuel sade till kocken: Få hit det stycket, som jag fick dig, och befallde att du skulle behålla det när dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Då bar kocken en bog upp, och hvad dervid hängde. Och han satte den för Saul, och sade: Si, detta blef öfver, lägg för dig och ät; förty det är på denna tid till dig förvaradt, då jag böd folket. Så åt Saul med Samuel på den dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Och då de gingo neder af höjdene in i staden, talade han med Saul på taket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Och de stodo bittida upp; och som morgonrodnaden gick upp, kallade Samuel Saul uppå taket, och sade: Statt upp, att jag må låta dig gå. Och Saul stod upp, och de gingo både tillsammans ut, han och Samuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Och då de kommo neder till ändan på staden, sade Samuel till Saul: Säg drängenom, att han går framför oss; och han gick framföre. Men du, statt nu här qvar, att jag må undervisa dig, hvad Gud hafver sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Då tog Samuel ett oljoglas, och göt uppå hans hufvud, och kysste honom, och sade: Ser du, att Herren hafver smort dig till en Första öfver hans arfvedel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'När du nu går ifrå mig, så finner du två män vid Rachels graf i BenJamins gränso i Zelzah; de skola säga till dig: Åsninnorna äro funna, der du efter gången äst, dem att söka; och si, din fader hafver öfvergifvit tänka på åsnarna, och sörjer om eder, och säger: Hvad skall jag göra om min son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Och när du går dädan fram bätter, så kommer du till den eken Thabor; der skola tre män råka dig, som gå upp till Gud i BethEl, den ene bär tre kid, den andre tre bröd, den tredje en flasko med vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Och de skola helsa dig vänliga, och gifva dig tu bröd, det skall du taga af deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Sedan kommer du på Guds hög, der de Philisteers lägre är; och när du kommer derin i staden, möta dig en hop med Propheter, som komne äro af höjdene, och för dem en psaltare, och trumma, och pipa, och harpa, och de prophetera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Och Herrans Ande skall komma öfver dig, att du propheterar med dem; och då skall du varda en annar man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'När nu dessa tecknen komma dig, så gör allt det dig för handen kommer; ty Gud är med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Men du skall gå neder för mig till Gilgal; si, der vill jag komma neder till dig, till att offra bränneoffer och tackoffer. I sju dagar skall du bida, tilldess jag kommer till dig, och undervisar dig hvad du göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Och som han vände ryggen åt Samuel, och gick ifrå honom, gaf honom Gud ett annat hjerta; och all dessa tecknen kommo på den dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Och då de kommo till högen, si, då mötte honom en hop Propheter; och Guds Ande kom öfver honom, så att han propheterade med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Då de nu alle sågo honom, som tillförene hade känt honom, att han propheterade med Propheterna, sade de till hvarannan: Hvad är Kis son tillkommet? Är ock Saul ibland Propheterna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Och en svarade der, och sade: Ho är deras fader? Dädan är det ordspråket kommet: Är ock Saul ibland Propheterna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Och då han utpropheterat hade, kom han upp till höjdena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Men Sauls faderbroder sade till honom, och till hans dräng: Hvart voren I gånge? De svarade: Till att uppsöka åsnar; och då vi såge att vi funne dem icke, komme vi till Samuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Då sade Sauls faderbroder: Säg mig, hvad sade eder Samuel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul svarade sinom faderbroder: Han sade oss, att åsninnorna funna voro; men om Konungariket sade han honom intet, hvad Samuel sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel kallade folket in till Herran i Mizpa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Och sade till Israels barn: Så säger Herren Israels Gud: Jag förde eder utur Egypten, och frälste eder utu de Egyptiers hand, och utur all Konungarikes hand som eder tvingade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Och I hafven i dag förkastat edar Gud, som eder utur all edor olycko och bedröfvelse hulpit hafver, och sägen till honom: Sätt en Konung öfver oss. Nu väl, så går nu fram för Herran efter edor slägter och hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Som nu Samuel framhade alla Israels slägter, vardt råkadt inpå BenJamins slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Och som han hade BenJamins slägt fram med hennes ätter, vardt råkadt inpå Matri ätt, och råkade inpå Saul, Kis son; och de sökte efter honom, men de funno honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Då frågade de åter Herran, om han ännu skulle ditkomma? Herren svarade: Si, han hafver undstungit sig under ett fat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Då lupo de dit, och hemtade honom. Och då han gick fram ibland folket, var han hufvudet högre än allt folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Och Samuel sade till allt folket: Här sen I, hvem Herren utvalt hafver; ty hans like är icke ibland allt folket. Då gladdes allt folket, och sade: Lycka ske Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Och Samuel sade folkena all riksens rätt, och skref det uti ena bok, och ladet inför Herran. Och Samuel lät allt folket gå, hvar och en i sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Och Saul gick ock hem till Gibea, och en del af hären gick med honom, hvilkes hjerta Gud rörde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Men somlige Belials barn sade: Hvad skulle denne hjelpa oss? Och föraktade honom, och båro honom inga gåfvor; men han låts som han intet hörde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Så for Nahas, den Ammoniten, upp, och belade Jabes i Gilead. Och alle män i Jabes sade till Nahas: Gör ett förbund med oss, så vilje vi tjena dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Men Nahas, den Ammoniten, svarade dem: I så måtto vill jag göra ett förbund med eder, att jag stinger ut högra ögat på eder alla, och sätter eder till en försmädelse i hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Då sade till honom alle äldste i Jabes: Gif oss sju dagar, att vi måge sända bådskap i alla Israels gränsor; är då ingen hjelp, så vilje vi gå ut till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Så kommo bådskapen till Gibea Sauls, och sade detta för folkens öron. Då hof allt folket sina röst upp, och gret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Och si, då kom Saul utaf markene, gångandes bakefter sitt fä, och sade: Hvad skadar folkena, att det gråter? Då förtäljde de honom de mäns ord af Jabes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Då kom Guds Ande öfver honom, när han dessa orden hörde, och hans vrede förgrymmade sig svårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Och han tog ett par oxar, och styckade dem, och sände i alla Israels gränsor med bådskap, och lät säga: Den som icke utdrager efter Saul och Samuel, hans oxar skall man så göra. Så föll Herrans fruktan öfver folket, att de utdrogo såsom en man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Och man räknade dem i Besek; och Israels barn voro tre resor hundradetusend män; och Juda barn tretiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Och de sade till bådskapen, som komne voro: Säger de män i Jabes i Gilead: I morgon skolen I få hjelp, när solen är som hetast. Då desse bådskapen kommo, och förkunnade det de män i Jabes, vordo de glade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Och de män i Jabes sade: I morgon vilje vi gå ut till eder, att I mågen göra oss allt det eder täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Den andra morgonen skickade Saul folket i tre hopar, och de kommo i lägret i morgonväktene, och slogo de Ammoniter allt intill dagen vardt som hetast. Och de som öfverblefvo, vordo så förskingrade, att icke två blefvo tillhopa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Då sade folket till Samuel: Hvar äro de, som sade: Skall Saul råda öfver oss? Låt de män komma här fram, att vi måge dräpa dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul sade: På denna dagen skall ingen dö; ty Herren hafver i dag gjort salighet i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel sade till folket: Kommer, låter oss gå till Gilgal, och der förnya Konungariket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Så drog allt folket till Gilgal, och gjorde der Saul till Konung för Herranom i Gilgal, och offrade tackoffer inför Herranom. Och Saul med alla Israels män fröjdade sig der ganska storliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Då sade Samuel till hela Israel: Si, jag hafver hört edra röst uti allt det I mig sagt hafven, och hafver gjort en Konung öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Och si, der går nu edar Konung för eder; men jag är gammal och grå vorden, och mine söner äro när eder, och jag hafver gångit för eder, ifrå min ungdom allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Si, här är jag: Svarer mig inför Herranom och hans smorda, om jag någons mans oxa eller åsna tagit hafver? Om jag hafver någrom gjort öfvervåld och orätt? Om jag någon undertryckt hafver? Om jag af någons mans hand hafver tagit gåfvor, och hållit det hemliga? Så vill jag gifva eder det igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'De sade: Du hafver intet öfvervåld eller orätt gjort oss, ej heller någon undertryckt; ej heller af någons mans hand något tagit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Han sade till dem: Herren och hans smorde vare vittne emot eder i dag, att i intet hafven funnit i mine hand. De sade: Ja, vare vittne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Och Samuel sade till folket: Ja, Herren, som Mose och Aaron gjort hafver, och förde edra fäder utur Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Så går nu fram, att jag må döma eder för Herranom, öfver all Herrans rättfärdighet, som han med eder och edra fäder gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Då Jacob var kommen in uti Egypten, ropade edra fäder till Herran. Och Herren sände Mose och Aaron, att de skulle föra edra fäder utur Egypten, och lät bo dem på detta rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Men när de förgåto Herran sin Gud, sålde han dem under Sisera våld, höfvitsmansens i Hazor, och uti de Philisteers våld, och uti de Moabiters Konungs våld; de stridde emot dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Och de ropade till Herran, och sade: Vi hafve syndat, att vi hafve öfvergifvit Herran, och tjent Baalim och Astaroth; men frälsa oss nu ifrå våra fiendars hand, så vilje vi tjena dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Då sände Herren JerubBaal, Bedan, Jephthah och Samuel, och frälste eder utur edra fiendars händer, allt omkring, och lät eder bo tryggeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'När I då sågen att Nahas, Ammons barnas Konung, Kom emot eder, saden I till mig: Icke du, utan en Konung skall råda öfver oss; ändock Herren edar Gud var edar Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nu, här hafven I edar Konung, den I utvalt och begärat hafven; ty, si, Herren hafver satt en Konung öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Om I nu frukten Herran, och tjenen honom, och hören hans röst, och icke ären Herrans mun ohörige, så skolen både I och edar Konung, som öfver eder råder, efterfölja Herran edar Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Om I icke hören Herrans röst, utan ären Herrans mun ohörige, så skall Herrans hand vara emot eder och edra fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Går också nu fram, och ser det stora ärende, som Herren göra skall för edor ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Är icke nu hveteanden? Dock vill jag åkalla Herran, att han skall låta dundra och regna, att I skolen förnimma och se det stora onda, som I för Herrans ögon gjort hafven, att I hafven bedts eder Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Och då Samuel åkallade Herran, lät Herren den samma dagen dundra och regna; då fruktade allt folket Herran och Samuel ganska storliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Och sade alle till Samuel: Bed för dina tjenare Herran din Gud, att vi icke dö; ty öfver alla våra synder hafve vi ock gjort detta onda, att vi beddes oss Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Och Samuel sade till folket: Frukter eder intet, I hafven sannerliga gjort allt det onda; dock träder icke af ifrå Herranom, utan tjener Herranom af allo hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Och viker icke efter fåfängelig ting; ty det gagnar eder intet, och kan intet hjelpa eder, efter det en fåfängelig ting är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Förty Herren öfvergifver icke sitt folk, för sitt stora Namns skull; ty Herren hafver begynt till att göra eder sig sjelfvom till ett folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Vare ock fjerran ifrå mig, att jag så skulle synda emot Herran, att jag skulle aflåta bedja för eder, och lära eder den goda och rätta vägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Allenast frukter Herran, och tjener honom troliga af allo hjerta; förty I hafven sett huru stor ting han gör med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Men om I gören det ondt är, så skolen både I och edar Konung förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul hade varit Konung ett år; och som han tu år hade rådit öfver Israel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Utvalde han sig tretusend män utur Israel; tutusend voro med Saul i Michmas, och uppå berget BethEl, och ett tusend med Jonathan i Gibea BenJamins; men det andra folket lät han gå, hvar och en i sina hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Och Jonathan slog de Philisteer i deras lägre, som i Gibea var; det kom för de Philisteer. Och Saul lät blåsa i basunen öfver hela landet, och säga: I Ebreer, hörer till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Och hela Israel hörde sägas: Saul hafver slagit de Philisteers lägre; ty Israel luktade illa för de Philisteer, och allt folket ropades till Saul i Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Då församlade sig de Philisteer till att strida med Israel, tretiotusend vagnar, sextusend resenärer, och eljest folk så mycket som sanden i hafsstrandene; och de drogo upp, och lägrade sig i Michmas, östan för BethAven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Då de män af Israel sågo, att de i nöd voro, ty folket var förskräckt, krupo de uti kulor, och klyfter, och klippor, och i hål, och i gropar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Och de Ebreer drogo öfver Jordan in uti Gads land och Gileads; men Saul var ännu i Gilgal, och allt folket, som följde honom, vardt förtvifladt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Då förbidde han i sju dagar, den tiden som Samuel förelagt hade; och efter Samuel icke kom till Gilgal, skingrade sig folket ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Då sade Saul: Bärer mig hit bränneoffer och tackoffer; och han offrade bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Och som han hade fullkomnat bränneoffret, si, då kom Samuel; då gick Saul ut emot honom, till att helsa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Men Samuel sade: Hvad hafver du gjort? Saul svarade: Jag såg att folket förskingrade sig ifrå mig, och du kom icke i rättom tid, och de Philisteer voro församlade i Michmas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Då sade jag: Nu komma de Philisteer hitneder till mig i Gilgal, och jag hafver icke bedit Herrans ansigte; då vågade jag det, och offrade bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Men Samuel sade till Saul: Du hafver gjort dårliga, och icke hållit Herrans dins Guds bud, som han dig budit hafver; ty Herren hade stadfäst ditt rike öfver Israel till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Men nu skall ditt rike icke blifva ståndandes. Herren hafver sökt sig en man efter sitt hjerta, honom hafver Herren budit att vara en Förste öfver hans folk; ty du hafver icke hållit Herrans bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Och Samuel stod upp, och gick ifrå Gilgal upp till Gibea BenJamins. Men Saul talde det folk, som när honom var, vid sexhundrad män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Och Saul med hans son Jonathan, och det folk som när honom var, blefvo uppå BenJamins hög; men de Philisteer hade lägrat sig i Michmas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Och utu de Philisteers lägre drogo tre hopar till att förhärja landet. Den ene vände sig inpå den vägen till Ophra uti Sauls land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Den andre vände sig inpå den vägen till BethHoron; den tredje vände sig på den vägen, som drager åt den dalen Zeboim vid öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Och ingen smed vardt funnen i hela Israels land; förty de Philisteer tänkte, de Ebreer måtte göra svärd och spjut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Ty måste hela Israel fara neder till de Philisteer, om någor ville låta hvässa sin plogbill, hacko, yxa eller lia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Och när eggen på liarna, hackorna, gafflarna och yxarna, vardt slö, och uddarna vordo stubbote.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Då nu stridsdagen kom, vardt intet svärd eller spjut funnet i hela folkens hand, som var med Saul och Jonathan; utan Saul och hans son hade värjor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Och de Philisteers lägre drog fram vid Michmas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Det begaf sig i den tiden, att Jonathan, Sauls son, sade till sin dräng, som hans värjo bar: Kom, låt oss gå utöfver till de Philisteers lägre, som deruppe är; och han sade sinom fader intet till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Men Saul blef ytterst i Gibea under ett granatträ, som i förstadenom var; och det folk, som när honom var, var vid sexhundrad män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Och Ahia, Achitobs son, Icabods broders, Pinehas sons, Eli sons, var Herrans Prest i Silo, och drog lifkjortelen uppå; folket visste icke heller, att Jonathan var bortgången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Och i vägenom, der Jonathan sökte efter att gå öfver till de Philisteers lägre, voro två branta klippor, den ena på denna sidone, och den andra på hinsidone; den ena het Bozez, den andra Sene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Och den ena var norrut ifrå Michmas, och den andra var söderut ifrå Gaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Och Jonathan sade till sin vapnedragare: Kom, låt oss gå utöfver till dessa oomskornas lägre; tilläfventyrs varder Herren något uträttandes genom oss; förty det är icke Herranom tungt hjelpa genom många, eller genom få.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Då svarade honom hans vapnedragare: Gör allt det i dino hjerta är; gack åstad, si, jag är med dig såsom ditt hjerta vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonathan sade: Nu väl, när vi komme ditöfver till det folket, och de få se oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Om de då säga: Står qvare, tilldess vi komme till eder; så vilje vi blifva ståndande i vårt rum, och icke stiga upp till dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Men om de säga: Kommer hitupp till oss; så vilje vi stiga upp till dem; så hafver Herren gifvit dem oss i våra händer; och det skall oss vara för ett tecken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Då nu de Philisteers lägre fingo se dem båda, sade de Philisteer: Si, de Ebreer äro utkrupne utu hålen, der de sig gömt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Och männerna i lägret svarade Jonathan och hans vapnedragare, och sade: Kommer hitupp till oss, vi vilje väl lära eder. Då sade Jonathan till sin vapnedragare: Träd efter mig, Herren hafver gifvit dem i Israels händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Och Jonathan klef med händer och fötter uppföre, och hans vapnedragare efter honom. Då föllo de neder för Jonathan, och hans vapnedragare slog allt ihjäl efter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Så att första slagtningen, som Jonathan och hans vapnedragare gjorde, var vid tjugu män, på en halfvan åker vid pass, som ett par oxars dagsplöjning är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Och en rädsel kom på markene i lägret, och på hela folket i lägrena; och de som utsände voro till att förhärja, dem kom ock rädsel uppå, och landet skalf dervid; ty det var en förskräckelse af Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Och Sauls väktare i Gibea BenJamins fingo se, att hopen skingrades, och lupo hit och dit, och vordo slagne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul sade till folket, som när honom var: Räkner, och ser till, hvilken af oss är bortgången; och då de räknade, si, då var Jonathan och hans vapnedragare icke der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Då sade Saul till Ahia: Bär fram Guds ark; ty Guds ark var på den tiden när Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Och som Saul ännu talade med Prestenom, förökade sig sorlet och löpandet uti de Philisteers lägre. Och Saul sade till Presten: Tag dina hand af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Och Saul ropade, och allt folket, som med honom var, och kommo i stridena; och si, då gick hvars och ens svärd emot den andra, och var ett mägta sorl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Och de Ebreer, som tillförene hade varit när de Philisteer, och hade varit uppdragne med dem i lägret allt omkring, gåfvo sig intill Israel, som voro med Saul och Jonathan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Och alle män af Israel, som sig förgömt hade på Ephraims berg, då de hörde att de Philisteer flydde, följde de efter med de andra till stridena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Alltså halp då Herren Israel på den tiden, och slaget stod allt intill BethAven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Och då Israels män försmäktade på den dagen, besvor Saul folket, och sade: Förbannad vare hvar och en, som bröd äter intill aftonen, att jag må hämnas på mina fiendar. Så smakade ock allt folket intet bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Och hela landet kom i skogen, och der låg hannog på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Då folket kom in i skogen, si, då flöt der hannog; men ingen lät honom med handene komma till sin mun; ty folket fruktade sig för eden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Men Jonathan hade icke hört, att hans fader hade besvorit folket; och räckte sin staf ut, som han hade i sine hand, och doppade med ändanom i hannogskakona, och vände sina hand till sin mun; så vordo hans ögon frisk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Då svarade en af folkena, och sade: Din fader hafver besvorit folket, och sagt: Förbannad vare hvar och en, som något äter i dag. Och folket var förtröttadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Då sade Jonathan: Min fader hafver bedröfvat landet; ser, huru min ögon äro frisk vordne deraf, att jag af denna hannogen något litet smakat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Hade folket i dag ätit af sina fiendars rof, som de funnit hafva, så hade ock slagtningen vordit större emot de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Och de slogo på den dagen de Philisteer, ifrå Michmas allt intill Ajalon; och folket vardt ganska trött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Och folket vände sig till bytet, och togo får, fä och kalfvar, och slagtade på jordene, och åto det med blodet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Så vardt Saul förkunnadt: Si, folket hafver syndat emot Herran, och ätit blod. Han sade: I hafven illa gjort; välter hit till mig en stor sten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Och Saul sade ytterligare: Går ut ibland folket, och säger dem, att hvar och en hafve sin oxa och sitt får till mig, och slagter det här, att I mågen äta, och icke synda emot Herranom med det blodätandet. Så drog allt folket fram, hvar och en sin oxa i sine hand, om nattena, och slagtade det der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Och Saul byggde Herranom ett altare; det är det första altare, som han byggde Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Och Saul sade: Låt oss draga ned efter de Philisteer i natt, och beröfva dem, tilldess i morgon ljust varder, att vi ingen af dem låte öfverblifva. De svarade: Gör allt det dig täckes. Men Presten sade: Låt oss gå hit till Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Och Saul frågade Gud: Skall jag draga ned efter de Philisteer, och vill du gifva dem uti Israels händer? Men han svarade honom på den tiden intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Då sade Saul: Låt gå hitfram all hörn af folket; och förfarer, och tillser, när hvilkom denna synden är på denna tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Ty så visst som Herren Israels hjelpare lefver, om det än vore min son Jonathan, så skall han dö. Och ingen svarade honom utaf hela folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Och han sade till hela Israel: Varer I på den sidon; jag och min son Jonathan vilje vara på desso sidone. Folket sade till Saul: Gör hvad dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Och Saul sade till Herran Israels Gud: Gör det rätt är. Då råkade det på Jonathan och Saul; och folket gick qvitt ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sade: Kaster öfver mig och min son Jonathan. Då råkade det på Jonathan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Och Saul sade till Jonathan: Säg mig, hvad hafver du gjort? Jonathan lät honom förståt, och sade: Jag smakade litet hannog med stafven, som jag i mine hand hade; och si, derföre måste jag dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Då sade Saul: Gud göre mig det och det; Jonathan, du måste döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Men folket sade till Saul: Skulle Jonathan dö, den en så stor salighet gjort hafver i Israel? Bort det! Så visst som Herren lefver, icke ett hår af hans hufvud skall falla på jordena; förty Gud hafver i dag gjort det igenom honom. Alltså friade folket Jonathan, att han icke dö måste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Så drog Saul upp ifrå de Philisteer; och de Philisteer drogo till sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Men då Saul hade tagit riket in öfver Israel, stridde han emot alla sina fiendar allt omkring; emot de Moabiter, emot Ammons barn, emot de Edomeer, emot Zoba Konungar, emot de Philisteer; och hvart han vände sig, der straffade han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Och han församlade en här, och slog de Amalekiter; och friade Israel ifrån allas deras hand, som dem förtryckte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Och Saul hade söner, Jonathan, Isvi, MalchiSua. Och hans två döttrar heto alltså: den förstfödda Merob, och den yngsta Michal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Och Sauls hustru het Ahinoam, Ahimaaz dotter; och hans härhöfvitsman het Abner, Ners son, Sauls faderbroders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Men Kis var Sauls fader, och Ner, Abners fader, var Abiels son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Och ett mägtigt örlig var emot de Philisteer, så länge Saul lefde; och hvar Saul såg en doglig och stridsam man, den tog han till sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Men Samuel sade till Saul: Herren sände mig, att jag skulle smörja dig till Konung öfver hans folk Israel; så hör nu röstena af Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Så säger Herren Zebaoth: Jag hafver tänkt uppå hvad Amalek gjorde Israel, och huru han låg i vägen för honom, då han drog utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Så drag nu åstad, och slå de Amalekiter, och gif dem tillspillo med allt det de hafva; skona dem intet, utan dräp både man och qvinno, barn, och dem som dia, fä och får, camel och åsna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul lät detta komma för folket, och talde dem i Telaim, tuhundradtusend fotfolk, och tiotusend män af Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Och då Saul kom till de Amalekiters stad, satte han ett bakhåll vid bäcken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Och lät säga de Keniter: Går edra färde, och gifver eder ifrå de Amalekiter, att jag icke utrotar eder med dem; förty I gjorden barmhertighet med all Israels barn, då de drogo utur Egypten. Alltså gåfvo de Keniter sig ifrå de Amalekiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Då slog Saul de Amalekiter, allt ifrå Hevila intill Sur, som ligger för Egypten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Och grep Agag, de Amalekiters Konung, lefvande; och allt folket gaf han tillspillo med svärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Men Saul och folket skonade Agag, och hvad god får och fä var, och väl fett, och lamb, och allt det godt var, och ville icke låtat tillspillo; men det som slemt var, och intet dogde, det läto de tillspillo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Då skedde Herrans ord till Samuel, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Mig ångrar, att jag hafver gjort Saul till Konung; ty han hafver vändt sig ifrå mig, och icke fullkomnat min ord. Dess vardt Samuel vred; och ropade till Herran den hela nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Och Samuel stod bittida upp, att han skulle om morgonen möta Saul; och honom vardt sagdt, att Saul var kommen till Carmel, och reste sig upp ett segertecken, och var omkringdragen, och kommen neder till Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Som nu Samuel kom till Saul, sade Saul till honom: Välsignad vare du Herranom! Jag hafver fullkomnat Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel svarade: Hvad är då det rop af får i min öron, och det rop af fä, som jag hörer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul sade: Utaf de Amalekiter hafva de tagit det; förty folket skonade det bästa får och fä, för Herrans dins Guds offers skull; det andra hafve vi låtit tillspillo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Men Samuel svarade Saul: Städ till, att jag säger dig, hvad Herren hafver talat med mig i denna natt. Han sade: Säg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sade: Är det icke så, då du liten vast för din ögon, vardt du ett hufvud i Israels slägter, och Herren smorde dig till Konung öfver Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Och Herren sände dig på vägen, och sade: Far bort, och förgör de syndare, de Amalekiter, och strid emot dem, tilldess du gör en ända på dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Hvi hafver du icke lydt Herrans röst; utan vändt dig till rof, och illa handlat inför Herrans ögon?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Då sade Saul till Samuel: Hafver jag dock lydt Herrans röst, och hafver dragit den vägen, som Herren mig sändt hafver; jag hafver fört hit Agag, de Amalekiters Konung, och förgjort de Amalekiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Men folket hafver tagit af rofvet får och fä, det bästa af de spillgifno, till att offra det Herranom dinom Gud i Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Men Samuel sade: Menar du att Herren hafver lust till offer och bränneoffer, såsom dertill, att man lyder Herrans röst? Si, lydnad är bättre än offer, och höra till är bättre än det feta af vädrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Förty olydnad är en trolldomssynd, och gensträfvighet är ett afguderi och afgudadyrkan; så, efter du hafver förkastat Herrans ord, hafver han ock förkastat dig; att du icke skall vara Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Då sade Saul till Samuel: Jag hafver syndat, att jag hafver öfvergångit Herrans befallning och din ord; ty jag fruktade folket, och hörde deras röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Och nu förlåt mig den synden, och vänd tillbaka med mig, att jag må tillbedja Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sade till Saul: Jag vänder intet om med dig; ty du hafver förkastat Herrans ord, och Herren hafver ock förkastat dig, att du icke skall vara Konung öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Och som Samuel vände sig om, till att gå sina färde, fattade han honom i hans kjortels flik, och hon refs sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Då sade Samuel till honom: Herren hafver i denna dag rifvit Israels Konungarike ifrå dig, och gifvit dinom nästa, den bättre är än du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ljuger icke heller Hjelten i Israel, eller låter sig ångra; ty han är ingen menniska, att han sig något ångra låter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Men han sade: Jag hafver syndat; så gör mig dock du den ärona inför de äldsta af mitt folk, och för Israel, och vänd om med mig, att jag må tillbedja Herran din Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Så vände då Samuel om, och följde Saul, så att Saul tillbad Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Och Samuel sade: Låt komma fram för mig Agag, de Amalekiters Konung; och Agag gick dristeliga fram till honom. Och Agag sade: Alltså måste man fördrifva dödsens bitterhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel sade: Såsom ditt svärd hafver gjort qvinnor barnlös, så skall ock din moder blifva barnlös ibland qvinnor. Så högg Samuel Agag i stycker inför Herranom i Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Och Samuel gick bort till Ramath; men Saul drog upp till sitt hus i Gibea Sauls.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Och Samuel såg Saul intet mer intilldess han blef död; dock likväl sörjde Samuel för Sauls skull, att Herren hade ångrat sig, att han hade gjort honom till Konung öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Och Herren sade till Samuel: Huru länge vill du sörja för Sauls skull, den jag förkastat hafver, så att han icke skall vara Konung öfver Israel? Uppfyll ditt horn med oljo, och gack åstad; jag vill sända dig till den BethLehemiten Isai; förty af hans söner hafver jag försett mig en Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel sade: Huru skulle jag gå dit? Saul får det veta, och slår mig ihjäl. Herren sade: Tag en kalf af fät till dig, och säg: Jag är kommen till att offra Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Och du skall kalla Isai till offret; då vill jag visa dig hvad du göra skall, att du der smörjer den jag dig säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel gjorde såsom Herren honom sagt hade, och kom till BethLehem; då förskräcktes de äldste i stadenom, och gingo emot honom, och sade: Är det frid, medan du kommer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Han sade: Ja, jag är kommen till att offra Herranom; helger eder, och kommer med mig till offret. Och han helgade Isai och hans söner, och böd dem till offret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Då de nu kommo in, såg han på Eliab, och tänkte: Visst är för Herranom här hans smorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Men Herren sade till Samuel: Se intet på hans skapnad, eller hans stora person; jag hafver förkastat honom, förty det går icke efter som en menniska ser. En menniska ser det för ögonen är, men Herren ser till hjertat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Då kallade Isai AbiNadab, och lät honom gå fram för Samuel; och han sade: Denna hafver Herren ock intet utvalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Då lät Isai gå fram Samma; men han sade: Denna hafver Herren ock intet utvalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Då lät Isai gå sina sju söner fram för Samuel; men Samuel sade till Isai: Herren hafver ingen af dem utvalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Och Samuel sade till Isai: Äro nu här piltarna? Han sade: Det är ännu en den minste igen, och si, han vaktar får. Då sade Samuel till Isai: Sänd bort, och låt hemta honom; ty vi skole icke sätta oss, förra än han kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Då sände han åstad, och lät hemta honom. Och han var brunaktig, med fager ögon och dägelig skapnad. Och Herren sade: Upp, och smörj honom; den är det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Då tog Samuel sitt oljohorn, och smorde honom midt ibland hans bröder. Och Herrans Ande kom öfver David, ifrå den dagen, och allt sedan; och Samuel stod upp, och gick till Ramath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Och Herrans Ande vek ifrå Saul, och en ond ande af Herranom qvalde honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Då sade Sauls tjenare till honom: Si, en ond ande af Gudi qväl dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Vår herre säge sina tjenare som för honom stå, att de söka en man, som kan på harpo och strängaspel; på det att, när den onde Guds anden kommer öfver dig, må han spela med sine hand, att det må varda bättre med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Då sade Saul till sina tjenare: Ser efter en man, som är god på strängaspel, och hafver honom hit till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Då svarade en af tjenarena, och sade: Si, jag hafver sett en Isai son, den BethLehemitens; han kan på strängaspel, en dogelig man, och stridsam, och förståndig i saker, och dägelig, och Herren är med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Då sände Saul båd till Isai, och lät säga honom: Sänd din son David till mig, som är med fåren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Så tog Isai en åsna, med bröd, och en lägel vin, och ett kid af getterna, och sände till Saul med sinom son David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Så kom David till Saul, och gick fram för honom; och han vardt honom ganska kär, och blef hans vapnedragare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Och Saul sände till Isai, och lät säga honom: Låt David blifva inför mig; ty han hafver funnit ynnest för min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'När nu den Guds anden kom öfver Saul, så tog David harpona, och spelade med sine hand; så kom Saul till sig igen, och det vardt bättre med honom, och den onde anden vek ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'De Philisteer församlade sina härar till strid, och kommo tillhopa i Socho i Juda, och lägrade sig emellan Socho och Aseka, vid ändan af Dammin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Men Saul och Israels män komma tillhopa, och lägrade sig i ekdalenom, och skickade sig till strid emot de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Och de Philisteer stodo på ett berg på hinsidon, och de Israeliter på ett berg på denna sidone, så att en del var emellan dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Då kom framträdandes utu de Philisteers lägre en man, en kämpe, benämnd Goliath af Gath, sex alnar och en tvärhand lång;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Och hade en kopparhjelm på sitt hufvud, och ett fjällpansar uppå; och vigten på pansaret var femtusend siklar koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Och hade kopparbenvapen uppå sin ben, och en kopparsköld på sina axlar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Och skaftet på hans spjut var såsom ett väfträ, och jernet på hans spjut höll sexhundrad siklar jern; och hans vapnedragare gick framför honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Och han stod och ropade till Israels slagorden, och sade till dem: Hvi ären I utdragne till att skicka eder till strid? Är icke jag en Philisteer, och I ären Sauls tjenare? Väljer en ut af eder, som går hitneder till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Kan han strida emot mig, och slår mig, så vilje vi vara edra tjenare; varder ock jag hans öfverman, och slår honom, så skolen I vara våra tjenare, och skolen tjena oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Och Philisteen sade: Jag hafver i denna dag gjort Israels här en skam; låter mig få en, och låter oss strida med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Då Saul och hela Israel hörde dessa Philisteens ord, förskräckte de sig, och fruktade sig storliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Men David var en Ephratisk mans son, af BethLehem Juda, som het Isai; han hade åtta söner, och var en gammal man i Sauls tid, och var ålderstigen ibland män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Och de tre äldste Isai söner voro dragne med Saul till stridena; och var detta deras namn: Eliab den förstfödde, AbiNadab den andre, och Samma den tredje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Men David var den yngste. Då nu de tre äldste voro utdragne med Saul till stridena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Gick David åter hem ifrå Saul, till att vakta sins faders får i BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Men den Philisteen trädde fram både morgon och afton, och stod der i fyratio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Och Isai sade till sin son David: Tag åt dina bröder detta epha af torkad ax, och dessa tio bröd, och löp bort i hären till dina bröder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Och dessa tio blöta ostar, och få höfvitsmannenom; och besök dina bröder, om dem väl går, och tag vara uppå hvad de säga dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Men Saul, och de, och alle Israels män voro i ekdalenom, och stridde emot de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Då stod David bittida upp om morgonen, och befallde fåren herdanom; lade uppå sig, och gick åstad, såsom Isai honom budit hade, och kom till vagnborgena; och hären var utdragen, och hade skickat sig, och de skriade i stridene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Ty Israel hade skickat sig; så voro ock de Philisteer redo emot deras här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Då lät David det han bar i tygvaktarens händer, och lopp bort i spetsen, och gick bort och helsade sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Och vid han nu talade med dem, si, då trädde den kämpen fram, som het Goliath, den Philisteen af Gath, utu de Philisteers här, och talade såsom tillförene; och David hörde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Men hvar man i Israel, då han den mannen såg, flydde för honom, och fruktade sig storliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Och hvar man i Israel sade: Hafven I icke sett denna mannen, som uppgången är? Ty han är uppgången till att tala försmädelse emot Israel; och den honom slår, honom vill Konungen göra mycket rik, och gifva honom sina dotter; och vill göra hans faders hus fritt i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Då sade David till männerna, som när honom stodo: Hvad skall man gifva honom, som slår denna Philisteen, och vänder denna skammen ifrån Israel? Ty hvad är denna oomskorne Philisteen, som försmäder lefvandes Guds här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Då sade folket honom såsom tillförene: Det skall man gifva honom, som honom slår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Och Eliab hans äldste broder hörde att han talade med männerna, och vardt vred på David, och sade: Hvi äst du hitneder kommen? Och hvi hafver du öfvergifvit de få fåren i öknene? Jag känner väl dina öfverdådighet, och dins hjertas ondsko; ty du äst hitned kommen till att se stridena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David sade: Hvad hafver jag då nu gjort? Är det mig icke befaldt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Och vände sig om till en annan, och sade såsom han hade sagt tillförene; då svarade honom folket såsom tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Och då de hörde de ord, som David sade, förkunnade de det Saul; och han lät hemta honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Och David sade till Saul: Ingens mans hjerta gifve sig för den sakens skull; din tjenare skall gå bort, och strida med Philisteen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul sade till David: Du kan icke gå bort emot denna Philisteen, och strida med honom; ty du äst en yngling, och han är en stridsman ifrå hans ungdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Men David sade till Saul: Din tjenare vaktade sins faders får, och då der kom ett lejon och en björn, och tog bort ett får af hjorden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Då följde han efter, och slog honom, och tog det utu hans mun; och då han reste sig upp emot mig, tog jag honom i skägget, och slog honom, och drap honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Så hafver din tjenare slagit både lejon och björn. Så må nu denne oomskorne Philisteen vara såsom endera; ty han hafver försmädat lefvandes Guds här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Och David sade: Herren, som mig frälste ifrå lejonet, och ifrå björnen, han frälsar mig ock ifrå denna Philisteen. Och Saul sade till David: Gack åstad, Herren vare med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Och Saul drog sin kläder uppå David, och satte honom en kopparhjelm på hans hufvud, och lade ett pansar uppå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Och David band sitt svärd öfver sin kläder, och begynte till att gå; ty han hade icke försökt det. Då sade David till Saul: Jag kan icke så gå; ty jag är det icke van. Och han lade det ifrå sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Och tog sin staf i sina hand, och utvalde fem släta stenar utu bäcken, och lade dem uti herdaskräppona, som han hade, och i säcken, och tog slungona i sina hand, och gick fram emot Philisteen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Och Philisteen gick ock framåt, och nalkades intill David, och hans vapnedragare för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Då nu Philisteen såg och skådade David, föraktade han honom; ty han var en yngling, brunaktig och dägelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Philisteen sade till David: Är jag då en hund, att du kommer emot mig med käppar? Och bannade David vid sina gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Och sade till David: Kom hit till mig, jag skall gifva ditt kött foglom under himmelen och djurom på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David sade till Philisteen: Du kommer till mig med svärd, spjut och sköld; men jag kommer till dig i Herrans Zebaoths Namn, Israels härs Guds, den du försmädat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Och Herren skall i denna dag gifva dig uti mina hand, att jag skall slå dig, och taga ditt hufvud af dig, och gifva de Philisteers härs kropp i denna dag foglom under himmelen, och djurom på markene, att all land skola förnimma, att Israel hafver en Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Och all denna menigheten skall förnimma, att Herren icke hjelper genom svärd eller spjut; ty striden är Herrans, och han skall gifva eder i våra händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Då nu Philisteen reste åstad, gick och nalkades in mot David, skyndade sig David, och lopp ifrå hären emot Philisteen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Och David tog sina hand i skräppona, och fattade derut en sten, och slungade, och råkade Philisteen i hans panno, så att stenen gick in i pannona; och han föll på jordena på sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Alltså öfvervann David Philisteen med slungone och stenenom, och slog honom, och drap honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Och efter David intet svärd hade i sine hand, lopp han fram till Philisteen, och tog hans svärd, och drog det utu skidone, och drap honom; och högg honom dermed hufvudet af. Då de Philisteer sågo, att deras starkaste var död, flydde de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Och Israels män och Juda reste upp, ropade och jagade efter de Philisteer, intilldess man kommer i dalen, och allt intill Ekrons portar; och de Philisteer föllo slagne på vägenom till portarna, allt intill Gath, och intill Ekron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Och Israels barn vände om af det jagandet efter de Philisteer, och skinnade deras lägre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Men David tog Philisteens hufvud, och förde det till Jerusalem; men hans vapen lade han i sina hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Men då Saul såg David utgå emot Philisteen, sade han till Abner sin härhöfvitsman: Hvars son är den ynglingen? Abner sade: Så visst som din själ lefver, Konung jag vet det icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Konungen sade: Så fråga derefter, hvars son den ynglingen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Då nu David kom igen, sedan Philisteen slagen var, tog Abner honom, och hade honom in för Saul; och han hade den Philisteens hufvud i sine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Och Saul sade till honom: Hvars son äst du, yngling? David sade: Jag är dins tjenares Isai den BethLehemitens son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Då han hade uttalat med Saul, förband sig Jonathans hjerta med Davids hjerta; och Jonathan vardt kär åt honom, såsom sitt eget hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Och Saul tog honom i den dagen, och lät honom icke mer komma i sins faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Och Jonathan och David gjorde ett förbund tillhopa; ty han hade honom kär, såsom sitt eget hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Och Jonathan drog af sin kjortel, som han hade uppå, och gaf honom David; dertill sin mantel, sitt svärd, sin båga och sitt bälte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Och David gick ut, dit Saul sände honom, och skickade sig visliga; och Saul satte honom öfver krigsfolket, och han var allo folkena, och desslikes Sauls tjenarom, täcker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Men det begaf sig, då han igenkommen var, sedan han hade slagit Philisteen, att qvinnorna af alla Israels städer gingo emot Konung Saul med sång och harpor, med trummor, med glädje, och med gigor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Och qvinnorna söngo till hvarandra, och spelade, och sade: Saul hafver slagit tusende; men David tiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Då förgrymmade sig Saul storliga, och det talet behagade honom ganska illa, och sade: De hafva gifvit David tiotusend, och mig tusende; han varder väl ännu Konung?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Och Saul såg illa uppå David, ifrå den dagen, och allt sedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'På den andra dagen föll den onde anden af Gudi öfver Saul, och han propheterade hemma i huset; men David spelade på strängerna med sine hand, såsom han dageliga plägade. Och Saul hade ett spjut i handene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Och sköt det åstad, och tänkte: Jag vill skjuta David igenom i väggena; men David gaf sig undan för honom i två gånger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Och Saul fruktade för David; ty Herren var med honom, och var gången ifrå Saul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Så satte Saul honom ifrå sig, och gjorde honom till höfvitsman öfver tusende män; och han gick ut och in för folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Och David hade sig förnumsteliga i alla sina gerningar; och Herren var med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Då nu Saul såg, att han var så ganska förnumstig, fruktade han för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Men hela Israel och Juda hade David kär; ty han gick ut och in för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Och Saul sade till David: Si, min äldsta dotter Merob vill jag gifva dig till hustru; var manlig, och för Herrans krig; ty Saul tänkte, min hand skall icke komma vid honom, utan de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Men David svarade Saul: Ho är jag? Eller hvad är mitt lefverne, och mins faders hus slägt i Israel, att jag skulle varda Konungens måg?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Då nu tiden kom, att Merob, Sauls dotter, skulle vordit gifven David, vardt hon gifven Adriel den Meholathiten till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Men Michal, Sauls dotter, hade David kär. Då det vardt sagdt Saul, sade han: Det är rätt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Jag vill gifva honom henne, att hon må komma honom på fall, och de Philisteers händer måga komma öfver honom. Och han sade till David: Du skall i dag varda min måg med den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Och Saul böd sina tjenare: Taler vid David hemliga, och säger: Si, Konungen hafver vilja till dig, och alla hans tjenare älska dig; så blif nu Konungens måg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Och Sauls tjenare talade dessa orden för Davids öron; men David sade: Tycker eder det vara en ringa ting, att vara Konungens måg? Och jag är en fattig och ringa man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Och Sauls tjenare gåfvo honom svar igen, och sade: Sådana ord hafver David sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul sade: Säger så till David: Konungen begärar ingen morgongåfvo, annan än hundrade förhudar af de Philisteer, att man må hämnas på Konungens fiendar; ty Saul for efter att fälla David genom de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Då sade hans tjenare David dessa orden. Och David tyckte så godt vara, att han måtte blifva Konungens måg. Och tiden var ännu icke ute.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Och David stod upp, och drog åstad med sina män, och slog af de Philisteer tuhundrad män; och David hade deras förhudar, och förnöjde Konungen med talet; på det han skulle varda Konungens måg. Då gaf Saul honom sina dotter Michal till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Och Saul såg och märkte, att Herren var med honom. Och Michal, Sauls dotter, hade honom kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Då fruktade Saul ännu mer för David, och vardt hans fiende i alla sina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Och då de Philisteers Förstar drogo ut, handlade David förnumsteligare än alle Sauls tjenare, när de utdrogo, så att hans namn vardt mycket aktadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Men Saul talade med sin son Jonathan, och med alla sina tjenare, att de skulle slå David ihjäl. Men Jonathan, Sauls son, hade stor vilja till David;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Och underviste honom det, och sade: Min fader Saul far efter, och vill dräpa dig; så förvara dig nu till morgons, och blif öfver en sido, och göm dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Men jag vill gå ut med min fader, och vill stå bredevid min fader på markene, der du äst, och tala om dig med min fader; och hvad jag ser, det vill jag kungöra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Och Jonathan talade det bästa om David med sinom fader Saul, och sade till honom: Konungen synde icke på sin tjenare David; ty han hafver intet brutit dig emot, och hans gerningar äro dig ganska nyttiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Och han hafver satt sitt lif i sina hand, och slog den Philisteen, och Herren gjorde en stor salighet helo Israel; det hafver du sett, och gladt dig deraf; hvi vill du då synda på ett oskyldigt blod, så att du dräper David utan sak?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Då lydde Saul Jonathans röst, och svor: Så visst som Herren lefver, skall han icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Då kallade Jonathan David, och sade honom alla dessa orden; och hade honom in för Saul, att han var för honom, såsom tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Så kom åter ett örlig; och David drog ut, och stridde emot de Philisteer, och slog en stor slagtning; så att de flydde för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Men den onde Herrans ande kom öfver Saul, och han satt i sitt hus, och hade ett spjut i sine hand; så spelade David på strängerna med handene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Men Saul for efter att skjuta David igenom med spjutet i väggena; men han vek undan ifrå Saul, och spjutet for in i väggena; och David flydde, och undslapp i den nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Och Saul sände båd i Davids hus, att de skulle taga vara uppå honom, och om morgonen slå honom ihjäl; men Michal, Davids hustru, underviste det honom, och sade: Om du i natt icke undsätter dina själ, så måste du i morgon dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Så lät Michal honom neder genom ett fenster; och han gick sina färde, flydde, och undslapp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Och Michal tog ett beläte, och lade det i sängena; och lade ett getskinn om dess hufvud, och öfvertäckte det med kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Då sände Saul båd, att de skulle hemta David; men hon sade: Han är krank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Då sände Saul båd, till att bese David, och sade: Bärer honom hitupp till mig med sängene, att han må dräpas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Då nu båden kommo, si, då låg belätet i sängene, och getskinn om dess hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Då sade Saul till Michal: Hvi hafver du bedragit mig, och släppt min fienda, att han skulle undkomma? Michal sade till Saul: Han sade till mig: Låt mig gå, eller jag slår dig ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Och David flydde, och undkom, och kom till Samuel i Rama, och sade honom allt det Saul honom gjort hade; och han gick bort med Samuel, och blefvo i Najoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Och det vardt undervist Saul: Si, David är i Najoth i Rama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Då sände Saul båd, att de skulle hemta David; och de sågo chorar med Propheter prophetera, och Samuel var deras tillsiare. Då kom Guds Ande uppå Sauls båd, så att de ock propheterade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Då det vardt Saul sagdt, sände han annor båd; de propheterade ock. Så sände han tredje båden; de propheterade ock.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Så gick han ock sjelf till Rama; och då han kom till den stora brunnen, som är i Sechu, frågade han, och sade: Hvar är Samuel och David? Då vardt honom sagdt: Si, i Najoth i Rama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Och han gick dit till Najoth i Rama; och Guds Ande kom också öfver honom; och han gick och propheterade, tilldess han kom till Najoth i Rama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Och han drog också sin kläder af, och propheterade också för Samuel, och föll naken neder den hela dagen, och den hela nattena. Deraf säger man: Är ock Saul ibland Propheter?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Och David flydde ifrå Najoth i Rama, och kom och talade för Jonathan: Hvad hafver jag gjort? Hvad hafver jag misshandlat? Hvad hafver jag syndat för dinom fader, att han står efter mitt lif?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Han sade till honom: Bort det! Du skall icke dö; si, min fader gör intet, hvarken stort eller litet, det han icke uppenbarar för min öron; hvi skulle då min fader dölja detta för mig? Det skall icke gå så till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Då svor David ytterligare, och sade: Din fader vet väl, att jag hafver funnit nåde för din ögon; derföre må han tänka, Jonathan skall intet veta häraf, på det han icke skall bedröfvas deraf; sannerliga, så visst som Herren lefver, och så visst som din själ lefver, det är icke mer än ett steg emellan mig och döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonathan sade till David: Jag vill göra dig allt det ditt hjerta begärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David sade till honom: Si, i morgon är nymånad, att jag skall sitta till bords med Konungen; så låt mig betämma, att jag gömmer mig på markene allt intill aftonen på tredje dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Om din fader frågar efter mig, så säg: David bad mig, att han måtte löpa till sin stad BethLehem; förty det är ett årligit offer allo slägtene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Är det så, att han säger: Det är godt; så står det väl med dinom tjenare; varder han ock vred, så varder du väl märkandes, att han hafver ondt i sinnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Så gör nu barmhertighet med dinom tjenare; ty du hafver med mig dinom tjenare gjort ett förbund i Herranom; är ock någor missgerning i mig, så dräp du mig, och låt mig icke komma inför din fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonathan sade: Bort det ifrå dig, att jag skulle märka, att min fader hade i sinnet göra dig ondt, och jag icke skulle det säga dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David sade: Ho skall säga mig det, om din fader svarar dig något hårdt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonathan sade till David: Kom, låt oss gå ut på markena; och de gingo både ut på markena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Och Jonathan sade till David: Herre Israels Gud, om jag utfrågar af minom fader i morgon och öfvermorgon, att det står väl till med David, och jag icke sänder till dig, och uppenbarar det för din öron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Så göre Herren det och det med Jonathan; men om minom fader täckes det ondt är emot dig, så vill jag ock uppenbara det för din öron, och släppa dig, att du går dina färde med frid; och Herren vare med dig, såsom han med minom fader vant hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Gör jag det icke, så gör du inga Herrans barmhertighet med mig, så länge jag lefver, ej heller när jag dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Och när Herren utrotar Davids fiendar, hvar och en utaf landet, så tag icke du dina barmhertighet bort ifrå mitt hus till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Alltså gjorde Jonathan ett förbund med Davids hus, och sade: Herren kräfve det utaf Davids fiendars händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Och Jonathan sade ytterligare, och svor David, så kär hade han honom; ty han hade honom så kär, som sina själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Och Jonathan sade till honom: I morgon är nymånad, så varder väl frågadt efter dig; ty man varder dig saknandes, der du plägar sitta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'På tredje dagen kom med hast neder, och gack uti något rum, der du kan gömma dig på söknedagenom, och sätt dig vid den stenen Asel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Så vill jag skjuta tre pilar utmed honom, såsom jag sköte till ett mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Och si, jag vill sända drängen: Gack och tag igen pilen; om jag säger till drängen: Si, pilarna ligga hitut bak dig, tag upp dem; så kom, ty det är frid, och är ingen fara, så visserliga som Herren lefver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Men om jag säger till drängen: Si, pilarna ligga bort bätter fram för dig; så gack dina färde, ty Herren hafver låtit dig gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Och hvad du och jag med hvarannan talat hafve, Herren vare emellan mig och dig i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Så gömde David sig i markene; och då nymånaden kom, satte Konungen sig till bords till att äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Då nu Konungen hade satt sig i sitt rum, såsom han tillförene var van, utmed väggene, stod Jonathan upp; och Abner satte sig vid Sauls sido; och man saknade David i hans rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Och Saul talade den dagen intet; ty han tänkte, honom är något vederkommet, att han icke är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'På den andra nymånadsdagenom, då man saknade David i hans rum, sade Saul till sin son Jonathan: Hvi är icke Isai son kommen till bords, hvarken i går eller idag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathan svarade Saul: Han bad mig, att han skulle gå till BethLehem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Och sade: Låt mig gå, förty vår slägt skall offra i stadenom, och min broder hafver sjelf budit mig; hafver jag nu funnit nåd för din ögon, så vill jag dit, och se mina bröder; derföre är han icke kommen till Konungens bord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Då vardt Saul vred på Jonathan, och sade: Du skalk och bofve, jag vet väl, att du hafver utvalt Isai son, dig och dine slemma moder till skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Ty så länge Isai son lefver på jordene, varder hvarken du eller ditt rike beståndandes. Så sänd nu, och låt hemta honom hit till mig; ty han måste dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonathan svarade sinom fader Saul, och sade till honom: Hvi skall han dö? Hvad hafver han gjort?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Då sköt Saul spjutet efter honom, att han måtte skjutit honom igenom. Då märkte Jonathan, att alldeles var beslutet med hans fader, att han ville dräpa David;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Och stod upp ifrå bordet ganska vred, och åt på den samma andra nymånadsdagenom intet bröd; ty han vardt bedröfvad om David, efter hans fader hade så beskämt honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Om morgonen gick Jonathan ut i markena, såsom han hade öfverens varit med David; och en liten dräng med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Och han sade till drängen: Löp och hemta mig pilarna upp igen, som jag skjuter; då drängen lopp, sköt han en pil öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Och då drängen kom på det rummet, dit Jonathan hade skjutit pilarna, ropade Jonathan efter honom, och sade: Pilen ligger bätter fram för dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Och ropade än en tid efter honom: Skynda dig full snart, statt icke stilla. Då hemtade drängen Jonathan pilarna upp, och bar dem till sin herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Och drängen visste intet hvad på färde var; allenast Jonathan och David visste det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Då fick Jonathan sinom dräng sin vapen, och sade till honom: Gack, och bär in i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Då drängen var ingången, stod David upp af rummet på södra sidone, och föll på sitt ansigte till jordena, och tillbad tre resor; och de kysste hvarannan, och greto tillhopa, ju David aldramest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Och Jonathan sade till David: Gack med frid, hvad vi både svorit hafve i Herrans Namn och sagt: Herren vare emellan mig och dig, emellan min säd och din säd, till evig tid. Och han stod upp, och gick sin väg; men Jonathan gick i staden igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Och David kom till Nobe till Presten Ahimelech, och Ahimelech vardt häpen vid han gick emot David, och sade till honom: Hvi kommer du så allena, och ingen man med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David sade till Presten Ahimelech: Konungen hafver befallt mig ett ärende, och sade till mig: Låt ingen veta hvarefter jag hafver sändt dig, och hvad jag hafver befallt dig, så hafver jag sagt mina tjenare före der och der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Om du nu hafver något under dina händer, till en fem bröd, få mig det i mina hand; eller hvad du finner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Presten svarade David, och sade: dag hafver ingen menlig bröd under mine hand; utan helig bröd, om eljest tjenarena hafva hållit sig ifrå qvinnor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'David svarade Prestenom, och sade till honom: Qvinnorna hafva varit oss ifråstängda i tre dagar, då jag for åstad; och tjenarens tyg voro helig; men är denna vägen ohelig, så skall han i dag helgad varda genom tygen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Så gaf Presten honom af det helga, efter det var intet annat bröd, utan skådobröden, dem man upptog för Herranom, på det man skulle lägga fram annor färsk bröd, på den dagen då han dem borttog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Men der var den dagen en man inne besluten för Herranom, utaf Sauls tjenare, benämnd Doeg, en Edomeer, den mägtigaste ibland Sauls herdar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Och David sade till Ahimelech: Är icke här under dina hand ett spjut eller svärd? Jag hafver icke tagit mitt svärd eller vapen med mig; förty Konungens ärende var hastigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Presten sade: Den Philisteens svärd, Goliaths, den du slogst i ekdalen, det är här svept uti en mantel bak lifkjortelen; vill du det, så tag det; ty här är intet annat, än det. David sade: Dess like är icke, få mig det hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Och David stod upp, och flydde för Saul, och kom till Achis, Konungen i Gath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Men Achis tjenare sade till honom: Denne är David, landsens Konung, om hvilken de söngo i dansen, och sade: Saul slog tusende, men David tiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Och David lade dessa orden på hjertat, och fruktade sig storliga för Achis, Konungenom i Gath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Och han förvandlade sina åthäfvor för dem, och föll neder i deras händer, och stötte sig emot dörrene i portenom, och hans spott flöt honom ut på skägget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Då sade Achis till sina tjenare: Si, I sen, att mannen är ursinnig; hvi hafven I haft honom till mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Hafver jag icke nog ursinniga, att I skullen hafva denna in till mig, att han skulle rasa för mig? Skulle han komma i mitt hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David gick dädan, och flydde bort uti den kulon Adullam. Då hans bröder det hörde, och hela hans faders hus, kommo de ditned till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Och till honom församlade sig allehanda män, som i nöd, i gäld och bedröfvadt hjerta voro, och han vardt deras höfvitsman, så att när honom voro vid fyrahundrade män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Och David gick dädan till Mizpa uti de Moabiters land, och sade till de Moabiters Konung: Låt min fader och min moder gå ut och in med eder, tilldess jag får se hvad Gud vill göra med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Och han lät dem in för de Moabiters Konung, att de voro när honom så länge som David var på borgene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Men den Propheten Gad sade till David: Blif icke på borgene, utan gack bort i Juda land. Så gick David åstad, och kom uti den skogen Hareth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Och det kom för Saul, att David och de män, som när honom voro, voro sedde. Som nu Saul bodde i Gibea i en lund i Rama, hade han sitt spjut i handene, och alla hans tjenare stodo bredevid honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Då sade Saul till sina tjenare, som stodo bredevid honom: Hörer, I Jemini barn, månn ock Isai son skola gifva eder allom åkrar och vingårdar, och göra eder alla till öfverstar öfver tusende, och öfver hundrade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Att I alle hafven förbundit eder emot mig, och ingen är, som det för min öron uppenbarar, efter min son hafver ock gjort ett förbund med Isai son? Är ingen ibland eder, hvilkom det gör ondt för mina skull, och uppenbarar det för min öron? Ty min son hafver uppväckt min tjenare emot mig; att han skall gå mig efter, såsom för ögon är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Så svarade Doeg den Edomeen, som stod ibland Sauls tjenare, och sade: Jag såg Isai son, att han kom till Nobe till Ahimelech, Ahitobs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Han frågade om honom Herran, och gaf honom spisning och Goliaths den Philisteens svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Då sände Konungen åstad, och lät kalla Presten Ahimelech, Ahitobs son, och hela hans faders hus, Presterna som voro i Nobe; och de kommo alle till Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Och Saul sade: Hör du, Ahitobs son. Han sade: Här är jag, min herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Och Saul sade till honom: Hvi hafven I gjort ett förbund emot mig, du och Isai son, så att du hafver gifvit honom bröd och svärd, och frågat Gud för honom, på det du skulle uppväcka honom, till att han skulle gå mig efter, såsom för ögon är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelech svarade Konungenom, och sade: Och ho är ibland alla dina tjenare sådana som David, trogen och Konungens måg, och går i dine lydno, och är mycket afhållen i ditt hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Hafver jag nu först i dag begynt fråga Gud för honom? Det vare långt ifrå mig; Konungen lägge sin tjenare icke sådant till i allo mins faders huse; förty din tjenare hafver intet vetat af allt detta, hvarken litet eller stort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Men Konungen sade: Ahimelech, du måste döden dö, du och hela dins faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Och Konungen sade till sina drabanter, som när honom stodo: Vänder eder, och dräper Herrans Prester; förty deras hand är ock med David; och då de visste att han flydde, underviste de mig det icke. Men Konungens tjenare ville icke komma deras händer vid Herrans Prester, och slå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Då sade Konungen till Doeg: Vänd du dig, och slå Presterna. Doeg den Edomeen vände sig, och slog Presterna, så att den dagen blefvo döde fem och åttatio män, som drogo linnan lifkjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Och Presternas stad Nobe slog han med svärdsegg, både män och qvinnor, barn och dem som didde, fä och åsnar, och får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Men en Ahimelechs son, Ahitobs sons, benämnd AbJathar, slapp undan, och flydde bort till David;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Och sade honom, att Saul hade dräpit Herrans Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Men David sade till AbJathar: Jag visste väl den dagen, då den Edomeen Doeg der var, att han skulle säga det Saul. Jag är skyldig för alla dins faders hus själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Blif när mig, och frukta dig intet. Den som står efter mitt lif, han skall ock stå efter ditt lif, och du skall med mig blifva förvarad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Och David vardt bådadt: Si, de Philisteer strida emot Kegila, och röfva ladorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Då frågade David Herran, och sade: Skall jag gå bort och slå dessa Philisteer? Och Herren sade till David: Gack åstad, du skall slå de Philisteer, och undsätta Kegila.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Men de män när David sade till honom: Si, vi hafve fruktan här i Juda; och vilje ännu gå bort till Kegila, till de Philisteers här?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Då frågade åter David Herran. Och Herren svarade honom, och sade: Upp, drag ned till Kegila; ty jag vill gifva de Philisteer i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Så drog David med sina män till Kegila, och stridde emot de Philisteer, och dref dem deras boskap bort, och slog dem en stor slagtning af. Alltså undsatte David dem i Kegila;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Ty då AbJathar, Ahimelechs son, flydde till David till Kegila, bar han lifkjortelen ditned med sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Då vardt Saul sagdt, att David var kommen till Kegila; och han sade: Gud hafver gifvit honom i mina händer, så att han är innelyckt, och är kommen i en stad, som är förvarad med portar och bommar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Och Saul lät kalla allt folket till strid, ditneder till Kegila, och skulle belägga David och hans män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Då David förmärkte, att Saul hade ondt i sinnet om honom, sade han till Presten AbJathar: Tag hit lifkjortelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Och David sade: Herre Israels Gud, din tjenare hafver hört, att Saul hafver i sinnet, att han skall komma till Kegila, till att förderfva staden för mina skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Månn borgarena i Kegila öfverantvarda mig i hans händer? Och månn Saul komma hitneder, såsom din tjenare hört hafver? Det låt din tjenare få veta, Herre Israels Gud. Och Herren sade: Han kommer hitneder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David sade: Månn borgarena i Kegila öfverantvarda mig och mina män i Sauls händer? Herren sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Då stod David upp med sina män, som voro vid sexhundrad, och drogo ut af Kegila, och vandrade hvart de kunde. Då nu Saul vardt sagdt, att David var utflydder af Kegila, lät han sitt uttåg bestå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Och David blef i öknene på borgene, och blef på berget i den öknene Siph; men Saul sökte honom så länge han lefde; men Gud gaf honom icke i hans händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Och David såg, att Saul utdragen var att söka efter hans lif; men David blef uti den öknene Siph i hedene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Då stod Jonathan upp, Sauls son, och gick bort till David ut i hedena, och styrkte hans hand i Gudi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Och sade till honom: Frukta dig intet; mins faders Sauls hand finner dig intet; och du varder Konung öfver Israel, så vill jag vara dig närmast; och detta vet min fader väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Och de gjorde både ett förbund tillhopa för Herranom. Och David blef i hedene; men Jonathan drog hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Men de Siphiter foro upp till Saul i Gibea, och sade: Är icke David gömder när oss på borgene i hedene, på den högen Hachila, som ligger på högra handene vid öknen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Så kom nu neder, Konung, efter allt dins hjertans begär, så vilje vi öfverantvarda honom i Konungens händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Då sade Saul: Välsignade varen I Herranom, att I hafven förbarmat eder öfver mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Så går nu bort, och varder dess ännu vissare, att I mågen få veta och se, på hvad rum hans fötter varit hafva, och tio honom der sett hafver; ty mig är sagdt, att han är listig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Beser och bespejer all rum der han gömmer sig; och kommer igen till mig, när ären visse vordne, så vill jag fara med eder. Är han i landena, så skall jag söka upp honom i all tusend i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Då stodo de upp, och gingo till Siph fram för Saul; men David och hans män voro i den öknene Maon, på den slättmarkene, på högra sidone vid öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Då nu Saul drog dit med sina män till att söka, vardt David förvarad, och drog ned uti en bergklippo i öknene Maon. Då Saul det hörde, jagade han efter David i den öknene Maon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Och Saul med sina män gick på ena sidon om berget, och David med sina män på den andra sidon om berget. Då nu David skyndade sig att undkomma för Saul, då kringhvärfde Saul med sina män David och hans män, att de måtte få dem fatt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Men ett bådskap kom till Saul, och sade: Skynda dig, och kom; förty de Philisteer äro infallne i landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Då vände Saul om af det sökandet efter David, och drog bort emot de Philisteer. Deraf kallar man det rummet SelaMahelkoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Och David drog med dädan, och blef på borgene i EnGedi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Då nu Saul igenkom ifrå de Philisteer, vardt honom sagdt: Si, David är i den öknene EnGedi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Och Saul tog tretusend unga män utu hela Israel, och drog åstad till att söka David med hans män, på de stengetters klippor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Och då han kom till de fårahyddor vid vägen, var der en kula; och Saul gick derin till att betäcka sina fötter; men David och hans män såto inne i kulone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Då sade Davids män till honom: Si, detta är den dagen, om hvilken Herren din Gud dig sagt hafver: Si, jag skall gifva din fienda i dina händer, att du gör med honom såsom dig täckes. Och David stod upp, och skar sakta bort ena flik af Sauls kjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Men sedan slog honom hans hjerta, att han hade skorit den Sauls flik bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Och sade till sina män: Det låte Herren vara långt ifrå mig, att jag det göra skulle, och komma mina hand vid min herra, Herrans smorda; ty han är Herrans smorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Och David stillte sina män med ordom, och lät dem icke öfverfalla Saul. Och Saul kom upp utu kulone, och gick ut på vägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Stod ock David sedan upp, och gick utu kulone, och ropade efter Saul, och sade: Min herre Konung. Saul såg tillbaka efter sig; och David böjde sitt ansigte ned till jordena, och tillbad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Och sade till Saul: Hvi hörer du de menniskors ord, som säga: David söker efter ditt argesta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Si, i dag se din ögon, att Herren hafver i denna dag gifvit dig i mina hand i kulone; och det vardt sagdt, att jag skulle dräpit dig; men dig vardt skonadt; ty jag sade: Jag vill icke komma mina hand vid min herra; ty han är Herrans smorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Min fader, se dock fliken af din kjortel i mine hand, att jag icke ville dräpa dig då jag bortskar en flik af din kjortel; känn och se, att intet ondt är i mine hand, eller någor öfverträdelse. Jag hafver ock intet syndat emot dig, och du går efter mina själ, att du må taga henne bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Herren skall vara domare emellan mig och dig, och Herren skall hämna mig på dig; men min hand skall icke vara öfver dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Såsom man säger af ett gammalt ordspråk: Af ogudaktigom kommer odygd; men min hand skall icke vara öfver dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Hvem förföljer du, Israels Konung? Hvem jagar du efter? En dödan hund, ena loppo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Herren vare domare, och döme emellan mig och dig, och se dertill, och rätte min sak ut, och frie mig ifrå dine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Som nu David hade dessa orden uttalat, sade Saul: Är det icke din röst, min son David? Och Saul upphof sina röst och gret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Och sade till David: Du äst rättfärdigare än jag; du hafver bevist mig godt; men jag hafver bevist dig ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Och du hafver i denna dag gifvit mig tillkänna, huru du hafver gjort väl emot mig; att Herren hade beslutit mig i dina händer, och du hafver dock icke dräpit mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Huru skulle någor finna sin fienda, och låta honom sedan gå en god väg? Herren vedergälle dig det goda, som du i denna dag med mig gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nu si, jag vet, att du varder Konung, och Israels Konungsrike står i dine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Så svär mig nu vid Herran, att du icke utrotar min säd efter mig, och icke utskrapar mitt namn utu mins faders hus. Och David svor Saul; och så drog Saul hem; men David och hans män drogo upp på borgena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Och Samuel blef död; och hela Israel församlade sig, begreto honom, och begrofvo honom i hans hus i Rama. Men David stod upp, och drog ned i den öknena Paran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Och en man var i Maon, och hans väsende var i Carmel, och den mannen var ganska mägtig, och hade tretusende får och tusende getter. Och det begaf sig, att han klippte sin får i Carmel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Och han het Nabal; och hans hustru het Abigail, och var en förnuftig qvinna, och dägelig under ansigtet; men mannen var hård och arg i sina gerningar, och var en af Caleb.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Då nu David fick höra i öknene, att Nabal klippte sin får,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Sände han ut tio unga män, och sade till dem: Går upp till Carmel, och då I kommen till Nabal, så helser honom, på mina vägnar, vänliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Och önsker honom lycko, och säger: Frid vare med dig, och med ditt hus, och med allt det du hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Jag hafver hört, att du hafver fåraklippare; si, dina herdar, som du hafver, hafva varit när oss; vi hafve aldrig talat dem illa till; och dem hafver intet fattats på talet, så länge de hafva varit i Carmel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Fråga dina dränger derom, de skola säga dig det. Så låt nu dessa unga män finna nåd för din ögon; ty vi äre komne på en god dag. Gif dina tjenare, och dinom son David, hvad din hand finner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Då de Davids unga män kommo dit, och hade på Davids vägnar talat all dessa orden med Nabal, höllo de upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Men Nabal svarade Davids tjenare, och sade: Ho är den David? Och ho är den Isai son? Det äro nu månge de tjenare, som gifva sig ifrå sina herrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Skulle jag taga mitt bröd, vatten, och kött som jag för mina klippare slagtat hafver, och gifva de folke, som jag intet vet hvadan de äro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Då vände de Davids unga män om igen på deras väg; och när de kommo till David, sade de honom allt detta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Då sade David till sina män: Hvar och en binde sitt svärd vid sig. Och hvar och en af dem band sitt svärd vid sig; och David band ock desslikes sitt svärd vid sig; och drogo med honom ned vid fyrahundrad män; men tuhundrad blefvo qvar när deras tyg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Men en af drängerna gaf Abigail, Nabals hustru, tillkänna, och sade: Si David hafver sändt båd utur öknene, till att helsa vår herra; och han snubbade dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Och de män hafva dock varit oss ganska nyttige, och intet talat oss illa till, och oss hafver intet fattats på talet, så länge vi hafve vistats när dem, medan vi i markene vorom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Utan de hafva varit våra murar dag och natt, så länge vi vaktade fåren när dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Så märk nu och se, hvad du göra vill; ty förvisso är ett ondt för handene öfver vår herra, och öfver hela hans hus; och han är en Belials man, hvilkom ingen något säga djerfves.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Då hastade sig Abigail, och tog tuhundrad bröd, och två läglar, vin, och fem kokad får, och fem skäppor mjöl, och hundrad stycke russin, och tuhundrad stycke fikon, och lade på åsnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Och sade till sina dränger: Går för mig, jag vill komma efter. Och hon sade sinom man Nabal här intet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Och som hon red på åsnanom, och kom neder i bergsskygdena, si, då kom David och hans män nederdragandes emot henne, så att hon mötte dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Och David hade sagt: Jag hafver förgäfves förvarat allt det denne hade i öknene, så att der hafver intet fattats af allt det han hade; och han betalar mig godt med ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Gud göre detta, och än mer, Davids fiendar, om jag låter honom blifva qvar, intill morgon ljust varder, en som på väggena pissar, utaf allt det han hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Då nu Abigail såg David, steg hon hastigt af åsnanom, och föll för David på sitt ansigte, och tillbad honom på jordene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Och föll till hans fötter, och sade: Ack! min Herre, min vare denna missgerning, och låt dina tjenarinno tala för din ögon; och hör dina tjenarinnos ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Min herre sätte icke sitt hjerta emot denna Nabal, den Belials mannen; ty han är en galen man, såsom hans namn är, och galenskap är med honom; men jag din tjenarinna hafver icke sett mins herras unga män, som du utsände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Men nu, min Herre, så visst som Herren lefver, och så visst som din själ lefver, Herren hafver förtagit dig, att du icke kom i blod, och hafver friat dig dina hand; men nu vare dine fiender såsom Nabal, och de som vilja minom herra ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Här är välsignelsen, som din tjenarinna minom herra fört hafver; gif henne de unga män, som med min herra vandra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Förlåt dine tjenarinno den öfverträdelsen; ty Herren skall göra minom herra ett tryggt hus; ty du förer Herrans krig, och intet ondt skall när dig funnet varda i alla dina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Och om någor menniska hafver sig upp till att förfölja dig, och står efter dina själ, så skall mins herras själ vara inbunden uti de lefvandes knippe, när Herranom dinom Gud; men dina fiendars själ skall varda bortslungad med slungo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'När nu Herren minom herra allt detta goda görandes varder, som han dig sagt hafver, och budit dig, att du skall vara en höfvitsman öfver Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Så varder detta icke görandes mins herras hjerta någon ångest eller nyck, att du hafver blod utgjutit utan orsak, och hämnat dig sjelfvan; så skall Herren göra minom herra godt, och du varder tänkandes på dina tjenarinno.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Då sade David till Abigail: Lofvad vare Herren Israels Gud, som dig i dag hafver emot mig sändt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Och lofvade vare dina åthäfvor; och lofvad vare du, som i dag hafver förtagit mig, att jag icke är kommen i blod, och hämnat mig med egna hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Sannerliga, så visst som Herren Israels Gud lefver, den mig förtagit hafver, att jag icke gjorde dig ondt, hade du icke snarliga kommit emot mig, så hade Nabal, intill morgon ljust varder, icke qvar blifvit en, som på väggena pissar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Alltså tog då David af hennes hand det hon honom fört hade, och sade till henne: Far med frid upp till ditt hus; si, jag hafver hört dina röst, och täckeliga tagit din person.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Då Abigail kom till Nabal, si, då hade han tillredt ena måltid i sitt hus, såsom en Konungs måltid, och hans hjerta var gladt i honom; ty han var mycket drucken. Men hon sade honom intet, hvarken litet eller stort, intill morgonen ljust vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Då dager vardt, när vinet var gånget af Nabal, sade hans hustru honom detta. Då vardt hans hjerta dödt i honom, så att han vardt såsom en sten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Och efter tio dagar slog Herren honom, så att han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Då David hörde att Nabal var död, sade han: Lofvad vare Herren, som hafver hämnat min försmädelse på Nabal, och hafver förvarat sin tjenare för det ondt var; och Herren hafver Nabals ondsko vedergullit in på hans hufvud. Och David sände bort, och lät tala med Abigail, att han måtte taga henne till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Och då Davids tjenare kommo till Abigail i Carmel, talade de till henne, och sade: David hafver sändt oss till dig, på det han må få dig till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Hon stod upp, och tillbad på sitt ansigte till jordena, och sade: Si, här är din tjenarinna, att hon må tjena mins herras tjenare, och två deras fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Och Abigail hastade sig, och gjorde redo, och red på en åsna, och fem tjenstepigor, som under henne voro; och följde Davids bådskap, och vardt hans hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Desslikes tog David Ahinoam af Jisreel; och voro båda hans hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Men Saul gaf sina dotter Michal, Davids hustru, Phalti, Lais sone, af Gallim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Och de af Siph kommo till Saul i Gibea, och sade: Är icke David fördold på berget Hachila, inför öknene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Då stod Saul upp, och drog ned till den öknen Siph; och med honom tretusend unge män af Israel; på det han skulle uppsöka David i öknene Siph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Och lägrade sig på det berget Hachila, som ligger inför öknene vid vägen; men David blef i öknene. Och då han såg, att Saul kom efter honom i öknena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Sände han spejare ut, och förfor att Saul visserliga kommen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Och David stod upp, och kom till det rummet, der Saul höll sitt lägre; och han såg rummet, der Saul låg med sin härhöfvitsman, Abner, Ners son; ty Saul låg i vagnborgene, och härfolket omkring honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Då svarade David, och sade till Ahimelech den Hetheen, och till Abisai, ZeruJa son, Joabs broder: Ho vill med mig neder till Saul i lägret? Abisai sade: Jag vill ned med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Så kom David och Abisai till folket om nattena, och si, Saul låg och sof i vagnborgene, och hans spjut stött i jordena, vid hans hufvud; men Abner och folket låg omkring honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Då sade Abisai till David: Gud hafver i denna dag beslutit din fienda i dina hand; så vill jag nu en gång med spjutet stinga honom igenom i jordena, så att han skall icke mer behöfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Men David sade till Abisai: Förderfva honom intet; ty ho vill komma sina hand vid Herrans smorda, och blifva oskyldig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Ytterligare sade David: Så visst som Herren lefver, om Herren icke slår honom, eller hans tid kommer, att han dör, eller han drager i en strid, och så blifver borta,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Så låte Herren det vara långt ifrå mig, att jag skall komma mina hand vid Herrans smorda; så tag nu spjutet vid hans hufvud, och vattubägaren, och låt oss gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Så tog David spjutet och vattubägaren vid Sauls hufvud, och gingo sina färde; och ingen var, som det såg eller märkte, eller vaknade, utan de sofvo alle; ty en tung sömn var fallen på dem af Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Då nu David var kommen öfver på hinsidon, gick han upp på bergskullan långt ifrå, så att der var stort rum emellan dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Och ropade till folket och till Abner, Ners son, och sade: Hörer du icke, Abner? Och Abner svarade, och sade: Ho äst du, att du så ropar Konungen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Och David sade till Abner: Äst du icke en man? Och ho är din like i Israel? Hvi hafver du då icke bevarat din herra Konungen? Ty en af folket är der ingången, till att slå din herra Konungen ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Det är icke redeligit, som du gjort hafver; så visst som Herren lefver, I ären dödsens barn, att I edar herra, Herrans smorda, icke bevarat hafven; nu se, här är Konungens spjut och vattubägaren, som stodo vid hans hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Då kände Saul Davids röst, och sade: Är det icke din röst, min son David? David sade: Det är min röst, min herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Och sade ytterligare: Hvi förföljer min herre så sin tjenare? Hvad hafver jag gjort? Och hvad ondt är i mine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Så höre dock nu min herre Konungen sin tjenares ord: Om Herren uppretar dig emot mig, så låte man ett spisoffer lukta; men om menniskors barn göra det, så vare de förbannade för Herranom, att de på denna dag hafva fördrifvit mig, att jag icke må blifva i Herrans arfvedel, och säga: Gack bort, och tjena andra gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Så förfalle nu icke mitt blod på jordena för Herrans ansigte; ty Israels Konung är utdragen till att söka ena loppo, såsom man jagar ett rapphöns på bergen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Och Saul sade: Jag hafver syndat. Kom igen, min son David, jag vill intet ondt mer göra dig, derföre att min själ hafver i denna dag dyr varit för din ögon; si, jag hafver gjorts dårliga och ganska ovisliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David svarade, och sade: Si, här är Konungens spjut; en af de unga män gånge hitupp, och tage det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Herren varder väl hvarjom och enom vedergällandes efter hans rättfärdighet och tro; ty Herren hade i dag gifvit dig i mina hand; men jag ville icke komma mina hand vid Herrans smorda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Och såsom din själ hafver i denna dagen för min ögon mycket aktad varit, så varde ock min själ mycket aktad för Herrans ögon, och hjelpe mig utur all bedröfvelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sade till David: Välsignad vare du, min son David; du skall görat, och gåt igenom. Så gick David sin väg; och Saul vände om hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Så tänkte David i sitt hjerta: Jag faller dock en dag Saul i händer; det är mig bättre, att jag rymmer undan in uti de Philisteers land; på det Saul må vända igen att ytterligare söka efter mig i alla Israels gränsor; så må jag då komma ifrå hans händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Och stod upp, och gick åstad med de sexhundrad män, som med honom voro, till Achis, Maochs son, Konungen i Gath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Så blef David när Achis i Gath, med sina män, hvar med sitt hus; David desslikes med sina två hustrur, Ahinoam den Jisreelitiskon, och Abigail, Nabals hustru, den Carmelitiskon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Då Saul vardt sagdt, att David var flydd till Gath, sökte han intet mera efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Och David sade till Achis: Hafver jag funnit nåd för din ögon, så låt gifva mig ett rum uti en af städerna på landena, att jag må bo derinne; hvi skulle din tjenare bo uti Konungsstadenom när dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Då gaf honom Achis på den dagen Ziklag. Deraf är Ziklag Juda Konungars, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Tiden, som David bodde uti de Philisteers land, var ett år och fyra månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Och David med sina män drog upp, och föll in uti de Gessuriters och de Girsiters och de Amalekiters land; ty desse bodde i landena af ålder, der man kommer till Zur, allt intill Egypti land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Och då han slog landet, lät han hvarken man eller qvinno lefva, och tog får, fä, åsnar, camelar och kläder, och vände om, och kom till Achis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'När nu Achis sade: Hafven I ock i dag någorstäds infallit? Då sade David: Söderut i Juda, och söderut till de Jerahmeehter, och söderut till de Keniter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Men David lät hvarken man eller qvinno lefvande komma till Gath, och tänkte: De måga säga på oss, och sqvallra. Så gjorde David, och det var hans sedvänja, så länge han bodde uti de Philisteers land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Derföre trodde Achis David, och tänkte: Han hafver gjort sig illa luktandes för sitt folk Israel; ty blifver han väl min tjenare till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Och, det begaf sig på den tiden, att de Philisteer församlade sin här, till att draga ut i strid emot Israel. Och Achis sade till David: Du skall veta, att du och dine män skolen draga ut med mig i hären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David sade till Achis: Nu väl, du skall se hvad din tjenare göra skall. Achis sade till David: Derföre skall jag sätta dig till mins hufvuds väktare, i mina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Som nu de Philisteer församlade sig, och kommo och lägrade sig i Sunem, församlade ock Saul hela Israel, och lagrade sig i Gilboa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Då Saul såg de Philisteers här, fruktade han sig, och hans hjerta var mycket försoffadt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Och han frågade Herran, och Herren svarade honom intet, hvarken i drömmar eller genom ljus, eller genom Propheter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Då sade Saul till sina tjenare: Söker mig ena qvinno, som en spådomsanda hafver, att jag må gå till henne, och fråga henne. Hans tjenare sade till honom: Si, i EnDor är en qvinna, som hafver en spådomsanda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Så var nu Samuel död, och hele Israel hade begråtit honom, och begrafvit honom i hans stad Rama. Så hade Saul bortdrifvit utu landet spåmän och tecknatydare. Och Saul omskifte sin kläder, och tog annor uppå, och gick dit, och två män med honom, och kommo om nattena till qvinnona, och sade: Kära, spå mig genom spådomsanda, och res mig upp den jag säger dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Qvinnan sade till honom: Si, du vetst väl hvad Saul gjort hafver, huru han hafver förödt de spåmän och tecknatydare utu landet; hvi vill du då komma min själ i nätet, att jag skulle blifva dödad?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Då svor Saul henne vid Herran, och sade: Så visst som Herren lefver, skall detta icke varda dig räknadt till missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Då sade qvinnan: Hvem skall jag uppresa dig? Han sade: Res mig Samuel upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Då nu qvinnan såg Samuel, ropade hon högt, och sade till Saul: Hvi hafver du bedragit mig? Du äst Saul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Och Konungen sade till henne: Frukta dig intet; hvad ser du? Qvinnan sade till Saul: Jag ser gudar stiga upp af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Han sade: Huru är hans skapnad? Hon sade: En gammal man kommer upp, och är klädd i en silkeskjortel. Så förnam Saul, att det var Samuel, och böjde sitt ansigte ned på jordena, och tillbad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Och Samuel sade till Saul: Hvi hafver du gjort mig omak, att du hafver låtit mig uppresas? Saul sade: Jag är i stora nöd; de Philisteer strida emot mig, och Gud är viken ifrå mig, och svarar mig intet, hvarken genom Propheter, eller genom drömmar; derföre hafver jag låtit kalla dig, att du skall undervisa mig hvad jag göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel sade: Hvad vill du fråga mig, efter Herren är ifrå dig viken, och är din ovän vorden?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herren varder dig görandes, såsom han genom mig talat hafver; och Herren skall rifva riket utu dine hand, och gifva det David dinom nästa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Derföre, att du Herrans röst icke lydt hafver; icke heller fullföljt hans vredes grymhet emot Amalek; derföre hafver nu Herren detta gjort dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Dertill skall Herren ock gifva Israel med dig uti de Philisteers händer. I morgon skall du och dine söner vara när mig; och Herren skall gifva Israels här uti de Philisteers händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Då föll Saul hasteliga till jordena; ty han kunde icke stå, och vardt svårliga förfärad för Samuels ord, så att ingen magt var mer i honom; ty han hade intet bröd ätit i den hela dagen, och den hela nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Och qvinnan gick in till Saul, och såg att han var mycket förfärad, och sade till honom: Si, din tjenarinna hafver lydt dine röst: och jag hafver satt mina själ i mina hand, så att jag lydde din ord, som du talade till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Så hör ock nu du dina tjenarinnos röst: Jag vill sätta för dig en beta bröd, att du äter, och kommer till magt igen, och går dina färde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Han nekade, och sade: Jag vill intet äta. Då nödgade honom hans tjenare och qvinnan, så att han lydde deras röst. Och han stod upp af jordene, och satte sig på sängena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Och qvinnan hade en göddan kalf i huset; då hastade hon sig, och slagtade honom, och tog mjöl, och blandade, och bakade det osyradt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Och bar fram för Saul, och för hans tjenare; och då de hade ätit, stodo de upp, och gingo alla den nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Men de Philisteer samlade alla sina härar i Aphek, och Israel lägrade sig i Ajin i Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Och de Philisteers Förstar gingo med hundrad, och med tusend; men David gick efterst med sina män när Achis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Då sade de Philisteers Förstar: Hvad skola denne Ebreer? Achis sade till dem: Är icke det David, Sauls tjenare, Israels Konungs, den nu när mig varit hafver år och dag; och jag hafver intet funnit med honom, ifrå den tiden han föll intill mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Men de Philisteers Förstar vordo vrede på honom, och sade till honom: Låt den mannen vända om, och blifva i sitt rum, der du hafver satt honom, att han icke drager neder med oss i stridena, och varder vår fiende i stridene; ty i hvad kunde han bättre blidka sin herra, än med dessa männernas hufvud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Är icke han den David, om hvilken de söngo i dansen: Saul slog tusende, men David slog tiotusend?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Då kallade Achis David, och sade till honom: Så visst som Herren lefver, jag håller dig för en redelig man; och din utgång och ingång, med mig i härenom, behagar mig väl, och hafver intet argt sport af dig, ifrå den tiden, du kom till mig, intill nu; men du behagar icke Förstomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Så vänd nu om, och gack med frid, på det du icke skall förtörna de Philisteers Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David sade: Hvad hafver jag gjort? Och hvad hafver du sport af din tjenare, ifrå den tid jag hafver varit när dig, intill nu, att jag icke skall komma och strida emot mins herras Konungens fiendar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Achis svarade, och sade till David: Jag vet väl, att du äst täck för min ögon, såsom en Guds Ängel; men de Philisteers Förstar hafva sagt: Låt honom icke draga upp med oss i stridena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Så var nu i morgon bittida uppe, och dins herras tjenare, som med dig komne äro; och när I ären i morgon bittida uppståndne, och ljust är, så går edar väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Så var då David och hans män bittida uppe, att de skulle om morgonen färdas, och komma uti de Philisteers land igen; men de Philisteer drogo upp till Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Då nu David på tredje dagen kom till Ziklag med sina män, voro de Amalekiter der infallne söderut, och till Ziklag; och hade slagit Ziklag, och uppbränt med eld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Och hade bortfört qvinnorna dädan, både små och stora; men de hade ingen slagit ihjäl, utan drifvit dem bort och voro sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Då nu David med sina män kom till staden, och såg att han var uppbränd med eld, och deras hustrur, söner och döttrar fångne,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Hof David och folket, som med honom var, deras röst upp, och greto, tilldess de icke mer gråta kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Ty Davids två hustrur voro ock fångna, Ahinoam den Jisreelitiskan, och Abigail, Nabals hustru, den Carmelitens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Och David var storliga bedröfvad; ty folket ville stena honom; ty hela folkens själ var bedröfvad, hvar och en öfver sina söner och döttrar. Men David stärkte sig i Herranom sinom Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Och sade till Presten AbJathar, Ahimelechs son: Bär mig fram lifkjortelen. Och då AbJathar hade burit fram lifkjorteln,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Frågade David Herran, och sade: Skall jag jaga efter krigsfolket? och skall jag få dem fatt? Han sade: Jaga efter dem; du skall få dem fatt, och undsätta rofvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Så drog David åstad, och de sexhundrad män, som när honom voro. Och då de kommo till den bäcken Besor, blefvo någre ståndande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Men David och fyrahundrad män jagade efter; och de tuhundrade män, som ståndande blefvo, hade försummat sig fara öfver bäcken Besor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Och de funno en Egyptisk man på markene, den förde de till David, och gåfvo honom bröd, att han åt, och gåfvo honom vatten dricka;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Och gåfvo honom ett stycke fikon, och tu stycke russin; och då han ätit hade, kom hans anda åter till honom; ty han hade i tre dagar och tre nätter intet bröd ätit, och intet vatten druckit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David sade till honom: Hvem hörer du till? Och hvadan äst du? Han sade: Jag är en Egyptisk dräng, en Amalekiters tjenare, och min herre hafver öfvergifvit mig; ty jag vardt krank för tre dagar sedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Vi vorom här infallne söder på Crethi, och uppå Juda, och söder på Caleb, och hafve bränt upp Ziklag med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David sade till honom: Vill du föra mig ned till det krigsfolket? Han sade: Svär mig vid Gud, att du icke slår mig ihjäl eller antvardar mig i mins herras hand, så vill jag föra dig ned till det krigsfolket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Och han förde dem ned; och si, de hade förstrött sig öfver hela jordena, åto och drucko, och fröjdade sig, för det stora bytets skull, som de tagit hade utu de Philisteers land, och utur Juda land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Och David slog dem, ifrå morgonen allt intill aftonen, emot den andra dagen, så att ingen af dem undslapp, förutan fyrahundrade ynglingar, de satte sig uppå cameler, och flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Så undsatte då David allt det de Amalekiter tagit hade, och sina två hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Och fattades ingen, hvarken liten eller stor, hvarken söner eller döttrar, eller af rofvet, eller hvad som helst de tagit hade; David hemtade det allt igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Och David tog får och fä, och dref boskapen för sig, och de sade: Detta är Davids rof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Och då David kom till de tuhundrade män, som sig försummat hade efterfölja David, och voro blefne vid bäcken Besor, gingo de ut emot David, och folket, som med honom var; och David gick till folket, och helsade dem vänliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Då svarade de som onde och Belials män voro, ibland dem som med David dragne voro, och sade: Efter de icke foro med oss, skall man intet gifva dem af rofvet, som vi undsatt hafve; utan hvar och en tage sina hustru och sin barn, och gånge sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Då sade David: I skolen icke så göra, mine bröder, med det som Herren oss gifvit hafver, och hafver förvarat oss, och gifvit det krigsfolket i våra händer, som emot oss komne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Ho skulle höra eder derutinnan? Sådana som deras del är, som voro neddragne i stridena, sådana skall ock deras del vara, som när tygen blifvit hafva, och skall lika bytt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Detta är också ifrå den tiden och allt sedan vordet för en sed och rätt i Israel, intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Och då David kom till Ziklag, sände han rofvet till de äldsta i Juda sina nästa, och sade: Si, der hafven I välsignelsen af Herrans fiendars rof;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Nämliga dem i BethEl, dem i Bamoth söderut, dem i Jathir,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Dem i Aroer, dem i Siphmoth, dem i Esthemoa,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Dem i Rachal, dem i de Jerahmeeliters städer, dem i de Keniters städer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Dem i Horma, dem i ChorAsan, dem i Atach,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Dem i Hebron, och allestäds der David vandrat hade med sina män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Så stridde nu de Philisteer emot Israel, och Israels män flydde för de Philisteer, och föllo slagne på det berget Gilboa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Och de Philisteer föllo hardt in på Saul och hans söner, och slogo Jonathan, och AbiNadab, och MalchiSua, Sauls söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Och striden vardt hård emot Saul, och skyttorna drabbade på honom med bågarna; och han vardt illa sår af skyttorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Då sade Saul till sin vapnedragare: Drag ditt svärd ut, och sting mig igenom dermed, att desse oomskorne icke komma, och stinga mig igenom, och drifva gabberi med mig. Men hans vapnedragare ville icke; ty han fruktade sig storliga. Så tog Saul svärdet, och föll deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Då nu hans vapnedragare såg, att Saul var död, föll han ock på sitt svärd, och blef död med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Så blef Saul död, och tre hans söner, och hans vapnedragare, och alle hans män tillhopa på den dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Då nu Israels män, som voro på hinsidon vid dalen, och på hinsidon Jordan, sågo, att Israels män voro flydde, och att Saul och hans söner voro döde, öfvergåfvo de städerna, och flydde sammaledes. Så kommo de Philisteer, och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Den andra dagen kommo de Philisteer till att afkläda de slagna; och funno Saul och hans tre söner liggande på berget Gilboa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Och höggo honom hans hufvud af, och drogo af honom hans vapen, och sände i de Philisteers land allt omkring, till att förkunna det i deras gudars husom, och ibland folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Och lade hans harnesk i Astaroths hus; men hans kropp hängde de upp på muren i Bethsan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Då de i Jabes och Gilead hörde, hvad de Philisteer hade gjort Saul,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Reste sig upp alle de som striddogse män voro, och gingo den hela nattena, och togo Sauls och hans söners kroppar ned af muren i Bethsan, och förde dem till Jabes, och brände dem der upp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Och togo deras ben, och begrofvo dem under ett trä i Jabes; och fastade i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Efter Sauls död, då David igenkommen var ifrå de Amalekiters slagtning, och hade blifvit två dagar i Ziklag,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Si, på tredje dagen kom en man ifrå Sauls här, med sönderrifven kläder, och jord på hans hufvud. Och som han kom till David, föll han ned på jordena, och tillbad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Men David sade till honom: Hvadan kommer du? Han sade till honom: Ifrån Israels här hafver jag flytt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David sade till honom: Säg mig, huru tillgånget är. Han sade: Folket är flydt af stridene, och mycket folk är fallet; dertill är ock Saul död, och hans son Jonathan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David sade till den ynglingen, som detta bådade: Hvaraf vetst du, att Saul och hans son Jonathan äro döde?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Ynglingen, som detta bådade, sade: Jag kom oförvarandes upp på Gilboa berg; och si, Saul böjde sig neder på sitt spjut, och vagnar och resenärer jagade efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Och han vände sig om, och fick se mig, och kallade mig, och jag sade: Här är jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Och han talade till mig: Ho äst du? Jag sade till honom: Jag är en Amalekit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Och han sade till mig: Kom hit till mig, och dräp mig; ty ångest hafver begripit mig; ty mitt lif är ännu allt helt i mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Så gick jag till honom, och drap honom; förty jag visste väl, att han icke skulle kunna lefva efter hans fall; och jag tog kronona af hans hufvud, och armsmidet af hans arm, och hafver burit det hit till dig, min herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Då fattade David sin kläder, och ref dem sönder, och alle de män, som när honom voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Och jämrade sig, och greto, och fastade allt intill aftonen öfver Saul och Jonathan hans son; och öfver Herrans folk, och öfver Israels hus, att de genom svärd fallne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Och David sade till ynglingen, som honom det bådat hade: Hvadan äst du? Han sade: Jag är en främling, en Amalekits son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David sade till honom: Hvi hafver du icke fruktat dig komma dina hand vid Herrans smorda, till att dräpa honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Och David sade till en af sina unga män: Fram, och slå honom. Och han slog honom, att han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Då sade David till honom: Ditt blod vare öfver ditt hufvud; ty din mun hafver talat emot dig sjelf, och sagt: Jag hafver dräpit Herrans smorda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Och David klagade denna klagan öfver Saul och Jonathan hans son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Och befallde, att man skulle lära Juda barn bågan: Si, det är skrifvet uti den redeligas bok:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'De ädlaste i Israel äro slagne på din berg; huru äro de hjeltar fallne!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Bebåder det icke i Gath, förkunner det icke på gatomen i Askelon; på det att de Philisteers döttrar sig icke fröjda skola, att de oomskornas döttrar icke glädjas skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'I Gilboa berg, komme på eder hvarken dagg eller regn, icke heller vare åkrar, der häfoffer af kommer; förty der är de hjeltars sköld afslagen, Sauls sköld, likasom han icke hade varit smord med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Jonathans båge felade icke, och Sauls svärd kom aldrig fåfängt igen ifrå de slagnas blod, och ifrå de hjeltars fetma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul och Jonathan, ljuflige och täcke medan de lefde, äro också icke åtskiljde i döden; raskare än örnar, och starkare än lejon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'I Israels döttrar, gråter öfver Saul, den eder klädde med rosenfärgo i kräselighet, och prydde eder med gyldene klenodier på edor kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Huru äro de hjeltar så fallne i stridene; Jonathan är slagen på dina högar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Jag sörjer om dig, min broder Jonathan; du hafver varit mig mycket kär; din kärlek var mig närmare än qvinnokärlek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Huru äro de hjeltar fallne, och vapnen borto blefne!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sedan detta skedt var, frågade David Herran, och sade: Skall jag draga upp uti någon af Juda städer? Och Herren sade till honom: Drag ditupp. David sade: Hvart? Han sade: Till Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Så drog då David dit med sina två hustrur, Ahinoam den Jisreelitiskon, och Abigail, Nabals den Carmelitens hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Dertill hade han ock de män upp med sig, som när honom voro, hvar och en med sitt hus; och bodde i Hebrons städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Och de män af Juda kommo, och smorde der David till Konung öfver Juda hus. Och då David vardt bådadt, att de af Jabes i Gilead hade begrafvit Saul,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Sände han båd till dem, och lät säga dem: Välsignade varen I Herranom, att I denna barmhertighet hafven gjort på edar herra Saul, och begrafvit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Så göre nu Herren med eder barmhertighet och trohet; och jag skall ock desslikes göra eder godt, att I detta gjorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Så vare nu edra händer trösta, och står faste; efter edar herre Saul är död, så hafver nu Juda hus smort mig till Konung öfver sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Men Abner, Ners son, som Sauls höfvitsman var, tog Isboseth, Sauls son, och förde honom genom Mahanaim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Och gjorde honom till Konung öfver Gilead, Assuri, Jisreel, Ephraim, BenJamin, och öfver hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Och Isboseth, Sauls son, var fyratio år gammal, då han blef Konung öfver Israel, och regerade i tu år; men Juda hus höll med David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Och den tiden, som David var Konung i Hebron öfver Juda hus, var sju år och sex månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Och Abner, Ners son, drog ut med Isboseths, Sauls sons, tjenare, utu Mahanaim till Gibeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Och Joab, ZeruJa son, drog ut med Davids tjenare, och mötte hvarannan vid dammen i Gibeon; och lade sig, desse på denna sidone vid dammen, och de andre på den andra sidone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Och Abner sade till Joab: Låt de unga män stå, upp och spela för oss. Joab sade: Det må väl vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Så stodo de upp, och gingo fram tolf i talet utaf BenJamin, på Isboseths, Sauls sons, sido, och tolf af Davids tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Och hvardera tog den andra vid halsen, och stötte honom svärdet i hans sido; och föllo den ene med den andra; deraf det rummet kallas HelkathHazurim, hvilket i Gibeon är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Och begyntes en ganska hård strid på den dagen; men Abner och de män af Israel vordo slagne för Davids tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Och tre ZeruJa söner voro der, Joab, Abisai och Asahel; men Asahel var snar till fötter, såsom en rå på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Han jagade efter Abner, och vek icke, hvarken på den högra sidon eller den venstra, ifrån Abner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Då vände Abner sig om, och sade: Äst du Asahel? Han sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner sade till honom: Gif dig ifrå mig, antingen på högra sidon eller den venstra, och tag dig före någon af de unga karlar, och tag honom harnesket af. Men Asahel ville icke vika ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Då sade Abner ytterligare till Asahel: Gif dig ifrå mig, hvi vill du att jag skall slå dig till markena? Och huru skulle jag töra häfva mitt ansigte upp för dinom broder Joab?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Men han ville ingalunda vika. Då stack Abner honom bakom sig med ett spjut i hans buk, så att spjutet gick bak ut, och han föll, och blef der död för honom; och hvilken som kom till det rummet, der Asahel låg död, han stod der stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Men Joab och Abisai jagade efter Abner, intill solen gick ned; och de kommo på det berget Amma, som ligger för Giah, på den vägen till Gibeons öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Då församlade sig BenJamins barn bakför Abner, och vordo till en hop, och gingo öfverst på en hög.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Och Abner ropade till Joab, och sade: Skall då svärdet fräta utan ända? Vetst du icke, att det vill på sistone skarpt varda? Huru länge vill du icke säga folkena, att de låta af fördölja sina bröder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab sade: Så sant som Gud lefver, hade du bittida i dag sagt detta till mig, folket hade väl aflåtit att förfölja hvar och en sin broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Och Joab blåste i basunen, och allt folket blef stilla ståndandes, och jagade intet mer efter Israel; och stridde ej heller mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Men Abner och hans män gingo den hela nattena öfver slättmarkena, och drogo öfver Jordan, och vandrade genom hela Bithron, och kommo till Mahanaim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Men Joab vände sig ifrån Abner, och församlade hela folket; och der saknades af Davids tjenare nitton män, och Asahel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Och Davids tjenare hade slagit af BenJamin och Abners män, så att trehundrad och sextio män voro döde blefne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Och de togo Asahel upp, och begrofvo honom i hans faders graf i BethLehem. Och Joab med sina män gingo den hela nattena, och kommo i morgonlysningene till Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Och det var ett långt örlig emellan Sauls hus och Davids hus; men David gick och förkofrades, och Sauls hus gick tillbaka och förminskades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Och David vordo födde bara i Hebron: hans förstfödde son Ammon, utaf Ahinoam den Jisreelitiskon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Den andre Chileab, utaf Abigail, Nabals hustru den Carmelitens; den tredje Absalom, Maachas son, Thalmai dotters, Konungens i Gesur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Den fjerde Adonia, Haggiths son; den femte SephatJa, Abitals son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Den sjette Jithream, utaf Egla, Davids hustru. Desse äro födde David i Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Som nu örlig var emellan Sauls hus och Davids hus, förstärkte Abner Sauls hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Och Saul hade ena frillo benämnd Rizpa, Aja dotter; och Isboseth sade till Abner: Hvi sofver du när mins faders frillo?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Då vardt Abner ganska vred af denna Isboseths ord, och sade: Är jag då ett hundahufvud, jag som emot Juda gör barmhertighet på dins faders Sauls hus, och på hans bröder och vänner, och hafver icke gifvit dig i Davids händer; och du räknar mig i dag en ogerning till för en qvinnos skull?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Gud göre med Abner det och det, om jag icke gör, såsom Herren David svorit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Att riket skall tagas ifrån Sauls hus; och Davids stol skall uppsätter varda öfver Israel och Juda, ifrå Dan allt intill BerSaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Och han kunde icke mer svara honom ett ord; ty han fruktade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Och Abner sände båd för sig till David, och lät säga honom: Hvem hörer landet till? Och sade: Gör ditt förbund med mig; si, min hand skall vara med dig, så att jag vill vända till dig hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Han sade: Ja väl, jag vill göra förbund med dig; men ett beder jag af dig, att du icke ser mitt ansigte, förra än du förer till mig Michal, Sauls dotter, när du kommer till att se mitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Sände ock David båd till Isboseth, Sauls son, och lät säga honom: Få mig mina hustru Michal, den jag mig fast hafver med hundrade Philisteers förhudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboseth sände åstad, och lät taga henne ifrå mannen Phaltiel, Lais son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Och hennes man gick med henne, och gret efter henne, allt intill Bahurim. Då sade Abner till honom: Vänd om, och gack dina färde. Och han vände om igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Och Abner hade ett tal med de äldsta i Israel, och sade: I hafven länge tillförene åstundat David, att han måtte vara Konung öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Så görer ock så nu; förty Herren hafver sagt om David: Jag skall frälsa mitt folk Israel, genom min tjenares Davids hand, utu de Philisteers hand, och utur alla deras fiendars hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Talade ock Abner för BenJamins öron; och gick desslikes bort till att tala för Davids öron i Hebron, allt det Israel och hela BenJamins hus täcktes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Då nu Abner kom till David i Hebron, och tjugu män med honom, gjorde David dem ett gästabåd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Och Abner sade till David: Jag vill stå upp, och gå bort till att församla hela Israel till min herra Konungen, och att de skola göra ett förbund med dig; på det du må vara en Konung, såsom din själ det begärar. Så lät då David Abner gå ifrå sig med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Och si, Davids tjenare och Joab kommo ifrå krigsfolket, och hade ett stort rof med sig; men Abner var icke nu qvar när David i Hebron, utan han hade låtit honom ifrå sig, så att han med frid bortgången var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Då nu Joab, och hela hären med honom, var kommen, vardt honom sagdt, att Abner, Ners son, var kommen till Konungen, och han hade låtit honom ifrå sig, så att han var med frid bortgången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Så gick Joab in till Konungen, och sade: Hvad hafver du gjort? Si, Abner är kommen till dig: Hvi hafver du släppt honom ifrå dig, så att han är bortgången?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Känner du icke Abner, Ners son? Ty han är kommen till att bedraga dig, att han må bespeja din utgång och ingång, och få veta allt det du gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Och som Joab utgick ifrån David, sände han båd efter Abner, att de skulle hem ta honom igen ifrå BorHasira; och David visste der intet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Som nu Abner igenkom till Hebron, hade Joab honom midt uti porten, att han skulle tala med honom enskildt; och stack honom der i buken, så att han blef död, för hans broders Asahels blods skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'När nu David detta hörde, sade han: Jag är oskyldig, och mitt rike, för Herranom evinnerliga, för Abners, Ners sons, blod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Men det komme öfver Joabs hufvud, och öfver hela hans faders hus; och vände icke åter i Joabs hus, den som en etterflöd och spitelsko hafver, och den som sländo håller, och den genom svärd faller och den som bröd fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Alltså dråpo Joab och hans broder Abisai Abner, derföre att han slog deras broder Asahel ihjäl, i stridene vid Gibeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Men David sade till Joab, och allt folket som med honom var: Rifver edor kläder sönder, och drager säcker uppå eder, och jämrer eder för Abners skull. Och Konungen gick efter bårena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Och då de begrofvo Abner i Hebron, upphof Konungen sina röst, och gret vid Abners graf; gret ock desslikes allt folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Och Konungen beklagade sig öfver Abner, och sade: Abner är icke död såsom en dåre dör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Dina händer voro intet bundna; dina fötter voro intet satte i fjettrar; du äst fallen, såsom man faller för arga skalkar. Då begret folket honom än mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Då nu allt folket kom in med David till att äta, och ännu bittida dags var, svor David, och sade: Gud göre mig det och det, om jag bröd eller något annat smakar, förrän solen nedergår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Och allt folket visste det, och det behagade dem väl allt det goda, som Konungen gjorde för hela folksens ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Och allt folket och hela Israel märkte på den dagen, att det var icke af Konungenom, att Abner, Ners son, vardt dräpen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Och Konungen sade till sina tjenare: Veten I icke, att på denna dag är en Förste och stor man fallen i Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Och jag är ännu späd, och en smord Konung; men de män ZeruJa söner äro mig allt för hårde; Herren vedergälle honom, som illa gör, efter hans ondsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Då nu Sauls son hörde, att Abner var död i Hebron, föll honom händer ned, och hela Israel vardt bedröfvad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Så voro två män höfvitsmän öfver krigsfolket under Sauls son; den ena het Baana, den andre Rechab, Rimmons den Beerothitens söner, utaf BenJamins barn; ty Beeroth vardt ock räknad under BenJamin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Och de Beerothiter voro flydde till Gitthaim, och der främlingar vordne, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Hade ock Jonathan, Sauls son, en son; han var ofärdig i fötterna, och var fem åra gammal, då tidenden kommo om Saul och Jonathan utaf Jisreel; och hans amma tog honom upp, och flydde; och i det hon hastade, och flydde, föll han, och vardt halt; och han het MephiBoseth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Så gingo nu Rimmons den Beerothitens söner, Bechab och Baana, bort, och kommo till Isboseths hus, då dagen var hetast; och han låg på sine säng om middagen, och sof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Och de kommo i huset till att hem ta hvete; och stungo honom i buken, och rymde sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ty då de kommo i huset, låg han på sine säng i sin sängakammar, och de stungo honom ihjäl, och höggo honom hufvudet af; och togo hans hufvud, och gingo bort den vägen på slättmarkene, i den hela nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Och båro Isboseths hufvud till David i Hebron, och sade till Konungen: Si, der är Isboseths hufvud, Sauls sons, din fiendas, som stod efter dina själ; Herren hafver i dag hämnat min herra Konungen på Saul och hans säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Då svarade David, och sade till dem: Så visst som Herren lefver, som mina själ utur all bedröfvelse frälst hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Den som mig bådade, och sade: Saul är död, och mente att han var ett godt bådskap, den tog jag fatt, och drap honom i Ziklag, den jag skulle tidendeslön gifvit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Och desse ogudaktige männerna hafva ihjälslagit en oskyldig man, uti hans hus, på hans säng? Ja, skulle jag icke utkräfva hans blod utur edra händer, och taga eder utaf jordene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Och David böd sina unga män, och de slogo dem ihjäl, och höggo dem händer och fötter af, och hängde dem vid dammen i Hebron; men Isboseths hufvud togo de, och begrofvo det i Abners graf, i Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Och alla Israels slägter kommo till David i Hebron, och sade: Si, vi äre af ditt ben och ditt kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Dertill ock tillförene, när Saul var Konung öfver oss, förde du Israel ut och in; så hafver nu Herren sagt dig: Du skall vakta mitt folk Israel, och skall vara en höfvitsmän öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Och alle äldste i Israel kommo till Konungen i Hebron; och Konung David gjorde med dem ett förbund i Hebron för Herranom; och de smorde David till Konung öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Tretio åra gammal var David, då han Konung vardt, och regerade i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'I Hebron regerade han i sju är och sex månader, öfver Juda; men i Jerusalem regerade han i tre och tretio är, öfver hela Israel och Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Och Konungen drog bort med sina män till Jerusalem, emot de Jebuseer, som bodde der i landena. Men de sade till David: Du skall icke komma härin, utan blinde och halte skola drifva dig af. Och deras mening var, att David skulle icke komma derin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Men David vann borgena Zion; det är Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Då sade David på den dagen: Den som slår de Jebuseer, och kommer upp till takrännorna; de halta och blinda, hvilka Davids själ hatar. Deraf säger man: Låt ingen blindan eller haltan komma i huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Så bodde då David på borgene, och kallade henne Davids stad; och David byggde omkring, ifrå Millo och innanföre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Och David gick, och förkofrade sig; och Herren Gud Zebaoth var med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Och Hiram, Konungen i Tyro, sände båd till David, och cederträ till väggar, och timbermän och stenhuggare, att de skulle bygga David ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Och David förmärkte, att Herren hade stadfäst honom för en Konung öfver Israel, och upphöjt hans rike för sitt folk Israels skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Och David tog ännu flera hustrur och frillor i Jerusalem, sedan han var kommen ifrå Hebron; och honom vordo ännu flere söner och döttrar födde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Och detta är deras namn, som honom födde voro i Jerusalem: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibehar, Elisua, Nepheg, Japhia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada, Eliphalet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Och då de Philisteer hörde, att man hade smort David till Konung öfver Israel, drogo de alle upp till att söka David. Då David det förnam, drog han neder till en borg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Men de Philisteer kommo, och lade sig neder i den dalenom Rephaim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Och David frågade Herran, och sade: Skall jag draga upp emot de Philisteer, och vill du gifva dem i mina hand? Herren sade till David: Drag ditupp; jag vill gifva de Philisteer i dina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Och David kom till BaalPerazim, och slog dem der, och sade: Herren hafver förskingrat mina fiendar för mig ifrå, hvarannan, såsom vattnen förskingras. Deraf kallar man det samma rummet BaalPerazim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Och de läto der deras afgudar; men David och hans män togo dem bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Men de Philisteer drogo åter upp, och lade sig neder i Rephaims dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Och David frågade Herran. Han sade: Du skall icke draga ditupp; utan kom bakuppå dem, så att du kommer uppå dem in mot päronaträn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Och när du får höra, att det ruskar öfverst uppe i skatarna af päronaträn, så var vid ett friskt mod; ty Herren är då utgången för dig, till att slå de Philisteers här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David gjorde som Herren honom budit hade, och slog de Philisteer, ifrå Geba allt intilldess man kommer till Gaser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Och David samlade åter alla de unga män i Israel, tretiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Och stod upp, och gick bort med allt det folk, som när honom var af Juda män, att han skulle hemta dädan Guds ark, hvilkens namn heter: Herrans Zebaoths Namn bor deruppå öfver Cherubim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Och de satte Guds ark uppå en ny vagn, och hemtade honom utur AbiNadabs hus, som bodde i Gibea; men Ussa och Ahio, AbiNadabs söner, drefvo den nya vagnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Och de förde honom med Guds ark utur AbiNadabs hus, som i Gibea bodde; och Ahio gick framför arkenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Då spelade David och hela Israels hus för Herranom, med allahanda strängaspel af granträ, med harpor, och psaltare, och trummor, och bjellror, och cymbaler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Och då de kommo till Nachons lado, tog Ussa till, och höll Guds ark; ty oxarna gingo afsides utaf vägenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Då förgrymmade sig Herrans vrede öfver Ussa, och Gud slog honom der för hans öfverdådighets skull, så att han blef der död vid Guds ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Då var David bedröfvad, att Herren så sönderref Ussa. Och vardt det samma rummet kalladt Perez Ussa allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Och David fruktade sig för Herranom på den dagen, och sade: Huru skall Herrans ark komma till mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Och ville icke låta bära honom till sig in i Davids stad; utan lät bära honom uti ObedEdoms den Gitthitens hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Och då Herrans ark blef i tre månader uti ObedEdoms den Gitthitens hus, välsignade Herren honom, och allt hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Och det vardt sagdt Konung David, att Herren hade välsignat ObedEdoms hus, och allt det han hade, för Guds arks skull. Då gick han bort, och hemtade Guds ark utur ObedEdoms hus, upp uti Davids stad, med fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Och som de voro framgångne vid sex tren med Herrans ark, offrade man en oxa och ett fett får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Och David dansade med allo magt för Herranom, och hade klädt uppå sig en linnan lifkjortel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Och David samt hela Israel förde Herrans ark upp, med trummeter och basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Och då Herrans ark kom in uti Davids stad, såg Michal, Sauls dotter, ut genom fenstret, och såg Konung David springa och dansa för Herranom; och föraktade honom i sitt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'När de nu båro Herrans ark in, satte de honom på sitt rum midt i tabernaklet, som David för honom uppslagit hade. Och David offrade bränneoffer och tackoffer för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Och då David hade utoffrat bränneoffer, och tackoffer, välsignade han folket i Herrans Zebaoths Namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Och utskifte allo folkena och Israels menighet, både man och qvinno, hvarjom och enom ett bröd, och ett stycke kött, och ett mått vin; sedan gick allt folket sin väg, hvar och en i sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Men då David igenkom, till att välsigna sitt hus, gick Michal, Sauls dotter, ut emot honom, och sade: Huru härlig hafver Israels Konung varit i dag, som sig blottat hafver för sina tjenares tjensteqvinnor, såsom lösaktiga menniskor sig blotta!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Men David sade till Michal: Jag skall spela för Herranom, den mig utvalt hafver, heldre än din fader, och heldre än allt hans hus, så att han hafver mig befallt vara en Förste öfver Herrans folk öfver Israel; ja, för Herranom vill jag spela;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Och vill ännu ringare varda än så, och vill nedrig vara i min ögon, och med de tjensteqvinnor, som du af sagt hafver, till äro komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Och Michal, Sauls dotter, hade intet barn intill hennes dödsdag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Då nu Konungen satt i sitt hus, och Herren hade honom ro gifvit för alla hans fiendar allt omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Sade han till den Propheten Nathan: Si, jag bor uti cedrehus, och Guds ark bor under tapeter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Nathan sade till Konungen: Gack, allt det du hafver i ditt hjerta, det gör; ty Herren är med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Men om natten kom Herrans ord till Nathan, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Gack och säg till min tjenare David: Detta säger Herren: Skulle du bygga mig ett hus, att jag deruti bo skulle?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Hafver jag dock intet bott i något hus, ifrå den dag, jag förde Israels barn utur Egypten, allt intill denna dag; utan jag hafver vandrat i tabernakel och hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Ehvart jag med alla Israels barn vandrade, hafver jag ock någon tid talat med någro Israels slägt, den jag befallt hafver att föda mitt folk, och sagt: Hvi hafven I icke byggt mig ett cedrehus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Så skall du nu säga minom tjenare David: Detta säger Herren Zebaoth: Jag hafver tagit dig utaf markene, der du gick efter fåren, att du skulle vara en Förste öfver mitt folk Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Och hafver varit med dig, ehvart du gångit hafver; och hafver utrotat alla dina fiendar för dig, och hafver gjort dig ett stort namn, såsom de storas namn på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Och jag vill sätta mino folke Israel ett rum, och plantera det så, att det skall der blifva, och icke yttermera rördt varda; och orättfärdighetenes barn skola icke mera tränga det, såsom tillförene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Och ifrå den tid jag skickade domare öfver mitt folk Israel; och jag skall gifva dig ro för alla dina fiendar. Och Herren förkunnar dig, att Herren vill göra dig ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'När nu din tid förliden är, att du afsomnad äst med dina fäder, skall jag uppväcka dina säd efter dig, som af ditt lif komma skall; honom skall jag stadfästa hans rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Han skall bygga mino Namne ett hus; och jag skall stadfästa hans rikes stol till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Jag skall vara hans fader, och han skall vara min son; om han gör något illa, skall jag straffa honom med menniskoris, och med menniskors barnas hugg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Men min barmhertighet skall icke ifrå honom vänd vara, såsom jag vände henne ifrå Saul, den jag för dig borttagit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Men ditt hus och ditt rike skall blifva ståndandes för dig evinnerliga; och din stol skall stadig blifva till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Då nu Nathan hade sagt David all dessa orden, och alla denna synena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Kom Konung David, och satte sig för Herranom, och sade: Ho är jag, Herre, Herre? Och hvad är mitt hus, att du hafver låtit mig komma härtill?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Dertill hafver det icke tyckt dig vara nog, Herre, Herre; utan du hafver ock talat till dins tjenares hus om tillkommande ting i längdene. Är det menniskorätt, Herre, Herre?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Och hvad skulle David mer tala med dig? Du känner din tjenare, Herre, Herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'För ditt ords skull, och efter ditt hjerta hafver du all denna stora tingen gjort, att du det dinom tjenare förkunna ville.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Derföre äst du ock mycket aktad, Herre Gud; ty det är ingen såsom du, och är ingen Gud, utan du, efter allt det vi med vår öron hört hafve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Förty hvar är ett folk på jordene, såsom ditt folk Israel? För hvilkets skull Gud är gången till att förlossa sig ett folk, och göra sig ett Namn, och göra sådana stor och förskräckelig ting på ditt land för dino folke, som du dig förlossade utur Egypten, ifrå Hedningarna och deras gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Och du hafver tillredt dig ditt folk Israel, dig till folk i evig tid; och du, Herre, äst deras Gud vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Så stadfäst nu, Herre Gud, ordet i evighet, det du öfver din tjenare, och öfver hans hus sagt hafver, och gör såsom du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Så blifver ditt Namn stort i evighet, så att man skall säga: Herren Zebaoth är Gud öfver Israel; och dins tjenares Davids hus varder fast för ditt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Ty du, Herre Zebaoth, du Israels Gud, hafver öppnat dins tjenares öra, och sagt: Jag skall bygga dig ett hus; derföre hafver din tjenare funnit sitt hjerta, att han denna bönena till dig bedja skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nu, Herre, Herre, du äst Gud, och din ord skola vara sanning; du hafver detta goda talat öfver din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Så tag nu till, och välsigna dins tjenares hus, att det blifver evigt för dig; ty du Herre, Herre, hafver det talat; och med din välsignelse skall dins tjenares hus välsignadt varda till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Och det begaf sig derefter, att David slog de Philisteer, och förnedrade dem, och tog träldomsbetslet utu de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Han slog ock de Moabiter så till jordena, att han två delar drap, och en del lät lefvandes blifva. Alltså vordo de Moabiter David underdånige, så att de förde skänker till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David slog ock HadadEser, Rehobs son, Konungen i Zoba, då han drog ut till att hemta sin magt igen, vid den älfven Phrath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Och David fångade af dem tusende och sjuhundrad resenärar, och tjugutusend fotfolk; och hasade alla vagnhästar, och behöll qvar hundrade vagnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Så kommo de Syrer af Damascon, till att hjelpa HadadEser, Konungen i Zoba; och David slog de Syrer, tu och tjugu tusend män;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Och lade folk till Damascon i Syria. Alltså vardt Syria David underdånig, så att de förde skänker till honom; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Och David tog de gyldene sköldar, som HadadEsers tjenare tillhört hade, och förde dem till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Men ifrå Bethah, och Berothai, HadadEsers städer, tog Konung David ganska mycken koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Då Thoi, Konungen i Hemath, hörde att David hade slagit alla HadadEsers magt,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Sände han Joram sin son till David, till att helsa honom vänliga, och välsigna honom, att han hade stridt med HadadEser, och slagit honom; ty Thoi hade örlig med HadadEser, och han hade med sig silfver, och gyldene, och koppartyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Hvilka Konung David ock helgade Herranom, samt med det silfver och guld, som han helgade af allom Hedningom, dem han under sig tvingade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Af Syria, af Moab, af Ammons barn, af de Philisteer, af Amalek, af HadadEsers rof, Rehobs sons, Konungens i Zoba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Och gjorde David sig ett namn, då han igenkom och slog de Syrer i saltdalenom, adertontusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Och han lade folk i hela Edomea; och hela Edom var David undergifven; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Alltså vardt David Konung öfver hela Israel; och han skaffade rätt och rättviso allo folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, ZeruJa son, var öfver hären; men Josaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, Ahitobs son, och Ahimelech, AbJathars son, voro Prester; Seraja var skrifvare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Jojada son, var öfver Crethi och Plethi; och Davids söner voro Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Och David sade: Månn ock någor vara qvar af Sauls hus, att jag måtte göra barmhertighet med honom, för Jonathans skull?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Så var en tjenare af Sauls hus, benämnd Ziba, den kallade de till David; och Konungen sade till honom: Äst du Ziba? Han sade: Ja, din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Konungen sade: Är ännu någor till af Sauls hus, att jag måtte göra barmhertighet med honom? Ziba sade till Konungen: Det är ännu en till, Jonathans son, ofärdig i fötterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Konungen sade till honom: Hvar är han? Ziba sade till Konungen: Si, han är i Lodebar, i Machirs hus, Ammiels sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Då sände Konung David bort, och lät hemta honom ifrå Lodebar, utu Machirs hus, Ammiels sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Då nu MephiBoseth, Jonathans son, Sauls sons, kom till David, föll han på sitt ansigte, och tillbad. Och David sade: MephiBoseth. Han sade: Här är jag, din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David sade till honom: Frukta dig intet; ty jag vill göra barmhertighet på dig, för Jonathans dins faders skull, och vill gifva dig alla dins faders Sauls åkrar igen; men du skall dageliga äta bröd vid mitt bord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Han tillbad, och sade: Ho är jag, din tjenare, att du vände dig till en död hund, såsom jag är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Då kallade Konungen Ziba, Sauls tjenare, och sade till honom: Allt det Saul hafver tillhört, och hans hela hus, hafver jag gifvit dins herras son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Så bruka nu honom hans åker, du och din barn, och tjenare, och låt det komma in, att det skall vara dins herras sons bröd, att han må föda dig; men MephiBoseth dins herras son skall dagliga äta bröd vid mitt bord. Och Ziba hade femton söner och tjugu tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Och Ziba sade till Konungen: Allt det min herre Konungen hafver budit sinom tjenare, det skall hans tjenare göra; och MephiBoseth äte vid mitt bord, såsom ett af Konungsbarnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Och MephiBoseth hade en liten son, som het Micha; men allt det i Ziba hus bodde, det tjente MephiBoseth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Och MephiBoseth bodde i Jerusalem; ty han åt dagliga vid Konungens bord; och haltade på båda sina fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Och det begaf sig derefter, att Ammons barnas Konung blef död, och hans son Hanun vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Då sade David: Jag vill göra barmhertighet på Hanun, Nahas son, såsom hans fader hafver gjort barmhertighet med mig. Och sände bort och lät genom sina tjenare hugsvala honom öfver hans fader. Och Davids tjenare kommo i Ammons barnas land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Då sade de öfverste öfver Ammons barn till sin herra Hanun: Menar du, att David hedrar din fader för din ögon, att han hafver sändt hugsvalare till dig? Menar du icke, att han fördenskull hafver sändt sina tjenare till dig, att han skall utspana och bespeja staden, och förstöra honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Då tog Hanun Davids tjenare, och lät raka dem hälft skägget af; och skar half kläden af på dem, allt intill bältet, och lät så gå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Då det vardt bådadt David, sände han emot dem; förty männerna voro ganska mycket skämde. Och Konungen lät säga dem: Blifver i Jericho tilldess edart skägg växer, och kommer så igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Då nu Ammons barn sågo, att de voro illa luktande vordne för David, sände de bort, och lejde sig de Syrer af Rehobs hus, och de Syrer i Zoba, tjugutusend män fotfolk, och af Konung Maacha tusend män, och af Istob tolftusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Då David det hörde, sände han Joab med hela hären af krigsfolket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Och Ammons barn drogo ut, och skickade sig till strid ut för stadsporten; men de Syrer af Zoba, af Rehob, af Istob, och af Maacha, voro allena i markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Då nu Joab såg, att striden var ställd på honom både bak och före, utvalde han utaf alla de unga män i Israel, och skickade sig emot de Syrer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Och det andra folket lät han under sins broders hand Abisai, och han skickade sig emot de Ammons barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Och sade: Om de Syrer varda mig för mägtige, så kom mig till hjelp; om Ammons barn varda dig öfvermägtige, så vill jag komma dig till hjelp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Var vid god tröst, och låt oss stå fasta för vårt folk och för vår Guds städer; men Herren göre hvad honom täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Och Joab drog åstad med det folk, som när honom var, till att strida emot de Syrer; och de flydde för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Och då Ammons barn sågo, att de Syrer flydde, flydde de ock för Abisai, och drogo in i staden. Så vände Joab om ifrån Ammons barn, och kom till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Och, då de Syrer sågo, att de voro slagne för Israel, församlade de sig tillhopa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Och HadarEser sände bort, och, lät utkomma de Syrer på hinsidon älfven; och lät deras magt inkomma; och Sobach, HadarEsers härhöfvitsman, drog för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Då det vardt bådadt David, församlade han tillhopa hela Israel, och drog öfver Jordan, och kom till Helam; och de Syrer skickade sig emot David, till att strida med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Men de Syrer flydde för Israel, och David slog ihjäl de Syrer sjuhundrad vagnar, och fyratiotusend resenärar; dertill slog han Sobach härhöfvitsmannen, så att han blef der död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Då nu de Konungar, som voro under HadarEser, sågo att de slagne voro för Israel, gjorde de frid med Israel, och vordo dem underdånige; och de Syrer fruktade sig mer hjelpa Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Och då året så led, att Konungar pläga utdraga, sände David Joab, och sina tjenare med honom, och hela Israel, att de skulle förderfva Ammons barn, och de belade Rabba; men David blef i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Och det begaf sig, att David om aftonstid stod upp af sine säng, och gick upp på taket af Konungshuset, och såg af taket ena qvinno två sig; och qvinnan var ganska dägelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Och David sände bort, och lät fråga efter qvinnona, och sade: Är icke detta BathSeba, Eliams dotter, Uria den Hetheens hustru?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Och David sände bort båd, och lät hemta henne; och då hon kom in till honom, sof han när henne; men hon renade sig ifrå sine orenlighet, och gick hem igen till sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Och qvinnan vardt hafvandes, och sände bort, och lät förkunna det David, och säga: Jag är hafvandes vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Så sände David till Joab, och sade: Sänd till mig Uria den Hetheen. Och Joab sände Uria till David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Och då Uria kom till honom, frågade David, om det stod väl till med Joab, och med folket, och med stridene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Och David sade till Uria: Gack af i ditt hus, och två dina fötter. Och då Uria gick utu Konungens hus, följde honom straxt efter Konungens gåfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Och Uria lade sig till att sofva för dörrene af Konungens hus, der alle hans herras tjenare lågo, och gick intet neder i sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Då nu David sagdt vardt: Uria är icke afgången i sitt hus, sade David till honom: Äst du icke kommen af markene? Hvi äst du icke afgången i ditt hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Men Uria sade till David: Arken, och Israel, och Juda blifva i tjäll, och Joab min Herre, och mins herras tjenare ligga i markene; och jag skulle gå i mitt hus, till att äta och; dricka, och ligga när mine hustru? Så sant som du lefver, och din själ lefver, jag gör det icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'David sade till Uria: Så blif ännu i dag här; i morgon vill jag låta dig gå. Så blef Uria i Jerusalem i den dagen, och den andra dagen dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Och David böd honom, att han skulle med honom äta och dricka, och gjorde honom drucken; och om aftonen gick han ut, och lade sig till att sofva i sin säng, med sins herras tjenare, och gick icke af i sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Om morgonen skref David ett bref till Joab, och sände det med Uria.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Och i brefvet skref han alltså: Skicka Uria i stridene, der hon aldrahårdast är; och vänder eder tillbaka ifrå honom, att han måtte varda slagen, och blifva död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Som nu Joab låg för staden, skickade han Uria på det rum, der han visste att stridsamme män voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Och då männerna slogo utu stadenom, och stridde emot Joab, föllo somlige af folket, Davids tjenare; och Uria den Hetheen blef ock död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Så sände Joab bort, och lät säga David all stridsens handel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Och befallde bådet, och sade: När du hafver uttalat all stridsens handel med Konungenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Och du får se, att Konungen är vred, och säger till dig: Hvi hafven I så när trädt intill staden med stridene? Veten I icke huru man plägar skjuta af muren?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Ho slog AbiMelech, JeruBeseths son? Kastade icke en qvinna ett stycke af en qvarnsten uppå honom af muren, så att han blef död i Thebez? Hvi hafven I trädt så när muren? Så skall du säga: Din tjenare Uria den Hetheen är ock död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Bådet gick åstad, och kom, och sade David allt detta, der Joab honom om sändt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Och bådet sade till David: De män fingo öfverhanden med oss, och föllo till oss ut på markena; men vi sloge dem tillbaka allt intill stadsporten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Och de skyttar sköto af muren på dina tjenare, och dråpo somliga af Konungens tjenare; dertill är ock din tjenare Uria den Hetheen död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David sade till bådet: Så skall du säga till Joab: Låt detta icke bekymra dig; ty svärdet uppfräter nu den ena, nu den andra; håll uppå att strida emot staden, att du må nederslå honom, och var tröst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Och då Uria hustru hörde, att hennes man var död, jämrade hon sig för sin husbondas skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Då hon ut gråtit hade, sände David bort, och lät hemta henne i sitt hus; och hon vardt hans hustru, och födde honom en son; men Herranom misshagade detta ärendet, som David bedref.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Och Herren sände Nathan till David. När han kom till honom, sade han till honom: Det voro två män uti en stad; den ene rik, den andre fattig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Den rike hade ganska mycken får och fä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Men den fattige icke utan ett litet får, hans endesta, hvilket han köpt hade, och uppfödde det, att det uppväxte när honom, och bredovid hans barn. Det åt af hans beta, och drack af hans drickekar, och sof i hans famn, och han höll det såsom ena dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Men då till den rika mannen kom en gäst, nändes han icke taga af sin får och fä, till att tillreda något åt den gästen, som till honom kommen var; och tog den fattiga mannens får, och redde det till för den mannen, som till honom kommen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Då förgrymmade sig David med stora vrede emot den mannen, och sade till Nathan: Så sant som Herren lefver, den mannen är dödsens barn, som detta gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Dertill skall han betala fåret fyradubbelt igen, efter han sådant gjort hafver, och icke hade det fördrag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Då sade Nathan till David: Du äst den mannen. Så säger Herren Israels Gud: Jag hafver smort dig till en Konung öfver Israel, och hafver frälst dig utu Sauls hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Och hafver gifvit dig dins herras hus; dertill hans hustrur i din famn, och hafver gifvit dig Israels hus och Juda; och är det icke nog, vill jag ännu det och det göra dig dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Hvi hafver du då föraktat Herrans ord, att du sådant ondt för hans ögon göra skulle? Uria den Hetheen hafver du slagit med svärd; hans hustru hafver du tagit dig till hustru; men honom hafver du dräpit med Ammons barnas svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nu, så skall icke svärd återvända af ditt hus till evig tid; efter du hafver föraktat mig, och Uria den Hetheens hustru tagit, att hon skall vara din hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Detta säger Herren: Si, jag skall uppväcka ondt öfver dig, utaf ditt eget hus, och skall taga dina hustrur för din ögon, och skall gifva dinom nästa, att han skall ligga när dina hustrur om ljusa dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ty du hafver gjort det hemliga; men jag vill detta göra för hela Israel, på ljusa dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Då sade David till Nathan: Jag hafver syndat emot Herranom. Nathan sade till David: Så hafver ock Herren tagit din synd bort; du skall icke dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Men efter du hafver med detta ärendet kommit Herrans fiendar till att förhäda, skall den sonen, som dig födder är, döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Och Nathan gick hem i sitt hus. Men Herren slog barnet, som Uria hustru David födt hade, så att det vardt dödssjukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Och David bad Gud om barnet, och fastade, och gick in, och låg öfver natt ena på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Då stodo upp de äldste i hans hus, och ville rätta honom upp af jordene; men han ville icke, och åt icke heller med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'På sjunde dagenom blef barnet dödt; och Davids tjenare torde icke säga honom att barnet var dödt; ty de tänkte: Si, då barnet ännu var lefvandes, talade vi med honom, och han hörde vår röst intet; huru mycket mer skall det göra honom ondt, om vi säge: Barnet är dödt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Och David fick se att hans tjenare talade i mjugg, och förmärkte att barnet var dödt, och sade till sina tjenare: Är barnet dödt? De sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Då stod David upp af jordene, och tvådde sig, och smorde sig, och lade annor kläder uppå, och gick in uti Herrans hus, och tillbad; och då han kom hem igen i sitt hus, lät han komma mat upp för sig, och åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Då sade hans tjenare till honom: Hvad är det för ett ting, som du gör? Då barnet lefde, fastade du, och gret; men nu, sedan det dödt är, står du upp, och äter!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Han sade: För barnets skull fastade jag, och gret, då det lefde; ty jag tänkte: Ho vet, om Herren varder mig nådelig, så att barnet må blifva vid lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Men nu, sedan det dödt är, hvad skulle jag fasta? Kan jag ock hemta honom igen? Jag går väl till honom, men han kommer intet till mig igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Och då David hade hugsvalat sina hustru BathSeba, gick han in till henne, och sof när henne; och hon födde en son, den kallade han Salomo; och Herren älskade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Och han fick honom under Nathans hand, Prophetens; han kallade honom JedidJa, för Herrans skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Så stridde nu Joab emot Rabba Ammons barnas, och vann den Konungsliga staden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Och sände båd till David, och lät säga honom: Jag hafver stridt emot Rabba, och hafver ock vunnit vattustaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Så tag nu tillhopa det folk, som qvart är, och belägg staden, och vinn honom; på det att jag icke vinner honom, och får der namnet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Alltså tog David allt folket tillhopa, och drog åstad, och stridde emot Rabba, och vann honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Och tog deras Konungs krono utaf hans hufvud, hvilken hade i vigt en centener guld, och ädla stenar; och den vardt satt David på hans hufvud; och förde ganska mycket rof utu staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Och folket derinne förde han ut, och lade dem under jernsågar och taggar, och jernkilar, och brände dem upp uti tegelugnar; så gjorde han alla Ammons barnas städer. Så vände då David och allt folket om igen till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Och det begaf sig derefter, att Absalom, Davids son, hade en dägelig syster, den het Thamar. Och Amnon, Davids son, fick henne kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Och Amnon ställde sig såsom han var sjuk för Thamars sin systers skull; ty hon var en jungfru; och Amnon syntes icke lätt vara att göra henne något.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Men Amnon hade en vän, han het Jonadab, Simea son, Davids broders; och den samme Jonadab var en ganska snäll man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Han sade till honom: Hvi varder du så mager, du Konungens son, dag frå dag? Må du icke säga mig det? Då sade Amnon till honom: Jag hafver Thamar, mins broders Absaloms syster, kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab sade till honom: Lägg dig på dina säng, och gör dig krank. När då din fader kommer till att besöka dig, så säg till honom: Käre, lät mina syster Thamar komma, att hon gifver mig äta, och reder mat för mig, så att jag ser det, och äter utu hennes hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Så lade Amnon sig, och gjorde sig krank. Då nu Konungen kom till att se honom, sade Amnon till Konungen: Käre, låt mina syster Thamar komma, att hon reder för mig ett mos eller tu, och jag må äta af hennes hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Då sände David efter Thamar i huset, och lät säga henne: Gack i dins broders Amnons hus, och red honom något mat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Thamar gick åstad till sins broders Amnons hus, och han låg på sängene; och hon tog en deg, och knådade, och söd det för hans ögon, och kokade honom ett mos;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Och hon tog den rätten, och gaf upp för honom; men han ville icke ätat. Och Amnon sade: Låt alla gå ut ifrå mig; och alle gingo ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Då sade Amnon till Thamar: Bär maten in i kammaren, att jag må äta af dine hand. Så tog Thamar moset, som hon gjort hade, och bar det till Amnon sin broder i kammaren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Och som hon hade burit honom moset in, att han skulle äta, fick han henne fatt, och sade till henne: Hit, min syster, och ligg när mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Men hon sade till honom: Icke så, min broder; förkränk mig icke; ty så plägar man icke göra i Israel. Gör icke en sådana galenskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Hvar skulle jag blifva för mina blygds skull? Och du vorde såsom en dåre i Israel. Tala heldre med Konungenom; han nekar mig dig icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Men han ville icke höra henne; utan vardt henne öfvermägtig, och förnedrade henne, och låg när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Och han fick ett stort hat till henne, så att hatet vardt större än tillförene kärleken var. Och Amnon sade till henne: Statt upp, och gack.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Men hon sade: Detta onda är större, än det andra, som du hafver gjort på mig, att du drifver mig ut. Men han hörde hennes röst intet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Utan kallade sin dräng, som hans tjenare var, och sade: Drif denna ut ifrå mig, och stäng igen dörrena efter henne,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Och hon hade en brokot kjortel uppå; ty sådana kjortlar drogo Konungens döttrar, så länge de voro jungfrur. Och då hans tjenare hade drifvit henne ut, och stängt dörrena igen efter henne,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Kastade Thamar asko på sitt hufvud, och ref den brokota kjortelen sönder, som hon uppå hade, och lade sina hand på hufvudet, och gick, och ropade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Och hennes broder Absalom sade till henne: Hafver din broder Amnon varit när dig? Nu, min syster, tig stilla; det är din broder, och lägg det ärendet icke så på hjertat. Så blef Thamar ensam i Absaloms sins broders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Och då Konung David allt detta hörde, tog han det ganska illa vid sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Men Absalom talade intet vid Amnon, hvarken ondt eller godt; dock hatade Absalom Amnon, derföre att han hans syster Thamar förkränkt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Efter tu år lät Absalom klippa sin får i BaalHazor, som ligger under Ephraim; och Absalom böd all Konungens barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Och kom till Konungen, och sade: Si, din tjenare hafver fåraklippare. Jag beder att Konungen, samt med sina tjenare, ville gå med sinom tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Men Konungen sade till Absalom: Icke så, min son; låt oss icke alla gå, att vi icke göra dig tunga; och då han föll hårdt efter honom, ville han dock icke gå, utan välsignade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Absalom sade: Skall icke då min broder Amnon gå med oss? Konungen sade till honom: Hvi skulle han gå med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Då nödgade Absalom honom, så att han lät Amnon och all Konungens barn gå med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Och Absalom böd sina tjenare, och sade: Tager vara uppå, när Amnon varder glad af vinet, och jag säger till eder: Slår Amnon; och dräper honom, att I intet frukten eder, ty jag hafver det befallt eder; varer tröste och frimodige dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Alltså gjorde Absaloms tjenare Amnon, såsom Absalom dem budit hade. Då stodo all Konungens barn upp, och hvar och en satte sig på sin mula, och flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Och medan de ännu voro på vägenom, kom rykte för David, att Absalom hade slagit all Konungens barn, så att icke en var öfverblifven af dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Då stod Konungen upp, och ref sin kläder sönder, och lade sig neder på jordena; och alle hans tjenare, som stodo omkring honom, refvo sin kläder sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Då svarade Jonadab, Simea son, Davids broders, och sade: Min herre tänke icke att alle drängerne, Konungens barn, äro döde; utan Amnon är allena död; ty Absalom hafver detta haft inne med sig, ifrå den dagen han förkränkte hans syster Thamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Så tage icke nu min herre Konungen sådant till hjertat, att all Konungens barn äro döde; utan Amnon är allena död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Men Absalom flydde; och drängen på vaktene lyfte upp sin ögon, och såg ut; och si, en stor hop folk kom på vägenom, hvar efter den andra, utmed bergssidon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Då sade Jonadab till Konungen: Si, Konungens barn komma; såsom din tjenare sagt hafver, så är det tillgånget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Och då han uttalat hade, si, då kommo Konungens barn, och upphofvo sina röst, och greto. Konungen och alle hans tjenare greto ock ganska fast.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Men Absalom flydde, och drog till Thalmai, Ammihuds son, Konungen i Gesur. Men han jämrade sig öfver sin son alla dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Men då Absalom flydd var, och drog till Gesur, var han der i tre år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Och Konung David öfvergaf att draga ut emot Absalom; ty han var hugsvalad öfver Amnon, att han död var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Men Joab, ZeruJa son, förmärkte att Konungens hjerta var vändt till Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Och han sände bort till Thekoa, och lät hämta dädan ena kloka qvinno, och sade till henne: Jämra dig, och drag sorgkläder uppå, och smörj dig icke med oljo; utan ställ dig såsom en qvinna, den en lång tid hafver haft sorg öfver någon dödan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Och skall gå in till Konungen, och tala så och så med honom. Och Joab gaf henne in hvad hon säga skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Och då Qvinnan af Thekoa ville tala med Konungenom, föll hon på sitt anlete neder på jordena, och tillbad, och sade: Hjelp mig, Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Konungen sade till henne: Hvad är dig? Hon sade: Jag är en enka, en qvinna som sorg hafver, och min man är död;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Och din tjenarinna hade två söner; de kifvade tillhopa på markene; och efter der var ingen, som dem förtagat kunde, slog den ene den andra, och drap honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Och si, nu reser sig upp hela slägten emot dina tjenarinno, och säga: Få hit den som slog sin broder ihjäl, att vi måge dräpa honom för hans broders själ, den han dräpit hafver, och göra dig arfvingalösa; och de vilja utsläcka mina gnisto, som ännu qvar är, att minom man intet namn och ingen återlefva blifva skall på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Konungen sade till qvinnona: Gack hem, jag vill bjuda för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Och qvinnan af Thekoa sade till Konungen: Min herre Konung, missgerningen vare uppå mig, och uppå mins faders hus; men Konungen och hans stol vare oskyldig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Konungen sade: Den som emot dig talar, honom haf till mig, så skall han intet mer röra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Hon sade: Konungen tänke på Herran din Gud, att de blodhämnare icke varda för månge till att förderfva, och att min son icke förgörs. Han sade: Så sant som Herren lefver, skall icke ett hår falla på jordene af dinom son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Och qvinnan sade: Låt dina tjenarinno något säga minom herra Konungenom. Han sade: Säg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Qvinnan sade: Hvi hafver du ett sådant tänkt emot Guds folk, att Konungen detta sagt hafver, att han skall komma sig i skuld, och icke låta igentaga sin fördrefna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Ty vi dö döden, och förlöpe såsom vatten i jordena, det man icke uppehåller; och Gud vill icke taga lifvet bort, utan betänker sig, att det fördrefna icke också skall fördrifvet varda af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Så är jag nu kommen, till att tala med min herra Konungen dessa ord; ty folket hafver förskräckt mig; ty din tjenarinna tänkte: Jag skall tala med Konungenom; kanhända, att han gör det hans tjenarinna säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Ty han skall väl höra sina tjenarinno, att han hjelper mig ifrån allas deras hand, som mig, samt med minom son, ifrå Guds arf förgöra vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Och din tjenarinna tänkte: Mins herras Konungens ord skall vara mig en tröst; ty min herre Konungen är såsom en Guds Ängel, så att han kan höra godt och ondt; derföre varder ock Herren din Gud med dig blifvandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Konungen svarade, och sade till qvinnona: Ljug icke för mig i det jag frågar dig. Qvinnan sade: Min herre Konungen tale.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Konungen sade: Är icke Joabs hand med dig i allo desso? Qvinnan svarade, och sade: Så sant som din själ lefver, min herre Konung, det är ingen annan, antingen på högra handen eller den venstra, utan såsom min herre Konungen sagt hafver; ty din tjenare Joab hafver detta så budit mig, och han hafver allt detta dine tjenarinno ingifvit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Att jag skulle så vända denna sakena, det hafver din tjenare Joab gjort; men min herre är vis såsom en Guds Ängels vishet, så att han allt vet på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Då sade Konungen till Joab: Si, jag hafver detta gjort; så gack nu bort, och haf pilten Absalom hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Då föll Joab på sitt ansigte till jordena, och tillbad, och tackade Konungenom, och sade: I dag förmärker din tjenare, att jag hafver funnit nåd för din ögon, min herre Konung, att Konungen gör hvad hans tjenare säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Så stod då Joab upp, och for till Gesur, och hade Absalom till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Men Konungen sade: Låt honom gå i sitt hus igen, och icke se mitt ansigte. Och så kom då Absalom igen i sitt hus, och såg intet Konungens ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Och i hela Israel var icke en man så dägelig och så prislig som Absalom; ifrå hans fotabjelle upp till hans hjessa var ingen brist på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Och när han skar sitt hår af; det skedde gemenliga hvart år, ty det var honom för tungt, så att man måste det afskära; så vog hans hufvudhår tuhundrade siklar, efter Konungsvigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Och Absalom vordo födde tre söner, och en dotter; hon het Thamar, och var en dägelig qvinna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Alltså blef Absalom i tu år i Jerusalem, att han Konungens ansigte intet såg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Och Absalom sände efter Joab, att han skulle sända honom till Konungen; och han ville icke komma till honom. Han sände annan gången, likväl ville han icke komma,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Då sade han till sina tjenare: Ser det stycket af Joabs åker bredevid min, och han hafver der bjugg uppå; så går bort, och sticker eld deruppå. Så stucko Absaloms tjenare eld på det stycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Då stod Joab upp, och kom till Absalom i huset, och sade till honom: Hvi hafva dine tjenare stuckit eld på mitt stycke?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom sade till Joab: Si, jag sände efter dig, och lät säga dig: Kom till mig, att jag må sända dig till Konungen, och låta säga: Hvi kom jag ifrå Gesur? Det vore mig bättre, att jag ännu vore der. Så låt mig nu få se Konungens ansigte; är ock någon missgerning i mig, så dräp mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Och Joab gick in till Konungen, och sade det honom; och han kallade Absalom, att han kom in till Konungen; och han tillbad på sitt ansigte neder till jordena för Konungenom; och Konungen kysste Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Och det begaf sig derefter, att Absalom beställde sig vagnar och resenärar, och femtio män, som hans drabanter voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Och Absalom stod bittida upp om morgonen, och gick in på den vägen vid porten; och hvar någor hade ett ärende, så att han skulle komma till rätta för Konungen, den kallade Absalom till sig, och sade: Utaf hvad stad äst du? Då nu någor sade: Din tjenare är utaf ene af Israels slägter,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Så sade Absalom till honom: Si, din sak är god och rätt: men du hafver ingen, som dig förhörer af Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Och Absalom sade: Ack! ho sätter mig till domare i landena, att hvar man måtte komma till mig, den någon sak och klagan hafver, att jag måtte hjelpa honom till rätta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Och när någon gick fram till honom, till att tala med honom, så räckte han sina hand ut, och fick honom fatt, och kysste honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Vid det sättet gjorde Absalom allom Israel, när de kommo med några saker till Konungen; och stal alltså bort männernas hjerta af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Efter fyratio år sade Absalom till Konungen: Jag vill gå bort och fullkomna mitt löfte i Hebron, som jag Herranom lofvat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Förty din tjenare gjorde ett löfte, då jag bodde i Gesur i Syrien, och sade: När Herren låter mig återkomma till Jerusalem, så vill jag göra Herranom en Gudstjenst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Konungen sade till honom: Gack i frid. Och han stod upp, och gick till Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Men Absalom hade utsändt spejare uti alla Israels slägter, och lät säga: När I fån höra ljudet af basunen, så säger: Absalom är Konung vorden i Hebron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Och med Absalom gingo tuhundrad män af Jerusalem kallade; men de gingo i enfaldighet, och visste intet af sakene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Sände ock desslikes Absalom efter Achitophel den Giloniten, Davids rådgifvare, utaf hans stad Gilo; och som han nu hade offrat, vardt förbundet starkt, och folket lopp till, och förökades med Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Så kom en och bidade David, och sade: Hvars mans hjerta i Israel följer Absalom efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Men David sade till alla sina tjenare, som när honom voro i Jerusalem: Upp, låt oss fly; ty här blifver ingen undflykt för Absalom; skynder eder, låt oss gå, att han icke är snarare än vi, och får oss fatt, och drifver inuppå oss det ondt är, och slår staden med svärdsegg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Då sade Konungens tjenare till honom: Hvad min herre Konungen täckes, si, här äro dine tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Och Konungen gick ut till fot, med allt sitt hus; men han lät blifva qvara tio frillor, till att bevara huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Och då Konungen och allt folket till fot utkommo, gingo de bortåt långt ifrå huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Och alle hans tjenare gingo när honom; dertill alle Crethi och Plethi, och alle de Gitthiter; sexhundrad män, som af Gath till fot komne voro, gingo framför Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Och Konungen sade till Itthai den Gitthiten: Hvi går du ock med oss? Vänd om, och blif när Konungenom; ty du äst främmande; far ock igen till ditt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'I går komst du, och i dag vågar du dig till att gå med oss? Jag går hvart jag gå kan, vänd om, och dina bröder med; dig vederfare barmhertighet och trohet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Itthai svarade, och sade: Så sant som Herren lefver, och så sant som min herre Konungen lefver, hvar som helst min herre Konungen blifver, antingen i lifvet eller i döden, der skall din tjenare ock blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David sade till Itthai: Så kom, och gack med. Alltså gick Itthai den Gitthiten, och alle hans män, och hela barnahopen, som med honom var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Och hela landet greto med höga röst, och allt folket gick med; och Konungen gick öfver den bäcken Kidron, och allt folket gick före, på den vägen som löper åt öknena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Och si, Zadok var ock der, och alle Leviterna, som med honom voro, och båro Gudsförbunds ark, och der satte de honom; och AbJathar steg upp, tilldess allt folket kom utu stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Men Konungen sade till Zadok: Bär Guds ark åter in i staden; om jag finner nåd för Herranom, så låter han mig väl komma igen, och låter mig få se honom, och sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Men om han säger: Jag hafver intet behag till dig; si, här är jag; han göre med mig såsom honom täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Och Konungen sade till Presten Zadok: O Siare, vänd om igen i staden med frid; och med eder Ahimaaz din son, och Jonathan, AbJathars son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Si, jag vill draga fram på slättmarkena i öknene, tilldess bådskap kommer ifrån eder, och gifver mig all ting tillkänna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Så båro då Zadok och AbJathar Guds ark in i Jerusalem igen, och blefvo der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Men David gick uppfor oljoberget, och gret, och hans hufvud var skyldt, och han gick barfött; dertill allt folket, som med honom var, hade hvar och en förskylt sitt hufvud, och gingo uppåt gråtandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Och då David vardt sagdt, att Achitohel var i förbundet med Absalom, sade han: Herre, gör Achitophels rådslag till galenskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Och då David kom öfverst på berget, der man plägar tillbedja Gud; si, der mötte honom Husai, den Architen, med sönderrifven kjortel, och jord på hans hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Och David sade till honom: Om du går med mig, äst du mig till tunga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Men går du åter i staden, och säger till Absalom: Jag är din tjenare, jag vill höra Konungenom till; jag, som tillförene var dins faders tjenare, vill nu vara din tjenare; så kan du göra Achitophels rådslag om intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Och äro der Zadok och AbJathar Presterna med dig; allt det du hörer utu Konungens hus, må du undervisa Presterna Zadok och AbJathar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Och si, när dem äro två deras söner, Ahimaaz, Zadoks, och Jonathan, AbJathars son, genom dem kan du bjuda mig till hvad du förnimmer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Så kom då Husai, Davids vän, i staden, och Absalom kom till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Och som David något litet var nedergången af berget, si, då mötte honom Ziba, MephiBoseths tjenare, med ett par sadlade åsnar; deruppå voro tuhundrad bröd, och hundrade stycke russin, och hundrade stycke fikon, och en lägel vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Då sade Konungen till Ziba: Hvad vill du göra härmed? Ziba sade: Åsnorna skola vara för Konungens husfolk, att de derpå rida; och bröden och fikonen för tjenarena, att de måga äta, och vinet till att dricka, när de varda trötte i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Konungen sade: Hvar är dins herras son? Ziba sade till Konungen: Si, han blef i Jerusalem; ty han sade: I dag varder Israels hus mig igengifvandes mins faders rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Konungen sade till Ziba: Si, allt det MephiBoseth hafver, skall vara ditt. Ziba sade med tillbedjande: Låt mig finna nåd för dig, min herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Då nu Konung David kom till Bahurim, si, då gick der en man utaf Sauls hus slägt, han het Simei, Gera son; han gick ut och bannades;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Och kastade stenar åt David, och åt alla Konung Davids tjenare; ty allt folk och alle de väldige voro vid hans högra, och vid hans venstra sido.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Och sade Simei, då han bannades: Härut, härut, du blodhund, du Belials man!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herren hafver vedergullit dig allt Sauls hus blod, att du äst vorden Konung i hans stad; nu hafver Herren gifvit riket i din sons Absaloms hand; och si, nu tränger dig din olycka; ty du äst en blodhund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Men Abisai, ZeruJa son, sade till Konungen: Skall denne döde hunden banna min herra Konungen? Jag vill gå bort, och hugga hufvudet af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Konungen sade: I ZeruJa barn, hvad hafver jag skaffa med eder? Låt honom banna, ty Herren hafver budit honom banna David. Ho kan nu säga, hvi gör du så?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Och David sade till Abisai, och till alla sina tjenare: Si, min son, som af mitt lif kommen är, går mig efter mitt lif; hvi ock icke nu Jemini son? Låt honom betämma, att han bannar; ty Herren hafver så budit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Må hända, att Herren ser till mina bedröfvelse, och Herren löner mig med godo dessa bannor, som jag lider i dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Alltså gick David med sitt folk framåt vägen; men Simei gick ut med bergssidone jemte vid honom, och bannades, och kastade stenar till honom, och hof jord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Och Konungen kom derin, och allt folket, som med honom var, trötte; och vederqvickte sig der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Men Absalom och allt folket, Israels män, kommo till Jerusalem, och Achitophel med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Då nu Husai den Architen, Davids vän, kom in till Absalom, sade han till Absalom: Till lycko, herre Konung, till lycko, herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom sade till Husai: Är detta din barmhertighet emot din vän? Hvi hafver du icke farit ut med dinom vän?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husai sade till Absalom: Icke så, utan den som Herren utväljer, och detta folk, och hvar man i Israel, honom vill jag tillhöra, och när honom blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Och sedan, hvem skulle jag tjena? Skulle jag icke tjena hans son? Såsom jag hafver tjent dinom fader, så vill jag ock tjena dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Och Absalom sade till Achitophel: Gifver råd, hvad skole vi göra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Achitophel sade till Absalom: Lägg dig när dins faders frillor, som han hafver låtit qvara blifva till att bevara huset, så får hele Israel höra, att du hafver gjort din fader illa luktande, och alles deras hand, som när dig äro, blifver styrkt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Då gjorde de till Absalom ett tjäll uppå taket; och Absalom belåg sins faders frillor för all Israels ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'På den tiden, då Achitophel gaf ett råd, var det såsom man hade frågat Gud om någon ting; alltså var all Achitophels rådslag, både när David, och så när Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Och Achitophel sade till Absalom: Jag vill utvälja mig tolftusend män, och stå upp till att fara efter David i denna nattene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Och vill öfverfalla honom, medan han trött och mödd är. När jag nu förskräcker honom, så att allt folket, som när honom är, flyr, vill jag slå Konungen allena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Och draga allt folket till dig igen. När då hvar man till dig dragen är, såsom du begärar, så blifver allt folket i frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Detta tycktes Absalom vara godt, och allom äldstom i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Men Absalom sade: Käre, låt oss ock kalla Husai den Architen, och höra hvad han säger derom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Och då Husai kom in till Absalom, sade Absalom till honom: Sådant hafver Achitophel sagt; säg du, skole vi göra så, eller ej?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Då sade Husai till Absalom: Det är intet godt råd, som Achitophel i denna gången gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Och Husai sade ytterligare: Du känner väl din fader, och hans män, att de äro starke och illsinnade såsom en björn, hvilkom ungarna äro ifråtagne i markene. Dertill är din fader en stridsman, och varder sig intet försummandes med folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Si, han hafver tilläfventyrs nu förvarat sig någorstäds i en kulo, eller annorstäds. Om det nu skedde, att det ginge icke väl i första gången, och uppkomme ett rykte, och sades: Det är skedt en slagtning på det folk, som Absalom efterföljer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Så varder hvar och en förtviflad, den dock eljest dugelig är, och hafver ett hjerta såsom ett lejon; ty hela Israel vet, att din fader är stark, och dugelige män de som när honom äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Men det råder jag, att du församlar dig hela Israel, ifrå Dan intill BerSeba, många såsom sanden i hafvet; och din person drage ibland dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Så vilje vi öfverfalla honom på hvad rum vi finne honom, och vilje komma öfver honom, såsom daggen faller på jordena, att vi icke låte blifva en qvar, af honom och alla hans män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Om han församlar sig in uti någon stad, så skall hela Israel kasta linor kringom samma stad, och rycka honom i strömmen, att der skall icke finnas en sten igen af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Då sade Absalom, och hvar och en i Israel: Husai den Architens råd är bättre, än Achitophels råd. Men Herren skickade det så, att det goda Achitophels råd skulle varda förhindradt, på det att Herren skulle låta komma en olycko på Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Och Husai sade till Zadok och AbJathar Presterna: Så och så hafver Achitophel rådt Absalom och dem äldstom i Israel; men jag hafver så och så rådt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Så sänder nu med hast åstad, och båder David, och säger: Blif icke öfver nattena på slättmarkene i öknene; utan drag deröfver snarliga, att Konungen icke varder uppsluken, och allt folket, som med honom är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Men Jonathan och Ahimaaz stodo vid den brunnen Rogel; och en tjenstepiga gick bort, och sade dem det; och de gingo åstad, och sade det Konung David; förty de torde icke låta sig se, så att de kommo in i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Men en dräng fick se dem, och sade det för Absalom. Då gingo de både med hast sin väg, och kommo uti ens mans hus i Bahurim; han hade en brunn i sinom gård, der stego de in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Och qvinnan tog och bredde ett öfvertäckelse öfver brunnshålet, och slog der gryn uppå, så att man kunde det intet märka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Och då de voro bortgångne, stego de upp utu brunnen, och gingo sina färde; och underviste det Konung David, och sade till David: Står upp, och går med hast öfver älfvena; ty så och så hafver Achitophel gifvit råd emot eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Då stod David upp, och allt folket, som när honom var, och gingo öfver Jordan, tilldess morgon ljust vardt; och icke en fattades, som icke var kommen öfver Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Då Achitophel såg, att hans råd icke hade framgång, sadlade han sin åsna, och stod upp, och for hem i sin stad, och skickade om sitt hus, och hängde sig, och blef död, och vardt begrafven i sins faders graf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Och David kom till Mahanaim; och Absalom drog öfver Jordan, och alle Israels män med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Och Absalom hade satt Amasa i Joabs stad öfver hären; och Amasa var ens mans son, som het Jithra, en Israelit, hvilken låg när Abigail, Nahas dotter, ZeruJa syster, Joabs moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Men Israel och Absalom lägrade sig i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Då David var kommen till Mahanaim, kommo der Sobi, Nahas son, af Rabba Ammons barnas, och Machir, Ammiels son af Lodebar, och Barsillai, en Gileadit af Rogelim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Och förde sängkläder, bäcken, lerkäril, hvete, bjugg, mjöl, torkad ax, bönor, linse, gryn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Då nu Absaloms tjenare kommo till qvinnona i huset, sade de: Hvar är Ahimaaz och Jonathan? Qvinnan sade till dem: De gingo öfver vattubäcken. Och då de sökte, och funno intet, gingo de tillbaka igen till Jerusalem. Hannog, smör, får, och nötaostar till David, och till folket, som med honom var, till spisning; ty de tänkte, folket varder hungrigt, trött och törstigt i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Och David skickade folket, som när honom var, och satte höfvitsmän öfver dem, öfver tusend, och öfver hundrad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Och sände ut folket, en tredjepart under Joab, och en tredjepart under Abisai, ZeruJa son, Joabs broder, och en tredjepart under Itthai den Gitthiten. Och Konungen sade till folket: Jag vill ock draga ut med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Men folket sade: Du skall icke draga ut; förty om vi än flydde, eller hälften af oss blefve döde, der skola de intet om sköta; men du äst så mycket som tiotusend af oss; så är det nu bättre, att du må vara oss till hjelp utu stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Konungen sade till dem: Såsom eder täckes, så vill jag göra. Och Konungen blef ståndandes i portenom, och allt folket drog ut, vid hundrad, och vid tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Och Konungen böd Joab och Abisai, och Itthai, och sade: Farer mig sakta med pilten Absalom. Och allt folket hörde, att Konungen böd alla höfvitsmännerna om Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Och då folket kom ut i markena emot Israel, vardt stridt i Ephraims skog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Och Israels folk vardt der slaget för Davids tjenare, så att i den dagen skedde en stor slagtning, till tjugutusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Och striden vardt der förströdd uppå allt landet; och skogen uppfrätte flera på den dagen än svärdet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Och Absalom mötte Davids tjenare, och red på en mula; och då mulen kom under en stor tjock ek, fastnade hans hufvud vid ekena, och han blef hängandes emellan himmel och jord; men mulen lopp sin väg undan honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Då en man fick det se, bådade han det Joab och sade: Si, jag såg Absalom hänga vid en ek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Och Joab sade till mannen, som det bådade: Si, sågst du det, hvi slog du honom icke der till jordena? Så ville jag gifvit dig på mina vägnar tio silfpenningar, och ett bälte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mannen sade till Joab: Om du hade vägit mig tusende silfpenningar i mina hand, så ville jag ändå icke låtit komma min hand på Konungens son; ty Konungen böd dig, och Abisai, och Itthai, i våro åhöro, och sade: Förvarer mig pilten Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Eller om jag än något ondt gjort hade på min själs fara, efter för Konungenom intet fördoldt varder, skulle du väl sjelfver fallit mig emot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Joab sade: Icke så; jag vill till honom för din ögon. Då tog Joab tre spetsar i sin hand, och stötte dem Absalom i hjertat, medan han ännu lefde i ekene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Och tio unge karlar, Joabs vapnedragare, gåfvo sig omkring honom, och slogo honom ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Då blåste Joab i basunen, och kallade folket igen, att de icke mer skulle jaga efter Israel; ty Joab ville skona folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Och de togo Absalom och kastade honom i skogen uti en stor grop, och lade en stor hop med stenar på honom; och hele Israel flydde, hvar och en i sina hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Men Absalom hade sig upprest en stod, medan han ännu lefde, den står i Konungsdalenom; ty han sade: Jag hafver ingen son; derföre skall detta vara mins namns åminnelse; och kallade den stodena efter sitt namn, och heter ännu på denna dag Absaloms rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaaz, Zadoks son, sade: Käre, låt mig löpa, och förkunna Konungenom, att Herren hafver skaffat honom rätt af hans fiendars händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joab sade till honom: Du bär ingen god tidende i denna dagen; på en annan dag må du bära tidende, och icke i dag; ty Konungens son är död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Men till Cusi sade Joab: Gack åstad, och båda Konungen hvad du sett hafver. Och Cusi tillbad Joab, och lopp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Men Ahimaaz, Zadoks son, sade åter till Joab: Huru, om jag ock löper efter Cusi? Joab sade: Hvad vill du löpa, min son? Kom hit, du bär ingen god tidende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Han svarade: Huru, om jag lopp? Han sade till honom: Så löp. Så lopp då Ahimaaz på den genesta vägen, och kom förr än Cusi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Men David satt emellan två portar; och väktaren gick uppå taket åt porten om på muren, och lyfte sin ögon upp, och fick se en man löpandes allena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Och han ropade, och sade det Konungenom. Konungen sade: Är han allena, så är det god tidende i hans mun. Som han ännu lopp, och kom närmer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Fick väktaren se en annan man löpandes, och han ropade af murenom, och sade: Si, en man löper allena. Åter sade Konungen: Den är ock ett godt bådskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Väktaren sade: Mig synes den förstas löpande, såsom det vore Ahimaaz löpande, Zadoks sons. Och Konungen sade: Det är en god man, och han bär god tidende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaaz ropade, och sade till Konungen: Frid; och tillbad för Konungen på sitt anlete ned till jordena, och sade: Lofvad vare Herren din Gud, som de menniskor beslutit hafver, som upphofvo sina hand emot min herra Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Konungen sade: Mår ock pilten Absalom väl? Ahimaaz sade: Jag såg ett stort sorl, då Konungens tjenare Joab sände mig, din tjenare, och jag vet icke hvad det var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Konungen sade: Gack afsides, och statt der; och han gick afsides, och stod der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Si, då kom Cusi, och sade: Jag bär god tidende, min herre Konung: Herren hafver i dag skaffat dig rätt af allas deras hand, som sig hafva uppsatt emot dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Konungen sade till Cusi: Mår ock pilten Absalom väl? Cusi sade: Gånge så med alla mins herras Konungens fiendar såsom med piltenom går, och med alla dem som sätta sig upp emot dig, till att göra dig ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Då vardt Konungen sorgse, och gick upp i salen i portenom, och gret; och vid han gick, sade han: Min son Absalom, min son, min son Absalom! Gifve Gud, att jag måtte dö för dig. O Absalom! min son, min son!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Och det vardt bådadt Joab: Si, Konungen gråter, och beklagar sig om Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Och vardt i den dagen en sorg af segren i hela folkena; förty folket hade i den dagen hört, att Konungen var bedröfvad om sin son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Och folket drog sig bort i den dagen, så att det icke kom i staden, lika som ett folk drager sig bort, som till blygd kommet är, när det i strid flytt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Men Konungen förskylde sitt ansigte, och ropade högt: Ack! min son Absalom! Absalom, min son, min son!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Så gick Joab in uti huset till Konungen, och sade: Du hafver i dag till blygd gjort alla dina tjenare, som i dag undsatt hafva dina, dina söners, dina döttrars, dina hustrurs och dina frillors själar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Så att du hafver dem kär som dig hata, och hatar dem som dig kär hafva; ty du låter dig märka i dag, att dig ligger ingen magt uppå höfvitsmännerna och tjenarena; utan jag märker i dag väl, att om allenast Absalom lefde dig, och vi alle i dag döde vore, det skulle dig tycka så godt vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Så statt nu upp, och gack ut, och tala vänliga med dina tjenare; ty jag svär dig vid Herran: Om du icke går ut, blifver icke en man qvar när dig öfver denna nattena; det skall vara dig värre, än allt det onda som öfver dig kommet är, ifrå din ungdom allt intill nu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Då stod Konungen upp, och satte sig i porten, och allo folkena vardt sagdt: Si, Konungen sitter i portenom. Så kom allt folket för Konungen; men Israel var flydd, hvar och en i sin hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Och allt folket kifvade tillhopa i alla Israels slägter, och sade: Konungen hafver hulpit oss utu våra fiendars hand, och förlossat oss utu de Philisteers hand, och hafver måst fly utaf landena för Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Så är Absalom död blifven i stridene, den vi öfver oss smort hade; hvi ären I nu så stilla, att I icke hemten Konungen igen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Och Konungen sände till Zadok och AbJathar Presterna, och lät säga dem: Taler med de äldsta i Juda, och säger: Hvi viljen I vara de siste, till att hemta Konungen hem i sitt hus igen? Ty hela Israels tal var kommet för Konungen i hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'I ären mine bröder, mitt ben, och mitt kött; hvi viljen I då vara de siste, till att hemta Konungen igen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Och till Amasa säger: Äst du icke mitt ben, och mitt kött? Gud göre mig det och det, om du icke skall blifva härhöfvitsman för mig, så länge du lefver, i Joabs stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Och han bevekte alla Juda mäns hjerta, såsom ens mans; och de sände till Konungen: Kom igen, du och alle dine tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Så kom då Konungen igen. Och som han kom till Jordan, voro Juda män komne till Gilgal, till att draga neder emot Konungen, att de skulle föra Konungen öfver Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Och Simei, Gera son, Jemini sons, som i Bahurim bodde, hastade sig, och drog neder med Juda män emot Konung David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Och med honom voro tusende män af BenJamin; desslikes ock Ziba, den tjenaren af Sauls hus, med hans femton söner, och tjugu tjenare, och de skyndade sig öfver Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Och beredde färjona för Konungenom, att de skulle föra Konungens tjenare öfver, och göra det honom till vilja var. Och Simei, Gera son, föll neder för Konungen, då han for öfver Jordan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Och sade till Konungen: Min Herre, tillräkna mig icke den missgerning, och kom icke ihåg, att din tjenare förtörnade dig den dagen, då min herre Konungen gick utu Jerusalem, och Konungen lägge ett icke på hjertat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Ty din tjenare känner, att jag syndat hafver. Och si, jag är i dag den förste kommen utaf Josephs hus, att jag skulle draga neder emot min herra Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Men Abisai, ZeruJa son, svarade, och sade: Och skulle icke Simei derföre dö, som bannade Herrans smorda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'David sade: Hvad hafver jag beställa med eder, I ZeruJa barn, att I viljen i dag varda mig till Satan? Skulle i dag någor dö i Israel? Menar du att jag icke vet, att jag i dag är vorden Konung öfver Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Och Konungen sade till Simei: Du skall icke dö; och Konungen svor honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Kom också MephiBoseth, Sauls son, neder emot Konungen, och hade intet ryktat sina fötter, eller sitt skägg, eller tvagit sin kläder, ifrå den dagen Konungen bortgången var, intill den dagen då han kom med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Då han nu till Jerusalem kom, till att möta Konungenom, sade Konungen till honom: Hvi for du icke med mig, MephiBoseth?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Och han sade: Min herre Konung, min tjenare gjorde orätt emot mig; ty din tjenare tänkte: Jag vill sadla en åsna, och stiga deruppå, och rida till min herra Konungen; förty din tjenare är ofärdig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Dertill hafver han ock beklagat din tjenare för min herra Konungenom; men min herre Konungen är såsom en Guds Ängel, och må göra hvad honom täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Ty allt mins faders hus hafver icke varit utan till döden skyldigt för minom herra Konungenom; så hafver du dock satt din tjenare ibland dem, som äta öfver ditt bord; hvad rätt hafver jag mer, eller hvad kan jag mer ropa till Konungen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Konungen sade till honom: Hvad talar du mer härom? Jag hafver sagt det, du och Ziba skifter åkren med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'MephiBoseth sade till Konungen: Han må tagan allsamman, efter min herre Konungen med frid hemkommen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Och Barsillai, den Gileaditen, kom neder ifrå Roglim, och for öfver Jordan för Konungen, på det han skulle ledsaga honom öfver Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Och Barsillai var fast gammal, väl åttatio år; han hade försörjt Konungen, medan han var i Mahanaim; ty han var en ganska väldig man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Och Konungen sade till Barsillai: Du skall draga fram med mig; jag vill försörja dig med mig i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Men Barsillai sade till Konungen: Hvad är det jag ännu hafver till att lefva, att jag ännu skulle draga upp med Konungenom till Jerusalem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Jag är i dag åttatio år gammal; huru skulle jag känna hvad godt eller ondt är? Eller smaka hvad jag äter eller dricker? Eller höra hvad de sångare eller sångerskor sjunga? Hvi skulle din tjenare ytterligare besvära min herra Konungen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Din tjenare skall något litet fara med Konungenom öfver Jordan; hvi skulle Konungen göra mig en sådana vedergällning?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Låt din tjenare vända om igen, att jag må dö i minom stad, och varda begrafven i mins faders och mine moders grift. Si, der är din tjenare Chimham, den låt draga öfver med min herra Konungen; och gör honom hvad dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Konungen sade: Chimham skall draga öfver med mig, och jag vill göra honom hvad dig är till vilja; och allt det du bedes af mig, det vill jag göra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Och då allt folket var kommet öfver Jordan, och Konungen desslikes, kysste Konungen Barsillai, och välsignade honom; och han vände om igen till sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Och Konungen drog öfver till Gilgal, och Chimham for med honom; och allt Juda folk hade fört Konungen öfver; men Israels folk var icke utan hälften der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Och si, då kommo alle Israels män till Konungen, och sade till honom: Hvi hafva våre bröder, Juda män, stulit dig, och hafva fört Konungen och hans hus öfver Jordan, och alla Davids män med honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Då svarade de af Juda dem af Israel: Konungen är oss när åkommen; hvi ären I der vrede före? Menen I, att vi af Konungenom kost och skänker fått hafve?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Så svarade då de af Israel dem af Juda, och sade: Vi hafve tio sinom mer, med Konungenom, med David också, än I; hvi hafver du då så ringa aktat mig, att vi icke måtte hafva varit de förste, till att hemta vår Konung? Men de af Juda talade hårdare, än de män af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Och dit var kommen en Belials man, som het Seba, Bichri son, ens mans af Jemini, han blåste i basunen, och sade: Vi hafve ingen del i David, eller något arf i Isai son; hvar och en fare i sina hyddo, o Israel!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Då föll ifrå David hvar man i Israel, och följde Seba, Bichri son; men Juda män blefvo vid sin Konung, ifrå Jordan intill Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Då Konung David kom hem till Jerusalem, tog han de tio frillor, som han återleft hade till att bevara huset, och satte dem i förvaring, och försörjde dem; men han belåg dem intet mer; och de voro så innelyckta intill deras död, och lefde i enkodom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Och Konungen sade till Amasa: Kalla mig tillhopa alla Juda män, på tredje dagen; och du skall också vara vid handena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Och Amasa gick bort till att kalla tillhopa Juda; och han fördröjde öfver den tiden, som han honom förelagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Och David sade till Abisai: Nu varder oss Seba, Bichri son, mer vedermödo görandes än Absalom; tag du dins herras tjenare, och jaga efter honom, att han tilläfventyrs icke finner fasta städer för sig, och undslipper utu vår ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Då drogo ut med honom Joabs män, dertill Crethi och Plethi, och alle starke; men de drogo ut af Jerusalem, till att jaga efter Seba, Bichri son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Som de nu komne voro till den stora stenen i Gibeon, kom Amasa der emot dem; och Joab var begjordad öfver sin kläder, som han uppå hade, och hade bundit derutanöfver ett svärd, det hängde vid hans länd i skidone; och det gick väl ut och in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Och Joab sade till Amasa: Frid vare med dig, min broder; och Joab fattade Amasa i skägget med högra handene, såsom han ville kyssa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Och Amasa gaf icke akt på svärdet i Joabs hand. Och han stack honom dermed i buken, så att hans inelfver utgingo på jordena, och gaf honom intet styng mer; och han blef död. Men Joab och hans broder Abisai jagade efter Seba, Bichri son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Och en af Joabs tjenare blef ståndandes när honom, och sade: Hvilken dristar sig emot Joab, och hvilken går efter Joab när David?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Men Amasa låg sölad i blodet midt uppå vägenom. Då nu en såg, att allt folket blef der ståndandes, drog han Amasa af vägen bort på markena, och kastade kläder på honom; efter han såg att, hvilken till honom kom, han blef der ståndandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Då han nu var utaf vägenom tagen, följde hvar man efter Joab, till att jaga efter Seba, Bichri son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Och han drog genom alla Israels slägter, till Abel och BethMaacha, och hela Haberim; och de församlade sig, och följde honom efter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Och kommo, och belade honom i Abel och BethMaacha, och de gjorde en skam om staden, och trädde intill muren; och allt folket, som med Joab var, stormade och ville kasta muren omkull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Då ropade en vis qvinna utu stadenom: Hörer, hörer; säger till Joab, att han kommer hit, jag vill tala med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Och då han kom till henne, sade qvinnan: Äst du Joab? Han sade: Ja. Hon sade till honom: Hör dine tjenarinnos tal. Han sade: Jag hörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Hon sade: I förtiden sade man: Den som fråga vill, han fråge i Abel; och så gick det väl till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Detta är den redelige och trogne staden i Israel, och du vill dräpa staden och modrena i Israel? Hvi vill du uppsluka Herrans arfvedel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab svarade, och sade: Bort det, bort det ifrå mig, att jag uppsluka eller förderfva skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Det hafver sig icke så; utan en man af Ephraims berg, benämnd Seba, Bichri son, hafver upphäfvit sig emot Konung David: Får honom hitut allena, så vill jag draga af ifrå stadenom. Qvinnan sade till Joab: Si, hans hufvud skall varda kastadt ut till dig öfver muren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Och qvinnan kom in till allt folket med sine vishet; och de höggo Seba, Bichri son, hufvudet af, och kastade det ut till Joab. Då blåste han i basunen, och de åtskiljde sig ifrå stadenom, hvar och en uti sin hyddo; och Joab kom igen till Konungen i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Och Joab var öfver all Israels här; Benaja, Jojada son, var öfver Crethi och Plethi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram var räntomästare; Josaphat, Ahiluds son, var canceller;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja var skrifvare; Zadok och AbJathar voro Prester;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Dertill var Ira, den Jairiten, Davids Prest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Så vardt en hård tid i Davids dagar i tre år efter hvartannat; och David sökte Herrans ansigte; och Herren sade: För Sauls skull, och för det blodhus skull, derföre att han drap de Gibeoniter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Då lät Konungen kalla de Gibeoniter, och talade med dem; men de Gibeoniter voro icke utaf Israels barn, utan voro igenblefne utaf de Amoreer; men Israels barn hade svorit dem; och Saul sökte efter att slå dem i sitt nit för Israels barn och Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Så sade nu David till de Gibeoniter: Hvad skall jag göra eder? Och hvarmed skall jag försonat, att I mågen välsigna Herrans arfvedel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'De Gibeoniter svarade honom: Oss är intet om guld eller silfver af Saul eller hans hus; och är oss intet om, att någor skall dräpas af Israel. Han sade: Hvad sägen I då, det jag eder göra skall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'De sade till Konungen: Den mannen, som oss förderfvat och tillintetgjort hafver, honom skole vi förderfva, så att intet blifver qvart af honom i alla Israels gränsor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Gif oss sju män utaf hans hus, att vi upphänge dem Herranom i Gibea Sauls, Herrans utvaldas. Konungen sade: Jag vill få eder dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Men Konungen skonade MephiBoseth, Jonathans son, Sauls sons, för Herrans eds skull, som emellan dem var, nämliga, emellan David och Jonathan, Sauls son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Men de två Rizpa söner, Aja dotters, hvilka hon Saul födt hade, Armoni och MephiBoseth; dertill de fem Michals söner Sauls dotters, hvilka hon Adriel, Barsillai den Meholathitens son, födt hade, tog Konungen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Och fick dem uti de Gibeoniters hand; dem upphängde de på bergena för Herranom. Och så föllo desse sju på eno reso; och blefvo döde i första andene, när bjugganden uppågick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Då tog Rizpa, Aja dotter, en säck och bredde honom på ena håll i andenes begynnelse, intilldess vattnet af himmelen dröp uppå dem; och lät i den dagen inga himmelens foglar sätta sig på dem; ej heller markenes djur om nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Och det vardt sagdt David, hvad Rizpa, Aja dotter, Sauls frilla, gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Och David gick bort, och tog Sauls ben, och Jonathans hans sons ben ifrå de borgare i Jabes i Gilead, hvilken de utaf Bethsans gato stulit hade; der de Philisteer dem hängt hade, på den tiden då de Philisteer slogo Saul på Gilboa berg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Och förde dem dädan ditupp, och samkade dem tillhopa med de hängdas ben;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Och begrofvo Sauls och hans sons Jonathans ben i BenJamins land i Zela, i hans faders Kis graf; och gjorde allt såsom Konungen budit hade. Alltså vardt då Gud sedan landena försonad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Så hof sig åter ett örlig upp utaf de Philisteer emot Israel. Och David drog neder, och hans tjenare med honom, och stridde emot de Philisteer. Och David vardt trött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Och Jesbi af Nob, hvilken en af Rapha barn var, och hans glafvens vigt var trehundrad kopparsvigter, och han hade ett nytt harnesk uppå, han for efter att slå David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Men Abisai, ZeruJa son, halp honom, och slog den Philisteen ihjäl. Då svoro honom Davids män, och sade: Du skall icke mer draga ut med oss i strid, att icke utsläckes lyktan i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Sedan hof sig åter ett örlig upp i Gob med de Philisteer; då slog Sibbechai, den Husathiten, Saph, den ock en var utaf de Rapha barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Och sig hof ännu upp ett örlig i Gob med de Philisteer; då slog ElhananJaere, Orgims son, en BethLehemit, Goliath, den Gitthiten, hvilken hade en spets, hvilkens stång var såsom ett väfträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Och sig upphof ännu ett örlig i Gath. Der var en lång man, han hade sex finger på sina händer, och sex tår på sina fötter, så att de voro fyra och tjugu på talet; och han var också födder af Rapha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Och då han talade hädelse till Israel, slog honom Jonathan, Simea son, Davids broders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Desse fyra voro Rapha födde i Gath; och föllo igenom Davids och hans tjenares hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Och David talade för Herranom denna visones ord, den tid då Herren hade hulpit honom ifrån alla hans fiendars hand, och ifrå Sauls hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Och sade: Herren är min klippa, och min borg, och min Frälsare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gud är min tröst, på honom vill jag trösta; min sköld och mine helsos horn; mitt beskärm, och min tillflykt, min Frälsare, du som mig hjelper ifrån orätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Jag vill lofva och åkalla Herran, så blifver jag ifrå mina fiendar förlossad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Ty dödsens förderf hade omhvärft mig; och Belials bäcker hade förskräckt mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Helvetes band omhvärfde mig; och dödsens snaror öfverföllo mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'När jag bedröfvad är, vill jag åkalla Herran, och ropa till min Gud, så hörer han mina röst utaf sitt tempel; och mitt rop kommer för honom i hans öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Jorden bäfvade och skalf; himmelens grundvalar hafva sig rört, och gifvit sig, då han var vred.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Rök gick upp utaf hans näso, och förtärande eld utaf hans mun; så att det ljungade deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Himmelen böjde han, och steg neder; och mörker var under hans fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Och han steg på Cherub, och flög, och syntes på vädrens vingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Hans tjäll kringom honom var mörker, och svart tjockt moln.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Af skenet för honom brann det med ljungande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herren dundrade af himmelen; och den Högste lät utgå sitt dunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Han sköt sina pilar, och förströdde dem; han lät ljunga, och förskräckte dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Då såg man vattnet uppvälla; och jordenes grund vardt blottad genom Herrans straff, och genom hans näsos anda och blåst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Han sände utaf höjdene, och hemtade mig, och drog mig utu stor vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Han frälste mig ifrå mina starka fiendar; ifrå mina hatare, som mig för mägtige voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'De mig öfverföllo i mine olyckos tid; och Herren är min tröst vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Han hafver utfört mig på rymdena. Han tog mig ut; förty han hade lust till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herren gör väl vid mig efter mina rättfärdighet; han betalar mig efter mina händers renhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Ty jag håller Herrans vägar, och är icke ogudaktig vorden emot min Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Förty alla hans rätter hafver jag för ögon; och hans bud kastar jag icke ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Men jag är utan vank för honom, och bevarar mig för synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Derföre vedergäller mig Herren efter min rättfärdighet; efter min renhet för hans ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Med de heliga äst du helig; med de fromma äst du from.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Med de rena äst du ren; och vid de afvoga ställer du dig afvog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Ty du hjelper det elända folk; och med din ögon förnedrar du de höga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ty du, Herre, äst min lykta; Herren upplyser mitt mörker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Förty med dig kan jag nederslå krigsfolk; och genom min Gud springa öfver muren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Guds vägar äro utan brist; Herrans tal är genomluttradt; han är en sköld allom dem som hoppas till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Ty hvilken är en Gud, utan Herren? Och hvilken är en tröst, utan vår Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Gud styrker mig med kraft, och visar mig en väg utan brist.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Han gör mina fötter lika som hjortars; och sätter mig uppå mina höjder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Han lärer mina händer strida, och drifver mina armars kopparbåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Och du gifver mig dine helsos sköld; och när du förnedrar mig, gör du mig storan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du gör rum för mig till att gå, att mina fötter icke slinta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Jag vill jaga efter mina fiendar, och förgöra dem; och vill icke omvända, tilldess jag gör en ända med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Jag vill förgöra dem, och nederslå dem, och de skola icke stå mig emot; de måste falla under mina fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Du kan omgjorda mig med kraft till strid; du kan kasta dem under mig, som sätta sig upp emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Du gifver mig mina fiendar på flyktena, att jag må förstöra dem som mig hata.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'De ropa, men der är ingen hjelpare; till Herran, men han svarar dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Jag skall sönderstöta dem såsom stoft på jordene; såsom träck uppå gatone skall jag göra dem till mull, och förströ dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du hjelper mig ifrå det trätosamma folket; och bevarar mig till ett hufvud öfver Hedningarna. Det folk, som jag intet kände, skall tjena mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'De främmande barn försaka mig; men desse lyda mig med hörsam öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'De främmande barn äro försmäktade, och brytas i sina bojor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herren lefver, och lofvad vare min tröst; och varde upphöjd Gud, mine helsos tröst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Gud, som gifver mig hämnden, och kastar folk under mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Han förer mig ut ifrå mina fiendar, och ifrå dem, som sätta sig emot mig, upphöjer du mig; och ifrå vrångvisa män frälsar du mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Derföre vill jag tacka dig, Herre, ibland Hedningarna, och dino Namne lofsjunga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Den der stor salighet bevisar sinom Konung; och gör väl med David sinom smorda, och med hans säd i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dessa äro de sista Davids ord; David, Isai son, sade: Den mannen sadet, som för en Jacobs Guds smord uppsätter är, och en lustig Israels diktare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Herrans Ande hafver talat genom mig, och hans ord är skedt genom mina tungo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israels Gud hafver talat till mig; Israels tröst hafver mig tillsagt, den der råder öfver menniskorna, den rättvise rådanden i Guds fruktan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Såsom ljuset är om morgonen, då solen uppgår bittida, utan moln; och af skenet efter regn växer gräs upp af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ty ingen ting är för Gudi såsom mitt hus; ty han hafver gjort ett evigt förbund med mig, i alla måtto visst och fast; ty det är all min salighet, och all lust, att intet så växa skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Men den ogudaktige Belial skall varda alldeles utrotad såsom törne, så att man intet behåller deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Och om någor antastar dem, skola de med jern och spets platt förderfva dem; och man skall uppbränna dem med eld i deras rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Desse äro namnen af Davids hjeltar: Jasabeam, Hachmoni son, den ypperste ibland tre; hvilken upphof sin spets, och slog ihjäl åttahundrad i ena reso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Näst honom var Eleazar, Dodi son, Ahohi sons, ibland de tre hjeltar med David, då de förhädde de Philisteer, och voro der församlade till strid, och Israels män drogo upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Då stod han, och slog de Philisteer, tilldess hans hand dofnade, trött af svärdena. Och Herren gaf en stor salighet på den tiden, så att folket vände om igen efter honom till att röfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Efter honom var Samma, Age son, den Hararitens. Då de Philisteer församlade sig i en rota, och der var en åker full med linse, och folket flydde för de Philisteer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Då trädde han midt uppå den åkren, och undsatte honom, och slog de Philisteer; och Herren gaf en stor salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Och desse tre ypperste ibland tretio kommo neder i andene, till David uti kulona Adullam; och de Philisteers rote låg i Rephaims dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Men David var på den tiden på borgene; och de Philisteers folk låg i BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Och David vardt lysten och sade: Ho vill hemta mig dricka af det vatten i BethLehems brunn, under portenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Då föllo de tre hjeltar in uti de Philisteers lägre, och hemtade vatten utu brunnenom i BethLehem, under porten, och båro till David; men han ville intet dricka det, utan utgöt det Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Och sade: Det låte Herren vara långt ifrå mig, att jag detta göra skulle; är det icke de mäns blod, som sitt lif vågade, och gingo dit? Och han ville icke drickat. Det gjorde nu de tre hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, Joabs broder, ZeruJa son, var ock en ypperst ibland tre. Han hof sin spets upp, och slog trehundrad, och var också prisad ibland tre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Och den härligaste ibland tre och var deras öfverste; men han kom icke intill de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Och Benaja, Jojada son, IsHails sons af storom gerningom, af Kabzeel, han slog tu de Moabiters lejon, och gick ned, och slog ett lejon i brunnenom i snötiden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Och slog desslikes en grufvelig Egyptisk man; den hade en spets i sine hand; men han gick neder till honom med en staf, och tog den Egyptien spetsen utu handene, och slog honom ihjäl med sin egen spets.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Detta gjorde Benaja, Jojada son, och var beprisad ibland de tre hjeltar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Och härligare än de tretio; men han kom icke till de tre. Och David gjorde honom till sitt hemliga Råd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, Joabs broder, är ibland de tretio; Elhanan, Dodo son, i BethLehem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma den Haroditen; Elika den Haroditen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez den Palthiten; Ira, Ikkes son, den Thekoitens;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser den Annethothiten; Mebunnai den Husathiten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon den Achothiten; Maharai den Netophathiten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, Baena son, den Netophathiten; Itthai, Ribai son, af Gibea BenJamins barnas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, den Pirgathoniten; Hiddai, af de bäcker Gaas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'AbiAlbon den Arbathiten; Asmaveth den Barhumiten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliaheba den Saalboniten, Jasens och Jonathans barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma den Harariten; Ahiam, Sarars son, dens Araritens;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, Ahasbai son, Maachathi sons; Eliam, Achitophels son, dens Gilonitens;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai den Carmeliten; Paarai den Arbiten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigeal, Nathans son, af Zoba; Bani den Gaditen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek den Ammoniten; Naharai den Beerothiten, Joabs vapnedragare, ZeruJa sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira den Jithriten; Gareb den Jithriten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uria den Hetheen. De äro alle tillhopa sju och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Och Herrans vrede förgrymmade sig åter emot Israel, och gaf David ibland dem in, att han sade: Gack bort, räkna Israel och Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Och Konungen sade till Joab sin härhöfvitsman: Far omkring i alla Israels slägter, ifrå Dan intill BerSeba, och räkna folket, att jag må veta huru mycket det är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab sade till Konungen: Herren din Gud föröke till detta folket, såsom det nu är, ännu hundrade resor så mycket, att min herre Konungen må se lust deruppå. Men hvad hafver min herre Konungen lust till detta ärendet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Men Konungens ord måste gå före, emot Joab och höfvitsmännerna öfver hären. Alltså drog Joab ut, och höfvitsmännerna öfver hären ifrå Konungenom, att de skulle tälja Israels folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Och foro öfver Jordan, och lägrade sig i Aroer, på högra sidone vid den staden, som ligger i Guds bäck, och i Jaeser;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Och kommo till Gilead, och i nederlandet Hadsi; och kommo till DanJaan, och omkring Zidon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Och kommo till den fasta staden Tyrus, och till alla de Heveers och Cananeers städer; och kommo ut söder på Juda till BerSeba;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Och drogo kringom hela landet. Och efter nio månader och tjugu dagar kommo de till Jerusalem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Och Joab fick Konungenom summan af folket, som taldt var; och det var i Israel åttahundrade sinom tusende starke män, som svärd utdrogo; och i Juda femhundrade sinom tusende män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Och Davids hjerta slog honom, sedan folket taldt var. Och David sade till Herran: Jag hafver svårliga syndat, att jag detta gjort hafver; och nu, Herre, tag bort dins tjenares missgerning; ty jag hafver gjort mycket dårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Och då David stod upp om morgonen, kom Herrans ord till Propheten Gad, Davids Siare, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Gack bort och tala till David: Så säger Herren: Treggehanda ting sätter jag dig före; utvälj der ett af, det jag dig göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad kom till David, och bådade honom, och sade till honom: Vill du, att hård tid kommer i sju år i ditt land? Eller att du i tre månader måste fly för dina fiendar, och de förfölja dig? Eller att pestilentie blifver i tre dagar i ditt land? Så märk nu, och se till hvad jag skall säga honom igen, som mig sändt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David sade till Gad: Mig är stor ångest; men låt mig falla i Herrans hand; ty hans barmhertighet är stor; jag vill icke falla i menniskohand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Alltså lät Herren komma pestilentie i Israel, ifrå morgonen intill bestämdan tid, så att folket blef dödt, ifrå Dan intill BerSeba, sjutiotusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Och då Ängelen utsträckte sina hand öfver Jerusalem, att han det förderfva skulle, ångrade Herranom det onda, och sade till Ängelen, som folket förderfvade: Det är nog; håll nu din hand tillbaka. Och Herrans Ängel var vid Arauna lado, den Jebuseens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Då David såg Ängelen, som folket slog, sade han till Herran: Si, jag hafver syndat; jag hafver gjort den missgerningena; hvad hafva desse fåren gjort? Låt dina hand vara emot mig och mins faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Och Gad kom till David i samma tiden, och sade till honom: Gack upp, och res upp Herranom ett altare uti Arauna lado, den Jebuseens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Alltså gick David upp, såsom Gad sagt och Herren budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Och då Arauna vände sig om, såg han Konungen med sina tjenare gå till sig; och tillbad på sitt ansigte ned till jordena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Och sade: Hvi kommer min herre Konungen till sin tjenare? David sade: Till att köpa ladona af dig, och bygga Herranom ett altare, att plågan må återvända i folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna sade till David: Min herre Konungen tage och offre såsom honom täckes; si, der äro oxarna till bränneoffer, och slädar, och redskapen till oxarna till ved.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Allt gaf Arauna Konungenom; och Arauna sade till Konungen: Herren din Gud låte dig vara sig behagelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Men Konungen sade till Arauna: Icke så, utan jag vill köpa dig det af för penningar; ty jag vill icke göra Herranom minom Gud bränneoffer, det jag till gifvins hafver. Alltså köpte David ladona, och oxarna, för femtio siklar silfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Och byggde dersammastäds Herranom ett altare; och offrade bränneoffer, och tackoffer. Och Herren vardt landena försonad, och plågan vände åter på Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Och då Konung David var gammal, och väl till ålders kommen, kunde han icke varda varm, ändå man höljde honom med kläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Då sade hans tjenare till honom: Låt dem söka minom herra Konungenom en pigo, en jungfru som står för Konungenom, och sköter honom, och sofver i hans famn, och värmer min herra Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Och de sökte upp en dägelig pigo i alla Israels gränsor, och funno Abisag af Sunem, och hade henne till Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Och hon var en ganska dägelig piga, och hon skötte Konungen, och tjente honom; men Konungen kände henne intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Men Adonia, Haggiths son, hof sig upp, och sade: Jag vill vara Konung; och gjorde sig vagnar och resenärar, och femtio män till drabanter för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Och hans fader bekymrade honom intet i sinom tid, så att han sade: Hvi gör du så? Och han var ock en dägelig man; och han hade födt honom näst efter Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Och han hade sitt råd med Joab, ZeruJa son, och med AbJathar Presten; de hulpo Adonia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Men Presten Zadok, och Benaja, Jojada son, och Nathan Propheten, och Simei, och Rei, och de Davids hjeltar, voro icke med Adonia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Och då Adonia offrade får, och oxar, och gödd boskap, vid den stenen Soheleth, som låg vid den brunnen Rogel, böd han alla sina bröder Konungens söner, och alla Juda män Konungens tjenare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Men den Propheten Nathan, och Benaja, och de hjeltar, och Salomo, sin broder, böd han intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Då sade Nathan till BathSeba, Salomos moder: Hafver du icke hört, att Adonia, Haggiths son, är Konung vorden, och vår herre David vet intet deraf?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Så kom nu, jag vill gifva dig ett råd, att du må undsätta dina och dins sons Salomos själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Bort, och gack in till Konungen David, och säg till honom: Hafver du icke, min herre Konung, svorit, och sagt dina tjenarinno: Din son Salomo skall vara Konung efter mig, och han skall sitta på minom stol; hvi är då Adonia Konung vorden?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Si, medan du ännu der är, och talar med Konungenom, vill jag komma in efter dig, och fullkomna ditt tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Och BathSeba gick in till Konungen i kammaren; och Konungen var ganska gammal; och Abisag af Sunem tjente Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Och BathSeba böjde sig, och tillbad Konungen. Konungen sade: Hvad vill du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Hon sade till honom: Min Herre, du hafver svorit dine tjenarinno vid Herran din Gud: Din son Salomo skall vara Konung efter mig, och sitta på minom stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Men nu, si, Adonia är Konung vorden; och min herre Konungen vet intet deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Han hafver offrat oxar, och gödd boskap, och mång får, och hafver budit alla Konungens söner; dertill AbJathar Presten, och Joab härhöfvitsmannen; men din tjenare Salomo hafver han intet budit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Men du äst min herre Konung; hela Israels ögon se på dig, att du skall gifva dem före, ho som skall sitta på mins herras Konungens stol efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'När nu min herre Konungen med sina fader afsomnad är, så måste jag och min son Salomo syndare vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Medan hon ännu talade med Konungenom, kom Propheten Nathan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Och de sade Konungenom till: Si, Propheten Nathan är der. Och som han kom in för Konungen, tillbad han Konungen på sitt ansigte neder till jordena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Och sade: Min herre Konung, hafver du sagt: Adonia skall vara Konung efter mig, och sitta på minom stol?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Ty han är i dag nedergången, och hafver offrat oxar, och gödd boskap, och mång får, och hafver budit alla Konungens söner, och höfvitsmännerna, dertill Presten AbJathar; och si, de äta och dricka för honom, och säga: Lycka ske Konungenom Adonia!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Men mig din tjenare, och Zadok Presten, och Benaja, Jojada son, och din tjenare Salomo, hafver han intet budit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Är det så af minom herra Konungenom befaldt, och du hafver det din tjenare icke veta låtit, hvilken uppå mins herras Konungens stol efter honom sitta skall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Konung David svarade, och sade: Kaller mig BathSeba. Och hon kom in för Konungen; och då hon stod för Konungenom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Svor Konungen, och sade: Så sant som Herren lefver, som min själ förlossat hafver utur alla nöd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Jag vill i dag göra, såsom jag dig vid Herran Israels Gud svorit hafver, och sagt: Salomo din son skall vara Konung efter mig, och han skall sitta på minom stol för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Då böjde sig BathSeba med sitt anlete neder till jordena, och tillbad Konungen, och sade: Lycka minom herra Konung David i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Och Konung David sade: Kaller mig Presten Zadok, och Propheten Nathan, och Benaja, Jojada son. Och då de kommo in för Konungen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Sade Konungen till dem: Tager med eder edars herras tjenare, och sätter min son Salomo uppå mina mulo, och förer honom ned till Gihon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Och Presten Zadok, samt med Propheten Nathan, smörje honom der till Konung öfver Israel; och blåser med basuner, och säger: Lycka ske Konung Salomo!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Och drager med honom upp, och kommer, så skall han sitta på minom stol, och vara Konung för mig; och jag vill bjuda honom, att han skall vara en Förste öfver Israel och Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Då svarade Benaja, Jojada son, Konungenom, och sade: Amen; det säge också Herren, mins herras Konungens Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Såsom Herren hafver varit med min herra Konungenom, så vare han ock med Salomo, att hans stol må större varda än mins herras Konung Davids stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Då gingo Presten Zadok och Propheten Nathan, och Benaja, Jojada son, och Crethi och Plethi, neder, och satte Salomo på Konung Davids mulo, och förde honom till Gihon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Och Presten Zadok tog oljohornet utu tabernaklet, och smorde Salomo; och de blåste med basuner, och allt folket sade: Lycka ske Konung Salomo!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Och allt folket drog upp efter honom, och folket pipade med pipor, och var ganska gladt, så att det skall i markene utaf deras skri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Och Adonia hörde det, och alle de budne som med honom voro, och de hade allaredo ätit; och då Joab hörde basunens ljud, sade han: Hvart vill det skriet och bullret i stadenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Som han ännu talade, si, då kom Jonathan, AbJathars Prestens son; och Adonia sade: Kom härin; ty du äst en dugelig man, och bär god tidende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonathan svarade, och sade till Adonia: Ja, vår herre Konung David hafver gjort Salomo till Konung;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Och hafver sändt med honom Presten Zadok, och Propheten Nathan, och Benaja, Jojada son, och Crethi och Plethi; och de hafva satt honom på Konungens mulo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Och Presten Zadok, med Propheten Nathan hafver smort honom till Konung i Gihon; och de äro uppdragne dädan med fröjd, så att staden sorlar; det är det skri, som I hört hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Dertill sitter Salomo på Konungastolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Och Konungens tjenare hafva ingångit till att välsigna vår herra Konung David, och hafva sagt: Din Gud göre Salomo ett bättre namn än ditt namn är, och göre hans stol större än din stol; och Konungen hafver tillbedit, der han låg på sängene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Och Konungen hafver så sagt: Lofvad vare Herren Israels Gud, som i dag hafver låtit en sitta på minom stol, så att min ögon det sett hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Då vordo förskräckte och stodo upp alle de som när Adonia budne vore, och gingo bort, hvar och en sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Men Adonia fruktade sig för Salomo, och stod upp, och gick bort, och fattade hornen af altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Och Salomo vardt sagdt: Si, Adonia fruktar för Konung Salomo; och si, han fattar altarets horn, och säger: Konung Salomo svärje mig i dag, att han icke dräper sin tjenare med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomo sade: Vill han vara redelig, så skall icke ett hår af honom falla på jordena; men varder något ondt befunnet med honom, så skall han dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Och Konung Salomo sände bort, och lät hemta honom neder ifrån altaret; och då han kom, tillbad han Konung Salomo; men Salomo sade till honom: Gack i ditt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Som nu tiden led, att David skulle dö, böd han sinom son Salomo, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Jag går alla verldenes väg; så var nu tröst, och var en man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Och akta på Herrans dins Guds vakt, så att du vandrar i hans vägar, och håller hans seder, bud, rätter, vittnesbörd, såsom skrifvet är i Mose lag; på det du skall vara klok i allt det du gör, och ehvart du dig vänder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'På det Herren skall uppväcka sitt ord, som han öfver mig talat hafver och sagt: Om din barn bevara sina vägar, så att de vandra troliga, och af allt hjerta och af allo själ, för mig, så skall aldrig fattas af dig en man på Israels stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Och vetst du väl hvad Joab, ZeruJa son, hafver gjort mig, hvad han gjorde de två härhöfvitsmän i Israel, Abner, Ners son, och Amasa, Jethers son, hvilka han drap, och utgöt krigsblod i fridenom, och lät komma krigsblod uppå sitt bälte, det omkring hans länder var, och uppå sina skor, som på hans fötter voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Gör efter dina vishet, så att du icke förer hans grå hår med frid ned till helvete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Och Barsillai barnom, den Gileaditens, skall du bevisa barmhertighet, så att de äta vid ditt bord; förty de gåfvo sig till mig, då jag flydde för dinom broder Absalom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Och si, du hafver Simei när dig, Gora son, Jemini sons af Bahurim, den mig skamliga bannade, på den tid jag gick till Mahanaim; men han kom neder emot mig vid Jordan; då svor jag honom vid Herran, och sade: Jag vill icke dräpa dig med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Men låt icke du blifva honom oskyldig; ty du äst en vis man, och vetst väl hvad du honom göra skall, att du låter hans grå hår med blod komma neder till helvete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Så afsomnade då David med sina fäder, och vardt begrafven uti Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Men tiden, som David hade varit Konung öfver Israel, var fyratio är. I sju är var han Konung i Hebron, och tre och tretio år i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Och Salomo satt på sins faders Davids stol, och hans rike vardt storliga befäst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Men Adonia, Haggiths son, kom in till BathSeba, Salomos moder; och hon sade: Kommer du ock med frid? Han sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Och han sade: Jag hafver något tala med dig. Hon sade: Säg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Han sade: Du vetst, att riket var mitt; och hela Israel hade vändt sitt ansigte till mig, att jag skulle vordit Konung; men nu är riket förvändt, och vordet mins broders; af Herranom är det hans vordet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nu beder jag en bön af dig låt icke mitt ansigte komma till blygd. Hon sade till honom: Säg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Han sade: Tala med Konungen Salomo, ty han låter icke ditt ansigte komma till blygd, att han gifver mig Abisag af Sunem till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'BathSeba sade: Väl; jag vill på dina vägnar tala till Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Och BathSeba kom in till Konung Salomo, till att tala med honom, på Adonia vägnar. Och Konungen stod upp, och gick emot henne, och tillbad henne, och satte sig på sin stol; och för Konungens moder vardt ock satt en stol, så att hon satte sig på hans högra sido.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Och hon sade: Jag beder en liten bön af dig; låt icke mitt ansikte komma till blygd. Konungen sade till henne: Bed, min moder; jag vill icke låta ditt ansigte komma till blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Hon sade: Låt gifva Abisag af Sunem dinom broder Adonia till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Då svarade Konung Salomo, och sade till sina moder: Hvi beder du om Abisag af Sunem till Adonia? Bed honom ock riket med; förty han är min äldste broder, och han hafver Presten AbJathar och Joab, ZeruJa son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Och Konung Salomo svor vid Herran och sade: Gud göre mig det och det, Adonia skall detta hafva talat emot sitt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Och nu, så visst som Herren lefver, den mig stadfäst hafver, och låtit sitta på mins faders Davids stol och den mig ett hus gjort hafver, såsom han sagt hafver; i dag skall Adonia dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Och Konung Salomo sände bort Benaja, Jojada son; han slog honom, så att han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Och till Presten AbJathar sade Konungen: Gack bort till Anathoth till din åker, ty du hörer döden till; men jag vill icke dräpa dig i dag; förty du hafver burit Herrans Herrans ark för minom fader David, och hafver med lidit, hvad som helst min fader lidit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Alltså fördref Salomo AbJathar, att han icke måtte blifva Herrans Prest; på det Herrans ord fullbordas skulle, som han öfver Eli hus talat hade i Silo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Och detta ryktet kom för Joab; ty Joab höll sig intill Adonia, ehuruväl han icke hade hållit sig till Absalom. Då flydde Joab in uti Herrans tabernakel, och fattade hornen af altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Och det vardt bådadt Konung Salomo, att Joab var flydd uti Herrans tabernakel, och si, han står vid altaret. Då sände Salomo Benaja, Jojada son, och sade: Gack, och slå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Och då Benaja kom till Herrans tabernakel, sade han till honom: Så säger Konungen: Gack härut. Han sade: Nej, här vill jag dö. Och Benaja sade detta Konungenom igen, och sade: Så hafver Joab sagt, och så hafver han svarat mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Konungen sade till honom: Gör såsom han sagt hafver, och slå honom, och begraf honom, att du ifrå mig och mins faders hus tager det blod, som Joab oförskyldt utgjutit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Och Herren betale honom hans blod uppå hans hufvud, att han hafver slagit två män, de der redeligare och bättre voro än han; och hafver dräpit dem med svärd, så att min fader David deraf intet visste, nämliga Abner, Ners son, den härhöfvitsmannen öfver Israel, och Amasa, Jethers son, härhöfvitsman öfver Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Så att deras blod må betaldt varda på Joabs hufvud, och hans säds, i evig tid. Men David och hans säd, hans hus och hans stol, hafve frid af Herranom i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Och Benaja, Jojada son, gick upp, och slog honom, och drap honom; och han vardt begrafven i sitt hus i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Och Konungen satte Benaja, Jojada son, i hans stad öfver hären; och Zadok Presten satte Konungen i AbJathars stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Och Konungen sände bort, och lät kalla Simei, och sade till honom: Bygg dig ett hus i Jerusalem, och bo der, och gack intet ut dädan, antingen hit eller dit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'På hvilken dag du der utgår, och går öfver den bäcken Kidron, så vet att du skall döden dö; ditt blod vare på ditt hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei sade till Konungen: Det är en god mening; såsom min herre Konungen sagt hafver, så skall din tjenare göra. Så bodde Simei i Jerusalem i långan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Men det begaf sig efter tre år, att två tjenare lupo ifrå Simei till Achis, Maacha son, Konungen i Gath. Och Simei vardt sagdt: Si, dine tjenare äro i Gath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Då stod Simei upp, och sadlade sin åsna, och drog åstad till Gath till Achis, att han skulle söka sina tjenare; och då han ditkom, förde han sina tjenare ifrå Gath. Och Konungen böd Benaja, Jojada son. Han gick ut, och slog honom, att han blef död. Och riket vardt befäst i Salomos hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Och det vardt sagdt Salomo, att Simei var faren af Jerusalem till Gath, och igen kommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Då sände Konungen bort, och lät kalla Simei, och sade till honom: Hafver jag icke svorit dig vid Herran, och betygat dig, och sagt: På hvilken dag du fore ut, antingen hit eller dit, att du då veta skulle att du skulle döden dö? Och du sade till mig: Jag: hafver hört en god mening.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Hvi hafver du då icke hållit dig efter Herrans ed, och det bud som jag dig budit hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Och Konungen sade till Simei: Du vetst allt det onda, som ditt hjerta med sig vet, som du minom fader David gjort hafver; Herren hafver betalat dina ondsko på ditt hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Och Konung Salomo är välsignad, och Davids stol varder befäst för Herranom i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Och Salomo befryndade sig med Pharao, Konungenom i Egypten, och tog Pharaos dotter, och förde henne uti Davids stad, tilldess han skulle fullbygga sitt hus, och Herrans hus, och muren omkring Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Men folket offrade ännu på höjdomen; ty det var ändå intet hus bygdt Herrans Namne, intill den tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Men Salomo hade Herran kär, och vandrade efter sins faders Davids seder; undantagno att han offrade, och rökte uppå höjdomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Och Konungen gick bort till Gibeon, till att offra der; ty der var en härlig höjd; och Salomo offrade tusende bränneoffer på det samma altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Och Herren syntes Salomo i Gibeon, uti en dröm om nattene. Och Gud sade: Bed hvad jag skall gifva dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo sade: Du hafver gjort med min fader David din tjenare stora barmhertighet, såsom han vandrade för dig i sanning och rättfärdighet, och med ett rättsinnigt hjerta när dig; och du hafver hållit honom denna stora barmhertigheten, och gifvit honom en son, som på hans stol sitta skulle, såsom nu tillgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nu, Herre min Gud, du hafver gjort din tjenare till Konung i mins faders Davids stad; så är jag en ung dräng, och vet icke min utgång eller ingång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Och din tjenare är ibland ditt folk, som du utvalt hafver, det så mycket är, att det ingen räkna eller beskrifva kan, för myckenhets skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Så gif nu dinom tjenare ett lydaktigt hjerta, att han må döma ditt folk, och förstå hvad godt och ondt är; ty ho förmår döma detta ditt mägtiga folk?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Då täcktes det Herranom väl, att Salomo bad om sådant.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Och Gud sade till honom: Efter du detta beddes, och bad icke om långt lif eller rikedomar, eller om dina fiendars själar, utan om förstånd till att döma,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Si, så hafver jag gjort efter din ord; si, jag hafver gifvit dig ett vist och förståndigt hjerta, så att din like hafver icke varit för dig, och icke heller efter dig uppkomma skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Dertill det du icke bedit hafver, det hafver jag också gifvit dig, nämliga rikedomar och härlighet; så att ingen skall vara din like ibland Konungarna i dina dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Och om du vandrar i mina vägar, så att du håller mina seder och bud, såsom din fader David vandrat hafver, så vill jag gifva dig långt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Och då Salomo vaknade, si, då var det en dröm; och han kom till Jerusalem, och gick fram för Herrans förbunds ark, och offrade bränneoffer och tackoffer; och gjorde ett stort gästabåd allom sinom tjenarom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'På den tiden kommo två skökor för Konungen, och gingo fram för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Och den ena qvinnan sade: Ack! min Herre, jag och denna qvinnan bodde uti ett hus, och jag födde när henne i huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Och efter tre dagar, sedan jag födt hade, födde hon och; och vi voro tillhopa, så att ingen främmande var med oss i huset, utan vi båda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Och denna qvinnones son blef död om nattena; ty hon förkramade honom i sömnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Och hon stod upp om nattena, och tog min son ifrå mine sido, vid din tjenarinna sof, och lade honom på sin arm; och sin döda son lade hon på min arm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Och då jag om morgonen uppstod, till att gifva min son dia, si, då var han död; men om morgonen såg jag granneliga på honom, och si, det var icke min son, den jag födt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Den andra qvinnan sade: Det är icke så; min son lefver, och din son är död. Men denna sade: Det är icke så; din son är död, och min son lefver; och talade alltså för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Och Konungen sade: Denna säger: Min son lefver, och din son är död; den andra säger: Icke så; din son är död, och min son lefver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Och Konungen sade: Tager mig hit ett svärd. Och då svärdet var buret fram till Konungen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Sade Konungen: Hugger det lefvande barnet i tu stycker, och gifver desso hälftena; och den andro ock hälftena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Då sade qvinnan, hvilkens barn lefde, till Konungen (ty hennes moderliga hjerta gaf sig öfver sin son): Ack! min Herre, gifver henne barnet lefvandes, och dräper det icke. Men den andra sade: Det vare hvarken mitt eller ditt, låt skiftat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Då svarade Konungen, och sade: Gifver desso barnet lefvandes, och dräper det icke; hon är dess moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Och den domen, som Konungen afsagt hade, spordes för hela Israel, och de fruktade Konungen; förty de sågo, att Guds vishet var i honom till att döma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Alltså vardt Salomo Konung öfver hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Och desse voro hans Förstar: AsarJa, Zadoks son, Prestens,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph och AhiJa, Sisa söner, voro skrifvare; Josaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, Jojada son, var härhöfvitsman; Zadok och AbJathar voro Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'AsarJa, Nathans son, var öfver ämbetsmännerna; Sabud, Nathans son, Prestens, var Konungens vän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar var hofmästare; Adoniram, Abda son, var räntomästare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Och Salomo hade tolf befallningsmän öfver hela Israel, som försörjde Konungen och hans hus; hvar hade en månad om året till att försörja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Och de heto alltså: Hurs son på Ephraims berg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekers son i Makaz, och i Saalbim, och i BethSemes, och i Elon BethHanan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Heseds son i Aruboth, och hade dertill Socho, och hela landet Hepher;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'AbiNadabs son hela landet Dor; och hade Taphath, Salomos dotter, till hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, Ahiluds son, i Taanach, och i Megiddo, och öfver hela BethSean, hvilket ligger vid Zarthana under Jisreel, ifrå BethSean intill den planen Mehola, intill hinsidon Jokmeam;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Gibers son i Ramoth i Gilead; och hade de städer Jairs, Manasse sons, i Gilead; och hade den ängden Argob, som i Basan ligger, sextio stora städer murade, och med kopparbommar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, Iddo son, i Mahanaim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaaz i Naphthali; och han tog också Basmath, Salomos dotter, till hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, Husai son, i Asser och i Aloth;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jasaphat, Paruahs son, i Isaschar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, Ela son, i BenJamin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, Uri son, i Gileads land, i Sihons, de Amoreers Konungs land; och Ogs, Konungens i Basan; en befallningsman var i de samma landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Men Juda och Israel voro månge, såsom sanden i hafvet, och de åto och drucko, och voro glade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Alltså var Salomo en herre öfver all rike, ifrån älfvene intill de Philisteers land, och allt intill de Egyptiers gränso; hvilke honom förde skänker, och tjente honom i hans lifstid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Och Salomo måste dagliga hafva till spisning tretio corer semlomjöl, sextio corer annat mjöl,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Tio gödda oxar, och tjugu oxar af betene, och hundrade får; förutan hjort och rå, stengetter, och hvad man på stall höll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Ty han var rådandes i hela landena, på denna sidon älfven, ifrå Tiphsah allt intill Gasa, öfver alla de Konungar på denna sidon älfven; och hade frid med alla sina grannar allt omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Så att Juda och Israel bodde trygge, hvar och en under sitt vinträ, och under sitt fikonaträ, ifrå Dan allt intill BerSeba, så länge Salomo lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Och Salomo hade fyratiotusend vagnhästar, och tolftusend resenärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Och befallningsmännerna försörjde Konung Salomo, och allt det som till Konungens bord hörde, hvar och en i sin månad; och läto intet fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Sammalunda ock korn, och halm för hästar och mular, förde de dit som han var, hvar och en efter som honom befaldt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Och Gud gaf Salomo ganska stor visdom och förstånd, och ett fritt mod, såsom sanden som ligger på hafsens strand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Så att Salomos visdom var större, än alla österländningabarnas, och alla Egyptiers visdom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Och var visare än alla menniskor, och visare än Ethan den Esrahiten, Heman, Chalchol och Darda, Mahols söner; och var namnkunnig ibland alla Hedningar allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Och han talade tretusend ordspråk; och hans visor voro tusende och fem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Och han talade om trä, ifrå ceder, som är i Libanon, allt intill isop, som växer utu väggene; desslikes talade han om djur, om foglar, om matkar, om fiskar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Och utaf all folk kommo till att höra Salomos visdom, ifrån alla Konungar på jordene, som af hans visdom hört hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Och Hiram, Konungen i Tyro, sände sina tjenare till Salomo; ty han hade hört, att de hade smort honom till Konung i hans faders stad; ty Hiram älskade David så länge han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Och Salomo sände till Hiram, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Du vetst, att min fader David icke kunde bygga Herrans sins Guds Namne ett hus, för örligs skull, som allt omkring honom var, intilldess Herren gaf dem under hans fotbjelle;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Men nu hafver Herren min Gud gifvit mig rolighet allt omkring, så att ingen motståndare, eller ondt hinder mer på färde är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Si, så hafver jag tänkt bygga ett hus, Herrans mins Guds Namne, såsom Herren talat hafver till min fader David, och sagt: Din son, som jag i din stad sätta skall på din stol, han skall bygga mino Namne hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Så befall nu, att man hugger mig ceder utu Libanon, och att dine tjenare äro med mina tjenare, och dina tjenares lön vill jag gifva dig, allt såsom du säger; ty du vetst, att när oss är ingen som kan hugga trä, såsom de Zidonier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Då Hiram hörde Salomos ord, fröjdade han sig storliga, och sade: Lofvad vare Herren i denna dag, som hafver gifvit David en visan son öfver detta myckna folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Och Hiram sände till Salomo, och lät säga honom: Jag hafver hört det du till mig sändt hafver; jag vill göra efter allt ditt begär med ceder och furoträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Mine tjenare skola föra dem neder af Libanon ut till hafvet; och jag vill låta lägga dem i flottor på hafvet, intill det rum som du mig föresägandes varder, och vill lossa dem der, och du skall låta hemta dem; men du skall ock göra mitt begär, och gifva mino folke kost.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Alltså gaf Hiram Salomo ceder och furoträ, efter allt hans begär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Och Salomo gaf Hiram tjugutusend corer hvete till kost för hans folk, och tjugu corer stött oljo; detta gaf Salomo Hiram årliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Och Herren gaf Salomo visdom, såsom han honom sagt hade; och var frid emellan Hiram och Salomo, och de gjorde både ett förbund med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Och Salomo böd uppå en utgärd öfver hela Israel; och i utgärdene voro tretiotusend män;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Och sände uppå Libanon, ju i hvarje månad tiotusend; så att de voro en månad på Libanon, och två månader hemma; och Adoniram var öfver den utgärden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Och Salomo hade sjutiotusend, de som båro bördor, och åttatiotusend, de som höggo på bergena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Förutan de öfversta Salomos befallningsmän, som öfver verket satte voro; nämliga tretusend och trehundrad, hvilke rådde öfver folket som arbetade på verket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Och Konungen; böd, att de skulle bryta ut stora och kosteliga stenar; nämliga huggna stenar, till husets grundval.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Och Salomos byggningsmän, och Hirams byggningsmän, och de som vid gränsona voro, höggo ut, och tillredde trä och stenar till husets byggning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Uti fjerde hundrade och åttationde årena, sedan Israels barn drogo utur Egypti land, i fjerde årena, sedan Salomo vardt rådandes öfver Israel, uti den månaden Sif, det är den andra månaden, vardt huset bygdt Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Och huset, som Konung Salomo byggde Herranom, var sextio alnar långt, tjugu alnar bredt, och tretio alnar högt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Och byggde ett förhus för templet, tjugu alnar långt, efter husets bredd, och tio alnar bredt, frammanför huset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Och gjorde fenster på huset, de man upp och åter låta kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Och han byggde en omgång på väggene af huset allt omkring, så att han gick både omkring templet och choren, och gjorde hans yttra vägg omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Den nederste gången var fem alnar bred, och den medlersta sex alnar bred, och den tredje sju alnar bred; ty han lade bjelkar utan omkring huset, så att de icke skulle gå in i väggena på huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Och då huset byggdes, vardt det bygdt af helom stenom, såsom de framförde voro; så att man intet hörde någon hammar, eller yxe, eller någon jernredskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Och en dörr var på högra sidone midt på husena, så att man uppgick genom en vindsten upp i den medelgången; och ifrå medelgången upp till den tredje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Alltså byggde han huset, och fullkomnade det, och bedrog huset med ceder, både ofvan och på väggarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Han byggde ock en gång ofvanpå hela huset omkring, fem alnar hög, och täckte huset med cedreträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Och Herrans ord kom till Salomo, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Det vare det hus, som du bygger; om du vandrar i min bud, och gör efter mina rätter, och håller all min bud, till att vandra deruti, så vill jag stadfästa min ord med dig, såsom jag dinom fader David sagt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Och vill bo ibland Israels barn, och skall icke öfvergifva mitt folk Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Alltså byggde Salomo huset, och fullkomnade det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Och byggde väggarna af huset innantill på sidomen af ceder, ifrå husets golf allt upp till taket; och bedrog med trä innantill, och telde golfvet på huset med furobräder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Och han byggde bak i husena en cedervägg, tjugu alnar lång, ifrå golfvet allt inunder taket, och byggde derinne choren och det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Men templets hus utanför chorenom var fyratio alnar långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Innantill var hela huset alltsamman af ceder, med svarfvade knappar och blomverk, så att man ingen sten såg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Men choren gjorde han innantill i husena, att man skulle derinne sätta Herrans förbunds ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Och för chorenom, den tjugu alnar lång, tjugu alnar bred, och tjugu alnar hög, och med klart guld bedragen var, bedrog han altaret med ceder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Och Salomo bedrog huset innantill med klart guld, och satte gyldene bommar för choren, som han med guld bedragit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Så att hela huset alltsammans med guld bedraget var. Dertill bedrog han ock hela altaret för choren allt öfver med guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'I Han gjorde ock i chorenom två Cherubim, tio alnar höga, utaf olivoträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Fem alnar höll hvar vingen af hvar Cherub, så att tio alnar voro ifrån andanom af den ena vingan, intill ändan på hans andra vinga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Alltså höll den andre Cherub ock tio alnar; och var lika mått och lika rum åt båda Cherubim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Så att hvar Cherub var tio alnar hög.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Och han satte de Cherubim innan i huset; och Cherubim räckte ut vingarna, så att ensderas vinge kom intill denna väggena; och dens andras Cherubs vinge kom intill den andra väggena; med midt i huset kom den enes vinge intill den andras.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Och han bedrog de Cherubim med guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Och på alla husets väggar allt omkring lät han göra snidverk med utskorna Cherubim, palmar och blomverk, innan och utan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Och bedrog han golfvet af huset med gyldene skifvor, innan och utan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Och i chorens ingång gjorde han två dörrar af olivoträ, med femhörnad dörrträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Och lät göra snidverk deruppå af Cherubim, palmar och blomverk, och öfverdrog dem med gyldene skifvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Alltså gjorde han ock i templets ingång fyrahörnad dörrträ af olivoträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Och två dörrar af furoträ, så att hvar dörren var i två delar, som tillhopahängde på deras hängsler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Och han gjorde deruppå snidverk af Cherubim, palmar och blomverk, och öfverdrog dem med guld, allt såsom det befaldt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Och han byggde desslikes en gård derinne af tre radar huggen sten, och af en rad höflad ceder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Uti fjerde årena i den månaden Sif vardt grundvalen lagd till Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Och i ellofte årena i den månaden Bul, det är den åttonde månaden, vardt huset redo, som det vara skulle, så att de byggde der i sju år uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Men uppå sitt hus byggde Salomo i tretton år, förr än det allt fullbygdt var, nämliga:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Han byggde ett hus af Libanons skog, hundrade alnar långt, femtio alnar bredt, och tretio alnar högt. På det samma fyrhörnada lade han bottnen af cedrebräde, på cedrestodar å rad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Och der ofvanuppå en sal af ceder på samma stodar, hvilka voro fem och fyratio, ju femton i hvar rad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Och voro fenster efter de tre radarna, tvärtemot hvartannat, tre emot tre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Och voro i deras bågar fyrahörnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Han byggde ock ett förhus med stodar, femtio alnar långt, och tretio alnar bredt; och ändå ett förhus för desso, med stodar och tjocka, bjelkar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Och byggde desslikes ett förhus till domstolen, der man rättgång uti hålla skulle, och telde båda bottnarna med cedreträ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Dertill sitt hus, der han uti bodde, i bakgårdenom bak vid förhuset, gjordt såsom de andra. Och gjorde han också ett hus såsom förhuset till Pharaos dotter, den Salomo till hustru tagit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Allt detta voro kostelige stenar huggne efter mått, och med såg skorne på alla sidor, ifrå grundvalen allt upp till taket; dertill ock utantill den store gården.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Grundvalarne voro af kosteliga och stora stenar, tio och åtta alnar stora;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Och deruppå kostelige huggne stenar efter mått, och ceder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Men den store gården omkring hade tre radar huggen sten, och en rad af cedrebräde. Sammalunda ock gården till Herrans hus innantill, och förhuset till huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Och Konung Salomo sände bort, och lät hemta Hiram af Tyro,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Ene enkos son af Naphthali slägte, och hans fader hade varit en man af Tyro; han var en mästare på koppar, full med visdom, förstånd och konst, till att arbeta allahanda kopparverk. Då han kom till Konung Salomo, gjorde han allt hans verk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Och gjorde två kopparstodar, hvardera aderton alnar hög; och en tråd, tolf alnar lång, var måttet omkring hvarjo stodena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Och gjorde två knappar, gjutna af koppar, till att sätta ofvanpå stoderna; och hvar knappen var fem alnar hög:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Och på hvar knappen ofvanpå stoderna sju flätade gjordar såsom kedjor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Och gjorde till hvar knappen två radar granatäple omkring, till ena gjord, der knappen med öfvertäckt vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Och knapparna voro såsom roser för förhusena, fyra alnar store.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Och de granatäplen i radarna omkring voro tuhundrad, ofvan och under på gjorden, som gick midt om knappen, om hvar knapp på båda stoderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Och han uppreste de stoderna inför förhusena af templet, och den som han satte på högra sidon, kallade han Jachin; och den som han satte på venstra sidon, kallade han Boas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Och det stod ofvanpå stoderna såsom roser. Alltså vardt fullkomnadt de stoders verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Och han gjorde ett haf gjutet, tio alnar bredt, ifrå den ena bräddene till den andra, rundt omkring; och fem alnar högt, och måttet rätt omkring var tretio alnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Och om det samma hafvet, det tio alnar bredt var, gick en krusering utmed dess brädd, allt omkring hafvet; den kruseringen var gjuten i två radar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Och det stod på tolf oxar; tre af dem vände sig norrut, tre vesterut, tre söderut, och tre österut; och hafvet der ofvanuppå; så att all bakdelen af dem var inunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Tjockheten af thy var en tvärhand; och brädden deruppå var såsom brädden på en bägare, såsom en utsprungen ros; och tutusende bath gick deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Han gjorde ock tio kopparstolar; hvardera fyra alnar lång och bred, och tre alnar hög.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Och var stolen så gjord, att han hade sidor emellan listor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Och på sidomen emellan listorna voro lejon, oxar och Cherubim, och sidorna, der lejonen, oxarna och Cherubim voro uppå, hade listor ofvan och nedan, och fötter deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Och hvar stolen hade fyra kopparhjul med kopparaxlar. Och uppå fyra hörnen voro gjutna styltor, hvar emot den andra stödjandes under kettilen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Men halsen midt på stolen var en aln hög och trind; half annan aln bred, och på halsenom voro bulor i planarna, hvilke fyrkant voro, och icke runde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Men de fyra hjul stodo nedan under sidorna, och axlarna åt hjulen voro vid stolen; hvart hjulet var halfannor aln högt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Och voro hjul såsom vagnshjul; och deras axlar, naf, ekrar och löter, voro allt gjutne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Och de fyra styltor, på de fyra hörnen af hvar stolen, voro ock alla fasta vid stolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Och på halsenom, ofvanuppå stolen en half aln högt allt omkring, voro listor och sidor på stolenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Och han lät grafva på det slätt var, på samma sidor och listor, Cherubim, lejon och palmträ, det ena efter det andra allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Vid det sättet gjorde han de tio gjutna stolar; enahanda mått och rum var på dem allom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Och han gjorde tio kopparkettlar, så att fyratio bath gingo uti hvar kettilen; och den var fyra alnar stor, och på hvar stol var en kettil.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Och han satte fem stolar på högra sidone i huset, och de andre fem på venstra; men hafvet satte han rätt framföre på högra sidone, söderut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Och Hiram gjorde desslikes grytor, skoflar, bäcken; och fullkomnade så all verk, som Konung Salomo göra lät i Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Nämliga de två stoder, och de två runda knappar ofvanuppå de två stodar, och de två vridna gjordar, till att betäcka de två runda knappar på stoderna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Och de fyrahundrad granatäple på de två vridna gjordar, ju två rader granatäple på en gjord, till att betäcka de två runda knapparna på stoderna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Dertill de tio stolar, och de tio kettlar der ofvanuppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Och hafvet, och de tolf oxar under hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Och de grytor, skoflar och bäcken; och all denna kärilen, som Hiram gjorde åt Konung Salomo till Herrans hus, voro utaf klar koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'I den ängden vid Jordan lät Konungen gjuta dem, i den lermarkene emellan Succoth och Zarthan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Och Salomo lät all dessa kärilen ovägne blifva; derföre att kopparen var så mycken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Och gjorde Salomo all tyg, som Herrans hus tillhörde; nämliga ett gyldene altar, ett gyldene bord, der skådobröd på ligga skulle;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Fem ljusastakar på högra, och fem ljusastakar på den venstra sidone, framför choren, af klart guld, med gyldene blommor, lampor och ljusanäpor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Dertill skålar, fat, bäcken, skedar och pannor, af klart guld. Och voro dörrahängslorna på dörrarna åt innersta huset, som var det aldrahelgasta, och åt templets husdörr, af guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Alltså vardt fullkomnadt allt verk, som Konung Salomo gjorde till Herrans hus. Och Salomo bar ditin det som hans fader David helgat hade, af silfver och guld, och käril, och lade det in uti Herrans hus skatt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Då församlade Konung Salomo till sig de äldsta af Israel, alla öfverstar i slägterna, och Förstar för fäderna ibland Israels barn, till Jerusalem, till att föra Herrans förbunds ark upp utu Davids stad, det är Zion.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Och sig församlade till Konung Salomo alle män i Israel, uti den månaden Ethanim på högtidene, det är sjunde månaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Och då alle äldste i Israel kommo, lyfte Presterna arken upp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Och båro Herrans ark ditupp; dertill vittnesbördsens tabernakel, och all helgedomens tyg, som i tabernaklet var; det gjorde Presterna och Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Och Konung Salomo och hela Israels menighet, som sig till honom församlat hade, gingo med honom fram för arken, och offrade får, och fä, så mycket att man dem hvarken tälja eller räkna kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Alltså båro Presterna Herrans förbunds ark uti sitt rum i husets chor, i det aldrahelgasta, under Cherubims vingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Ty Cherubim räckte vingarna ut till det rum der arken stod, och öfverskylde arken och hans stänger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Och så långa voro stängerna, att deras ändar syntes i helgedomenom för choren; men utantill vordo de intet sedde; och de blefvo der intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Och i arkenom var intet, utan allenast de två Mose stentaflor, som han lät deruti i Horeb, då Herren gjorde ett förbund med Israels barnom, då de utur Egypti land dragne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Då nu Presterna gingo utu helgedomenom, uppfyllde en molnsky Herrans hus,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Så att Presterna icke kunde stå och sköta ämbetet för molnskyn; ty Herrans härlighet uppfyllde Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Då sade Salomo: Herren hafver sagt, att han ville bo i mörkrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Jag hafver byggt ett hus dig till boning; ett säte, att du skall bo der till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Och Konungen vände sitt ansigte, och välsignade hela menighetena Israel, och hela menigheten Israel stod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Och han sade: Lofvad vare Herren Israels Gud, som med sin mun med minom fader David talat, och med sine hand fullbordat hafver, och sagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Ifrå den dag, då jag förde mitt folk Israel utur Egypten, hafver jag ingen stad utvalt i några af Israels slägter, att mig skulle varda ett hus bygdt, så att mitt Namn skulle vara der; men David hafver jag utvalt, att han skall vara öfver mitt folk Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Och min fader David hade väl i sinnet, att han skulle bygga Herrans Israels. Guds Namne ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Men Herren sade till min fader David: Att du hafver i sinnet bygga mino Namne ett hus, hafver du gjort väl, att du hade det i sinnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Dock skall icke du bygga det huset, utan din son, som utaf dina länder komma skall, han skall bygga mino Namne ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Och Herren hafver gjort sitt ord fast, som han talat hafver; ty jag är uppkommen i mins faders Davids stad, och sitter på Israels stol, såsom Herren sagt, och hafver byggt Herrans Israels Guds Namne ett hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Och hafver derutinnan tillpyntat ett rum till arken, som Herrans förbund uti är, det han gjort hafver med våra fäder, då han dem utur Egypti land förde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Och Salomo stod för Herrans altare emot hela Israels menighet, och räckte ut sina händer upp till himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Och sade: Herre Israels Gud, det är ingen Gud, antingen ofvantill i himmelen, eller nedre på jordene, din like; du som håller förbund och barmhertighet dinom tjenarom, som vandra för dig af allo hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Du som hafver hållit dinom tjenare David, minom fader, allt det du honom sagt hafver; med dinom mun hafver du talat det, och med dine hand hafver du fullkomnat det, såsom det nu i denna dag tillgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nu, Herre Israels Gud, håll dinom tjenare David, minom fader, det du med honom talat hafver, och sagt: Dig skall icke fattas en man för mig, som sitta skall på Israels stol; såframt din barn förvara sina vägar, att de vandra såsom du för mig vandrat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nu, Israels Gud, låt din ord blifva sann, som du till din tjenare David, min fader, talat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Ty menar du ock, att Gud bor på jordene? Si, himmelen och alla himlars himlar kunna icke begripa dig; huru skulle då detta huset göra det, som jag nu byggt hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Så vänd dig till dins tjenares bon, och till hans begär, Herre min Gud, så att du hörer det lof, och den bön, som din tjenare gör för dig i dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Att din ögon måga stå öppne öfver detta hus, natt och dag; öfver det rum, der du om sagt hafver: Mitt Namn skall vara der; att du ville höra den bön, som din tjenare gör på detta rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Och ville höra dins tjenares, och dins folks Israels bön, den de här görande varda i detta rum; och höra det der du bor i himmelen; och, när du det hörer, vara nådelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'När nu någor syndar emot sin nästa, och tager dess en ed uppå sig, der han sig med förpligtar, och eden kommer inför ditt altare i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Att du ville då höra i himmelen, och skaffa dina tjenare rätt, att du fördömer den ogudaktiga, och låter hans väg komma öfver hans hufvud; och rättfärdigar den rätta, att du honom gör efter hans rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Om ditt folk Israel vorde slaget för sina fiendar, efter de emot dig syndat hafva; och vända sig till dig, och bekänna ditt Namn, och bedja, och begära af dig i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Att du ville då hörat i himmelen, och dins folks Israels syndom nådelig vara; och föra dem åter i det land, som du deras fäder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Om himmelen igenlyckt varder, så att intet regnar, efter de emot dig syndat hafva; och varda bedjande på detta rum, och bekänna ditt Namn, och vända sig ifrå sina synder, efter du plågar dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Att du ville i himmelen höra dem, och vara dina tjenares, och dins folks Israels synder nådelig; att du visar dem den goda vägen, der de uti vandra skola, och låter regna på landet, som du dino folke till arfs gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Om en hård tid, eller pestilentie, eller torka, eller brand, eller gräshoppor, eller matkar på landet kommande varda; eller deras fiende belägger deras portar i landena, eller någor plåga eller krankhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Den då beder eller begärar, ehvad de äro andra menniskor, eller ditt folk Israel, som förnimma sina plågo, hvar och en i sitt hjerta, och räcka sina händer ut till detta huset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Att du ville då höra i himmelen, i det säte der du bor, och vara nådelig; och fly det så, att du gifver hvarjom och enom såsom han vandrat hafver, såsom du hans hjerta känner; ty du allena känner alla menniskors barnas hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'På det att de skola frukta dig alltid, så länge de lefva i landena, det du våra fäder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Om ock en främmande, som icke är af ditt folk Israel, kommer af fjerran land för ditt Namns skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'Ty de varda hörande om ditt stora Namn, och om dina mägtiga hand, och om din uträckta arm; och kommer till att bedja i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Att du då ville höra i himmelen, i det säte der du bor, och göra allt det den främmande dig om åkallar; på det all folk på jordene måga känna ditt Namn, att de ock frukta dig lika som ditt folk Israel, och förnimma, att detta huset efter ditt Namn nämndt är, det jag byggt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Om ditt folk utdrager i strid emot sina fiendar, den vägen som du dem sändandes varder, och de varda bedjande till Herran, emot vägen till den staden som du utvalt hafver, och emot huset som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Att du då ville höra deras bön och begär i himmelen, och skaffa dem rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Om de varda syndande emot dig; ty det är ingen menniska, som icke syndar; och du varder vred, och gifver dem för deras fiendar, så att de föra dem fångna i fiendaland, fjerran eller när;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Och de besinna sig i sitt hjerta, uti landena der de fångne äro, och omvända sig, och bedja dig uti deras fängelses land, och säga: Vi hafve syndat, och gjort illa, och varit ogudaktige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Och vända sig så till dig af allt hjerta, af allo själ, uti deras fiendars land, som dem bortfört hafva, och bedja till dig emot vägen till deras land, som du deras fäder gifvit hafver, emot den staden som du utvalt hafver, och emot det huset som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Att du då ville höra deras bön och begär i himmelen, af det säte der du bor, och skaffa dem rätt,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Och vara dino folke nådelig, som emot dig syndat hafver, och all deras öfverträdelse, der de med hafva förbrutit sig emot dig; och gifva dem barmhertighet för dem som dem fångna hålla, att de förbarma sig öfver dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Förty de äro ditt folk, och ditt arf, som du utur Egypten, utu jernugnenom fört hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Att din ögon måga öppne vara till dins tjenares och dins folks Israels bön; att du ville höra dem i allt det, der de om åkalla dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Ty du hafver dem dig af skiljt till ett arf utur all folk på jordene, såsom du sagt hafver genom din tjenare Mose, då du våra fäder utur Egypten förde, Herre, Herre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Och då Salomo hade all denna bön och begäran utbedit för Herranom, stod han upp ifrå Herrans altare, och höll upp att böja sin knä, och uträcka sina händer till himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Och stod, och välsignade alla menighetena Israel, med höga, röst, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Lofvad vare Herren, som sino folke Israel ro gifvit hafver, såsom han sagt hafver; icke ett är förfallet af hans goda ord, som han genom sin tjenare Mose talat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Herren vår Gud vare med oss, såsom han varit hafver med våra fäder. Han öfvergifve oss icke, och tage icke handena bort ifrån oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Till att böja vårt hjerta till sig, att vi måge vandra i alla hans vägar, och hålla hans bud, seder och rätter, som han våra fäder budit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Och att desse orden, som jag för Herranom bedit hafver, måtte nalkas Herranom vårom Gud dag och natt, att han må skaffa sinom tjenare rätt, och sino folke Israel, hvarjom och enom i sinom tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'På det att all folk på jordene måga känna, att Herren är Gud, och ingen annar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Och edor hjerta vare rättsinnig med Herranom vårom Gud, till att vandra i hans seder, och till att hålla hans bud, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Och Konungen, samt med hela Israel, offrade offer för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Och Salomo offrade tackoffer, som han Herranom offrade, tu och tjugu tusend oxar, och hundradetusend och tjugutusend får. Alltså vigde de Herrans hus, Konungen och all Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'På samma dagen vigde Konungen medelgården, som var för Herrans hus, dermed att han der uträttade bränneoffer, spisoffer, och det feta af tackoffret; förty kopparaltaret, som för Herranom stod, var för litet till bränneoffer, spisoffer, och till det feta af tackoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Och Salomo gjorde på den tiden en högtid, och all Israel med honom en stor församling, ifrå den gränson Hamath, allt intill Egypti bäck, för Herranom vårom Gud i sju dagar, och åter i sju dagar; det voro fjorton dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Och på åttonde dagen lät han folket gå; och de välsignade Konungen, och gingo sina färde i sina hyddor, glädjandes och fröjdandes sig öfver allt det goda, som Herren med sinom tjenare David, och med sitt folk Israel, gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Och då Salomo hade fullbyggt Herrans hus, och Konungshuset, och allt det hans hjerta begärade, och lust hade till att göra,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Syntes honom Herren annan gång, såsom han honom synts hade i Gibeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Och Herren sade till honom: Jag hafver hört dina bön och begär, som du för mig bedit hafver, och helgat detta huset, som du byggt hafver; så att jag skall sätta der mitt Namn till evig tid, och skola min ögon och mitt hjerta vara der alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Och du, om du vandrar för mig, såsom din fader David vandrat hafver, med rättsinnigt hjerta, och rättfärdighet, så att du gör allt det som jag dig budit hafver, och håller min bud och mina rätter,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Så vill jag befästa dins rikes stol öfver Israel i evig tid, såsom jag med din fader David talat hafver, och sagt: Dig skall icke fattas en man på Israels stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Hvar I ock vänden eder tillbaka ifrå mig, I och edor barn, och icke hållen min bud och rätter, som jag eder föresatt hafver; och gången bort och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Så skall jag utrota Israel ut af det land, som jag dem gifvit hafver; och det huset, som jag mino Namne helgat hafver, skall jag bortkasta ifrå mitt ansigte; och Israel skall vara till ett ordspråk och fabel ibland allt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Och detta huset skall förfalla, så att alle de som gå der framom skola förundra sig, och hvissla, och säga: Hvi hafver Herren desso lande och desso huse så gjort?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Då skall blifva svaradt: Derföre, att de Herran sin Gud öfvergifvit hade, som deras fäder utur Egypti land förde, och tagit sig andra gudar, och tillbedit dem och tjent dem; derföre hafver Herren allt detta onda låtit komma öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Då nu de tjugu år framlidne voro, i hvilko Salomo de tu husen byggde, som var Herrans hus, och Konungshuset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Till hvilket Hiram, Konungen i Tyro, Salomo cedreträ, och furoträ, och guld, efter allt hans begär skickade; då gaf Konung Salomo Hiram tjugu städer i Galilea land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Och Hiram drog utaf Tyro, till att bese de städer, som Salomo honom gifvit hade; och de behagade honom intet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Och sade: Hvad är detta för städer, min broder, som du mig gifvit hafver? Och han kallade dem Cabuls land allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Och Hiram hade sändt Konungenom hundrade och tjugu centener guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Och det är summan af skattenom, som Konung Salomo uppbar, till att bygga Herrans hus, och sitt hus, och Millo, och Jerusalems murar, och Hazor, och Megiddo, och Gaser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Ty Pharao, Konungen i Egypten, var uppkommen, och hade vunnit Gaser, och uppbränt det med eld, och slagit ihjäl de Cananeer, som i staden bodde, och hade gifvit honom sine dotter, Salomos hustru, till en skänk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Alltså byggde Salomo Gaser, och det nedra BethHoron,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Och Baalath, och Thadmor uti öknene, i landet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Och alla kornhusstäder, som Salomo hade, och alla vagnsstäder, och resenärsstäder, och hvad som helst han lust hade till att bygga i Jerusalem, i Libanon, och hela landet, som under hans välde var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Och allt det folket, som igenblef af de Amoreer, Hetheer, Phereseer, Heveer och Jebuseer, som icke voro af Israels barnom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Deras barn, som de läto igenblifva efter sig i landena, hvilka Israels barn icke kunde tillspillogifva, dem gjorde Salomo skattskyldiga allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Men af Israels barnom gjorde han ingen till träl; utan lät dem vara krigsmän och sina tjenare, och Förstar, och riddare, och öfver hans vagnar och resenärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Och de ämbetsmän, som voro öfver Salomos sysslor, voro femhundrad och femtio, som öfver folket rådde, och alla sysslor uträttade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Och Pharaos dotter drog upp ifrå Davids stad, uti sitt hus, som Salomo för henne byggt hade; då byggde han ock Millo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Och Salomo offrade tre resor om året bränneoffer, och tackoffer, på altaret, som han Herranom byggt hade, och rökte derpå för Herranom; och alltså vardt huset redo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Och Salomo gjorde desslikes skepp i EzionGeber, som vid Eloth ligger, på strandene vid det röda hafvet, uti de Edomeers land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Och Hiram sände sina tjenare till skepps, som förstodo sig på skepp, och till sjös förfarne voro, med Salomos tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Och de kommo till Ophir, och hemtade der fyrahundrad och tjugu centener guld, och förde till Konung Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Och då Salomos rykte af Herrans Namn kom för Drottningen af rika Arabien, kom hon till att försöka honom med gåtor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Och hon kom till Jerusalem med en ganska stor skara, med cameler, som speceri båro, och med mycket guld och ädla stenar. Och då hon kom in till Konung Salomo, talade hon med honom allt det hon sig föresatt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Och Salomo sade henne det allt; och Konungenom var intet fördold, det han henne icke säga kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Då nu Drottningen af rika Arabien såg all Salomos visdom, och det hus, som han byggt hade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Och rätterna på hans bord, och hans tjenares boningar, och hans tjenares ämbeten, och deras kläder, och hans skänkesvänner, och hans bränneoffer som han i Herrans hus offrade, kunde hon icke längre hålla sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Och sade till Konungen: Allt det jag i mitt land utaf ditt väsende, och af din visdom, hört hafver, det är sant.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Och jag hafver icke velat trott det, tilldess jag är kommen, och hafver det med min ögon sett; och si, mig är icke hälften sagdt. Du hafver mer visdom och rikedomar, än ryktet är, som jag hört hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Salige äro dine män, och dine tjenare, som alltid för dig stå, och höra din visdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Lofvad vare Herren din Gud, som till dig lust haft hafver, så att han dig på Israels stol satt hafver; derföre, att Herren älskar Israel i evig tid, och hafver satt dig till Konung, att du rätt och redelighet göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Och hon gaf Konungenom hundrade och tjugu centener guld, och ganska mycket speceri, och ädla stenar. Der kom icke sedan så mycket speceri, såsom Drottningen af rika Arabien Konung Salomo gaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Dertill de Hirams skepp, som guld förde af Ophir, förde också ganska mycket hebenträ, och ädla stenar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Och Konungen lät göra af hebenträ pelare i Herrans hus, och i Konungshuset, och harpor och psaltare för sångare. Der kom icke sedan så mycket hebenträ, vardt ej heller sedt, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Och Konung Salomo gaf Drottningene af rika Arabien allt det hon begärade och beddes, förutan det han gaf henne af sig sjelf. Och hon vände om, och drog med sina tjenare i sitt land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Men det guld, som Salomo inkom årliga, var till vigt sexhundrad sex och sextio centener;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Förutan det af krämare och köpmän, och af apothekare, och ifrå de nästa Konungar, och ifrå de yppersta i landet kom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Och Konung Salomo lät göra tuhundrad spetsar af bästa guld; sexhundrad stycke guld lät han till hvar spets;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Och trehundrad sköldar, af bästa guld; ju tre pund guld till hvar sköld. Och Konungen lade dem uti det huset af Libanons skog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Och Konungen gjorde en stor stol af elphenben, och bedrog honom med ädlasta guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Och stolen hade sex trappor; och hufvudet af stolen var rundt baktill, och voro stolpar på båda sidor vid sätet, och tu lejon stodo vid stolparna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Och tolf lejon stodo på de sex trappor på båda sidor. Sådant är icke gjordt i något Konungarike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'All Konung Salomos dryckekar voro af guld; och käril uti huset af Libanons skog voro också af klart guld; förty silfver aktade man intet i Salomos tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Ty Konungens skepp, som till hafs foro med Hirams skepp, kommo en gång i hvar tre är, och förde guld, silfver, elphenben, apor och påfoglar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Alltså vardt Konung Salomo större med rikedomar och visdom, än alle Konungar på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Och all verlden begärade se Salomo, att de måtte höra den vishet, som Gud honom i hans hjerta gifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Och alle båro honom skänker, silfver och gyldene tyg, kläder och harnesk, örter, hästar, mulor, hvart år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Och Salomo drog tillhopa vagnar och resenärar, så att han hade tusende och fyrahundrad vagnar, och tolftusend resenärar; och han lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Och Konungen gjorde, att silfver i Jerusalem var så mycket som stenar, och cederträ så mycket som mulbärträ i dalarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Och man förde hästar utur Egypten till Salomo, och allahanda varor, och Konungens köpmän köpte samma varor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Och förde dem utur Egypten; hvar vagn för sexhundrad silfpenningar, och hvar häst för hundrade och femtio. Alltså förde man dem ock till alla de Hetheers Konungar, och till de Konungar i Syrien, genom deras hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Men Konung Salomo älskade många utländska qvinnor, Pharaos dotter, och Moabitiskor, Ammonitiskor, Edoinitiskor, Zidonitiskor och Hetheerskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Af sådant folk, der Herren Israels barnom om sagt hade: Går icke till dem, och låter dem icke komma till eder; de varda förvisso bevekande edor hjerta efter sina gudar. Till dessa gaf sig Salomo, till att älska dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Och han hade sjuhundrad hustrur, Förstinnor, och trehundrad frillor; och hans hustrur bevekte hans hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Och då han nu gammal var, bevekte hans hustrur hans hjerta efter främmande gudar, så att hans hjerta icke var fulleliga med Herranom hans Gud, såsom hans faders Davids hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Alltså vandrade Salomo efter Astoreth, deras gud af Zidon, och Milcom, de Ammoniters styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Och Salomo gjorde det ondt var för Herranom, och följde icke Herran alldeles, såsom hans fader David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Då byggde Salomo en höjd till Chemos, de Moabiters styggelse, på berget som för Jerusalem ligger; och till Molech, de Ammoniters styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Alltså gjorde Salomo allom sinom utländskom hustrum, de der för sina gudar rökte och offrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Och Herren vardt vred på Salomo, att hans hjerta ifrå Herranom Israels Gud afvändt var, den honom två gånger synts hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Och honom härom budit hade, att han icke skulle vandra efter andra gudar; och hade dock icke hållit det honom Herren budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Derföre sade Herren till Salomo: Efter sådant är skedt med dig, och du hafver mitt förbund och min bud icke hållit, som jag dig budit hafver, så vill jag ock, rifva riket ifrå dig, och gifva det dinom tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Dock i din tid vill jag icke göra det, för dins faders Davids skull; utan af dins sons hand vill jag rifva det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Dock vill jag icke allt riket afrifva; ena slägt vill jag gifva dinom son, för min tjenares Davids skull, och för Jerusalems skull, det jag utvalt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Och Herren uppväckte Salomo en fienda, Hadad den Edomeen, af Konungsligo säd, hvilken var i Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Ty då David var i Edom, och Joab den härhöfvitsmannen drog upp till att begrafva de slagna, slog han allt det mankön var i Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Förty Joab blef der sex månader, och hele Israel, intilldess han utrotade allt det mankön var i Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Då flydde Hadad, och med honom någre män Edomeer af hans faders tjenare, så att de kommo uti Egypten; men Hadad var en ung dräng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Och de stodo upp ifrån Midian, och kommo till Paran, och togo män med sig utaf Paran, och kommo uti Egypten titt Pharao, Konungen i Egypten. Han gaf honom ett hus, och förenämnd spis, och fick honom ett land in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Och Hadad fann stora nåd för Pharao, så att han ock gaf honom sina hustrus, Drottningenes Tahpenes syster, till hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Och Tahpenes syster födde honom Genubath sin son; Och Tahpenes födde honom upp i Pharaos hus; så att Genubath var i Pharaos huse ibland Pharaos barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Då nu Hadad hörde uti Egypten, att David afsomnad var med sina fäder, och att Joab härhöfvitsmannen var död, sade han till Pharao: Låt mig draga i mitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Pharao sade till honom: Hvad fattas dig när mig, att du vill draga till ditt land? Han sade: Intet; utan låt mig fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Än uppväckte honom Gud en fienda, Reson, ElJada son, hvilken ifrå sin herra HadadEser, Konungen i Zoba, flydd var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Och församlade emot honom män, och vardt en höfvitsman för krigsknektar, den tid David slog dem ihjäl; och drogo till Damascon, och bodde der, och voro rådande i Damascon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Och han var Israels fiende, så länge Salomo lefde. Det är den skadan, som Hadad led; derföre hade han en vämjelse emot Israel, och blef rådandes i Syrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Dertill Jerobeam, Nebats son, en Ephrateer af Zareda, Salomos tjenare; och hans moder het Zeruga, en enka; hof också handena upp emot Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Och detta är saken, hvarföre han upphof handena emot Konungen: då Salomo byggde Millo, slöt han igen ett gap på sins faders Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Och Jerobeam var en stridsam man; och då Salomo såg att mannen var snäll, satte han honom öfver alla Josephs hus utskylder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Men det begaf sig på den tiden, att Jerobeam gick utaf Jerusalem, och Propheten Ahia af Silo fann honom på vägenom; och han hade en ny mantel uppå; och de voro både allena på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Och Ahia fattade den nya mantelen, som han på hade, och ref honom sönder i tolf stycker;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Och sade till Jerobeam: Tag tio stycker till dig; förty så säger Herren Israels Gud: Si, jag skall rifva riket utu Salomos hand, och gifva dig tio slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'En slägt skall han hafva för min tjenares Davids skull, och för staden Jerusalems skull, den jag utvalt hafver utur alla Israels slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Derföre att de hafva öfvergifvit mig, och tillbedit Astoreth, de Zidoniers gud, Chemos, de Moabiters gud, och Milcom, Ammons barnas gud, och icke vandrat i mina vägar, så att de måtte gjort hvad mig behagade, min bud och rätter, såsom David hans fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Jag vill ock icke taga hela riket utu hans hand; utan jag vill göra honom till en Första i hans lifstid, för Davids min tjenares skull, den jag utvalt hafver, den min bud och rätter hållit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Utu hans sons hand vill jag taga riket, och vill gifva dig tio slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Och hans son ena slägt, på det min tjenare David ju allstädes hafver ena lykto för mig uti den staden Jerusalem, den jag mig utvalt hafver, att jag mitt Namn der sätta skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Så vill jag nu taga dig, att du skall råda öfver allt det ditt hjerta begärar; och skall vara Konung öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Om du nu vill höra allt det jag dig bjudandes varder, och vandra i mina vägar, och göra hvad mig behagar, så att du håller mina rätter och bud, såsom min tjenare David gjort hafver, så vill jag vara med dig, och bygga dig ett beständigt hus, såsom jag David byggt hafver, och vill gifva dig Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Och vill dermed förnedra Davids säd; dock icke till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Men Salomo for efter att dräpa Jerobeam. Då stod Jerobeam upp, och flydde uti Egypten till Sisak, Konungen i Egypten, och blef i Egypten, tilldess Salomo blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Hvad mer af Salomo sägandes är, och allt det han gjort hafver, och hans visdom, det är skrifvet i Chrönicon om Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Men tiden, som Salomo var Konung i Jerusalem, öfver hela Israel, var fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Och Salomo afsomnade med sina fäder, och vardt begrafven uti sins faders Davids stad; och hans son Rehabeam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Och Rehabeam drog till Sichem; förty hela Israel var kommen till Sichem, till att göra honom till Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Och då Jerobeam, Nebats son, det hörde, der han ännu i Egypten var, dit han för Konung Salomo flydd var, kom han igen utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Och de sände bort, och läto kalla honom. Och Jerobeam samt med hela Israels menighet kommo, och talade med Rehabeam, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Din fader hafver gjort vårt ok för svårt; så gör nu du den hårda tjensten, och det svåra oket lättare, det han oss pålagt hafver, så vilje vi vara dig underdånige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Men han sade till dem: Går edra färde intill tredje dagen, och kommer så till mig igen. Och folket gick sina färde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Och Konung Rehabeam höll råd med de äldsta, som för hans fader Salomo stodo, då han lefde, och sade: Huru råden I, att vi måge gifva desso folkena svar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'De sade till honom: Om du i denna dag gör desso folkena en tjenst, och är dem till vilja, och hörer dem, och gifver dem god ord, så blifva de dig underdånige så länge du lefver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Men han öfvergaf de äldstas råd, som de honom gifvit hade; och höll ett råd med de unga, som med honom uppväxte voro, och för honom stodo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Och han sade till dem: Hvad råden I, det vi desso folkena svara skole, som till mig sagt hafva: Gör det oket lättare, som din fader uppå oss lagt hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Och de unge, som med honom uppväxte voro, sade till honom: Till folket, som till dig säger: Din fader hafver gjort vårt ok för svart, gör du oss det lättare; skall du säga: Mitt minsta finger skall tjockare vara än mins faders länder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Min fader hafver lagt på eder ett svårt ok; men jag skall ännu föröka det öfver eder. Min fader hafver tuktat eder med gisslar; jag skall tukta eder med scorpioner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Alltså kom Jerobeam med allo folkena till Rehabeam på tredje dagen, såsom Konungen talat hade, och sagt: Kommer igen till mig på tredje dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Och Konungen gaf folkena ett hårdt svar, och öfvergaf det råd, som de äldste honom gifvit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Och talade med dem efter de ungas råd, och sade: Min fader hafver gjort edart ok svårt; men jag vill ännu mer föröka det öfver eder. Min fader hafver tuktat eder med gisslar; men jag skall tukta eder med scorpioner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Alltså hörde Konungen intet folket; ty Herren vände det så, på det han skulle stadfästa sitt ord, som Herren genom Ahia af Silo sagt hade till Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Då nu hele Israel såg, att Konungen intet ville höra dem, gaf folket Konungenom ett svar, och sade: Hvad del hafve vi i David, eller arf i Isai son? Israel, gack i dina hyddor; så se nu du till ditt hus, David. Alltså gick Israel i sina hyddor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Så att Rehabeam rådde allenast öfver de Israels barn, som bodde i Juda städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Och då Konung Rehabeam sände åstad Adoram räntomästaren, kastade hele Israel honom ihjäl med stenar; men Konungen Rehabeam steg med hast på en vagn, och flydde till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Alltså föll Israel ifrå Davids hus, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Då nu hele Israel hörde, att Jerobeam var igenkommen, sände de bort, och läto kalla honom till alla menighetena, och gjorde honom till Konung öfver hela Israel; och ingen följde Davids hus, utan Juda slägt allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Och då Rehabeam kom till Jerusalem, församlade han hela Juda hus, och BenJamins slägt, hundrade och åttatio tusend unga stridsamma män, till att strida emot Israels hus, och draga riket igen till Rehabeam, Salomos son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Men Guds ord kom till den Guds mannen Semaja, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Tala till Rehabeam, Salomos son, Juda Konung, och till hela Juda hus, och BenJamin, och till det andra folket, och säg:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Detta säger Herren: I skolen icke draga upp, och strida emot edra bröder Israels barn; hvar och en gånge åter hem; ty detta är skedt af mig. Och de lydde Herrans ord, och vände om, och gingo sin väg, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Men Jerobeam byggde Sichem på Ephraims berg, och bodde deruti, och drog dädan ut, och byggde Pnuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Men Jerobeam tänkte i sitt hjerta: Nu varder riket fallandes till Davids hus igen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Om detta folk skall gå ditupp, till att offra i Herrans hus i Jerusalem, och detta folkets hjerta varder sig vändandes till deras herra Rehabeam, Juda Konung, och slå mig ihjäl, och falla igen till Rehabeam, Juda Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Och Konungen höll ett råd, och gjorde två gyldene kalfvar, och sade till dem: Det är eder för tungt gå upp till Jerusalem; si, der är din gud, Israel, som dig utur Egypti land fört hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Och satte endera i BethEl, och den andra i Dan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Och det vardt till synd; ty folket gick bort för dem ena, allt intill Dan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Han gjorde också ett höjdars hus, och gjorde Prester utaf de ringesta i folket, de icke af Levi barnom voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Och han gjorde en högtid, på femtonde dagen i åttonde månadenom, såsom den högtiden i Juda, och offrade på altarena. Så gjorde han i BethEl, att man offrade kalfvomen, som han gjort hade; och skickade i BethEl Prester till höjderna, som han gjort hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Och offrade på altaret, som han gjort hade i BethEl, på femtonde dagen i åttonde månadenom, hvilken han utu sitt hjerta upptänkt hade; och gjorde Israels barnom högtider, och offrade på altaret, det man röka skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Och si, en Guds man kom af Juda, genom Herrans ord, till BethEl. Och Jerobeam stod vid altaret till att röka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Och han ropade emot altaret genom Herrans ord, och sade: Altare, altare, så säger Herren: Si, Davids huse skall varda född en son, benämnd Josia, han skall på dig offra höjdernas Prester, som på dig röka, och uppbränna menniskoben på dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Och han gaf på den dagen ett tecken, och sade: Detta är tecknet, att Herren detta talat hafver: si, altaret skall remna, och askan, som derpå är, skall förspillas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Då nu Konung Jerobeam hörde ordet af den Guds mannen, som emot altaret i BethEl ropade, räckte han ut sin hand vid altaret, och sade: Tager fatt på honom. Och hans hand förtorkades, som han emot honom uträckt hade; och han kunde icke draga henne igen till sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Och altaret remnade, och askan vardt förspilld af altaret, efter tecknet, som Guds mannen genom Herrans ord gifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Och Konungen svarade och sade till den Guds mannen: Bed Herrans dins Guds ansigte, och bed för mig, att min hand kommer till mig igen. Då bad Guds mannen Herrans ansigte, och Konungens hand kom till honom igen, och vardt såsom hon tillförene var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Och Konungen talade med Guds mannenom: Kom hem med mig, och vederqvick dig; jag vill gifva dig en skänk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Men Guds mannen sade till Konungen: Om du än gåfve mig halft ditt hus, så ginge jag dock icke med dig; ty jag vill i detta rum intet bröd äta, eller vatten dricka;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Ty så är mig genom Herrans ord budet och sagdt: Du skall intet bröd äta, och intet vatten dricka, och icke komma den samma vägen tillbaka igen, som du gångit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Och han gick sina färde en annan väg, och kom icke den vägen tillbaka igen, som han till BethEl kommen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Men i BethEl bodde en gammal Prophet; till honom kommo hans söner, och förtäljde honom all verk, som Guds mannen på den dagen gjort hade i BethEl, och de ord, som han till Konungen sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Och deras fader sade till dem: Hvilken vägen hafver han farit? Och hans söner viste honom vägen, som Guds mannen farit hade, den af Juda kommen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Men han sade till sina söner: Sadler mig åsnan. Och då de hade sadlat honom åsnan, red han deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Och drog efter Guds mannen, och fann honom sittandes under en ek, och sade till honom: Äst du den Guds mannen, som af Juda kommen äst? Han sade: Ja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Han sade till honom: Kom med mig hem, och ät bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Han sade: Jag kan icke vända om med dig, och komma med dig; jag vill ej heller bröd äta, eller vatten dricka med dig, på detta rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Ty med mig är taladt vordet genom Herrans ord: Du skall der hvarken bröd äta, eller vatten dricka; du skall icke gå den vägen tillbaka igen, som du ditgången äst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Han sade till honom: Jag är ock en Prophet såsom du, och en Ängel hafver talat med mig genom Herrans ord, och sagt: Haf honom hem med dig igen, att han må bröd äta, och vatten dricka. Men han lög för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Och han förde honom tillbaka igen, så att han åt bröd, och drack vatten i hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Och vid de såto till bords, kom Herrans ord till Propheten, som honom hade tillbaka haft;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Och han ropade till den Gudsmannen, som af Juda kommen var, och sade: Detta säger Herren: Derföre, att du hafver Herrans mun ohörig varit, och hafver icke hållit det bud, som Herren din Gud dig budit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Och hafver omvändt, ätit bröd, och vatten druckit, på det rum der han dig om sade: Du skall der hvarken bröd äta, eller vatten dricka; skall din lekamen icke komma uti dina faders graf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Och sedan han bröd ätit, och druckit hade, sadlade man åsnan åt den Propheten, som han igen haft hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Och då han bort drog, fann honom ett lejon på vägenom, och drap honom; och hans kropp låg kastad på vägen; och åsnan stod jemte honom, och lejonet stod när kroppenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Och då der gick folk framom, sågo de kroppen på vägen kastad, och lejonet ståndandes när kroppen; och de kommo och sade det i stadenom, der den gamle Propheten uti bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Då Propheten det hörde, som honom igenhaft hade, sade han: Det är den Guds mannen, som Herrans mun ohörig var; derföre hafver Herren gifvit honom lejonena; det hafver sönderkrossat honom och dräpit, efter det ord som Herren honom sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Och sade till sina söner: Sadler mig åsnan. Och de sadlade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Då drog han dit, och fann hans kropp kastad på vägen, och åsnan och lejonet ståndande der jemte kroppen; lejonet hade intet ätit af kroppen, och ej heller rifvit åsnan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Då tog Propheten den Guds mansens kropp upp, och lade honom på åsnan, och förde honom tillbaka igen; och kom uti den gamla Prophetens stad, att de måtte begråta honom, och begrafvan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Och han lade kroppen uti sina graf, och de begreto honom: Ack! min broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Och då de hade begrafvit honom, sade han till sina söner: När jag dör, så begrafver mig i de grafvene, som den Guds mannen uti begrafven är, och lägger min ben jemte vid hans ben;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Förty det varder skeendes, som han emot altaret i BethEl genom Herrans ord ropat hafver, och emot alla höjders hus, som i Samarie städer äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Men sedan detta skedt var, vände Jerobeam sig intet ifrå sin onda väg; utan förvände sig, och gjorde Prester till höjderna, utaf de ringesta i folket; hvilken honom täcktes, honom fyllde han handena, och han vardt Prest till höjderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Och detta vardt Jerobeams huse till synd, att han skulle förderfvas, och förgöras af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'På den tiden var Abia, Jerobeams son, krank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Och Jerobeam sade till sina hustru: Statt upp, och förkläd dig, så att ingen kan märka, att du äst Jerobeams hustru, och gack bort till Silo; si, der är den Propheten Ahia, den mig sade, att jag skulle varda Konung öfver detta folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Och tag med dig tio bröd, och kakor, och ett käril med hannog, och gack till honom, att han må säga dig, huru med piltenom gå skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Och Jerobeams hustru gjorde så, och stod upp, och gick bort till Silo, och kom i Ahia hus; men Ahia kunde intet se; ty hans ögon voro mörk vorden för ålders skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Men Herren sade till Ahia: Si, Jerobeams hustru kommer, att hon skall fråga ett ärende af dig om sin son, ty han är krank: så tala nu du med henne så och så. Då hon nu inkom, höll hon sig främmande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Som nu Ahia hörde dönen af hennes fötter, vid hon ingick, sade han: Kom hitin, du Jerobeams hustru; hvi håller du dig så främmande? Jag är sänder till dig ett hårdt bådskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gack bort, och säg Jerobeam: Så säger Herren Israels Gud: Jag hafver upphöjt dig utu folkena, och satt dig till en Första öfver mitt folk Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Och hafver rifvit riket ifrå Davids hus, och gifvit det dig; men du hafver intet varit såsom min tjenare David, den min bud höll, och vandrade efter mig med allo hjerta, så att han gjorde hvad mig ljuft var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Och du hafver illa gjort, öfver alla de som för dig varit hafva; du hafver gångit bort, och gjort dig andra gudar, och gjuten beläte, att du skulle reta mig till vrede; och hafver kastat mig bakom din rygg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Och si, jag skall låta komma olycko öfver Jerobeams hus, och förgöra af Jerobeam ock den uppå väggena pissar; den innelyckta, och den igenlefda i Israel; och skall utsopa Jerobeams hus efterkomman de, såsom man träck utsopar, tilldess det blifver allt ute med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Den som af Jerobeam dör i stadenom, honom skola hundarna äta; men den som dör på markene, honom skola himmelens foglar äta; ty Herren hafver det sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Så statt nu upp, och gack hem; och då din fot träder in i staden, skall pilten blifva död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Och hela Israel skall begråta honom, och skola begrafvan; ty denne allena af Jerobeam skall till grafva komma; förty något godt är funnet i honom för Herranom Israels Gud, i Jerobeams hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Och Herren skall uppväcka en Konung öfver Israel, han skall utrota Jerobeams hus på den dagen; och hvad är det nu allaredo sker?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Och Herren skall slå Israel, såsom rören böjas i vattnena; och skall utrycka Israel utu desso goda landena, som han deras fader gifvit hafver, och skall förströ dem bort öfver älfvena; derföre att de hafva gjort sig lundar till att förtörna Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Och skall öfvergifva Israel, för Jerobeams synds skull, hvilken syndat hafver och kommit Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Och Jerobeams hustru stod upp, gick, och kom till Thirza; och då hon kom till tröskelen åt huset, blef pilten död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Och de begrofvo honom, och hele Israel begreto honom, efter Herrans ord, som han genom sin tjenare Propheten Ahia talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Hvad mer om Jerobeam sägandes är, huru han stridde och regerade, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Tiden, som Jerobeam regerade, var tu och tjugu år; och han af somnade med sina fäder. Och hans son Nadab vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Så var nu Rehabeam, Salomos son, Konung i Juda; ett och fyratio år gammal var Rehabeam, då han vardt Konung; och regerade i sjutton år i Jerusalem, i dem stadenom, som Herren utvalt hade utur alla Israels slägter, att han skulle sätta der sitt Namn uti. Hans moder het Naama, en Ammonitiska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Och Juda gjorde det ondt var för Herranom, och rette honom mera, än allt det deras fäder gjort hade, med deras synder som de gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Ty de byggde sig också höjder, stodar och lundar, på alla höga backar, och under all grön trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Och voro desslikes roffare i landena; och de gjorde all Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Men i femte Konung Rehabeams åre drog Sisak, Konungen i Egypten, uppemot Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Och tog ut de håfvor utu Herrans hus, och utu Konungshuset, och allt det som der tagas kunde; och tog alla gyldene sköldar, som Salomo hade göra låtit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'I hvilkas stad Konung Rehabeam lät göra kopparsköldar, och befallde dem under de öfversta drabanternas hand, som dörrena vaktade för Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Och så ofta Konungen gick in uti Herrans hus, båro drabanterna dem; och hade dem åter uti drabantakammaren igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Hvad nu mer af Rehabeam sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Men emellan Rehabeam och Jerobeam var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Och Rehabeam afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids stad; och hans moder het Naama, en Ammonitiska. Och hans son Abiam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'På adertonde årena Konung Jerobeams, Nebats sons, vardt Abiam Konung i Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Och regerade tre år i Jerusalem. Hans moder het Maacha, Abisaloms dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Och han vandrade i alla sins faders synder, som han för honom gjort hade; och hans hjerta var icke rättsinnigt till Herran hans Gud, såsom hans faders Davids hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Men för Davids skull gaf Herren hans Gud honom ena lykto i Jerusalem, så att han uppväckte hans son efter honom, och behöll honom i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Derföre att David gjort hade det Herranom ljuft var, och var icke viken ifrån allt det han honom böd, så länge han lefde; förutan i den handelen med Uria den Hetheen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Men emellan Rehabeam och Jerobeam var örlig, så länge han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Hvad nu mer af Abiam sägandes är, och allt det han gjort hafver; si, det är skrifvet uti Juda Konungars Chrönico. Och det var örlig emellan Abiam och Jerobeam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Och Abiam afsomnade med sina fäder; och de begrofvo honom uti Davids stad. Och Asa hans son vardt Konung uti hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Uti tjugonde årena Konungs Jerobeams öfver Israel, vardt Asa Konung i Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Och regerade ett och fyratio år i Jerusalem. Hans moder het Maacha, Abisaloms dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Och Asa gjorde det Herranom behageligit var, såsom hans fader David;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Och dref de roffare utu landet, och borttog alla de afgudar, som hans fäder gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Dertill satte han sina moder Maacha af ämbetet, för det hon Miplezeth gjort hade i lundenom; och Asa utrotade hennes Miplezeth, och uppbrände honom vid den bäcken Kidron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Men de höjder lade de icke bort; dock var Asa hjerta rättsinnigt till Herran, så länge han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Och det silfver och guld, och tyg, som hans fader helgat hade, och hvad som helgadt var till Herrans hus, lät han komma derin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Och emellan Asa och Baesa, Israels Konung, var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Men Baesa, Israels Konung, drog upp emot Juda, och byggde Rama, att ingen skulle draga ut och in af Asa part, Konungens i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Då tog Asa allt silfver och guld, som qvart var i Herrans hus skatt, och i Konungshusets skatt, och fick det i sina tjenares händer; och sände dem till Benhadad, Tabrimmons son, Hesions sons, Konungen i Syrien, som bodde i Damascon, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Ett förbund är emellan, mig och dig, och emellan min fader och din, fader; derföre skickar jag dig en, skänk, silfver och guld, att du ville låta det förbundet fara, som du hafver med Baesa, Israels Konung, att han må draga ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Benhadad hörde Konung Asa, och sände sina höfvitsmän emot Israels städer, och slog Ijon och Dan, och AbelBethMaacha, hela Cinneroth med hela Naphthali land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Då Baesa det hörde, vände han igen bygga Rama, och drog till Thirza igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Men Konung Asa lät båda öfver hela Juda: Ingen ursake sig; och de togo bort sten och trä af Rama, der Baesa med byggt hade. Och Konung Asa byggde dermed Geba BenJamin, och Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Hvad nu mer af Asa sägandes är, och all hans magt, och allt det han gjorde, och de städer som han byggde, si, det är skrifvet uti Juda Konungars Chrönico; undantagno, att han på sinom ålder var krank i sina fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Och Asa afsomnade med sina fader, och vardt begrafven med sina fader uti Davids sins faders stad. Och Josaphat hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Men Nadab, Jerobeams son, vardt Konung öfver Israel, uti de andra årena Asa, Juda Konungs; och rådde öfver Israel i tu år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Och gjorde det för Herranom ondt var, och vandrade i sins faders vägar, och i hans synder, der han med kom Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Men Baesa, Ahia son, utaf Isaschars hus, gjorde ett förbund emot honom, och slog honom i Gibbethon, som var de Philisteers; ty Nadab och hele Israel belade Gibbethon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Så drap Baesa honom, uti tredje årena Asa, Juda Konungs; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Som han nu Konung var, slog han hela Jerobeams hus, och lät intet qvart blifva, det anda hade, af Jerobeam, tilldess han utrotade honom, efter Herrans ord, som han talat hade genom sin tjenare Ahia af Silo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'För Jerobeams synds skull, som han gjorde, och dermed han kom Israel till att synda; och med det retandet, dermed han rette Herran Israels Gud till vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Hvad nu mer af Nadab sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Och emellan Asa och Baesa, Israels Konung, var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Uti tredje årena Asa, Juda Konungs, vardt Baesa, Ahia son, Konung öfver hela Israel i Thirza, fyra och tjugu ar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Och gjorde det ondt var för Herranom, och vandrade i Jerobeams väg, och i hans synd, dermed han hade kommit Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Så kom Herrans ord till Jehu, Hanani son, emot Baesa, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Derföre, att jag dig utu stoftet upphäfvit hafver, och gjort dig till en Första öfver mitt folk Israel, och du vandrar i Jerobeams väg, och kommer mitt folk Israel till att synda, så att du mig förtörnar genom deras synder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Si, så vill jag borttaga Baesa efterkommande, och hans hus efterkommande, och vill sätta ditt hus såsom Jerobeams hus, Nebats sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Den af Baesa dör i staden, honom skola hundar uppäta; och den af honom dör på markene, honom skola himmelens foglar uppäta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Hvad nu mer om Baesa sägandes är, och hvad han gjort hafver, och hans magt, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Och Baesa afsomnade med sina fäder, och vardt begrafven i Thirza; och hans son Ela vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Och Herrans ord kom genom Propheten Jehu, Hanani son, öfver Baesa, och öfver hans hus, och emot allt det onda, som han för Herranom gjort hade, till att förtörna honom genom sina händers verk, att det skulle varda såsom Jerobeams hus, och derföre, att han denna slagit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Uti sjette och tjugonde årena Asa, Juda Konungs, vardt Ela, Baesa son, Konung öfver Israel i Thirza, i tu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Men hans tjenare Simri, en öfverste öfver hälften af vagnarna, gjorde ett förbund emot honom; men han var i Thirza, drack och var drucken i Arza hus, fogdans i Thirza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Och Simri kom derin, och slog honom ihjäl, uti sjunde och tjugonde årena Asa, Juda Konungs; och blef Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Och då han var Konung, och satt på sin stol, slog han hela Baesa hus, och lät intet qvart blifva, icke den som på väggena pissar; dertill hans fränder och vänner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Alltså förgjorde Simri hela Baesa hus, efter Herrans ord, som han om Baesa talat hade, genom den Propheten Jehu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'För alla Baesa och hans sons Ela synders skull, som de gjort hade, och kommo Israel till att synda, och förtörnade Herran Israels Gud i deras afguderi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Hvad nu mer af Ela sägandes är, och allt det han gjorde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Uti sjunde och tjugonde årena Asa, Juda Konungs, vardt Simri Konung i sju dagar i Thirza; ty folket låg för Gibbethon de Philisteers.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Då nu folket i lägret hörde sägas, att Simri hade gjort ett förbund, och slagit Konungen ihjäl, gjorde hele Israel på samma dagen Amri, härhöfvitsmannen, till Konung öfver Israel i lägrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Och Amri drog upp, och hele Israel med honom, ifrå Gibbethon, och belade Thirza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Då nu Simri såg, att staden skulle varda vunnen, gick han uti palatset i Konungshusena, och brände sig upp med Konungshusena, och blef död;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'För sina synders skull, som han gjort hade, så att han hade gjort det ondt var för Herranom, och vandrade uti Jerobeams väg, och i hans synd, som han gjorde, och kom Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Hvad nu mer af Simri sägandes är, och huru han gjorde ett förbund, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'På den tiden söndrade sig folket Israel i två delar: en hälften höll sig intill Thibni, Ginaths son, och gjorde honom till Konung; den andra hälften höll sig intill Amri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Men det folk, som höll sig intill Amri, vardt starkare än det folk, som höll sig intill Thibni, Ginaths son. Och Thibni blef död, och så blef Amri Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Uti första och tretionde årena Asa, Juda Konungs, vardt Amri Konung öfver Israel i tolf år; och regerade i Thirza i sex år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Han köpte Samarie berg af Semer, för två centener silfver; och byggde uppå bergena, och kallade staden, som han byggde, efter Semers namn, som herre var på Samarie berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Och Amri gjorde det ondt var för Herranom, och var argare än alla de för honom varit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Och vandrade i alla Jerobeams vägar, Nebats sons, och i hans synder, dermed han kom Israel till att synda, så att de förtörnade Herran Israels Gud uti deras afguderi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Hvad nu mer af Amri sägandes är, och allt det han gjort hafver, och om hans magt som han bedref, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Och Amri afsomnade med sina fäder, och vardt begrafven i Samarien; och Achab hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Uti åttonde och tretionde årena Asa, Juda Konungs, vardt Achab, Amri son, Konung öfver Israel; och regerade öfver Israel i Samarien tu och tjugu år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Och gjorde det ondt var för Herranom, öfver alla dem som för honom varit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Och var honom icke nog, att han vandrade i Jerobeams, Nebats sons, synder; utan tog dertill Isebel, EthBaals dotter, Konungens i Zidon, till hustru, och gick bort, och tjente Baal, och tillbad honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Och uppsatte Baal ett altare uti Baals hus, det han honom byggde i Samarien;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Och gjorde en lund; så att Achab mer gjorde till att förtörna Herran Israels Gud, än alle Israels Konungar, som för honom varit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'På samma tid byggde Hiel af BethEl Jericho. Det kostade honom hans första son Abiram, då han grundvalen lade; och hans yngsta son Segub, då han satte portarna derföre, efter Herrans ord, som han sagt hade genom Josua, Nuns son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Och Elia den Thisbiten, utaf de Gileads inbyggare, sade till Achab: Så sant som Herren Israels Gud lefver, för hvilkom jag står, det skall i dessa år hvarken dagg eller regn komma, utan jag säger det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Och Herrans ord kom till honom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Gack bort hädan, och vänd dig österut, och fördölj dig vid den bäcken Cherith, som löper för Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Och du skall dricka af bäckenom; och jag hafver budit korpom, att de skola der föda dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Han gick dit, och gjorde efter Herrans ord, och gick bort, och satte sig vid bäcken Cherith, som löper för Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Och korpar förde honom bröd och kött, om morgon och om afton; och han drack utaf bäcken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Och det skedde efter några dagar, att bäcken förtorkades; ty intet regn vardt i landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Då kom Herrans ord till honom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Statt upp, och gack till Zarpath, som vid Zidon ligger, och blif der; ty jag hafver der befallt ene enko, att hon skall föda dig,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Och han stod upp och gick till Zarpath. Och då han kom till stadsporten, si, då var enkan der, och hemtade ved. Och han talade till henne, och sade: Hemta mig litet vatten i kärilet, att jag må dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Då hon nu åstad gick till att hemtat, ropade han efter henne, och sade: Bär mig ock en beta bröd med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Hon sade: Så sant som Herren din Gud lefver, jag hafver intet bröd, utan en hand full af mjöl uti skäppone, och litet oljo i krukone; och si, jag hafver hemtat ett trä eller tu; och går bort att reda det till, mig och minom son, att vi måge äta och dö;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elia sade till henne: Frukta dig intet; gack åstad, och gör såsom du sagt hafver; dock gör mig först ett litet bröd deraf, och bär mig det hitut; men dig och dinom son skall du ock så sedan göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Ty så säger Herren Israels Gud, att mjölet i skäppone skall icke varda uttärdt, och oljan i krukone skall icke förminskas, intill den dag Herren låter regna på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Hon gick åstad, och gjorde såsom Elia sagt hade. Och han åt; och hon desslikes, och hennes hus, en tid lång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Och vardt mjölet icke uttärdt i skäppone; och icke heller förminskades oljan i krukone, efter Herrans ord, som han genom Elia sagt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Sedan detta skedt var, vardt qvinnones, hans värdinnos, son krank; och hans krankhet vardt så stark, att ingen ande var mer uti honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Och hon sade till Elia: Hvad hafver jag med dig göra, du Guds man? Du äst ingången till mig, att mina missgerningar skulle ihågkommas, och min son dräpas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Han sade till henne: Få mig din son hit. Och han tog honom utu hennes sköte, och gick upp i salen, der han vistades, och lade honom på sina säng;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Och ropade till Herran, och sade: Herre, min Gud, hafver du ock så illa gjort emot denna enkona, som jag gäster när, att du dräper hennes, son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Och han räckte sig ut öfver pilten i tre gånger, och ropade till Herran, och sade: Herre min Gud, låt denna piltens själ åter komma i honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Och Herren hörde Elia röst; och piltens själ kom igen till honom, och han fick lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Och Elia tog pilten, och bar honom neder utaf salen i huset, och fick honom hans moder, och sade: Si der, din son, lefver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Och qvinnan sade till Elia: Nu förnimmer jag, att du äst en Guds man, och Herrans ord i dinom mun är visst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Efter en lång tid kom Herrans ord till Elia, i tredje årena, och sade: Gack bort, och te dig för Achab, att jag må låta regna på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Och Elia gick åstad, och tedde sig för Achab; men en ganska hård tid var i Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Och Achab kallade Obadja sin hofmästare. Och Obadja fruktade Herran storliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Förty då Isebel utrotade Herrans Propheter, tog Obadja hundrade Propheter, och gömde dem i kulor, femtio här, och femtio der; och försörjde dem med bröd och vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Så sade nu Achab till Obadja: Drag igenom landet till alla vattubrunnar och bäcker, att vi måtte finna gräs, och behålla hästar och mular, så att boskapen icke all förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Och de delade sig i landet, så att de drogo det igenom. Achab drog allena på en väg, och Obadja desslikes allena på den andra vägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Då nu Obadja var på vägenom, si, då mötte honom Elia. Och som han kände honom, föll han uppå sitt anlete, och sade: Äst du icke min herre Elia?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Han sade: Ja; gack och säg dinom herra: Si, Elia är här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Han sade: Hvad hafver jag syndat, att du vill gifva din tjenare i Achabs händer, att han skall dräpa mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Så sant som Herren din Gud lefver, det är intet folk eller Konungarike, dit min herre icke sändt hafver till att söka dig, och när de hafva sagt: Han är icke här, hafver han tagit en ed af det riket och folket, att man icke hade funnit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Och du säger nu: Gack och säg dinom herra: Si, Elia är här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'När jag nu ginge ifrå dig, så toge Herrans Ande dig bort, jag vet icke hvart; och jag komme då och underviste det Achab, och funne dig icke, så sloge han mig ihjäl; men jag din tjenare fruktar Herran af minom ungdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Är minom herra icke undervist, hvad jag gjort hafver, då Isebel drap Herrans Propheter? att jag gömde hundrade Herrans Propheter, femtio här, och femtio der, uti kulor; och försörjde dem med bröd och vatten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Och nu säger du: Gack bort, och säg dinom herra: Elia är här; att han må dräpa mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elia sade: Så sant som Herren Zebaoth lefver, för hvilkom jag står, i dag skall jag te mig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Då gick Obadja emot Achab, och sade honom detta. Och Achab gick emot Elia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Och då Achab såg Elia, sade Achab till honom: Äst du den som förvillar Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Han sade: Jag förvillar icke Israel, utan du och dins faders hus, dermed att I Herrans bud öfvergifvit hafven, och vandren efter Baalim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Nu väl, så sänd nu bort, och församla mig hela Israel på Carmels berg; och fyrahundrad och femtio Baals Propheter, och de fyrahundrad lundarnas Propheter, som äta vid Isebels bord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Alltså sände Achab bort ibland all Israels barn, och församlade Propheterna på Carmels berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Då gick Elia fram för allt folket, och sade: Huru länge halten I på båda sidor? Är Herren Gud, så vandrer efter honom; men är Baal det, så vandrer efter honom. Och folket svarade honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Då sade Elia till folket: Jag allena är qvar blifven, en Herrans Prophet; men Baals Propheter äro fyrahundrade och femtio män,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Så får oss nu två stutar, och låter dem utvälja en stuten och stycka honom, och lägga honom på ved; men låte ingen eld komma dertill; så vill jag taga den andra stuten, och lägga honom på ved, och ej heller låta der någon eld till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Så åkaller I edars guds namn, och jag vill åkalla Herrans Namn; hvilken Gud, som nu svarar med elden, han vare Gud. Och hela folket svarade och sade: Det är rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Och Elia sade till Baals Propheter: Utväljer eder en stuten, och görer I först; förty I ären månge; och åkaller edars guds namn, och låter ingen eld dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Och de togo stuten, som han fick dem, och redde till, och åkallade Baals namn, ifrå morgonen allt intill middag, och sade: Baal, hör oss. Men der var ingen röst eller svar. Och de sprungo om altaret, såsom deras seder var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Då nu middag var, bespottade dem Elia, och sade: Roper högt; ty han är en gud; han begrundar, eller hafver något beställa, eller är ute på markene, eller sofver tilläfventyrs, att han måtte vaka upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Och de ropade högt, och riste sig med knifvar, och med prener, efter deras sed, så att blodet gick der ut efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Då nu middagen förgången var, propheterade de, intilldess man skulle göra spisoffer; och der var dock ingen röst, eller svar, eller tillhörare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Då sade Elia till allt folket: Kommer hit till mig. Och då allt folket gick fram till honom, botade han Herrans altare, som nederslaget var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Och tog tolf stenar, efter talet på Jacobs barnas slägter, till hvilken Herrans ord talade, och sade: Du skall heta Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Och byggde af de stenar ett altare i Herrans Namn, och gjorde ena graf kringom altaret, tu kornmått vid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Och redde till veden, och styckade stuten, och lade honom på veden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Och sade: Hemter fyra sår fulla med vatten, och gjuter det på bränneoffret och uppå veden; och sade: Görer det än en tid. Och de gjorde det än en tid. Och han sade: Görer det än tredje reson. Och de gjorde det i tredje reson.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Och vattnet lopp om altaret, och grafven vardt också full med vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Och som tid var till att offra spisoffer, gick Propheten Elia fram, och sade: Herre, Abrahams Gud, Isaacs, och Israels, låt i denna dag kunnigt varda, att du äst Gud i Israel, och jag din tjenare, och att jag allt detta efter ditt ord gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Hör mig, Herre, hör mig, att detta folket må veta att du, Herre, äst Gud; att du sedan må omvända deras hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Då föll Herrans eld neder, och uppbrände bränneoffret, veden, stenar och jord, och uppslekte vattnet i grafvene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Då allt folket såg det; föll det på sitt ansigte, och sade: Herren är Gud, Herren är Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Men Elia sade till dem: Tager fatt på Baals Propheter, att icke en af dem undslipper. Och de togo fatt på dem; och Elia förde dem neder till den bäcken Kison, och drap dem der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Och Elia sade till Achab: Drag upp, ät och drick; förty det dånar, såsom det ville komma ett stort regn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Och då Achab drog upp till att äta och dricka, gick Elia upp på kullen af Carmel, och böjde sig neder till jordena, och satte sitt hufvud emellan sin knä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Och talade till sin dräng: Gack ditupp, och se ut till hafvet. Han gick upp, och såg ut, och sade: Der är intet. Han sade: Gack åter ditupp sju resor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Och i sjunde resone sade han: Si, der går ett litet moln upp utu hafvet såsom en mans hand. Han sade: Gack upp, och säg Achab: Spänn före din vagn, och far ned, att regnet icke hinner dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Och förr än man såg till, vardt himmelen svart af moln och väder; och ett stort regn kom. Men Achab for, och kom till Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Och Herrans hand kom öfver Elia, och han gjordade sina länder, och lopp för Achab, tilldess han kom till Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Och Achab sade till Isebel allt det Elia gjort hade; och huru han hade dräpit alla Baals Propheter med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Då sände Isebel ett båd till Elia, och lät säga honom: Gudarne göre mig det och det, om jag icke, i morgon vid denna tiden, gör dine själ såsom ene af dessas själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Då han det såg, stod han upp, och gick hvart han ville, och kom till BerSeba i Juda, och lät der sin dräng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Men han gick bort uti öknena ena dagsreso, och kom derin, och satte sig under ett enebärsträ, och bad att hans själ måtte dö, och sade: Det är nog. Så tag nu, Herre, mina själ; jag är icke bättre än mine fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Och han lade sig, och sof under enebärsträt. Och si, Ängelen tog uppå honom, och sade till honom: Statt upp, och ät.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Och han såg sig om; och si, vid hans hufvud låg ett glödbakadt bröd, och en kanna med vatten. Och då han ätit och druckit hade, lade han sig åter till att sofva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Och Herrans Ängel kom till honom annan gången igen, och tog på honom, och sade: Statt upp, och ät; ty du hafver en stor väg för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Och han stod upp, och åt, och drack, och gick af den matens kraft fyratio dagar och fyratio nätter intill Guds berg Horeb;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Och kom der uti ena kulo, och blef der öfver nattena. Och si, Herrans ord kom till honom, och sade till honom: Hvad gör du här, Elia?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Han sade: Jag hafver haft nit om Herran Gud Zebaoth; förty Israels barn hafva öfvergifvit ditt förbund, och nederbrutit din altare, och dräpit dina Propheter med svärd; och jag är allena igenblifven, och de fara efter att de måga taga mig lifvet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Han sade: Gack härut, och stig upp på berget inför Herran. Och si, Herren gick der framom, och ett stort starkt väder, som bröt berg, och sönderbråkade hällar inför Herranom; men icke var Herren i vädrena. Efter vädret kom en jordbäfning; men icke var Herren i jordbäfningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Och efter jordbäfningen kom en eld; men icke var Herren i eldenom. Och efter elden kom ett ljud af ett sakta väder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Då Elia det hörde, skylde han sitt ansigte med sin mantel, och gick ut, och steg i dörrena af kulone; och si, då kom en röst till honom, och sade: Hvad hafver du här göra, Elia?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Han sade: Jag hafver haft nit om Herran Gud Zebaoth; förty Israels barn hafva öfvergifvit ditt förbund, nederbrutit din altare, dräpit dina Propheter med svärd; och jag är allena igenblifven, och de stå derefter, att de måga taga mig lifvet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Men Herren sade till honom: Gack din väg igen, genom öknena in i Damascon; och gack derin, och smörj Hasael till Konung öfver Syrien;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Och Jehu, Nimsi son, till Konung öfver Israel; och Elisa, Saphats son, af AbelMehola, till en Prophet i din stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Och skall ske, att den som undslipper Hasaels svärd, honom skall Jehu dräpa; och den som undslipper Jehu svärd, honom skall Elisa dräpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Och jag skall låta igenblifva sjutusend i Israel, nämliga all knä som sig icke hafva böjt för Baal, och hvar och en mun som honom icke kysst hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Och han gick dädan, och fann Elisa, Saphats son, der han plöjde med tolf par oxar, och han var sjelf ibland de tolf; och Elia gick till honom, och kastade sin mantel öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Men han öfvergaf oxarna, och lopp efter Elia, och sade: Låt mig kyssa min fader, och mina moder, så vill jag följa dig efter. Han sade till honom: Gack, och kom igen; ty jag hafver något beställa med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Och han lopp åter ifrå honom, och tog ett par oxar, och offrade dem, och kokade köttet med träredskapen till oxarna, och gaf folket, att de åto; och stod upp, och följde Elia efter och tjente honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Och Benhadad, Konungen i Syrien, församlade alla sina magt, och voro två och tretio Konungar med honom, och hästar och vagnar; och drog upp, och belade Samarien, och stridde deremot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Och sände båd till Achab, Israels Konung, in uti staden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Och lät säga honom: Så säger Benhadad: Ditt silfver och ditt guld är mitt; och dina hustrur, och din bästa barn äro också min.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israels Konung svarade, och sade: Min herre Konung, såsom du sagt hafver, jag är din, och allt det jag hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Och båden kommo igen, och sade: Så säger Benhadad: Efter jag hafver sändt till dig, och låtit säga: Ditt silfver och ditt guld, dina hustrur och din barn skall du få mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Så vill jag i morgon på denna tiden sända mina tjenare till dig, att de ransaka ditt hus, och dina underdånares hus; och hvad dig kärt är, skola de taga i deras händer, och bära bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Då kallade Israels Konung alla landsens äldsta, och sade: Märker och ser, hvilket ondt han företager; han sände till mig om mina hustrur och barn, silfver och guld, och jag hafver det intet nekat honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Då sade till honom alle de gamle, och allt folket: Du skall intet höra honom, eller samtyckat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Och han sade till Benhadads båd: Säger minom herra Konungenom: Allt det du böd dinom tjenare i förstone, vill jag göra; men detta kan jag icke göra. Och båden gingo sina färde, och sade sådant igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Då sände Benhadad till honom, och lät säga honom: Gudarna göre mig det och det, om stoftet i Samarien skall räcka till att allt folket under mig må taga der en hand full af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Men Konungen i Israel svarade och sade: Säger: Den som lägger harnesket uppå, skall icke så berömma sig, såsom den det aflagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Då Benhadad det hörde, och drack med Konungarna i tjällen, sade han till sina tjenare: Gör er redo; och de gjorde redo emot staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Och si, en Prophet gick fram till Achab, Israels Konung, och sade: Så säger Herren: Du hafver ju sett allan den stora hopen; si, jag vill i dag gifva honom i dina hand, att du veta skall att jag är Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Achab sade: Genom hvem? Han sade: Så säger Herren: Genom landsfogdarnas tjenare. Han sade: Ho skall begynna striden? Han sade: Du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Då räknade han landsfogdarnas tjenare, och de voro tuhundrad och två och tretio; och räknade efter dem hela folket af all Israels barn, sjutusend män;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Och drogo ut om middag. Men Benhadad drack, och var drucken i tjällen, med de två och tretio Konungar, som honom till hjelp komne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Och landsfogdarnas tjenare drogo först ut. Då sände Benhadad ut; och de bådade honom, och sade: Det draga män utu Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Han sade: Griper dem lefvande, ehvad de äro utdragne till frid eller strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Då landsfogdarnas tjenare voro utdragne, och hären efter dem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Slog hvar och en den han öfverkom. Och de Syrer flydde, och Israel jagade efter dem; och Benhadad, Konungen i Syrien, undslapp med hästar och resenärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Och Israels Konung drog ut, och slog hästar och vagnar, så att han gjorde en stor slagtning på de Syrer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Då gick en Prophet till Israels Konung, och sade till honom: Gack bort, och förstärk dig, och märk och se hvad du göra skall; ty Konungen i Syrien varder igenkommandes emot dig, när året är ute.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Förty Konungens tjenare i Syrien sade till honom: Deras gudar äro bergsgudar, derföre hafva de vunnit oss. O! att vi måtte strida med dem på slättene; hvad gäller, vi skulle vinna dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Gör alltså: Tag bort Konungarna, hvar af sitt rum, och sätt öfverstar i deras stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Och skicka dig en här, sådana som hären var, som du mist hafver, och hästar och vagnar, såsom hine voro, och låt oss strida emot dem på slättene; hvad gäller, vi öfvervinne dem? Han hörde deras röst, och gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Som nu året omgånget var, skickade Benhadad de Syrer, och drog upp till Aphek, till att strida emot Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Och Israels barn skickade sig ock, och bespisade sig, och drogo dit emot dem, och lägrade sig emot dem, såsom två små getahjordar; men landet var fullt med Syrer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Och en Guds man gick fram, och sade till Israels Konung: Så säger Herren: Derföre, att de Syrer hafva sagt: Herren är en Gud på bergom, och icke en Gud i dalar; så hafver jag gifvit allan denna stora hopen uti dina hand, att I skolen veta att jag är Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Och de lägrade sig tvärtemot hina i sju dagar; på sjunde dagen drogo de tillhopa i strid. Och Israels barn slogo de Syrer hundradetusend fotfolk af, på en dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Och de som öfverblefvo, flydde till Aphek in i staden. Och murarna föllo uppå de sju och tjugu tusend män, som qvare blefvo. Och Benhadad flydde också in i staden, uti en liten kammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Då sade hans tjenare till honom: Si, nu hafve vi hört, att Israels hus Konungar äro barmhertige Konungar; så låt oss taga säcker kringom våra länder, och rep kringom vår hufvud, och gå ut till Israels Konung; tilläfventyrs han låter dina själ lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Och de bundo säcker öfver sina länder, och rep om sin hufvud, och kommo till Israels Konung, och sade: Benhadad din tjenare låter dig säga: Käre, låt mina själ lefva. Han sade: Lefver han ännu, så är han min broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Och männerna togo med hast ordet af honom, och tydde det ut för sig, och sade: Ja, din broder Benhadad. Han sade: Kommer, och hafver honom hit. Då gick Benhadad ut till honom, och han lät honom sitta på sinom vagn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Och han sade till honom: De städer, som min fader dinom fader aftagit hafver, vill jag få dig igen; och gör dig gator i Damascon, såsom min fader gjort hafver i Samarien; så vill jag fara ifrå dig med ett förbund. Och han gjorde ett förbund med honom, och lät honom fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Då sade en man utaf de Propheters söner till sin nästa, igenom Herrans ord: Käre, slå mig; men han nekade sig vilja slå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Då sade han till honom: Derföre, att du icke hafver hört Herrans röst, si, så skall ett lejon slå dig, när du går ifrå mig. Och då han gick ifrå honom, fann honom ett lejon, och slog honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Och han fann en annan man, och sade: Käre, slå mig. Och mannen slog honom, och gjorde honom sår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Då gick den Propheten bort, och trädde fram för Konungen på vägenom, och förvandlade sitt ansigte med asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Och när Konungen for der framom, ropade han till Konungen, och sade: Din tjenare var utdragen midt i striden; och si, en man var afviken, och hade en man till mig, och sade: Förvara denna mannen; om han kommer bort, så skall din själ vara i hans själs stad, eller du skall gifva en centener silfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Och då din tjenare der och der beställa hade, kom han sin väg. Konungen sade till honom: Det är din dom, som du sjelfver afsagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Så strök han med hast askona af ansigtet; och Israels Konung kände honom, att han var en af Propheterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Och han sade till honom: Så säger Herren: Derföre, att du hafver släppt den man utu dina händer, som tillspillogifven var, skall din själ vara för hans själ, och ditt folk för hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Men Israels Konung for sina färde, illa tillfrids och vred, i sitt hus, och kom till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Sedan detta skedt var, begaf sig, att Naboth, en Jisreelit, hade en vingård i Jisreel, vid Achabs palats, Konungens i Samaria.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Och Achab talade med Naboth, och sade: Låt mig få din vingård; jag vill göra mig der en kålgård af, efter han ligger så när mitt hus; jag vill gifva dig en bättre vingård igen; eller, om dig så täckes, vill jag gifva dig der silfver före, så mycket han är värd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Men Naboth sade till Achab: Det låte Herren vara långt ifrå mig, att jag skulle låta dig få mina fäders arf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Då kom Achab hem, illa tillfrids och vred, för det ordets skull, som Naboth den Jisreeliten till honom talat hade, och sagt: Jag vill icke låta dig få mina fäders arf. Och han lade sig uppå sin säng, och vände sitt anlete, och åt intet bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Då kom Isebel hans hustru in till honom, och sade till honom: Hvad är det, att din ande är så illa tillfrids, och du intet bröd äter?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Han sade till henne: Jag hafver talat till Naboth den Jisreeliten, och sagt: Låt mig få din vingård för penningar; eller, om du hafver der lust till, vill jag gifva dig en annan igen; men han sade: Jag vill icke låta dig få min vingård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Då sade Isebel hans hustru till honom: Hvad vore för ett rike i Israel, om du gjordet? Statt upp, och ät bröd, och var vid godt mod; jag vill skaffa dig Naboths den Jisreelitens vingård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Och hon skref bref under Achabs namn, och beseglade det med hans signet, och sände till de äldsta och öfversta i hans stad, de som bodde med Naboth;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Och skref brefvet alltså: Låter utropa en fasto, och sätter Naboth främst ibland folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Och låter komma två Belials män fram för honom, som vittna, och säga: Du hafver välsignat Gud och Konungen; och förer honom ut, och stener honom till döds.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'De äldste och hans stads öfverstar, som i hans stad bodde, gjorde såsom Isebel dem budit hade, såsom i brefvet skrifvet var, det hon till dem sändt hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Och läto utropa en fasto, och läto Naboth sitta öfverst ibland folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Då kommo de två Belials män, och ställde sig framför honom, och vittnade emot Naboth inför folket, och sade: Naboth hafver välsignat Gud och Konungen. Då förde de honom ut för staden, och stenade honom ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Och de bådade Isebel, och sade: Naboth är stenad, och död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Då nu Isebel hörde, att Naboth var stenad, och död, sade hon till Achab: Statt upp, och tag in Naboths vingård den Jisreelitens, den han dig nekat hafver för penningar; förty Naboth lefver icke, utan är död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Då Achab hörde, att Naboth var död, stod han upp, att han skulle gå ned till Naboths den Jisreelitens vingård, och taga honom in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Men Herrans ord kom till Elia den Thisbiten, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Statt upp, och gack ned emot Israels Konung, som är i Samarien; si, han är i Naboths vingård, dit han nedergången är, till att taga honom in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Och tala med honom, och säg: Så säger Herren: Du hafver dräpit, dertill ock intagit. Och du skall tala med honom, och säga: Detta säger Herren: På den staden, der hundar hafva slekt Naboths blod, skola ock hundar sleka ditt blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Och Achab sade till Elia: Hafver du ju funnit mig för din fienda? Han sade: Ja, hafver jag så funnit dig; derföre, att du såld äst till att intet annat göra, än det ondt är för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Si, jag skall låta komma ondt öfver dig, och borttaga dina efterkommande, och skall utrota utaf Achab ock den som på väggena pissar, och den som innelyckt och igenlefd är i Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Och skall göra ditt hus såsom Jerobeams hus, Nebats sons, och såsom Baesa hus, Ahia sons, för det retandets skull, der du mig med förtörnat hafver, och kommit Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Och om Isebel talade Herren desslikes, och sade: Hundar skola uppäta Isebel vid murarna i Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Hvilken af Achab dör i stadenom, den skola hundar äta; och hvilken som dör på markene, den skola foglar under himmelen äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Alltså var ingen, den, så alldeles såld var till att göra det ondt var för Herranom, såsom Achab; ty hans hustru Isebel eggade honom dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Och han gjorde sig till en stor styggelse, så att han vandrade efter afgudar, såsom de Amoreer gjort hade, hvilka Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Då Achab dessa orden hörde, ref han sönder sin kläder, och drog en säck på sin kropp, och fastade, och sof i säckenom, och gick luto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Och Herrans ord kom till Elia den Thisbiten, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Hafver du icke sett, huru Achab bugar sig för mig? Efter han nu bugar sig för mig, vill jag icke låta komma det onda i hans dagar; men i hans sons tid skall jag låta komma det onda öfver hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Och gingo tre år om, att intet örlig var emellan de Syrer och Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I tredje årena drog Josaphat, Juda Konung, ned till Israels Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Och Israels Konung sade till sina tjenare: Veten I icke, att Ramoth i Gilead är vårt, och vi sitte stilla, och tage det icke igen utu Konungens hand i Syrien?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Och sade till Josaphat: Vill du draga med mig i strid emot Ramoth i Gilead? Josaphat sade till Israels Konung: Jag vill vara såsom du, och mitt folk såsom ditt folk, och mina hästar såsom dina hästar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Och Josaphat sade till Israels Konung: Fråga dock i dag om Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Då församlade Israels Konung Propheter vid fyrahundrad män, och sade till dem: Skall jag draga till Ramoth i Gilead till strid, eller skall jag låta bestå det? De sade: Drag ditupp; Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Men Josaphat sade: Är här nu ingen Herrans Prophet mer, att vi måge, fråga af honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Israels Konung sade till Josaphat: Der är ännu en man, Micha, Jimla son, af hvilkom vi måge fråga Herran; men jag är vred på honom, ty han spår mig intet godt, utan allt ondt. Josaphat sade: Konungen tale icke så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Då kallade Israels Konung en kamererare, och sade: Haf med hast Micha, Jimla son, hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Och Israels Konung, och Josaphat, Juda Konung, såto hvardera på sinom stol, klädde i Konungslig kläder, på platsen för portenom af Samarien; och alle Propheterna spådde för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Och Zedekia, Chenaana son, hade gjort sig jernhorn, och sade: Detta säger Herren: Härmed skall du stöta de Syrer, tilldess du gör ända på dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Och alle Propheterna spådde sammalunda, och sade: Drag upp till Ramoth i Gilead, och far lyckosamliga; Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Och bådet, som bortgånget var till att kalla Micha, sade till honom: Si, Propheternas tal är endrägteliga godt för Konungenom; så låt nu ditt tal ock vara såsom deras tal, och tala det godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micha sade: Så sant som Herren lefver, jag skall tala det som Herren mig sägandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Och då han kom till Konungen, sade Konungen till honom: Micha, skole vi draga till Ramoth i Gilead till att strida, eller skole vi låta det bestå? Han sade till honom: Ja, drag ditupp, och far lyckosamliga. Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Konungen sade åter till honom: Jag besvär dig, att du icke annat säger mig än sanningen, i Herrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Han sade: Jag såg hela Israel förströdd på bergen såsom får, de ingen herdan hafva; och Herren sade: Hafva desse ingen herra? Hvar och en vände om hem igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Då sade Israels Konung till Josaphat: Hafver jag icke sagt dig, att han intet godt spår mig, utan allt ondt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Han sade: Derföre hör nu Herrans ord: Jag såg Herran sitta på sinom stol; och allan himmelska hären stå der när honom, på hans högra sido, och hans venstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Och Herren sade: Ho vill komma Achab i det sinnet, att han drager upp, och faller i Ramoth i Gilead? Och en sade det, och den andre det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Då gick en ande ut, och steg fram för Herran, och sade: Jag vill komma honom i det sinnet. Herren sade till honom: Hvarmed?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Han sade: Jag vill utgå, och vill vara en falsk ande uti alla hans Propheters mun. Han sade: Du skall komma honom i det sinnet, och få framgång; gack åstad, och gör alltså.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Nu se, Herren hafver gifvit en falsk anda uti alla dessa dina Propheters mun; och Herren hafver talat ondt öfver dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Då gick Zedekia fram, Chenaana son, och slog Micha vid kindbenet, och sade: Huru? Hafver då Herrans Ande öfvergifvit mig, och talat med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micha sade: Du skall få set på den dagen, då du går utu den ena kammaren uti den andra, att du må förgömma dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Israels Konung sade: Tag Micha, och låt honom blifva när Amon borgamästaren, och när Joas, Konungens son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Och säg: Detta säger Konungen: Sätter denna i fängsle, och spiser honom med bedröfvelses bröd och vatten, tilldess jag kommer igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Micha sade: Kommer du med frid igen, så hafver icke Herren talat genom mig. Och sade: Hörer häruppå, allt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Alltså drog Israels Konung och Josaphat, Juda Konung, upp till Ramoth i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Och Israels Konung sade till Josaphat: Jag vill förkläda mig, och komma i stridena; men du klädd i din egna kläder. Israels Konung förklädde sig, och drog i stridena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Men Konungen i Syrien böd sina öfverstar öfver hans vagnar, som voro två och tretio, och sade: I skolen icke strida antingen emot små eller stora, utan emot Israels Konung allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Och då de öfverste sågo Josaphats vagnar, mente de att det hade varit Israels Konung, och föllo till honom med stridene; men Josaphat ropade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Då nu då öfverste för vagnarna sågo, att det var icke Israels Konung, vände de tillbaka igen ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Och en man bände sin båga hårdt, och sköt Israels Konung emellan magan och lungorna. Och han sade till sin foroman: Vänd dina hand, och för mig utu hären; ty jag är sår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Och striden vardt svår i den dagen. Och Konungen stod uppå vagnen emot de Syrer, och om aftonen blef han död; och blodet flöt utaf såret midt i vagnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Och man lät utropa i hären, då solen gick neder, och säga: Hvar och en gånge i sin stad, och i sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Alltså blef Konungen död, och vardt förd till Samarien; och de begrofvo honom i Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Och då de tvådde vagnen vid dammen för Samarien, slekte hundar hans blod; och skökor tvådde honom, efter Herrans ord, det han talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Hvad mer af Achab sägandes är, och hvad allt han gjort hafver, och om det elphenbenshus som han byggde, och om alla de städer som han byggde, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Alltså afsomnade Achab med sina fäder; och hans son Ahasia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Och Josaphat, Asa son, vardt Konung öfver Juda, i fjerde årena Achabs, Israels Konungs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Och var fem och tretio år gammal, då han vardt Konung, och regerade fem och tjugu år i Jerusalem; hans moder het Asuba, Silhi dotter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Och vandrade uti allom sins faders Asa väg, och gick icke derifrå, och gjorde det Herranom behagade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Dock kastade han icke bort de höjder; och folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Och han hade frid med Israels Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Hvad nu mer af Josaphat sägandes är, och hans magt, hvad han gjort, och huru han stridt hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Och fördref han desslikes utu landena hvad ännu qvart var af de roffare, som i hans faders Asa tid igenblefne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Och ingen Konung var i Edom; men en höfvitsman var regent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Och Josaphat hade låtit göra skepp i hafvet, som skulle till Ophir att hemta guld; men de foro intet åstad; förty de vordo sönderslagne i EzionGeber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'På den tiden sade Ahasia, Achabs son, till Josaphat: Låt mina tjenare fara med dina tjenare i skeppen; men Josaphat ville icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Och Josaphat afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids hans faders stad; och Joram hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahasia, Achabs son, vardt Konung öfver Israel i Samarien, i sjuttonde årena i Josaphats, Juda Konungs, och regerade öfver Israel i tu år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Och gjorde det ondt var för Herranom, och vandrade i sins faders och sine moders väg, och i Jerobeams, Nebats sons, väg, hvilken Israel kom till att synda. Och han tjente Baal, och tillbad honom, och förtörnade Herran Israels Gud, såsom hans fader gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Och de Moabiter föllo af ifrån Israel, då Achab död var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Och Ahasia föll genom gallren i sinom sal i Samarien, och vardt krank; och sände ut bådskap, och sade till dem: Går bort, och fråger BaalSebub, den guden i Ekron, om jag skall vederfås af denna krankheten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Men Herrans Ängel sade till Elia den Thisbiten: Statt upp, och gack emot Konungens bådskap i Samarien, och säg till dem: Är nu ingen Gud i Israel, att I behöfven gå bort, och fråga BaalSebub, Ekrons gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Derföre, så säger Herren: Du skall icke komma utaf sängene, der du dig på lagt hafver; utan skall döden dö. Och Elia gick sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Och då båden igenkommo till honom, sade han till dem: Hvi kommen I igen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'De sade till honom: En man kom upp emot oss, och sade till oss: Går tillbaka igen till Konungen, som eder utsändt hafver, och säger till honom: Detta säger Herren: Är nu ingen Gud i Israel, att du skall sända bort, och fråga BaalSebub, Ekrons gud? Derföre skall du icke komma af sängene, der du hafver lagt dig uppå; utan skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Han sade till dem: Hurudana var den mannen, som eder mötte, och sade detta till eder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'De sade till honom: Mannen var luden, och en lädergjord om hans länder. Han sade: Det är Elia den Thisbiten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Och han sände bort till honom en höfvitsman öfver femtio, med de samma femtio. Och då han kom upp till honom, si, då satt han uppe på bergena; och han sade till honom: Du Guds man, Konungen säger: Du skall komma ned:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elia svarade höfvitsmannen öfver femtio, och sade till honom: Är jag en Guds man, så falle eld af himmelen, och upptäre dig och dina femtio. Då föll eld af himmelen, och upptärde honom och hans femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Och han sände åter en: annan höfvitsman öfver femtio till honom, med hans femtio: Han sade till honom: Du Guds man, detta säger Konungen: Kom snarliga ned.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elia svarade, och sade: Är jag en Guds man, så falle eld af himmelen, och upptäre dig och dina femtio. Då föll Guds eld af himmelen, och upptärde honom och hans femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Då sände han ännu den tredje höfvitsmannen öfver femtio, med hans femtio. Då han kom upp till honom, böjde han sin knä för Elia, och bad honom, och sade till honom: Du Guds man, låt mina själ, och dina tjenares, dessa femtios själar, något aktade varda för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Si, elden är fallen af himmelen, och hafver upptärt de första två höfvitsmän öfver femtio, med deras femtio; men nu låt mina själ något aktad varda för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Då sade Herrans Ängel till Elia: Gack ned med honom, och frukta dig intet för honom. Han stod upp, och gick ned med honom till Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Och han sade till honom: Så säger Herren: Derföre, att du sände bådskap bort, och lät fråga BaalSebub, Ekrons gud, likasom ingen Gud vore i Israel, hvilkens ord man fråga kunde, så skall du icke komma af sängene, der du hafver lagt dig uppå; utan skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Alltså blef han död, efter Herrans ord, det Elia talat hade. Och Joram vardt Konung i hans stad, i andra årena Jorams, Josaphats sons, Juda Konungs; ty han hade ingen son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Hvad nu mer af Ahasia sägandes är, hvad han gjort hafver, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Då nu Herren ville upptaga Elia i vädret till himmelen, gick Elia och Elisa från Gilgal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Och Elia sade till Elisa: Käre, blif här; ty Herren hafver sändt mig till BethEl; men Elisa sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de kommo ned till BethEl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Då gingo de Propheters söner, som i BethEl voro, ut till Elisa, och sade till honom: Vetst du ock, att Herren varder i denna dag tagandes din herra ifrå ditt hufvud? Han sade: Jag vet det ock väl; tiger man stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Och Elia sade till honom: Elisa, käre, blif här; ty Herren hafver sändt mig till Jericho. Han sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de kommo till Jericho.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Då gingo de Propheters söner, som i Jericho voro, till Elisa, och sade till honom: Vetst du ock, att Herren varder i denna dag tagandes din herra ifrå ditt hufvud? Han sade: Jag vet det ock väl; tiger man stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Och Elia sade till honom: Käre, blif här; förty Herren hafver sändt mig till Jordan. Han sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de gingo både tillsamman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Men femtio män af Propheternas söner gingo bort, och blefvo ståndande tvärt öfver, långt ifrå dem; men de både stodo vid Jordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Då tog Elia sin mantel, och svepte honom ihop, och slog i vattnet, och det delade sig på båda sidor; så att de både gingo torre derigenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Och då de öfver kommo, sade Elia till Elisa: Bed hvad jag dig göra skall, förr än jag varder ifrå dig tagen. Elisa sade: Att din ande varder öfver mig, till att tala dubbelt så mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Han sade: Du hafver bedit en svår ting; dock, om du ser mig, när jag varder ifrå dig tagen, så sker det; hvar ock icke, så sker det intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Och vid de gingo tillsamman och talade, si, då kom en brinnande vagn med brinnande hästar, och skiljde dem båda ifrå hvarannan; och Elia for så upp i vädret till himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Men Elisa såg det, och ropade: Min fader, min fader, Israels vagn, och hans resenärar; och såg honom intet mer. Och han fattade sin kläder, och ref dem i tu stycker;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Och tog upp Elia mantel, som ifrå honom fallen var, och vände om, och gick till Jordans strand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Och tog den samma Elia mantel, som ifrå honom fallen var, och slog i vattnet, och sade: Hvar är nu Herren, Elia Gud? och slog i vattnet; så delade det sig på båda sidor, och Elisa gick derigenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Och då Propheternas söner, som i Jericho tvärsöfver voro, sågo honom, sade de: Elia ande blifver på Elisa; och gingo emot honom, och tillbådo på jordena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Och sade till honom: Si, ibland dina tjenare äro femtio starke män; låt dem gå och söka din herra; tilläfventyrs Herrans Ande hafver tagit honom, och kastat honom någorstäds uppå ett berg, eller någorstäds uti en dal. Han sade: Låter intet gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Men de nödgade honom, tilldess han skämdes, och sade: Låter gå dem. Och de sände åstad femtio män; och de sökte honom i tre dagar, och funno honom intet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Och kommo åter till honom; och han blef i Jericho, och sade till dem: Sade jag icke eder, att I icke skullen gå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Och männerna i stadenom sade till Elisa: Si, det är godt att bo i denna staden, såsom min herre ser; men här är ondt vatten, och landet ofruktsamt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Han sade: Tager mig hit ett nytt kärile, och lägger salt deruti. Och de gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Då gick han ut till vattukällona, och kastade saltet deruti, och sade: Så säger Herren: Jag hafver gjort detta vattnet helbregda; ingen död eller ofruktsamhet skall härefter komma deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Alltså vardt vattnet helbregda allt intill denna dag, efter Elisa ord, som han talade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Och han gick upp till BethEl; och vid han var på vägen ditåt, kommo små piltar utaf staden, och begabbade honom, och sade till honom: Du skallote, kom upp; du skallote, kom upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Och han vände sig om; och då han såg dem, bannade han dem i Herrans Namn. Då kommo två björnar utu skogenom, och refvo två och fyratio piltar ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Dädan gick han upp på Carmels berg, och vände sedan om dädan till Samarien igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, Achabs son, vardt Konung öfver Israel i Samarien, uti adertonde årena Josaphats, Juda Konungs; och regerade i tolf ar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Och gjorde det ondt varför Herranom, dock icke såsom hans fader och hans moder; ty han kastade bort Baals stöder, som hans fader hade göra låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Men han blef vid Jerobeams, Nebats sons, synder, hvilken kom Israel till att synda; och trädde intet derifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Men Mesa, de Moabiters Konung, hade mång får, och han skattade Israels Konunge ull af hundradetusend lamb, och af hundradetusend vädrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Då nu Achab var död, föll de Moabiters Konung af ifrån Israels Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Då drog ut på den tiden Konung Joram af Samarien, och skickade hela Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Och sände bort till Josaphat, Juda Konung, och lät säga honom: De Moabiters Konung är affallen ifrå mig. Kom med mig till att strida emot de Moabiter. Han sade: Jag vill uppkomma; jag är såsom du, och mitt folk såsom ditt folk, och mine hästar såsom dine hästar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Och sade: Hvilken vägen vilje vi draga ditupp? Han sade: Den vägen igenom Edoms öken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Alltså drogo åstad Israels Konung, Juda Konung, och Edoms Konung. Och som de omkringdragit hade sju dagsresor, hade hären, och de öker, som med dem voro, intet vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Då sade Israels Konung: Ack, ve! Herren hafver dessa tre Konungar församlat, på det han skall gifva dem uti de Moabiters händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Men Josaphat sade: Är här ingen Herrans Prophet, att vi måge genom honom fråga Herran? Då svarade en ibland Israels Konungs tjenare, och sade: Här är Elisa, Saphats son, hvilken göt vatten på Elia händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat sade: Herrans ord är när honom. Alltså drogo neder till honom Israels Konung, och Josaphat, och Edoms Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Då sade Elisa till Israels Konung: Hvad hafver du med mig skaffa? Gack bort till dins faders Propheter, och till dine moders Propheter. Israels Konung sade till honom: Nej; ty Herren hafver församlat dessa tre Konungar, på det han skall gifva dem uti de Moabiters händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sade: Så sant som Herren Zebaoth lefver, för hvilkom jag står, om jag icke ansåge Josaphat, Juda Konung, jag ville icke anse dig eller akta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Så låter nu en spelman komma hit. Och då spelmannen spelade på strängerna, kom Herrans hand öfver honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Och han sade: Detta säger Herren: Görer grafver vid denna bäcken här och der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Förty så säger Herren: I skolen intet väder eller regn se; likväl skall bäcken varda full med vatten, så att I, och edart folk, och edra öker skola få dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Dertill är detta en ringa ting för Herranom; han skall ock gifva de Moabiter i edra händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Så att I skolen slå alla fasta städer, och alla utvalda städer, och skolen omkullhugga all god trä, och skolen förstoppa alla vattubrunnar, och skolen förderfva alla goda åkrar med stenar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Om morgonen, då man spisoffer offrade, si, då kom ett vatten på den vägen ifrån Edom, och fyllde landet med vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Då nu de Moabiter hörde, att Konungarna drogo upp till att strida emot dem, kallade de tillhopa alla, som vuxne voro att bära vapen, och derutöfver, och drogo intill gränson.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Och som de om morgonen bittida uppstode, och solen uppgick öfver vattnet, tyckte de Moabiter, att vattnet emot dem var rödt såsom blod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Och de sade: Det är blod; Konungarna hafva slagits inbördes med svärd, och den ene hafver slagit den andra. Nu Moab, statt upp, och tag byte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Men då de kommo till Israels lägre, reste Israel upp, och slog de Moabiter, och de flydde för dem; men de kommo in, och slogo Moab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Bröto städerna neder, och hvar och en kastade sin sten på alla goda åkrar, och uppfyllde dem, och förstoppade alla vattubrunnar, och fällde all god trä, tilldess att allenast stenarna i tegelmuren qvare blefvo; och de kringhvärfde staden med slungor, och slogo honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Då de Moabiters Konung såg att striden vardt honom för stark, tog han sjuhundrade män till sig, som svärd utdrogo, till att slå ut emot Edoms Konung; men de kunde icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Då tog han sin första son, som i hans stad skulle Konung vordit, och offrade honom till ett bränneoffer på muren. Då kom en stor vrede öfver Israel; så att de drogo ifrå honom, och vände till landet igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Och en qvinna utaf de Propheters söners hustrur ropade till Elisa, och sade: Din tjenare, min man, är död blefven; så vetst du, att han din tjenare fruktade Herran; nu kommer den han skyldig var, och vill taga båda mina söner till trälar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sade till henne: Hvad skall jag göra dig? Säg mig, hvad hafver du i huset? Hon sade: Din tjenarinna hafver intet i huset, utan ena kruko med oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Han sade: Gack bort, och beds af alla dina grannhustrur tom käril, väl mång;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Och gack in, och slut dörrena igen efter dig, med dina söner, och gjut i all kärilen; och när du hafver fyllt dem, så tag bort dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Hon gick bort, och slöt dörrena igen efter sig, samt med sina söner; de båro kärilen fram till henne, och hon göt uti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Och då kärilen voro full, sade hon till sin son: Hemta mig ännu ett kärile. Han sade till henne: Här är intet kärile mer. Så stadnade oljan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Och hon gick bort, och sade det Guds mannenom. Han sade: Gack bort, sälj oljona, och betala dem du skyldig äst; men du och dine söner, lefver utaf det andra, som öfver är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Och det begaf sig på en tid, att Elisa gick till Sunem. Der var en rik qvinna, och hon höll honom uppe, så att han fick sig der mat. Och som han ofta färdades derigenom, gick han ju in till henne, och åt när henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Och hon sade till sin man: Si, jag förmärker, att denne Guds mannen är helig, som alltid går här fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Låt oss göra en liten brädesal, och sätta derin en säng, bord, stol, och ljusastaka; på det att, när han till oss kommer, må han der blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Så hände det sig på en tid, att han kom ditin, och lade sig i salen, och sof derinne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Och sade till sin tjenare Gehasi: Kalla den Sunamitiskona. Och då han hade kallat henne, gick hon fram för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Han sade till honom; Säg henne: Si, du hafver gjort oss alla denna tjenstena; hvad skall jag göra dig? Hafver du något värf till Konungen, eller till härhöfvitsmannen? Hon sade: Jag bor ibland mitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Han sade: Hvad skall man då göra henne? Gehasi sade: Ack! hon hafver ingen son, och hennes man är gammal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Han sade: Kalla henne. Och då han hade kallat henne, kom hon i dörrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Och han sade: På denna tiden, när frukten kan lefva, skall du hafva en son i famnen. Hon sade: Ack! nej, min Herre, du Guds man, ljug icke för dine tjenarinno.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Och qvinnan vardt hafvandes, och födde en son, på samma tiden då frukten lefva kunde, såsom Elisa hade sagt henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Då pilten vardt stor, hände sig, att han gick ut till sin fader, till skördemännerna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Och sade till sin fader: Ack! mitt hufvud, mitt hufvud. Han sade till sin tjenare: Haf honom bort till sina moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Och han tog honom, och hade honom till hans moder. Och hon satte honom i sitt sköte allt intill middagen; då blef han död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Och hon gick upp, och lade honom på Guds mansens säng, slöt till, och gick ut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Och kallade sin man, och sade: Sänd mig en af tjenarena, och ena åsninno; jag vill till Guds mannen, och komma igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Han sade: Hvi vill du till honom? Är dock i dag icke nymånad eller Sabbath. Hon sade: Väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Och hon sadlade åsninnona, och sade till tjenaren: Drif uppå, och låt oss icke töfva med ridandet, såsom jag säger dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Alltså drog hon åstad, och kom till Guds mannen på Carmels berg. Som nu Guds mannen såg henne komma, sade han till sin tjenare Gehasi: Si, den Sunamitiskan är der;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Så löp nu emot henne, och fråga henne, om henne, och hennes man, och son väl går. Hon sade: Väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Men då hon uppkom till Guds mannen på berget, fick hon honom om hans fötter. Och Gehasi gick fram, och ville drifva henne bort; men Guds mannen sade: Låt blifva henne; förty hennes själ är bedröfvad; och Herren hafver mig det fördolt, och icke låtit mig det förstå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Hon sade: När hafver jag bedts en son af min herra? Sade jag icke, att du icke skulle bespotta mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Han sade till Gehasi: Begjorda dina länder, och tag min staf i dina hand, och gack åstad; om någor möter dig, så helsa honom intet; och om någor helsar dig, så svara honom intet; och lägg min staf på piltens anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Men piltens moder sade: Så sant som Herren lefver, och din själ, jag släpper dig icke. Då stod han upp, och följde henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Men Gehasi var allaredo gången framför dem, och lade stafven på piltens anlete; men der var hvarken röst eller sinne. Och han gick tillbaka igen emot honom, och bådade honom, och sade: Pilten är icke uppväckt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Och då Elisa kom i huset, si, då låg pilten död på hans säng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Och han gick in, och slöt igen dörrena om sig båda, och bad till Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Och steg upp, och lade sig öfver pilten, och lade sin mun på piltens mun, och sin ögon på hans ögon, och sina händer på hans händer, och räckte sig så ut öfver honom, så att piltens kropp vardt varm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Men han stod åter upp, och gick en gång hit och dit i huset, och steg upp, och räckte sig ut öfver honom. Då prustade pilten sju resor; sedan lät pilten ögonen upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Och han kallade Gehasi, och sade: Kalla Sunamitiskona. Och då han hade kallat henne, kom hon in till honom. Han sade: Tag här din son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Då kom hon, och föll till hans fötter, och tillbad på jordena; och tog sin son, och gick ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Då Elisa kom igen till Gilgal, vardt dyr tid i landena, och de Propheters söner bodde för honom. Och han sade till sin tjenare: Sätt fram en stor gryto, och koka ett mos för Propheternas söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Så gick en ut på markena till att hemta krydde; och han fann en kurbitsstjelk, och hemte deraf vildkurbits sitt kläde fullt. Och då han kom, skar han det i grytona till moset; förty de kände det icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Och då de gåfvo det upp för männerna till att äta, och de åto af moset, ropade de, och sade: O! Guds man, döden i grytone; ty de kunde icke ätat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Han sade: Hafver hit mjöl; och han kastade det i grytona, och sade: Gif upp för folket, att de måga äta. Så var det intet bittert i grytone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Och en man kom ifrå BaalSalisa, och bar Guds mannenom förstlingsbröd, nämliga tjugu bjuggbröd, och ny säd i sin kjortel. Men han sade: Gif det folkena, att de äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Hans tjenare sade: Hvad kan det slå framför hundrade män? Han sade: Gif det folkena, att de måga äta; förty så säger Herren: De skola äta, och skall ändå öfverblifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Och han lade det fram för dem, så att de åto; och blef ändå öfver, efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, Konungens härhöfvitsman af Syrien, var en härlig man för sin herra, och mycket aktad; förty genom honom hade Herren gifvit salighet i Syrien; och han var en mägtig man, dock spitelsk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Och krigsmännerna i Syrien voro utfallne, och hade bortfört en liten pigo utur Israels land; och hon var i tjenst när Naamans hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Hon sade till sina fru: Ack! att min herre vore när den Propheten i Samarien, den skulle väl göra honom fri ifrå hans spitelsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Då gick hon in till sin herra, och gaf honom det tillkänna, och sade: Så och så hafver den pigan af Israels land sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Konungen i Syrien sade: Så far dit, och jag vill skrifva Israels Konung ett bref till. Och han drog dit, och tog med sig tio centener silfver, och sextusend gylden, och tio högtidskläder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Och förde brefvet till Israels Konung, och det lydde alltså: När detta bref kommer till dig, si, så vet att jag hafver sändt min tjenare Naaman till dig, att du gör honom fri ifrån hans spitelsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'När Israels Konung las brefvet, ref han sin kläder sönder, och sade: Är jag då Gud, att jag skulle kunna döda och lif gifva, efter han sänder till mig, att jag skall göra den mannen fri ifrå hans spitelsko? Märker och ser, huru han söker tillfälle emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Då Elisa den Guds mannen det hörde, att Israels Konung hade rifvit sin kläder sönder, sände han till honom, och lät säga honom: Hvi hafver du rifvit din kläder? Låt honom komma till mig, att han må förnimma att en Prophet är i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Alltså kom Naaman med hästar och vagnar, och höll för Elisa husdörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Då sände Elisa ett båd till honom, och lät säga honom: Gack bort, och två dig sju resor i Jordan; och ditt kött skall komma sig till igen, och varda rent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Då vardt Naaman vred, och drog sina färde, och sade: Jag mente han skulle komma hitut till mig, och gå fram, och åkalla Herrans sins Guds Namn, och med sine hand taga på rummet, och så bota spitelskona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Äro icke Abana och Pharphars vatten i Damascon bättre än all vatten i Israel, att jag må två mig deruti, och varda ren? Och vände sig, och for sin väg med vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Då gingo hans tjenare till honom, och talade till honom, och sade: Min fader, om Propheten hade sagt dig något dråpeligit före, skulle du icke hafva gjort det? Huru mycket mer, medan han säger till dig: Två dig, så varder du ren?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Då steg han af, och doppade sig i Jordan sju resor, såsom Guds mannen sagt hade; och hans kött kom till sig igen, såsom en ung drängs kött, och vardt ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Och han vände om igen till Guds mannen, med all sin skara. Och då han kom in, gick han fram för honom, och sade: Si, jag vet, att ingen Gud är i all land, utan i Israel; så tag nu välsignelse af dinom tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Men han sade: Så sant som Herren lefver, för hvilkom jag står, jag tager det icke. Och han nödgade honom, att han skulle tågat; men han ville icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Då sade Naaman: Må då icke dinom tjenare varda gifvet en börda af denna jordene, så mycket som två mular orka bära? ty din tjenare vill icke mer androm gudom offra, och bränneoffer göra, utan Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Att Herren ville derutinnan vara dinom tjenare nådelig, när jag tillbeder i Rimmons hus, när min herre går uti Rimmons hus till att tillbedja der, och han stödjer sig vid mina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Han sade till honom: Far i frid. Och han for ifrå honom ett litet stycke vägs på markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Då tänkte Gehasi, Gudsmannens Elisa tjenare: Si, min herre hafver spart denna Syren Naaman, så att han intet hafver tagit af honom, det han hit hade; så sant som Herren lefver, jag vill löpa efter honom, och taga något af honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Alltså jagade Gehasi efter Naaman; och då Naaman såg, att han lopp efter honom, steg han af vagnen emot honom, och sade: Går det väl till?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Han sade: Ja; men min herre hafver sändt mig, och låter dig säga: Si, nu på stundene äro till mig komne ifrå Ephraims berg två unga män utaf de Propheters söner. Gif dem en centener silfver, och tu högtidskläder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman sade: Gerna; tag två centener. Och han nödgade honom, och band två centener silfver i två säcker, och tu högtidskläder, och fick det två sina tjenare; och de båro det med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Och då han kom till mörkt rum, tog han det utaf deras händer, och lade det öfver en sido i huset, och lät männerna gå; och de gingo bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Då gick han fram för sin herra. Och Elisa sade till honom: Hvadan kommer du, Gehasi? Han sade: Din tjenare hafver hvarken hit eller dit gångit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Han sade till honom: Månde icke mitt hjerta vandra med dig, då mannen vände om igen ifrå sin vagn emot dig? Nu, du hafver tagit silfver och kläder, oljogårdar, vingårdar, får, oxar, tjenare och tjenarinnor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Men Naamans spitelska skall låda vid dig, och dina säd, till evig tid. Så gick han ut ifrå honom spitelsker såsom en snö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'De Propheters söner sade till Elisa: Si, rummet, der vi för dig bo, är oss för trångt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Låt oss gå till Jordan; och hvar och en hemte der timber, att vi måge bygga oss der ett rum till att bo uti. Han sade: Går åstad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Och en sade: Kom ock du, och gack med dina tjenare. Han sade: Jag vill gå med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Och han gick med dem. Och då de kommo till Jordan, höggo de trä neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Och som en af dem fällde ett trä, föll yxen i vattnet; och han ropade, och sade: Ack! ve, min herre; och hon är mig lånt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Men Guds mannen sade: Hvar är hon fallen? Och då han viste honom rummet, skar han ett trä af, och kastade det dit; och yxen flöt uppe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Och han sade: Tag henne upp. Han räckte ut sina hand, och tog henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Och Konungen i Syrien förde örlig emot Israel. Och han rådfrågade med sina tjenare, och sade: Vi vilje lägra oss der och der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Men Guds mannen sände till Israels Konung, och lät säga honom: Tag dig till vara, att du icke drager till det rummet; förty de Syrer ligga der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Så sände då Israels Konung bort till det rummet, som Guds mannen om sade, förvarade det, och höll der vakt; och gjorde det icke en gång eller två gångor allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Då vardt Konungens hjerta i Syrien illa tillfreds deröfver, och kallade sina tjenare, och sade till dem: Viljen I då icke säga mig, hvilken af våra är flydd till Israels Konung?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Då sade en af hans tjenare: Icke så, min herre Konung; utan Elisa, den Propheten i Israel, säger Konungenom i Israel allt det du talar i kammaren, der din säng är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Han sade: Så går bort, och ser till hvar han är, att jag må sända bort och låta hemta honom. Och de underviste honom, och sade: Si, i Dothan är han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Då sände han dit hästar och vagnar, och en stor magt. Och som de ditkommo om nattena, belade de staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Och Guds mansens tjenare stod bittida upp, att han skulle gå ut; och si, då låg en här om staden, med hästar och vagnar. Då sade hans tjenare till honom: Ack! ve, min Herre, hvad vilje vi nu göra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Han sade: Frukta dig intet; förty de äro flere som med oss äro, än de som med dem äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Och Elisa bad, och sade: Herre, öppna honom ögonen, att han må se. Då öppnade Herren tjenarenom hans ögon, att han fick se. Och si, då var berget fullt med brinnande hästar och vagnar omkring Elisa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Och då de kommo ditneder till honom, bad Elisa, och sade: Herre, slå detta folket med blindhet Och han slog dem med blindhet, efter Elisa ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Och Elisa sade till dem: Detta är icke den vägen, eller den staden; följer mig efter, jag vill föra eder till den man, som I söken; och förde dem till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Som de kommo till Samarien, sade Elisa: Herre, öppna dessom ögonen, att de måga se. Och Herren öppnade dem ögonen, att de sågo. Och si, då voro de midt i Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Och Israels Konung, då han såg dem, sade han till Elisa: Min fader, skall jag slå dem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Han sade: Du skall icke slå dem; de som du får med ditt svärd och båga, dem slå. Sätt dem vatten och bröd före, att de måga äta och dricka; och lät dem fara till sin herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Så vardt dem tillredd en stor måltid. Och när de hade ätit och druckit, lät han dem gå, så att de drogo till sin herra. Och sedan kom icke mer krigsfolk af Syrien i Israels land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Derefter begaf sig, att Benhadad, Konungen i Syrien, församlade all sin här, och drog upp, och belade Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Och en hård tid var i Samarien; men de belade staden, intilldess ett åsnahufvud galt åttatio silfpenningar; och en fjerdedel af ett kab dufvoträck fem silfpenningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Och då Israels Konung gick på murenom, ropade en qvinna till honom, och sade: Hjelp mig, min herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Han sade: Hjelper icke Herren dig, hvadan skulle jag hjelpa dig? Af loganom, eller af pressenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Och Konungen sade till henne: Hvad är dig? Hon sade: Denna qvinnan sade till mig: Få hit din son, att vi måge äta honom, i dag; i morgon vilje vi äta min son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Så hafve vi kokat min son, och ätit. Och jag sade till henne den andra dagen: Få hit din son, och låt oss äta; men hon undstack sin son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Då Konungen hörde qvinnones ord, ref han sin kläder sönder, vid han gick på murenom. Då såg allt folket, att han hade en säck på kroppenom, innan under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Och han sade: Gud göre mig det och det, om Elisa, Saphats sons, hufvud skall i dag blifva ståndandes på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Och Elisa satt i sitt hus. Och de äldste såto när honom. Och han sände en man framför sig. Men förr än bådet kom till honom sade han till de äldsta: Hafven I sett, huru denne mördaren hafver hitsändt, att taga mitt hufvud af? Ser till, när bådet kommer, att I lycken dörrena igen, och klämmer honom med dörrene; si, dönen af hans herras fötter följer efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Vid han ännu med dem talade, si, då kom bådet ned till honom, och sade: Si, detta onda kommer af Herranom; hvad skall jag mer vänta af Herranom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Men Elisa sade: Hörer Herrans ord; så säger Herren: I morgon på denna tiden skall en skäppa semlomjöl gälla en sikel, och två skeppor bjugg en sikel, i Samarie port.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Då svarade en riddare, vid hvilkens hand Konungen sig stödde, Guds mannenom, och sade: Om Herren än gjorde fenster på himmelen, huru kunde detta ske? Han sade: Si, du skall få se det med din ögon; men intet skall du äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Och fyra spitelske män voro utan porten, och den ene sade till den andra: Hvad vilje vi blifva här tilldess vi dö?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Det vi än ville gå in i staden, så är hård tid i stadenom, att vi måste dock der dö; blifve vi ock här, så måste vi ock dö. Så låt oss nu gå bort, och gifva oss till de Syrers här; låta de oss lefva, så lefve vi; dräpa de oss, så äre vi döde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Och de voro bittida uppe om morgonen, på det de skulle gå till de Syrers här. Och som de kommo till det främsta på lägret, si, då var der ingen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Ty Herren hade låtit de Syrer höra en gny af hästar och vagnar, och af en mägtig här, så att de sade till hvarannan: Si, Israels Konung hafver besoldat emot oss de Hetheers Konungar, och de Egyptiers Konungar, att de skola komma öfver oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Och stodo upp, och flydde bittida om morgonen, och läto blifva sina hyddor, hästar, åsnar och lägret, såsom det stod, och flydde med deras lif derifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Som nu de spitelske kommo till det främsta af lägret, gingo de in uti ena hyddo; åto och drucko, och togo silfver och guld, och kläder, och gingo bort, och förgömde det; och kommo igen, och gingo in uti en annor hyddo, och togo derut, och gingo bort, och förgömde det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Men de sade till hvarannan: Låt oss icke så göra; denne dagen är ett godt bådskaps dag; om vi detta förtige, och bide intill ljus morgon, så varder vår missgerning funnen. Så låt oss nu gå bort och bebåda det i Konungshuset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Och då de kommo, ropade de vid stadsporten, och underviste dem och sade: Vi kommo uti de Syrers lägre, och si, der är ingen, ej heller någor menniskos röst; utan hästar och åsnar bundne, och hyddorna såsom de stå. Och riddaren svarade Guds mannenom, och sade: Si, om Herren än gjorde fenster på himmelen, huru kunde detta ske? Men han sade: Si, med din ögon skall du se det, och intet äta deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Då ropade man till porthållarena, att de skulle det derinne säga i Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Och Konungen stod upp om nattena, och sade till sina tjenare: Jag vill säga eder, huru de Syrer bära sig åt med oss; de veta att vi lide hunger, och äro utu lägret gångne, och hafva fördolt sig i markene, och tänka: När de gå utu staden, vilje vi gripa dem lefvande, och komma så i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Då svarade en af hans tjenare, och sade: Man må taga de fem hästar, som ännu igenblefne äro härinne; si, de äro härinne igenblefne af hela hopen i Israel, de andre äro åtgångne; låt oss dem sända och, beset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Då togo de två vagnhästar; och Konungen sände dem till i de Syrers lägre, och sade: Farer, och ser till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Och de drogo efter dem allt intill Jordan, si, då låg vägen full med kläder och tyg, som de Syrer hade ifrå sig kastat, då de hastade sig. Båden kommo igen, och underviste det Konungenom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Då gick folket ut, och skinnade de Syrers lägre. Och så galt en skäppa semlomjöl en sikel, och desslikes två skäppor bjugg ock en sikel, efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Men Konungen skickade den riddaren, vid hvilkens hand han stödde sig, i porten; och folket förtrampade honom i portenom, så att han blef död, såsom Guds mannen sagt hade, då Konungen hade gångit ned till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Och skedde såsom Guds mannen med Konungenom talat hade, då han sade: I morgon på denna tiden skola två skäppor bjugg gälla en sikel, och en skäppa semlomjöl en sikel, i Samarie port.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Och det gick honom ock så; ty folket förtrampade honom i portenom, så att han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa talade med den qvinnone, hvilkens son han hade lefvande gjort, och sade: Statt upp och gack dina färde med ditt hus, och var främmande hvar du kan; ty Herren varder kallandes en hunger, och han skall komma öfver landet i sju är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Qvinnan stod upp, och gjorde såsom Guds mannen sade: och drog åstad med sitt hus, och var främmande uti de Philisteers land i sju är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Då de sju åren förlidne voro, kom qvinnan åter utu de Philisteers land; och hon gick ut till att ropa till Konungen om sitt hus och åker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Då talade Konungen med Gehasi, den Guds mansens tjenare, och sade: Förtälj mig all de stora ting, som Elisa gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Och som han förtäljde Konungenom, huru han hade gjort en dödan lefvande, si, i det samma kom qvinnan dertill, hvilkens son han hade lefvande gjort, och ropade till Konungen om sitt hus och åker. Då sade Gehasi: Min herre Konung, detta är qvinnan, och detta är hennes son, som Elisa hafver lefvande gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Och Konungen frågade qvinnona, och hon förtäljde honom det. Då fick Konungen henne en kamererare, och sade: Fly henne igen allt det hennes är; dertill allt afgället af åkrenom, ifrå den tid hon öfvergaf landet intill nu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Och Elisa kom till Damascon; då låg Benhadad, Konungen i Syrien, krank; och honom vardt bådadt och sagdt: Den Guds mannen är kommen här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Då sade Konungen till Hasael: Tag skänker med dig, och gack emot den Guds mannen, och fråga genom honom Herran, och säg: Månn jag vederfås af denna krankheten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hasael gick emot honom, och tog skänker med sig, och allahanda ägodelar i Damascon, fyratio camelers bördor. Och då han kom, gick han fram för honom, och sade: Din son Benhadad, Konungen i Syrien, hafver sändt mig till dig, och låter säga dig: Kan jag ock vederfås af denna krankheten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sade till honom: Gack bort, och säg honom: Du skall vederfås; men Herren hafver undervist mig, att han skall döden dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Och Guds mannen begynte se skarpt ut, och hade sig ömkeliga, och gret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Då sade Hasael: Hvi gråter min herre? Han sade: Jag vet hvad ondt du skall göra Israels barnom; du skall uppbränna deras fasta städer med eld, och deras unga män dräpa med svärd, och döda deras unga barn, och deras hafvande qvinnor sönderrifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sade: Hvad är din tjenare, den hunden, att han sådana stor ting göra skall? Elisa sade: Herren hafver tett mig, att, du skall varda Konung i Syrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Och han gick sin väg ifrån Elisa, och kom till sin herra. Han sade till honom: Hvad sade dig Elisa? Han svarade: Han sade mig: Du skall vederfås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Men på den andra dagen tog han täckenet, och stack det i vatten, och bredde öfver sig; då blef han död. Och Hasael vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Uti femte årena Jorams, Achabs sons, Israels Konungs, i Josaphats, Juda Konungs, tid, vardt Joram, Josaphats son, regerande i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Tu och tretio år gammal var han, då han vardt Konung, och regerade åtta år i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Och vandrade på Israels Konungars väg, såsom Achabs hus gjorde; ty Achabs dotter var hans hustru; och han gjorde det ondt var för Herran om.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Men Herren ville icke förderfva Juda, för sin tjenare Davids skull, såsom han honom sagt hade, att gifva honom en lykto ibland hans barn i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Uti hans tid föllo de Edomeer af ifrå Juda, och gjorde en Konung öfver sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Förty Joram var dragen genom Zair, och alla vagnarna med honom, och hade ståndit upp om nattena, och slagit de Edomeer, som omkring honom voro; dertill ock de öfversta öfver vagnarna, så att folket flydde i sina hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Derföre föllo de Edomeer af ifrå Juda, allt intill denna dag. Föll ock desslikes Libna af på samma tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Hvad nu mer af Joram sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Och Joram afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids stad; och Ahasia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Uti tolfte årena Jorams, Achabs sons, Israels Konungs, vardt Ahasia, Jorams son, Konung i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Tu och tjugu år gammal var Ahasia, då han Konung vardt, och regerade ett år i Jerusalem; hans moder het Athalja, Amri dotter, Israels Konungs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Och han vandrade på Achabs hus väg, och gjorde det ondt var för Herranom, såsom Achabs hus; ty han var Achabs hus svåger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Och han drog med Joram, Achabs son, i strid emot Hasael, Konungen i Syrien, till Ramoth i Gilead; men de Syrer slogo Joram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Då vände Konung Joram tillbaka, att låta läka sig i Jisreel, för de sårs skull, som de Syrer honom slagit hade i Rama, då han stridde med Hasael, Konungenom i Syrien. Och Ahasia, Jorams son, Juda Konung, kom neder till att bese Joram, Achabs son i Jisreel; ty han låg krank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Elisa kallade en af de Propheters söner, och sade till honom: Gjorda dina länder, och tag denna oljokrukona med dig, och gack till Ramoth i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Och då du kommer dit, får du der se Jehu, Josaphats son, Nimsi sons, och gack in, och bed honom stå upp ibland sina bröder, och haf honom in uti den innersta kammaren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Och tag oljokrukona, och gjut den ut på hans hufvud, och säg: Detta säger Herren: Jag hafver smort dig till Konung öfver Israel. Och du skall låta upp dörrena, och fly, och icke förtöfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Och Prophet ens tjenare, den unge mannen, gick åstad till Ramoth i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Och då han inkom, si, då såto der höfvitsmännerna för hären. Och han sade: Höfvitsman, jag hafver något säga dig. Jehu sade: Hvilkom af oss alla? Han sade: Dig, höfvitsman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Då stod han upp, och gick in; men han göt oljona på hans hufvud, och sade till honom: Detta säger Herren Israels Gud: Jag hafver smort dig till Konung öfver Herrans folk Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Och du skall slå dins herras Achabs hus, att jag skall hämnas mina tjenares Propheternas blod, och alla Herrans tjenares lod, utur Isebels hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Så att hela Achabs hus skall förgås; och jag skall af Achab utrota den som på väggena pissar, och den innelyckta, och den igenlefda i Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Och skall göra Achabs hus, såsom Jerobeams hus, Nebats sons, och såsom Baesa hus, Ahia sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Och hundar skola uppäta Isebel på åkren i Jisreel; och ingen skall begrafva henne. Och han lät upp dörrena, och flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Och då Jehu gick ut till sins herras tjenare, sade de till honom: Går det allt väl till? Hvar efter är denne rasaren kommen till dig? Han sade till dem: I kännen dock mannen väl, och hvad han säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'De sade: Det är icke sant, säg du oss det. Han sade: Så och så hafver han talat med mig, och sagt: Detta säger Herren, jag hafver smort dig till. Konung öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Då hastade de sig, och hvar och en tog sin kläder, och lade under honom invid säjaren, och blåste med basuner, och sade: Jehu är Konung vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Alltså gjorde Jehu, Josaphats son, Nimsi sons, ett förbund emot Joram; men Joram låg för Ramoth i Gilead med hela Israel, emot Hasael, Konungen i Syrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Men Konung Joram var igenkommen, till att låta sig läka i Jisreel, af de sår som de Syrer honom slagit hade, då han stridde med Hasael, Konungenom i Syrien. Och Jehu sade: Är det så eder i sinnet, så skall ingen slippa utaf staden, att han går bort, och bådar det i Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Och han for upp, och drog till Jisreel; förty Joram låg der. Så var Ahasia, Juda Konung, nederdragen till att bese Joram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Men väktaren, som på tornet i Jisreel stod, fick se Jehu hop komma, och sade: Jag ser en hop. Då sade Joram: Tag en vagn, och sänd emot dem, och säg: Är allt fridsamt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Och foromannen for emot honom, och sade: Detta säger Konungen: Är allt fridsamt? Jehu sade: Hvad kommer friden dig vid? Far här bakefter mig. Väktaren förkunnade, och sade: Bådet är kommet till dem, och kommer intet igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Då sände han en annan foroman. Då han kom till dem, sade han: Detta säger Konungen: Är allt fridsamt? Jehu sade: Hvad kommer friden dig vid? Far här bakefter mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Det förkunnade väktaren, och sade: Han är kommen till dem, och kommer intet igen; och det är ett körande, såsom Jehu körande, Nimsi sons; ty han körer lika som han vore rasande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Då sade Joram: Sätter före. Och de satte före hans vagn. Och de drogo ut, Joram, Israels Konung, och Ahasia, Juda Konung, hvardera på sin vagn, att de skulle komma emot honom. Och de råkade honom på Naboths åker, den Jisreelitens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Och då Joram såg Jehu, sade han: Jehu, är allt fridsamt? Han sade: Hvad, frid? Dine moders Isebels horeri och trolldom hafver icke ännu ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Då vände Joram sina hand om, och flydde, och sade till Ahasia: Här är förräderi, Ahasia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Men Jehu fattade bågan, och sköt Joram emellan härderna, så att pilen gick ut igenom hjertat, och han föll uti sin vagn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Och Jehu sade till höfvitsmannen Bidkar: Tag och kasta honom uppå åkrastycket, Naboths den Jisreelitens; förty jag kommer ihåg, att du med mig forom efter hans fader på enom vagn, att Herren lade denna tungan uppå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Hvad gäller, sade Herren, jag skall vedergälla dig på denna åkren Naboths blod, och hans söners blod, det jag i går såg. Så tag honom nu, och kasta honom på åkren, efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Då Ahasia, Juda Konung, det såg, flydde han på den vägen till örtagårdshuset; men Jehu jagade efter honom, och böd desslikes slå honom på vagnenom in mot Gur, som ligger vid Jibleam; och han flydde till Megiddo, och blef der död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Och hans tjenare läto föra honom till Jerusalem; och begrofvo honom i hans graf med sina fäder uti Davids, stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Men Ahasia regerade öfver Juda i ellofte årena Jorams, Achabs sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Och då Jehu kom till Jisreel, och Isebel det fick veta, färgade hon sitt ansigte, och beprydde sitt hufvud, och såg ut genom fenstret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Och då Jehu kom in igenom porten, sade hon: Är det Simri väl afgånget, som drap sin herra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Och han hof sitt ansigte upp till fenstret, och sade: Ho är här när mig? Då vände sig två eller tre kamererare till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Han sade: Störter henne utföre. Och de störte henne utföre, så att väggen och hästarna vordo stänkte med hennes blod; och hon vardt förtrampad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Och då han var inkommen, och hade ätit och druckit, sade han: Beser dock den förbannada, och begrafver henne; ty hon är en Konungs dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Då de nu gingo bort till att begrafva henne, funno de intet af henne, utan hufvudskallen och fötterna och flata händerna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Och kommo igen, och sade honom det. Han sade: Detta är nu det, som Herren genom sin tjenare Elia, den Thisbiten, talade, och sade: På Jisreels åker skola hundar äta Isebels kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Alltså vardt Isebels as såsom en träck på markene uppå Jisreels åker, så att man intet säga kunde: Detta är Isebel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Och Achab hade sjutio söner i Samarien; och Jehu skref bref, och sände till Samarien till de öfversta i Israels stad, till de äldsta, och Achabs förmyndare, hvilket så lydde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'När detta bref kommer till eder, när hvilkom edars herras söner äro, hans vagnar, hästar, faste städer och rustning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Så ser till, hvilken bäst och likast är ibland edars herras söner, och sätter honom på hans faders stol, och strider för edars herras hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Men de fruktade sig ganska fast, och sade: Si, två Konungar hafva icke blifvit ståndande för honom; huru skulle vi då stå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Och de som voro öfver huset, och öfver staden, och de äldste, och förmyndarena, sände bort till Jehu, och läto säga honom: Vi äre dine tjenare, vi vilje göra allt det du säger oss; vi vilje ingen göra till Konung; gör hvad dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Då skref han ett annat bref till dem; det lydde alltså: Ären I mine, och lyden mine röst, så tager hufvuden af de män edars herras söner, och förer dem i morgon bittida till mig i Jisreel. Och Konungssönerna voro sjutio män, och de ypperste i staden uppfödde dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Då nu brefvet kom till dem, togo de Konungssönerna, och dråpo sjutio män, och lade deras hufvud i korgar, och sände dem till honom i Jisreel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Och då bådet kom, och bådade honom det, och sade: De hafva fört hit Konungssönernas hufvud; sade han: Lägger dem i två hopar för stadsporten, intill morgons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Och om morgonen, när han utgick, trädde han dit, och sade till allt folket: Ären I rättvise? Si, hafver jag gjort ett förbund emot min herra, och dräpit honom; ho hafver då slagit alla dessa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Så må I ju se, att intet Herrans ord är på jordena fallet, som Herren talat hafver emot Achabs hus; och Herren hafver gjort såsom han talat hafver genom sin tjenare Elia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Alltså slog Jehu alla dem som qvare voro af Achabs hus i Jisreel, alla hans yppersta, hans vänner, och hans Prester, tilldess icke en var qvar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Och stod upp, och drog bort till Samarien. Men i vägen var ett herdahus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Der råkade Jehu vid Ahasia, Juda Konungs, bröder, och sade: Ho ären I? De sade: Vi äre Ahasia bröder, och drage ned till att helsa Konungens barn, och Drottningenes barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Han sade: Griper dem lefvande. Och de grepo dem lefvande, och dråpo dem vid brunnen när herdahuset, två och fyratio män; och lät icke en af dem slippa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Och då han drog dädan, fann han Jonadab, Rechabs son, den honom mötte, och helsade honom, och sade till honom: Är ditt hjerta rätt, såsom mitt hjerta med dino hjerta? Jonadab sade: Ja. Är det så, sade han, så räck mig dina hand. Och han räckte honom sina hand; och han lät honom sitta uppe när sig på vagnen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Och sade: Kom med mig, och se mitt nit om Herran. Och de förde honom med honom på hans vagn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Då han kom till Samarien, slog han allt det som qvart var af Achab i Samarien, tilldess han förgjorde honom, efter Herrans ord, som han till Elia talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Och Jehu församlade allt folket, och lät säga till dem: Achab hafver fögo tjent Baal; Jehu vill bättre tjena honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Så låt nu kalla alla Baals Propheter, alla hans tjenare, och alla hans Prester, till mig, så att ingen är borto; förty jag hafver ett stort offer till att göra Baal; hvilken borto är, den skall icke lefva. Men Jehu gjorde detta med listighet, att han måtte förgöra Baals tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Och Jehu sade: Helger Baal ena högtid, och låter den utropa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Och sände Jehu i hela Israel, och lät komma alla Baals tjenare, så att ingen qvar var, som icke kom. Och de kommo i Baals hus; så att Baals hus vardt fullt i all rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Då sade han till dem, som voro öfver klädehuset: Bärer ut kläder för alla Baals tjenare. Och de båro kläder ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Och Jehu gick in uti Baals hus med Jonadab, Rechabs son, och sade till Baals tjenare: Ransaker, och ser till, att ingen Herrans tjenare är ibland eder, utan Baals tjenare allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Och som de kommo in till att göra offer och bränneoffer, beställde Jehu sig åttatio män utanföre, och sade: Ho som släpper någon af männerna, som jag får under edra händer, hans själ skall vara för hans själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'När nu bränneoffret fullkomnadt var, sade Jehu till drabanterna och höfvitsmännerna: Går in, och slår dem allasamman; låter ingen komma derut. Och de slogo dem med svärdsegg, och drabanterna och höfvitsmännerna hofvo dem bort. Och de gingo till Baals hus stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Och togo ut de stodar i Baals hus, och brände dem upp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Och slogo sönder Baals stodar, samt med Baals hus; och gjorde der ett hemligt hus af, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Alltså förgjorde Jehu Baal utur Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Men ifrå Jerobeams, Nebats sons, synder, den Israel kom till att synda, gick Jehu icke, och öfvergaf icke de guldkalfvar i BethEl och i Dan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Och Herren sade till Jehu: Derföre, att du hafver viljog varit till att göra min vilja, och hafver gjort på Achabs hus allt det i mino hjerta var, skola dina söner sitta dig på Israel stol intill fjerde led.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Dock höll icke Jehu, att han i Herrans Israels Guds lag vandrade af allo hjerta; ty han trädde icke ifrå Jerobeams synder, som kom Israel till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'På den tiden begynte Herren ledas vid Israel; ty Hasael slog dem i alla Israels gränsor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Ifrå Jordan österut, och hela Gilead, de Gaditers, Rubeniters, och Manassiters land, ifrån Aroer, som ligger när den bäcken vid Arnon; och Gilead, och Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Hvad nu mer af Jehu sägande är, och allt det han gjort hafver, och all hans magt, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Och Jehu afsomnade med sina fäder; och de begrofvo honom i Samarien; och Joahas hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Men tiden, som Jehu öfver Israel regerade i Samarien, är åtta och tjugu år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Men Athalja, Ahasia moder, då hon såg, att hennes son var död, stod hon upp, och förgjorde all Konungslig säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Men Joseba, Konung Jorams dotter, Ahasia syster, tog Joas, Ahasia son, och stal honom ifrå Konungsbarnen, som dräpne vordo, med hans ammo i sängkammarenom, och hon förgömde honom för Athalja, så att han icke vardt dräpen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Och han vardt undstungen med henne i Herrans hus i sex år; och Athalja var rådandes i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Uti sjunde årena sände Presten Jojada bort, och tog till sig de öfversta öfver hundrade, med höfvitsmännerna och drabanterna, och lät komma dem till sig i Herrans hus, och gjorde ett förbund med dem, och tog en ed af dem i Herrans hus, och viste dem Konungens son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Och böd dem, och sade: Detta är det I göra skolen; tredjeparten af eder, hvilkens skifte om Sabbathsdagen uppå går, skolen hålla vakt i Konungshusena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Och en tredjepart skall vara vid den porten Sur; och en tredjepart skall vara vid den porten, som är bak drabanterna; och skolen hålla vakt för Massa hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Men två parter af eder allom, I som om Sabbathsdagen afgån, skolen vakta i Herrans hus när Konungen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Och skolen ställa eder rundt omkring Konungen, och hvar och en med sine värjo i handene; och ho som kommer in emellan väggarna, han skall dö; så att I ären när Konungen, då han ut och in går.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Och de öfverste öfver hundrade gjorde allt det Presten Jojada dem budit hade; och togo sina män till sig, som på Sabbathsdagen uppå gingo, med de som på Sabbathsdagen af gingo, och kommo till Presten Jojada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Och Presten fick höfvitsmännerna spetsar, och sköldar, som hade varit Konung Davids, och voro i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Och drabanterna stodo omkring Konungen, hvar och en med sine värjo i handene; ifrå husens hörn på högra sidone, allt intill det hörnet på den venstra, intill altaret, och till huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Och han lät Konungens son komma fram, och satte ena krono på honom, och tog vittnesbördet, och gjorde honom till Konung, och voro glade, och klappade händerna tillhopa, och sade: Lycka ske Konungenom!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Och då Athalja fick höra ropet af folket, som lopp dertill, kom hon ut till folket i Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Och såg till, si, då stod Konungen invid stodena, såsom sedvänja var, och sångare och trummetare när Konungenom; och allt folket i landena var gladt, och blåste med trummeter. Då ref Athalja sin kläder, och sade: Uppror, uppror.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Men Presten Jojada böd de öfversta öfver hundrade, som voro satte öfver hären, och sade till dem: Hafver henne utu huset i gården; och om någor följer henne, han dräpes med svärd; ty Presten hade sagt, att hon icke skulle dö i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Och de båro händerna på henne, och hon gick in på den vägen, som hästarna till Konungshuset gå, och vardt der dräpen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Så gjorde Jojada ett förbund emellan Herran, och Konungen, och folket, att de skulle vara Herrans folk; desslikes ock emellan Konungen och folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Då gick allt folket i landena in uti Baals hus, och bröto hans altare ned; och sönderslogo hans beläte allt grant, och Matthan, Baals Prest, slogo de ihjäl inför altaret; och Presten beställde ämbeten uti Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Och tog de öfversta öfver hundrade, och de höfvitsmän och de drabanter, och allt folket i landena, och förde Konungen ned ifrå Herrans hus, och kommo den vägen ifrå drabantaporten intill Konungshuset; och han satte sig på Konungsstolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Och allt folket i landet var gladt, och staden vardt stilla. Men Athalja dråpo de med svärd i Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Och Joas var sju är gammal, då han vardt Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Uti sjunde årena Jehu vardt Joas Konung, och regerade i fyratio år i Jerusalem; hans moder het Zibja, af BerSeba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Och Joas gjorde det rätt var, och det Herranom väl behagade, så länge Presten Jojada lärde honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Undantagno, att han icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Och Joas sade till Presterna: Alla de penningar, som dertill helgade varda, att de skola läggas till Herrans hus, nämliga de penningar, som hvar och en gifver i skatt, och de penningar, som hvar och en löser sina själ med, och alla de penningar, som hvar och en offrar af fritt hjerta, dertill att det skall läggas till Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Det låter Presterna taga till sig, hvardera sin del; dermed skola de bota hvad som förfaller på (Herrans) hus, ehvar de finna att det förfallet är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Då nu Presterna, allt intill tredje och tjugonde året Konungs Joas, icke botade hvad som förfallet var i husena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Kallade Konung Joas Presten Jojada, samt med Presterna, och sade till dem: Hvi boten I icke hvad som förfaller i husena? Så skolen I nu icke taga de penningar till eder, hvar och en sin del; utan skolen låta kommat till det, som förfallet är i husena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Och Presterna samtyckte inga penningar vilja taga af folkena, till att bota det förfallet var af huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Då tog Presten Jojada ena kisto, och gjorde der ett hål ofvanuppå, och satte henne på högra sidon vid altaret, der man ingår i Herrans hus. Och Presterna, som vakt höllo för dörrene, läto komma alla penningar deruti, som till Herrans hus fördes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'När de nu sågo, att många penningar voro i kistone, så kom Konungens skrifvare upp, och öfverste Presten, och bundo penningarna tillhopa, och räknade hvad till Herrans hus funnet vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Och man gaf penningarna redo i handena dem som arbetade, och skickade voro till Herrans hus; och de gåfvo dem ut timbermannom, som byggde och arbetade på Herrans huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Nämliga murmästarom, och stenhuggarom, och dem som trä och huggna stenar köpte: på det att det förfallna på Herrans hus måtte botadt varda, och hvad som helst de funno af nödene vara att botas skulle på huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Dock lät man icke göra silfskålar, bägare, bäcken, trummeter, eller något gyldene eller silfvertyg i Herrans hus, af de penningar, som till Herrans hus förde voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Utan man gaf dem arbetarena, att de dermed botade det förfallna på Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Och behöfde de män ingen räkenskap göra, som man fick penningarna, till att utgifva dem arbetarena; utan de handlade på sina tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Men de penningar af skuldoffer och syndoffer vordo icke förde uti Herrans hus; förty de voro Presternas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'På den tiden drog Hasael, Konungen i Syrien, upp, och stridde emot Gath, och vann det. Och då Hasael ställde sitt ansigte till att draga upp till Jerusalem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tog Joas, Juda Konung, allt det helgada, som hans fader; Josaphat, Joram och Ahasia, Juda Konungar, helgat hade, och det han helgat hade; dertill allt det guld, som man fann i Herrans hus skatt, och i Konungshusena, och sände det till Hasael, Konungen i Syrien. Sedan drog han sina färde ifrå Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Hvad nu mer af Joas sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Och hans tjenare hofvo sig upp, och gjorde ett förbund, och slogo honom i Millo hus, der man nedergår till Silla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Ty Josachar, Simeaths son, och Josabad, Somers son, hans tjenare, slogo honom ihjäl; och man begrof honom med hans fäder uti Davids stad. Och Amazia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Uti tredje och tjugonde årena Joas, Ahasia sons, Juda Konungs, vardt Joahas, Jehu son, Konung öfver Israel i Samarien, sjutton år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Och han gjorde det ondt var för Herranom, och vandrade efter Jerobeams synder, Nebats sons, hvilken Israel kom till att synda; och öfvergaf det icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Och Herrans vrede förgrymmade sig öfver Israel, och gaf dem under Hasaels hand, Konungens i Syrien, och i Benhadads, Hasaels sons, hand, i deras lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Men Joahas bad Herrans ansigte, och Herren hörde honom; ty han såg på Israels jämmer, som Konungen i Syrien dem gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Och Herren gaf Israel en frälsare, som dem förde utu de Syrers våld; så att Israels barn bodde uti sina hyddor, såsom tillförene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Dock öfvergåfvo de icke Jerobeams hus synder, hvilken Israel kom till att synda, utan vandrade derutinnan; och den lunden i Samarien blef ståndandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Förty af Joahas folk var icke mer qvart blifvet, än femtio resenärer, tio vagnar, och tiotusend fotfolk; ty Konungen i Syrien hade slagit dem ihjäl, och gjort dem såsom tröskestoft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Hvad nu mer af Joahas sägandes är, och allt det han gjort hafver, och hans magt, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Och Joahas afsomnade med sina fäder, och man begrof honom i Samarien; och hans son Joas vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Uti sjunde och tretionde årena Joas, Juda Konungs, vardt Joas, Joahas son, Konung öfver Israel i Samarien, sexton år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Och gjorde det ondt var för Herranom, och öfvergaf icke alla Jerobeams, Nebats sons, synder, den Israel kom till att synda; utan vandrade derutinnan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Hvad nu mer af Joas sägandes är, och hvad han gjort hafver, och hans magt, huru han med Amazia, Juda Konung, stridt hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Och Joas afsomnade med sina fader; och Jerobeam satt på hans stol. Men Joas vardt begrafven i Samarien när de Israels Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Då vardt Elisa krank, der han ock af död blef; och Joas, Israels Konung, kom ned till honom, och gret för honom, och sade: Min fader, min fader, Israels vagn, och hans resenärer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa sade till honom: Tag bågan och pilarna. Och då han tog bågan och pilarna,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Sade han till Israels Konung: Bänd bågan med dine hand. Och han bände med sine hand. Och Elisa lade sina hand på Konungens hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Och sade: Låt upp fenstret österut; och han lät det upp. Och Elisa sade: Skjut; och han sköt. Han sade: En salighetspil af Herranom, en salighetspil emot de Syrer; och du skall slå de Syrer i Aphek, tilldess de blifva ändade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Och han sade: Tag pilarna. Och då han tog dem, sade han till Israels Konung: Slå på jordena. Och han slog tre gånger, och höll upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Då vardt Guds mannen vred på honom, och sade: Hade du slagit fem eller sex gånger, så skulle du hafva slagit de Syrer, tilldess du hade gjort en ända på dem; men nu skall du slå dem tre gånger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Då nu Elisa var död, och man hade begrafvit honom, föllo de Moabiters krigsfolk in uti landet på samma året.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Och det begaf sig, att de begrofvo en man; och som de fingo se krigsfolket, kastade de mannen uti Elisa graf; och då han kom vid Elisa ben, vardt han lefvandes, och stod upp på sina fötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Alltså tvingade nu Hasael, Konungen i Syrien, Israel, så länge Joahas lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Men Herren gjorde nåd med dem, och förbarmade sig öfver dem, och vände sig till dem för sitt förbunds skull med Abraham, Isaac och Jacob, och ville, icke förderfva dem; och förkastade dem icke heller ifrå sitt ansigte allt härtill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Och Hasael, Konungen i Syrien, blef död; och hans son Benhadad vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Men Joas vände om, och tog de städer igen utu Benhadads, Hasaels sons, hand, som han utu hans faders Joahas hand med strid tagit hade. Tre gånger slog Joas honom, och fick Israels städer igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Uti andro årena Joas, Joahas sons, Israels Konungs, vardt Amazia Konung, Joas, Juda. Konungs, son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Fem och tjugu åra gammal var han, då han vardt Konung; och regerade nio och tjugu år i Jerusalem; hans moder het Joaddan af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Och han gjorde det Herranom väl behagade; dock icke såsom hans fader David, utan såsom hans fader Joas gjort hade, så gjorde han ock.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Ty höjderna vordo icke aflagda; utan folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Då han nu var mägtig vorden i riket, slog han sina tjenare, som Konungen hans fader dräpit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Men dråparenas barn drap han icke; såsom ock skrifvet är i Mose lagbok, der Herren budit hade, och sagt: Fäderna skola icke dö för barnens skull, och barnen skola icke dö för fädernas skull; utan hvar och en skall dö för sina synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Han slog desslikes de Edomeer i saltdalenom, tiotusend, och vann den staden Sela med strid; och kallade honom Joktheel, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Då sände Amazia båd till Joas, Joahas son, Jehu sons, Israels Konung, och lät säga honom: Kom hit, och låt oss se hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Men Joas, Israels Konung, sände till Amazia, Juda Konung, och lät säga honom: Törnebusken, som i Libanon är, sände till cedreträt i Libanon, och sade: Gif dina dotter minom son till hustru; men vilddjuret på markene i Libanon lopp öfver törnebuskan, och förtrampade honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Du hafver slagit de Edomeer, deraf förhäfver sig ditt hjerta; behåll den prisen, och blif hemma; hvi söker du efter olycko, att du må falla, och Juda med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Men Amazia hörde honom intet. Så drog Joas, Israels Konung, upp; och de besågo hvarannan, han och Amazia, Juda Konung, i BethSemes, som i Juda ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Men Juda vardt slagen för Israel, så att hvar och en flydde i sina hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Och Joas, Israels Konung, grep Amazia, Juda Konung, Joas son, Ahasia sons, i BethSemes; och kom till Jerusalem, och ref omkull, murarna i, Jerusalem, ifrån Ephraims port, allt intill hörnporten, fyrahundrad alnar långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Och tog allt det guld och silfver, och tyg, som funnet vardt i Herrans hus, och i Konungshusens fatebur, dertill barnen, till pant; och drog åter till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Hvad nu mer af Joas sägande är, det han gjort hafver, och hans magt, och huru han med Amazia, Juda Konung, stridde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Och Joas afsomnade med sina fader, och vardt begrafven i Samarien ibland Israels Konungar; och hans son Jerobeam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Men Amazia. Joas son, Juda Konungs, lefde efter Joas död, Joahas sons, Israels Konungs, i femton år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Hvad nu mer af Amazia sägandes är, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Och de gjorde ett förbund emot honom i Jerusalem; men han flydde till Lachis. Och de sände efter honom till Lachis, och dråpo honom der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Och de förde honom dädan på hästar; och han vardt begrafven i Jerusalem, när sina fäder uti Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Och hela Juda folk togo Asaria, uti lians sextonde äre, och, gjorde honom till Konung i hans faders Amazia stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Han byggde Elath, och fick det igen under Juda, sedan Konungen med hans fäder afsomnad var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Uti femtonde årena Amazia, Joas sons, Juda Konungs, vardt Jerobeam, Joas son, Konung öfver Israel i Samarien, ett och fyratio ar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Och gjorde det ondt varför Herranom, och öfvergaf icke alla Jerobeams, Nebats sons, synder, den Israel kom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Men han tog igen Israels gränsor, ifrå Hamath allt intill hafvet, som ligger i hedmarkene, efter Herrans Israels Guds ord, som han sagt hade genom, sin tjenare Propheten Jona, Amitthai son, som var af GathHepher.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Ty Herren såg till Israels svåra jämmer, så att ock de innelyckte och igenlefde förgingos; och ingen hjelpare var i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Och Herren hade icke sagt, att han ville utskrapa Israels namn under himmelen; utan halp dem genom Jerobeam, Joas son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Hvad nu mer af Jerobeam sägandes är, och allt det han gjort hafver, och hans magt, huru han stridt hafver, och huru han igenfick Damascon och Hamath till Juda i Israel, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Och Jerobeam afsomnade med sina fäder, Israels Konungar; och hans son Zacharia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Uti sjunde och tjugonde årena Jerobeams, Israels Konungs, vardt Asaria Konung, Amazia son, Juda Konungs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Och var sexton åra gammal, då han Konung vardt, och regerade tu och femtio år i Jerusalem; hans moder het Jecholia af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Och han gjorde det Herranom väl behagade, alldeles såsom hans fader Amazia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Undantagno, att de icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Men Herren plågade Konungen, så att han var spitelsk allt intill döden, och bodde uti ett fritt hus; men Jotham, Konungens son, regerade huset, och dömde folket i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Hvad nu mer af Asaria sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Och Asaria afsomnade med sina fäder, och man begrof honom när sina fäder uti Davids stad; och hans son Jotham vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Uti åttonde och tretionde årena Asaria, Juda Konungs, vardt Zacharia, Jerobeams son, Konung öfver Israel i Samarien, i sex månader;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Och gjorde det ondt var för Herranom, såsom hans fäder gjort hade. Han vände icke igen ifrå Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Och Sallum, Jabes son, gjorde ett förbund emot honom, och slog honom för folkena, och drap honom; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Hvad mer af Zacharia sägandes är, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Och det är det som Herren till Jehu talat hade, sägandes: Din barn skola sitta på Israels stol, allt intill fjerde led. Och det skedde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, Jabes son, vardt Konung uti nionde och tretionde årena Usia, Juda Konungs, och regerade en månad i Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Ty Menahem, Gadi son, drog upp ifrå Thirza, och kom till Samarien, och slog Sallum, Jabes son, i Samarien, och drap honom; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Hvad nu mer af Sallum sägandes är, och om hans förbund, som han gjorde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'På den tiden slog Menahem Thiphsah, med alla de som derinne voro, och dess gränsor, allt ifrå Thirza; derföre att de icke ville låta honom in; och slog alla deras hafvande qvinnor, och sönderref dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Uti nionde och tretionde årena Asaria, Juda Konungs, vardt Menahem, Gadi son, Konung öfver Israel i tio år, i Samarien;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Och gjorde det ondt var för Herranom, och öfvergaf icke i sin lifstid Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Och Phul, Konungen i Assyrien, kom i landet; och Menahem gaf Phul tusende centener silfver, på det han skulle hålla med honom, och befästa honom i rikena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Och Menahem lade en skatt i Israel uppå de rikesta, femtio siklar silfver på hvar man, att han skulle gifva det Konungenom i Assyrien. Alltså drog Konungen af Assyrien hem igen, och blef icke i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Hvad nu mer af Menahem sägandes är, och allt det han gjort hafver, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Och Menahem afsomnade med sina fader; och Pekahia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Uti femtionde årena Asaria, Juda Konungs, vardt Pekahia, Menahems son, Konung öfver Israel i Samarien, i tu år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Och gjorde det ondt var för Herranom; ty han vände icke åter af Jerobeams, Nebats sons, synder, den Israel kom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Och Pekah, Remalia son, hans riddare, gjorde ett förbund emot honom, och slog honom i Samarien, uti Konungshusets palats, med Argob, och Arie, och femtio män med honom af Gileads barn; och drap honom, och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Hvad mer af Pekahia; sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Uti andra och femtionde årena Asaria, Juda Konungs, vardt Pekah, Remalia son, Konung öfver Israel i Samarien i tjugu är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Och gjorde det ondt var för Herranom; ty han vände icke åter af Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Uti Pekah, Israels Konungs, tid kom ThiglathPileser, Konungen i Assyrien, och tog Ijon, AbelBethMaacha, Janoha, Kedes, Hazor, Gilead, Galilea och hela Naphthali land, och förde dem bort i Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Och Hosea, Ela son, gjorde ett förbund emot Pekah, Remalia son, och slog honom ihjäl, och vardt Konung i hans stad, uti tjugonde årena Jothams, Usia sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Hvad nu mer af Pekah sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Uti andra årena Pekah, Remalia sons, Israels Konungs, vardt Jotham Konung, Usia son, Juda Konungs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Och var fem och tjugu åra gammal, då han Konung vardt, och regerade i sexton år i Jerusalem; hans moder het Jerusa, Zadoks dotter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Och gjorde det Herranom väl behagade, alldeles såsom hans fader Usia gjort hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Undantagno, att han icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna. Han byggde den höga porten på Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Hvad nu mer af Jotham sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'I den tiden begynte Herren sända till Juda Rezin, Konungen i Syrien, och Pekah, Remalia son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Och Jotham afsomnade med sina fäder, och vardt begrafven när sina fäder, uti sins faders Davids stad; och Ahas hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Uti sjuttonde årena Pekah, Remalia sons, vardt Ahas Konung, Jothams, Juda Konungs, son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Tjugu åra gammal var Ahas, då han vardt Konung, och regerade sexton är i Jerusalem, och gjorde intet det Herranom hans Gud behagade, såsom hans fader David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Ty han vandrade på Israels Konungars väg; dertill lät han sin son gå igenom eld, efter de Hedningars styggelse, hvilka Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Och han gjorde offer, och rökte på höjderna, och på alla backar, och under all grön trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'På den tiden drog Rezin, Konungen i Syrien, och Pekah, Remalia son, Israels Konung, upp till Jerusalem till att strida, och belade Ahas; men de kunde icke vinna det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'På samma tiden fick Rezin, Konungen i Syrien, Elath igen till Syrien, och dref Judarna utur Elath. Och de Syrier kommo, och bodde deruti, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Men Ahas sände båd till Thiglath Pileser, Konungen i Assyrien, och lät säga honom: Jag är din tjenare, och din son. Kom hitupp, och hjelp mig utu Konungens hand i Syrien, och Israels Konungs, hvilka sig emot mig upprest hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Och Ahas tog det silfver och guld, som i Herrans huse och uti Konungshusens fatebur funnet vardt, och sände Konungenom i Assyrien skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Och Konungen i Assyrien hörde honom; och drog upp till Damascon, och vann det; och förde dem bort till Kir, och drap Rezin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Och Konung Ahas drog emot ThiglathPileser, Konungen i Assyrien, till Damascon. Och då han såg ett altare, som i Damascon var, sände Konung Ahas ett mönster och en efterliknelse till Presten Uria, såsom det gjordt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Och Uria Presten byggde ett altare, och gjorde det efter det, som Konung Ahas honom sändt hade ifrå Damascon, tilldess Konung Ahas kom ifrå Damascon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Och då Konungen kom ifrå Damascon och såg altaret, offrade han deruppå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Och upptände deruppå sitt bränneoffer, och spisoffer, och göt deruppå sitt drickoffer; och blodet af tackoffrena, som han offrade, lät han stänka på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Men det kopparaltaret, som för Herranom stod, tog han bort, så att det icke skulle stå emellan altaret och Herrans hus; utan satte det utmed sidona vid altaret norrut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Och Konung Ahas böd Prestenom Uria, och sade: På det stora altaret skall du upptända bränneoffer om morgonen, och spisoffer om aftonen, och Konungens bränneoffer, och hans spisoffer, och allt folkens bränneoffer i landena, samt med deras spisoffer, och drickoffer; och allt blodet af bränneoffret, och af allo andro offer skall du stänka deruppå; men om kopparaltaret vill jag vara förtänkt hvad jag göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Presten Uria gjorde allt det Konung Ahas befallde honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Och Konung Ahas bröt bort sidorna af stolarna, och hof bort kettlarna deraf, och hafvet hof han utaf de kopparoxar, som voro derunder, och satte det uppå stengolfvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Dertill Sabbathspredikostolen, den de i husena byggt hade. Och Konungsgången utantill vände han i Herrans hus, för Konungens skull i Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Hvad nu mer af Ahas sägandes är? hvad han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Och Ahas afsomnade med sina fäder, och vardt begrafven när sina fäder uti Davids stad; och Hiskia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Uti tolfte årena Ahas, Juda Konungs, vardt Hosea, Ela son, Konung öfver Israel i Samarien, i nio år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Och gjorde det ondt var för Herranom, dock icke såsom de Israels Konungar, som för honom voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Emot honom drog upp Salmanasser, Konungen i Assyrien och Hosea vardt honom undergifven, så att han gaf honom skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Då Konungen i Assyrien fick veta, att Hosea hade ett förbund för händer, och hade sändt båd till So, Konungen i Egypten, och icke utgifva ville årliga skänkerna Konungenom i Assyrien; belade han honom, och kastade honom i fängelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Och Konungen i Assyrien drog in i hela landet, och till Samarien, och belade det i tre är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Och uti nionde årena Hosea vann Konungen i Assyrien Samarien, och förde Israel bort i Assyrien, och satte dem i Halah, och i Habor vid den älfven Gosan, och uti de Meders städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Ty då Israels barn syndade emot Herran deras Gud, den dem utur Egypti land fört hade, utu Pharaos hand, Konungens i Egypten, och fruktade andra gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Och vandrade efter Hedningarnas seder, hvilka Herren för Israels barn fördrifvit hade, och såsom Israels Konungar gjort hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Och skickade sig icke tillbörliga för Herranom sinom Gud; och byggde sig höjder i alla städer, både på slott och i fasta städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Och uppreste stodar och lundar på alla backar, och under all grön trä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Och rökte der på alla höjder, lika såsom Hedningarna, hvilka Herren för dem fördrifvit hade; och bedrefvo slem stycke, der med de förtörnade Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Och tjente afgudar, om hvilka Herren dem sagt hade: Detta skolen I icke göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Och då Herren betygade i Israel och Juda, genom alla Propheter och Siare, och lät säga dem: Vänder om utaf edra onda vägar, och håller min bud och rätter, efter all de lag som jag edra fäder budit hafver, och jag genom mina tjenare Propheterna till eder sändt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Men de lydde intet, utan gjorde sig hårdnackade, såsom ock deras fäder gjort hade, hvilke icke trodde på Herran deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Dertill föraktade de hans bud, och hans förbund som han med deras fäder gjort hade, och hans vittnesbörd som han ibland dem gjort hade, och vandrade efter deras fåfängelighet, och vordo fåfängelige såsom Hedningarna, som omkring dem voro, om hvilka Herren dem budit hade, att de icke skulle göra såsom de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Men de öfvergåfvo all Herrans deras Guds bud, och gjorde sig två gjutna kalfvar, och lundar; och tillbådo allan himmelens här, och tjente Baal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Och läto sina söner och döttrar gå igenom eld, och foro med spådom och trolldom; och gåfvo sig till att göra det ondt var för Herranom, till att förtörna honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Så vardt Herren ganska vred på Israel, och kastade dem bort ifrå sitt ansigte; så att intet blef qvart, utan Juda slägt allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Dertill höll icke heller Juda Herrans sins Guds bud, utan vandrade efter Israels seder, som de gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Derföre förkastade Herren all Israels säd, och plågade dem; och gaf dem i röfvarehänder, tilldess han kastade dem ifrå sitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Förty Israel vardt söndrad ifrå Davids hus, och hade gjort sig Jerobeam, Nebats son, till Konung. Han vände Israel ifrå Herranom, och gjorde det så, att de svårliga syndade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Alltså vandrade Israels barn uti alla Jerobeams synder, som han hade åstadkommit, och icke återvände deraf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Intilldess Herren kastade Israel ifrå sitt ansigte, såsom han igenom alla sina tjenare Propheterna sagt hade. Så vardt då Israel bortförd utu sitt land in uti Assyrien, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Och Konungen af Assyrien lät komma folk af Babel, af Cutha, af Ava, af Hamath och Sepharvaim, och besatte de städer i Samarien uti Israels barnas stad; och de togo Samarien in, och bodde uti dess städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Men som de då begynte att bo der, och fruktade intet Herran, sände Herren lejon ibland dem, som slogo dem ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Och de läto säga Konungenom i Assyrien: De Hedningar, som du hafver låtit komma hit, och besatt med de städer i Samarien, veta intet af landsens Guds seder; derföre hafver han sändt lejon ibland dem, och si, de dräpa dem, efter de icke veta utaf landsens Guds seder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Konungen i Assyrien böd, och sade: Förer dit en af Presterna, som dädan bortförde äro; han fare dit, och bo der; och han läre dem landsens Guds seder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Så kom en af Presterna, som af Samarien bortförde voro, och satte sig i BethEl, och lärde dem, huru de skulle frukta Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Men hvart och ett folk gjorde sig sin gud, och satte dem uti de höjders hus, som de Samariter gjorde, hvart och ett folk uti sina städer, der de bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'De af Babel gjorde SuccothBenoth; de af Cuth gjorde Nergal; de af Hamath gjorde Asima;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'De af Ava gjorde Nibhas och Thartak; de af Sepharvaim brände upp sina söner Adrammelech och Anammelech, Sepharvaims gudom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Och efter de ock fruktade Herran, gjorde de honom Prester på höjderna utaf de ringesta ibland dem, och satte dem i höjdernas hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Alltså fruktade de Herran, och tjente likväl af gudomen, efter hvars folkens sed, dädan de förde voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Och intill denna dag göra de efter det gamla sättet, att de hvarken frukta Herran, eller göra hans seder och rätter, efter de lag och bud, som Herren Jacobs barn budit hafver, hvilkom han det namnet Israel gaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Och gjorde Herren ett förbund med dem, och böd dem, och sade: Frukter inga andra gudar, och tillbeder dem icke, och tjener dem icke, och offrer dem icke;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Utan Herranom, som eder utur Egypti land fört hafver, med stora magt och uträcktom arm, honom frukter, honom tillbeder, och offrer honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Och håller de seder, rätter, lag och bud, som han eder hafver skrifva låtit; att I alltid gören derefter, och icke frukten andra gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Och förgäter icke det förbund, som han med eder gjort hafver, att I icke frukten andra gudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Utan frukter Herran edar Gud; han varder eder hjelpandes ifrån alla edra fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Men desse lydde icke, utan gjorde efter sin förra sed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Alltså fruktade desse Hedningarna Herran, och tjente likväl sina gudar. Sammalunda gjorde ock deras barn och barnabarn, såsom deras fäder gjort hade, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Uti tredje årena Hosea, Ela sons, Israels Konungs, vardt Hiskia Konung, Ahas son, Juda Konungs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Och var fem och tjugu åra gammal, då han vardt Konung, och regerade nio och tjugu är i Jerusalem; hans moder het Abi, Zacharia dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Och han gjorde det godt var för Herranom, såsom hans fader David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Han lade bort de höjder, och bröt omkull stodarna, och utrotade lundarna, och slog sönder den kopparormen, som Mose gjort hade; ty allt intill den tiden hade Israels barn rökt för honom, och han kallade honom Nehusthan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Han förtröste på Herran Israels Gud, så att ingen hans like var efter honom, ej heller för honom, ibland alla Juda Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Han höll sig intill Herran, och trädde icke ifrå honom, och höll hans bud, som Herren hade budit Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Och Herren var med honom, och hvart han utdrog, handlade han visliga. Dertill föll han af ifrå Konungen i Assyrien, och var honom icke underdånig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Han slog ock de Philisteer, allt intill Gasa, och deras gränsor, både slott och fasta städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Uti fjerde årena Hiskia, Juda Konungs, det var sjunde året Hosea, Ela sons, Israels Konungs, då drog Salmanasser, Konungen i Assyrien, upp emot Samarien, och belade det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Och vann det efter tre år, uti sjette Hiskia åre, det är, uti nionde årena Hosea, Israels Konungs, så vardt Samarien vunnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Och Konungen af Assyrien förde Israel bort till Assyrien, och satte dem i Halah och Habor, vid den älfven Gosan, och uti de Meders städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Derföre, att de icke lydt hade Herrans sins Guds röst, och hade öfverträdt hans förbund; och allt det Mose Herrans tjenare budit hade, det hade de intet lydt, eller gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Men uti fjortonde årena Konungs Hiskia, drog upp Sanherib, Konungen i Assyrien, emot alla fasta städer i Juda, och tog dem in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Då sände Hiskia, Juda Konung, till Konungen af Assyrien i Lachis, och lät säga honom: Jag hafver syndat, vänd om ifrå mig; hvad du lägger mig uppå, det vill jag draga. Så lade Konungen af Assyrien på Hiskia, Juda Konung, trehundrad centener silfver, och tretio centener guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Alltså gaf Hiskia ut allt det silfver, som i Herrans hus, och i Konungshusets drätsel funnet vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'På den samma tiden slog Hiskia, Juda Konung, sönder dörrarna af Herrans tempel, och de skifvor, som han sjelf hade låtit bedraga dem med, och fick dem Konungenom af Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Och Konungen af Assyrien sände Tharthan, och öfversta kamereraren, och RabSake ifrå Lachis, till Konung Hiskia med stora magt till Jerusalem, och de drogo upp; och då de kommo, höllo de vid vattugrafvena af öfversta dammen, som ligger vid den vägen på valkareåkrenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Och de kallade Konungen. Då kom ut till dem Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Asaphs son, cancelleren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Och RabSake sade till dem: Käre, säger Konung Hiskia: Så säger den store Konungen, Konungen af Assyrien: Hvad är detta för en tröst, der du förlåter dig uppå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Menar du, att du hafver ännu råd och magt till att strida? Hvaruppå förlåter då du dig nu, att du äst affallen ifrå mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Si, förlåter du dig uppå den sönderbråkade rörstafven Egypten? Hvilken som stöder sig vid honom, honom varder han gångandes upp i handena, och genomstinger henne; alltså är Pharao, Konungen i Egypten, allom dem som förlåta sig på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Om I ock viljen säga till mig: Vi förlåte oss på Herran vår Gud; är icke han den, hvilkens höjder och altare Hiskia hafver aflagt, och sagt till Juda och Jerusalem: För detta altaret, som i Jerusalem är, skolen I tillbedja?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Så gör nu samman en hop minom herra, Konungenom af Assyrien, så vill jag få dig tutusend hästar; lät se, om du kan åstadkomma dem, som deruppå rida måga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Huru vill du då blifva ståndandes för en den minsta höfdingan, mins herras underdåna, om du förlåter dig uppå Egypten, för vagnars och resenärars skull?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Menar du, att jag utan Herrans vilja är hit uppdragen, till att förderfva denna staden? Herren hafver mig det befallt: Drag upp i detta landet, och förderfva det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Då sade Eliakim, Hilkia son, och Sebna, och Joah, till RabSake: Tala med dina tjenare på Syrisko, ty vi förstå det, och tala icke med oss på Judisko, för folkens öron, som på muren är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Men RabSake sade till dem: Hafver nu min herre sändt mig till din herra, eller till dig, att jag dessa orden säga skulle? Ja, till de män som sitta på muren, att de skulle äta sin egen träck med eder, och dricka sitt piss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Alltså stod RabSake, och ropade med höga röst på Judisko, talade, och sade: Hörer den stora Konungens röst, Konungens af Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Detta säger Konungen: Låter icke Hiskia bedraga eder; ty han förmår icke fria eder utu mine hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Och låter icke Hiskia förtrösta eder på Herran, så att han säger: Herren skall fria oss, och denne stad skall icke gifven varda i Konungens händer af Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Hörer icke Hiskia; ty så säger Konungen af Assyrien: Görer mig till vilja, och kommer ut till mig, så skall hvar och en äta af sitt vinträ, och af sitt fikonaträ, och dricka af sin brunn:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Intilldess jag kommer, och hemtar eder uti ett land, det edro lande likt är, der korn, must, bröd, vingårdar, oljoträ, olja och hannog uti är, så fån I lefva, och icke dö; hörer intet Hiskia, ty han förförer eder, då han säger: Herren varder oss hjelpandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Hafva ock Hedningarnas gudar hvar och en hulpit sitt land ifrå Konungens hand i Assyrien?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Hvar äro de gudar i Hamath och Arphad? Hvar äro de gudar i Sepharvaim, Hena och Iva? Hafva de ock hulpit Samarien utu mine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Hvar är en gud ibland alla lands gudar, som sitt land friat hafver utu mina hand, att Herren nu skall fria Jerusalem utu mina hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Då tigde folket, och svarade honom intet; ty Konungen hade budit, och sagt: Svarer honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Så kom då Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Asaphs son, cancelleren, till Hiskia med rifven kläder, och gåfvo honom tillkänna RabSake ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Då Konung Hiskia det hörde, ref han sin kläder, och drog en säck uppå sig, och gick in uti Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Och sände Eliakim hofmästaren, och Sebna skrifvaren, samt med de äldsta Presterna, klädda i säcker, till Propheten Esaia, Amos son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Och de sade till honom: Så säger Hiskia: Denne dagen är en bedröfvelses, bannors och förhädelses dag; barnen äro komne till födslon; men ingen magt är till att föda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Om tilläfventyrs Herren din Gud ville höra all RabSake ord, hvilken hans Herre, Konungen i Assyrien, utsändt hafver, till att tala förhädelse emot lefvandes Gud; och till att bannas med de ord, som Herren din Gud hört hafver; så upphäf nu din bön för dem som ännu igenlefde äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Och Konungens Hiskia tjenare kommo till Esaia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Då sade Esaia till dem: Så säger edrom herra: Detta säger Herren: Frukta dig intet för de ord, som du hört hafver, der Konungens tjenare af Assyrien mig med förhädt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Si, jag vill gifva honom en anda, att han skall få höra ett rykte, och draga tillbaka igen i sitt land; och jag vill fälla honom med svärd i hans land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Och då RabSake kom igen, fann han Konungen af Assyrien stridandes emot Libna; förty han hade hört, att han var dragen ifrå Lachis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Och han fick höra om Thirhaka, Konungen i Ethiopien: Si, han är utdragen till att strida emot dig. Då vände han om, och sände båd till Hiskia, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Detta säger Hiskia, Juda Konung: Låt icke din Gud bedraga dig, på hvilken du dig förlåter, och säger: Jerusalem varder icke gifvet uti Konungens hand i Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Si, du hafver hört, hvad Konungarna i Assyrien gjort hafva allom landom, och gifvit dem tillspillo; och du skulle nu friad varda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Hafva ock Hedningarnas gudar friat dem, hvilka mine fäder förderfvat hafva; Gosan, Haran, Reseph, och Edens barn, som i Thelassar voro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Hvar är Konungen i Hamath, Konungen i Arphad, Konungen i den staden Sepharvaim, Hena och Iva?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Då Hiskia hade anammat brefvet af båden, och läsit det, gick han upp i Herrans hus, och upplät det för Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Och bad inför Herranom, och sade: Herre Israels Gud, som sitter öfver Cherubim, du äst allena Gud i all rike på jorden; du hafver gjort himmel och jord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herre, böj din öron, och hör; Herre, upplåt din ögon och se; och hör Sanheribs ord, den hitsändt hafver, till att tala hädelse emot lefvandes Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Det är sant, Herre, Konungarna i Assyrien hafva med svärd förlagt Hedningarna, och deras land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Och hafva kastat deras gudar i elden; ty de voro icke gudar, utan menniskors handaverk, stock och sten; derföre hafva de förlagt dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Men nu, Herre vår Gud, hjelp oss utu hans hand, på det all rike på jordene skola förstå, att du, Herre, allena äst Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Så sände Esaia, Amos son, till Hiskia, och lät säga honom: Detta säger Herren Israels Gud: Hvad du af mig bedit hafver om Sanherib, Konungen i Assyrien, det hafver jag hört.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Detta är det Herren emot honom talat hafver: Jungfrun, dottren Zion, föraktar dig, och bespottar dig; dottren Jerusalem rister hufvudet efter dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Hvem hafver du försmädat och förhädt? Öfver hvem hafver du upphöjt dina röst? Du hafver upphäfvit dina ögon emot den Heliga i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Du hafver genom din sändningabåd försmädat Herran, och sagt: Jag hafver genom mina många vagnar stigit upp på bergshöjderna, uppå Libanons sido; jag hafver afhuggit dess höga ceder, och utvalda furor, och är kommen intill yttersta herberget, i hans Carmels skog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Jag hafver grafvit, och utdruckit de främmande vatten, och hafver med mitt fotabjelle uttorkat all förvarad vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Men hafver du icke hört, att jag detta långt tillförene gjort hafver, och af begynnelsen hafver jag beredt det? Men nu hafver jag det komma låtit, att faste städer skulle förfalla till en öde stenhop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Och de som deruti bodde, skulle varda vanmägtige, och rädas och skämmas, och varda såsom örter på markene, och som gröna gräset till hö på taken, hvilket förtorkas förr än det moget varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Jag vet din boning, din utgång och ingång; och att du rasar emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Så efter du rasar emot mig, och ditt högmod är uppkommet för min öron, så skall jag sätta en ring i dina näso, och ett bett i din mun, och skall föra dig den vägen hem igen, som du hit kommen äst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Och detta skall vara dig ett tecken: Uti detta år ät hvad som förtrampadt är; uti de andro årena hvad sjelft växer; uti tredje årena sår och uppskärer, och planterer vingårdar, och äter deras frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Och Juda hus, som frälst och igenblifvet är, skall ännu rota sig nedantill, och bära frukt ofvantill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Ty utaf Jerusalem varda utgångande de som igenblefne äro; och utaf Zions berg de som undsluppne äro; Herrans Zebaoths nit varder detta görandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Derföre säger Herren om Konungen i Assyrien alltså: Han skall icke komma i denna staden, och ingen pil skjuta der in, och ingen sköld föra der före, och ingen vall uppkasta der omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Utan han skall draga den vägen tillbaka igen, som han kommen är, och skall intet komma i denna staden; Herren hafver det sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Och jag skall beskärma denna staden, så att jag honom hjelpa vill för mina skull, och för Davids min tjenares skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'På den samma nattena for Herrans Ängel ut, och slog i de Assyriers lägre hundradetusend, och fem och åttatio tusend män; och då de om morgonen bittida uppstodo, si, då låg allt fullt med döda kroppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Alltså bröt Sanherib, Konungen af Assyrien, upp, drog sina färde, och vände om, och blef i Nineve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Och då han tillbad i Nisrochs sins guds hus, slogo honom hans söner med svärd, Adrammelech och SarEzer, och undflydde in uti det landet Ararat; och hans son EsarHaddon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'På den tiden vardt Hiskia dödsjuk; och Propheten Esaia, Amos son, kom till honom, och sade till honom: Så säger Herren: Skicka om ditt hus; ty du måste dö, och icke blifva lefvandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Men han vände sitt ansigte till väggena, och bad till Herran, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ack Herre! Kom dock ihåg, att jag hafver troliga vandrat för dig, och med rättsinnigt hjerta, och gjort det dig hafver ljuft varit. Och Hiskia gret svårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Men som Esaia icke ännu halfväges igenom staden utkommen var, kom Herrans ord till honom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Vänd om, och säg Hiskia mins folks Första: Detta säger Herren dins faders Davids Gud: Jag hafver hört dina bön, och sett dina tårar; si, jag vill göra dig helbregda; tredje dagen härefter skall du uppgå i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Och jag skall förlänga ditt lif till femton år, och fria dig och denna staden utu Konungens hand i Assyrien, och beskärma denna staden för mina skull, och för min tjenares Davids skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Och Esaia sade: Får mig hit ett stycke fikon. Och när de hade det fått honom, lade han det på böldena, och han vardt helbregda,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hiskia sade till Esaia: Hvad tecken är dertill, att Herren vill göra mig helbregda, och jag uppgå skall i Herrans hus tredje dagen härefter?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Esaia sade: Detta tecknet skall du hafva af Herranom, att Herren skall så göra med dig, som han sagt hafver; vill du att skuggen skall gå tio streck framåt, eller tio streck tillbaka?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia sade: Det är lätt, att skuggen går framåt tio streck, det vill jag icke; utan att han går tio streck tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Då åkallade Propheten Esaia Herran, och skuggen gick tillbaka tio streck, som han framåt gångit hade på Ahas säjare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'På den tiden sände Berodach Baladan, Baladans son, Konungen i Babel, bref och gåfvor till Hiskia; förty han hade hört, att Hiskia hade varit krank.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Och Hiskia gjorde sig glad med dem, och viste dem hela örtahuset, silfver, guld, speceri, och den bästa oljon, och harneskhuset, och allt det i hans fatebur för handene var; och var intet i hans hus, och i allt hans våld, det Hiskia dem icke viste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Så kom Propheten Esaia till Konung Hiskia, och sade till honom: Hvad hafva desse männerna sagt? Och hvadan äro de komme till dig? Hiskia sade: De äro utaf fjerran land komne till mig, ifrå Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Han sade: Hvad hafva de sett i dino huse? Hiskia sade: De hafva sett allt det i mino huse är; och i mina håfvor är intet, som jag dem icke vist hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Då sade Esaia till Hiskia: Hör Herrans ord:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Si, den tid skall komma, att allt skall bortfördt varda utu ditt hus till; Babel, och allt det dine fäder församlat hafva intill denna dag; och skall intet igenlefdt varda, säger Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Dertill de barn, som af dig komma, som du födandes varder, skola varda tagne till att vara kamererare i Konungens palats i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia sade till Esaia: Det är så godt, som Herren sagt hafver. Och sade ytterligare: Vare dock frid och sanning i min tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Hvad nu mer af Hiskia sägandes är, och all hans magt, och hvad han gjort hafver, och om dammen och vatturännorna, dermed han ledde vatten in i staden, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Och Hiskia afsomnade med sina fäder; och Manasse hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse var tolf åra gammal, då han vardt Konung, och regerade fem och femtio år i Jerusalem; hans moder het Hephziba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Och han gjorde det ondt var för Herranom, efter Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Och han afvände sig, och uppbyggde de höjder, som hans fader Hiskia nederbrutit hade, och uppsatte Baals altare, och gjorde lundar, såsom Achab, Israels Konung, gjort hade; och tillbad all himmelens här, och tjente dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Och byggde altare i Herrans hus, der Herren om sagt hade: Jag skall sätta mitt Namn i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Och han byggde allom himmelens här altare, uti båda gårdarna till Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Och lät sin son gå igenom eld, och aktade på foglarop och tecken, och höll spåmän och tecknatydare, och gjorde mycket det ondt var för Herranom, der han honom med förtörnade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Han satte ock en lundagud, den han gjort hade, i huset, om hvilket Herren till David och hans son Salomo sagt hade: Uti detta hus, och i Jerusalem, det jag utvalt hafver utur alla Israels slägter, vill jag sätta mitt Namn i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Och skall icke låta Israels fot mer röra sig ifrå det land, som jag deras fader gifvit hafver dock så, om de hålla och göra efter allt det jag budit hafver, och efter all de lag, som min tjenare Mose dem budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Men de lydde intet; utan Manasse förförde dem, så att de gjorde värre än Hedningarna, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Då talade Herren genom sina tjenare Propheterna, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Derföre, att Manasse, Juda Konung, hafver denna styggelsen gjort, som värre är än all den styggelse som de Amoreer gjort hafva, som för honom voro; och hafver desslikes kommit Juda till att synda med sina afgudar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Derföre säger Herren Israels Gud alltså: Si, jag skall låta komma olycka öfver Jerusalem och Juda, så att hvilken som helst det får höra, honom skall det gälla i båda hans Öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Och jag skall utsträcka öfver Jerusalem Samarie snöre, och Achabs hus vigt; och skall utskölja Jerusalem, såsom man utsköljer diskar, och skall omstörta det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Och jag skall låta några af minom arfvedel blifva qvara, och gifva dem uti deras fiendars händer, att de skola varda till ett rof och sköfvel allom deras fiendom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Derföre, att de gjort hafva det mig illa behagar, och hafva förtörnat mig, ifrå den dag, då deras fäder foro utur Egypten, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Och utgöt Manasse ganska mycket oskyldigt blod, in tilldess Jerusalem på alla sidor fullt vardt; förutan de synder, der han med kom Juda till att synda, att de gjorde det ondt var för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Hvad nu mer af Manasse sägandes är, och allt det han gjort hafver, och om hans synder, som han bedref, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Och Manasse afsomnade med sina fäder, och vardt begrafven i trägårdenom vid lians hus, nämliga i Ussa trägård; och hans son Amon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Tu och tjugu åra gammal var Amon, då han vardt Konung, och han regerade i tu år i Jerusalem; hans moder het Mesullemeth, Haruz dotter, af Jotba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Och han gjorde det Herranom illa behagade, såsom hans fader Manasse gjort hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Och vandrade i allan den väg, som hans fader vandrat hade, och tjente de afgudar, som hans fader tjent hade, och tillbad dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Och öfvergaf Herran sina fäders Gud, och vandrade icke på Herrans väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Och hans tjenare gjorde ett förbund emot Amon, och dråpo Konungen i hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Men folket i landena slog alla dem, som förbundet emot Konung Amon gjort hade. Och folket i landena gjorde Josia, hans son, till Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Hvad Amon nu mer gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Och man begrof honom i hans graf, i Ussa trägärd; och hans son Josia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josia var åtta åra gammal, då han vardt Konung, och regerade ett och tretio år i Jerusalem; hans moder het Jedida, Adaja dotter, af Bozkath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Han gjorde det godt var för Herranom, och vandrade i allom sins faders Davids väg, och böjde hvarken på högra sidona, eller på den venstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Uti adertonde årena Konungs Josia, sände Konungen Saphan, Azalia son, Mesullams sons, skrifvaren, bort uti Herrans hus, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Gack upp till öfversta Presten Hilkia, att man må få honom de penningar, som till Herrans hus införde äro, och dörravaktarena församlat hafva af folkena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Att de måga gifva dem arbetarena, som beställde äro i Herrans hus, och gifva dem som arbeta på Herrans hus, och bota det som förfallet är i husena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Nämliga timbermannom, byggningsmannom, murmästarom, och dem som trä och huggen sten köpa skola, till husets förbättring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Dock så, att man ingen räkenskap skulle taga af dem för de penningar, som under deras hand antvardade vordo; utan de skulle handla dermed på sina tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Och öfverste Presten Hilkia sade till skrifvaren Saphan: Jag hafver funnit lagbokena uti Herrans hus; och Hilkia fick Saphan bokena, att han skulle den läsa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Och skrifvaren Saphan bar henne till Konungen, och bådade honom igen, och sade: Dine tjenare hafva tillhopahemtat de penningar, som i husena funne voro, och hafva utgifvit dem arbetarena, som beställde äro i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Och förtäljde skrifvaren Saphan Konungenom, och sade: Hilkia Presten fick mig ena bok; och Saphan las henne för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Då Konungen hörde orden i lagbokene, ref han sin kläder sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Och Konungen böd Hilkia Prestenom, och Ahikam, Saphans sone, och Achbor, Michaja sone, och Saphan skrifvarenom, och Asaja, Konungens tjenare, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Går bort, och fråger Herran, för mig, för folket, och för hela Juda, om denna bokenes ord, som funnen är; ty det är en stor Herrans vrede, som är upptänd öfver oss; derföre, att våre fäder icke lydt hafva denna bokenes ord, att de måtte gjort allt det derutinnan skrifvet är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Då gingo åstad Hilkia Presten, Ahikam, Achbor, Saphan och Asaja, till den Prophetissan Hulda, Sallums hustru, Thikva sons, Harhas sons, klädavaktarens; och hon bodde i Jerusalem i dem andra delenom, och de talade med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Men hon sade till dem: Detta säger Herren Israels Gud: Säger dem månne, som eder till mig sändt hafver:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Så säger Herren: Si, jag skall låta komma olycko öfver detta rum, och dess inbyggare, efter all lansens ord, som Juda konung hafver läsa låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Derföre, att de hafva öfvergifvit mig, och rökt andra gudar, förtörnande mig med allt deras handaverk; derföre skall min vrede upptändas emot detta rum, och skall icke utsläckt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Men Juda Konunge, som eder utsändt hafver till att fråga Herran, skolen I så säga: Så säger Herren Israels Gud:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Derföre, att ditt hjerta hafver bevekt sig, af de ord, som, du hört hafver, och hafver ödmjukat dig för Herranom, då du hörde hvad jag sagt hade emot detta rum, och dess inbyggare, att de skulle varda till en förödelse och förbannelse, och hafver rifvit din kläder sönder, och hafver gråtit för mig, så hafver jag ock hört det, säger Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Derföre vill jag samka dig till dina fäder, att du skall samkas i grafvena med frid, och din ögon icke se skola alla denna olyckona, som jag öfver detta rum föra skall. Och de sade Konungenom det igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Och Konungen sände bort, och till honom församlades alle de äldste i Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Och Konungen gick upp i Herrans hus, och hvar man af Juda, och alle Jerusalems inbyggare med honom, Prester och Propheter, och allt folket, både små och store; och man las för deras öron all förbundsens boks ord, hvilken i Herrans hus funnen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Och Konungen gick in till en stod, och gjorde ett förbund för Herranom, att de skulle vandra efter Herranom, och hålla hans bud, vittnesbörd och rätter, af allt hjerta, och af allo själ, att de skulle upprätta detta förbunds ord, som skrifne stodo uti desso bok; och allt folket trädde uti förbundet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Och Konungen böd öfversta Prestenom Hilkia, och Prestenom af det andra skiftet, och dörravaktaromen, att de skulle utkasta af Herrans tempel allahanda tyg, som till Baal och lunden, och all himmelens här gjordt var; och de brände det upp utanför Jerusalem i Kidrons dal, och stoftet deraf vardt buret till BethEl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Och han afsatte de Camarim, hvilka Juda Konungar stiktat hade, till att röka på höjderna uti Juda städer, och omkring Jerusalem; desslikes Baals, solenes, månans, planeternas och all himmelens härs rökare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Och lät föra lunden utu Herrans hus, ut för Jerusalem, i Kidrons bäck; och brände honom upp i Kidrons bäck, och gjorde honom till stoft, och kastade stoftet uppå det meniga folks grifter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Och han bröt bort de roffarehus, som voro vid Herrans hus, der qvinnor uti vofvo tapeter till lunden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Och han lät församla alla Presterna utu Juda städer, och orenade de höjder, der Presterna rökte, ifrå Geba allt intill BerSeba; och han bröt bort portaltaren, som voro uti ingångenom i Josua stadsfogdans port, hvilken voro på venstra sidone, der man går till stadsporten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Dock offrade icke höjdernas Prester någon tid på Herrans altare i Jerusalem, utan åto af de osyrade brödena, ibland sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Han orenade ock Tophet, uti Hinnoms barnas dal, att ingen skulle låta gå sin son eller sina dotter genom eld för Molech;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Och tog bort de hästar, hvilka Juda Konungar solene uppsatt hade, i ingångenom åt Herrans hus, till NethanMelechs åminnelse, kamererarens, som i Parvarim var; och solenes vagnar brände han upp i eld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Så ock altaren på taken i Ahas sal, den Juda Konungar gjort hade; och de altare, som Manasse gjort hade uti de två gårdar åt Herrans hus, bröt Konungen bort, och lopp dädan, och kastade deras stoft i Kidrons bäck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Och de höjder, som för Jerusalem voro, på högra sidone, vid berget Mashith, som Salomo Israels Konung byggt hade till Astoreth, Zidons styggelse, och Chemos, Moabs styggelse, och Milcom, Ammons barnas styggelse, orenade Konungen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Och slog sönder stoderna, och utrotade lundarna, och uppfyllde deras rum med menniskoben;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Sammalunda ock det altaret i BethEl, höjden, som Jerobeam, Nebats son, gjort hade, den Israel hade kommit till att synda; det samma altaret bröt han neder, och höjdena, och brände upp höjdena, och gjorde henne till stoft, och brände upp lunden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Och Josia vände sig om, och fick se de grifter, som voro på bergena, och sände bort, och lät hemta benen utu grifterna, och uppbrände dem på altarena, och orenade det, efter Herrans ord, som Guds mannen utropat hade, den detta så föresagt hade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Och han sade: Hvad är detta för en vård, som jag här ser? Och folket i stadenom sade till honom: Det är den Guds mansens grift, som af Juda kom, och detta utropade, som du gjort hafver med altarena i BethEl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Och han sade: Låt honom ligga; ingen röre hans ben. Alltså vordo hans ben friade, med den Prophetens ben, som utaf Samarien kommen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Han kastade ock bort all höjders hus uti Samarie städer, som Israels Konungar gjort hade, till att förtörna (Herran), och gjorde med dem alldeles såsom han i BethEl gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Och han offrade alla höjdernas Prester, som der voro, på altaren, och brände så menniskoben deruppå, och kom igen till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Och Konungen böd folkena, och sade: Håller Herranom edrom Gud Passah, såsom skrifvet är i denna förbunds bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Ty intet Passah var så hållet som detta, ifrå de domares tid, som Israel dömde, och i alla Israels Konungars och Juda Konungars tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Utan i adertonde årena Konungs Josia vardt detta Passah hållet Herranom i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Desslikes rensade Josia ut alla spåmän, tecknatydare, beläte och afgudar, och all styggelse, som i Juda land och i Jerusalem sedde vordo; på det han skulle upprätta lagsens ord, som skrifne stodo i bokene, som Presten Hilkia fann i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Hans like hade ingen Konung varit för honom, den så af allt hjerta, af allo själ, och alla krafter sig till Herran vände, efter all Mose lag; och efter honom kom ej heller hans like upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Dock vände icke Herren sig ifrå sine stora vredes grymhet, der han med öfver Juda förtörnad var, för all de retelses skull, dermed Manasse honom rett hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Och Herren sade: Jag vill ock kasta Juda ifrå mitt ansigte, såsom jag Israel bortkastat hafver; och skall förkasta denna staden, som jag utvalt hafver, nämliga Jerusalem, och det hus, der jag om sagt hafver: Mitt Namn skall vara der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Hvad nu mer af Josia sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Uti hans tid drog Pharao Necho, Konungen i Egypten, upp emot Konungen af Assyrien, vid den älfvena Phrat; men Konung Josia drog emot honom, och blef död i Megiddo, då han hade sett honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Och hans tjenare förde honom dödan ifrå Megiddo, och hade honom till Jerusalem, och begrofvo honom i hans graf; och folket i landena togo Joahas, Josia son, och smorde honom, och gjorde honom till Konung i hans faders stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Tre och tjugu åra gammal var Joahas, då han vardt Konung, och regerade tre månader i Jerusalem; hans moder het Hamutal, Jeremia dotter af Libna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Och han gjorde det ondt var för Herranom, såsom hans fäder gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Men PharaoNecho grep honom i Riblath i Hamaths land, att han icke regera skulle i Jerusalem; och lade en beskattning på landet, hundrade centener silfver, och en centener guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Och PharaoNecho gjorde Eliakim, Josia son, till Konung uti hans faders Josia stad, och vände hans namn Jojakim. Men Joahas tog han, och förde in uti Egypten; der blef han död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Och Jojakim gaf Pharao silfret och guldet; dock beskattade han landet, att han sådant silfver gifva kunde efter Pharaos befallning; hvar och en, efter sina förmågo, beskattade han till silfver och guld ibland folket i landena, att han det PharaoNecho gifva skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Fem och tjugu åra gammal var Jojakim, då han vardt Konung, och regerade ellofva år i Jerusalem; hans moder het Zebuda, Pedaja dotter af Ruma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Och han gjorde det ondt var för Herranom, såsom hans fäder gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Uti hans tid drog NebucadNezar upp, Konungen i Babel, och Jojakim vardt honom underdånig i tre är. Och han vände sig om, och föll ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Och Herren lät komma öfver honom krigsfolk, utu Chaldeen, utu Syrien, utu Moab, och ifrån Ammons barn; och lät komma dem i Juda, att de skulle förderfva honom, efter Herrans ord, det han talat hade genom sina tjenare Propheterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Men det skedde Juda alltså, efter Herrans ord, på det han skulle kasta dem ifrå sitt ansigte för Manasse synds skull, som han gjort hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Och för det oskyldiga blods skull, som han utgöt, och gjorde Jerusalem fullt med oskyldigt blod; och derföre ville Herren icke förlåtat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Hvad nu mer af Jojakim sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Och Jojakim afsomnade med sina fäder, och hans son Jojachin vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Och Konungen i Egypten drog icke mer utu sitt land; förty Konungen i Babel hade honom borttagit allt det som Konungens i Egypten var, ifrån Egypti bäck allt intill den älfven Phrath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Aderton åra gammal var Jojachin, då han Konung vardt, och regerade tre månader i Jerusalem; hans moder het Nehustha, Elnathans dotter af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Och han gjorde det ondt var för Herranom, såsom hans fader gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'På den tiden drogo NebucadNezars Konungens tjenare i Babel upp till Jerusalem, och kringlade staden med bålverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Och då NebucadNezar kom till staden med sina tjenare, belade han honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Men Jojachin, Juda Konung, gick ut till Konungen af Babel med sine moder, med sina tjenare, med sina öfverstar och kamererare. Och Konungen af Babel anammade honom i lians rikes åttonde åre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Och tog ut dädan alla håfvor uti Herrans hus, och i Konungshuset; och slog sönder all gyldene kärile, som Salomo, Israels Konung, gjort hade uti Herrans tempel, såsom Herren sagt hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Och förde bort hela Jerusalem, alla öfverstar, alla väldiga, tiotusend fångar, och alla timbermän, och alla smeder, och lät intet qvart blifva, utan det ringesta folket i landena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Och förde bort Jojachin till Babel, Konungens moder, Konungens hustrur, och hans kamererare; desslikes de myndiga i landena förde han ock fångna bort ifrå Jerusalem till Babel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Och hvad bästa folket var, sjutusend, och de timbermän och smeder, tusende, alle starke krigsmän. Och Konungen af Babel förde dem till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Och Konungen af Babel gjorde Matthania, hans faderbroder, till Konung i hans stad, och förvände hans namn Zedekia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Ett och tjugu år gammal var Zedekia, då han vardt Konung, och regerade ellofva år i Jerusalem; hans moder het Hamital, Jeremia dotter af Libna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Och han gjorde det ondt var för Herranom, såsom Jojakim gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Ty det skedde alltså med Jerusalem och Juda utaf Herrans vrede, tilldess han kastade dem bort ifrå sitt ansigte. Och Zedekia vardt affällig ifrå Konungenom i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Och det begaf sig i nionde årena af hans rike, på tionde dagen i tionde månadenom, kom NebucadNezar, Konungen i Babel, med all sin magt för Jerusalem, och de lägrade sig der före, och byggde skansar allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Alltså vardt staden belagd, allt intill ellofte året af Konung Zedekia rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Men i nionde månadenom vardt hungren stark i stadenom, så att folket i landena hade intet äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Då föll man in i staden, och alle krigsmän flydde om nattena, den vägen ifrå porten, som går emellan de två murar åt Konungsträgården. Och de Chaldeer lågo omkring staden. Och han flydde den vägen åt hedmarkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Men de Chaldeers magt jagade efter Konungen, och grepo honom på hedmarkene vid Jericho. Och alle krigsmännerna, som när honom voro, vordo förskingrade ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Men Konungen grepo de, och förde honom upp till Konungen af Babel till Riblath; och de sade en dom öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Och de slogo Zedekia barn ihjäl för hans ögon, och stungo Zedekia hans ögon ut, och bundo honom med kedjor, och förde honom till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'På sjunde dagen i femte månadenom, det är nittonde året NebucadNezars, Konungens i Babel, kom NebusarAdan hofmästaren, Konungens tjenare i Babel, till Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Och uppbrände Herrans hus, och Konungshuset, och all hus i Jerusalem, och all stor hus brände han upp med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Och hela de Chaldeers magt, som med hofmästarenom var, bröt omkull murarna, som omkring Jerusalem voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Men det andra folket, som qvart var i stadenom, och de som till Konungen af Babel fallne voro, och det andra meniga folket, förde NebusarAdan hofmästaren bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Och af de ringesta i landena lät hofmästaren blifva till vingårdsmän, och åkermän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Men de kopparstodar i Herrans hus, och stolarna, och kopparhafvet, som i Herrans hus var, slogo de Chaldeer sönder, och förde kopparen till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Och grytor, skoflar, knifvar, skedar, och all kopparkärile, dermed man tjente, togo de bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Dertill tog hofmästaren pannor och bäcken, hvad af guld och silfver var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Två stodar, ett haf, och de stolar, som Salomo hade göra låtit till Herrans hus; kopparen af all denna tygen stod icke till vägandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Aderton alnar hög var en stoden, och knappen derpå var ock af koppar, och tre alnar hög; och gjordarne, och granatäplen allt omkring knappen, var ock allt af koppar; vid samma sättet var ock den andre stoden med gjordar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Och hofmästaren tog Presten Seraja af första skiftet, och Presten Zephania af det andra skiftet, och tre dörravaktare,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Och en kamerer utu stadenom, som öfver krigsmännerna satt var, och fem män, som allstädes hade ståndit för Konungenom, och i stadenom funne voro, och Sopher, härhöfvitsmannen, som folket i landena strida lärde, och sextio män af landsfolkena, som i stadenom funne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Dessa tog NebusarAdan hofmästaren, och förde dem till Konungen af Babel till Riblath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Och Konungen i Babel slog dem ihjäl i Riblath, i de landena Hamath. Alltså vardt Juda bortförd utu sitt land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Men öfver det folk, som qvart blef i Juda land, som NebucadNezar, Konungen i Babel, qvart blifva lät, satte han Gedalja, Ahikams son, Saphans sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Då nu allt krigsfolkets höfvitsmän och männerna hörde, att Konungen af Babel hade uppsatt Gedalja, kommo de till Gedalja i Mizpa, nämliga Ismael, Nethania son, och Johanan, Kareahs son, och Seraja, Thanhumeths son, den Netophathiten, och Jaesania, Maachati son, samt med deras män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Och Gedalja svor dem, och deras män, och sade till dem: Frukter eder intet att vara de Chaldeers underdånar; blifver i landena, och varer Konungenom af Babel underdånige, så går eder väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Men i sjunde månadenom kom Ismael, Nethania son, Elisama sons, utaf Konungsliga slägt, och tio män med honom, och slogo Gedalja ihjäl; dertill de Judar och Chaldeer, som med honom voro i Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Då reste sig upp allt folket, både små och store, och krigsöverstarna, och kommo in uti Egypten; förty de fruktade sig för de Chaldeer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Uti sjunde och tretionde årena, sedan Jojachin, Juda Konung, bortförd var, på sjunde och tjugonde dagen i tolfte månadenom, hof EvilMerodach, Konungen i Babel, uti första årena af sitt rike, Jojachins, Juda Konungs, hufvud upp utu fängslehuset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Och talade vänliga med honom, och satte hans stol utöfver de Konungars stolar, som när honom voro i Babel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Och förvandlade hans fängelsekläder; och han åt alltid inför honom i alla sina lifsdagar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Och satte honom före hans del, den man honom alltid gifva skulle af Konungenom, hvar dag, så länge han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalaleel, Jared,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Methusalah, Lamech,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sena, Ham, Japhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Japhets barn äro desse: Gomer, Magog, Madai, Javan, Thubal, Mesech, Thiras.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Men Gomers barn äro: Ascenas, Riphath, Thogarma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Javans barn äro: Elisa, Tharsisa, Chittim, Dodam, Dodanim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hams barn äro: Chus, Mizraim, Phut, Canaan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Men Chus barn äro desse: Seda, Havila, Sabtha, Raema, Sabtecha, Raema barn äro: Seba och Dedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Men Chus födde Nimrod. Han begynte vara väldig på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim födde Ludim, Anamim, Lehabim, Naphthuhim,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrusim, Casluhim; af hvilkom utkomne äro de Philistim och Caphthorim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Men Canaan födde Zidon, sin första son, och Heth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Jebusi, Emori, Girgasi,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hivi, Arki, Sini,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvadi, Zemari och Hamathi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sems barn äro desse: Elam, Assur, Arphachsad, Lud, Aram, Uz, Hul, Gether och Maseeh.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Men Arphachsad födde Salah; Salah födde Eber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Men Eber vordo födde två söner; den ene het Peleg, derföre, att i hans tid vardt landet deladt; och hans broder het Jaketan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Jaketan födde Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Usal, Dikela,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Seba,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Havila och Jobab. Desse äro alle Jaketans barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphachsad, Salah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tharah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, det är Abraham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Men Abrahams barn äro: Isaac och Ismael.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Detta är deras ätter: den förste Ismaels son Nebajoth; Kedar, Adbeel, Mibsam,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Massa, Hadad, Thema,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jethur, Naphis, Kedma. Desse äro Ismaels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Men Keturas barn, Abrahams frillos: hon födde Simran, Jaksan, Medan, Midian, Jisbak, Suah. Och Jaksans barn äro: Seba och Dedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Och Midians barn äro: Epha, Epher, Hanoch, Abida, Eldaa. Desse äro alle Keturas barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham födde Isaac. Isaacs barn äro: Esau och Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Esau barn äro: Eliphas, Reguel, Jeus, Jaelam, Korah.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Eliphas barn äro: Teman, Omar, Zephi, Gatham, Kenas, Thimna, Amalek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguels barn äro: Nahath, Serah, Samma och Missa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirs barn äro: Lotan, Sobal, Zibeon, Ana, Dison, Ezer, Disan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotans barn äro: Hori, Homam; och Thimna var Lotans syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sobals barn äro: Aljan, Manahat, Ebal, Zephi, Onam. Zibeons barn: Aja och Ana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Ana barn äro: Dison. Disons barn äro: Hamran, Esban, Jithran, Cheran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Ezers barn äro: Bilhan, Saavan, Jaachan. Disans barn äro: Uz och Aran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Desse äro de Konungar, som regerade uti Edoms land, förra än någor Konung regerade ibland Israels barn: Bela, Geors son; och hans stad het Dinhaba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Och då Bela blef död, vardt Konung i hans stad Jobab, Serahs son af Bozra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Då Jobab blef död, vardt Konung i hans stad Husam, utaf de Themaniters land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Då Husam blef död, vardt Konung i hans stad Hadad, Badads son, hvilken slog de Midianiter på de Moabiters mark; och hans stad het Avith.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Då Hadad blef död, vardt Konung i hans stad Samla af Masreka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Då Samla blef död, vardt Konung i hans stad Saul af Rehoboth vid älfvena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Då Saul blef död, vardt Konung i hans stad Baalhanan, Achbors son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Då Baalhanan blef död, vardt Konung i hans stad Hadad; och hans stad het Pagi; och hans hustru het Mehetabeel, Matreds dotter, och Mesahabs dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Då Hadad blef död, vordo Förstar i Edom: den Försten Thimna, den Försten Alja, den Försten Jetheth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Den Försten Aholibama, den Försten Ela, den Försten Pinon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Den Försten Kenas, den Försten Theman, den Försten Mibzar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Den Försten Magdiel, den Försten Iram. Desse äro de Förstar i Edom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Desse äro Israels barn: Ruben, Simeon, Levi, Juda, Isaschar, Sebulon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, BenJamin, Naphthali, Gad, Asser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Juda barn äro: Er, Onan, Sela; de tre vordo honom födde af Sua dotter den Cananeiskon. Men Er, den förste Juda son, var arg för Herranom, derföre drap han honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Men Thamar hans sonahustru födde honom Perez och Serah, så att all Juda barn voro fem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Perez barn äro: Hezron och Hamul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Men Serah barn äro: Simri, Ethan, Heman, Chalcol, Dara. Desse tillhopa äro fem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Charmi barn äro: Achar, hvilken bedröfvade Israel, då han förtog sig på det tillspillogifvet var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Ethans barn äro: Asaria.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Hezrons barn, som honom födde äro: Jerahmeel, Ram, Chelubai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram födde Amminadab; Amminadab födde Nahesson, den Förstan för Juda barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahesson födde Salma; Salma födde Boas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boas födde Obed; Obed födde Isai;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai födde sin första son Eliab, AbiNadab den andre, Simea den tredje,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneel den fjerde, Raddai den femte,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozem den sjette, David den sjunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Och deras systrar voro: ZeruJa och Abigail. ZeruJa barn äro: Abisai, Joab, Asahel, de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Men Abigail födde Amasa; och Amasa fader var Jether, en Ismaelit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Caleb, Nezrons son, födde med den qvinnone Asuba och med Jerigoth; och desse äro hennes barn; Jeser, Sobab och Ardon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Då Asuba blef död, tog Caleb Ephrath; hon födde honom Hur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur födde Uri; Uri födde Bezaleel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Derefter besof Hezron Machirs dotter, Gileads faders; och han tog henne, då han var sextio åra gammal; och hon födde honom Segub.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub födde Jair; han hade tre och tjugu städer i Gileads land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Och han tog utaf de samma Gesur och Aram, Jairs byar; dertill Kenath med dess döttrar, sextio städer. Desse äro alle Machirs barn, Gileads faders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Efter Hezrons död i CalebEphrata lefde Hezron sina hustru Abia; hon födde honom Ashur, Thekoa fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jerahmeel, Hezrons förste son, hade barn; den förste Ram, Buna, Oren och Ozem, och Ahia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Och Jerahmeel hade ännu ena andra hustru, som het Atarah; hon är Onams moder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Rams barn, Jerahmeels första sons, äro: Maaz, Jamin och Eker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Men Onam hade barn: Sammai och Jada. Sammai barn äro: Nadab och Abisur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Men Abisurs hustru het Abihail; hon födde honom Ahban och Molid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadabs barn äro: Seled och Appaim; och Seled blef död barnlös.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Appaims barn äro: Jisei. Jisei barn äro: Sesan. Sesans barn äro: Ahlai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Jada barn, Sammai broders, äro: Jether och Jonathan; men Jether blef död barnlös.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Men Jonathans barn äro: Peleth och, Sasa. Det äro Jerahmeels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Men Sesan hade inga söner, utan döttrar. Och Sesan hade en Egyptisk tjenare, han het Jarha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Och Sesan gaf Jarha, sinom tjenare, sina dotter till hustru; hon födde honom Attai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai födde Nathan; Nathan födde Sabad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Sabad födde Ephlal; Ephlal födde Obed;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed födde Jehu; Jehu födde Asaria;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asaria födde Helez; Helez födde Elasa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa födde Sismai; Sismai födde Sallum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum födde Jekamia; Jekamia födde Elisama.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Calebs barn, Jerahmeels broders, äro: Mesa, hans förste son; han är Siphs fader, och Maresa barn, Hebrons faders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebrons barn äro: Korah, Thappuah, Rekem och Serna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Men Serna födde Raham, Jorkeams fader; Rekem födde Sammai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Sammai son het Maon; och Maon var Bethzurs fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Men Epha, Calebs frilla, födde Haran, Moza och Gases. Haran födde Gases.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Men Jahdai barn äro: Regem, Jotham, Gesan, Pelet, Epha och Saaph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Men Maacha, Calebs frilla, födde Seber och Thirhana;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Och födde desslikes Saaph, Madmanna foder, och Seva, Machbena fader, och Gibea fader. Achsa var Calebs dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Desse voro Calebs barn, Hurs den förste sonens af Ephrata: Sobal, KiriathJearims fader,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, BethLehems fader, Hareph, BethGaders fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Och Sobal, KiriathJearims fader, hade söner; han såg halfva Manuhoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Men de slägter i KiriathJearim voro: de Jithriter, Puthiter, Sumathiter och Misraiter. Utaf dessom äro utkomne de Zorgathiter och Esthaoliter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salma barn äro: BethLehem och de Netophathiter, kronorna till Joabs hus, och hälften af de Manathiter af den Zorgiten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Och de skrifvares släkter, som i Jabez bodde, äro: de Thirathiter, Simathiter, Suchathiter. Det äro de Kiniter, som komne äro af Hamath, BethRechabs fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Desse äro Davids barn, som honom födde äro i Hebron: den förste, Ammon, af Ahinoam den Jisreelitiskone; den andre, Daniel, af Abigail den Carmelitiskone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Den tredje, Absalom, Maachas son, Thalmai dotters, Konungens i Gesur; den fjerde, Adonia, Haggiths son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Den femte, SephathJa, af Abital; den sjette, Jithream, af hans hustru Egla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Desse sex äro honom födde i Hebron; förty han regerade der i sju år och sex månader; men i Jerusalem regerade han i tre och tretio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Och desse äro honom födde i Jerusalem: Simea, Sobab, Nathan, Salomo, de fyra, af BathSua, Ammiels dotter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Dertill Jibehar, Elisama, Eliphelet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noga, Nepheg, Japhia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada, Eliphelet, de nio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Desse äro alle Davids barn, förutan de som frillobarn voro. Och Thamar var deras syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomos son var Rehabeam. Hansson var Abia. Hans son var Asa. Hans son var Josaphat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Hans son var Joram. Hans son var Ahasia. Hans son var Joas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Hans son var Amazia. Hans son var Asaria. Hans son var Jotham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Hans son var Ahas. Hans son var Hiskia. Hans son var Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Hans son var Amon. Hans son var Josia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Men Josia söner voro: Den förste, Johanan; den andre, Jojakim; den tredje, Zedekia; den fjerde, Sallum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Men Jojakims barn voro: Jechonia. Hans son var Zedekia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Jechonia barn, den fången vardt, voro: Sealthiel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Phedaja, Seneazar, Jekamia, Hosama, Nedabia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Phedaja barn voro: Serubbabel och Simei. Serubbabels barn voro: Mesullam och Hanania, och deras syster Selomith;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Dertill Hasuba, Ohel, Berechia, Hasadia, JusabHesed, de fem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hanania barn voro: Pelatia och Jesaia. Hans son var Rephaja. Hans son var Arnan. Hans son var Obadja. Hans son var Sechania.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Men Sechania barn voro: Semaja, Semaja barn voro: Hattus, Jigeal, Bariah, Nearia, Saphat, de sex.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearia barn voro: Eljoenai, Hiskia, Asrikam, de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoenai barn voro: Hodaja, Eljasib, Phelaja, Akkub, Johanan, Delaja, Anani, de sju.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Juda barn voro: Perez, Hezron, Charmi, Hur och Sobal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Men Reaja, Sobals son, födde Jahath. Jahath födde Ahumai och Lahad. Det äro de Zorgathiters slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Detta är den fadrens Ethams slägte: Jisreel, Jisma, Jidbas; och deras syster het Hazelelponi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Och Pnuel, Gedors fader, och Eser, Husa fader. Det äro Hurs barn, den första Ephrata sons, BethLehems faders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Men Ashur, Thekoa fader, hade två hustrur: Helea och Naara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Och Naara födde honom Ahusam, Hepher, Themeni, Ahastari. Det äro Naara barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Men Helea barn voro: Zereth, Jesohar och Ethnan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Men Coz födde Anub, och Hazobeba, och de Aharhels slägter, Harums sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Men Jabez var härligare än hans bröder; och hans moder kallade honom Jabez; ty hon sade: Jag hafver födt honom med bekymmer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Och Jabez åkallade Israels Gud, och sade: Om du välsignar mig, och förvidgar mina gränsor, och din hand blifver med mig, och så skaffar med det onda, att det mig intet bekymrar. Och Gud lät ske som han bad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Men Chelub, Suahs broder, födde Mehir, det är Esthons fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Men Esthon födde Bethrapha, Paseah och Thehinna, fadren till den staden Nahas. Det äro de män af Recha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kenas barn voro: Athniel och Seraja. Athniels barn voro: Hathath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Och Meonothai födde Ophra. Och Seraja födde Joab, en fader åt de timbermän i dalenom; ty de voro timbermän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Calebs barn, Jephunne sons, voro: Iru, Ela och Naam. Ela barn voro: Kenas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehaleleels barn voro: Siph, Sipha, Thiria och Asareel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Esra barn voro: Jether, Mered, Epher och Jalon, och Thahar med MirJam, Sammai, Jisbah Esthemoa fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Och hans hustru Judija födde Jered, Gedors fader, Heber, Socho fader, Jekuthiel, Sanoahs fader. Desse äro Bithias barn, Pharaos dotters, hvilka Mared tog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Den hustrunes Hodijas barn, Nahams systers, Kegila faders, voro: Hagarmi, och Esthemoa den Maachathiten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Simeons barn voro: Amnon, Rinnah, och Benhanan, Thilon. Jisei barn voro: Soheth och Bensoheth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Sela barn, Juda sons, voro: Er, Lecha fader, Laeda, Maresa fader, och de linväfvares slägter i Asbea hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Dertill Jokim, och de män af: Coseba, Joas, Saraph, hvilke husherrar voro i Moab, och bodde i Lahem; som de gamle säga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'De voro pottomakare, och bodde ibland planteringar och gårdar, när Konungenom i hans arbete, och kommo och blefvo der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeons barn voro: Nemuel, Jamin, Jarib, Serah, Saul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Hans son var Sallum. Hans son var Mibsam. Hans son var Misma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Misma barn voro: Hamuel. Hans son var Saccur. Hans son var Simei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei hade sexton söner, och sex döttrar; och hans bröder hade icke mång barn; och all deras slägt förökade sig icke så mycket, som Juda barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Men de bodde i BerSeba, Molada, HazarSual,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilha, Ezem, Tholad,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Bethuel, Horma, Ziklag,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'BethMarchaboth, HazarSusim, BethBirei, Saarim. Det voro deras städer, allt intill Konung David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Dertill deras byar, Etham, Ain, Rimmon, Thochen, Asan, de fem städerna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Och alle de byar, som voro omkring dessa städerna, allt intill Baal. Det är deras boning, och deras ätt ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Och Mesobab, Jamlech, Josa, Amazia son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jehu Josibia son, Seraja sons, Asiels sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaacoba, Jesohaja, Asaja, Adiel, Jisimiel, och Benaja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Sisa, Siphei son, Allons sons, Jedaja sons, Simri sons, Semaja sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Desse voro namnkunnige Förstar uti deras ätter, och i deras fäders hus; och delade sig ut, efter det de voro månge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Och de drogo bort till att fara till Gedor, intill öster på dalen, på det de skulle söka bet för deras får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Och de funno feta och goda bet, och ett vidt land, stilla och rikt; ty i förtiden bodde der de af Ham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Och de som nu vid namn beskrifne äro, kommo i Hiskia tid, Juda Konungs, och slogo deras hyddor och boningar, som der funne vordo, och gjorde dem tillspillo, allt intill denna dag; och bodde i deras stad; ty der var bet för får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Och gingo ut af dem af Simeons barnom, femhundrad män, intill Seirs berg, med deras öfverstar; Pelatia, Nearia, Rephaja, och Ussiel, Jisei barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Och slogo de återlefde af de Amalekiter, som undsluppne voro; och bodde der allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Rubens barn, första Israels sons, ty han var förste sonen; men derföre, att han sins fäders säng besmittade, vardt hans förstfödslorätt gifven Josephs barnom, Israels sons; och han vardt icke räknad till förstfödslona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Ty Juda, som mägtig var ibland sina bröder, honom vardt Förstadömet för honom gifvet, och Joseph förstfödslorätten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Så äro nu Rubens, första Israels sons, barn: Hanoch, Pallu, Hezron och Charmi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joels barn voro: Semaja. Hans son var Gog. Hans son var Simei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Hans son var Micha. Hans son var Reaja. Hans son var Baal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Hans son var Beera, hvilken ThiglathPilneser, Konungen i Assyrien, bortförde fången; han är en Förste ibland de Rubeniter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Men hans bröder i deras ätter, då de i deras börd räknade vordo, hade Jegiel och Zacharia för höfvitsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Och Bela, Asas son, Serna sons, Joels sons, han bodde i Aroer, och intill Nebo och BaalMeon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Och bodde emot öster intill man kommer till öknena vid den älfvena Phrath; förty deras boskap var mycken i Gileads land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Och i Sauls tid förde de örlig emot de Hagariter, så att de föllo genom desses hand, och bodde i deras hyddor, in mot alla den östra ängden Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gads barn bodde tvärtöfver ifrå dem, uti de landena Basan, allt intill Salcha:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel den främste, Sapham den andre, Jaenai och Saphat i Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Och deras bröder i deras fäders hus voro: Michael, Mesullam, Seba, Jorai, Jaecan, Sia och Eber, de sju.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Desse äro Abihails barn, Huri sons, Jaroahs sons, Gileads sons, Michaels sons, Jesisai sons, Jahdo sons, Bus sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, Abdiels son, Guni sons, var en öfverste uti deras fäders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Och bodde uti Gilead i Basan, och i dess döttrar, och i alla Sarons förstäder, allt intill dess ändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Desse vordo alle räknade i Jothams, Juda Konungs, och Jerobeams, Israels Konungs tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rubens barn, de Gaditers, och de halfva slägtenes Manasse, voro stridsamme män, som sköld och svärd föra och båga spänna kunde, och förfarne till att strida; de voro fyra och fyratio tusend, och sjuhundrad och sextio, som i här drogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Och då de stridde med de Hagariter, hulpo dem Jetur, Naphis och Nodab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Och gåfvo de Hagariter i deras händer, och allt det som med dem var; förty de ropade till Gud i stridene, och han bönhörde dem; ty de trodde till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Och de förde bort deras boskap, femtiotusend camelar, tuhundrad och femtio tusend får, tutusend åsnar, och hundradtusend menniskors själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Och der föllo månge såre; ty striden var af Gudi. Och de bodde i deras stad allt intill den tiden de fångne vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'De halfva slägtenes Manasse barn bodde i de landena, ifrå Basan allt intill BaalHermon och Senir, och det berget Hermon, och de voro månge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Och desse voro höfvitsmän till deras fäders hus: Epher, Jisei, Eliel, Asriel, Jeremia, Hodavia, Jahdiel; väldige, mägtige män, och namnkunnige höfvitsmän uti deras fäders husom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Och då de förtogo sig emot deras fäders Gud, och i horeri gingo efter de folks gudar der i landena, som Gud för dem förgjort hade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Uppväckte Israels Gud Phuls anda, Konungens i Assyrien, och ThiglathPilnesers anda, Konungens i Assyrien, och förde bort de Rubeniter, Gaditer och den halfva slägtena Manasse, och lät komma dem till Halah och Hober och Hara, och till den älfvena Gosan, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levi barn voro: Gersom, Kehath och Merari.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Kehaths barn voro: Amram, Jizear, Hebron och Ussiel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Amrams barn voro: Aaron, Mose och MirJam. Aarons barn voro: Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar födde Pinehas; Pinehas födde Abisua;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua födde Bukki; Bukki födde Ussi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ussi födde Serahia; Serahia födde Merajoth;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajoth födde Amaria; Amaria födde Ahitob;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ahitob födde Zadok; Zadok födde Ahimaaz;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Ahimaaz födde Asaria; Asaria födde Johanan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan födde Asaria, hvilken Prest var i husena, som Salomo byggde i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Asaria födde Amaria; Amaria födde Ahitob;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Ahitob födde Zadok; Zadok födde Sallum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sallum födde Hilkia; Hilkia födde Asaria;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Asaria födde Seraja; Seraja födde Jozadak;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Men Jozadak vardt med bortförd, då Herren lät bortföra Juda och Jerusalem fångna af NebucadNezar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Så äro nu Levi barn desse: Gersom, Kehath, Merari.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Gersoms barn heta alltså: Libni och Simei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Kehaths barn heta: Amram, Jizear, Hebron och Ussiel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Merari barn heta: Maheli och Musi. Det äro de Leviters ätter efter deras fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersoms son var Libni; hans son var Jahath; hans son var Simma;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Hans son var Joah; hans son var Iddo; hans son var Serah; hans son var Jeathrai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Men Kehaths son var Amminadab; hans son var Korah; hans son var As sir;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Hans son var Elkana; hans son var Ebjasaph; hans son var Assir;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Hans son var Tahath; hans son var Uriel; hans son var Ussia; hans son var Saul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Elkana barn voro: Amasai och Ahimoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Hans son var Elkana; hans son var ElkanaSophai; hans son var Nahath;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Hans son var Eliab; hans son var Jeroham; hans son var Elkana;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Hans son var Samuel; hans förstfödde var Vasni och Abija.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merari son var Maheli; hans son var Libni; hans son var Simei; hans son var Ussa:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Hans son var Simea; hans son var Haggija; hans son var Asaja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Desse äro de som David satte till att sjunga i Herrans hus, då arken hvilade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Och tjente för boningene och vittnesbördsens tabernakel med sjungande, allt intill Salomo byggde Herrans hus i Jerusalem; och stodo efter deras sätt i deras ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Och desse äro de som stodo, och deras barn: Utaf Kehaths barnom var Heman sångaren, Joels son, Samuels sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Elkana sons, Jerohams sons, Eliels sons, Thoahs sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Zuphs sons, Elkana sons, Mahaths sons, Amasai sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Elkana sons, Joels sons, Asaria sons, Zephania sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Thahaths sons, Assirs sons, Ebjasaphs sons, Korahs sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Jizears sons, Kehaths sons, Levi sons, Israels sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Och hans broder Assaph stod på hans högra sido. Och Assaph var Berechia son, Simea sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Michaels sons, Baaseja sons, Malchija sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Ethni sons, Serahs sons, Adaja sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Ethans sons, Simma sons, Simei sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Jahaths sons, Gersoms sons, Levi sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Men deras bröder, Merari barn, stodo på venstra sidone, nämliga Ethan, Kisi son, Abdi sons, Malluchs sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Hasabia sons, Amazia sons, Hilkia sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Amzi sons, Bani sons, Sam ers sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Maheli sons, Musi sons, Merari sons, Levi sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Men deras bröder, Leviterna, voro skickade till allehanda ämbete uti Guds hus boning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Men Aaron och hans söner voro i det ämbetet, som var, upptända på bränneoffrets altare, och på rökaltarena, och till alla sysslor uti det aldrahelgaste, och till att försona Israel, såsom Mose Guds tjenare budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Aarons barn äro desse: Eleazar hans son; hans son var Pinehas; hans son var Abisua;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Hans son var Bukki; hans son var Ussi; hans son var Serahia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Hans son var Merajoth; hans son var Amaria; hans son var Ahitob;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Hans son var Zadok; hans son var Ahimaaz.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Och detta är deras boning och säte uti deras gränsor, nämliga Aarons barnas af de Kehathiters ätt; ty lotten föll till dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Och de gåfvo dem Hebron i Juda land, och dess förstäder allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Men stadsens mark och dess byar gåfvo de Caleb, Jephunne son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Så gåfvo de nu Aarons barnom de fristäder, Hebron och Libna, och dess förstäder, Jattir och Esthemoa, och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilen och dess förstäder, Debir och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asan och dess förstäder, BethSemes och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Och af BenJamins släkte, Geba och dess förstäder, Alemeth och dess förstäder, Anathoth och dess förstäder; så att all städer i deras ätter voro tretton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Men dem androm Kehaths barnom deras ätter vordo, af den halfva Manasse slägte, genom lott gifne tio städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Gersoms barnom i deras ätter vordo i Isaschars slägte, och af Assers slägte, och af Naphthali slägte, och af Manasse slägt i Basan, tretton städer gifne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Merari barnom i deras ätter vordo genom lott gifne, af Rubens slägte, och af Gads slägte, och af Sebulons slägte, tolf städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Och Israels barn gåfvo också Leviterna städer, med deras förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Nämliga genom lott, af Juda barns slägte, och af Simeons barnas slägte, och BenJamins barnas slägte, de städer, som de vid namn före sade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Men Kehaths barnas ätt kommo städer till, af Ephraims slägtes gränsor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Så gåfvo de nu de andra Kehaths barnas ätt de fristäder, Sechem på Ephraims berg och dess förstäder, Geser och dess förstäder,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeam och dess förstäder, BethHoron och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalon och dess förstäder, GathRimmon och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Dertill, af den halfva slägtene Manasse, Aner och dess förstäder, Bileam och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Men Gersoms barnom gåfvo de, af de halfva Manasse slägtes ätt, Golan i Basa och dess förstäder, Astaroth och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Af Isaschars slägte, Kades och dess förstäder, Daberath och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoth och dess förstäder, Anem och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Af Assers slägte, Masal och dess förstäder, Abdon och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukok och dess förstäder, Rehob och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Af Naphthali slägte, Kedes i Galilea och dess förstäder, Hammon och dess förstäder, Kiriathaim och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Dem androm Merari barnom gåfvo de, af Sebulons slägte, Rimmono och dess förstäder, Thabor och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Och på hinsidon Jordan tvärsöfver Jericho österut vid Jordan: Af Ruben slägte, Bezer i öknene och dess förstäder Jahzah och dess förstäder,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemoth och dess förstäder, Mephaath och dess förstäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Af Gads slägte, Ramoth i Gilead och dess förstäder, Mahanaim och dess förstäder,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbon och dess förstäder, Jaeser och dess förstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Isaschars barn voro: Thola, Phua, Jasub och Simrom, de fyra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Thola barn voro: Ussi, Rephaja, Jeriel, Jahmai, Jibsam och Samuel, hufvud uti deras fäders hus af Thola, och väldige män i deras ätter, vid det talet i Davids tid tu och tjugu tusend och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Ussi barn voro: Jisraja. Jisraja barn voro: Michael, Obadja, Joel och Jissija, de fem; och voro alle höfvitsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Och med dem i deras ätter uti deras fäders hus voro väpnade härfolk till strid, sex och tretio tusend; ty de hade många hustrur och barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Och deras bröder i alla Isaschars ätter, väldige män, voro sju och åttatio tusend, och vordo alle räknade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'BenJamins barn voro: Bela, Becher och Jediael, de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Bela barn voro: Ezbon, Ussi, Ussiel, Jeremoth och Iri, de fem, höfvitsmän i fädernas hus, väldige män, och vordo räknade tu och tjugu tusend, och fyra och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bechers barn voro: Semira, Joas, Elieser, Eljoenai, Omri, Jeremoth, Abia, Anathot och Alameth, de voro alle Bechers barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Och vordo räknade i deras ätter efter höfvitsmännerna i deras fäders hus, väldige män, tjugutusend och tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaels barn voro: Bilhan. Bilhans barn voro: Jeus, BenJamin, Ehud, Chenaana, Sethan, Tharsis och Ahisahar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'De voro alle Jediaels barn, fädernas höfvitsmän, väldige män, sjuttontusend tuhundrad, som i här utdrogo till att strida.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Och Suppim och Huppim voro Irs barn; men Husim voro Achers barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naphthali barn voro: Jahziel, Guni, Jezer och Sallum af Bilha barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manasse barn äro desse: Esriel, hvilken hans frilla Aramia födde; men han födde Machir, Gileads fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Och Machir gaf Huppim och Suppim hustrur, och hans syster het Maacha; hans andre son het Zelaphehad; och Zelaphehad hade döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Och Maacha, Machirs hustru, födde en son, den kallade hon Peres: och hans broder het Seres; och hans söner voro: Ulam och Rakem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Men Ulams son var Bedan. Detta är Gileads barn, Machirs sons, Manasse sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Och hans syster Molecheth födde Ishod, Abieser och Mahela.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Och Semida hade dessa barnen: Ahjan, Sechem, Likhi och Aniam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Ephraims barn voro desse: Suthelah. Hans son var Bered; hans son var Thahath; hans son var Elada; hans son var Thahath;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Hans son var Sabad; hans son var Suthelah, Eser och Elad. Och de män i Gath, infödde i landena, dråpo dem, derföre att de nederdragne voro till att taga bort deras boskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Och deras fader Ephraim sörjde i långan tid, och hans bröder kommo till att hugsvala honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Och han besof sina hustru; hon vardt hafvandes, och födde en son, och han kallade hans namn Beria, derföre att illa tillgick i hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Hans dotter var Seera. Hon byggde nedra och öfra BethHoron och UssenSeera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Hans son var Repha; hans son var Reseph och Thelah; hans son var Thahan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Hans son var Laedan; hans son var Ammihud; hans son var Elisama;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Hans son var Nun; hans son var Josua.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Och deras ägor och boning var BethEl och dess döttrar, och österut af Naaran, och vesterut ifrå Geser och dess döttrar; Sechem och dess döttrar, allt intill Assa och dess döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Och intill Manasse barn, BethSean och dess döttrar; Thaanach och dess döttrar; Megiddo och dess döttrar; Dor och dess döttrar. Deruti bodde Josephs barn, Israels sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Assers barn voro desse: Jimna, Jisva, Jisvi, Beria, och Serah deras syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Beria barn voro: Heber och Malchiel, det är Birsaviths fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber födde Japhlet, Somer, Hotham, och Suah deras syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Japhlets barn voro: Pasach, Bimhal och Asvath; desse voro Japhlets barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Somers barn voro: Ahi, Rohgah, Jehubba och Aram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Och hans broders Helems barn voro: Sopha, Jimna, Seles och Amal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sopha barn voro: Suah, Harnepher, Sual, Beri, Jimra,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bszer, Hod, Samma, Silsa, Jithran och Beera.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jethers barn voro: Jephunne, Phispah och Ara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ulla barn voro: Arah, Haniel och Rizia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Desse voro alle Assers barn, höfvitsmän, i deras fäders hus utvalde, väldige män, och hufvud öfver Förstar, och vordo räknade i här till strids vid deras tal, sex och tjugu tusend män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'BenJamin födde Bela sin första son, Asbel den andra, Ahrah den tredje,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nohah den fjerde, Rapha den femte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Och Bela hade barn: Addar, Gera, Abihud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman, Ahoah,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephuphan och Huram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Desse äro Ehuds barn, som hufvud voro för de fäder, som bodde i Geba, och drogo bort till Manahath;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Nämliga Naaman, Ahia och Gera, den samme förde dem bort; och han födde Ussa och Ahihud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Och Saharaim födde i Moabs land, (då han hade låtit dem ifrå sig) af Husim och Baara sinom hustrum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Och han födde af Hodes sine hustru Jobab, Zibia, Mesa, Malcham,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeuz, Sachia och Mirma. Desse äro hans barn, hufvud för fäderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Af Husim födde han Abitob och Elpaal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaals barn voro: Eber, Misam och Samed; den samme byggde Ono och Lod, och dess döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Och Beria och Serna voro hufvud för fäderna ibland dem som bodde i Ajalon; de förjagade dem som bodde i Gath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Men hans broder, Sasak, Jeremoth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadia, Arad, Ader,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Jispa och Joha. Desse äro Beria barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Sebadia, Mesullam, Hiski, Heber,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia, Jobab. Desse äro Elpaals barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Sichri, Sabdi,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Zillethai, Eliel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja och Simrath. Desse äro Simri barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eber, Eliel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sichri, Hanan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hanania, Elam, Anthothia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jiphdeja och Pnuel. Desse äro Sasaks barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharia, Athalia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaresia, Elia och Sichri. Desse äro Jerohams barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Desse äro hufvud för fäderna i deras ätter; de bodde i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Men i Gibeon bodde fadren Gibeon; och hans hustru het Maacha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Och hans förste son var Abdon, Zur, Kis, Baal, Nadab,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahio och Secher.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Men Mikloth födde Simea; och de bodde tvärsemot deras bröder i Jerusalem med sinom brödrom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner födde Kis, Kis födde Saul, Saul födde Jonathan, MalchiSua, AbiNadab och Esbaal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonathans son var MeriBaal. MeriBaal födde Micha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Micha barn voro: Pithon, Melech, Thaerea och Ahas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahas födde Joadda. Joadda födde Alemeth, Asmaveth och Simri. Simri födde Moza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza födde Binea; hans son var Rapha; hans son var Eleasa; hans son var Azel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Men Azel hade sex söner. De heto: Asrikam, Bochru, Ismael, Searia, Obadja, Hanan. De äro alle Azels söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Eseks barn, hans broders, voro: Ullam hans förste son, Jeus den andre, Eliphelet den tredje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Men Ullams barn voro väldige män, och välbehändige med bågar och hade många söner och sonasöner, hundrade och femtio. De äro alle af BenJamins barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Och hele Israel vardt räknad, och si, de äro uppskrifne i Israels och Juda Konungars bok, och nu bortförde till Babel för sina missgerningars skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'De som tillförene bodde på sina ägor och städer, nämliga Israel, Prester, Leviter och de Nethinim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Men i Jerusalem bodde någre af Juda barn, någre af BenJamins barn, någre af Ephraims och Manasse barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Nämliga utaf Perez barn, Juda sons, var Athai, Ammihuds son, Omri sons, Imri sons, Bani sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Men af Siloni, Asaja förste sonen, och hans andre söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Af Serahs barn, Jeguel och deras bröder, sexhundrad och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Af BenJamins barn, Sallu, Mesullams son, Hodavia sons, Hassenua sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Och Jibneja, Jerohams son. Och Ela, Ussi son, Michri sons, och Mesullam, Sephatia son, Reguels sons, Jibneja sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Dertill deras bröder uti deras ätter, niohundrad och sex och femtio. Alle desse männerna voro höfvitsmän för fäderna uti deras fäders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Af Presterna, Jedaja, Jojarib, Jachin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Och Asaria, Hilkia son, Mesullams sons, Zadoks sons, Merajoths sons, Ahitobs sons, en Förste i Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Och Adaja, Jerohams son, Pashurs sons, Malchia sons; och Masai, Adiels son, Jahsera sons, Mesullams sons, Mesillemiths sons, Immers sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Dertill deras bröder höfvitsmän i deras fäders huse, tusende sjuhundrad och sextio starke män, till att beställa hvad ämbetet tillhörde i Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Men af Leviterna, af Merari barnom, Semaja, Hasubs son, Asrikams sons, Hasabia sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Och Bakbakkar, den timbermannen, och Galal; och Matthania, Micha son, Sichri sons, Assaphs sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Och Obadja, Semaja son, Galals sons, Jeduthuns sons, och Berechia, Asa son, Elkana sons, den som uti de Netophathiters byar bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Dörravaktarena voro: Sallum, Akkub, Talmon, Ahiman, med deras bröder; och Sallum, öfversten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Ty härtill hade vaktat för Konungsporten östantill Levi barn, i lägre,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sallum, Kore son, Ebiasaphs sons, Korans sons, och hans bröder utu hans faders hus, de Korhiter, vid ämbetets sysslo, att de vaktade vid tabernaklets dörrar, och deras fader i Herrans lägre, att de skulle vakta på ingången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Men Pinehas, Eleazars son, var Försten öfver dem, derföre att Herren hade tillförene varit med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharia, Meselemia son, var väktare vid vittnesbördsens tabernakels dörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Alle desse voro utvalde till väktare vid dörrarna, tuhundrad och tolf. De voro räknade i deras byar. Och David och Samuel Siaren stiktade dem genom deras tro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Att de och deras barn skulle taga vara på Herrans hus, nämliga på tabernaklets hus, att de det vakta skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'De samme dörravaktare voro ställde på fyra sidor, östan, vestan, norr, söder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Men deras bröder voro i sina byar, så att de ju inkommo på sjunde dagen, till att alltid vara när dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Förty Leviterna voro dessom fyra öfversta dörravaktaromen betrodde, och de voro öfver kistorna och skatten i Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Och blefvo de öfver nattena omkring Guds hus; ty dem hörde vakten till, att de skulle upplåta hvar morgon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Och somlige af dem voro öfver ämbetstygen; förty de båro dem tald ut och in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Och somlige af dem voro beställde öfver kärilen, och öfver all helig redskap; öfver semlomjöl, öfver vin, öfver oljo, öfver rökelse, öfver rökverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Men Presternas barn gjorde somlige rökverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Mattithia utaf Leviterna, dem första Sallums sone, den Korhitens, voro betrodda pannorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Utaf de Kehathiter deras bröder, voro till att bereda skådobröden, så att de tillredde dem på hvar Sabbathsdag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Desse äro de sångare, höfvitsmän ibland Leviternas fäder, öfver kistorna skickade; förty dag och natt voro de der öfver i sysslomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Desse äro höfvitsmän förfäderna ibland Leviterna uti deras ätter; och bodde i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'I Gibeon bodde Jegiel, Gibeons fader; hans hustru het Maacha;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Och hans förste son Abdon, Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahio, Zacharia, Mikloth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Men Mikloth födde Simeam; de bodde också omkring deras bröder i Jerusalem, ibland sina bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner födde Kis. Kis födde Saul. Saul födde Jonathan, MalchiSua, AbiNadab, Esbaal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonathans son var Meribaal; Meribaal födde Micha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Micha barn voro: Pithon, Melech och Thahrea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahas födde Jaera. Jaera födde Alemeth, Asmaveth och Simri. Simri födde Moza.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza födde Binea. Hans son var Rephaja, Hans son var Eleasa. Hans son var Azel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel hade sex söner; de heto: Asrikam, Bochru, Ismael, Searia, Obadja, Hanan. Desse äro Azels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'De Philisteer stridde emot Israel, och de af Israel flydde för de Philisteer, och de slagne föllo på Gilboa berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Och de Philisteer gåfvo sig hardt in på Saul och hans söner, och slogo Jonathan, AbiNadab och MalchiSua, Sauls söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Och striden vardt skarp emot Saul; och de bågaskyttar kommo inpå honom, så att han blef sår af skyttorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Då sade Saul till sin vapnedragare: Drag ditt svärd ut, och stick mig igenom dermed, att desse oomskorne icke komma och fara skamliga med mig. Men hans vapnedragare ville icke; ty han fruktade sig svårliga. Då tog Saul sitt svärd, och föll deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Som nu hans vapnedragare såg, att Saul var död, föll han ock på svärdet, och blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Alltså blef Saul död, och hans tre söner, och hans hela hus tillika.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Då nu de män af Israel, som i dalenom voro, sågo att de voro flydde, och att Saul och hans söner voro döde, öfvergåfvo de sina städer, och flydde; och de Philisteer kommo, och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Den andra morgonen kommo de Philisteer till att afkläda de slagna, och funno Saul och hans söner liggande på Gilboa berg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Och klädde honom af, och togo hans hufvud och hans vapen, och sände uti de Philisteers land allt omkring, och läto förkunnat för deras af gudar och folkena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Och lade hans vapen i deras guds hus; och hans hufvud slogo de på Dagons hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Då nu alle de i Jabes i Gilead hörde allt det de Philisteer Saul gjort hade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Reste de upp alle stridsamme män, och togo Sauls lekamen, och hans söners, och förde dem till Jabes, och begrofvo deras ben under den eken i Jabes; och fastade i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Alltså blef Saul död i sine missgerning, som han emot Herran gjort hade, emot Herrans ord, det han icke höll; också derföre, att han frågade spåqvinnona,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Och icke frågade Herran; derföre drap han honom, och vände riket till David, Isai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Och hele Israel samlade sig: till David i Hebron, och sade: Si, vi äre ditt ben och ditt kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Och tillförene, medan Saul var Konung, förde du Israel ut och in; så hafver ock Herren din Gud sagt till dig: Du skall föda mitt folk Israel, och du skall vara en Förste öfver mitt folk Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Kommo också alle Israels äldste till Konungen i Hebron. Och David gjorde ett förbund med dem i Hebron för Herranom. Och de smorde David till Konung öfver Israel, efter Herrans ord, genom Samuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Och David drog åstad, och hele Israel, till Jerusalem, det är Jebus; ty de Jebuseer bodde i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Och de borgare i Jebus sade till David: Du skall icke komma härin. Men David vann den borgen Zion, det är Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Och David sade: Den som de Jebuseer först slår, han skall vara hufvud och öfverste. Då steg Joab, ZeruJa son, först upp, och vardt höfvitsmän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Och David bodde på borgene; deraf kallar man henne Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Och han byggde staden omkring, ifrå Millo och sedan allt omkring; och Joab lät lefva dem som qvare voro i stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Och David hade framgång, och kom sig före; och Herren Zebaoth var med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Desse äro de öfverste ibland Davids väldiga, de der manliga höllo med honom i hans rike, när hela Israel, så att man gjorde honom till Konung, efter Herrans ord, öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Och detta är talet på Davids väldiga män: Jasabeam, Hachmoni son, den ypperste ibland tretio; han hof sin spets upp, och slog trehundrad i en gång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Näst honom var Eleazar, Dodo son, den Ahohiten, och han var ibland de tre väldiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Denne var med David, då de talade hädelse, och de Philisteer sig der församlat hade till strid; och var ett stycke åker fullt med bjugg, och folket flydde för de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Och de trädde midt uppå åkerstycket, och undsatte det, och slogo de Philisteer; och Herren gaf en stor salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Och de tre utaf de yppersta tretio drogo neder till bergshällen till David, i den kulona Adullam; men de Philisteers lägre var i Rephaims dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Och David var i borgene; och de Philisteers folk var på den tid i BethLehem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Och David fick lusta, och sade: Ho vill gifva mig dricka af det vattnet i den brunnen i BethLehem, under portenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Då slogo desse tre genom de Philisteers lägre, och hemtade vatten utu brunnen i BethLehem, under portenom, och båro till David. Men han ville icke drickat, utan utgöt det Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Och sade: Det låte Gud vara långt ifrå mig, att jag detta göra skulle, och dricka dessa mäns blod i deras lifsfara; förty de hafva det hemtat med sins lifs fara; derföre ville han icke drickat. Det gjorde de tre hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai, Joabs broder, han var den ypperste ibland tre, och han hof sin spets upp, och slog trehundrad, och han var beprisad ibland tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Och han den tredje härligare än de två, och var deras öfverste; men till de tre kom han icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Jojada son, IsHails sons, den mycket bedrifvit hade, af Kabzeel, han slog tu de Moabiters lejon; och gick neder, och slog ett lejon midt i brunnenom i snötiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Han slog ock en Egyptisk man; han var fem alnar lång, och hade en spets i handene såsom ett väfträ; men han gick ned till honom med en staf, och tog honom spetsen utu handene, och drap honom med hans egen spets.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Det gjorde Benaja, Jojada son, och vardt beprisad ibland tre hjeltar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Och var den härligaste ibland tretio; men till de tre kom han icke; honom gjorde David till sitt hemliga råd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'De stridsamme hjeltar äro desse: Asahel, Joabs broder, Elhanan, Dodo son af BethLehem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth den Haroriten, Helez den Peloniten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, Ikkes son, den Thekoiten, Abieser den Anthothiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbechai den Husathiten, Ilai den Ahohiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai den Netophathiten, Heled, Baana son, den Netophathiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithai, Ribai son, af Gibea, BenJamins barnas, Benaja den Pirgathoniten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai af de bäcker Gaas, Abiel den Arbathiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmaveth den Baharumiten, Eliahba den Saalboniten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Hasems barn den Gisonitens, Jonathan, Sage son, den Hararitens,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, Sachars son, den Hararitens, Eliphal, Urs son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher den Mecherathiten, Ahija den Peloniten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro den Carin eliten, Naarai, Esbai son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, Nathans broder, Mibhar, Hagri son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek den Ammoniten, Naharai den Berothiten, Joabs vapnedragare, ZeruJa sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira den Jithriten, Gareb den Jithriten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria den Hetheen, Sabad, Ahelai son,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, Sisa son, den Rubeniten, en höfvitsmän för de Rubeniter, och tretio voro under honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, Maacha son, Josaphat den Mithniten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ussija den Asthrathiten, Sama och Jegiel, Hothams söner, den Aroeritens,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, Simri son, Joha hans broder, den Thiziten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel den Mahaviten, Jeribai och Josavja, Elnaams söner, Jithma den Moabiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed, och Jasiel af Mezobaja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Och kommo desse till David i Ziklag, då han ännu flyktig var för Saul, Kis son; och de voro också ibland de hjeltar, som hulpo till strid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Och voro skickeliga med bågar, på båda händer, till stenar, pilar och bågar, af Sauls bröder, de af BenJamin voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Den ypperste Ahieser, och Joas, Semaa barn, den Gibeathitens, Jesiel, och Paleth, Asmaveths barn, Beracha, och Jehu den Anthothiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jismaja den Gibeoniten, väldig ibland tretio, och öfver tretio, Jeremia, Jahasiel, Johanan, Josabad den Gederathiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elusai, Jerimoth, Bealia, Semaria, Sephatia den Hariphiten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jissija, Asareel, Joeser, Jasabeam, de Korhiter,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela, och Sebadia, Jerohams barn af Gedor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Af de Gaditer söndrade sig ut till David, på borgene i öknene, starke hjeltar och krigsmän, som sköld och spjut förde, och deras ansigte såsom lejons, och raske såsom rår uppå bergen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Den förste, Eser; den andre, Obadja; den tredje, Eliab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Den fjerde, Mismanna; den femte, Jeremia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Den sjette, Atthai; den sjunde, Eliel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Den åttonde, Johanan; den nionde, Elsabad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Den tionde, Jeremia; den ellofte, Machbannai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Desse voro af Gads barnom, höfvitsmän i härenom, den ringaste öfver hundrade, och den ypperste öfver tusende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Desse äro de, som öfver Jordan gingo i första månadenom, då han full var till båda bräddar, så att alle dalar jemne voro både östan och vestan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Kommo ock desslikes af BenJamins barn och Juda till Davids borg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Och David gick ut till dem, och svarade, och sade till dem: Om I kommen med frid till mig, och till att hjelpa mig, så skall mitt hjerta vara med eder; kommen I ock på arga list att vara mig emot, der dock ingen missgerning i mig är, så se våra fäders Gud dertill, och straffe det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Så iklädde Guds Ande Amasai höfvitsmannen öfver tretio, och han sade: Dine äre vi, David, och med dig hålle vi, du Isai son; frid, frid vare med dig; frid vare med dina hjelpare; förty din Gud hjelper dig. Då tog David dem till sig, och satte dem till höfvitsmän öfver krigsfolket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Och af Manasse föllo till David, då han kom med de Philisteer emot Saul till strid, och halp dem dock intet; ty de Philisteers Förstar gingo till råds, och viste honom bort ifrå sig, och sade: Om han fölle till sin herra Saul, så måtte det gälla vår hals.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Då han nu igen drog till Ziklag, föllo till honom af Manasse, Adna, Josabad, Jediael, Michael, Josabad, Elihu, Zillethai, höfvitsmän öfver tusende i Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Och de hulpo David emot krigsfolket; ty de voro alle mägtige hjeltar, och vordo höfvitsmän öfver hären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Och kommo hvar dag någre till David, honom till hjelp, tilldess det vardt en stor här, såsom en Guds här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Och detta är talet på de höfvitsmän, som utrustade kommo till David i Hebron, till att vända Sauls rike till honom efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Juda barn, som sköld och spjut båro, voro sextusend och åttahundrad, väl utredde till strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Simeons barn, mägtige hjeltar till strid, sjutusend och hundrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Levi barn, fyratusend och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Och Jojada, den Försten ibland dem af Aaron, med tretusend och sjuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Zadok den unge mannen, en mägtig hjelte, med sins faders hus, två och tjugu öfverste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'BenJamins barn, Sauls bröder, tretusend; ty allt intill den tiden höllo ännu månge med Sauls hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Ephraims barn, tjugutusend och åttahundrad, mägtige hjeltar och namnkunnige män uti deras faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Utaf den halfva slägt ene Manasse adertontusend, som vid namn nämnde vordo, att de skulle komma och göra David till Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Utaf Isaschars barn, de förståndige voro, då tiden så krafde, att man visste hvad Israel göra skulle, tuhundrad höfvitsmän; och alle deras bröder följde deras ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Utaf Sebulon, de som i här drogo till strid, väpnade med allahanda vapen till strid, femtiotusend, endrägtige till att skicka sig i ordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Utaf Naphthali tusend höfvitsmän, och med dem de som sköld och spjut förde, sju och tretio tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Utaf Dan väpnade till strid, åtta och tjugu tusend sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Utaf Asser, de som i här drogo väpnade till strid, fyratiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Ifrå hinsidon Jordan utaf de Rubeniter, Gaditer och den halfva Manasse slägten, med allahanda vapen till strid, hundrade och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Alle desse krigsmän, väl skickade till strid, kommo af allo hjerta till Hebron, att göra David till Konung öfver hela Israel; och var alla de andras af Israel ett hjerta, att man skulle göra David till Konung;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Och voro der när David i tre dagar, åto och drucko; förty deras bröder hade tillredt för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Och de som näst omkring dem voro, allt intill Isaschar, Sebulon och Naphthali, de förde bröd på åsnar, camelar, mular och oxar, till att äta; mjöl, fikon, russin, vin, oljo, oxar och får, allt fullt; ty en fröjd var i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Och David höll ett råd med de höfvitsmän öfver tusende, och öfver hundrade, och med alla Förstar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Och sade till hela Israels menighet: Täckes eder, och är det af Herranom vårom Gud, så låt oss allestäds utsända till de andra våra bröder i all Israels land, och till Presterna och Leviterna i städerna, der de förstäder hafva, att de varda till oss församlade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Och låt oss hem ta till oss igen vår Guds ark; ty i Sauls tid frågade vi intet efter honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Då sade hela menigheten, att man skulle så göra; ty detta täcktes allo folkena väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Alltså församlade David hela Israel allt ifrå Sihor vid Egypten, intilldess man kommer till Hamath, till att hemta Guds ark ifrå KiriathJearim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Och David drog upp med hela Israel till Baalath, det är KiriathJearim, som i Juda ligger, att han skulle dädan uppföra Herrans Guds ark, den på Cherubim sitter, der Namnet åkalladt varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Och de läto föra Guds ark uppå en ny vagn, utur AbiNadabs hus. Men Ussa och Ahio drefvo vagnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Och David med hela Israel spelade framför Gudi med all magt, med sånger, med harpor, med psaltare, med trummor, med cymbaler, och med basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Som de nu kommo uppå den platsen Chidon, räckte Ussa ut sina hand, till att hålla arken; förty oxarne gingo afsides.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Då förgrymmade sig Herrans vrede öfver Ussa, och slog honom, derföre att han hade räckt sina hand ut på arken, så att han der död blef för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Då vardt David bedröfvad, att Herren hade sönderrifvit Ussa, och kallade det rummet PerezUssa, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Och David fruktade sig för Gud den dagen, och sade: Huru skall jag hafva Guds ark in till mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Derföre lät han icke föra in till sig Guds ark uti Davids stad, utan förde honom in uti ObedEdoms hus, den Gitthitens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Alltså blef Guds ark när ObedEdom i hans huse i tre månader. Och Herren välsignade ObedEdoms hus, och all det han hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Och Hiram, Konungen i Tyro, sände båd till David, och cedreträ, murmästare och timbermän, att de skulle bygga honom ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Och David förmärkte, att Herren hade stadfäst honom till Konung öfver Israel; ty hans rike steg upp för hans folks Israels skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Och David tog ännu flera hustrur i Jerusalem, och födde ännu flera söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Och de honom födde vordo i Jerusalem, heto alltså: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua, Elephelet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga, Nepheg, Japhia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, BelJada, Eliphelet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Och då de Philisteer hörde, att David var smord till Konung öfver hela Israel, drogo de alle upp till att söka David. Då David det hörde, drog han ut emot dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Och de Philisteer kommo, och lade sig neder i Rephaims dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Men David frågade Gud, och sade: Skall jag draga upp emot de Philisteer, och vill du gifva dem i mina hand? Herren sade till honom: Drag upp, jag hafver gifvit dem i dina händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Och då de drogo upp till BaalPerazim, slog David dem der. Och David sade: Gud hafver förskingrat mina fiendar genom mina hand, såsom vattnet förskingras. Deraf kallade de det rummet BaalPerazim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Och de läto der deras gudar, hvilka David böd uppbränna i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Men de Philisteer gjorde åter redo, och lade sig neder i dalenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Och David frågade åter Gud. Och Gud sade till honom: Du skall icke draga upp efter dem; utan böj ifrå dem, att du må komma emot dem in mot päronaträn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'När du då hörer ett ruskande ofvan i päronaträn gångandes, så far ut till stridena; ty Gud är der utdragen för dig, till att slå de Philisteers här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Och David gjorde såsom Gud honom budit hade. Och de slogo de Philisteers här, allt ifrå Gibeon intill Gaser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Och Davids namn gick ut i all land. Och Herren lät hans räddhåga komma öfver alla Hedningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Och han byggde sig hus uti Davids stad, och tillredde ett rum till Guds ark, och gjorde ett tabernakel öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'På den tiden sade David: Guds ark bör icke bäras, utan af de Leviter; ty dem hafver Herren utvalt, att de skola bära Guds ark, och tjena honom evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Derföre församlade David hela Israel till Jerusalem, att de skulle bära Herrans ark upp i det rum, som han dertill beredt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Och David lät komma tillhopa Aarons barn, och Leviterna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Utaf Kehats barn, Uriel, den öfversten, med hans bröder, tjugu och hundrade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Utaf Merari barn, Asaja, den öfversten, med hans bröder, tjugu och tuhundrade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Utaf Gersoms barn, Joel, den öfversten, med hans bröder, tretio och hundrade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Utaf Elisaphans barn, Semaja, den öfversten, med hans bröder, tuhundrade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Utaf Hebrons barn, Eliel, den öfversten, med hans bröder, åttatio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Utaf Ussiels barn, Amminadab, den öfversten, med hans bröder, tolf och hundrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Och David kallade Zadok och AbJathar, Presterna och Leviterna, nämliga Uriel, Asaja, Joel, Semaja, Eliel, Amminadab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Och sade till dem: I ären hufvuden för fäderna ibland de Leviter; så helger eder nu och edra bröder, att I mågen uppbära Herrans Israels Guds ark dit, der jag honom tillredt hafver:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Ty tillförene, när I icke voren tillstädes, gjorde Herren vår Gud en refvo ibland oss, derföre att vi icke sökte honom, såsom det borde sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Alltså helgade Presterna sig och Leviterna, att de skulle uppbära Herrans Israels Guds ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Och Levi barn båro Guds ark på sina axlar, med stängerna dervid, såsom Mose budit hade efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Och David sade till de öfverstar för de Leviter, att de skulle sätta sina bröder till sångare, med strängaspel, med psaltare, harpor och klingande cymbaler, så att de högt söngo och med fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Då beställde de Leviter Hem an, Joels son, och utaf hans bröder Assaph, Berechia son, och utaf Merari barn deras bröder, Ethan, Kusaja son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Och med dem deras bröder af det andra skiftet, nämliga Zacharia, Ben, Jaesiel, Semiramoth, Jehiel, Unni, Eliab, Benaja, Maaseja, Mattithia, Elipheleja, Mikneja, ObedEdom, Jegiel, dörravaktarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Ty Heman, Assaph och Ethan voro sångare med kopparcymbaler, att klinga högt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Men Zacharia, Asiel, Semiramoth, Jehiel, Unni, Eliab, Maaseja och Benaja, med psaltare, till att sjunga efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Men Mattithia, Elipheleja, Mikneja, ObedEdom, Jegiel och Asasia, med harpor af åtta stränger, till att sjunga för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Men Chenanja, Leviternas öfverste sångmästare, att han skulle undervisa dem om sången, ty han var förståndig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Och Berechia och Elkana voro dörravaktare om arken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Men Sechania, Josaphat, Nethaneel, Amasai, Zacharia, Benaja, Elieser, Presterna, blåste med trummeter för Guds ark. Och ObedEdom och Jehia voro dörravaktare om arken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Alltså gingo David och de äldste i Israel, och de öfverste öfver tusende upp, till att hem ta Herrans förbunds ark utur ObedEdoms hus med fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Och medan Gud halp Leviterna, som båro Herrans förbunds ark, offrade man sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Och David hade en linnan kjortel uppå; så ock alle Leviter, som arken båro, och sångarena och Chenanja sångmästaren, med sångarena; hade också David en linnan lifkjortel uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Alltså båro hele Israel Herrans förbunds ark upp med fröjd, basuner, trummeter och klingande cymbaler, med psaltare och harpor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Då nu Herrans förbunds ark kom uti Davids stad, såg Michal, Sauls dotter, ut genom fenstret; och då hon fick se Konung David springa och spela, föraktade hon honom i sitt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Då de båro Guds ark in, satte de honom uti tabernaklet, som David honom beredt hade; och offrade bränneoffer och tackoffer för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Och då David hade fullkomnat bränneoffren och tackoffren, välsignade han folket i Herrans Namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Och utskifte hvarjom och enom i Israel, både man och qvinno, ett stycke bröd, och kött, och ett mätt vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Och han satte inför Herrans ark några Leviter till tjenare, att de skulle prisa, tacka och lofva Herran Israels Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Nämliga Assaph den första, Zacharia den andra, Jegiel, Semiramoth, Jehiel, Mattithia, Eliab, Benaja, ObedEdom; och Jegiel med psaltare och harpor; men Assaph med klingande cymbaler;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Och Benaja och Jahasiel, Presterna, med trummeter, alltid för Guds förbunds ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'På den tiden beställde David i förstone att tacka Herranom, genom Assaph och hans bröder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Tacker Herranom, prediker hans Namn; förkunner ibland folken hans verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Sjunger honom, speler, och taler om all hans under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Lofver hans helga Namn; deras hjerta fröjde sig, som söka Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Söker efter Herran, och efter hans magt; söker hans ansigte alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Tänker på hans under, som han gjort hafver; på hans under, och hans ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'I Israels hans tjenares säd, I Jacobs hans utkorades barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Han är Herren vår Gud, han dömer i allo verldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Kommer ihåg hans förbund evinnerliga; hvad han utlofvat hafver i tusende slägter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Hvilket han gjort hafver med Abraham, och hans ed med Isaac.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Och han satte det Jacob till en rätt, och Israel till ett evigt förbund,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Och sade: Jag skall gifva dig Canaans land, edar arfvedels lott.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Då de få och ringa voro, och främlingar derinne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Och de drogo ifrå det ena folket till det andra, och utur ett rike bort till ett annat folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Han lät ingen göra dem skada; och för deras skull straffade han Konungar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Kommer icke vid mina smorda; och görer intet ondt mina Propheter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Sjunger Herranom all land; förkunner dageliga hans salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Förtäljer ibland Hedningarna hans härlighet; och hans under ibland folken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Ty Herren är stor, och fast loflig; och underlig öfver alla gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Förty alle Hedningars gudar äro afgudar; men Herren hafver gjort himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Det står härliga och kosteliga till för honom, och går krafteliga och gladeliga till i hans rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Bärer fram Herranom, I folk; bärer fram Herranom äro och magt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Bärer fram Herrans Namne äro; bärer fram skänker, och kommer för honom, och tillbeder Herran i heligo prydelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'All verlden frukte för honom; han hafver befäst jordena, så att hon intet röres.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Fröjde sig himmelen, och jorden vare glad; och man må säga ibland Hedningarna, att Herren är rådandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Hafvet dåne, och hvad deruti är; och marken vare glad, och hvad deruppå är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Fröjde sig all trä i skogen för Herranom: ty han kommer till att döma jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Tacker Herranom, ty han är god, och hans barmhertighet varar evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Och säger: Hjelp oss, Gud vår Frälsare, och församla oss, och hjelp oss ifrå Hedningarna, att vi måge tacka dino helgo Namne, och lofsäga dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Lofvad vare Herren Israels Gud, ifrån evighet till evighet; och allt folket säge Amen, och lofve Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Alltså lät han der för Herrans förbunds ark Assaph och hans bröder, till att tjena inför arken alltid, och hvar dag i sitt dagsverk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Men ObedEdom och hans bröder, åtta och sextio; och ObedEdom, Jeduthuns son, och Hosa till dörravaktare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Och Zadok Presten, och hans bröder Presterna, lät han inför Herrans tabernakel, på höjdene i Gibeon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Att de dageliga skulle göra Herranom bränneoffer, uppå bränneoffrens altare, om morgon och afton, såsom skrifvet står uti Herrans lag, som han Israel budit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Och med dem Heman och Jeduthun, och de andra utvalda, som vid namn benämnde voro, till att tacka Herranom, att hans barmhertighet varar evinnerliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Och med dem Heman och Jeduthun, med trummeter och cymbaler, till att klinga, och med Guds strängaspel. Men Jeduthuns söner gjorde han till dörravaktare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Alltså drog allt folket sin väg, hvar och en i sitt hus. Drog också David bort till att välsigna sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Det begaf sig, då David bodde i sitt hus, sade han till Propheten Nathan: Si, jag bor uti cedrehus; och Herrans förbunds ark under tapeter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Nathan sade till David: Allt det i ditt hjerta är, det gör; ty Gud är med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Men i samma natt ene kom Guds ord till Nathan, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Gack och säg minom tjenare David: Detta säger Herren: Du skall icke bygga mig ett hus till boning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Förty jag hafver icke bott uti något hus, ifrå den dag, då jag Israels barn utförde, allt intill denna dagen; utan jag hafver varit der tabernaklet varit hafver, och boningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Ehvar jag vandrade i hela Israel, hafver jag ock någor tid talat till någon domare i Israel, den jag budit hafver, att föda mitt folk, och sagt: Hvi byggen I icke mig ett cedrehus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Så säg nu alltså till min tjenare David: Detta säger Herren Zebaoth: Jag hafver tagit dig utaf markene, der du följde fåren, att du skulle vara en Förste öfver mitt folk Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Och hafver varit med dig, ehvart du for, och hafver utrotat dina fiendar för dig; och hafver gjort dig ett namn, såsom de store på jordene namn hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Men jag skall sätta mino folke Israel ett rum, och skall plantera det, så att det skall der bo, och icke mer rördt varda; och arghetens barn skola icke mer qvälja det, såsom tillförene,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Och på den tiden, då jag böd domarena öfver mitt folk Israel. Och jag skall undertrycka alla dina fiendar; och förkunnar dig, att Herren vill bygga dig ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'När nu dine dagar ute äro, att du går till dina fäder, så skall jag uppväcka dina säd efter dig, den en af dina söner vara skall, honom vill jag bereda ett rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Han skall bygga mig ett hus, och jag vill stadfästa hans stol till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Jag skall vara hans fader, och han skall vara min son; och jag skall icke vända mina barmhertighet ifrå honom, såsom jag vände henne ifrå honom, som för dig var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Utan jag skall sätta honom i mitt hus, och uti mitt rike evinnerliga, så att hans stol skall blifva beständig i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Och då Nathan efter all desso ord och syn talat hade med David,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Kom Konung David, och blef inför Herranom, och sade: Ho är jag, Herre Gud? Och hvad är mitt hus, att du hafver låtit mig komma härtill?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Och dig hafver ändå icke tyckt det nog vara, Gud; utan du hafver ock öfver dins tjenares hus ännu talat om tillkommande ting i framtiden, och hafver sett till mig, Herre Gud, ofvanefter, såsom en menniska den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Hvad skall David mer säga till dig, att du skulle ära din tjenare? Du känner din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herre, för din tjenares skull, efter ditt hjerta hafver du all sådana stor ting gjort, att du skulle all storhet kunnoga göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herre, ingen är din like, och ingen Gud är utan du, af hvilkom vi med vår öron hört hafve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Och hvar är något folk på jordene, såsom ditt folk Israel, dit en Gud gången är, till att förlossa sig ett folk, och göra sig sjelfvom ett Namn af stor och förskräckelig ting, till att utdrifva Hedningar för dino folke, som du utur Egypten förlossat hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Och hafver gjort ditt folk Israel dig till folk evinnerliga, och du, Herre, äst deras Gud vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nu, Herre, det ord, som du talat hafver öfver din tjenare, och öfver hans hus, varde sant i evig tid, och gör såsom du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Och ditt Namn varde sant och stort i evig tid, att man säga må: Herren Zebaoth Israels Gud är Gud i Israel; och dins tjenares Davids hus vare beständigt för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Ty du, min Gud, hafver öppnat din tjenares öra, att du vill bygga honom ett hus; derföre hafver din tjenare funnit, att han inför dig beder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nu, Herre, du äst Gud, och du hafver sådana god ting sagt till din tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Tag nu till att välsigna dins tjenares hus, att det blifver evinnerliga för dig; ty hvad du, Herre, välsignar, det är välsignadt evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Derefter slog David de Philisteer, och undertryckte dem, och tog Gath och dess döttrar utu de Philisteers hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Slog han ock de Moabiter, så att de Moabiter vordo David underdånige, och förde honom skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Han slog ock HadarEser, Konungen i Zoba, uti Hamath, då han dit drog, till att uppresa sitt tecken vid den älfvena Phrath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Och David vann af honom tusende vagnar, sjutusend resenärar, och tjugutusend män till fots och David hasade alla vagnhästarna, och behöll hundrade vagnar qvara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Och de Syrer af Damasco kommo HadarEser, Konungenom i Zoba, till hjelp; men David slog de samma Syrer, tu och tjugu tusend män;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Och lade folk till Damascon i Syrien, så att de Syrer vordo David underdånige, och förde honom skänker; ty Herren halp David, ehvart han for.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Och David tog de gyldene sköldar, som HadarEsers tjenare hade, och förde dem till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Tog också David utu HadarEsers städer, Tibhath och Chun, ganska mycken koppar, af hvilkom Salomo kopparhafvet, och stoderna och kopparkärilen gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Och då Thou, Konungen i Hamath, hörde, att David hade slagit alla HadarEsers magt, Konungens i Zoba;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Sände han sin son Hadoram till Konung David, och lät helsa och välsigna honom, att han med HadarEser stridt, och honom slagit hade; ty Thou hade örlig med HadarEser. Och all gyldene, silfver, och kopparkärile,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Dem helgade Konung David Herranom, med det silfver och guld, som han tagit hade ifrå Hedningarna, nämliga ifrå de Edomeer, Moabiter, Ammoniter, Philisteer och Amalekiter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Och Abisai, ZeruJa son, slog de Edomeer i saltdalenom, adertontusend;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Och lade folk i Edomeen; så att alle Edomeer voro David underdånige; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Alltså regerade David öfver hela Israel, och höll rätt och rättvisa allo sino folke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, ZeruJa son, var öfver hären; Jojaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadok, Ahitobs son, och AbiMelech, AbJathars son, voro Prester; Sausa var skrifvare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, Jojada son, var öfver Crethi och Plethi; och de förste Davids söner voro Konungenom vid handen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Så begaf sig derefter, att Nahas, Ammons barnas Konung, blef död, och hans son vardt Konung i hans stad,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Då tänkte David: Jag vill göra barmhertighet på Hanun, Nahas son; ty hans fader hafver gjort barmhertighet med mig. Och han sände dit båd, till att hugsvala honom efter hans fader. Och då Davids tjenare kommo uti Ammons barnas land, till Hanun, att hugsvala honom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Sade de Förstar för Ammons barn till Hanun: Menar du, att David ärar din fader för din ögon, att han sänder hugsvalare till dig? Ja, hans tjenare äro komne till dig, till att utfråga, bespana och bespeja landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Då tog Hanun Davids tjenare, och rakade dem, och skar deras kläder half bort allt intill länderna, och lät gå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Och de gingo sin väg, och bådade det David med några män. Han sände emot dem; förty männerna voro svårliga beskämde, och Konungen sade: Blifver i Jericho, tilldess edart skägg växer, sedan kommer då igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Då Ammons barn sågo, att de illa luktade för David, sände de bort, både Hanun och Ammons barn, tusende centener silfver, till att besolda sig vagnar och resenärar utu Mesopotamien, utu Syrien Maacha, och utu Zoba;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Och besoldade tu och tretio tusend vagnar, och Konungen i Maacha med hans folk. De kommo och lägrade sig för Medba. Och Ammons barn församlade sig desslikes utu sina städer, och kommo till strids.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Då David det hörde, sände han Joab dit, med hela de hjeltars här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Och Ammons barn voro utdragne, och skickade sig till strid för stadsporten; men Konungarna, som komne voro, höllo besynnerliga i markene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Då nu Joab såg, att både för honom och bak honom var strid emot honom, utvalde han af alla unga män i Israel, och skickade sig emot de Syrer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Det andra folket fick han under Abisai sin broders hand, att de skulle draga emot Ammons barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Och sade: Om de Syrer varda mig för starke, så kom mig till hjelp; om Ammons barn varda dig för starke, så vill jag komma dig till hjelp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Var tröst, och låt oss trösteliga handla för vårt folk, och för vår Guds städer. Herren göre hvad honom täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Och Joab drog fram med det folk, som med honom var, till att strida emot de Syrer; och de flydde för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Då nu Ammons barn sågo, att de Syrer flydde, flydde de ock för Abisai hans broder, och drogo in i staden; men Joab drog till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Som de Syrer sågo, att de för Israel slagne voro, sände de ut båd, och läto utkomma de Syrer på hinsidon älfven; och Sophach, HadarEsers härhöfvitsman, drog för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Då det blef sagdt David, församlade han hela Israel, och drog öfver Jordan; och då han kom till dem, skickade han sig emot dem. Och David skickade sig emot de Syrer till strid, och de stridde med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Men de Syrer flydde för Israel; och David slog af de Syrer sjutusend vagnar, och fyratiotusend män till fot; dertill drap han Sophach härhöfvitsmannen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Då HadarEsers tjenare sågo, att de voro slagne för Israel, gjorde de frid med David och hans tjenare. Och de Syrer ville icke mer hjelpa Ammons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Och då året omgånget var, på den tid som Konungar utdraga, utförde Joab hären, och förderfvade Ammons barnas land; kom och belade Rabba; men David blef i Jerusalem. Och Joab slog Rabba, och bröt det neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Och David tog deras Konungs krono af hans hufvud, och fann deruti en centener gulds vigt och ädla stenar; och hon vardt satt på Davids hufvud; förde han ock ganska mycket rof utu staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Men folket derinne förde han ut, och lät sönderdela dem med sågar och jernhackor och kilar; alltså gjorde David alla Ammons barnas städer. Och David drog med folkena till Jerusalem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Derefter hof sig en strid upp i Gaser med de Philisteer. På den tiden slog Sibbechai, den Husathiten, Sippai, den utaf Rephaims barnom var, och undertryckte honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Och det hof sig ännu en strid upp med de Philisteer. Då slog Elhanan, Jairs son, Lahmi, Goliaths broder den Gitthiten, hvilkens spjutskaft var såsom ett väfträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Åter vardt en strid i Gath. Der var en stor man, han hade sex finger och sex tår, det gör fyra och tjugu. Han var också födder af Rapha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Han bespottade Israel; men Jonathan, Simea son, Davids broders, slog honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Desse voro födde af Rapha i Gath, och föllo genom Davids och hans tjenares hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Och Satan hof sig upp emot Israel, och gaf David in, att han lät räkna Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Och David sade till Joab, och till folkens öfverstar: Går bort, och räkner Israel, allt ifrå BerSeba intill Dan; och bärer till mig, att jag må veta talet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab sade: Herren föröke till sitt folk hundrade sinom så mycket som det nu är: Min herre Konung, äro de icke alle mins herras tjenare? Hvi frågar då min herre derefter? Hvi skulle en skuld komma på Israel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Men Konungens ord gick fram emot Joab; och Joab drog ut, och for omkring all Israel, och kom till Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Och fick David talet på det räknade folket; och det var af hela Israel ellofva sinom hundrade tusend män, som svärd utdrogo; och Juda fyrahundrade sinom tusend, och sjutiotusend män, som svärd utdrogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Men Levi och BenJamin räknade han intet ibland dessa; förty Konungens ord var Joab en styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Men Gudi misshagade detta; och han slog Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Och David sade till Gud: Jag hafver svårliga syndat, att jag detta gjort hafver; men nu tag dins tjenares missgerning bort; förty jag hafver fast dårliga gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Och Herren talade med Gad, Davids Siare, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Gack, tala med David, och säg: Detta säger Herren: Treggehanda sätter jag dig före; utvälj dig der ett af, det jag dig göra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Då Gad kom till David, sade han till honom: Detta säger Herren:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Utvälj dig, antingen tre hård år, eller tre månaders flykt för dina ovänner, och för dina fiendars svärd, det du icke undkomma kan; eller tre dagar Herrans svärd och pestilentie i landena, så att Herrans Ängel förderfvar i alla Israels gränsor; så se nu till, hvad jag skall svara honom, som mig utsändt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David sade till Gad: Mig är fast ångest; dock vill jag falla i Herrans hand; ty hans barmhertighet är ganska stor; och icke falla i menniskohand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Då lät Herren komma pestilentie i Israel, så att sjutiotusend män föllo af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Och Gud sände Ängelen till Jerusalem till att slå det; och när han förderfvade, såg Herren dertill, och ångrade det onda, och sade till Ängelen, som förderfvade: Det är nog, håll dina hand tillbaka. Men Herrans Ängel stod vid Arnans, den Jebuseens lado.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Och David hof upp sin ögon, och fick se Herrans Ängel stå emellan himmelen och jordena, och ett draget svärd i hans hand, uträckt öfver Jerusalem. Då föll David och de äldste på sin ansigte, klädde i säcker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Och David sade till Gud: Är icke jag den som lät räkna folket? Jag är den som syndade och det onda gjort hafver; dessa far, hvad hafva de gjort? Herre, min Gud, låt dina hand vara emot mig och mins faders hus, och icke emot ditt folk, till plågo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Och Herrans Ängel sade till Gad, att han skulle säga David, att David skulle gå upp, och resa Herranom ett altare i Arnans, den Jebuseens, lado.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Alltså gick David upp efter Gads ord, som han i Herrans Namn talat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Men då Arnan vände sig, och såg Ängelen, han och hans fyra söner med honom, gömde de sig bort; ty Arnan tröskade vete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Som nu David gick till Arnan, såg Arnan och vardt varse David, och gick utaf ladone, och tillbad David på sitt ansigte till jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Och David sade till Arnan: Gif mig ladones rum, att jag må bygga Herranom ett altare deruppå; för fulla penningar skall du få mig det, att plågan på folket må återvända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Arnan sade till David: Tag dig det, och gör, min herre Konung, såsom dig täckes. Si, jag gifver också oxarna till bränneoffret, och redskapen till ved, och hvete till spisoffer; alltsamman gifver jag det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Men Konung David sade till Arnan: Icke så, utan för fulla penningar vill jag köpat; ty jag vill icke taga det ditt är för Herranom, och göra bränneoffer till gifvins.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Alltså gaf David Arnan, för rummet, gyldene siktar till vigt sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Och David byggde dersammastäds Herranom ett altare, och offrade bränneoffer och tackoffer; och då han åkallade Herran, hörde han honom genom eld af himmelen uppå bränneoffrets altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Och Herren sade till Ängelen, att han skulle sticka sitt svärd i skidona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'På samma tiden, då David såg, att Herren hade hört honom uppå Arnans den Jebuseens plats, offrade han der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Ty Herrans tabernakel, som Mose i öknene gjort hade, och bränneoffrets altare, var i den tiden på höjdene i Gibeon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Men David kunde icke gå ditin för det, till att söka Gud; så var han förskräckt för Herrans Ängels svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Och David sade: Här skall Herrans Guds hus vara, och detta altaret till Israels bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Och David lät församla de främlingar, som i Israels land voro, och beställde stenhuggare, till att hugga sten till Guds hus byggning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Och David tillredde mycket jern till naglar åt dörrena i portomen, och hvad tillhopanaglas skulle; och så mycken koppar, att han icke stod till vägandes;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Och cedreträ utan tal; förty de af Zidon och Tyro förde mycket cedreträ till David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Ty David tänkte: Min son Salomo är en ung pilt och späd; men huset, som Herranom byggas skall, måste vara stort, att dess namn och lof utgå må i all land derföre vill jag skaffa honom virke. Alltså skaffade David mycket virke, förr än han dödde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Och han kallade sin son Salomo, och böd honom bygga Herrans Israels Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Och sade till honom: Min son, jag hade i sinnet att bygga Herrans mins Guds Namne ett hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Men Herrans ord kom till mig, och sade: Du hafver mycket blod utgjutit, och fört stort örlig: derföre skall du icke bygga mino Namne hus, efter du så mycket blod utgjutit hafver för mig på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Si, din son, som dig skall född varda, han skall vara en rolig man; förty jag vill låta honom få ro för alla hans fiendar allt omkring. Han skall heta Salomo; ty jag skall gifva frid och rolighet öfver Israel uti hans lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Han skall bygga mino Namne ett hus; han skall vara min son, och jag skall vara hans fader, och jag skall stadfästa hans Konungsliga stol öfver Israel till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Så varder nu, min son, Herren med dig blifvandes, och du skall blifva lyckosam, att du må bygga Herranom dinom Gud ett hus, såsom han om dig sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Och Herren varder dig gifvandes klokhet och förstånd, och skall befalla dig Israel, att du skall hålla Herrans dins Guds lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Men då varder du lyckosam, när du håller dig, att du gör efter de seder och rätter, som Herren Mose budit hafver till Israel. Var tröst och vid godt mod, frukta dig intet, och gif dig intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Si, jag hafver i minom fattigdom förskaffat till Herrans hus hundradetusend centener guld och tusende resor tusende centener silfver; dertill koppar och jern utan tal, ty det är fast mycket. Hafver jag också beställt timber och stenar, det kan du ännu föröka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Så hafver du många arbetare, stenhuggare och timbermän till sten och trä, och allahanda kloka på allahanda verk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'På guld, silfver, koppar och jern utan tal. Så statt nu upp, och beställ det; Herren skall vara med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Och David böd allom öfverstom i Israel, att de skulle hjelpa hans son Salomo:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Är icke Herren edar Gud med eder, och hafver gifvit eder rolighet allt omkring? Ty han hafver gifvit landsens inbyggare uti edra händer, och landet är undergifvet vordet för Herranom, och för hans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Så gifver nu edor hjerta och edra själar, till att söka Herran edar Gud; och står upp, och bygger Herranom Gudi en helgedom, att man må bära Herrans förbunds ark och de heliga Guds kärilen in uti huset, som Herrans Namne skall bygdt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Alltså gjorde David Salomo, sin son, till Konung öfver Israel, då han gammal, och af lefvande mätt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Och David församlade alla öfverstar i Israel, och Presterna och Leviterna,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Att man skulle räkna Leviterna, ifrå tretio är och derutöfver; och deras tal var, ifrå hufvud till hufvud, det starke män voro, åtta och tretio tusend;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Af hvilkom voro fyra och tjugu tusend, som drefvo arbetet på Herrans hus; och sextusend ämbetsmän och domare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Och fyratusend dörravaktare; och fyratusend lofsångare Herranom med strängaspel, som jag till lofsång gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Och David gjorde en ordning ibland Levi barn, nämliga ibland Gerson, Kehath och Merari.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Då Gersoniter voro: Laedan och Simei.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Laedans barn: Den förste Jehiel, Setam och Joel, de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Men Simei barn voro: Selomith, Hasiel och Haran, de tre. Desse voro de ypperste ibland fäderna af Laedan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Voro också desse Simei barn: Jahath, Sina, Jeus och Beria. Desse fyra voro ock Simei barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahath var den förste, Sisa den andre. Men Jeus och Beria hade icke mång barn; derföre vordo de räknade för ens faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehaths barn voro: Amram, Jizear, Hebron och Ussiel, de fyra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrams barn voro: Aaron och Mose. Men Aaron vardt afskild, så att han vardt helgad till det aldrahelgasta, han och hans söner, till evig tid, till att röka för Herranom, och till att tjena och välsigna i Herrans Namn i evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Och Mose, den Guds mansens, barn vordo nämnde ibland de Leviters slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mose barn voro: Gersom och Elieser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Gersoms barn: Den förste var Sebuel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliesers barn: Den förste var Rehabia. Och Elieser hade inga annor barn; men Rehabia barn voro mycket flere.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jizears barn voro: Selomith den förste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebrons barn voro: Jeria den förste, Amaria den andre, Jahasiel den tredje, och Jekameam den fjerde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Ussiels barn voro: Micha den förste, och Jissija den andre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merari barn voro: Maheli och Musi. Maheli barn voro: Eleazar och Kis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Men Eleazar blef död, och hade inga söner, utan döttrar; och Kis barn, deras bröder, togo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Musi barn voro: Maheli, Eder och Jeremoth, de tre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Detta äro Levi barn i deras faders hus, och de ypperste af fäderna, som räknade vordo, efter namnens tal efter hufvuden, hvilke gjorde de sysslor i ämbeten i Herrans hus, ifrå tjugu år, och derutöfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Ty David sade: Herren Israels Gud hafver gifvit sino folke ro, och skall bo i Jerusalem till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Leviterna behöfde ock icke bära tabernaklet, med all dess redskap, efter deras ämbete;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Utan, efter Davids yttersta ord, vordo Levi barn räknade ifrå tjugu år, och derutöfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Att de skulle stå under Aarons barnas händer, till att tjena i Herrans hus, i gårdenom, och till kistorna, och till reningen, och till allahanda helgedom, och till alla ämbetens sysslor i Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Och till skådobröd, till semlomjöl, till spisoffer, till osyrade kakor, till pannor, till halster, och till all vigt och mått;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Och till att stå om morgonen, och tacka och lofva Herran; om aftonen desslikes;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Och till att offra Herranom all bränneoffer på Sabbatherna, nymånadom och högtidom, efter talet och sättet, alltid för Herranom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Att de skulle taga vara på vaktena vid vittnesbördsens tabernakel, och helgedomens; och Aarons barnas, deras bröders, till att tjena i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Men Aarons barnas ordning var denna: Aarons barn voro Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Men Nadab och Abihu blefvo döde inför deras fader, och hade inga barn; och Eleazar och Ithamar vordo Prester.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Och David skickade dem alltså, Zadok af Eleazars barn, och Ahimelech af Ithamars barn, efter deras tal och ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Och vordo Eleazars barn flere funne till yppersta starka män än Ithamars barn. Och han skickade dem alltså; nämliga sexton utaf Eleazars barn, till öfverstar ibland deras fäders hus; och åtta af Ithamars barn ibland deras fäders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Och han skifte dem efter lott, derföre, att både af Eleazars och Ithamars barn voro öfverstar i helgedomenom, och öfverstar för Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Och skrifvaren Semaja, Nethaneels son, utaf Leviterna, beskref dem för Konungenom, och för öfverstarna, och för Zadok Prestenom, och för Ahimelech, AbJathars son, och för öfversta fäderna ibland Presterna och Leviterna; nämliga ett fadershus för Eleazar, och det andra för Ithamar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Och förste lotten föll uppå Jojarib, den andre uppå Jedaja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Den tredje på Harim, den fjerde på Seorim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Den femte på Malchija, den sjette på Mijamin;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Den sjunde på Hakkoz, den åttonde på Abia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Den nionde på Jesua, den tionde på Sechania;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Den ellofte på EljaSib, den tolfte på Jakim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Den trettonde på Huppa, den fjortonde på Jesebeab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Den femtonde på Bilga, den sextonde på Immer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Den sjuttonde på Hesir, den adertonde på Happizez;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Den nittonde på Petahja, den tjugonde på Jeheskel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Den förste och tjugonde på Jachin, den andre och tjugonde på Gamul;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Den tredje och tjugonde på Delaja, den fjerde och tjugonde på Mahasia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Detta är ordningen efter deras ämbeten, till att gå i Herrans hus efter deras sätt, under deras fader Aaron, såsom Herren Israels Gud dem budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Men utaf de andra Levi barn, af Amrams barn var Subael. Af Subaels barn var Jehdeja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Af Rehabia barn var den förste Jissija.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Men af de Jizeariter var Selomoth. Af Selomoths barn var Jahath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, '(Hebrons) barn voro: Jeria den förste, Amaria den andre, Jahasiel den tredje, Jekameam den fjerde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Ussiels barn voro: Micha. Utaf Micha barn var Samir.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Micha broder var Jissija. Utaf Jissija barn var Zacharia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merari barn voro: Maheli och Musi; hans son var Jaasia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merari barn, af Jaasia, hans son, voro: Soham, Saccur och Ibri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Men Maheli hade Eleazar, och Eleazar hade inga söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Af Kis: Kis barn voro: Jerahmeel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Musi barn voro: Maheli, Eder och Jerimoth. Detta äro de Leviters barn, i deras faders hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Och man kastade också för dem lott, bredovid deras bröder Aarons barn, inför Konung David och Zadok, och Ahimelech, och inför de öfversta fäderna af Prestomen och Levitomen, dem minsta brodrenom så väl som dem öfversta af fäderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Och David, samt med härhöfvitsmännerna, afskiljde till ämbete af Assaphs barn, Heman och Jeduthun, de Propheterna med harpor, psaltare och cymbaler; och de vordo talde till verket, efter sitt ämbete:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Utaf Assaphs barn: Saccur, Joseph, Nethania, Asarela, Assaphs barn, under Assaph, som propheterade när Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Af Jeduthun: Jeduthuns barn voro: Gedalia, Zeri, Jesaja, Hasabia, Mattithia, de sex, under deras fader Jeduthun, med harpor, hvilke propheterade till att tacka och lofva Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Af Heman: Hemans barn voro: Bukkija, Matthania, Ussiel, Sebuel, Jerimoth, Hanania, Hanani, Eliatha, Giddalthi, RomamthiEser, Josbekasa, Mallothi, Hothir och Mahasioth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Desse voro alle Hemans barn, Konungens Siares i Guds ordom, till att upphöja hornet; ty Gud hade gifvit Heman fjorton söner och tre döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Desse voro alle under deras fäder Assaph, Jeduthun och Heman, till att sjunga i Herrans hus med cymbaler, psaltare och harpor, efter ämbetet i Guds hus när Konungen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Och talet på dem, med deras bröder, som i Herrans sång lärde voro, allesammans mästare, tuhundrad åtta och åttatio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Och de kastade lott öfver deras ämbete, dem minsta såsom dem största; mästarenom såsom lärjunganom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Och den förste lotten föll på Joseph under Assaph; den andre på Gedalia, med hans bröder och söner, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Den tredje på Saccur, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Den fjerde på Jizri, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Den femte på Nethania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Den sjette på Bukkija, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Den sjunde på Jesarela, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Den åttonde på Jesaja, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Den nionde på Matthania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Den tionde på Simei, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Den ellofte på Asareel, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Den tolfte på Hasabia, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Den trettonde på Subael, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Den fjortonde på Mattithia, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Den femtonde på Jeremoth, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Den sextonde på Hanania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Den sjuttonde på Josbekasa, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Den adertonde på Hanani, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Den nittonde på Mallothi, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Den tjugonde på Elijatha, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Den förste och tjugonde på Hothir, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Den andre och tjugonde på Giddalthi, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Den tredje och tjugonde på Mahasioth, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Den fjerde och tjugonde på RomamthiEser, med hans söner och bröder, de voro tolf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Om dörravaktarenas ordning: Utaf de Korhiter var Meselemia, Kore son, af Assaphs barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemia barn voro desse: Den förstfödde Zacharia, den andre Jediael, den tredje Sebadja, den fjerde Jathniel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Den femte Elam, den sjette Johanan, den sjunde Eljoenai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Men ObedEdoms barn voro desse: Den förstfödde Semaja, den andre Josabad, den tredje Joah, den fjerde Sacar, den femte Nethaneel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Den sjette Ammiel, den sjunde Isaschar, den åttonde Peulthai; ty Gud hade välsignat honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Och hans sone Semaja vordo ock söner födde, som i deras fäders hus regerade; ty de voro starke hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Så voro nu Semaja barn: Othni, Rephael, Obed, och Elsabad, hvilkens bröder mägtige män voro, Elihu och Semachia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Desse voro alle utaf ObedEdoms barn; de med deras barn och bröder, mägtige män, skicklige till ämbete, två och sextio af ObedEdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemia hade barn och bröder, mägtige män, aderton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Men Hosa utaf Merari barnom hade barn: Den ypperste Simri; ty den förstfödde var icke till, derföre satte hans fader honom främst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Den andre Hilkia, den tredje Tebalia, den fjerde Zacharia. All Hosa barn och bröder voro tretton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Detta är dörravaktarenas ordning, bland höfdingarna i ämbetet med deras bröder, till att tjena i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Och lotten vardt kastad dem litsla såväl som dem stora, i deras fäders hus till hvarjo dörrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Den lotten österut föll på Selemia; men hans sone Zacharia, hvilken en klok och rådig man var, kastade man lotten, och honom föll norrut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Men ObedEdom söderut, och hans sönom vid huset Asuppim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Och Suppim och Hosa, vesterut vid dörrena Sallecheth, på bränneoffers vägenom, der vakterna vid hvarandra stå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Österut voro sex af Leviterna, norrut fyra om dagen, söderut fyra om dagen; men vid Asuppim ju två och två;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Vid Parbar, vesterut, fyra på vägenom, och två vid Parbar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Detta är dörravaktarenas ordning, ibland de Korhiters barn, och Merari barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Utaf Leviterna var Ahija öfver halvorna i Guds hus; och öfver de håfvor, som helgada vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Af Laedans barn, de Gersoniters barn; af Laedan voro höfdingar ibland fäderna, nämliga de Jehieliter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'De Jehieliters barn voro: Setham och hans broder Joel, öfver Herrans hus håfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Utaf de Amramiter, Jizeariter, Hebroniter och Asieliter,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Var Sebuel, Gersoms son, Mose sons, en Förste öfver håfvorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Men hans broder Elieser hade en son Rehabia. Hans son var Jesaja; hans son var Joram; hans son var Sichri; hans son var Selomith.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Den samme Selomith och hans bröder voro öfver alla de helgada tings håfvor, hvilka Konung David helgade, och de öfverste fäderna ibland de öfversta öfver tusende och öfver hundrade, och de öfverste i härenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Utaf strid och rof hade de helgat det, till att förbättra Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Desslikes allt det Samuel Siaren, och Saul Kis son, och Abner, Ners son, och Joab, ZeruJa son, helgat hade; allt det helgada var under Selomiths hand, och hans bröders.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Utaf de Jizeariter var Chenanja med sina söner, till de verk utantill, öfver Israel befallningsmän och domare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Utaf de Hebroniter var Hasabia och hans bröder, mägtige män, tusende och sjuhundrade, öfver Israels ämbete, på desso sidone Jordan vesterut, till allahanda Herrans sysslo, och till att tjena Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Var ock ibland de Hebroniter Jeria, den ypperste ibland de Hebroniter, af fäderna i hans ätt. Det vordo ock af dem sökte och funne, uti fyrationde årena af Davids rike, mägtige män, i Jaeser i Gilead;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Och deras bröder, mägtige män, tutusend och sjuhundrad öfverste fäder. Och David satte dem öfver de Rubeniter, Gaditer, och öfver den halfva slägtena Manasse, till all Guds och Konungens ärende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Men Israels barn efter sitt tal voro höfdingar öfver fäderna, och öfver tusende, och öfver hundrade; och ämbetsmän, som på Konungen vaktade, efter deras ordning, till att draga till och frå, hvar i sin månad, i hvar månad om året. Hvart skiftet hade fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Öfver första skiftet i första månadenom var Jasabeam, Sabdiels son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Men af Perez barnom var den öfverste öfver alla höfvitsmännerna i härarna i första månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Öfver det skiftet i den andra månaden var Dodai den Ahohiten; och Mikloth var Förste öfver hans skifte; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Den tredje härhöfvitsmannen i tredje månadenom, den öfverste, var Benaja, Jojada Prestens son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Denne är Benaja, den hjelten ibland tretio, och öfver tretio; och hans skifte var under hans son Ammisabad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Den fjerde i fjerde månadenom var Asahel, Joabs broder, och efter honom Sebadia, hans son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Den femte i femte månadenom var Samhuth den Jisrahiten; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Den sjette i sjette månadenom var Ira, Ikkes den Thekoitens son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Den sjunde i sjunde månadenom var Helez den Peloniten, af Ephraims barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Den åttonde i åttonde månadenom var Sibbechai den Husathiten, af de Sarhiter; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Den nionde i nionde månadenom var Abieser den Anthothiten, af Jemini barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Den tionde i tionde månadenom var Maharai den Netophathiten, af de Serahiter; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Den ellofte i ellofte månadenom var Benaja den Pirgathoniten, af Ephraims barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Den tolfte i tolfte månadenom var Heldai den Netophathiten, af Athniel; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Öfver Israels slägter voro desse: För de Rubeniter var Förste Elieser, Sichri son; för de Simeoniter var Sephatia, Maacha son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'För de Leviter var Hasabia, Kemuels son; för de Aaroniter var Zadok;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'För Juda var Elihu af Davids bröder; för Isaschar var Omri, Michaels son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'För Sebulon var Jismaja, Obadja son; för Naphthali var Jerimoth, Asriels son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'För Ephraims barn var Hosea, Asasia son; för den halfva slägtene Manasse var Joel, Phedaja son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'För den halfva slägtene Manasse i Gilead var Jiddo, Zacharia son; för BenJamin var Jaasiel, Abners son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'För Dan var Asarel, Jerohams son Detta äro de Förstar för Israels slägter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Men David tog intet tal af dem som voro tjugu åra, och der för nedan; ty Herren hade sagt, att han skulle föröka Israel såsom stjernorna på himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Men Joab, ZeruJa son, hade begynt räkna, och lyktade det icke; ty en vredo kom fördenskull öfver Israel, derföre kom det talet icke uti Konung Davids Chrönico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Öfver Konungens håfvor var Asmaveth, Adiels son; och öfver de håfvor på landena, i städer, byar och slott, var Jonathan, Ussija son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Öfver åkermännerna till landsbruket var Esri, Chelubs son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Öfver vingårdarna var Simei den Ramathiten; öfver vinkällarena och vinet var Sabdi den Siphmiten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Öfver oljogårdarna, och mulbärträ i markene var BaalHanan den Gederiten; öfver oljona var Joas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Öfver den boskap, som i bet var i Saron, var Sithrai den Saroniten; men öfver den boskap i dalomen var Saphat, Adlai son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Öfver camelarna var Obil den Ismaeliten; öfver åsnarna var Jehdeja den Meronothiten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Öfver fåren var Jasis den Hagariten, Desse voro alle öfverstar öfver Konung Davids ägodelar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Men Jonathan, Davids faderbroder, var rådgifvare, hofmästare och canceller; Jehiel, Hachmoni son, var när Konungens barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel var ock Konungens rådgifvare; Husai den Arachiten var Konungens vän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Efter Achitophel var Jojada, Benaja son, och AbJathar; men Joab var Konungens härhöfvitsman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Och David församlade till Jerusalem alla Israels öfverstar, nämliga Förstarna för slägterna, Förstarna för skiften, som på Konungen vaktade; Förstarna öfver tusende, och öfver hundrade; Förstarna öfver Konungens och hans söners ägodelar och boskap; med kamererare, krigsmän och alla mägtiga män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Och Konung David stod upp på sina fötter, och sade: Hörer härtill, mine bröder, och mitt folk: Jag hafver tagit mig före att bygga ett hus, der Herrans förbunds ark uti hvilas skulle, och en fotapall till vår Guds fötter, och hade redt mig till att bygga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Men Gud lät säga mig: Du skall icke bygga mino Namne hus; förty du äst en krigsman, och hafver blod utgjutit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Nu hafver Herren Israels Gud utvalt mig utu hela mins faders hus, att jag skulle vara Konung öfver Israel till evig tid; ty han hafver utvalt Juda till ett Förstadöme; och i Juda huse, mins faders hus, och ibland mins faders barn hafver han haft ynnest till mig, så att han gjorde mig till Konung öfver hela Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Och ibland alla, mina söner (ty Herren hafver gifvit mig många söner) hafver han utvalt min son Salomo, att han sitta skall på Herrans rikes stol öfver Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Och hafver sagt till mig: Din son Salomo skall bygga mitt hus och gårdar; ty jag hafver utvalt mig honom till son, och jag skall vara hans fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Och skall stadfästa hans rike i evig tid, om han håller uppå att göra efter min bud och rätter, såsom i denna dag tillgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nu inför hela Israel Herrans menighet, och för vår Guds öron, så håller och söker all Herrans edars Guds bud; på det I mågen besitta detta goda landet, och ärfva det till edor barn efter eder, till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Och du, min son Salomo, känn dins faders Gud, och tjena honom af allt hjerta, och af en välviljog själ; ty Herren ransakar all hjerta, och förstår alla tankars uppsåt. Om du söker honom, så finner du honom; om du öfvergifver honom, så förkastar han dig till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Så se nu till, ty Herren hafver utvalt dig, att du skall bygga honom ett hus till helgedom. Var tröst, och gör så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Och David gaf sinom son Salomo en eftersyn till förhuset, och till sitt hus, och till maken, och till salen, och till kamrar innantill, och till nådastolens hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Dertill en eftersyn till allt det i hans sinne var, nämliga till gården åt Herrans hus, och till all maken omkring, till håfvorna i Guds hus, och de, helgada tings håfvor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Till Presternas och Leviternas skifte, och till alla sysslor i ämbeten uti Herrans hus, och till alla tjenstenes käril i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Guld efter gulds vigt, till allahanda tyg i hvart ämbetet, och allahanda silftyg, efter vigt, till allahanda redskap i hvart ämbetet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Och vigt till gyldene ljusastakar och gyldene lampor, hvarjom ljusastaka och hans lampor sina vigt; sammalunda ock till silfljusastakar gaf han vigt, till ljusastaka och hans lampor, efter hvars ljusastakans ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Gaf han desslikes guld till skådobrödsborden, till hvart bordet sina vigt; sammalunda ock silfver till silfborden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Och klart guld till gafflar, backen och kannor; och till gyldene skålar, hvar skål sina vigt; och till silfskalar, hvar skål sina vigt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Och till rökaltaret sina vigt, det aldraklaresta guld; och en eftersyn till vagnen för de gyldene Cherubim, så att de uträckte sig, och öfvertäckte Herrans förbunds ark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Alltsammans, sade han, är mig gifvet, beskrifvet af Herrans hand, som mig underviste all eftersynenes verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Och David sade till sin son Salomo: Var tröst och frimodig, och gör så; frukta dig intet, och var icke förskräckt; Herren Gud, min Gud, skall vara med dig, och skall icke draga sina hand ifrå dig, eller förlåta dig, allt intill du all verk till ämbeten i Herrans hus fullkomnat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Si, Presternas och Leviternas ordning till all ämbeten i Guds hus, äro med dig i all ärende, och äro viljoge och förståndige till all ämbeten; dertill Förstarna och allt folket i alla dina handlingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Och Konung David sade till hela menigheten: Gud hafver utvalt Salomo, en af mina söner, den ännu ung och späd är; men verket är stort, ty det är icke ens menniskos boning, utan Herrans Guds.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Men jag hafver utaf alla mina krafter beredt till Guds hus, guld till gyldene, silfver till silfvers, koppar till koppars, jern till jerns, trä till träs redskap; onichstenar, infattada rubiner och spräcklota stenar, och allahanda ädla stenar, och marmorsten ganska mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Derutöfver, af ynnest till mins Guds hus, hafver jag det mitt eget är, guld och silfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Tretusend centener guld af Ophir, och sjutusend centener klart silfver, det gifver jag till Guds helga hus, utöfver allt det jag förskickat hafver till att öfverdraga väggarna i husen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Så att af guld blifver det af guld vara skall, och af silfver det af silfver vara skall, och till allahanda verk igenom mästarenas hand. Och ho är nu i dag friviljog till att fylla sina hand Herranom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Då voro Förstarna för fäderna, Förstarna för Israels slägter, Förstarna öfver tusend och öfver hundrad, och Förstarna öfver Konungsärenden, friviljoge;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Och gåfvo till ämbeten i Guds hus femtusend centener guld, och tiotusend gylden, och tiotusend centener koppar, och hundradetusend centener jern.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Och när hvilkom stenar funne vordo, dem gåfvo de till håfvor uti Herrans hus, under Jehiels hand, den Gersonitens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Och folket var gladt, att de så friviljoge voro; ty de gåfvo Herranom af allo hjerta friviljoge. Och Konung David fröjdade sig desslikes högeliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Och lofvade Herran, och sade inför hela menighetene: Lofvad vare du, Herre, Israels vår foders Gud, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dig, Herre, tillhörer majestät och magt, härlighet, seger och tack; ty allt det i himmelen och på jordene ar, det är ditt; ditt, Herre, är riket, och du äst upphöjd öfver all ting till en öfversta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Dine äro rikedomar och härlighet för dig, du råder öfver all ting; i dine hand står kraft och magt, i dine hand står det att göra hvar och en stor och stark.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nu, vår Gud, vi tacke dig, och prise dins härlighets Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Ty hvad är jag, hvad är mitt folk, att vi skulle åstadkomma kraft till att gifva friviljeliga, såsom nu tillgår? Ty af dig är det allt kommet, och af dine hand hafve vi det gifvit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Förty vi äre främlingar och utländningar för dig, såsom alle våre fäder; vårt lefvande på jordene är såsom en skugge, och dväljs intet. Herre vår Gud, all denna hopen, som vi tillskickat hafve till att bygga dino helgo Namne ett hus, är kommen ifrå dine hand; och ditt är det allt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Jag vet, min Gud, att du pröfvar hjertat, och enfaldighet är dig täck; derföre hafver jag allt detta utaf enfaldigo hjerta friviljeliga gifvit; och hafver nu sett med glädje ditt folk, som här för handene är, att det hafver friviljeliga gifvit dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herre, våra fäders Abrahams, Isaacs och Israels Gud, bevara evinnerliga sådana håg och sinne i dins folks hjerta, och skicka deras hjerta till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Och minom son Salomo gif ett rättsinnigt hjerta, att han håller din bud, vittnesbörd och rätter, att han det allt gör, och bygger denna boning, som jag skickat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Och David sade till hela menighetena: Lofver Herran edar Gud. Och hela menigheten lofvade Herran deras fäders Gud, och bugade sig, och tillbådo Herran och Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Och de offrade Herranom offer; och den andra morgonen offrade de Herranom bränneoffer, tusende stutar, tusende vädrar, tusende lamb, med deras drickoffer; och offrade all hopen i hela Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Och åto och drucko den samma dagen för Herranom med stora glädje, och gjorde annan gången Salomo, Davids son, till Konung, och smorde honom Herranom till en Första, och Zadok till Prest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Alltså satt Salomo på Herrans stol, en Konung i sins faders Davids stad, och vardt lyckosam, och all Israel var honom hörsam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Och alle öfverstar och väldige, desslikes all Konung Davids barn, gåfvo sig under Konung Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Och Herren gjorde Salomo ju större och större för hela Israel, och gaf honom ett härligit rike, att ingen för honom sådant öfver Israel haft hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Så var nu David, Isai son, Konung öfver hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Men tiden, som han öfver Israel Konung var, var fyratio år. I Hebron regerade han sju är, och i Jerusalem tre och tretio är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Och blef död i godom ålder, mätt af lefvande, rikedomar och äro; och hans son Salomo vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Men Konung Davids gerningar, både de första och de sista, si, de äro skrifna ibland Samuels den Siarens gerningar, och ibland den Prophetens Nathans gerningar, och ibland Gads den Siarens gerningar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Med allt hans rike, välde och tid, som under honom förlupen är, både öfver Israel och all rike i landen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Och Salomo, Davids son, vardt i sitt rike förstärkt, och Herren hans Gud var med honom, och gjorde honom ju större och större.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Och Salomo talade med hela Israel, med de öfverstar öfver tusend och hundrade, med domare och alla Förstar i Israel, med de öfversta fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Att de skulle gå, Salomo och hela menigheten med honom, bort till den höjden, som i Gibeon var; ty der var Guds vittnesbörds tabernakel, som Mose Herrans tjenare gjort hade i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Ty Guds ark hade David uppfört ifrå KiriathJearim, dit han för honom tillredt hade; förty han hade honom uppslagit ett tabernakel i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Men det kopparaltaret som Bezaleel, Uri son, Hurs sons, gjort hade, var der för Herrans tabernakel; och Salomo och menigheten plägade söka det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Och Salomo offrade för Herranom på kopparaltaret, som der för dörrene af vittnesbördsens tabernakel stod, tusende bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'I samma nattene syntes Gud Salomo, och sade till honom: Bed, hvad skall jag gifva dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Och Salomo sade till Gud: Du hafver gjort stora barmhertighet med minom fader David, och hafver gjort mig till Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Så låt nu, Herre Gud, din ord varda sann till min fader David; ty du hafver gjort mig till Konung öfver ett folk, det så mycket är som stoftet på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Så gif mig nu vishet och förstånd, att jag för detta folket må gå ut och in; ty ho förmår döma detta ditt myckna folk?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Då sade Gud till Salomo: Efter du hafver detta i sinnet, och hafver icke bedit om rikedomar, eller ägodelar, eller om härlighet, eller om dina fiendars själar, eller om långt lif; utan hafver bedit om visdom och förstånd, att du må döma mitt folk, der jag dig en Konung öfver gjort hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Så vare dig visdom och förstånd gifvet; dertill vill jag ock gifva dig rikedomar, ägodelar och härlighet, så att din like ibland Konungarna för dig icke varit hafver, ej heller varda skall efter dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Alltså kom Salomo ifrå höjdene, som i Gibeon var, till Jerusalem, ifrå vittnesbördsens tabernakel, och regerade öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Och Salomo församlade sig vagnar och resenärar, så att han åstadkom tusende och fyrahundrade vagnar, och tolftusend resenärar, och lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Och Konungen gjorde, att silfver och guld var i Jerusalem så mycket som stenar; och cedreträ så mycket som mulbärsträ i dalarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Och man förde Salomo hästar utur Egypten, och allahanda varor. Och Konungens köpmän köpte samma varor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Och förde dem utur Egypten, hvar vagn för sexhundrad silfpenningar, och hvar häst för hundrade och femtio; alltså förde man dem ock till alla de Hetheers Konungar, och till de Konungar i Syrien, genom deras hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Och Salomo satte sig före att bygga Herrans namne ett hus, och ett sins rikes hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Och afräknade sjutiotusend män till bördor, och åttatiotusend timbermän uppå berget, och tretusend och sexhundrad befallningsmän öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Och Salomo sände till Hyram, Konungen i Tyro, och lät säga honom: Såsom du med minom fader David gjorde, och sände honom cedreträ, att han skulle bygga sig ett hus, der han uti bo skulle;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Si, jag vill bygga Herrans mins Guds Namne ett hus, att honom må helgadt varda, till att röka god rökverk för honom, och till alltid bereda skådobröd, och bränneoffer om morgon och afton, på Sabbather och nymånader, och på Herrans vår Guds högtider; till evig tid för Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Och det hus, som jag bygga vill, skall vara stort; förty vår Gud är större än alle gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Men ho är dess mägtig, att han bygger honom hus? Ty himmelen och alla himlars himlar kunna icke begripa honom. Ho skulle då jag vara, att jag skulle bygga honom hus? Utan att man må röka för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Så sänd mig nu en vis man, till att arbeta på guld, silfver, koppar, jern, skarlakan, rosenrödt, gult silke, och den som kan utgrafva med de visa, som när mig äro i Juda och Jerusalem, hvilka min fader David beställt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Och sänd mig cedreträ, furoträ och hebenträ af Libanon; förty jag vet, att dine tjenare kunna hugga trä på Libanon; och si, mine tjenare skola vara med dina tjenare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Att man tillreder mig mycket trä; ty huset, som jag bygga vill, skall vara stort och härligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Och si, jag vill gifva dina tjenare timbermannomen, som trä hugga, tjugutusend corar stött hvete, och tjugutusend corar bjugg, och tjugutusend bath vin, och tjugutusend bath oljo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Då sade Hyram, Konungen i Tyro, genom skrifvelse, och sände till Salomo: Derföre, att Herren hafver sitt folk kärt, hafver han gjort dig till Konung öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Och Hyram sade ytterligare: Lofvad vare Herren Israels Gud, som himmel och jord gjort hafver, att han gifvit hafver Konung David en visan, klokan och förståndigan son, som Herranom ett hus, och ett sins rikes hus bygga må.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Så sänder jag nu en visan man, som förstånd hafver, nämliga Hyram Abiv;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Ene qvinnos son utaf Dans döttrar, och hans fader hade varit en Tyrer; han kan arbeta på guld, silfver, koppar, jern, sten, trä, skarlakan, gult silke, linnet, rosenrödt: och allahanda utgrafva, och göra allahanda konsteliga, det man honom föregifver, med dina visa, och med mins herras Konung Davids dins faders visa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Så sände nu min herre hvete, bjugg, oljo och vin, till sina tjenare, såsom han sagt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Så vilje vi hugga trä på Libanon, så mycket som behöfves, och vilje låta det lägga i flottar i hafvet, in åt Japho; dädan må du låta föra det upp till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Och räknade Salomo alla främlingar i Israels land, efter det tal då David hans fader dem räknade; och vordo funne hundrade och femtio tusend, tretusend och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Och han gjorde af dem sjutiotusend dragare, och åttatiotusend huggare på bergena, och tretusend och sexhundrad befallningsmän, som folket vid arbetet höllo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Och Salomo begynte till att bygga Herrans hus i Jerusalem, på Moria berg, det David hans fader utvist var, hvilket David tillredt hade för rum, på Arnans plats den Jebuseens;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Och tog till att bygga i dem andra månadenom, den andra dagen i fjerde årena af sitt rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Och alltså lade Salomo grundvalen, till att bygga Guds hus: i förstone, längden sextio alnar, bredden tjugu alnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Och förhuset, för breddene af huset, var tjugu alnar långt, höjden var hundrade och tjugu alnar; och bedrog det innantill med klart guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Men det stora huset bedrog han med furoträ, och bedrog det med bästa guld, och gjorde deruppå palmar och kedjoverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Och bedrog huset med ädla stenar till prydelse; och guldet var Parvaims guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Och han bedrog huset, bjelkarna, dörrträn, väggarna och dörrarna med guld, och lät skära Cherubim på väggarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Han gjorde desslikes huset till det aldrahelgasta; dess längd var tjugu alnar efter husets bredd, och dess bredd var ock tjugu alnar; och bedrog det med bästa guld, vid sexhundrade centener.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Gaf han också till naglar femtio siklar guld i vigt; och bedrog salarna med guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Han gjorde ock uti dess aldrahelgastas huse två Cherubim, efter snickarekonst, och bedrog dem med guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Och längden af Cherubims vingar var tjugu alnar; så att en vingen hade fem alnar, och kom intill väggena af huset; den andre vingen hade ock fem alnar, och kom intill vingan af den andra Cherub.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Alltså hade ock en vingen af den andra Cherub fem alnar, och kom intill väggena af huset; och hans andre vinge ock fem alnar, och kom intill vingan af den andra Cherub;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Så att desse Cherubims vingar voro utsträckte tjugu alnar; och de stodo på sina fötter, och deras ansigte voro vänd åt huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Han gjorde ock en förlåt af gult verk, skarlakan, rosenrödt och linverk, och gjorde Cherubim deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Och han gjorde framför huset två stodar, fem och tretio alnar höga, och knappen der ofvanuppå fem alnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Och gjorde kedjoverk till choren, och satte ofvanuppå stoderna, och gjorde hundrade granatäple, och satte dem i det kedjoverket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Och reste de stoderna uppför templet, ena på den högra, och den andra på den venstra sidone; och kallade den på högra sidone Jachin, och den på venstra Boas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Han gjorde ock ett kopparaltare, tjugu alnar långt och bredt, och tio alnar högt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Och han gjorde ett gjutet haf, tio alnar bredt, ifrå den ena bräddene till den andra, rundt omkring, och fem alnar högt, och måttet omkring var tretio alnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Och oxabeläte voro der nedan under, allt omkring; och voro två radar krusering omkring hafvet, det tio alnar bredt var, hvilke vidgjutne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Och det stod så på de tolf oxar, att tre vändes norrut, tre vesterut, tre söderut, och tre österut, och hafvet der ofvanuppå; och bakdelen af dem allom var inunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Tjockheten deraf var en tvärhand, och dess brädd var såsom ens bägares brädd, och en utsprungen ros; och det höll tretusend bath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Och han gjorde tio kettlar, af dem satte han fem på högra sidone, och fem på den venstra, till att två derutinnan hvad som bränneoffer tillhörde, att de skulle kasta det deruti; men hafvet var till att Presterna skulle två sig deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Han gjorde ock tio gyldene ljusastakar, såsom de vara skulle, och satte dem i templet, fem på den högra, och fem på den venstra sidone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Ock gjorde han tio bord, och satte dem i templet, fem på högra, och fem på venstra sidone; och han gjorde hundrade gyldene bäcken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Han gjorde ock en gård för Presterna, och en stor gård, och dörrar i gårdenom; och öfverdrog dörrarna med koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Och satte hafvet på högra sidone österut, sunnantill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Och Hyram gjorde grytor, skoflar, och bäcken. Alltså lyktade Hyram arbetet, som Konung Salomo hade fått honom, på Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Nämliga de två stodar, med bukar, och knappar ofvanpå båda stoderna, och de båda vridna gjordar, till att betäcka båda bukarna åt knapparna, ofvanpå stoderna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Och de fyrahundrade granatäplen på de båda vridna gjordar, två radar granatäple på hvarjo gjordene, till att betäcka båda knapparnas bukar, som ofvanpå stoderna voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Ock gjorde han stolar, och kettlar uppå stolarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Och ett haf, och tolf oxar derunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Dertill grytor, skonar, gafflar och all deras tyg, gjorde Hyram Abiv åt Konung Salomo, till Herrans hus, utaf klar koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'I den ängden vid Jordan lät Konungen gjuta dem i lerjord, emellan Succoth och Zeredatha.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Och Salomo gjorde all denna tygen ganska mång; så att vigten af den koppar icke utfrågas kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Och Salomo gjorde all tyg till Guds hus, nämliga gyldene altaret, bord till skådobröd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Ljusastakarna med deras lampor, af klart guld, att de skulle brinna för chorenom, såsom det borde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Och de blommor vid lamporna, och de näpor voro af guld; allt var af rent guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Dertill knifvar, bäcken, slefvar och släcketyg, voro af klart guld; och ingången, och hans dörr innantill, åt det aldrahelgasta, och dörrarna till tempelshuset, voro af guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Alltså vardt allt arbetet fullkomnadt, som Salomo gjorde på Herrans hus. Och Salomo lät komma derin allt det hans fader David helgat hade, nämliga silfver och guld, och allahanda tyg; och lade det in uti fataburen i Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Då församlade Salomo alla äldsta i Israel, alla höfdingar i slägterna, Förstar för fäderna i Israels barn, till Jerusalem, att de skulle låta uppkomma Herrans förbunds ark utu Davids stad, det är Zion.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Och församlade sig till Konungen alle Israels män på högtidene, det är i sjunde månadenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Och kommo alle äldste i Israel; och de Leviter togo arken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Och båro honom upp, samt med vittnesbördsens tabernakel, och all helig tyg, som i tabernaklet voro; och Presterna Leviterna båro det allt med upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Men Konung Salomo och hela Israels menighet med honom, församlad inför arken, offrade får och fä, så mycket, att det ingen tälja eller räkna kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Alltså båro Presterna Herrans förbunds ark uti sitt rum, i husets chor, uti det aldrahelgasta, under Cherubims vingar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Så att Cherubim utsträckte sina vingar öfver arkens rum; och Cherubim öfvertäckte arken och hans stänger, ofvantill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Men stängerna voro så långa, att man såg ändarna på dem för choren ifrån arkenom; men utantill såg man dem icke; och blef han der allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Och i arken var intet utan de två taflor, som Mose hade lagt deruti i Horeb, då Herren ett förbund gjorde med Israels barn, den tid de utur Egypten drogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Och då Presterna gingo utu det helga; ty alle de Prester, som för handene voro, helgade sig, så att ock skiften icke hållne vordo,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Och de Leviter, med alla dem som under Assaph, Heman, Jeduthun, och deras barn och bröder, voro, klädde med linnen kläder, sjöngo med cymbaler, psaltare och harpor, och stodo österut ifrån altaret, och när dem tjugu och hundrade Prester, som blåste med trummeter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Och det var, såsom det hade varit allt en som trummetade, och sjöng, såsom man hörde ena röst, till att lofva och tacka Herranom; och då rösten upphof sig af trummeterna, cymbaler och annor strängaspel, och af Herrans lof, att han mild är, och hans barmhertighet varar till evig tid; då vardt Herrans hus uppfyldt med ett moln;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Så att Presterna icke stå kunde, till att tjena, för molnets skull; ty Herrans härlighet uppfyllde Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Då sade Salomo: Herren hafver sagt, att han vill bo i mörkrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Och jag hafver byggt ett hus dig till boning, och ett säte, der du bo skall till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Och Konungen vände sitt ansigte, och välsignade hela Israels menighet; ty hela Israels menighet stod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Och han sade: Lofvad vare Herren Israels Gud, som genom sin mun till min fader David talat, och med sine hand fullkomnat hafver, då han sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Efter den tiden, att jag mitt folk utur Egypti land förde, hafver jag ingen stad utvalt i alla Israels slägter, der ett hus att bygga, så att mitt Namn der vara skulle; hafver ej heller någon man utvalt, att han skulle vara en Förste öfver mitt folk Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Men Jerusalem hafver jag utvalt, att mitt Namn der vara skall; och David hafver jag utvalt, att han skall vara öfver mitt folk Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Och då min fader David i sinnet hade att bygga Herrans Israels Guds Namne ett hus,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Sade Herren till min fader David: Du hafver gjort väl, att du hafver i sinnet att bygga mino Namne ett hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Dock skall du icke bygga det huset, utan din son, som utaf dina länder komma skall, han skall bygga mino Namne hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Så hafver nu Herren stadfäst sitt ord, som han talat hafver; ty jag är uppkommen uti mins faders Davids stad, och sitter på Israels stol, såsom Herren sagt hafver; och hafver byggt ett hus Herrans Namne Israels Guds;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Och hafver satt deruti arken, der Herrans förbund uti är, det han med Israels barn gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Och han gick fram för Herrans altare, i hela Israels menighets närvaro, och uträckte sina händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Ty Salomo hade gjort en kopparkettil, och satt honom midt i gården, fem alnar lång och bred, och tre alnar hög: till den samma gick han, och föll neder på sin knä inför hela Israels menighet, och uträckte sina händer upp åt himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Och sade: Herre Israels Gud, det är ingen Gud dig liker, antingen i himmelen eller på jordene; du som håller förbund och barmhertighet dinom tjenarom, som vandra för dig af allt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Du hafver hållit din om tjenare David, minom fader, hvad du honom sagt hafver; med dinom mun hafver du sagt det, och med dine hand hafver du fullkomnat det, såsom det nu i denna dag tillgår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nu, Herre Israels Gud, håll dinom tjenare David, minom fader, hvad du till honom talat hafver, och sagt: Dig skall icke fattas en man för mig, som sitta skall på Israels stol; dock, såframt din barn förvara sina vägar, att de vandra i min lag, såsom du för mig vandrat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nu, Herre Israels Gud, låt din ord sann varda, som du dinom tjenare David sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Ty menar du ock, att Gud bor när menniskomen på jordene? Si, himmelen och alla himlars himlar kunna icke begripa dig; huru skulle då detta huset göra det, som jag byggt hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Men vänd dig, Herre, min Gud, till dins tjenares bön, och till hans begär, att du ville höra den bön och bedjande, som din tjenare för dig gör;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Att din ögon måga blifva öppne öfver detta hus dag och natt; öfver det rum, som du lofvat hafver, att ditt Namn der vara skall; att du ville höra den bön, som din tjenare på detta rum görandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Så hör nu dins tjenares, och dins folks Israels bön, som de bedjande varda i detta rum; och hör dertill ifrå det rum, der du bor i himmelen; och när du hörer, att du ville ock nådelig vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Om någor syndar emot sin nästa, och honom varder en ed pålagd, som han svärja skall; och den eden kommer för ditt altare i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Att du ville då höra af himmelen, och skaffa dinom tjenare rätt; att du ville vedergälla dem ogudaktiga, och gifva honom hans väg på hans hufvud, och gifva dem rättfärdiga rätt; och att du gifver honom efter hans rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Om ditt folk Israel för sina fiendar slaget varder, efter de emot dig syndat hafva; och de omvända sig, och bekänna ditt Namn, bedja och begära för dig i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Att du ville då höra dertill af himmelen, och vara dins folks Israels synder nådelig, och låta dem komma uti det land, som du dem och deras fäder gifvit hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Om himmelen tillyckt varder, så att intet regnar, efter de emot dig syndat hafva; och de bedja i detta rum, och bekänna ditt Namn, och omvända sig ifrå sina synder, sedan du dem ödmjukat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Att du då ville höra dem i himmelen, och vara dina tjenares och dins folks Israels synder nådelig, att du lärer dem en god väg, der de uti vandra måga; och låter regna på ditt land, som du dino folke gifvit hafver till besittning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Om en hunger varder i landena, eller pestilentie, eller torka, brand, gräshoppor, gräsmatkar; eller om deras fiendar i landet belägga deras portar; eller eljest någor plåga eller krankhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Den då beder, eller begärar ibland allahanda menniskor, och ibland allt ditt folk Israel, då någor sina plågo och vedermödo känner, och uträcker sina händer till detta huset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Att du då ville höra dertill af himmelen, af dins bonings säte, och vara nådelig, och gifva hvarjom och enom efter alla hans vägar, efter som du känner hans hjerta; ty du allena känner menniskors barnas hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'På det att de skola frukta dig, och vandra på dina vägar alla dagar, så länge som de lefva i landet, som du våra fäder gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Om ock en främmande, som icke är utaf ditt folk Israel, kommer af fjerran land, för ditt stora Namn och mägtiga hand och uträckta arms skull, och beder i desso huse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Att du ville höra dertill af himmelen, af dins bonings säte, och göra allt det, der han dig om åkallar; på det att all folk på jordene måga känna ditt Namn och frukta dig såsom ditt folk Israel, och förnimma att detta hus, som jag byggt hafver, efter ditt Namn nämndt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Om ditt folk utdrager i strid emot sina fiendar, den vägen som du dem sändandes varder, och de bedja till dig på den vägen emot denna staden, som du utvalt hafver, och till det hus, som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Att du då ville höra deras bön och begär af himmelen, och hjelpa dem till deras rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Om de varda syndande emot dig, efter ingen menniska är som icke syndar; och du varder vred på dem, och gifver dem för deras fiendar, att de föra dem bort fångna uti något land, fjerran eller när;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Och de omvända sig i sino hjerta, uti de lande der de uti fångne äro, och omvända sig, och bedja dig uti sins fängelses land, och säga: Vi hafve syndat, illa gjort och varit ogudaktige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Och vända sig så till dig af allt hjerta, och af allo själ, uti sins fängelses land, der man dem fångna håller, och de bedja på den väg emot sitt land, som du deras fäder gifvit hafver, och emot den stad, som du utvalt hafver, och emot huset, som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Att du då ville höra deras bön och begär af himmelen, af dins bonings säte, och hjelpa dem till deras rätt, och vara dino folke nådelig, som emot dig syndat hafva,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Så låt nu, min Gud, din ögon öppna vara, och din öron gifva akt på bönen i detta rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Så statt nu upp, Herre Gud, till dina ro, du och dins magts ark; låt dina Prester, Herre Gud, varda iklädde med salighet, och dina heliga glädja sig öfver det goda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herre Gud, vänd icke bort din Smordas ansigte; tänk uppå den barmhertighet, som din tjenare David lofvad är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Och då Salomo utbedit hade, föll en eld af himmelen, och förtärde bränneoffret och annat offer; och Herrans härlighet uppfyllde huset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Så att Presterna icke kunde ingå uti Herrans hus, så länge Herrans härlighet uppfyllde Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Och sågo all Israels barn elden falla neder, och Herrans härlighet öfver huset, och föllo ned med ansigtet till jordena på golfvet, och tillbådo, och tackade Herranom, att han är god, och hans barmhertighet varar till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Men Konungen och allt folket offrade för Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Ty Konung Salomo offrade tu och tjugu tusend nöt, och hundrade och tjugu tusend får; och vigde så Guds hus, både Konungen och allt folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Men Presterna stodo i sine vakt, ock Leviterna med Herrans strängaspel, som Konung David hade låtit göra till att tacka Herranom, att hans barmhertighet varar till evig tid, med Davids psalmer, genom deras hand; och Presterna blåste i trummeterna emot dem, och hele Israel stod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Och Salomo helgade medelgården, som för Herrans hus var; ty han hade der offrat bränneoffer, och det feta af tackoffrena; förty kopparaltaret, som Salomo hade göra låtit, kunde icke räcka till allt bränneoffret, spisoffret, och till det feta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Och Salomo höll på den samma tiden ena högtid i sju dagar, och hele Israel med honom, en ganska stor menighet, allt ifrå Hamath, intill Egypti bäck;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Och höll på åttonde dagen ena församling; ty altarets vigning höllo de i sju dagar, och högtiden sammalunda i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Men på tredje och tjugonde dagen i sjunde månadenom lät han gå folket i deras hyddor, glädjandes och fröjdandes sig öfver allt det goda, som Herren med David, Salomo och sino folke Israel gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Allt så lyktade Salomo Herrans hus, och Konungshuset, och allt det i hans hjerta kommet var, till att göra i Herrans huse, och i sino huse, i goda måtto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Och Herren syntes Salomo om nattena, och sade till honom: Jag hafver hört dina bön, och utvalt mig detta rummet till ett offerhus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si, om jag igenlycker himmelen, så att intet regnar, eller jag bjuder gräshoppor uppfräta landet, eller låter en pestilentie komma ibland mitt folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Att de mitt folk ödmjuka, det efter mitt namn nämndt är; och de bedja och söka mitt ansigte, och omvända sig ifrå sina onda vägar; så vill jag af himmelen höra dertill, och förlåta dem deras synder, och bota deras land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Så skola nu min ögon öppna vara, och min öron gifva akt på bönerna i desso rumme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Och hafver jag nu utvalt och helgat detta hus, att mitt Namn skall vara der till evig tid, och min ögon och mitt hjerta skall vara der allstädes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Och om du varder vandrandes för mig, såsom din fader David vandrat hafver, så att du gör allt det jag befaller dig, och håller min bud och rätter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Så skall jag befästa dins rikes stol, såsom jag mig förbundit hafver med dinom fader David, sägandes: Dig skall icke fattas en man, som öfver Israel en herre vara skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Men om I afvänden eder, och öfvergifven mina rätter och bud, som jag eder förelagt hafver, och gången bort, och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Så skall jag utrota dem utu mitt land, som jag dem gifvit hafver; och detta hus, som jag mino Namne helgat hafver, skall jag bortkasta ifrå mitt ansigte, och skall gifva det till ett ordspråk och en fabel ibland all folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Och för desso huse, det aldrahögst vordet är, skola sig förskräcka alle de som der framom gå, och säga: Hvi hafver Herren så farit med desso lande, och med desso huse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Då skall man säga: Derföre, att de öfvergåfvo Herran deras fäders Gud, den dem utur Egypti land fört hade, och togo sig andra gudar, och tillbådo dem, och tjente dem; derföre hafver han låtit allt detta onda komma öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Och efter tjugu år, i hvilkom Salomo Herrans hus, och sitt hus byggde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Byggde han ock de städer, som Hyram gaf Salomo, och lät Israels barn bo deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Och Salomo drog till HamathZoba, och gjorde det fast;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Och byggde Thadmor i öknene, och alla kornstäder, som han byggde i Hamath.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Han byggde ock öfra och nedra BethHoron, hvilka faste städer voro med murar, portar och bommar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Desslikes Baalath, och alla kornstäder som Salomo hade, och alla vagnsstäder, och resenärars städer, och allt det Salomo lyste att bygga, både i Jerusalem och på Libanon, och i allo hans väldes lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Allt det folk, som qvart blifvet var, af de Hetheer, Amoreer, Phereseer, Heveer och Jebuseer, som icke voro af Israels barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Och deras barn, som de efter sig left hade i landena, hvilka Israels barn icke förlagt hade, gjorde Salomo skattpligtiga, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Men af Israels barn gjorde Salomo inga trälar, till sitt arbete; utan de voro krigsmän, och öfver hans riddare, och öfver hans vagnar och resenärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Och de öfverste Konung Salomos befallningsmän voro tuhundrad och femtio, som öfver folket rådde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Och Pharaos dotter lät Salomo hemta af Davids stad, uti det hus, som han för henne byggt hade; ty han sade: Min hustru skall icke bo uti Davids Israels konungs huse; förty det är helgadt, efter Herrans ark der inkommen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Sedan offrade Salomo Herranom bränneoffer på Herrans altare, som han byggt hade för förhuset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Till att offra hvart på sin dag, efter Mose bud; på Sabbather, nymånader, och på bestämda tider, tre resor om året; nämliga på osyrade bröds högtidene, på veckohögtidene, och på löfhyddohögtidene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Och han satte Presterna i deras skifte till deras ämbete, såsom David hans fader det lagat hade; och Leviterna på deras vakt till att lofva och tjena för Presterna, hvar sin dag; och de dörravaktare i deras skifte, hvar vid sina dörr; ty så hade David den Guds mannen befallt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Och man vek icke ifrå Konungens bud, om Presterna och Leviterna, i någrahanda ärende och håfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Alltså vardt redo hvad Salomo för händer haft hade, ifrå den dag, då Herrans hus grundadt vardt, intilldess han fullkomnade det; så att Herrans hus allt redo vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Så drog Salomo till EzionGeber, och till Eloth, vid hafsstrandena i Edoms land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Och Hyram sände honom skepp med sina tjenare, som sjöfarne voro; och de foro med Salomos tjenare till Ophir, och hemtade dädan fyrahundrad och femtio centener guld, och förde till Konung Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Och då Drottningen af rika Arabien hörde Salomos rykte, kom hon med ganska stor skara till Jerusalem med cameler, som örter och guld båro, väl mycket, och ädla stenar, till att försöka Salomo med gåtor. Och då hon kom till Salomo, talade hon med honom allt det hon sig i sitt hjerta föresatt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Och Salomo sade henne allt det hon frågade; och Salomo var ingen ting fördold, det han icke sade henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Och då Drottningen af rika Arabien såg Salomos vishet, och huset, som han byggt hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Maten på hans bord, boningarna för hans tjenare, hans tjenares ämbete, och deras kläder, hans skänkesvänner, med deras kläder, och hans sal, der man uppgick uti Herrans hus, kunde hon icke längre hålla sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Och hon sade till Konungen: Det är sant, hvad jag hört hafver uti mitt land, af ditt väsende, och af dinom visdom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Men jag ville icke tro deras ord, till dess jag kommen är, och hafver det sett med min ögon; och si, mig är icke hälften sagt af dinom stora visdom; det är mer med dig än ryktet, som jag hört hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Salige äro dine män, och salige desse dine tjenare, som alltid stå för dig, och höra din visdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Herren din Gud vare lofvad, som dig kär hafver, att han dig till en Konung på din stol satt hafver, Herranom dinom Gud; det gör, att din Gud hafver Israel kär, så att han vill dem vid magt hålla till evig tid; derföre hafver han satt dig öfver dem till en Konung, att du skall hålla rätt och redelighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Och hon gaf Konungenom hundrade och tjugu centener guld, och ganska mycket örter, och ädla stenar: inga örter voro sådana som dessa, som Drottningen af rika Arabien Konung Salomo gaf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Dertill Hyrams tjenare och Salomos tjenare, som guld förde ifrån Ophir, de förde ock hebenträ, och ädla stenar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Och Salomo lät göra trappor utaf hebenträ i Herrans hus, och i Konungshusena, och harpor och psaltare för sångare; ingen sådana trä voro tillförene sedd i Juda land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Men Konung Salomo gaf Drottningene af rika Arabien allt det hon begärade och beddes, utan det hon hade fört till Konungen. Och hon vände om, och drog i sitt land igen med sina tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Men det guld, som Salomo årliga tillfördt vardt, var sexhundrad sex och sextio centener;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Förutan det som krämare och köpmän förde; och alle Arabers Konungar, och herrarna i landen förde guld och silfver till Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Och gjorde Konung Salomo tuhundrad spetsar af bästa guld; så att sexhundrad stycke guld kommo till hvar spets.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Och trehundrad sköldar af bästa guld, så att trehundrad stycke guld kommo till hvar sköld; och Konungen lät dem i huset af Libanons skog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Och Konungen gjorde en stor elphenbensstol, och öfverdrog honom med klart guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Och stolen hade sex trappor och en gyldene fotapall till stolen, och två stolpar, på båda sidor om sätet; och tu lejon stodo vid stolparna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Och tolf lejon stodo på de sex trappor, på båda sidor. En sådan är icke gjord i all Konungarike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Och all Konung Salomos drickekar voro af guld, och all käril i Libanons skogs huse voro af klart guld; förty silfver vardt intet aktadt i Salomos tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Ty Konungens skepp foro till sjös med Hyrams tjenare, och kommo en gång i hvar tre år, och förde guld, silfver, elphenben, apor och påfoglar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Alltså vardt Konung Salomo större, än alle Konungar på jordene, med rikedomar och vishet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Och alle Konungar på jordene begärade Salomos ansigte, att höra hans visdom, som Gud honom i hjertat gifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Och de förde honom årliga hvar och en sina skänkningar, silfkar och guldkar, kläder, harnesk, örter, hästar och mular.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Och Salomo hade fyratusend vagnshästar, och tolftusend resenärar, och man lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Och han var en herre öfver alla Konungar, allt ifrån älfvene intill de Philisteers land, och allt intill Egypti gränso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Och Konungen lät silfver i Jerusalem varda så mycket som stenar, och cederträ så mycket som mulbärsträ i dalarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Och man förde honom hästar utur Egypten, och utur all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Hvad nu mer af Salomo sägande är, både om hans första och om hans sista, si, det är skrifvet uti den Prophetens Nathans Chrönico, och uti Ahias Prophetia af Silo, och uti de syner Jeddo den Siarens, emot Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Och Salomo regerade i Jerusalem öfver hela Israel i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Och Salomo afsomnade med sina fäder, och man begrof honom uti Davids hans faders stad. Och Rehabeam, hans son, vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam drog till Sechem; ty hele Israel var kommen till Sechem, att göra honom till Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Och då Jerobeam, Nebats son, som i Egypten var, dit han för Konung Salomo flydd var, det hörde, kom han igen utur Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Och de sände bort, och läto kalla honom. Och Jerobeam kom med hela Israel; och de talade med Rehabeam, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Din fader hafver gjort vårt ok allt för hårdt; så lätta du ini dins faders hårda tjenst, och det svåra ok som han på oss lagt hafver, så vilje vi vara dig underdånige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Han sade till dem: Efter tre dagar kommer igen till mig. Och folket gick sin väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Och Konung Rehabeam rådfrågade med de äldsta, som för hans fader Salomo ståndit hade, medan han lefde, och sade: Hvad råden I, det jag skall svara desso folkena?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'De talade med honom, och sade: Om du ställer dig vänliga till detta folk, och far väl åt dem, och gifver dem god ord, så blifva de dig underdånige i alla sina dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Men han lät blifva de äldstas råd, som de honom gifvit hade, och rådfrågade med de unga, som med honom uppväxte voro, och för honom stodo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Och sade till dem: Hvad råden I, det vi desso folkena svara skole, som med mig talat hafva, och sagt: Lätta oss det ok, som din fader på oss lagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Men de unge, som med honom uppväxte voro, talade med honom, och sade: Så skall du säga till folket, som till dig talat hafver, och säger: Din fader hafver gjort vårt ok allt för tungt, gör du vårt ok lättare; och säg till dem: Mitt minsta finger skall vara tjockare än mins faders länder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Hafver nu min fader för tungt ok lagt uppå eder, så skall jag ännu göra edart ok tyngre; min fader hafver tuktat eder med gisslar, men jag med scorpioner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Som nu Jerobeam och allt folket kom till Rehabeam på tredje dagen, såsom Konungen sagt hade: Kommer igen till mig på tredje dagen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Svarade Konungen dem hårdeliga; och Konung Rehabeam öfvergaf de äldstas råd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Och talade med dem efter de ungas råd, och sade: Hafver min fader gjort edart ok för svårt, så skall jag ännu göra det svårare; min fader hafver tuktat eder med gisslar, men jag med scorpioner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Alltså hörde Konungen folket intet; ty det vardt alltså vändt af Gudi, på det Herren skulle göra sitt ord fast, som han talat hade genom Ahia af Silo till Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Då nu hele Israel såg, att Konungen intet hörde dem, svarade folket Konungenom, och sade: Hvad del hafve vi med David, eller arf med Isai son? Hvar och en af Israel drage till sina hyddor: Så se du nu till ditt hus, David. Och hele Israel gick i sina hyddor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Så att Rehabeam regerade allenast öfver de Israels barn, som bodde i Juda städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Då sände Konung Rehabeam Hadoram räntomästaren; men Israels barn stenade honom ihjäl. Och Konung Rehabeam steg med hast på sin vagn, och flydde till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Alltså föll Israel af ifrå Davids hus, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Då Rehabeam kom till Jerusalem, församlade han Juda hus och BenJamin, hundradetusend, och åttatiotusend unga män, som stridsamme voro, till att strida emot Israel, att de måtte komma åter riket under Rehabeam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Men Herrans ord kom till Semaja, den Guds mannen, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Tala till Rehabeam, Salomos son, Juda Konung, och till hela Israel, som under Juda och BenJamin är, och säg:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Detta säger Herren: I skolen icke draga upp, ej heller strida emot edra bröder; hvar och en gånge åter hem, förty det är skedt af mig. De lydde Herrans ord, och vände igen att draga emot Jerobeam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Men Rehabeam bodde i Jerusalem, och byggde de städer fasta i Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Nämliga Bethlehem, Etham, Thekoa,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethzur, Socho, Adullam,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gath, Maresa, Siph,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lachis, Aseka,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zorga, Ajalon och Hebron; hvilke voro de fastaste städer i Juda och BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Och han gjorde dem fasta, och satte der öfverstar in, och besörjde dem med spisning, oljo och vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Och i alla städer skaffade han sköldar och spjut, och gjorde dem ganska fasta. Och Juda och BenJamin voro under honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Och gåfvo sig till honom Presterna och Leviterna utaf hela Israel, och alla deras gränsor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Och de öfvergåfvo alla deras förstäder och håfvor, och kommo till Juda i Jerusalem; förty Jerobeam och hans söner fördrefvo dem, att de icke kunde bruka Herranom Presterskapet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Men han stiktade sig Prester till höjderna, och till djeflar, och kalfvar, som han göra lät.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Och efter dem kommo, utaf all Israels slägter, de som sitt hjerta gåfvo till att fråga efter Herran Israels Gud, till Jerusalem, att de måtte offra Herranom sina fäders Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Och förstärkte alltså Juda rike, och styrkte Rehabeam, Salomos son, i tre år; ty de vandrade på Davids och Salomos väg i tre år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Och Rehabeam tog Mahalath, Jerimoths dotter, Davids sons, till hustru, och Abihail, Eliabs dotter, Isai sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Hon födde honom dessa söner: Jehus, Semaria och Saham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Derefter tog han Maacha, Absaloms dotter. Hon födde honom Abia, Attai, Sisa och Selomith.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Men Rehabeam hade Maacha, Absaloms dotter, kärare, än alla sina hustrur och frillor; ty han hade aderton hustrur, och sextio frillor, och födde åtta och tjugu söner, och sextio döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Och Rehabeam satte Abia, Maachas son, till ett hufvud och Första öfver hans bröder; ty han hade i sinnet göra honom till Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Och han växte till, och yppade sig för alla hans söner i Juda och BenJamins land, i alla fasta städer. Och han gaf dem spisning en stor hop; och han tog många hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Då Rehabeams rike vardt stadfäst och förstärkt, öfvergaf han Herrans lag, och hele Israel med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Men i femte årena Konungs Rehabeams drog upp Sisak, Konungen i Egypten, emot Jerusalem; förty de hade syndat emot Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Med tusende och tuhundrad vagnar, och med sextiotusend resenärar, och det folk var icke till räknande, som med honom kom utur Egypten, Lybia, Suchim och Ethiopien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Och han vann de fasta städer, som i Juda voro, och kom intill Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Så kom Semaja den Propheten till Rehabeam, och till de öfversta i Juda, som sig till Jerusalem församlat hade för Sisak, och sade till dem: Detta säger Herren: I hafven öfvergifvit mig, derföre hafver jag öfvergifvit eder i Sisaks hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Då ödmjukade sig de öfverste i Israel, med Konungenom, och sade: Herren är rättvis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Då Herren nu såg, att de ödmjukade sig, kom Herrans ord till Semaja, och sade: De hafva ödmjukat sig, derföre vill jag icke förderfva dem, utan jag vill gifva dem en liten undsättning, så att min vrede icke skall drypa på Jerusalem genom Sisak.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Dock skola de varda honom underdånige, att de måga lära hvad det är att tjena mig, och tjena Konungariken i landomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Alltså drog Sisak, Konungen i Egypten, upp till Jerusalem, och tog ut de håfvor i Herrans hus, och de håfvor i Konungshusena, och förde alltsammans bort. Desslikes tog han ock de gyldene sköldar, som Salomo göra lät;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'I hvilkas stad Konung Rehabeam lät göra kopparsköldar, och befallde dem de öfversta för drabanterna, som vakt höllo för portenom af Konungshusena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Och så ofta som Konungen gick uti Herrans hus, kommo drabanterna, och båro dem, och lade dem åter i drabantakammaren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Och efter han ödmjukade sig, vände sig Herrans vrede ifrå honom, så att icke allt förderfvadt vardt; ty det var ännu något godt i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Alltså kom Konung Rehabeam sig före i Jerusalem, och regerade. Ett och fyratio år gammal var Rehabeam, då han vardt Konung, och regerade i sjutton år i Jerusalem, uti den stad som Herren utvalt hade utur all Israels slägter, att han der sitt Namn sätta skulle; hans moder het Naama, en Ammonitiska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Och han handlade illa, och skickade icke sitt hjerta till att söka Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Men Rehabeams gerningar, både de första och de sista, äro beskrifna uti den Prophetens Semaja, och i Iddo den Siarens gerningar, och upptecknade. Och örligade Rehabeam och Jerobeam så länge de lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Och Rehabeam afsomnade med sina fäder, och vardt begrafven uti Davids stad; och hans son Abia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Uti adertonde årena Konungs Jerobeams vardt Abia Konung i Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Och regerade tre år i Jerusalem; hans moder het Michaja, Uriels dotter, af Gibea. Och en strid hof sig upp emellan Abia och Jerobeam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Och Abia gjorde redo till strid med fyrahundradtusend unga män, starka till strid; men Jerobeam gjorde redo till att strida emot dem med åttahundradtusend starka unga män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Och Abia steg upp på Zemaraims berg, som ligger på Ephraims berg, och sade: Hörer härtill, Jerobeam, och hele Israel!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Veten I icke, att Herren Israels Gud hafver gifvit David Israels Konungarike till evig tid; honom och hans söner ett saltförbund?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Men Jerobeam, Nebats son, Salomos tjenare, Davids sons, kastade sig upp, och satte sig emot sin herra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Och till honom hafva gifvit sig lösaktige män och Belials barn, och hafva förstärkt sig emot Rehabeam, Salomos son; förty Rehabeam var ung, och af blödigt hjerta, så att han icke varde sig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Nu menen I vilja sätta eder emot Herrans rike, ibland Davids söner; efter I ären en stor hop, och hafven gyldene kalfvar, som Jerobeam eder för gudar gjort hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Hafven I icke fördrifvit Herrans Prester, Aarons söner, och Leviterna; och hafven gjort eder egna Prester, såsom folken i landen? Den som kommer till att fylla sina hand med en ung stut och sju vädrar, den varder Prest till dem som icke äro gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Men med oss är Herren vår Gud, den vi icke öfvergifve, och Presterna, som Herranom tjena, Aarons barn, och Leviterna i deras sysslor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Och upptända Herranom bränneoffer, hvar morgon och hvar afton, dertill det goda rökverket, och tillreda bröden på det rena bordet, och den gyldene stakan med sina lampor, så att de varda upptände hvar afton; ty vi behålle Herrans vår Guds vakt; men I hafven öfvergifvit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Si, med oss är Gud i spetsen, och hans Prester och trummeterna till att trummeta; så att man skall trummeta emot eder; I Israels barn, strider icke emot Herran edra fäders Gud; ty det varder eder icke väl bekommandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Men Jerobeam gjorde en bakhär, att han måtte komma bakuppå dem; så att desse voro frammanför Juda, och bakhären efter dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Då nu Juda vände sig om, si, då var strid både för och efter. Då ropade de till Herran, och Presterna trummetade med trummeter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Och hvar man i Juda skriade. Och då hvar man i Juda skriade, plågade Gud Jerobeam och hela Israel för Abia och Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Och Israels barn flydde för Juda; och Gud gaf dem i deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Och Abia med sitt folk gjorde en stor slagtning på dem; och föllo af Israel slagne femhundradtusend unge män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Alltså vordo Israels barn nedertryckte i den tiden; och Juda barn vordo tröste; förty de förläto sig på Herran deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Och Abia jagade efter Jerobeam, och vann honom städer af, BethEl med dess döttrar, Jesana med dess döttrar, och Ephron med dess döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Så att Jerobeam kom intet mer till magt, så länge Abia lefde. Och Herren plågade honom, så att han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Då nu Abia vardt förstärkt, tog han fjorton hustrur, och födde två och tjugu söner och sexton döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Hvad nu mer af Abia sägande är, och om hans vägar, och hans gerningar, det är skrifvet uti den Prophetens Iddo Historia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Och Abia afsomnade med sina fader, och de begrofvo honom uti Davids stad; och Asa hans son vardt Konung i hans stad; uti den tiden var landet stilla i tio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Och Asa gjorde det rätt var, och det Herranom hans Gud väl behagade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Och kastade bort de främmande altare, och höjderna, och slog sönder stoderna, och högg af lundarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Och lät säga Juda, att de skulle söka Herran deras fäders Gud, och göra efter lagen och budorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Och han kastade bort utur alla Juda städer höjderna och afgudarna; ty riket var stilla för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Och han byggde fasta städer i Juda, medan landet stilla, och intet örlig emot honom var uti de årena; ty Herren gaf honom ro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Och han sade till Juda: Låt oss bygga dessa städerna, och låta gå murar deromkring, och torn, portar och bommar, efter vi hafve rolighet i landena; ty vi hafve sökt Herran vår Gud, ja, vi hafve sökt honom, och han hafver gifvit oss ro allt omkring. Alltså byggde de, och det gick väl fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Och Asa hade en här, som spjut och sköld båro: utaf Juda trehundradtusend, och utaf BenJamin de som sköld båro, och med båga kunde, tuhundradtusend, och åttatiotusend; och desse voro alle starke hjeltar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Så drog emot dem Serah den Ethiopen, med en mägtig här, tusende resor tusende, dertill trehundrade vagnar, och kommo intill Maresa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Och Asa drog ut emot honom; och de redde sig till strid uti den dalen Zephatha vid Maresa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Och Asa åkallade Herran sin Gud, och sade: Herre, när dig är ingen skilfång hjelpa, ibland många, eller der ingen magt är. Hjelp oss. Herre vår Gud; ty vi förlåte oss på dig, och i ditt Namn äro vi komne emot denna hopen; Herre vår Gud, för dig förmår ingen menniska något.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Och Herren plågade de Ethioper för Asa, och för Juda, så att de flydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Och Asa med folkena, som med honom var, jagade efter dem allt intill Gerar. Och de Ethioper föllo, så att ingen af dem blef lefvandes, utan de vordo nederlagde för Herranom, och för hans här; och de togo ganska mycket rof deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Och han slog alla städer omkring Gerar; ty Herrans fruktan kom öfver dem, och de skinnade alla städer; ty der var mycket rof inne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Slogo de också boskapens hyddor, och togo får ganska mycken, och camelar; och kommo igen till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Och uppå Asaria, Obeds son, kom Guds Ande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Han gick ut emot Asa, och sade till honom: Hörer härtill, Asa, och hele Juda och BenJamin; Herren är med eder, efter I ären med honom; och när I söken honom, låter han sig af eder finna; om I ock öfvergifven honom, så öfvergifver han ock eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Men det skall vara många dagar i Israel, att der skall ingen rätter Gud vara; ingen Prest, som lärer; ingen lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Och när de omvända sig i sine nöd till Herran Israels Gud, och söka honom, så skall han låta sig finna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'På den tiden varder icke väl gångandes dem som ut och in gå; förty det varder ett stort buller öfver alla de som bo på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Ty det ena folket skall slå det andra, och en stad den andra; förty Gud skall förskräcka dem med allahanda ångest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Men I varer tröste, och drager icke edra händer ifrå; ty edart verk hafver sin lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Då Asa hörde dessa orden, och Obeds den Prophetens Prophetia, vardt han tröst, och kastade bort de styggelser utu hela Juda land och BenJamin, och utu städerna, som han vunnit hade på Ephraims berg, och förnyade Herrans altare, som för Herrans förhus stod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Och församlade hela Juda och BenJamin, och främlingarna när dem utaf Ephraim, Manasse och Simeon; förty till honom föllo månge af Israel, som de sågo att Herren hans Gud med honom var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Och de församlade sig till Jerusalem i tredje månadenom, i femtonde årena Asa rikes;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Och offrade på den dagen Herranom utaf rofvet, som de hemtat hade, sjuhundrad nöt, och sjutusend får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Och de trädde uti förbundet, att de skulle söka Herran deras fäders Gud, af allt hjerta, och af allo själ;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Och hvilken som icke sökte Herran Israels Gud, han skulle dö, både liten och stor, både man och qvinna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Och de svoro Herranom med höga röst, med rop, med trummeter och basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Och hele Juda fröjdade sig öfver eden; ty de hade svorit af allt hjerta, och de sökte honom af allom vilja, och han lät sig af dem finna; och Herren gaf dem ro allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Ock satte Konung Asa sina moder Maacha af ämbetet, för det hon stiktat hade uti Miplezeths lund; och Asa utrotade hennes Miplezeth, och sönderslog honom, och uppbrände honom vid Kidrons bäck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Men höjderna vordo icke bortlagda utur Israel; dock var Asa hjerta rättsinnigt, så länge han lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Och han lät komma in uti Guds hus hvad hans fader helgat hade, och hvad han helgat hade, silfver, guld och käril.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Och intet örlig var allt intill femte och tretionde året Asa rikes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Uti sjette och tretionde årena Asa rikes drog Baesa upp, Israels Konung, emot Juda, och byggde Rama, på det han skulle förmena Asa Juda Konung ut och in fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Men Asa tog af håfvorna uti Herrans hus, och i Konungshusena, silfver och guld, och sände till Benhadad, Konungen i Syrien, som bodde i Damascon, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Emellan dig och mig är ett förbund, emellan min och din fader; derföre hafver jag sändt dig silfver och guld, att du det förbund med Baesa, Konungenom i Israel, öfvergifva skall, att han må draga bort ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad lydde Konung Asa, och sände sina härförstar emot Israels städer; de slogo Ijon, Dan och AbelMajim, och alla Naphthali kornstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Då Baesa det hörde, vände han igen att bygga Rama, och höll upp af sitt verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Men Konung Asa tog till sig hela Juda, och de togo bort sten och trä ifrå Rama, der Baesa med byggde, och han byggde dermed Geba och Mizpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'På den tiden kom Hanani, Siaren, till Asa, Juda Konung, och sade till honom: Efter du förlätst dig på Konungen i Syrien, och hafver icke förlåtit dig på Herran din Gud; derföre är Konungens magt af Syrien undsluppen dina hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Voro icke de Ethioper och Lybier en mägta stor hop, med ganska många vagnar och resenärar? Likväl gaf Herren dem i dina hand, då du förlätst dig på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Förty Herrans ögon skåda all land, att han skall styrka dem, som af allt hjerta hålla sig intill honom. Du hafver gjort dårliga; derföre skall du ock härefter få örlig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Men Asa vardt vred på Siaren, och lade honom i fängelse; ty han knorrade emot honom om detta stycket. Och Asa undertryckte några af folket i den tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Men Asa gerningar, både de första och de sista, si, de äro skrifna uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Och Asa vardt krank i sina fötter, uti nionde och tretionde årena sins rikes; och hans krankhet fick öfvermagten, och han sökte intet Herran i sine krankhet, utan läkare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Alltså afsomnade Asa med sina fäder, och blef död i första och fyrationde årena sins rikes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Och man begrof honom uti hans graf, som han sig hade grafva låtit uti Davids stad; och de lade honom på sin säng, hvilka man uppfyllt hade med godt rökverk, och allahanda speceri, efter apothekares konst gjordt; och gjorde ett ganska stort brännande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Och hans son Josaphat vardt Konung i hans stad, och vardt mägtig emot Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Och lade krigsfolk uti alla Juda fasta städer, och satte befallningsmän i Juda land, och i Ephraims städer, som hans fader Asa vunnit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Och Herren var med Josaphat; ty han vandrade i de förra Davids sins faders vägar, och sökte icke Baalim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Utan sins faders Gud, och vandrade i hans bud, och icke efter Israels gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Derföre stadfäste Herren honom riket; och hele Juda gaf Josaphat skänker; och han hade rikedomar och härlighet ganska mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Och då hans hjerta dristigt vardt i Herrans vägar, hof han också bort höjderna och lundarna utu Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Uti tredje årena sins rikes sände han sina Förstar, Benhail, Obadia, Zacharia, Nethaneel och Michaja, att de skulle lära i Juda städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Och med dem de Leviter, Semaja, Nethania, Sebadja, Asahel, Semiramoth, Jonathan, Adonia, Tobia och TobAdonia; och med dem Presterna, Elisama och Joram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Och de lärde i Juda, och hade Herrans lagbok med sig, och foro omkring i alla Juda städer, och lärde folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Och Herrans fruktan kom öfver all rike i de land, som lågo omkring Juda, så att de intet stridde emot Josaphat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Och de Philisteer förde Josaphat skänker, en hop silfver; och de Araber förde honom sjutusend och sjuhundrad vädrar, och sjutusend och sjuhundrad bockar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Alltså växte Josaphat till, och vardt ju större och större; och han byggde i Juda slott och kornstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Och hade mycket till skaffa i Juda städer; och voro stridsamme och väldige män i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Och detta var ordningen ibland deras fäders hus, som i Juda Öfverstar voro öfver tusende: Adna den öfversten, och med honom voro trehundradetusend väldige män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Näst honom var Johanan den öfversten, och med honom voro tuhundrade och åttatio tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Dernäst Amasia, Sichri son, den Herrans friviljoge, och med honom voro tuhundradetusend väldige män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Af BenJamins barn var Eljada en väldig man, och med honom voro tuhundradetusend, som med bågar och sköld färdige voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Efter honom var Josabad, och med honom voro hundrade och åttatio tusend färdige män till strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Desse vaktade alle på Konungen, förutan de som Konungen lagt hade uti de fasta städer i hela Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Och Josaphat hade stora rikedomar och härlighet, och befryndade sig med Achab.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Och efter tu år drog han ned till Achab till Samarien; och Achab lät slagta för honom, och för det folk som när honom var, mycken får och fä; och han kom honom dertill, att han skulle draga med honom upp till Ramoth i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Och Achab, Israels Konung, sade till Josaphat, Juda Konung: Drag med mig till Ramoth i Gilead. Han sade till honom: Jag är såsom du, och mitt folk såsom ditt folk, vi vilje med dig i stridena,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Men Josaphat sade till Israels Konung: Käre, fråga i denna dag Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Och Israels Konung församlade af Propheterna fyrahundrade män, och sade till dem: Skole vi, draga till Ramoth i Gilead i strid, eller skall jag låta det bestå? De sade: Drag upp, Gud varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Men Josaphat sade: Är här icke ännu någor Herrans Prophet, att vi måge fråga af honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israels Konung sade till Josaphat: Här är ännu en man, att vi måge fråga Herran af honom; men jag är vred på honom, förty han spår intet godt öfver mig, utan alltid ondt, nämliga Micha, Jimla son. Josaphat sade: Konungen säge icke så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Och Israels Konung kallade en sin kamererare, och sade: Hemta med hast hit Micha, Jimla son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Och Israels Konung och Josaphat, Juda Konung, såto, hvardera på sin stol, beklädde; och de såto på platsen för ingångenom till porten i Samarien, och alle Propheterna spådde för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Och Zedekia, Chenaana son, gjorde sig jernhorn, och sade: Detta säger Herren: Härmed skall du stöta de Syrer, tilldess du gör ända med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Och alle Propheterna spådde detsamma, och sade: Drag upp till Ramoth i Gilead, och var lyckosam; Herren skall gifva det i Konungens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Och bådet, som åstad gånget var till att kalla Micha, talade med honom, och sade: Si, Propheternas tal är endrägteliga godt för Konungenom; käre, låt ock din ord vara såsom ensderas, och tala det godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micha sade: Så sant som Herren lefver, hvad min Gud sägandes varder, det vill jag tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Och då han kom till Konungen, sade Konungen till honom: Micha, skole vi draga till Ramoth i Gilead till strid, eller skall jag låta det blifva? Han sade: Drager upp, och eder ske lycka; det skall eder i edra händer gifvet varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Men Konungen sade till honom: Jag besvär dig ännu en gång, att du säger mig icke annat än sanningen, i Herrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Då sade han: Jag såg hela Israel förströdd på bergen, såsom får, de ingen herdan hafva. Och Herren sade: Hafva desse ingen herra? Fare hvar och en hem igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Då sade Israels Konung till Josaphat: Sade icke jag dig, han spår intet godt öfver mig, utan ondt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Men han sade: Derföre hörer Herrans ord: Jag såg Herran sitta på sinom stol, och all den himmelska hären stod vid hans högra sido, och vid hans venstra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Och Herren sade: Ho vill tälja Achab, Israels Konung i det sinnet, att han drager upp, och faller i Ramoth i Gilead? Och då den ene sade så, och den andre så,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Kom fram en ande, och stod för Herranom, och sade: Jag vill tälja honom i det sinnet. Herren sade till honom: Hvarmed?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Han sade: Jag vill fara ut, och vara en falsk ande uti alla hans Propheters mun. Och han sade: Du skall tälja honom i det sinnet, och uträttat; far åstad, och gör alltså.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nu si, Herren hafver gifvit en falsk anda uti dessa dina Propheters mun, och Herren hafver talat ondt öfver dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Då trädde fram Zedekia, Chenaana son, och slog Micha vid kindbenet, och sade: Hvilken vägen är Herrans Ande gången ifrå mig, till att tala med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micha sade: Si, du skall få set, då du kommer uti innersta kammaren, till att undstinga dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Men Israels Konung sade: Tager Micha, och låter honom blifva när Amon stadsfogdanom, och när Joas, Konungens son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Och säger: Så säger Konungen: Lägger denna i fängelse, och spiser honom med bedröfvelsens bröd och vatten, tilldess jag kommer igen med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Micha sade: Om du kommer igen med frid, så hafver icke Herren talat genom mig. Och han sade: Hörer härtill, allt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Alltså drog Israels Konung upp, och Josaphat, Juda Konung, till Ramoth i Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Och Israels Konung sade till Josaphat: Jag vill förkläda mig, och komma i stridena; men du haf din kläder uppå. Och Israels Konung förklädde sig; och de kommo i stridena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Men Konungen i Syrien hade budit sina öfversta resenärar, att de skulle strida emot ingen, antingen liten eller stor, utan emot Israels Konung allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Då nu de öfverste resenärerna fingo se Josaphat, tänkte de, det är Israels Konung: och drogo omkring till att strida uppå honom; men Josaphat ropade, och Herren halp honom, och Gud vände dem ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Ty då de öfverste resenärerna sågo, att det icke var Israels Konung, vände de sig bort ifrå honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Men en man bände sin båga hårdt, och sköt Israels Konung emellan magan och lungorna. Då sade han till sin foroman: Vänd dina hand, och för mig utu hären; förty jag är sår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Och striden växte till i den dagen. Och Israels Konung stod på sinom vagn emot de Syrer, allt intill aftonen; och blef död, när solen nedergick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Men Josaphat, Juda Konung, kom hem igen med frid till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Och gick ut emot honom. Jehu, Hanani son, Siaren, och sade till Konung Josaphat: Skulle du så hjelpa den ogudaktiga, och älska dem som Herran hata? Och fördenskull är öfver dig Herrans vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Så är dock likväl något godt funnet i dig, att du hafver borthäfvit de lundar utu landena, och hafver skickat ditt hjerta till att söka Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Alltså blef Josaphat i Jerusalem. Och han drog åter ut ibland folket, allt ifrå BerSeba, och in uppå Ephraims berg, och igenkallade dem till Herran deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Och han beställde domare i landena uti alla Juda fasta städer, ju några uti hvar stad; Och sade till domarena: Ser till hvad I gören; förty I hållen icke menniskodom, utan Herrans, och han är med eder i domen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Derföre, låter Herrans fruktan vara när eder. Tager eder vara, och görer så; ty när Herranom vårom Gud är ingen orätt, eller anseende till personer, ej heller tager han gåfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Ock satte Josaphat i Jerusalem utaf Leviterna och Presterna, och utaf de öfversta fäderna i Israel, öfver Herrans dom och saker, och lät dem bo i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Och böd dem och sade: Görer alltså uti Herrans fruktan, med tro och rätto hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Uti alla de saker, som komma till eder ifrån edra bröder, som bo i sina städer, emellan blod och blod, emellan lag och bud, emellan seder och rätter, skolen I undervisa dem, att de icke förbryta sig emot Herran, och en vrede må komma öfver eder, och edra bröder; görer alltså, så varden I icke brottslige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Si, Amaria Presten är öfverste öfver eder i alla Herrans saker; så är Sebadia, Ismaels son, Förste i Juda hus, i alla Konungssaker; så hafven I ämbetsmän Leviterna för eder. Varer tröste, och görer så, och Herren varder blifvandes med dem goda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Derefter kommo Moabs barn, Ammons barn, och med dem de af Ammonim, till att strida emot Josaphat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Och man kom, och bådade det Josaphat, och sade: Emot dig kommer ett mägta stort tal ifrå hinsidon hafvet, af Syrien, och si, de äro i HazezonThamar, det är EnGedi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Men Josaphat fruktade sig, och ställde sitt ansigte till att söka Herran, och lät utropa en fasto i hela Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Och Juda kom tillhopa, till att söka Herran; kommo ock utaf alla Juda städer till att söka Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Och Josaphat trädde in i menigheten af Juda och Jerusalem, uti Herrans hus inför nya gården;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Och sade: Herre, våra fäders Gud, äst icke du Gud i himmelen, och råder öfver all Hedningarnas rike? Och i dine hand är kraft och magt, och ingen är, som emot dig stå kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hafver du, vår Gud, icke fördrifvit detta lands inbyggare för dino folke Israel, och hafver gifvit det Abrahams dins väns säd till evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Så att de hafva bott deruti, och byggt dig derinne till ditt Namn en helgedom, och sagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Om något ondt, svärd, straff, pestilentie, eller hård tid öfver oss komme, skulle vi stå för detta hus inför dig; förty ditt Namn är i desso huse; och ropa till dig i våra nöd, så ville du höra dertill och hjelpa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Nu si, Ammons barn, Moab, och de af Seirs berg, öfver hvilka du icke lät Israels barn draga, då de foro utur Egypti land, utan de måste vika af ifrå dem, och icke förderfva dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Och si, de låta oss det umgälla, och komma till att utdrifva oss utu ditt arf, som du oss gifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Vår Gud, vill du icke döma dem? Ty i oss är ingen magt emot denna stora hopen, som emot oss kommer; vi vete icke hvad vi göra skole, utan vår ögon se till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Och hele Juda stod för Herranom med sin barn, hustrur och söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Men öfver Jahasiel, Sacharia son, Benaja sons, Jehiels sons, Matthania sons, den Leviten utaf Assaphs barn, kom Herrans Ande midt i menighetene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Och sade: Akter härtill, hele Juda, och I Jerusalems inbyggare, och Konung Josaphat; så säger Herren till eder: I skolen icke frukta eder, eller gifva eder för denna stora hopenom; ty det striden icke I, utan Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'I morgon skolen I draga ned till dem; och si, de draga upp till Ziz, och I skolen råka dem vid bäcken, för öknene Jeruel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Förty I skolen intet strida i denna sakene; allenast träder fram, och står, och ser Herrans salighet, den med eder är; Juda och Jerusalem, frukter eder intet, och gifver eder icke; i morgon drager ut emot dem. Herren är med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Då böjde sig Josaphat med sitt ansigte till jordena, och hela Juda och Jerusalems inbyggare föllo neder för Herranom, och tillbådo Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Och Leviterna utaf de Kehathiters barn, och utaf de Korinters barn, stodo upp till att lofva Herran Israels Gud med höga röst åt himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Och de voro bittida uppe om morgonen, och drogo ut till den öknen Thekoa. Och då de utdrogo, stod Josaphat och sade: Hörer härtill, Juda, och I Jerusalems inbyggare: Tror uppå Herran edar Gud, så varden I trygge; och tror hans Propheter, så sker eder lycka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Och han underviste folket, och satte sångare för Herranom, och dem som lofva skulle i heligom skrud, och gå för väpnade hären, och säga: Tacker Herranom, ty hans barmhertighet varar evinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Och då de begynte till att tacka och lofva, lät Herren bakhären, som emot Juda kommen var, komma in på Ammons barn, Moab, och dem af Seirs berg; och de slogo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Då stodo Ammons barn och Moab emot dem af Seirs berg, till att förspilla och nederlägga dem; och då de hade gjort ända på dem af Seirs berg, halp den ene dem andra, att de ock förderfvade sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Men då Juda kom till Mizpe vid öknen, vände de sig emot hopen; och si, då lågo de döde kroppar på jordene, så att ingen undsluppen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Och Josaphat kom med sitt folk till att byta deras rof, och funno ibland dem myckna ägodelar och kläder, och kostelig tyg; och skinnade dem, så att de icke mer kunde föra, och utbytte rofvet i tre dagar; ty det var ganska mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'På fjerde dagenom kommo de tillhopa uti lofsdalenom; förty der lofvade de Herran; deraf heter det rummet lofsdal, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Alltså vände hvar och en af Juda och Jerusalem tillbaka igen, och Josaphat för dem, så att de drogo till Jerusalem med fröjd; ty Herren hade gifvit dem en glädje öfver deras fiendar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Och drogo in uti Jerusalem med psaltare, harpor och trummeter, till Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Och Guds fruktan kom öfver all rike i landen, då de hörde, att Herren hade stridt emot Israels fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Alltså vardt Josaphats rike stilla; och Gud gaf honom ro allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Och Josaphat regerade öfver Juda; och var fem och tretio år gammal, då han Konung vardt, och regerade fem och tjugu år i Jerusalem. Hans moder het Asuba, Silhi dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Och han vandrade uti sins faders Asa väg, och gick intet derifrå, att han ju gjorde det Herranom väl täcktes;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Undantagno, att de höjder icke borttagne vordo; förty folket hade ännu icke skickat sitt hjerta till deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Hvad nu mer af Josaphat sägande är, både det första och det sista, si, det är skrifvet i Jehu gerningar, Hanani sons, hvilka han upptecknat hafver uti Israels Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Derefter förenade sig Josaphat, Juda Konung, med Ahasia, Israels Konung, hvilken ogudaktig var med sitt väsende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Och han samfällde sig med honom till att göra skepp, att de skulle fara till sjös; och skeppen gjorde de i EzionGeber.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Men Elieser, Dodava son af Maresa, spådde emot Josaphat, och sade: Derföre, att du hafver förenat dig med Ahasia, hafver Herren omintetgjort din verk. Och skeppen vordo sönderslagne, och kunde intet till sjös fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Och Josaphat af somnade med sina fäder, och vardt begrafven när sina fader uti Davids stad; och hans son Joram vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Och han hade bröder, Josaphats söner, Asaria, Jehiel, Zacharia, Asaria, Michael, och SephatJa; desse voro alle Josaphats, Juda Konungs, barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Och deras fader gaf dem myckna gåfvor i silfver, guld och klenodier, med fasta städer i Juda; men riket gaf han Joram; ty han var den förstfödde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Då nu Joram uppkom öfver sins faders rike, och vardt dess mägtig, drap han alla sina bröder med svärd, dertill ock somliga af de öfverstar i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Tu och tretio år gammal var Joram, då han vardt Konung; och regerade åtta år i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Och vandrade uti Israels Konungars väg, såsom Achabs hus gjort hade; förty Achabs dotter var hans hustru; och han gjorde hvad Herranom illa behagade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Men Herren ville icke förderfva Davids hus, för det förbunds skull, som han med David gjort hade, såsom han sagt hade, att gifva honom ena lykto, och hans barnom i alla dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'I hans tid föllo de Edomeer af ifrå Juda, och gjorde öfver sig en Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Förty Joram var ditöfver dragen med sina öfverstar, och alla vagnarna med honom; och hade varit uppe om nattena, och slagit de Edomeer allt omkring sig, och öfverstarna för vagnarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Derföre föllo de Edomeer af ifrå Juda, allt intill denna dag. På samma tiden föll ock Libna ifrå honom; ty han öfvergaf Herran sina fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Gjorde han ock höjder på bergen i Juda, och kom dem i Jerusalem till horeri, och förförde Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Men en skrifvelse kom till honom ifrå den Propheten Elia, så lydandes: Detta säger Herren dins faders Davids Gud: Derföre, att du icke vandrat hafver uti dins faders Josaphats vägar, icke heller i Asa, Juda Konungs, vägar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Utan du vandrar uti Israels Konungars väg, och kommer Juda och dem i Jerusalem till horeri, efter Achabs hus horeri; och hafver dertill dräpit dina bröder af dins faders hus, som bättre voro än du;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Si, Herren skall slå dig med en stor plågo på ditt folk, på din barn, på dina hustrur, och uppå alla dina ägodelar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Och du skall få mycken sjukdom uti dina inelfver, tilldess att dina inelfver skola för sjukdoms skull utgå dag frå dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Alltså uppväckte Herren emot Joram de Philisteers anda, och de Arabers, som ligga vid Ethiopien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Och de drogo upp till Juda, och förstörde det, och förde bort alla håfvor, som för handene voro i Konungshusena; dertill hans söner och hans hustrur, så att honom blef ingen son qvar, förutan Joahas, hans yngste son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Och efter allt detta plågade Herren honom i hans inelfver med en sådana sjukdom, som icke stod till botandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Och som det nu varade dag frå dag, och då tu års tid förgången var, gingo hans inelfver ut af honom med hans sjukdom; och han blef död af ondom sjukdom; och de gjorde intet brännande öfver honom, såsom de hans fäder gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Tu och tretio är gammal var han, då han vardt Konung, och regerade i åtta år i Jerusalem, och vandrade så, att det icke mycket dogde; och de begrofvo honom i Davids stad; dock icke ibland Konungsgrifterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Och de i Jerusalem gjorde till Konung Ahasia hans yngsta son, i hans stad; förty krigsfolket, som utaf de Araber med här kommo, hade de första alla ihjälslagit; derföre vardt Ahasia Konung, Jorams son, Juda Konungs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Tu och fyratio år gammal var Ahasia, då han Konung vardt, och regerade ett år i Jerusalem. Hans moder het Athalja, Amri dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Han vandrade ock uti Achabs hus vägar; ty hans moder höll honom dertill, att han skulle göra det ondt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Derföre gjorde han det Herranom icke behagade, såsom Achabs hus; ty de voro hans rådgifvare efter hans faders död, så att de förderfvade honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Och han vandrade efter deras råd, och han drog bort med Joram, Achabs son, Israels Konung, i strid, till Ramoth i Gilead, emot Hasael, Konungen i Syrien. Men de i Rama slogo Joram;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Så att han omvände, till att låta läka sig i Jisreel; förty han hade sår, som han fått hade i Rama, då han stridde med Hasael, Konungen i Syrien. Och Asaria, Jorams son, Juda Konungs, for ned till att bese Joram, Achabs son, i Jisreel, som krank låg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Ty den ofärden var så af Gudi Ahasia tillfogad, att han skulle komma till Joram, och så med Joram utdraga emot Jehu, Nimsi son, hvilken Herren smort hade, till att utrota Achabs hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Då nu Jehu höll uppå att straffa Achabs hus, fann han några öfverstar af Juda, och Ahasia bröders barn, som tjente, och drap dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Och han sökte Ahasia, och fick honom fatt, der han sig undstungit hade i Samarien; och han vardt hafder fram för Jehu. Han drap honom, och man begrof honom; ty de sade: Han är Josaphats son, hvilken efter Herran sökte af allt hjerta. Och var sedan ingen qvar utaf Ahasia huse, som Konung kunde varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Då nu Athalja, Ahasia moder, såg att hennes son död var, stod hon upp, och förgjorde all Konungslig säd i Juda hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Men Josabeath, Konungens dotter, tog Johas, Ahasia son, och stal honom undan ibland Konungsbarnen, som dräpne vordo, och lät honom med hans ammo uti en sängakammar. Alltså fördolde honom för Athalja Josabeath, Konung Jorams dotter, Prestens Jojada hustru; ty hon var Ahasia syster; att han icke dräpen vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Och han var med dem i Guds hus fördold i sex år, medan Athalja regerade i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Uti sjunde årena tog Jojada dristighet till sig, och tog med sig i förbund de öfversta öfver hundrade, nämliga Asaria, Jerohams son, Ismael, Johanans son, Asaria, Obeds son, Maaseja, Adaja son, och Elisaphat, Sichri son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'De foro omkring Juda, och hade de Leviter tillhopa utur alla Juda städer, och de öfversta fäderna i Israel; och de kommo till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Och hela menigheten gjorde ett förbund i Guds hus med Konungenom; och han sade till dem: Si, Konungens son skall Konung vara, såsom Herren sagt hafver, öfver Davids barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Så skolen I nu alltså göra: tredjedelen af eder, som på Sabbathsdagenom uppå gå, skola vara ibland de Prester och Leviter, som dörravaktare äro vid dörrarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Tredjedelen i Konungshuset, och tredjedelen vid grundvalsdörrena; men allt folket skall vara i gårdenom till Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Och att ingen går uti Herrans hus, utan Presterna och Leviterna, som tjena, de skola gå derin; förty de äro helige; och allt folket vakte Herrans vakt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Och Leviterna skola gifva sig omkring Konungen, hvar och en med sine värjo i handene; och hvilken som går in i huset, han dräpes; och de skola vara när Konungenom, då han går ut och in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Och Leviterna, med hela Juda, gjorde såsom Presten Jojada budit hade. Och hvar och en tog sina män, som på Sabbathen uppå gingo, med dem som på Sabbathen af gingo: ty Presten Jojada lät icke komma de två hoparna ifrå hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Och Presten Jojada fick öfverstarna öfver hundrade spetsar och sköldar, och Konung Davids vapen, som i Guds hus voro:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Och ställde allt folket, hvar och en med sine värjo i handene, ifrå det högra hörnet i husena allt intill det venstra hörnet, till altaret, och till huset omkring Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Och de hade fram Konungens son, och satte krono uppå honom, och vittnesbördet, och gjorde honom till Konung. Och Jojada med hans söner smorde honom, och sade: Lycka ske Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Då Athalia hörde ropet af folket, som tillopp och lofvade Konungen, gick hon till folket i Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Och hon fick se, och si, Konungen stod i sitt rum i ingångenom, och öfverstarna och trummeterna omkring Konungen; och allt landsfolket var gladt, och blåste med trummeter, och sångarena med allahanda strängaspel skickade till att lofva. Då ref hon sin kläder, och sade: Uppror, uppror.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Men Presten Jojada drog sig ut med de öfversta öfver hundrade, som öfver hären voro, och sade till dem: Hafver henne utu huset i gården; och hvilken henne efterföljer, honom skall man dräpa med svärd. Förty Presten hade befallt, att man icke skulle dräpa henne i Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Och de togo fatt på henne. Och då hon kom till hästaportens ingång, vid Konungshuset, dråpo de henne der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Och Jojada gjorde ett förbund emellan sig, och allt folket, och Konungen, att de skulle vara Herrans folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Då gick allt folket uti Baals hus, och bröto det neder, och slogo sönder hans altare och beläte, och slogo ihjäl Matthan, Baals Prest, inför altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Och Jojada beställde ämbeten i Herrans hus, under Presterna, Leviterna, som David förskickat hade till Herrans hus, till att göra bränneoffer Herranom, såsom skrifvet står i Mose lag, med fröjd och sånger, som David diktat hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Och ställde dörravaktare vid dörrarna åt Herrans hus, att der skulle intet orent inkomma i någon måtto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Och han tog de öfversta öfver hundrade, och de mägtiga, och herrarna i folkena, och allt landsfolket, och hade Konungen neder ifrå Herrans hus; och förde honom in genom den höga porten af Konungshuset, och läto Konungen sätta sig på Konungsstolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Och allt landsfolket, var gladt, och staden var stilla; men Athalja varat dråpen med svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas var sju år gammal, då han Konung vardt, och regerade fyratio år i Jerusalem. Hans moder het Zibja af BerSeba.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Och Joas gjorde det Herranom väl behagade, så länge Presten Jojada lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Och Jojada tog honom två hustrur, och han födde söner och döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Derefter tog Joas till att förnya Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Och församlade Prester och Leviter, och sade till dem: Farer ut till alla Juda städer, och församler penningar utaf hela Israel, till att förbättra edars Guds hus årliga, och skynder eder till att göra så; men Leviterna fördröjde dermed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Då kallade Konungen Jojada den yppersta, och sade till honom: Hvi hafver du icke akt på Leviterna, att de låta införa af Juda och Jerusalem den hjelpeskatten, som Mose Herrans tjenare påbudit hade, att samkas skulle i Israel, till vittnesbördsens tabernakel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Förty den ogudaktiga Athalia och hennes söner hafva förderfvat Guds hus; och allt det som till Herrans hus helgadt var, hafva de lagt till Baalim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Så befallde Konungen, att man skulle göra ena kisto; och de satte henne utantill vid dörrena af Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Och lät utropa i Juda och Jerusalem, att man skulle införa Herranom den hjelpeskatten, som Guds tjenare Mose på Israel lagt hade i öknene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Då fröjdade sig alle öfverstar, och allt folket, och gjorde tillhopa, och lade i kistona, intilldess hon full vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Och då tid var att kistan skulle hafvas fram af Leviterna, efter Konungens befallning, då de sågo, att der många penningar uti voro, så kom Konungens skrifvare, och den som af öfversta Prestenom befallning hade, och tömde kistona, och båro henne i sitt rum igen. Så gjorde de hvar dag, tilldess de samkade en ganska stor hop penningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Och Konungen och Jojada fingo det arbetarena, som skaffare voro på Herrans hus; de samme lejde stenhuggare och timbermän, till att förnya Herrans hus, desslikes de mästare på jern och koppar, till att bättra Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Och arbetsmännerna arbetade, så att förbättringen på verket gick fram genom deras hand, och läto Guds hus komma sig till igen, och gjorde det fast.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Och då de hade det lyktat, båro de penningarna, som öfver voro, in för Konungen och Jojada; deraf gjordes käril till Herrans hus, käril till tjensten, och till bränneoffer, skedar, och gyldene silfvertyg. Och de offrade bränneoffer vid Herrans hus framgent, så länge Jojada lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Och Jojada vardt gammal och mätt af ålder, och blef död, och var hundrade och tretio år gammal, då han blef död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Och de begrofvo honom uti Davids stad, ibland Konungarna, derföre att han hade gjort väl med Israel, och med Gud och hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Efter Jojada död kommo de öfverste i Juda, och tillbådo Konungen; då hörde Konungen dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Och de öfvergåfvo Herrans deras faders Guds hus, och tjente lundom och afgudom; så kom vrede öfver Juda och Jerusalem för dessa deras brotts skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Och han sände Propheter till dem, att de skulle omvända sig till Herran. Och de betygade dem; men de hörde dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Och Guds Ande utiklädde Sacharia, Jojada Prostens son. Han steg fram för folket, och sade till dem: Detta säger Gud: Hvi öfverträden I Herrans bud, det eder icke väl bekommandes varder? Efter I hafven öfvergifvit Herran, så varder han ock öfvergifvandes eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Men de gjorde ett förbund emot honom, och stenade honom, efter Konungens bud, i gårdenom för Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Och Konung Joas tänkte intet på den barmhertighet, som Jojada hans fader med honom gjort hade, utan drap hans son; men då han blef död, sade han: Herren varder detta seendes och sökandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Och då året var omgånget, drog upp de Syrers här, och kommo i Juda och Jerusalem, och förgjorde alla öfverstar i folkena; och allt deras rof sände de till Konungen i Damascon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Ty de Syrers magt kom med fögo folk, likväl gaf Herren i deras hand en ganska stor magt, derföre att de Herran deras fäders Gud öfvergifvit hade; desslikes lade de ock straff på Joas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Och då de drogo ifrå honom, läto de honom qvar i stora krankhet. Och hans tjenare gjorde ett förbund emot honom, för Prestens Jojada söners blods skull, och dråpo honom på hans säng, och han blef död; och man begrof honom uti Davids stad, dock icke ibland Konungagrifterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'De som förbundet gjorde emot honom voro desse: Sabad, Simeaths son, den Ammonitiskones, och Josabad, Simriths son, den Moabitiskones.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Men hans söner, och summan som under honom församlad var, och Guds hus byggning, si, de äro beskrifne uti Historien i Konungabokene. Och hans son Amazia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Fem och tjugu åra gammal var Amazia, då han Konung vardt, och regerade nio och tjugu år i Jerusalem; hans moder het Joaddan af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Och han gjorde det Herranom väl behagade, dock icke af allt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Då nu hans rike stadfäst var, drap han sina tjenare, som hans fader Konungen slagit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Men deras barn drap han intet; förty det står så skrifvet i lagen i Mose bok, der Herren bjuder och säger: Fäderna skola icke dö för barnen, och icke barnen för fäderna; utan hvar och en skall för sina synd dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Och Amazia församlade Juda, och satte dem efter fadershusen, efter öfverstarna öfver tusende och öfver hundrade, i hela Juda och BenJamin; och talde dem allt ifrå tjugu år, och derutöfver, och fann dem trehundradtusend utvalda, som i här draga kunde, som spjut och sköld föra kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Dertill besoldade han utaf Israel hundradtusend starka krigsmän, för hundrade centener silfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Men en Guds man kom till honom, och sade: Konung, låt icke Israels här komma med dig; förty Herren är icke med Israel, eller med all Ephraims barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ty om du kommer till att bevisa dina dristighet i stridene, så låter Gud dig falla för dina fiendar; förty när Gudi står magten till att hjelpa, och till att stjelpa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amazia sade till Guds mannen: Hvad skall man då göra med de hundrade centener, som jag hafver gifvit de krigsmän af Israel? Guds mannen sade: Herren hafver väl mer än det är, som han dig gifva kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Då skiljde Amazia de krigsmän ifrå, som till honom af Ephraim komne voro, så att de gingo till deras rum igen. Då förgrymmade deras vrede sig svårliga emot Juda, och drogo hem igen illa tillfrids.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Men Amazia var tröst, och förde sitt folk ut, och drog ut i saltdalen, och slog af Seirs barn tiotusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Och Juda barn fångade af dem tiotusend lefvande; dem förde de uppå en bergsklint, och störte dem utför bergsklinten, att de alle sönderkrossades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Men de krigsmän, som Amazia hade ifrå sig sändt, så att de icke drogo med hans folk till stridena, lade sig neder i Juda städer, allt ifrå Samarien intill BethHoron, och slogo af dem tretusend, och togo mycket rof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Och då Amazia igenkom af de Edomeers slagtning, hade han med sig Seirs barnas afgudar, och satte dem sig till gudar, och tillbad dem, och rökte för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Då förgrymmade sig Herrans vrede öfver Amazia, och sände en Prophet till honom. Han sade till honom: Hvi söker du dess folks gudar, som sitt folk intet undsätta kunde ifrå dine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Och då han talade med honom, sade han till honom: Hafver man gjort dig till Konungens råd? Vänd igen; hvi vill du varda slagen? Då vände Propheten igen, och sade: Jag förmärker väl, att Gud hafver i sinnet förderfva dig, efter du detta gjort hafver, och hörer intet mitt råd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Och Amazia, Juda Konung, var till råds, och sände bort till Joas, Joahas son, Jehu sons, Israels Konung, och lät säga honom: Kom, låt oss bese hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Men Joas, Israels Konung, sände till Amazia, Juda Konung, och lät säga honom: Törnebusken i Libanon sände till cedreträt i Libanon, och lät säga honom: Gif dina dotter minom son till hustru; men vilddjuren i Libanon lupo öfver törnebuskan, och trampade honom neder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du menar: Si, jag hafver slagit de Edomeer, der förhäfver sig ditt hjerta utaf, och berömmer sig. Nu sitt hemma; hvi söker du efter olycko, att du må falla, och Juda med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Men Amazia hörde det intet; förty det skedde af Gudi, på det att de skulle varda gifne i fiendahand; derföre, att de de Edomeers gudar sökt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Då drog Joas, Israels Konung, upp, och de besågo hvarannan, han och Amazia, Juda Konung, i BethSemes, som i Juda ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Men Juda vardt slagen för Israel, och flydde, hvar och en i sina hyddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Och Joas, Israels Konung, grep Amazia, Joas son, Joahas sons, Juda Konung, i BethSemes, och förde honom till Jerusalem, och bröt muren neder i Jerusalem, allt ifrån Ephraims port intill hörnporten, fyrahundrade alnar långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Och allt det guld och silfver, och all käril, som för handene voro i Guds hus när ObedEdom, och i fataburenom i Konungshusena, och barnen, tog han till pant med sig till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Och Amazia, Joas son, Juda Konung, lefde efter Joas, Joahas sons, Israels Konungs, död i femton år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Hvad nu mer af Amazia sägande är, både det första och det sista, si, det är skrifvet uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Och ifrå den tiden, att Amazia trädde ifrå Herranom, gjorde de ett förbund emot honom i Jerusalem; men han flydde till Lachis. Då sände de efter honom till Lachis, och dråpo honom der;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Och förde honom med hästar, och begrofvo honom när sina fäder uti Juda stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Då tog hele Juda folk Ussia, som var sexton åra gammal, och gjorde honom till Konung i hans faders Amazia stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Han byggde Eloth, och lät det igenkomma till Juda, sedan Konungen afsomnad var med sina fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sexton åra gammal var Ussia, då han Konung vardt, och regerade tu och femtio är i Jerusalem; hans moder het Jecholia af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Och han gjorde det Herranom väl behagade, såsom hans fader Amazia gjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Och han sökte Gud, så länge Zacharia lefde, den läraren i Guds syner; och så länge han sökte Herren, lät honom Gud väl gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Ty han drog ut, och stridde emot de Philisteer, och bröt neder murarna i Gath, och murarna i Jabne, och murarna i Asdod, och ibland de Philisteer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Ty Gud halp honom emot de Philisteer, emot de Araber, dem i Gurbaal, och emot de Menniter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Och de Ammoniter gåfvo Ussia skänker, och han vardt namnkunnig allt intill der man kommer in i Egypten; ty han vardt ju starkare och starkare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Och Ussia byggde torn i Jerusalem på hörnportenom, och på dalportenom, och på annor hörn, och befäste dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Han byggde ock slott i öknene, och grof många brunnar; ty han hade mycken boskap, både i dalar och slättmark, desslikes åkermän och vingårdsmän på bergen, och på Carmel; förty han hade lust till åkerverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Och Ussia hade en magt till strid, af krigsmän som i här drogo, i tal räknade under Jegiels skrifvarens hand, och Maaseja befallningsmansens, under Hanania hand, den af Konungens öfverstar var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Och talet på de yppersta fäder af de starka örligsmän var tutusend och sexhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Och under deras hand härsmagten trehundradtusend, och sjutusend och femhundrad, skickelige till strid i härskraft, till att hjelpa Konungenom emot fienderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Och Ussia fick dem till hela hären sköldar, spjut, hjelmar, pansar, bågar, och slungor till att kasta sten med;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Och gjorde i Jerusalem bröstvärn konsteliga, som skulle vara på tornen och hörnen, till att der utskjuta med pil och stora stenar. Och hans rykte kom vidt ut, derföre, att honom besynnerliga hulpet vardt, tilldess han mägtig blef.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Och då han var mägtig vorden, hof hans hjerta sig upp till hans förderf; ty han förtog sig på Herranom sinom Gud, och gick in i Herrans tempel, till att röka på rökaltaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Men Asaria Presten gick efter honom, och åttatio Herrans Prester med honom, starke män;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Och stodo emot Konung Ussia, och sade till honom: Det hörer icke dig till, Ussia, att röka för Herranom; utan Prestomen, Aarons barnom, som till att röka helgade äro. Gack härutu helgedomenom; ty du förtager dig, och det kommer dig till ingen äro för Herranom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Men Ussia vardt vred, och hade ett rökelsekar i handene; och som han trätte med Presterna, gick spitelska ut i hans änne, för Presterna i Herrans hus, inför rökaltaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Och Asaria öfverste Presten vände sig till honom, och alle Presterna; och si, då var han spitelsk i hans änne; och de drefvo honom dädan. Skyndade han sig ock sjelf ut; ty hans plåga var af Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Alltså var Konung Ussia spitelsk allt intill sin död, och bodde uti ett fritt hus spitelsk; ty han vardt utdrifven af Herrans hus. Men Jotham hans son stod Konungshuset före, och dömde folket i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Hvad nu mer af Ussia sägande är, både det första och det sista, hafver den Propheten Esaia, Amos son, skrifvit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Och Ussia afsomnade med sina fäder, och de begrofvo honom med sina fäder i åkrenom när Konungagrafvarna; ty de sade: Han är spitelsk. Och Jotham hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotham var fem och tjugu åra gammal, då han Konung vardt, och regerade i sexton år i Jerusalem; hans moder het Jerusa, Zadoks dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Och han gjorde det Herranom väl behagade, såsom hans fader Ussia gjort hade; undantagno, att han icke gick i Herrans tempel. Och folket bar sig ännu illa åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Han byggde den höga porten i Herrans hus, och uppå muren Ophel byggde han mycket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Och byggde städer på Juda berg, och i skogomen byggde han slott och torn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Och han stridde med Ammons barnas Konung; och han vardt dem öfvermägtig; så att Ammons barn gåfvo honom i de samma årena hundrade centen er silfver, tio tusend corar hvete, och tiotusend corar bjugg; så mycket gåfvo ock Ammons barn honom i de andra och tredje årena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Alltså vardt Jotham mägtig; ty han skickade sina vägar för Herranom sinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Hvad nu mer af Jotham sägande är, och alla hans strider, och hans vägar, si, det är skrifvet i Israels och Juda Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Fem och tjugu åra gammal var han, då han Konung vardt; och regerade i sexton år i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Och Jotham afsomnade med sina fader; och de begrofvo honom i Davids stad. Och hans son Ahas vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahas var tjugu åra gammal, då han Konung vardt, och regerade i sexton är i Jerusalem; och gjorde icke det Herranom väl behagade, såsom hans fader David;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Utan han vandrade i Israels Konungars vägar, dertill gjorde han gjuten beläte till Baalim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Och rökte i Hinnoms barnas dal, och brände sina söner upp med eld, efter Hedningarnas styggelse, hvilka Herren för Israels barn fördrifvit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Och offrade, och rökte på höjder, på backar, och under all grön trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Derföre gaf Herren hans Gud honom i Konungens hand af Syrien, så att de slogo honom, och förde bort en stor hop af hans fångna, och läto komma till Damascon. Vardt han ock gifven under Israels Konungs hand, så att han gjorde en stor slagtning på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Ty Pekah, Remalia son, slog af Juda hundrade och tjugu tusend på en dag, som alle dugelige män voro; derföre, att de öfvergåfvo Herran deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Och Sichri, en väldig af Ephraim, drap Maaseja, Konungens son, Asrikam husförstan, och Elkana den yppersta näst Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Och Israels barn förde bort fångna af deras bröder tuhundradtusend qvinnor, söner och döttrar; och togo dertill stort rof af dem, och förde rofvet till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Och var sammastäds en Herrans Prophet, som het Obed. Han gick ut emot hären, som till Samarien kom, och sade till dem: Si, efter Herren edra fäders Gud är vred på Juda, hafver han gifvit dem i edra händer; men I hafven så grufveliga slagit dem ihjäl, att det räcker upp till himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nu menen I undertrycka eder Juda barn, och Jerusalem till trälar och trälinnor; är det nu icke skuld när eder emot Herran edar Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Så hörer mig nu och förer fångarna dit igen, dem I bortfört hafven af edra bröder; ty Herrans vrede förgrymmar sig öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Då hofvo sig upp någre de myndigaste af Ephraims barn, Asaria, Johanans son, Berisha, Mesillemoths son, Jehiskia, Sallums son, och Amasa, Handlat son, emot dem som utu hären kommo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Och sade till dem: I skolen icke hafva dessa fångar hitin; ty I kommen intet annat än skuld på oss för Herranom, på det I skolen desto flera göra våra synder och skulder; här är skuld nog tillförene, och vrede förgrymmar sig öfver Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Då läto de väpnade fångarna och rofvet, inför öfverstarna, och inför hela menighetena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Då stodo de män upp, som nu vid namn nämnde voro, och togo fångarna, och alle de, som ibland dem nakne voro, klädde de, af det röfvadt var. Och då de hade klädt dem, drogo de skor uppå dem, och gåfvo dem mat och dryck, och smorde dem, och förde på åsnar alla dem, som svage voro, och läto komma dem till Jericho palmstaden, till deras bröder; och kommo igen till Samarien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'På samma tiden sände Konung Ahas till Konungarna af Assur, att de skulle hjelpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Och de Edomeer kommo åter pånytt, och slogo Juda, och förde somliga bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Och de Philisteer lade sig neder i de städer på hedene, och sunnan på Juda, och vunno BethSemes, Ajalon, Gederoth och Socho, med dess döttrar, Thimna med dess döttrar, och Gimso med dess döttrar; och bodde deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Ty Herren plågade Juda för Ahas skull, Israels Konungs, derföre, att han hade blottat Juda, och förtog sig emot Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Och emot honom kom ThiglathPilneser, Konungen af Assur; han belade honom; men han kunde icke vinna honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Och Ahas tog en del i Herrans hus, och i Konungshusena, och i de öfverstas, det han gaf Konungenom i Assur; men det halp honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Yttermera, i hans nöd förtog Konung Ahas sig ännu mer emot Herran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Och offrade gudomen i Damasco, som honom slagit hade, och sade: Konungens gudar af Syrien hjelpa honom; derföre vill jag offra dem, att de måga ock hjelpa mig; ändock de voro honom och helo Israel till fall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Och Ahas lade tillhopa de tyg i Guds hus, och slog dem sönder, och lyckte igen dörrarna af Herrans hus, och gjorde sig altare i hvarjo vrå i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Och i Juda städer, både här och der, gjorde han höjder till att röka androm gudom, och rette Herran sina fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Hvad nu mer af honom sägande är, och alla hans vägar, både första och sista, si, det är skrifvet i Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Och Ahas afsomnade med sina fäder, och de begrofvo honom i stadenom i Jerusalem; ty de lade honom icke ibland Israels Konungars grifter. Och hans son Jehiskia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Jehiskia var fem och tjugu åra gammal, då han Konung vardt, och regerade nio och tjugu år i Jerusalem; hans moder het Abija, Zacharia dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Och han gjorde det Herranom väl behagade, såsom hans fader David.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Han lät upp dörrarna på Herrans hus, i första månadenom af första årena sins rikes, och gjorde dem färdiga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Och lät komma derin Presterna och Leviterna, och församlade dem på breda gatone östantill;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Och sade till dem: Hörer härtill, I Leviter: Helger eder nu, på det I mågen helga Herrans edra fäders Guds hus; och hafver ut orenligheten af helgedomenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Ty våre fäder hafva förtagit sig, och gjort det ondt var för Herranom vårom Gud, och hafva öfvergifvit honom; förty de hafva vändt sitt ansigte ifrå Herrans boning, och vändt ryggen till,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Och hafva igenlyckt dörrarna till förhuset, och utsläckt lamporna, och intet rökverk röka låtit, och intet bränneoffer gjort Israels Gudi i helgedomenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Deraf är Herrans vrede kommen öfver Juda och Jerusalem, och han hafver gifvit dem till att förskingras och förödas, så att man hvisslar åt dem, såsom I med edor ögon sen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Ty si, fördenskull äro våre fäder fallne genom svärd; våre söner, döttrar och hustrur äro bortförde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nu hafver jag i sinnet att göra med Herranom Israels Gud ett förbund, att hans vrede och grymhet må vända sig ifrån oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nu, mine söner, varer icke försummelige; ty eder hafver Herren utkorat, att I skolen stå för honom, och att I skolen vara hans tjenare och rökare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Då stodo Leviterna upp, Mahath, Amasai son, och Joel, Asaria son af de Kehathiters barn; men af Merari barn, Kis, Abdi son, och Asaria, Jehaleleels son; af de Gersoniters barn, Joah, Simma son, och Eden, Joahs son;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Och af Elizaphans barn, Simri och Jegiel; af Assaphs barn, Sacharia och Matthania;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Af Hemans barn, Jehiel och Simei; af Jeduthuns barn, Semaja och Usiel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Och de församlade sina bröder, och helgade sig, och gingo in, efter Konungens bud, af Herrans ord, till att rena Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Och Presterna gingo in uti Herrans hus, till att rena det, och lade all den orenhet, som i Herrans tempel funnen vardt, uppå gården åt Herrans hus; och Leviterna togo henne upp, och båro ut i Kidrons bäck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'På första dagen af första månadenom begynte de till att helga sig, och på åttonde dagen i den månaden gingo de uti Herrans förhus, och helgade Herrans hus åtta dagar, och fullkomnade det på sextonde dagen i första månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Och de gingo in till Konung Hiskia, och sade: Vi hafve renat hela Herrans hus, bränneoffrets altare, och all dess tyg; skådobrödens bord, och all dess tyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Och all de kärile, som Konung Ahas, då han Konung var, bortkastat hade, då han syndade; dem hafve vi tillredt och helgat, si, de äro för Herrans altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Då var Konung Jehiskia bittida uppe, och församlade de öfversta i stadenom, och gick upp till Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Och hade fram sju stutar, sju vädrar, sju lamb och sju getabockar, till syndoffer, för riket, för helgedomen, och för Juda. Och han sade till Presterna Aarons barn, att de skulle offra på Herrans altare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Då slagtade de stutarna, och Presterna togo blodet, och stänkte det på altaret; och slagtade vädrarna, och stänkte blodet på altaret; och slagtade lamben, och stänkte blodet på altaret;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Och hade bockarna fram till syndoffer inför Konungen och menighetena, och lade sina händer på dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Och Presterna slagtade dem, och stänkte deras blod på altaret, till att försona hela Israel; ty Konungen hade befallt offra bränneoffer och syndoffer för hela Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Och han satte Leviterna i Herrans hus med cymbaler, psaltare och harpor, såsom David det befallt hade, och Gad, Konungens Siare, och den Propheten Nathan; ty det var Herrans bud igenom hans Propheter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Och Leviterna stodo med Davids strängaspel, och Presterna med trummeter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Och Hiskia bad dem göra bränneoffer på altarena; och som man begynte bränneoffret, begyntes ock på Herrans sång och trummeterna, och med mångahanda Davids, Israels Konungs, strängaspel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Och hela menigheten tillbad; Och sångarenas sång och trummeternas trummetning varade allt intilldess bränneoffret öfverfaret var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Då nu bränneoffret gjordt var, bugade sig Konungen, och alle de som när honom vid handen voro, och tillbådo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Och Konung Jehiskia, med öfverstarna, bad Leviterna lofva Herran, med Davids och den Siarens Assaphs dikt. Och de lofvade honom med glädje; och de böjde sig, och tillbådo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Och Jehiskia svarade, och sade: Nu hafven I fyllt edra händer Herranom; går fram och bärer fram offer och lofoffer till Herrans hus. Och menigheten bar fram offer och lofoffer; och hvar och en af friviljogt hjerta bränneoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Och talet på bränneoffret, som menigheten frambar, var sjutio oxar, hundrade vädrar, och tuhundrad lamb; och allt detta till bränneoffer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Och de helgade sexhundrad oxar, och tretusend får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Men Presterna voro för få, och förmådde icke draga hudena af allo bränneoffrena; derföre togo de sina bröder Leviterna, tilldess det verk öfverståndet vardt, och så länge Presterna helgade sig; förty de Leviter stå lätteligare till att helga, än Presterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Var också bränneoffret mycket, med det feta af tackoffren, och drickoffret till bränneoffret. Alltså vardt ämbetet i Herrans hus redo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Och Jehiskia fröjdade sig med allo folkena, att man var så redo vorden med Gudi; ty det skedde med hastighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Och Jehiskia sände ut till hela Israel och Juda, och skref bref till Ephraim och Manasse, att de skulle komma till Herrans hus i Jerusalem, och hålla Passah Herranom Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Och Konungen höll ett råd med sina öfversta, och med hela menighetene i Jerusalem, till att hålla Passah i dem andra månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Förty de kunde icke hålla det på den samma tiden, derföre att Presterna icke nog helgade voro, och folket icke ännu tillhopakommet var till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Och det täcktes Konungenom väl, och hela menighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Och de beställde, att det så utropadt vardt i hela Israel, ifrå BerSeba allt intill Dan, att de skulle komma och hålla Passah Herranom Israels Gud i Jerusalem; ty de hade i långan tid icke hållit det, såsom det skrifvet står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Och båden gingo åstad med brefven ifrå Konungens och hans öfverstars hand, igenom hela Israel och Juda, efter Konungens befallning, och sade: I Israels barn, vänder eder om till Herran, Abrahams, Isaacs och Israels Gud, så varder han sig vändandes till de undsluppna, som ännu återlefde äro ifrå Konungens hand i Assur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Och varer icke såsom edre fäder och bröder, som sig emot Herran deras faders Gud förtagit hafva; och han gaf dem till en förödelse, såsom I sjelfve sen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Så varer nu icke halsstyfve, såsom edra fäder; utan räcker Herranom edra hand, och kommer till hans helgedom, den han helgat hafver till evig tid; och tjener Herranom edrom Gud, så vänder sig hans vredes grymhet ifrån eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Förty, om I omvänden eder till Herran, så skola edra bröder och barn få barmhertighet för dem som dem fångna hålla, så att de skola komma åter i detta land igen; ty Herren edar Gud är nådelig och barmhertig, och varder icke vändandes sitt ansigte ifrån eder, om I omvänden eder till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Och båden gingo ifrå den ena staden till den andra, i Ephraims och Manasse land, och allt intill Sebulon; men de gjorde gabb utaf dem, och bespottade dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Dock någre af Asser, och Manasse, och Sebulon, ödmjukade sig, och kommo till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Kom också Guds hand i Juda, så att han gaf dem endrägtigt hjerta, till att göra efter Konungens och de öfverstars bud, efter Herrans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Och kom samman i Jerusalem en stor hop folk, till att hålla osyrade bröds högtidena i dem andra månadenom, en mägta stor menighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Och de stodo upp, och kastade bort de altare, som i Jerusalem voro, och allt rökverk hofvo de bort och kastade uti den bäcken Kidron;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Och slagtade Passah på fjortonde dagen af den andra månaden; och Presterna och Leviterna blygdes, och helgade sig, och båro bränneoffer till Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Och stodo i deras ordning, såsom det sig borde, efter Mose den Guds mansens lag; och Presterna stänkte blodet af Leviternas hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Ty der voro månge i menighetene, som sig icke helgat hade; derföre slagtade Leviterna Passah för alla dem som icke rene voro, så att de Herranom helgade vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Var ock desslikes mycket folk af Ephraim, Manasse, Isaschar och Sebulon, som icke rene voro; utan åto Passahlambet, icke såsom skrifvet står; ty Jehiskia bad för dem, och sade: Herren, som milder är, varder dem allom nådelig,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Som ställa sitt hjerta till att söka Herran Gud, deras fäders Gud, och icke för den helga renselsens skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Och Herren hörde Jehiskia, och helade folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Alltså höllo Israels barn, som i Jerusalem funne vordo, osyrade bröds högtidena i sju dagar, med stora fröjd. Och Leviterna och Presterna lofvade Herran hvar dag, med Herrans mägtiga strängaspel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Och Jehiskia talade hjerteliga med alla Leviterna, som ett godt förstånd hade om Herran; och de åto öfver hela högtidena i sju dagar, och offrade, och tackade Herranom deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Och hela menigheten vardt till råds, att hålla det ännu i andra sju dagar, och höllo också de sju dagarna med glädje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Ty Hiskia, Juda Konung, gaf till häfoffer för menighetena tusende stutar, och sjutusend får; men de öfverste gåfvo till häfoffer för menighetene tusende stutar och tiotusend får; alltså helgade sig då månge Presterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Och gladdes hela menigheten Juda, Presterna och Leviterna, och hela menigheten, som af Israel kommen var, och främlingarna, som af Israels land komne voro, och de som i Juda bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Och var en stor glädje i Jerusalem; ty ifrå Salomos, Davids sons, Israels Konungs tid, hade sådana icke varit i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Och Presterna och Leviterna stodo upp, och välsignade folket; och deras röst vardt hörd, och deras bön kom inför hans helga boning i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Då detta alltså uträttadt var, drogo ut alle de Israeliter, som i Juda städer funne voro, och bröto ned stoderna, och höggo bort lundarna, och bröto ned höjderna och altaren, i hela Juda, BenJamin, Ephraim och Manasse, tilldess de gjorde en ända på dem. Och Israels barn drogo alle till sina ägor i sina städer igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Men Jehiskia ställde Presterna och Leviterna uti deras ordning, hvar och en efter sitt ämbete, både Prester och Leviter, till bränneoffer och tackoffer, att de skulle tjena, tacka och lofva, i portarna åt Herrans lägre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Och Konungen gaf sin del af sina håfvor till bränneoffer, om morgon och om afton, och till bränneoffer om Sabbatherna, och nymånadom, och högtidom, efter som skrifvet står i Herrans lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Och han sade till folket, som i Jerusalem bodde, att de skulle gifva Presterna och Leviterna delar, att de måtte desto bättre akta på Herrans lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Och då det talet kom ut, gåfvo Israels barn mycken förstling af säd, vin, oljo, hannog och allahanda årsväxt på markene; och allahanda tiond förde de in, ganska mycket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Förde också Israels barn och Juda, som i Juda städer bodde, tiond fram af fä och får, och tiond af det helgada som de Herranom sinom Gud helgat hade, och lade en hop här, och en hop der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Uti tredje månadenom begynte de att lägga hoparna, och i sjunde månadenom lyktade de det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Och då Jehiskia med de öfversta ingingo, och sågo hoparna, lofvade de Herran, och hans folk Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Och Jehiskia frågade Presterna och Leviterna om hoparna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Och Asaria Presten, den ypperste i Zadoks hus, sade till honom: Ifrå den tid man begynte införa häfoffret i Herrans hus, hafve vi ätit och äre mätte vordne, och här är ännu mycket qvart; förty Herren hafver välsignat sitt folk; derföre är denne hopen öfverblefven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Då befallde Konungen, att de skulle reda till kistor i Herrans hus; och de tillredde dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Och lade derin häfoffret, tionden, och det helgada, på sina tro. Och öfver det samma var skickad Chanania den Leviten, och Simei hans broder den andre;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Och Jehiel, Asasia, Nahath, Asahel, Jerimoth, Josabad, Eliel, Jismacha, Mahath och Benaja, förskickade af Chanania och Simei hans broders hand, efter Konungens Jehiskia befallning. Men Asaria var öfverste i Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Och Kore, Jimna son, den Leviten, den dörravaktaren östantill, var öfver de friviljoga Guds gåfvor, som Herranom till häfoffer gifna vordo, och öfver det aldrahelgasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Och under hans hand voro Eden, Minjamin, Jesua, Semaja, Amaria och Sechania, uti Presternas städer, på sina tro; att de skulle gifva sina bröder efter deras ordning, dem minsta såsom dem största;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Desslikes dem som för manspersoner räknade vordo, tre åra gamle, och derutöfver, ibland alla dem som uti Herrans hus gingo, hvar på sin dag till sitt ämbete, och i sine vakt efter sitt skifte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Sammalunda dem som för Prester räknade vordo, i deras fäders hus, och Leviterna, ifrå tjugu är och derutöfver, i deras vakt efter deras skifte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Dertill dem som räknade vordo ibland deras barn, hustrur, söner och döttrar, i hela menighetene; förty de helgade på sina tro det helgada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Voro också män vid namn nämnde ibland Aarons barn, Presterna uppå förstädernes mark, i alla städer, att de skulle del gifva alla manspersoner ibland Presterna, och allom dem som ibland Leviterna räknade vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Alltså gjorde Jehiskia i hela Juda, och gjorde det godt, rätt och sant var för Herranom sinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Och i all handel, som han tog sig före med Guds hus tjenste, efter lagen och buden, till att söka sin Gud, det gjorde han af allt hjerta; derföre gick han det ock väl igenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Efter denna handel och trohet kom Sanherib, Konungen i Assur, och drog in i Juda, och lägrade sig för de fasta städer, och hade i sinnet, att han ville taga det in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Då Jehiskia såg, att Sanherib kom, och hans ansigte stod till att strida emot Jerusalem,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Vardt han till råds med sina öfversta och väldiga, att de skulle öfvertäcka vattnen af källorna, som utanför staden voro; och de hulpo honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Och sig församlade mycket folk, och öfvertäckte alla källor och bäcker midt i landena, och sade, att de Konungar af Assur icke skola mycket vatten finna, när de komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Och han tog styrko till sig, och byggde igen alla murar, som förfallne voro, och gjorde torn deruppå; och byggde ändå derutanföre en annan mur. Och Millo gjorde han fast i Davids stad, och lät göra många värjor och sköldar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Och skickade höfvitsmän till strids med folket; och han församlade dem till sig på den breda gatona vid stadsporten, och talade hjerteliga till dem, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Varer tröste och vid godt mod; frukter eder intet, och gifver eder intet för Konungenom af Assur, eller för all den hop, som när honom är; ty med oss är en större än med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Med honom är en köttslig arm; men med oss är Herren vår Gud, att han skall hjelpa oss, och föra våra strid. Och folket förlät sig på Jehiskia, Juda Konungs, ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Derefter sände Sanherib, Konungen i Assur, sina tjenare till Jerusalem, ty han låg för Lachis, och all hans magt med honom, till Jehiskia, Juda Konung, och till hela Juda, som i Jerusalem var, och lät säga honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Detta säger Sanherib, Konungen i Assur: Hvar förtrösten I eder uppå, I som bon uti det belagda Jerusalem?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Jehiskia förförer eder, att han må komma eder i döden, hunger och törst, och säger: Herren vår Gud skall undsätta oss utu Konungens hand af Assyrien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Är icke han den Jehiskia, som hans höjder och altare bortkastat hafver, och sagt till Juda och Jerusalem: För ett altare skolen I tillbedja, och deruppå röka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Veten I icke, hvad jag och mine fäder gjort hafva allom folkom i landen? Hafva ock Hedningarnas gudar i landen kunnat hjelpa deras land ifrå mine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Hvilken är den af alla dessa Hedningarnas gudar, som mina fäder nederlagdt hafva, som hafver kunnat hjelpa sitt folk utu mine hand; att edar Gud skulle förmå hjelpa eder utu mine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Så låter icke nu Hiskia bedraga eder, och låter icke tälja eder i sådant sinne, och tror honom intet; förty, medan ingen alla Hedningars och Konungarikens gud hafver kunnat hjelpa sitt folk ifrå mine och mina fäders hand, så varda icke heller edre gudar eder hjelpande ifrå mine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Dertill talade hans tjenare ännu mer emot Herran Gud, och emot hans tjenare Jehiskia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Skref han ock bref ut, deruti han hädde Herran Israels Gud, och talade om honom, och sade: Såsom Hedningarnas gudar i landen icke hafva hulpit deras folk ifrå mine hand, så varder ock icke Jehiskia Gud hjelpandes hans folk ifrå mine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Och de ropade med höga röst, på Judiskt mål, till folket i Jerusalem, som på muren voro, till att göra dem rädda och förskräckta, att de så måtte få staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Och talade de så emot Jerusalems Gud, såsom emot folkens gudar på jordene, hvilke menniskos handaverk voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Men Konung Jehiskia med Prophetenom Esaia, Amos son, bådo deremot, och ropade till himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Och Herren sände en Ängel, som förgjorde alla de väldiga i hären, och Förstarna och öfverstarna i Konungens lägre af Assyrien; så att han med skam drog åter till sitt land igen. Och då han gick uti sins guds hus, dråpo honom der med svärd, de som af hans eget lif komne voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Alltså halp Herren Jehiskia, och dem i Jerusalem, utu Sanheribs hand, Konungens i Assyrien, och alla andras; och bevarade dem för allom omkring;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Så att månge båro skänker Herranom till Jerusalem, och klenodier Jehiskia, Juda Konung. Och han vardt sedan högt räknad för alla Hedningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'På den tiden vardt Jehiskia dödsjuk, och han bad Herran; han hörde honom, och gaf honom ett tecken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Dock vedergalt icke Jehiskia, efter som honom gifvet var; ty hans hjerta upphof sig; derföre kom vrede öfver honom, och öfver Juda, och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Men Jehiskia ödmjukade sig, att hans hjerta hade upphäfvit sig, samt med dem i Jerusalem; derföre kom Herrans vrede icke öfver dem, så länge Jehiskia lefde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Och Jehiskia hade ganska stora rikedomar och härlighet; och han gjorde sig en skatt af silfver, guld, ädla stenar, örter, sköldar och allahanda kostelig tyg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Och hus till inkommandes årsväxt, vin och oljo; och stall för allahanda boskap, och hus för får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Och han byggde sig städer, och hade boskap, får och fä till en stor hop; förty Gud gaf honom ganska många ägodelar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Han är den Jehiskia, som igentäppte den öfra vattukällona i Gihon, och ledde henne nedåt, vester om Davids stad. Och var Jehiskia lyckosam i alla sina gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Men då de öfverstars sändningabåd af Babel till honom sände voro, att fråga efter det undertecken, som i landena skedt var, öfvergaf Gud honom, så att han försökte honom; på det att kunnigt skulle varda allt det i hans hjerta var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Hvad nu mer af Jehiskia sägande är, och om hans barmhertighet, si, det är skrifvet i den Propheten Esaia, Amos sons, syn, uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Och Jehiskia afsomnade med sina fäder, och de begrofvo honom öfver Davids barnas grifter; och hele Juda och de i Jerusalem gjorde honom äro i hans död. Och hans son Manasse vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse var tolf åra gammal, då han Konung vardt, och regerade fem och femtio år i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Och gjorde det ondt var för Herranom, efter Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Och han afvände sig, och uppbyggde höjder, som hans fader Jehiskia nederslagit hade, och stiktade altare till Baalim, och gjorde lundar, och tillbad allan himmelens är, och tjente dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Han byggde ock altare i Herrans hus, om hvilket Herren sagt hade: I Jerusalem skall mitt Namn vara i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Och han byggde altare till allan himmelens här, i båda gårdarna åt Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Och han lät sina söner gå genom eld uti Hinnoms sons dal, och utvalde dagar, och aktade på foglarop, och brukade trolldom, och stiktade spåmän och tecknatydare, och gjorde mycket det Herranom illa behagade, till att reta honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Han satte desslikes beläte och afgudar, som han i Guds hus göra lät, der Gud om sagt hade till David, och hans son Salomo: Uti detta hus, i Jerusalem, som jag utvalt hafver för alla Israels slägter, vill jag sätta mitt Namn i evig tid;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Och skall icke mer låta Israels fot vika ifrå landena, som jag deras fäder beställt hafver; så framt de hålla sig, så att de göra allt det jag dem budit hafver, i all lag, bud och rätter, igenom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Men Manasse förförde Juda och dem i Jerusalem, så att de gjorde värre än Hedningarna, som Herren för Israels barn förgjort hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Och när Herren lät tala till Manasse och hans folk, aktade de det intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Derföre lät Herren komma öfver dem de öfverstar öfver Konungens här i Assur; de togo Manasse fången i fjettrar, och bundo honom med kedjor, och förde honom till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Och som han var i ångest, bad han Herran sin Gud, och ödmjukade sig storliga för sina fäders Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Och bad honom innerliga. Då hörde han hans bön, och lät honom komma till Jerusalem igen till sitt rike. Och besinnade då Manasse, att Herren är Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Derefter byggde han de yttersta murarna till Davids stad, vestantill vid Gihon i bäckenom, och der man ingår genom fiskaporten, och allt omkring intill Ophel, och gjorde dem ganska höga; och satte höfvitsmän uti Juda fasta städer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Och kastade bort de främmande gudar och afgudar utu Herrans hus, och all altare, som han byggt hade på Herrans hus berg, och i Jerusalem, och kastade dem ut för staden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Och uppfärdade Herrans altare, och offrade deruppå tackoffer och lofoffer, och befallde Juda, att de skulle tjena Herranom Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Likväl offrade folket ännu på höjderna; dock Herranom deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Hvad nu mera af Manasse sägande är, och om hans bön till sin Gud, och om de ord, som Siarena med honom talade i Herrans Israels Guds Namn, si, det är ibland Israels Konungars gerningar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Och om hans bön, och huru han bönhörd vardt, och alla hans synder och missgerningar, och rummet, der han höjder uppå byggde, och lundar och afgudar stiktade, förr än han ödmjukad vardt, si, det är allt skrifvet ibland Siarenas gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Och Manasse afsomnade med sina fäder, och de begrofvo honom i hans hus; och hans son Amon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Tu och tjugu år gammal var Amon, då han Konung vardt, och regerade tu år i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Och gjorde det ondt var för Herranom, såsom hans fader Manasse gjort hade; och Amon offrade allom afgudom, som hans fader Manasse gjort hade, och tjente dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Men han ödmjukade sig intet för Herranom, såsom hans fader Manasse sig ödmjukat hade; ty denne Amon förökade skuldena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Och hans tjenare gjorde ett förbund emot honom, och dråpo honom i hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Då slog folket i landena alla dem som förbundet emot Konung Amon gjort hade; och folket i landena gjorde hans son Josia till Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'ÅÅtta åra gammal var Josia, då han Konung varat, och regerade ett och tretio är i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Och gjorde det godt var för Herranom, och vandrade uti sins faders Davids vägom, och vek hvarken på den högra eller venstra sidona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Ty i åttonde årena af sitt rike, medan han ännu en dräng var, begynte han att söka sins faders Davids Gud. Och i tolfte årena begynte han till att rensa Juda och Jerusalem af höjder, och lundar, och af gudar, och gjuten beläte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Och lät afbryta för sig Baalims altare; och beläten deruppå högg han neder; och de lundar, och afgudar, och beläte, slog han sönder, och gjorde dem till stoft, och strödde dem på deras grifter, som för dem offrat hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Och brände upp Presternas ben på altaren, och rensade alltså Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Sammalunda i Manasse städer, Ephraim, Simeon, och allt intill Naphthali, uti deras ökner, allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Och då han hade afbrutit altaren och lundarna, och afgudarna sönderkrossat, och all beläte sönderslagit i hela Israels land, drog han åter till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Uti adertonde årena sins rikes, då han landet och huset renat hade, sände han Saphan, Azalia son, och Maaseja stadsfogdan, och Joah. Joahas son, cancelleren, till att förbättra Herrans sins Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Och de kommo till den öfversta Presten Hilkia, och man fick dem de penningar, som till Guds hus införde voro, hvilka Leviterna, som dörrarna vaktade, församlat hade, af Manasse, Ephraim, och af allom igenlefdom i Israel, och af hela Juda och BenJamin, och af dem som i Jerusalem bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Och de gåfvo dem uti arbetarenas händer, som beställde voro till Herrans hus; och de gåfvo dem som arbetade på Herrans hus, der det förfallet var, att de skulle förbättra huset. Och Saphan bar henne till Konungen, och gaf Konungenom svar igen, och sade: Allt det i dina tjenares händer befaldt är, det göra de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'De samme gåfvo dem sedan timbermannom och byggningsmannom, till att köpa huggen sten, och höfladt trä till bjelkar, på de hus, som Juda Konungar förderfvat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Och männerna arbetade på verket på sina tro; och öfver dem voro skickade Jahath, och Obadja, Leviter, utaf Merari barn; Sacharia och Mesullam, utaf de Kehathiters barn, till att drifva arbetet; och voro alle Leviter, som på strängaspel kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Men öfver dragare, och dem som drefvo till allahanda arbete i all ämbeten, voro utaf Leviterna, skrifvare, ämbetsmän och dörravaktare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Och då de togo ut penningarna, som i Herrans hus inlagde voro, fann Hilkia Presten lagbokena, som Herren genom Mose gifvit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Och Hilkia svarade, och sade till Saphan skrifvaren: Jag hafver funnit lagbokena i Herrans hus. Och Hilkia fick Saphan bokena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Och de penningar, som i Herrans hus funne äro, hafva de lagt ihop, och fått dem föreståndarenom och arbetaromen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Och Saphan skrifvaren underviste Konungen, och sade: Hilkia Presten hafver fått mig ena bok. Och Saphan las deruti för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Och då Konungen hörde lagsens ord, ref han sin kläder sönder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Och Konungen böd Hilkia, och Ahikam, Saphans son, och Abdon, Micha son, och Saphan skrifvarenom, och Asaja, Konungens tjenare, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Går bort, och fråger Herran för mig, och för dem som qvare äro i Israel, och för Juda, om bokens ord, som funnen är; förty Herrans grymhet är stor, som öfver oss upptänd är, att våre fäder icke hållit hafva Herrans ord, att de måtte gjort såsom i desso bok skrifvet står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Då gick Hilkia, samt med de andra, som af Konungenom sände voro, bort till den Prophetissan Hulda, Sallums hustru, Thakehaths sons, Hasra sons, klädevaktarens, som i Jerusalem bodde, uti den andra delenom, och talade detta med henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Och hon sade till dem: Detta säger Herren Israels Gud: Säger dem mannenom, som eder till mig sändt hafver:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Detta säger Herren: Si jag skall låta komma olycko öfver detta rum, och dess inbyggare, nämliga all de förbannelse, som i bokene skrifven stå, som för Juda Konung läsen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Derföre, att de hafva öfvergifvit mig, och rökt androm gudom, så att de hafva rett mig med allt deras händers verk; och min grymhet skall upptänd varda öfver detta rum, och icke utsläckt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Och Juda Konunge, som eder utsändt hafver till att fråga Herran, skolen I så säga: Detta säger Herren Israels Gud, om de ord, som du hörde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Derföre, att ditt hjerta hafver bevekt sig, och du hafver ödmjukat dig för Gudi, då du hans ord hörde emot detta rum, och emot dess inbyggare, och hafver ödmjukat dig för mig, och rifvit din kläder, och gråtit för mig; så hafver jag ock hört dig, säger Herren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Si, jag vill samka dig till dina fader, att du uti dina graf med frid samkad varder, att din ögon icke skola se all denna olyckon, som jag öfver detta rum och dess inbyggare skall komma låta. Och de sade Konungenom detta igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Då sände Konungen bort, och lät tillhopakomma alla de äldsta i Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Och Konungen gick upp i Herrans hus, och hvar man i Juda, och inbyggarena i Jerusalem, Presterna, Leviterna, och allt folket, både små och store; och vordo för deras öron läsen all ord i förbundsens bok, som i Herrans hus funnen var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Och Konungen gick i sitt rum, och gjorde ett förbund för Herranom, att man skulle vandra efter Herranom, till att hålla hans bud, vittnesbörd och rätter, af allt hjerta, och af allo själ, till att göra efter all förbundsens ord, som skrifne stodo i desso bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Och stodo der alle de, som i Jerusalem och i BenJamin för handene voro. Och Jerusalems inbyggare gjorde efter Guds förbund, deras fäders Guds.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Och Josia hof bort all styggelse utur all land, som Israels barnas voro, och skaffade att alle de, som i Israel funne vordo, tjente Herranom deras Gud. Så länge Josia lefde, veko de intet ifrå Herranom deras fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Och Josia höll Herranom Passah i Jerusalem; och slagtade Passah på fjortonde dagenom i första månaden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Och han ställde Presterna uti deras vakt, och styrkte dem till deras ämbete i Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Och sade till Leviterna, som hela Israel lärde, och Herranom helgade voro: Låter den helga arken uti huset, som Salomo, Davids son, Israels Konung, byggt hafver; I skolen icke bära honom på axlarna; så tjener nu Herranom edrom Gud, och hans folke Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Och skicker edra fäders hus, i edor skifte, såsom de beskrifne äro af David, Israels Konung, och hans son Salomo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Och står i helgedomenom efter fädernas hus skifte ibland edra bröder af folket, och desslikes fädernas hus skifte ibland Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Och slagter Passah, och helger eder, och skicker edra bröder, att de göra efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Och Josia gaf till häfoffer för den meniga man lamb och kid, alltsammans till Passah, för alla dem som vid handena voro, på talet tretiotusend, och tretusend nöt; alltsammans af Konungens ägodelar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Hans Förstar gåfvo till häfoffer friviljoge för folket, och för Presterna och Leviterna; nämliga Hilkia, Sacharia och Jehiel, Förstarna i Guds hus, ibland Presterna till Passah, tutusend och sexhundrad (lamb och kid), dertill trehundrad nöt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Men Chanania, Semaja, Nethaneel, och hans bröder, Hasabia, Jejel och Josabad öfverstar för Leviterna, gåfvo Levitomen häfoffer till Passah, femtusend (lamb och kid), och dertill femhundrad nöt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Alltså vardt Gudstjenst beskickad, och Presterna stodo i sitt rum, och Leviterna i sin ordning, efter Konungens bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Och de slagtade Passah, och Presterna togo af deras händer och stänkte, och Leviterna drogo thy hudena af;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Och gjorde bränneoffer deraf, att de skulle dela det ut ibland fadershusen uti deras meniga hop, till att offrat Herranom, såsom skrifvet står i Mose bok; sammaledes gjorde de ock med oxarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Och de kokade Passah vid eld, såsom det sig borde; men hvad som helgadt var, kokade de i grytor, kettlar och pannor, och de gjorde det med hast för meniga hopen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Derefter redde de ock för sig, och för Presterna; förty Presterna, Aarons söner, hade att skaffa med bränneoffret, och med det feta, allt intill nattena; derföre måste Leviterna tillreda för sig och för Presterna, Aarons söner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Och sångarena, Assaphs barn, stodo i sitt rum, efter Davids bud, och Assaphs, och Hemans, och Jeduthuns, Konungens Siares; och dörravaktarena vid alla dörrarna, och de veko intet ifrå sitt ämbete; ty Leviterna, deras bröder, redde till för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Alltså vardt beskickad all Herrans tjenst på den dagen, så att man höll Passah, och bränneoffer gjorde på Herrans altare, efter Konung Josia bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Alltså höllo Israels barn, som vid handen voro, Passah i den tiden, och osyrade bröds högtid i sju dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Intet Passah var i Israel hållet, såsom detta, allt ifrå den Propheten Samuels tid; och ingen Israels Konung hade sådant Passah hållit, såsom Josia Passah höll, och Presterna, Leviterna, hela Juda och det af Israel för handen var, och Jerusalems inbyggare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Uti adertonde årena af Josia rike vardt detta Passah hållet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Derefter, när Josia huset tillredt hade, drog Necho, Konungen i Egypten, upp, till att strida emot Carchemis vid Phrath; och Josia drog ut emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Men han sände båd till honom, och lät säga honom: Hvad hafver jag med dig göra, Juda Konung? Jag kommer icke nu emot dig, utan jag strider emot ett (annat) hus; och Gud hafver sagt, att jag skulle skynda mig; håll upp att göra emot Gud, som med mig är, att han icke förderfvar dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Men Josia vände icke sitt ansigte ifrå honom, utan ställde sig till att strida emot honom; och lydde intet Necho ord utaf Guds mun, och kom till att strida med honom på den slättene vid Megiddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Och skyttorna sköto Konung Josia. Och Konungen sade till sina tjenare: Förer mig hädan; ty jag är illa sår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Och hans tjenare togo honom af vagnen, och lade honom på hans andra vagn, och förde honom till Jerusalem. Och han blef död, och vardt begrafven ibland sina fäders grifter; och hele Juda och Jerusalem sörjde för Josia skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Och Jeremia jämrade sig öfver Josia; och alle sångare och sångerskor höllo deras klagovisor öfver Josia, allt intill denna dag, och gjorde en sedvänjo deraf i Israel; si, det är skrifvet uti de klagovisor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Hvad nu mer af Josia sägande är, och om hans barmhertighet, efter skriftene i Herrans lag,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Och hans gerningar, både de första och de sista, si, det är skrifvet uti Israels och Juda Konungars bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Och folket i landena tog Joahas, Josia son, och gjorde honom till Konung i hans faders stad i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Tre och tjugu åra gammal var Joahas, då han Konung vardt och regerade i tre månader i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Ty Konungen i Egypten satte honom af i Jerusalem, och beskattade landet till hundrade centener silfver, och en centener guld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Och Konungen i Egypten gjorde Eliakim, hans broder, till Konung öfver Juda och Jerusalem, och förvände hans namn Jojakim; men Necho tog hans broder Joahas, och förde honom uti Egypten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Fem och tjugu åra gammal var Jojakim, då han Konung vardt; och regerade ellofva år i Jerusalem, och gjorde det ondt var för Herranom sinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Och NebucadNezar, Konungen i Babel, drog upp emot honom, och band honom med kedjor, att han skulle föra honom till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Och förde NebucadNezar någor Herrans hus kärile till Babel, och satte dem uti sitt tempel i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Hvad nu mer af Jojakim sägande är, och hans styggelse, som han gjorde, och med honom funnen vordo, si, de äro skrifne uti Israels och Juda Konungars bok: och hans son Jojachin vardt Konung i hans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Åtta åra gammal var Jojachin, då han Konung vardt, och regerade i tre månader och tio dagar i Jerusalem, och gjorde det Herranom illa behagade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Då nu året omgick, sände NebucadNezar, och lät hemta honom till Babel, med de kosteliga tygen i Herrans hus; och man gjorde Zedekia hans broder till Konung öfver Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Ett och tjugu åra gammal var Zedekia, då han Konung vardt; och regerade ellofva är i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Och gjorde det ondt var för Herranom sinom Gud, och ödmjukade sig intet för den Propheten Jeremia, som talade utaf Herrans mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Dertill vardt han affällig ifrå NebucadNezar, Konungenom i Babel, hvilken af honom en ed vid Gud tagit hade; och vardt halsstyf, och förstockade sitt hjerta, så att han intet omvände sig till Herran Israels Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Sammalunda alle öfverstarna ibland Presterna, samt med folket, syndade svårliga, och förtogo sig med allahanda Hedningastyggelse, och orenade Herrans hus, det han helgat hade i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Och Herren deras fäders Gud sände till dem med sin bådskap bittida; ty han skonade sitt folk och sina boning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Men de begabbade Guds bådskap, och föraktade hans ord, och bespottade hans Propheter, intilldess Herrans grymhet växte öfver hans folk, att dem nu intet mer stod till botande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Ty han förde öfver dem de Chaldeers Konung, och lät dräpa deras unga män med svärd, uti deras helgedoms huse, och skonade hvarken piltar eller pigor, hvarken åldrigom eller utgamlom; alla gaf han dem i hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Och all tyg i Guds hus, stor och små, håfvorna i Herrans hus, och Konungens och hans Förstars håfvor; allt lät han föra till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Och de brände upp Guds hus, och bröto ned murarna i Jerusalem; och all deras palats brände de upp med eld, så att all deras kosteliga ting blefvo förfaren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Och de som för svärdet undsluppo, fördes till Babel, och vordo hans och hans söners trälar, tilldess riket kom till de Perser;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'På det att fullkomnas skulle Herrans ord genom Jeremia mun, tilldess att landet hade fyllest i sina Sabbather; förty hele tiden af förderfvelsen var Sabbath, intilldess sjutio år fullkomnade vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Men i första årena Cores, Konungens i Persien, på det fullkomnadt skulle varda Herrans ord, taladt genom Jeremia mun, uppväckte Herren Cores anda, Konungens i Persien, att han lät utropa öfver allt sitt rike, ja ock med bref, och säga:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Detta säger Cores, Konungen i Persien: Herren Gud af himmelen hafver gifvit mig all rike i landen, och hafver befallt mig bygga sig ett hus i Jerusalem i Juda; hvilken som nu ibland eder är af hans folk, med honom vare Herren hans Gud, och drage ditupp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Uti första årena Cores, Konungens i Persien, på det fullkomnas skulle Herrans ord, taladt igenom Jeremia mun, uppväckte Herren Cores anda, Konungens i Persien, att han lät utropa i all sitt rike, och igenom skrifvelse, och säga:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Detta säger Cores, Konungen i Persien: Herren Gud i himmelen hafver gifvit mig all rike i landen, och hafver befallt mig bygga sig ett hus i Jerusalem, i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Hvilken som nu ibland eder är af hans folk, med honom vare hans Gud, och han drage upp till Jerusalem i Juda, och uppbygge Herrans Israels Guds hus; han är den Gud, som i Jerusalem är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Och hvilken som ännu igenlefd är, ehvar som helst han en främling är, honom hjelpe folket i det rum med silfver och guld, med gods och boskap, af en fri vilja, till Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Då stodo upp de öfverste fäder af Juda och BenJamin, och Presterna och Leviterna, alle, hvilkas anda Gud uppväckte till att draga upp, och bygga Herrans hus i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Och alle de som voro omkring dem, styrkte deras hand med silfver och gyldene tyg, med gods och boskap, och klenodier; förutan det de friviljoge gåfvo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Och Konung Cores fick ut Herrans hus kärile, som NebucadNezar utu Jerusalem tagit hade, och låtit lägga uti sins guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Och Konung Cores i Persien fick dem ut igenom Mithredath räntomästaren, och uträknade dem Sesbazar, Förstanom i Juda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Och detta är talet: tretio gyldene bäcken, och tusende silfverbäcken, nio och tjugu knifvar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Tretio gyldene skålar, och de andra silfskålar, fyrahundrad och tio, och annor kärile tusende;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Så att all kärilen både af guld och silfver voro femtusend och fyrahundrad. All dem förde Sesbazar upp, med dem som utu fängelset uppdrogo ifrå Babel till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Desse äro de barn utu landen, som uppdrogo utu fängelset, hvilka NebucadNezar, Konungen i Babel, hade fört till Babel, och igenkommo till Jerusalem och Juda, hvar och en uti sin stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Och kommo med Serubbabel: Jesua, Nehemia, Seraja, Reelaja, Mardechai, Bilsan, Mispar, Bigvai, Rehum, och Baana. Detta är nu talet af männerna i Israels folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paros barn, tutusend hundrade två och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sephatja barn, trehundrad två och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Arahs barn, sjuhundrad fem och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'PahathMoabs barn, utaf Jesua Joabs barnom, tutusend åttahundrad och tolf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sattu barn, niohundrad fem och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Saccai barn, sjuhundrad och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Bani barn, sexhundrad två och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebai barn, sexhundrad tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Asgads barn, tusende tuhundrad två och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikams barn, sexhundrad sex och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvai barn, tutusend sex och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adins barn, fyrahundrad fyra och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aters barn af Jehiskia, åtta och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Bezai barn, trehundrad tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jorahs barn, hundrade och tolf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hasums barn, tuhundrad tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbars barn, fem och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'BethLehems barn, hundrade tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netopha män, sex och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'De män af Anathoth, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Asmaveths barn, två och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'De barn af KiriathArim, Chephira, och Beeroth, sjuhundrad tre och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'De barn af Rama och Gaba, sexhundrad en och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'De man af Michmas hundrade två och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'De män af BethEl och Aj, tuhundrad tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebo barn, två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'De män af Magbis, hundrade sex och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'De andra Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harims barn, trehundrad och tjugu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lod, Hadid och Ono barn, sjuhundrad fem och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jereho barn, trehundrad fem och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Senaa barn, tretusend sexhundrad och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Presterna: Jedaja barn, af Jesua huse, niohundrad tre och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immers barn, tusende två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurs barn, tusende tuhundrad sju och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Horims barn, tusende och sjutton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviterna: Jesua barn, och Kadmiel, af Hodavia barnom, fyra och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Sångarena: Assaphs barn, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Dörravaktarenas barn: Sallums barn, Aters barn, Talmons barn, Akkubs barn, Hatita barn, och Sobai barn; alle tillhopa hundrade nio och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'De Nethinim: Ziha barn, Hasupha barn, Thabaoths barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keros barn, Siaha barn, Padons barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebana barn, Hagaba barn, Akkubs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagabs barn, Samlai barn, Hanans barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddels barn, Gahars barn, Reaja barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Rezins barn, Nekoda barn, Gassams barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Ussa barn, Paseahs barn, Besai barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asna barn, Mennims barn, Nephusims barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbuks barn, Hakupha barn, Harhurs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Bazluts barn, Mehida barn, Harsa barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkos barn, Sisera barn, Thamahs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Neziahs barn, Hatipha barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salomos tjenares barn: Sotai barn, Sopherets barn, Peruda barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaala barn, Darkons barn, Giddels barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sephatja barn, Hattils barn, Pochereths barn af Zebaim, Ami barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Alle Nethinim, och Salomos tjenares barn, voro tillhopa trehundrad två och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Och desse drogo också med upp af ThelMelah, ThelHarsa, Cherub, Addan och Immer; men de kunde icke utvisa sina fäders hus, eller ock sina säd, om de voro af Israel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delaja barn, Tobia barn, Nekoda barn, sexhundrad två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Och af Prestabarnen: Habaja barn, Koz barn, Barsillai barn, den en hustru tog utaf Barsillai den Gileaditens döttrar, och vardt nämnd under deras namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'De samme sökte efter deras börds skrifter, och funno dem intet; derföre vordo de Presterskapet qvitte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Och Thirsatha sade till dem, att de icke skulle äta utaf det aldrahelgasta, tilldess en Prest uppstode med Ljus och Fullkomlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Hela menigheten, såsom en man, var tu och fyratio tusend, trehundrad och sextio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Förutan deras tjenare och tjenarinnor, de voro sjutusend trehundrad sju och tretio; och hade tuhundrad sångare, och sångerskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Sjuhundrad sex och tretio hästar, tuhundrad fem och fyratio mular;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Fyrahundrad fem och tretio camelar, och sextusend sjuhundrad och tjugu åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Och somlige utaf öfversta fäderna, när de kommo till Herrans hus i Jerusalem, vordo de friviljoge till Guds hus, att man skulle det sätta uppå sitt rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Och gåfvo, efter sina förmågo, till drätselen åt verket, ett och sextio tusend gylden, och fem tusend pund silfver, och hundrade Prestakjortlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Alltså satte sig Presterna och Leviterna, och somlige af folket, och sångarena och dörravaktarena, och de Nethinim, uti sina städer; och hele Israel i sina städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Och då sjunde månaden kom, och Israels barn nu voro i sina städer, kom folket tillhopa, såsom en man, till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Och Jesua, Jozadaks son, och hans bröder Presterna, och Serubbabel, Sealthiels son, och hans bröder stodo upp, och byggde Israels Guds altare, till att offra bränneoffer deruppå, såsom skrifvet står i Mose dens Guds mansens lag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Och de satte altaret uppå sin fot; ty en förskräckelse var ibland dem, för folket i landen; och offrade Herranom bränneoffer deruppå om morgon och afton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Och de höllo löfhyddohögtid, såsom det skrifvet står, och gjorde bränneoffer hvar dag, efter det tal som det sig borde, hvar dagen sitt offer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Derefter ock de dageliga bränneoffer, och nymånadas, och alla Herrans högtidsdagars, som helgade voro, och all friviljog offer, som de Herranom friviljeliga gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'På första dagen i sjunde månadenom begynte de att göra Herranom bränneoffer; men grundvalen till Herrans tempel var ännu icke lagd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Men de gåfvo stenhuggarom och timbermannom penningar, och spis, och dryck, och oljo, dem i Zidon och Tyro, att de skulle låta komma cedreträ af Libanon till sjös intill Japho; efter Cores, Konungens af Persien, befallning till dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Uti andro årena, sedan de kommo till Guds hus i Jerusalem, uti dem andra månadenom, begynte Serubbabel, Sealthiels son, och Jesua, Jozadaks son, och de andre af deras bröder, Prester och Leviter, och alle de som af fängelset komne voro till Jerusalem; och skickade Leviterna, allt ifrå tjugu år och derutöfver, att de skulle drifva verket på Herrans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Och Jesua stod, med sina söner och bröder, och Kadmiel, med sina söner, och Juda barn, såsom en man, till att drifva arbetarena på Guds hus; nämliga Henadads barn, med deras barn, och deras bröder Leviterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Och då byggningsmännerna lade grundvalen på Herrans tempel, stodo Presterna klädde, med trummeter, och Leviterna, Assaphs barn, med cymbaler, till att lofva Herran, med Davids dikt, Israels Konungs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Och söngo emot hvarannan, med lof och tacksägelse Herranom, att han god är, och hans barmhertighet varar i evighet öfver Israel. Och allt folket upphof sin röst till Herrans lof, att grunden på Herrans hus lagd var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Men månge af de gamla Prester och Leviter, och öfverste fäder, som det förra huset sett hade i dess grundval, och detta hus var för deras ögon, greto med höga röst; dock upphöjde månge sina röst till glädje;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Så att folket icke kunde känna det glädjerop, för gråtropet i folkena; ty folket ropade högt, så att man hörde ropet långt ifrå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Då nu Juda och BenJamins motståndare hörde, att fängelsens barn byggde Herranom Israels Gud templet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Kommo de till Serubbabel, och till öfversta fäderna, och sade till dem: Vi vilje bygga med eder; förty vi söke edar Gud lika som I; och vi hafve offrat allt ifrå den tid EsarHaddon, Konungen i Assur, förde oss hitupp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Men Serubbabel och Jesua, och de andre öfverste fäder i Israel, svarade dem: Det betämmer sig icke, att vi och I bygge vår Guds hus; utan vi vilje allena bygga Herranom Israels Gud, såsom Cores, Konungen i Persien, budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Då hindrade folket i landena Juda folks hand, och afskräckte dem af byggningene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Och lejde rådgifvare emot dem, och förhindrade deras råd, så länge Cores, Konungen i Persien, lefde, intill Darios regemente. Konungens i Persien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Men då Ahasveros vardt Konung, uti hans rikes begynnelse, skrefvo de ett klagomål emot dem af Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Och uti Arthahsasta tid skref Bislam, Mithredath, Tabeel, och de andre af deras Råd, till Arthahsasta, Konungen i Persien; och skriften i brefvet var på Syrisk skrifven, och vardt på Syrisk uttydd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum cancelleren och Simsai skrifvaren skrefvo detta bref emot Jerusalem till Konung Arthahsasta:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Vi Rehum canceller, och Simsai skrifvare, och andre i det Rådet; af Dina, af Apharsach, af Tharpelath, af Persien, af Arach, af Babel, af Susan, af Deha, och af Elam;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Och de andre folk, hvilken den store och högprisade Asnappar försändt hade, och satt uti Samarie städer, och andre på desso sidon älfven, och i Canaan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Och detta är brefvets lydelse, som de till Konung Arthahsasta sände: Dine tjenare, de män på desso sidona älfven, och Cheeneth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Kunnigt vare Konungenom, att de Judar, som ifrå dig hitupp till oss komne äro till Jerusalem, i den upproriska ock onda staden, bygga honom upp, och göra hans murar, och låta uppgå dem af grunden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Så må nu Konungen veta, om denne stad uppbyggd varder, och murarna igen uppsatte, så varda de icke gifvande skatt, tull och årliga utskylder, och deras anslag varder kommandes Konungarna till skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Så, efter vi alle hafve varit med, och nederlagt templet, hafve vi icke länger kunnat se på Konungens föraktelse; derföre sände vi nu, och låtom det kungöra Konungenom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Att man låte söka i dina faders Chrönicor; så skall du finna i samma Chrönicor, och förfara, att denne staden är upprorisk, och Konungom och landom skadelig, och kommer desslikes andra till affall af ålder; derföre staden ock förstörd är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Ty gifve vi Konungenom till förstå, att, om denne stad uppbyggd varder, och dess murar uppsatte, så behåller du intet för dem på desso sidon älfven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Då sände Konungen ett svar till Rehum canceleren, och Simsai skrifvaren, och de andra i deras Råd, som i Samarien bodde, och de andra på hinsidon älfvena: Frid och helso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Brefvet, som I till oss sändt hafven, är uppenbarliga läsit för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Och är af mig befaldt, att man söka skulle, och är funnet, att denne stad af ålder hafver kastat sig upp emot Konungar; och uppror och affall sker deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Hafva också mägtige Konungar varit i Jerusalem, som rådit hafva öfver allt det som hinsidon älfven är; så att dem hafver tull, skatt och årliga utskylder gifven varit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Så görer nu efter denna befallning: Förtager de samma män, att staden icke byggd varder, intilldess befallning af mig gifven varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Så ser nu till, att I härutinnan icke försummelige ären, att Konungenom ingen skada härar sker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Då nu Konungens Arthahsasta bref läset vardt för Rehum och Simsai skrifvarenom, och deras Råd, drogo de straxt upp till Jerusalem till Judarna, och förhindrade dem med arm och välde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Då höll upp arbetet på Guds hus i Jerusalem, och blef tillbaka, allt intill det andra året Darios, Konungens i Persien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Och de Propheter Haggai och Zacharia, Iddo son, propheterade till Judarna, som i Juda och Jerusalem bodde, i Israels Guds Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Då stodo Serubbabel upp, Sealthiels son, och Jesua, Jozadaks son, och begynte till att bygga Guds hus i Jerusalem; och med dem Guds Propheter, som dem styrkte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'På den tiden kom till dem Thathnai, landshöfdingen på denna sidon älfven, och SetharBosnai, och deras Råd, och sade alltså till dem: Ho hafver befallt eder att bygga detta huset, och uppsätta dess murar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Då sade vi dem, huru männerna heto, som desso byggning för händer hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Men deras Guds öga kom uppå Judarnas äldsta, så att dem icke förtaget vardt, tilldess man måtte låta komma sakena till Darios, och en skrifvelse derom igenkomme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Och detta är brefvets innehållelse, som Thathnai, landshöfdingen på desso sidon älfven, och SetharBosnai, och deras Råd af Apharsach, som på desso sidona älfven voro, sände till Konung Darios.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Och de ord, som de till honom sände, lydde alltså: Konungenom Darios allan frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Konungenom vare vetterligit, att vi komme uti Judiska landet, till den stora Gudens hus, hvilket man bygger med allahanda stenar, och bjelkar lägger man i väggarna, och arbetet går fast fram i deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Men vi hafve frågat de äldsta, och sagt till dem alltså: Ho hafver befallt eder bygga detta hus, och uppsätta dess murar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Ock frågade vi, huru de heto, på det vi skulle det låta dig förstå, och vi hafve de mäns namn beskrifna, som deras öfverstar äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Men de gåfvo oss dessa ord för svar, och sade: Vi äre himmelens och jordenes Guds tjenare, och bygge det hus upp, som för mång år bygdt var, hvilket en stor Israels Konung byggt och uppsatt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Men då våre fäder förtörnade Gud af himmelen, gaf han dem uti NebucadNezars hand, Konungens i Babel, den Chaldeens; han slog detta hus ned, och förde bort folket till Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Men i första årena Cores, Konungens i Babel, befallde samme Konung Cores att bygga detta Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Ty ock de gyldene och silfverkärile i Guds hus, som NebucadNezar utu templet i Jerusalem tagit hade, och fört uti det templet i Babel, dem tog Konung Cores utu templet i Babel, ock fick dem Sesbazar vid namn, den han för en landshöfdinga satte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Och sade till honom: Tag dessa kärilen; far bort, och för dem uti templet i Jerusalem, och låt uppbygga Guds hus i sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Då kom samme Sesbazar, och lade grundvalen till Guds hus i Jerusalem. Ifrå den tiden hafver man byggt, och är ännu icke fullkomnadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Om nu Konungenom täckes, så låte söka i Konungens skatthuse, som i Babel är, om det så befaldt är af Konung Cores, att bygga Guds hus i Jerusalem, och sände till oss Konungens mening härom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Då befallde Konung Darios, att man söka skulle i cancelliet, uti Konungens skatthus, som i Babel låg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Då fann man i Ahmeta, på det slottet som i Meden ligger, ena bok, och derutinnan var ett sådana ärende beskrifvet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Uti första årena Konungs Cores befallde Konung Cores uppbygga Guds hus i Jerusalem, på det rum der man offrar, och grundval lägga, till sextio alnars höjd, till bredden ock sextio alnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Och tre väggar af allahanda stenar, och en vägg af trä; och kosten skall gifven varda utaf Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Dertill de Guds hus gyldene och silfvertyg, som NebucadNezar uti templet i Jerusalem tagit, och till Babel fört hade, skall man igengifva, så att de skola igenförde varda uti templet i Jerusalem, i sitt rum, i Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Så farer nu långt ifrå dem, du Thathnai, landshöfdinge hinsidon vid älfven, och SetharBosnai, och deras Råd af Apharsach, som hinsidon älfven ären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Låter dem arbeta på Guds hus, så att Judarnas höfvitsman och deras äldsta måga bygga Guds hus på sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Är också af mig befaldt, hvad man de äldsta i Juda utfå skall, till att bygga Guds hus, nämliga att man skall fliteliga taga utaf Konungens drätsel, det är, af den ränto hinsidon älfven, och gifva männerna, och att man icke förhindrar dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Och om de behöfva kalfvar, lamb, eller bockar, till bränneoffer till himmelens Gud, hvete, salt, vin och oljo, efter Presternas sed i Jerusalem, skall man dem gifva dagliga hvad de behöfva; och att detta sker oförsummeliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Att de måga offra till en söt lukt Gudi i himmelen, och bedja för Konungens lif, och hans barnas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Af mig är denna befallning gifven; och hvilken menniska denna orden förvänder, utaf hans hus skall man taga en bjelka, och resa honom upp, och hängan deruti, och hans hus skall skamliga förstördt varda för den gernings skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Och Gud, som hafver låtit sitt namn bo der, förstöre alla Konungar, och folk, som sina hand uträcka, till att förstöra och nederslå Guds hus i Jerusalem; jag Darios hafver detta befallt, att detta skall ock så alldeles fullföljdt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Då gjorde det Thathnai landshöfdingen hinsidon älfven, och SetharBosnai med deras Råd, till hvilka Konung Darios sändt hade, fliteliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Och Judarnas äldste byggde, och det gick för handena, efter den Prophetens Haggai och Zacharia, Iddo sons, Prophetia. Och de byggde, och uppsatte, efter Israels Guds befallning, och efter Cores, Darios och Arthahsasta, Konungarnas i Persien, befallning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Och fullkomnade huset, intill tredje dagen i dem månadenom Adar, det var sjette året af Konung Darios rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Och Israels barn, Presterna, Leviterna, och de andre fängelsens barnen, höllo Guds hus vigning med glädje;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Och offrade i Guds hus vigning hundrade kalfvar, tuhundrad lamb, fyrahundrad bockar; och till syndoffer för hela Israel, tolf getabockar, efter slägternas tal i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Och de satte Presterna i deras ordning, och Leviterna i deras vakt, till att tjena Gudi, som i Jerusalem är; såsom skrifvet står i Mose bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Och fängelsens barn höllo Passah på fjortonde dagen i dem första månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Ty Presterna och Leviterna hade renat sig, så att de alle rene voro, såsom en man; och de slagtade Passah för all fängelsens barn, och för deras bröder Presterna, och för sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Och Israels barn, som af fängelsen voro igenkomne, och alle de som sig till dem afskiljt hade ifrå Hedningarnas orenhet i landena, till att söka Herran Israels Gud, åto;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Och höllo osyrade bröds högtid i sju dagar med glädje; förty Herren hade gjort dem glada, och vändt Konungens hjerta af Assur till dem, så att deras händer styrkta vordo i verket på Guds hus, den Israels Gudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Sedan detta skedt var i Arthahsasta rike, Konungens i Persien, kom ned af Babel Esra, Seraja son, Asaria sons, Hilkia sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Sallums sons, Zadoks sons, Ahitobs sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Amaria sons, Asaria sons, Merajoths sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Serahja sons, Ussi sons, Bukki sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Abisua sons, Pinehas sons, Eleazars sons, Aarons den öfversta Prestens sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Hvilken en skickelig Skriftlärder var i Mose lag, som Herren Israels Gud gifvit hade: och Konungen gaf honom allt det han begärade, efter Herrans Guds hand öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Och drogo någre upp af Israels barn, Prester, Leviter, sångare, dörravaktare, och Nethinim, till Jerusalem, i sjunde årena Konungens Arthahsasta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Och de kommo till Jerusalem i femte månadenom, det är sjunde året Konungens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Förty på första dagen i första månadenom vardt han till råds att uppdraga ifrå Babel; och på första dagen i femte månadenom kom han till Jerusalem, efter Guds goda hand öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Ty Esra skickade sitt hjerta till att söka Herrans lag, och till att göra och lära i Israel bud och rätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Och detta är brefvets innehåll, som Konung Arthahsasta gaf Esra Prestenom, dem Skriftlärda, hvilken en lärare var i Herrans ord, och hans bud öfver Israel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Arthahsasta, Konung öfver alla Konungar, Esra Prestenom, dem Skriftlärda i Guds lag af himmelen, frid och helso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Af mig är befaldt, att alle de af Israels folk, som friviljoge äro i mitt rike, och Presterna, och Leviterna, till att fara till Jerusalem, att de måga fara med dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Utsände af Konungenom, och af de sju rådherrar, till att besöka Juda och Jerusalem, efter dins Guds lag, hvilken i dine hand är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Och att du medtager silfver och guld, som Konungen och hans rådherrar friviljoge gifva Israels Gudi, hvilkens boning i Jerusalem är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Och allahanda silfver och guld, som du finna kan i hela Babels landskap, med det som folket och Presterna friviljoge gifva till Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Allt detta tag, och köp fliteliga för de samma penningar kalfvar, lamb, bockar och spisoffer, och drickoffer, att man må offra uppå altaret vid edars Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Dertill hvad dig och dina bröder täckes att göra af de penningar, som öfverblifva, det görer efter edars Guds vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Och de tyg, som dig antvardas, till ämbetet i dins Guds huse, öfverantvarda dem inför Gud i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Hvad sedan mer af nödene är till dins Guds hus, det du behöfver utgifva, det låt utgifva utu Konungens kammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Jag, Konung Arthahsasta, hafver detta befallt räntomästaromen på hinsidon älfven, så att hvad Esra Presten, den Skriftlärde i Guds lag af himmelen, af eder äskar, att I det fliteliga gören;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Allt intill hundrade centener silfver, och intill hundrade corer hvete, och till hundrade bath vin, och till hundrade bath oljo, och salt utan mått;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Allt det der hörer till Guds lag af himmelen, att man det fliteliga låter komma till Guds hus af himmelen; att en vrede icke må komma öfver Konungens rike, och hans barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Och eder skall vetterligit vara, att I icke magt hafven att lägga någon utskuld, tull eller årliga ränto på någon Prest, Levit, sångare, dörravaktare, Nethinim, och tjenare i denna Guds huse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Men du, Esra, efter dins Guds visdom, som i dine hand är, uppsätt domare och lagmän, som allt folket döma måga, som på hinsidon älfven är, alla de som veta dins Guds lag, alla de som icke veta dem, dem lär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Och alle de som icke med flit göra dins Guds lag, och Konungens lag, de skola straxt hafva sin dom för sina gernings skull, antingen till döds eller till landsflykt, eller till penningaplikt, eller till fängelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Lofvad vare Herren våra fäders Gud, som sådant Konungenom ingifvit hafver, att han skulle bepryda Herrans hus i Jerusalem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'Och tillböjt sina barmhertighet till mig, för Konungenom, och hans rådherrar, och alla Konungens väldiga. Och jag vardt styrkt efter Herrans mins Guds hand öfver mig, och församlade de yppersta i Israels hus, att de med mig ditupp drogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Desse äro hufvuden för deras fäder, som räknade vordo, och med mig uppdrogo ifrå Babel, i den tiden, då Konung Arthahsasta regerade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Af Pinehas barn: Gersom. Af Ithamars barn: Daniel. Af Davids barn: Hattus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Af Sechania barn, Paros barn: Zacharia, och med honom räknade hundrade och femtio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Af PahathMoabs barn: Eljoenai, Seraja son, och med honom tuhundrad män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Af Sechania barn: Jahasiels son, och med honom trehundrad män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Af Adins barn: Ebed, Jonathans son, och med honom femtio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Af Elams barn: Jesaia, Athalia son, och med honom sjutio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Af Sephatja barn: Sebadja, Michaels son, och med honom åttatio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Af Joabs barn: Obadja, Jehiels son, och med honom tuhundrad och aderton män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Af Selomiths barn: Josiphia son, och med honom hundrade och sextio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Af Bebai barn: Zacharia, Bebai son, och med honom åtta och tjugu män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Af Asgads barn: Johanan, Kåtans son, och med honom hundrade och tio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Af de sista Adonikams barn; och heto alltså: Eliphelet, Jehiel och Semaja, och med dem sextio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Af Bigvai barn: Uthai och Sabbud, och med dem sjutio män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Och jag församlade dem till älfvena, som kommer till Ahava; och blefvom der i tre dagar. Och då jag gaf akt uppå folket och Presterna, fann jag der inga Leviter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Då sände jag till Elieser, Ariel, Semaja, Elnathan, Jarib, Elnathan, Nathan, Zacharia och Mesullam, öfverstar; och Jojarib och Elnathan, lärare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Och sände dem ut till Iddo öfverstan, till Casiphja, att de skulle hemta oss tjenare uti var Guds hus. Och jag gaf dem in hvad de tala skulle med Iddo och hans bröder, de Nethinim i Casiphja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Och de hade till oss, efter Guds goda hand öfver oss, en klok man utaf Maheli barn, Levi sons, Israels sons, Serebia, med hans söner och bröder, aderton;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Och Hasabia, och med honom Jesaia af Merari barn, med hans bröder och deras söner, tjugu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Och af de Nethinim, hvilka David och Förstarna gåfvo till att tjena Leviterna, tuhundrad och tjugu, alle nämnde vid namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Och jag lät der vid älfvena, vid Ahava, utropa ena fasto, att vi skulle ödmjuka oss för vårom Gud, till att söka af honom en rättan väg för oss, och vår barn, och alla våra håfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Ty jag skämdes bedas ledsagare och resenärar af Konungenom, att de skulle hjelpa oss för fienderna på vägenom; förty vi hade sagt Konungenom: Var Guds hand är till det bästa öfver alla de honom söka; och hans starkhet och vrede öfver alla dem, som honom öfvergifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Alltså fastade vi, och sökte detta af vårom Gud, och han hörde oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Och jag afskiljde tolf af de öfversta Presterna, Serebia och Hasabia, och med dem tio deras bröder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Och vog dem till silfver, och guld, och tyg till häfoffer i vår Guds hus, hvilka Konungen, och hans rådherrar, och Förstar, och hele Israel, som för handene var, till häfoffer gifvit hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Och vog dem till i deras hand sexhundrad och femtio centener silfver, och i silfvertyg hundrade centener, och i guld hundrade centener;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Tjugu gyldene skålar, de höllo tusende gylden, och tu god kostelig kopparkäril, klar såsom guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Och sade till dem: I ären helige Herranom; så äro ock kärilen helig; dertill det frigifna silfver och guld Herranom edra fäders Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Så vaker, och bevarer det, tilldess I vägen det inför öfversta Presterna, och Leviterna, och öfversta fäderna i Israel i Jerusalem, uti Herrans hus kistor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Då togo Presterna och Leviterna det vägna silfret, och guldet, och kärilen, att de skulle föra det till Jerusalem, till vår Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Alltså fore vi ifrån älfvene Ahava, på tolfte dagen i första månadenom, att vi skulle draga till Jerusalem; och var Guds hand var öfver oss, och bevarade oss ifrå fiendernas hand och försåt på vägenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Och vi komme till Jerusalem, och blefvom der i tre dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'På fjerde dagenom vardt väget silfret och guldet, och kärilen uti vår Guds hus, under Meremoths hand, Uria sons Prestens, och med honom Var Eleazar, Pinehas son; och med dem Josabath, Jesua son, och Noadja, Binnui son, de Leviter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Efter hvars tal och vigt; och vigten vardt på den tiden all beskrifven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Och fängelsens barn, som utu fängelset komne voro, offrade bränneoffer Israels Gudi, tolf stutar för hela Israel, sex och niotio vädrar, sju och sjutio lamb, tolf bockar till syndoffer; alltsammans till bränneoffer Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Och de antvardade Konungens befallning Konungens ämbetsmän och landshöfdingom på denne sidon älfven; och de upphöjde folket, och Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Då nu allt detta bestäldt var, gingo till mig de öfverste, och sade: Israels folk, och Presterna, och Leviterna, äro icke afskilde ifrå folken i landen, efter deras styggelse, som är de Cananeers, Hetheers, Phereseers, Jebuseers, Ammoniters, Moabiters, Egyptiers och Amoreers.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Förty de hafva tagit deras döttrar, och deras söner, och gjort den helga sädena menliga med folken i landen; och öfverstarnas och rådherrarnas hand var den första i denna missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Då jag detta hörde, ref jag min kläder och min kjortel sönder, och utryckte mitt hufvudhår och skägg, och satt ensam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Och sig församlade till mig alle de som Israels Guds ord fruktade, för deras öfverträdelse, som i fängelset varit hade; och jag satt ensam allt intill aftonoffret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Och vid aftonoffret stod jag upp af min jämmer, och ref min kläder och min kjortel sönder, och föll uppå min knä, och uträckte mina händer till Herran min Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Och sade: Min Gud, jag skämmes och blyges att upphäfva min ögon till dig, min Gud: ty vår missgerning är vuxen öfver vårt hufvud, och var skuld är stor upp till himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Allt ifrå vara fäders tid hafve vi varit i stora skuld, allt intill denna dag; och för våra missgerningars skull äre vi, och våre Konungar och Prester, gifne i Konungarnas hand i landen, uti svärd, i fängelse, i rof, och i ansigtes blygd, såsom det går i denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Så är oss dock nu någon liten tid nåde af Herranom vårom Gud vederfaren, att ännu något af oss är qvart blifvet, att han skulle gifva oss en nagla i sitt helga rum; och att vår Gud skulle upplysa var ögon, och gifva oss ännu ett litet lif i vår träldom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Förty vi äre trälar, och vår Gud hafver icke förlåtit oss, ändock vi trälar äre; och hafver böjt till oss barmhertighet för Konungarna i Persien, att de läto oss lefva, och upphöja vår Guds hus, och upprätta dess förstöring, och gifva oss en gård i Juda och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Nu, hvad skole vi säga, vår Gud, efter detta? Att vi din bud öfvergifvit hafve,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Som du genom dina tjenare Propheterna budit hafver, och sagt: Det land, som I uti kommen till att besitta det, är ett orent land, igenom folkens orenhet i landen, uti deras styggelse, med hvilken de hafva uppfyllt det med orenhet allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Så skolen I nu icke gifva edra döttrar deras söner, och deras döttrar skolen I icke taga edrom sönom, och söker icke deras frid eller välfärd i evig tid; på det I skolen blifva mägtige, och äta det goda i landena, och lefva det edrom barnom till arfs i evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Och efter allt det som öfver oss kommet är för våra onda gerningars och stora synders skull, hafver du vår Gud öfversett med oss det vi illa gjort hafve, och hafver gifvit oss en förlossning, såsom det nu är för ögonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Men vi hafve vändt oss om, och låtit din bud fara, så att vi hafve befryndat oss med desso styggelsens folke; vill du då vred vara öfver oss, tilldess det allt ute är, så att intet qvart blifver, eller ingen förlossning mer är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herre, Israels Gud, du äst rättfärdig, ty vi äre igenblefne och behållne, såsom det i denna dag för ögon är; si, vi äre för dig uti vår skuld; ty fördenskull kan man intet blifva ståndandes för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Då Esra så bad, bekände och gret, och låg inför Guds hus, församlade sig till honom utaf Israel en ganska stor menighet af män, qvinnor och barn; förty folket gret svårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Och Sechania, Jehiels son, af Elams barn, svarade, och sade till Esra: Si, vi hafve förtagit oss emot vår Gud, att vi hafve tagit oss främmande hustrur utaf landsens folk; men här är ännu hopp derom i Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Så låt oss nu göra ett förbund med vårom Gud, så att vi utdrifve alla hustrur, och dem som af dem födde äro, efter Herrans råd, och deras som frukta vår Guds bud, att man må göra efter lagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Så statt nu upp; ty det hörer dig till: Vi vilje vara med dig; var vid en god tröst, och gör så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Då stod Esra upp, och tog en ed af de öfversta Presterna, och Leviterna, och hela Israel, att de skulle göra efter detta talet. Och de svoro det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Och Esra stod upp inför Guds hus, och gick in uti Johanans, Eljasibs sons, kammar. Och då han ditkom, åt han intet bröd, och drack intet vatten; förty han sörjde öfver deras öfverträdelse, som i fängelset varit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Och de läto utropa i Juda och Jerusalem, till all fängelsens barn, att de skulle församla sig till Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Och hvilken som icke komme innan tre dagar, efter öfverstarnas och de äldstas råd, hans ägodelar skulle alla tillspillogifvas, och han afskiljas ifrå fångarnas menighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Då församlade sig alle Juda män och BenJamin till Jerusalem, innan tre dagar; det är, på tjugonde dagen i den nionde månadenom. Och allt folket satt uppå gatone inför Guds hus, och bäfvade för detta ärendes skull, och för regnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Och Esra Presten stod upp, och sade till dem: I hafven förtagit eder, i det att I hafven tagit främmande hustrur, på det I skullen ännu föröka Israels skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Så bekänner nu Herran edra fäders Gud, och görer det honom ljuft är, och skiljer eder ifrå landsens folk, och ifrå de främmande hustrur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Då svarade hela menigheten, och sade med höga röst: Ske såsom du oss sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Men folket är mycket, och regnväder, och kan icke stå ute; så är det icke heller ens eller två dagars gerning; ty vi hafve sådana öfverträdelse mycken gjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Låt oss beställa våra öfverstar i hela menighetene, att alle de i våra städer, som främmande hustrur tagit hafva, komma på bestämd tid; och de äldste i hvar staden, och deras domare med, tilldess vår Guds vrede må ifrån oss vänd varda i denna sakene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Då vordo beställde Jonathan, Asahels son, och Jahesia, Thikva son, öfver denna saken; och Mesullam, och Sabbethai Leviterna hulpo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Och fängelsens barn gjorde alltså. Och Presten Esra, och de ypperste fäderne i deras fäders hus, och alle de nu nämnde äro, afskiljde sig, och satte sig på första dagen i tionde månadenom till att ransaka om detta ärendet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Och de uträttade det på alla de män, som främmande hustrur hade, på första dagen i första månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Och vordo funne ibland Presternas barn, som främmande hustrur tagit hade, nämliga ibland Jesua barn, Jozadaks sons, och hans bröder: Maaseja, Elieser, Jarib och Gedalia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Och de gåfvo deras hand deruppå, att de ville utdrifva hustrurna; och till deras skuldoffer offra en vädur för sina skuld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Ibland Immers barn: Hanani och Sebadia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Ibland Harims barn: Maaseja, Elia, Semaja, Jehiel och Ussia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Ibland Pashurs barn: Eljoenai, Maaseja, Ismael, Nethaneel, Josabad och Eleasa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Ibland Leviterna: Josabad, Simei och Kelaja, den är Kelita; Pethabja, Juda och Elieser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Ibland sångarena: Eljasib. Ibland dörravaktarena: Sal lura, Telem och Uri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Utaf Israel: Ibland Paros barn: Ramia, Jissija, Malchija, Mijamin, Eleazar, Malchija och Benaja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Ibland Elams barn: Mattania, Zacharia, Jehiel, Abdi, Jeremoth och Elia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Ibland Sattu barn: Eljoenai, Eljasib, Mattania, Jeremoth, Sabad och Asisa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Ibland Bebai barn: Johanan, Hanania, Sabbai och Athlai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Ibland Bani barn: Mesullam, Malluch, Adaja, Jasub, Seal och Jeramoth.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Ibland PahathMoabs barn: Adna, Chelal, Benaja, Maaseja, Mattania, Bezaleel, Binnui och Manasse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Ibland Harims barn: Elieser, Jissija, Malchija, Semaja, Simeon,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'BenJamin, Malluch och Semaria.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Ibland Hasums barn: Mattenai, Mattatta, Sabad, Elipheleth, Jeremai, Manasse och Simi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Ibland Bani barn: Maadai, Amram, Uel,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Cheluhu,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Banja, Meremoth, Eljasib,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattania, Mattenai, Jaasav,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnui, Simi,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemia, Nathan, Adaja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbai, Sasai, Sarai,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asareel, Selemia, Semaria,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria och Joseph.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Ibland Nebo barn: Jegiel, Mattithia, Sabad, Sebina, Jaddai, Joel och Benaja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Desse hade alle tagit främmande hustrur; och voro somlige ibland de samma hustrur, som barn födt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Dessa äro Nehemia, Hachalja sons, ord. Det begaf sig uti dem månadenom Chislev, i tjugonde årena, att jag var i Susan på slottet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Då kom Hanani, en af mina bröder, med några män utaf Juda; och jag frågade dem, huru det gick med Judarna, som behållne och igenlefde voro af fängelset; och huru det tillgick i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Och de sade till mig: De igenlefde af fängelset äro der i landena uti stor vedermödo och försmädelse; murarna i Jerusalem äro nederbrutne, och dess portar uppbrände med eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Då jag nu sådana ord hörde, satt jag och gret, och jämrade mig i några dagar, och fastade, och bad inför Gud af himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Och sade: Ack! Herre Gud af himmelen, du store och förskräckelige Gud, som håller förbund och barmhertighet dem som dig älska och hålla din bud:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Låt dock din öron höra härtill, och din ögon öppne vara, så att du hörer dins tjenares bön, som jag nu beder inför dig, bide dag och natt, för dina tjenare Israels barn, och bekänner Israels barnas synd, som vi emot dig gjort hafve; och jag med mins faders hus hafvom också syndat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Vi äre vordne förderfvade, att vi icke hafve hållit din bud, befallningar och rätter, som du dinom tjenare Mose budit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Men tänk dock uppå det ord, som du dinom tjenare Mose böd, och sade: Om I förtagen eder, så vill jag förströ eder ibland folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Men om I omvänden eder till mig, och hållen min bud, och gören dem; och om I än bortdrefne voren allt intill himmelens ända, så vill jag dock dädan församla eder, och skall låta eder komma till det rum, som jag utvalt hafver, till att mitt Namn der bo skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'De äro dock dine tjenare, och ditt folk, som du förlossat hafver, igenom dina stora kraft och mägtiga hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ack! Herre, låt din öron höra till din tjenares bön, och till dina tjenares bön, som begära frukta ditt Namn; och låt lyckosamliga tillgå i dag med dinom tjenare, och gif honom barmhertighet för denna mannenom. Ty jag var Konungens skänk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Uti den månaden Nisan, i tjugonde årena Konungs Arthahsasta, då vin stod för honom, tog jag vinet upp, och fick Konungenom; och jag var icke lustig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Då sade Konungen till mig: Hvi ser du så illa ut? Du är ju icke krank? Det äret icke, utan du äst bedröfvad. Men jag fruktade mig svårliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Då sade jag till Konungen: Konungen lefve evinnerliga! Skulle jag icke se illa ut? Den staden, der mina faders begrafningshus är, ligger öde, och dess portar äro med eld uppbrände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Då sade Konungen till mig: Hvad är då ditt begär? Då bad jag Gud af himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Och sade till Konungen: Om Konungenom så godt tyckte, och din tjenare funne nåd för dig, att du ville sända mig till Juda, till den staden, der mina fäder begrafne äro, att jag måtte uppbygga honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Och Konungen sade till mig, och Drottningen, som jemte honom satt: Huru lång kan din resa varda? Och när kan du komma igen? Och Konungenom föll i sinnet, att han skulle sända mig åstad. Och jag satte honom en bestämd tid före;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Och sade till Konungen: Om Konungenom så godt tycker, så gifve han mig bref till landshöfdingarna på hinsidon älfvena, att de ledsaga mig derigenom, tilldess jag kommer in i Juda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Och bref till Assaph, Konungens skogshöfvitsman, att han låter mig få trä till bjelkar åt portarna i palatset i husena, och till stadsmurarna, och till huset, der jag infara skall. Och Konungen gaf mig det, efter mins Guds goda hand öfver mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Och då jag kom till landshöfdingarna på hinsidon älfvena, fick jag dem Konungens bref. Och Konungen sände med mig höfvitsmän och resenärar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Då nu Saneballat den Horoniten, och Tobia tjenaren, den Ammoniten, det hörde, förtröt det dem svårliga, att någor menniska kommen var, som något godt sökte för Israels barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Och då jag kom till Jerusalem, och hade varit der i tre dagar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Stod jag om nattena upp, och någre få män med mig; ty jag sade det ingen menniska, hvad mig min Gud ingifvit hade till att göra med Jerusalem; och intet djur var med mig, utan det jag red uppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Och jag red ut genom dalporten om nattena, och framom drakabrunnen, och åt dyngoportenom, och besåg Jerusalems murar, som sönder voro, och portarna, som med eld uppbrände voro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Och gick öfver till brunnporten, och till Konungsdammen; och var intet rum, der djuret, som under mig var, uppå gå kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Så drog jag om nattena bort åt bäcken, och besåg murarna, och vände om, och kom igenom dalporten hem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Och öfverstarna visste icke hvart jag gick, eller hvad jag gjorde; förty jag hade ändå intet sagt Judarna, och Presterna, rådherrarna och öfverstarna, och dem androm, som uppå verket arbetade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Så sade jag dem nu: I sen den uselhet, som vi uti äre, att Jerusalem ligger öde, och dess portar äro med eld uppbrände; kommer, låter oss bygga murarna till Jerusalem, att vi icke länger skola vara till en försmädelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Och jag lät dem förstå min Guds hand, den öfver mig god var; dertill Konungens ord, som han med mig talat hade. Och de sade: Så låt oss nu vara uppe. Och vi byggde, och deras händer voro tröste till godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Då nu Saneballat den Horoniten, och Tobia tjenaren, den Ammoniten, och Gesem den Araben, hörde det, begabbade de oss, och föraktade oss, och sade: Hvad är det I gören? Viljen I åter falla af ifrå Konungenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Då svarade jag dem, och sade: Gud af himmelen gifver oss lycko; ty vi hans tjenare hafve uppe varit, och byggom; men I hafven ingen del eller rätt, eller åminnelse i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Och Eljasib, öfverste Presten, stod upp med sina bröder Presterna, och byggde fåraporten; honom helgade de, och satte in hans dörrar; men de helgade honom allt intill det tornet Mea, nämliga allt intill det tornet Hananeel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Bredevid dem byggde de män af Jericho; och näst dem byggde Saccur, Imri son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Men fiskaporten byggde Senaa barn; honom täckte de, och satte in hans dörrar, lås och bommar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Näst dem byggde Meremoth, Uria son, Hakkoz sons; näst dem byggde Mesullam, Berechia son, Mesesabeels sons; näst dem byggde Zadok, Baana son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Näst dem byggde de af Thekoa; men deras väldige böjde icke sin hals till sins herras tjenst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Den gamla porten byggde Jojada, Paseahs son, och Mesullam, Besodeja son; honom täckte de, och satte in hans dörrar, och lås och bommar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Näst dem byggde Melatia af Gibeon, och Jadon af Merono, män af Gibeon och Mizpa, på landshöfdingans säte, på denna sidon älfven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Näst efter honom byggde Ussiel, Harhaja son, guldsmeden; näst honom byggde Hanania, apothekarens son, och de förstärkte Jerusalem allt intill de breda murar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Näst honom byggde Rephaja, Hurs son, öfversten öfver en half fjerding af Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Näst honom byggde Jedaja, Harumaphs son, tvärtöfver sitt hus; näst honom byggde Hattus, Hasabenja son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Men Malchija, Harims son, och Hasub, Pahath Moabs son, byggde ett annat stycke, och tornet med ugnarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Näst honom byggde Sallum, Halohes son, öfversten för en half fjerding i Jerusalem, han och hans döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dalporten byggde Hanun och borgarena af Sanoah; de byggde honom, och satte in hans dörrar, och lås och bommar, och tusende alnar på murenom allt intill dyngoporten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Men dyngoporten byggde Malchija, Rechabs son, öfversten i vingårdsmännernas fjerding; han byggde honom, och satte in hans dörrar, lås och bommar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Brunnporten byggde Sallum, CholHose son, en öfverste för en fjerding i Mizpa; han byggde honom, och täckten, och satte in hans dörrar, lås och bommar; dertill ock murarna vid dammen Selah, vid Konungsörtagården, allt intill trapporna, som gå nederåt ifrå Davids stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Näst honom byggde Nehemia, Asbuks son, öfversten för den halfva fjerdingen i BethZur, allt intill gentemot Davids grafvar, och allt intill den dammen Asuja, och allt intill de väldigas hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Efter honom byggde de Leviter, Rehum, Bani son; bredevid honom byggde Hasabia, öfversten för halfva fjerdingen i Kegila, i hans fjerding.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Efter honom byggde deras broder Bavai, Henadads son, öfversten för en half fjerding i Kegila.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Efter honom byggde Eser, Jesua son, öfversten i Mizpa, ett annat stycke, inåt harneskhushörnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Efter honom, uppå berget, byggde Baruch, Sabbi son, ett annat stycke, ifrå hörnet allt intill Eljasibs öfversta Prestens husdörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Efter honom byggde Meremoth, Uria son, Hakkoz sons, ett annat stycke, ifrån Eljasibs husdörr, allt intill ändan af Eljasibs hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Efter honom byggde Presterna, de män af landsbygdene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Efter dem byggde BenJamin och Hasub, tvärsöfver deras hus; efter dem byggde Asaria, Maaseja son, Anania sons, jemte sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Efter honom byggde Binnui, Henadads son, ett annat stycke, ifrån Asaria hus intill båget, och allt intill hörnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, Usai son, emot båget, och det höga tornet, som synes utaf Konungshuset, vid fångahusens gård; efter honom Pedaja, Paros son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Men de Nethinim bodde uti Ophel, allt intill vattuporten österut, der tornet ut synes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Efter dem byggde de af Thekoa ett annat stycke, tvärtemot det stora tornet, som ut synes, allt intill murarna Ophel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Men ifrå hästaporten byggde Presterana, hvardera emot sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Efter dem byggde Zadok, Immers son, emot sitt hus; efter honom byggde Semaja, Sechania son, den dörravaktaren, östantill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Efter honom byggde Hanania, Selemia son, och Hanun, Zalaphs son, den sjette, ett annat stycke; efter honom byggde Mesullam, Berechia son, emot sin fatabur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Efter honom byggde Malchija guldsmedssonen, allt intill de Nethinims och krämares hus, emot rådsporten, och intill hörnsalen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Och emellan hörnsalen allt intill fåraporten byggde guldsmederna och krämarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Då nu Saneballat hörde, att vi byggde murarna, vardt han vred, och förgrymmade sig svårliga; och han bespottade Judarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Och sade för sina bröder, och för de väldiga i Samarien: Hvad göra de vanmägtige Judar? Månn man så skola låta betämma dem? Månn de skola offra? Månn de skola en dag fullkomna det? Månn de göra stenarna lefvande af stofthopar, som förbrände äro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Men Tobia den Ammoniten, som när honom var, sade: Låt bygga dem; när räfvarna löpa ditupp, skola de väl sönderrifva deras stenmurar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Hör, vår Gud, huru föraktade äre vi; vänd deras försmädelse in uppå deras hufvud, så att du gifver dem uti föraktelse i deras fängelses lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Öfverskyl icke deras missgerning, och bortskrapa icke deras synd för dig; förty de hafva rett byggningsmännerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Men vi byggde murarna, och fogde dem alla tillhopa intill halfva höjd; och folket fick hjerta till att arbeta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Då nu Saneballat och Tobia, och de Araber och Ammoniter, och Asdoditer hörde, att murarna i Jerusalem voro igenbyggde, och de hade begynt igentäppa det öppet var, vordo de ganska vrede;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Och gjorde alla ett förbund tillhopa, att de skulle komma och strida emot Jerusalem, och göra en villo derinne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Men vi bådom vår Gud, och satte vakt uppå dem dag och natt, emot dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Och Juda sade: Dragarenas magt är allt för svag, och gruset är för mycket; vi kunne icke bygga uppå murenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Men våre fiender tänkte: De skola icke få vetat, eller set, förr än vi komme midt i hopen uppå dem, och slå dem ihjäl, och förhindre arbetet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Då nu Judarna, som när dem bodde, kommo, och sade oss det väl tio gånger, af all rum, der de omkring oss bodde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Då satte jag nedre utmed muren i grafvene folket, efter deras slägter, med deras svärd, spetsar och bågar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Och besåg det, och stod upp, och sade till rådherrarna, och öfverstarna, och till det andra folket: Frukter eder intet för dem; tänker uppå den stora förskräckeliga Herran, och strider för edra bröder, söner, döttrar, hustrur och hus,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Då nu våre fiender hörde, att vi hade fått vetat, gjorde Gud deras råd omintet; och vi vände oss åter alle till muren, hvar och en till sitt arbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Och det skedde sedan, att hälften af de unga män gjorde arbetet; den andre hälften höllo spetsar, sköldar, bågar, och pansar; och öfverstarne stodo bakför hela Juda hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'De som byggde på muren, och de som båro bördor ifrå dem som uppå ladde; med den ena handene gjorde de arbetet, och med den andra höllo de värjona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Och hvar och en af dem, som byggde, hade sitt svärd bundet vid sidona, och byggde så; och den som blåste med basunen, var när mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Och jag sade till rådherrarna, och öfverstarna, och till det andra folket: Arbetet är stort och vidt, och vi äre förströdde på murenom, långt ifrå hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'På hvilket rum I nu hören blåsa i basunen, dit kommer till oss. Vår Gud varder för oss stridandes;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Och vi vilje arbeta på verket; och hälften af dem höll spetsar, allt ifrå morgonrodnan intill stjernorna uppgingo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Ock sade jag på den tiden till folket: Hvar och en blifve med sinom dräng öfver natten i Jerusalem, att vi om nattena tage vara på vaktena, och om dagen på arbetet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Men jag och mine bröder, och mine tjenare, och de män i vaktene efter mig, drogo intet vår kläder af, när någor i vattnet gick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Och sig upphof ett stort rop af folket, och deras hustrur, emot sina bröder Judarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Och voro somlige, som sade: Våre söner och döttrar äro allt för månge; låt oss taga säd, och äta, att vi måge lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Och somlige sade: Låt oss utsätta våra åkrar, vingårdar och hus, och taga säd i denna hårda tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Somlige sade: Låt oss låna penningar på ränto till Konungen, på våra åkrar och vingårdar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Ty våra bröders kropp är såsom vår kropp, och deras barn såsom vår barn; eljest gifve vi våra söner och döttrar i träldom, och äre allaredo våra döttrar somliga undergifna, och ingen magt är i våra händer; komma också våra åkrar och vingårdar androm tillhanda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Då jag nu deras rop och dessa orden hörde, vardt jag ganska vred.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Och mitt hjerta fick till råds, att jag straffade rådherrarna och öfverstarna, och sade till dem: Viljen I drifva ocker, den ene på den andra? Och jag hade tillhopa emot dem en stor församling;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Och sade till dem: Vi hafve igenköpt våra bröder Judarna, som Hedningomen sålde voro, efter våra förmågo; och I viljen också sälja edra bröder, de vi till oss köpt hafve? Då tego de, och funno intet till att svara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Och jag sade: Det är icke godt, som I gören. Skullen I icke vandra i Gudsfruktan, för Hedningarnas försmädelses skull, våra fiendars?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Jag och mine bröder, och mine tjenare, hafvom ock fått dem penningar och säd; men ockret vilje vi låta blifva tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Så får dem nu i denna dag igen sina åkrar, vingårdar, oljogårdar och hus, och hundradedelen af penningomen för säd, vin och oljo, som I på dem ockrat hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Då sade de: Vi vilje få dem det igen, och vilje intet äska af dem; och vilje göra såsom du sagt hafver. Och jag kallade Presterna, och tog en ed af dem, att de så göra skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Och jag skuddade mitt sköte ut, och sade: Så skudde Gud hvar och en af sitt hus, och ifrå hans arbete, den icke blifver vid detta ord, så att han blifve utskuddad och blottad. Och hela församlingen sade Amen; och lofvade Herran. Och folket gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Desslikes, ifrå den tiden, då mig vardt befaldt att vara landshöfding i Juda land, nämliga ifrå tjugonde årena, allt intill annat och tretionde året Konungs Arthahsasta, det är i tolf år, höll jag mig och mina bröder intet af höfdingakoste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Förty de förre landshöfdingar, som för mig varit hade, hade besvärat folket, och hade tagit af dem bröd och vin, och dertill fyratio siklar silfver, och deras tjenare hade haft sig väldeliga med folket; men jag gjorde icke så, för Gudsfruktans skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Arbetade jag ock på murarbetet, och köpte ingen åker; och alle mine tjenare måste der komma samman till arbetes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Dertill voro ock af Judarna och Förstarna hundrade och femtio vid mitt bord, som till mig komne voro ifrå Hedningarna, som kringom oss äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Och man måste beställa mig om dagen en oxa, och sex utvald får, och foglar, och ju i tio dagar allahanda vin tillfyllest. Likväl äskade jag intet höfdingakosten; förty tungen var svår på folkena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Min Gud, betänk mig till godo allt det jag desso folkena gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Då Saneballat, Tobia och Gesem den Araben, och andre våre fiender förnummo, att jag murarna byggt hade, och intet gap var mer deruppå; ändock jag ändå på den tiden icke upphängt hade dörrarna i portomen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sände Saneballat och Gesem till mig, och läto säga mig: Kom, och låt oss komma tillsammans på bygdene, på slättene vid den staden Ono. Och de aktade göra mig ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Men jag sände båd till dem, och lät säga dem; Jag hafver ett stort verk till att uträtta, jag kan icke komma neder; det måtte försummadt blifva, om jag tager handena af, och far neder till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'De sände väl fyra gånger till mig vid samma sinnet; och jag svarade dem allt vid samma sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Då sände Saneballat femte gången sin tjenare till mig, med ett öppet bref i hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Derutinnan var skrifvet: Det är kommet för Hedningarna, och Gesem hafver det sagt, att du och Judarna viljen affalla; derföre uppbygger du murarna, och du vill vara deras Konung i denna sakene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Och du hafver beställt dig Propheter, som om dig skola utropa i Jerusalem, och säga: Han är Juda Konung. Sådant kommer för Konungen. Så kom nu, låt oss rådslå med hvarannan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Men jag sände till honom, och lät säga honom: Detta är icke skedt, som du säger, du hafver diktat det af ditt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Ty de ville alle rädda oss, och mente: De varda aflåtande af arbetet, och varda stille. Men jag förstärkte mina hand desto mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Och jag kom uti Semaja hus, Delaja sons, Mehetabeels sons, och han hade innelyckt sig; och sade: Låt oss komma tillhopa i Guds hus, midt i templet, och sluta dörrarna till af templet; förty de varda kommande till att dräpa dig, och komma om nattena, att de skola slå dig ihjäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Men jag sade: Skulle en sådana man fly? Skulle en sådana man, som jag är, gå uti templet, på det han skall blifva lefvandes? Jag vill icke gå derin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Ty jag förmärkte, att Gud hade intet sändt honom. Han spådde väl sådant om mig; men Tobia och Saneballat hade gifvit honom penningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Derföre tog han penningar, på det jag skulle taga en fruktan till mig, och göra så, och synda; och de skulle hafva ett ondt rop uppå mig, dermed de måtte förlasta mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Tänk, min Gud, på Tobia och Saneballat, efter dessa deras gerningar, och på Propheten Noadja, och de andra Propheterna, som mig afskräcka ville.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Och muren vardt redo på femte och tjugonde dagen af den månaden Elul, i två och femtio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Och då alle våre fiender det hörde, fruktade sig alle Hedningar, som omkring oss voro, och deras mod förföll dem; förty de märkte, att detta verk var af Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Voro ock på den tiden månge af Juda öfverstar, hvilkas bref gingo till Tobia; och ifrå Tobia till dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Ty de voro månge i Juda, som honom besvorne voro; förty han var Sechania svåger, Arahs sons; och hans son Johanan hade Mesullams dotter, Berechia sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Och de talade godt om honom för mig, och förde mitt tal ut för honom. Så sände nu Tobia bref till att afskräcka mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Då vi nu hade byggt murarna, hängde jag portarna före, och vordo beställde porthållare, sångare och Leviter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Och jag böd min broder Hanani, och Hanania palatsfogdanom i Jerusalem; ty han var en trofast man, och gudfruktig för många andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Och sade till dem: Man skall icke upplåta portarna i Jerusalem, tilldess solen varder varm; och medan man ännu arbetar, skall man slå portarna till, och bommen före. Och väktare vordo beställde utaf borgarena i Jerusalem, hvar och en på sine vakt, och om sitt hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Och staden var vid till rum, och stor; men folket litet derinne, och husen voro icke uppbyggd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Och min Gud gaf mig i hjertat, att jag församlade rådherrarna och öfverstarna, och folket, till att räkna dem; och jag fann ett register på mantalet, deras som tillförene uppkomne voro, och fann deruti så skrifvet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Desse äro landsens barn, som uppkomne voro utaf fängelset, af dem som NebucadNezar, Konungen i Babel, hade bortfört, och i Jerusalem bodde, och i Juda, hvar och en i sin stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Och voro komne med Serubbabel: Jesua, Nehemia, Asaria, Raamja, Nahamani, Mordechai, Bilsan, Misperet, Bigvai, Nehum och Baana. Detta är talet af männerna af Israels folk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paros barn voro tutusend hundrade två och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sephatja barn, trehundrad två och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arahs barn, sexhundrad två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'PahathMoabs barn, ibland Jesua och Joabs barn, tutusend åttahundrad och aderton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sattu barn, åttahundrad fem och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Saccai barn, sjuhundrad och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnui barn, sexhundrad åtta och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebai barn, sexhundrad åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Asgads barn, tutusend trehundrad två och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikams barn, sexhundrad sju och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvai barn, tutusend sju och sextio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adins barn, sexhundrad fem och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aters barn af Hiskia, åtta och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hasums barn, trehundrad åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Bezai barn, trehundrad fyra och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Hariphs barn, hundrade och tolf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeons barn, fem och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'De män af BethLehem och Nethopha, hundrade åtta och åttatio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'De män af Anathot, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'De män af BethAsmaveth, två och fyra tio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'De män af KiriathJearim, Chephira och Beeroth, sjuhundrad tre och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'De män af Rama och Gaba, sexhundrad en och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'De män af Michmas, hundrade två och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'De män af BethEl och Aj, hundrade tre och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'De män af Nebo dess andras, två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Dens andras Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harims barn, trehundrad och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jerecho barn, trehundrad fem och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lod, Hadid, och Ono barn, sjuhundrad en och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Senaa barn, tretusend niohundrad och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Presterna: Jedaja barn, af Jesua hus, niohundrad tre och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immers barn, tusende två och femtio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurs barn, tusende tuhundrad sju och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harims barn, tusende och sjutton.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leviterna: Jesua barn, af Kadmiel, ibland Hodeva barn, fyra och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Sångarena: Assaphs barn, hundrade åtta och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Dörravaktarena: Sallums barn, Aters barn, Talmons barn, Akkubs barn, Hatita barn, Sobai barn; alle tillhopa hundrade åtta och tretio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'De Nethinim: Ziha barn, Hasupha barn, Tabaoths barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keros barn, Sia barn, Padons barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebana barn, Hagaba barn, Salmai barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hanans barn, Giddels barn, Gahars barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reaja barn, Rezins barn, Nekoda barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gassams barn, Ussa barn, Paseahs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besai barn, Meunims barn, Nephisesims barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbuks barn, Hakupha barn, Harhurs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Bazliths barn, Mehida barn, Harsa barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkos barn, Sisera barn, Thamahs barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Neziahs barn, Hathipha barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salomos tjenares barn: Sotai barn, Sophereths barn, Perida barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaala barn, Darkons barn, Giddels barn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sephatja barn, Hattils barn, Pocherets barn af Zebaim, Amons barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Alle de Nethinim, och Salomos tjenares barn, voro trehundrad två och niotio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Desse drogo också med upp, af ThelMelah, ThelHarsa, Cherub, Addon och Immer; men de kunde icke bevisa deras fäders hus, eller deras säd, om de voro af Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delaja barn, Tobia barn, Nekoda barn, voro sexhundrad två och fyratio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Och af Presterna: Habaja barn, Hakkoz barn, Barsillai barn, hvilken hustru tog af Barsillai den Gileaditens döttrar, och vardt efter deras namn nämnd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Desse sökte deras börds register; och då de icke funno det, vordo de qvitte vid Presterskapet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Och Thirsatha sade till dem, att de icke skulle äta utaf det aldrahelgaste, intilldess en Prest uppkomme med Ljus och Fullkomlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Hela menigheten, såsom en man, var tu och fyratio tusend trehundrad och sextio;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Undantagne deras tjenare och tjenarinnor, de voro sjutusend trehundrad sju och tretio; och de hade tuhundrad fem och fyratio sångare och sångerskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Sjuhundrad sex och tretio hästar; tuhundrad fem och fyratio mular;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Fyrahundrad fem och tretio camelar; sextusend sjuhundrad och tjugu åsnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Och somlige af öfversta fäderna gåfvo till verket: Thirsatha gaf till drätselen tusende gylden, och femtio bäcken, femhundrad och tretio Prestakjortlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Och somlige af de öfversta fäder gåfvo i drätselen till verket tjugutusend gylden, tutusend och tuhundrad pund silfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Och det andra folket gaf tjugutusend gylden, och tutusend pund silfver, och sju och sextio Prestakjortlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Och Presterna, och Leviterna, och dörravaktarena, sångare, och somlige af folket, och de Nethinim, och hele Israel, satte sig uti sina städer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Då nu sjunde månaden kom, och Israels barn voro i sina städer, församlade sig allt folket, såsom en man, på breda gatone inför vattuporten, och sade till Esra den skriftlärda, att han skulle hemta fram Mose lagbok, som Herren Israel budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Och Esra Presten hemtade fram lagen inför menighetena, både män och qvinnor, och för alla dem som det förstå kunde, på första dagen i sjunde månadenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Och las deruti, på breda gatone, som för vattuporten är, allt ifrå morgonlysningen intill middag, för män och qvinnor, och för dem som det förstå kunde; och hela folkens öron voro vänd till lagbokena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Och Esra den Skriftlärde stod uppå en hög trästol, den de till predikan gjort hade; och när honom stodo Mattithia, Serna, Anaja, Uria, Hilkia och Maaseja, på hans högra sido; och på hans venstra Pedaja, Misael, Malchija, Hasum, Hasbadana, Zacharia och Mesullam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Och Esra lät upp bokena för hela folket; förty han stod högt öfver allt folket; och då han upplät henne, stod allt folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Och Esra lofvade Herran den stora Guden; och allt folket svarade: Amen, Amen, med uppräckta händer; och bugade sig, och tillbådo Herran med ansigtet ned på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Och Jesua, Bani, Serebia, Jamin, Akkub, Sabbethai, Hodija, Maaseja. Kelita, Asaria, Josabad, Hanan, Pelaja, och Leviterna, beställde att folket gaf akt uppå lagen; och folket stod uppå sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Och de läste uti Guds lagbok klarliga och förståndeliga, så att man förstod, då läset vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Och Nehemia, hvilken är Thirsatha, och Esra Presten, den Skriftlärde, och Leviterna, som folket höllo till att akta på, sade till allt folket: Denne dagen är helig Herranom edrom Gud; derföre sörjer intet, och gråter icke; ty allt folket gret, då de hörde lagsens ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Derföre sade han till dem: Går bort, och äter det feta, och dricker det söta, och sänder dem ock delar, som intet för sig tillredt hafva; förty denne dagen är helig vårom Herra. Derföre bekymrer eder icke; ty fröjd i Herranom är edor starkhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Och Leviterna stillade allt folket, och Sade: Varer tyste, ty dagen är helig; bekymrens intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Och allt folket gick bort till att äta, dricka och del sända, och gjorde sig en stor glädje; förty de hade förståndit orden, som man dem förkunnat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'På annan dagen församlade sig öfversta fäderna ibland allt folket, och Presterna, och Leviterna, till Esra den Skriftlärda, att han skulle undervisa dem i lagsens ordom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Och de funno beskrifvet i lagen, att Herren genom Mose budit hade, att Israels barn skulle bo i löfhyddor, på den högtidene i sjunde månadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Och de läto det varda kunnigt, och utropadt i alla deras städer, och i Jerusalem, och sade: Går ut uppå berget, och hemter oljoqvistar, balsamqvistar, myrthenqvistar, palmqvistar och qvistar af tjockqvistadt trä, att man må göra löfhyddor, såsom skrifvet står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Och folket gick ut, och hemtade, och gjorde sig löfhyddor, hvar uppå sitt tak, och i sina gårdar, och i Guds hus gårdar; och uppå den breda gatone vid vattuporten, och uppå den breda gatone vid Ephraims port.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Och hela menigheten af dem, som af fängelset igenkomne voro, gjorde löfhyddor, och bodde deruti; ty Israels barn hade ifrå Josua, Nuns sons, tid, allt intill denna dag, intet så gjort; och var en ganska stor glädje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Och vardt hvar dag läset i Guds lagbok, ifrå första dagen allt intill den yttersta; och de höllo den högtiden i sju dagar; och på åttonde dagen församlingenes dag, såsom det borde sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'På fjerde och tjugonde dagen i denna månadenom kommo Israels barn tillsammans med fasto, och säcker, och mull uppå dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Och afskiljde Israels säd ifrån all främmande barn, och gingo fram, och bekände sina synder och sina fäders missgerning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Och stodo upp i sin rum; och man las i Herrans deras Guds lagbok, fyra gånger om dagen; och de bekände och tillbådo Herran sin Gud, fyra gånger om dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Och Leviterna stodo upp i höjdene; nämliga Jesua, Bani, Kadmiel, Sebanja, Bunni, Serebia, Bani och Chenani, och ropade högt till Herran deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Och Leviterna, Jesua, Kadmiel, Bani, Hasabnia, Serebia, Hodija, Sebanja, Pethahja, sade: Står upp, och lofver Herran edar Gud ifrån evighet till evighet; och man lofve dins härlighets Namn, hvilken upphöjd är med all välsignelse och lof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Herre, du äret allena; du hafver gjort himmelen och alla himlars himlar, med all deras här, jordena och allt det deruppå är, hafvet och allt det derinne är: du gör allt lefvande, och den himmelske hären tillbeder dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du äst Herren Gud, som Abram utvalde, och förde honom ut ifrån Ur i Chaldeen, och nämnde honom Abraham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Och du fann hans hjerta trofast för dig, och gjorde ett förbund med honom, till att gifva hans säd de Cananeers, Hetheers, Amoreers, Phereseers, Jebuseers och Girgaseers land; och du hafver hållit din ord; ty du äst rättfärdig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Och du hafver sett till våra fäders jämmer i Egypten, och hört deras rop vid röda hafvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Och gjort tecken och under på Pharao, och alla hans tjenare, och på allt folket i hans land; ty du förnam, att de voro stolte emot dem; och hafver gjort dig ett Namn, såsom det i denna dag för ögon är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Och hafver åtskiljt hafvet för dem, så att de gingo torre midt igenom hafvet; och kastat deras förföljare i djupet, såsom stenar i mägtig vatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Och fört dem om dagen uti en molnstod, och om nattena uti en eldstod, till att lysa dem på vägen, den de drogo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Och hafver nederstigit uppå berget Sinai, och talat med dem af himmelen, och gifvit dem rättvisa rätter, och trofast lag, god bud och seder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Och kungjort dem din helga Sabbath; och budit dem bud, seder och lag, genom din tjenare Mose;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Och gifvit dem bröd af himmelen, då de hungrade, och låtit gå vatten utaf bergklippone, då dem törste; och sagt dem, att de skulle gå in, och taga in landet, der du dina hand öfver upplyft hade, att du skulle det gifva dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Men våre fäder vordo stolte och halsstyfve, så att de icke lydde din bud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Och ville icke höra dem, och tänkte intet uppå din under, som du med dem gjort hade; utan vordo halsstyfve, och uppkastade en höfvitsman, att de skulle vända sig till sin träldom i sine olydno; men du, (min) Gud, gaf dem till, och var dem nådelig, barmhertig, tålig, och af en stor barmhertighet, och öfvergaf dem icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Och ändock de gjorde en gjuten kalf, och sade: Det är din Gud, som dig utur Egypti land fört hafver; och gjorde stor försmädelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Likväl öfvergaf du dem icke i öknene, efter din stora barmhertighet; och molnstoden vek icke ifrå dem om dagen, att ledsaga dem på vägen; ej heller eldstoden om nattena, till att lysa dem på vägen, den de drogo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Och du gafst din goda Anda, till att undervisa dem; och ditt Man vände du icke ifrå deras mun, och gaf dem vatten, när dem törste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'I fyratio år besörjde du dem i öknene, så att dem intet fattades; deras kläder föråldrades intet, och deras fötter svullnade intet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Och gaf dem rike och folk, och fördelade dem här och der, så att de intogo Sihons land, Konungens i Hesbon, och Ogs land, Konungens i Basan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ock förökade du deras barn, såsom stjernorna på himmelen, och lät komma dem i landet, det du deras fader tillsagt hade, att de skulle draga derin, och intaga det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Och barnen kommo derin, och togo landet in; och du undertryckte för dem landsens inbyggare, de Cananeer, och gafst dem uti deras händer, och deras Konungar, och folken i landena, så att de gjorde med dem efter sin vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Och de vunno fasta städer, och ett fett land, och intogo hus full med allahanda ägodelar, uthuggna brunnar, vingårdar, oljogårdar och trä, der man af äter, väl mång. Och de åto och vordo mätte och fete, och lefde i vällust af dine stora godhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Men de vordo olydige, och vordo dig genstörtige, och kastade din lag tillrygga bakom sig, och slogo ihjäl dina Propheter, som dem betygade att de skulle omvända sig till dig; och gjorde stor försmädelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Derföre gafst du dem uti deras fiendars hand, hvilke dem betvingade; och uti deras ångests tid ropade de till dig; och du hörde dem af himmelen, och genom dina stora barmhertighet gafst du dem frälsare, som dem hulpo utu deras fiendars hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'När de nu till rolighet kommo, vände de om igen, till att göra det ondt var för dig; så öfvergaf du dem uti deras fiendars hand, att de skulle råda öfver dem. Så omvände de sig då, och ropade till dig; och du hörde dem af himmelen, och halp dem efter dina stora barmhertighet i flera resor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Och du lät betyga dem, att de skulle omvända sig till din lag; men de voro stolte, och lydde intet din bud, och syndade emot dina rätter; hvilka om en menniska gör, lefver hon derutinnan; och vände sina skuldror bort, och vordo halsstyfve, och lydde intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Och du fördröjde i mång år med dem, och lät betyga dem genom din Anda i dina Propheter: men de skötte der intet om, derföre hafver du gifvit dem i folks hand i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Dock, af dine stora barmhertighet, hafver du icke platt gjort ända på dem, eller öfvergifvit dem; förty du äst en nådelig och barmhertig Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nu, vår Gud, du store Gud, mägtige och förskräckelige, du som håller förbund och barmhertighet; akta icke ringa all den vedermöda, som på oss drabbat hafver, och på våra Konungar, Förstar, Prester, Propheter, fäder, och allt ditt folk, ifrå Konungarnas tid i Assur, allt intill denna dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du äst rättvis i allt det du hafver låtit komma öfver oss; ty du hafver gjort rätt, men vi hafve varit ogudaktige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Och våre Konungar, Förstar, Prester och fäder, hafva icke gjort efter din lag, och intet aktat på din bud och vittnesbörd, som du hafver låtit betyga dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Och de hafva icke tjent dig i sitt rike, och i dina stora ägodelar, som du dem gifvit hafver, och uti det vida och feta landet, som du dem infått hafver, och hafva icke omvändt sig ifrå sitt onda väsende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Si, vi äre i denna dag trälar, och i de lande, som du våra fäder gafst, till att äta dess frukt och goda, si, der äre vi trälar uti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Och dess årsväxt förökar sig Konungomen, som du öfver oss satt hafver för våra synders skull; och de råda öfver våra kroppar och vår boskap, efter sin vilja; och vi äre i stor nöd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Och i allt detta göre vi nu ett fast förbund, och skrifvom, och låte våra Förstar, Leviter och Prester besegla det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Men de som beseglade det, voro desse: Nehemia Thirsatha, Hachalia son, och Zedekia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Asaria, Jeremia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amaria, Malchija,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebanja, Malluch,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremoth, Obadja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginnethon, Baruch,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Mijamin,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maasia, Bilgai, och Semaja: De voro Presterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Men Leviterna voro: Jesua, Asanja son, Binnui af Henadads barnom, Kadmiel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Och deras bröder, Sebanja, Hodija, Kelita, Pelaja, Hanan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rehop, Hasabia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Saccur, Serebia, Sebanja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani och Benihu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hufvuden i folken voro: Paros, PahathMoab, Elam, Sattu, Bani,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Asgad, Bebai,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonia, Bigvai, Adin,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hiskia, Assur,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Hasum, Bezai,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Anathoth, Nebai,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Hesir,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesesabeel, Zadok, Jaddua,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Hanan, Anaja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosea, Hanania, Hasub,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallohes, Pilha, Sobek,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maaseja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahija, Hanan, Anan,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluch, Harim och Baana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Och det andra folket, Presterna, Leviterna, dörravaktarena, sångarena, Nethinim, och alle de som hade söndrat sig ifrå folken i landen, intill Guds lag, med sina hustrur, söner och döttrar, alle de som det kunde förstå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Och deras mägtige, togo sig det till för sina bröder, och de kommo till att svärja och förpligta sig med ed, till att vandra i Guds lag, som igenom Guds tjenare Mose gifven är, att de hålla och göra ville efter all Herrans vår Guds bud, rätter och seder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Och att vi icke skulle gifva folken i landena våra döttrar; ej heller vårom sönom taga deras döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Desslikes, när folket i landet förer om Sabbathsdagen någon varo och allahanda spisning, till att sälja, att vi icke ville taga det af dem om Sabbathen och helgedagar; och att vi i sjunde årena ville göra förlösning på allahanda tunga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Och lägga ett bud uppå oss, att vi årliga gifva skulle en tridiung af en sikel silfver, till tjensten i vår Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Nämliga till skådobröd, till dagligit spisoffer, till dagligit bränneoffer, på Sabbaths, nymånads och högtidsdagom, och till det helgada, och till syndoffer, der Israel skulle med försonad varda, och till all verk i vår Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Och vi kastade lott emellan Presterna, Leviterna och folket, om vedoffer, det man till vår Guds hus årliga framföra skulle, efter våra fäders hus, på bestämd tid, att bränna på Herrans vår Guds altare, såsom det i lagen skrifvet är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Och till att årliga frambära förstlingen af vårt land, och förstlingen af allo frukt, af all trä till Herrans hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Och förstlingen af vara söner, och af vår boskap, såsom det i lagen skrifvet står; och förstlingen af vårt fä, och af vår får, att vi allt detta skulle hafva in uti vår Guds hus till Presterna, som i vår Guds hus tjena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Och att vi ville frambära förstlingen af vår deg, och vårt häfoffer, och frukt af allahanda trä, vin och oljo, till Presterna, i kistorna vid vår Guds hus; och vårt lands tiond till Leviterna, så att Leviterna skulle hafva tionden i alla städer, der vårt åkerverk är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Och Presten Aarons son skall ock del hafva af Leviternas tiond, med Leviterna; så att Leviterna skola bära tionden af sine tiond upp till vår Guds hus, i kistorna, uti skatthuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Ty Israels barn, och Levi barn, skola bära häfoffret af säd, vin och oljo, upp i kistorna. Dersammastäds äro helgedomens kärile, och Presterna, som der tjena, och dörravaktare, och sångare; att vi vår Guds hus icke öfvergifve.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Och öfverstarna för folket bodde i Jerusalem; men det andra folket kastade lott derom, att af tio skulle en del draga till Jerusalem, den helga staden, till att bo der, och nio delar i städerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Och folket välsignade alla de män, som friviljoge voro till att bo i Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Desse äro hufvuden i landskapen, de som i Jerusalem bodde; men i Juda städer bodde hvar och en på sina ägor, som i deras städer voro; nämliga Israel, Presterna, Leviterna, Nethinim och Salomos tjenares barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Och i Jerusalem bodde någre af Juda barn, och BenJamin. Af Juda barn: Athaja, Ussia son, Zacharia sons, Amaria sons, Sephatja sons, Mahalaleels sons, af Parez barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Och Maaseja, Baruchs son. CholHose sons, Hasaja sons, Adaja sons, Jojaribs sons, Zacharia sons, Siloni sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'All Parez barn, som i Jerusalem bodde, voro fyrahundrad åtta och sextio dugelige män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Desse äro BenJamins barn: Sallu, Mesullams son, Joeds sons, Pedaja sons, Kolaja sons, Maasesa sons, Ithiels sons, Jesaja sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'Och efter honom Gabbai, Sallia, niohundrad åtta och tjugu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Och Joel, Sichri son, var deras föreståndare; och Juda, Hasuna son, öfver den andra delen i stadenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Af Presterna bodde: Jedaja, Jojaribs son, Jachin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, Hilkia son, Mesullams sons, Zadoks sons, Merajoths sons, Ahitobs sons, var Förste i Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Och deras bröder, som i husena skaffa hade, voro åttahundrad två och tjugu. Och Adaja, Jerohams son, Pelalja sons, Amzi sons, Zacharia sons, Pashurs sons, Malchija sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Och hans bröder öfverstar ibland fäderna, voro tuhundrad två och fyratio; och Amassai, Asareels son, Ahsai sons, Mesillemoths sons, Immers sons,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Och deras bröder, väldige män, voro hundrade åtta och tjugu; och deras föreståndare var Sabdiel, Gedolims son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Af Leviterna: Semaja, Hasubs son, Asrikams sons, Hasabia sons, Bunni sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Och Sabbethai, och Josabad af Leviternas öfverstar, uti de ärende, som utantill voro vid Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Och Matthania, Micha son, Sabdi sons, Assaphs sons, den hufvudet var till att begynna tacksägelse i bönene; och Bakbukia den andre ibland sina bröder: och Abda, Sammua son, Galals sons, Jeduthuns sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Alle Leviterna i dem helga stadenom voro tuhundrad fyra och åttatio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Och dörravaktarena, Akkub och Talmon, och deras bröder, som vid dörrarna vaktade, voro hundrade två och sjutio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Men de andre Israel, Prester och Leviter, voro uti alla Juda städer, hvar och en i sinom arfvedel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Och de Nethmim bodde i Ophel; och Ziha, och Gispa hörde till de Nethinim.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Föreståndaren öfver de Leviter i Jerusalem var Ussi, Bani son, Hasabia sons. Mattania sons, Micha sons. Utaf Assaphs barn voro sångare vid tjensten i Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Förty Konungens bud var öfver dem, att sångarena skulle handla troliga, hvar och en på den dag, som honom borde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Och Petahja, Mesesabeels son, af Serahs barn, Juda sons, var i Konungens stad i all ärende till folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Och Juda barn, som ute voro på bygdene i sin land, bodde somlige i KiriathArba, och i dess döttrom, och i Dibon, och i dess döttrom, och i Kabzeel, och dess döttrom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Och i Jesua, Molada, BethPhalet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'HazarSual, BerSeba, och dess döttrom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Och i Ziklag, och Mechona, och dess döttrom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Och i EnRimmon, Sarega, Jarmuth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Sanoah, Adullam, och dess döttrom; i Lachis, och på dess mark; i Aseka, och i dess döttrom. Och de lägrade sig, allt ifrå BerSeba intill Hinnoms dal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Men BenJamins barn af Geba bodde i Michmas, Aija, BethEl och dess döttrar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Och i Anathoth, Nob, Anania,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Rama, Gittaim,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Zeboim, Neballat,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod, Ono, i timberdalenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Och somlige Leviterna, som del hade i Juda, bodde ibland BenJamin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Desse äro de Prester och Leviter, som uppdrogo med Serubbabel, Sealthiels son, och Jesua: Seraja, Jeremia, Esra,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluch, Hattus,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechania, Rehum, Meremoth,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnethoi, Abia,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadia, Bilga,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkia och Jedaja. Desse voro hufvuden ibland Presterna, och deras bröder i Jesua tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Men Leviterna voro desse: Jesua, Binnui, Kadmiel, Serebia, Juda och Mattania, öfver tackämbetet, han och hans bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Bakbukia och Unni, deras bröder, voro omkring dem i vakt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua födde Jojakim. Jojakim födde Eljasib. Eljasib födde Jojada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada födde Jonathan. Jonathan födde Jaddua.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Och i Jojakims tid voro desse öfverste fäder ibland Presterna, nämliga af Seraja var Meraja; af Jeremia var Hanania;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Af Esra var Mesullam; af Amaria var Johanan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Af Malluch var Jonathan; af Sebania var Joseph;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Af Harim var Adna; af Merajoth var Helkai;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Af Iddo var Zacharia; af Ginnethon var Mesullam;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Af Abia var Sichri; af MinjaminMoadia var Piltai;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Af Bilga var Sammua; af Semaja var Jonathan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Af Jojarib var Mattenai; af Jedaja var Ussi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Af Sallai var Kallai; af Amok var Eber;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Af Hilkia var Hasabia; af Jedaja var Nethaneel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Och i Eljasibs tid, Jojada, Johanan och Jaddua, vordo öfverste fäderna ibland Leviterna och Presterna beskrifne, under Darios, den Persens rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Men Levi barn, öfverste fäderna vordo beskrifne i Chrönicon, allt intill Johanans tid, Eljasibs sons.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Och desse voro öfverstarne i Leviterna: Hasabia, Serebia och Jesua, Kadmiels son; och deras bröder jemte dem, till att lofva och tacka, såsom den Guds mannen David det budit hade, den ena vakten vid den andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattania, Bakbukia, Obadja, Mesullam, Talmon och Akkub, voro dörravaktare i vaktene vid dörrena i portomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Desse voro i Jojakims tid, Jesua sons, Jozadaks sons; och i Nehemia den landshöfdingans, och Prestens Esra den Skriftlärdas tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Och uti murens vigning i Jerusalem sökte man Leviterna utur all deras rum, att man skulle hafva dem till Jerusalem, till att hålla vigning med glädje, med tacksägelse, med sång, med cymbaler, psaltare och harpor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Och sig församlade sångarenas barn, och af den ängden omkring Jerusalem, och af Netophati byar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Och af Gilgals hus, och af den mark i Geba, och Asmaveth; förty sångarena hade byggt sig byar omkring Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Och Presterna och Leviterna renade sig, och renade folket, portarna och muren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Och jag lät Juda Förstar stiga upp på muren, och beställde två stora tackchorar; de gingo åstad, den ene på högra sidone ofvan uppå murenom, åt dyngoporten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Och efter dem gick Hosaja, och hälften af Juda Förstar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Och Asaria, Esra, Mesullam,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, BenJamin, Semaja och Jeremia;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Och någre af Prestabarnen med trummeter, nämliga Zacharia, Jonathans son, Semaja sons, Mattania sons, Michaja sons, Saccurs sons, Assaphs sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Och hans bröder, Semaja, Asareel, Milalai, Gilalai, Maai, Nethaneel och Juda, Hanani med den Guds mansens Davids strängaspel; men Esra den Skriftlärde för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Och vid brunnporten, gentöfver dem, gingo de på trappomen åt Davids stad, uppåt muren om Davids hus, allt intill vattuporten östantill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Den andre tackchoren gick tvärsifrå dem, och jag efter honom, och hälften af folket, utåt murenom uppåt ugnatornet, allt intill den breda muren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'Och uppåt Ephraims port, och till gamla porten, och till fiskaporten, och till Hananeels torn, och till Mea torn, allt intill fåraporten; och blefvo ståndande i fängelseportenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Och stodo alltså de två tackchorer uti Guds huse, och jag, och hälften af öfverstarna med mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Och Presterna, nämliga Eljakim, Maaseja, Minjamin, Michaja, Eljoenai, Zacharia, Hanania, med trummeter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Och Maaseja, Semaja, Eleasar, Ussi, Johanan, Malchija, Elam och Eser; och sångarena söngo högt; och Jisrahja var föreståndaren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Och stor offer vordo offrad på den samma dagen, och de voro glade; ty Gud hade gjort dem en stor glädje, så att både qvinnor och barn fröjdade sig; och Jerusalems glädje hördes långan väg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'På den tiden vordo män förskickade öfver skattkistona, der häfoffer, förstling och tiond uti var, att de skulle samka tillhopa af åkromen omkring städerna, till att utdela efter lagen för Prester och Leviter; ty Juda hade en glädje af Presterna och Leviterna, att de stodo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Och de höllo sins Guds vakt, och reningenes vakt; och sångarena och dörravaktarena stodo efter Davids och hans sons Salomos bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Förty i Davids och Assaphs tid vordo stiktade öfverste sångare, och lofsånger, och tacksägningar till Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Men hele Israel gaf sångarena och dörravaktarena delar uti Serubbabels och Nehemia tid, hvar dagen sin del. Och de gåfvo af det helgada Levitomen; och Leviterna gåfvo Aarons barnom af det helgada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Och på den tid vardt Mose bok läsen för folkens öron; och vardt funnet deruti skrifvet, att de Ammoniter och de Moabiter skulle aldrig komma uti Guds församling;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Derföre, att de icke mötte Israels barnom med bröd och vatten, utan lejde Bileam emot dem, att han skulle förbanna dem; ändock vår Gud vände den förbannelsen uti välsignelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Då de nu hörde denna lagen, af skiljde de allt blandningsfolk ifrån Israel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Och tillförene hade Presten Eljasib lagt Tobia håfvor uti offerkammaren, i vår Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Förty han hade gjort honom en stor kammar, der de hade tillförene lagt spisoffer, rökelse, redskap och tiond af säd, vin och oljo, efter Leviternas, sångarenas och dörravaktarenas bud; dertill Presternas häfoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Men i allt detta var jag icke i Jerusalem; ty uti andra och tretionde årena Arthahsasta, Konungens i Babel, kom jag till Konungen; och efter några dagar förvärfde jag lof af Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Och jag drog åter till Jerusalem; och jag förmärkte, att det icke godt var, som Eljasib med Tobia gjort hade, i det han gjorde honom en kammar i gårdenom till Guds hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Och mig förtröt det svårliga; och jag kastade all Tobia hus tyg ut för kammaren,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Och bad, att de skulle rena kamrarna; och jag lät komma dit i samma staden Guds hus tyg, spisoffer och rökelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Och jag förnam, att Leviternas delar vordo dem icke gifne; för hvilka sak Leviterna och sängarena voro bortflydde, hvar till sin åker, till att arbeta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Då straffade jag öfverstarna, och sade: Hvi öfvergifve vi Guds hus? Men jag församlade dem, och satte dem i sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Och hele Juda lät komma fram tiond af säd, vin och oljo, i drätselen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Och jag satte öfver drätselen Selemia Presten, och Zadok den Skriftlärda, och af Leviterna, Pedaja; och under deras hand Hanan, Saccurs son, Mattania sons; förty de voro hållne för trogna män, och dem vardt befaldt utskifta sinom brödrom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Tänk uppå mig, min Gud, derföre, och bortkasta icke mina barmhertighet, som jag med mins Guds huse, och i hans vakt, gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'På samma tiden såg jag i Juda trampas i presserna om Sabbathen, och införas kärfvar, och åsnar ladda med vin, drufvor, fikon och allahanda bördor, till Jerusalem, på Sabbathsdagen; och jag betygade dem på den dagen, då de sålde spisningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Bodde desslikes Tyrer derinne; de förde fisk och allahanda varor, och sålde det på Sabbatherna, Juda barnom och Jerusalem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Då straffade jag de öfversta i Juda, och sade till dem: Hvad är det för en ond ting, som I gören, och bryten Sabbathsdagen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Gjorde icke våre fäder så, och vår Gud lät komma alla denna olyckon öfver oss, och öfver denna staden? Och I gören ännu vredena öfver Israel större, brytande Sabbathen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Och då portarna i Jerusalem uppdragne voro för Sabbathen, böd jag tillsluta portarna, och befallde, att man icke skulle upplåta dem intill efter Sabbathen; och jag satte några af mina tjenare vid portarna, att ingen börda skulle föras derin om Sabbathsdagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Så blefvo de krämare och köpmän, med allahanda varor, om nattena, utanför porten af Jerusalem, en gång och annan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Då betygade jag dem, och sade till dem: Hvi blifven I om nattene utanför muren? Om I gören så mer, skall min hand komma uppå eder. Ifrå den tiden kommo de intet om Sabbathen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Och jag sade till Leviterna, som rene voro, att de skulle komma och vakta portarna, till att helga Sabbathsdagen. Min Gud, tänk ock på mig för detta här, och skona mig efter dina stora barmhertighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Jag såg ock på den tiden, att Judarna togo sig hustrur af Asdod, Ammon och Moab;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Och deras barn talade half Asdodisko, och kunde icke tala Judisko, utan efter hvars folkens mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Och jag straffade dem, och bannade dem, och slog några män, och hårdrog dem, och tog en ed af dem vid Gud: I skolen icke gifva edra döttrar deras söner, icke heller taga deras döttrar till edra söner, eller till eder sjelf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hafver icke Salomo, Israels Konung, syndat dermed? Och var dock ibland många Hedningar ingen Konung honom lik. Och han var sinom Gud kär; och Gud satte honom till Konung öfver hela Israel. Likväl kommo de utländska qvinnor honom till att synda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Hafven I det icke hört, medan I sådant stort ondt gören, och förtagen eder emot vår Gud med främmande qvinnors giftermål?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Och en af Jojada barn, Eljasibs sons, öfversta Prestens, hade befryndat sig med Saneballat den Horoniten; men jag dref honom ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Tänk uppå dem, min Gud, som besmitta Presterskapet, och Presterskapens förbund, och Leviternas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Alltså renade jag dem ifrån alla utländska; och beställde Presternas och Leviternas vakt, hvar och en till sitt ämbete;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Och till att offra ved, på bestämd tid, och förstling. Tänk uppå mig, Gud, till det bästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Uti Ahasveros tid, hvilken rådandes var, allt ifrån Indien intill Ethiopien, öfver hundrade sju och tjugu land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Då han satt på sinom Konungsliga stol, i den staden Susan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'I tredje årena hans rikes, gjorde han ett gästabåd när sig, åt alla sina Förstar och tjenare; nämliga dem väldigom i Persien och Meden, landshöfdingom och öfverstom i sin land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'På det han skulle låta se sins rikes härliga rikedomar och det kosteliga prål af sitt majestät, i många dagar, nämliga i hundrade och åttatio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Då de dagar ute voro, gjorde Konungen ett gästabåd allo folkena, som i stadenom Susan var, både stora och små, i sju dagar, uti en sal i trägårdenom invid Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Der voro upphängd hvit, röd och gul tapeter, fattad med linnen och skarlakanståg, uti silfringar på marmorstodar. Bänkerna voro af guld och silfver, på golfvena, som lagdt var med grön, hvit, gul och svart marmorsten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Och dryckerna bar man in uti gyldene kar, och ju annor och annor kar, och Konungsligit vin tillfyllest, såsom Konungen det väl förmådde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Och man lade ingom före hvad han dricka skulle; ty Konungen hade befallt alla föreståndarena i sitt hus, att hvar och en skulle göra såsom honom lyste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Och Drottningen Vasthi gjorde också ett gästabåd för qvinnorna uti Konungshusena, der Konung Ahasveros plägade vistas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Och på sjunde dagen, då Konungen vardt lustig af vinet, sade han till Mehuman, Bistha, Harbona, Bigtha, Abagtha, Sethar och Charcas, de sju kamererare, som för Konung Ahasveros tjente,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Att de skulle hafva Drottning Vasthi in för Konungen, med Drottningakrono, på det han skulle låta folket och Förstarna se hennes dägelighet; ty hon var dägelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Men Drottning Vasthi ville icke komma efter Konungens ord, genom hans kamererare. Då vardt Konungen ganska vred, och upptänd i grymhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Och Konungen sade till de visa, som i landsseder förfarne voro; ty Konungens ärende måste hafvas inför alla förståndiga i lag och rätt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Men de näste, som när honom voro, voro Charsena, Sethar, Admatha, Tharsis, Meres, Marsena och Memuchan, de sju Förstar af Persien och Meden, som sågo på Konungens ansigte, och såto främst i rikena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Hvad man göra skulle Drottning Vasthi för en rätt, derföre, att hon icke gjort hade efter Konungens ord, genom hans kamererare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Då sade Memuchan inför Konungenom och Förstarna: Drottning Vasthi hafver icke allenast illa gjort emot Konungen, utan ock emot alla Förstar, och allt folk uti Konung Ahasveros landom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Förty detta stycket af Drottningen kommer väl ut till alla qvinnor, så att de skola förakta sina män för sin ögon, och skola säga: Konung Ahasveros böd Drottningene Vasthi komma inför sig, men hon ville icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Så varda nu de Förstinnor i Persien och Meden sammalunda sägande till alla Konungens Förstar, när de få detta Drottningenes stycke höra; så skall föraktelse och vrede nog upphäfva sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Om Konungenom så täckes, så låte han ett Konungsligit bud af sig utgå, och skrifva efter de Persers och Meders lag, hvilken man icke öfverträda tör, att Vasthi icke mer skall komma inför Konung Ahasveros; och Konungen gifve hennes rike hennes nästo, den bättre är än hon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Och att detta Konungens bref, som göras skall, må förkunnadt varda i hela rikena, det väl stort är, att alla qvinnor måga hålla sina män för ögon, ibland både små och stora.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Detta täcktes Konungenom och Förstarna; och Konungen gjorde efter Memuchans ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Då vordo bref utsänd i all Konungens land, i hvart landet efter dess skrift, och till hvart folk efter dess tungomål, att hvar och en man skulle vara husbonde i sitt hus; och lät tala efter sins folks tungomål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Sedan detta skedt var, när Konungens Ahasveros vrede hade saktat sig, kom han Vasthi ihåg, hvad hon gjort hade, och hvad om henne beslutet var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Då sade Konungens svenner, som honom tjente: Man söke Konungenom upp dägeliga unga jungfrur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Och Konungen beställe skådare i all land i sitt rike, att de låta komma tillhopa alla dägeliga unga jungfrur, intill den staden Susan i fruhuset, under Hegai hand, Konungens kamererares, hvilken qvinnorna vakta skulle, och få dem deras skrud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Och hvilken pigan Konungenom täckes, den blifve Drottning i Vasthis stad. Det behagade Konungenom, och han gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Då var en Judisk man i Susans stad, han het Mardechai, Jairs son, Simei sons, Kis sons, Jemini sons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Den med bortförd var ifrå Jerusalem, då Jechonia, Juda Konung, bortförd var, hvilken NebucadNezar, Konungen i Babel, bortförde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Och han var förmyndare till Hadassa, denna är Esther, sins faderbroders dotter; förty hon hade hvarken fader eller moder, och hon var en fager och dägelig piga; och då hennes fader och moder blefvo döde, tog Mardechai henne för sin dotter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Då Konungens bud och beslut vardt kunnigt, och många pigor voro tillhopahemtade till staden Susan, under Hegai hand, vardt Esther ock tagen uti Konungshuset, under Hegai hand, qvinnovaktarens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Och pigan täcktes honom, och hon fann barmhertighet för honom; och han skyndade sig med hennes skrud, att han skulle få henne hennes del, och sju dägeliga pigor utaf Konungshuset dertill; och han satte henne med hennes pigor uti bästa rummet i fruhuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Och Esther sade honom intet utaf sitt folk, eller sitt slägte; förty Mardechai hade budit henne, att hon skulle icke sägat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Och Mardechai spatserade hvar dag i gårdenom åt fruhuset, att han måtte förnimma, om väl ginge med Esther, och hvad med henne ske kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Då nu hvarjo pigones bestämda tid kom, att hon skulle komma till Konungen Ahasveros, sedan hon hade varit i tolf månader i fruprydning; förty deras prydelse måste så mycken tid hafva, nämliga sex månader med balsam och myrrham, och sex månader med godt speceri, så voro då qvinnorna tillprydda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Och så gick då en piga in till Konungen; och hvilka hon ville, måste man få henne, som med henne gå skulle ifrå fruhuset till Konungshuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Och när en om aftonen inkom, gick hon om morgonen ifrå honom in uti det andra fruhuset, under Saasgas hand, Konungens kamererares, frillovaktarens; och hon måste icke komma igen till Konungen, utan Konungenom täcktes, och han lät kalla henne vid namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Då nu Esthers tid kom, Abihails dotters, Mardechai faderbroders, den henne för dotter tagit hade, att hon skulle komma till Konungen, begärade hon intet annat, än det Hegai, Konungens kamererare, qvinnovaktaren, sade henne före. Och Esther fann nåd för alla dem, som sågo uppå henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Men Esther vardt tagen till Konungen Ahasveros, uti Konungshuset, i tionde månadenom, den Thebeth kallas; i sjunde årena hans rikes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Och Konungen fick Esther kär öfver alla qvinnor, och hon fann nåd och barmhertighet för honom, för alla jungfrur; och han satte Drottningakrono uppå hennes hufvud, och gjorde henne till Drottning i Vasthis stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Och Konungen gjorde ett stort gästabåd, till alla sina Förstar och tjenare; det gästabådet var för Esthers skull; och lät landen hafva rolighet, och gaf ut Konungsliga skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Och då man annan gång församlade jungfrur, satt Mardechai vid Konungens dörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Och Esther hade ännu icke sagt sitt slägte, eller folk, såsom Mardechai henne budit hade; ty Esther gjorde efter Mardechai ord, lika som då han hennes förmyndare var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'På samma tiden, då Mardechai vid Konungens dörr satt, vordo två Konungens kamererare vrede, Bigthan och Theres, som dörrena vaktade, och hade i sinnet, att de ville slå uppå Konungen Ahasveros.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Det förnam Mardechai, och lät Drottningena Esther få veta det; och Esther sade det för Konungenom, på Mardechai vägnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Och då man ransakade derefter, vardt det så funnet; och de vordo både hängde i trän; och det vardt beskrifvet i Chrönicon för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Sedan detta skedt var, uppsatte Konungen Haman, Medatha son, den Agagiten, och upphöjde honom; och satte hans stol öfver alla Förstar, som när honom voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Och alle Konungens tjenare, som för Konungens dörr vistades, böjde knän och tillbådo Haman: ty Konung Ahasveros hade så budit. Men Mardechai böjde icke knän, och tillbad honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Då sade Konungens tjenare, som för Konungens dörr voro, till Mardechai: Hvi öfverträder du Konungens bud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Och som de hvar dag sade honom sådant, och han skötte intet derom, sade de det för Haman, att de skulle få se, om Mardechai ville blifva ståndandes vid sin ord; ty han hade sagt dem, att han var en Jude.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Och då Haman såg, att Mardechai icke böjde honom knän, ej heller tillbad honom, vardt han full med grymhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Och räknade för litet, att han skulle bära sina hand på Mardechai allena; ty de hade sagt honom om Mardechai folk; utan han for efter att förgöra Mardechai folk, alla de Judar som i hela Ahasveros rike voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Uti första månadenom, det är i den månaden Nisan, i tolfte årena Konungs Ahasveros, vardt lotten kastad för Haman, ifrå den ena dagen till den andra, och ifrå månad, allt intill den tolfte månaden, det är den månaden Adar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Och Haman sade till Konung Ahasveros: Ett folk är förströdt, och hafver delat sig ibland all folk i all dins rikes land, och deras lag äro annor än all folks, och de göra icke efter Konungens lag; och Konungenom står icke till görande att låta dem så blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Om Konungenom så täckes, så skrifve att man förgör dem; så vill jag uppväga tiotusend centener silfver i arbetares hand, till att låta inkomma uti Konungens kammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Då tog Konungen sin ring af handene, och fick Haman, Medatha son, dem Agagitenom, Judarnas fienda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Och Konungen sade till Haman: Silfret vare dig skänkt, och folket dertill, att du må dermed göra hvad dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Då kallade man Konungens skrifvare, på trettonde dagen i första månadenom; och vardt skrifvet, såsom Haman befallde, till Konungens Förstar och till landshövdingarna, både här och der i landen, och till höfvitsmännerna för hvart folket i landen här och der, efter hvars och ens folks skrift, och efter deras mål, under Konung Ahasveros namn, och med Konungens insegel försegladt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Och brefven vordo försänd med båd, uti all Konungens land, till att förgöra, dräpa och förlägga alla Judar, både unga och samla, barn och qvinnor, allt på en dag, nämliga på trettonde dagen i tolfte månadenom, det är den månaden Adar; och till att sköfla deras gods.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Alltså höll brefvet inne, att ett båd utgånget var i all land, till att förkunna all folk, att de på den samma dagen skulle redo vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Och båden gingo ut med hast, efter Konungens befallning, och i staden Susan vardt uppslaget ett påbud; och Konungen och Haman såto och drucko; och staden Susan vardt bekymrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Då Mardechai förnam hvad skedt var, ref han sin kläder sönder, och drog en säck uppå, och strödde asko uppå sig; och gick ut midt i staden, ropandes högeliga och klageliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Och kom inför Konungens dörr; ty ingen måtte komma in genom Konungens dörr, som en säck hade på sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Och i all land, dit som Konungens ord och bud räckte, var en stor jämmer ibland Judarna; och månge fastade och greto, sörjde, och lågo i säcker och i asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Då kommo Esthers tjenstepigor, och hennes kamererare, och sade henne det. Då vardt Drottningen svårliga förfärad; och hon sände kläder till Mardechai, att han skulle draga dem uppå, och lägga säcken af sig; men han tog dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Då kallade Esther Hatach, en af Konungens kamererare, som för henne stod, och gaf honom befallning till Mardechai, att hon måtte få veta hvad det vore, och hvi han gjorde så.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Då gick Hatach ut till Mardechai, der han stod på gatone i stadenom, utanför Konungens port.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Och Mardechai sade honom allt det honom händt var, och summon af silfret, som Haman tillredt hade, till att väga in uti Konungens kammar, för Judarnas skull, att han måtte förgöra dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Och fick honom afskriftena af budet, som i Susan uppslaget var på deras förderf, att han skulle det låta se Esther; och böd henne att hon skulle ingå till Konungen, och bedas en bön af honom, och få veta af honom om sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'När Hatach kom in, och sade Esther Mardechai ord,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Sade Esther till Hatach, och lät säga Mardechai:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Det veta alle Konungens tjenare och folken i Konungens land, att hvilken som ingår till Konungen i den inra gården, vare sig man eller qvinna, den icke kallad är, den skall efter lagen straxt dö, utan så är, att Konungen räcker ut emot honom den gyldene spiron, att han dermed må lefvandes blifva; men jag är nu intet kallad i tretio dagar, till att komma in till Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Då denna Esthers ord vordo sagd Mardechai,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Bad Mardechai säga henne igen: Tänk icke det, att du undsätter ditt lif, efter du äst i Konungens hus, för alla Judar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Förty om du i denna gången tiger stilla, så kommer Judomen en hjelp och undsättning af en annan väg, och du och dins faders hus varder förgåendes; och ho vet, om du icke för denna tidens skull äst kommen till riket?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Esther lät svara Mardechai:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Så gack nu bort, och församla alla Judar, som i Susan för handene äro; och faster för mig, så att I icke äten eller dricken i tre dygn, hvarken dag eller natt; jag och mina tjenarinnor vilje också fasta; och så vill jag gå in för Konungen, emot budet; blifver jag borto, så är jag borto.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mardechai gick bort, och gjorde alltså, som Esther honom budit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'På tredje dagen klädde Esther sig i Drottningaklädning, och gick in i gården för Konungshuset, innerst emot Konungsmaket; och Konungen satt på sinom Konungsliga stol i Konungshusena, tvärt emot dörrena i huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Och då Konungen såg Esther Drottningena stå i gårdenom, fann hon nåde för hans ögon; och Konungen räckte ut den gyldene spiron i sine hand emot Esther. Så gick Esther fram, och tog på ändan af spirone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Då sade Konungen till henne: Hvad vill du, Drottning Esther, och hvad begärar du? Ja, ock hälften af riket skall dig gifvet varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Esther sade: Om Konungenom täckes, så komme Konungen och Haman i dag till en måltid, som jag tillredt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Konungen sade: Skynder eder, att Haman må göra, som Esther sagt hafver. Och Konungen och Haman kommo till måltiden, som Esther tillredt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Då sade Konungen till Esther, när han vin druckit hade: Hvad bedes du? Det skall dig gifvet varda; och hvad begärar du? Ja, ock hälften af mitt rike, det skall dig ske.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Esther svarade, och sade: Min bön och begärar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Hafver jag funnit nåd för Konungenom, och Konungenom täckes gifva mig min bön, och göra mitt begär, så komme Konungen och Haman till måltid, som jag för dem tillreda vill, så vill jag i morgon göra som Konungen sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Så gick Haman den dagen glad derut, och lustig; och då han såg Mardechai vid Konungens dörr, att han icke uppstod, och icke en tid rörde sig för honom; vardt han full med vrede öfver Mardechai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Men Haman lät det intet bekomma sig; och då han hemkom, sände han, och lät kalla sina vänner, och sina hustru Seres;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Och förtäljde för dem sina rikedomars härlighet, och sina barnas myckenhet, och huru Konungen hade gjort honom väldigan, och att han upphöja var öfver Konungens Förstar och tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Och sade Haman ytterligare: Ock hafver Drottningen Esther ingen låtit komma med Konungenom till den måltid, som hon tillredt hade, utan mig; och är jag desslikes i morgon buden till henne, med Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Men med detta allt kan jag intet vara tillfrids, så länge jag ser den Judan Mardechai sitta för Konungens dörr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Då sade till honom hans hustru Seres, och alle hans vänner: Låt uppresa en galga, femtio alnar hög, och säg i morgon Konungenom, att man låter hänga der Mardechai uti; så kommer du med Konungenom glad till måltid. Det täcktes Haman väl, och han lät uppresa en galga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Uti den samma nattene kunde Konungen intet sofva, och lät hemta Chrönicor och Historier; och de vordo läsna för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Då råkade man der uppå, der skrifvet var, huru Mardechai hade gjort förvaring, att de två Konungens kamererare, Bigthan och Theres, som vaktade vid dörrena, hade i sinnet slå uppå Konungen Ahasveros.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Och Konungen sade: Hvad hafve vi gjort Mardechai till äro och lön derföre? Då sade Konungens svenner, som honom tjente; Honom är intet skedt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Och Konungen sade: Ho är der i gårdenom? Ty Haman var kommen i gården, utanför Konungshuset, att han skulle säga Konungenom om Mardechai, att han måtte hänga i galganom, som han honom tillredt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Och Konungens svenner sade till honom: Si, Haman står ute på gårdenom. Konungen sade: Låt honom komma in.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Då Haman kom in, sade Konungen till honom: Hvad skall man göra dem månne, som Konungen gerna ära vill? Men Haman tänkte i sitt hjerta: Hvem skulle Konungen gerna vilja göra äro, utan mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Och Haman sade till Konungen: Den man, som Konungen gerna vill ära,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Honom skall man hafva fram, och kläda uppå honom Konungslig kläder, de Konungen plägar draga, och den häst, som Konungen plägar uppå rida, och att man sätter en Konungslig krono på hans hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Och man må få den klädningen och hästen uti en Konungens Förstas hand, att han ikläder den man, som Konungen gerna ära vill, och förer honom på hästenom öfver stadsgatorna, och låter ropa framför honom: Så skall man göra dem, som Konungen gerna ära vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Konungen sade till Haman: Skynda dig, och tag klädningen och hästen, såsom du sagt hafver, och gör alltså med dem Judanom Mardechai, som för Konungens dörr sitter; och låt intet fattas af allt det du sagt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Så tog Haman klädningen och hästen, och kläddepå Mardechai, och förde honom på stadsgatone, och ropade framför honom: Så skall man göra dem månne, som Konungen gerna ära vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Och Mardechai kom igen inför Konungens dörr; men Haman skyndade sig hem, och sörjde med skyldt hufvud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Och förtäljde sine hustru Seres, och allom sinom vännom, allt det honom händt hade. Då sade till honom hans vise, och hans hustru Seres: Är Mardechai af Juda säd, för hvilkom du hafver begynt att falla, så hafver du ingen magt med honom, utan du måste falla för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Vid de ännu med honom talade, kommo Konungens kamererare dertill, och hastade på Haman, till att komma till måltidena, som Esther tillredt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Då Konungen kom neder med Haman till måltiden, som Drottningen Esther tillredt hade,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Sade Konungen till Esther, på den andra dagen, då han vin druckit hade: Hvad bedes du, Drottning Esther, det man dig gifva må? Och hvad begärar du? Ja, ock halfva riket, det skall ske dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Drottningen Esther svarade, och sade: Hafver jag funnit nåd för dig, o Konung, och om Konungenom så täckes, så gif mig mitt lif för mina böns skull, och mitt folk för mitt begärs skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Ty vi äro sålde, jag och mitt folk, till att vi skole förgöras, slås ihjäl och förläggas; Gud gifve, att vi dock hade till trälar och trälinnor sålde varit, så ville jag hafva tegat; och hade då fienden icke gjort Konungenom skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Konungen Ahasveros talade, och sade till Drottningen Esther: Hvilken är den? Eller ho är den som sådant tör sätta sig i sinnet att göra?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Esther sade: Den fienden och hataren är denne onde Haman. Men Haman vardt förskräckt för Konungenom och Drottningene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Och Konungen stod upp ifrå måltidene, och ifrå vinet, i sine grymhet, och gick in uti trägården vid huset; och Haman stod upp, och bad Drottningena Esther om sitt lif; ty han såg, att honom var ondt beredt af Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Och då Konungen kom åter igen af trägårdenom vid huset, in uti salen, der man ätit hade, lutade Haman inpå bänken, der Esther på satt. Då sade Konungen: Vill han ock öfverfalla Drottningena här i husena när mig? Då det ordet gick utu Konungens mun, förskylde de Hamans ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Och Harbona, en af kamererarena inför Konungenom, sade: Si, uti Hamans hus står en galge femtio alnar hög, som han till Mardechai gjort hafver, hvilken för Konungenom godt talat hafver. Konungen sade: Låt hänga honom deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Alltså hängde man Haman i galgan, som han till Mardechai gjort hade. Sedan saktade sig Konungens vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'På den dagen gaf Konungen Ahasveros Drottningene Esther Hamans, Judarnas fiendas, hus; och Mardechai kom för Konungen; förty Esther lät förstå, huru han var henne åkommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Och Konungen tog sin ring af, som han af Haman tagit hade, och fick Mardechai. Och Esther satte Mardechai öfver Hamans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Och Esther talade ytterligare för Konungenom, och föll honom till fota, gret och bad honom, att han skulle tillintetgöra Hamans den Agagitens ondsko, och hans uppsåt, som han emot Judarna för händer hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Och Konungen räckte den gyldene spiron till Esther. Då stod Esther upp, och trädde fram för Konungen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Och sade: Om Konungenom täckes, och jag hafver funnit nåd för honom, och det så vore Konungenom beläget, och om jag täckes honom; så skrifve man, att Hamans uppsåts bref, Medatha sons, den Agagitens, måga varda igenkallade, de han utskrifvit hafver till att förgöra Judarna i all Konungens land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Ty huru kan jag lida det onda, som mitt folk uppå gäller? Och huru kan jag se uppå min slägts förderf?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Då sade Konungen Ahasveros till Drottningen Esther, och till Mardechai den Judan: Si, jag hafver gifvet Esther Hamans hus, och honom hafver man hängt i en galga, derföre att han bar sina hand på Judarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Så skrifver I nu ut för Judarna, såsom eder täckes, under Konungens namn, och besegler med Konungens ring; förty de skrifvelse, som under Konungens namn skrifvas, och med Konungens ring beseglade varda, dem måtte ingen igenkalla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Så vordo Konungens skrifvare kallade, på den tiden i tredje månadenom, det är den månaden Sivan, på tredje och tjugonde dagen; och vardt skrifvet såsom Mardechai böd, till Judarna, och till Förstarna, landshöfdingarna och höfvitsmännerna i landen, allt ifrån Indien intill Ethiopien, nämliga i hundrade sju och tjugu land; hvarjo lande efter sina skrift, hvarjo folke efter sitt mål, och Judomen efter deras skrift och mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Och det skrefs under Konung Ahasveros namn, och med Konungens ring beseglades; och han sände brefven med ridande båd på unga mular.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Och befallde Judomen, der som de voro i städerna, att de skulle församla sig, och stå för deras lif, och förgöra, dräpa och förlägga, all lands och folks magt, som dem bedröfvade, med deras barn och qvinnor, och taga deras gods:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'På en dag i all Konungens Ahasveros land, nämliga på trettonde dagen i tolfte månadenom, det är den månaden Adar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Och brefvets innehållelse var, att ett bud utgifvet var i all land, till att kungöra all folk, att Judarna skulle på den dagen redo vara till att hämnas öfver deras fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Och de ridande båden på mular redo ut snarliga och med hast, efter Konungens ord; och påbudet vardt uppslaget i Susans stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Men Mardechai gick ut ifrå Konungenom, i Konungsligom klädom, gult och hvitt, och med en stor guldkrono, klädd uti en linnen och purpurmantel; och staden Susan fröjdade sig och var glad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Men Judomen var uppgånget ljus och fröjd, glädje och ära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Och i all land och städer, dit Konungens ord och bud räckte, der vardt ibland Judarna fröjd, glädje, lust och goda dagar; så att månge af folken i landen vordo Judar; ty Judarnas fruktan kom öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Uti tolfte månadenom, det är den månaden Adar, på trettonde dagen, hvilken Konungens ord och bud förelagt hade, att man det göra skulle; rätt uppå samma dagen, då fienderna skulle öfverfallit Judarna, vände det sig så, att Judarna skulle öfverfalla sina fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Så församlade Judarne sig i deras städer, i allom Konungs Ahasveros landom, att de skulle göra anfall på dem som dem ondt ämnade; och ingen kunde stå emot dem; förty deras fruktan var kommen öfver all folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Och alle öfverstarna i landen, och Förstarna, och landshöfdingarna, och Konungens ämbetsmän höllo Judarna i äro; ty Mardechai fruktan kom öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Förty Mardechai var myndig i Konungens hus, och hans rykte hördes i all land, huru han växte till, och vardt väldig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Alltså slogo Judarna alla sina fiendar med svärd, dråpo och nederlade dem; och gjorde efter sin vilja på dem som dem fiender voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Och i Susans stad slogo Judarna och dråpo femhundrad män.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Dertill slogo de Parsandatha, Dalphon, Aspatha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratha, Adalja, Aridatha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastha, Arisai, Aridai, Vajesatha,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'De tio Hamans söner, Medatha sons, Judarnas fiendas; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'På samma tiden kom talet på de slagna i Susans stad inför Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Och Konungen sade till Drottningen Esther: Judarna hafva i Susans stad slagit och nederlagt femhundrad män, och de tio Hamans söner; hvad skola de göra i de andra Konungens land? Hvad bedes du, att man dig gifva skall? Och hvad begärar du mer, att man göra skall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Esther sade: Om Konungenom täcktes, så låte han ock i morgon Judarna göra i Susan efter det bud, som i dag varit hafver, att de måga hänga de tio Hamans söner i galga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Och Konungen befallde att göra så; och budet vardt i Susan uppslaget, och de tio Hamans söner vordo hängde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Och Judarna församlade sig i Susan på fjortonde dagen i den månaden Adar, och slogo ihjäl i Susan trehundrad män; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Men de andre Judar i Konungens landom kommo tillsamman, och stodo för sitt lif, att de måtte göra sig rolighet för sina fiendar, och slogo sina fiendar fem och sjutio tusend; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Detta skedde på trettonde dagen i den månaden Adar; och på fjortonde dagen i samma månadenom höllo de hvilo; den gjorde de sig till en vällusts och fröjds dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Men de Judar i Susan voro tillsammankomne, både på trettonde och fjortonde dagen, och höllo hvilo på femtonde dagen; och den dagen gjorde man till en vällusts och glädjes dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Derföre gjorde de Judar, som på bygdene och i småstäderna bodde, den fjortonde dagen i den månaden Adar till en vällusts och glädjes dag, och sände den ene dem andra skänker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Och Mardechai skref allt detta som skedt var, och sände brefven till alla Judar, som voro uti all Konung Ahasveros land, både när och fjerran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Att de skulle vedertaga och hålla den fjortonde och femtonde dagen i den månadenom Adar, hvart år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Efter de dagar, i hvilka Judarna till ro komne voro för sina fiendar, och efter den månaden, i hvilkom deras sorg och glädje, och deras gråt i vällust vänd vardt; att de skulle dem hålla för vällusts och glädjes dagar, och sända den ene dem andra skänker, och dela med de fattiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Och Judarna togo der vid, och gjorde som de begynt hade, och det Mardechai till dem skref;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Huruledes Haman, Medatha son, den Agagiten, alla Judars fiende, hade i sinnet att förgöra alla Judar, och låta kasta lott, till att förskräcka och förgöra dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Och huru Esther hade ingångit till Konungen och beställt, att hans onda uppsåt, som han emot Judarna tänkte, måtte genom bref vändas inpå hans hufvud; och huru man honom och hans söner hade hängt i galga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Af hvilko desse dagar kallades Purim, efter lottsnamnet, efter all detta brefs ord, och hvad de sjelfve sett hade, och hvad till dem räckt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Och Judarna togo det uppå sig och sina säd, och uppå alla dem som gåfvo sig till dem, att de icke ville gå härifrå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Att de ju ville hålla dessa två dagarna hvart år, såsom de föreskrefne och förelagde voro, så att desse dagar icke skulle förgätne, utan hållne varda, barn efter barn i alla slägter, i all land och städer; det äro de dagar Purim, hvilke icke skola brutne varda ibland Judarna, och deras åminnelse icke förgås när deras säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Och Drottningen Esther, Abihails dotter, och Mardechai den Juden, skrefvo med alla magt, till att fast göra detta andra brefvet om Purim;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Och sände brefven till alla Judar, uti de hundrade sju och tjugu land i Konungs Ahasveros rike, med vänlig och trofast ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Att de skulle hålla dessa dagar Purim på deras bestämda tid, såsom Mardechai den Juden, och Drottningen Esther dem förelagt hade; såsom de uppå sina själar och uppå sina säd anammat hade det ärendet om fastone och ropet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Och Esther befallde stadfästa detta ärendet om Purim, och skrifva uti en bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Och Konung Ahasveros lade en skatt uppå landet, och uppå öarna i hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Men allt det under hans våld och magt skedde, och om den stora härlighet, som Konungen gaf Mardechai, si, det är skrifvet uti de Konungars Chrönico i Meden och Persien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Ty Mardechai den Juden var den andre näst Konungenom Ahasveros, och stor ibland Judarna, och täck för alla sina bröder; den der sökte det godt var för sitt folk, och talade det bästa för allo sino säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'En man var uti det landet Uz, som het Job; han var from och rättfärdig, gudfruktig, och flydde det onda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Och honom vordo födde sju söner och tre döttrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Och han ägde sjutusend får, tretusend camelar, femhundrade par oxar, och femhundrade åsninnor, och ganska mycket tjenstefolk; och han var mägtigare än alle de i österlanden bodde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Och hans söner gingo bort, och gjorde gästabåd, hvar sin dag i sitt hus; och sände bort, och läto bjuda sina tre systrar, till att äta och dricka med sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Och när en gästabådsdagen ute var, sände Job bort och helgade dem; och stod bittida upp om morgonen, och offrade bränneoffer, efter allas deras tal. Förty Job tänkte: Mine söner kunna hafva syndat, och välsignat Gud i sin hjerta. Så gjorde Job hvar dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Men det hände på en dag, då Guds barn kommo, och trädde fram för Herran, kom Satan ock med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Men Herren sade till Satan: Hvadan kommer du? Satan svarade Herranom, och sade: Jag hafver farit genom landet allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Då sade Herren till Satan: Hafver du icke gifvit akt uppå min tjenare Job? Ty hans like är icke i landena, from och rättfärdig, gudfruktig, och flyr det onda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Satan svarade Herranom, och sade: Menar du, att Job fruktar Gud förgäfves?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hafver du dock förvarat honom, hans hus, och allt det han hafver allt omkring. Du hafver välsignat hans handaverk, och hans gods hafver utspridt sig i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Men räck ut dina hand, och kom vid allt det han äger; det gäller, han skall välsigna dig i ansigtet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Herren sade till Satan: Si, allt det han äger vare i dine hand, allena vid honom sjelfvan kom icke dina hand. Då gick Satan ut ifrå Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Men den dagen, då hans söner och döttrar åto och drucko vin i deras äldsta broders hus,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Kom ett båd till Job, och sade: Man plöjde med oxarna, och åsninnorna gingo der när i bet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Då föllo de af rika Arabien till, och togo dem, och slogo drängerna med svärdsegg; och jag undslapp allena, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Medan han ännu talade, kom en annar, och sade: Guds eld föll af himmelen, och brände upp fåren och drängerna, och förtärde dem; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Medan han ännu talade, kom en och sade: De Chaldeer gjorde tre spetsar, föllo till camelarna, och togo dem, och slogo drängerna med svärdsegg; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Medan han ännu talade, kom en och sade: Dine söner och döttrar åto och drucko i deras äldsta broders hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Och si, der kom ett stort väder utaf öknene, och stötte på husens fyra hörn, och kastade det på piltarna, att de blefvo döde; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Då stod Job upp, och ref sönder sin kläder, och ref sig i hufvudet, och föll ned på jordena, och tillbad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Och sade: Jag är naken kommen af mine moders lif; naken skall jag åter fara dit; Herren gaf, och Herren tog; välsignadt vare Herrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'I allt detta syndade Job intet, och gjorde intet dårligit emot Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Det begaf sig på en dag, då Guds barn kommo, och trädde fram för Herran, att Satan ock kom med dem, och trädde fram för Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Då sade Herren till Satan: Hvadan kommer du? Satan svarade Herranom, och sade: Jag hafver farit genom landet allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Herren sade till Satan: Hafver du icke gifvit akt på min tjenare Job? Ty hans like är icke i landena, from och rättfärdig, gudfruktig, och flyr det onda, och står ännu i sine fromhet; och du eggade mig, att jag utan sak hafver förderfvat honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satan svarade Herranom, och sade: Hud för hud, och allt det en man hafver, låter han för sitt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Men räck ut dina hand, och kom vid hans ben och kött; det gäller, han skall välsigna dig i ansiktet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Herren sade till, Satan: Si, han vare i dine hand; dock skona hans lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Då for Satan ut ifrå Herrans ansigte, och slog Job med ond sår, ifrå hans fotablad upp till hans hjessa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Och han tog ett stycke af en potto, och skrapade af sig dermed, och satt i asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Och hans hustru sade till honom: Står du ännu i dine fromhet? Välsigna Gud, och dö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Men han sade till henne: Du talar såsom de dåraktiga qvinnor tala. Hafve vi fått godt af Gudi, skole vi ock icke anamma det onda? Uti allt detta syndade Job icke med sina läppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Då nu tre Jobs vänner hörde all den olycka, som öfver honom kommen var, kommo de hvar af sin stad: Eliphas af Thema, Bildad af Suah, och Zophar af Naema; ty de vordo öfverens, att de skulle komma och ömka sig öfver honom, och trösta honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Och då de upphofvo sin ögon långt ifrå, kände de honom intet; och upphofvo sina röst, och greto, och hvardera ref sin kläder sönder, och kastade jord på sin hufvud upp åt himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Och såto med honom på jordene i sju dagar och sju nätter, och talade intet med honom; ty de sågo, att hans sveda var ganska stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Derefter upplät Job sin mun, och förbannade sin dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Utbrast, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Den dagen vare förtappad, på hvilkom jag född är; och den natten, då man sade: En man är aflad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Den samme dagen vare mörk, och Gud fråge intet efter honom ofvanefter; ingen klarhet skine öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Mörkret behålle honom, och töcken blifve öfver honom med tjockt moln; och dimba om dagen göre honom gräselig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Den samma nattena begripe mörker; och glädje sig icke ibland årsens dagar, och komme icke i månadetalet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Si, vare den natten ensam, och ingen glädje komme deruti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'De der dagen förbanna, de förbanne henne; och de som redo äro till att uppväcka Leviathan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Hennes stjernor varde mörka; förvänte ljus, och det komme intet; och se intet morgonrodnans ögnabryn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Att hon icke igenlyckte mins lifs dörr, och icke bortgömde olyckona för min ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Hvi blef jag icke straxt död i moderlifvet? Hvi vardt jag icke förgjord, då jag utu moderlifvet kommen var?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Hvi hafva de tagit mig upp i skötet? Hvi hafver jag ditt spenar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Så låge jag nu, och vore stilla; sofve och hade ro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Med Konungar och rådherrar på jordene, som bygga det öde är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Eller med Förstar, som guld hafva, och sin hus full med silfver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Eller som den der otida född är fördold, och vore icke till; såsom de unga barn, som aldrig hafva sett ljuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Der måste ju de ogudaktige låta af sitt öfvervåld; der hvilas dock de som mycket omak haft hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Der hafva fångar frid med androm, och höra icke trugarens röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Der äro både små och store; tjenaren och den som ifrå sin herra fri är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Hvi är ljus gifvet dem arma, och lif de bedröfvade hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, '(De der vänta efter döden, och han kommer icke; och uppgrofvo honom väl utu fördold rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'De der fröjda sig mycket, och äro glade, att de kunna få grafvena;)');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Och dem månne, hvilkens väg fördold är, och för honom af Gudi skyld varder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Förty min suckan är min dagliga spis; mine tårar äro min dryck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Ty det jag fruktade, det är kommet öfver mig; och det jag räddes, hafver råkat på mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Var jag icke lyckosam? Var jag icke stilla? Hade jag icke goda ro? Och sådana oro kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Du lider tilläfventyrs icke gerna, om man försöker att tala med dig? Men ho kan låtat?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Si, du hafver undervisat många, och styrkt trötta händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Ditt tal hafver upprest dem, som fallne voro; och bäfvande knä hafver du förstärkt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Men nu, medan det kommer på dig, varder du förtvinad; och nu, medan det drabbar på dig, förskräckes du.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ja, der är nu din (Guds) fruktan, din tröst, ditt hopp, och din fromhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Käre, tänk uppå, hvar är någor oskyldiger förgången? Eller hvar äro de rättfärdige någon tid utrotade?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Såsom jag väl sett hafver, de som vedermödo plöjde, och olycko sådde, de skåro det ock upp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Att de äro genom Guds anda förgångne, och af hans vredes anda förgjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Lejonens rytande, och lejinnones röst, och de unga lejons tänder äro sönderbrutna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Lejonet är förgånget, att det icke mera röfvar; och de unga lejon äro förskingrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Och till mig är kommet ett hemligit ord, och mitt öra hafver deraf fått något märkeligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Då jag begrundade nattenes syner, då sömnen faller på menniskorna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Då kom fruktan och bäfvande mig uppå, och all min ben förskräcktes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Och då anden gick framom mig, reste mig håret på minom kropp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Då stod en för min ögon, och dess skapnad kände jag intet; han var stilla, och jag hörde ena röst:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Huru kan en menniska vara rättfärdigare än Gud; eller en man vara renare än han, som honom gjort hafver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Si, ibland sina tjenare finner han icke trohet, och i sinom Änglom finner han dårhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Huru mycket mer de som bo i lerhus; och de der grundade äro på jordene, skola förtäras af matk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Det varar ifrå morgonen intill aftonen, så varda de upphuggne; och förr än de varda det varse, äro de platt borto;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Och deras käraste förgås; och dö ock oförvarandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Nämn mig en, hvad gäller, om du någon finner; och se dig om någorstäds efter en helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Men en dåra dräper väl vreden, och en ovisan dödar nitet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Jag såg en dåra väl rotad, och jag bannade straxt hans huse:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hans barn skola vara fjerran ifrå helsone, och skola varda sönderkrossade i porten, der ingen hjelpare är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Hans säd skall den hungrige uppäta, och de väpnade skola taga henne; och hans gods skola de törstige utsupa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Förty vedermödan går icke upp af jordene, och olyckan växer icke upp af åkrenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Utan menniskan varder född till olycko, såsom foglarna till att flyga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Dock vill jag nu tala om Gud, och handla om honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Som gör mägtig ting, de der icke ransakas kunna; och under, som icke räknas kunna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Den der regn gifver på jordena, och låter vatten komma på markena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Den der upphöjer de nedriga, och upphjelper de förtryckta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Han gör deras anslag, som listige äro till intet, att deras hand intet kan uträtta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Han begriper de visa i deras listighet, och gör de klokas råd till galenskap;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Att de om dagen löpa i mörkrena, och famla om middagen såsom om nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Och han hjelper den fattiga ifrå svärdet, och ifrå deras mun; och utu dens väldigas hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Och är dens fattigas tröst, att orättfärdigheten måste hålla sin mun till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Si, salig är den menniska, den Gud straffar; derföre förkasta icke dens Allsmägtigas tuktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Ty han sargar, och läker; han slår, och hans hand helar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Utaf sex bedröfvelser frälsar han dig, och i den sjunde kommer intet ondt vid dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'I dyr tid frälsar han dig ifrå döden, och i stridene ifrå svärdsens hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Han skall skyla dig för tungones gissel, att du icke skall frukta för förderf, då det kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Uti förderf och hunger skall du le, och icke frukta för vilddjuren i landena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Utan ditt förbund skall vara med stenom på markene; och vilddjuren i landena skola hålla frid med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Och du skall förnimma, att din hydda hafver frid, och skall försörja dina boning, och icke synda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Och skall förnimma, att din säd skall varda mycken, och dine efterkommande såsom gräs på jordene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Och skall i ålderdomen komma till grafva, såsom en hvetekärfve införd varder, i rättom tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Si, det hafve vi ransakat, och det är så; hör dertill, och rätta dig derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'När man voge min jämmer, och lade allt mitt lidande på ena våg,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Så skulle det vara svårare, än sanden i hafvet; derföre är förgäfves hvad jag säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Förty dens Allsmägtigas pilar stå i mig, hvilkens grymhet utsuper allan min anda; och Guds förskräckelse äro ställd uppå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Icke ropar vildåsnen, när han hafver gräs; ej heller oxen, då han hafver foder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Kan man ock äta det som osaltadt är? Eller månn någor vilja smaka det hvita om äggeblomman?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Der min själ tillförene vämjade vid, det är nu min mat för värks skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O! att min bön måtte ske, och Gud gåfve mig det jag förhoppas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Att Gud toge till att sönderslå mig, och låte sina hand sönderkrossa mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Så hade jag ändå tröst, och ville bedja i minom sjukdom, att han icke skonade mig; jag hafver dock icke nekat dens Heligas tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Hvad är min kraft, att jag skulle kunna härda ut? Och hvad är min ändalykt, att min själ skulle vara tålig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Min kraft är dock icke af sten, ej är heller mitt kött af koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Hafver jag dock ingenstäds hjelp; och ingen ting vill gå fram med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Den der icke bevisar sinom nästa barmhertighet, han öfvergifver dens Allsmägtigas fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mine bröder gå förakteliga framom mig, såsom en bäck; såsom en ström framom flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Dock de som rädas för rimfrostet, öfver dem varder fallandes snö.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Den tid hetten tvingar dem, skola de försmäkta; och när det hett blifver, skola de förgås utaf sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Deras väg går afsides bort; de vandra der intet vägadt är, och förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'De se uppå Thema vägar; på rika Arabiens stigar akta de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Men de skola komma på skam, då det är aldrasäkrast; och skola skämma sig, då de deruppå komne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Ty I ären nu komne till mig; och medan I sen jämmer, frukten I eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Hafver jag ock sagt: Bärer hit, och skänker mig af edro förmågo?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Och hjelper mig utu fiendans hand? Och förlosser mig utu tyranners händer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Lärer mig, jag vill tiga; och det jag icke vet, det underviser mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Hvi straffen I rättfärdigt tal? Hvilken är ibland eder, som det straffa kan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'I sätten samman ord, allenast till att straffa, och gören med ordom ett förtvifladt mod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'I öfverfallen en fattigan faderlösan, och rycken edar nästa upp med rötter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Dock, medan I hafven begynt, ser uppå mig, om jag varder beslagen med någon lögn för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Svarer hvad som rätt är; min svar skola väl blifva rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Hvad gäller, min tunga hafver icke orätt, och min mun föregifver icke ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Måste icke menniskan alltid vara i strid på jordene; och hennes dagar äro såsom en dagakarls?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Såsom en dräng åstundar skuggan, och en dagakarl, att hans arbete må vara ute;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Så hafver jag väl arbetat hela månaden fåfängt, och bedröfvada nätter äro mig många vordna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'När jag lägger mig, säger jag: När månn jag skola uppstå? Och sedan räknar jag, när afton skall varda; ty jag var hvarjom manne en styggelse intill mörkret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mitt kött är fullt med matk och mull allt omkring; min hud är sammanskrynkt och till intet vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mine dagar äro snarare bortflogne än en väfspole; och äro förledne utan all förtöfvan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Tänk uppå, att mitt lif är ett väder, och min ögon komma icke igen till att se det goda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Och intet lefvandes öga varder mig mera seendes; din ögon se på mig, deröfver förgås jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Molnet varder allt, och går bort; så ock den som far neder i helvetet, han kommer icke upp igen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Och besitter icke sitt hus igen, och hans rum blifver öde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Derföre vill jag ock icke förmena minom mun; jag vill tala i mins hjertas ångest, och vill utsäga min själs bedröfvelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Är jag ett haf, eller en hvalfisk, att du så förvarar mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Ty jag tänkte: Min säng skall trösta mig; mitt lägre skall lisa mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'När jag talar med mig sjelf, så förskräcker du mig med drömmar, och gör mig förfärelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Att min själ önskar sig vara hängd, och min ben döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Jag begärar intet mer lefva; håll upp af mig; ty mine dagar äro fåfängelige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Hvad är en menniska, att du aktar henne högt, och bekymrar dig med henne?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Du hemsöker henne dagliga, och försöker henne alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Hvi går du icke ifrå mig, och släpper mig, så länge jag uppsvälger min spott?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Hafver jag syndat, hvad skall jag göra dig, o du menniskors gömmare? Hvi gjorde du mig, att jag uppå dig stöta skulle, och är mig sjelfvom till tunga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Och hvi förlåter du mig icke mina missgerning, och tager icke bort mina synd? Ty nu skall jag lägga mig i mull; och när man om morgonen söker mig, är jag då intet till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Huru länge vill du sådana tala, och låta dins muns tal hafva ett sådant högmod?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Menar du, att Gud dömmer orätt; eller den Allsmägtige skall vrida rätten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Om dine söner hafva syndat för honom, så hafver han förkastat dem för deras missgernings skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Men om du i tid gifver dig in till Gud, och beder den Allsmägtiga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Och om du äst ren och from, så varder han uppvakandes till dig, och varder åter upprättandes boningen för dina rättfärdighets skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Och der du tillförene hafver haft litet, skall det härefter ganska mycket förökas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Ty fråga de slägter, som i förtiden varit hafva, och tag dig före att fråga deras fäder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Ty vi äre såsom i går komne, och vete intet; vårt lif är en skugge på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'De skola lära dig, och säga dig det, och gifva sitt tal före utaf sitt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Icke kan säfvet växa, utan det står i vätsko; eller gräs växa utan vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Eljest, medan det än står i blomster, förr än det afhugget varder, förtorkas det, förr än man hö bergar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Så går allom dem som förgäta Gud, och de skrymtares hopp varder förtappadt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Ty hans tröst blifver omintet, och hans hopp såsom ett dvergsnät.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Han förlåter sig på sitt hus, och skall dock icke, bestå; han skall hålla sig derintill, och dock icke beständig blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Det grönskas väl förr än solen kommer, och qvistar växa uti dess örtagård;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Dess säd står tjock vid källor, och dess hus på stenar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Men när han uppsluker honom af sitt rum, ställer han sig emot honom, såsom han kände honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Si, detta är fröjden i dess väsende; och annor växa upp igen af stoftet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Derföre, si, att Gud icke förkastar de goda, och icke uppehåller de ondas hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Tilldess din mun varder full med löje, och dine läppar fulle med fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Men de, som dig hata, skola komma på skam, och de ogudaktigas boning skall icke blifva beståndandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Job svarade och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Ja, jag vet det fullväl, att så är, att en menniska icke kan bestå rättfärdig för Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Täckes honom träta med honom, så kan han icke svara honom ett emot tusende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Han är vis och mägtig; hvem hafver det dock gått väl af, som sig hafver satt emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Han försätter bergen, förr än de det förnimma; hvilka han i sine vrede omkastar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Han rörer jordena af sitt rum, så att hennes pelare bäfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Han talar till solena, så går hon intet upp, och han förseglar stjernorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Han allena utsträcker himmelen, och går på hafsens vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Han gör Karlavagnen (på himmelen) och Orion; sjustjernorna, och de stjernor söderut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Han gör mägtig ting, som man icke utransaka kan, och under, deruppå intet tal är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Si, han går framom mig, förr än jag varder det varse; och han förvandlar sig, förr än jag det märker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Si, om han går hasteliga bort, ho vill hemta honom igen? Ho vill säga till honom: Hvad gör du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Han är Gud, hans vrede kan ingen stilla; under honom måste buga sig de stolta herrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Huru skulle jag då svara honom, och finna några ord emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Om jag än rätt hafver, så kan jag dock likväl intet svara honom; utan måste i rättenom bedjas före.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Och om jag än åkallade honom, och han hörde mig; så tror jag dock icke, att han hörer mina röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Ty han far öfver mig med storm, och gör mig såren mång utan sak.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Han låter icke min anda vederqvickas, utan gör mig full med bedröfvelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Vill man magt, så är han för mägtig; vill man rätten, ho vill vittna med mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Om jag säger att jag är rättfärdig, så fördömer han mig dock; är jag from, så för han mig dock till ondan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Är jag än from, så tör min själ dock intet hålla sig dervid; jag begärer intet mer lefva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Det är det som jag sagt hafver; han förgör både den goda, och den ogudaktiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'När han begynner till att slå, så dräper han straxt, och begabbar de oskyldigas frestelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Men landet varder gifvet under dens ogudaktigas hand, att han undertrycker dess domare; är det icke så, huru skulle det annars vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mine dagar hafva varit snarare än en löpare; de hafva flytt, och hafva intet godt sett.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'De äro förgångne såsom stark skepp; såsom en örn flyger till maten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'När jag tänker: Jag vill glömma bort min klagan; jag vill förvandla mitt ansigte, och vederqvicka mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Så fruktar jag mig för all min sveda, vetandes, att du icke låter mig vara oskyldig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Är jag nu ogudaktig, hvi hafver jag då sådana onyttiga vedermödo?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Om jag än tvådde mig i snö, och gjorde mina händer rena i källo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Så doppar du mig dock i träck, och min kläder varda mig illa ståndande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Ty han är icke min like, dem jag svara kunde, att vi måtte både komma för rätten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Det är ingen, som oss åtskiljer; som sätter sina hand emellan oss båda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Han tage sitt ris ifrå mig, och låte sin förskräckelse komma ifrå mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Att jag må tala, och icke mer torf frukta för honom; ty jag vet mig oskyldig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Min själ grufvar sig för mitt lif; min klagan vill jag låta fara fort, och tala i mine själs bedröfvelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Och säga till Gud: Fördöm mig icke; låt mig få veta, hvarföre du träter med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Hafver du der lust till, att du brukar öfvervåld; och förkastar mig, hvilken dina händer gjort hafva; och låter de ogudaktigas anslag komma till äro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Hafver du ock då köttslig ögon? Eller ser du såsom en menniska ser?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Eller är din tid såsom ens menniskos tid; eller din år såsom ens mans år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Att du frågar efter mina orättfärdighet, och uppsöker mina synd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ändå du vetst, att jag icke är ogudaktig; ändå det är ingen, som kan fria ifrå dine hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Dina händer hafva fliteliga gjort mig, och allansamman beredt mig; och du nedsänker mig så alldeles.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Tänk dock uppå, att du hafver gjort mig af ler, och skall åter låta mig komma till jord igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Hafver du icke molkat mig såsom mjölk, och låtit mig ystas såsom ost?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Du hafver klädt mig uti hud och kött; med ben och senor hafver du sammanfogat mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Lif och välgerning hafver du gjort mig, och ditt uppseende bevarar min anda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Och ändå att du fördöljer sådana i ditt hjerta, så vet jag dock likväl, att du kommer det ihåg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Om jag syndar, så märker du det straxt, och låter mina missgerning icke vara ostraffad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Är jag ogudaktig, så är mig ve; är jag rättfärdig, så tör jag likväl icke upplyfta mitt hufvud, som den der full är med föraktelse, och ser mina eländhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Och såsom ett upprest lejon jagar du mig, och handlar åter grufveliga med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Du förnyar din vittne emot mig, och gör dina vrede mycken öfver mig; mig plågar det ena öfver det andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Hvi hafver du låtit mig komma utaf moderlifvet? Ack! att jag dock hade varit förgjord, att intet öga hade sett mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Så vore jag, såsom den der intet hafver varit till, buren ifrå moderlifvet till grafvena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Vill då icke mitt korta lif hafva en ända? Vill du icke låta af mig, att jag något litet måtte vederqvickas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Förr än jag går bort, och kommer intet igen, nämliga i mörkrens och töcknones land?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Det ett land är, hvilkets ljus är tjocka mörkret, och der som ingen skickelighet är; der skenet är såsom en töckna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Då svarade Zophar af Naema, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'När en hafver länge talat, måste han ock icke höra? Eller skall en sqvallrare alltid hafva rätt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Måste man tiga för dig allena, att du försmäder, och ingen skall genhöfta dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du säger: Min lärdom är ren, och klar är jag för din ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ack! att Gud talade med dig, och uppläte sina läppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Och tedde dig hvad han ännu hemliga vet; ty han hade ännu väl mer med dig; på det att du måtte veta, att han icke tänker på alla dina synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Menar du, att du vetst så mycket som Gud vet; och vill alltså fullkomliga råkat, såsom den Allsmägtige?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Han är högre än himmelen, hvad vill du göra? djupare än helvetet, huru kan du kännan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Längre än jorden, och bredare än hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Om han all ting omvände eller fördolde, eller kastade dem i en hop, ho vill förmena honom det?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Han känner de fåfängeliga män, och ser odygdena, och skulle han icke förståt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'En fåfängelig man högmodas, och en född menniska vill vara såsom en ung vildåsne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Hade du ställt ditt hjerta (till Gud), och uppräckt dina händer till honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Hade du långt ifrå dig bortkastat missgerningena, som är i din hand, att ingen orätt hade bott i dine hyddo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Så måtte du upplyft ditt ansigte utan last, och vorde fast ståndandes, och intet fruktandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Så vorde du ock förgätandes uselhetena, och såsom det vattnet, som framlupet är, komme du det icke ihåg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Och din lifstid vorde uppgångandes såsom en middag, och vorde skinandes såsom en morgon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Och du måtte förtrösta dig, att hopp vore på färde; och vorde med rolighet kommandes i grafvena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Och du skulle lägga dig, och ingen skulle rädda dig; och månge skulle knekta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Men de ogudaktigas ögon skola försmäkta, och skola icke undkomma kunna; ty deras hopp skall fela deras själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Då svarade Job, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Ja, I ären rätte männerna; med eder blifver visheten död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Jag hafver så väl ett hjerta som I, och är icke ringare än I; och ho är den som sådana icke vet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Den som af sin nästa begabbad varder, han må åkalla Gud, han varder honom hörandes: Den rättfärdige och fromme måste varda begabbad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Och är dem rikom såsom en lampa, föraktad i deras hjerta, dock tillredd, att de skola deruppå stöta fötterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Röfvarenas hyddor hafva nog, och de rasa dristeliga emot Gud; ändå att Gud hafver gifvit dem det i deras händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Fråga dock djuren, de skola lärat dig, och foglarna under himmelen, de skola sägat dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Eller tala med jordene, och hon skall lärat dig, och fiskarna i hafvet skola förkunnat dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Ho är den som allt sådant icke vet, att Herrans hand hafver det gjort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Att i hans hand är alles dess själ, som lefvandes är, och alla menniskors kötts ande?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Profvar icke örat talet, och munnen smakar maten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Ja, när fäderna är vishet, och förstånd när de gamla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'När honom är vishet och magt, råd och förstånd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Si, när han bryter neder, så hjelper intet bygga; när han någon innelycker, så kan ingen utsläppa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Si, när han förhåller vattnet, så torkas allt, och när han släpper det löst, så omstörter det landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Han är stark, och går det igenom; hans är den som villo far; så ock den som förförer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Han förer de kloka såsom ett rof, och gör domarena galna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Han förlossar utu Konungars tvång, och binder med ett bälte deras länder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Presterna förer han såsom ett rof, och de fasta låter han fela.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Han bortvänder de sannfärdigas läppar, och de gamlas seder tager han bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Han utgjuter föraktelse på Förstarna, och gör de mägtigas förbund löst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Han öppnar de mörka grund, och förer mörkret ut i ljuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Han gör somliga till stort folk, och gör dem åter till intet; han utsprider ett folk, och fördrifver det åter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Han förvänder hjertat i öfverstarna för folket i landena, och låter dem fara ville i vildmarkene, der ingen väg är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Att de famla i mörkret utan ljus, och förvillar dem såsom de druckna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Si, allt detta hafver mitt öga sett, och mitt öra hört, och hafver det förstått.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Det I veten, det vet jag ock, och är intet ringare än I;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Dock vill jag tala om den Allsmägtiga, och hafver vilja till att träta med Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Ty I uttyden det falskeliga, och ären alle onyttige läkare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ack! att I kunden tiga, så vorden I vise.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Hörer dock mitt straff, och akter på sakena, der jag talar om.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Viljen I försvara Gud med orätt; och för honom bruka svek?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Viljen I anse hans person? Viljen I gifva eder i försvar för Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Skall det ock blifva eder väl gångandes, då han skall döma eder? Menen I, att I skolen gäcka honom, såsom man gäckar ena mennisko?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Han varder eder straffandes, om I hemliga ansen personen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Månn han icke förskräcka eder, när han kommer fram? Och hans fruktan varder fallandes öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Edor åminnelse varder liknad vid asko, och edra rygger skola vara såsom en lerhop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Tiger för mig, att jag må tala; det skall icke fela för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Hvi skall jag bita mitt kött med mina tänder, och sätta mina själ i mina händer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Si, han varder mig dock dräpandes, och jag kan icke afbidat; dock vill jag straffa mina vägar för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Han blifver ju min helsa; ty ingen skrymtare kommer för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Hörer mitt tal, och min uttydelse för edor öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Si, jag hafver allaredo sagt domen af; jag vet, att jag varder rättfärdig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Ho är den som vill gå till rätta med mig? Men nu måste jag tiga, och förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Tveggehanda gör mig icke; så vill jag icke gömma mig bort för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Låt dina hand vara långt ifrå mig, och din förskräckelse förskräcke mig icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Kalla mig, och jag vill svara dig; eller jag vill tala, och svara du mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Huru många äro mina missgerningar och synder? Låt mig få veta min öfverträdelse och synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Hvi fördöljer du ditt ansigte, och håller mig för din fienda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Vill du så hård vara emot ett flygande löf; och förfölja ett torrt halmstrå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Ty du tillskrifver mig bedröfvelse, och vill förderfva mig för mins ungdoms synders skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Du hafver satt min fot i en stock, och gifver akt på alla mina stigar, och ser på all min fotspår;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Jag, som dock förgås som ett ruttet as, och som ett kläde, det ätet varder af mal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Menniskan, af qvinno född, lefver en liten tid, och är full med orolighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Växer upp som ett blomster, och faller af; flyr bort som en skugge, och blifver icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Och öfver en sådana upplåter du din ögon, och drager mig för dig i rätten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Ho vill finna en renan när dem, der ingen ren är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Han hafver sin förelagda tid; hans månaders tal är när dig; du hafver satt honom ett mål före, derutöfver varder han icke gångandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Gack ifrå honom, att han må hvilas, så länge hans tid kommer, den han såsom en dagakarl bidar efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Ett trä hafver hopp, om det än är afhugget, att det skall åter förvandla sig, och dess telningar vända icke igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ändock dess rot föråldras i jordene, och stubben dör i mullene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Så grönskas han dock åter af vattnets lukt, och växer lika som han plantad vore.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Men hvar är en menniska, då hon död, förgången och borto är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Såsom ett vatten löper utur en sjö, och såsom en bäck utlöper och förtorkas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Så är en menniska, då hon lägges ned, och varder intet uppståndandes, och varder intet uppvaknandes, så länge himmelen varar, och varder icke uppväckt af sinom sömn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ack! att du fördolde mig i helvete, och fördolde mig, så länge din vrede afgår, och satte mig ett mål, att du ville tänka uppå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Menar du, att en död menniska skall åter lefva igen? Jag förbidar dagliga, medan jag strider, tilldess min förvandling kommer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Att du ville kalla mig, och jag måtte svara dig; och du ville icke förkasta ditt handaverk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Ty du hafver allaredo talt min tren; men akta dock icke uppå mina synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Min öfverträdelse hafver du förseglat uti ett knippe, och sammanfattat mina missgerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Förfaller dock ett berg, och förgås, och en klippa går af sitt rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Vattnet sköljer stenarna bort, och floden förer jordena bort; men menniskones hopp är förloradt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Ty du stöter henne platt omkull, så att hon förgås; du förvandlar hennes väsende, och låter henne fara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Äro hennes barn i äro, det vet hon icke; eller om de äro föraktelige, det förnimmer hon intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Medan hon är i köttena, måste hon hafva sveda; och medan hennes själ är än när henne, måste hon lida vedermödo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Skall en vis man tala så i vädret, och uppfylla sin buk med väder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Du straffar med onyttigom ordom, och ditt tal kommer intet till gagns.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Du hafver bortkastat räddhågan, och talar förakteliga för Gudi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Ty så lärer din ondska din mun, och du hafver utvalt ena skalkatungo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Din mun skall fördöma dig, och icke jag; dina läppar skola svara dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Äst du den första menniska, som född är? Äst du för all berg aflader?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hafver du hört Guds hemliga råd? Och är sjelfva visdomen ringare än du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Hvad vetst du, det vi icke vete? Hvad förstår du, det som icke är när oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Gråhårote och gamle äro när oss, som länger hafva lefvat än dine fäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Skulle Guds hugsvalelse så ringa aktas för dig? Men du hafver något hemligit stycke när dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Hvad tager ditt hjerta före? Hvi ser du så stolt ut?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Hvi sätter ditt sinne sig emot Gud, att du låter sådana ord gå af dinom mun?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Hvad är en menniska, att hon skulle vara ren; och att han skulle vara rättfärdig, som af qvinno född är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Si, ibland hans helga är ingen ostraffelig, och himlarna äro icke rene för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Huru mycket mer menniskan, som är stygg och ond; den der orättfärdighetena dricker såsom vatten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Jag vill visa dig det, hör mig; jag vill förtälja dig, hvad jag sett hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Hvad de vise sagt hafva, och för deras fader icke hafver fördoldt varit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Hvilkom allena landet gifvet är, så att ingen främmande må gå ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'En ogudaktig bäfvar i alla sina lifsdagar, och enom tyrann är hans åratal fördoldt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Hvad han hörer, det förskräcker honom; och ändå att frid är, så hafver han dock den sorg, att han skall förderfvas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Han tror icke, att han skall kunna undfly olyckona, och förmodar sig alltid svärdet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'När han far ut hit och dit efter sin näring, så tycker honom att hans olyckos tid är för handene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Ångest och nöd förskräcka honom, och slå honom ned, såsom en Konung med enom här;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Ty han hafver utsträckt sina hand emot Gud, och emot den Allsmägtiga förstärkt sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Han löper med hufvudet emot honom, och står halsstyf emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Han hafver upphäfvit sig emot honom, och satt sig hårdt emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Men han skall bo i nederslagna städer, der inga hus äro; utan ligga i enom hop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Han skall icke varda rik, och hans gods skall icke förökas; och skall icke utspridas i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Han skall icke undfly olycko; eldslågen skall förtorka hans grenar; och skall varda borttagen af hans muns anda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Han är så bedragen, att han icke tror att det skall varda värre med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Han får en ända, när honom obeqvämt är; och hans gren skall icke grönskas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Han varder afhemtad såsom en omogen drufva af vinträt, och såsom ett oljoträ bortfaller sitt blomster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Ty de skrymtares församling skall blifva ensam, och elden skall förtära hans hus, som gåfvor tager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Han anar olycko, och föder vedermödo; och deras buk bär list fram.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Jag hafver sådana ofta hört; I ären alle arme hugsvalare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'När vilja dock dessa lösa ord hafva en ända? Eller hvad fattas dig, att du så svarar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Jag kunde ock väl tala såsom I; jag ville att edor själ vore i mine själs stad; jag ville ock finna ord emot eder, och så rista mitt hufvud öfver eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Jag ville styrka eder med munnen, och tala af sinnet med mina läppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Men om jag än talar, så skonar min svede mig dock intet; låter jag ock blifvat, så går han dock intet ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Men nu gör han mig vedermödo, och förstörer all min ledamot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Han hafver mig gjort skrynkotan, och vittnar emot mig; och min motståndare hafver sig upp emot mig, och svarar emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hans vrede sliter mig, och den som är mig vred, biter samman tänderna öfver mig; min motståndare ser hvasst med sin ögon på mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'De gapa med sin mun emot mig, och hafva hånliga slagit mig vid mitt kindben; de hafva tillhopa släckt sin harm på mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Gud hafver öfvergifvit mig dem orättfärdiga, och låtit mig komma i de ogudaktigas händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Jag var rik, men han hafver mig gjort till intet; han hafver tagit mig vid halsen, och sönderslitit mig, och uppsatt mig sig till ett mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Han hafver kringhvärft mig med sina skyttor; han hafver sargat mina njurar, och intet skonat; han hafver utgjutit min galla på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Han hafver gjort mig ett sår öfver det andra; han hafver öfverfallit mig såsom en kämpe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Jag hafver sömmat en säck på mina hud, och hafver lagt mitt horn i mull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mitt ansigte är svullet af gråt, och min ögonlock äro vorden mörk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Ändock att ingen orättfärdighet är i mine hand, och min bön är ren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ack jord! öfvertäck icke mitt blod, och mitt rop hafve intet rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Och si nu, mitt vittne är i himmelen, och den mig känner är i höjdene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Mine vänner äro mine begabbare; mitt öga fäller tårar till Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Om en man kunde gå till rätta med Gud, såsom menniskors barn med sin nästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Men de förelagda år äro komne; och jag går den vägen bort, den jag aldrig igen kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Min ande är svag, och mine dagar äro afkortade, och grafven är för handene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Ingen är bedragen af mig; likväl måste mitt öga derföre blifva i bedröfvelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Om du än ville hafva borgen af mig; ho ville lofva för mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Förstånd hafver du för deras hjerta fördolt; derföre skall du icke upphöja dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Han rosar fast bytet för sinom vännom; men hans barnas ögon skola försmäkta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Han hafver satt mig till ett ordspråk ibland folk, och jag måste vara ett under ibland dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Mitt ansigte är mörkt vordet för sorgs skull, och all min ledamot äro såsom en skugge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Öfver detta varda de rättfärdige häpne, och de oskyldige varda sättande sig emot skrymtarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Den rättfärdige varder behållandes sin väg, och den som rena händer hafver, varder stark blifvandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Nu väl, vänder eder alle hit, och kommer; jag varder dock icke finnandes någon visan ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mine dagar äro förgångne; min anslag äro förskingrade, som mitt hjerta besatt hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Och hafva gjort dag af nattene, och af dagenom natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Om än jag fast länge bidde, så är dock helvetet mitt hus, och min säng är i mörkrena uppgjord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Förgängelsen kallade jag min fader, och matkarna mina moder, och mina syster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Efter hvad skall jag bida? Och ho aktar mitt hopp?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Neder i helvetet varder det farandes, och varder med mig liggandes i mullene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'När viljen I göra en ända på att tala? Akter dock till; sedan vilje vi tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Hvi varde vi aktade (för dig) såsom oskälig djur, och äre så orene för edor ögon?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Vill du brista för hätskhets skull? Menar du, att för dina skull skall jorden öfvergifven varda, och hälleberget utaf sitt rum försatt varda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Och skall dens ogudaktigas ljus utslockna, och gnistan af hans eld skall intet lysa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Ljuset i hans hyddo skall varda till mörker, och hans lykta öfver honom skall utsläckt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hans håfvors tillgångar skola varda trånga, och hans anslag skall fela honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Ty han är med sina fötter förd i snarona, och vandrar i nätet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'En snara skall hålla hans häl, och de törstige skola få fatt på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Hans snara är lagd på jordene, och hans gildre på hans stig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'På alla sidor skola hastig förfärelse förskräcka honom, så att han icke skall veta hvartut han skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Hunger skall blifva hans håfvor, och uselhet skall blifva honom tillredd, och hänga vid honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Hans huds starkhet skall förtärd varda, och hans starkhet skall dödsens Förste förtära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hans tröst skall utrotas utu hans hyddo, och de skola drifva honom till förskräckelsens Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Uti hans hyddo skall intet blifva; öfver hans palats skall svafvel strödt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Nedantill skola hans rötter förtorkas, och ofvanuppå afskäras hans säd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hans åminnelse skall förgås i landena, och skall intet namn hafva på gatone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Han skall fördrifven varda ifrå ljusena i mörkret, och af jordene bortkastad varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Han skall ingen barn hafva, och ingen barnabarn i sin folk; honom skall ingen qvar blifva i hans slägt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'De som efter honom komma, skola gifva sig öfver hans dag; och dem, som för honom äro, skall fruktan uppå komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Detta är dens orättfärdigas boning; och detta är rummet till honom, som intet vet af Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Hvi plågen I dock mina själ, och döfven mig neder med ordom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'I hafven nu i tio gångor hädat mig, och I skämmen eder intet, att I så omdrifven mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Far jag vill, så far jag mig vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Men I upphäfven eder sannerliga emot mig, och straffen mig till min smälek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Märker dock en gång, att Gud gör mig orätt, och hafver invefvat mig uti sin garn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Si, om jag än ropar öfver öfvervåld, så varder jag dock intet hörd; jag ropar, och här är ingen rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Han hafver igentäppt min väg, att jag icke kan gå der fram; och hafver satt mörker uppå min stig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Han hafver utuklädt mig mina äro, och tagit kronona utaf mitt hufvud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Han hafver sönderbråkat mig allt omkring, och låter mig gå; och hafver uppryckt mitt hopp såsom ett trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hans vrede hafver förgrymmat sig öfver mig, och han håller mig för sin fienda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hans krigsmän äro tillika komne, och hafva lagt sin väg öfver mig; och hafva lägrat sig allt omkring mina hyddo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Han hafver låtit komma mina bröder långt ifrå mig, och mine kände vänner äro mig främmande vordne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mine näste hafva unddragit sig, och mine vänner hafva förgätit mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Mitt husfolk och mina tjensteqvinnor hålla mig för främmande; jag är vorden okänd för deras ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Jag ropade min tjenare, och han svarade mig intet; jag måste bedja honom med min egen mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Min hustru stygges vid min anda; jag måste knekta mins lifs barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Förakta också mig de unga barn; om jag uppreser mig, så tala de emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Alle mine trogne vänner hafva styggelse vid mig, och de jag kär hade, hafva vändt sig emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Min ben låda vid min hud och kött; jag kan med hudene icke skyla mina tänder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Förbarmer eder öfver mig; förbarmer eder öfver mig, ju I mine vänner; ty Guds hand hafver kommit vid mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Hvi förföljen I mig såväl som Gud, och kunnen af mitt kött icke mätte varda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ack! att mitt tal måtte skrifvet varda; ack! att det måtte uti en bok satt varda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Med en jernstyl ingrafvet uti bly; och till en evig åminnelse hugget i sten:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Jag vet att min Förlossare lefver; och han skall på sistone uppväcka mig af jordene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Och jag skall sedan med desso mine hud omklädd varda, och skall i mitt kött få se Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Honom skall jag mig se, och min ögon skola skåda honom, och ingen annan. Mine njurar äro upptärde uti mino sköte;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Ty I sägen: Huru skole vi förfölja honom, och finna en sak emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Frukter eder för svärdet; förty svärdet är en hämnd öfver missgerningar; på det I veta mågen, att näpst är till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Då svarade Zophar af Naema, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Deruppå måste jag svara, och kan icke bida;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Och vill gerna höra, ho mig det straffa och lasta skall; ty mins förstånds ande skall svara för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Vetst du icke, att alltid så tillgånget är, ifrå den tiden menniskorna på jordene varit hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Att de ogudaktigas berömmelse står icke länge, och skrymtares glädje varar ett ögnablick?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Om hans höjd än räckte upp i himmelen, och hans hufvud komme intill skyn,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Så måste han dock på sistone förgås såsom träck; så att de, som se uppå honom, skola säga: Hvar är han?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Såsom en dröm förgår, så skall han ej heller funnen varda; och såsom en syn, den om nattena försvinner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Det öga, som honom sett hafver, det ser honom intet mer; och hans rum skall icke mer se honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hans barn skola tigga gå, och hans hand skall gifva honom vedermödo till löna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Hans ben skola umgälla hans ungdoms synder; och skola lägga sig i jordene med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Om än ondskan smakar honom väl uti hans mun, skall hon dock fela honom på hans tungo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Hon skall varda förhållen, och icke tillåten; och skall varda honom förtagen i hans hals.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Hans mat skall förvända sig i hans buk uti ormagalla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'De ägodelar, som han uppsvulgit hafver, måste han åter utspy; och Gud skall drifva dem utu hans buk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Han skall suga huggormagalla, och ormatunga skall dräpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Han skall icke få se de strömmar eller vattubäckar, som med hannog och smör flyta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Han skall arbeta, och intet nyttjat; och hans ägodelar skola varda annars mans, så att han icke skall hafva hugnad utaf dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Förty han hafver undertryckt och förlåtit den fattiga; han hafver rifvit till sig hus, de han intet byggt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Ty hans buk kunde icke full varda; och skall icke igenom sina kosteliga ägodelar undkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Af hans mat skall intet qvart vara; derföre skola hans goda dagar intet varaktige blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Om han än öfverflödar, och hafver nog, skall honom dock likväl ångest ske; alla händers möda skall öfver honom komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Hans buk skall honom en gång full varda; och han skall sända sina vredes grymhet öfver honom; han skall öfver honom regna låta sina strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Han skall fly för jernharnesk, och kopparbågen skall förjaga honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Ett draget svärd skall gå igenom honom, och svärds blänkande, som honom skall bittert varda, skall med förskräckelse gå öfver honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Intet mörker är, som honom skyla må; en eld skall förtära honom, den intet uppblåst är; och den som qvar blifver i hans hyddo, honom skall illa gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Himmelen skall uppenbara hans ondsko, och jorden skall sätta sig upp emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Hans säd i hans huse skall bortförd varda, förspilld uti hans vredes dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Detta är en ogudaktigs menniskos lön när Gudi, och hans ords arf när Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Job svarade och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Hörer dock till min ord, och låter säga eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Hafver tålamod med mig, att jag ock må tala; och görer sedan spott af mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Månn jag handla med en mennisko, att min ande icke skulle härutinnan ångse varda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Vänder eder hit till mig; I skolen förundra eder, och måsten lägga handena på munnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'När jag tänker deruppå, så förskräckes jag; och ett bäfvande kommer uppå mitt kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Hvi lefva då de ogudaktige, varda gamle, och växa till i ägodelar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Deras säd är säker omkring dem, och deras afföda är när dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Deras hus hafver frid för räddhåga, och Guds ris är icke öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Deras oxa släpper man till, ock missgår icke; deras ko kalfvar, och är icke ofruktsam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Deras unga barn gå ut såsom en hjord, och deras barn springa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'De fröjda sig med trummor och harpor, och äro glade med pipande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'De varda gamle med göda dagar, och förskräckas som nogast ett ögnablick för helvetet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'De dock säga till Gud: Gack bort ifrån oss; vi vilje intet veta af dina vägar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Ho är den Allsmägtige, att vi honom tjena skole? Eller hvad kan det båta oss, om vi löpe emot honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Men si, deras ägodelar stå icke uti deras händer; derföre skall de ogudaktigas sinne vara långt ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Huru varder de ogudaktigas lykta utsläckt; och deras förderf kommer öfver dem? Han skall utskifta jämmer i sine vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'De skola varda såsom strå för vädret, och såsom agnar, hvilka stormen bortförer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Gud förvarar hans barnom bedröfvelse; när han skall löna honom, då skall man förnimmat,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Hans ögon skola se hans förderf, och af dens Allsmägtigas vrede skall han dricka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Ty ho skall hafva behag till hans hus efter honom? Och hans månaders tal skall näppliga hälft blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Ho vill lära Gud, den ock dömer de höga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Denne dör frisk och helbregda, rik och säll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Hans mjölkekar äro full med mjölk, och hans ben varda full med märg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Men en annan dör med bedröfvada själ, och hafver aldrig ätit i glädje.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Och de ligga tillhopa med hvarannan i jordene, och matkar öfvertäcka dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Si, jag känner väl edra tankar, och edor vrånga anslag emot mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Ty I sägen: Hvar är Förstans hus? Och hvar äro hyddorna, der de ogudaktige bodde?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Talen I dock derom såsom meniga folket; och veten icke hvad de andras väsende betyder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Ty den onde varder behållen intill förderfvelsens dag, och intill vredenes dag blifver han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Ho vill säga hvad han förtjenar, när man det utvärtes anser? Ho vill vedergälla honom hvad han gör?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Men han varder bortdragen till grafvena, och man vaktar efter honom i högomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Bäckaslem behagar honom väl, och alla menniskor varda dragna efter honom; och uppå dem, som för honom varit hafva, är intet tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Huru trösten I mig så fåfängt, och edor svar finnas dock orätt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Menar du att en man kan liknas vid Gud; eller någor är så klok, att han kan likna sig vid honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Menar du att dem Allsmägtiga behagar, att du räknar dig så from? Eller hvad hjelper det honom, om än dine vägar utan brist voro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Menar du han fruktar att straffa dig, och gå till rätta med dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ja, din ondska är fast stor, och uppå din orättfärdighet är ingen ände.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Du hafver tagit af dinom broder pant utan sak; du hafver dragit kläden af dem nakna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Du hafver icke gifvit dem trötta vatten dricka; du hafver nekat dem hungroga ditt bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Du hafver brukat våld i landena, och bott deruti med stort prål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Enkor hafver du låtit gå ohulpna, och sönderbrutit de faderlösas armar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Derföre äst du omvefvad med snaro, och fruktan hafver dig hasteliga förskräckt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Skulle du då icke se mörkret, och vattufloden icke öfvertäcka dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Si, Gud är hög i himmelen, och ser stjernorna uppe i höjdene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Och du säger: Hvad vet Gud? Skulle han kunna döma det i mörkret är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Skyn skyler för honom, och han ser intet; han vandrar i himmelens omgång.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Vill du akta på verldenes lopp, der de orättfärdige uti gångne äro?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Hvilke förgångne äro, förr än tid var, och vattnet hafver bortsköljt deras grund;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'De som till Gud sade: Far ifrån oss; hvad skulle den Allsmägtige kunna göra dem?.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Ändock han uppfyllde deras hus med ägodelar; men de ogudaktigas råd vare långt ifrå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'De rättfärdige skola få det se, och glädja sig; och den oskyldige skall bespotta dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Deras väsende skall försvinna, och det qvart är af dem, skall elden förtära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Så förlika dig nu med honom, och haf frid; derutaf skall du hafva mycket godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Hör lagen utaf hans mun, och fatta hans tal uti ditt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Om du omvänder dig till den Allsmägtiga, så skall du uppbyggd varda; och kasta det orätt är långt ifrå dine hyddo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Så skall han gifva guld igen för stoft, och för sten gyldene bäcker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Och du skall hafva guld nog, och silfver skall dig med hopom tillfalla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Då skall du hafva din lust i dem Allsmägtiga, och upplyfta ditt anlete till Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Du skall bedja honom, och han skall höra dig; och ditt löfte skall du betala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Ehvad du tager dig före, det skall han låta dig väl af gå; och ljus skall skina på dina vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Förty de som sig ödmjuka, dem upphöjer han; och den som sin ögon nederslår, han skall blifva frälst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Och den oskyldige skall hulpen varda; för sina händers renhets skull skall han hulpen varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Mitt tal blifver ännu bedröfvadt; min magt är svag för mitt suckandes skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ack! det jag visste, huru jag skulle finna honom, och komma till hans stol;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Och sätta min rätt fram för honom, och uppfylla min mun med straff;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Och förfara hvad ord han mig svara ville, och förnimma hvad han mig sägandes vorde!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Vill han med stora magt träta med mig? Han ställe sig icke så emot mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Utan lägge mig före hvad likt är, så vill jag väl vinna min rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Men går jag rätt framåt, så är han der intet; går jag tillbaka, så varder jag honom intet varse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Är han på venstra sidone, så fattar jag honom intet; förgömmer han sig på högra sidone, så ser jag honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Men han känner väl min väg; han försöke mig, så skall jag funnen varda såsom guld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Ty jag sätter min fot uppå hans fjät, och håller hans väg, och viker intet deraf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Och träder intet ifrå hans läppars bud, och bevarar hans muns ord, mer än jag skyldig är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Han är enig; ho vill svara honom? Och han gör allt som han vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Och om han mig än vedergäller hvad jag förtjent hafver, så står ändå för honom mycket tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Derföre är jag förskräckt för honom, och när jag det märker, så fruktar jag mig för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Gud hafver gjort mitt hjerta blödigt, och den Allsmägtige hafver mig förskräckt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Ty mörkret vänder icke åter med mig, och mörker vill för mig intet bortgömdt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Hvi skulle tiderna dem Allsmägtiga icke fördolda vara? Och de honom känna, se intet hans dagar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'De flytta råmärken, de röfva bort hjorden, och föda honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'De drifva bort de faderlösas åsna, och taga enkones oxa till pant.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'De fattige måste vika för dem, och de torftige i landena måste förgömma sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Si, vilddjuren i öknene gå ut, såsom de pläga, bittida till rofs, att de skola bereda mat för ungarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'De uppskära af den åker, som dem intet tillhörer; och berga den vingård, som de med orätt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'De nakna låta de ligga, och låta dem intet öfvertäckelse i frostena, hvilkom de deras kläder borttagit hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Så att de måste hålla sig i bergskrefvom, när en regnskur af bergen faller neder uppå dem; efter de eljest ingen råd hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'De slita barnet ifrå bröstet, och göra det faderlöst; och göra menniskorna fattiga med pantande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Den nakna låta de gå utan kläder, och dem hungroga borttaga de axen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'De tvinga dem till att göra oljo uppå deras qvarn, och trampa deras pressar, och låta dem likväl törsta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'De göra folket i staden suckande, och dess slagnas själar ropande; och Gud straffar dem intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Derföre äro de affallne ifrå ljusena, och känna icke dess väg, och vända icke om till dess stigar igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'I lysningene står mördaren upp, och dräper den fattiga och torftiga; och om nattena är han som en tjuf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Horkarlens öga hafver akt på skymningena, och säger: Mig ser intet öga; och han förtäcker sitt anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'I mörkrena bryter han sig in i husen; om dagen gömma de sig med hvarannan, och vilja intet veta af ljusena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Ty om än morgonen kommer dem, är det dem såsom ett mörker; förty han förnimmer mörkrens förskräckelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Han far lätteliga åstad såsom uppå ett vatten; hans håfvor varda icke stora i landena, och han brukar intet sin vingård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Helvetet tager bort dem som synda, såsom hette och torka förtärer snövattnet bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'De barmhertige skola förgäta honom; hans lust varder full med matk; man skall icke mer tänka uppå honom; han skall sönderbruten varda såsom ett ruttet trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Han hafver bedröfvat den ensamma, som intet föder; och enkone hafver han intet godt gjort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Och hafver dragit de mägtiga under sig med sine kraft. När han står, skall han icke viss vara uppå sitt lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Han gör sig sjelf en trygghet, der han sig uppå förlåter; dock se hans ögon uppå deras handel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'De äro en liten tid upphäfne; men de varda omintet, och undertryckte, och taga en ända såsom all ting; och såsom agnar på axen skola de afslagne varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Är det icke så? Nu väl, ho vill straffa mig för lögn, och göra min ord om intet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Är icke herrskap och fruktan när honom, hvilken frid gör ibland sina högsta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Ho kan räkna hans krigsmän? Och öfver hvem uppgår icke hans ljus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Och huru kan en menniska rättfärdig varda för Gudi? Eller huru kan ene qvinnos barn rent vara?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Si månen skin icke ännu, och stjernorna äro ännu icke rena för hans ögon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Huru mycket mindre en menniska, den malen, och ens menniskos barn, den matken?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Hvem äst du biståndig? Dem som ingen magt hafver? Hjelper du honom, som ingen starkhet hafver i armenom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Hvem gifver du råd? Dem som intet vet? Och du bär fram dina stora gerningar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'För hvem talar du? Och inför hvem går anden ifrå dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'De Reser ängslas under vattnen, och de som när dem bo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Helvetet är bart för honom, och förderfvet hafver intet öfvertäckelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Han sträcker ut nordet på ingo, och hänger jordena uppå intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Vattnet samkar han i sina skyar, och skyarna remna icke derunder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Han håller sin stol, och utbreder sin sky derföre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Han hafver satt ett mål om vattnet, intilldess ljus och mörker blifver ändadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Himmelens stodar skälfva, och gifva sig för hans näpst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'För hans kraft varder hafvet hasteliga stormande, och för hans klokhet stillar sig hafsens höghet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'På himmelen varder det klart igenom hans väder, och hans hand drifver bort hvalfisken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Si, alltså går det till med hans gerningar; men hvad besynnerligit hafve vi derutinnan hört? Ho kan förstå hans magts dunder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Och Job höll talet fram; hof upp sitt ordspråk, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Så sant som Gud lefver, den mig min rätt förvägrar, och den Allsmägtige, som mina själ bedröfvar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Så länge min ande i mig är, och andedrägten af Gudi i mino näso är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Mine läppar skola intet orätt tala, och min tunga skall intet bedrägeri för händer hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Bort det ifrå mig, att jag skulle gifva eder rätt; intilldess min ände kommer, skall jag icke vika ifrå mine fromhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Ifrå mine rättfärdighet, som jag håller vill jag icke gå; mitt samvet gnager mig intet för alla mina lifsdagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Men min fiende varder funnen ogudaktig, och min motståndare orättvis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Ty hvad är ens skrymtares hopp, att han så girig är; och Gud rycker dock hans själ bort?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Menar du, att Gud skall höra hans röst, när ångest kommer honom uppå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Huru kan han hafva lust till den Allsmägtiga, och något åkalla honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Jag vill lära eder om Guds hand, och hvad för dem Allsmäktiga gäller, vill jag icke dölja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Si, I hållen eder alle, att I ären vise; hvi gifven I då sådana onyttig ting före?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Detta är en ogudaktig menniskos lön när Gudi, och de tyranners arf, som de af dem Allsmägtiga få skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Om han får mång barn, så skola de höra svärdet till; och hans afföda skall icke af bröd mätt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Hans återlefde skola i dödenom begrafne varda, och hans enkor skola intet gråta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Om han samkar penningar tillhopa såsom stoft, och tillreder sig kläder såsom ler,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Så skall han väl tillredat; men den rättfärdige skall kläda sig deruti, och den oskyldige skall utskifta penningarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Han bygger sitt hus såsom en spindel, såsom en väktare gör sig ett skjul.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'När den rike nedläggs, skall han intet få med sig; han skall upplåta sin ögon, och finna intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Honom skall öfverfalla förskräckelse såsom vatten; om nattena skall stormväder taga honom bort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Östanväder skall föra honom bort, att han skall förgås; och oväder skall drifva honom af hans rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Detta skall han låta komma öfver honom, och skall intet skona honom; allt skall det gå honom ifrå hända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Man skall klappa händer tillhopa öfver honom, och hvissla öfver honom, der han varit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Silfret hafver sin gång, och guldet sitt rum, der det verkas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Jern tager man utaf jordene, och utaf stenar smälter man koppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'På mörkret varder ju en tid ände, och finner ju någor på sistone det fördolda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Det springer ut en sådana bäck, att de, som bo deromkring, icke kunna gå deröfver till fots; han varder menniskomen allt för djup, och flyter sin kos.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Man får ock eld nedan utu jordene; der dock ofvantill bröd växer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Man finner saphir på somlig rum, och jordklimpar, der guld är uti.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Den stigen hafver ingen fogel kunnat, och intet gamsöga sett;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'De stolta barn hafva icke trampat honom, och intet lejon gångit deruppå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Bär man också handena på stenen, och grafver bergen omkull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Man grafver bäcker utu hällebergen, och allt det kosteligit är, ser ögat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Man förtager strömmom vattnet, och hafver fram i ljuset det derutinnan fördoldt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Huru vill man nu vishet finna, och hvar är rummet till förståndighet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Ingen vet hvar hon ligger; och varder icke funnen i de lefvandes lande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Afgrundet säger: Hon är icke i mig; och hafvet säger: När mig är hon icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Man kan icke gifva der penningar före, ej heller silfver uppväga, till att betala henne med.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Hon räknas icke vid Ophiriskt guld, eller vid kostelig onich och saphir;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Guld och diamant kan icke liknas dervid, ej heller kan hon tillbytas för gyldene klenodier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Ramoth och Gabis aktar man intet; hon är högre aktad än perlor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topats af Ethiopien varder icke lika skattad emot henne, och det renaste guld gäller icke deremot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Hvadan kommer då visheten? Och hvar är rummet till förståndigheten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Hon är fördold för allas lefvandes ögon, och öfverskyld för foglarna under himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Fördömelsen och döden säga: Vi hafve med vår öron hört hennes rykte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Gud vet vägen dertill, och känner hennes rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Förty han ser jordenes ända, och skådar allt det under himmelen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Så att han gifver vädrena sina vigt, och vattnena sitt matt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Då han satte regnena ett mål före, och tordönenom och ljungeldenom sin väg,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Då såg han henne, och räknade henne; tillredde henne, och fann henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Och sade till menniskona: Si, Herrans fruktan är vishet; och fly det onda är förståndighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Och Job hof åter upp sitt ordspråk, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ack! att jag vore såsom uti de förra månader, uti de dagar då Gud bevarade mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Då hans lykta sken öfver mitt hufvud, och jag i mörkrena gick vid hans ljus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Såsom jag var i min ungdoms tid, då Guds hemlighet var öfver mina hyddo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Då den Allsmägtige ännu med mig var, och mine tjenare allt omkring mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Då jag tvådde min väg uti smör, och hälleberget utgöt mig oljoflodar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Då jag utgick till stadsporten, och lät bereda mig mitt säte på gatone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Då mig ynglingar sågo, och undstungo sig, och de gamle uppstodo för mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Då de öfverste igen vände att tala, och lade sina hand på sin mun;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Då Förstarnas röst gömde sig undan, och deras tunga lådde vid deras gom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Ty hvilkens öra mig hörde, den prisade mig saligan; och hvilkens öga mig såg, den vittnade om mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Förty jag halp den fattiga, som ropade, och den faderlösa, som ingen hjelpare hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Dens välsignelse, som förgås skulle, kom öfver mig; och jag tröstade enkones hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Rättfärdighet var min klädebonad, den iklädde jag såsom en kjortel; och min dom var min skrud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Jag var dens blindas öga, och dens haltas fot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Jag var de fattigas fader, och hvilken sak jag icke visste, den utfrågade jag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Jag sönderslog dens orättfärdigas oxlatänder, och tog rofvet utu hans tänder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Jag tänkte: Jag vill dö uti mitt näste, och göra mina dagar många såsom sand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Min säd gick upp af vätsko, och dagg blef öfver min årsväxt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Min härlighet förnyade sig för mig, och min båge förvandlade sig i mine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'De hörde mig, och tigde; och vaktade uppå mitt råd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Efter min ord talade ingen mer, och mitt tal dröp på dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'De vaktade på mig såsom på regn, och uppgapade med munnen såsom efter aftonregn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Om jag log till dem, förläto de sig intet deruppå; och torde intet bedröfva mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'När jag ville komma till deras handlingar, så måste jag sitta främst; och bodde såsom en Konung ibland krigsfolk, då jag hugsvalade dem som sorgfulle voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Nu le de att mig, som yngre äro än jag; hvilkas fäder jag icke ville vårdat sätta ibland mins hjords hundar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Hvilkas förmågo jag för intet höll; de icke till ålders komma kunde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'De som för hungers skull och bekymmer ensamme flydde in i öknena, nyliga förderfvade och elände vordne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'De som nesslo uppryckte omkring buskarna, och enerötter var deras mat;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Och då de dem uppryckte, fröjdades de deröfver såsom en tjuf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Vid de stygga bäcker bodde de, uti jordkulor och bergskrefvor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Emellan buskar ropade de, och ibland tistlar församlade de sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'De lösa och föraktada menniskors barn, de som ringast voro i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Nu är jag deras strängaspel vorden, och måste vara deras nymäre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'De styggas vid mig, och draga sig långt ifrå mig; och spara icke att spotta för mitt ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Ty han hafver spänt mina seno, och hafver ödmjukat mig; och lagt ett betsel i munnen uppå mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'På högra sidone, der jag grönskades, satte de sig upp emot mig; och stötte mina fötter bort, och gjorde en väg öfver mig, till att förderfva mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'De hafva förspillt mina stigar; det var dem så lätt att göra mig skada, att de ingen hjelp behöfde dertill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'De äro inkomne såsom genom stora refvor, och äro utan ordan infallne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Förskräckelse hafver vändt sig emot mig, och såsom ett väder förföljt mina frihet, och såsom en löpande sky mina helso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Men nu utgjuter sig min själ öfver mig, och mine sorgedagar hafva fattat mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Om nattena varda min ben allestäds igenomborrad; och de, som mig jaga, läggar sig intet till att sofva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Genom stora kraft varder jag margalunda klädd; och de begjorda mig dermed, såsom igenom min kjortels hufvudsmog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Man hafver trampat mig i träck, och aktat mig lika emot stoft och asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Ropar jag till dig, så svarar du mig intet; går jag fram, så aktar du mig intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Du äst mig förvänd till en grufveligan, och drager ditt hat till mig med dine hands starkhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du lyfter mig upp, och låter mig fara uppå vädrena, och försmälter mig krafteliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Ty jag vet, du öfverantvardar mig dödenom; der är det hus, som allom lefvandom förelagdt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Dock räcker han icke sina hand ut in i benhuset, och de varda ej ropande öfver sitt förderf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Jag gret ju uti den hårda tiden, och min själ varkunnade sig öfver den fattiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Jag vänte det goda, och det onda kom; jag vänte ljuset, och mörkret kom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mina inelfvor sjuda, och hålla intet upp; mig är uppåkommen sorgetid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Jag går bedröfvad, ändock jag på ingen vredgas; jag står upp i menighetene och ropar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Jag är drakars broder, och strutsfoglars stallbroder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Min hud öfver mig är svart vorden, och min ben är förtorkad af hetta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Min harpa är vorden en klagan, och min pipa en gråt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Jag hafver gjort ett förbund med min ögon, att jag intet skall sköta efter någon jungfru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Men hvad gifver mig Gud till löna ofvan efter, och hvad arfvedel den Allsmägtige af höjdene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Skulle icke heldre den orättfärdige hafva den vedermödona, och en ogerningsman sådana jämmer lida?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ser han icke mina vägar, och räknar alla mina gånger?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Hafver jag vandrat i fåfängelighet, eller min fot skyndat sig till bedrägeri?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Man väge mig på en rätt våg, så skall Gud förnimma min fromhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Hafver min gång vikit utaf vägen, och mitt hjerta efterföljt min ögon, och något lådat vid mina händer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Så låt mig så, och en annar äte det; och min ätt varde utrotad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Hafver mitt hjerta låtit sig draga till qvinno, och hafver vaktat vid mins nästas dörr,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Så varde min hustru af enom androm skämd, och andre besofve henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Ty det är en last och en missgerning för domarena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Ty det vore en eld, som förtärer intill förderf, och all min tilldrägt utrotade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Hafver jag föraktat, mins tjenares eller mine tjenarinnos rätt, då de med mig trätte?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Hvad ville jag göra, när Gud reser sig upp? Och hvad ville jag svara, när han hemsöker?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hafver ock icke han gjort honom, den mig i moderlifvet gjorde; och hafver ju så väl tillredt honom i lifvena?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Hafver jag dem torftigom förnekat hvad de begärde, och låtit enkones ögon försmäkta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Hafver jag ätit min beta allena, att den faderlöse icke också hafver ätit deraf?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Ty ifrå minom ungdom hafver jag hållit mig såsom en fader, och allt ifrå mitt moderlif hafver jag gerna hugsvalat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Hafver jag någon sett förgås, derföre att han icke hade kläder; och låtit den fattiga gå oskyldan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Hafva icke hans sidor välsignat mig, då han af min lambs skinn värmad vardt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Hafver jag låtit komma mina hand vid den faderlösa, ändock jag såg mig i portenom magt hafva,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Så falle mina skuldror ifrå mina axlar, och min arm gånge sönder ifrå läggenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Ty jag fruktade Gud såsom en olycko öfver mig, och kunde hans tunga icke bära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Hafver jag satt guld till min tröst, och sagt till guldklimpen: Du äst mitt hopp?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Hafver jag gladt mig, att jag myckna ägodelar hade, och min hand allahanda förvärfvat hade?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Hafver jag sett på ljuset, då det klarliga sken, och på månan, då han i fyllo gick?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Hafver mitt hjerta hemliga låtit sig tälja i det sinnet, att min mun skulle kyssa mina hand?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Hvilket ock en missgerning är för domarena; förty dermed hade jag nekat Gud i höjdene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Hafver jag gladt mig, när minom fiende gick illa, och upphäfvit mig, att olycka råkade uppå honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Ty jag lät min mun icke synda, så att han önskade hans själ ena banno.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Hafva icke de män i mine hyddo måst säga: Ack! att vi icke måtte af hans kött mättade varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Ute måste den främmande icke blifva; utan dem vägfarande lät jag mina dörr upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Hafver jag såsom en menniska skylt mina skalkhet, att jag skulle hemliga fördölja min missgerning?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Hafver jag grufvat mig för stora hopen; eller hafver frändernas föraktelse mig förskräckt? Jag blef stilla, och gick icke ut genom dörrena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ho gifver mig en förhörare, att den Allsmägtige må höra mitt begär? Att någor måtte skrifva en bok om mine sak;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Så ville jag taga henne uppå mine axlar, och ombinda mig henne såsom en krono.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Jag ville förkunna talet på mina gånger, och såsom en Förste ville jag det frambära.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Om min jord ropar emot mig, och dess fårar alle tillika gråta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Hafver jag dess frukt obetalad ätit, och gjort åkermännernas lefverne tungt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Så växe mig tistel för hvete, och törne för bjugg. En ända hafva Jobs ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Då vände de tre män åter att svara Job; efter han höll sig rättfärdigan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Men Elihu, Baracheels son, af Bus af Kams slägte, vardt vreder uppå Job, att han höll sina själ rättfärdigare än Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Ock vardt han vred uppå de tre hans vänner, att de intet svar funno, och dock fördömde Job.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Ty Elihu hade bidt, så länge de hade talat med Job, efter de voro äldre än han.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Derföre, då, han såg, att intet svar var i de tre mäns mun, vardt han vred.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Och så svarade Elihu, Baracheels son, af Bus, och sade: Jag är ung, och I ären gamle, derföre hafver jag skytt, och fruktat bevisa min konst på eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Jag tänkte: Låt åren tala, och åldren bevisa vishet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Men anden är i menniskone, och dens Allsmägtigas Ande gör henne förståndiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Mästarena äro icke de visaste, och de gamle förstå icke hvad rätt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Derföre vill jag ock tala; hör härtill, jag vill ock bevisa mina konst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Si, jag hafver bidt, medan I talat hafven; jag hafver gifvit akt på edart förstånd, tilldess I hafven gjort en ända på edart tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Och jag hafver haft akt uppå eder, och si, ingen är ibland eder, som Job straffa, eller till hans ord svara kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'I mågen tilläfventyrs säga: Vi hafve drabbat på vishetena, att Gud hafver bortkastat honom, och ingen annar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Det talet gör mig icke fyllest; jag vill intet svara honom, efter som I taladen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ack! de uppgifvas, och kunna intet mer svara; de kunna intet mer tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Efter jag nu bidt hafver, och de kunna intet tala; förty de stå tyste, och svara intet mer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Vill jag dock svara min part, och bevisa mina konst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Ty jag är så full med ordom, att min ande ängslas i minom buk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Si, min buk är såsom must, dem tilltäppt är, hvilken ny fat sönderslår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Jag måste tala, att jag må få andas; jag måste upplycka mina läppar och svara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Jag vill på ingens person se, och ingo mennisko till vilja tala;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Förty jag vet icke, om jag så gjorde, om min skapare innan en kort tid mig borttagandes vorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Hör dock, Job, mitt tal, och gif akt på all min ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Si, jag låter min mun upp, och min tunga skall tala i minom mun;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mitt hjerta skall tala rätt, och mine läppar skola säga ett rent förstånd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Guds Ande hafver gjort mig, och dens Allsmägtigas Ande hafver gifvit mig lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Kan du, så svara mig; kom fram jemte mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Si, jag hörer Gudi till, såsom du säger, och utaf jord är jag också gjord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Dock du torf icke förfäras för mig, och min hand skall icke vara dig för svår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Du hafver talat för min öron; dins ords röst måste jag höra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Jag är ren och utan all last, oskyldig, och hafver ingen synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Si, han hafver funnit en sak emot mig, derföre håller han mig för sin fienda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Han hafver satt min fot i stocken, och förvarat alla mina vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Si, rätt derutaf besluter jag emot dig, att du icke äst rättfärdig; ty Gud är mer än en menniska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Hvi vill du träta med honom, att han icke gör dig räkenskap på allt det han gör?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Om Gud en gång något befaller, skall man då icke först se derefter, om det rätt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Uti synenes dröm om nattene, när sömnen faller uppå menniskorna, när de sofva på sängene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Då öppnar han menniskors öra; och förskräcker dem, och näpser dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'På det han skall vända menniskona ifrån olycko, och förvara henne för öfvermod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Han skonar hennes själ för förderf, och hans lif, att det icke skall falla i svärdet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Och näpser honom med sveda uppå hans säng, och all hans ben mägteliga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Och far så med honom, att honom vämjes vid maten, och hans sjal icke hafver lust till att äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hans kött försvinner, så att man intet ser det, och hans ben förkrossas, så att man icke gerna ser dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Att hans själ nalkas till förderf, och hans lif till de döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Om nu en Ängel, en af tusende, trädde fram för honom, till att förkunna menniskone Guds rättfärdighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Då skall han förbarma sig öfver honom, och säga: Han skall förlossad varda, att han icke skall fara neder i förderfvet; ty jag hafver funnit en försoning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Hans kött komme sig till igen, såsom i ungdomen, och låt honom åter varda ung igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Han skall bedja Gud, den skall bevisa honom nåder; han skall se sitt ansigte med glädje, och skall vedergälla menniskone hennes rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Han skall för menniskomen bekänna, och säga: Jag hafver syndat och illa gjort, och mig är ännu för litet skedt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Han hafver förlossat mina själ, att hon icke skulle komma i förderf; utan mitt lif skulle få se ljuset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Si, allt detta gör Gud två eller tre gångor med hvarjom och enom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'På det han skall hemta hans själ igen utu förderfvet; och upplyser honom med de lefvandes ljuse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Gif akt häruppå, Job, och hör härtill, och tig, att jag må tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Men hafver du något att tala, så svara mig. Säg, äst du rättfärdig; jag vill gerna hörat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Hafver du ock intet, så hör mig, och tig; jag vill lära dig visdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Och Elihu svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Hörer, I vise, mitt tal, och I förståndige, akter på mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Ty örat pröfvar talet, och munnen smakar maten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Låt oss utvälja en dom, att vi måge emellan oss känna hvad godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Ty Job hafver sagt: Jag är rättfärdig, och Gud hafver förvägrat mig min rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Jag måste ljuga, om jag än rätt hade; jag varder plågad af min skott, om jag än det intet förskyllat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Ho är en sådana, som Job; som gabberi dricker såsom vatten,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Och går på vägenom med illgerningsmän, så att han vandrar med ogudaktiga män?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Ty han hafver sagt: Om än någor rätt färdig vore, så gäller han dock intet när Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Hörer mig, I vise män: Bort det, att Gud skulle vara ogudaktig, och den Allsmägtige orättvis;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Utan han lönar menniskone, efter som hon hafver förtjent; och drabbar uppå hvar och en efter hans gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Utan tvifvel, Gud fördömer ingen med orätt, och den Allsmägtige böjer icke rätten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Ho hafver skickat det uppå jordene är, och ho hafver satt hela jordenes krets?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Om han det toge sig före, kunde han allas anda och lif till sig samla;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Allt kött vorde tillhopa förgåendes, och menniskan vorde åter till asko igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Hafver du förstånd, så hör detta, och gif akt på mins tals röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Skulle någon fördenskull tvinga rätten, att han hatar honom? Och derföre att du stolt äst, skulle du fördenskull fördöma den rättfärdiga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Skulle någor säga till Konungen: Du Belial? och till Förstarna: I ogudaktige?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Den dock icke ser på Förstarnas person, och känner icke mer den härliga än den fattiga; förty de äro alle hans handaverk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Med hast måste menniskorna dö, och om midnattstid förskräckas och förgås; de mägtige varda kraftlöse borttagne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Ty hans ögon se uppå hvars och ens vägar, och han skådar alla deras gånger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Intet mörker eller skygd är, att ogerningsmän måga sig der fördölja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Ty det varder ingom tillstadt, att han kommer med Gud till rätta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Han förgör många stolta, som icke stå till att räkna; och sätter andra i deras stad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Derföre, att han känner deras gerningar; och omstörter dem om nattena, att de skola sönderkrossade varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Han kastar de ogudaktiga uti en hop, der man gerna ser det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Derföre, att de icke hafva följt honom efter, och förstodo ingen af hans vägar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Att de fattigas rop skulle komma inför honom, och han dens eländas rop höra måtte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Om han frid gifver, ho vill fördöma? Och om han förskyler anletet, ho vill se uppå honom ibland folken och menniskorna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Så låter han nu en skrymtare regera, till att plåga folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'För Guds skull vill jag lida talet, och icke förmenat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Hafver jag icke drabbat rätt, lär du mig bättre; hafver jag orätt handlat, vill jag icke göra så mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Man vänter nu svar af dig; ty du förkastar all ting, och du hafver begynt det, och icke jag. Vetst du nu något, så tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Visa män låter jag väl tala, och en vis man hörer mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Men Job talar ovisliga, och hans ord äro icke vis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Min Fader, låt Job försökt varda allt intill ändan, derföre att han vänder sig till orättfärdiga menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Han hafver utöfver sina synd ännu dertill hädat; derföre låt honom inför oss slagen varda; och träte sedan med sinom ordom inför Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Och Elihu svarade, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Håller du det för rätt, att du säger: Jag är rättvisare än Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Ty du säger: Ho blifver något räknad för dig? Hvad hjelper det, om jag håller mig ifrå synd?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Jag vill svara dig med ordom, och dinom vännom med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Se upp till himmelen, och skåda; och se uppå skyarna, att de äro dig för höge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Om du syndar, hvad kan du skaffa emot honom? Och om din ondska är stor, hvad kan du göra honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Och om du äst rättfärdig, hvad kan du gifva honom, eller hvad kan han taga af dina händer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Ene mennisko, såsom du äst, må din ondska något göra, och ene menniskos barne din rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'De samme måga ropa, när dem mycket öfvervåld sker, och ropa öfver de väldigas arm;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'De der intet säga: Hvar är Gud, min skapare, som sånger gör om nattena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Den oss gör lärdare än djuren på jordene, och visare än foglarna under himmelen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Men de skola der ock ropa öfver de ondas högmod, och han skall intet höra dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Ty Gud hörer icke fåfängelighetena, och den Allsmägtige ser der intet till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Nu säger du; Du ser honom intet; men en dom är för honom, allenast förbida honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Om hans vrede icke så hastigt hemsöker, och intet sköter, att der så många laster äro,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Derföre hafver Job fåfängt öppnat sin mun; och gifver onyttig ord före med oförnuft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu talade ytterligare, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Töfva ännu litet, jag vill visa dig det; ty jag hafver ännu på Guds vägnar något säga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Jag vill hemta mitt förstånd fjerranefter, och bevisa, att min skapare är rättvis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Mitt tal skall utan tvifvel intet falskt vara; mitt förstånd skall utan fel vara för dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Si, Gud förkastar icke de mägtiga; ty han är ock mägtig af hjertans kraft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Den ogudaktiga bevarar han icke; utan hjelper den arma till rätta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Han vänder icke sin ögon ifrå den rättfärdiga; och Konungarna låter han sitta på stolenom i evig tid, att de höge blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Och om fångar ligga i bojor, och bundne med tåg jämmerliga,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Så gifver han dem tillkänna hvad de gjort hafva; och deras odygd, att de hafva brukat våld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Och öppnar dem örat till tuktan, och säger dem, att de skola omvända sig ifrå det orätt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Om de höra och tjena honom, så skola de i godom dagom gamle varda, och lefva med lust.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Höra de icke, så skola de falla för svärd, och förgås förr än de varda det varse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'De skrymtare, när vreden kommer uppå dem, ropa de intet, när de fångne ligga;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Så skall deras själ dö med qval, och deras lif ibland bolare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Men den arma skall han, hjelpa utu hans armod, och öppnar dem arma örat i bedröfvelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Han skall taga dig utur ångestens vida mun, den ingen botten hafver, och ditt bord skall hafva ro, uppfyldt med allt godt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Men du gör de ogudaktigas sak godan, så att deras sak och rätt blifver behållen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Se till, om icke otålighet hafver rört dig i qvalena; eller stora gåfvor icke hafva böjt dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Menar du, att din väldighet skall bestå kunna utan bedröfvelse; eller eljest någon starkhet eller förmåga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Du torf icke begära nattena till att öfverfalla menniskorna i deras rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Vakta dig, och vänd dig icke till det orätt är, såsom du för jämmers skull dig företagit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Si, Gud är för hög i sine kraft; ho är en lagförare såsom han är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Ho vill hemsöka öfver honom hans väg? Och ho vill säga till honom: Du gör orätt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Tänk uppå, att du intet vetst hans verk, såsom menniskorna sjunga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Ty alla menniskor se det, menniskorna se det fjerran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Si, Gud är stor och okänd; hans åratal kan ingen utfråga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Han gör vattnet till små droppar, och drifver sina skyar samman till regn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Så att skyarna flyta, och drypa fast uppå menniskorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Då han tager sig före att skingra sina skyar, och tager sitt täckelse bort;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Si, så utbreder han sitt ljus öfver dem, och öfvertäcker hafvet, dädan de komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Ty dermed dömer han folket, och gifver dem mat tillfyllest.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Han håller händerna före, och betäcker ljuset, och bjuder thy, att det skall igenkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Om det samma förkunnar hans herde, och hans boskap om skyn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Deraf förskräcker sig mitt hjerta, och bäfvar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Hörer hans rösts skall, och det ljud som utaf hans mun går.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Han ser under alla himlar, och hans ljus skin uppå jordenes ändar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Efter honom bullrar dundret, han dundrar med ett stort skall; och när hans dundrande hördt varder, kan man intet förhålla det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gud dundrar med sitt dunder grufveliga, och gör stor ting, och varder dock intet känd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Han talar till snön, så är han straxt här på jordene, och till regnskuren, så är regnskuren der med magt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Man förgömmer sig ibland alla menniskor, att folket skall känna hans verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Vilddjuret kryper uti skjul, och blifver i sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Sunnanefter kommer väder, och nordanefter köld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Af Guds anda kommer frost, och stort vatten, då han utgjuter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'De tjocke skyar skilja sig, att klart skall varda, och igenom molnet utbrister hans ljus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Han vänder skyarna hvart han vill, att de skola göra allt det han bjuder dem på jordenes krets;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Ehvad det är öfver en slägt, eller öfver ett land, då man finner honom barmhertigan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Akta deruppå, Job; statt och förnim Guds under.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Vetst du, när Gud låter detta komma öfver dem; och när han låter sina skyars ljus utgå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Vetst du, huru skyarna utsprida sig; hvilka under de fullkomlige veta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Att din kläder varm äro, då landet är stilla af sunnanväder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ja, du utbreder icke skyarna med honom, hvilke starke äro, och anseende såsom en grund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Låt oss höra hvad vi skole säga honom; förty vi räcke icke intill honom för mörker.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Ho skall förtälja honom hvad jag talar? Om någor talar, han varder uppsluken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Nu ser man icke ljuset, som inom skyn lyser; men när vädret blås, göres det klart.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Ifrå nordan kommer guld, den förskräckelige Gudi till lof;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Men den Allsmägtiga kunna de intet finna, den så stor är i magtene; ty han måste ingen räkenskap göra af sinom rätt och rättfärdigom sakom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Derföre måste menniskorna frukta honom, och han fruktar inga visa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Och Herren svarade Job uti ett väder, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Hvilken är den som i sina tankar så fela vill, och talar så med oförnuft?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Gjorda dina länder såsom en man; jag vill fråga dig: Säg, äst du så klok?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Hvar vast du, då jag grundade jordena? Säg mig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Vetst du, ho henne hafver satt sitt mått; eller ho hafver dragit något snöre öfver henne?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Eller hvaruppå står hennes fotafäste; eller ho hafver henne en hörnsten lagt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Då morgonstjernorna tillsammans lofvade mig, och all Guds barn fröjdade sig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Ho hafver tillslutit hafvet med sina dörrar, då det utbrast såsom utu moderlifve;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Då jag klädde det med skyar, och invefvade det i töckno, såsom i lindakläde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Då jag förtog thy dess flod med minom dam, och satte thy bom och dörrar före;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Och sade: Allt härintill skall du komma, och icke vidare; här skola dina stolta böljor sätta sig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hafver du i dinom tid budit morgonen, och vist morgonrodnanom sitt rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Att jordenes ändar måga fattade varda, och de ogudaktige der utskuddade blifva?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Inseglet skall sig förvandla såsom ler, så att de skola blifva såsom ett kläde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Och dem ogudaktigom skall deras ljus förtaget varda, och de högfärdigas arm skall sönderbruten varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Hafver du kommit uti hafsens grund, och vandrat uti djupsens fjät?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Hafva dödsens dörrar någon tid upplåtit sig för dig; eller hafver du sett dörrarna åt mörkret?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hafver du förnummit huru bred jorden är? Låt höra, vetst du allt detta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Hvilken är vägen dit, der ljuset bor, och hvilket är mörkrens rum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Att du måtte aftaga dess gränso, och märka stigen till dess hus?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Visste du, att du skulle på den tiden född varda, och huru många dina dagar blifva skulle?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Hafver du der varit, dädan snön kommer; eller hafver du sett, hvadan haglet kommer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Hvilka jag bevarat hafver intill bedröfvelsens dag, intill stridenes och örligets dag?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Genom hvilken vägen delar sig ljuset, och östanväder uppkommer på jordena?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Ho hafver utskift regnskurene sitt lopp, och ljungeldenom och dundrena vägen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Så att det regnar uppå jordena, der ingen är, i öknene, der ingen menniska är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Att det skall uppfylla ödemarken och öknen, och kommer gräset till att växa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Ho är regnets fader? Ho hafver födt daggenes droppar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Utu hvars lif är isen utgången; och ho hafver födt rimfrostet under himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Att vattnet skulle fördoldt varda såsom under stenar, och djupet blifver ofvanuppå ståndandes?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Kan du binda tillsammans sjustjärnornas band, eller upplösa Orions band?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Kan du hemta morgonstjernorna fram i sin tid, eller föra vagnen på himmelen öfver sin barn?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Vetst du, huru himmelen skall regeras; eller kan du sätta ett herradöme öfver honom på jordene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kan du föra dina dunder högt uppe i skynom, att vattnens myckenhet dig öfvertäcker?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Kan du utsläppa ljungeldar, att de fara åstad, och säga: Här äre vi?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Ho hafver satt visdomen uti det fördolda? Ho hafver gifvit tankomen förstånd?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Ho är så vis, att han skyarna räkna kan? Ho kan förstoppa vattuläglarna i himmelen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'När stoftet är vått vordet, så att det tillhopalöper, och klimparne låda tillsammans?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Kan du gifva lejinnone hennes rof i jagtene; och mätta de unga lejonen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Så att de lägga sig uti sitt rum, och stilla ligga i kulone på vakt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ho reder korpenom mat, när hans ungar ropa till Gud, och veta icke hvar deras mat är?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Kan du sätta tiden, när stengetterna skola kidla på bergen? Eller hafver du märkt, när hindarna gå hafvande?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Hafver du räknat deras månader, när de fulle varda; eller vetst du tiden, när de skola föda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'De böja sig, när de föda, och rifva sig, och låta ut sina ungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Deras ungar varda fete, och växa ute; de gå ut, och komma intet till dem igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ho hafver låtit vildåsnan så fri gå? Ho hafver vildåsnans band upplöst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Hvilkom jag markena till hus gifvit hafver, och öknena till boning?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Han gör lek af stadsbullret; plågarenas trug hörer han intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Han ser efter bergen, der hans bet är, och söker hvar grönt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Menar du, att enhörningen skall tjena dig, och skall blifva vid dina krubbo?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Kan du binda honom oket uppå i dina fårar, så att han efter dig plog drager i dalomen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Kan du förlåta dig på honom, deraf att han mycket förmår, och låta honom för dig arbeta?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Kan du betro honom, att han drager dig dina säd hem igen, och församlar henne i dina lado?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Påfoglens vingar äro skönare än storkens, eller strutsfoglens vingar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Som sin ägg lägger i jordena, och låter heta jordena utkläcka dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Han förgäter, att de måga varda trampade, och något vilddjur sönderslår dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Han är så hård emot sina ungar, likasom de icke voro hans; han aktar icke, att han arbetar fåfängt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Ty Gud hafver förtagit honom visdom, och hafver intet förstånd gifvit honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'På den tiden han reser sig, upphöjer han sig, och bespottar både häst och man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Kan du gifva hästenom kraft; eller kan du pryda hans hals med hans gnäggande?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Kan du förfara honom såsom gräshoppor? Hvad förfärligit är, det är hans nos pris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Han rifver jordena, och är frimodig i sin starkhet; och drager ut emot den väpnada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Han bespottar räddhågan, och förfäras intet; och flyr icke för svärd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Det ännu kogret emot honom skallrade, och glimmade både glafven och sköld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Han skälfver och rasar, och trampar jordena; och tror intet, att trummeten lyder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'När trummeten fast klingar, säger han huj; och känner lukten af stridene lång väg, Förstarnas rop och fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Flyger höken genom ditt förstånd, och utbreder sina vingar söderut?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Flyger örnen så högt af din befallning, att han gör sitt näste i höjdene? I bergklippon bor han, och blifver i bergskrefvom, och i fast rum. Dädan af skådar han efter mat, och hans ögon se långt bort. Hans ungar supa blod, och hvar en åtel är, der är han. Och Herren svarade Job, och sade: Den som vill träta med den Allsmägtiga, skulle han draga sig undan? Och den som vill straffa Gud, måste han icke svara? Job svarade Herranom, och sade: Si, jag hafver bannats, hvad skall jag svara? Jag vill lägga mina hand uppå min mun. Jag hafver en gång talat, derföre vill jag icke mer svara; på en annan tid vill jag icke göra det mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Och Herren svarade Job utur ett väder, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Gjorda dina länder som en man. Jag vill fråga dig, och säg du mig:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Skulle du göra min dom omintet, och fördöma mig, på det du skall vara rättfärdig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Och hafver du en arm såsom Gud, och kan du med lika röst dundra, såsom han gör?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Bepryd dig med härlighet, och upphäf dig; kläd dig med lof och äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Strö ut dins grymhets vrede; se uppå alla högmodiga, och böj dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Och förtryck de ogudaktiga, der de äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Begraf dem tillsammans i jordene, och försänk deras prål uti det fördolda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Så vill jag ock bekänna dig, att din högra hand dig hjelpa kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Si, Behemoth, den jag bredovid dig gjort hafver, han skall äta hö såsom en oxe.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Si, hans kraft är uti hans länder, och hans förmåga i hans buks nafla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Hans stjert sträcker sig ut såsom ett ceder; hans hemlig tings senor äro förvecklada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Hans ben äro såsom kopparrör; hans benlägger såsom jernstafrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Han är begynnelsen af Guds vägar, den honom gjort hafver, han öfverfaller honom med sitt svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Bergen bära honom gräs, och all vilddjur spela der.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Han ligger i skuggan fördold, i rör och i träck.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Busken öfvertäcker honom med sin skugga, och pilträ vid bäcker öfvertäcka honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Si, han uppsluker strömmen, och grufvar sig intet; han låter sig tycka, att han vill uttömma Jordanen med sin mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Likväl griper man honom med sin egen ögon, och med snöre igenomborrar man honom hans näso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Kan du draga Leviathan med en krok, och fatta hans tungo med ett snöre?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Kan du sätta honom en ring i näsona, och borra honom hans kindben igenom med en syl?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Menar du, att han skall mycket bedjas före, eller smeka dig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Menar du, att du kan göra ett förbund med honom, att du må hafva honom till en träl evinnerliga?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Kan du spela med honom såsom med en fogel; eller binda honom dinom pigom? Menar du, att sällskapet skola skära honom sönder, att han blifver utdelad ibland köpmännerna? Kan du fylla ena not med hans hud, och någon fiskaryssjo med hans hufvud? När du kommer dina hand vid honom, så kom ihåg, att det en strid är, den du icke uthålla kan. Si, hans hopp skall fela honom, och han skall uppenbarligen fördrifven varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Ingen är så dristig, att han honom uppväcka tör. Ho är då den, som för mig bestå kan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Ho hafver något gifvit mig tillförene, att jag må honom det vedergälla? Mitt är allt det under hela himmelen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Jag vill icke förtiga hans kraft; ej heller hans magt, eller huru välskapad han är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Ho kan upptäcka honom hans kläde? Eller ho tör vågat, att fatta honom i tänderna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Ho kan öppna hans anletes kindben? Förskräckeliga stå hans tänder allt omkring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Hans fjäll äro lika som sköldar, sammanfäste hvar i annan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Det ena hänger in i det andra, så att vädret icke går deremellan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Det hänger hvar i annan, och hålla sig tillsammans, så att de icke kunna skiljas åt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Hans njusande är såsom ett glimmande ljus; hans ögon äro såsom morgonrodnans ögnahvarf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Utaf hans mun fara bloss och eldbrandar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Utaf hans näso går rök, såsom utaf heta grytor och kettlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Hans ande är glödande kol, och utu hans mun går låge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Han hafver en starkan hals, och det är honom lust, då han något förderfvar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Hans kötts ledamot hänga vid hvartannat; de äro faste i honom, att han icke rörd varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Hans hjerta är hårdt såsom sten, och så fast som ett stycke af understenen i qvarnene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'När han reser sig, förfära sig de starke; och när han får dem fatt, är der ingen nåde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Om man vill till honom med svärd, så rörer han sig intet; eller med spets, skott och harnesk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Han aktar jern såsom strå, och koppar såsom ruttet trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Ingen skytte förjagar honom; slungostenar äro honom såsom agnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Hammaren aktar han såsom strå; han bespottar de bäfvande spetsar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Han kan ligga på skarpt grus; han lägger sig uppå det skarpt är, såsom på dyngo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Han gör, att djupa hafvet sjuder såsom en gryta, och rörer det ihop, såsom man blandar ena salvo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Efter honom är vägen ljus; djupet aktar han såsom en gamlan gråhårotan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'På jordene kan ingen liknas honom; han är gjord till att vara utan fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Han föraktar allt det högt är; han är Konung öfver alla högmodiga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Och Job svarade Herranom, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Jag vet, att du all ting förmår; och ingen tanke är för dig fördold.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Det är en fåvitsk man, som menar fördölja sitt råd; derföre hafver jag ovisliga talat det mig för högt är, och det jag icke förstår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Så hör nu, låt mig tala; jag vill fråga dig, lär mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Jag hafver hört dig med öronen, och min ögon se dig ock nu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Derföre gifver jag mig skuld, och gör bot i stoft och asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Då nu Herren dessa orden med Job talat hade, sade Herren till Eliphas af Thema: Min vrede är förgrymmad öfver dig, och öfver dina två vänner; förty I hafven icke rätteliga talat om mig, såsom min tjenare Job.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Så tager nu sju stutar, och sju vädrar, och går bort till min tjenare Job, och offrer bränneoffer för eder, och låter min tjenare Job bedja för eder; förty honom vill jag anse, så att jag icke skall låta eder se, huru I hafven bedrifvit ena dårhet; förty I hafven icke rätt talat, såsom min tjenare Job.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Då gingo bort Eliphas af Thema, Bildad af Suah, och Sophar af Naema, och gjorde såsom Herren dem sagt hade; och Herren såg till Jobs person;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Och Herren vände Jobs fängelse, då han bad för sina vänner; och Herren gaf Job dubbelt så mycket, som han tillförene haft hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Och till honom kommo alle hans bröder, och alla hans systrar, och alle de honom tillförene kände, och åto med honom i hans hus, och vände sig till honom, och hugsvalade honom öfver allt det onda, som Herren hade låtit komma öfver honom; och hvardera gaf honom ett stycke penningar, och ett gyldene klenodium.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Och Herren välsignade Job mer än tillförene; så att han fick fjortontusend får, och sextusend camelar, och tusende par oxar, och tusende åsnar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Och fick sju söner och tre döttrar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Och kallade den första Jemima, den andra Kezia, och den tredje KerenHappuch.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Och vordo icke funna så dägeliga qvinnor i all land, såsom Jobs döttrar; och deras fader gaf dem arfvedel med deras bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Och Job lefde derefter hundrade och fyratio år, så att han fick se sin barn och barnabarn, allt intill fjerde led.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Och Job blef död, gammal och mätt af lefvande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Säll är den, som icke wandrar uti de ogudaktigas råd, och icke träder in uppå de syndares wäg; ej heller sitter der de bespottare sitta. [1]');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Utan hafwer lust til HERrans lag; och talar om hans lag både dag och natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Han är såsom et trä, planteradt wid wattubäcker, hwilket sina frukt bär i sinom tid, och dess löf förfallna intet; och hwad han gör, det lyckas wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Men de ogudaktige äro icke så; utan såsom agnar, som wädret bortförer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Derföre blifwa icke de ogudaktige i domenom; eller syndarena i de rättfärdigas församling. [2]');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Ty HERren känner de rättfärdigas wäg: men de ogudaktigas wäg förgås.');
