INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'En Psalm Davids, til at föresjunga på Gitthith.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'HERre, wår HERre; huru herligit är ditt namn i all land, der man tackar dig i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Utaf unga barns och spenabarns mun hafwer du ena magt uprättat, för dina owänners skull; at du skalt nederlägga owännen, och den hämndgiruga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Ty jag skal se himlarna, dins fingers werk; månan och stjernorna, som du beredt hawfer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Hwad är människan, at du tänker på henne? Eller människones son, at du låter dig wårda om honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Du skalt låta honom en liten tid af Gudi öwfergifwen warda; men med äro och härlighet skalt du kröna honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Du skalt göra honom til en Herra öfwer dina händers werk; all ting hafwer du under hans fötter lagt:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Får och fä alltsamman; wilddjuren också dertil:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Foglarna under himmelen, och fiskarna i hawfet; och hwad i hafwena går. HERre, wår HERre, huru härligit är ditt namn i all land.');
