INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'En Psalm Davids. HERren är min herde, mig skall intet fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Han föder mig på en grön äng, och förer mig til friskt watn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Han wederqwecker mina själ; han förer mig in på rätta wägen, för sitt Namns skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Och om jag än wandrade i enom mörkom dal, fruktade jag intet ondt; ty du äst när mig; din käpp och staf trösta mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du bereder til mig et bord emot mina fiendar; du smörjer mit hufwud med oljo, och inskänker fullt för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Godhet och barmhertighet skola följa mig i alla mina lifsdagar; och jag skall blifwa i HERrans hus ewinnerliga.');
