INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'En Psalm Davids, til at föresjunga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'HERre, uppå dig förtröstar jag; låt mig aldrig på skam komma: Fräls mig genom dina rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Böj tin öron til mig, hasteliga hjelp mig: War mig en stark klippa och en borg, at du hjelper mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Ty du äst min klippa och min borg; at du dock för ditt Namns skull mig leda och föra wille.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'At du wille draga mig utu nätet, som de för mig stält hafwa; ty du äst min starkhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Uti dina händer befaller jag min anda; du hafwer mig förlöst, HERre, du trofaste Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Jag hatar dem, som hålla uppå lösaktiga läro; men jag hoppas til HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Jag fröjdar mig, och är glad öfwer dina godhet; at du anser mitt elände, och känner mina själ i nödene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Och du öfwergifwer mig icke uti fiendans händer: Du sätter mina fötter uppå widt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'HERre, war mig nådelig; ty mig är ångest; mitt ansikte är förfallet för sorgs skull, dertil min själ och min buk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Ty mitt lefwande är förtärdt wordet af bedröfwelse, och mina år af suckande: Min kraft är, genom mina missgerning, förfallen, och min ben äro försmäktade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Det går mig så illa, at jag är en stor försmädelse worden minom grannom, och en styggelse minom kändom; de som mig se på gatone, de fly för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Jag är förgäten af hjertat, såsom en döder; jag är worden såsom et sönderslaget kärille.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ty månge försmäda mig illa, så at hwar man skyr wid mig; de rådslå med hwarannan om mig, och akta taga mig lifwet bort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Men jag, HERre, hoppas uppå dig, och säger: Du äst min Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Min tid står i dina händer: Hjelp mig utu mina fiendars hand, och ifrå dem som mig förfölja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Låt ditt ansikte lysa öfwer din tjenare: Hjelp mig genom dina godhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'HERre, låt mig icke til skam warda, ty jag åkallar dig: De ogudaktige warde til skam, och tystade i helwete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Tystne de falske munnar, som tala emot den rättfärdiga hårdeliga, högmodeliga och hånliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Huru stor är din godhet, den du dem, som dig frukta, bewarat hafwer; och bewisar dem, som trösta uppå dig, inför menniskors barn?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du förgömer dem hemliga när dig för hwars mans trug: Du förskyler dem i hyddone för de trätosama tungor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Lofwad ware HERren; at han mig en underlig godhet bewisat hafwer, i enom fastom stad. [1]');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ty jag sade i mine häpenhet: Jag är bortdrifwen ifrå dina ögon; likwäl hörde du mine böns röst, då jag til dig ropade. [2]');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Älsker HERran, alle hans helige: HERren bewarar de trogna, och wedergäller dem rikeliga, som högmod öfwa. Warer tröste och oförfärade, alle J, som HERran förbiden.');
