INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja. Lofwer, I HERrans tjenare, lofwer HERrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Lofwadt ware HERrans Namn, ifrå nu och i ewighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Ifrå solens upgång, allt intil nedergången, ware HERrans Namn lofwadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'HERren är hög öfwer alla Hedningar: Hans ära går så widt, som himmelen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Hwilken är såsom HERren wår Gud, den sig så högt satt hafwer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Och ser uppå det nedriga, i himmelen och på jordene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Den som den ringa uprättar utu stoftet, och uplyfter den fattiga utu träcken:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'At han skall sätta honom bredowid Förstar, wid hans folks Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Den der låter den ofruktsamma bo i huset, at hon en glad barnamoder warder. Halleluja.');
