INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lofwer HERRran, alle Hedningar; priser honom, all folk:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Ty hans nåd är wäldig öfwer oss, och HERrans sanning (warar) i ewighet. Halleluja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Tacker HERranom, ty han är mild, och hans godhet warar ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Nu säge Israel: Hans godhet warar ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Nu säge Aarons hus: Hans godhet warar ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Nu säge de som HERran frukta: Hans godhet warar ewinnerliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Uti ångest åkallade jag HERran; och HERren bönhörde mig, och tröste mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'HERren är med mig, derföre fruktar jag mig intet: Hwad kunna menniskor göra mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'HERren är med mig, til at hjelpa mig: Och jag will lust se på mina fiendar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Det är godt, at förtrösta på HERran, och icke förlåta sig på menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Det är godt, at förtrösta uppå HERran, och icke förlåta sig på Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle Hedningar belägga mig; men i HERrans Namn will jag förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'De kringhwärfwa mig på alla sidor; men i HERrans Namn will jag nederlägga dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'De omlägga mig såsom bi, de släcka såsom eld i törne; men i HERrans Namn will jag förgöra dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Man stöter mig, at jag falla skall; men HERren hjelper mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'HERren är min magt, och min psalm; och är min salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Man sjunger med glädje om seger uti de rättfärdigas hyddom: HERrans högra hand behåller segren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'HERrans högra hand är uphöjd: HERrans högra hand behåller segren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Jag skall icke dö, utan lefwa, och förkunna HERrans gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'HERren näpser mig wäl; men han gifwer mig icke dödenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Upplåter mig rättfärdighetenes portar, at jag må der ingå, och tacka HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Det är HERrans port, de rättfärdige skola der ingå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Jag tackar dig, at du näpste mig, och halp mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Den stenen, som byggningsmännerna förkastade, är til en hörnsten worden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Det är skedt af HERranom, och är et under för wår ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Detta är den dagen, den HERren gör; låt oss på honom fröjdas och glädjas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'O! HERre, hjelp; O! HERre, låt wäl gå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Lofwad ware den, som kommer i HERrans Namn; wi wälsigne eder, som af HERrans hus ären.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'HERren är Gud, den oss uplyser; pryder högtidena med löf, allt intill hornen på altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du äst min Gud, och jag tackar dig; min Gud, jag will prisa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Tacker HERranom, ty han är mild, och hans godhet warar ewinnerliga.');
