INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Salomos Höga Wisa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Han kysse mig med sins muns kyssande; ty din bröst äro ljufligare än win;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Att man må lukta din goda salvo; ditt Namn är en utgjuten salvo; derföre hafwa pigorna dig kär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Drag mig efter dig, så löpe wi; Konungen förde mig in uti sin kammar: Wi fröjde oss, och äre glade öfwer dig; wi tänke uppå din bröst mer än uppå win: De fromme älska dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Jag är swart, men ganska täck, J Jerusalems döttrar, såsom Kedars hyddor, såsom Salomos tapeter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ser icke derefter, att jag så swart är; ty solen hafwer bränt mig: Mins moders barn wredgas emot mig. Man hafwer satt mig till wingårdsvaktersko; men min wingård, den jag hade, bewarade jag icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Säg mig du, den min själ älskar, hwar du beter, hwar du hwilar om middagen; att jag icke skall gå hit och dit, till dina stallbröders hjordar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Känner du dig icke, du dägeligasta ibland qwinnor, så gack uppå fårens fotspår, och bet din kid wid herdahusen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Jag liknar dig, min kära wid mitt resigtyg, wid Pharaos wagnar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Dina kinder stå ljufliga i spann, och din hals i kedjo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Wi wilje göra dig gyldene spann med silfdoppor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Då Konungen wände sig hit, gaf min nardus sina lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Min wän är mig ett knippe af myrrham, det emellan min bröst hänger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Min wän är mig en drufwa Copher, uti de wingårdar i EnGedi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Si, min kära, du äst dägelig; dägelig äst du, din ögon äro såsom dufwoögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Si, min wän, du äst dägelig och ljuflig; wår säng grönskas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Wår hus bjelkar äro cederträ; wåre sparrar äro cypress.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jag är ett blomster i Saron, och en lilja i dalenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Såsom en ros ibland törne, så är min kära ibland döttrarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Såsom ett äpleträ ibland skogsträ, så är min wän ibland sönerna: Jag sitter under dens skugga, som jag begärar, och hans frukt är minom hals söt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Han hafwer mig in uti winkällaren, och kärleken är hans baner öfwer mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Han wederqwicker mig med blomster, och uppfriskar mig med äple; ty jag är krank af älskog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hans wenstra hand ligger under mitt hufwud, och hans högra hand omfamnar mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Jag beswär eder, Jerusalems döttrar, wid rår, eller wid hinder i markene, att J icke uppwäcken eller omaken mina käresto, tilldess henne själf lyster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Detta är mins wäns röst; si, han kommer, och springer på bergen, och springer på högarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Min wän är lik enom råbock, eller ungom hjort; Si, han står bak wår wägg, och ser genom fenstret, och gluggar genom gallret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Min wän swarar, och säger till mig: Statt upp, min kära, min dägeliga, och kom hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Ty si, wintren är förgången, regnet är öfwerståndet, och är sin wäg;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Blomstren äro utgångna på markene; wårtiden är kommen, och tuturdufwan låter sig höra i wårt land;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Fikonträt är knoppadt, winträn blomstras, och gifwa sina lukt: Statt upp, min kära, och kom, min dägeliga, kom hit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Min dufwa uti stenklyftor, uti bergsrefwor, låt mig se ditt ansigte, låt mig höra dina röst; ty din röst är söt, och ditt ansigte ljufligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Tager oss räfwar, de små räfwar, som förderwa wingårdar; ty wåra wingårdar blomstras.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Min wän är min, och jag är hans, den der beter ibland roser;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Intil dess att dagen swal warder, och skuggarne afwika: Wänd om, blif såsom en rå, min wän, eller såsom en ung hjort på skiljebergen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Jag sökte om nattena i mine säng, den min själ kär hade; jag sökte, men jag fann honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Jag will stå upp och gå omkring i staden, på gator och gränder, och söka den min själ kär hafwer: Jag sökte, men jag fann honom intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Mig funno wäktarena, som kringom i staden gå: Hafwen J icke sett den min själ kär hafwer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Då jag kom litet framom dem, så fann jag den min själ kär hafwer: Jag håller honom, och will icke öfwergiwa honom, tilldess jag hafwer honom in uti mine moders hus, uti mine moders kammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Jag beswär eder, J Jerusalems döttrar, wid rår och hinder på markene, att J icke uppwävcken mina käro, eller omaken henne, tilldess henne själf lyster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Ho är denna, som uppgår utur öknene, såsom en rök af myrrham, rökelse och allahanda apothekares pulver?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Si omkring Salomos säng stå sextio starke, utaf de starka i Jsrael;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Alle hålla de swärd, och äro behändige till strids; hwardera hafwer sitt swärd wid sina sido, för fruktans skull, om nattena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Konung Salomo lät göra sig ett sängerum af Libanons trä;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Dess stodar woro af silfwer, täckelsen af guld, sätet af purpur, bottnen deruti war lusteliga lagd för Jerusalems döttrars skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Går ut, J Zions döttrar, och skåder Konung Salomo, i den krono, der hans moder honom med krönt hafwer, på hans bröllopsdag, och på hans hjertas fröjds dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Si, min kära, du äst dägelig, si, dägelig äst du; din ögon äro såsom dufwoögon, emellan dina lockar: Ditt hår är såsom getahjordar, som klippte äro på det berget Gilead.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Dina tänder äro såsom hjordar med afklippta ull, som twagne komma utu wattnet, hwilke allesamman äro hafwande med twillingar, och ingen af dem är ofruktsam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Dina läppar äro såsom ett rosenfärgadt snöre, och ditt tal ljufligit; dine kinder såsom skörden på granatäplet, emellan dina lockar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Din hals är såsom Davids torn, gjord med bröstwärn, der tusende sköldar uppå hänga, och allahanda de starkas wapen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Din tu bröst äro såsom twå unga råtwillingar, hwilke ibland roser i bet gå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Till dess dagen swal warder, och skuggorna afwika: Jag will gå till myrrhamsberget, och rökelsehögen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Du äst med allone dägelig, min kära, och ingen fläck är på dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Kom, min brud, ifrå Libanon, kom ifrå Libanon: Gack in, träd hit ifrån Amana kulle, ifrå Senir och Hermons kulle, ifrå lejonens boning, ifrå de leoparders berg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hafwer tagit mig hjertat bort, min syster, kära brud, med ett ditt öga, och med ene dine halskedjo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Huru dägelig äro din bröst, min syster, kära brud: Din bröst äro lustigare än win, och din salvos lukt öfwergår alla örter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Dine läppar, min brud, äro såsom drypande hannogskaka: Hannog och mjölk är under dine tungo, och din kläders lukt är såsom lukt af Libanon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Min syster, kära brud, du äst en tillsluten örtagård; en tillsluten källa, en förseglad brunn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Din frukt är såsom en lustgård af granatäple med ädla frukter, cyper med nardus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardus med saffran, calmus och canel, med allahanda Libanons trä; myrrham och aloes med alla bästa örter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Såsom en örtegårds brunn, såsom en brunn af lefwande watten, det af Libanon flyter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Statt upp, nordanwäder, och kom, sunnanwäder, och blås igenom min örtegård, att hans örter måga drypa. Min wän komme uti sin örtegård, och äte sina ädla frukter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Jag kom, min syster, kära brud, uti min örtegård; jag hafwer mitt myrrham, samt med mina örter, uppskurit; jag hafwer ätit mina hannogskako, samt med minom hannog; jag hafwer druckit mitt win med mine mjölk: Äter, mine käre, och dricker, mine wänner, och warder druckne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Jag sofwer, och mitt hjerta wakar; der är mins wäns röst, som klappar: Låt mig upp, min kära, min syster, min dufwa, min fromma; ty mitt hufwud är fullt med dagg, och mina lockar fulle med nattenes droppar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Jag hafwer afklädt min kjortel, huru skulle jag åter kläda honom uppå igen? Jag hafwer twagit mina fötter, huru skulle jag besmitta dem igen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Men min wän stack sina hand in genom ett hål, och mitt lif darrade derwid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Då stod jag upp, att jag skulle låta minom wän upp: Mina händer drupo af myrrham, och myrrham lopp öfwer mina finger på stängelen åt låset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Och då jag minom wän upplåtit hade, war han borto, och sin wäg gången. Då gick min själ ut efter hans ord: Jag sökte honom, men jag fann honom intet; jag ropade, men han swarade mig intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Wäktarena, som omkringgå i stadenom, funno mig, de slogo mig till sårs; wäktarena på murenom togo mig bort mitt hufwudkläde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Jag beswär eder, Jerusalems döttrar; finnen J min wän, så säger honom, att jag för älskog krank ligger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Hwad är din wän för andra wänner, o du aldradägeligasta ibland qwinnor? Hwad är din wän för andra wänner, att du så hafwer besworit oss?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Min wän är hwit och röd, utkorad ibland mång tusend.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hans hufwud är det bästa guld; hans hår är krusadt, swart såsom en korp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Hans ögon äro såsom dufwoögon wid wattubäcker, twagne med mjölk, och stå full.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Hans kinder äro såsom apothekares wäxande örtesängar; hans läppar äro såsom roser, de der drypa af flytande myrrham.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Hans händer äro såsom guldringar, fulle med turkoser; hans lif är såsom rent elphenben, besatt med saphirer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hans ben äro såsom marmors pelare, grundade uppå gyldene fötter; hans skapnad är såsom Libanon, utkorad såsom cederträ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hans hals är söt och ganska lustig: En sådana är min wän; min wän är sådana, J Jerusalems döttrar. Hwart är då din wän gången, o du dägeligasta ibland qwinnor? Hwart hafwer din wän wändt sig, så wilje wi honom söka med dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Min wän är nedergången uti sin örtagård, till örtasängarna, att han sig der förlusta skall i örtagårdarna, och hemta roser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Min wän är min, och jag är hans, den sig ibland roser förlustar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Du äst dägelig, min kära, såsom Thirza; lustig såsom Jerusalem, förskräckelig såsom en härordan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Wänd din ögon ifrå mig; förty de göra mig brinnande: Ditt hår är såsom en getahjord, de som på berget Gilead klippte äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Dina tänder äro såsom en fårahjord, de der twagne komma utu watten, hwilke allesammans äro med twillingar hafwande, och ingen ibland dem är ofruktsam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Dine kinder äro såsom skörden på granatäplet, emellan dina lockar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Sextio äro Drottningarna, och åttatio frillorna, och på jungfrurna är intet tal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Men en är min dufwa, min fromma; en är sine moder kärast, och sine moders utkorada: Då döttrarna sågo henne, prisade de henne saliga; Drottningarna och frillorna lofwade henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Ho är denna, som uppgår såsom en morgonrodne, dägelig såsom månen, utkorad, såsom solen, förskräckelig såsom en härordan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Jag är nedergången i nöttagården, till att skåda telningarna wid bäcken; till att skåda, om winträt blomstrades, om granatäplen grönskades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Min själ wisste icke, att han mig intill AmmiNadibs wagnar satt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Wänd om, wänd om, o Sulamith; wänd om, wänd om, att wi måge skåda dig; hwad sen J på Sulamith annat, än dans i Mahanaim?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Huru dägelig är din gång i skorna, du Förstas dotter! Dina länder stå lika wid hwarandra, såsom tu spann, de ens mästares hand gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Din nafle är såsom en rund skål, den aldrig dryck fattas; din buk är såsom en hwetehop, omsatt med roser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Din tu bröst äro såsom twå unge råtwillingar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Din hals är såsom ett elphenbenstorn, din ögon äro såsom de dammar i Hesbon wid den porten Bathrabbim; din näsa är såsom tornet af Libanon, hwilket sig wänder emot Damascon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Ditt hufwud står på dig såsom Carmel; håret på ditt hufwud är såsom Konungens purpur i fållar bunden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Huru dägelig och huru ljuflig äst du, kära, i wällust!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Din längd är lik wid ett palmträ; och din bröst wid windrufwor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Jag sade: Jag måste stiga upp i palmträt, och fatta dess qwistar: Låt din bröst wara såsom drufwor på winträ, och lukten af dine näso såsom äple;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Och din hals såsom godt win, det minom wän lätteliga infår; och tala om gammal ärende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Min wän är min, och han hålleer sig ock till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Kom min wän, låt oss gå ut på markena, och wistas i landsbyarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Att wi måge bittida uppstå till wingårdarna, och få se, om winträt blomstras, och hafwer fått knoppar; om de granatäple utgångna äro: Der will jag gifwa dig min bröst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Liljorna gifwa sin lukt, och för wåra dörr allahanda ädla frukter; min wän, jag hafwer bewarat åt dig både nytt och gammalt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O! att jag måtte finna dig ute, min broder, du, som mins moders bröst suger, och måtte få kyssa dig; att ock ingen föraktade mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Jag wille taga dig, och hafwa dig uti mine moders hus, der du mig lära skulle; der wille jag skänka dig kryddadt win, och must af min granatäple.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hans wenstra hand ligger under mitt hufwud, och hans högra hand omfamnar mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Jag beswär eder, Jerusalems döttrar, att J icke uppwäcken mina käro, eller omaken henne, tilldess henne sjelf lyster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Ho är denna, som uppkommer ifrån öknene, och stöder sig in uppå sin wän? Under äpleträt wäcker jag dig, der din moder dig födt hafwer; der hon, som dig födde, med dig legat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Sätt mig såsom ett insegel på ditt hjerta, och såsom ett insegel uppå din arm; ty kärleken är stark såsom döden, och nitälskan är fast såsom helwetet: Dess glöd är brinnande, och en HERrans låge;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Så att ock mycket watten icke förmå utsläcka kärleken, eller strömmar fördränka honom: Om en wille gifwa alla ägodelar i sino huse för kärleken, så gulle det alltsammans intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Wår syster är liten, och hafwer ingen bröst; hwad skole wi göra till wår syster, när man nu skall tala henne till?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Är hon en mur, så wilje wi göra silfwerbålwerk deruppå; är hon en dörr, så wilje wi befästa henne med cederbräde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Jag är en mur, och min bröst äro såsom torn, deraf är jag worden för hans ögon såsom den der frid finner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomo hafwer en wingård i BaalHamon, den wingården fick han waktarom, att hwardera skulle gifwa, för hans frukt, tusende silfpenningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Min wingård är för mig: Dig Salomo bör tusende; men waktaromen öfwer hans frukter, tuhundrad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Du, som bor i örtagårdarna, sällskapen akta deruppå; låt mig höra dina röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fly, min wän, och war lik ene rå, eller enom ungom hjort, in på örtabergen. Ände på Salomos Höga Wisa.');
