INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Uti tredje årena af Jojakims, Juda Konungs, rike kom NebucadNezar, Konungen i Babel, in för Jerusalem, och belade det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Och HERren gaf Jojakim, Juda Konung, honom i händer, och en hop af kärille utu Guds hus; hwilken han lät föra in uti Sinear land, i sins guds hus, och lade de kärillen uti sins guds fatabur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Och Konungen sade til Aspenas, sin öfwersta kamererare, at han skulle utsöka honom af Israels barnom, af Konungsliga slägt, och herra barnom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Några unga drängar, som ingen wank hade; utan dägelige woro, förnuftige, wise, kloke och förståndige; hwilke skickelige woro til at tjena i Konungens gård, och til at lära Chaldeiska skrift och mål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Dessom bestälte Konungen, hwad man dem dageliga gifwa skulle af hans spis, och af det win, der han sjelf af drack; på det at då de så i tre år upfödde woro, skulle de sedan tjena inför Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Så woro ibland dem Daniel, Hanania, Misael och Asaria, af Juda barnom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Och den öfwerste kamereraren gaf dem namn; och nämnde Daniel Beltesazar, och Hanania Sadrach, och Misael Mesach, och Asaria AbedNego.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Men Daniel satte sig före i sitt hjerta, at han icke wille orena sig med Konungens spis, och med det win, som han sjelf drack; och bad öfwersta kamereraren, at han icke skulle orena sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Och Gud gaf Daniel, att öfwerste kamereraren warde honom gunstig och god.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Och han sade til honom: Jag fruktar för min Herra Konungen, den eder spis och dryck bestyrt hafwer: Om han får se, at edor ansikte äro magrare än de andra drängars, som eder jämnåldrige äro, så gören I mig brotsligan til döden, inför Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Då sade Daniel til Melzar, hwilkom öfwerste kamereraren Daniel, Hanania, Misael och Asaria, befallt hade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Försök dock der med dina tjenare i tio dagar, och låt gifwa oss mos til at äta, och watn til at dricka:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Och låt alltså komma för dig wår och de andra drängars ansikte, som af Konungens spis äta; och efter som du då ser, derefter gör med dina tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Och han hörde dem derutinnan, och försökte det med dem i tio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Och efter de tio dagar woro de dägeligare och bättre wid hull, än alle de drängar, som spisades af Konungens spis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Så satte Melzar bort deras spis och dryck, den dem tilskickad war, och gaf dem mos.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Men dessa fyras Gud gaf dem konst och förstånd uti allahanda skrift och wishet; men Daniel gaf han förstånd i alla syner och drömar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Då tiden förlupen war, som Konungen förelagt hade, at de skulle hafwas inför honom, hade öfwerste kamereraren dem in för NebucadNezar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Och Konungen talade med dem: Och wardt ingen ibland dem alla funnen, som Daniels, Hanania, Misaels och Asaria, like war; och de wordo Konungens tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Och Konungen fann dem i alla saker, de han dem frågade, tio sinom klokare och förståndigare, än alla stjernokikare och wisa i hela sino rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Och lefde Daniel intil Konung Cores första år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Uti andro årena af NebucadNezars rike såg NebucadNezar en dröm, af hwilkom han wardt förskräckt, så at han waknade up.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Då lät han tilhopa komma alla stjernokikare och wisa, och trollkarlar, och Chaldeer, at de skulle säga Konungenom sin dröm. De kommo, och trädde fram för Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Och Konungen sade til dem: Jag hafwer haft en dröm, som mig förskräckt hafwer, och jag will gerna weta, hwad det för en dröm warit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Då sade de Chaldeer til Konungen, på Syriskt mål: Herre Konung, Gud låte dig länge lefwa; säg dinom tjenarom drömen, så wilje wi uttyda honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Konungen swarade, och sade til de Chaldeer: Det är fallet mig utu minnet; om I icke låten mig få weta drömen, och uttyden honom, så skolen I platt förgöras, och edor hus skämliga förstörd warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Om I ock låten mig få drömen weta, och uttyden honom, så skolen I få skänker, gåfwor och stora äro, af mig; derföre säger mig nu drömen, och hans uttydning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'De swarade åter, och sade: Konungen säge sinom tjenarom drömen, så wilje wi uttyda honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Konungen swarade, och sade: Sannerliga, jag förmärker, at I fördröjen tiden, efter I sen dock, att det är fallet mig utu minnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Men om I icke sägen mig drömen, så skall rätten gå öfwer eder, lika som öfwer de der taga sig före at tala lögn och drafwel för mig, så länge tiden skall förlöpa; derföre säger mig nu drömen, så kan jag märka, at I ock wäl finnen uppå uttydningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Då swarade de Chaldeer för Konungenom, och sade til honom: Ingen menniska är på jordene, den, det Konungen begärar, säga kan, och är ej heller någon Konung, ehuru stor eller mägtig han är, som sådant af någrom stjernokikare, wisom eller Chaldee, eskar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Ty det Konungen uppå eskar, är för högt, och är ej heller någon, som detta för Konungenom säga kan, undantagna gudarna, hwilke icke bo när menniskomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Då wardt Konungen ganska wred, och böd förgöra alla de wisa i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Och domen gick ut, at man skulle dräpa de wisa: Wardt också Daniel med sina stallbröder sökt, at man dem dräpa skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Då förnam Daniel sådana dom och befallning, af Arioch, Konungens öfwersta domare, hwilken utfor til at döda de wisa i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Och han hof up, och sade til Konungens befallningsman Arioch: Hwarföre är denne stränge domen utgången ifrå Konungenom? Och Arioch lät Daniel det förstå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Så gick Daniel up, och bad Konungen, at han skulle gifwa honom tid til, at han måtte säga Konungenom uttydningena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Sedan gick Daniel hem, och gaf det sina stallbröder, Hanania, Misael och Asarie, tilkänna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'At de skulle bedja Gud af himmelen om nåd til denna hemlighet; at Daniel och hans medbröder, samt med de andra wisa i Babel, icke förgöras skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Då wardt denna hemlig ting Daniel genom ena syn om nattene uppenbarad; för hwilket Daniel lofwade Gud af himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Och Daniel tog til at tala, och säga: Lofwadt ware Guds Namn, ifrån ewighet til ewighet; ty hans är både wishet och starkhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Han förwandlar tider och stunder: Han sätter Konungar af, och sätter Konungar up: Han gifwer de wisa deras wishet, och de förståndiga deras förstånd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Han uppenbarar det djupt och hemligit är: Han wet hwad i mörkrena ligger; ty när honom är alltsammans ljus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Jag tackar och lofwar dig, mina fäders Gud, at du hafwer förlänt mig wishet och starkhet, och hafwer nu det uppenbarat, der wi dig om bedit hafwe; det är, Konungens ärende hafwer du oss uppenbarat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Så gick Daniel up til Arioch, den af Konungenom befallning hade til at dräpa de wisa i Babel, och sade til honom alltså: Du skalt icke förgöra de wisa i Babel; utan haf mig up til Konungen, jag will säga Konungenom uttydelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Arioch hade Daniel med hast up för Konungen, och sade til honom alltså: En är funnen ibland Juda fångar, som Konungenom uttydningen säga kan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Konungen swarade, och sade til Daniel, den de Beltesazar kallade: Äst du den samme, som mig kan säga den dröm, som jag hafwer, och hans uttydning?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel swarade inför Konungenom, och sade: Den hemlighet, som Konungen eskar af de wisa, lärda, stjernokikare och spåmän, står icke i deras magt att säga Konungenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Utan Gud af himmelen, han kan uppenbara hemlig ting; han hafwer tett Konungenom NebucadNezar, hwad i tilkommande tider ske skall; din dröm och din syn, då du sof, war denna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Du Konung tänker i dine säng, huru det måtte tilgå i framtiden: Och den som hemlig ting uppenbarar, han tedde dig, huru det gå skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Så är mig denna hemlighet uppenbarad, icke igenom mina wishet, lika som hon större wore än allas de som lefwa; utan derföre, at uttydningen måtte Konungenom underwist warda, och du dins hjertas tankar weta få.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du Konung sågst, och si, et ganska stort och högt beläte stod för dig, det war grufweligit uppå se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Dess belätes hufwud war af klart guld, dess bröst och armar woro af silfwer, buken och länderna woro af koppar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Dess ben woro af jern, dess fötter woro somt af jern, och somt af ler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Sådant sågst du, til dess en sten nederrifwen wardt utan händer, han slog belätet uppå dess fötter, som af jern och ler woro, och förkrossade dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Då wordo all tilhopa förkrossad, jernet, leret, kopparen, silfret och guldet, och wordo såsom agnar på enom sommarloga, och wädret bortförde det, så at man kunde intet mer finna det; men stenen, som slog belätet, wardt til ett stort berg, så at det upfyllde hela werldena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Detta är drömen: Nu wilje wi säga uttydningen för Konungenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du Konung äst en Konung öfwer alla Konungar, den Gud af himmelen rike, magt, starkhet och äro, gifwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Och allt det, der menniskor bo, och djuren på markene, och foglarna under himmelen, hafwer han gifwit i dina händer, och förlänt dig magt öfwer detta allt: Du äst det gyldene hufwudet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Efter dig skall et annat Konungarike upkomma, sämre än ditt; derefter det tredje Konungarike, som af koppar är, hwilket öfwer all land regera skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Det fjerde skall wara hårdt såsom jern; ty lika wisst som jern sönderskär och sönderkrossar all ting; ja, lika som jern sönderslår all ting, så skall ock detta sönderkrossa och sönderslå alltsamman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Men at du sågst fötterna och tånar, somt af ler, och somt af jern, det skall wara et söndradt Konungarike; dock skall af jerns planto blifwa deruti, såsom du sågst jern beblandadt med ler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Och at tånar på dess fötter, somt af jern, och somt af ler woro, det skall wara endels et starkt, och endels et swagt rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Och at du sågst jern beblandadt med ler, skola de wäl beblanda sig efter menniskos blod tilsammans; men de skola likwäl intet hänga tilhopa, lika som jern icke kan bemängas med ler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Men uti dessa Konungarikes tid skall Gud af himmelen uprätta et Konungarike, det aldrig skall förlagdt warda; och hans rike skall icke komma til något annat folk; det skall förkrossa och förstöra all dessa riken; men det skall blifwa i ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Såsom du sågst en sten nederrifwen af et berg utan händer, hwilken sönderslog jernet, kopparen, leret, silfret och guldet; alltså hafwer nu den store Gud tett Konungenom, hwad som framdeles ske skall: Och detta är wisserliga drömen, och uttydningen är rätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Då föll Konungen NebucadNezar uppå sitt ansikte, och tilbad inför Daniel; och befallte, at man skulle göra honom spisoffer och rökoffer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Och Konungen swarade Daniel, och sade: Det är intet twifwel, edar Gud är en Gud öfwer alla gudar, och en Herre öfwer alla Konungar, den hemlig ting uppenbara kan; efter du dessa hemlig ting hafwer kunnat uppenbara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Och Konungen uphöjde Daniel, och gaf honom stora myckna skänker; och gjorde honom til en Första öfwer hela landet Babel, och satte honom til en Öfwersta öfwer alla de wisa i Babel. Och Konungen uphöjde Daniel, och gaf honom stora myckna skänker; och gjorde honom til en Första öfwer hela landet Babel, och satte honom til en Öfwersta öfwer alla de wisa i Babel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Och Daniel bad Konungen, at han måtte sätta Sadrach, Mesach och AbedNego, öfwer de landskap i Babel; men Daniel sjelf blef när Konungenom i hans gård. Och Daniel bad Konungen, at han måtte sätta Sadrach, Mesach och AbedNego, öfwer de landskap i Babel; men Daniel sjelf blef när Konungenom i hans gård.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Konung NebucadNezar lät göra et gyldene beläte, sextio alnar högt, och sex alnar bredt; och lät sätta det i Babels land på en skön plan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Och Konung NebucadNezar sände efter Förstar, herrar, landshöfdingar, domare, fogdar, rådherrar, ämbetsmän, och alla wäldiga i landet, at de skulle komma tilsammans, och wiga det belätet, som Konungen NebucadNezar hade upsätta låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Då kommo Förstarne, herrarne, landshöfdingarne, domarena, fogdarne, rådherrarne, ämbetsmännerne, och alle wäldige i landet tilsamman, til at wiga belätet, som Konung NebucadNezar hade upsätta låtit, och de måste gå fram för belätet, som NebucadNezar hade upsätta låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Och härolden ropade öfwerljudt: Det låter eder sagdt wara, I all folk, slägter och tungomål:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'At när I hören basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, så skolen I nederfalla, och tilbedja det gyldene belätet, som Konung NebucadNezar hafwer upsätta låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Men den som då icke nederfaller och tilbeder, han skall på samma stund kastas uti en brinnande ugn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Då de nu hörde ljudet af basuner, trummeter, gigor, psaltare och allahanda strängaspel, föllo neder all folk, slägter och tungomål, och tilbådo det gyldene belätet, som Konungen NebucadNezar hade upsätta låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Strax på samma stund gingo någre Chaldeiske män fram, och anklagade Judarna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Begynte, och sade til Konungen NebucadNezar: Herre Konung, Gud unne dig länge lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du hafwer, o Konung, låtit utgå et bud, at alla menniskor, då de hörde ljudet af basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, skulle de nederfalla, och tilbedja det gyldene belätet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Och den som icke nederfölle och tilbåde, han skulle kastas uti en brinnande ugn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nu äro här någre Judiske män, hwilka du öfwer de ämbete i Babels land satt hafwer, Sadrach, Mesach och AbedNego, de samme förakta ditt bud, o Konung, och wörda icke dina gudar, och tilbedja icke det gyldene belätet, som du hafwer upsätta låtit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Då befallte NebucadNezar, med grymhet och wrede, at man skulle hafwa fram för honom Sadrach, Mesach och AbedNego och männerne wordo framhafde för Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Då talade NebucadNezar til dem, och sade: Huru är det? Wiljen I, Sadrach, Mesach och AbedNego, icke wörda min gud, och icke tilbedja det gyldene belätet, som jag hafwer upsätta låtit?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nu wäl, reder eder til, så snart I hören ljudet af basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, så faller neder, och tilbeder belätet, som jag hafwer upsätta låtit: Om I icke tilbedjen det, så skolen I på samma stund warda kastade uti en brinnande ugn: Låt se, hwilken den Guden är, som eder utu mina händer tager.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Då swarade Sadrach, Mesach och AbedNego, och sade til Konung NebucadNezar: Det är icke af nödene, at wi sware dig deruppå:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Si, wår Gud, den wi dyrke, kan wäl hjelpa oss utu den brinnande ugnen, och frälsa oss utu dine hand, o Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Och om han än icke det göra will, så skalt du ändå weta, o Konung, at wi dina gudar intet wörde, ej heller det gyldene beläte, som du hafwer upsätta låtit, tilbedja wiljom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Då wardt NebucadNezar full med grymhet, så att hans ansikte förwandlade sig öfwer Sadrach, Mesach och AbedNego; och befallte, at man skulle göra ugnen sju resor hetare, än han eljest plägade wara:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Och böd de bästa krigsmän, som uti hans här woro, at de skulle binda Sadrach, Mesach och AbedNego, och kasta dem uti den brinnande ugnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Alltså wordo desse männerne, uti deras mantlar, skor, hattar och annor kläder, bundne, och kastade uti den brinnande ugnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Ty Konungens befallning måste man med hast fullgöra: Och elden wardt så stark i ugnen, at de män, som Sadrach, Mesach och AbedNego, upbränna skulle, blefwo döde af eldslåganom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Men de tre männerne, Sadrach, Mesach och AbedNego, föllo neder uti den brinnande ugnen, så bundne som de woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Då förskräckte sig Konung NebucadNezar, och gick hastigt up, och sade til sitt Råd: Hafwe wi icke låtit kasta tre män i elden bundna? De swarade, och sade til Konungen: Ja, Herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Han swarade, och sade: Ser jag dock fyra män lösa gå i eldenom, och dem skadar intet; och den fjerde är lika som han wore en Guds son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Och NebucadNezar gick fram för gapet på den brinnande ugnen, och sade: Sadrach, Mesach och AbedNego, högsta Guds tjenare, går här ut, och kommer hit. Så gingo Sadrach, Mesach och AbedNego, utur eldenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Och Förstarne, herrarne, fogdarne, och Konungens Råd kommo tilsamman, och sågo uppå, huru elden ingen magt uppå dessa männernas kroppar bewisat hade; och deras hufwudhår icke ens afswedt war, och deras kläder intet skadd; ja, man kunde icke känna någon eldslukt uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Då hof NebucadNezar sin röst up, och sade: Lofwad ware Sadrachs, Mesachs och AbedNegos Gud, den sin ängel utsändt hafwer, och halp sina tjenare, som uppå honom trodde, och icke gjorde efter Konungens bud, utan utgåfwo deras lekamen, at de ingen gud ära eller tilbedja wille, utan allena sin Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Så är nu detta mitt bud: At ho som hälst ibland all folk, slägter och tungomål, försmäder Sadrachs, Mesachs och AbedNegos Gud, han skall förgöras, och hans hus skamliga förstördt warda. Ty det är ingen annan gud, som så hjelpa kan, som denne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Och Konungen gaf Sadrach, Mesach och AbedNego, stort wälde i Babels land. Konung NebucadNezar, allom landom, folkom och tungomålom: Gud gifwe eder mycken frid! Mig synes godt wara, at jag förkunnar de tekn och under, som Gud den högste med mig gjort hafwer; Ty hans tekn äro stor, och hans under äro mägtig, och hans rike är et ewigt rike, och hans wälde warar ifrå slägte til slägte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Jag NebucadNezar, då jag god ro hade i mitt hus, och allt wäl tilstod i mitt palats;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Såg en dröm, och wardt förskräckt; och de tankar, som jag i mine säng hade, öfwer synena, som jag sett hade, bedröfwade mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Och jag befallte, at alle de wise i Babel skulle komma up för mig, at de måtte säga mig, hwad drömen betydde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Då hade man fram de stjernokikare, wisa, Chaldeer och spåmän, och jag förtälde drömen för dem; men de kunde intet säga mig, hwad han betydde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Intil dess Daniel, på det sista, kom för mig, hwilken Beltesazar kallas, efter mins guds namn, den de helga gudars anda hafwer; och jag förtälde för honom drömen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Beltesazar, du öfwerste ibland de stjernokikare, jag wet, at du hafwer de helga andars anda, och dig är intet fördoldt; säg mig mins dröms syn, den jag sett hafwer, och hwad han betyder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Så är detta synen, som jag såg i mine säng: si, et trä stod midt i landet; det war ganska högt,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Stort och tjockt; dess högd räckte up i himmelen, och utwidgade sig allt intil landsens ända;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Dess qwistar woro dägelige, och båro mycken frukt, der alle af äta kunde; all djur i markene funno skugga under thy, och foglarna under himmelen satte sig på dess qwistar, och allt kött hade sin födo deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Och jag såg en syn i mine säng, och si, en helig wäktare kom neder af himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Han ropade öfwerljudt, och sade alltså: Hugger trät omkull, och hugger bort qwistarna, och rifwer bort löfwet, och förströr dess frukt, så at djuren, som derunder ligga, löpa sin wäg, och foglarna flyga bort af dess qwistar:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Dock, låter stubban blifwa i jordene med rötterna; men han skall gå in i jern- och kopparkädjor i gräset på markene, han skall ligga under himmelens dagg, och warda wåt, och skall föda sig ibland djuren af gräset på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Och det menniskliga hjertat skall warda ifrå honom taget, och et wilddjurs hjerta gifwas honom igen, til dess at sju tider framgångne äro öfwer honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Detta är beslutit i wäktarenas råd, och i de heligas tal rådslagit; på det de som lefwa, måga känna, at den Högste hafwer magt öfwer menniskors rike, och gifwer dem hwem han will, och uphöjer de förnedrada dertil.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Sådana dröm hafwer jag, Konung NebucadNezar, sett; men du Beltesazar, säg hwad han betyder; ty alle de wise, som i mitt rike äro, kunna icke säga mig hwad han betyder; men du kant det wäl; ty de helga gudars ande är i dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Då wardt Daniel, den ock Beltesazar het, häpen deröfwer, wid en tima långt, och hans tankar bedröfwade honom; men Konungen sade: Beltesazar, låt icke drömen och hans uttydning bedröfwa dig. Då hof Beltesazar up, och sade: Ack! min Herre, at denne drömen gulle dina fiendar uppå, och hans uttydning dina owänner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Trät, som du sågst, at det war stort och tjockt, och dess högd räckte up til himmelen, och utwidgade sig öfwer hela landet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Och dess qwistar dägelige, och dess frukt mycken war, der alle sina födo af hade, och djuren på markene bodde derunder, och himmelens foglar på dess qwistar såto;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Det äst du, Konung, som så stor och mägtig äst; ty din magt är stor, och räcker up til himmelen, och ditt wälde sträcker sig intil werldenes ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Men det, at Konungen såg en helig wäktare komma neder af himmelen, och säga: Hugger trät omkull, och förgörer det; dock låter stubban med sina rötter blifwa i jordene; men han skall gå i jern- och kopparkädjor i gräset på markene, och ligga under himmelens dagg, och warda wåter, och föda sig ibland djuren på markene, til dess sju tider öfwer honom framlidne äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Detta är uttydningen, Herre Konung, och sådana dens Högstas råd går öfwer min Herra Konungen:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Man skall drifwa dig bort ifrå folk, och du måste blifwa med wilddjur på markene, och man skall dig låta äta gräs såsom oxar, och skalt ligga under himmelens dagg, och warda wåter, til dess sju tider öfwer dig framlidne äro; på det du skalt besinna, at den Högse hafwer wåld öfwer menniskors rike, och gifwer dem hwem han will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Men det som sagdt är, at man ändå skall låta blifwa stubban af trät med sina rötter qwar: Ditt rike skall blifwa dig, då du känt hafwer magten i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Derföre, Herre Konung, låt mitt råd täckas dig, och går dig lös ifrå dina synder, genom rättfärdighet, och ledig ifrå dina missgerningar, genom wälgerningar emot de fattiga; så hafwer han tålamod med dina synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Allt detta wederfors Konung NebucadNezar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Ty efter tolf månader, då Konungen gick på Konungsborgene i Babel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Hof han up, och sade: Detta är den store Babel, som jag upbygt hafwer til et Konungs hus, genom mina stora magt, mine härlighet til äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Förr än Konungen dessa orden uttalat hade, kom en röst af himmelen: Dig, Konung NebucadNezar, ware sagdt: Ditt rike skall dig aftaget warda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Och man skall drifwa dig bort ifrå ditt folk, och du skalt blifwa med wilddjur, som på markene gå; gräs skall man dig äta låta såsom oxar, til dess sju tider öfwer dig framlidne äro; på det du skalt förnimma, at den Högse hafwer wåld öfwer menniskors rike, och gifwer dem hwem han will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'I samma stund wardt ordet fullkomnadt öfwer NebucadNezar, så at han wardt bortdrifwen ifrå folk, och han åt gräs såsom oxar, och hans lekamen låg under himmelens dagg, och wardt wåter, til dess hans hår wäxte såsom örnafjädrar, och hans naglar wordo såsom foglaklor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Efter den tiden hof jag, NebucadNezar, up min ögon til himmelen, och kom åter til sinne igen, och lofwade den Högsta; jag prisade och ärade honom, som lefwer ewinnerliga, hwilkens wälde är ewigt, och hans rike warar slägte ifrå slägte. Emot hwilkom alle de, som på jordene bo, för intet räknas; Han gör allt såsom han will, både med krafterna i himmelen, och med dem som bo på jordene; och ingen kan stå hans hand emot, eller säga til honom: Hwad gör du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'På samma tid kom jag til sinne igen, och til mina Konungsliga äro, til mina härlighet, och til min skapnad, och mitt Råd och wäldige sökte mig; och när jag wardt åter fast uti mitt rike igen, och fick ännu större härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Derföre lofwar jag, NebucadNezar, och ärar och prisar Konungen i himmelen; ty alla hans gerningar äro sanning, och hans wägar äro rätte, och den som stolt är, kan han ödmjuka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Konung Belsazar gjorde et härligit gästabod til sina wäldiga och höfwitsmän, och drack sig drucken med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Och då han drucken war, böd han bära fram de gyldene och silfwer kärille, som hans fader, NebucadNezar, utu templet i Jerusalem borttagit hade, at Konungen, med sina wäldiga, med sina hustrur, och med sina frillor, skulle dricka deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Alltså wordo framburne de gyldene kärille, som utu templet, utu Guds huse, i Jerusalem tagne woro; och Konungen, hans wäldige, hans hustrur och frillor, drucko deraf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Och då de så drucko, lofwade de de gyldene, silfwer-, koppar-, jern-, trä och stengudar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'På samma stund syntes finger, såsom ene menniskos hand, de skrefwo twärs öfwer ifrå ljusa stakan, på den hwitmenade wäggene i Konungssalenom; och Konungen wardt warse handena som skref.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Då förwandlades Konungens ansikte, och hans tankar förskräckte honom, så at hans länder bäfwade, och hans ben darrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Och Konungen ropade öfwerljudt, at man skulle låta komma wisa, Chaldeer och spåmän, och lät säga til de wisa i Babel: Den menniska, som denna skriftena läs, och kan säga hwad hon betyder, han skall warda klädd i purpur, och bära en gyldene kädjo om halsen, och warea den tredje herren i mitt rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Så wordo alle Konungens wise uphafde; men de kunde hwarken läsa skriftena, eller underwisa Konungenom uttydningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Deraf förfärades Konungen Belsazar ännu fastare, och tappade platt sin hy; och hans wäldige wordo illa tilfrids.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Då gick Drottningen, för sådana Konungens och hans wäldigas ärendes skull, up i salen, och sade: Herre Konung, Gud unne dig länge lefwa; låt dina tankar icke så förskräcka dig, och omskift icke så din hy.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Det är en man i ditt rike, som hafwer de helga gudars anda; ty uti dins faders tid wardt i honom funnen uplysning, klokhet och wishet, sådana, som de gudars wishet är; och din fader, Konung NebucadNezar, satte honom öfwer de stjernokikare, wisa, Chaldeer och spåmän;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Derföre, at en hög ande wardt funnen i honom; dertil förstånd och klokhet til at uttyda drömar, råda uppå mörkt tal, och uppenbara hemlig ting, nämliga, Daniel, den Konungen lät Beltesazar kalla: Så låt nu kalla Daniel, han warder wäl sägandes uttydningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Då hade man Daniel up för Konungen, och Konungen sade til Daniel: Äst du Daniel, en af de fångar utaf Juda, hwilka Konungen, min fader, utu Juda fört hafwer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Jag hafwer hört sägas om dig, at du hafwer de helga gudars anda, och at uplysning, förstånd och hög wishet, i dig funnen är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nu hafwer jag låtit komma för mig kloka och wisa, at de skola läsa mig denna skriftena, och underwisa mig hwad hon betyder, och de kunna intet säga mig hwad sådant betyder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Men om dig hörer jag, at du kant gifwa uttydning, och uppenbara det hemligt är; kant du nu läsa denna skriftena, och underwisa mig hwad hon betyder, så skalt du med purpur klädd warda, och bära en gyldene kädjo om din hals, och wara den tredje herren i mitt rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Då swarade Daniel, och sade inför Konungen: Behålt dina gåfwor sjelf, och gif din skänk enom androm; jag will dock wäl läsa Konungenom skriftena, och underwisa hwad hon betyder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Herre Konung, Gud den högse gaf dinom fader, NebucadNezar, rike, magt, äro och härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Och för sådana magts skull, som honom gifwen war, fruktade och räddes för honom all land, och folk, och tungomål: Han drap hwem han wille, han slog hwem han wille, han uphöjde hwem han wille, han nedertryckte hwem han wille.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Men då hans hjerta uphof sig, at han wardt stolt och högmodig, wardt han kastad ifrå sin Konungsliga sol, och miste sina härlighet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Och wardt drifwen ifrå menniskor; och hans hjerta wardt likt wid wilddjur, och han måste löpa ibland wildåsnar, och åt gräs såsom oxar, och hans kropp låg under himmelens dagg, och wardt wåt, til dess han lärde weta, at den Högste hafwer wåld öfwer menniskors rike, och gifwer dem hwem han will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Och du Belsazar, hans son, hafwer icke ödmjukat ditt hjerta, ändock du allt sådant wetst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Utan hafwer uphäfwit dig emot himmelens Herra, och man hafwer måst bära hans hus kärille fram för dig, och du, dine wäldige, dina hustrur och dina frillor, hafwen druckit win deraf: Dertil lofwat de silfwer-, gyldene, koppar-, jern-, trä- och stengudar, hwilke hwarken se, eller höra, eller känna; men den Guden, som hafwer din anda och alla dina wägar i sine hand, hafwer du intet ärat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Derföre är denna handen sänd ifrå honom, och den skrift, som der upteknad står.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Och detta är skriften, som der upteknad är: Mene Mene, Thekel Upharsin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Och hon betyder detta: Mene, det är: Gud hafwer räknat ditt rike, och ändat det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Thekel, det är: Man hafwer wägit dig på ene wåg, och funnit dig allt för lättan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, det är: Ditt rike är åtskildt, och gifwit de Meder och Perser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Då befallte Belsazar, at man skulle kläda Daniel uti purpurkläde, och gifwa honom ena gyldene kädjo om hans hals; och lät förkunna om honom, at han war den tredje herren i rikena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'I den samma nattene wardt de Chaldeers Konung Belsazar ihjälslagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Och Darios utaf Meden tog riket in, då han tu och sextio år gammal war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Och Darios syntes godt wara, at han skulle sätta öfwer hela riket tjugu och hundrade landshöfdingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Öfwer dessa satte han tre Förstar; den ene war Daniel, hwilkom de landshöfdingar skulle räkenskap göra, at Konungen dess mindre bekymmer hafwa skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Men Daniel gick alla de Förstar och landshöfdingar widt öfwer; ty en hög ande war i honom; derföre tänkte Konungen at sätta honom öfwer hela riket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Fördenskull foro de Förstar och landshöfdingar der efter, huru de kunde finna en sak med Daniel, den emot riket wore; men de kunde ingen sak eller missgerning finna; ty han war trogen, så at man ingen skuld eller ogerning med honom finna kunde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Då sade männerne: Wi finne ingen sak med Daniel, utan om hans Gudstjenst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Då kommo de Förstar och landshöfdingar tilhopa inför Konungen, och sade til honom alltså: Herre Konung, Darios, Gud unne dig länge lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'De Förstar i rikena, herrarne, landshöfdingarne, Rådet och ämbetsmännerne, hafwa alle betänkt, at man skall låta utgå en Konungslig befallning, och et strängt påbud, at ho som hälst i tretio dagar någon ting will bedja af någon Gud eller mennisko, utan af dig Konung allena, han skall warda kastad för lejon uti gropena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Derföre, o Konung, måste du detta budet stadfästa, och underskrifwa dig; på det at det icke skall omwändt warda, efter de Meders och Persers rätt, det ingen öfwerträda djerfwes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Alltså underskref sig Konungen Darios.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Som nu Daniel förnam, at sådant bud underskrifwit war, gick han up i sitt hus; och han hade i sino sommarhuse öpna fönster emot Jerusalem: Der föll han tre resor om dagen uppå sin knä, bad, lofwade och tackade sin Gud, såsom han tilförene plägade göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Då kommo desse männerne hopetals, och funno Daniel bedjandes och åkallandes inför sin Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Så gingo de fram, och talade med Konungen om det Konungsliga budet: Herre Konung, hafwer du icke underskrifwit et bud, at ho som hälst i tretio dagar något både af någon Gud, eller af någon mennisko, utan af dig Konungenom allena, han skulle kastas för lejon i gropena? Konungen swarade, och sade: Det är sant, och de Meders och Persers rätt skall ingen öfwerträda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'De swarade, och sade för Konungen: Daniel, en af Juda fångar, aktar hwarken dig, o Konung, eller din bud, som du underskrifwit hafwer; ty han beder tre resor om dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Då Konungen detta hörde, wardt han fast bedröfwad, och winlade sig storliga, at han måtte fria Daniel; och arbetade derom intil solen undergick, at han måtte hjelpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Men männerne kommo samman til Konungen, och sade til honom: Du wetst, Herre Konung, at de Meders och Persers rätt är, at all bud och befallningar, som Konungen beslutit hafwer, skola oförwandlade blifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Då befallte Konungen, at man skulle hafwa Daniel fram, och de kastade honom för lejonen i gropena; men Konungen sade til Daniel: Din Gud, den du utan återwändo tjenar, han hjelpe dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Och de båro en sten fram, den lade de på locket af gropene; honom förseglade Konungen med sin egen ring, och med sina wäldigas ring, på det at ingen skulle eljest något bruka på Daniel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Och Konungen gick sin wäg på sina borg, och åt intet, och lät ingen mat för sig bära, och kunde ej heller sofwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Om morgonen bittida, då det dagades, stod Konungen up, och gick med hast til gropena, der lejonen uti woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Och som han kom til gropena, ropade han til Daniel med sorgeliga röst, och Konungen sade til Daniel: Daniel, du lefwandes Guds tjenare, hafwer ock din Gud, den du utan återwändo tjenar, förmått frälsa dig för lejonen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Då talade Daniel med Konungen: Herre Konung, Gud unne dig länge lefwa!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Min Gud hafwer sändt sin ¢ngel, hwilken lejonens mun tilhållit hafwer, at de hafwa ingen skada gjort mig; ty för honom är jag oskyldig funnen: Så hafwer jag ej heller något gjort emot dig, Herre Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Då wardt Konungen ganska glad, och lät taga Daniel utu gropene; och de togo Daniel utu gropene, och man fann platt ingen skada gjord wara uppå honom; ty han hade trott sinom Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Då lät Konungen komma fram de män, som Daniel beklagat hade, och kasta dem in för lejonen i gropena, samt med deras barn och hustrur; och förr än de kommo ned til botnen, fingo lejonen dem fatt, förkrossade ock alla deras ben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Sedan lät Konungen Darios skrifwa til all land, och folk, och tungomål: Gud gifwe eder mycken frid!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Detta är min befallning, at uti allt mins rikes herradöme skall man frukta och rädas Daniels Gud; ty han är den lefwande Gud, som blifwer ewinnerliga, och hans rike är oförgängeligit, och hans herradöme hafwer ingen ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Han är en frälsare och nödhjelpare, och han gör tekn och under, både i himmelen och på jordene: Han hafwer frälst Daniel ifrå lejonen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Och Daniel war wäldig i Darios rike, och desslikes i Cores, den Persens, rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Uti första årena Belsazars, Konungens i Babel, hade Daniel en dröm och syn på sin säng; och han skref den samma drömen, och författade honom alltså:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Jag, Daniel, såg en syn om nattene, och si, de fyra wäder under himmelen stormade emot hwartannat på stora hafwena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Och fyra stor djur stego up utu hafwet, ju det ena annorlunda än det andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Det första såsom et lejon, och hade wingar såsom en örn: Jag såg til, intil dess at wingarne wordo thy afryckte, och det wardt tagit bort af jordene, och det stod på sina fötter såsom en mennisko, och thy wardt et menniskligt hjerta gifwit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Och si, det andra djuret dernäst war likt enom björn, och stod på den ena sidone, och hade i sinom mun, ibland sina tänder, tre stora långa tänder, och man sade til det: Statt up, och ät mycket kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Efter detta såg jag, och si, et annat djur, likt enom parde, det hade fyra wingar, såsom en fogel, på sin rygg; och det samma djuret hade fyra hufwud, och thy wardt magt gifwen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Efter detta såg jag i denna synene om nattene, och si, det fjerde djuret war grufweligit och förskräckligit, och mägta starkt, och hade stora jerntänder; åt omkring sig, och förkrossade, och hwad qwart war, trampade det med sina fötter: Det war ock mycket annars, än de förra, och hade tio horn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Då jag nu skådade hornen, si, då gick der ut ibland dem et annat litet horn, för hwilko de tre främsta hornen af stött wordo; och si, det samma hornet hade ögon såsom mennisko ögon, och en mun, den stor ting talade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Sådant såg jag, till dess solar framsatte wordo, och den gamle satte sig, hwilkens kläde war snöhwitt, och håret på hans hufwud såsom ren ull: Hans stol war alltsammans eldslåge, och hans hjul brunno af eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Och af honom utgick en lång eldstrimma: Tusende sinom tusend tjente honom, och tio sinom hundrade stodo för honom: Domen wardt hållen, och böckerna wordo uplåtna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Jag såg til, för de stora ords skull, som det hornet talade: Jag såg til, intil dess djuret dräpit wardt, och dess kropp förgicks, och i eld kastad wardt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Och de andra djurs wälde också ute war; ty dem war en tid och stund bestämd, huru länge hwartdera wara skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Jag såg i denna synene om nattene; och si, en kom i himmelens sky, såsom ens menniskos son, allt intil den gamla, och han wardt framhafd för honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Honom gaf han wåld, äro och rike, at all land, och folk, och tungomål, skulle tjena honom: Hans wälde är ewigt, det icke förgås, och hans rike hafwer ingen ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Jag, Daniel, förskräckte mig derföre, och sådana syn förfärade mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Och jag gick til en af dem, som der stodo, och bad honom, at han skulle gifwa mig en wiss underwisning om allt detta; och han talade med mig, och tedde mig, hwad det betydde:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Dessa fyra stora djur äro fyra rike, som på jordena komma skola;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Men dens Högstas helige skola intaga riket, och skola besitta det i ewig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Sedan hade jag gerna wetat en wiss underwisning om det fjerde djuret, hwilket platt annars war, än all de andra, ganska grufweligit; det jerntänder och kopparklor hade, det omkring sig åt, och förkrossade, och det qwart war med sina fötter trampade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Och om de tio horn på dess hufwud, och om det andra som upwäxte, för hwilko tre afföllo; och om det samma hornet, som ögon hade, och en mun, som stor ting talade, och större war än de der bredwid woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Och jag såg det samma hornet strida emot de heliga, och det behöll segren emot dem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Til dess den gamle kom, och höll dom för dens Högstas heligom, och tiden kom, at de helige intogo riket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Han sade alltså: Det fjerde djuret skall wara det fjerde riket på jordene, hwilket mägtigare skall wara än all rike; det skall upäta, förtrampa och förkrossa all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'De tio horn betyda tio Konungar, som i de rikena upkomma skola, efter dem skall en annar upkomma, han skall wara mägtigare än någor af de förra, och skall undertrycka tre Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Han skall försmäda den Högsta, och för störa dens Högstas heliga; och skall taga sig före att förwandla tider och lag; men de skola warda gifne uti hans hand i en tid, och några tider, och en half tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Derefter skall domen hållen warda; så skall då hans wälde borttaget warda, så at han skall i grund förderfwad och förgjord warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Men riket, magten och wäldet under hela himmelen skall warda gifwit dens Högstas heligo folke, hwilkes rike ewigt är; och allt wälde skall tjena honom, och lyda honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Det war änden på talet. Men jag, Daniel, wardt swårliga bedröfwad i mina tankar, och mitt ansikte förwandlade sig uppå mig; dock behöll jag talet i mitt hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Uti tredje årena af Konung Belsazars rike syntes mig, Daniel, en syn, efter den som mig i förstone synts hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Men jag war, då jag denna syn såg, i Susan, hufwud stadenom i Elams land, wid den älfwen Ulai.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Och jag hof up min ögon, och såg; och si, en wädur stod för älfwene, och han hade tu hög horn; dock det ena högre än det andra, och det högsta wäxte sidst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Jag såg, at wäduren stötte med hornen wäster ut, norr ut och söder ut, och intet djur kunde bestå för honom, eller fria sig ifrå hans hand; utan han gjorde hwad han wille, och wardt stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Och wid jag gaf der akt uppå, så kom en getabock, wästan efter, öfwer hela jordena, så at han intet kom wid jordena; och den bocken hade et skönt horn emellan sin ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Och han kom allt intil den wäduren, som en horn hade, den jag såg stå för älfwene, och han lopp i sine wrede wäldeliga intil honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Och jag såg, at han kom hardt intil wäduren, och förgrymmade sig öfwer honom, och stötte til wäduren, och sönderslog hans tu horn; och wäduren hade ingen magt til att stå honom emot, utan han stötte honom til markena, och trampade uppå honom; och ingen förmåtte hjelpa wäduren utu hans hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Och den getabocken wardt ganska stor, och då han som starkast worden war, gick det stora hornet sönder, och i dess stad wäxte fyra sköna, emot fyra himmelens wäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Och af eno dera wäxte et litet horn, det wardt ganska stort, söder ut, öster ut, och in emot det lustiga landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Och det wäxte allt intil himmelens här, och kastade somliga neder dädan, och af stjernorna til jordena, och trampade uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ja, det wäxte allt intil Förstan för hären, och tog bort ifrå honom det dageliga offret, och förödde hans helgedoms boning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Och sådana magt wardt honom gifwen emot det dageliga offret för syndernas skull, så at han skulle slå neder sanningena, och hwad han gjorde, skulle framgång hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Men jag hörde en Heligan tala; och den samme Helige sade til en som talade: Huru länge skall dock denna synen, om det dagliga offret, wara, och om synderna, för hwilkas skull denna förödning skre, så at både helgedomen och hären förtrampad warder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Och han swarade mig: Det är tu tusende och trehundrade dagar, efter afton och morgon räknandes, så skall helgedomen åter wigder warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Och då jag, Daniel, såg den synena, och hade gerna förståndit henne, si, då stod för mig såsom en man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Och jag hörde emellan Ulai ene menniskos röst, som ropade och sade: Gabriel, uttyd dessom synena, så at han förstår henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Och han kom hardt intil mig: Och jag wardt förskräckt, då han kom, och föll neder uppå mitt ansikte, och han sade til mig: Gif akt häruppå, du menniskobarn, ty denna synen lyder uppå ändans tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Och då han talade med mig, dignade jag af wanmägtighet neder på mitt ansikte til jordena; men han tog uppå mig, och rätte mig up, så at jag blef ståndandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Och han sade: Si, jag will wisa dig, huru det gå skall på yttersta wredenes tid; ty änden hafwer sin bestämda tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Wäduren med de tu horn, som du sågst, äro de Konungar i Meden och Persien;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Men getabocken är Konungen i Grekeland: Det stora hornet emellan hans ögon är den förste Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Men at fyra stodo i dess stad, då det sönderslagit wardt, betyder, at fyra rike skola upkomma af det folket; men icke så mägtig, som han war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Efter dessa riken, när öfwerträdelsen stor worden är, skall upkomma en arg och listig Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Han skall wara mägtig, dock icke genom sina kraft: Han skall underliga föröda, och skall hafwa framgång, at han det uträttar; han skall förstöra de starka, och det heliga folket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Och genom hans klokhet skall hans bedrägeri framgå, och han skall uphäfwa sig i sitt hjerta, och genom framgång skall han många förderfwa, och skall upsätta sig emot alla Förstars Första; men han skall utan hand förlagd warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Denna synen, om afton och morgon, som dig sagd är, hon är sann; men du skalt hålla synena hemliga, ty det är ännu en lång tid dit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Och jag, Daniel, wardt swag, och låg i några dagar krank: Sedan stod jag up, och bestälte Konungens ärende, och förundrade mig uppå synena; och ingen war, som kunde reda mig henne ut.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Uti första årena Darios, Ahasveros sons, utaf de Meders slägte, hwilken öfwer de Chaldeers rike Konung wardt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Uti de samma första årena af hans rike förmärkte jag, Daniel, i böckerna, uppå det åratalet, der HERren om talat hade til Propheten Jeremia, at Jerusalem skulle öde ligga i sjutio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Och jag wände mig til HERran Gud, til at bedja och åkalla med fasto, uti säck och asko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Och jag bad til HERran min Gud, bekände och sade: Ack! HERre, du store och förskräcklige Gud, du som håller förbund och nåde dem, som dig älska, och hålla din bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Wi hafwe syndat, gjort orätt, hafwe warit ogudaktige, och wordet affällige; wi hafwe wikit ifrå din bud och rätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Wi lydde icke dina tjenare, Propheterna, som predikade i ditt Namn wårom Konungom, Förstom, fädrom, och allo folkena i landena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Du, HERre, äst rättfärdig; men wi måstom skämma oss, såsom det ock nu går dem af Juda, och dem af Jerusalem, och hela Israel, både dem som när, och dem som fjerran äro, i all land, dit du dem utkastat hafwer, för deras missgerningars skull, som de emot dig bedrifwit hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja, HERre, wi, wåre Konungar, wåre Förstar och wåre Fäder, måstom skämma oss, at wi hafwe syndat emot dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Men din, HERre wår Gud, är barmhertighet och förlåtelse; ty wi äre affällige wordne:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Och lydde icke HERrans wår Guds röst, at wi hadom mått wandrat i hans lag, som han oss genom sina tjenare, Propheterna, förelade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Utan hele Israel öfwerträdde din lag, och weko af, så at de icke lydde dine röst; derföre hafwer ock den förbannelse och ed kommit öfwer oss, som i Mose, Guds tjenares, lag skrifwen står; ty wi hafwe syndat emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Och han hafwer hållit sin ord, som han talat hafwer emot oss, och wåra domare, som oss döma skulle; så at han hafwer låtit gå så stor olycka öfwer oss, at sådant är icke skedt under hela himmelen, såsom öfwer Jerusalem skedt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Såsom det skrifwit är i Mose lag, så är allt detta stora onda öfwer oss gånget: Icke bådom wi heller inför HERran wår Gud, at wi måttom wändt oss ifrå wåra synder, och tänkt uppå dina sanning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Derföre hafwer icke heller HERren försummat sig med denna olyckone, utan hafwer låtit henne gå oss utöfwer; ty HERren wår Gud är rättfärdig i alla sina gerningar, som han gör; ty wi lydde icke hans röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Och nu, HERre wår Gud, du som ditt folk utur Egypti land med starka hand förde, och gjorde dig et Namn såsom det nu är: Wi hafwe ju syndat, och hafwe, thy wärr! warit ogudaktige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ack HERre! för alla dina rättfärdighets skull, hålt up af dine wrede och grymhet öfwer din stad Jerusalem, och öfwer ditt helga berg; ty för wåra synders skull, och för wåra Fäders missgerningars skull, lider Jerusalem och ditt folk försmädelse, när alla de som här omkring äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Och nu, wår Gud, hör dins tjenares bön och hans begäran, och war miskundsam öfwer din helgedom, som förlagd är, för HERrans skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Böj neder din öron, min Gud, och hör; låt up din ögon, och skåda, huru wi förstörde äro, och staden, som efter ditt Namn nämnder är; ty wi ligge inför dig med wåra böner, icke uppå wåra rättfärdighet, utan på dina stora barmhertighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ack HERre! hör; ack HERre! war miskundsam; ack HERre! akta uppå, och gör det: Fördröj icke, för din egen skull, min Gud; ty din stad och ditt folk är nämndt efter ditt Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Som jag ännu så talade och bad, och mina och mins folks Israels synder bekände, och låg med mine bön upför HERranom minom Gud, för mins Guds helga bergs skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Rätt då jag så talade i mine bön, slög den mannen Gabriel fram, den jag tilförene i synene sett hade, och tog uppå mig i aftonoffrens tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Och han underwiste mig, och talade til mig, och sade: Daniel, nu är jag utsänd til at underwisa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Ty då du begynte at bedja, gick denna befallningen ut; och jag kommer fördenskull til at underwisa dig; ty du äst behagelig och täck; så märk nu til, at du må förstå synena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sjutio weckor äro bestämda öfwer ditt folk, och öfwer din helga stad; så skall öfwerträdelsen blifwa förtagen, och synden betäckt, och missgerningen försonad, och den ewiga rättfärdigheten framhafd, och synen och prophetien beseglad, och den Aldraheligaste smord warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Så wet nu, och märk til, ifrå den tiden, då befallningen utgår, at Jerusalem skall igen upbygd warda, intil den Förstan Christum, äro sju weckor; och twå och sextio weckor, så skola gatorna och murarne åter upbygde warda, ändock i bullersam tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Och efter de twå och sextio weckor skall Christus dödad warda, och de skola icke wilja honom: Och et Förstans folk skall komma, och förstöra staden och helgedomen, så at det skall blifwa ändadt, såsom igenom en flod, och efter stridena skall det öde blifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Men han skall mångom stadfästa förbundet i ena wecko långt: Och midt i weckone skall offret och spisoffret återwända, och förödningens styggelse stå bredowid wingarna; och är beslutet, at det skall öde blifwa allt intil ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Uti tredje årena Konungs Cores af Persien wardt Daniel, den Beltesazar het, något uppenbaradt, det wist, och om dråplig ting är; och han aktade deruppå, och förstod synena wäl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'På samma tid war jag, Daniel, sorgse i tre weckor långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Jag åt ingen kräselig mat; kött och win kom intet i min mun, och jag smorde mig ej heller, til dess tre weckor framledna woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'På fjerde och tjugonde dagen i första månadenom war jag wid den stora älfwena Hiddekel:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Och uplyfte min ögon, och såg: Och si, der stod en man i linkläder, och hade et gyldene bälte omkring sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Hans kropp war såsom en hyacint, hans anlete syntes såsom en ljungeld, hans ögon såsom brinnande bloss, hans armar och fötter såsom en glödandes koppar, och hans tal war såsom en stor dön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Och jag, Daniel, såg sådana syn allena, och de män, som när mig woro, sågo henne intet; dock föll en stor förskräckelse öfwer dem, så at de flydde bort, och gömde sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Och jag blef allena, och såg den stora synena; men ingen magt blef uti mig, och min hy wardt förwandlad på mig, och jag hade ingen magt mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Och jag hörde hans tal; och i det jag det hörde, seg jag neder uppå mitt ansikte til jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Och si, en hand tog uppå mig, och halp mig uppå knän, och uppå händerna:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Och sade til mig: Du älskelige Daniel, gif akt uppå orden, som jag med dig talar, och res dig up; ty jag är nu sänder til dig. Och då han sådant sade til mig, reste jag mig up, och darrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Och han sade til mig: Frukta dig intet Daniel; ty ifrå första dagenom, då du af hjertat begärade förstå, och betwingade dig inför din Gud, äro din ord hörd, och jag är för dina skull kommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Men den Försten öfwer det riket i Persien hafwer ståndit mig emot i en och tjugu dagar, och si, Michael, en af de ypperste Förstar, kom mig til hjelp; då behöll jag segren när Konungenom i Persien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Men nu kommer jag til at underwisa dig, huru dino folke härefter gå skall; ty synen skall ske efter någon tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Och som han detta med mig talade, slog jag mitt ansikte neder åt jordena, och teg stilla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Och si, en som war lik ene mennisko tog uppå mina läppar: Då öppnade jag min mun, och talade, och sade til honom, som för mig stod: Min Herre, mine ledamöter bäfwa mig öfwer synena, och jag hafwer ingen magt mer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Och huru kan mins Herras tjenare tala med minom Herra, efter ingen magt är nu mer uti mig, och jag hafwer ej heller någon anda mer?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Då tog åter en uppå mig, hwilken war såsom en menniska, och han stärkte mig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Och han sade: Frukta dig intet, du älskelige man, frid ware med dig, war tröst, war tröst. Och som han med mig talade, förmannade jag mig, och sade: Tala, min Herre; ty du hafwer stärkt mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Och han sade: Wetst du ock, hwarföre jag är kommen til dig? Nu will jag åter mina färde, och skrida med Förstanom i Persien; men när jag far mina färde, si, så skall Försten af Grekeland komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Dock will jag låta dig förstå, hwad skrifwit är, det wisserliga ske skall: Och ingen är den mig hjelper derutinnan, utan edar Förste Michael.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Jag stod ock med honom uti första årena Darios, den Medens, til at hjelpa och styrka honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Och nu will jag underwisa dig, hwad som i sanning ske skall: Si, tre Konungar skola ännu blifwa i Persien; men den fjerde skall få större rikedomar än alle andre: Och som han i sina rikedomar är aldramägtigast, skall han upwäcka alla emot det riket i Grekeland.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sedan skall en mägtig Konung upkomma, och regera med stora magt, och skall göra ehwad han will.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Och som han är kommen uppå det högsta, skall hans rike brista, och dela sig i fyra himmelens wäder; dock icke til hans affödo, ej heller med sådana magt, som hans warit hafwer; ty hans rike warder utrotadt, och skall komma främmandom til lott.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Och Konungen i Söderlanden, den en af hans Förstar är, skall mägtig warda; men emot honom skall ock en mägtig warda, och regera, hwilkens wälde skall stort warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Efter någor år skola de befrynda sig tilhopa; och Konungens dotter i Söderlanden skall komma til Konungen i Nordlanden, til at göra en förening; men hon warder icke blifwandes wid arms magt, ej heller hennes säd ståndandes; utan hon skall warda öfwergifwen, samt med dem som henne framförde, och med barnena, och med dem som henne en tid långt wid magt hållit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Men en Telning af hennes slägte skall upkomma, han skall komma med härs kraft, och falla in uti Konungens fäste i Nordlanden, och skall blifwa wid sig, och få öfwerhandena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Och han skall bortföra deras gudar och beläten, samt med de kosteliga klenodier, både af silfwer och guld, in uti Egypten; och skall blifwa wäl ståndandes för Konungenom i Nordlanden i någor år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Och då han hafwer dragit igenom det riket, skall han draga hem i sitt land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Men hans söner skola warda wrede, och samka tilhopa många härar; och den ene skall komma, och fara fram åt såsom en flod, och åter reta den andra til wrede inför hans fäste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Då skall Konungen i Söderlanden warda wred, draga ut och skrida med Konungenom i Nordlanden; och skall hemta tilhopa en så stor hop, at den andre hopen skall warda gifwen honom i hans hand:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Och han skall föra samma hop bort; och skall hans hjerta förhäfwa sig deraf, at han så mång tusend underlagt hafwer; men dermed får han intet öfwerhandena med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Ty Konungen af Nordlanden skall åter samka en större hop tilsammans, än de förre war; och efter någor år skall han draga dit med stor härs kraft, och med stora rikedomar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Och på samma tid skola månge sätta sig upp emot Konungen af Söderlanden; skola ock desslikes någre affällige af dino folke uphäfwa sig, och upfylla prophetien och falla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Alltså skall Konungen af Nordlanden draga ut, och bolwerk göra, och winna fasta städer; och Söderlandens armar skola icke kunna förtagat, och hans bästa folk skola icke kunna stå emot;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Utan han skall, när han kommer til honom, skaffa sin wilja, och ingen skall kunna stå honom emot; han skall ock komma in uti det lustiga landet, och skall förderfwat genom dess hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Och skall ställa der sitt ansikte efter, at han må komma med allo sins rikes magt; men han skall förlika sig med honom, och skall gifwa honom sina dotter til hustru, på det han skall förderfwa honom; dock skall det icke lyckas honom, och der warder intet af.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Derefter skall han wända sig emot öarna, och winna många af dem; men en Förste skall twinga honom, så at han måste wända igen med skam; på det honom icke skall wederfaras mer skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Alltså skall han wända tilbaka til sins lands fäste, och skall stöta sig och falla, så at man intet skall finna honom mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Och i hans stad skall en upkomma, hwilken sitta skall uti Konungsliga äro, som en öfwerträdare och tyrann; men efter få dagar skall han förgås, dock hwarken genom wrede eller strid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Uti hans stad skall upkomma en föraktelig man, hwilkom riksens ära intet betänkt war: Han skall komma, och få sin wilja, och intaga riket med sötom ordom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Och de armar, hwilke såsom en flod komma, skola för honom, såsom med ene flod, öfwerfallne och sönderbrutne warda; dertil ock den Försten, som förbundet med gjordt war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Ty sedan han med honom befryndad är, skall han listeliga handla med honom; och skall draga up, och warda honom öfwermägtig med fögo folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Och der skall lyckas honom, så at han skall komma inuti bästa städerna i landena, och skall beskaffa, det hans fäder eller föräldrar icke göra kunde, med rof, skinneri och byte, och skall fara efter de fasta städer, och det en tid långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Och han skall upwäcka sina magt och sitt hjerta emot Konungen i Söderlanden, med stor härs kraft: Då skall Konungen af Söderlanden uprett warda til strid, med en stor mägtig härs kraft; men han blifwer intet beståndandes; ty förräderi skall warda gjordt emot honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ja, de som hans bröd äta, de skola hjelpa til at förderfwa honom, och hans här undertrycka, så at ganska månge skola slagne warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Och båda Konungarnas hjerta skall tänka til, huru de skola göra hwarannan skada, och skola dock öfwer et bord tala falskeliga med hwarannan; men det skal fela dem; ty änden är ännu bestämd in uppå en annan tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Sedan skall han draga hem igen med stora rikedomar, och skall ställa sitt hjerta emot det helga förbundet: Der warder han något beskaffandes, och sedan draga hem i sitt land igen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Derefter skall han åter, på belägen tid, draga emot Söderlanden; men det skall icke lyckas honom i den andra resone, såsom i den första.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Ty af Chittim skola skepp komma emot honom, så at han skall warda förtwiflad, och måste wända tilbaka igen: Då skall han förgrymma sig emot det helga förbundet, och skall beskaffat, och skall se sig om, och draga dem til sig, som det helga förbundet öfwergifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Och hans armar skola der stå; de skola oskära helgedomen i fästet, och aflägga det dageliga offret, och upsätta en förödnings styggelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Och han skall skrymta, och gifwa dem ogudaktigom, som förbundet öfwerträda, god ord; men det folk, som sin Gud känna, skola förmanna sig, och beskaffat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Och de förståndige i folket skola lära många andra; derföre skola de förföljde warda med swärd, eld, fängelse och rof, en tid långt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Men i den samma förföljelsen skall dem likwäl ske en liten hjelp; dock skola månge gifwa sig til dem bedrägeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Och de förståndige skola somlige förföljde warda, på det de skola warda bepröfwade, rene och klare, til dess at det får en ända; ty det är ännu en annar tid för handene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Och Konungen skall göra ehwad han will, och skall uphäfwa och upkasta sig öfwer allt det Gud är, och skall grufweliga tala emot den, som är alla gudars Gud, och det skall lyckas honom, intil des wreden är ute; ty det är beslutit, huru länge det skall wara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Och sina fäders Gud skall han intet akta: Han skall icke akta uppå qwinnokärlek, eller uppå någon gud; ty han skall upsätta sig emot alla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Men sin egen gud, Maussim, skall han dyrka; ty en gud, der hans fäder intet af wisst hafwa, den skall han ära, med guld, silfwer, ädla stenar och klenodier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Och han skall göra dem stora äro, som hjelpa honom stärka Maussim, med den främmande guden, som han utwalt hafwer; och skall göra dem til Herrar öfwer stora rikedomar, och utskifta dem landet til lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Och på ändalyktene skall Konungen af Söderlanden stötas med honom; och Konungen af Nordlanden skall församla sig emot honom, med wagnar, resenärer, och mång skepp, och skall infalla i landen, och förderfwa, och draga derigenom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Och skall infalla uti det lustiga landet, och månge skola dräpne warda; men desse skola undslippa hans hand, Edom, Moab och Ammons barns Förstar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Och han skall sända sina magt i landen, och Egypten skall icke undslippa honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Utan han skall med sitt indragande warda rådandes öfwer gyldene och silfwer skatter, och öfwer all klenodier i Egypten, Libyen och Ethiopien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Men et rykte skall förskräcka honom, af östan och af nordan; så at han skall draga ut med stora wrede, i det sinnet, at han skall många förgöra och förderfwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Och han skall upslå sins palatses tjäll emellan hafwen, omkring det lustiga helga berget, til dess med honom warder en ände; och ingen skall hjelpa honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'På samma tiden skall den store Försten Michael, som för ditt folk står, upresa sig; ty en sådana bedröfwad tid skall komma, at ingen slik warit hafwer, ifrå den tid menniskor hafwa warit til, intil den tiden: Uti den samma tiden skall ditt folk frälst warda, alle de som i bokene skrifne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Och månge de, som under jordene sofwa ligga, skola upwakna, somlige til ewigt lif, somlige til ewig försmädelse och blygd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Men Lärarena skola lysa såsom himmelens sken, och de som många underwisa till rättfärdighet, såsom stjernor i ewighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Och du, Daniel, fördölj dessa orden, och besegla denna skriftena intil den yttersta tiden; så skola månge deröfwer komma, och finna et stort förstånd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Och jag, Daniel, såg, och si, der stodo twå andre, en på denna stranden wid älfwena, en annar på den andra strandene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Och han sade til den, som i linkläder ofwan uppå älfwenes watn stod: När skall då änden warda med sådana under?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Och jag lydde til den mannen, som i linkläden stod ofwan uppå watnena; och han hof up sina högra och wenstra hand til himmelen, och swor wid honom som lefwer ewinnerliga, at det skulle wara til en tid, och några tider, och en half tid; och när dess heliga folkens förskingring en ända hafwer, så skall allt sådant ske.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Och jag hörde det, men jag för stod det intet; och jag sade: Min Herre, hwad skall ske derefter?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Han sade: Gack, Daniel, ty det är fördoldt och besegladt intil yttersta tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Månge skola renade, luttrade och bepröfwade warda; och de ogudaktige skola föra et ogudaktigt wäsende; och de ogudaktige skola intet aktat; men de förståndige skola aktat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Och ifrå den tiden, när det dageliga offret borttaget, och förödelsens styggelse upsatt warder, skall wara tusende tuhundrade och niotio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Wäl är honom, som då förbidar, och räcker intil tusende trehundrad och fem och tretio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Men du, Daniel, gack bort, til dess änden kommer, och hwila dig, at du må upstå i dinom del, när dagarne hafwa ända.');
