INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'HErrans ord skedde till Jona, Amitthai son, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Upp, och gack in uti den stora staden Nineve, och predika derinne; förty hans ondska är kommen upp för mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Men Jona stod upp, och flydde ifrå Herranom, och wille ut till hafs, och kom neder till Japho; och då han fann ett skepp, som till hafs fara wille, gaf han skepplön, och steg deruti, på det han skulle fara med dem till hafs, ifrå Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Då lät Herren komma ett stort wäder uppå hafwet, och en stor storm upphof sig på hafwet, så att man mente att skeppet skulle söndergå.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Och skeppmännerna fruktade sig, och ropade hwar och en till sin gud, och kastade de tyg, som i skeppena woro, uti hafwet, att det skulle lättare warda; men Jona war stigen neder i skeppet, låg och sof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Då gick skepparen till honom, och sade till honom: Hwi sofwer du? Statt upp, åkalla din Gud, att Gud till äfwentyrs wille tänka uppå oss, att wi icke förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Och den ene sade till den andra: Kommer, wi wilje kasta lott, att wi förfara måge, för hwilkens skull oss så illa går. Och då de kastade lotten, råkade det på Jona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Då sade de till honom: Säg oss, hwarföre går oss så illa? Hwad är din handel, och hwadan äst du kommen? Utaf hwad land äst du, och af hwad folk äst du?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Han sade till dem: Jag är en Ebreer, och fruktar Herran Gud af himmelen, som hafwet och det torra gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Då fruktade männerna storliga, och sade till honom: Hwi hafwer du då detta gjort? Ty de wisste, att han flydde ifrå Herranom; ty han hade sagt dem det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Då sade de till honom: Hwad skole wi då göra med dig, på det hafwet måtte oss stilla warda? Ty hafwet gick fast uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Han sade till dem: Tager och kaster mig i hafwet, så stillas eder hafwet; ty jag wet, att sådana stor storm öfwer eder kommer för mina skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Och männerna rodde, att de måtte åter komma till lands igen; men de kunde intet: ty hafwet gick swårliga uppå dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Då ropade de till Herran, och sade: Ack! Herre, låt oss icke förgås för denna mansens själs skull, och räkna oss icke oskyldigt blod till; ty du, Herre, gör, såsom dig täckes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Och de togo Jona, och kastade honom i hafwet; då wände hafwet igen af sinom storm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Och männerna fruktade Herran storliga, och gjorde Herranom offer och löfte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Och HErren förskaffade en stor fisk, till att uppsluka Jona; och Jona war i fiskens buk tre dagar och tre nätter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Och Jona bad till HErran sin Gud, i fiskens buk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Och han sade: Jag ropade till HErran i mine ångest, och han swarade mig; jag ropade utu helwetes buk, och du hörde mina röst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Du kastade mig uti djupet, midt i hafwet, så att floderna kommo omkring mig; alle dine wåger och böljor gingo öfwer mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Jag tänkte, att jag bortkastad war ifrå din ögon; men jag skall ännu få se ditt helga tempel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Wattnen omhwärfde mig allt intill mitt lif; djupet omgrep mig, sjöwassen öfwertäckte mitt hufwud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Jag sönk neder till bergsgrunden, jorden hade beslutit mig med sina bommar ewinnerliga; men du hafwer fört mitt lif utu förderfwet, HErre min Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Då min själ öfwergaf sig, tänkte jag uppå HErran, och min bön kom till dig, uti ditt helga tempel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Men de som förlåta sig uppå sina gerningar, hwilka dock intet äro, de akta intet om nådena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Men jag will offra med tacksägelse. Min löfte will jag betala HErranom, att han mig hulpit hafwer. Och HErren sade till fisken, och han utsputade Jona in uppå landet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'OCH HErrans ord skedde annan gång till Jona, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Statt upp, och gack in uti den stora staden Nineve, och predika honom den predikan, som jag dig säger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Då stod Jona upp, och gick bort till Nineve, såsom HErren sagt hade; men Nineve war en Guds stad, tre dagsresor stor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Och då Jona begynte ingå ena dagsreso in i staden, predikade han, och sade: Det är ännu fyratio dagar, och så skall Nineve förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Då trodde de Ninevitiske män uppå Gud, och läto predika fasto, och drogo säcker uppå sig, både store och små.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Och då det kom för Konungen i Nineve, stod han upp af sitt säte, och lade af sitt purpur, och tog en säck omkring sig, och satte sig i asko;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Och lät utropa och säga i Nineve, af Konungens och hans wäldigas befallning, alltså: Det skall hwarken menniska eller djur, hwarken fä eller får något smaka; och man skall intet hafwa dem i bet, eller låta dem watten dricka;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Och skola taga säcker om sig, både folk och fä, och ropa stadeliga till Gud; och hwar och en wände sig ifrå sinom onda wäg, och ifrå sina händers ondsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ho wet? Gud måtte omwända sig, och ångra det, och wända sig ifrå sine grymma wrede, att wi icke förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Då nu Gud såg deras gerningar, att de omwände sig ifrå sinom onda wäg, ångrade Gudi det onda, som han talat hade att han dem göra wille; och gjorde det intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Det förtröt Jona ganska storliga, och wardt wred;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Och bad till HErran, och sade: Ack! HErre, det är det som jag sade, då jag ännu war i mitt land; derföre jag ock wille det förekomma, och fly till hafs; ty jag wet att du äst en nådelig Gud, barmhertig, långmodig, och af stor mildhet, och låter dig ångra det onda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Så tag då nu mina själ ifrå mig, HErre; ty jag will heldre wara död, än lefwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Men HErren sade: Menar du, att du skäliga wredgas?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Och Jona gick utu staden, och satte sig östan för staden, och gjorde sig der ena hyddo; der satte han sig neder i skuggan, till dess han måtte se hwad stadenom wederfaras skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Men HErren Gud förskaffade en kurbits; den wäxte öfwer Jona, att hon skulle skygga öfwer hans hufwud, och wederqwicka honom i hans wedermödo; och Jona gladdes fast öfwer den kurbitsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Men Gud förskaffade en matk om morgonen, då morgonrodnen uppgick; han åt kurbitsen, så att hon förtorkades.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Men då solen uppgången war, förskaffade Gud ett torrt östanwäder, och solen stack Jona uppå hufwudet, så att han wanmägtig wardt. Då önskade han sine själ döden, och sade: Jag wille heldre wara död, än lefwandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Då sade Gud till Jona: Menar du, att du skäliga wredgas om kurbitsen? Och han sade: Jag må wäl wredgas allt intill döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Och HErren sade: Du jämrar dig om kurbitsen, der du intet uppå arbetat hafwer, och hafwer ej heller låtit henne uppwäxa, hwilken i ene natt wardt, och i ene natt förgicks;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Och jag skulle icke jämra mig öfwer Nineve, en sådana stor stad, der mer uti är än hundradetusend och tjugutusend menniskor, som intet weta åtskilja mellan sina högra hand och den wenstra; dertill ock mycken djur?');
