INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, dem heligom som uti Epheso äro, och trognom i Jesu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Välsignad vare Gud, och vårs Herras Jesu Christi Fader, den oss välsignat hafver med all andelig välsignelse, i de himmelska ting, genom Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Såsom han oss utvalt hafver i honom, förr än verldenes grund lagder var, att vi skole vara helige och ostraffelige för honom uti kärleken;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Och hafver tagit oss sig sjelfvom till barn, genom Jesum Christum, efter sins viljas goda behag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Sina härliga nåd till lof, genom hvilka han hafver oss täcka gjort uti honom, som kärkommen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'I hvilkom vi hafvom förlossning genom hans blod, syndernas förlåtelse, efter hans nåds rikedomar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Af hvilka han oss rundeliga delaktiga gjort hafver uti all visdom och klokhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Och hafver oss låtit få veta sins viljas hemlighet, efter sitt goda behag, och hafver det framhaft igenom honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Att det skulle predikadt varda, då tiden fullkomnad var; på det allting skulle sammanfattad varda i Christo, både det i himmelen och på jordene är, genom den sammas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Genom hvilken vi ock komne äre till arfvedelen, beskärde efter hans uppsåt, som all ting verkar efter sin egen viljas råd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Att vi skole vara hans härlighet till lof, vi som tillförene hoppadoms på Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Genom hvilken ock I hört hafven sanningenes ord, som är edor salighets Evangelium; uti hvilkom I ock, sedan I trodden, ären beseglade vordne med löftsens Helga Anda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Hvilken vårt arfs pant är, till vår förlossning, att vi skulle varda hans egendom, hans härlighet till pris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Derföre ock jag, efter jag hört hafver af den tro, som i eder är till Herran Jesum, och edar kärlek till all helgon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Vänder jag icke åter att tacka Gud för eder, alltid tänkandes på eder i mina böner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Att vårs Herras Jesu Christi Gud, härlighetenes Fader, ville gifva eder visdomsens och uppenbarelsens Anda, till sin kunskap,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Och upplysa edars förstånds ögon; att I förstå kunnen, hvad hopp han hafver kallat eder uti, och huru rik hans arfs härlighet är uti helgonen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Och huru öfversvinneliga stor hans kraft är till oss, som tron, efter hans mägtiga starkhets verkan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Hvilka han verkade i Christo, då han uppväckte honom ifrå de döda, och satte honom på sin högra hand i himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Öfver all Förstadöme, välde, magt, Herradöme, och allt det som nämnas kan, icke allenast i denna verldene, utan ock i den tillkommande;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Och hafver all ting lagt under hans fötter, och hafver satt honom församlingene till ett hufvud öfver all ting;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Hvilken är hans kropp, och hans uppfyllelse, som allt i allom uppfyller.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Och eder också, då I döde voren genom öfverträdelser och synder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Der I uti fordom vandraden, efter denna verldenes lopp, efter den Förstan, som magt hafver i vädret, nämliga efter den andan, som nu verkar i otrones barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Ibland hvilka vi ock alle fordom vandrat hafve, uti vårt kötts begärelser, och gjordom hvad köttet och sinnet lyste: och vorom af naturen vredsens barn, såsom ock de andre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Men Gud, som är rik i barmhertigheten, för sina stora kärleks skull, der han oss med älskat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Den tid vi ännu döde vorom i synderna, hafver han oss samt med Christo gjort lefvande (genom nådena ären I frälste);');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Och hafver samt med honom uppväckt oss, och samt med honom satt oss i det himmelska väsendet i Christo Jesu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'på det han i tillkommande tid bevisa skulle sine nåds öfversvinneliga rikedom, genom sina mildhet öfver oss, i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Ty af nådene ären I frälste, genom trona; och det icke af eder, Guds gåfva är det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Icke af gerningar, på det ingen skall berömma sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Ty vi äre hans verk, skapade i Christo Jesu till goda gerningar, till hvilka Gud oss tillförene beredt hafver, att vi uti dem vandra skole.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Derföre, tänker derpå, att I som fordom efter köttet hafven varit Hedningar, och vorden kallade förhud af dem som kallas omskärelse efter köttet, den med handene sker;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Att I på den tid voren utan Christo, främmande och utan Israels borgareskap, och främmande ifrå löftsens Testament, intet hopp hafvande, och voren utan Gud i verldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Men nu, I som i Christo Jesu ären, och fordom fjerran voren, ären nu när vordne, genom Christi blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Ty han är vår frid, den af bådom hafver gjort ett; och hafver nederbrutit medelbalken, i det att han igenom sitt kött borttog ovänskapen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Nämliga lagen, som i budordom stod; på det han skulle af tvåm skapa ena nya mennisko i sig sjelfvom, och frid göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Och att han skulle försona dem båda med Gudi uti en kropp, genom korset; och hafver dödat ovänskapen genom sig sjelf;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Och är kommen, och hafver igenom Evangelium bådat eder frid, I som fjerran voren; så ock dem som när voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Ty genom honom hafve vi både tillgång uti en Anda till Fadren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Så ären I icke nu mera gäster och främmande; utan helga manna medborgare, och Guds husfolk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Uppbyggde på Apostlarnas och Propheternas grund, der Jesus Christus öfverste hörnestenen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'På hvilken hela byggningen tillhopafogad växer till ett heligt tempel i Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'På hvilken ock I med uppbyggde varden, Gudi till ett hemman, genom Andan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'För denna saks skull är jag Paulus Christi Jesu fånge för eder, Hedningar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Om I eljest hört hafven om Guds nåds ämbete, som mig gifvet är till eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Att denna hemlighet är mig genom uppenbarelse förkunnad, såsom jag tillförene med få ord skref;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Af hvilko, om I det läsen, I mågen märka mitt förstånd i Christi hemlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Hvilket icke kunnigt gjordt är i förtiden menniskors barnom, såsom det nu uppenbaradt är hans heliga Apostlar och Propheter, genom Andan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Nämliga att Hedningarna skola vara medarfvingar, och samma lekamens och hans löftes delaktige i Christo, genom Evangelium;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Hvilkets tjenare jag vorden är, efter den gåfvo af Guds nåd, som mig gifven är, efter hans krafts verkning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mig, som är den aldra ringaste ibland all helgon, är denna nåd gifven, att jag skall ibland Hedningarna förkunna de obegrundeliga Christi rikedomar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Och i ljuset frambära för hvar man, hurudana delaktighet är i den hemlighet, som härtilldags i verldene hafver fördold varit i Gudi, den all ting skapat hafver genom Jesum Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'På det nu skulle kunnigt varda Förstadömen och Herradömen i himmelen, på församlingene, Guds mångfaldeliga vishet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Efter den försyn af verldenes begynnelse, hvilka han bevist hafver i Christo Jesu, vårom Herra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Genom hvilken vi hafve dristighet och tillgång med all förtröstning, genom trona på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Derföre beder jag, att I icke uppgifvens för mina bedröfvelsers skull, som jag lider för eder, hvilka äro eder till pris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Fördenskull böjer jag min knä till vårs Herras Jesu Christi Fader;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Den der rätte Fadren är öfver allt det Fader heter i himmelen och på jordene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Att han ville gifva eder kraft, efter sine härlighets rikedomar, att I starke varden genom hans Anda, till den invärtes menniskan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Att Christus må bo genom trona i edor hjerta, stadeliga rotade och grundade i kärlekenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Att I mågen begripa med all helgon, hvad bredden, och längden, och djupet, och höjden är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Och dermed känna Christi kärlek, den all kunskap öfvergår; på det I mågen uppfyllde varda med allahanda Guds fullhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Men honom, som rikeliga förmår göra, öfver allt det vi bedjom, eller tänkom, efter den kraft som verkar i oss;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Honom vare ära i församlingen, genom Christum Jesum, i allan tid, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Så förmanar jag nu eder, jag fången i Herranom, att I vandren såsom tillbörligit är, i den kallelse, der I uti kallade ären;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Med alla ödmjukhet och saktmodighet; med tålamod, unddragandes den ene den andra i kärlekenom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Vinnläggande eder att hålla Andans enhet genom fridsens band;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'En kropp, och en Ande, såsom I ock kallade ären uti ett edars kallelses hopp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'En Herre, en tro, ett dop, en Gud, och allas våra Fader;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Hvilken är öfver eder alla, genom eder alla, och i eder alla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Men hvarjom och enom af oss är gifven nåd, efter Christi gåfvos mått.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Derföre säger han: Han är uppstigen i höjden, och hafver fört fängelset fånget, och hafver gifvit menniskomen gåfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Men det han uppfaren är, hvad är det annat än han for först härned, uti de nedersta jordenes rum?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Den der nederfor, han är ock den der uppfor öfver alla himlar, på det han skulle all ting uppfylla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Han hafver ock somliga satt till Apostlar, somliga till Propheter, somliga till Evangelister, somliga till herdar och lärare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Att de helige skola skickelige vara till ämbetsens verk, genom hvilket Christi lekamen må uppbyggd varda:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Till dess att vi alle kommom till ena tro, och Guds Sons kunskap, och vardom en fullkommen man, den der är uti Christi fullbordiga ålders mått;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'på det vi icke mer skolom vara barn, och låta oss beveka och omföras af allahanda lärdomsväder, genom menniskors skalkhet och illfundighet, med hvilka de falla till, att de måga bedraga oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Men varom rättsinnige i kärlekenom, och växom till i all stycke i honom, som hufvudet är, Christus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Af hvilkom hele kroppen tillhopafogas, och en lem hänger intill den andra genom all ledamöten, der den ene tjenar dem andra, efter det verk som hvar lem hafver i sitt mått, och gör att kroppen växer sig sjelf till förbättring, genom kärleken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Så säger jag nu, och betygar det i Herranom, att I icke mer vandren såsom de andre Hedningar vandra, i deras sinnes fåfängelighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Hvilkas förstånd förmörkradt är, och de bortkomne ifrå det lif som af Gudi är, genom den fåvitsko som i dem är, och genom deras hjertas blindhet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Hvilke, sedan de vordo förstockade, gåfvo de sig sjelfva uti otukt, till att bedrifva all orenlighet, samt med girighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Men I hafven icke så lärt Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Om I annars honom hört hafven, och uti honom lärde ären, huru ett rättsinnigt väsende är i Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Så lägger nu bort ifrån eder den gamla menniskan, der I förra med umgingen, hvilken genom lustar i villfarelse sig förderfvar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Och förnyer eder i edar sinnes anda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Och ikläder eder den nya menniskona, den efter Gud skapad är, i sannskyldiga rättfärdighet och helighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Derföre, lägger bort lögnen, och taler sanningen, hvar och en med sin nästa; efter vi ärom inbördes lemmar');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Vredgens och synder icke; läter icke solena gå ned öfver edra vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Gifver ock icke lastarenom rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Den der stulit hafver, han stjäle icke mer; utan heldre arbete med sina händer det godt är; på det han något skall hafva dela med den som nödtorftig är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Intet ohöfviskt tal gånge utaf edar mun; utan det nyttigt är till förbättring, der det behöfves; att det må dem, som det höra, till tacka vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Och bedröfver icke Guds Helga Anda der I med beseglade ären till förlossningenes dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'All bitterhet och grymhet, och vrede, och rop, och hädelse vare långt ifrån eder, samt med alla ondsko.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Men varer inbördes till hvarannan vänlige, godhjertige; och förlåter den ene dem andra, såsom ock Gud genom Christum hafver förlåtit eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Så varer nu Guds efterföljare, såsom älskelige barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Och vandrer i kärlekenom, såsom ock Christus hafver älskat oss, och utgifvit sig sjelf för oss till gåfvo och offer, Gudi till en söt lukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Boleri och all slemhet, eller girighet läter ibland eder icke ens nämnda varda, såsom helgon tillhörer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Och slem ord, eller gäckeri, eller skämt som icke höfves; utan heldre tacksägelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Ty I skolen veta, att ingen bolare, eller oren, eller giriger, hvilken är en afgudadyrkare, hafver arfvedel uti Christi och Guds rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Läter eder ingen förföra med fåfäng ord; ty för sådana plägar Guds vrede komma öfver otrones barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Derföre varer icke deras stallbröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Ty I voren fordom mörker, men nu ären I ljus i Herranom; vandrar såsom ljusens barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Ty Andans frukt är uti all godhet, och rättfärdighet, och sanning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Och pröfver hvad Herranom täckt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Och hafver ingen delaktighet med de onyttiga mörksens verk; utan straffer dem heldre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Ty hvad hemliga af dem sker, det är ock skamligit att säga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Men allt detta varder uppenbart, när det af ljuset straffadt varder; ty allt det uppenbart varder, det är ljus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Derföre säger han: Vaka upp, du som sofver, och statt upp ifrå de döda, så varder Christus dig upplysandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Så ser nu till, huru I vandren visliga; icke som de ovise, utan som vise.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Och skicker eder efter tiden; ty tiden är ond.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Derföre, varer icke oförståndige, utan förståndige hvad Herrans vilje är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Och dricker eder icke druckna af vin, af hvilko ett oskickeligit väsende kommer; utan uppfyllens af den Helga Anda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Talande emellan eder i psalmer, och lofsånger, och andeliga visor; sjungandes och spelandes Herranom uti edor hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Alltid tacksägandes Gudi och Fadrenom för hvar man, uti vårs Herras Jesu Christi Namn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Ymsom underdånige, den ene dem andra, i Guds räddhåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Hustrurna vare sina män underdåniga, såsom Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Ty mannen är hustruns hufvud; såsom ock Christus är församlingenes hufvud; och han är ock sins kropps helsa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Såsom nu församlingen är underdånig Christo, så skola ock hustrurna uti all ting vara sina män underdåniga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'I män, älsker edra hustrur, såsom ock Christus älskade församlingen, och hafver utgifvit sig sjelf för henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'På det han henne helga skulle, och hafver gjort henne rena i vattnens bad, genom ordet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'På det han skulle beställa sig sjelf ena församling, den härlig är, den ingen fläck eller skrynko hafver, eller annat sådant; utan att hon skulle vara helig och ostraffelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Så skola ock männerne älska sina hustrur, såsom sina egna kroppar. Den sina hustru älskar, han älskar sig sjelf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Ty ingen hafver någon tid hatat sitt eget kött; utan heldre föder och fordrar det, såsom ock Herren församlingen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Ty vi äre ledamöter af hans kropp, af hans kött, och af hans benom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Fördenskull skall menniskan öfvergifva sin fader och moder, och blifva vid sin hustru, och af tväm varder ett kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Denna hemlighet är stor; men jag talar om Christo och församlingen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Dock ock I, hvar i sin stad, älske sina hustru, såsom sig sjelf; men hustrun hafve mannen i vördning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'I Barn, varer hörige edra föräldrar i Herranom; ty det är rättvist.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Hedra din fader och moder; hvilket är det första bud, som löfte med sig hafver:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'På det dig skall väl gå, och du må blifva långlifvad på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'I fäder, reter icke edor barn till vrede; utan uppföder dem i tukt och Herrans förmaning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'I tjenare, varer hörige edrom lekamligom herrom med räddhåga och bäfvan, i edor hjertas enfaldighet, såsom Christo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Icke tjenande allena för ögonen, såsom menniskom till vilja; utan såsom Christi tjenare, görande det Gud vill utaf hjertat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Med välviljoghet läter eder tycka, att I tjenen Herranom, och icke menniskom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Vetande, att hvad godt hvar och en gör, det skall han igenfå af Herranom, ehvad han är tjenare eller fri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Och I herrar, görer ock detsamma emot dem, och öfvergifver trug; vetande, att ock edar Herre är i himmelen, och för honom är intet anseende till personen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'På det sista, käre bröder, varer starke i Herranom, och i hans starkhets magt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ikläder eder allt Guds harnesk, på det I mågen stå emot djefvulens listiga anlopp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Ty vi hafvom icke strid emot kött och blod; utan emot Förstar och väldiga, nämliga emot verldenes herrar, de som regera i denna verldenes mörker, emot de onda andar under himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Derföre, tager på eder allt Guds harnesk, att I mågen emotstå i den onda dagen, och all ting väl uträtta, och beståndande blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Så står nu omgjordade kringom edra länder med sanningene, och iklädde rättfärdighetenes kräfveto;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Och fötterna skodde, att I mågen redo vara till fridsens Evangelium.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Men öfver all ting tager trones sköld, med hvilkom I kunnen utsläcka all hins ondas glödande skott.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Och tager på eder salighetenes hjelm, och Andans svärd, som är Guds ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'I all bön och åkallan, alltid bedjande i Andanom; och vaker dertill, med all idkelighet, och bön för all helgon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Och för mig, att mig måtte gifvet varda tala dristeliga med öppen mun, att jag måtte kunniga göra Evangelii hemlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Hvilkets bådskap jag är i denna kedjon; på det jag deruti må fri tala, som mig bör tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Men på det I mågen ock veta, huru med oss tillstår, och hvad jag gör, skall Tychicus, min älskelige broder och trogne tjenare i Herranom, eder undervisa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Hvilken jag derföre sände till eder, att I skolen få veta, huru med mig tillstår; och att han skulle trösta edor hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Frid vare bröderna, och kärlek med trone, af Gud Fader och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Nåd vare med allom, som vår Herra Jesum Christum rättsinneliga kär hafva. Amen. Sänd af Rom till de Epheser, med Tychico.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus och Thimotheus, Jesu Christi tjenare, allom heligom i Christo Jesu, som äro i Philippis, samt med Biskopar och tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Jag tackar min Gud, så ofta jag tänker på eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Hvilket jag alltid gör i alla mina böner för eder alla, och gör samma bön med glädje;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Att I ären delaktige vordne i Evangelio, ifrå första dagen intill nu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Och förser mig detsamma, att den uti eder ett godt verk begynt hafver, han skall det ock fullborda, intill Jesu Christi dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Såsom mig rätt är, att jag den meningen hafver om eder alla; derföre att jag i minom bojom, i hvilkom jag försvarar och stadfäster Evangelium, hafver eder i mitt hjerta, såsom de der alle med mig delaktige ären i nådene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Ty Gud är mitt vittne, huru jag åstundar eder alla af hjertans grund i Jesu Christo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Och beder, att edar kärlek ju mer och mer må rik varda i all kunskap, och i allt förstånd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Att I mågen bepröfva hvad bäst är; på det I mågen vara rene, och ingom till förargelse, intill Christi dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Uppfyllde med rättfärdighetenes frukt, hvilken genom Jesum Christum kommer till Guds pris och lof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Jag vill att I veta skolen, käre bröder, att det med mig skedt är, det är mer kommet Evangelio till framgång;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Så att mina bojor äro uppenbara vordna i Christo, öfver hela Rådhuset, och när alla andra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Och att månge bröder i Herranom, styrkte af minom bojom, äro dess dristigare vordne till att tala ordet utan räddhåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Somlige predika ock Christum för afunds och trätos skull, och somlige uti en god mening.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'De förre predika Christum af kif, och icke renliga; menandes dermed föröka bedröfvelsen till mitt fängelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Men de sednare af kärlek, vetandes att jag här ligger till Evangelii försvarelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Hvad äret då? Att ju Christus förkunnad varder, i hvad måtto det ske kan, antingen af tillfälle, eller sannskyldeliga; deraf fröjdar jag mig, och jemväl fröjda vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Ty jag vet, att det kommer mig till salighet, genom edra bön, och Jesu Christi Andas tillhjelp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Såsom jag visserliga väntar och förhoppas, att jag uti ingen ting skall till blygd komma; utan med all frihet, såsom alltid, så ock nu, måtte Christus afhållen varda i minom lekamen, ehvad det är genom lif, eller genom död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Ty Christus är mitt lif, och döden är min vinning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Men efter det, att lefva i köttet, tjenar mer till att göra frukt, så vet jag icke hvilket jag utvälja skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ty både delarne ligga mig hårdt uppå. Jag åstundar skiljas hädan, och vara när Christo; hvilket ock mycket bättre vore;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Men det är mer nödtorftigt blifva i köttet för edra skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Och vet jag visserliga, att jag skall blifva, och med eder allom vara, eder till godo, och till trones fröjd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'På det I mågen storliga berömma eder af mig i Christo Jesu, genom min igenkommelse till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Allenast vandrer såsom Christi Evangelio värdt är; att hvad jag heldre kommer och får eder se, eller frånvarandes får höra om eder, att I blifven ståndande uti enom anda och ene själ, samt med oss kämpande uti Evangelii tro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Och uti ingen ting förskräcken eder för edra motståndare, hvilket dem är ett tecken till förtappelse; men eder till salighet, och det af Gudi!');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Ty eder är gifvet för Christo, icke allenast att I tron på honom, utan jemväl liden för hans skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Hafvande samma stridena, som I sågen i mig, och I nu hören om mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Är nu någor förmaning när eder i Christo; är någor tröst i kärlekenom; är någor Andans delaktighet; är någor hjertelig kärlek och barmhärtighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Så, uppfyller mina glädje, att I ären ens till sinnes, lika kärlek hafvande, endrägtige, samhällige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Att intet sker med kif eller fåfäng äro; utan med ödmjukhet räkne hvar den andra yppare än sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ser icke hvar på sitt eget bästa, utan hvar och en på ens annars bästa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Hvar och en vare så till sinnes, som ock Christus Jesus var;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Hvilken, ändå han var i Guds skepelse, räknade han icke för rof Gudi jemlik vara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Utan förnedrade sig sjelf, tagandes på sig en tjenares skepelse, och vardt lika som en annor menniska, och i åthäfvor funnen som en menniska;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Ödmjukade sig sjelf; vardt lydig intill döden, ja, intill korsens död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Derföre hafver ock Gud förhöjt honom, och gifvit honom ett Namn, det öfver all namn är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Att i Jesu Namn skola sig böja all knä, deras som i himmelen, på jordene, och under jordene äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Och alla tungor skola bekänna, att Jesus Christus är Herren, Gud Fader till äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Så, mine älskelige, som I alltid hafven varit lydige, icke allenast i mine närvaro, utan ock nu mycket mer i mine frånvaro, skaffer med fruktan och bäfvan, att I salige varden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Ty Gud är den som verkar i eder både vilja och gerning, efter sitt goda behag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Görer all ting utan knorr och tvekan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'På det I mågen vara oförtalade och rene, och Guds barn ostraffelige, midt ibland det vanartiga och vrånga slägtet; ibland hvilka lyser såsom ljus i verldene;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Att I blifven vid lifsens ord, mig till en berömmelse på Christi dag, att jag icke fåfängt lupit, eller fåfängt arbetat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Och om jag än offras öfver edra tros offer och Gudstjenst, så gläder jag mig, och fröjdar mig med eder alla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'För det sammas skull skolen I ock glädjas, och skolen glädjas med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Men jag hoppas i Herranom Jesu, att jag innan kort varder sändandes till eder Timotheum; att jag ock må varda vid ett godt mod, då jag förnimmer huru med eder tillstår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Ty jag hafver ingen, den som så alldeles lika med mig till sinnes är, den så hjerteliga omsorg hafver för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Ty de söka alle efter sitt eget, icke det Christo Jesu tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Men I veten, att han bepröfvad är; ty såsom ett barn med fadrenom, hafver han med mig tjent uti Evangelio.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Honom hoppas mig nu sända, det första jag hafver besett min ärende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Jag tröstar ock på Herran, att jag ock sjelf snart kommandes varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Mig hafver ock synts nödtorftigt vara sända till eder Epaphroditum, brödren, min medhjelpare och medstridare, och edar Apostel, den ock mig uti mine nödtorft tjenar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Efter han hade en åstundan till eder alla, och var storliga bekymrad deraf, att I sport haden honom krankan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Som han ock visserliga var dödssjuk; men Gud förbarmade sig öfver honom; och icke allenast öfver honom, utan ock öfver mig, att jag icke skulle få sorg på sorg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Jag hafver nu sändt honom dess snarare, att I skolen få se honom, och dess gladare varda igen, och jag dess mindre sorg hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Så undfår nu honom i Herranom med alla glädje; och de sådane äro, dem hafver i vördning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Ty för Christi verks skull var han dödenom så när kommen, att han fögo tänkte på lifvet; på det han skulle tjena mig i edar stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Ytterligare, mine bröder, fröjder eder i Herranom. Att jag eder ju allt detsamma skrifver, det förtryter mig intet; men det gör eder dess vissare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Vakter eder för de hundar, vakter eder för de onda arbetare, vakter eder för afskärelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Ty vi äre omskärelsen, vi som tjene Gudi i Andanom, och berömmom oss af Christo Jesu, och sättom icke tröst på köttet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Ändock jag ock väl må trösta på köttet. Hvar en annar sig tycka låter, att han må förtrösta sig på köttet, jag mycket mer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Som på åttonde dagen omskoren är, en af Israels folk och Benjamins slägte, en Ebree af Ebreer, efter lagen en Pharisee;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Efter nitet förföljandes församlingen, efter den rättfärdighet, som är af lagen, ostraffelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Men det mig en vinning var, det hafver jag räknat för skada, för Christi skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Ja, jag räknar det allt för skada emot den öfver svinnleliga mins Herras Christi Jesu kunskap; för hvilkens skull jag allt hafver för skada räknat, och håller det för träck, på det jag må vinna Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Och varda funnen i honom, icke hafvandes mina rättfärdighet, som kommer af lagen, utan den som af Christi tro kommer; nämliga den rättfärdighet, som af Gudi kommer genom trona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Till att känna honom, och hans uppståndelses kraft, och hans pinos delaktighet, lik vorden hans död;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Om jag ock måtte komma emot honom i de dödas uppståndelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Icke att jag allaredo hafver det fattat, eller allaredo fullkommen är; men jag far fast der efter, om jag det ock fatta må, som jag ock fattad är af Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Käre bröder, jag kan icke säga, att jag ännu sjelf det fattat hafver; men ett säger jag: Jag förgäter det till rygga är, och sträcker mig till det som frammantill är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Jagandes efter målet, som föresatt är, till den lön som förehålles ofvanefter, af Guds kallelse i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Så månge vi nu fullkomne äre, varom så sinnade; och om I något annorlunda hålla skolen, så låter Gud eder det uppenbara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Dock så, att vi uti det, der vi allaredo tillkomne äre, vandrom efter ena reglo, och äre ens sinnade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Varer ock, käre bröder, mine efterföljare, och ser på dem som så vandra, som I oss för en efterdömelse hafven.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Ty månge vandra, af hvilkom jag eder ofta sagt hafver, men nu säger jag ock gråtandes, fiendar till Christi kors;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Hvilkas ände är förtappelse, och deras buk deras Gud, och deras ära till skam, de der akta hvad jordena tillhörer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Men vår umgängelse är i himmelen, dädan vi ock vänte Frälsaren, Herran Jesum Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Hvilken vår skröpliga lekamen skall förklara; på det han skall göra honom lik med sinom förklarada lekamen, af den kraft der han med förmår sig all ting underlägga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Så, mine käre och önskade bröder, min fröjd och min krona, blifver så ståndande i Herranom, mine älskelige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evodiam förmanar jag, och Syntychen förmanar jag, att de äro ens till sinnes i Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, jag beder ock dig, min rättsinniga make, var dem behjelpelig, som med mig öfver Evangelium stridt hafva, samt med Clement, och andra mina medarbetare, hvilkas namn äro uti lifsens bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Fröjder eder i Herranom alltid; och åter säger jag: Fröjder eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Edor saktmodighet låter allom menniskom kunnoga varda. Herren är när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Hafver ingen omsorg; utan edart begär vare kunnigt inför Gud, i all ting, med bön, åkallan, och tacksägelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Och Guds frid, som öfvergår allt förstånd, förvare edor hjerta, och edart sinne, i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Yttermera, käre bröder, hvad sant är, hvad ärligit är, hvad rätt, hvad kyskt, hvad ljufligit, hvad väl lyder; är någor dygd, och är något lof, tänker derefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Hvad I ock lärt, och undfått, och hört, och sett hafven på mig, det görer; och så varder fridsens Gud med eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Men jag är storliga fröjdad i Herranom, att I ären åter komne dertill, att I hafven omsorg om mig; ändock I väl allstädes omsorg haft hafven; men tiden sade icke så till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Detta säger jag icke derföre, att mig något fattas; ty jag hafver lärt, ibland dem jag umgår, låta mig nöja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Jag kan låg vara; jag kan ock hög vara; allestäds och i all ting är jag skickelig, både mätt och hungrig vara, både nog hafva och nöd lida.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'All ting förmår jag, genom Christum, som mig mägtigan gör.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Dock hafven I rätt gjort, att I hafven tagit eder min bedröfvelse till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Veten I ock väl, I Philipper, att af första Evangelii begynnelse, då jag drog utu Macedonien, ingen församling hafver något delat med mig, efter räkenskap, i utgift och uppbörd, utan I allena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Ty I sänden ena reso, och så andra, till mig i Thessalonica, till min nödtorft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Icke att jag söker sådana skänker; utan söker derefter, att uti edar räkenskap skall en öfverflödig frukt finnas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Ty jag hafver allt, och öfverflödar, och är uppfylld, sedan jag undfick, med Epaphroditus, det som ifrån eder sändt var, en söt lukt, ett offer, Gudi täckt och anammeligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Men min Gud skall eder uppfylla alla edra nödtorft, efter sina rikedomar i härlighetene, genom Christum Jesum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Men Gudi och vårom Fader vare pris af evighet till evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Helser all helgon i Christo Jesu. Eder helsa de bröder, som med mig äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Eder helsa all helgon, enkannerliga de, som äro utaf Kejsarens hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen. Skrifven af Rom, med Epaphrodito.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, och Timotheus brodren;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'De helgon, och trogna bröder i Christo, som äro i Colossen: Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Vi tackom Gudi, och vårs Herras Jesu Christi Fader, och bedjom alltid för eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Ty vi hafve sport edra tro i Christo Jesu, och (edar) kärlek till all helgon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'För det hopps skull, som eder är förvaradt i himmelen; af hvilket I tillförene hört hafven, genom Evangelii sanna ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Som till eder kommet är, såsom ock i alla verldena, och är fruktsamt, såsom ock i eder, ifrå den dag I hörden och förnummen Guds nåd i sanningene,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Som I ock lärt hafven af Epaphra, vår älskeliga medtjenare, hvilken är en trogen Christi tjenare för eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Den ock oss undervist hafver edar kärlek i Andanom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Derföre ock vi, ifrå den dag vi det hördom, vände vi icke igen bedja för eder och önska, att I mågen uppfyllde varda med hans viljas kunskap, uti all andelig visdom och förstånd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Att I mågen vandra värdeliga Herranom till allt behag; och ären fruktsamme i alla goda gerningar, och växen till i Guds kunskap;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Och stärkte varden med allo kraft, efter hans härliga magt, uti allt tålamod och långmodighet, med glädje;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Och tacken Fadrenom, som oss hafver beqväma gjort till att delaktige vara i de heligas arfvedel i ljuset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Hvilken oss uttagit hafver ifrå mörksens väldighet, och hafver försatt oss uti sin älskeliga Sons rike;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'I hvilkom vi hafve förlossning genom hans blod, nämliga syndernas förlåtelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Hvilken är osynliga Guds beläte, förstfödder för all kreatur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Ty genom honom äro all ting skapade, som i himmelen och på jordene äro, synliga och osynliga, vare sig thron, eller herrskap, eller Förstadöme, eller Öfverhet; allt är skapadt genom honom, och till honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Och han är för alla, och all ting bestå i honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Och han är hufvudet till kroppen, nämliga till församlingena, hvilken är begynnelsen, förstfödd ifrå de döda, på det han i all ting skall hafva föregången.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Ty behageligit hafver varit (Fadrenom), att all fullhet skulle bo i honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Och att han genom honom all ting försona skulle med sig sjelf; till frids ställandes, genom blodet på hans kors, både det på jordene och i himmelen är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Och eder, som fordom voren främmande, och fiender med sinnet i onda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Men nu hafver han försonat eder med sins kötts lekamen, genom döden; på det han skulle ställa eder heliga, och ostraffeliga, och obesmittade, i sin åsyn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Om I annars blifven i trone, grundade, och faste, och orörlige ifrå det hopp som i Evangelio är, hvilket I hört hafven, och predikadt är för all kreatur, som under himmelen äro, hvilkets jag Paulus är en tjenare vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nu fröjdar jag mig uti mitt lidande för eder, och uppfyller i mitt kött hvad som fattas i Christi lidande, för hans lekamen, som är församlingen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Hvilkens tjenare jag vorden är, efter Guds predikoämbete, det mig gifvet är ibland eder, att jag Guds ord rikeliga predika skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Nämliga den hemlighet, hvilken fördold hafver varit ifrå verldenes begynnelse, och evig tid; men nu är uppenbar vorden hans helgon;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Hvilkom Gud ville kunnigt göra, hvilken denna hemlighetenes härliga rikedom är ibland Hedningarna, hvilken är Christus uti eder, härlighetenes hopp;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Den vi förkunnom, förmanande hvar menniska i all visdom; på det vi skole ställa hvar menniska fullbordada i Christo Jesu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Der jag ock på arbetar och kämpar, efter hans verkan som krafteliga verkar i mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Så vill jag att I veta skolen, hvilken kamp jag hafver om eder, och om dem som äro i Laodicea, och om alla dem som min person i köttet icke sett hafva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'På det deras hjerta måga få någon hugnad, och sammanfogade varda i kärlekenom, till all rikedom uti fullkomligit förstånd, till att kunna besinna Guds hemlighet, både Fadrens och Christi;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Uti hvilkom fördolda ligga alla visdoms och förstånds häfvor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Men detta säger jag, på det ingen skall bedraga eder med klok ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Ty ändock jag är ifrån eder efter köttet, är jag dock när eder i Andanom, fröjdar mig, och ser edor skickelse, och edar tros stadighet på Christum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Såsom I nu anammat hafven Herran Christum Jesum, så vandrer i honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Och varer rotade och uppbyggde i honom, och varer faste i trone, såsom I lärde ären, och varer i henne rikeliga tacksamme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Ser till, att eder icke någor bortröfvar med Philosophia och fåfängt bedrägeri, efter menniskors stadgar, och efter verldenes stadgar, och icke efter Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Ty i honom bor all Gudomsens fullhet lekamliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Och I ären i honom fullkomne, hvilken är hufvudet öfver all Förstadöme och väldighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'I hvilkom I ock omskorne ären med den omskärelse, som sker utan händer, då I afladen syndakroppen i köttet, nämliga med Christi omskärelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'I det, att I med honom begrafne ären genom dopet; i hvilkom I ock uppståndne ären genom trona, den Gud verkar, hvilken honom uppväckt hafver ifrå de döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Han hafver ock gjort eder lefvande med honom, då I döde voren i synderna, och uti edars kötts förhud; och hafver förlåtit oss alla synder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Och afplånat den handskrift, som oss emot var; hvilken af stadgarna kom, och var oss emot; och den hafver han tagit oss af vägen, och naglat vid korset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Och hafver blottat Förstadömen, och väldigheterna, och fört dem uppenbarliga, och gjort en härlig seger af dem, genom sig sjelf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Så låter nu ingen göra eder samvet öfver mat, eller dryck, eller öfver bestämda helgedagar, eller nymånader, eller Sabbather;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Hvilket är skuggen af det som tillkommande var; men kroppen sjelf är i Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Låter ingen taga eder lönen ifrå, den som vandrar efter egen godtycko i Änglaödmjukhet och andelighet, i de ting han aldrig sett hafver, och är förgäfves uppblåst i sitt köttsliga sinne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Och håller sig icke vid hufvudet, af hvilko hele lekamenen genom leder och ledamot kraft får och tillsammans hänger, och tillväxer i den förökelse som Gud gifver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Efter I nu döde ären med Christo, ifrå de verldsliga stadgar; hvi låten I eder då begripas med beskrefna stadgar, lika som I ännu lefden i verldene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'De der säga: Du skall icke komma vid det; icke smaka det; icke handtera det;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Hvilket dock allt förgås i brukningene, och är efter menniskors bud och lärdom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Hvilke hafva väl ett sken af visdom, genom sjelftagen andelighet och ödmjukhet, och derigenom att de icke skona kroppen, och göra icke köttena dess äro till dess nödtorft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Om I nu ären uppståndne med Christo, så söker det ofvantill är, der Christus är sittandes på Guds högra hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Farer efter det som ofvantill är, icke efter det som på jordene är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Ty I ären döde, och edart lif är fördoldt med Christo i Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Men när edart lif, Christus, uppenbarad varder, då varden ock I uppenbarade med honom i härligheten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'så döder nu edra lemmar, som på jordene äro; boleri, orenlighet, lusta, ond begärelse och girighet, hvilken afgudadyrkan är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'För hvilka styckers skull Guds vrede kommer öfver otrones barn;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Uti hvilka I ock fordom vandraden, då I deruti lefden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Men lägger ock nu I bort alltsammans, vrede, grymhet, ondsko, försmädelse, skamlig ord, af edar mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ljuger icke för hvarannan; afkläder eder den gamla menniskan med hans gerningar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Och ikläder eder den nya, den der förnyas till hans kunskap och beläte, som honom skapat hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Der icke Grek och Jude är, omskärelse och förhud, Barbarisk och Scytisk, tjenare och fri, utan allt i allom Christus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Så kläder eder nu såsom Guds utkorade, helgon och älskelige, uti hjertans barmhertighet, vänlighet, ödmjukhet, saktmodighet, långmodighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Och unddrager hvarannan, och förlåter hvarandrom, om någor hafver någon klagomål emot den andra; såsom ock Christus eder förlåtit hafver, så görer ock I.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Men öfver allt detta ikläder eder kärleken, hvilken är fullkomlighetenes band.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Och Guds frid regere i edor hjerta, till hvilken I ock kallade ären uti en lekamen; och varer tacksamme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Låter Christi ord rikeliga bo uti eder med all visdom; lärer och förmaner eder inbördes med Psalmer och lofsånger, och andeliga visor i nådene, och sjunger Herranom i edart hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Och allt det I gören, med ord eller gerning, det görer allt i Herrans Jesu Namn, och täcker Gudi och Fadrenom genom honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'I hustrur, varer edra män underdåniga, såsom tillbörligit är, i Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'I män, älsker edra hustrur, och varer icke bittre emot dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'I barn, varer edra föräldrar lydige i all ting; ty det täckes väl Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'I fäder, reter icke edor barn; på det de icke skola vara klenmodige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'I tjenare, varer lydige edra köttsliga herrar i all ting; icke med tjenst för ögonen, såsom menniskom till vilja, utan med hjertans enfaldighet, och med Gudsfruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Allt hvad I gören, det görer af hjertat, såsom Herranom, och icke menniskom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Och veter, att I af Herranom skolen få arfsens lön; ty I tjenen Herranom Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Men den som orätt gör, han skall undfå hvad han orätt gjort hafver; och varder intet anseende till personen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'I herrar, hvad lika och rätt är, det beviser tjenaromen; vetande, att I hafven ock en Herra i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Håller uppå bedja, och vaker deruti med tacksägelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Bedjande också för oss, att Gud ville upplåta oss ordsens dörr, till att tala Christi hemlighet, för hvilket jag ock bunden är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Att jag må det uppenbara, såsom mig bör att tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Vandrer visliga med dem som utantill äro, och skicker eder efter tiden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Edart tal vare alltid ljufligit, och med salt förmängdt, att I veten huru I skolen svara hvarjom och enom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Huru med mig går, skall Tychicus, min älskeliga broder, och trogne tjenare och medtjenare i Herranom, eder allt kungöra;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Hvilken jag hafver till eder sändt fördenskull, att han skall få veta, huru det hafver sig med eder, och att han må hugsvala edor hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Samt med Onesimo, minom trogna och älskeliga broder, hvilken en af eder är; de skola eder undervisa allt, huru här tillstår.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Helsar eder Aristcarchus, min medfånge, och Marcus, Barnabe syssling, af hvilkom I hafven fått några befallningar; kommer han till eder, så undfår honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Och Jesus, som kallas Justus, hvilke äro af omskärelsen; desse äro allena mine medhjelpare till Guds rike, de mig ock varit hafva till hugnad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Helsar eder ock Epaphras, den en af eder är, Christi tjenare, alltid arbetandes för eder i böner, på det I mågen blifva ståndande fullkomlige, och uppfyllde i all Guds vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Jag bär vittnesbörd med honom, att han hafver mycken omsorg om eder, och dem i Laodicea, och dem i Hierapoli.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Helsar eder Lucas, läkaren, den älskelige, och Demas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Helser de bröder i Laodicea, och Nympham, och den församling, som i hans hus är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Och då Epistelen är läsen när eder, så beställer att han varder ock läsen för den församling i Laodicea; och att I ock den Laodiska Epistelen läsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Och säger Archippo: Se på ämbetet, som du fått hafver i Herranom, att du det uträttar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Mina helsning med mine Pauli hand. Tänker på mina bojor. Nåd vare med eder. Amen. Skrifven af Rom, med Tychico och Onesimo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus, och Silvanus, och Timotheus: Den församling i Thessalonica, uti Gud Fader, och HERranom JEsu Christo: Nåd ware med eder, och frid af Gudi, wårom Fader, och HERranom JEsu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Wi tackom Gudi alltid för eder alla, och hafwom eder i åminnelse i wåra böner, utan återwändo:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Tänkande på edart werk i trone, och på edart arbete i kärleken, och på edart tålamod i hoppet, hwilket är wår HERre, JEsus Christus, för Gudi och wårom Fader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Ty, käre bröder, af Gudi älskade, wi wete, huru I ären utwalde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'At wårt Ewangelium hafwer warit när eder, icke allenast med ordom, utan både i kraft, och i den Helga Anda, och i fulla wisshet, såsom I weten, hurudane wi worom när eder, för edra skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Och I ären wordne wåre efterföljare, och HERrans; och hafwen anammat ordet ibland mång bedröfwelse, med den Helga Andas fröjd:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Så at I ären wordne en efterdömelse allom trognom uti Macedonia och Achaja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Ty af eder är HERrans ord utgånget, icke allenast i Macedonia, och Achaja; utan ock i all rum är edor tro, som I hafwen til Gud, utkommen; så at oss är icke behof at säga något.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ty de sjelfwe förkunna om eder, hurudana ingång wi hadom til eder; och huru I omwände worden til Gud ifrån afgudarna, til at tjena den lefwande och sanna Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Och til at wänta hans Son af himmelen, hwilken han upwäckt hafwer ifrå de döda, JEsum, den oss frälsar ifrå den tilkommande wrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Käre bröder, I weten sjelfwe wår ingång til eder, at han war icke fåfäng:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Utan, såsom wi tilförene hade lidit, och försmådde warit uti Philippis, som I veten, worom wi ändå wid god tröst i wårom Gud, til at tala när eder Guds Ewangelium, med mycken kämpning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Ty wår förmaning war icke til willfarelse, icke heller til orenlighet, icke heller med list:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Utan, såsom wi af Gudi bepröfwade worom, at oss Ewangelium betrodt är til at predika, så talom wi: icke såsom wi wille täckas menniskom, utan Gudi, den der pröfwar wår hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Ty wi hafwe icke umgått med smekligom ordom, såsom I weten, icke heller med tilfälle til girighet; Gud är dess wittne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Hafwom icke heller sökt pris af menniskom, hwarken af eder, eller androm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Ändock wi wäl hadom haft magt at förtunga eder, såsom Christi Apostlar; men wi worom milde när eder, lika som en amma fostrar sin barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Så hafwom wi hjertans lust haft til eder, at dela med eder, icke allenast Guds Ewangelium, utan ock wårt eget lif; ty I ären oss käre wordne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'I minnens wäl, käre bröder, wårt arbete och wår mödo; ty dag och natt arbetade wi, på det wi ingen af eder skulle förtunga; och predikadom ibland eder Guds Ewangelium.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Dess ären I wittne, och Gud, huru heliga, huru rättfärdeliga och ostraffeliga wi umgingom med eder, som trodden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Såsom I weten, at wi, såsom en fader sin barn, hafwe förmanat och tröstat hwar och en ibland eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Och betygat, at I wärdeliga skullen wandra för Gudi, den eder kallat hafwer til sitt rike och härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'För hwilket wi ock utan återwändo tackom Gudi, at då I anammaden af oss det predikade ordet om Gud, anammaden I det icke såsom menniskors ord, utan såsom det sannerliga är, som Guds ord, hwilken ock werkar i eder, som tron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ty I ären wordne, käre bröder, de Guds församlingars efterföljare, som uti Judeen äro, i Christo JEsu, at I detsamma lidit hafwen af edra egna fränder, som de af Judomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Hwilke ock HERran JEsum dråpo, och sina egna Propheter, och hafwa förföljt oss, och täckas icke Gudi, och allom menniskom äro de emot:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Förbjuda oss underwisa Hedningomen, dermed de skola salige warda, på det de skola fullkomna sina synder alltid; ty wreden är kommen öfwer dem intil ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Men wi, käre bröder, sedan wi til någon tid hade mist eder efter ansigtet, och icke efter hjertat, hafwe wi dess mer hastat til at se edart ansigte, med stor begärelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Derföre hadom wi welat komma til eder, (jag Paulus) twå resor; och Satanas hafwer oss förhindrat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Ty hwad är wårt hopp, eller fröjd, eller kronan til wår berömelse? Ären ock icke I det, för warom HERra JEsu Christo i hans tilkommelse?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'I ären ju wår pris och fröjd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Derföre kundom wi icke längre hafwat fördrag; och oss syntes, at wi uti Athen allena skulle qware blifwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Och hafwe sändt Timotheum, wår broder, och Guds tjenare, och wår hjelpare i Ewangelio Christi, til at styrka och trösta eder i edra tro:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'På det ingen skulle låta wika sig uti denna bedröfwelse; ty I weten, at wi ärom dertil satte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Ty när wi worom när eder, sade wi eder det tilförene, at wi måste lida bedröfwelse; såsom ock skedt är, och I weten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Derföre kunde jag ock icke länger hafwat fördrag, utan sände åstad; på det jag skulle förfara edra tro, at til äfwentyrs frestaren icke hade försökt eder, och wårt arbete hade då fåfängt wordit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Men nu nyliga, sedan Timotheus kommen war til oss ifrån eder, och underwiste oss edra tro och kärlek; och at I alltid tänken på oss til det bästa, och åstunden at se oss, såsom ock wi eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Wordom wi, käre bröder, hugswalade på eder, uti all wår bedröfwelse och nöd, genom edra tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Ty wi lefwe nu, efter I stån i HERranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Hwad tack kunne wi Gudi säga för eder. för all den glädje, som wi hafwe af eder, för wår Gud?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'wi bedje dag och natt ganska mycket, at wi mågom se edart ansigte, och upfylla det i edra tro fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Men Gud sjelfwer, och wår Fader, och wår HERre JEsus Christus, skicke wår wäg til eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Men HERren föröke eder, och låte kärleken öfwerflöda inbördes och til hwar man; såsom ock wi äre til eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'At edor hjerta måga styrkt och ostraffelig blifwa, i helighet, för Gudi och wårom Fader, uti wårs HERras JEsu Christi tilkommelse, med all hans helgon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Yttermera, käre bröder, bedje wi eder, och förmane genom wår HERra JEsum, såsom I hafwen undfångit af oss, huru I wandra skolen, och täckas Gudi, at I ju mer fullkomlige warden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Ty I weten hwad bud wi gåfwom eder, genom HERran JEsum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Ty deta är Guds wilje, edor helgelse, at I flyn boleri:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Och hwar och en af eder wet behålla sitt fat i helgelse och äro:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Icke uti lustig begärelse, såsom Hedningar, de som af Gudi intet weta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Och at ingen förtrycker eller swiker sin broder i någon handel; ty HERren är hämnaren öfwer allt deta; såsom wi ock eder tilförene sadom och betygadom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Ty Gud hafwer icke kallat oss till orenlighet, utan til helgelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Den der nu föraktar, han föraktar icke någon mennisko, utan Gud, den sin Helga Anda hafwer gifwit i eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Men om broderlig kärlek görs icke behof, at jag skrifwer eder; ty I ären sjelfwe lärde af Gudi, at I skolen älska eder inbördes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Och det gören I ock på alla bröderna, som i hela Macedonien äro; men wi förmane eder, käre bröder, at I ju mer fullkomlige warden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Och winlägger eder, at I ären rolige, och sköter edor egen stycke; och arbeter med edra händer, såsom wi eder budit hafwe:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'At I hafwen eder ärliga med dem, som utantil äro, och at I deras intet betorfwen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Men wi wilje icke dölja för eder, käre bröder, om dem som afsomnade äro, at I icke sörjen, såsom de andre, de der intet hopp hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Ty om wi tro, at JEsus är döder och upstånden; så skall ock Gud dem som afsomnade äro, genom JEsum framhafwa med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Ty detta säge wi eder, såsom HERrans ord; at wi som lefwe och igenblifwe uti HERrans tillkommelse, skole icke förekomma dem som sofwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Ty sjelfwer HERren skall stiga ned af himmelen med härskri, och öfwerängels röst, och med Guds basun, och de döde i Christo skola upstå i förstone:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Derefter wi som lefwe och igenblifwe, wardom tillika med dem borttagne i skyn emot HERran i wädret, och så skole wi blifwa när HERranom alltid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Så tröster eder nu med dessa orden inbördes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Men om tider och stunder, käre bröder, är icke behof at skrifwa eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Ty I weten wäl, at HERrans dag skall komma såsom en tjuf om nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Derföre, när de warda sägande: Det är frid, och all ting utan fara, då skall dem hasteligit förderf öfwerkomma; lika som födslopinan qwinnone påkommer, som hafwandes är, och de skola icke kunna undfly.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Men I, käre bröder, ären icke uti mörkret, at den dagen, såsom en tjuf, skall få eder fatt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Alle I ären ljusens barn, och dagsens barn; wi hörom icke nattene til, icke heller mörkret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Så låter oss nu icke sofwa, såsom de andre; utan låter oss waka och nyktre wara;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Ty de som sofwa, de sofwa om nattene, och de som druckne äro, de äro druckne om nattene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Men wi, som dagen tilhöre, skole nyktre wara, iklädde trones och kärlekens kräfweto, och salighetenes hopp för en hjelm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Ty Gud hafwer icke satt oss til wrede, utan at äga salighet, genom wår HERra JEsum Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Den för oss död är; på det, ehwad wi wake eller sofwe, skole wi lefwa samt med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Derföre förmaner eder inbördes; och upbygger hwar den andra, såsom I ock gören.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Men wi bedje eder, käre bröder, at I kännen dem som arbeta ibland eder, och stå eder före i HERranom, och förmana eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Håller dem dess kärare, för deras werks skull, och warer fridsamme med dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Men wi bedje eder, käre bröder, förmaner de osediga, tröster de klenmodiga, hjelper de swaga, warer långmodige wid hwar man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Ser til, at ingen wedergäller någrom ondt för ondt; utan alltid farer efter det goda inbördes, och med hwar man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'warer alltid glade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Bedjen utan återwändo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'warer tacksamme i all ting; ty det är Guds wilje om eder, genom JEsum Christum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Utsläcker icke Andan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Förakter icke Prophetier.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Men pröfwer all ting, och behåller det godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Flyr allt det som ondt synes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Men sjelfwer fridsens Gud helge eder öfwer allt, at edar hele ande, och själ, och kropp, måtte wara behållen utan straff, i wårs HERras JEsu Christi tilkommelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Han är trofast, som eder kallat hafwer; den det ock wäl fullbordar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Käre bröder, beder för oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Helser alla bröderna uti en helig kyss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Jag beswär eder wid HERran, at I denna Epistelen läsa låten för alla heliga bröderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Wårs HERras JEsu Christi nåd ware med eder. Amen. Til de Thessalonicer den förra, skrifwen af Athen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus, och Silvanus, och Timotheus; den församling i Thessalonica, i Gudi, wårom Fader, och HERranom JESu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Nåd ware med eder, och frid af Gudi wårom Fader, och HERranom JESu Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Wi skole tacka Gudi alltid för eder, käre bröder, såsom tilbörligit är; ty edor tro förökas storliga, och allas edra kärlek öfwerflödar inbördes:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Så at wi sjelfwe beröme oss i Guds församlingar, af edart tålamod och tro, uti alla edra förföljelser och bedröfwelser, som I liden:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Såsom et bewis til Guds rättwisa dom; på det I mågen warda wärdige til Guds rike, för hwilket I ock liden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Efter det är rättwist för Gudi gifwa dem bedröfwelse igen, som eder bedröfwa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Men eder, som bedröfwens, rolighet med oss; då HERren JESus upenbar warder af himmelen, samt med sine krafts Änglar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Och med eldslåga, til at hämnas öfwer dem som icke känna Gud, och öfwer dem som icke lydige äro wårs HERras JESu Christi Evangelio:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Hwilke pino lida skola, det ewiga förderfwet, af HERrans ansikte, och af hans härliga magt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Då han skall komma, til at förklaras i sin helgon, och underlig warda i allom dem som tro; ty wårt wittnesbörd til eder om den dagen hafwen I trott.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Och fördenskull bedje wi ock alltid för eder, at wår Gud wille göra eder wärdiga til denna kallelsen, och upfylla allt godhetenes upsåt, och trones werk i kraftene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'På det wårs HERras JESu Christi Namn må prisadt warda på eder, och I på honom, efter wår Guds och HERrans JESu Christi nåd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Men wi bedje eder, käre bröder, för wårs HERras JESu Christi tilkommelse, och för wåra församlings skull i honom:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'At I icke snarliga låten beweka eder ifrån edart sinne; icke heller förskräcka, hwarken genom anda, eller genom ord, eller genom bref, lika som det sändt wore af oss, såsom Christi dag för handen wore.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Låter ingen förföra eder i någon måtto; ty han kommer icke, utan tilförene sker affall, och uppenbar warder syndenes menniska, förtappelsens barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Hwilken är en motståndare, och uphäfwer sig öfwer allt det Gud eller Gudstjenst kallas; så at han sätter sig i Guds tempel, såsom en Gud, och gifwer sig före som han wore Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Minnens I icke, at jag sade eder detta, då jag ännu war när eder?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Och hwad ännu hindrar, weten I; at han skall warda upenbar i sin tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Ty han werkar allaredo ondskona hemliga; allenast den der nu hindrar, han måste komma af wägen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Och så warder då den Onde upenbar, hwilken HERren skall dräpa med sins muns Anda; och skall göra en ända med honom, genom sin tilkommelses upenbarelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Hwilkens tilkommelse sker efter Satans werkan, med alla lögnaktiga krafter, och tekn, och under:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Och med all förförelse til orättfärdighet, ibland dem som förtappade warda; derföre, at de icke anammade kärleken til sanningena, at de måtte salige wordet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Fördenskull skall Gud sända dem kraftig willfarelse, så at de skola tro lögnene:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'På det de skola alle dömde warda, som icke hafva trott sanningene, utan hafva lust til orättfärdigheten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Men wi skole alltid tacka Gudi för eder, käre bröder, älskade af HERranom, at Gud hafver eder utwalt til salighet af begynnelsen, genom Andans helgelse, och i sanningenes tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'I hwilko han eder kallat hafver genom vårt Evangelium, til wårs HERras JESu Christi härliga egendom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Så står nu, käre bröder, och håller eder wid de stadgar, som I lärt hafwen, ehwad det är skedt af wårt ord eller bref.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Men sjelfwer wår HERre, JESus Christus, och Gud och wår Fader, den oss älskat hafwer, och gifwit en ewig tröst, och et godt hopp genom nådena:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Han hugswale edor hjerta, och styrke eder uti all lärdom, och goda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Yttermera, kära bröder, beder för oss, at HERrans ord må hafwa framgång, och prisadt warda, såsom ock när eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Och at wi mågom friade warda ifrå wanartiga och arga menniskor; ty tron är icke hwars mans.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Men HERren är trofast, den eder styrka skall, och bewara för det onda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Men wi förse oss til eder i HERranom, at I gören, och görande warden, hwad wi eder budit hafwe:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Men HERren styre edart hjerta til Guds kärlek, och til Christi tålamod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Och bjudom wi eder, käre bröder, i wårs HERras JESu Christi Namn, at I dragen eder ifrå hwar och en broder som oskickeliga wandrar, och icke efter den stadga, som han hafwer fått af oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Ty I weten sjelfwe, huru I skolen oss efterfölja: För den skull wi hadom oss icke oskickeliga ibland eder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Icke heller tagit brödet til gäfwes af någrom; utan med arbete och mödo, natt och dag, hafwe wi brukat oss, på det wi ingen af eder skulle wara til tunga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Icke derföre, at wi dess icke magt hadom; utan at wi skulle gifwa oss sjelfwa eder til efterdömelse, at efterfölja oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Och då wi worom när eder, böde wi eder sådant, at ho der icke wille arbeta, han skulle icke heller äta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Ty wi höre, at somlige ibland eder umgås oskickeliga, och arbeta intet, utan drifwa fåfängo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Men dem som sådana äro, bjude wi och förmane, genom wår HERra JESum Christum, at de arbeta med stilhet, och äta sitt eget bröd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Men I, käre bröder, förtröttens icke göra det godt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Om nu någor icke wille lyda wårt ord, honom tekner up i et bref, och hafwer ingen umgängelse med honom, på det han skall blygas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Dock håller honom icke såsom en owän; utan förmaner honom såsom en broder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Men sjelfwer fridsens HERre gifwe eder frid alltid, i allahanda måtto. HERren ware med eder allom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Hälsning med mine Pauli hand, hwilket är tecknet i all bref. Så skrifwer jag:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Wårs HERras JESu Christi nåd ware med eder allom. Amen. Sänd af Athen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Jesu Christ i Apostel, efter Guds vår Frälsares och Herrans Jesu Christi befallning, den vårt hopp är,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timotheo, minom rättsinniga son i trone: Nåd, barmhertighet, frid af Gudi varom Fader, och af Jesu Christo varom Herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Såsom jag bad dig, att du skulle blifva qvar i Epheso, då jag for in i Macedonien, sa gör ock; att du må bjuda somligom, att de ingen annan lärdom efterfölja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Och ingen akt gifva på fabler och slägtregister, de ingen ända hafva, och åstadkomma spörsmål, mer än förbättring till Gud, i trone.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Ty hufvudsumman af budet är kärleken af ett rent hjerta, och af ett godt samvete, och af en oskrymtad tro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Ifrå hvilken somlige hafva farit ville, och äro omvände till onyttigt sqvaller;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Och vilja vara mästare i Skriften, och förstå icke hvad de säga, eller hvad de hålla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Vi vete väl att lagen är god, då man henne rätteliga brukar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Vetandes, att dem rättfärdiga är ingen lag satt; utan orättfärdigom, och olydigom, ogudaktigom, och syndarom, oheligom, och oandeligom, fadermördarom och modermördarom, mandräparom,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Bolarom, drängaskändarom,menniskotjufvom, ljugarom, menedarom; och hvad annat sådant är, det en helsosam lärdom emot faller;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Efter dens saliga Guds härliga Evangelium, hvilket mig betrodt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Och jag tackar varom Herra Christ o Jesu, som mig hafver gjort mägtig, och räknat mig trogen, och satt i det ämbetet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Jag, som tillförene var en försmädare, och en förföljare, och en våldsverkare; men mig är barmhertighet vederfaren; ty jag hafver det gjort ovetandes, i otro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Men vårs Herras nåd hafver dess mer öfverflödat, genom trona och kärleken, i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Det är ett fast ord, och i alla måtto väl värdt att man det anammar, att Christus Jesus är kommen i verldena, till att frälsa syndare; ibland hvilka jag är den förnämligaste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Men mig är vederfaren barmhertighet, på det Jesus Christus skulle på mig förnämligast bevisa alla långmodighet, dem till efterdöme, som på honom tro skulle till evinnerligit lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Men Gudi, den eviga Konungenom, oförgängligom, osynligom, allena visom, vare pris och ära, i alla evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Detta budet befaller jag dig, min son Timothee, efter de förra Prophetier om dig, att du brukar dig deruti som en god krigsman;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Hafvandes trona, och godt sam vet; hvilket somlige hafva bortdrifvit, och äro skeppsbrutne vordne i trone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Af hvilkom är Hymeneus, och Alexander, hvilka jag Satane antvardat hafver; på det de skulle lära icke mer försmäda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Så förmanar jag nu, att man för all ting hafver böner, åkallan, förböner och tacksägelser, för alla menniskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'För Konungar, och för alla Öfverhet; på det vi måge lefva uti ett roligit och stilla lefverne, i all Gudaktighet och ärlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Ty sådant är godt och tacknämligit för Gudi, varom Frälsare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Som vill att alla menniskor skola frälste varda, och till sanningenes kunskap komma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Ty det är en Gud, och en Medlare emellan Gud och menniskor, nämliga den menniskan Christus Jesus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Hvilken sig sjelf gifvit hafver för alla till återlösen, att sådant skulle i sin tid predikadt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Der jag ock uti skickad är en Predikare och Apostel; jag säger sanningen i Christo, och ljuger icke, Hedningarnas lärare i trone och sanningene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Så vill jag nu, att männerna bedja i all rum, och upplyfta heliga händer, utan vrede och tvekan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Sammalunda ock. att qvinnorna pryda sig i höfveligom klädebonad, med blygaktighet och kyskhet; icke med flätadt hår, eller guld, eller perlor, eller kostelig klädnad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Utan, såsom de qvinnor höfves som gudaktighet bevisa, med goda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'En qvinna läte lära sig i stillhet, med all underdånighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Men qvinnone städer jag icke, att hon andra lärer; och icke heller råder öfver mannen, utan vare i stillhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Ty Adam vardt först skapad, och sedan Eva;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Och Adam vardt icke bedragen; utan qvinnan vardt bedragen, och kom öfverträdelsen åstad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Men hon varder likväl salig, genom barnsbörden, om hon blifver i trone, och kärlekenom, och i helgelse, med kyskhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Det är ju ett fast ord: Om någor begärar ett Biskopsämbete, han åstundar en. god gerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Så skall nu en Biskop vara ostraffelig; ene hustrus man, vakande, nykter, sedig, gästgifvare, läraktig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Ingen drinkare, icke bitter, icke sniken efter slem vinning; utan mild, icke trätosam, icke girig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Den sitt hus väl förestår; den der lydig barn hafver, med alla ärlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Hvar nu någor icke kan förestå sitt eget hus, huru skall han förestå Guds församling?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Icke Nychristen; på det han icke skall uppblåsas, och falla i lastarens dom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Han måste ock hafva ett godt vittnesbörd af dem som utantill äro; på det han icke skall falla uti lastarens försmädelse och snaro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Sammalunda ock tjenarena, skola ärlige vara, icke tvetalige, icke drinkare, icke snikne efter slem vinning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Hållandes trones hemlighet med ett rent sam vet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Och de skola först försökas; och sedan skola de tjena, när ingen kan straffa dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Deras hustrur sammaledes, skola ock ärliga vara, icke förtalerskor; nyktra, trofasta i all ting.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Tjenarena skola vara ene hustrus män, de sin barn väl förestå, och sin egen hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Ty de der väl tjena, förvärfva sig ett godt uppsteg, och mycken tröst i trone, som är i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Detta skrifver jag dig, förhoppandes ske skola att jag kommer snart till dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Och om så hände att jag förtöfvar, att du må veta huruledes du umgå skall uti Guds hus, som är lefvandes Guds församling, en pelare, och sanningenes grundval.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Och utan tvifvel är Gudaktighetenes hemlighet stor: Gud är uppenbar vorden i köttet, rättfärdigad i Andanom, synt Änglomen, predikad Hedningomen, trodd i verldene, upptagen i härligheten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Men Anden säger klarliga, att i yttersta tiderna skola somlige falla ifrå trone, hållande sig intill bedrägeliga andar och djeflalärdom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Genom dem som med skrymteri tala lögn, och hafva brändt tecken i sin samvet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Och förbjuda ägtenskap; bjuda skona maten, som Gud skapat hafver till att taga med tacksägelse, dem trognom, och dem som hafva förstått sanningena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Ty allt det Gud skapat hafver är godt, och intet bortkastandes, som med tacksägelse taget varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Ty det varder helgadt genom Guds ord och bönen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'När du sådant gifver bröderna före, så blifver du en god Jesu Christi tjenare; såsom du uppfödder äst i trones ordom, och god lärdom, med hvilken du alltid varit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Men oandeliga och kärlingafabler låt fara; men öfva dig sjelf till gudaktighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Ty lekamlig öfning är föga till nytto; men gudaktighet är nyttig till all ting, och hafver löfte om detta lifvet, och det tillkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Det är ju ett fast ord, och i alla måtto väl värdt att man det anammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Ty derpå arbete vi ock, och vardom försmådde, att vi hoppas på lefvandes Gud, som är alla menniskors Frälsare, men besynnerliga deras som tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Sådant bjud, och lär.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ingen förakte din ungdom; utan var dem trognom en eftersyn, i ord, i umgängelse, i kärlek, i andanom, i trone, i kyskhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Håll på att läsa, förmana, lära, tilldess jag kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Försumma icke den gåfvo som i dig är, den dig gifven är genom prophetien, med Presternas händers åläggning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Detta akta; blif deruti; på det din förbättring må h värj om månne uppenbar varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Haf akt på dig sjelfvan, och på lärdomen; blif i dessa stycker; ty om du så gör, frälsar du dig sjelfvan, och dem som dig höra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Den gamla skall du icke hårdeliga straffa; utan förmana såsom en fader; de unga såsom bröder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'De gamla qvinnor såsom mödrar; de unga såsom systrar, med all kyskhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Hedra enkorna, de der rätta enkor äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Om någon enka hafver barn, eller barnabarn, sådana skola först lära väl regera sitt eget hus, och göra såsom föräldrarna dem gjort hafva; ty det är väl gjordt, och Gudi tacknämligit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Men det är en rätt enka, som ensam är, den sitt hopp sätter till Gud, och blifver alltid i böner och åkallan, natt och dag;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Men den som lefver i vällust, hon är lefvandes död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Sådant bjud, att de äro ostraffeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Hvar nu någor sina, besynnerliga sitt husfolk, icke försörjer, den hafver försakat trona, och är argare än en Hedninge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Lät inga enko utväljas yngre än sextio år, den som hafver varit ens mans hustru;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Och vittnesbörd hafver om goda gerningar; om hon hafver uppfödt barn; om hon hafver herbergat; om hon hafver tvagit de heligas fötter; om hon hafver hulpit de bedröfvada; om hon i alla goda gerningar hafver idkelig varit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Men de unga enkor låt fara; ty när de begynna kättjas emot Christum, så vilja de gifta sig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Och hafva sin dom, att de den första tron brutit hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Dertillmed äro de fåfänga, och lära löpa omkring i husen; ja, icke allenast fåfänga, utan ock sqvallerfulla, och förvetna, och tala det som icke borde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Så vill jag nu; att de unga enkor gifta sig, föda barn, stå hus före, intet tillfälle gifva motståndarenom till att tala illa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Ty några hafva allaredo vändt tillbaka efter Satanam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Hvar nu någor trogen man eller qvinna hafver enkor, han försörje dem, och läte icke församlingen förtungas, att det må dem tillräcka, som rätta enkor äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'De Prester, som väl förestå, skall man hälla vara dubbel heder värda; mest de, som arbeta i ordet och lärdomen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Ty Skriften säger: Du skall icke binda munnen till på oxan som tröskar; och: En arbetare är sin lön värd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Tillstäd ingen klagomål emot en Prest, utan med tu eller tre vittne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'De som synda, straffa för allom, att andre skola ock frukta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Jag betygar för Gudi, och Herranom Jesu Christo, och för de utkorada Änglar, att du håller detta, utan egen godtycko, och gör intet efter väld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Lägg icke hastigt händerna på någon, och gör dig icke heller delaktig i annars mans synder; håll dig sjelfvan kysk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Drick icke länger vatten, utan bruka något fögo vin, för din magas skull, och att du ofta sjuk äst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Somliga menniskors synder äro uppenbara, att man dem tillförene döma kan; men somliga varda sedan uppenbara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Sammalunda äro ock somliga goda gerningar uppenbara; och de andra blifva ock intet fördolda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Trälarna, som under ok äro, skola hålla sina herrar alla äro värda; på det Guds Namn och lärdom icke skall försmädd varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Men de som hafva trogna herrar, de skola icke förakta dem, fördenskull de äro bröder; utan vara dess mer tjenstaktige, att de trogne, och älskade, och delaktige uti välgerningene äro. Sådant lär, och förmana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ho der annars lärer, och icke blifver vid vars Herras Jesu Christi helsosamma ord. och vid den lärdom som är om Gudaktigheten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Han är förmörkrad, och vet intet, utan är sjuk i spörsmål och ordaträtor, af hvilkom födes afund, kif, försmädelse, onda misstankar,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Onyttiga disputeringar emellan de menniskor, som i sitt sinne förderfvade äro, i trä hvilka sanningen är borttagen, de der mena att gudaktigheten är en vinning. Drag dig ifrå sådana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Men vara gudelig, och låta sig nöja, är vinning nog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Ty vi hafve intet fört in i verldena; derföre är det klart, att vi icke heller kunne något föra härut;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Utan då vi hafve födo och kläder, så låtom oss dermed nöja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Men de som vilja rike varda, falla uti frestelse, och i snaro, och i mång dåraktig och skadelig begärelse, de der sänka menniskorna uti förderf och fördömelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Ty girighet är en rot till allt ondt; till hvilka somlige hafva haft lust, och äro deri med ville farne ifrå trone, och hafva gjort sig sjelfva mycken bedröfvelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Men du, Guds menniska, fly sådant; far efter rättfärdigheten, Gudaktigheten, tron, kärleken, tålamod, saktmod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kämpa en god trones kamp; fatta evinnerligit lif, till hvilket du ock kallad äst, och bekant hafver en god bekännelse för mång vittne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Jag bjuder dig för Gudi, som all ting gör lefvande; och för Christo Jesu, som under Pontio Pilato betygat hafver en god bekännelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Att du håller budet obesmittadt, ostraffelig, intill vårs Herras Jesu Christi uppenbarelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Hvilka oss bete skall i sin tid den salige och allena väldige Konungen öfver alla Konungar, och Herren öfver alla herrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Den der allena hafver odödelighet; den der bor uti ett ljus der ingen tillkomma kan; den ingen menniska sett hafver, icke heller se kan; honom vare ära och evigt rike. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bjud dem som rike äro i denna verld, att de icke äro storsinte, icke heller sätta sitt hopp på de ovissa rikedomar; utan på lefvande Gud, hvilken oss all ting rikeliga gifver till att nyttja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Att de göra väl, och rike varda på goda gerningar, gerna gifva, äro oförtrutne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Sammansamka sig sjelfvom en god grund framdeles, att de måga fatta evinnerligit lif.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timothee, förvara det dig betrodt är; och fly oandelig och onyttig ord och trätor, som gå af falskeliga berömd konst;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Hvilka somlige föregifva, och fara ville om trona. Nåd vare med dig. Amen. Sänd af Laodicea, hvilken är hufvudstaden i Phrygia Pacatiana,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, till att predika lifsens löfte, i Christo Jesu;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Min om kära son Timotheo: Nåd, barmhertighet, frid af Gud Fader, och Christo Jesu varom Herra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Jag tackar Gudi, den jag tjenar ifrå mina föräldrar, uti ett rent samvet, att jag utan upphäll hafver din åminnelse i mina böner, natt och dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Och mig längtar efter att se dig, när jag tänker på dina tårar; på det jag med glädje måtte uppfylld varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Och jag drager mig till minnes den oskrymtade tro, som i dig är, den tillförene bodde uti dine fadermoder Loide, och i dine moder Evnica; är jag viss att sammalunda ock i dig;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'För hvilka saks skull jag förmanar dig, att du uppväcker Guds gåfvo, som i dig är, genom mina händers påläggning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Ty Gud hafver icke gifvit oss räddhågans anda, utan kraftenes, och kärlekens, och tuktighetenes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Derföre skäm dig icke vid vårs Herras vittnesbörd; icke heller vid mig, som är hans fånge; utan var delaktig uti Evangelii bedröfvelse, efter Guds kraft;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Den oss frälsat hafver, och kallat med en helig kallelse; icke efter våra gerningar, utan efter sitt uppsåt, och nåd, den oss gifven är i Christo Jesu, för evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Men nu är hon uppenbar vorden genom vår Frälsares Jesu Christi uppenbarelseren der döden borttagit hafver, och lifvet och ett oförgängeligit väsende framburit i ljuset, genom Evangelium;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Uti hvilket jag är sätter till en predikare, och Apostel, och Hedningarnas lärare;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'För hvilka saks skull jag ock detta lider; och skämmes dock intet; ty jag vet på hvem jag tror, och är viss att han förmår förvara mitt betrodda gods intill den dagen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Håll dig efter de helsosamma ords eftersyn, som du hört hafver af mig, om trona och kärleken i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Detta goda betrodda godset bevara genom den Helga Anda, den uti oss bor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du vetst att alle de, som i Asien äro, hafva vändt sig ifrå mig; ibland hvilka är Phygellus, och Hermogenes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Herren gifve Onesiphori huse barmhertighet; ty han hafver ofta vederqvickt mig, och skämdes icke vid mina kedjo;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Utan, då han var i Rom, sökte han fliteliga efter mig, och fann mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Gifve honom Herren, att han finner barmhertighet när Herranom på den dagen; och i huru mång stycke han mig till tjenst var i Epheso, vetst du bäst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Så stärk dig nu, min son, genom nådena, som är i Christo Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Och livad du af mig hört hafver, genom mång vittne, det befalla trogna menniskor, som ock dugelige äro att lära andra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Lid och umgäll, såsom en god Jesu Christi stridsman.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Ingen stridsman befattar sig med näringshandel; på det han skall täckas honom, som honom till en stridsman upptagit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Hvar ock nu någor kämpar, han krönes icke, utan han redeliga kämpar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Åkermannen, som åkren brukar, honom bör först få af fruktene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Märk hvad jag säger; men Herren skall gifva dig i all ting förstånd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Tänk på Jesum Christum, som är uppstånden ifrå de döda, af Davids säd, efter mitt Evangelium;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Uti hvilket jag bedröfvelse lider, intill bojor, såsom en ogerningsman; men Guds ord är icke bundet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Derföre lider jag det allt, för de utkoradas skull, att de skola ock få salighet i Christo Jesu, med eviga härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Det är ju ett fast ord: Dö vi med, så skole vi lefva med;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Lide vi, så skole vi med regnera; om vi försake honom, så försakar ock han oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Tro vi honom icke, så blifver han dock trofast; han kan icke neka sig sjelf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Sådant förmana, och betyga för Herranom, att de icke träta om ord till ingen nytto, utan till att afvända dem som på höra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Vinnlägg dig att bevisa dig Gudi en bepröfvad och ostraffelig arbetare, som rätt delar sanningenes ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Men oandelig och onyttig ord kasta bort; ty det hjelper mycket till ogudaktighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Och deras tal fräter omkring sig, såsom kräfvetan; ibland hvilka är Hymeneus och Philetus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'De der om sanningen felat hafva, sägande uppståndelsen redan skedd vara; och hafva förvändt somliga menniskors tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Men den fäste Guds grund blifver ståndandes, och hafver detta insegel: Herren känner sina; och hvar och en som åkallar Christi Namn, gånge ifrå orättfärdighetene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Men uti ett stort hus äro icke allenast gyldene och silffat, utan jemväl träfat och lerfat; och somlig till heder, och somlig till vanheder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Hvar nu någor renar sig ifrå sådant folk, han varder ett helgadt fat till heder, husherranom brukeligit, beredt till ull t godt verk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fly ungdomsens lustar; men far efter rättfärdigheten, tron, kärleken, frid med allom dem, som af rent hjerta åkalla Herran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Men förkasta dåraktig och öfverdådig spörsmål, vetandes att de föda träto af sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Men Herrans tjenare skall icke vara trätosam, utan ljuflig vid hvar man, läraktig, den de onda lida kan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Och med saktmodighet straffa dem som emotstå; om Gud en gång vill gifva dem bättring, till att förstå sanningen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Och besinna sig ifrå djefvulens snaro, af hvilkom de fångne äro efter hans vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Men detta skall du veta, att uti yttersta dagarna tillstunda farliga tider.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Ty der varda kommande menniskor, som älska sig sjelfva; girige, stortalige, högfärdige, försmädare, föräldromen olydige, otacksamme, ogudaktige,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Okärlige, hårdnackade, skändare, okyske, omilde, hatande det goda,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Förrädare, öfverdådige, uppblåste, de der mer älska vällust än Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Hafvandes ett sken till Gudaktighet; men dess kraft försaka de. Och fly sädana.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Af dem äro de som löpa utu det ena huset i det andra, och föra qvinnfolk fångna, som med synder betungade äro, och drifvas af mångahanda lustar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Alltid läras de, och kunna dock aldrig komma till sanningens kunskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Men såsom Jannes och Jambres stodo emot Mose, så stå ock desse emot sanningene; det äro menniskor, förderfvade i sitt sinne, odugelige till trona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Men de skola icke länger hafva framgång; ty deras galenskap varder allom uppenbar, såsom ock de förras var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Men du hafver förnummit min lärdom, mitt sätt, mitt uppsåt, mina tro, min långmodighet, min kärlek, mitt tålamod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Mina förföljelser, mina bedröfvelser, som mig öfvergingo i Antiochien, Iconio, Lystris; hurudana förföljelser jag der led; och af allt hafver Herren förlossat mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Och alle, de der gudeliga vilja lefva i Christo Jesu, måste lida förföljelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Men med onda menniskor och bedragare varder det ju länger ju argare; de förföra, och varda förförde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Men du, blifvid det du lärt hafver, och det dig betrodt är, vetandes af hvem du det lärt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Och efter du af barndom hafver kunnat den Helga Skrift, kan hon dig undervisa till salighet, genom trona på Christum Jesum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Ty all skrift af Gudi utgifven är nyttig till lärdom, till straff, till bättring, till tuktan i rättfärdighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Att en Guds menniska skall vara fullbordad, till alla goda gerningar skickelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Så betygar jag nu för Gudi, och Herranom Jesu Christo, den der döma skall lefvande och döda, i sin tillkommelse, och i sitt rike;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Predika ordet; håll uppå i tid och i otid; straffa, truga, förmana, med all saktmodighet och lärdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Ty den tid skall komma, att de icke skola kunna lida helsosam lärdom; utan skola, efter sina egna lustar, samla sig lärare; efter dem kliar i öronen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Och skola vända sin öron ifrå sanningen, och vända sig till fabler.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Men du, var valken i all ting, lid och umgäll; gör ens Evangelisk Predikares verk; uträtta ditt ämbete redeliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Ty jag offras nu, och tiden tillstundar att jag skall skiljas hädan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Jag hafver kämpat en god kamp, jag hafver fullbordat loppet; jag hafver hållit trona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Härefter är mig förvarad rättfärdighetenes krona, hvilka Herren mig gifva skall på den dagen, den rättfärdige domaren; men icke mig allenast, utan ock allom dem, som älska hans uppenbarelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Vinnlägg dig, att du kommer snarliga till mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Ty Deinas hafver öfvergifvit mig, och fått kärlek till denna verldena; och är faren till Thessalonica; Crescens till Galatien; Titus till Dalmatien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lucas är allena med mig. Tag Marcuim till dig, och haf honom med dig; ty han är mig mycket nyttig till tjenst.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychicum hafver jag sändt till Ephesum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Men Herren skall förlossa mig af all ond gerning, och frälsa mig till sitt himmelskarike; hvilkom vare ära ifrån evighet till evighet. Amen. Men Herren skall förlossa mig af all ond gerning, och frälsa mig till sitt himmelskarike; hvilkom vare ära ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander, kopparsmeden, hafver mig mycket ondt bevist. Herren betale honom efter hans gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Tag ock du dig vara för honom; ty han hafver svårliga ståndit emot vår ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Uti min första försvarelse stod ingen när mig, utan alle öfvergåfvo mig; det varde dem icke tillräknadt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Men Herren stod med mig, och styrkte mig; på det genom mig skulle predikanen stadfäst varda, och alle Hedningar höra skulle; och jag är friad af lejonens mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Helsa Priscam, och Aqvilam, och Onesiphori husfolk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blef i Corintho; men Trophimum lät jag qvar i Mileto sjuk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Vinnlägg dig, att du kommer för vintren. Dig helsar Eubulus, och Pudens, och Linus, och Claudia, och alle bröderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Herren Jesus Christus vare med din anda. Nåd vare med eder. Amen. Den andra Epistelen till Timotheum, skrifven af Rom, då Paulus åter hades fram för Kejsar Neronem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Guds tjenare, men Jesu Christi Apostel, till att predika Guds utvaldom trona och sanningenes kunskap, hvilken till Gudaktighet förer,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'I hoppet till evinnerligit lif, det Gud, som icke ljuga kan, för evigt utlofvat hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Men i sinom tid hafver han uppenbarat sitt ord genom predikan, den mig betrodd är, efter Guds vår Frälsares befallning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Minom rättsinniga son Tito, efter begges våra tro: Nåd, barmhertighet, frid af Gud Fader, och Herranom Jesu Christo, vårom Frälsare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Fördenskull lät jag dig qvar i Creta, att hvad som ännu fattades, skulle du fullkomliga beställa, och besätta städerna här och der med Prester, såsom jag dig befallt hafver;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Den som är ostraffelig, ene hustrus man; den der trogen barn hafver, oberyktad för öfverflödighet och genstörtighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Ty en Biskop bör vara ostraffelig, såsom en Guds skaffare; icke ensinnig, icke sticken, ingen drinkare, icke bitter, icke sniken efter slem vinning;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Utan gästgifvare, och älskar det godt är; tuktig, rättvis, helig, kysk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Och håller sig vid det ord, som visst är och lära kan; på det han må mägtig vara att förmana genom helsosam lärdom, och öfvervinna dem som deremot säga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Ty månge äro genstörtige, onyttige sqvallrare, och bedragare, besynnerliga de af omskärelsen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Hvilkom man måste tillstoppa munnen; de som hela husen förvända, och lära det intet doger, för slem vinnings skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'En af dem hafver sagt, deras egen Prophet: De Creter äro alltid ljugare, ond djur, och late bukar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Detta vittnesbörd är sant. Derföre straffa dem skarpeliga, att de äro rätte i trone;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Och icke akta på de Judiska fabler och menniskors bud, som sig draga ifrå sanningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Dem, som rene äro, äro all ting rene; men dem orenom och otrognom är intet rent; utan både deras sinne och samvet är orent.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'De säga sig känna Gud; men med gerningarna neka de det; efter de äro styggelige för Gud, och olydige, och till alla goda gerningar odugelige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Men tala du, såsom tillbörligit är, efter en helsosam lärdom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'De gamla, att de äro nyktre, ärlige, tuktige, rätte i trone, i kärlekenom, i tålamod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'De gamla qvinnor desslikes, att de ställa sig såsom heligom höfves, icke förtalerskor, icke drinkerskor, goda lärerskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Att de unga qvinnor lära tukt af dem; älska sina män, hafva sin barn kär;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Vara sediga, kyska, husaktiga, fromma, sina män underdåniga; på det Guds ord icke skall försmädt varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Sammalunda förmana ock de unga män, att de äro tuktige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Uti all ting ställ dig sjelf för en eftersyn till goda gerningar, med oförfalskad lärdom, med ärlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Med helsosam och ostraffelig ord; på det han, som emotstår, må blygas, intet ondt hafvandes det han om oss säga kan;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Tjenarena, att de äro sinom herrom underdånige, och uti all ting behagelige, icke gensvarige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Icke otrogne; utan alla goda trohet bevisande; på det de måga pryda Guds vår Frälsares lärdom i all stycke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Ty Guds nåd, helsosam allom menniskom, är uppenbarad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Och lärer oss, att vi skole försaka alla ogudaktighet och verldslig lusta, och lefva tukteliga, rättfärdeliga, och gudeliga i denna verlden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Och vänta det saliga hoppet, och den stora Guds och vår Frälsares Jesu Christi härliga uppenbarelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Den sig sjelf gaf för oss; på det han skulle förlossa oss ifrån all orättfärdighet, och rena oss sig sjelfvom ett folk till egendom, det sig om goda gerningar beflitar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Sådant tala, och förmana, och straffa med fullt allvar. Låt ingen förakta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Förmana dem, att de äro Förstarna och Öfverheten underdånige och lydige; redebogne till alla goda gerningar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Om ingen illa tala, icke trätosamma; utan milde, bevisande all saktmodighet till alla menniskor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Ty vi vorom ock fordom ovise, ohörige, villfarande, tjenande begärelsom och mångahanda lustom, och vandradom i ondsko och afund, hätske; och hatadom hvarannan inbördes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Men sedan Guds, vår Frälsares, godhet och kärlek till menniskorna uppenbarades;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Icke för rättfärdighetenes gernings skull, som vi gjort hade; utan efter sina barmhertighet gjorde han oss saliga, genom den nya födelsens bad, och den Heliga Andas förnyelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Hvilken han öfver oss rikeliga utgjutit hafver, genom vår Frälsare Jesum Christum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'På det vi skole rättfärdige varda genom hans nåd, och arfvingar blifva till evinnerligit lif, efter hoppet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Det är ju ett fast ord; detta vill jag att du lärer, såsom det der visst är, att de, som Gudi trott hafva, vinnlägga sig i goda gerningar föregå; ty sådant är menniskomen godt och nyttigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Men dåraktig spörsmål, och slägtregister, och trätor, och kämpning om lagen förkasta; ty de äro onyttig och fåfäng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Fly en kättersk mennisko, då han en gång och annan förmanad är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Vetandes, att en sådan är förvänd, och syndar, såsom den sig sjelf fördömt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Då jag till dig sänder Artheman, eller Tychicum, så skynda dig snart till mig till Nicopolis; ty jag hafver satt mig före att blifva der öfver vintren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenan, den lagkloka, och Apollo, fordra med flit, att dem intet fattas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Men lät ock dem, som våre äro, lära i goda gerningar föregå der det behöfves, att de icke äro ofruktsamme.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Helsa dig alla, som med mig äro. Helsa dem, som oss älska i trone. Nåd vare med eder allom. Amen. Skrifven af Nicopolis, i Macedonien.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, '');
