INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, '');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Fordom talade Gud ofta, och i mångahanda måtto, till fäderna, genom propheterna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'På det yttersta i dessa dagar hafwer Han talat till oss genom Sonen; hwilken Han satt hafwer till arfwinge öfwer all ting; genom hwilken Han ock werlden gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Hwilken efter Han är Hans härlighets sken, och Hans wäsendes rätta beläte, och bär all ting med sitt kraftiga ord, och hafwer rensat wåra synder genom sig sjelf, sitter Han på Majestätsens högra sida i höjden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Så mycket bättre worden än englarna, som Han för dem högre namn ärfdt hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Ty, till hwilken af englarna hafwer Han någon tid sagt: Du äst min Son, i dag hafwer jag födt dig? Och åter: Jag skall wara Hans Fader, och Han skall wara min Son?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Och åter, då han införer den förstfödde i werlden, säger han: Och alle Guds englar skola tillbedja Honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Men om englarna säger han: Han gör sina englar andar, och sina tjenare eldslåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Men till Sonen: Gud, din stol warar ifrån ewighet till ewighet; ditt rikes spira är en rättwis spira.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du hafwer älskat rättfärdigheten och hatat orättfärdigheten; derföre hafwer, Gud, din Gud smort dig med glädjens olja, mer än dina medbröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Och du, HERre, grundade jorden af begynnelsen, och himlarna äro dina händers werk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'De skola förgås; men du skall blifwa; och de skola alle föråldras såsom ett kläde;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Och såsom en klädnad skall du förwandla dem, och de warda förwandlade; men du blifwer densamme, och dina år hafwa ingen ända.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Men till hwilken af englarna hafwer Han någon tid sagt: Sätt dig på min högra hand, till dess jag lägger dina fiender dig till en fotapall?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Äro de icke allesammans tjenstandar, utsände till tjenst, för deras skull, som saligheten ärfwa skola?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Derföre skole wi dess bättre taga wara på det oss sagdt är, att wi tilläfwentyrs icke förderfwas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Ty wardt det ordet fast, som genom englarna taladt war; och all öfwerträdelse och olydighet hafwer fått sin rätta lön;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Huru skole wi undfly, om wi sådan salighet icke akte? Hwilken sedan hon först predikad wardt af HERranom, är kommen in på oss af dem, som det hört hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Och Gud hafwer gifwit wittnesbörd dertill med tecken, under och mångahanda krafter, och med den Heliga Andas utstiftelse, efter Hans wilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Ty Han hafwer icke undergifwit englarna den tillkommande werlden, der wi om tale.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Men en betygar enestäds, och säger: Hwad är menniskan, att du tänker på honom? Eller menniskones Son, att du söker honom?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Du hafwer en liten tid låtit Honom öfwergifwen wara af englarna: med ära och pris hafwer du krönt Honom, och satt Honom öfwer dina händers werk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'All ting hafwer du lagt under Hans fötter. I det Han nu all ting hafwer Honom underlagt, hafwer Han intet undantagit, det Honom icke underlagt är. Dock se wi icke ännu all ting wara Honom underlagd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Men JEsum, som en liten tid hafwer öfwergifwen warit af englarna, se wi för dödsens lidandes skull krönt wara med ära och pris: på det Han af Guds nåd skulle smaka döden för alla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Ty det höfdes Honom, för hwilkens skull all ting äro, och genom hwilken all ting äro, den der många barn till härlighet fört hade, att Han deras Salighetshöfding skulle genom lidande fullkommen göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Efter den, som helgar, och de, som helgade warda, äro alle af enom; derföre skämmes Han ock icke kalla dem bröder,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Sägande: Jag will förkunna ditt namn minom brödrom, och midt i församlingen prisa dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Och åter: Jag will sätta min tröst till Honom. Och åter: Si, jag och barnen, som Gud mig gifwit hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Efter barnen hafwa kött och blod, är ock Han dess delaktig worden; på det Han skulle genom döden nederlägga honom, som döden i wåld hade, det är djefwulen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Och göra dem fria, som i allt sitt lefwerne genom dödens räddhåga måste trälar wara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Ty Han tager ingenstäds på sig englarna; utan Abrahams säd tager Han på sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Derföre måste Han i alla stycken wara bröderna lik: på det Han skulle wara barmhertig, och en trogen Öfwersteprest för Gudi, att försona folkens synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Ty deraf att Han wardt pint och frestad, kan Han hjelpa dem, som frestas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Derföre, I helige bröder, som delaktige ären uti den himmelska kallelsen, akter på Aposteln och Öfwerstepresten, den wi bekänna, Christum Jesum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Hwilken trogen är Honom, som Honom gjort hafwer, såsom ock Moses, i allt Hans hus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Så mycket större ära wärd än Moses, som Han hafwer större ära som huset byggde, än sjelfwa huset.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Ty hwart och ett hus bygges af någon; men Gud är den som all ting gjort hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Och Moses war trogen i allt Hans hus, såsom en tjenare, de ting till wittnesbörd, som framdeles yppas skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Men Christus såsom en Son, i sitt hus; hwilket hus wi äro, om wi annars förtröstningen, och hoppets berömmelse, intill ändan fast behålle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Derföre, såsom den Helige Ande säger: I dag om I fån höra Hans röst,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Så förhärder icke edra hjertan; såsom skedde i wreden på frestelsedagen, i öknen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Då edra fäder frestade mig; de bepröfwade, och sågo mina werk, i fyratio år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Derföre wardt jag wred på detta slägte, och sade: Alltid fara de wille med hjertat; men de wisste icke mina wägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Så att jag ock swor i min wrede: De skola icke komma uti min rolighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Ser till, käre bröder, att tilläfwentyrs uti någon bland eder icke är ett argt och otroget hjerta, som träder ifrån lefwande Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Utan förmaner eder sjelfwa alla dagar, så länge det nämnes i dag: att ingen ibland eder blifwer förhärdad genom syndens bedragelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Ty wi äro delaktige wordne af Christo: om wi annars tron, som wi begynt hafwe, fast behålle intill ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Emedan det säges: I dag, om I fån höra Hans röst, så förhärder icke edra hjertan, såsom skedde i wreden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ty somlige, som henne hörde, förtörnade Honom; men icke alle som farne woro utaf Egypten, genom Mose.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Men hwilkom war Han wred i fyratio år? War Han icke dem, som syndat hade, hwilkas kroppar förföllo i öknen?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Men hwilka swor Han då, att de icke skulle komma in i Hans rolighet, utan de otrogna?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Och wi se, att de icke kunde ingå, för otrons skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Så låt oss nu frukta, att wi icke försumme det löfte, som är, att wi skole ingå i Hans rolighet; och att ibland oss icke någon tillbaka blifwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Ty det är ock oss förkunnadt, så wäl som dem; men det halp dem intet, att de hörde ordet; efter de som hörde, satte der icke tro till.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Ty wi, som tro, ingå i roligheten; som Han sade: Såsom jag swor i min wrede, de skola icke ingå i min rolighet; der dock de werk fullbordade woro af werldens begynnelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ty Han sade enstäds om den sjunde dagen alltså: Och Gud hwilade på sjunde dagen af all sin werk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Och åter nu här: De skola icke ingå i min rolighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Efter det är ännu för handen, att somlige skola der ingå, och de, som det i förstone bebådadt wardt, äro icke komne dertill, för otrons skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Lägger Han åter en dag före, efter så lång tid, och säger genom David: I dag, såsom sagdt är, i dag, om I hören Hans röst, så förhärder icke edra hjertan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ty om Josue hade kommit dem till rolighet, hade han ingalunda om en annan dag sedan sagt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Derföre står Guds folk en rolighet tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Ty den som ingången är uti Hans rolighet, han hafwer ock fått hwila af sina werk, såsom Gud af sina.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Så winnläggom oss nu, att wi måge inkomma uti denna roligheten, på det icke någon skall falla uti samma otros efterdömelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Ty Guds ord är lefwande, och kraftigt, och skarpare än något twäeggat swärd: och går igenom, till dess det åtskiljer själ och anda, och märg och ben; och är en domare öfwer tankar och hjertans uppsåt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Och för Honom är intet kreatur osynligt: utan all ting äro blott och uppenbar för Hans ögon: om Honom tale wi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Efter wi nu hafwe en stor Öfwersteprest, JEsum Guds Son, som i himmelen faren är, så låt oss hålla bekännelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Ty wi hafwe icke en Öfwersteprest, som icke kan warkunna sig öfwer wår swaghet; utan den som frestad är i all ting, likasom wi, dock utan synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Derföre låt oss trösteliga framgå till nådastolen: att wi måge få barmhertighet, och finna nåd, på den tid oss hjelp behöfwes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Förty, hwar och en öfwersteprest, den af menniskor uttages, han warder satt för meniskorna, i de ting som Gudi på röra, att han skall offra gåfwor och offer för synderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Den der kan warkunna sig öfwer dem, som fåkunnige äro, och wille fara: efter Han är ock sjelf belagd med swaghet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Derföre måste han ock, såsom för folket, så ock för sig sjelf offra, för synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Och ingen tager sig sjelf ära; utan den som ock kallad warder af Gud, likasom Aron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Så hafwer ock icke Christus gjort sig sjelf härligan, att Han skulle wara Öfwersteprest; utan den som sade till Honom: Du äst min Son, i dag hafwer jag födt dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Såsom Han ock annorstädes säger: Du äst en prest i ewig tid, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Och hafwer på sitt kötts dagar offrat bön och åkallan, med starkt rop och tårar till Honom, som Honom frälsa kunde ifrån döden: och wardt bönhörd, derföre att Han höll Gud i wördning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Och ändå Han war Guds Son, hafwer Han dock af thy Han led, lärt lydno.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Och då Han fullkommen wardt, blef Han allom dem, som Honom lyda, en orsak till ewig salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Kallad af Gud en Öfwersteprest, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Derom wi hade wäl mycket tala; men det är swårt, efter I ären så oförståndige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Och I, som länge sedan skulle warit lärare, behöfwen åter, att man lärer eder de första bokstäfwerna af Guds ord; och att man gifwer eder mjölk, och icke stadig mat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ty hwem man ännu mjölk gifwa måste, han är oförfaren i rättfärdighetens ord: ty han är ett barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Men dem, som fullkomne äro, tillhörer stadig mat, de som genom wanan öfwade äro i sinnen, till att åtskilja godt och ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Derföre wilje wi låta bestå den lärdom, som lyder på begynnelsen till ett christeligt lefwerne, och taga det före, som till fullkomligheten drager: icke på nytt läggande grunden till bättring af döda gerningar, till tron på Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Till döpelsen, till lärdom, till händers påläggning, till de dödas uppståndelse, och till den ewiga domen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Och det wilje wi göra, om Gud annars det tillstäder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Ty det är omöjligt, att de som en gång upplyfte äro, och smakat hafwa den himmelska gåfwan, och delaktige wordne äro af den Heliga Anda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Och smakat hafwa det goda Guds ord, och den tillkommande werldens kraft:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Om de affalla, och på nytt sig sjelfwom korsfästa Guds Son, och för spott hålla; att de skola igen förnyas till bättring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ty jorden som indricker regnet, som ofta kommer på henne, och bär dem beqwäma örter, som henne bruka, hon får wälsignelse af Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Men den törne och tistel bär, hon är oduglig, och närmast förbannelsen; hwilkens ändalykt är, att hon skall brännas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Men wi förse oss, I älskelige, till eder det bättre är, och det saligheten närmare är; ändock wi så tala.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Ty Gud är icke orättwis, att Han förgäter eder gerning och arbete i kärleken, som I bewisat hafwer på Hans namn, då I tjenten helgonen, och ännu tjenen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Men wi begäre, att hwar och en af eder densamma flit bewisar, till att hålla hoppet fast allt intill ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Att I cke tröge blifwen, utan deras efterföljare, som genom tron och långmodighet få det arf, som utlofwadt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Ty när Gud lofwade Abraham, då Han ingen större hade, der Han wid swärja kunde, swor Han wid sig sjelf,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Och sade: Sannerligen, jag will wälsigna dig, och föröka dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Ock så, efter han i tålamod förbidde, fick han det som utlofwadt war.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ty menniskorna swärja wid den der större är än de; och dem emellan blifwer en ände på alla trätor, om det stadfäst blifwer med en ed.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Men då Gud wille rikeligen bewisa arfwingarna till löftet sitt uppsåts fasthet, lade Han der en ed uppå:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Att wi genom tu owikeliga ting, i hwilka omöjligt är, att Gud ljuga skulle, en stark tröst hafwa skulle, wi som dertill flytt hafwa, att wi måtte få det hopp, som tillbjudet är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Hwilket wi hålla såsom ett säkert och fast wår själs ankare; det ock ingår intill det, som innanför förlåten är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Dit Förelöparen för oss ingången är, JEsus, en Öfwersteprest worden till ewig tid, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Denne Melchisedek war konung i Salem, högsta Guds prest, den Abraham mötte, då han igenkom från den konungaslagtning, och wälsignade honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Hwilken ock Abraham gaf tionde af all ting. Först uttolkas han rättwisans konung; men sedan, är han ock Salems konung, det är, fridens konung;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Utan fader, utan moder, utan slägt; och hafwer hwarken begynnelse på dagarna, eller ända på lifwet; men han är lik worden wid Guds Son, och blifwer prest i ewighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Men ser, huru stor den är, som ock Abraham patriarken gaf tionde af bytet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Men Levi söner, då de presterskapet anamma, hafwa befallning taga tionde af folket, det är, af sina bröder, efter lagen; ändå de ock af Abrahams länder komne äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Men den, hwilkens slägte icke räknas ibland dem, han tog tionde af Abraham, och wälsignade honom, som löftet hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Nu nekar det ingen, att det, som mindre är, tager wälsignelse af det, som större är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Och här taga de menniskor tionde, som dödlige äro; men der Han, som betygas om, att Han lefwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Och, om jag så säga skall: Levi, som tionden plägar taga, wardt ock tiondad i Abraham;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Ty han war ändå i sin faders länder, då Melchisedek honom mötte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Är nu fullkomlighet skedd genom det Levitiska presterskapet, ty derunder fick folket lagen; hwad behöfde sägas, att en annan prest uppkomma skulle, efter Melchisedeks sätt, och icke efter Arons sätt?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Ty der presterskapet förwandladt warder, der måste ock lagen förwandlas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ty den, som detta sägs om, är af ett annat slägte, af hwilket aldrig någon skötte altaret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Ty det är ju uppenbart, att wår HERre är kommen af Juda slägte; till hwilkens slägte Moses icke talat hafwer om presterskapet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Och är det ännu klarare, medan en annan prest efter Melchisedeks sätt uppkommer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Hwilken icke är gjord efter köttslig budords lag, utan efter oändelig lifs kraft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Ty han betygar: Du är en prest ewinnerligen, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ty dermed sker, att den förra lag afkommer, för hennes swaghets och onyttas skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Ty lagen kunde icke göra fullkomligt; och warder ett bättre hopp infördt, genom hwilket wi nalkas Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Och då mycket mer, att det icke skedde utan ed; ty de förre äro utan ed prester wordne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Men denne med ed, genom den som sade till Honom: HERren swor, och det skall icke ångra Honom: du är en Prest ewinnerligen, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Så mycket bättre testamente hafwer JESus uträttat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Och de förre äro månge prester wordne; derföre att döden lät dem icke blifwa;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Men denne, efter Han blifwer ewinnerligen, hafwer ett oförgängligt presterskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Hwarföre Han ock kan ewinnerligen saliga göra dem, som genom Honom komma till Gud, och lefwer alltid, och beder alltid för dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Ty en sådan Öfwersteprest höfdes oss hafwa, den der helig wore, oskyldig, obesmittad, skild ifrån syndare, och högre än himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Hwilken icke dagligen behöfde, såsom de andre öferste prester, först för sina egna synder offra, och sedan för folkens synder; ty Han gjorde det en resa, då Han sig sjelf offrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Ty lagen sätter menniskor till öfwersta prester, som swaghet hafwa; men edens ord, som efter lagen sagdt är, det sätter Sonen ewig och fullkomlig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Men summan af det wi tale, är detta: Wi hafwa en sådan Öfwersteprest, som sitter på högra handen på Majestätets stol i himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Och är en skaffare öfwer de heliga håfwor, och öfwer det sannskyldiga tabernaklet, hwilket Gud upprest hafwer, och ingen menniska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Ty hwar och en öfwersteprest warder skickad till att offra gåfwor och offer; derföre är det af nöden, att denne ock något hafwer, det han offra skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Hwar Han nu wore på jorden, så wore Han icke prest: der prester äro, de der efter lagen offra gåfor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Hwilka tjena eftersynen och skuggan till de himmelska ting: såsom Mose af Gud swaradt wardt, då han skulle fullkomna tabernaklet: Se till, sade Han, att du gör allt efter den eftersyn, som dig wist är på berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Men nu hafwer Han fått ett bättre embete, såsom Han ett bättre testamentes Medlare är, det ock på bättre löfte satt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Ty om det första hade warit ostraffeligt, hade ingalunda wordet sökt rum till ett annat.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Ty Han straffar dem, och säger: Si de dagar skola komma, säger HERren, att jag skall fullkomna öfwer Israels hus, och Juda hus, ett nytt testamente;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Icke efter det testamentet, som jag deras fäder gjorde, på den dag, då jag tog dem wid deras hand, att utföra dem af Egypti land; efter de blefwo icke ståndande i mitt testamente, så hafwer jag ock gifwit dem utur mitt sinne, säger HERren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Ty detta är det testamente, som jag will göra Israels hus, efter dessa dagar, säger HERren: Jag will gifwa min lag uti deras sinne, och uti deras hjertan will jag skrifwa dem; och jag will wara deras Gud, och de skola wara mitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Och skall ingen lära sin nästa, eller sin broder, och säga: Känn HERran; ty de skola alle känna mig, ifrån den minsta ibland dem, ock till den största.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Ty jag warder förblidkad öfwer deras orättfärdigheter, och deras synder, och deras ondska skall jag icke mer ihågkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'I det Han säger: Ett nytt, föråldrade Han det första; det nu åldrigt och gammalt är, det är hardt wid ändan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Hade och wäl det första sina rätter, och gudstjenst, och utwärtes helighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Ty det främre tabernaklet war der uppsatt; uti hwilket woro ljusastakarna, och bordet, och skådobröden; och detta kallades det heliga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Men bak den andra förlåten war det tabernaklet, som man kallade det allraheligaste;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Hwilket hade det gyllene rökelsekaret, och testamentets ark, på alla sidor beslagen med guld; uti hwilken war det gyllene ämbar, der det himmelsbrödet uti war, och Aarons staf, som blomstrats hade, och testamentets taflor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Men der ofwan uppå woro härlighetens Cherubim, som öfwerskyggde nådastolen; af hwilka stycken på denna tid icke besynnerligen är sägandes.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Då nu detta så beredt war, gingo presterna alltid in i det främre tabernaklet, och uträttade gudstjensten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Men uti det andra gick allenast den öfwerstepresten; en tid om året; icke utan blod, det han offrade för sina egna, och för folkens synder:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Der den Helige Ande med betydde, att helighetens wäg ändå icke uppenbar war, medan det första tabernaklet stod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Hwilket war en liknelse i den tiden, i hwilken gåfwor och offer offrades, och kunde icke göra honom fullkommen, efter samwetet, som den gudstjensten gjorde,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Allenast med mat och dryck, och mångahanda twagning, och utwärtes helighet, som pålagda woro, intill bättringens tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Men Christus är kommen, att Han skall wara Öfwerseprest till det tillkommande goda; genom ett större och fullkomligare tabernakel, det med händer icke gjordt är, det är, det icke så bygdt är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Icke heller genom bockablod, eller kalfwablod: utan Han är genom sitt eget blod en resa ingången uti det heliga, och hafwer funnit en ewig förlossning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Ty hafwer oxablod och bockablod, och strödd aska af kon helgat de orena, till köttslig renhet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Huru mycket mer skall Christi blod, som hafwer sig sjelf obesmittad, genom den Heliga Anda, Gudi offrat, rena wårt samwete af de döda gerningar, till att tjena lefwande Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Derföre är Han ock Nya Testamentets Medlare; på det de, som kallade äro, skulle få det ewiga arfwets löfte, i det, att Hans död gick der emellan, till förlossning ifrån de öfwerträdelser, som under det förra Testamentet woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Ty hwar ett testamente är, måste ock hans död med wara, som testamentet gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Ty testamentet blifwer gildt genom döden; annars hafwer det ännu ingen makt, så länge han lefwer, som testamentet gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Derföre war ock icke det första stiktadt utan blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Ty då Moses allt folket föregifwit hade hwart och ett budord efter lagen, tog han kalfwablod och bockablod, med watten, och purpurull, och isop, ock bestänkte boken, och allt folket;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Och sade: Detta är Testamentets blod, det Gud hafwer eder bjudit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Och desslikes tabernaklet, och alla käril, der gudstjenst plägade med göras, bestänkte Han sammalunda med blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Och warda mest all ting efter lagen rena gjorda i blod; och utan blodsutgjutelse sker ingen förlåtelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Så är nu af nöden, att de himmelska tings eftersyner skola med sådant renade warda: men de himmelska tingen måste bättre offer hafwa än dessa woro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Ty Christus är icke ingången i det heliga, som med händer gjort är, hwilket är en eftersyn till det sanskyldiga, utan in uti sjelfwa himmelen, på det Han skall nu wara i Guds åsyn för oss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Icke att han skall ofta offra sig, såsom öfwerstepresten gick hwart år in uti det heliga med annans blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Sjelf måste Han skolat ofta lida, af werldens begynnelse; men nu, på werldens ändalykt, är Han en gång uppenbarad, genom sitt eget offer, till att borttaga synden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Och såsom menniskorna är förelagdt en gång dö, men sedan domen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Så är ock Christus en resa offrad, till att borttaga mången mans synder: men en annan gång skall Han låta se sig utan synd dem, som Honom wänta, till salighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Ty lagen hafwer skuggan af det tillkommande goda, och icke sjelfwa warelsen. Årligen måste man offra alltid enahanda offer, och kan icke göra dem fullborda, som det offra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Annars hade det återwändt offras: efter de, som så offra, hade sedan intet samwete haft af synder, när de hade en resa warit rene gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Utan dermed sker en åminnelse på synderna hwart år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Ty omöjligt är genom oxablod och bockablod borttaga synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Derföre, då Han kommer i werlden, säger Han: Offer och gåfwor hafwer du icke welat; men kroppen hafwer du mig beredt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Bränneoffer och syndoffer behaga dig icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Då sade jag: Si, jag kommer; i boken är skrifwet om mig, att jag skall göra din wilja, o Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Tillförene då Han sade: Offer och gåfwor, bränneoffer och syndoffer hafwer du icke welat; icke behaga de dig heller, hwilka efter lagen offras;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Då sade Han: Si jag kommer, till att göra, o Gud, din wilja. Der tager Han det första bort, att Han det andra insätta skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'I hwilken wilja wi helgade äro en resa, genom JEsu Christi kropps offer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Och hwar och en prest är insatt, att han dagligen skall sköta gudstjensten, och ofta offra enahanda offer, hwilka aldrig kunna borttaga synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Men denne, då han hade offrat ett offer för synderna, det ewinnerligen gäller, sitter Han på Guds högra hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Och wäntar nu, till dess Hans owänner lagde warda Honom till en fotapall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Ty med ett offer hafwer Han ewinnerligen fullkomnat dem, som helige warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Det betygar oss ock den Helige Ande, ty då Han tillförene sagt hade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Det är det Testamentet, som jag dem göra will, efter de dagar, säger HERren: jag will gifwa min lag i deras hjerta, och i deras sinne will jag skrifwa dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Och deras synder och orättfärdighet will jag icke mer ihågkomma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Der nu sådan förlåtelse är, der är icke mer offer för synder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Efter wi nu hafwa, käre bröder, frihet till att ingå uti det heliga, genom JEsu blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Hwilken Han oss beredt hafwer till en ny och lefwande wäg, genom förlåten, det är, genom sitt kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Och hafwa en Öfwersteprest öfwer Guds hus;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Så låt oss framgå, med ett sannskyldigt hjerta, uti en fullkomlig tro, bestänkte i hjertan ifrån ett ondt samwete, och twagne om kroppen med rent watten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Och låt oss hålla hoppets bekännelse owikligen; ty Han är trofast, som det lofwat hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Och låt oss akta på oss inbördes, till att uppwäcka till kärlek och goda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Icke öfwergifwande wår församling, såsom somlige för sed hafwa, utan förmaner eder inbördes, och det dess mer, att I sen huru dagen nalkas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Ty om wi sjelfwiljande synda, sedan wi förstått hafwa sanningen, då står oss intet offer igen för synderna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Utan en förskräcklig domens förbidelse, och eldens nit, som motståndarena förtära skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Ho som bryter Mose lag, han måste dö utan barmhertighet, efter tu eller tre wittnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Huru mycket större näpst, menen I, förtjenar den, som Guds Son förtrampar, och Testamentets blod såsom orent aktar, genom hwilket Han helgad är, och försmäder nådens Anda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Ty wi känna den som sade: Hämden är min; jag skall wedergälla det, säger HERren. Och åter: HERren skall döma sitt folk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Det är gräseligt falla uti lefwandes Guds händer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Men kommer ihåg de framlidna dagar, i hwilka I upplyste woren, och stoden en stor törning i bedröfwelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'En dels, då I sjelfwe genom hädelse och bedröfwelse ett widunder worden; och en dels, då I sällskap haden med dem, som det så går.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Ty I hafwen delaktige warit af de bedröfwelser, som af mina bojor gingo, och med fröjd lidit edra egodelars försköfling, wetande, att I när eder sjelfa bättre och blifwande egodelar hafwen i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Så kaster icke nu bort eder tröst, som en stor lön hafwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Ty tålamodet är eder behof; på det I mågen göra Guds wilja, och få det, som lofwat är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Ty ännu en liten tid, så kommer den som komma skall, och fördröjer icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Men den rättfärdige skall lefwa af tron; och hwilken sig undandrager, han skall icke behaga min själ.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Men wi äro icke de, som oss undandrage till förtappelse; utan af dem som tro, och frälsa själen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Men tron är en wiss förlåtelse på det som man hoppas, och intet twifla om det man icke ser.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Genom henna hafwa de gamla fått wittnesbörd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Genom tron besinna wi, att werlden är fullbordad genom Guds ord: så att allt, det man ser, är wordet af intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Genom tron offrade Abel Gudi större offer än Cain, med hwilket han fick wittnesbörd, att han war rättfärdig, då Gud gaf om hans gåfwor wittnesbörd; och genom henne talar han ännu, ändock han död är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Genom tron wardt Enock borttagen, så att han icke skulle se döden, och fanns icke, derföre att Gud borttog honom; ty förr än han borttagen war, hade han fått wittnesbörd, att han täcktes Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Ty utan tron är omöjligt täckas Gudi. Ty den till Gud komma will, han måste tro att Gud är; och att Han lönar dem som söka Honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Genom tron ärade Noe Gud, och beredde arken till sitt hus salighet, då han fick Guds befallning om de ting, som icke syntes; genom hwilken han fördömde werlden, och wardt den rättfärdiges arfwinge, som af tron är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Genom tron wardt Abraham lydig, då han kallad wardt till att utgå i det land, som han få skulle till arfs; och for ut, och wisste icke, hwart komma skulle.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Genom tron war han en främling uti det landet honom lofwadt war, likasom uti ett främmande land, bodde uti tabernaklet med Isaac och Jacob, som medarfwingar woro till samma löfte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Ty han wäntade efter en stad, som grund hade; hwilken byggmästare och skapare är Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Genom tron fick och Sara kraft till att afla, och födde öfwer sin ålders tid; ty hon höll honom trofast, som det lofwat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Derföre wordo ock af en, som i den måtton död war, många födde, såsom stjernorna på himmelen, och som sanden är i hafstranden, den otalig är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'I tron äro desse alle döde, och hafwa dock intet fått af löftet; utan sett det fjerran efter, och trott deruppå, och låtit sig nöja, bekännande sig wara gäster och främande på jorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ty de, som sådant säga, gifwa tillkänna, att de söka ett fädernesland.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Och om de hade det ment, der de utgångne woro, hade de wäl haft tid att wända tillbaka.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Men nu begära de ett bättre, det är, det himmelska. Derföre skämmes icke Gud kallas deras Gud; ty Han hafwer beredt dem en stad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Genom tron offrade Abraham Isaac, när han försökt wardt; och offrade enda sonen, då han hade fått löftet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Om hwilken sagdt war: Uti Isaac skall dig din säd kallad warda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Och tänkte, att Gud kunde ock wäl uppwäcka ifrån det döda; deraf tog han ock honom igen till en liknelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Genom tron wälsignade Isaac Jacob och Esau om tillkommande ting.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Genom tron, då Jacob dog, wälsignade han båda Josephs söner; och tillbad det öfwersta på hans spira.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Genom tron, då Joseph dö skulle, talade han om Israels barns utgång; och gaf befallning om sina ben.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Genom tron wardt Moses fördåld i tre månader af sina föräldrar, då han född war; derföre att de sågo, att han war ett däjeligt barn, och fruktade icke konungens bud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Genom tron, då Moses war stor worden, nekade han sig wara Pharaos dotterson;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Och wille mycket hellre lida bedröfwelse med Guds folk, än till en tid hafwa lust i synden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Och höll Christi försmädelse för större rikedom, än de håfwor uti Egypten; ty han såg efter lönen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Genom tron öfwergaf han Egypten, icke fruktande konungens wrede; ty han höll sig wid den han icke såg, såsom han Honom sett hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Genom tron höll han Påska, och blods utgjutelse, på det han, som drap allt det förstfödt war, skulle icke komma wid dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Genom tron gingo de genom det Röda hafwet, såsom på torra landet; hwilket de Egyptier ock försökte, och drunknade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Genom tron föllo murarna i Jericho, då man i sju dagar omkring gångit hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Genom tron förgicks icke den skökan Rahab med de otrogna, då hon de spejare anammat hade med frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Och hwad skall jag mer säga? Tiden wore mig för stackot, när jag förtälja skulle, om Gideon, om Barak, och Simson, och Jephthah, och David, och Samuel, och propheterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Hwilka genom tron hafwa wunnit konungariken, gjort rättfärdighet, fått löfte, igenstoppat lejons mun;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Elds kraft utsläckt, swärdsegg undkommit, äro kraftige wordne af swagheten, äro starke wordne i striden, hafwa nederlagt främmande härar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Qwinnorna hafwa igenfått sina döda utaf uppståndelsen; somliga wordo sönderslagne, och hafwa ingen förlossning welat anamma, på det de skulle få uppståndelsen, som bättre är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Somlige hafwa lidit spott och hudflängning; och dertill bojor och fängelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Wordo stenade, sönderhuggne, genomstugne, döde för swärd; hafwa gångit i fårskinn och getskinn, fattige, trängde, bedröfwade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Hwilkom werlden icke wärdig war; och hafwa gått elände i öknar, och i berg, och i skrefwor, och i jordkulor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Alla dessa hafwa genom tron fått wittnesbörd, och hafwa dock icke fått löftet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Därföre att Gud hade föresett om oss något det bättre war: att de icke utan oss skulle fullkomnade warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Efter wi nu hafwa om oss en så stor hop med wittnen, låt oss aflägga synden, som alltid låder wid oss, och gör oss tröga; och låt oss med tålamod löpa i den kamp, som oss förelagd är;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Och se på Jesum, som tron begynt och fullkomnat hafwer, hwilken, då Han måtte haft glädje, led korset, och aktade icke smäleken; och är sittande på högra handen på Guds stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Tänker på Honom, som af syndare sådan gensägelse led emot sig, att I icke tröttens i edert sinne, gifwande eder utöfwer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ty I hafwen icke ännu allt intill blods emot ståndit, kämpande emot synden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Och hafwer redan förgätit den tröst, som till eder talar, likasom till sina barn: Min son, förakta icke HERrens aga; och gif dig icke utöfwer, då du näpses af Honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Ty hwem HERren älskar, den agar Han; men Han gisslar hwar och en son, Han anammar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Hwar I nu liden agan, så bjuder sig Gud till eder såsom till barn; ty hwilken är den son, som hans fader icke agar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ären I utan aga, i hwilken alle delaktige wordne äro, så ären I oäkta, och icke barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Hafwa wi nu köttsliga fäder, som oss aga, och frukta dem, skola wi då icke mycket mer underdånige wara den anderliga Fadren, att wi må lefwa?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Och de förra hafwa agat oss i några få dagar, efter som dem syntes; men denne till det, som nyttigt är, att wi måga få Hans helgelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'All aga synes nu icke wara till fröjd, utan till ångest; men sedan wedergäller Han en fridsam rättfärdighetens frukt dem, som deruti öfwade äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Derföre lyfter upp edra lata händer och trötta knän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Och stiger wissa steg med edra fötter, att icke någon haltar såsom en ofärdig, utan hellre helbregda warder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Farer efter frid med alla; och efter helgelse, utan hwilken ingen får se HERran.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Och ser till, att ingen försummar Guds nåd, att icke uppwäxer någon bitter rot, och gör något hinder, och många måtte genom henne besmittade warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Att ingen ware en bolare, eller ohelig såsom Esau, hwilken för en måltid bortsålde sin förstfödslorätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Men I weten, att då han wille sedan med arfsrätt få wälsignelse, wardt han bortdrifwen; och war honom då intet rum till någon bot, ändock han med tårar derefter sökte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ty I ären icke gångne till det berget, der man på taga kunde, och med eld brann, eller till töcknet, och mörkret, och stormen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Och basunsklanget, och till ordarösten, hwilka de wedersakade, som henne hörde, begärande att ordet skulle dem ju icke sagdt warda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Ty de förmådde icke lida det, som der sades: Om något djur kom wid berget, skulle det stenas, eller skjutas igenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Och så förskräckelig war den synen, att Mose sade: Jag är förskräckt, och bäfwar');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Utan I ären komne till Sions berg, och till lefwande Guds stad, det himmelska Jerusalem, och till den otaliga englaskaran;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Och till de försföddas församling, som i himmelen äro beskrifne; och till Gud, som alla dömer, och till de fullkomliga rättfärdigas andar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Och till Nya testamentets Medlare JEsus, och till stänkelseblodet, som bättre talar än Abels blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Ser till, att I icke wedersaken Honom, som med eder talar; ty kunde icke de undfly, som wedersakade Honom, som talade på jorden; huru mycket mindre wi, om wi wedersaka Honom, som af himmelen talar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Hwilkens röst på den tid gjorde jorden bäfwande; men nu lofwar Han, och säger: Ännu en tid skall jag göra bäfwande, icke allenast jorden, utan ock himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Det Han säger: ännu en tid, det gifwer tillkänna de tings förwandling, som bäfwa, såsom de der gjorda äro; på det de ting blifwa skola, som obäfwande äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Derföre, efter wi få det rike, som icke bäfwa kan, hafwa wi nåd, genom hwilken wi tjena Gudi, till att täckas Honom med tuktighet och fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Ty wår Gud är en förtärande eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Blifwer faste i broderlig kärlek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Förgäter icke att herberga; ty dermed hafwa somlige fått englar owetande till herberges.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Tänker på dem, som bundne äro, såsom medbundne, och på dem, som bedröfwelse lida, såsom de der ock af lekamen äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Äktenskapet skall hållas ärligt ibland alla, och äktenskapssäng obesmittad; men bolare och horkarlar skall Gud döma.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Umgängelsen ware utan girighet; och låter eder nöja med det I hafwen; ty Han sade: Jag skall icke öfwergifwa eller förlåta dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Så att wi dristeligen måge säga: HERren är min hjelpare; och jag will icke frukta: hwad kan en menniska göra mig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Tänker på edra lärare, de eder Guds ord sagt hafwa, och efterföljer deras tro, skådande hwad ända deras umgängelse hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'JEsus Christus i går och i dag, och Han desslikes i ewighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Låter eder icke omföras med mångahanda och främmande lärdom; ty det är godt att stadfästa hjertat med nåden; icke med maten, hwilken intet gagnat hafwer dem, som dermed umgått hafwa.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Wi hafwa ett altare, af hwilket de hafwa icke makt att äta, som tjena i tabernaklet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ty ehwad djurs blod, som öfwerstepresten för synden inbär uti det heliga, deras kroppar uppbrännas utom lägret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Derföre ock JEsus, på det Han skulle helga folket med sitt eget blod, hafwer Han lidit utom porten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Så låt oss nu gå ut till Honom utur lägret, och bära Hans smälek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Ty wi hafwa här ingen waraktig stad; utan wi söka efter den tillkommande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Så låt oss nu genom Honom alltid offra Gudi lofoffer, det är, läpparnas frukt, de Hans namn bekänna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Förgäter icke göra wäl, och meddela; ty sådana offer täckas Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Warer edra lärare lydige, och följer dem; ty de waka öfwer edra själar, såsom de der räkenskap göra skola: på det de måga det göra med fröjd, och icke med suckan; ty det är eder icke nyttigt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Beder för oss; wår tröst är den, att wi ett godt samwete hafwa, och winnlägga oss hafwa en god umgängelse när all;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Men allramest beder jag eder, att I sådant gören, att jag med det snaraste måtte komma till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Men fridens Gud, som igenfört hafwer ifrån de döda den stora Fåraherden, genom det ewiga Testamentets blod, wår HERra JEsum;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Han göre eder skickliga uti allt godt werk, till att göra sin wilja, och skaffe uti eder hwad Honom täckeligt är, genom JEsum Christum; hwilken ware ära af ewighet i ewighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Jag förmanar eder, käre bröder, tager förmanelsens ord till godo; ty jag hafwer eder med få ord tillskrifwit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Weten, att brodren Timotheus lös är; med hwilken, om han snart kommer, will jag se eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Helser alla edra lärare, och alla helgon. Eder helsa bröderna uti Walland.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Nåd ware med eder alla. Amen. Till de Ebreer skrifwen af Walland med Timotheus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacobus, Guds och Herrans Jesu Christi tjenare: dem tolf slägtom, som äro här och der förskingrade, helso.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mine bröder, håller det för all glädje, när I fallen i mångahanda frestelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Och veter, att edor tros bepröfvelse gör tålamod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Men låter tålamodet hafva ett fullbordadt verk; på det I skolen vara fullkomna och hele, och intet fel hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Hvar nu någrom ibland eder fattas visdom, han bedje af Gudi, den der gifver enfaldeliga allom, och förviter icke; och han skall honom gifven varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Men han bedje i trone, intet tviflandes; ty den der tviflar, han är såsom hafsens våg, som af vädret drifs och föres.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Sådana menniska tänke icke, att hon får något af Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'En man, som tviflar, är ostadig i alla sina vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Men en broder, som ringa är, berömme sig af sin upphöjelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Och den som rik är, af sin förnedring; ty såsom blomstret af gräset skall han förgås.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Solen går upp med hetta, och gräset förvissnar, och blomstret faller af, och dess sköna fägring förgås; så skall ock den rike förvissna uti sina vägar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Salig är den man, som tåleliga lider frestelse; ty då han bepröfvad är, skall han ta lifsens krono, den Gud lofvat hafver dem som honom älska.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ingen säge, då han frestad varder, att han af Gudi frestad varder; ty Gud frestas icke af ondt, han frestar ock ingen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Utan hvar och en varder frestad, då han af sin egen begärelse dragen och lockad varder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Derefter, sedan begärelsen hafver aflat, föder hon synden; men då synden är fullbordad, föder hon döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Farer icke ville, mine käre bröder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'All god gåfva, och all fullkomlig gåfva kommer ofvanefter, ifrå ljusens Fader; när hvilkom ingen förvandling är, eller ljus och mörkers omskiftelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Han hafver oss födt efter sin vilja, genom sanningenes ord, på det vi skulle vara förstlingen af hans kreatur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Derföre, mine käre bröder, hvar och en menniska vare snar till att höra, och sen till att tala, och sen till vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Ty mansens vrede gör icke det rätt är för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Lägger fördenskull bort alla orenlighet och alla ondsko, och anammer ordet med saktmodighet, som i eder plantadt är, det edra själar kan saliga göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Men varer ordets görare, och icke allenast hörare, bedragandes eder sjelfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Ty der någor är allenast ordsens hörare, och icke görare, han är lik den man, som sitt lekamliga ansigte skådar i en spegel;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Ty då han sig beskådat hafver, går han derifrån, och förgäter straxt hurudana han var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Men den der skådar uti frihetenes fullkomliga lag, och blifver deruti, och är icke en glömsker hörare, utan en görare, den samme varder salig uti sin gerning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Hvar nu någor ibland eder låter sig tycka, att han tjenar Gudi, och icke styrer sina tungo, utan bedrager sitt hjerta, hans Gudstjenst är fåfäng.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Detta är för Gudi och Fadren en ren och obesmittad Gudstjenst, söka faderlös och moderlös barn, och enkor, uti deras bedröfvelse, och behålla sig obesmittad af verldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mine bröder, håller det icke derföre, att tron på Jesum Christum, vår Herra till härlighetena, kan lida personers anseende.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Ty om uti edra församling komme en man med en guldring, och med en härlig klädnad; komme ock en fattig man i snöplig klädnad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Och I sågen på den som hafver de härliga kläden, och saden till honom: Sitt här väl; och dem fattiga saden I: Statt der, eller, sitt här vid mina fötter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Och betänken det icke rätt, utan varden domare, och gören en ond åtskilnad;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Hörer till, mine käre bröder: Hafver icke Gud utvalt de fattiga i denna verldene, de der rike voro på trona, och arfvingar till riket, som han lofvat hade dem som honom älska?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Men I hafven föraktat den fattiga. Förtrycka icke de rike eder med våld, och draga eder fram för rätten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Försmäda icke de det goda namnet, der I af nämnde ären?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Fullborden I den Konungsliga lagen efter Skriften: Älska din nästa, såsom dig sjelf; så gören I väl.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Men sen I efter personen, då synden I, och varden straffade af lagen, såsom öfverträdare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Ty om någor håller hela lagen, och syndar på ett, han är saker till allt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Ty den som sade: Du skall icke göra hor, han hafver ock sagt: Du skall icke dräpa. Hvar du nu icke gör hor, och dräper likväl, äst du lagsens öfverträdare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Så taler, och så görer, som de der skola genom frihetenes lag dömde varda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ty dom utan barmhertighet skall honom öfvergå, som barmhertighet icke gjort hafver; och barmhertigheten berömmer sig emot domen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Hvad hjelper det, mine bröder, om någor säger sig hafva trona, och hafver dock icke gerningarna? Kan ock tron göra honom salig?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Om en broder eller syster vore nakot, och fattades dagelig föda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Och någor edra sade till dem: Går i frid, värmer eder, och mätter eder; och gifver dem likväl intet hvad lekamen behöfver; hvad hulpe dem det?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Så ock tron, då hon icke hafver gerningarna, är hon död i sig sjelf.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Nu måtte någor säga: Du hafver trona, och jag hafver gerningarna; visa mig dina tro med dina gerningar, så vill jag ock visa dig mina tro med mina gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du tror, att en Gud är; der gör du rätt uti; djeflarna tro det ock, och bäfva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Vill du, fåfängelig menniska, veta att tron utan gerningar är död?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Vardt icke Abraham, vår fader, af gerningarna rättfärdigad, då han sin son Isaac offrade på altaret?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Ser du, att tron hafver medverkat i hans gerningar, och att tron är fullkommen vorden af gerningarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Och Skriften är fullkomnad, som säger: Abraham trodde Gudi, och det vardt honom räknadt till rättfärdighet; och vardt kallad Guds vän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Sen I nu, att af gerningarna rättfärdigas menniskan, och icke af trone allena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Sammalunda ock den skökan Rahab, vardt hon icke af gerningom rättfärdigad, då hon undfick sändningabåden, och släppte dem en annan väg ut?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Derföre, såsom kroppen utan anda är död, så är ock tron utan gerningar död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mine bröder, farer icke hvar man efter att vara lärare; vetande att vi dess större dom fåm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Ty i mång stycke fele vi alle; men den der icke felar uti ett ord, han är en fullkommen man, och kan regera hela lekamen med betsel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Si, vi läggom hästomen betsel i munnen, att de skola lyda oss, och omkastom deras hela kropp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Si ock skeppen, ehuru stor de äro, och af starkt väder drifvas, varda de dock likväl omvänd med ett litet roder, ehvart rodermannen vill.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Så är ock tungan en klen lem, och kommer stor ting åstad; si en liten eld, huru stor skog han upptänder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Och tungan är ock en eld, en verld full med orätt. Så är ock tungan ibland våra lemmar, och besmittar hela lekamen, och upptänder all vår umgängelse, då hon upptänd är af helvete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Ty all natur, både djurs, och foglars, och ormars, och deras som i hafvet äro, varder tam, och är tamd af menniskors natur;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Men tungan kan ingen menniska tämja, det oroliga onda, full med dödelig förgift.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Med henne prise vi Gud, och Fadren; och med henne bannom vi menniskorna, som äro skapade efter Guds liknelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Af samma mun går pris och bannor. Det bör icke, mine bröder, så vara.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Icke gifver en källa af ett hål både sött och bäskt vatten?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Icke kan fikonträt, mine bröder, bära oljo, eller vinträt fikon? Så kan ock ingen källa salt och sött vatten gifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Ho är vis och klok ibland eder, han bevise med sin goda umgängelse sina gerningar, uti saktmodighet och visdom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Om I hafven bittert nit och träto uti edart hjerta, berömmer eder icke, och ljuger icke emot sanningen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ty den visdom är icke ofvanefter kommen, utan är jordisk, mennisklig, och djefvulsk.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Ty hvar nit och träta är, der är ostadighet och allt ondt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Men den visdom, som ofvanefter är, han är först kysk, och sedan fridsam, saktmodig, låter säga sig, full med barmhertighet och goda frukter, opartisk, oskrymtelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Men rättfärdighetenes frukt varder sådd i frid, dem som frid hålla.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Hvadan äro örlig och krig ibland eder? Äro de icke deraf, af edrom begärelsom, som strida i edra lemmar?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'I begären, och fån intet; I hafven afund och nit, och kunnen intet vinna; I striden och örligen, och hafven intet, derföre att I intet bedjen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'I bedjen, och fån intet; ty I bedjen illa, nämliga att I det uti edra vällust förtära skolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'I horkarlar och horkonor, veten I icke, att verldenes vänskap är Guds ovänskap? Ho som verldenes vän vill vara, han varder Guds ovän.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Menen I att Skriften säger fåfängt: Anden, som bor uti eder, begärar emot hatet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Men han gifver rikeliga nåd. Ty Skriften säger: Gud står emot de högfärdiga; men dem ödmjukom gifver han nåd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Så varer nu Gudi underdånige; står emot djefvulen, så flyr han ifrån eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nalkens Gudi, så nalkas han eder. Rener edra händer, I syndare, och renser edor hjerta, I ostadige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Varer elände, och sörjer, och gråter: edart löje vände sig i gråt, och glädjen i sorg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Förnedrer eder för Herranom, så skall han eder upphöja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Förtaler icke hvarannan, käre bröder; den som förtalar sin broder, och dömer sin broder, han förtalar lagen, och dömer lagen; men dömer du lagen, så äst du icke lagsens görare, utan domare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Ty en är laggifvaren, som kan saliggöra, och fördöma; ho äst du, som dömer en annan?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nu väl, I som sägen: I dag, eller i morgon vilje vi gå uti den eller den staden, och vilje der ligga ett år, och handla, och vinna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Och veten icke hvad i morgon ske kan; ty hvad är edart lif? Ett damb äret, som en liten tid varar, och sedan försvinner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'För det I säga skullen: Om Herren vill, och vi lefve, så vilje vi göra det eller det.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Men nu berömmen I eder i edart högmod. All sådana berömmelse är ond.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Den der kan göra godt, och gör icke, honom är det synd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nu väl, I rike, gråter, och tjuter öfver edor uselhet, som eder öfverkomma skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Edre rikedomar äro förruttnade; edor kläder äro uppäten af mal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Edart guld och silfver är förrostadt, och deras rost skall vara eder till vittnesbörd, och skall uppäta edart kött såsom en eld. I hafven församlat eder ägodelar i yttersta dagarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Si, arbetarenas lön, som edart land afbergat hafva, hvilken I dem svikliga ifrå haft hafven, ropar; och deras rop, som afbergade, är inkommet i Herrans Zebaoths öron.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'I hafven lefvat i kräselighet på jordene, och haft edra vällust, och uppfödt edor hjerta, såsom på en slagtedag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'I hafven dömt och dödat den rättfärdiga, och han hafver eder intet emotståndit.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Så varer nu tålige, käre bröder, intill Herrans tillkommelse. Si, åkermannen väntar efter den kosteliga jordenes frukt, tåleliga bidandes, så länge han får ett morgonregn och aftonregn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Så varer ock I tålige, och styrker edor hjerta; ty Herrans tillkommelse är när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Sucker icke, käre bröder, emot hvarannan, på det I icke varden fördömde. Si, domaren är för dörrene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Tager, mine bröder, Propheterna för efterdömelse, till bedröfvelse och tålamod, hvilke talat hafva i Herrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Si, vi hålle dem saliga, som lidit hafva. Jobs tålamod hafven I hört, och Herrans ända hafven I sett; ty Herren är barmhertig, och en förbarmare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Öfver all ting, mine bröder, svärjer icke, hvarken vid himmelen, eller vid jordena, eller någon annan ed. Men edor ord skola vara: Ja, ja, Nej, nej; på det I icke skolen falla uti skrymteri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Lider någor ibland eder bedröfvelse; han bedje. Är någor vid godt mod, han sjunge psalmer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Är någor sjuk ibland eder, han kalle till sig Presterna i församlingene, och låte dem bedja öfver sig, och smörja med oljo uti Herrans Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Och trones bön skall hjelpa den sjuka, och Herren upprättar honom; och om han är stadd i synder, varda de honom förlåtna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekänner inbördes synderna, den ene dem andra, och beder för eder inbördes, att I helbregda varden; ty ens rättfärdigs mans bön förmår mycket, der hon allvar är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias var en menniska såsom vi, och han bad ena bön, att det icke skulle regna; och det regnade ock intet på jordena, i tre år och sex månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Och bad åter, och himmelen gaf regn, och jorden bar sin frukt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Käre bröder, om någor ibland eder fore vill ifrå sanningen, och någor omvände honom;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Han skall veta, att den der omvänder en syndare af hans vägars villo, han frälsar ena själ ifrå döden, och skyler all öfverträdelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, Jesu Christi Apostel, dem utkoradom främlingom, som bo här och der i Ponto, Galatien, Cappadocien, Asien, och Bithynien,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Efter Guds Faders försyn, genom Andans helgelse, till lydnona och Jesu Christi blods stänkelse. Nåd och frid föröke sig i eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Välsignad vare Gud, och vårs Herras Jesu Christi Fader, som oss för sin stora barmhertighet hafver födt på nytt till ett lefvandes hopp, genom Jesu Christi uppståndelse ifrå de döda;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Till oförgängeligit, obesmittadt, och ovanskeligit arf; hvilket i himmelen förvaradt är till eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Som med Guds magt bevarens genom trona till salighet, hvilken beredd är, att hon skall uppenbar varda i den yttersta tiden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'I hvilkom I eder fröjda skolen, I som nu en liten tid liden bedröfvelse, i margahanda försökelse, hvar så behöfves:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'På det edor tro skall rättsinnig och mycket kosteligare befunnen varda, än det förgängeliga guld som pröfvas med eld, till lof, pris och äro, när Christus Jesus blifver uppenbar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Hvilken I älsken, ändock I icke sen honom; den I ock nu tron uppå, och dock icke sen; så skolen I fröjda eder med osägeliga och härliga glädje;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Och få edor tros ändalykt, nämliga själarnas salighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Efter hvilken salighet Propheterne hafva sökt och ransakat, som propheterat hafva om den tillkommande nåd till eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Och hafva ransakat, på hvad eller hurudana tid Christi Ande utviste, den i dem var, och tillförene hade betygat de lidande, som i Christo äro, och den härlighet, som derefter följa skulle,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Hvilkom det ock uppenbaradt var: ty de hafva icke sig sjelfvom, utan oss, dermed tjent; hvilke stycker eder nu förkunnad äro, genom dem som eder Evangelium predikat hafva, genom den Helga Anda som sändes af himmelen, hvilket Änglomen ock lyster se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Derföre, begjorder edor sinnes länder, och varer nyktre, och sätter fullkomligit hopp till den nåd som eder tillbuden varder, genom Jesu Christi uppenbarelse,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Såsom lydaktig barn; och ställer eder icke såsom tillförene, då I uti fåvitsko lefden, efter begärelsen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Utan efter honom, som eder kallat hafver, och helig är, varer ock I helige uti all edor umgängelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Ty det är skrifvet: I skolen vara helige; ty jag är helig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Och efter I åkallen honom för en Fader, som dömer efter hvars och ens gerning, och hafver intet anseende till personen, så ser till att I, uti detta edart elände, vandren i räddhåga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Och veter, att I icke med förgängeligit silfver eller guld igenlöste ären ifrån edart fåfänga lefverne, efter fädernas sätt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Utan med Christi dyra blod, såsom med ett menlöst och obesmittadt lambs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Hvilken väl föresedd var för verldenes begynnelse; men uppenbarad i de yttersta tiderna, för edra skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Som genom honom tron på Gud; den honom uppväckt hafver ifrå de döda, och gifvit honom härlighet; på det I skullen hafva tro och hopp till Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Och görer edra själar kyska, i sanningenes lydno genom Andan, till oskrymtad broderlig kärlek; älsker eder storliga inbördes af rent hjerta;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Såsom de, som födde äro på nytt; icke af någor förgängelig säd, utan af oförgängelig, som är af lefvandes Guds ord, det evinnerliga blifver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ty allt kött är såsom gräs, och all menniskos härlighet såsom blomster på gräset; gräset är vissnadt, och blomstret är affallet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Men Herrans ord blifver evinnerliga; och det är det ord, som predikadt är ibland eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Så lägger nu bort alla ondsko, och allt svek, och skrymteri, och afund, och allt förtal;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Och åstunder förnuftenes mjölk, som intet svek vet, såsom nyfödd barn; på det att I uppväxen af henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Om I annars hafven smakat att Herren är god;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Till hvilken I komne ären, såsom till den lefvande stenen, som af menniskom förkastad är, men när Gudi utkorad och kostelig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'I ock, såsom lefvande stenar, uppbygger eder till ett andeligit hus, och till ett heligt Presterskap, till att offra andelig offer, som Gudi äro tacknämlig, genom Jesum Christum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Derföre håller ock Skriften: Si, jag lägger i Zion en utvald kostelig hörnsten, och hvilken som tror på honom, han skall icke komma på skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Eder, som tron, är han kostelig; men dem som icke tro är stenen, som byggningsmännerna hafva bortkastat, vorden till en hörnsten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Och en sten, der man stöter sig på, och en förargelseklippo dem som stöta sig på ordet, och tro icke derpå, der de till skickade voro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Men I ären det utvalda slägtet, det Konungsliga Presterskapet, det heliga folket, och det egendomsfolket; att I skolen kungöra hans dygd, som eder kallat hafver af mörkret, till sitt underliga ljus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'I, som tillförene icke voren folk, ären nu Guds folk; och I, som tillförene icke haden fått barmhertighet, hafven nu fått barmhertighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Käre bröder, jag förmanar eder, såsom främmande och elända, att I förvaren eder för köttsliga begärelser, hvilka strida emot själena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Och förer en god umgängelse ibland Hedningarna; på det de, som pläga förtala eder såsom illgerningsmän, måga se edra goda gerningar, och prisa Gud, när det i dagsljuset kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Varer underdånige all mennisklig ordning, för Herrans skull, ehvad det är Konungenom, såsom den öfversta,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Eller befallningsmännerna, såsom de der sände äro af honom, de onda till straff, och de goda till pris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Ty så är Guds vilje, att I med goda gerningar skolen igenstoppa munnen af de galna och oförståndiga menniskor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Såsom de frie, och icke såsom I hafven den frihet till att skyla ondskona med, utan såsom Guds tjenare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Varer hedersamme emot hvar man; älsker bröderna; frukter Gud; ärer Konungen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'I tjenare, varer underdånige edrom herrom med all fruktan; icke allenast dem godom och saktmodigom, utan ock dem genvördigom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Ty detta är nåd, om någor, för samvetets skull till Gud, fördrager bedröfvelse, och lider orätt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Ty hvad pris är det, om I för edra missgerningar slagne varden, och liden? Men när I för välgerningars skull liden, och hafven tålamod, det är nåd för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Ty dertill ären I kallade, efter ock Christus led för oss, låtandes oss en efterdömelse, att I skolen efterfölja hans fotspår;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Hvilken ingen synd gjort hade; och intet bedrägeri vardt funnet i hans mun;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'När han blef bannad, bannade han intet igen, och när han led, hotades han intet; utan ställde hämnden till den som rätt dömer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Hvilken våra synder sjelf offrade i sin lekamen på träd; på det vi skulle vara döde syndene, och lefva rättfärdighetene; genom hvilkens sår I ären helbregda vordne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Ty I voren såsom villfarande får; men I ären nu omvände till herdan, och edra själars Biskop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Sammalunda hustrurna, vare sina män underdåniga; på det ock de, som icke tro på ordet, måga af hustrurnas umgängelse, utan ord, blifva vunne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'När de förmärka edor kyska umgängelse med fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Hvilkas prydning icke skall vara utvärtes, med flätadt hår, eller kringhängande guld, eller i kostelig kläder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Utan om den fördolda menniskan i hjertat är utan vank, med saktmodigom och stillom anda, det är kosteligit för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Ty i så måtto hafva ock de helga qvinnor fordom prydt sig, de der satte sitt hopp till Gud, och voro sina män underdåniga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Såsom Sara var lydig Abrahe, kallandes honom herra; hvilkens döttrar I vordna ären, om I väl gören, och ären icke så förfärade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Sammaledes I män, bor när dem med förnuft, och gifver det qvinliga kärilet, såsom det der svagast är, sina äro; såsom ock medarfvingom till lifsens nåd; på det edra böner icke blifva förhindrade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Men på sistone, varer alle vid ett sinne, medlidande, broderlig kärlek hafvande till hvarannan, barmhertige, vänlige;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Icke vedergällande ondt för ondt, icke bannor för bannor; utan heldre tvärtemot, välsigner; vetandes att I ären dertill kallade, att I skolen ärfva välsignelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Ty den der vill älska lifvet, och se goda dagar, han stille sina tungo ifrå det ondt är, och sina läppar, att de icke tala bedrägeri;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Vände sig ifrå det ondt är, och göre det godt är; söke efter friden, och fare honom efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Ty Herrans ögon äro öfver de rättfärdiga, och hans öron till deras bön; men Herrans ansigte är öfver dem som ondt göra.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Och ho är den som kan göra eder skada, om I faren efter det goda?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ja, om I än något liden för rättfärdighetenes skull, ären I dock likväl salige. Frukter eder intet för deras trug; icke heller förskräcker eder;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Utan helger Herran Gud uti edor hjerta. Varer ock alltid redebogne till att svara hvarjom och enom, som begärar skäl till det hopp som i eder är; och det med saktmodighet och fruktan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Och hafver ett godt samvet; på det de, som vilja förtala eder såsom ogerningsmän, skola komma på skam, att de förlastat hafva edor goda umgängelse i Christo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Ty det är bättre, om Guds vilje så är, att I för goda gerningar liden, än för onda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Ty Christus led ock ena reso för syndernas skull, rättfärdig för orättfärdiga; på det han skulle offra oss Gudi, och är dödad efter köttet; men lefvande gjord efter Andan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'I dem samma gick han ock bort, och predikade för andarna i fängelset;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Som fordom icke trodde, när Gud en gång bidde, och tålamod hade i Noe tid, då arken byggdes, i hvilkom få, det är åtta själar, blefvo frälste genom vattnet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Hvilket nu ock oss saliga gör i dopet, som genom hint betydt är (icke att köttsens smittor afläggas, utan att man hafver ett godt samvet till Gud), genom Jesu Christi uppståndelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Hvilken är på Guds högra hand, uppfaren till himla; och honom äro Änglarna, och väldigheterna, och krafterna underdåniga.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Medan nu Christus lidit hafver i köttet för oss, så skolen I ock väpna eder med det samma sinnet; ty den der lider i köttet, han vänder åter af synden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'På det han den tiden, som tillbaka är i köttet, icke lefva skall efter menniskolusta, utan efter Guds vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Ty det är nog att vi, i förliden tid, hafve vårt lefverne förslitit efter Hedningarnas vilja, då vi vandrade i lösaktighet, i begärelse, i dryckenskap, i fråsseri, i svalg, och grufveliga afgudadyrkan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Och det synes dem sällsynt vara, att I icke löpen med dem uti samma slemma, oskickeliga väsende, och försmäden;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Hvilke skola göra räkenskap honom, som redo är döma lefvande och döda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Ty dertill är ock Evangelium predikadt för de döda, att de skola dömde varda efter menniskor, i köttet; men i Andanom lefva Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Men nu tillstundar änden på all ting. Så varer nu nyktre, och vakande till att bedja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Men öfver all ting hafver ju en brinnande kärlek inbördes; ty kärleken skyler ock all öfverträdelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Varer inbördes hvarannars herbergare, utan allt knorr.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Och varer tjenstaktige inbördes, hvar och en med den gåfvo som han hafver fått, såsom gode den margfaldeliga Guds nåds skaffare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Om någor talar, han tale såsom Guds ord; om någor hafver ett ämbete, han tjene såsom af den förmågo, som Gud gifver; på det Gud blifver ärad i all ting, genom Jesum Christum, hvilkom vare ära och våld evinnerliga. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mine käreste, förundrer eder icke på den hetta, som eder vederfars (den eder vederfars, att I skolen försökte varda), såsom eder hände något nytt;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Utan glädjens heldre, att I liden med Christo; på det I ock fröjdas och glädjas mågen uti hans härlighets uppenbarelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Salige ären I, om I för Christi Namns skull blifven försmådde; ty Anden, som är härlighetenes och Guds Ande, hvilas på eder; när dem blifver han försmådd, men när eder beprisad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Ingen ibland eder lide, såsom en mördare, tjuf, illgerningsman, eller som den der träder in i ens annars ämbete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Men lider han såsom en Christen, skämme sig intet; utan prise Gud för den delen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Ty tiden är, att domen skall begynnas på Guds hus; begynnes det på oss, hvad blifver då deras ändalykt, som icke tro Guds Evangelio?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Och blifver den rättfärdige med plats salig, hvar blifver då den ogudaktige och syndaren?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Derföre, de der lida efter Guds vilja, de skola befalla honom sina själar, såsom enom trofastom Skapare, med goda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Presterna, som äro ibland eder, förmanar jag, som ock är en Prest, och vittne till Christi pino, och delaktig i den härlighet som uppenbaras skall:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Föder Guds hjord, som är ibland eder; och hafver akt på honom, icke nödige, utan sjelfviljande; icke för slem vinnings skull, utan af en god vilja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Icke heller såsom herrar öfver sitt folk; utan varer hjordenom till efterdömelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Och sedan, då öfverste Herden uppenbar varder, skolen I undfå härlighetenes ovanskeliga krona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Sammalunda I unge, varer dem gamlom underdånige. Varer alle inbördes hvarannan underdånige, och håller eder hårdt vid ödmjukhetena; ty Gud står emot de högfärdiga, men de ödmjuka gifver han nåd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Så ödmjuker eder nu under Guds mägtiga hand, på det han eder upphöjer i sinom tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Alla edra omsorg kaster på honom; ty han hafver omsorg om eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Varer nyktre, och vaker; ty edar fiende, djefvulen, går omkring såsom ett rytande lejon, och söker hvem han uppsluka må.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Står honom emot, stadige i trone; och veter, att samma vedermöda vederfars edra bröder i verldene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Men Gud, som all nåd kommer af, den eder kallat hafver till sin eviga härlighet i Christo Jesu, han fullborde eder, som en liten tid liden, styrke, stödje och stadfäste;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Honom vare ära, och magt evinnerliga. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Med edar trogna broder Silvanus, som jag menar, hafver jag eder tillskrifvit med få ord, förmanandes och betygandes, att detta är den rätta Guds nåd, som I uti stån.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Helsar eder den församling i Babylonien, utvald lika med eder; och min son Marcus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Helser eder inbördes med kärlekens kyss. Frid vare med eder allom, som äro i Christo Jesu. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petrus, Jesu Christi tjenare och Apostel; dem som med oss lika dyrbara tro fått hafva i rättfärdighetene, som vår Gud gifver, och Frälsaren Jesus Christus.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Nåd och frid föröke sig i eder, genom Guds och vårs Herras Jesu Christi kunskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Efter det allahanda af hans Gudoms kraft, hvad som till lif och Gudaktighet tjenar, oss skänkt är, genom hans kunskap, som oss hafver kallat genom (sina) härlighet och dygd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Genom hvilka oss de dyra och aldra största löfte gifna äro; nämliga, att I derigenom mågen blifva delaktige af Guds natur, om I flyn verldenes förgängeliga lusta:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Så lägger eder nu derom alla vinning, att I uti edra tro låten finnas dygd, och i dygdene beskedelighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'I beskedelighetene måttelighet, i måttelighetene tålamod, i tålamodet Gudaktighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'I Gudaktighetene broderlig kärlek, i broderlig kärlek allmännelig kärlek.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Ty när dessa stycker äro rikeliga när eder, så låta de eder icke finnas fåfänga eller utan frukt, i vårs Herras Jesu Christi kunskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Men hvilken denna icke hafver, han är blind, och ser intet, och hafver förgätit, att han var ren gjord af de synder, som han förra hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Derföre, käre bröder, lägger eder heldre vinning om att I gören edor kallelse och utkorelse fast; ty om I det gören, så fallen I icke någon tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Ty i så måtto blifver eder rikeliga gifven ingången i vårs Herras och Frälsares Jesu Christi eviga rike.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Derföre vill jag icke hafva fördrag att förmana eder alltid härom, ändock I det veten, och ären stadfäste i denna närvarande sanning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ty jag menar det vara tillbörligit, så länge jag är i denna hyddo, att uppväcka och förmana eder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Ty jag vet att jag skall snarliga aflägga denna mina hyddo, såsom ock vår Herre Jesus Christus hafver mig kungjort.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Men jag vill vinnlägga mig att I, efter min död, skolen behålla detta i åminnelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Ty vi hafve icke efterföljt några kloka fabler, då vi kungjordom eder vårs Herras Jesu Christi kraft och tillkommelse; utan vi hafve sjelfve sett hans härlighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Då han fick af Gud Fader äro och pris, genom ena röst, som till honom skedde af den stora härligheten, så lydandes: Denne är min älskelige Son, i hvilkom jag hafver ett godt behag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Och denna röst hörde vi komma af himmelen, då vi vorom med honom på det helga berget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Vi hafvom ett fast prophetiskt ord; och I gören väl att I akten derpå, lika som på ett ljus, som skin uti ett mörkt rum, så länge det dagas, och morgonstjernan uppgår i edor hjerta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Och det skolen I först veta, att ingen Prophetia i Skriftene sker af egen utläggning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Ty ingen Prophetia är ännu framkommen af menniskovilja; utan de helga Guds menniskor hafva talat, rörde af dem Helga Anda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Men falske Propheter voro ock ibland folket, som ock ibland eder varda skola falske lärare; hvilke med ibland införa skola förderfvelig partier, och förneka Herran, som dem köpt hafver; och skola föra öfver sig sjelfva en hastig fördömelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Och månge skola efterfölja deras förderf; genom hvilka sanningenes väg blifver försmädd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Och uti girighet, med diktad ord, skola de handla med eder; hvilkom domen nu längesedan icke sen är, och deras fördömelse sofver icke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ty hafver Gud icke skonat Änglomen, som syndade, utan hafver dem med mörksens kedjor nederkastat till helvetes, öfverantvardandes till att förvaras till domen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Och hafver icke skonat den förra verldene; utan bevarat Noe, rättfärdighetenes Predikare, sjelf åttonde, och lät floden gå öfver de ogudaktigas verld;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Och hafver gjort de städer Sodoma och Gomorra till asko, omstört och fördömt dem; och satt för ett efterdömelse dem ogudaktigom, som sedan komma skulle;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Och hafver frälst den rättfärdiga Lot, som var plågad af skamliga menniskor, genom deras sköraktiga umgängelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Ty efter han var rättfärdig, och bodde ibland dem, och måste dock sådana se och höra, plågade de dageligen den rättfärdiga själen med sina onda gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Herren kan frälsa de gudaktiga utaf frestelsen, men behålla de orättfärdiga till domedag, till att pinas;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Men aldramest dem som vandra efter köttet, uti orenom lusta, och försmå herrskapet, öfverdådige, ensinnade, och intet rädas försmäda väldigheterna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Ändock Änglarna, som i kraftene och starkhetene större äro, icke draga kunna den försmädeliga domen emot sig, af Herranom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Men de äro såsom de oförnuftiga djur, som af naturen dertill födda äro, att de skola fångna och slagtade varda; försmäda det de intet förstå, och skola uti sitt förderfveliga väsende förgås;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Och få orättfärdighetenes lön. De hållat för vällust, att de lefva i timeliga kräselighet; de äro slemheter och skamfläckar; pråla af edra gåfvor, slösa med edart;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Hafva ögonen full med horeri, låta icke förmena sig syndena, och locka till sig de istadiga själar; hafva sin hjerta genomöfvad i girighet; förbannadt folk;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'öfvergifva rätta vägen, och gå ville, och efterfölja Balaams, Bosors sons väg, hvilken älskade vrånghetenes lön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Men han blef straffad för sin vrånghet; det stumma arbetsdjuret talade med menniskoröst, och förtog Prophetens galenskap.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'De äro källor utan vatten, och molnskyr, som af vädret drifvas; hvilkom förvaradt är ett svart mörker, till evig tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ty de tala stolt ord, som äro fåfäng: och igenom otukt locka dem till köttslig lusta, som rättsliga undsluppne voro, och ännu vandra i villfarelse;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Och lofva dem frihet, ändock de sjelfve äro förderfvelsens tjenare; ty af hvem någor öfvervunnen varder, hans tjenare är han vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Ty sedan de, genom Herrans och Frälsarens Jesu Christi kunskap, undflytt hafva verldenes orenlighet, och hafva åter bevefvat sig deruti, och äro öfvervunne, är dem det yttersta värre vordet än det första.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Och hade dem bättre varit intet förståndit rättfärdighetenes väg, än, sedan de förstodo, vända sig ifrå det helga budet, som de anammat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Dem är vederfaret det som för ett sant ordspråk plägar sägas: Hunden går åter till sina spyo; och svinet, som tvaget är, sölar sig åter i träcken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Detta är nu den andra Epistelen, som jag skrifver eder till, mine käreste, i hvilko jag uppväcker och förmanar edart rena sinne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Att I ihågkommen de ord, som tillförene sagd äro af de heliga Propheter; och desslikes vårt bud, vi som ärom Herrans och Frälsarens Apostlar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Och veter det i förstone, att i yttersta dagarna varda kommande bespottare, som vandra efter sin egen lusta:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Och säga: Hvar är nu det löfte om hans tillkommelse? Ty ifrå den dag fäderne äro afsomnade, blifver allt såsom det af kreaturens begynnelse varit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Men sjelfviljande vilja de icke veta, att himlarna hafva ock varit i förtiden, och jorden af vattnet, och i vattnena bestånd haft, genom Guds ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Likväl vardt på den tid verlden, genom de samma, med flodene förderfvad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Sammalunda ock nu himlarna och jorden varda genom hans ord sparde, att de skola varda eldenom förvarade till domedag, då de ogudaktiga menniskor fördömas skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Men ett skall eder icke fördoldt vara, mine käreste, att en dag för Herranom är såsom tusende år, och tusende år såsom en dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Herren fördröjer intet sitt löfte, såsom somlige mena det vara fördröjelse; men han hafver tålamod med oss, och vill icke att någre skola förgås, utan att hvar och en vänder sig till bättring.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Men Herrans dag varder kommandes såsom en tjuf om natten; och då skola himlarna med en stor hastighet förgås, och elementen skola försmälta af hetta, och jorden, med de verk, som derpå äro, skola afbrännas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Efter nu allt detta skall förgås, hurudana bör eder då vara, uti helig umgängelse och Gudaktighet?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Så att I vänten och åstunden efter Guds dags tillkommelse; i hvilkom himlarna af eld förgås skola, och elementen försmälta af hetta.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Men nya himlar och en ny jord väntom vi, efter hans löfte, der rättfärdighet uti bor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Derföre, mine käreste, medan I detta vänten, så lägger eder vinning om att I obesmittade och ostraftelige för honom finnas mågen i frid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Och vårs Herras Jesu Christi tålamod räkner för edra salighet; såsom ock vår käre broder, Paulus, efter den vishet som honom gifven är, hafver skrifvit eder till;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Såsom han ock i all bref talar om sådana stycker; ibland hvilka något är som är svårt till förstå, det de olärde och lösaktige förvärra, såsom ock andra skrifter, till sin egen förtappelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Men I, mine käreste, medan I veten det tillförene, så förvarer eder, att I icke förförde varden genom de ogudaktigas villfarelse, samt med dem, och fallen ifrå eder egen stadighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Utan växer i nådene, och vårs Herras och Frälsares Jesu Christi kunskap. Honom vare ära, nu och till evig tid. Amen.');
