INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Detta är Jesu Christi uppenbarelse, den Gud hafver gifvit honom, till att förkunna sinom tjenarom, hvad innan kort tid ske skall; och hafver betecknat och sändt, med sin Ängel, till sin tjenare Johannem;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Hvilken betygat hafver Guds ord och vittnesbörd om Jesu Christo, hvad han sett hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Salig är den som läs och hörer denna Propheties ord, och håller det deruti skrifvet är; ty tiden är när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes, de sju församlingar i Asien: Nåd vare med eder, och frid af honom som är, och som var, och som komma skall, och af de sju Andar som för hans stol äro;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Och af Jesu Christo, som är ett troget vittne, förstfödder ifrå de döda, och en Förste öfver Konungarna på jordene; den oss älskat hafver, och tvagit oss af våra synder med sitt blod;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Och gjort oss till Konungar och Prester för Gudi, och sinom Fader. Honom vare ära och välde, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Si, han kommer, med skyn, och all ögon skola se honom, och de honom stungit hafva, och all slägte på jordene skola jämra sig; ja, Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jag är A och O, begynnelsen och änden, säger Herren, som är, som var, och som komma skall, den Allsmägtige.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Jag, Johannes, edar broder, och delaktig i bedröfvelsen, och i riket, och i Jesu Christi tålamod, var på den ön Pathmos, för Guds ords skull, och för Jesu Christi vittnesbörds skull.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Jag var i andanom, på en Söndag, och hörde efter mig en stor röst, såsom en basun;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Sägandes: Jag är A och O, den förste och den siste. Hvad du ser, det skrif uti ena bok, och sänd till de församlingar, som äro i Asien, i Epheso, och i Smirnen, och i Pergame, och i Thyatira, och i Sardis, och i Philadelphia, och i Laodicea.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Och jag vände mig om till att se efter rösten, som med mig talade; och som jag mig vände, såg jag sju gyldene ljusastakar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Och midt ibland de sju gyldene ljusastakar en, som lik var menniskones Son, klädd i en sid kjortel, och begjordad kring om bröstet med ett gyldene bälte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Men hans hufvud och hans hår var hvitt, som en hvit ull, och såsom snö; och hans ögon voro såsom en eldslåge.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Och hans fötter voro såsom glödande messing i ugnen, och hans röst såsom en dön af mycket vatten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Och han hade i sine högra hand sju stjernor, och af hans mun utgick ett skarpt tveeggadt svärd; och hans ansigte sken såsom klara solen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Och då jag såg honom, föll jag till hans fötter, såsom jag hade varit död; och han lade sin högra hand på mig, och sade till mig: Var icke förfärad; jag är den förste och den siste;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Och den lefvande; och jag var död, och si, jag är lefvandes, ifrån evighet till evighet: Amen; och hafver nycklarna till helvetet och döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Så skrif nu hvad du sett hafver, och hvad nu är, och hvad härefter ske skall;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Hemligheten af de sju stjernor, som du sett hafver i mine högra hand, och de sju gyldene ljusastakar: De sju stjernor äro de sju församlingars Änglar; och de sju ljusastakar, som du sett hafver, äro de sju församlingar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Och skrif den församlings Ängel i Epheso: Detta säger han, som hafver sju stjernor i sine högra hand, den der vandrar midt ibland de sju gyldene ljusastakar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Jag vet dina gerningar, och ditt arbete, och ditt tålamod, och att du icke må lida de onda, och hafver försökt dem som säga att de äro Apostlar, och äro dock icke, och hafver befunnit dem ljugare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Och du lider och hafver tålamod, och arbetar för mitt Namns skull, och är icke trött vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Men jag hafver emot dig, att du den första din kärlek öfvergifvit hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Betänk derföre hvaraf du fallen äst, och bättra dig, och gör de första gerningarna; hvar det icke sker, då varder jag dig snarliga kommandes, och skall bortstöta din ljusastaka af sitt rum, utan du bättrar dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Men detta hafver du, att du hatar de Nicolaiters verk, hvilka jag ock hatar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Den der öra hafver, han höre hvad Anden säger församlingarna: Den der vinner, honom vill jag gifva äta af lifsens trä, som är i Guds Paradis.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Och skrif den församlings Ängel i Smirnen: Detta säger den förste och den siste, den död var, och är lefvandes vorden:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Jag vet dina gerningar och din bedröfvelse, och din fattigdom (men du äst rik), och hädelse af dem som sig säga vara Judar, och äro icke, utan äro Satans hop.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Frukta intet för något, som du lida skall. Si, djefvulen skall kasta några af eder i fängelse, på det I skolen försökte varda, och hafva bedröfvelse i tio dagar. Var trofast intill döden, så skall jag gifva dig lifsens krono.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Den der öra hafver, han höre hvad Anden säger församlingarna. Den der vinner, han skall ingen skada få af den andra döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Och skrif den församlings Ängel i Pergamen: Detta säger han, som hafver det skarpa tveeggade svärdet:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Jag vet dina gerningar, och hvar du bor, att der Satans säte är; och du håller mitt Namn, och hafver icke nekat mina tro; och i de dagar är Antipas, mitt trogna vittne, dödader när eder, der Satan bor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Men jag hafver något litet emot dig; ty du hafver der dem, som hålla Balaams lärdom, hvilken lärde genom Balak åstadkomma förargelse för Israels barn, till att äta af det afgudom offradt var, och bedrifva boleri;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Så hafver du ock dem, som hålla de Nicolaiters lärdom, hvilket jag hatar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Bättra dig; annars skall jag dig snarliga komma, och skall strida med dem, med mins muns svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Den der öra hafver, han höre hvad Anden säger församlingarna. Den der vinner, honom vill jag gifva äta af det fördolda Manna, och vill gifva honom ett godt vittnesbörd, och med det vittnesbörd ett nytt namn beskrifvet, det ingen känner, utan den det får.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Ock skrif den församlings Ängel i Thyatira: Detta säger Guds Son, som ögon hafver såsom eldslåge, och hans fötter lika som messing;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Jag vet dina gerningar, och din kärlek, och dina tjenst, och dina tro, och ditt tålamod, och dina gerningar, de sista flere än de första.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Men jag hafver något litet emot dig, att du tillstädjer den qvinnan Jesabel, som säger att hon är en Prophetissa, lära och bedraga mina tjenare, bedrifva boleri, och äta af det afgudom offradt är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Och jag hafver gifvit henne tid, att hon skulle bättra sig af sitt boleri; och hon hafver intet bättrat sig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Si, jag skall lägga henne i sängena; och de som med henne hor bedrifva, skola komma uti aldrastörsta bedröfvelse, om de icke bättra sig af sina gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Och hennes barn skall jag dräpa; och alla församlingar skola veta, att jag är den som ransakar njurar och hjerta; och skall gifva hvarjom och enom af eder efter hans gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Men eder säger jag, och androm som i Thyatira ären, som icke hafva sådana lärdom, och icke hafva förstått Satans djuphet, såsom de säga: Jag skall icke lägga på eder några andra bördo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Dock hvad I hafven, det håller, så länge jag kommer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Och den der vinner, och håller min verk intill ändan, honom skall jag gifva magt öfver Hedningarna;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Och han skall regera dem med jernris; och han skall sönderkrossa dem såsom en pottomakares käril;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Såsom jag ock fått hafver af minom Fader, och vill gifva honom morgonstjernona.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Skrif ock församlingenes Ängel i Sardis: Detta säger den, som hafver de sju Guds Andar, och de sju stjernor: Jag vet dina gerningar; ty du hafver namnet att du lefver, och äst död.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Var vaken, och stärk det andra som dö vill; ty jag hafver icke befunnit dina gerningar fullkomliga för Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Så tänk nu på hvad du fått och hört hafver, och håll det, och bättra dig; äst du icke vaken, så skall jag komma till dig som en tjuf plägar komma, och du skall icke veta på hvad stund jag kommer till dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Du hafver ock få namn i Sardis, som sin kläder icke besmittat hafva, och de skola vandra med mig i hvit kläder, ty de äro dess värde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Den som vinner, han skall klädder varda med hvit kläder; och jag skall icke utskrapa hans namn af lifsens bok; och jag skall vederkänna hans namn för min Fader, och för hans Änglar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Skrif ock den församlings Ängel i Philadelphia: Detta säger den Helige, och den Sannfärdige, som hafver Davids nyckel, den der upplåter, och ingen menniska igenlåter; den der igenlåter, och ingen menniska upplåter;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Jag vet dina gerningar. Si, jag hafver gifvit dig en öppen dörr, och ingen kan låta henne igen; ty du hafver liten kraft, och du hafver hållit min ord, och hafver icke nekat mitt Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Si, jag vill gifva dig utu Satans hop; de sig säga vara Judar, och äro icke, utan ljuga. Si, jag vill drifva dem dertill, att de skola komma och tillbedja för dina fötter, och skola veta att jag hafver älskat dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Efter du hafver hållit mitt tålamods ord, skall jag ock bevara dig för frestelsens stund, hvilken tillstundar allo verldene, till att fresta dem som bo på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Si, jag kommer snarliga; håll det du hafver, att ingen tager dina krono.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Den der vinner, honom vill jag göra till en pelare uti mins Guds tempel, och han skall icke mer utgå; och jag skall skrifva på honom mins Guds Namn, och mins Guds stads, dess nya Jerusalems, namn, som nederkommer af himmelen ifrå min Gud, och mitt nya Namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Skrif ock den församlings Ängel i Laodicea: Detta säger Amen, det trogna och sannfärdiga vittnet, begynnelsen till Guds kreatur:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Jag vet dina gerningar, att du äst hvarken kall eller varm; jag ville att du vore antingen kall, eller varm.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Men efter du äst ljum, och hvarken kall eller varm, skall jag dig utspy utu min mun.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ty du säger: Jag är rik, och hafver nog, och behöfver intet; och vetst icke att du äst elände, och jämmerlig, fattig, och blind, och nakot.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Jag råder dig att du köper guld af mig, det genomeldadt och bepröfvadt är, att du må blifva rik; och hvit kläder, som du må kläda dig uti, på det dine nakenhets blygd icke skall synas; och smörj din ögon med ögnasalvo, att du må få se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'De jag älskar, dem agar jag och näpser. Så var nu flitig, och bättra dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Si, jag står för dörrene och klappar; den der hörer mina röst, och upplåter dörrena, till honom skall jag ingå, och hålla nattvard med honom, och han med mig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Den der vinner, honom skall jag sitta låta med mig på min stol, såsom ock jag vunnit hafver, och är sittandes vorden med minom Fader på hans stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Sedan såg jag, och si, en dörr vardt upplåten i himmelen; och den första rösten, som jag hörde, såsom en basun, med mig tala, sade: Stig här upp; jag vill visa dig, hvad ske skall härefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Och straxt var jag i Andanom; och si, en stol vardt satt i himmelen, och på stolen satt en.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Och den der satt, han var påseende såsom den stenen jaspis, och sardis; och en regnbåge var om stolen, påseendes såsom en smaragd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Och kringom stolen voro fyra och tjugu stolar; och på de stolar såto fyra och tjugu äldste, klädde med hvit kläder, och på deras hufvud voro gyldene kronor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Och af stolenom utgingo ljungeld, tordön och röster; och sju eldslampor brunno för stolen; hvilka äro de sju Guds Andar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Och framför stolen var såsom ett glashaf, likt vid christall; och midt i stolen, och kringom stolen, fyra djur full med ögon, både före och bak.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Och det första djuret var likt ett lejon; och det andra djuret likt enom kalf; och det tredje djuret hade ett ansigte såsom en menniska; och det fjerde djuret likt enom flygande örn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Och de fyra djur hade hvartdera sex vingar allt omkring, och de voro innantill full med ögon, och hade ingen ro dag eller natt, och sade: Helig, Helig, Helig är Herren Gud allsmägtig, som var, och som är, och som komma skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Och då de djuren gåfvo honom pris, och äro, och tack, som satt på stolen, den der lefver ifrån evighet till evighet,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Föllo de fyra och tjugu äldste framför honom, som satt på stolen, och tillbådo den der lefver ifrån evighet till evighet; och kastade sina kronor för stolen, och sade:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Herre, du äst värdig taga pris, och äro, och kraft; ty du hafver skapat all ting, och för din viljas skull hafva de varelse, och äro skapt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Och jag såg i hans högra hand, som satt på stolen, ena bok skrifven innan och utan, beseglad med sju insegel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Och jag såg en stark Ängel, som predikade med höga röst: Ho är värdig upplåta bokena, och uppbryta hennes insegel?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Och ingen i himmelen, eller på jordene, eller under jordene, kunde upplåta bokena, och icke heller se på henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Och jag gret svårliga, att ingen vardt funnen värdig till att upplåta bokena, och läsa henne, eller se på henne;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Och en af de äldsta sade till mig: Gråt icke. Si, Lejonet af Juda slägte, Davids rot, hafver vunnit till att upplåta bokena, och uppbryta hennes sju insegel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Och jag såg, och si, midt i stolen, och ibland de fyra djuren, och midt ibland de äldsta stod ett Lamb, såsom det hade slagtadt varit, och hade sju horn, och sju ögon, hvilka äro de sju Guds Andar sände i all land.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Och det kom, och tog bokena utaf hans högra hand, som satt på stolen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Och då det hade tagit bokena, föllo de fyra djur, och de fyra och tjugu äldste framför Lambet, hafvande hvar och en harpor och gyldene skålar fulla med rökverk, hvilket är de heligas böner;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Och söngo en ny sång, och sade: Du äst värdig att taga bokena, och upplåta hennes insegel; ty du äst dödad, och hafver igenlöst oss Gudi med ditt blod, af allahanda slägte och tungomål, och folk och Hedningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Och hafver gjort oss vårom Gudi till Konungar och Prester; och vi skole regnera på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Och jag såg, och hörde en röst af många Änglar, kringom stolen och kringom djuren, och kringom de äldsta, och talet på dem var mång sinom tusende tusend;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Sägande med höga röst: Lambet, som dödadt är, det är värdigt att hafva kraft, och rikedom, och visdom, och starkhet, och äro, och pris, och lof.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Och all kreatur, som i himmelen äro, och de på jordene, och de under jordene, och i hafvet, och allt det uti dem är, hörde jag säga till honom, som satt på stolen, och till Lambet: Lof, och ära, och pris, och kraft, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Och de fyra djuren sade: Amen; och de fyra och tjugu äldste föllo ned (på sin ansigte), och tillbådo honom, som lefver ifrån evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Och jag såg, att Lambet uppbröt ett af inseglen, och jag hörde ett af de fyra djuren säga, såsom med tordönsröst: Kom, och se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Och jag såg, och si, en hvit häst; och den derpå satt, hade en båga, och honom vardt gifven en krona; och han for ut till att vinna, och få seger.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Och då det uppbröt det andra inseglet, hörde jag det andra djuret säga: Kom, och se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Och der utgick en annar häst, röd; och honom, som derpå satt, vardt gifvet att han skulle borttaga friden af jordene, och att de skulle slå sig ihjäl inbördes; och honom vardt gifvet ett stort svärd.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Och då det uppbröt det tredje inseglet, hörde jag det tredje djuret säga: Kom, och se. Och jag såg, och si, en svart häst; och den der satt på honom hade ena vågskål i sine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Och jag hörde ena röst midt ibland de fyra djur, sägandes: Ett mått hvete om en penning, och tre mått bjugg om en penning; och oljone och vinet gör ingen skada.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Och då det uppbröt det fjerde inseglet, hörde jag dess fjerde djursens röst säga: Kom, och se.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Och jag såg, och si, en black häst; och den som på honom satt, hans namn var döden, och helvetet följde honom efter; och dem vardt magt gifven öfver fjerde parten på jordene, att döda med svärd, och med hunger, och med döden af de vilddjur på jordene äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Och då det uppbröt det femte inseglet, såg jag, under altaret, deras själar, som dödade voro för Guds ords skull, och för det vittnesbörds skull, som de hade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Och de ropade med höga röst, och sade: Herre, du som äst helig och sannfärdig, huru länge dömer du icke, och hämnas icke vårt blod på dem, som bo på jordene?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Och dem vardt gifvet hvarjom och enom ett sidt hvitt kläde, och till dem vardt sagdt, att de skulle ännu hvilas en liten tid, till dess talet blefve fullt af deras medtjenare och bröder, de der ock skola dödade varda, såsom ock de.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Och jag såg, att det uppbröt det sjette inseglet; och si, då vardt en stor jordbäfning, och solen vardt svart som en hårsäck, och månen vardt alltsammans såsom blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Och stjernorna föllo af himmelen ned på jordena, såsom fikonaträt sin fikon nedersläpper, då det ristes af stort väder.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Och himmelen gick bort, såsom en tillslagen bok; och all berg och öar vordo rörd af sitt rum.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Och Konungarna på jordene, och de öfverste, och rike, och höfvitsmän, och väldige och alle tjenare, och alle frie, fördolde sig uti jordkulor, och i bergskrefvor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Och sade till berg och klippor: Faller öfver oss, och skyler oss för hans ansigte, som sitter på stolen, och för Lambsens vrede;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Ty den store hans vredes dag är kommen; och ho kan bestå?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Sedan såg jag fyra Änglar stå på fyra jordenes hörn, hållande fyra jordenes väder, att intet väder skulle blåsa på jordena, eller på hafvet, eller på något trä.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Och jag såg en annan Ängel uppstiga ifrå solens uppgång; han hade lefvandes Guds insegel, och ropade med höga röst till de fyra Änglar, hvilkom gifvet var skada göra jordene och hafvena;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Och sade: Görer icke jordene skada, eller hafvena, eller trän, så länge vi med insegel tecknom vår Guds tjenare på deras anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Och jag hörde talet på dem, som tecknade voro, hundrade fyra och fyratio tusend, som tecknade voro, af all Israels barnas slägter:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Af Juda slägte tolftusend tecknade; af Rubens slägte tolftusend tecknade; af Gads slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Af Assers slägte tolftusend tecknade; af Nephthali slägte tolftusend tecknade; af Manasse slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Af Simeons slägte tolftusend tecknade; af Levi slägte tolftusend tecknade; af Isaschars slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Af Zabulons slägte tolftusend tecknade; af Josephs slägte tolftusend tecknade; af BenJamins slägte tolftusend tecknade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Sedan såg jag, och si, en stor skare, den ingen räkna kunde, af allom Hedningom, och slägtom, och folkom, och tungomålom, ståndande för stolen, och för Lambena, klädd i sid hvit kläder, och palmer i deras händer;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Och de ropade med höga röst, och sade: Salighet honom, som sitter på stolen, vårom Gudi och Lambena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Och alle Änglar stodo kringom stolen, och om de äldsta, och om de fyra djuren, och föllo på sin ansigte framför stolen, och tillbådo Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Och sade: Amen, lof, och ära, och vishet, och tack, och pris, och kraft, och starkhet vare vårom Gud, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Och en af de äldsta svarade, och sade till mig: Ho äro desse, som uti de sida hvita kläder klädde äro? Och hvadan äro de komne?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Och jag sade till honom: Herre, du vetst det. Och han sade till mig: Desse äro de som komne äro utu stor bedröfvelse, och hafva tvagit sin kläder, och gjort dem hvit i Lambsens blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Derföre äro de för Guds stol, och tjena honom dag och natt uti hans tempel; och den på stolen sitter, skall bo öfver dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'De skola intet mer hungra, eller törsta; icke heller skall solen falla på dem, icke heller någon hette;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Ty Lambet, som midt i stolen är, skall regera dem, och leda dem till lefvande vattukällor; och Gud skall aftorka alla tårar af deras ögon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Och då det uppbröt det sjunde inseglet, vardt en tysta i himmelen vid en half stund.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Och jag såg sju Änglar stå för Gud, och dem vordo gifne sju basuner.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Och en annar Ängel kom, och stod för altaret, och hade ett gyldene rökelsekar; och honom vardt gifvet mycket rökverk, på det han skulle gifva till all helgons böner på gyldene altaret, som är för stolenom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Och rökverksens rök, af helgonens böner, gick upp af Ängelens hand för Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Och Ängelen tog rökelsekaret, och uppfyllde det med eld af altaret, och kastade ned på jordena; och der skedde tordön, röster, och ljungeld, och jordbäfning.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Och de sju Änglar, med de sju basuner, skickade sig till att basuna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Och den förste Ängelen basunade; och vardt ett hagel och eld, bemängdt med blod, och det vardt kastadt på jordena; och tredjeparten af trän vardt uppbränd, och allt grönt gräs brann upp.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Och den andre Ängelen basunade; och uti hafvet vardt kastadt såsom ett stort brinnande berg, och tredjeparten af hafvet vardt blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Och tredjeparten af de lefvande kreatur, som i hafvet voro, blefvo döde; och tredjeparten af skeppen förgingos.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Och den tredje Ängelen basunade; och en stor stjerna föll ned af himmelen, brinnandes som ett bloss; och föll uti tredjeparten af älfverna, och uti vattukällorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Och stjernones namn kallas malört; och tredjeparten vändes i malört, och många menniskor blefvo döda af vattnet, som förbittradt vardt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Och den fjerde Ängelen basunade; och tredje parten af solene vardt slagen, och tredjeparten af månan, och tredjeparten af stjernorna, så att tredjeparten af dem vardt förmörkrad, och tredjedelen af dagen intet skina kunde, och af nattene sammalunda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Och jag såg, och hörde en Ängel, som flög midt igenom himmelen, och sade med höga röst: Ve, ve, ve dem som bo på jordene, för de andra röster af de tre Änglars basuner, som ännu basuna skola.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Och den femte Ängelen basunade; och jag såg ena stjerno falla af himmelen på jordena; och honom vardt gifven nyckelen till afgrundens brunn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Och han upplät afgrundens brunn, och der uppgick en rök, såsom af en stor ugn; och solen och vädret vordo förmörkrad af brunsens rök.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Och utu röken kommo gräshoppor på jordena; och dem vardt gifven magt, såsom scorpioner på jordene magt hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Och vardt sagdt till dem, att de icke skulle göra gräset på jordene skada, icke heller något det grönt var, icke heller något trä; utan allena menniskorna, de som icke hade Guds tecken i sin anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Och dem vardt gifvet, att de icke skulle döda dem; utan att de skulle qvälja dem i fem månader; och deras qval var såsom qval af scorpion, då han hafver stungit menniskorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Och i de dagar skola menniskorna söka efter döden, och skola icke finna honom, och de skola begära dö, och döden skall fly ifrån dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Och de gräshoppor äro lika de hästar, som till krigs beredde äro, och på deras hufvud såsom kronor gulde lika, och deras ansigte såsom menniskors ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Och de hade hår såsom qvinnohår, och deras tänder voro såsom lejons;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Och hade pansar såsom jernpansar, och bullret af deras vingar såsom vagnsbuller, der månge hästar löpa till krigs;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Och hade stjertar såsom scorpioner, och gaddar voro i deras stjertar; och deras magt var till att qvälja menniskorna i fem månader;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Och hade öfver sig en Konung, en Ängel af afgrunden, hvilkens namn på Ebreisko heter Abaddon, på Grekisko Apollyon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Ett Ve är framfaret, och si, här komma ännu tu annor Ve efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Och den sjette Ängelen basunade, och jag hörde ena röst af de fyra hörn af det gyldene altaret, som är för Guds ögon:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Och sade till den sjette Ängelen, som basunen hade: Lös de fyra Änglar, som bundne äro uti den stora älfven Euphrates.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Och de fyra Änglar vordo löse, hvilke beredde voro till ena stund, till en dag, till en månad, och till ett år, att de skulle döda tredjeparten af menniskorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Och talet på det resigtyget var mång sinom tusende tusend, och jag hörde deras tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Och så såg jag ock hästarna i synene, och de som såto på dem, de hade glödande, gula, och svafvels pansar; och hufvuden på hästarna voro såsom lejonahufvud; och af deras mun utgick eld, och rök, och svafvel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Af dessa tre plågor vardt dödad tredjeparten af menniskorna, af elden, och röken, och svallet, som utaf deras mun gick.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Ty deras magt var i deras mun, och i deras stjertar; och stjertarne voro ormom like, och hade hufvud, der de skada med gjorde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Och voro ännu menniskor, som icke voro dödade af dessa plågor, och icke bättrade sig af sina händers verk; att de icke tillbådo djefvulskap, och afgudar af guld, silfver, koppar, sten och trä, de der hvarken se kunna, eller höra, eller gå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Och icke gjorde bot för sitt mord, trolldom, skörhet och tjufveri.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Och jag såg en annan stark Ängel nederkomma af himmelen; han var klädd med en sky, och en regnbåge öfver hans hufvud, och hans ansigte såsom solen, och hans fötter såsom eldspelare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Och han hade i sine hand en öppen bok; och han satte sin högra fot på hafvet, och den vänstra på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Och ropade med höga röst, som ett rytande lejon. Och då han ropade, talade sju tordöner sina röster.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Och då de sju tordöner talat hade sina röster, ville jag skrifvit dem; då hörde jag ena röst af himmelen säga till mig: Besegla det de sju tordöner talat hafva, och skrif det intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Och Ängelen, som jag såg stå på hafvet och på jordene, hof sina hand upp till himmelen,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'Och svor vid honom, som lefver ifrån evighet till evighet, den der himmelen skapat hafver och hvad deruti är, och jordena och hvad deruti är, och hafvet och hvad deruti är, att ingen tid skall vara mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Utan i de dagar, då den sjunde Ängelens röst höres, då han varder basunandes; då skall Guds hemlighet fullkomnad varda, såsom han förkunnat hade genom sina tjenare Propheterna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Och jag hörde åter ena röst af himmelen tala med mig, och säga: Gack, och tag den öppna bokena af Ängelens hand, som står på hafvet och på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Och jag gick till Ängelen, och sade till honom: Få mig bokena; och han sade till mig: Tag, och ät upp henne, och hon skall rifva dig i buken; men i din mun skall hon vara söt som hannog.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Och jag tog bokena af Ängelens hand, och åt henne upp, och hon vardt i min mun söt som hannog; och då jag hade ätit henne, ref hon mig i buken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Och han sade till mig: Du måste åter prophetera folkom, Hedningom, och tungomålom, och mångom Konungom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Och mig vardt fången en rö såsom en käpp, och mig vardt sagdt: Statt upp, och mäl Guds tempel och altare, och de som tillbedja derinne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Men den inra choren af templet kasta ut, och mäl honom intet; ty han är gifven Hedningomen, och de skola förtrampa den heliga staden, i två och fyratio månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Och jag skall gifva tu minom vittnom, och de skola prophetera i tusende, tu hundrade och sextio dagar, klädde i säckar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Desse äro tu oljoträ, och tu bloss, ståndande för jorderikes Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Och hvar någor ville göra dem skada, så går elden ut af deras mun, och förtärer deras fiendar; och hvar någor ville göra dem ondt, så måste han dödas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Desse hafva magt till att igenlycka himmelen, att intet regnar uti de dagar då de prophetera; och hafva magt öfver vattnet, att förvända det i blod, och slå jordena med allahanda plågo, så ofta de vilja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Och då de hafva lyktat sitt vittnesbörd, skall det vilddjuret, som uppstiger af afgrunden, hålla ena strid med dem, och skall öfvervinna dem, och döda dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Och deras lekamen skola blifva liggande på gatorna, i den stora staden, som heter andeliga Sodoma och Egypten, der vår Herre korsfäst är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Och skola någre af folken och slägterna, och tungomålen, och af Hedningarna, se deras lekamen i tre dagar och en half, och skola icke vilja tillstädja deras lekamen läggas i grafvar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Och de på jordene bo, skola fröjda sig öfver dem, och skola glädjas, och sända hvarandrom gåfvor; ty desse två Propheter tvingade dem som bo på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Och efter tre dagar och en half kom lifsens ande af Gudi uti dem, och de stodo på sina fötter; och en stor förskräckelse föll på dem som sågo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Och de hörde en hög röst af himmelen säga till dem: Stiger hit upp. Och de stego upp i himmelen uti en sky, och deras ovänner sågo dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Och i samma stundene vardt en stor jordbäfning, och tionde delen af staden föll ned; och blefvo i jordbävningen dödade sjutusend menniskors namn; och de andre vordo förfärade, och gåfvo Gudi i himmelen pris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Det andra Ve gick öfver, och si, det tredje Ve kommer snart.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Och den sjunde Ängelen basunade, och i himmelen hördes höga röster, de der sade: Denna verldenes rike äro vordne vårs Herras och hans Christs, och han skall regnera af evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Och de fyra och tjugu äldste, som för Gudi på sina stolar såto, föllo på sin ansigte, och tillbådo Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Och sade: Vi tackom dig, Herre, allsmägtig Gud, du som äst, och varit hafver, och tillkommande äst; ty du hafver tagit dina stora kraft, och regnerar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Och Hedningarna äro vrede vordne; och din vrede är kommen, och de dödas tid, att de skola dömas, och att du skall löna dina tjenare Propheterna, och helgonen, och dem som frukta ditt Namn, små och stora, och förderfva dem som jordena förderfvat hafva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Och Guds tempel vardt upplåtet i himmelen, och hans Testaments ark vardt sedd i hans tempel, och der skedde ljungeld och röster, och tordöner, och jordbäfning, och stort hagel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Och i himmelen syntes ett stort tecken: En qvinna beklädd med solene, och månen under hennes fötter, och på hennes hufvud en krona af tolf stjernor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Och hon var hafvandes, ropade, och pintes med barn, och hade stort qval till att föda.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Och så syntes ett annat tecken i himmelen, och si, en stor röd drake, som hade sju hufvud och tio horn, och på hans hufvud sju kronor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Och hans stjert drog tredjeparten af himmelens stjernor, och kastade dem ned på jordena; och draken stod för qvinnone som föda skulle, på det, när hon födt hade, skulle han uppäta hennes barn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Och hon födde ett svenbarn, som regera skulle alla Hedningar med jernris; och hennes barn vardt borttaget till Gud, och till hans stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Och qvinnan flydde uti öknena, der hon rum hade, beredt af Gudi, att hon der föda skulle, i tusende, tuhundrade och sextio dagar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Och det vardt en stor strid i himmelen: Michael och hans Änglar stridde med drakan, och draken stridde och hans Änglar;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Och de vunno intet; och deras rum vardt icke mer funnet i himmelen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Och den store draken, den gamle ormen, den der heter djefvul och Satanas, vardt utkastad, den der bedrager hela verldena; och han vardt kastad på jordena, och hans änglar vordo ock bortkastade med honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Och jag hörde en stor röst, som sade i himmelen: Nu är vår Guds salighet, och kraft, och rike, och magt hans Christs vorden, efter våra bröders åklagare är förkastad, den dem åklagade för Gud, dag och natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Och de vunno honom för Lambsens blods skull, och för dess vittnesbörds ords skull, och de hafva icke älskat sitt lif allt intill döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Derföre, glädjens, I himlar, och de som bo i dem. Ve dem som bo på jordene, och på hafvet; ty djefvulen stiger ned till eder, och hafver en stor vrede, vetandes att han icke lång tid hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Och då draken såg att han förkastad var på jordena, förföljde han qvinnona, som svenbarnet födt hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Och qvinnone vordo gifne två vingar, såsom af en stor örn; att hon skulle flyga uti öknena uti sitt rum, der hon födes en tid, och två tider, och en half tid, ifrån ormsens ansigte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Och ormen sputade utu sin mun vatten, såsom en ström, efter qvinnona; på det han skulle fördränka henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Men jorden halp qvinnone, och upplät sin mun, och uppsvalg strömmen, som draken af sin mun utsputat hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Och draken vardt vred på qvinnona, och gick bort, att han skulle örliga med de andra af hennes säd, de som hålla Guds bud, och hafva Jesu Christi vittnesbörd. Och han stod på hafsens sand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Och jag såg ett vilddjur uppstiga utu hafvet, det hade sju hufvud och tio horn, och på dess horn tio kronor, och på dess hufvud hädelsens namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Och vilddjuret, som jag såg, det var likt enom pardel, och dess fötter såsom björnafötter, och dess mun såsom lejons mun; och draken gaf thy sina kraft, och sin stol, och stora magt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Och jag såg ett af hans hufvud såsom sargadt till döds, och dess dödssår var igenläkt, och hela jorden förundrade sig på vilddjuret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Och de tillbådo drakan, som vilddjurena hade magt gifvit; och tillbådo vilddjuret, sägande: Ho är vilddjuret lik? Eller ho förmå strida emot thy?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Och thy vardt gifven en mun, till att tala stor ting och hädelse; och thy vardt gifven magt till att bruka sig i två och fyratio månader.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Och det upplyfte sin mun, till att tala hädelse emot Gud, till att häda hans Namn och hans tabernakel, och dem som bo i himmelen; och thy vardt medgifvet strida med helgonen, och vinna dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Och thy vardt gifven magt öfver all slägter, och tungomål, och Hedningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Och alle de som på jordene bo, tillbådo det, hvilkas namn icke skrifna äro i Lambsens lifs bok, hvilket dödadt är ifrå verldenes begynnelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Den der öra hafver, han höre.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Den der leder i fängelse, han skall gå i fängelse; den der dräper med svärd, han måste dödas med svärd. Här är de heligas tålamod och tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Och jag såg ett annat vilddjur uppstiga utu jordene; och det hade tu horn lika som Lambet; och det talade som drakan.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Och det gör alla dess första vilddjurets magt, i dess åsyn; och det kommer jordena, och dem derpå bo, till att tillbedja det första vilddjuret; hvilkets dödssår igenläkt var.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Och det gör stor tecken, så att det ock låter eld falla ned af himmelen på jordena, i menniskors åsyn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Och det bedrager dem som bo på jordene, för de teckens skull, som thy gifna äro att göra för vilddjuret; sägandes till dem som bo på jordene, att de skola göra vilddjurena, som sargadt var af svärd, och var lefvande vordet, ett beläte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Och thy vardt gifvet, att det skulle gifva vilddjurets beläte anda, och att vilddjurets beläte skulle tala, och så beställat, att hvilke som helst icke tillbådo vilddjurets beläte, skulle dödas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Och det lät alla, små och stora, rika och fattiga, fria och tjenare, taga vedertecken uti deras högra hand, eller på deras anlete;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Att ingen skall må köpa, eller sälja, utan den der hafver vedertecknet, eller vilddjurets namn, eller dess namns tal.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Här är visdomen: Den der förstånd hafver, han räkne vilddjurets tal; ty det är ens menniskos tal, och dess tal är sexhundrad sextio och sex.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Och jag såg, och si: Ett Lamb stod på Sions berg, och med thy hundrade fyra och fyratio tusend: de hade dess Faders Namn beskrifvet på sin anlete.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Och jag hörde ena röst af himmelen, såsom af ett stort vatten; och såsom ena röst af en stor tordön; och rösten, som jag hörde, var såsom harpolekares, de der lekte på sina harpor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Och de söngo såsom en ny sång för stolen, och för de fyra djuren, och för de äldsta; och ingen kunde lära den sången, utan de hundrade fyra och fyratio tusend, som köpte äro af jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Desse äro de, som med qvinnor icke besmittade äro, ty de äro jungfrur; desse äro de som följa Lambet, ehvart det går; desse äro köpte ifrå menniskorna, till en förstling Gudi, och Lambena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Och i deras mun är intet svek funnet; ty de äro utan smitto, för Guds stol.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Och jag såg en annan Ängel flyga midt genom himmelen; han hade ett evigt Evangelium, det han förkunna skulle dem som på jordene bo, och allom Hedningom, och slägtom, och tungomålom, och folkom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Och sade med höga röst: Frukter Gud, och gifver honom äro; ty stunden är kommen till hans dom, och tillbeder honom, som hafver gjort himmel och jord, hafvet och vattukällorna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Och en annar Ängel följde efter, och sade: Fallen, fallen är den store staden Babylon; ty han hafver dricka gifvit allom Hedningom af vredenes vin, sins boleris.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Och tredje Ängelen följde dem, och sade med höga röst: Hvar någor tillbeder vilddjuret, och dess beläte, och tager dess vedertecken på sitt anlete, eller på sin hand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Han skall ock dricka af Guds vredes vin, det inskänkt och klart är i hans vredes kalk; och han skall varda plågad med eld och svafvel, i heliga Änglars åsyn, och i Lambsens åsyn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Och röken af deras plågo skall uppstiga af evighet till evighet; och de hafva hvarken dag eller natt ro, som tillbedja vilddjuret och dess beläte, och der någor tagit hafver dess namns vedertecken.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Här är de heligas tålamod; här äro de som hålla Guds bud och Jesu tro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Och jag hörde ena röst af himmelen säga till mig: Skrif: Salige äro de döde, som i Herranom dö, härefter; ja, Anden säger, att de skola hvila sig ifrå sitt arbete; ty deras gerningar följa dem efter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Och jag såg, och si en hvit sky; och på skynom satt en, som lik var menniskones Son, och hade på sitt hufvud en guldkrono, och i hans hand en hvass lia.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Och en annar Ängel kom utu templet, och ropade med höga röst till den, som satt på skynom: Hugg till med din lia, och skär; ty tiden är dig kommen, att du skall skära; ty säden på jordene är torr vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Och han, som satt på skyn, högg till med sin lia på jordena, och jorden vardt afskoren.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Och en annar Ängel kom utu templet, som i himmelen är, den ock en hvass lia hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Och en annar Ängel kom utur altaret, den magt hade öfver elden; och ropade med höga röst till honom, som hade den hvassa lian, och sade: Hugg till med din hvassa lia, och skär upp vinqvistarna på jordene; ty hennes vinbär äro mogen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Och Ängelen högg till med sin skarpa lia på jordena, och skar upp vingårdarna på jordene, och kastade dem uti Guds vredes stora präss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Och vardt prässen trampad utom staden; och blodet gick ut af prässen, allt intill betslen på hästarna, utöfver tusende sexhundrad stadier vägs.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Och jag såg ett annat tecken af himmelen, stort och underligit: Sju Änglar, som hade sju de yttersta plågor; ty med dem är fullkomnad Guds vrede.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Och jag såg såsom ett glashaf, beblandadt med eld, och dem stå på samma glashaf, som seger vunnit hade på vilddjuret, och dess beläte, och vedertecken, och på dess namns tal; och de hade Guds harpor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Och de söngo Mose, Guds tjenares, sång, och Lambsens sång, sägande: Stor och underlig äro din verk, Herre Gud allsvåldig; rättfärdige och sanne äro dine vägar, du helgonens Konung.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Ho skulle icke frukta dig, Herre, och prisa ditt Namn? Ty du äst allena helig, och alle Hedningar skola komma och tillbedja i din åsyn; ty dine domar äro uppenbare vordne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Sedan såg jag; och si, vittnesbördsens tabernakels tempel vardt öppnadt i himmelen;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Och gingo derut af templet de sju Änglar, som de sju plågor hade, klädde uti rent, hvitt linkläde, och omgjordade kringom bröstet med gyldene bälte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Och ett af de fyra djuren gaf de sju Änglar sju gyldene skålar, fulla med Guds vrede, den der lefver af evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Och templet vardt uppfyldt med rök af Guds härlighet, och af hans kraft; och ingen kunde gå in i templet, till dess de sju plågor, som de sju Änglar hade, fullkomnade vordo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Och jag hörde ena stora röst uti templet; den sade till de sju Änglar: Går, och utgjuter de Guds vredes skålar på jordena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Och den förste Ängelen gick åstad, och göt sina skål ut på jordena; och det vardt ett ondt och skadeligit sår på menniskomen, som vilddjurets vedertecken hade, och på dem som tillbådo dess beläte.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Och den andre Ängelen göt ut sina skål i hafvet; och det vardt såsom ens döds mans blod, och allt det lif hade i hafvet blef dödt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Och den tredje Ängelen göt ut sina skål i älfvena, och i vattukällorna; och det vardt blod.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Och jag hörde en Ängel säga: Rättfärdig äst du, Herre, som äst, och varit hafver, och helig, att du detta dömt hafver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Ty de hafva utgjutit helgonens och Propheternas blod, och blod hafver du ock gifvit dem dricka; ty de äro dess värde.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Och jag hörde en annan Ängel säga af altaret: Ja, Herre Gud allsvåldig, sanne och rätte äro dine domar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Och den fjerde Ängelen göt ut sina skål i solena; och honom vardt gifvet att plåga menniskorna med hetta af eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Och menniskorna vordo brinnande uti en stor hetta, och de hädde Guds Namn, som magten hade öfver dessa plågor; och gjorde inga syndabättring, att de måtte gifvit honom äro.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Och den femte Ängelen göt ut sina skål på vilddjurets stol; och dess rike vardt förmörkradt, och de sönderbeto sina tungor, för värks skull;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Och hädde Gud i himmelen, för sin värk och sin sårs skull, och bättrade sig intet af sina gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Och den sjette Ängelen göt ut sina skål på den stora älfvena Euphrates; och dess vatten borttorkades; på det vägen skulle beredas för de Konungar östanefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Och jag såg utu drakans mun, och utu vilddjurets mun, och utu den falska Prophetens mun, utgå tre orena andar, såsom paddor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Och det äro djefvulsens andar, som tecken göra, och utgå till Konungarna på hela jordene, att församla dem till strids på den stora allsvåldiga Guds dag.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Si, jag kommer, som tjufven plägar komma; salig är den som vakar, och förvarar sin kläder, att han icke går naken, och de få se hans skam.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Och han församlade dem på ett rum, det heter på Ebreisko Armageddon.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Och den sjunde Ängelen göt ut sina skål i vädret; och gick en stor röst utaf himmelens tempel ifrå stolen, som sade: Det är gjordt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Och det vardt röster, och tordön, och ljungeld, och stor jordbäfning, sådana, att dess like icke varit hade, sedan menniskorna på jordene varit hade, sådana jordbäfning, så stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Och den store staden vardt i tre delar, och Hedningarnas städer föllo; och den store Babylon kom i åminnelse för Gudi, att han ville gifva honom kalken af sine grymma vredes vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Och alle öar flydde, och bergen funnos intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Och stort hagel, såsom en centener, kom ned af himmelen på menniskorna; och menniskorna hädde Gud, för den stora plåga af haglet; ty dess plåga var ganska stor.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Och kom en af de sju Änglar, som hade de sju skålar, och talade med mig, och sade till mig: Kom, jag vill visa dig den stora skökones fördömelse, som sitter på mycken vatten;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Med hvilka Konungarna på jordene bolat hafva; och de der på jordene bo, äro druckne vordne af hennes boleris vin.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Och han förde mig i Andanom uti öknena; och jag såg qvinnona sitta på ett rosenfärgo vilddjur, det var fullt med hädelsenamn, och hade sju hufvud och tio horn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Och qvinnan var klädd med purpur och rosenfärgo, och öfvergyld med guld, och ädla stenar, och perlor; och hade en gyldene kalk i sine hand, full med styggelse, och sins boleris orenlighet;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Och på hennes anlete skrifvet det namn, Hemlighet: Den store Babylon, modren till boleri, och till styggelse på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Och jag såg qvinnona druckna af helgonens blod, och af deras blod, som Jesu vittne voro; och jag förundrade mig storliga, då jag såg henne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Och Ängelen sade till mig: Hvi förundrar du dig? Jag vill säga dig hemligheten om denna qvinnone, och om vilddjuret, som bär henne, och hafver sju hufvud och tio horn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Vilddjuret, som du hafver sett, hafver varit, och är icke; och det skall åter uppkomma utaf afgrunden, och skall gå uti fördömelse; och de, som på jordene bo, skola förundra sig, hvilkas namn icke skrifna äro i lifsens bok, ifrå verldenes begynnelse; då de se vilddjuret, som hafver varit, och som icke är, ändock det är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Och här är sinnet, der visdom tillhörer; de sju hufvud äro sju berg, der qvinnan sitter uppå, och det äro sju Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Fem äro fallne; en är, och den andre är icke ännu kommen; och när han kommer, skall han icke länge blifva.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Och vilddjuret, som hafver varit, och icke är, den är den åttonde, och han är utaf de sju, och han går uti fördömelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Och de tio horn, som du sett hafver, äro tio Konungar, som ännu icke hafva fått rike, utan skola, såsom Konungar, på en stund få magt med vilddjuret.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Desse hafva alle ett råd, och skola gifva vilddjurena sina magt och kraft.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'De skola strida med Lambena, och Lambet skall vinna dem; ty det är en Herre öfver alla herrar, och en Konung öfver alla Konungar; och med thy äro de utkallade, och utkorade, och trogne.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Och han sade till mig: Vattnet, som du såg, der skökan sitter på, är folk och skarar, och Hedningar, och tungomål.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Och de tio horn, som du sett hafver på vilddjuret, skola hata skökona, och lägga henne öde och naken; och de skola uppäta hennes kött, och bränna henne upp i eld.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Ty Gud hafver gifvit dem i hjertat, att de skola göra det honom behagar, och göra alle ena mening, att de skulle gifva vilddjurena riket, till dess Guds ord varda fullkomnad.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Och qvinnan, som du sett hafver, är den store staden, som rike hafver öfver jordenes Konungar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Och sedan såg jag en annan Ängel komma neder af himmelen, den stora magt hade; och jorden vardt upplyst af hans klarhet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Och han ropade med magt och höga röst, sägandes: Fallen, fallen är den store Babylon, och är vorden djeflaboning, och alla orena andars behåll, och alla orena och ohyggeliga foglars behåll.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Ty alle Hedningar hafva druckit af vredenes vin, hennes boleris, och Konungarne på jordene hafva bolat med henne, och köpmännerne på jordene äro rike vordne af hennes stora vällust.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Och jag hörde ena andra röst af himmelen, som sade: I mitt folk, går ut ifrå henne, att I icke delaktige varden i hennes synder, och att I icke fån något af hennes plågor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Ty hennes synder räcka allt upp i himmelen, och Gud hafver dragit till minnes hennes orättfärdigheter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Betaler henne, såsom hon hafver betalat eder, och görer henne dubbelt efter hennes gerningar; och med samma kalk, som hon hafver inskänkt eder, inskänker henne dubbelt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Så mycket hon sig hafver härliga hållit och i vällust varit, så mycket inskänker henne pino och gråt; ty hon säger i sitt hjerta: Jag sitter och är en Drottning, och icke enka, och hafver ingen sorg.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Derföre skola hennes plågor komma på en dag, död, gråt, och hunger; och hon skall varda uppbränd i eld; ty Herren Gud är stark, som henne döma skall.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Och jordenes Konungar skola gråta henne, och beklaga sig öfver henne, de som med henne bolat, och i vällust lefvat hafva, då de få se röken af hennes brand;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Och skola stå långt ifrå, för hennes plågos räddhågas skull, och säga: Ve, ve den store staden Babylon, den starke staden; ty uti en stund är din dom kommen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Och köpmännerna på jordene skola gråta och sörja öfver henne, att ingen köper deras varor mer:');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Guld, och silfver, och ädla stenar, och perlor, och silke, och purpur, och skarlakan, och allt Thynenträ, och all käril af kosteligit trä, och af koppar, och jern, och marmor,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Och canel, och timian, och salvo, och rökelse, och vin, och oljo, och semlor, och hvete, och boskap, och får, och hästar, och vagnar, och kroppar, och menniskors själar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Och de äple, som din själ begärar, äro bortkomna ifrå dig, och allt det fett och härligit var, är förgånget ifrå dig, och du skall icke nu finnat härefter.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Köpmännerna som sådana varor pläga hafva, och äro rike vordne af honom, skola stå långt ifrå, för räddhågas skull af hans plågo, gråta och sörja;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Och säga: Ve, ve den stora staden, som med silke, och purpur, och skarlakan beklädd var, och öfvergyld med guld, och ädla stenar, och perlor;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Ty uti ene stund äro förödde sådane rikedomar; och alle skeppare, och alle de som på skeppen vistas, och sjömän, och de som till sjös handla, stodo långt ifrå;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Och ropade, då de sågo röken af hans brand, sägande: Hvar är dens stora stadsens like?');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Och de kastade mull på sin hufvud, och ropade, gråtande och sörjande, och sade: Ve, ve den stora staden, i hvilkom alle äro rike vordne, som i hafvet hafva haft sin skepp af hans varor; ty uti en stund är han öde vorden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Fröjda dig öfver honom, himmel, och I helige Apostlar, och Propheter; ty Gud hafver dömt edar dom på honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Och en stark Ängel tog upp en stor sten som en qvarnsten, och kastade i hafvet, och sade: Med sådana hastighet skall förkastad varda den store staden Babylon, och han skall icke nu mer varda funnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Och harpares, och sångares, och pipares, och basuners röst skall icke mer hörd varda i dig; och alle handtverksmän, ehvad handtverk det är, skola icke mer varda funne i dig; och qvarnaröst skall icke mer höras i dig.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Och ljus och ljusastaka skall icke mer lysa i dig; och brudgummes och bruds röst skall icke mer hörd varda i dig; ty dine köpmän voro Förstar på jordene; ty i dinom trolldom hafva alle Hedningar ville farit;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Och i honom vardt funnen Propheternas och helgonens blod, och allas deras som dräpne äro på jordene.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Sedan hörde jag, såsom en stor röst, af en stor skara i himmelen, som sade: Halleluja; salighet och pris, ära och kraft, vare Herranom vårom Gudi.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Ty hans domar äro sanne och rätte; ty han hafver dömt den stora skökan, den med sitt boleri hafver förderfvat jordena; och hafver hämnat sina tjenares blod utu hennes hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Och åter sade de: Halleluja; och röken gick upp af evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Och de fyra och tjugu äldste, och de fyra djur, föllo neder och tillbådo Gud, som satt på stolen, och sade: Amen, Halleluja.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Och en röst gick af stolen, och sade: Lofver vår Gud, I alle hans tjenare, och I som frukten honom, både små och store.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Och jag hörde ena röst, såsom af en stor skara, och såsom en röst af mycket vatten, och såsom en röst af stor tordön, säga: Halleluja; ty vår Herre, allsmägtig Gud, hafver intagit riket.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Låt oss glädjas och fröjdas, och gifva honom äro; ty Lambsens bröllop är kommet, och dess hustru hafver sig tillredt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Och henne vardt gifvet att kläda sig uti rent och skinande silke; men silket är helgonens rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Och han sade till mig: Skrif: Salige äro de, som kallade äro till Lambsens bröllop. Och han sade till mig: Dessa äro sann Guds ord.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Och jag föll för hans fötter, att tillbedja honom; och han sade till mig: Se till, att du det icke gör; ty jag är din och dina bröders medtjenare, som Jesu vittnesbörd hafva. Tillbed Gud; ty Jesu vittnesbörd är Propheties Ande.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Och jag såg himmelen öppen; och si, en hvit häst; och den som satt på honom, han het Trofast och Sannfärdig; och han dömer och strider med rättfärdighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Och hans ögon såsom eldslåge, och på hans hufvud många kronor; och hade ett namn skrifvet, det ingen kände, utan han sjelfver.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Och han var klädd i ett kläde, som med blod bestänkt var; och hans namn heter: Guds Ord;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Och honom efterföljde den här, som i himmelen är, med hvita hästar, klädde uti hvitt och rent silke.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Och utu hans mun utgick ett skarpt tveeggadt svärd, att han dermed skall slå Hedningarna; och han skall regera dem med jernris; och han trampar allsmägtig Guds grymma vredes vinpräss.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Och han hafver på sin kläder, och på sina länd ett namn, skrifvet alltså: Konung öfver alla Konungar, och Herre öfver alla herrar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Och jag såg en Ängel stå i solene, och han ropade med höga röst, och sade till alla foglar, som flugo under himmelen: Kommer, och församlens till den stora Guds Nattvard;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Att I skolen äta Konungarnas kött, och höfvitsmännernas kött, och de starkas kött, och hästars kött, och deras som sitta på dem, och allas deras kött, som frie och trälar äro, och både smås och storas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Och jag såg vilddjuret, och jordenes Konungar, och deras härar församlada, till att hålla ena strid med honom, som satt på hästen, och med hans här.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Och vilddjuret vardt fånget, och med thy den falske Propheten, som tecken gjorde för thy, med hvilko han bedrog dem, som togo vilddjursens vedertecken, och dem som tillbådo dess beläte; desse två vordo lefvande kastade uti en brinnande sjö, som brann med svafvel.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Och de andre vordo dräpne med hans svärd, som satt på hästen, det utu hans mun gick; och alle foglar vordo mättade af hans kött.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Och jag såg en Ängel nederkomma af himmelen; han hade nyckelen till af grunden, och ena stora kedjo i sine hand.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Och han grep drakan, den gamla ormen, som är djefvulen och Satan, och band honom i tusende år;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Och kastade honom uti afgrunden, och lät åter om honom, och beseglade der ofvan uppå, att han icke mer bedraga skulle Hedningarna, till dess fullkomnad vordo tusende är; och sedan måste han lös varda till någon liten tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Och jag såg stolar, och de såto på dem, och dem vardt gifven dom; och deras själar, som halshuggne voro för Jesu vittnesbörd, och för Guds ords skull; och de der icke tillbådo vilddjuret eller dess beläte; ej heller togo dess vedertecken på sin anlete, eller i sina händer; och de lefde, och regnerade med Christo i tusende är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Men de andre döde fingo icke lif igen, till dess tusende är fullkomnad vordo; denna är den första uppståndelsen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Salig och helig är den som del hafver uti första uppståndelsen; öfver dem hafver den andre döden ingen magt; utan de varda Guds och Christi Prester, och skola regnera med honom i tusende år.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Och då tusende år fullkomnad äro, varder Satanas lös utu sitt fängelse.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Och han skall utgå, till att bedraga Hedningarna, som äro på fyra jordenes parter, Gog och Magog, på det han skall församla dem i strid; hvilkas tal är såsom sanden i hafvet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Och de gåfvo sig upp på jordenes bred het, och kringhvärfde helgonens lägre, och den älskeliga staden; och neder af himmelen for eld af Gudi, och förtärde dem.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Och djefvulen, som dem bedragit hade, vardt kastad uti den brinnande sjön, och svallet, der både vilddjuret och den falske Propheten skola plågas, dag och natt, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Och jag såg en stor hvit stol, och en sitta på honom, för hvilkens ansigte flydde jord och himmel, och dem vardt intet rum funnet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Och jag såg de döda, stora och små, stå i Guds åsyn, och böckerna vordo upplåtna; och en annar bok vardt upplåten, som är lifsens; och de döde vordo dömde, efter som skrifvet var i böckerna, efter deras gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Och hafvet gaf igen de döda, som deruti voro; och döden och helvetet gåfvo igen de döda, som uti dem voro; och det blef dömdt om hvar och en, efter deras gerningar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Och döden och helvetet vordo kastade, uti den brinnande sjön; denne är den andre döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Och den der icke vardt funnen skrifven i lifsens bok, han vardt kastad i den brinnande sjön.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Och jag såg en ny himmel och en ny jord; ty den förste himmelen och den första jorden förgingos; och hafvet är icke mer.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Och jag, Johannes, såg den helga staden, det nya Jerusalem, nederkomma af himmelen, ifrå Gudi, tillredd såsom en prydd brud till sin man.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Och jag hörde ena stora röst af himmelen säga: Si Guds tabernakel ibland menniskorna, och han skall bo med dem; och de skola vara hans folk, och sjelfver Gud med dem skall vara deras Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Och Gud skall aftorka alla tårar af deras ögon, och ingen död skall sedan vara; icke heller gråt, icke heller rop, icke heller någor värk varder mer; ty det första är förgånget.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Och den der satt på stolen sade: Si, jag gör all ting ny. Och han sade till mig: Skrif; ty dessa ord äro viss och sann.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Och han sade till mig: Det är gjordt. Jag är A och O, begynnelsen och änden; jag skall gifva honom, som törstar, af lefvande vattnens källo för intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Den som vinner, han skall allt detta få äga; och jag skall vara honom hans Gud, och han skall vara min son.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Men dem räddom, och otrognom, och grufligom, och mandråparom, och bolarom, och trollkarlom, och afgudadyrkarom, och allom lögnaktigom, deras del skall vara uti den sjön, som brinner med eld och svafvel; hvilket är den andre döden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Och till mig kom en af de sju Änglar, som hade sju skålar fulla med de sju yttersta plågor; och han talade med mig, och sade: Kom, och jag vill visa dig brudena, Lambsens hustru.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Och han förde mig, i Andanom, på ett stort och högt berg, och viste mig den stora staden, det helga Jerusalem, nederkomma af himmelen ifrå Gud;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Och hade Guds härlighet; och hans ljus var lika som den aldraädlaste stenen, en klar jaspis,');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Och han hade en stor och hög mur, den der tolf portar hade, och i portarna tolf Änglar, och inskrifna namn, hvilka äro de tolf Israels söners slägters namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Östantill tre portar, nordantill tre portar, sunnantill tre portar, vestantill tre portar.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Och stadsmuren hade tolf grundvalar, och i dem de tolf Lambsens Apostlars namn.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Och den som talade med mig, hade ena gyldene rö, der han med mäta skulle staden, och hans portar, och hans mur.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Och staden ligger fyrkant, och hans längd är så stor som bredden; och han mälte staden med rön, tolf tusend stadier; och hans längd, och bredd, och höjd äro lika.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Och han mälte hans mur, hundrade fyra och fyratio alnar, efter ens menniskos mått, som Ängelen hade.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Och hans murs byggning var af jaspis; men sjelfve staden af klart guld, lik vid rent glas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Och stadsmurens grundvalar voro prydde med all dyrbar sten; förste grundvalen var af jaspis, den andre en saphir, den tredje en chalcedonier, den fjerde en smaragd;');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Den femte en sardonix, den sjette en sardis, den sjunde en chrysolith, den åttonde en beryll, den nionde en topazier, den tionde en chrysopras, den ellofte en hyacinth, den tolfte en amethist.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Och de tolf portar voro tolf perlor, hvar för sig; och hvar port var af ene perlo; och stadsens gator voro klart guld, såsom genomskinande glas.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Och jag såg der intet tempel uti; ty Herren, allsvåldig Gud, är templet deruti, och Lambet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Och staden behöfver icke sol eller måna, att de skola lysa deruti; ty Guds härlighet upplyser honom, och hans ljus är Lambet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Och Hedningarna, som salige varda, skola vandra i hans ljus; och Konungarna på jordene skola föra sina härlighet och ära in uti honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Och hans portar låtas intet till om dagen; ty der varder ingen natt.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Och de skola föra Hedningarnas härlighet och ära in uti honom.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Der skall intet inkomma, som besmitteligit är, eller det styggelse gör och lögn; utan de som skrifne äro i Lambsens lefvande bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Och han viste mig ena klara älf, med lefvande vatten, klar som christall, den gick ifrå Guds stol och Lambsens.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Midt uppå hans gator, och på båda sidor vid älfvena, stod lifsens trä, bärandes tolffald frukt, och bar sina frukt alla månader; och löfven af trät tjente till Hedningarnas helbregdo.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Och intet förbannadt skall vara mer; utan Guds och Lambsens stol skall blifva deruti, och hans tjenare skola honom tjena.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Och de skola se hans ansigte, och hans Namn skall vara på deras anleten.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Och natt blifver icke mer der, och de behöfva icke ljus, icke heller solens ljus; ty Herren Gud upplyser dem, och de skola regnera ifrån evighet till evighet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Och han sade till mig: Dessa ord äro viss och sann; och Herren, de helga Propheters Gud, sände sin Ängel, att visa sina tjenare hvad ske skall innan kort tid.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Och si, jag kommer snarliga; salig är den som håller Prophetiens ord i desso bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Och jag är Johannes, som hörde och såg detta; och sedan jag hade det hört och sett, föll jag ned att tillbedja för Ängelens fötter, som mig detta viste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Och han sade till mig: Se till, att du gör det icke; ty jag är din medtjenare, och dina bröders, Propheternas, och deras som hålla denna boks ord: Tillbed Gud.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Och han sade till mig: Besegla icke denna Propheties ord i desso bok; ty tiden är när.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Den som onder är, han vare ännu onder; och den som oren är, han vare ännu oren; men den som from är, han varde ännu frommare; och den helig är, varde ännu heligare.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Och si, jag kommer snart, och min lön med mig, till att vedergälla hvarjom och enom, såsom hans gerning är.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jag är A och O, begynnelsen och änden, den förste och den siste.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Salige äro de som hålla hans bud, på det deras magt skall vara i lifsens trä, och ingå genom portarna i staden.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Ty utantill äro hundar, och trollkarlar, och bolare, och mandråpare, och afgudadyrkare, och alle de som älska och göra lögnen.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Jag, Jesus, sände min Ängel, att han skulle betyga eder detta i församlingarna: Jag är Davids rot och slägte, en klar morgonstjerna.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Och Anden och bruden säga: Kom. Och den det hörer, han säge: Kom. Och den der törster, han komme; och den der vill, han tage lifsens vatten för intet.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Men jag betygar hvar och en, som hörer Prophetiens ord i desso bok: Ho som lägger något härtill, på honom skall Gud lägga de plågor, som skrefne äro i denna bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Och om någor tager något ifrå denna boks Propheties ord, hans del skall Gud borttaga utu lifsens bok, och utu den helga staden, och utu det som skrifvet är i denna bok.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Det säger han, som vittnesbörd bär härtill: Ja, jag kommer snart. Amen. Ja, kom, Herre Jesu.');
INSERT INTO `SweKarlXII_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen.');
